'use client';
import { useEffect, useState, useCallback, useMemo } from 'react'
import Link from 'next/link'
import { createClient, type BrowserSession } from '@/lib/api-client/client'
import type { PlanId } from '@/lib/subscription/catalog'
import type { CurrencyCode } from '@/lib/subscription/catalog'
import { z } from 'zod'
import { apiGet, apiPost, ApiError } from '@/lib/api/client'

// ---------------------------------------------------------------------------
// Schemas
// ---------------------------------------------------------------------------

const subscriptionResponseSchema = z.object({
  plan: z.string().optional(),
  status: z.string().optional(),
  paymentMethod: z.string().optional(),
  currency: z.string().optional(),
  periodStart: z.string().optional(),
  periodEnd: z.string().optional(),
  trialEndsAt: z.string().nullable().optional(),
}).passthrough()

const paymentMutationSchema = z.object({}).passthrough()

interface PaymentRecord {
  id: string
  amount: number
  currency: CurrencyCode
  status: string
  payment_method: string
  transaction_id: string | null
  plan_id: PlanId
  created_at: string
}

interface SubscriptionRecord {
  plan_id: PlanId
  status: string
  payment_method: string
  currency: string
  current_period_start: string
  current_period_end: string
  trial_ends_at: string | null
}

const CURRENCY_SYMBOLS: Record<CurrencyCode, string> = {
  KES: 'KSh ', UGX: 'USh ', TZS: 'TSh ', NGN: '₦ ',
  GHS: 'GH₵ ', ZAR: 'R ', USD: '$ ', EUR: '€ ',
  GBP: '£ ', INR: '₹ ', IDR: 'Rp ', BRL: 'R$ ', AUD: 'A$ ',
}

const STATUS_COLORS: Record<string, string> = {
  completed: 'text-green-400',
  pending: 'text-amber-400',
  failed: 'text-red-400',
  refunded: 'text-gray-400',
  active: 'text-green-400',
  cancelled: 'text-red-400',
  expired: 'text-gray-400',
  trial: 'text-blue-400',
}

export default function BillingPage() {
  // AUDIT FIX (H-007, 2026-07-27): useMemo prevents infinite loop.
  const dbClient = useMemo(() => createClient(), [])
  const [user, setUser] = useState<NonNullable<BrowserSession['user']> | null>(null)
  const [subscription, setSubscription] = useState<SubscriptionRecord | null>(null)
  const [payments, setPayments] = useState<PaymentRecord[]>([])
  const [loading, setLoading] = useState(true)
  const [cancelling, setCancelling] = useState(false)
  const [message, setMessage] = useState('')

  const loadData = useCallback(async () => {
    const { data: { session } } = await dbClient.auth.getSession()
    const user = (session as BrowserSession | null)?.user ?? null
    setUser(user)

    if (user) {
      const subPromise = apiGet(
        '/api/subscription',
        subscriptionResponseSchema,
        { ttlMs: 0 },
      ).catch(() => null)
      const payPromise = dbClient
        .from('payment_history')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false })
                .limit(10) as unknown as { data: PaymentRecord[] | null }
      const [subRes, { data: pay }] = await Promise.all([subPromise, payPromise])
      // Map API response to SubscriptionRecord format
      if (subRes) {
        setSubscription({
          plan_id: subRes.plan as PlanId,
          status: subRes.status || 'active',
          payment_method: subRes.paymentMethod || '',
          currency: subRes.currency || 'KES',
          current_period_start: subRes.periodStart || new Date().toISOString(),
          current_period_end: subRes.periodEnd || new Date(Date.now() + 30 * 86400000).toISOString(),
          trial_ends_at: subRes.trialEndsAt || null,
        })
      }
      setPayments((pay || []) as PaymentRecord[])
    }
    setLoading(false)
  }, [dbClient])

  useEffect(() => {
    loadData()
  }, [loadData])

  async function handleCancel() {
    if (!confirm('Are you sure you want to cancel your subscription? You will retain access until the end of the billing period.')) return
    setCancelling(true)
    setMessage('')

    const provider = subscription?.payment_method || 'stripe'

    try {
      await apiPost(
        '/api/payments',
        paymentMutationSchema,
        { provider, action: 'cancel-subscription' },
      )
      setMessage('Subscription cancelled. You retain access until the end of your billing period.')
      await loadData()
    } catch (err) {
      if (err instanceof ApiError) {
        setMessage(`Error: ${err.message}`)
      } else {
        setMessage('Error: Failed to cancel')
      }
    }
    setCancelling(false)
  }

  async function handleReactivate() {
    setCancelling(true)
    setMessage('')

    const provider = subscription?.payment_method || 'stripe'

    try {
      await apiPost(
        '/api/payments',
        paymentMutationSchema,
        { provider, action: 'reactivate-subscription' },
      )
      setMessage('Subscription reactivated.')
      await loadData()
    } catch (err) {
      if (err instanceof ApiError) {
        setMessage(`Error: ${err.message}`)
      } else {
        setMessage('Error: Failed to reactivate')
      }
    }
    setCancelling(false)
  }

  const formatAmount = (amount: number, currency: CurrencyCode) =>
    `${CURRENCY_SYMBOLS[currency] || `${currency} `}${amount.toLocaleString()}`

  const formatDate = (date: string) =>
    new Date(date).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })

  if (loading) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="text-[var(--accent)]">Loading...</div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)] py-12">
      <div className="max-w-3xl mx-auto px-6">
        <div className="flex items-center justify-between mb-8">
          <h1 className="text-3xl font-bold text-[var(--text-primary)]">Billing</h1>
          <Link href="/pricing" className="text-[var(--accent)] hover:underline text-sm">
            View Plans
          </Link>
        </div>

        {message && (
          <div className="mb-6 rounded-lg border px-4 py-3 text-sm bg-[var(--bg-secondary)] border-[var(--border-color)]">
            {message}
          </div>
        )}

        <div className="space-y-6">
          <Section title="Current Plan">
            {subscription ? (
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-[var(--text-primary)] font-bold text-xl capitalize">
                      {subscription.plan_id} Plan
                    </p>
                    <p className="text-[var(--text-secondary)] text-sm">
                      {subscription.status === 'trial'
                        ? `Free trial ends ${formatDate(subscription.trial_ends_at || '')}`
                        : subscription.status === 'active'
                        ? `Renews ${formatDate(subscription.current_period_end)}`
                        : subscription.status === 'cancelled'
                        ? `Cancels ${formatDate(subscription.current_period_end)} — access ends then`
                        : `Status: ${subscription.status}`}
                    </p>
                    {subscription.payment_method && (
                      <p className="text-[var(--text-muted)] text-xs mt-1">
                        Paid via {subscription.payment_method}
                      </p>
                    )}
                  </div>
                  <span className={`text-sm font-bold px-3 py-1 rounded-full bg-[var(--bg-tertiary)] ${STATUS_COLORS[subscription.status] || 'text-white'}`}>
                    {subscription.status.toUpperCase()}
                  </span>
                </div>

                {subscription.status === 'active' && (
                  <div className="flex gap-3">
                    <button
                      onClick={handleCancel}
                      disabled={cancelling}
                      className="px-4 py-2 border border-red-800 text-red-400 rounded-lg text-sm hover:bg-red-900/20 disabled:opacity-50"
                    >
                      {cancelling ? 'Cancelling...' : 'Cancel Subscription'}
                    </button>
                  </div>
                )}

                {subscription.status === 'cancelled' && (
                  <div className="flex gap-3">
                    <button
                      onClick={handleReactivate}
                      disabled={cancelling}
                      className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-semibold hover:bg-[var(--accent-dim)] disabled:opacity-50"
                    >
                      {cancelling ? 'Reactivating...' : 'Reactivate Subscription'}
                    </button>
                  </div>
                )}

                {subscription.status === 'trial' && (
                  <div className="flex gap-3">
                    <Link
                      href="/checkout"
                      className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-semibold hover:bg-[var(--accent-dim)]"
                    >
                      Upgrade Now
                    </Link>
                  </div>
                )}
              </div>
            ) : (
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-[var(--text-primary)] font-bold text-xl">Free Plan</p>
                  <p className="text-[var(--text-secondary)] text-sm">No active subscription</p>
                </div>
                <Link
                  href="/pricing"
                  className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-semibold hover:bg-[var(--accent-dim)]"
                >
                  Upgrade
                </Link>
              </div>
            )}
          </Section>

          <Section title="Payment History">
            {payments.length > 0 ? (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="text-left text-[var(--text-muted)] border-b border-[var(--border-color)]">
                      <th className="pb-2 font-medium">Date</th>
                      <th className="pb-2 font-medium">Plan</th>
                      <th className="pb-2 font-medium">Amount</th>
                      <th className="pb-2 font-medium">Method</th>
                      <th className="pb-2 font-medium">Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {payments.map((pay) => (
                      <tr key={pay.id} className="border-b border-[var(--border-color)]/50 text-[var(--text-primary)]">
                        <td className="py-3">{formatDate(pay.created_at)}</td>
                        <td className="py-3 capitalize">{pay.plan_id}</td>
                        <td className="py-3">{formatAmount(pay.amount, pay.currency)}</td>
                        <td className="py-3 capitalize">{pay.payment_method || '—'}</td>
                        <td className={`py-3 font-medium ${STATUS_COLORS[pay.status] || 'text-white'}`}>
                          {pay.status}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <p className="text-[var(--text-secondary)]">No payment history yet.</p>
            )}
          </Section>

          <Section title="Billing Address">
            <p className="text-[var(--text-secondary)] text-sm">
              Contact <a href="mailto:billing@metardu.app" className="text-[var(--accent)] hover:underline">billing@metardu.app</a> to update your billing address or request invoices.
            </p>
          </Section>
        </div>
      </div>
    </div>
  )
}

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
      <h2 className="text-lg font-semibold text-[var(--text-primary)] mb-4">{title}</h2>
      {children}
    </div>
  )
}

'use client';
import { useEffect, useState } from 'react'
import { useSession } from 'next-auth/react'
import { createClient } from '@/lib/api-client/client'
import { z } from 'zod'
import { apiGet, apiPost, ApiError } from '@/lib/api/client'

// ── Schemas ────────────────────────────────────────────────────────────────
const subscriptionResponseSchema = z.object({
  plan: z.string().optional(),
  status: z.string().optional(),
  trialEndsAt: z.string().optional(),
  periodEnd: z.string().optional(),
}).passthrough()
const updatePasswordMutationSchema = z.object({}).passthrough()

interface Subscription {
  plan_id: string
  status: string
  trial_ends_at: string
  current_period_end: string
  subscription_plans?: { name: string }
}

export default function AccountPage() {
  const { data: session, status } = useSession()
  const dbClient = createClient()
  const [subscription, setSubscription] = useState<Subscription | null>(null)
  const [saving, setSaving] = useState(false)
  const [message, setMessage] = useState('')

  const user = session?.user ?? null
  const loading = status === 'loading'

  useEffect(() => {
    if (!user?.id) return
    async function loadSubscription() {
      try {
        const data = await apiGet(
          '/api/subscription',
          subscriptionResponseSchema,
          { ttlMs: 0 },
        )
        setSubscription({
          plan_id: data.plan || 'free',
          status: data.status || 'active',
          trial_ends_at: data.trialEndsAt || '',
          current_period_end: data.periodEnd || new Date(Date.now() + 30 * 86400000).toISOString(),
        })
      } catch (err) {
        if (err instanceof ApiError) {
          // Subscription fetch failed — keep default
        }
      }
    }
    loadSubscription()
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id])

  async function updatePassword(newPassword: string) {
    setSaving(true)
    setMessage('')
    try {
      await apiPost(
        '/api/auth/update-password',
        updatePasswordMutationSchema,
        { password: newPassword },
      )
      setMessage('Password updated successfully!')
    } catch (err) {
      if (err instanceof ApiError) {
        setMessage('Error: ' + err.message)
      } else {
        setMessage('Error: Password update failed')
      }
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="text-[var(--accent)]">Loading...</div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)] py-16">
      <div className="max-w-3xl mx-auto px-6">
        <h1 className="text-3xl font-bold text-[var(--text-primary)] mb-8">Account Settings</h1>

        <div className="space-y-8">
          <Section title="Profile">
            <div className="space-y-4">
              <div>
                <label htmlFor="account-email" className="block text-sm text-[var(--text-secondary)] mb-1">Email</label>
                <input id="account-email"
                  type="email"
                  value={user?.email || ''}
                  disabled
                  className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg px-4 py-2 text-[var(--text-muted)]"
                />
              </div>
            </div>
          </Section>

          <Section title="Change Password">
            <form
              onSubmit={(e) => {
                e.preventDefault()
                const form = e.target as HTMLFormElement
                const newPassword = (form.elements.namedItem('newPassword') as HTMLInputElement).value
                updatePassword(newPassword)
              }}
              className="space-y-4"
            >
              <div>
                <label htmlFor="account-new-password" className="block text-sm text-[var(--text-secondary)] mb-1">New Password</label>
                <input id="account-new-password"
                  name="newPassword"
                  type="password"
                  required
                  minLength={6}
                  className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg px-4 py-2 text-[var(--text-primary)]"
                />
              </div>
              <button
                type="submit"
                disabled={saving}
                className="bg-[var(--accent)] text-black px-6 py-2 rounded-lg font-medium hover:bg-[var(--accent-dim)] disabled:opacity-50"
              >
                {saving ? 'Updating...' : 'Update Password'}
              </button>
              {message && (
                <p className={`text-sm ${message.includes('Error') ? 'text-red-500' : 'text-green-500'}`}>
                  {message}
                </p>
              )}
            </form>
          </Section>

          <Section title="Subscription">
            {subscription ? (
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-[var(--text-primary)] font-medium capitalize">
                      {subscription.subscription_plans?.name || subscription.plan_id} Plan
                    </p>
                    <p className="text-[var(--text-secondary)] text-sm">
                      {subscription.status === 'trial' 
                        ? `Trial ends ${new Date(subscription.trial_ends_at).toLocaleDateString()}`
                        : `Renews ${new Date(subscription.current_period_end).toLocaleDateString()}`
                      }
                    </p>
                  </div>
                  <span className={`text-xs px-2 py-1 rounded ${
                    subscription.plan_id === 'enterprise' ? 'bg-amber-900/50 text-amber-400' :
                    subscription.plan_id === 'firm' ? 'bg-purple-900/50 text-purple-400' :
                    subscription.plan_id === 'team' ? 'bg-blue-900/50 text-blue-400' :
                    subscription.plan_id === 'pro' ? 'bg-green-900/50 text-green-400' :
                    'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'
                  }`}>
                    {subscription.plan_id.toUpperCase()}
                  </span>
                </div>
                <a
                  href="/pricing"
                  className="inline-block bg-[var(--accent)] text-black px-6 py-2 rounded-lg font-medium hover:bg-[var(--accent-dim)]"
                >
                  {subscription.plan_id === 'free' ? 'Upgrade Plan' : 'Manage Plan'}
                </a>
              </div>
            ) : (
              <p className="text-[var(--text-secondary)]">No active subscription</p>
            )}
          </Section>

          <Section title="Payment History">
            <p className="text-[var(--text-secondary)]">No payment history yet.</p>
          </Section>

          <Section title="Danger Zone">
            <div className="bg-red-900/20 border border-red-800 rounded-lg p-4">
              <h4 className="text-red-400 font-medium mb-2">Delete Account</h4>
              <p className="text-[var(--text-secondary)] text-sm mb-4">
                Once you delete your account, there is no going back. All your projects and data will be permanently deleted.
              </p>
              <button className="bg-red-900 text-red-400 px-4 py-2 rounded-lg text-sm hover:bg-red-800">
                Delete My Account
              </button>
            </div>
          </Section>
        </div>
      </div>
    </div>
  )
}

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
      <h2 className="text-xl font-semibold text-[var(--text-primary)] mb-4">{title}</h2>
      {children}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { Menu, X } from 'lucide-react'
import AppSidebar from '@/components/layout/AppSidebar'
import { PerformanceMonitor } from '@/components/admin/PerformanceMonitor'
import MetarduLogo from '@/components/MetarduLogo'

// ---------------------------------------------------------------------------
// Layout
// ---------------------------------------------------------------------------

export default function AdminLayout({
  children,
}: {
  children: React.ReactNode
}) {
  const [sidebarOpen, setSidebarOpen] = useState(false)

  return (
    <div className="min-h-screen flex">
      {/* Mobile overlay */}
      {sidebarOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/50 lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar — unified AppSidebar component */}
      <aside
        className={`
          fixed lg:sticky top-0 left-0 z-50 lg:z-auto
          w-64 h-screen lg:h-auto
          transform transition-transform duration-200 ease-in-out
          ${sidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
        `}
      >
        <AppSidebar
          variant="admin"
          onNavigate={() => setSidebarOpen(false)}
        />
      </aside>

      {/* Main content */}
      <div className="flex-1 min-w-0">
        {/* Mobile header */}
        <div className="lg:hidden flex items-center gap-3 px-4 py-3 border-b border-[var(--border-color)] bg-[var(--bg-secondary)]">
          <button
            onClick={() => setSidebarOpen(true)}
            className="p-2 -ml-2 text-[var(--text-secondary)] hover:text-[var(--text-primary)]"
          >
            <Menu className="w-5 h-5" />
          </button>
          <MetarduLogo size={24} showWordmark={true} color="var(--text-primary)" />
          <span className="ml-auto text-xs text-[var(--text-muted)] uppercase tracking-wider">Admin</span>
        </div>

        {/* Page content */}
        <div className="p-4 md:p-6 lg:p-8 max-w-7xl mx-auto">
          {children}
        </div>

        {/* Performance Monitor — admin-only Core Web Vitals overlay */}
        <PerformanceMonitor visible={true} />
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState, useCallback } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import {
  Users, FolderKanban, LandPlot, RadioTower,
  DollarSign, Activity, Clock, Database,
  HardDrive, Cpu, TrendingUp,
  UserPlus, ShieldCheck, Settings2, FileText,
  CreditCard, Loader2, AlertCircle, ChevronRight,
  Megaphone, Check, X,
} from 'lucide-react'
import { z } from 'zod'
import { apiGet, apiPost, apiPatch, ApiError } from '@/lib/api/client'
import dynamic from 'next/dynamic'
import { RevenueLineChart, SubscriptionDonutChart, Sparkline } from '@/components/admin/charts/AdminCharts'
import SystemHealthPanel from '@/components/admin/SystemHealthPanel'

const DashboardSearch = dynamic(
  () => import('@/components/dashboard/DashboardSearch').then(m => m.default || m),
  { ssr: false },
)
const PerformanceDashboard = dynamic(
  () => import('@/components/PerformanceDashboard').then(m => m.default || m),
  { ssr: false },
)

// ponytail: response schemas — Phase 4 wave 2 will move these to src/lib/api/schemas/

// Dashboard payload is large and may grow; accept any object shape and cast to DashboardData.
const dashboardResponseSchema = z.record(z.any())

const announcementMutationSchema = z.object({
  ok: z.boolean().optional(),
  id: z.union([z.string(), z.number()]).optional(),
}).passthrough()

const overridePlanMutationSchema = z.object({
  ok: z.boolean().optional(),
  plan: z.string().optional(),
}).passthrough()

const verifyIskMutationSchema = z.object({
  ok: z.boolean().optional(),
  verified: z.boolean().optional(),
}).passthrough()

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface DashboardData {
  users: {
    total: number
    newThisMonth: number
    active: number
  }
  projects: {
    total: number
    byStatus: Record<string, number>
  }
  parcels: number
  beacons: number
  revenue: {
    total: number
    byMonth: { month: string; total: number }[]
  }
  recentSignups: {
    id: string
    email: string
    name: string
    role: string
    plan: string
    createdAt: string
  }[]
  iskPendingCount: number
  iskQueue: {
    id: string
    email: string
    name: string
    iskNumber: string
    submittedAt: string
  }[]
  activeSubscriptions: { free: number; pro: number; enterprise: number }
  submissionsThisMonth: number
  system: {
    database: {
      status: string
      latencyMs: number
    }
    uptime: number
    memory: {
      heapUsedMb: number
      heapTotalMb: number
      rssMb: number
    }
    responseTimeMs: number
  }
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function formatUptime(seconds: number): string {
  const days = Math.floor(seconds / 86400)
  const hrs = Math.floor((seconds % 86400) / 3600)
  const mins = Math.floor((seconds % 3600) / 60)
  if (days > 0) return `${days}d ${hrs}h`
  if (hrs > 0) return `${hrs}h ${mins}m`
  return `${mins}m`
}

function formatCurrency(amount: number): string {
  return new Intl.NumberFormat('en-KE', {
    style: 'currency',
    currency: 'KES',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(amount)
}

function formatDate(dateStr: string): string {
  return new Date(dateStr).toLocaleDateString('en-KE', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  })
}

function roleBadgeClass(role: string): string {
  switch (role) {
    case 'super_admin':
      return 'bg-red-500/15 text-red-400 border-red-500/30'
    case 'org_admin':
      return 'bg-orange-500/15 text-orange-400 border-orange-500/30'
    case 'admin':
      return 'bg-orange-500/15 text-orange-400 border-orange-500/30'
    case 'project_manager':
      return 'bg-blue-500/15 text-blue-400 border-blue-500/30'
    case 'surveyor':
      return 'bg-green-500/15 text-green-400 border-green-500/30'
    case 'viewer':
      return 'bg-gray-500/15 text-gray-400 border-gray-500/30'
    default:
      return 'bg-gray-500/15 text-gray-400 border-gray-500/30'
  }
}

// ---------------------------------------------------------------------------
// Stat Card
// ---------------------------------------------------------------------------

function StatCard({
  icon: Icon,
  label,
  value,
  subValue,
  trend,
  color = 'var(--accent)',
}: {
  icon: React.ComponentType<{ className?: string }>
  label: string
  value: string | number
  subValue?: string
  trend?: 'up' | 'down' | 'neutral'
  color?: string
}) {
  return (
    <div className="card p-5 flex flex-col gap-3">
      <div className="flex items-center justify-between">
        <div
          className="w-10 h-10 rounded-lg flex items-center justify-center"
          style={{ backgroundColor: `${color}15` }}
        >
          <span style={{ color }}><Icon className="w-5 h-5" /></span>
        </div>
        {trend === 'up' && (
          <div className="flex items-center gap-1 text-xs text-green-400">
            <TrendingUp className="w-3 h-3" />
            <span>Up</span>
          </div>
        )}
      </div>
      <div>
        <p className="text-2xl font-bold text-[var(--text-primary)]">{value}</p>
        {subValue && (
          <p className="text-xs text-[var(--text-muted)] mt-0.5">{subValue}</p>
        )}
      </div>
      <p className="text-xs text-[var(--text-secondary)]">{label}</p>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Main Page
// ---------------------------------------------------------------------------

export default function AdminDashboardPage() {
  const { data: session, status: sessionStatus } = useSession()
  const router = useRouter()
  const [data, setData] = useState<DashboardData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Broadcast state
  const [announcementTitle, setAnnouncementTitle] = useState('')
  const [announcementBody, setAnnouncementBody] = useState('')
  const [announcementTarget, setAnnouncementTarget] = useState('all')
  const [broadcastSending, setBroadcastSending] = useState(false)
  const [broadcastResult, setBroadcastResult] = useState<{ ok: boolean; msg: string } | null>(null)

  // Subscription override state
  const [overrideEmail, setOverrideEmail] = useState('')
  const [overridePlan, setOverridePlan] = useState('pro')
  const [overrideDays, setOverrideDays] = useState('30')
  const [overrideSending, setOverrideSending] = useState(false)
  const [overrideResult, setOverrideResult] = useState<{ ok: boolean; msg: string } | null>(null)

  // ISK queue processing
  const [iskProcessing, setIskProcessing] = useState<Set<string>>(new Set())

  const fetchDashboard = useCallback(async () => {
    try {
      setLoading(true)
      setError(null)
      const json = await apiGet('/api/admin/dashboard', dashboardResponseSchema, { ttlMs: 0 })
      setData(json as unknown as DashboardData)
    } catch (err) {
      if (err instanceof ApiError) {
        if (err.isUnauthorized) {
          router.push('/login')
          return
        }
        if (err.isForbidden) {
          router.push('/dashboard')
          return
        }
        setError(err.message)
      } else {
        setError(err instanceof Error ? err.message : 'Failed to load dashboard')
      }
    } finally {
      setLoading(false)
    }
  }, [router])

  useEffect(() => {
    if (sessionStatus === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (sessionStatus === 'authenticated') {
      fetchDashboard()
    }
  }, [sessionStatus, fetchDashboard, router])

  const handleBroadcast = async () => {
    if (!announcementTitle || !announcementBody) return
    setBroadcastSending(true)
    setBroadcastResult(null)
    try {
      await apiPost(
        '/api/admin/announcements',
        announcementMutationSchema,
        {
          title: announcementTitle,
          body: announcementBody,
          target: announcementTarget,
        },
      )
      setBroadcastResult({ ok: true, msg: 'Announcement sent successfully!' })
      setAnnouncementTitle('')
      setAnnouncementBody('')
    } catch (err) {
      const msg = err instanceof ApiError ? err.message : 'Network error'
      setBroadcastResult({ ok: false, msg })
    } finally {
      setBroadcastSending(false)
    }
  }

  const handleOverride = async () => {
    if (!overrideEmail || !overridePlan) return
    setOverrideSending(true)
    setOverrideResult(null)
    try {
      await apiPatch(
        '/api/admin/users/override-plan',
        overridePlanMutationSchema,
        {
          email: overrideEmail,
          plan: overridePlan,
          days: parseInt(overrideDays, 10) || 30,
        },
      )
      setOverrideResult({ ok: true, msg: `Plan updated to ${overridePlan} for ${overrideDays} days` })
      setOverrideEmail('')
    } catch (err) {
      const msg = err instanceof ApiError ? err.message : 'Network error'
      setOverrideResult({ ok: false, msg })
    } finally {
      setOverrideSending(false)
    }
  }

  const handleIskAction = async (userId: string, approve: boolean) => {
    setIskProcessing(prev => new Set(prev).add(userId))
    try {
      await apiPatch(
        `/api/admin/users/${userId}/verify-isk`,
        verifyIskMutationSchema,
        { verified: approve },
      )
      // Remove from queue locally
      setData(prev => prev ? {
        ...prev,
        iskQueue: prev.iskQueue.filter(u => u.id !== userId),
        iskPendingCount: Math.max(0, prev.iskPendingCount - 1),
      } : prev)
    } catch (err) {
      // ponytail: surface the failure so the admin knows to retry — previously this was a silent swallow
      const msg = err instanceof ApiError ? err.message : 'Failed to update ISK status'
      setError(msg)
    } finally {
      setIskProcessing(prev => {
        const next = new Set(prev)
        next.delete(userId)
        return next
      })
    }
  }

  // Loading state
  if (sessionStatus === 'loading' || (loading && !data)) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="flex flex-col items-center gap-3">
          <Loader2 className="w-8 h-8 text-[var(--accent)] animate-spin" />
          <p className="text-sm text-[var(--text-secondary)]">Loading admin dashboard...</p>
        </div>
      </div>
    )
  }

  // Error state
  if (error && !data) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="card p-8 max-w-md w-full mx-4 text-center">
          <AlertCircle className="w-12 h-12 text-red-400 mx-auto mb-4" />
          <h2 className="text-lg font-semibold text-[var(--text-primary)] mb-2">
            Failed to Load Dashboard
          </h2>
          <p className="text-sm text-[var(--text-secondary)] mb-4">{error}</p>
          <button onClick={fetchDashboard} className="btn btn-primary">
            Retry
          </button>
        </div>
      </div>
    )
  }

  if (!data) return null

  const userRole = (session?.user as { role?: string })?.role ?? ''
  const isSuperAdmin = userRole === 'super_admin'
  const isAdminRole = userRole === 'admin' || userRole === 'super_admin'
  const canOverridePlans = isAdminRole

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[var(--text-primary)]">Admin Dashboard</h1>
          <p className="text-sm text-[var(--text-secondary)] mt-1">
            Platform overview for Metardu administrators
          </p>
        </div>
        <div className="flex items-center gap-3">
          <DashboardSearch />
          <button
            onClick={fetchDashboard}
            className="btn btn-secondary text-sm"
            disabled={loading}
          >
            {loading ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <Activity className="w-4 h-4" />
            )}
            Refresh
          </button>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
        <StatCard
          icon={Users}
          label="Total Users"
          value={data.users.total.toLocaleString()}
          subValue={`${data.users.newThisMonth} new this month`}
          trend="up"
          color="#4ade80"
        />
        <StatCard
          icon={Activity}
          label="Active Users"
          value={data.users.active.toLocaleString()}
          subValue="Last 30 days"
          color="#60a5fa"
        />
        <StatCard
          icon={FolderKanban}
          label="Total Projects"
          value={data.projects.total.toLocaleString()}
          subValue={Object.entries(data.projects.byStatus)
            .map(([s, c]) => `${s}: ${c}`)
            .join(', ')}
          color="#f59e0b"
        />
        <StatCard
          icon={LandPlot}
          label="Total Parcels"
          value={data.parcels.toLocaleString()}
          color="#a78bfa"
        />
        <StatCard
          icon={RadioTower}
          label="Total Beacons"
          value={data.beacons.toLocaleString()}
          color="#f472b6"
        />
      </div>

      {/* Extended Stats Row + Subscription Donut */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <StatCard
          icon={CreditCard}
          label="Pro Subscribers"
          value={data.activeSubscriptions?.pro ?? 0}
          subValue={`Enterprise: ${data.activeSubscriptions?.enterprise ?? 0}`}
          color="#a78bfa"
        />
        <StatCard
          icon={FileText}
          label="Submissions (month)"
          value={data.submissionsThisMonth ?? 0}
          subValue="This calendar month"
          color="#34d399"
        />
        <StatCard
          icon={ShieldCheck}
          label="ISK Pending Verification"
          value={data.iskPendingCount ?? 0}
          trend={data.iskPendingCount > 0 ? 'up' : 'neutral'}
          color="#fbbf24"
        />
        {/* Subscription Donut Chart */}
        <div className="card p-4">
          <p className="text-xs text-[var(--text-secondary)] mb-2">Subscriptions</p>
          <SubscriptionDonutChart
            data={[
              { name: 'free', value: data.activeSubscriptions?.free ?? 0 },
              { name: 'pro', value: data.activeSubscriptions?.pro ?? 0 },
              { name: 'enterprise', value: data.activeSubscriptions?.enterprise ?? 0 },
            ]}
          />
        </div>
      </div>

      {/* Revenue + ISK Verification Queue */}
      <div className="grid lg:grid-cols-2 gap-6">
        {/* Revenue Overview */}
        <div className="card">
          <div className="card-header">
            <div className="flex items-center gap-2">
              <DollarSign className="w-5 h-5 text-green-400" />
              <h2 className="text-base font-semibold text-[var(--text-primary)]">
                Revenue Overview
              </h2>
            </div>
            <span className="text-xs text-[var(--text-muted)]">Completed payments</span>
          </div>
          <div className="p-5">
            <p className="text-3xl font-bold text-[var(--text-primary)] mb-4">
              {formatCurrency(data.revenue.total)}
            </p>
            {data.revenue.byMonth.length > 0 ? (
              <RevenueLineChart data={data.revenue.byMonth} />
            ) : (
              <p className="text-sm text-[var(--text-muted)]">No revenue data yet</p>
            )}
          </div>
        </div>

        {/* ISK Verification Queue */}
        <div className="card">
          <div className="card-header">
            <div className="flex items-center gap-2">
              <ShieldCheck className="w-5 h-5 text-amber-400" />
              <h2 className="text-base font-semibold text-[var(--text-primary)]">
                ISK Verification Queue
              </h2>
            </div>
            <Link href="/admin/users?role=surveyor" className="text-xs text-[var(--accent)] hover:underline flex items-center gap-1">
              View all <ChevronRight className="w-3 h-3" />
            </Link>
          </div>
          <div className="p-0">
            {(data.iskQueue ?? []).length > 0 ? (
              <div className="max-h-72 overflow-y-auto">
                <table className="w-full min-w-[480px]">
                  <thead>
                    <tr className="table-header">
                      <th className="px-4 py-2 text-left">Surveyor</th>
                      <th className="px-4 py-2 text-left">ISK No.</th>
                      <th className="px-4 py-2 text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.iskQueue.map((user) => (
                      <tr key={user.id} className="table-row">
                        <td className="table-cell">
                          <div>
                            <p className="text-[var(--text-primary)] font-medium text-sm truncate max-w-[160px]">
                              {user.name}
                            </p>
                            <p className="text-xs text-[var(--text-muted)] truncate max-w-[160px]">
                              {user.email}
                            </p>
                          </div>
                        </td>
                        <td className="table-cell text-sm font-mono">
                          {user.iskNumber}
                        </td>
                        <td className="table-cell text-right">
                          <div className="flex items-center justify-end gap-1.5">
                            <button
                              onClick={() => handleIskAction(user.id, true)}
                              disabled={iskProcessing.has(user.id)}
                              className="w-8 h-8 flex items-center justify-center rounded-lg bg-green-500/10 text-green-400 hover:bg-green-500/20 transition-colors disabled:opacity-50"
                              title="Approve ISK"
                            >
                              {iskProcessing.has(user.id) ? (
                                <Loader2 className="w-3.5 h-3.5 animate-spin" />
                              ) : (
                                <Check className="w-3.5 h-3.5" />
                              )}
                            </button>
                            <button
                              onClick={() => handleIskAction(user.id, false)}
                              disabled={iskProcessing.has(user.id)}
                              className="w-8 h-8 flex items-center justify-center rounded-lg bg-red-500/10 text-red-400 hover:bg-red-500/20 transition-colors disabled:opacity-50"
                              title="Reject ISK"
                            >
                              <X className="w-3.5 h-3.5" />
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="p-5 text-center text-sm text-[var(--text-muted)]">
                No pending ISK verifications
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Recent Signups + Broadcast */}
      <div className="grid lg:grid-cols-2 gap-6">
        {/* Recent Signups */}
        <div className="card">
          <div className="card-header">
            <div className="flex items-center gap-2">
              <UserPlus className="w-5 h-5 text-blue-400" />
              <h2 className="text-base font-semibold text-[var(--text-primary)]">
                Recent Signups
              </h2>
            </div>
            <Link
              href="/admin/users"
              className="text-xs text-[var(--accent)] hover:underline flex items-center gap-1"
            >
              View all <ChevronRight className="w-3 h-3" />
            </Link>
          </div>
          <div className="p-0">
            {data.recentSignups.length > 0 ? (
              <div className="max-h-72 overflow-x-auto overflow-y-auto">
                <table className="w-full min-w-[500px]">
                  <thead>
                    <tr className="table-header">
                      <th className="px-4 py-2 text-left">User</th>
                      <th className="px-4 py-2 text-left">Role</th>
                      <th className="px-4 py-2 text-left">Plan</th>
                      <th className="px-4 py-2 text-right">Joined</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.recentSignups.map((user) => (
                      <tr key={user.id} className="table-row">
                        <td className="table-cell">
                          <div>
                            <p className="text-[var(--text-primary)] font-medium text-sm truncate max-w-[160px]">
                              {user.name}
                            </p>
                            <p className="text-xs text-[var(--text-muted)] truncate max-w-[160px]">
                              {user.email}
                            </p>
                          </div>
                        </td>
                        <td className="table-cell">
                          <span
                            className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium border ${roleBadgeClass(user.role)}`}
                          >
                            {user.role}
                          </span>
                        </td>
                        <td className="table-cell text-sm capitalize">
                          {user.plan}
                        </td>
                        <td className="table-cell text-sm text-right text-[var(--text-muted)]">
                          {formatDate(user.createdAt)}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="p-5 text-center text-sm text-[var(--text-muted)]">
                No users yet
              </div>
            )}
          </div>
        </div>

        {/* Broadcast Announcement */}
        <div className="card">
          <div className="card-header">
            <div className="flex items-center gap-2">
              <Megaphone className="w-5 h-5 text-blue-400" />
              <h2 className="text-base font-semibold text-[var(--text-primary)]">
                Broadcast Announcement
              </h2>
            </div>
          </div>
          <div className="p-5 space-y-3">
            <input
              type="text"
              aria-label="Announcement title" placeholder="Announcement title..."
              className="w-full bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-[var(--text-primary)] text-sm focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/30 outline-none transition-all"
              value={announcementTitle}
              onChange={e => setAnnouncementTitle(e.target.value)}
            />
            <textarea
              placeholder="Message body..."
              rows={3}
              className="w-full bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-[var(--text-primary)] text-sm resize-none focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/30 outline-none transition-all"
              value={announcementBody}
              onChange={e => setAnnouncementBody(e.target.value)}
            />
            <div className="flex gap-2">
              <select
                className="flex-1 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-[var(--text-primary)] text-sm focus:border-[var(--accent)] outline-none transition-all"
                value={announcementTarget}
                onChange={e => setAnnouncementTarget(e.target.value)}
              >
                <option value="all">All Users</option>
                <option value="pro">Pro Users Only</option>
                <option value="free">Free Users Only</option>
                <option value="enterprise">Enterprise Only</option>
              </select>
              <button
                onClick={handleBroadcast}
                className="btn btn-primary flex items-center gap-2"
                disabled={!announcementTitle || !announcementBody || broadcastSending}
              >
                {broadcastSending ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
                Send
              </button>
            </div>
            {broadcastResult && (
              <p className={`text-xs ${broadcastResult.ok ? 'text-green-400' : 'text-red-400'}`}>
                {broadcastResult.msg}
              </p>
            )}
          </div>
        </div>
      </div>

      {/* System Health + Quick Actions + Subscription Override */}
      <div className="grid lg:grid-cols-3 gap-6">
        {/* System Health — Enhanced with charts */}
        <SystemHealthPanel />

        {/* Quick Actions */}
        <div className="card">
          <div className="card-header">
            <h2 className="text-base font-semibold text-[var(--text-primary)]">
              Quick Actions
            </h2>
          </div>
          <div className="p-5 grid grid-cols-2 gap-3">
            <Link
              href="/admin/users"
              className="flex items-center gap-3 p-3 rounded-lg border border-[var(--border-color)] hover:border-[var(--accent)]/40 hover:bg-[var(--accent)]/5 transition-all group"
            >
              <Users className="w-5 h-5 text-[var(--accent)]" />
              <div>
                <p className="text-sm font-medium text-[var(--text-primary)] group-hover:text-[var(--accent)]">
                  User Management
                </p>
                <p className="text-xs text-[var(--text-muted)]">Manage users & roles</p>
              </div>
            </Link>

            <Link
              href="/audit-logs"
              className="flex items-center gap-3 p-3 rounded-lg border border-[var(--border-color)] hover:border-[var(--accent)]/40 hover:bg-[var(--accent)]/5 transition-all group"
            >
              <ShieldCheck className="w-5 h-5 text-[var(--accent)]" />
              <div>
                <p className="text-sm font-medium text-[var(--text-primary)] group-hover:text-[var(--accent)]">
                  Audit Logs
                </p>
                <p className="text-xs text-[var(--text-muted)]">View security logs</p>
              </div>
            </Link>

            <Link
              href="/admin/payments"
              className="flex items-center gap-3 p-3 rounded-lg border border-[var(--border-color)] hover:border-[var(--accent)]/40 hover:bg-[var(--accent)]/5 transition-all group"
            >
              <CreditCard className="w-5 h-5 text-[var(--accent)]" />
              <div>
                <p className="text-sm font-medium text-[var(--text-primary)] group-hover:text-[var(--accent)]">
                  Payments
                </p>
                <p className="text-xs text-[var(--text-muted)]">Revenue & billing</p>
              </div>
            </Link>

            <Link
              href="/admin"
              className="flex items-center gap-3 p-3 rounded-lg border border-[var(--border-color)] hover:border-[var(--accent)]/40 hover:bg-[var(--accent)]/5 transition-all group"
            >
              <Settings2 className="w-5 h-5 text-[var(--accent)]" />
              <div>
                <p className="text-sm font-medium text-[var(--text-primary)] group-hover:text-[var(--accent)]">
                  System Health
                </p>
                <p className="text-xs text-[var(--text-muted)]">View diagnostics</p>
              </div>
            </Link>
          </div>
        </div>

        {/* Subscription Override (admin/super_admin) */}
        {canOverridePlans && (
          <div className="card">
            <div className="card-header">
              <div className="flex items-center gap-2">
                <CreditCard className="w-5 h-5 text-purple-400" />
                <h2 className="text-base font-semibold text-[var(--text-primary)]">
                  Subscription Override
                </h2>
              </div>
            </div>
            <div className="p-5 space-y-3">
              <input
                type="email"
                aria-label="User email" placeholder="User email..."
                className="w-full bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-[var(--text-primary)] text-sm focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/30 outline-none transition-all"
                value={overrideEmail}
                onChange={e => setOverrideEmail(e.target.value)}
              />
              <div className="flex gap-2">
                <select
                  className="flex-1 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-[var(--text-primary)] text-sm focus:border-[var(--accent)] outline-none transition-all"
                  value={overridePlan}
                  onChange={e => setOverridePlan(e.target.value)}
                >
                  <option value="free">Free</option>
                  <option value="pro">Pro</option>
                  <option value="enterprise">Enterprise</option>
                </select>
                <input
                  type="number"
                  aria-label="Override duration (days)" placeholder="Days"
                  className="w-24 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-[var(--text-primary)] text-sm focus:border-[var(--accent)] outline-none transition-all"
                  value={overrideDays}
                  onChange={e => setOverrideDays(e.target.value)}
                />
                <button
                  onClick={handleOverride}
                  className="btn btn-primary flex items-center gap-2"
                  disabled={!overrideEmail || overrideSending}
                >
                  {overrideSending ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
                  Apply
                </button>
              </div>
              {overrideResult && (
                <p className={`text-xs ${overrideResult.ok ? 'text-green-400' : 'text-red-400'}`}>
                  {overrideResult.msg}
                </p>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Performance Dashboard — Web Vitals & Optimization */}
      <div className="card">
        <div className="card-header">
          <div className="flex items-center gap-2">
            <Activity className="w-5 h-5 text-[var(--accent)]" />
            <h2 className="text-base font-semibold text-[var(--text-primary)]">
              Performance Monitoring
            </h2>
          </div>
        </div>
        <div className="[&_*]:text-[var(--text-primary)] [&_.bg-gray-900]:bg-[var(--bg-primary)] [&_.bg-gray-800]:bg-[var(--bg-secondary)] [&_.bg-gray-700]:bg-[var(--bg-tertiary)] [&_.text-white]:text-[var(--text-primary)] [&_.text-gray-400]:text-[var(--text-muted)] [&_.text-gray-300]:text-[var(--text-secondary)] [&_.text-gray-500]:text-[var(--text-muted)] [&_.border-gray-700]:border-[var(--border-color)] [&_.border-b_border-gray-700]:border-[var(--border-color)]">
          <PerformanceDashboard />
        </div>
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState, useCallback } from 'react'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import {
  CreditCard, DollarSign, Loader2, AlertCircle,
  ChevronLeft, ChevronRight, Download,
} from 'lucide-react'
import { MobilePaymentCard } from '@/components/admin/MobileCards'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface PaymentRecord {
  id: string
  userId: string
  userEmail: string
  userName: string
  amount: number
  currency: string
  status: string
  method: string
  planId: string
  createdAt: string
}

interface Pagination {
  page: number
  limit: number
  total: number
  totalPages: number
  hasMore: boolean
}

interface PaymentsResponse {
  payments: PaymentRecord[]
  pagination: Pagination
  summary: {
    totalRevenue: number
    thisMonth: number
    pendingPayouts: number
  }
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function formatDate(dateStr: string): string {
  return new Date(dateStr).toLocaleDateString('en-KE', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  })
}

function formatCurrency(amount: number): string {
  return new Intl.NumberFormat('en-KE', {
    style: 'currency',
    currency: 'KES',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(amount)
}

function statusBadgeClass(status: string): string {
  switch (status) {
    case 'completed':
      return 'bg-green-500/15 text-green-400 border-green-500/30'
    case 'pending':
      return 'bg-yellow-500/15 text-yellow-400 border-yellow-500/30'
    case 'failed':
      return 'bg-red-500/15 text-red-400 border-red-500/30'
    case 'refunded':
      return 'bg-blue-500/15 text-blue-400 border-blue-500/30'
    default:
      return 'bg-gray-500/15 text-gray-400 border-gray-500/30'
  }
}

// ---------------------------------------------------------------------------
// Stat Card
// ---------------------------------------------------------------------------

function StatCard({
  icon: Icon,
  label,
  value,
  subValue,
  color = 'var(--accent)',
}: {
  icon: React.ComponentType<{ className?: string }>
  label: string
  value: string | number
  subValue?: string
  color?: string
}) {
  return (
    <div className="card p-5 flex flex-col gap-3">
      <div className="flex items-center justify-between">
        <div
          className="w-10 h-10 rounded-lg flex items-center justify-center"
          style={{ backgroundColor: `${color}15` }}
        >
          <span style={{ color }}><Icon className="w-5 h-5" /></span>
        </div>
      </div>
      <div>
        <p className="text-2xl font-bold text-[var(--text-primary)]">{value}</p>
        {subValue && (
          <p className="text-xs text-[var(--text-muted)] mt-0.5">{subValue}</p>
        )}
      </div>
      <p className="text-xs text-[var(--text-secondary)]">{label}</p>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Main Page
// ---------------------------------------------------------------------------

export default function AdminPaymentsPage() {
  const { data: session, status: sessionStatus } = useSession()
  const router = useRouter()

  const [payments, setPayments] = useState<PaymentRecord[]>([])
  const [pagination, setPagination] = useState<Pagination>({
    page: 1,
    limit: 25,
    total: 0,
    totalPages: 0,
    hasMore: false,
  })
  const [summary, setSummary] = useState({ totalRevenue: 0, thisMonth: 0, pendingPayouts: 0 })
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchPayments = useCallback(
    async (page = 1) => {
      try {
        setLoading(true)
        setError(null)
        const params = new URLSearchParams({
          page: String(page),
          limit: '25',
        })

        const res = await fetch(`/api/admin/payments?${params}`)
        if (res.status === 401) {
          router.push('/login')
          return
        }
        if (res.status === 403) {
          router.push('/dashboard')
          return
        }
        if (!res.ok) throw new Error('Failed to fetch payments')

                const data: PaymentsResponse = await res.json() as unknown as PaymentsResponse
        setPayments(data.payments || [])
        setPagination(data.pagination || pagination)
        setSummary(data.summary || summary)
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load payments')
      } finally {
        setLoading(false)
      }
    },
    [router],
  )

  useEffect(() => {
    if (sessionStatus === 'unauthenticated') {
      router.push('/login')
      return
    }
    if (sessionStatus === 'authenticated') {
      fetchPayments(1)
    }
  }, [sessionStatus, fetchPayments, router])

  const handlePageChange = (newPage: number) => {
    fetchPayments(newPage)
  }

  // Auth loading
  if (sessionStatus === 'loading') {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <Loader2 className="w-8 h-8 text-[var(--accent)] animate-spin" />
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[var(--text-primary)]">Payments</h1>
          <p className="text-sm text-[var(--text-secondary)] mt-1">
            Track revenue, transactions, and payout status
          </p>
        </div>
      </div>

      {/* Summary Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <StatCard
          icon={DollarSign}
          label="Total Revenue"
          value={formatCurrency(summary.totalRevenue)}
          color="#4ade80"
        />
        <StatCard
          icon={CreditCard}
          label="This Month"
          value={formatCurrency(summary.thisMonth)}
          subValue="Completed transactions"
          color="#60a5fa"
        />
        <StatCard
          icon={Download}
          label="Pending Payouts"
          value={formatCurrency(summary.pendingPayouts)}
          subValue="Awaiting processing"
          color="#f59e0b"
        />
      </div>

      {/* Error */}
      {error && (
        <div className="card p-4 border-red-500/30 flex items-center gap-3">
          <AlertCircle className="w-5 h-5 text-red-400 shrink-0" />
          <p className="text-sm text-red-400">{error}</p>
          <button
            onClick={() => fetchPayments(pagination.page)}
            className="ml-auto text-xs text-[var(--text-muted)] hover:text-[var(--text-primary)]"
          >
            Retry
          </button>
        </div>
      )}

      {/* Payments — Card layout on mobile, table on lg+ */}
      {/* Mobile: card list */}
      <div className="lg:hidden space-y-3">
        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="w-6 h-6 text-[var(--accent)] animate-spin" />
            <p className="text-sm text-[var(--text-muted)] ml-2">Loading payments...</p>
          </div>
        ) : payments.length === 0 ? (
          <div className="text-center py-12">
            <CreditCard className="w-10 h-10 text-[var(--text-muted)] mx-auto mb-2" />
            <p className="text-sm text-[var(--text-muted)]">No payments found</p>
          </div>
        ) : (
          payments.map((payment) => (
            <MobilePaymentCard key={payment.id} payment={payment} />
          ))
        )}
      </div>

      {/* Desktop: table */}
      <div className="card overflow-hidden hidden lg:block">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="table-header">
                <th className="px-4 py-3 text-left">User</th>
                <th className="px-4 py-3 text-left">Amount</th>
                <th className="px-4 py-3 text-left">Plan</th>
                <th className="px-4 py-3 text-left">Method</th>
                <th className="px-4 py-3 text-left">Status</th>
                <th className="px-4 py-3 text-left">Date</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr>
                  <td colSpan={6} className="px-4 py-12 text-center">
                    <Loader2 className="w-6 h-6 text-[var(--accent)] animate-spin mx-auto" />
                    <p className="text-sm text-[var(--text-muted)] mt-2">Loading payments...</p>
                  </td>
                </tr>
              ) : payments.length === 0 ? (
                <tr>
                  <td colSpan={6} className="px-4 py-12 text-center">
                    <CreditCard className="w-10 h-10 text-[var(--text-muted)] mx-auto mb-2" />
                    <p className="text-sm text-[var(--text-muted)]">No payments found</p>
                  </td>
                </tr>
              ) : (
                payments.map((payment) => (
                  <tr key={payment.id} className="table-row">
                    <td className="table-cell">
                      <div>
                        <p className="text-[var(--text-primary)] font-medium text-sm">
                          {payment.userName}
                        </p>
                        <p className="text-xs text-[var(--text-muted)]">{payment.userEmail}</p>
                      </div>
                    </td>
                    <td className="table-cell text-sm font-medium text-[var(--text-primary)]">
                      {formatCurrency(payment.amount)}
                    </td>
                    <td className="table-cell text-sm capitalize text-[var(--text-secondary)]">
                      {payment.planId}
                    </td>
                    <td className="table-cell text-sm text-[var(--text-secondary)] capitalize">
                      {payment.method}
                    </td>
                    <td className="table-cell">
                      <span
                        className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium border ${statusBadgeClass(payment.status)}`}
                      >
                        {payment.status}
                      </span>
                    </td>
                    <td className="table-cell text-sm text-[var(--text-muted)]">
                      {formatDate(payment.createdAt)}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {!loading && pagination.totalPages > 1 && (
          <div className="flex items-center justify-between px-4 py-3 border-t border-[var(--border-color)]">
            <p className="text-xs text-[var(--text-muted)]">
              Showing {(pagination.page - 1) * pagination.limit + 1}–
              {Math.min(pagination.page * pagination.limit, pagination.total)} of{' '}
              {pagination.total} payments
            </p>
            <div className="flex items-center gap-2">
              <button
                onClick={() => handlePageChange(pagination.page - 1)}
                disabled={pagination.page <= 1}
                className="btn btn-secondary text-xs px-4 py-2.5 disabled:opacity-40"
              >
                <ChevronLeft className="w-4 h-4" />
                Previous
              </button>
              <span className="text-xs text-[var(--text-muted)]">
                Page {pagination.page} of {pagination.totalPages}
              </span>
              <button
                onClick={() => handlePageChange(pagination.page + 1)}
                disabled={!pagination.hasMore}
                className="btn btn-secondary text-xs px-4 py-2.5 disabled:opacity-40"
              >
                Next
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Mobile pagination */}
      {!loading && pagination.totalPages > 1 && (
        <div className="flex items-center justify-between lg:hidden px-2">
          <p className="text-xs text-[var(--text-muted)]">
            {pagination.page} / {pagination.totalPages}
          </p>
          <div className="flex items-center gap-2">
            <button
              onClick={() => handlePageChange(pagination.page - 1)}
              disabled={pagination.page <= 1}
              className="btn btn-secondary text-xs px-3 py-2 disabled:opacity-40"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
            <button
              onClick={() => handlePageChange(pagination.page + 1)}
              disabled={!pagination.hasMore}
              className="btn btn-secondary text-xs px-3 py-2 disabled:opacity-40"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useCallback } from 'react'
import { PageHeader } from '@/components/shared/PageHeader'
import { checkSurveyPlan, type PlanCheckInput, type PlanCheckResult } from '@/lib/marketplace/aiPlanChecker'
import {
  AlertCircle, CheckCircle2, AlertTriangle, Upload, FileText, Shield,
} from 'lucide-react'

interface ImportedPoint {
  name: string
  easting: number
  northing: number
  elevation?: number
}

export default function AIPlanCheckerPage() {
  const [projectName, setProjectName] = useState('')
  const [surveyType, setSurveyType] = useState<PlanCheckInput['surveyType']>('boundary')
  const [country, setCountry] = useState<PlanCheckInput['country']>('kenya')
  const [csvText, setCsvText] = useState('')
  const [result, setResult] = useState<PlanCheckResult | null>(null)
  const [error, setError] = useState('')

  const handleCheck = useCallback(() => {
    setError('')
    setResult(null)

    if (!projectName.trim()) {
      setError('Project name is required.')
      return
    }

    // Parse CSV: name,easting,northing,elevation
    const lines = csvText.trim().split('\n').filter(l => l.trim() && !l.startsWith('#'))
    if (lines.length < 3) {
      setError('At least 3 survey points are required. Paste CSV data (name,easting,northing,elevation).')
      return
    }

    const points: ImportedPoint[] = []
    for (let i = 0; i < lines.length; i++) {
      const parts = lines[i].split(',').map(s => s.trim())
      if (parts.length < 3) {
        setError(`Line ${i + 1}: expected at least 3 columns (name,easting,northing)`)
        return
      }
      const easting = parseFloat(parts[1])
      const northing = parseFloat(parts[2])
      const elevation = parts[3] ? parseFloat(parts[3]) : undefined
      if (isNaN(easting) || isNaN(northing)) {
        setError(`Line ${i + 1}: invalid coordinates`)
        return
      }
      points.push({ name: parts[0], easting, northing, elevation })
    }

    const input: PlanCheckInput = {
      projectName,
      surveyType,
      country,
      points,
    }

    const res = checkSurveyPlan(input)
    setResult(res)
  }, [projectName, surveyType, country, csvText])

  const severityIcon = (severity: string) => {
    switch (severity) {
      case 'error': return <AlertCircle className="w-4 h-4 text-red-400" />
      case 'warning': return <AlertTriangle className="w-4 h-4 text-amber-400" />
      case 'info': return <CheckCircle2 className="w-4 h-4 text-blue-400" />
      default: return <CheckCircle2 className="w-4 h-4 text-green-400" />
    }
  }

  const severityColor = (severity: string) => {
    switch (severity) {
      case 'error': return 'border-red-700/40 bg-red-950/20'
      case 'warning': return 'border-amber-700/40 bg-amber-950/20'
      case 'info': return 'border-blue-700/40 bg-blue-950/20'
      default: return 'border-green-700/40 bg-green-950/20'
    }
  }

  return (
    <div className="max-w-5xl mx-auto px-4 md:px-6 py-8">
      <PageHeader
        title="Plan Compliance Checker"
        subtitle="Automated survey plan compliance checking against regulatory standards"
        reference="Survey Act Cap. 299 | RDM 1.1 | Survey Regulations 1994"
        // AUDIT FIX (2026-07-03): Removed the 'AI' badge — the checker
        // is a deterministic rule engine (5 + 14 rules), not an LLM.
        // Calling it 'AI' was misleading. The functionality is real;
        // only the label was wrong.
      />

      {/* Input form */}
      <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6 mb-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1.5" htmlFor="project-name">Project Name</label>
            <input id="project-name"
              type="text"
              value={projectName}
              onChange={e => setProjectName(e.target.value)}
              placeholder="LR 2090/42"
              className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-sm text-[var(--text-primary)] focus:outline-none focus:border-[var(--accent)]"
            />
          </div>
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1.5" htmlFor="survey-type">Survey Type</label>
            <select id="survey-type"
              value={surveyType}
              onChange={e => setSurveyType(e.target.value as PlanCheckInput['surveyType'])}
              className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-sm text-[var(--text-primary)] focus:outline-none focus:border-[var(--accent)]"
            >
              <option value="boundary">Boundary / Cadastral</option>
              <option value="traverse">Traverse</option>
              <option value="leveling">Levelling</option>
              <option value="topographic">Topographic</option>
              <option value="engineering">Engineering</option>
            </select>
          </div>
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1.5" htmlFor="country">Country</label>
            <select id="country"
              value={country}
              onChange={e => setCountry(e.target.value as PlanCheckInput['country'])}
              className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-sm text-[var(--text-primary)] focus:outline-none focus:border-[var(--accent)]"
            >
              <option value="kenya">Kenya</option>
              <option value="uganda">Uganda</option>
              <option value="tanzania">Tanzania</option>
              <option value="nigeria">Nigeria</option>
              <option value="other">Other</option>
            </select>
          </div>
        </div>

        <div className="mb-4">
          <label className="block text-xs text-[var(--text-muted)] mb-1.5" htmlFor="survey-points-csv-format-name-easting-northing-elevation">
            Survey Points (CSV format: name, easting, northing, elevation)
          </label>
          <textarea
             id="survey-points-csv-format-name-easting-northing-elevation" value={csvText}
            onChange={e => setCsvText(e.target.value)}
            placeholder="TS1, 274812.403, 9856214.778, 1895.250&#10;TS2, 274937.125, 9856340.501, 1897.100&#10;TS3, 275061.802, 9856466.234, 1899.550"
            rows={6}
            className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-sm font-mono text-[var(--text-primary)] placeholder:text-[var(--text-muted)] focus:outline-none focus:border-[var(--accent)]"
          />
        </div>

        {error && (
          <div className="mb-4 p-3 rounded-lg bg-red-950/20 border border-red-700/40 text-red-300 text-sm">
            {error}
          </div>
        )}

        <button
          onClick={handleCheck}
          className="px-6 py-2.5 bg-[var(--accent)] text-[var(--bg-primary)] font-semibold rounded-lg text-sm hover:bg-[var(--accent-dim)] transition-colors"
        >
          <Shield className="w-4 h-4 inline mr-2" />
          Run Compliance Check
        </button>
      </div>

      {/* Results */}
      {result && (
        <div className="space-y-4">
          {/* Score */}
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-[var(--text-primary)]">Compliance Score</h2>
              <div className={`text-3xl font-bold ${
                result.overallScore >= 80 ? 'text-green-400' :
                result.overallScore >= 50 ? 'text-amber-400' : 'text-red-400'
              }`}>
                {result.overallScore}/100
              </div>
            </div>
            <div className={`inline-block px-4 py-1.5 rounded-full text-sm font-medium ${
              result.grade === 'excellent' ? 'bg-green-900/40 text-green-300' :
              result.grade === 'good' ? 'bg-blue-900/40 text-blue-300' :
              result.grade === 'acceptable' ? 'bg-amber-900/40 text-amber-300' :
              'bg-red-900/40 text-red-300'
            }`}>
              Grade: {result.grade} · {result.passed ? 'PASSES' : 'FAILS'} compliance
            </div>
          </div>

          {/* Issues */}
          {result.issues.length > 0 && (
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <h2 className="text-lg font-semibold text-[var(--text-primary)] mb-4">
                Issues Found ({result.issues.length})
              </h2>
              <div className="space-y-2">
                {result.issues.map((issue, i) => (
                  <div
                    key={i}
                    className={`flex items-start gap-3 p-3 rounded-lg border ${severityColor(issue.severity)}`}
                  >
                    {severityIcon(issue.severity)}
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1">
                        <span className="text-sm font-medium text-[var(--text-primary)]">{issue.title}</span>
                        <span className="text-[10px] uppercase tracking-wider text-[var(--text-muted)] px-1.5 py-0.5 rounded bg-[var(--bg-tertiary)]">
                          {issue.category}
                        </span>
                      </div>
                      <p className="text-xs text-[var(--text-muted)]">{issue.description}</p>
                      {issue.recommendation && (
                        <p className="text-xs text-[var(--accent)] mt-1">→ {issue.recommendation}</p>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {result.issues.length === 0 && (
            <div className="bg-green-950/20 border border-green-700/40 rounded-xl p-6 text-center">
              <CheckCircle2 className="w-8 h-8 text-green-400 mx-auto mb-2" />
              <p className="text-sm text-green-300">No compliance issues found. Plan meets all regulatory requirements.</p>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useEffect } from 'react'
import { useSession } from 'next-auth/react'
import {
  AreaChart, Area, XAxis, YAxis, CartesianGrid,
  PieChart, Pie, Cell,
} from 'recharts'
import { ChartContainer, ChartTooltip, ChartTooltipContent, type ChartConfig } from '@/components/ui/chart'
import { Loader2 } from 'lucide-react'
import { logger } from '@/lib/logger'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface AnalyticsData {
  totalProjects: number
  activeProjects: number
  completedSurveys: number
  totalPoints: number
  storageUsed: number
  apiCalls: number
  userActivity: { date: string; count: number }[]
  projectTypes: { type: string; count: number }[]
  // Previous period data for delta computation
  prevTotalProjects: number
  prevActiveProjects: number
  prevCompletedSurveys: number
}

const emptyData: AnalyticsData = {
  totalProjects: 0,
  activeProjects: 0,
  completedSurveys: 0,
  totalPoints: 0,
  storageUsed: 0,
  apiCalls: 0,
  userActivity: [],
  projectTypes: [],
  prevTotalProjects: 0,
  prevActiveProjects: 0,
  prevCompletedSurveys: 0,
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function computeDelta(current: number, previous: number): string | null {
  if (previous === 0 && current === 0) return null
  if (previous === 0) return current > 0 ? '+100%' : null
  const change = ((current - previous) / previous) * 100
  const sign = change >= 0 ? '+' : ''
  return `${sign}${change.toFixed(0)}%`
}

function deltaColor(delta: string | null): string {
  if (!delta) return 'text-[var(--text-muted)]'
  return delta.startsWith('+') ? 'text-green-400' : 'text-red-400'
}

const TYPE_COLORS = ['#60a5fa', '#4ade80', '#f59e0b', '#a78bfa', '#f472b6', '#94a3b8']

const activityChartConfig: ChartConfig = {
  count: { label: 'Projects Created', color: 'hsl(var(--accent))' },
}

const typeChartConfig: ChartConfig = {
  cadastral: { label: 'Cadastral', color: '#60a5fa' },
  topographic: { label: 'Topographic', color: '#4ade80' },
  engineering: { label: 'Engineering', color: '#f59e0b' },
  control: { label: 'Control', color: '#a78bfa' },
  other: { label: 'Other', color: '#94a3b8' },
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function AnalyticsPage() {
  const { data: session, status } = useSession()
  const [period, setPeriod] = useState('7d')
  const [data, setData] = useState<AnalyticsData>(emptyData)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    if (status === 'loading') return
    if (!session?.user?.id) {
      setLoading(false)
      return
    }

    async function fetchAnalytics() {
      try {
        // Use the admin dashboard API for richer data if admin,
        // otherwise fall back to direct DB query via Supabase
        const isAdmin = (session?.user as { role?: string })?.role === 'super_admin' ||
          (session?.user as { role?: string })?.role === 'admin'

        if (isAdmin) {
          const res = await fetch('/api/admin/dashboard')
          if (res.ok) {
            const json = (await res.json()) as {
              data?: {
                projects?: {
                  total?: number
                  byStatus?: Record<string, number>
                }
                parcels?: number
                submissionsThisMonth?: number
                revenue?: { byMonth?: Array<{ month: string; total: number }> }
              }
            }
            const d = (json.data ?? json) as {
              projects?: {
                total?: number
                byStatus?: Record<string, number>
              }
              parcels?: number
              submissionsThisMonth?: number
              revenue?: { byMonth?: Array<{ month: string; total: number }> }
            }
            setData({
              totalProjects: d.projects?.total ?? 0,
              activeProjects: d.projects?.byStatus?.active ?? d.projects?.total ?? 0,
              completedSurveys: d.projects?.byStatus?.completed ?? 0,
              totalPoints: d.parcels ?? 0,
              // AUDIT FIX: Don't fabricate storage from parcel count.
              storageUsed: 0,
              apiCalls: d.submissionsThisMonth ?? 0,
              userActivity: (d.revenue?.byMonth ?? []).map((m: { month: string; total: number }) => ({
                date: m.month,
                count: m.total,
              })),
              projectTypes: Object.entries(d.projects?.byStatus ?? {}).map(([type, count]) => ({
                type,
                count: count as number,
              })),
              // AUDIT FIX: Don't fabricate 'previous period' deltas.
              prevTotalProjects: 0,
              prevActiveProjects: 0,
              prevCompletedSurveys: 0,
            })
          }
        } else {
          // Regular user — query their own projects
          const { createClient } = await import('@/lib/api-client/client')
          const dbClient = createClient()
          const userId = session!.user!.id!

          const [projectsRes, pointsRes] = await Promise.all([
            dbClient.from('projects').select('id, survey_type, created_at').eq('user_id', userId),
            dbClient.from('survey_points').select('id, created_at').eq('user_id', userId),
          ])

          type ProjectRow = { id: string; survey_type: string | null; created_at: string }
          type PointRow = { id: string; created_at: string }
          const projects = (projectsRes.data ?? []) as ProjectRow[]
          const points = (pointsRes.data ?? []) as PointRow[]

          // Build activity based on period
          const days = period === '7d' ? 7 : period === '30d' ? 30 : period === '90d' ? 90 : 365
          const lastNDays: { date: string; count: number }[] = []
          for (let i = days - 1; i >= 0; i--) {
            const d = new Date()
            d.setDate(d.getDate() - i)
            const dateStr = d.toISOString().split('T')[0]
            const count = projects.filter((p) => p.created_at?.startsWith(dateStr)).length
            lastNDays.push({ date: dateStr, count })
          }

          const projectTypesMap: Record<string, number> = {}
          projects.forEach((p) => {
            const type = p.survey_type ?? 'Other'
            projectTypesMap[type] = (projectTypesMap[type] ?? 0) + 1
          })

          // Compute previous period deltas
          const halfPoint = Math.floor(projects.length / 2)
          const recentProjects = projects.slice(0, halfPoint)
          const olderProjects = projects.slice(halfPoint)

          setData({
            totalProjects: projects.length,
            activeProjects: projects.length,
            completedSurveys: projects.filter((p) => p.survey_type !== null).length,
            totalPoints: points.length,
            // AUDIT FIX (2026-07-03): Don't fabricate storage from points count.
            storageUsed: 0,
            // AUDIT FIX: apiCalls=0 was hardcoded. We don't track per-user API calls yet.
            apiCalls: 0,
            userActivity: lastNDays,
            projectTypes: Object.entries(projectTypesMap).map(([type, count]) => ({ type, count })),
            prevTotalProjects: olderProjects.length,
            prevActiveProjects: olderProjects.length,
            prevCompletedSurveys: olderProjects.filter((p) => p.survey_type !== null).length,
          })
        }
      } catch (err) {
        logger.error('Analytics fetch failed:', { error: err })
      } finally {
        setLoading(false)
      }
    }

    fetchAnalytics()
  }, [session?.user?.id, status, period])

  if (loading) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
        <Loader2 className="w-8 h-8 text-[var(--accent)] animate-spin" />
      </div>
    )
  }

  const deltas = {
    totalProjects: computeDelta(data.totalProjects, data.prevTotalProjects),
    activeProjects: computeDelta(data.activeProjects, data.prevActiveProjects),
    completedSurveys: computeDelta(data.completedSurveys, data.prevCompletedSurveys),
    apiCalls: null as string | null,
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)]">
      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="flex flex-wrap justify-between items-center mb-8 gap-4">
          <div>
            <h1 className="text-3xl font-bold text-[var(--text-primary)]">Analytics</h1>
            <p className="text-[var(--text-muted)]">Track your METARDU usage</p>
          </div>
          <select
            value={period}
            onChange={(e) => setPeriod(e.target.value)}
            className="p-2 border border-[var(--border-color)] rounded-lg bg-[var(--bg-secondary)] text-[var(--text-primary)]"
          >
            <option value="7d">Last 7 days</option>
            <option value="30d">Last 30 days</option>
            <option value="90d">Last 90 days</option>
            <option value="1y">Last year</option>
          </select>
        </div>

        {/* Stat cards with computed deltas */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
          {[
            { label: 'Total Projects', value: data.totalProjects, delta: deltas.totalProjects },
            { label: 'Active Projects', value: data.activeProjects, delta: deltas.activeProjects },
            { label: 'Completed Surveys', value: data.completedSurveys, delta: deltas.completedSurveys },
            { label: 'API Calls', value: data.apiCalls, delta: deltas.apiCalls },
          ].map((card) => (
            <div key={card.label} className="bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] p-6">
              <p className="text-sm text-[var(--text-muted)] mb-1">{card.label}</p>
              <p className="text-3xl font-bold text-[var(--text-primary)]">
                {typeof card.value === 'number' ? card.value.toLocaleString() : card.value}
