import { z } from 'zod'

// AUTO-GENERATED by api-row-sweep --apply — REVIEW these column types.
// pg returns bigint/numeric as string, timestamptz as Date; add `| null` where nullable.
interface AuditLogRow {
  id: string
  event_type: string
  description: string
  metadata: unknown
  created_at: Date
}

const insertSchema = z.object({
  event_type: z.string().min(1).max(120),
  description: z.string().min(1).max(500),
  metadata: z.record(z.unknown()).optional(),
})

export const GET = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const { rows } = await db.query<AuditLogRow>(
    `SELECT id, action as event_type, details as description, details as metadata, created_at
     FROM audit_logs
     WHERE user_id = $1
     ORDER BY created_at DESC
     LIMIT 100`,
    [ctx.userId]
  )
  return NextResponse.json({ logs: rows })
})

export const POST = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const parsed = insertSchema.safeParse(ctx.body)
  if (!parsed.success) {
    return NextResponse.json({ error: 'Invalid payload', issues: parsed.error.issues }, { status: 400 })
  }

  const { event_type, description, metadata } = parsed.data

  const { rows } = await db.query<AuditLogRow>(
    `INSERT INTO audit_logs (user_id, action, details)
     VALUES ($1, $2, $3)
     RETURNING id, action as event_type, details as description, details as metadata, created_at`,
    [ctx.userId, event_type, JSON.stringify({ description, ...(metadata ?? {}) })]
  )

  const cpdEvents = ['plan_generated', 'traverse_completed', 'report_exported', 'levelbook_completed']
  if (cpdEvents.includes(event_type)) {
    try {
      await db.query<never>(
        `INSERT INTO cpd_activities (user_id, title, provider, hours, category, source)
         VALUES ($1, $2, $3, $4, $5, $6)`,
        [ctx.userId, 'METARDU Professional Practice', 'METARDU Platform — auto-logged', 0.5, 'Technical Practice', 'METARDU Platform — auto-logged']
      )
    } catch (e) {
      logger.warn('Could not insert CPD activity (table might not exist)', { error: e })
    }
  }

  return NextResponse.json({ log: rows[0] }, { status: 201 })
})

export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { logger } from '@/lib/logger'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { sendTemplatedEmail } from '@/lib/email-templates'
import { db } from '@/lib/db'

// AUTO-GENERATED by api-row-sweep --apply — column types from migrations/*.sql + name heuristics.
// pg returns bigint/numeric as string, timestamptz as Date; nullable columns carry `| null`; REVIEW.
interface UserSubscriptionRow {
  id: string
}
export async function POST(req: NextRequest) {
  const session = await getServerSession(authOptions)
  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const existingSub = await db.query<UserSubscriptionRow>(
    'SELECT id FROM user_subscriptions WHERE user_id = $1',
    [session.user.id]
  )

  if (existingSub.rows.length > 0) {
    return NextResponse.json({ ok: true })
  }

  const now = new Date()
  await db.query<never>(
    `INSERT INTO user_subscriptions 
     (user_id, plan_id, status, trial_ends_at, current_period_start, current_period_end)
     VALUES ($1, 'pro', 'trial', $2, $3, $4)`,
    [
      session.user.id,
      new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000).toISOString(),
      now.toISOString(),
      new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString()
    ]
  )

  // Fire-and-forget welcome email — don't block the response. Sent directly
  // through the template registry (the previous self-HTTP fetch carried no
  // session cookie, so /api/emails/welcome always 401'd and the email never
  // fired), and with the REAL trial end date we just persisted.
  const userEmail = session.user.email
  const userName = session.user.name
  if (userEmail) {
    void sendTemplatedEmail('welcome', {
      to: userEmail,
      name: userName || '',
      trialEndsAt: new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000).toISOString(),
    }).then((res) => {
      if (!res.success && res.error !== 'Email service not configured') {
        logger.warn('[register-complete] Welcome email not sent:', { error: res.error })
      }
    })
  }

  return NextResponse.json({ ok: true })
}

