  const { getSupportedSystems } = await import('@/lib/online/coordinates')
  return NextResponse.json({
    endpoint: '/coordinates/batch',
    description: 'Batch coordinate transformation',
    systems: getSupportedSystems(),
    maxPoints: 1000,
  })
})

