    }
    if (projectCheck.rows[0].project_type !== 'scheme') {
      return NextResponse.json({ error: 'Only scheme projects can have blocks' }, { status: 400 })
    }

    const dupCheck = await db.query<{ id: string }>(
      'SELECT id FROM blocks WHERE project_id = $1 AND block_number = $2',
      [project_id, block_number]
    )
    if (dupCheck.rows.length > 0) {
      return NextResponse.json({ error: `Block "${block_number}" already exists in this project` }, { status: 409 })
    }

    const result = await db.query<BlockRow>(
      `INSERT INTO blocks (project_id, block_number, block_name, description)
      VALUES ($1, $2, $3, $4) RETURNING *`,
      [project_id, block_number, block_name || null, description || null]
    )

    return NextResponse.json({ data: result.rows[0] }, { status: 201 })
  }
)

export const GET = apiHandler(
  { auth: true, rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const { searchParams } = new URL(req.url)
    const projectId = searchParams.get('project_id')

    if (!projectId) {
      return NextResponse.json({ error: 'project_id query parameter is required' }, { status: 400 })
    }

    const projectCheck = await db.query<{ id: string }>(
      'SELECT id FROM projects WHERE id = $1 AND user_id = $2',
      [projectId, ctx.userId]
    )
    if (projectCheck.rows.length === 0) {
      return NextResponse.json({ error: 'Project not found' }, { status: 404 })
    }

    const result = await db.query<BlockWithCountsRow>(
      `SELECT b.*,
      COALESCE(pc.parcel_count, 0) as parcel_count,
      COALESCE(pc.completed_count, 0) as completed_count
      FROM blocks b
      LEFT JOIN (
        SELECT block_id,
        COUNT(*) as parcel_count,
        COUNT(*) FILTER (WHERE status IN ('approved', 'submitted')) as completed_count
        FROM parcels
        GROUP BY block_id
      ) pc ON pc.block_id = b.id
      WHERE b.project_id = $1
      ORDER BY b.block_number ASC`,
      [projectId]
    )

    return NextResponse.json({ data: result.rows })
  }
)

﻿import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { apiHandler } from '@/lib/apiHandler'
import { UpdateBlockSchema } from '@/lib/validation/apiSchemas'

interface BlockCheckRow {
  id: string
  project_id: string
  block_number?: string
  updated_at?: Date
}

interface BlockRow {
  id: string
  project_id: string
  block_number: string
  block_name: string | null
  description: string | null
  created_at: Date
  updated_at: Date
}

export const dynamic = 'force-dynamic'

export const PATCH = apiHandler(
  {
    auth: true,
    schema: UpdateBlockSchema,
    optimisticLock: true,
    audit: 'block_updated',
    rateLimit: { max: 60, windowMs: 60000 },
    // P1-3 (2026-07-24): Scheme block updates are cadastral mutations.
    auditChain: {
      entityType: 'parcel',
      action: 'update',
      entityIdParam: 'id',
      reason: 'scheme block update',
    },
  },
  async (req, ctx) => {
    const blockId = ctx.params.id
    const validated = ctx.body as Record<string, unknown> & {
      block_number?: string; block_name?: string; description?: string; updated_at?: string
    }

    const check = await db.query<BlockCheckRow>(
      `SELECT b.id, b.project_id, b.updated_at FROM blocks b
      JOIN projects p ON p.id = b.project_id
      WHERE b.id = $1 AND p.user_id = $2`,
      [blockId, ctx.userId]
    )
    if (check.rows.length === 0) {
      return NextResponse.json({ error: 'Block not found' }, { status: 404 })
    }

    if (validated.block_number) {
      const dupCheck = await db.query<{ id: string }>(
        `SELECT id FROM blocks WHERE project_id = $1 AND block_number = $2 AND id != $3`,
        [check.rows[0].project_id, validated.block_number, blockId]
      )
      if (dupCheck.rows.length > 0) {
        return NextResponse.json({ error: `Block "${validated.block_number}" already exists` }, { status: 409 })
      }
    }

    const updates: string[] = []
    const values: unknown[] = []
    let paramIndex = 1

    if (validated.block_number !== undefined) {
      updates.push(`block_number = $${paramIndex++}`)
      values.push(validated.block_number)
    }
    if (validated.block_name !== undefined) {
      updates.push(`block_name = $${paramIndex++}`)
      values.push(validated.block_name || null)
    }
    if (validated.description !== undefined) {
      updates.push(`description = $${paramIndex++}`)
      values.push(validated.description || null)
    }

    if (updates.length === 0) {
      return NextResponse.json({ error: 'No fields to update' }, { status: 400 })
    }

    updates.push(`updated_at = NOW()`)
    values.push(blockId)
    // T1.8 FIX (2026-07-09): Optimistic lock guard in the SQL WHERE clause.
    const clientUpdatedAt = validated.updated_at
    if (!clientUpdatedAt) {
      return NextResponse.json({ error: 'updated_at is required for optimistic locking', code: 'CONFLICT' }, { status: 409 })
    }
    values.push(clientUpdatedAt)
    const result = await db.query<BlockRow>(
      `UPDATE blocks SET ${updates.join(', ')} WHERE id = $${paramIndex} AND updated_at = $${paramIndex + 1} RETURNING *`,
      values
    )

    if (result.rows.length === 0) {
      return NextResponse.json(
        { error: 'This block was modified by another user. Please refresh and try again.', code: 'CONFLICT' },
        { status: 409 }
      )
    }

    return NextResponse.json({ data: result.rows[0] })
  }
)

export const DELETE = apiHandler(
  {
    auth: true,
    audit: 'block_deleted',
    rateLimit: { max: 60, windowMs: 60000 },
    auditChain: {
      entityType: 'parcel',
