import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'

interface SchemeParcelRow {
  parcel_number: string
  lr_number_proposed: string | null
  area_ha: number | string | null
  status: string | null
  block_number: string
  station_name: string | null
  easting: number | string | null
  northing: number | string | null
  elevation: number | string | null
}

interface SchemeCoord {
  station: string | null
  x: number
  y: number
  z: number
}

interface ProjectNameRow {
  name: string | null
  scheme_number: string | null
}

export const dynamic = 'force-dynamic'

export const GET = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const { searchParams } = new URL(req.url)
  const projectId = searchParams.get('project_id')
  if (!projectId) {
    return NextResponse.json({ error: 'project_id is required' }, { status: 400 })
  }

  // Fetch all parcels with coordinates
  const { rows: parcels } = await db.query<SchemeParcelRow>(
    `SELECT p.parcel_number, p.lr_number_proposed, p.area_ha, p.status,
      b.block_number,
      tc.station_name, tc.easting, tc.northing, tc.elevation
     FROM parcels p
     JOIN blocks b ON b.id = p.block_id
     LEFT JOIN traverse_coordinates tc ON tc.traverse_id = (
       SELECT id FROM parcel_traverses WHERE parcel_id = p.id AND status IN ('computed', 'approved')
       ORDER BY computed_at DESC LIMIT 1
     )
     WHERE b.project_id = $1
     ORDER BY b.block_number, p.parcel_number`,
    [projectId]
  )

  // Group coordinates by parcel
  const parcelData = new Map<string, { info: SchemeParcelRow; coords: SchemeCoord[] }>()
  parcels.forEach((row) => {
    const key = `${row.block_number}-${row.parcel_number}`
    if (!parcelData.has(key)) {
      parcelData.set(key, {
        info: row,
        coords: [],
      })
    }
    if (row.easting !== null && row.northing !== null) {
      parcelData.get(key)!.coords.push({
        station: row.station_name,
        x: Number(row.easting),
        y: Number(row.northing),
        z: row.elevation ? Number(row.elevation) : 0,
      })
    }
  })

  // Generate DXF content
  const dxfLines: string[] = []

  // HEADER section
  dxfLines.push('0', 'SECTION', '2', 'HEADER')
  dxfLines.push('9', '$ACADVER', '1', 'AC1009') // AutoCAD R12
  dxfLines.push('9', '$INSUNITS', '70', '6') // Meters
  dxfLines.push('0', 'ENDSEC')

  // TABLES section with layers
  dxfLines.push('0', 'SECTION', '2', 'TABLES')
  dxfLines.push('0', 'TABLE', '2', 'LAYER', '70', String(parcelData.size + 3))

  // Define layers
  const layers = [
    { name: '0', color: 7 }, // White (default)
    { name: 'BOUNDARY', color: 1 }, // Red
    { name: 'POINTS', color: 3 }, // Green
    { name: 'TEXT', color: 7 }, // White
    ...Array.from(parcelData.entries()).map(([key, _]) => ({
      name: key.replace(/[^A-Za-z0-9_]/g, '_').substring(0, 31),
      color: 4, // Cyan
    }))
  ]

  layers.forEach(layer => {
    dxfLines.push('0', 'LAYER', '2', layer.name, '70', '0', '62', String(layer.color), '6', 'CONTINUOUS')
  })
  dxfLines.push('0', 'ENDTAB', '0', 'ENDSEC')

  // ENTITIES section
  dxfLines.push('0', 'SECTION', '2', 'ENTITIES')

  // Draw parcel boundaries
  parcelData.forEach((data, key) => {
    const coords = data.coords

    if (coords.length < 2) return

    // Draw boundary lines
    for (let i = 0; i < coords.length; i++) {
      const from = coords[i]
      const to = coords[(i + 1) % coords.length] // close polygon

      dxfLines.push('0', 'LINE', '8', 'BOUNDARY')
      dxfLines.push('10', String(from.x.toFixed(3)), '20', String(from.y.toFixed(3)), '30', '0')
      dxfLines.push('11', String(to.x.toFixed(3)), '21', String(to.y.toFixed(3)), '31', '0')
    }

    // Draw points
    coords.forEach(c => {
      dxfLines.push('0', 'POINT', '8', 'POINTS')
      dxfLines.push('10', String(c.x.toFixed(3)), '20', String(c.y.toFixed(3)), '30', String(c.z.toFixed(3)))
    })

    // Add parcel label at centroid
    if (coords.length > 0) {
      const cx = coords.reduce((s, c) => s + c.x, 0) / coords.length
      const cy = coords.reduce((s, c) => s + c.y, 0) / coords.length

      dxfLines.push('0', 'TEXT', '8', 'TEXT')
      dxfLines.push('10', String(cx.toFixed(3)), '20', String(cy.toFixed(3)), '30', '0')
      dxfLines.push('40', '5') // Text height 5m
      dxfLines.push('1', `${data.info.parcel_number}`)

      dxfLines.push('0', 'TEXT', '8', 'TEXT')
      dxfLines.push('10', String(cx.toFixed(3)), '20', String((cy - 8).toFixed(3)), '30', '0')
      dxfLines.push('40', '3') // Text height 3m
      dxfLines.push('1', `${data.info.area_ha ? Number(data.info.area_ha).toFixed(4) + ' ha' : ''}`)
    }
  })

  dxfLines.push('0', 'ENDSEC', '0', 'EOF')

  const dxfContent = dxfLines.join('\n')
  const project = await db.query<ProjectNameRow>('SELECT name, scheme_number FROM projects p LEFT JOIN scheme_details sd ON sd.project_id = p.id WHERE p.id = $1', [projectId])
  const projRow: ProjectNameRow | undefined = project.rows[0]
  const fileName = `Scheme_${projRow?.scheme_number || projRow?.name || projectId}.dxf`

  return new NextResponse(dxfContent, {
    headers: {
      'Content-Type': 'application/dxf',
      'Content-Disposition': `attachment; filename="${fileName}"`,
    },
  })
})

import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { apiHandler } from '@/lib/apiHandler'
import { CreateParcelSchema } from '@/lib/validation/apiSchemas'
import {
  parcelResponseSchema,
  parcelWithBlockListResponseSchema,
  type Parcel,
  type ParcelWithBlock,
} from '@/lib/validation/scheme'

interface BlockOwnerRow {
  id: string
  project_id: string
}

export const dynamic = 'force-dynamic'

export const POST = apiHandler(
  { auth: true, schema: CreateParcelSchema, audit: 'parcel_created' , rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const { block_id, parcel_number, lr_number_proposed, area_ha, notes } = ctx.body as {
      block_id: string; parcel_number: string; lr_number_proposed?: string;
      area_ha?: number; notes?: string
    }

    const blockCheck = await db.query<BlockOwnerRow>(
      `SELECT b.id, b.project_id FROM blocks b
      JOIN projects p ON p.id = b.project_id
      WHERE b.id = $1 AND p.user_id = $2`,
      [block_id, ctx.userId]
    )
    if (blockCheck.rows.length === 0) {
      return NextResponse.json({ error: 'Block not found in this project' }, { status: 404 })
    }

    const projectId = blockCheck.rows[0].project_id

    const dupCheck = await db.query<{ id: string }>(
      'SELECT id FROM parcels WHERE block_id = $1 AND parcel_number = $2',
      [block_id, parcel_number]
    )
    if (dupCheck.rows.length > 0) {
      return NextResponse.json(
        { error: `Parcel "${parcel_number}" already exists in this block` },
        { status: 409 }
      )
    }

    const result = await db.query<Parcel>(
      `INSERT INTO parcels (project_id, block_id, parcel_number, lr_number_proposed, area_ha, status, notes)
      VALUES ($1, $2, $3, $4, $5, 'pending', $6) RETURNING *`,
      [projectId, block_id, parcel_number, lr_number_proposed || null, area_ha || null, notes || null]
    )

    // Validate the created row against the shared parcel schema — the same one
    // the client type derives from. If it drifts (e.g. an out-of-enum status
    // or a non-UUID id), fail loudly instead of shipping a mismatched parcel.
    const parsed = parcelResponseSchema.safeParse({ data: result.rows[0] })
    if (!parsed.success) {
      // eslint-disable-next-line no-console -- internal response drift log, not user-facing
      console.error('[scheme/parcels] response validation failed:', parsed.error.issues)
      return NextResponse.json({ error: 'Internal response validation failed' }, { status: 500 })
    }
    return NextResponse.json(parsed.data, { status: 201 })
  }
)

export const GET = apiHandler(
  { auth: true, rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const { searchParams } = new URL(req.url)
    const blockId = searchParams.get('block_id')
    const projectId = searchParams.get('project_id')

    if (!blockId && !projectId) {
      return NextResponse.json(
        { error: 'block_id or project_id query parameter is required' },
        { status: 400 }
      )
    }

    if (blockId) {
      const check = await db.query<{ id: string }>(
        `SELECT b.id FROM blocks b
        JOIN projects p ON p.id = b.project_id
        WHERE b.id = $1 AND p.user_id = $2`,
        [blockId, ctx.userId]
      )
      if (check.rows.length === 0) {
        return NextResponse.json({ error: 'Block not found' }, { status: 404 })
      }

      const result = await db.query<ParcelWithBlock>(
        `SELECT p.*, b.block_number, b.block_name
        FROM parcels p
        JOIN blocks b ON b.id = p.block_id
        WHERE p.block_id = $1
        ORDER BY p.parcel_number ASC`,
        [blockId]
      )

      const parsed = parcelWithBlockListResponseSchema.safeParse({ data: result.rows })
      if (!parsed.success) {
        // eslint-disable-next-line no-console -- internal response drift log, not user-facing
        console.error('[scheme/parcels] response validation failed:', parsed.error.issues)
        return NextResponse.json({ error: 'Internal response validation failed' }, { status: 500 })
      }
      return NextResponse.json(parsed.data)
    }

    if (projectId) {
      const check = await db.query<{ id: string }>(
        'SELECT id FROM projects WHERE id = $1 AND user_id = $2',
        [projectId, ctx.userId]
      )
      if (check.rows.length === 0) {
        return NextResponse.json({ error: 'Project not found' }, { status: 404 })
      }

      const result = await db.query<ParcelWithBlock>(
        `SELECT p.*, b.block_number, b.block_name
        FROM parcels p
        JOIN blocks b ON b.id = p.block_id
        WHERE p.project_id = $1
        ORDER BY b.block_number ASC, p.parcel_number ASC`,
        [projectId]
      )

      const parsed = parcelWithBlockListResponseSchema.safeParse({ data: result.rows })
      if (!parsed.success) {
        // eslint-disable-next-line no-console -- internal response drift log, not user-facing
        console.error('[scheme/parcels] response validation failed:', parsed.error.issues)
        return NextResponse.json({ error: 'Internal response validation failed' }, { status: 500 })
      }
      return NextResponse.json(parsed.data)
    }

    return NextResponse.json({ data: [] })
  }
)

import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { apiHandler } from '@/lib/apiHandler'
import { UpdateParcelSchema } from '@/lib/validation/apiSchemas'
import { parcelResponseSchema, type Parcel } from '@/lib/validation/scheme'

interface ParcelCheckRow {
  id: string
  project_id: string
  block_id: string
  parcel_number?: string
  updated_at?: Date
}

export const dynamic = 'force-dynamic'

export const PATCH = apiHandler(
  { auth: true, schema: UpdateParcelSchema, optimisticLock: true, audit: 'parcel_updated',
    auditChain: { entityType: 'parcel', action: 'update', entityIdParam: 'id' },
    rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const parcelId = ctx.params.id
    const validated = ctx.body as Record<string, unknown> & {
      parcel_number?: string; lr_number_proposed?: string; lr_number_confirmed?: string;
      area_ha?: number; status?: string; assigned_surveyor?: string | null; notes?: string;
      updated_at?: string
    }

    const check = await db.query<ParcelCheckRow>(
      `SELECT p.id, p.project_id, p.block_id, p.updated_at FROM parcels p
      JOIN projects pr ON pr.id = p.project_id
      WHERE p.id = $1 AND pr.user_id = $2`,
      [parcelId, ctx.userId]
    )
    if (check.rows.length === 0) {
      return NextResponse.json({ error: 'Parcel not found' }, { status: 404 })
    }

    if (validated.parcel_number) {
      const dupCheck = await db.query<{ id: string }>(
        `SELECT id FROM parcels WHERE block_id = $1 AND parcel_number = $2 AND id != $3`,
        [check.rows[0].block_id, validated.parcel_number, parcelId]
      )
      if (dupCheck.rows.length > 0) {
        return NextResponse.json(
          { error: `Parcel "${validated.parcel_number}" already exists in this block` },
          { status: 409 }
        )
      }
    }

    const updates: string[] = []
    const values: unknown[] = []
    let paramIndex = 1

    const fieldMap: Record<string, unknown> = {
      parcel_number: validated.parcel_number,
      lr_number_proposed: validated.lr_number_proposed,
      lr_number_confirmed: validated.lr_number_confirmed,
      area_ha: validated.area_ha,
      status: validated.status,
      assigned_surveyor: validated.assigned_surveyor,
      notes: validated.notes,
    }

    for (const [field, value] of Object.entries(fieldMap)) {
      if (value !== undefined) {
        updates.push(`"${field}" = $${paramIndex++}`)
        values.push(value)
      }
    }

    if (updates.length === 0) {
      return NextResponse.json({ error: 'No fields to update' }, { status: 400 })
    }

    updates.push(`updated_at = NOW()`)
    values.push(parcelId)
    // T1.8 FIX (2026-07-09): Optimistic lock guard in the SQL WHERE clause itself.
    // The old checkOptimisticLock() did SELECT → JS check → UPDATE without the guard,
    // allowing a TOCTOU race. Now the UPDATE is atomic: if updated_at changed,
    // 0 rows are returned and we send 409.
    const clientUpdatedAt = validated.updated_at
    if (!clientUpdatedAt) {
      return NextResponse.json({ error: 'updated_at is required for optimistic locking', code: 'CONFLICT' }, { status: 409 })
    }
    values.push(clientUpdatedAt)
    const result = await db.query<Parcel>(
      `UPDATE parcels SET ${updates.join(', ')} WHERE id = $${paramIndex} AND updated_at = $${paramIndex + 1} RETURNING *`,
      values
    )

    if (result.rows.length === 0) {
      return NextResponse.json(
        { error: 'This parcel was modified by another user. Please refresh and try again.', code: 'CONFLICT' },
        { status: 409 }
      )
    }

    // Validate the updated row against the shared parcel schema so a status
    // or shape drift can't reach the client unchecked.
    const parsed = parcelResponseSchema.safeParse({ data: result.rows[0] })
    if (!parsed.success) {
      // eslint-disable-next-line no-console -- internal response drift log, not user-facing
      console.error('[scheme/parcels/[id]] response validation failed:', parsed.error.issues)
      return NextResponse.json({ error: 'Internal response validation failed' }, { status: 500 })
    }
    return NextResponse.json(parsed.data)
  }
)

export const DELETE = apiHandler(
  { auth: true, audit: 'parcel_deleted' , rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const parcelId = ctx.params.id

    const check = await db.query<ParcelCheckRow>(
      `SELECT p.id, p.parcel_number FROM parcels p
      JOIN projects pr ON pr.id = p.project_id
      WHERE p.id = $1 AND pr.user_id = $2`,
      [parcelId, ctx.userId]
    )
    if (check.rows.length === 0) {
      return NextResponse.json({ error: 'Parcel not found' }, { status: 404 })
    }

    await db.query<never>('DELETE FROM parcels WHERE id = $1', [parcelId])

    return NextResponse.json({
      message: `Parcel "${check.rows[0].parcel_number}" deleted successfully`
    })
  }
)

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { isAdmin } from '@/lib/auth/rbac'
import { UpdateSchemeStatusSchema } from '@/lib/validation/apiSchemas'

export const dynamic = 'force-dynamic'

/**
 * Scheme status workflow:
 * planning → in_progress → review → approved
 *
 * Only admin users can advance status.
 * Any status can go back to 'planning' (reset).
 */

interface SchemeStatusRow {
  status: string
  updated_at: Date
}

const VALID_TRANSITIONS: Record<string, string[]> = {
  planning: ['in_progress'],
  in_progress: ['review', 'planning'],
  review: ['approved', 'in_progress'],
  approved: [], // Terminal — only DBA can reopen
}

export const GET = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const { searchParams } = new URL(req.url)
  const projectId = searchParams.get('project_id')
  if (!projectId) {
    return NextResponse.json({ error: 'project_id is required' }, { status: 400 })
  }

  const { rows } = await db.query<SchemeStatusRow>(
    'SELECT status, updated_at FROM scheme_details WHERE project_id = $1',
    [projectId]
  )

  if (rows.length === 0) {
    return NextResponse.json({ error: 'Scheme not found' }, { status: 404 })
  }

  const current = rows[0].status
  const allowed = VALID_TRANSITIONS[current] || []

  return NextResponse.json({
    data: {
      current_status: current,
      allowed_transitions: allowed,
      workflow: Object.entries(VALID_TRANSITIONS).map(([from, tos]) => ({ from, to: tos })),
    }
  })
})

export const POST = apiHandler({
  auth: true,
  schema: UpdateSchemeStatusSchema,
  // T1.9 FIX (2026-07-09): Add audit chain for scheme status changes.
  // Status cascades to all parcels in the scheme — needs tamper-evident logging.
  auditChain: {
    entityType: 'parcel',
    action: 'update',
    projectIdFromBody: 'projectId',
    reason: 'Scheme status changed',
  },
}, async (req, ctx) => {
  const userRole = (ctx.session!.user as { role?: string }).role || 'surveyor'

  // Only admins can change scheme status
  if (!isAdmin(userRole)) {
    return NextResponse.json({ error: 'Only admins can change scheme status' }, { status: 403 })
  }

  const { project_id, new_status, reason } = ctx.body as z.infer<typeof UpdateSchemeStatusSchema>

  // Get current status
  const { rows: current } = await db.query<SchemeStatusRow>(
    'SELECT status FROM scheme_details WHERE project_id = $1',
    [project_id]
  )
  if (current.length === 0) {
    return NextResponse.json({ error: 'Scheme not found' }, { status: 404 })
  }

  // Validate transition
  const allowed = VALID_TRANSITIONS[current[0].status] || []
  if (!allowed.includes(new_status) && current[0].status !== new_status) {
    return NextResponse.json({
      error: `Invalid transition: ${current[0].status} → ${new_status}. Allowed: ${allowed.join(', ') || 'none'}`,
      status: 400,
    })
  }

  // Update status
  const { rows } = await db.query<SchemeStatusRow>(
    'UPDATE scheme_details SET status = $1, updated_at = NOW() WHERE project_id = $2 RETURNING status, updated_at',
    [new_status, project_id]
  )

  // Log activity
  await db.query<never>(
    `INSERT INTO scheme_activity_log (project_id, user_id, action, entity_type, entity_id, details)
     VALUES ($1, $2, $3, 'scheme', $1, $4)`,
    [
      project_id,
      ctx.userId,
      `status_change:${new_status}`,
      JSON.stringify({ from: current[0].status, to: new_status, reason: reason || null }),
    ]
  )

  return NextResponse.json({
    data: {
      previous_status: current[0].status,
      new_status: rows[0].status,
      updated_at: rows[0].updated_at,
    }
  })
})

import { NextRequest, NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { z } from 'zod'

interface NextNumRow {
  next_num: number
}

interface ParcelCountRow {
  total: number
  computed: number
}

interface SubmissionTrackRow {
  id: string
  project_id: string
  submission_number: number
  submitted_by: string
  status: string
  documents: unknown
  parcel_count: number
  deed_plan_count: number
  review_notes: string | null
  created_at: Date
  updated_at: Date
  submitted_by_name: string | null
}

export const dynamic = 'force-dynamic'

const createSubmissionSchema = z.object({
  project_id: z.string().min(1),
  notes: z.string().optional(),
})

export const GET = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (request, ctx) => {
  const projectId = request.nextUrl.searchParams.get('project_id')

  if (!projectId) {
    return NextResponse.json({ error: 'project_id is required' }, { status: 400 })
  }

  const { rows } = await db.query<SubmissionTrackRow>(
    `SELECT s.*, u.full_name as submitted_by_name
     FROM submissions s
     LEFT JOIN users u ON u.id = s.submitted_by
     WHERE s.project_id = $1
     ORDER BY s.submission_number DESC`,
    [projectId]
  )

  return NextResponse.json({ data: rows })
})

export const POST = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (request, ctx) => {
  const parsed = createSubmissionSchema.safeParse(ctx.body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.issues[0]?.message }, { status: 400 })
  }

  const { project_id, notes } = parsed.data

  // Get next submission number
  const { rows: existing } = await db.query<NextNumRow>(
    'SELECT COALESCE(MAX(submission_number), 0) + 1 as next_num FROM submissions WHERE project_id = $1',
    [project_id]
  )
  const nextNum = existing[0].next_num

  // Count parcels and traverses
  const { rows: parcelCounts } = await db.query<ParcelCountRow>(
    `SELECT COUNT(*)::int as total, 
      COUNT(CASE WHEN pt.status IN ('computed', 'approved') THEN 1 END)::int as computed
     FROM parcels p
     JOIN blocks b ON b.id = p.block_id
     LEFT JOIN parcel_traverses pt ON pt.parcel_id = p.id
     WHERE b.project_id = $1`,
    [project_id]
  )

  const { rows } = await db.query<SubmissionTrackRow>(
    `INSERT INTO submissions (project_id, submission_number, submitted_by, 
      status, documents, parcel_count, deed_plan_count, review_notes)
     VALUES ($1, $2, $3, 'submitted', '[]'::jsonb, $4, $5, $6)
     RETURNING *`,
    [project_id, nextNum, ctx.userId, parcelCounts[0].total, parcelCounts[0].computed, notes || null]
  )

  return NextResponse.json({ data: rows[0] }, { status: 201 })
})

