export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { generateFormC22Pdf } from '@/lib/generators/formC22'
import type { FormC22Input } from '@/lib/generators/formC22'
import { logger } from '@/lib/logger'

/**
 * POST /api/submission/form-c22
 *
 * Generates a Form C22 (Computation Sheet) PDF for a given project.
 *
 * Body: { projectId: string }
 * Query: ?format=json  (returns metadata JSON instead of the PDF binary)
 *
 * Fetches project metadata + traverse results from the DB, assembles
 * a FormC22Input, and streams the generated PDF back as a download.
 */
export const POST = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const body = ctx.body as {
    projectId?: string
    format?: string
    county?: string
    division?: string
    district?: string
    locality?: string
    surveyType?: string
    revision?: string
    parcelNumber?: string
    referenceNumber?: string
  }
  const { projectId } = body

  // Build overrides from body fields (only include non-empty values)
  const overrides = {
    county: body.county || undefined,
    division: body.division || undefined,
    district: body.district || undefined,
    locality: body.locality || undefined,
    surveyType: body.surveyType || undefined,
    revision: body.revision || undefined,
    parcelNumber: body.parcelNumber || undefined,
    referenceNumber: body.referenceNumber || undefined,
  }

  if (!projectId) {
    return NextResponse.json({ error: 'Missing projectId' }, { status: 400 })
  }

  // ── 1. Fetch project row ──────────────────────────────────────────────
  const { rows: projectRows } = await db.query<ProjectRow>(
    `SELECT
       p.id, p.name, p.survey_type, p.lr_number, p.location,
       p.registration_district, p.locality, p.ref_no, p.area_ha,
       p.boundary_data,
       sp.isk_number  AS surveyor_isk,
       sp.firm_name   AS surveyor_firm,
       u.full_name    AS surveyor_name
     FROM projects p
     LEFT JOIN surveyor_profiles sp ON sp.user_id = p.user_id
     LEFT JOIN users u             ON u.id = p.user_id
     WHERE p.id = $1 AND p.user_id = $2
     LIMIT 1`,
    [projectId, ctx.userId]
  )

  if (projectRows.length === 0) {
    return NextResponse.json({ error: 'Project not found' }, { status: 404 })
  }

  const proj = projectRows[0]

  // ── 2. Fetch traverse results (most recent) ───────────────────────────
  const { rows: traverseRows } = await db.query<TraverseResultRow>(
    `SELECT results
     FROM traverse_results
     WHERE project_id = $1
     ORDER BY updated_at DESC
     LIMIT 1`,
    [projectId]
  )

  // ── 3. Assemble FormC22Input ──────────────────────────────────────────
  const input = assembleFormC22Input(proj, traverseRows[0]?.results ?? null, overrides)

  // ── 4. Format=json metadata branch ────────────────────────────────────
  if (body.format === 'json') {
    return NextResponse.json({
      success: true,
      metadata: {
        projectName: input.projectName,
        lrNumber: input.lrNumber,
        county: input.county,
        stationCount: input.stations.length,
        areaHa: input.areaHa,
        precisionRatio: input.precisionRatio,
        angularMisclosureSec: input.angularMisclosureSec,
        linearMisclosureM: input.linearMisclosureM,
      },
    })
  }

  // ── 5. Generate PDF ──────────────────────────────────────────────────
  const pdfBuffer = generateFormC22Pdf(input)

  // ── 6. Audit log ──────────────────────────────────────────────────────
  try {
    await db.query<never>(
      `INSERT INTO form_c22_audits
         (project_id, generated_by, station_count, area_ha, precision_ratio, angular_misclosure_sec, linear_misclosure_m, file_size_bytes)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`,
      [
        projectId,
        ctx.userId,
        input.stations.length,
        input.areaHa,
        input.precisionRatio,
        input.angularMisclosureSec,
        input.linearMisclosureM,
        (pdfBuffer as unknown as Uint8Array).length,
      ]
    )
  } catch (auditErr) {
    // Audit failure should not block the PDF response
    logger.error('[form-c22] audit log failed:', { error: auditErr })
  }

  const safeName = (input.lrNumber || input.projectName || 'unknown')
    .replace(/[^a-zA-Z0-9_-]/g, '_')
    .toLowerCase()

  return new NextResponse(pdfBuffer as unknown as BodyInit, {
    headers: {
      'Content-Type': 'application/pdf',
      'Content-Disposition': `attachment; filename="form-c22-${safeName}.pdf"`,
    },
  })
})

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

interface ProjectRow {
  name: string
  survey_type: string | null
  lr_number: string | null
  location: string | null
  registration_district: string | null
  locality: string | null
  ref_no: string | null
  area_ha: number | null
  boundary_data: Record<string, unknown> | null
  surveyor_isk: string | null
  surveyor_firm: string | null
  surveyor_name: string | null
}

interface TraverseResultRow {
  results: Record<string, unknown> | null
}

/**
 * Build a FormC22Input from the project row and optional traverse results.
 *
 * When traverse results are available the closure statistics are populated
 * from the computed data.  Otherwise sensible defaults are used so the PDF
 * still generates (useful for pre-computation previews).
 */
function assembleFormC22Input(
  proj: ProjectRow,
  traverseResults: Record<string, unknown> | null,
  overrides?: {
    county?: string
    division?: string
    district?: string
    locality?: string
    surveyType?: string
    revision?: string
    parcelNumber?: string
    referenceNumber?: string
  }
): FormC22Input {
  // ── Stations from boundary_data (saved by CadastralComputeIntegration) ─
  const stations = extractStations(proj.boundary_data)

  // ── Closure data from traverse results JSONB ──────────────────────────
  const closure = extractClosure(traverseResults)

  return {
    projectName: proj.name || 'Untitled Project',
    lrNumber: proj.lr_number || '',
    parcelNumber: overrides?.parcelNumber || '',
    county: overrides?.county || proj.registration_district || '',
    division: overrides?.division || '',
    district: overrides?.district || '',
    locality: overrides?.locality || proj.locality || '',
    surveyType: overrides?.surveyType || proj.survey_type || '',
    surveyorName: proj.surveyor_name || '',
    iskNumber: proj.surveyor_isk || '',
    firmName: proj.surveyor_firm || '',
    referenceNumber: overrides?.referenceNumber || proj.ref_no || '',
    revision: overrides?.revision || '',
    stations,
    angularMisclosureSec: closure.angularMisclosureSec,
    angularToleranceSec: closure.angularToleranceSec,
    linearMisclosureM: closure.linearMisclosureM,
    perimeterM: closure.perimeterM,
    precisionRatio: closure.precisionRatio,
    areaM2: closure.areaM2,
    areaHa: closure.areaHa,
  }
}

/**
 * Extract stations array from `projects.boundary_data.adjustedStations`.
 *
 * Each entry from CadastralComputeIntegration looks like:
 *   { pointName, originalEasting, originalNorthing, adjustedEasting, adjustedNorthing }
 *
 * For C22 we also need to compute raw departures/latitudes and corrections.
 */
function extractStations(
  boundaryData: Record<string, unknown> | null
): FormC22Input['stations'] {
  if (!boundaryData?.adjustedStations || !Array.isArray(boundaryData.adjustedStations)) {
    return []
  }

  const raw: Array<Record<string, number>> = boundaryData.adjustedStations as Array<Record<string, number>>

  if (raw.length < 3) return []

  // Compute per-leg departures, latitudes, and the Bowditch corrections
  const n = raw.length
  const legs: Array<{
    dE: number
    dN: number
    dist: number
    bearing: number
  }> = []

  for (let i = 0; i < n; i++) {
    const curr = raw[i]
    const next = raw[(i + 1) % n]
    const dE = (next.adjustedEasting ?? 0) - (curr.adjustedEasting ?? 0)
    const dN = (next.adjustedNorthing ?? 0) - (curr.adjustedNorthing ?? 0)
    const dist = Math.sqrt(dE * dE + dN * dN)
    const bearing = ((Math.atan2(dE, dN) * 180) / Math.PI + 360) % 360
    legs.push({ dE, dN, dist, bearing })
  }

  const perimeter = legs.reduce((s, l) => s + l.dist, 0)
  const sumDE = legs.reduce((s, l) => s + l.dE, 0)
  const sumDN = legs.reduce((s, l) => s + l.dN, 0)

  // Distribute the misclosure proportionally (Bowditch)
  return legs.map((leg, i) => {
    const ratio = perimeter > 0 ? leg.dist / perimeter : 0
    const corrE = -sumDE * ratio
    const corrN = -sumDN * ratio

    // Observed distance = raw distance (already stored as leg distance)
    // Observed bearing = bearing from adjusted coords (best we have)
    const stationFrom = raw[i]
    const stationTo = raw[(i + 1) % n]

    return {
      label: String(stationFrom.pointName ?? `ST${i + 1}`),
      observedBearing: leg.bearing,
      observedDistance: leg.dist,
      easting: (stationFrom.adjustedEasting ?? 0) - corrE,
      northing: (stationFrom.adjustedNorthing ?? 0) - corrN,
      adjustedEasting: stationTo.adjustedEasting ?? 0,
      adjustedNorthing: stationTo.adjustedNorthing ?? 0,
      departureRaw: leg.dE,
      latitudeRaw: leg.dN,
      departureCorrection: corrE,
      latitudeCorrection: corrN,
    }
  })
}

/**
 * Extract closure statistics from traverse_results JSONB.
 */
function extractClosure(
  results: Record<string, unknown> | null
): {
  angularMisclosureSec: number
  angularToleranceSec: number
  linearMisclosureM: number
  perimeterM: number
  precisionRatio: number
  areaM2: number
  areaHa: number
} {
  const defaults = {
    angularMisclosureSec: 0,
    angularToleranceSec: 30, // 30″ for a typical cadastral traverse
    linearMisclosureM: 0,
    perimeterM: 0,
    precisionRatio: 10000,
    areaM2: 0,
    areaHa: 0,
  }

  if (!results) return defaults

  // The JSONB structure from traverse_runner may vary — handle common shapes
  const r = results as Record<string, Record<string, unknown>>

  // Try nested shape: { adjustedStations: { linearMisclosure, ... } }
  const adj = r.adjustedStations ?? r.adjustedStations as Record<string, unknown> | undefined
  const misc = r.misclosure ?? r.closure ?? r.summary ?? {} as Record<string, unknown>

  return {
    angularMisclosureSec: toNum(adj?.angularMisclosure ?? misc?.angularMisclosure ?? 0),
    angularToleranceSec: toNum(adj?.angularTolerance ?? misc?.angularTolerance ?? defaults.angularToleranceSec),
    linearMisclosureM: toNum(adj?.linearMisclosure ?? misc?.linearMisclosure ?? misc?.linearMisclosureM ?? 0),
    perimeterM: toNum(adj?.perimeter ?? misc?.perimeter ?? 0),
    precisionRatio: toNum(adj?.precisionRatio ?? misc?.precisionRatio ?? defaults.precisionRatio),
    areaM2: toNum(r.areaM2 ?? r.area_sqm ?? r.computedAreaM2 ?? 0),
    areaHa: toNum(r.areaHa ?? r.area_hectares ?? 0),
  }
}

function toNum(v: unknown): number {
  if (typeof v === 'number') return isFinite(v) ? v : 0
  const n = Number(v)
  return isFinite(n) ? n : 0
}

// ──────────────────────────────────────────────────────────────────────────
// METARDU — Audit Trail API Routes
// ──────────────────────────────────────────────────────────────────────────
// GET  /api/survey/audit?projectId=...     → List audit entries
// GET  /api/survey/audit?surveyId=...      → List audit entries for survey
// GET  /api/survey/audit?id=...            → Get single entry
// GET  /api/survey/audit/stats?projectId=... → Get statistics
// GET  /api/survey/audit/verify?projectId=... → Verify chain integrity
// GET  /api/survey/audit/export?projectId=...&format=json|text → Export report
// POST /api/survey/audit                    → Store new audit entry
// ──────────────────────────────────────────────────────────────────────────

import { NextRequest, NextResponse } from 'next/server';
import { getToken } from 'next-auth/jwt';
import {
  storeAuditEntry,
  getAuditEntriesBySurvey,
  getAuditEntriesByProject,
  getAuditEntryById,
  getAuditStats,
  verifyAuditChain,
} from '@/lib/survey/audit-store';
import {
  AuditTrail,
  type AuditEntry,
  type AuditOperation,
  type CorrectionRecord,
  type AccuracyCheckResult,
} from '@/lib/survey/audit-trail';
import { logger } from '@/lib/logger'

interface AuditEntryBody {
  surveyId: string
  projectId: string
  userId: string
  operation: AuditOperation
  inputs: Record<string, unknown>
  outputs: Record<string, unknown>
  correctionsApplied?: CorrectionRecord[]
  formula: string
  reference: string
  durationMs?: number
  accuracyCheck?: AccuracyCheckResult | null
  [key: string]: unknown
}

// ─── GET Handler ─────────────────────────────────────────────────────────

export async function GET(request: NextRequest) {
  // Auth check
  const token = await getToken({ req: request, secret: process.env.AUTH_SECRET });
  if (!token?.email) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const { searchParams } = new URL(request.url);

  // ── Single entry by ID ──
  const id = searchParams.get('id');
  if (id) {
    const entry = await getAuditEntryById(id);
    if (!entry) {
      return NextResponse.json({ error: 'Audit entry not found' }, { status: 404 });
    }
    return NextResponse.json(entry);
  }

  // ── Chain verification ──
  if (searchParams.has('verify')) {
    const projectId = searchParams.get('projectId') || searchParams.get('verify');
    if (!projectId) {
      return NextResponse.json({ error: 'projectId required for verification' }, { status: 400 });
    }
    const result = await verifyAuditChain(projectId);
    return NextResponse.json(result);
  }

  // ── Statistics ──
  if (searchParams.has('stats')) {
    const projectId = searchParams.get('projectId') || searchParams.get('stats');
    if (!projectId) {
      return NextResponse.json({ error: 'projectId required for stats' }, { status: 400 });
    }
    const stats = await getAuditStats(projectId);
    return NextResponse.json(stats);
  }

  // ── Export report ──
  if (searchParams.has('export')) {
    const projectId = searchParams.get('projectId');
    if (!projectId) {
      return NextResponse.json({ error: 'projectId required for export' }, { status: 400 });
    }
    const format = searchParams.get('format') || 'json';

    if (format === 'text') {
      const trail = new AuditTrail();
      const entries = await getAuditEntriesByProject(projectId);
      // Reconstruct trail for export (entries already in order)
      const report = [
        '═══════════════════════════════════════════════════════════════',
        '  METARDU — Survey Computation Audit Report',
        '═══════════════════════════════════════════════════════════════',
        '',
        `  Project ID:     ${projectId}`,
        `  Generated:      ${new Date().toISOString()}`,
        `  Entries:        ${entries.length}`,
        '',
        '───────────────────────────────────────────────────────────────',
        '',
      ];

      for (const e of entries) {
        report.push(`  [${e.operation.toUpperCase().replace(/_/g, ' ')}]`);
        report.push(`    Timestamp:  ${e.timestamp}`);
        report.push(`    Survey:     ${e.surveyId}`);
        report.push(`    User:       ${e.userId}`);
        report.push(`    Formula:    ${e.formula}`);
        report.push(`    Reference:  ${e.reference}`);
        report.push(`    Checksum:   ${e.checksum.substring(0, 24)}…`);
        if (e.accuracyCheck) {
          report.push(`    Accuracy:   ${e.accuracyCheck.passed ? 'PASS' : 'FAIL'} — ${e.accuracyCheck.details}`);
        }
        report.push('');
      }

      report.push('═══════════════════════════════════════════════════════════════');

      return new NextResponse(report.join('\n'), {
        headers: {
          'Content-Type': 'text/plain; charset=utf-8',
          'Content-Disposition': `attachment; filename="audit-report-${projectId}.txt"`,
        },
      });
    }

    // JSON format
    const entries = await getAuditEntriesByProject(projectId);
    const chainResult = await verifyAuditChain(projectId);
    return NextResponse.json({
      projectId,
      generatedAt: new Date().toISOString(),
      chainValid: chainResult.valid,
      chainDetails: chainResult.details,
      entries,
    });
  }

  // ── List entries ──
  const surveyId = searchParams.get('surveyId');
  const projectId = searchParams.get('projectId');

  if (surveyId) {
    const entries = await getAuditEntriesBySurvey(surveyId);
    return NextResponse.json({ entries, count: entries.length });
  }

  if (projectId) {
    const entries = await getAuditEntriesByProject(projectId);
    return NextResponse.json({ entries, count: entries.length });
  }

  return NextResponse.json(
    { error: 'Provide id, surveyId, projectId, or action parameter (verify/stats/export)' },
    { status: 400 }
  );
}

// ─── POST Handler ────────────────────────────────────────────────────────

export async function POST(request: NextRequest) {
  // Auth check
  const token = await getToken({ req: request, secret: process.env.AUTH_SECRET });
  if (!token?.email) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const body = (await request.json()) as AuditEntryBody;

    // Validate required fields
    const required = ['surveyId', 'projectId', 'userId', 'operation', 'inputs', 'outputs', 'formula', 'reference'];
    for (const field of required) {
      if (!body[field]) {
        return NextResponse.json({ error: `Missing required field: ${field}` }, { status: 400 });
      }
    }

    // Create audit entry with checksums
    const trail = new AuditTrail();
    const entry = trail.record({
      surveyId: body.surveyId,
      projectId: body.projectId,
      userId: body.userId,
      operation: body.operation,
      inputs: body.inputs,
      outputs: body.outputs,
      correctionsApplied: body.correctionsApplied || [],
      formula: body.formula,
      reference: body.reference,
      durationMs: body.durationMs || 0,
      accuracyCheck: body.accuracyCheck || null,
    });

    // Persist to database
    await storeAuditEntry(entry);

    return NextResponse.json(entry, { status: 201 });
  } catch (err) {
    logger.error('[Audit API] POST error:', { error: err });
    return NextResponse.json(
      { error: 'Failed to store audit entry', details: String(err) },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { requireSurveyPointOwnership } from '@/lib/auth/ownership'
import { z } from 'zod'

// AUTO-GENERATED by api-row-sweep --apply — column types from migrations/*.sql + name heuristics.
// pg returns bigint/numeric as string, timestamptz as Date; nullable columns carry `| null`; REVIEW.
interface SurveyPointRow {
  id: string
  updated_at: Date | null
}

export const dynamic = 'force-dynamic'

/**
 * PATCH /api/survey-points/[id]
 *
 * Update a survey point's mutable fields with optimistic locking.
 *
 * SECURITY: IDOR protection — verifies the survey point's project
 * belongs to the requesting user before allowing update.
 *
 * Frontend MUST send `updated_at` in the request body — the value should be
 * the `updated_at` timestamp from the most recent GET/fetch of this point.
 * If the DB row's `updated_at` differs (another surveyor edited it), returns 409.
 */
const patchSurveyPointSchema = z.object({
  point_name: z.string().optional(),
  easting: z.number().nullable().optional(),
  northing: z.number().nullable().optional(),
  elevation: z.number().nullable().optional(),
  description: z.string().nullable().optional(),
  code: z.string().nullable().optional(),
  // T1.5d FIX (2026-07-10): Allow toggling is_control + CRS fields
  is_control: z.boolean().optional(),
  datum: z.string().nullable().optional(),
  utm_zone: z.number().int().min(1).max(60).nullable().optional(),
  hemisphere: z.enum(['N', 'S']).nullable().optional(),
  epoch_year: z.number().int().min(1900).max(2100).nullable().optional(),
  source: z.string().nullable().optional(),
  observation_date: z.string().nullable().optional(),
  // T1.5i FIX (2026-07-10): Make updated_at optional. When provided, optimistic
  // locking is enforced. When omitted, the update is unconditional.
  updated_at: z.string().optional(),
})

export const PATCH = apiHandler(
  { auth: true, optimisticLock: true, schema: patchSurveyPointSchema,
    auditChain: { entityType: 'control_point', action: 'update', entityIdParam: 'id' } },
  async (_req, ctx) => {
    const { id } = ctx.params
    const body = ctx.body as z.infer<typeof patchSurveyPointSchema>

    // IDOR protection — verify the survey point's project belongs to the user
    const ownership = await requireSurveyPointOwnership(id, ctx.userId)
    if (!ownership.ok) return ownership.error!

    // Fetch current row for optimistic lock check
    const { rows } = await db.query<SurveyPointRow>(
      'SELECT id, updated_at FROM survey_points WHERE id = $1',
      [id]
    )

    if (rows.length === 0) {
      return NextResponse.json(
        { error: 'Survey point not found', code: 'NOT_FOUND' },
        { status: 404 }
      )
    }

    // T1.8 FIX (2026-07-09): Optimistic lock guard moved to the SQL WHERE clause.

    // Build dynamic UPDATE — only SET fields that were provided
    const fields: string[] = []
    const values: unknown[] = []
    let paramIdx = 1

    const allowedFields: Record<string, string> = {
      point_name: 'point_name',
      easting: 'easting',
      northing: 'northing',
      elevation: 'elevation',
      description: 'description',
      code: 'code',
      // T1.5d FIX (2026-07-10): Allow toggling is_control via PATCH.
      // Previously this was excluded, so the only way to promote a detail
      // point to a control point was to delete + re-insert.
      is_control: 'is_control',
      // CRS / accuracy fields (migration 027) — allow updating these
      datum: 'datum',
      utm_zone: 'utm_zone',
      hemisphere: 'hemisphere',
      epoch_year: 'epoch_year',
      source: 'source',
      observation_date: 'observation_date',
    }

    for (const [bodyKey, colName] of Object.entries(allowedFields)) {
      if (bodyKey in body && body[bodyKey as keyof typeof body] !== undefined) {
        fields.push(`${colName} = $${paramIdx++}`)
        values.push(body[bodyKey as keyof typeof body])
      }
    }

    if (fields.length === 0) {
      return NextResponse.json(
        { error: 'No fields to update', code: 'NO_FIELDS' },
        { status: 400 }
      )
    }

    // Always bump updated_at
    fields.push(`updated_at = NOW()`)
    values.push(id)

    // T1.5i FIX (2026-07-10): Make optimistic locking conditional.
    // If updated_at is provided, use the guard (WHERE id = $N AND updated_at = $N+1).
    // If updated_at is NOT provided (e.g. from AddPointModal without the prop),
    // skip the guard (WHERE id = $N only) — unconditional update.
    let sql: string
    if (body.updated_at) {
      values.push(body.updated_at)
      sql = `UPDATE survey_points SET ${fields.join(', ')} WHERE id = $${paramIdx} AND updated_at = $${paramIdx + 1} RETURNING *`
    } else {
      sql = `UPDATE survey_points SET ${fields.join(', ')} WHERE id = $${paramIdx} RETURNING *`
    }

    const result = await db.query<SurveyPointRow>(sql, values)

    // Only return 409 if the optimistic lock guard was used AND 0 rows returned.
    // Without the guard, 0 rows means the point doesn't exist (404).
    if (result.rows.length === 0) {
      if (body.updated_at) {
        return NextResponse.json(
          { error: 'This survey point was modified by another user. Please refresh and try again.', code: 'CONFLICT' },
          { status: 409 }
        )
      } else {
        return NextResponse.json(
          { error: 'Survey point not found', code: 'NOT_FOUND' },
          { status: 404 }
        )
      }
    }

    return NextResponse.json({ data: result.rows[0] })
  }
)

export const dynamic = 'force-dynamic'

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { createSurveyReport, saveSurveyReport } from '@/lib/api-client/surveyReports'
import type { SurveyReportInput, SectionContent } from '@/types/surveyReport'

export const POST = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const {
    reportId,
    projectId,
    input,
    sections,
    completeness
  } = ctx.body as {
    reportId?: string
    projectId?: string
    input?: Partial<SurveyReportInput>
    sections?: SectionContent[]
    completeness?: number
  }

  if (!projectId) {
    return NextResponse.json({ error: 'Project ID required' }, { status: 400 })
  }

  if (!sections || !Array.isArray(sections)) {
    return NextResponse.json({ error: 'Sections required' }, { status: 400 })
  }

  const comp = completeness ?? 0

  if (reportId) {
    await saveSurveyReport(reportId, input!, sections, comp)
    return NextResponse.json({ id: reportId, saved: true })
  } else {
    const id = await createSurveyReport(input!, sections, comp, projectId)
    return NextResponse.json({ id, created: true })
  }
})

export const dynamic = 'force-dynamic'

/**
 * Field Data Sync API Route
 *
 * Handles batch upload of observations collected offline in the field.
 * Surveyors work all day offline (IndexedDB), then sync at end of day.
 *
 * SECURITY (audit C2, fixed 2026-07-02):
 *   Previously this route accepted `surveyorId` and `surveyorName` from
 *   the request body and wrote them to the audit log without verifying
 *   the session. Any authenticated user could impersonate any surveyor.
 *   Now the route uses `getServerSession` to derive the user identity
 *   from the JWT, ignoring any client-supplied surveyorId/surveyorName.
 *
 * RESOLVED (audit H1, fixed 2026-07-02): The previous TODO noted that
 *   this route used Prisma models (Survey, Observation) that didn't
 *   match the actual SQL schema. That has been fixed — the route now
 *   queries the real `projects` table via raw SQL (see line ~57). The
 *   Prisma client was deleted on 2026-07-05 because it had 0 importers.
 *
 * REMAINING WORK: The `observations` payload from the client is still
 *   shape-compatible with the old Prisma Observation model, which doesn't
 *   match the real `traverse_observations` / `level_observations` tables.
 *   The batchCreateObservations() helper in src/lib/db/queries/observations.ts
 *   is responsible for routing each observation to the correct table.
 */

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { batchCreateObservations, getObservations } from '@/lib/db/queries/observations'
import { createAuditLog } from '@/lib/db/queries/audit'
import { db } from '@/lib/db'
import { FieldSyncSchema } from '@/lib/validation/apiSchemas'
import { appendAuditEntry } from '@/lib/audit/auditLog'
import { logger } from '@/lib/logger'

// AUTO-GENERATED by api-row-sweep --apply — column types from migrations/*.sql + name heuristics.
// pg returns bigint/numeric as string, timestamptz as Date; nullable columns carry `| null`; REVIEW.
interface ProjectRow {
  id: string
  user_id: string | null
  organization_id: string | null
}

export async function POST(request: NextRequest) {
  // ── Auth: derive identity from session, never from body ───────────────
  const session = await getServerSession(authOptions)
  if (!session?.user?.id) {
    return NextResponse.json(
      { error: 'Authentication required' },
      { status: 401 }
    )
  }
  const userId = session.user.id
  const userName = (session.user as { name?: string }).name ?? session.user.email ?? 'Unknown'

  try {
    const rawBody: unknown = await request.json().catch(() => null)
    const parsed = FieldSyncSchema.safeParse(rawBody)
    if (!parsed.success) {
      return NextResponse.json(
        { error: 'Validation failed', details: parsed.error.issues },
        { status: 422 }
      )
    }

    // surveyorId/surveyorName from body are IGNORED — identity comes from session.
    const { surveyId, observations } = parsed.data

    // AUDIT FIX (H1, 2026-07-02): Replaced prisma.survey.findUnique with
    // raw SQL against the real `projects` table. The Prisma `Survey`
    // model never existed in the SQL schema. `surveyId` is treated as
    // a project ID (the caller's convention).
    const surveyResult = await db.query<ProjectRow>(
      `SELECT id, user_id, organization_id FROM projects WHERE id = $1`,
      [surveyId]
    )

    if (surveyResult.rows.length === 0) {
      return NextResponse.json(
        { error: 'Project not found' },
        { status: 404 }
      )
    }

    const project = surveyResult.rows[0]
    // Ownership check: the session user must own the project OR be a
    // member of the project's organization.
    if (project.user_id && project.user_id !== userId) {
      // Check org membership if the project belongs to an org
      if (project.organization_id) {
        const orgMemberResult = await db.query<never>(
          `SELECT 1 FROM organization_members
           WHERE user_id = $1 AND organization_id = $2 AND is_active = TRUE`,
          [userId, project.organization_id]
        )
        if (orgMemberResult.rows.length === 0) {
          return NextResponse.json(
            { error: 'Forbidden: project belongs to another user' },
            { status: 403 }
          )
        }
      } else {
        return NextResponse.json(
          { error: 'Forbidden: project belongs to another user' },
          { status: 403 }
        )
      }
    }

    // Batch create all observations
    const result = await batchCreateObservations({
      surveyId,
      observations: observations.map(obs => ({
        surveyId,
        fromStationId: obs.fromStationId,
        toStationId: obs.toStationId,
        rawHorizontalAngle: obs.rawHorizontalAngle,
        rawVerticalAngle: obs.rawVerticalAngle,
        rawSlopeDistance: obs.rawSlopeDistance,
        edmConstant: obs.edmConstant,
        ppmSetting: obs.ppmSetting,
        temperature: obs.temperature,
        pressure: obs.pressure,
        humidity: obs.humidity,
        instrumentHeight: obs.instrumentHeight,
        targetHeight: obs.targetHeight,
        observationDate: obs.observationDate ? new Date(obs.observationDate) : undefined,
      })),
    })

    // Audit log — identity from session, never from body
    await createAuditLog({
      entityType: 'Survey',
      entityId: surveyId,
      action: 'SYNC_OBSERVATIONS',
      userId,
      userName,
      changes: JSON.stringify({ count: observations.length }),
    })

    // Tamper-evident audit chain (audit C3 — wire into more routes)
    try {
      await appendAuditEntry({
        projectId: surveyId,
        userId,
        entityType: 'custom',
        entityId: surveyId,
        action: 'import',
        payload: {
          metadata: {
            operation: 'SYNC_OBSERVATIONS',
            count: observations.length,
            syncedAt: new Date().toISOString(),
          },
        },
      })
    } catch {
      // Audit chain failure should NOT block the sync — log and continue.
      logger.warn('[sync] appendAuditEntry failed — chain integrity check recommended')
    }

    return NextResponse.json({
      success: true,
      count: result.count,
      message: `Synced ${result.count} observations`,
    })
  } catch (error) {
    logger.error('Sync error:', { error: error })
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Sync failed' },
      { status: 500 }
    )
  }
}

/**
 * GET: Retrieve synced observations for a survey.
 * Used by the client to verify what was synced.
 */
export async function GET(request: NextRequest) {
  // ── Auth: same fix as POST ────────────────────────────────────────────
  const session = await getServerSession(authOptions)
  if (!session?.user?.id) {
    return NextResponse.json(
      { error: 'Authentication required' },
