/**
 * POST /api/workers/process
 *
 * Processes pending jobs from the background_jobs queue.
 * Designed to be called by an external cron (e.g. Vercel Cron, systemd timer)
 * or a dedicated worker process.
 *
 * Processes up to 5 jobs per invocation with proper error handling,
 * timeout management, and status updates.
 *
 * Security: requires auth — only the system account can process jobs.
 */

export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { apiHandler, apiSuccess } from '@/lib/apiHandler'
import { db } from '@/lib/db'

// ─── Row interface ───────────────────────────────────────────────────────
interface JobRow {
  id: string
  job_type: string
  status: string
  payload: string | Record<string, unknown> | null
  retry_count: number | null
  priority: number | null
  created_at: Date | string
  scheduled_at: Date | string | null
  started_at: Date | string | null
  completed_at: Date | string | null
  duration_ms: number | null
  error_message: string | null
  result: unknown
}

const JOB_TIMEOUT_MS = 55_000 // stay within Vercel 60s limit

export const POST = apiHandler(
  { auth: true, rateLimit: { max: 10, windowMs: 60_000 } },
  async (req, ctx) => {
    const body = ctx.body as { limit?: number; jobId?: string }

    const limit = Math.min(body.limit ?? 5, 20)

    // Fetch pending jobs ordered by priority then creation time
    const fetchQuery = body.jobId
      ? `SELECT * FROM background_jobs WHERE id = $1 AND status = 'pending' LIMIT 1`
      : `SELECT * FROM background_jobs WHERE status = 'pending'
         ORDER BY priority DESC, created_at ASC LIMIT $1`

    const params = body.jobId ? [body.jobId] : [limit]
    const { rows: jobs } = await db.query<JobRow>(fetchQuery, params)

    const results: Array<{ jobId: string; status: string; error?: string; durationMs: number; retries?: number; nextRetryIn?: string }> = []

    for (const job of jobs) {
      const start = Date.now()

      try {
        await db.query<never>(
          `UPDATE background_jobs SET status = 'running', started_at = NOW() WHERE id = $1 AND status = 'pending'`,
          [job.id]
        )

        const payload = typeof job.payload === 'string' ? JSON.parse(job.payload) as Record<string, unknown> : (job.payload || {})
        const result = await processJob(job.job_type, payload)

        const durationMs = Date.now() - start

        await db.query<never>(
          `UPDATE background_jobs
             SET status = 'completed',
                 result = $2,
                 completed_at = NOW(),
                 duration_ms = $3
             WHERE id = $1`,
          [job.id, JSON.stringify(result), durationMs]
        )

        results.push({ jobId: job.id, status: 'completed', durationMs })

      } catch (err: unknown) {
        const durationMs = Date.now() - start
        const message = err instanceof Error ? err.message : 'Unknown error'

        // ByteByteGo audit fix: DLQ pattern — after 3 retries, move to dead-letter
        // Per ByteByteGo "6 cloud messaging patterns": failed messages go to DLQ
        // for human inspection instead of retrying forever.
        const MAX_RETRIES = 3
        const newRetryCount = (job.retry_count || 0) + 1
        const isDeadLetter = newRetryCount >= MAX_RETRIES

        if (isDeadLetter) {
          // Move to dead-letter queue (keep in same table but mark as 'dead_letter')
          await db.query<never>(
            `UPDATE background_jobs
               SET status = 'dead_letter',
                   error_message = $2,
                   completed_at = NOW(),
                   duration_ms = $3,
                   retry_count = $4
             WHERE id = $1`,
            [job.id, `DLQ: ${message.slice(0, 450)}`, durationMs, newRetryCount]
          )
          results.push({ jobId: job.id, status: 'dead_letter', error: message, durationMs, retries: newRetryCount })
        } else {
          // Re-queue for retry (set back to pending with exponential backoff delay)
          const delayMs = Math.pow(2, newRetryCount) * 1000  // 2s, 4s, 8s
          await db.query<never>(
            `UPDATE background_jobs
               SET status = 'pending',
                   error_message = $2,
                   duration_ms = $3,
                   retry_count = $4,
                   scheduled_at = NOW() + ($5 || '0')::interval
             WHERE id = $1`,
            [job.id, message.slice(0, 500), durationMs, newRetryCount, `${delayMs} milliseconds`]
          )
          results.push({ jobId: job.id, status: 'requeued', error: message, durationMs, retries: newRetryCount, nextRetryIn: `${delayMs}ms` })
        }
      }
    }

    return apiSuccess({
      processed: results.length,
      jobs: results,
      timestamp: new Date().toISOString(),
    })
  },
)

/**
 * Process a single job based on its type.
 * Each handler receives the parsed payload and returns a result object.
 * Errors are caught by the outer try/catch and written to the job record.
 */
async function processJob(
  jobType: string,
  payload: Record<string, unknown>
): Promise<Record<string, unknown>> {
  const timeout = JOB_TIMEOUT_MS

  switch (jobType) {
    case 'pdf_generation': {
      const { generateDocument } = await import('@/lib/submission/assembleDocument')
      const docResult = await Promise.race([
        generateDocument({
          projectId: String(payload.project_id),
          documentId: String(payload.document_id),
          surveyType: String(payload.survey_type ?? 'cadastral'),
          userId: payload.userId ? String(payload.userId) : undefined,
        }),
        new Promise<never>((_, reject) =>
          setTimeout(() => reject(new Error(`Job timed out after ${timeout}ms`)), timeout)
        ),
      ])
      return { fileUrl: (docResult as { fileUrl: string }).fileUrl }
    }

    case 'dxf_generation': {
      const projectId = String(payload.project_id)
      const dxfType = String(payload.dxfType ?? 'form_no_4')
      const { generateFormNo4DXF } = await import('@/lib/submission/generators/formNo4')
      const { assembleSubmissionPackage } = await import('@/lib/submission/assembleSubmission')

      const submission = await Promise.race([
        assembleSubmissionPackage(projectId),
        new Promise<never>((_, reject) =>
          setTimeout(() => reject(new Error(`DXF: failed to assemble submission package`)), timeout)
        ),
      ])

      const dxfContent = await Promise.race([
        generateFormNo4DXF((submission as { zipBuffer: Buffer; ref: string; qa: unknown }).zipBuffer as unknown as Parameters<typeof generateFormNo4DXF>[0]),
        new Promise<never>((_, reject) =>
          setTimeout(() => reject(new Error(`DXF job timed out after ${timeout}ms`)), timeout)
        ),
      ])
      void dxfContent // DXF string generated; caller retrieves via document record
      return { type: dxfType, dxfLength: typeof dxfContent === 'string' ? dxfContent.length : 0, ref: (submission as { ref: string }).ref }
    }

    case 'assemble_submission': {
      const { assembleSubmissionPackage } = await import('@/lib/submission/assembleSubmission')
      const asmResult = await Promise.race([
        assembleSubmissionPackage(String(payload.project_id)),
        new Promise<never>((_, reject) =>
          setTimeout(() => reject(new Error(`Assembly job timed out after ${timeout}ms`)), timeout)
        ),
      ])
      const asm = asmResult as { ref: string; qa: { passed: boolean } }
      return { ref: asm.ref, qaPassed: asm.qa.passed }
    }

    case 'traverse_compute': {
      const { computeTraverse } = await import('@/lib/computations/traverseEngine')
      const traverseResult = await Promise.race([
        computeTraverse(payload as Parameters<typeof computeTraverse>[0]),
        new Promise<never>((_, reject) =>
          setTimeout(() => reject(new Error(`Traverse job timed out after ${timeout}ms`)), timeout)
        ),
      ])
      const tr = traverseResult as { coordinates: Array<unknown>; precisionRatio: number }
      return { pointCount: tr.coordinates.length, precisionRatio: tr.precisionRatio }
    }

    case 'earthworks_boq': {
      const { generateEarthworksBoQ } = await import('@/lib/print/earthworksBoQ')
      const inp = payload.input as Parameters<typeof generateEarthworksBoQ>[0]
      const boqResult = await Promise.race([
        generateEarthworksBoQ(inp),
        new Promise<never>((_, reject) =>
          setTimeout(() => reject(new Error(`Earthworks BoQ timed out after ${timeout}ms`)), timeout)
        ),
      ])
      return { htmlLength: String(boqResult).length }
    }

    default:
      throw new Error(`Unknown job type: ${jobType}`)
  }
}

/**
 * GET /api/workspaces?surveyType=cadastral
 *
 * Returns the workspace configuration for the given survey type.
 * If surveyType is omitted, returns all available workspaces.
 *
 * Used by the frontend to morph the UI based on the active workspace
 * (tool categories, map layers, hotkeys, document types).
 */

export const dynamic = 'force-dynamic'

import { apiHandler, apiSuccess } from '@/lib/apiHandler'
import {
  getWorkspaceConfig,
  listWorkspaces,
  autoDetectWorkspace,
  type WorkspaceId,
} from '@/lib/workspaces/config'

export const GET = apiHandler(
  { auth: true, rateLimit: { max: 60, windowMs: 60000 } },
  async (req, _ctx) => {
    const url = new URL(req.url)
    const surveyType = url.searchParams.get('surveyType')

    if (surveyType) {
      // Auto-detect workspace from survey type and return its config
      const workspaceId = autoDetectWorkspace(surveyType)
      const config = getWorkspaceConfig(workspaceId)
      return apiSuccess({ workspace: config })
    }

    // No surveyType — return all workspaces for the switcher UI
    const workspaces = listWorkspaces()
    return apiSuccess({ workspaces })
  }
)

'use client';
import React from 'react'

import { useState, useEffect, useCallback, useRef, useMemo } from 'react'
import { createClient } from '@/lib/api-client/client'
import { utmToGeographic } from '@/lib/geodesy/coordinates'
import Link from 'next/link'
import { BeaconRegistryPanel } from '@/components/beacons/BeaconRegistryPanel'
import { ControlPointRegistry } from '@/components/survey/ControlPointRegistry'
// ponytail: Phase 6 — use typed imports from ol (which ships its own .d.ts files)
// instead of dynamic imports + `as any` casts. Same bundle (Next.js code-splits
// these automatically), but now TypeScript can catch API misuse.
import Map from 'ol/Map'
import View from 'ol/View'
import TileLayer from 'ol/layer/Tile'
import VectorLayer from 'ol/layer/Vector'
import VectorSource from 'ol/source/Vector'
import OSM from 'ol/source/OSM'
import Style from 'ol/style/Style'
import CircleStyle from 'ol/style/Circle'
import Fill from 'ol/style/Fill'
import Stroke from 'ol/style/Stroke'
import Text from 'ol/style/Text'
import Feature from 'ol/Feature'
import Point from 'ol/geom/Point'
import { fromLonLat } from 'ol/proj'
import Overlay from 'ol/Overlay'
import type { Map as MapType, Overlay as OverlayType } from 'ol'
import { logger } from '@/lib/logger'

interface Beacon {
  id: string
  name: string
  easting: number
  northing: number
  elevation?: number
  utm_zone: number
  hemisphere: string
  authority?: string
  beacon_type: string
  description?: string
  datum?: string  // T1.5d: added for beacon import
}

interface Project {
  id: string
  name: string
  location?: string
  survey_type?: string
  created_at: string
}

function getMarkerIcon(type: string) {
  const icons: Record<string, string> = {
    trig: '▲',
    control: '●',
    boundary: '■',
    benchmark: '◆',
    gnss: '',
    other: '●'
  }
  return icons[type] || '●'
}

function getMarkerColor(type: string) {
  const colors: Record<string, string> = {
    trig: '#ef4444',
    control: '#f97316',
    boundary: '#eab308',
    benchmark: '#22c55e',
    gnss: '#3b82f6',
    other: '#6b7280'
  }
  return colors[type] || '#6b7280'
}

export default function BeaconsPage() {
  const [importMsg, setImportMsg] = React.useState<{text:string;ok:boolean}|null>(null)
  // AUDIT FIX (2026-07-03): Removed 'activity' view — it placed projects
  // at Math.random() positions (pins jumped on every refresh). Only
  // the 'beacons' view is real.
  const [beacons, setBeacons] = useState<Beacon[]>([])
  const [projects, setProjects] = useState<Project[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<string>('all')
  const [search, setSearch] = useState('')
  const [importProject, setImportProject] = useState('')
  const [importBeacon, setImportBeacon] = useState<Beacon | null>(null)
  const [importLoading, setImportLoading] = useState(false)

  const mapRef = useRef<HTMLDivElement>(null)
  const popupRef = useRef<HTMLDivElement>(null)
  const mapInstance = useRef<MapType | null>(null)
  const overlayRef = useRef<OverlayType | null>(null)

  // AUDIT FIX (H-007, 2026-07-27): useMemo to prevent infinite loop on /beacons.
  // Same pattern as H-003 in /fieldbook.
  const dbClient = useMemo(() => createClient(), [])

  const fetchData = useCallback(async () => {
    setLoading(true)
    
    const [beaconsRes, projectsRes] = await Promise.all([
      dbClient.from('public_beacons').select('*').eq('status', 'verified'),
      dbClient.from('projects').select('id, name, location, survey_type, created_at')
    ])

    if (beaconsRes.data) setBeacons(beaconsRes.data as unknown as Beacon[])
    if (projectsRes.data) setProjects(projectsRes.data as unknown as Project[])
    setLoading(false)
  }, [dbClient])

  useEffect(() => {
    fetchData()
  }, [fetchData])

  // Initialize map once (typed ol imports — Next.js still code-splits)
  useEffect(() => {
    if (!mapRef.current) return

    let cancelled = false

    async function initMap() {
      try {
        // ponytail: imports are now at module top-level (typed). The async
        // wrapper is kept for the cancelled-flag pattern.
        await Promise.resolve() // keep async signature for callers
        if (cancelled || !mapRef.current) return

        const map = new Map({
          target: mapRef.current,
          layers: [new TileLayer({ source: new OSM() })],
          view: new View({
            center: fromLonLat([36.8219, -1.2921]),
            zoom: 6,
          }),
        })

        if (popupRef.current) {
          const overlay = new Overlay({
            element: popupRef.current,
            autoPan: { animation: { duration: 250 } },
          })
          map.addOverlay(overlay)
          overlayRef.current = overlay
        }

        mapInstance.current = map

        // Click handler for popup
        // ponytail: use a structural type for evt; cast handler when
        // registering with map.on() so TS doesn't complain about the
        // ol MapBrowserEvent<UIEvent> signature mismatch.
        const handleClick = (evt: { pixel: [number, number]; coordinate: [number, number] }) => {
          const overlay = overlayRef.current
          if (!overlay || !popupRef.current) return

          const feature = map.forEachFeatureAtPixel(evt.pixel, (f) => f as Feature)
          const popupData = feature?.get('popupData') as
            | { color: string; icon: string; name: string; authority?: string; beacon_type: string; easting: number; northing: number; elevation?: number; utm_zone: number; hemisphere: string }
            | undefined
          if (feature && popupData && popupRef.current) {
            // VULN-002 FIX: render with textContent, never innerHTML.
            const el = popupRef.current
            el.replaceChildren()

            const wrap = document.createElement('div')
            wrap.className = 'text-sm min-w-[200px]'
            wrap.style.color = 'var(--text-primary)'

            const title = document.createElement('div')
            title.style.cssText = 'font-weight:bold;font-size:1.1rem;color:' + popupData.color
            title.textContent = `${popupData.icon} ${popupData.name}`
            wrap.append(title)

            if (popupData.authority) {
              const authority = document.createElement('div')
              authority.style.cssText = 'color:var(--text-muted);margin-top:4px'
              authority.textContent = `Authority: ${popupData.authority}`
              wrap.append(authority)
            }

            const typeRow = document.createElement('div')
            typeRow.style.cssText = 'color:var(--text-muted);text-transform:capitalize'
            typeRow.textContent = `Type: ${popupData.beacon_type}`
            wrap.append(typeRow)

            const coords = document.createElement('div')
            // white-space:pre-line preserves the \n line break (textContent
            // would otherwise collapse it to a space, unlike the old <br/>).
            coords.style.cssText = 'font-family:monospace;margin-top:8px;white-space:pre-line'
            coords.textContent = `E: ${popupData.easting.toFixed(4)}\nN: ${popupData.northing.toFixed(4)}`
            wrap.append(coords)

            if (popupData.elevation) {
              const elev = document.createElement('div')
              elev.style.cssText = 'color:var(--text-muted)'
              elev.textContent = `Elev: ${popupData.elevation.toFixed(3)} m`
              wrap.append(elev)
            }

            const utm = document.createElement('div')
            utm.style.cssText = 'color:var(--text-muted);font-size:0.75rem;margin-top:4px'
            utm.textContent = `UTM Zone ${popupData.utm_zone}${popupData.hemisphere}`
            wrap.append(utm)

            el.append(wrap)
            overlay.setPosition(evt.coordinate)
          } else {
            overlay.setPosition(undefined)
          }
        }
        map.on('click', handleClick as (e: unknown) => void)
      } catch (err) {
        logger.error('Beacons map init failed:', { error: err })
      }
    }

    initMap()

    return () => {
      cancelled = true
      if (mapInstance.current) mapInstance.current.setTarget(undefined)
      overlayRef.current = null
    }
  }, [])

  // Update map features when data changes
  useEffect(() => {
    const map = mapInstance.current
    if (!map || loading) return

    let cancelled = false

    async function updateFeatures() {
      try {
        // ponytail: re-assert map is non-null inside async closure (TS can't
        // track the outer null check across the async boundary)
        if (!map || cancelled) return

        const vectorSource = new VectorSource()

      const filteredBeacons = beacons.filter((b) => {
        if (filter !== 'all' && b.beacon_type !== filter) return false
        if (search && !b.name.toLowerCase().includes(search.toLowerCase()) &&
            !b.authority?.toLowerCase().includes(search.toLowerCase())) return false
        return true
      })

      filteredBeacons.forEach((beacon) => {
        const coords = utmToGeographic(beacon.easting, beacon.northing, beacon.utm_zone, beacon.hemisphere as 'N' | 'S')
        const color = getMarkerColor(beacon.beacon_type)
        const icon = getMarkerIcon(beacon.beacon_type)

        const feature = new Feature({
          geometry: new Point(fromLonLat([coords.lon, coords.lat])),
        })
        feature.setStyle(new Style({
          image: new CircleStyle({
            radius: 8,
            fill: new Fill({ color }),
            stroke: new Stroke({ color: '#fff', width: 2 }),
          }),
          text: new Text({ text: icon, font: '12px sans-serif', fill: new Fill({ color: '#fff' }) }),
        }))
        // VULN-002 FIX (security review 2026-08-03): store structured data
        // instead of an HTML string — beacon names/authorities are
        // user-entered and would otherwise execute as stored XSS. The popup
        // is rendered with textContent in the click handler below.
        feature.set('popupData', {
          color,
          icon,
          name: beacon.name,
          authority: beacon.authority,
          beacon_type: beacon.beacon_type,
          easting: beacon.easting,
          northing: beacon.northing,
          elevation: beacon.elevation,
          utm_zone: beacon.utm_zone,
          hemisphere: beacon.hemisphere,
        })
        feature.set('beaconId', beacon.id)
        vectorSource.addFeature(feature)
      })

      // Pan to Kenya/East Africa if beacons exist
      if (filteredBeacons.length > 0) {
        const extent = vectorSource.getExtent()
        if (extent && (extent[2] - extent[0] > 0 || extent[3] - extent[1] > 0)) {
          map.getView().fit(extent, { padding: [50, 50, 50, 50], maxZoom: 10 })
        }
      } else {
        map.getView().setCenter(fromLonLat([36.8219, -1.2921]))
        map.getView().setZoom(6)
      }

        // Remove old vector layers, add new one
        const existing = map.getLayers().getArray().find((l) => l instanceof VectorLayer)
        if (existing) map.removeLayer(existing)
        map.addLayer(new VectorLayer({ source: vectorSource }))
      } catch (err) {
        logger.error('Beacons map feature update failed:', { error: err })
      }
    }

    updateFeatures()

    return () => {
      cancelled = true
    }
  }, [beacons, projects, filter, search, loading])

  const handleImport = async () => {
    if (!importBeacon || !importProject) return
    
    setImportLoading(true)
    
    try {
      const { error } = await dbClient.from('survey_points').insert({
        project_id: importProject,
        point_name: importBeacon.name,  // T1.5d FIX: was 'name' (column doesn't exist)
        easting: importBeacon.easting,
        northing: importBeacon.northing,
        elevation: importBeacon.elevation,
        is_control: true,
        // T1.5d: control_order and locked columns don't exist — removed.
        // The beacon's datum/utm_zone could be carried over here too.
        datum: importBeacon.datum || 'Arc 1960',
        utm_zone: importBeacon.utm_zone || 37,
        source: 'beacon_registry',
      })

      if (error) throw error
      
      setImportMsg({text:'Beacon imported successfully!', ok:true}); setTimeout(()=>setImportMsg(null),3000)
      setImportBeacon(null)
      setImportProject('')
    } catch (err: unknown) {
      const msg = err instanceof Error ? (err as Error).message : String(err)
      setImportMsg({text:'Error: '+msg, ok:false}); setTimeout(()=>setImportMsg(null),4000)
    }
    
    setImportLoading(false)
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)] flex flex-col">
      <header className="bg-[var(--bg-secondary)] border-b border-[var(--border-color)] px-4 py-4">
        <div className="max-w-7xl mx-auto">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h1 className="text-2xl font-bold text-[var(--text-primary)]">Community Beacons</h1>
              <p className="text-sm text-[var(--text-secondary)]">East Africa Control Network</p>
            </div>
            <div className="flex gap-3">
              <Link
                href="/beacons/submit"
                className="px-4 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded-lg"
              >
                + Submit Beacon
              </Link>
            </div>
          </div>

          <div className="flex gap-4 items-center">
              <input
                type="text"
                placeholder="Search by name or authority..."
                value={search}
                onChange={e => setSearch(e.target.value)}
                className="flex-1 px-4 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)]"
              />
              <div className="flex gap-2">
                {['all', 'trig', 'control', 'boundary', 'benchmark'].map((f) => (
                  <button
                    key={f}
                    onClick={() => setFilter(f)}
                    className={`px-3 py-2 rounded text-sm capitalize ${
                      filter === f ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-primary)]'
                    }`}
                  >
                    {f}
                  </button>
                ))}
              </div>
            </div>
        </div>
      </header>

      <main className="flex-1 relative">
        {loading ? (
          <div className="flex items-center justify-center h-full">
            <div className="animate-spin w-8 h-8 border-2 border-[var(--accent)] border-t-transparent rounded-full"></div>
          </div>
        ) : (
          <div className="h-full" style={{ height: 'calc(100vh - 140px)' }}>
            <div ref={mapRef} className="w-full h-full" />
            <div ref={popupRef} className="bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded p-2 text-sm shadow-lg" style={{ display: 'none' }}></div>
          </div>
        )}
      </main>

      {/* Import Modal */}
      {importBeacon && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-xl p-6 max-w-md w-full mx-4">
            <h3 className="text-lg font-bold text-[var(--text-primary)] mb-4">Import Beacon</h3>
            <p className="text-[var(--text-primary)] mb-4">
              Import {importBeacon.name} as a locked Primary control point?
            </p>
            
            <div className="mb-4">
              <label htmlFor="beacon-project" className="block text-sm text-[var(--text-secondary)] mb-2">Select Project</label>
              <select
                id="beacon-project"
                value={importProject}
                onChange={e => setImportProject(e.target.value)}
                className="w-full px-4 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]"
              >
                <option value="">Choose project...</option>
                {projects.map((p) => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
              </select>
            </div>

            <div className="flex gap-3">
              <button
                onClick={() => setImportBeacon(null)}
                className="flex-1 px-4 py-2 bg-[var(--bg-tertiary)] text-[var(--text-primary)] rounded"
              >
                Cancel
              </button>
              <button
                onClick={handleImport}
                disabled={!importProject || importLoading}
                className="flex-1 px-4 py-2 bg-[var(--accent)] text-black font-semibold rounded disabled:opacity-50"
              >
                {importLoading ? 'Importing...' : 'Import'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Beacon Registry — searchable global database */}
      <div className="max-w-7xl mx-auto w-full px-4 py-6">
        <BeaconRegistryPanel />
      </div>

      {/* Control Point Registry — SoK Trig stations, KENCORS, benchmarks */}
      <div className="max-w-7xl mx-auto w-full px-4 pb-6">
        <ControlPointRegistry />
      </div>
    </div>
  )
}

'use client';

import { Suspense, useEffect, useMemo, useState } from 'react'
import { useSearchParams } from 'next/navigation'
import type { CurrencyCode, PlanId } from '@/lib/subscription/catalog'
import { PLAN_CATALOG } from '@/lib/subscription/catalog'
import {
  checkMpesaPaymentStatus,
  getCurrencyForCountry,
  getPaymentMethods,
  startSubscriptionPayment,
  type PaymentMethod,
} from '@/lib/enterprise'

// PayPal only supports these currencies
const PAYPAL_CURRENCIES = new Set(['USD', 'EUR', 'GBP', 'AUD', 'CAD', 'CHF', 'CZK', 'DKK', 'HKD', 'HUF', 'ILS', 'JPY', 'MXN', 'NOK', 'NZD', 'PHP', 'PLN', 'SEK', 'SGD', 'THB', 'TWD'])

function CheckoutContent() {
  const searchParams = useSearchParams()
  const [step, setStep] = useState<1 | 2 | 3 | 4>(1)
  const [selectedPlanId, setSelectedPlanId] = useState<PlanId>(() => {
    const planParam = searchParams.get('plan') as PlanId | null
    if (planParam && PLAN_CATALOG.some(p => p.id === planParam)) return planParam
    return 'pro'
  })
  const [country, setCountry] = useState('Kenya')
  const [currency, setCurrency] = useState<CurrencyCode>('KES')
  const [method, setMethod] = useState<PaymentMethod['type']>('mpesa')
  const [phoneNumber, setPhoneNumber] = useState('')
  const [email, setEmail] = useState('')
  const [processing, setProcessing] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [mpesa, setMpesa] = useState<{ paymentId: string; checkoutRequestId: string } | null>(null)

  const plan = useMemo(
    () => PLAN_CATALOG.find((p) => p.id === selectedPlanId)!,
    [selectedPlanId]
  )

  const paymentMethods = useMemo(() => getPaymentMethods(country), [country])

  useEffect(() => {
    if (!paymentMethods.some((m) => m.type === method)) {
      setMethod(paymentMethods[0]?.type ?? 'card')
    }
  }, [paymentMethods, method])

  const formatPrice = (amount: number) => {
    const symbols: Partial<Record<CurrencyCode, string>> = {
      KES: 'KSh ',
      UGX: 'USh ',
      TZS: 'TSh ',
      NGN: '₦ ',
      GHS: 'GH₵ ',
      ZAR: 'R ',
      USD: '$ ',
      EUR: '€ ',
      GBP: '£ ',
      INR: '₹ ',
      IDR: 'Rp ',
      BRL: 'R$ ',
      AUD: 'A$ ',
    }
    return `${symbols[currency] ?? `${currency} `}${amount.toLocaleString()}`
  }

  const onStart = async () => {
    setError(null)
    setProcessing(true)
    try {
      const res = await startSubscriptionPayment({
        planId: plan.id,
        currency,
        method,
        email,
        phoneNumber: phoneNumber || undefined,
        country,
      })

      if (res.kind === 'activated') {
        window.location.href = '/dashboard'
        return
      }

      if (res.kind === 'redirect') {
        window.location.href = res.url
        return
      }

      if (res.kind === 'mpesa') {
        setMpesa({ paymentId: res.paymentId, checkoutRequestId: res.checkoutRequestId })
        setStep(4)
        return
      }

      setError('Unexpected payment response.')
    } catch (e: unknown) {
      setError(((e as Error)?.message) ?? 'Payment failed.')
    } finally {
      setProcessing(false)
    }
  }

  const canContinueDetails =
    !!email && (method !== 'mpesa' || !!phoneNumber) && paymentMethods.some((m) => m.type === method)

  return (
    <div className="min-h-screen">
      <div className="max-w-4xl mx-auto px-4 py-8 md:py-10">
        <h1 className="text-2xl md:text-3xl font-bold text-[var(--text-primary)] mb-2">Checkout</h1>
        <p className="text-[var(--text-secondary)] mb-8">Choose a plan and complete payment.</p>

        <div className="flex gap-2 mb-8">
          {[1, 2, 3].map((s) => (
            <div
              key={s}
              className={`flex-1 h-2 rounded ${step >= s ? 'bg-[var(--accent)]' : 'bg-[var(--bg-tertiary)]'}`}
            />
          ))}
        </div>

        {error && (
          <div className="mb-6 rounded-lg border border-red-900/50 bg-red-900/10 px-4 py-3 text-sm text-red-200">
            {error}
          </div>
        )}

        {step === 1 && (
          <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold text-[var(--text-primary)] mb-4">1) Select Plan</h2>

            <div className="mb-4">
              <label htmlFor="checkout-country" className="block text-sm font-medium text-[var(--text-primary)] mb-2">Country</label>
              <select
                id="checkout-country"
                value={country}
                onChange={(e) => {
                  const c = e.target.value
                  setCountry(c)
                  setCurrency(getCurrencyForCountry(c))
                }}
                className="w-full p-3 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)] min-h-[44px]"
              >
                <option value="Kenya">Kenya</option>
                <option value="Uganda">Uganda</option>
                <option value="Tanzania">Tanzania</option>
                <option value="Nigeria">Nigeria</option>
                <option value="Ghana">Ghana</option>
                <option value="South Africa">South Africa</option>
                <option value="Germany">Germany</option>
                <option value="UK">UK</option>
                <option value="US">US</option>
              </select>
              <p className="text-xs text-[var(--text-muted)] mt-2">Currency auto-selects from country, and you can still pay via card globally.</p>
            </div>

            <div className="space-y-3">
              {PLAN_CATALOG.map((p) => (
                <button
                  key={p.id}
                  type="button"
                  onClick={() => setSelectedPlanId(p.id)}
                  className={`w-full text-left p-4 border-2 rounded-lg transition min-h-[56px] ${
                    selectedPlanId === p.id ? 'border-[var(--accent)] bg-[var(--accent)]/10' : 'border-[var(--border-color)] hover:border-[var(--border-hover)]'
                  }`}
                >
                  <div className="flex items-center justify-between gap-4">
                    <div>
                      <div className="text-[var(--text-primary)] font-semibold text-lg">{p.name}</div>
                      <div className="text-[var(--text-muted)] text-sm">{p.features.slice(0, 2).join(' • ')}</div>
                    </div>
                    <div className="text-right">
                      <div className="text-[var(--accent)] font-bold text-2xl">{formatPrice(p.prices[currency])}</div>
                      <div className="text-[var(--text-muted)] text-xs">/month</div>
                    </div>
                  </div>
                </button>
              ))}
            </div>

            <button
              onClick={() => setStep(2)}
              className="w-full mt-6 py-3.5 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] font-medium min-h-[44px]"
            >
              Continue
            </button>
          </div>
        )}

        {step === 2 && (
          <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold text-[var(--text-primary)] mb-4">2) Payment Details</h2>

            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <label htmlFor="checkout-email" className="block text-sm font-medium text-[var(--text-primary)] mb-2">Email</label>
                <input
                  id="checkout-email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="you@example.com"
                  className="w-full p-3 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)] min-h-[44px]"
                />
              </div>
              <div>
                <label htmlFor="checkout-phone" className="block text-sm font-medium text-[var(--text-primary)] mb-2">Phone (M-Pesa only)</label>
                <input
                  id="checkout-phone"
                  type="tel"
                  value={phoneNumber}
                  onChange={(e) => setPhoneNumber(e.target.value)}
                  placeholder="e.g. 254712345678"
                  className="w-full p-3 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)] min-h-[44px]"
                />
                <p className="text-xs text-[var(--text-muted)] mt-2">Required only for M-Pesa STK Push.</p>
              </div>
            </div>

            <div className="mt-6">
              <div className="block text-sm font-medium text-[var(--text-primary)] mb-2">Payment Method</div>
              <div className="space-y-2">
                {paymentMethods.map((pm) => (
                  <label
                    key={pm.id}
                    className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer min-h-[44px] ${
                      method === pm.type ? 'border-[var(--accent)] bg-[var(--accent)]/10' : 'border-[var(--border-color)]'
                    }`}
                  >
                    <input aria-label="Paymentmethod"
                      type="radio"
                      name="paymentMethod"
                      value={pm.type}
                      checked={method === pm.type}
                      onChange={() => setMethod(pm.type)}
                    />
                    <span className="text-[var(--text-primary)]">{pm.name}</span>
                  </label>
                ))}
              </div>
            </div>

            <div className="flex gap-3 mt-6">
              <button
                onClick={() => setStep(1)}
                className="flex-1 py-3.5 border border-[var(--border-hover)] text-[var(--text-primary)] rounded-lg hover:bg-[var(--bg-primary)] font-medium min-h-[44px]"
              >
                Back
              </button>
              <button
                onClick={() => setStep(3)}
                disabled={!canContinueDetails}
                className="flex-1 py-3.5 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] disabled:bg-gray-700 disabled:text-[var(--text-primary)] font-medium min-h-[44px]"
              >
                Review Order
              </button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold text-[var(--text-primary)] mb-4">3) Confirm & Pay</h2>

            <div className="rounded-lg border border-[var(--border-color)] bg-[var(--bg-primary)] p-4 mb-6">
              <div className="flex items-center justify-between text-[var(--text-primary)] mb-2">
                <span>Plan</span>
                <span className="font-semibold">{plan.name}</span>
              </div>
              <div className="flex items-center justify-between text-[var(--text-primary)] mb-2">
                <span>Currency</span>
                <span className="font-semibold">{currency}</span>
              </div>
              <div className="flex items-center justify-between text-[var(--text-primary)] mb-2">
                <span>Method</span>
                <span className="font-semibold">{paymentMethods.find((p) => p.type === method)?.name ?? method}</span>
              </div>
              <div className="flex items-center justify-between border-t border-[var(--border-color)] pt-2 mt-2 text-[var(--text-primary)]">
                <span className="font-semibold">Total</span>
                <span className="font-bold text-lg text-[var(--accent)]">{formatPrice(plan.prices[currency])}</span>
              </div>
            </div>

            <div className="text-xs text-[var(--text-muted)] mb-6">
              Card payments use Stripe Checkout (Visa/Mastercard). PayPal redirects to PayPal approval. M-Pesa triggers STK push.
              {method === 'paypal' && !PAYPAL_CURRENCIES.has(currency) && (
                <span className="block mt-2 text-amber-400">
                  PayPal does not support {currency}. You will be charged the USD equivalent.
                </span>
              )}
            </div>

            <div className="flex gap-3">
              <button
                onClick={() => setStep(2)}
                className="flex-1 py-3.5 border border-[var(--border-hover)] text-[var(--text-primary)] rounded-lg hover:bg-[var(--bg-primary)] font-medium min-h-[44px]"
              >
                Back
              </button>
              <button
                onClick={onStart}
                disabled={processing}
                className="flex-1 py-3.5 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] disabled:bg-gray-700 disabled:text-[var(--text-primary)] font-medium min-h-[44px]"
              >
                {processing ? 'Starting payment…' : 'Pay Now'}
              </button>
            </div>
          </div>
        )}

        {step === 4 && mpesa && (
          <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold text-[var(--text-primary)] mb-2">M-Pesa STK Push Sent</h2>
            <p className="text-[var(--text-secondary)] mb-6">Complete payment on your phone, then verify to activate your plan.</p>

            <button
              onClick={async () => {
                setProcessing(true)
                setError(null)
                try {
                  const r = await checkMpesaPaymentStatus(mpesa)
                  if (r.status === 'completed') {
                    window.location.href = '/dashboard'
                    return
                  }
                  if (r.status === 'failed') setError('Payment failed. Please try again.')
                  if (r.status === 'pending') setError('Still pending. If you have paid, wait a moment then try again.')
                } catch (e: unknown) {
                  setError(((e as Error)?.message) ?? 'Failed to verify payment.')
                } finally {
                  setProcessing(false)
                }
              }}
              disabled={processing}
              className="w-full py-3.5 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] disabled:bg-gray-700 disabled:text-[var(--text-primary)] font-medium min-h-[44px]"
            >
              {processing ? 'Checking…' : 'Verify Payment'}
            </button>

            <button
              onClick={() => {
                setMpesa(null)
                setStep(2)
              }}
              className="w-full mt-3 py-3.5 border border-[var(--border-hover)] text-[var(--text-primary)] rounded-lg hover:bg-[var(--bg-primary)] font-medium min-h-[44px]"
            >
              Change method
            </button>
          </div>
        )}
      </div>
    </div>
  )
}

export default function CheckoutPage() {
  return (
    <Suspense fallback={
      <div className="min-h-screen flex items-center justify-center">
        <div className="w-6 h-6 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin" />
      </div>
    }>
      <CheckoutContent />
    </Suspense>
  )
}

