'use client';

import { useState, useEffect } from 'react'
import {
  getCPDRequirements,
  type CPDRequirement,
  type CPDSummary
} from '@/lib/marketplace/cpdCertificates'

/**
 * AUDIT FIX (H9, 2026-07-02): Rewired to call the real CPD API
 * (/api/cpd) instead of the stub cpdCertificates.getUserActivities()
 * which always returned []. The stub is still imported for
 * getCPDRequirements + getActivityTypes (static reference data that
 * doesn't need the DB), but all user-data fetches now go through
 * the API which calls lib/cpd.ts → cpd_records table.
 */

/**
 * Shape rendered by the "My Activities" list. The /api/cpd endpoint actually
 * returns CPDRecord[] (lib/cpd.ts); these display fields are legacy and may be
 * undefined for API-sourced rows — kept optional to match what the JSX reads.
 */
interface CpdActivityRow {
  id: string
  title?: string
  provider?: string
  date?: string
  hours?: number
  status?: string
}

export default function CPDPage() {
  const [loading, setLoading] = useState(true)
  const [fetchError, setFetchError] = useState<string | null>(null)
  const [activities, setActivities] = useState<CpdActivityRow[]>([])
  const [summary, setSummary] = useState<CPDSummary | null>(null)
  const [country, setCountry] = useState('Kenya')
  const [requirements, setRequirements] = useState<CPDRequirement[]>([])
  const [totalPoints, setTotalPoints] = useState(0)

  useEffect(() => {
    const loadData = async () => {
      setRequirements(getCPDRequirements(country))

      try {
        // Fetch real CPD data from the API (which calls lib/cpd.ts → DB)
        const year = new Date().getFullYear()
        const res = await fetch(`/api/cpd?year=${year}`, { credentials: 'include' })
        let fetchedTotal = 0
        if (res.ok) {
          const data = (await res.json()) as { records?: CpdActivityRow[]; total?: number }
          setActivities(data.records ?? [])
          fetchedTotal = data.total ?? 0
          setTotalPoints(fetchedTotal)
        } else if (res.status === 401) {
          // Not logged in — show empty state
          setActivities([])
          setTotalPoints(0)
        } else {
          setFetchError('Failed to load CPD records')
        }

        // Build summary from the fetched total (not from state, which may be stale)
        const req = getCPDRequirements(country)[0]
        const requiredHours = req?.yearlyHours ?? 40
        setSummary({
          totalHours: fetchedTotal,
          requirementHours: requiredHours,
          compliancePercentage: requiredHours > 0 ? Math.min(100, (fetchedTotal / requiredHours) * 100) : 0,
          status: fetchedTotal >= requiredHours ? 'compliant' : fetchedTotal >= requiredHours * 0.75 ? 'at_risk' : 'non_compliant',
        } as CPDSummary)
      } catch {
        setFetchError('Network error loading CPD records')
      }

      setLoading(false)
    }
    loadData()
    // AUDIT FIX: Removed totalPoints from dependency array — it's SET inside
    // the effect, so including it causes an infinite render loop.
  }, [country])

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'approved': return 'bg-green-100 text-green-800'
      case 'pending': return 'bg-yellow-100 text-yellow-800'
      case 'rejected': return 'bg-red-100 text-red-800'
      default: return 'bg-[var(--bg-tertiary)] text-[var(--text-primary)]'
    }
  }

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center">
      <div className="text-[var(--text-muted)] text-sm animate-pulse">Loading...</div>
    </div>
  )

  return (
    <div className="min-h-screen bg-[var(--bg-primary)]">
      <div className="max-w-6xl mx-auto px-4 py-8">
        <h1 className="text-3xl font-bold text-[var(--text-primary)] mb-2">CPD Certificates</h1>
        <p className="text-[var(--text-muted)] mb-8">Continuing Professional Development tracking and certificates</p>
        
        <div className="bg-blue-50/50 border border-blue-100 rounded-lg p-3 mb-6 flex items-start gap-3 text-sm">
          <div className="text-blue-500 mt-0.5">(i)</div>
          <p className="text-[var(--text-secondary)]">
            <span className="font-medium text-[var(--text-primary)]">Auto-logging active:</span> Hours are auto-logged when you use METARDU computation tools. Manual entries can be added below.
          </p>
        </div>

        <div className="mb-6">
          <label htmlFor="cpd-country" className="block text-sm font-medium text-[var(--text-muted)] mb-2">Select Country</label>
          <select
            id="cpd-country"
            value={country}
            onChange={(e) => setCountry(e.target.value)}
            className="p-2 border rounded-lg w-64"
          >
            <option value="Kenya">Kenya (ISK)</option>
            <option value="Uganda">Uganda</option>
            <option value="Tanzania">Tanzania</option>
            <option value="Nigeria">Nigeria</option>
            <option value="South Africa">South Africa</option>
          </select>
        </div>

        {requirements.map((req) => (
          <div key={req.id} className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-6">
            <h3 className="font-semibold text-blue-900">{req.body}</h3>
            <p className="text-sm text-blue-700">{req.notes}</p>
          </div>
        ))}

        {summary && (
          <div className="grid md:grid-cols-4 gap-4 mb-8">
            <div className="bg-[var(--bg-card)] rounded-lg border border-[var(--border-color)] p-4">
              <p className="text-sm text-[var(--text-muted)]">Total Hours</p>
              <p className="text-2xl font-bold">{summary.totalHours}</p>
            </div>
            <div className="bg-[var(--bg-card)] rounded-lg border border-[var(--border-color)] p-4">
              <p className="text-sm text-[var(--text-muted)]">Required</p>
              <p className="text-2xl font-bold">{summary.requirementHours}</p>
            </div>
            <div className="bg-[var(--bg-card)] rounded-lg border border-[var(--border-color)] p-4">
              <p className="text-sm text-[var(--text-muted)]">Compliance</p>
              <p className={`text-2xl font-bold ${
                summary.status === 'compliant' ? 'text-green-600' :
                summary.status === 'at_risk' ? 'text-yellow-600' : 'text-red-600'
              }`}>{summary.compliancePercentage.toFixed(0)}%</p>
            </div>
            <div className="bg-[var(--bg-card)] rounded-lg border border-[var(--border-color)] p-4">
              <p className="text-sm text-[var(--text-muted)]">Status</p>
              <p className={`text-lg font-bold ${
                summary.status === 'compliant' ? 'text-green-600' :
                summary.status === 'at_risk' ? 'text-yellow-600' : 'text-red-600'
              }`}>{summary.status.replace('_', ' ').toUpperCase()}</p>
            </div>
          </div>
        )}

        <div className="bg-[var(--bg-card)] rounded-lg border border-[var(--border-color)] p-6 mb-6">
          <h2 className="text-lg font-semibold mb-4">Category Breakdown</h2>
          {summary && (
            <div className="space-y-3">
              {/* AUDIT FIX (H-008, 2026-07-27): categoryBreakdown is not part
                  of the locally-built CPDSummary shape (only totalHours,
                  requirementHours, compliancePercentage, status). The API
                  (`/api/cpd`) returns a different shape. Guard with `?.` to
                  prevent "Cannot read properties of undefined (reading
                  'technical')". */}
              {(['technical', 'ethics', 'safety', 'management'] as const).map((cat) => {
                const hours = summary.categoryBreakdown?.[cat] ?? 0
                const pct = summary.totalHours > 0 ? (hours / summary.totalHours) * 100 : 0
                const barColor =
                  cat === 'technical' ? 'bg-blue-600' :
                  cat === 'ethics' ? 'bg-green-600' :
                  cat === 'safety' ? 'bg-yellow-600' :
                  'bg-purple-600'
                const label = cat.charAt(0).toUpperCase() + cat.slice(1)
                return (
                  <div key={cat}>
                    <div className="flex justify-between text-sm mb-1">
                      <span>{label}</span>
                      <span>{hours} hours</span>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-2">
                      <div className={`${barColor} h-2 rounded-full`} style={{ width: `${pct}%` }}></div>
                    </div>
                  </div>
                )
              })}
              {!summary.categoryBreakdown && (
                <p className="text-sm text-[var(--text-muted)]">
                  Category breakdown unavailable — your CPD records haven't been categorized yet.
                </p>
              )}
            </div>
          )}
        </div>

        <div className="bg-[var(--bg-card)] rounded-lg border border-[var(--border-color)] p-6">
          <h2 className="text-lg font-semibold mb-4">My Activities</h2>
          <div className="space-y-3">
            {activities.map((activity) => (
              <div key={activity.id} className="flex items-center justify-between border-b pb-3">
                <div>
                  <h4 className="font-medium">{activity.title}</h4>
                  <p className="text-sm text-[var(--text-muted)]">{activity.provider} • {new Date(activity.date ?? '').toLocaleDateString()}</p>
                </div>
                <div className="text-right">
                  <p className="font-semibold">{activity.hours} hours</p>
                  <span className={`text-xs px-2 py-1 rounded ${getStatusColor(activity.status ?? '')}`}>
                    {activity.status}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  )
}

'use client';

import { useState } from 'react'
import { 
  signDocument, 
  verifySignature, 
  generateQRPayload, 
  parseQRPayload,
  createSurveyReportSignature,
  SignedDocument,
  QRVerificationResult
} from '@/lib/integrations/digitalSignature'

export default function DigitalSignaturePage() {
  const [validationMsg, setValidationMsg] = useState<string|null>(null)
  const [activeTab, setActiveTab] = useState<'sign' | 'verify'>('sign')
  const [signForm, setSignForm] = useState({
    documentId: '',
    content: '',
    signerId: '',
    secret: ''
  })
  const [verifyForm, setVerifyForm] = useState({
    qrPayload: '',
    originalContent: '',
    secret: ''
  })
  const [signedDoc, setSignedDoc] = useState<SignedDocument | null>(null)
  const [verificationResult, setVerificationResult] = useState<QRVerificationResult | null>(null)
  const [qrCode, setQrCode] = useState('')

  const handleSign = async () => {
    if (!signForm.documentId || !signForm.content || !signForm.signerId || !signForm.secret) {
      setValidationMsg('Please fill all required fields.'); return
    }
    const signed = await signDocument(
      signForm.documentId,
      signForm.content,
      signForm.signerId,
      signForm.secret
    )
    setSignedDoc(signed)
    setQrCode(generateQRPayload(signed))
  }

  const handleVerify = async () => {
    if (!verifyForm.qrPayload || !verifyForm.originalContent || !verifyForm.secret) {
      setValidationMsg('Please fill all required fields.'); return
    }
    const parsed = parseQRPayload(verifyForm.qrPayload)
    if (!parsed) {
      setVerificationResult({
        valid: false,
        message: 'Invalid QR payload format',
        verifiedAt: Date.now()
      })
      return
    }
    const result = await verifySignature(parsed, verifyForm.originalContent, verifyForm.secret)
    setVerificationResult(result)
  }

  const handleSurveySign = async () => {
    if (!signForm.signerId || !signForm.secret) {
      setValidationMsg('Please enter your signer ID and secret key.'); return
    }
    const measurements: Record<string, number> = {
      pointA_Easting: 500000.00,
      pointA_Northing: 9800000.00,
      pointB_Easting: 500100.00,
      pointB_Northing: 9800100.00,
      distance_AB: 141.42,
      bearing_AB_Value: 45.0
    }
    const signed = await createSurveyReportSignature(
      `SURVEY-${Date.now()}`,
      signForm.signerId,
      measurements,
      signForm.secret
    )
    setSignedDoc(signed)
    setQrCode(generateQRPayload(signed))
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)]">
      <div className="max-w-4xl mx-auto px-4 py-8">
        <h1 className="text-3xl font-bold text-[var(--text-primary)] mb-2">Digital Signature & QR Verification</h1>
        <p className="text-[var(--text-muted)] mb-8">Sign survey documents and verify signatures with QR codes</p>

        <div className="flex gap-2 mb-6">
          <button
            onClick={() => setActiveTab('sign')}
            className={`px-4 py-2 rounded-lg font-medium ${
              activeTab === 'sign' 
                ? 'bg-blue-600 text-white' 
                : 'bg-[var(--bg-secondary)] text-[var(--text-secondary)] border border-[var(--border-color)]'
            }`}
          >
            Sign Document
          </button>
          <button
            onClick={() => setActiveTab('verify')}
            className={`px-4 py-2 rounded-lg font-medium ${
              activeTab === 'verify' 
                ? 'bg-blue-600 text-white' 
                : 'bg-[var(--bg-secondary)] text-[var(--text-secondary)] border border-[var(--border-color)]'
            }`}
          >
            Verify Signature
          </button>
        </div>

        {activeTab === 'sign' && (
          <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold mb-4">Sign a Document</h2>
            
            <div className="space-y-4 mb-6">
              <div>
                <label htmlFor="sig-document-id" className="block text-sm font-medium text-[var(--text-secondary)] mb-1">
                  Document ID
                </label>
                <input
                  id="sig-document-id"
                  type="text"
                  value={signForm.documentId}
                  onChange={e => setSignForm({...signForm, documentId: e.target.value})}
                  aria-label="Document ID" placeholder="e.g., SURVEY-2024-001"
                  className="w-full p-2 border rounded-lg"
                />
              </div>
              <div>
                <label htmlFor="sig-content" className="block text-sm font-medium text-[var(--text-secondary)] mb-1">
                  Document Content
                </label>
                <textarea
                  id="sig-content"
                  value={signForm.content}
                  onChange={e => setSignForm({...signForm, content: e.target.value})}
                  placeholder="Enter document content to sign..."
                  rows={4}
                  className="w-full p-2 border rounded-lg"
                />
              </div>
              <div>
                <label htmlFor="sig-signer-id" className="block text-sm font-medium text-[var(--text-secondary)] mb-1">
                  Signer ID (License Number)
                </label>
                <input
                  id="sig-signer-id"
                  type="text"
                  value={signForm.signerId}
                  onChange={e => setSignForm({...signForm, signerId: e.target.value})}
                  aria-label="Signer ID (License Number)" placeholder="e.g., LS/2024/1234"
                  className="w-full p-2 border rounded-lg"
                />
              </div>
              <div>
                <label htmlFor="sig-secret" className="block text-sm font-medium text-[var(--text-secondary)] mb-1">
                  Secret Key
                </label>
                <input
                  id="sig-secret"
                  type="password"
                  value={signForm.secret}
                  onChange={e => setSignForm({...signForm, secret: e.target.value})}
                  aria-label="Secret key" placeholder="Enter signing secret"
                  className="w-full p-2 border rounded-lg"
                />
              </div>
            </div>

            <div className="flex gap-3 mb-6">
              <button
                onClick={handleSign}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
              >
                Sign Document
              </button>
              <button
                onClick={handleSurveySign}
                className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
              >
                Quick Survey Report Sign
              </button>
            </div>

            {signedDoc && (
              <div className="bg-green-50 border border-green-200 rounded-lg p-4">
                <h3 className="font-medium text-green-800 mb-2"> Document Signed Successfully</h3>
                <div className="text-sm text-green-700 space-y-1">
                  <p><strong>Document ID:</strong> {signedDoc.documentId}</p>
                  <p><strong>Signer:</strong> {signedDoc.signerId}</p>
                  <p><strong>Timestamp:</strong> {new Date(signedDoc.timestamp).toLocaleString()}</p>
                  <p><strong>Document Hash:</strong> <code className="text-xs">{signedDoc.documentHash}</code></p>
                  <p><strong>Signature:</strong> <code className="text-xs">{signedDoc.signature}</code></p>
                </div>
                
                {qrCode && (
                  <div className="mt-4 p-4 bg-[var(--bg-secondary)] rounded-lg border border-[var(--border-color)]">
                    <p className="text-sm font-medium text-[var(--text-secondary)] mb-2">QR Payload (Base64):</p>
                    <textarea
                      readOnly
                      value={qrCode}
                      className="w-full p-2 text-xs font-mono border rounded bg-[var(--bg-secondary)] text-[var(--text-primary)]"
                      rows={3}
                    />
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {activeTab === 'verify' && (
          <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold mb-4">Verify a Signature</h2>
            
            <div className="space-y-4 mb-6">
              <div>
                <label htmlFor="verify-qr" className="block text-sm font-medium text-[var(--text-secondary)] mb-1">
                  QR Payload (Base64)
                </label>
                <textarea
                  id="verify-qr"
                  value={verifyForm.qrPayload}
                  onChange={e => setVerifyForm({...verifyForm, qrPayload: e.target.value})}
                  placeholder="Paste QR payload from signed document..."
                  rows={3}
                  className="w-full p-2 border rounded-lg font-mono text-sm"
                />
              </div>
              <div>
                <label htmlFor="verify-original" className="block text-sm font-medium text-[var(--text-secondary)] mb-1">
                  Original Document Content
                </label>
                <textarea
                  id="verify-original"
                  value={verifyForm.originalContent}
                  onChange={e => setVerifyForm({...verifyForm, originalContent: e.target.value})}
                  placeholder="Enter original document content..."
                  rows={4}
                  className="w-full p-2 border rounded-lg"
                />
              </div>
              <div>
                <label htmlFor="verify-secret" className="block text-sm font-medium text-[var(--text-secondary)] mb-1">
                  Secret Key
                </label>
                <input
                  id="verify-secret"
                  type="password"
                  value={verifyForm.secret}
                  onChange={e => setVerifyForm({...verifyForm, secret: e.target.value})}
                  aria-label="Secret key" placeholder="Enter signing secret"
                  className="w-full p-2 border rounded-lg"
                />
              </div>
            </div>

            <button
              onClick={handleVerify}
              className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 mb-6"
            >
              Verify Signature
            </button>

            {verificationResult && (
              <div className={`border rounded-lg p-4 ${
                verificationResult.valid 
                  ? 'bg-green-50 border-green-200' 
                  : 'bg-red-50 border-red-200'
              }`}>
                <h3 className={`font-medium mb-2 ${
                  verificationResult.valid ? 'text-green-800' : 'text-red-800'
                }`}>
                  {verificationResult.valid ? ' Signature Verified' : '[x] Verification Failed'}
                </h3>
                <p className="text-sm">{verificationResult.message}</p>
                <p className="text-xs text-[var(--text-muted)] mt-2">
                  Verified at: {new Date(verificationResult.verifiedAt).toLocaleString()}
                </p>
                
                {verificationResult.document && verificationResult.valid && (
                  <div className="mt-4 text-sm text-green-700">
                    <p><strong>Document ID:</strong> {verificationResult.document.documentId}</p>
                    <p><strong>Signer:</strong> {verificationResult.document.signerId}</p>
                    <p><strong>Signed:</strong> {new Date(verificationResult.document.timestamp).toLocaleString()}</p>
                  </div>
                )}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { PageHeader } from '@/components/shared/PageHeader'
import {
  Upload, Cloud, Loader2, CheckCircle2, XCircle, Download,
  Map as MapIcon, Box, Mountain, FileCode, ChevronRight, RefreshCw,
} from 'lucide-react'
import Link from 'next/link'
import { logger } from '@/lib/logger'

// ─── Types ──────────────────────────────────────────────────────────────────

type TaskStatus = 'uploading' | 'queued' | 'running' | 'completed' | 'failed' | 'imported'

interface DroneTask {
  id: string
  name: string
  photo_count: number
  total_size_mb: number
  status: TaskStatus
  progress: number
  error_message?: string
  orthophoto_path?: string
  pointcloud_path?: string
  dsm_path?: string
  dtm_path?: string
  contour_path?: string
  created_at: string
  processing_completed_at?: string
}

// ─── Upload Section ─────────────────────────────────────────────────────────

function UploadSection({ onTaskCreated }: { onTaskCreated: (taskId: string) => void }) {
  const [uploading, setUploading] = useState(false)
  const [progress, setProgress] = useState(0)
  const [taskName, setTaskName] = useState(`Drone Survey ${new Date().toLocaleDateString()}`)
  const [selectedFiles, setSelectedFiles] = useState<File[]>([])
  const [error, setError] = useState<string | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || [])
    setSelectedFiles(prev => [...prev, ...files])
    setError(null)
  }

  const handleUpload = async () => {
    if (selectedFiles.length === 0) {
      setError('Select at least one photo')
      return
    }

    setUploading(true)
    setProgress(0)
    setError(null)

    try {
      const formData = new FormData()
      formData.append('name', taskName)
      selectedFiles.forEach(f => formData.append('photos', f))

      // Simulate progress while uploading (we can't get real progress from fetch)
      const progressInterval = setInterval(() => {
        setProgress(p => Math.min(p + 5, 90))
      }, 500)

      const res = await fetch('/api/drone/upload', {
        method: 'POST',
        body: formData,
      })

      clearInterval(progressInterval)
      setProgress(100)

      if (!res.ok) {
        const data = (await res.json()) as { error?: string }
        throw new Error(data.error || `Upload failed (${res.status})`)
      }

      const data = (await res.json()) as { taskId: string }
      onTaskCreated(data.taskId)
      setSelectedFiles([])
      if (fileInputRef.current) fileInputRef.current.value = ''
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Upload failed')
    } finally {
      setUploading(false)
      setTimeout(() => setProgress(0), 1000)
    }
  }

  return (
    <div className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-card)] p-6">
      <div className="flex items-center gap-3 mb-4">
        <Upload className="w-5 h-5 text-[var(--accent)]" />
        <h2 className="text-lg font-bold text-[var(--text-primary)]">1. Upload Drone Photos</h2>
      </div>

      <div className="space-y-4">
        {/* Task name */}
        <div>
          <label htmlFor="drone-survey-name" className="block text-sm text-[var(--text-muted)] mb-2">Survey Name</label>
          <input
            id="drone-survey-name"
            type="text"
            value={taskName}
            onChange={e => setTaskName(e.target.value)}
            className="w-full bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-sm text-[var(--text-primary)] focus:border-[var(--accent)] outline-none"
          />
        </div>

        {/* File input */}
        <div>
          <label htmlFor="drone-photos" className="block text-sm text-[var(--text-muted)] mb-2">Photos (JPG, PNG, or TIFF — max 25MB each, max 200 photos)</label>
          <div
            onClick={() => fileInputRef.current?.click()}
            className="border-2 border-dashed border-[var(--border-color)] rounded-lg p-8 text-center cursor-pointer hover:border-[var(--accent)] transition-colors"
          >
            <Upload className="w-8 h-8 text-[var(--text-muted)] mx-auto mb-2" />
            <p className="text-sm text-[var(--text-secondary)]">
              {selectedFiles.length > 0
                ? `${selectedFiles.length} photo${selectedFiles.length !== 1 ? 's' : ''} selected (${Math.round(selectedFiles.reduce((s, f) => s + f.size, 0) / 1024 / 1024)}MB)`
                : 'Click to select photos'}
            </p>
          </div>
          <input
            ref={fileInputRef}
            id="drone-photos"
            type="file"
            multiple
            accept=".jpg,.jpeg,.png,.tif,.tiff"
            onChange={handleFileSelect}
            className="hidden"
          />
        </div>

        {/* Selected files list */}
        {selectedFiles.length > 0 && (
          <div className="max-h-32 overflow-y-auto space-y-1">
            {selectedFiles.slice(0, 5).map((f, i) => (
              <div key={i} className="text-xs text-[var(--text-muted)] flex justify-between">
                <span className="truncate">{f.name}</span>
                <span className="shrink-0 ml-2">{(f.size / 1024 / 1024).toFixed(1)}MB</span>
              </div>
            ))}
            {selectedFiles.length > 5 && (
              <p className="text-xs text-[var(--text-muted)]">...and {selectedFiles.length - 5} more</p>
            )}
          </div>
        )}

        {/* Upload progress */}
        {uploading && (
          <div className="space-y-1">
            <div className="flex justify-between text-xs text-[var(--text-muted)]">
              <span>Uploading {selectedFiles.length} photos...</span>
              <span>{progress}%</span>
            </div>
            <div className="h-2 bg-[var(--bg-tertiary)] rounded-full overflow-hidden">
              <div
                className="h-full bg-[var(--accent)] transition-all duration-300"
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>
        )}

        {error && (
          <p className="text-xs text-red-400 bg-red-500/10 rounded-lg p-2">{error}</p>
        )}

        <button
          onClick={handleUpload}
          disabled={uploading || selectedFiles.length === 0}
          className="w-full py-2.5 bg-[var(--accent)] text-black font-semibold rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-40 transition-colors text-sm flex items-center justify-center gap-2"
        >
          {uploading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Upload className="w-4 h-4" />}
          {uploading ? 'Uploading...' : `Upload ${selectedFiles.length} Photo${selectedFiles.length !== 1 ? 's' : ''}`}
        </button>
      </div>
    </div>
  )
}

// ─── Processing Section ─────────────────────────────────────────────────────

function ProcessingSection({ taskId }: { taskId: string }) {
  const [task, setTask] = useState<DroneTask | null>(null)
  const [processing, setProcessing] = useState(false)
  const [options, setOptions] = useState({
    demResolution: 5,
    orthophotoResolution: 5,
    dsm: true,
    dtm: true,
    contourResolution: 0.5,
  })

  const fetchTask = useCallback(async () => {
    const res = await fetch(`/api/drone/process?taskId=${taskId}`)
    if (res.ok) {
      const data = (await res.json()) as { task: DroneTask }
      setTask(data.task)
    }
  }, [taskId])

  useEffect(() => {
    fetchTask()

    // Poll every 5 seconds if task is running
    const interval = setInterval(() => {
      if (task && (task.status === 'queued' || task.status === 'running')) {
        fetchTask()
      }
    }, 5000)

    return () => clearInterval(interval)
  }, [fetchTask, task?.status])

  const startProcessing = async () => {
    setProcessing(true)
    try {
      const res = await fetch('/api/drone/process', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ taskId, ...options }),
      })

      if (!res.ok) {
        const data = (await res.json()) as { error?: string }
        throw new Error(data.error || 'Failed to start processing')
      }

      await fetchTask()
    } catch (err) {
      logger.error(err instanceof Error ? err.message : String(err))
    } finally {
      setProcessing(false)
    }
  }

  if (!task) return <div className="animate-pulse">Loading task...</div>

  const isProcessing = task.status === 'queued' || task.status === 'running'
  const isCompleted = task.status === 'completed'
  const isFailed = task.status === 'failed'

  return (
    <div className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-card)] p-6">
      <div className="flex items-center gap-3 mb-4">
        <Cloud className="w-5 h-5 text-[var(--accent)]" />
        <h2 className="text-lg font-bold text-[var(--text-primary)]">2. Process Photos</h2>
      </div>

      {/* Task summary */}
      <div className="grid grid-cols-3 gap-3 mb-4 text-center">
        <div className="bg-[var(--bg-tertiary)] rounded-lg p-2">
          <p className="text-lg font-bold text-[var(--text-primary)]">{task.photo_count}</p>
          <p className="text-[10px] text-[var(--text-muted)] uppercase">Photos</p>
        </div>
        <div className="bg-[var(--bg-tertiary)] rounded-lg p-2">
          <p className="text-lg font-bold text-[var(--text-primary)]">{Math.round(task.total_size_mb)}</p>
          <p className="text-[10px] text-[var(--text-muted)] uppercase">MB</p>
        </div>
        <div className="bg-[var(--bg-tertiary)] rounded-lg p-2">
          <p className="text-lg font-bold capitalize" style={{
            color: isCompleted ? '#34d399' : isFailed ? '#ef4444' : isProcessing ? '#f59e0b' : 'var(--text-primary)'
          }}>
            {task.status}
          </p>
          <p className="text-[10px] text-[var(--text-muted)] uppercase">Status</p>
        </div>
      </div>

      {/* Processing options (only show before processing starts) */}
      {!isProcessing && !isCompleted && (
        <div className="space-y-3 mb-4">
          <p className="text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider">Processing Options</p>
          <div className="grid grid-cols-2 gap-3">
            <label className="text-xs text-[var(--text-muted)]">
              Orthophoto Resolution (cm/px)
              <input
                type="number"
                value={options.orthophotoResolution}
                onChange={e => setOptions(o => ({ ...o, orthophotoResolution: +e.target.value }))}
                className="w-full mt-1 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded px-2 py-1.5 text-[var(--text-primary)]"
                min={1}
                max={50}
              />
            </label>
            <label className="text-xs text-[var(--text-muted)]">
              DSM Resolution (cm/px)
              <input
                type="number"
                value={options.demResolution}
                onChange={e => setOptions(o => ({ ...o, demResolution: +e.target.value }))}
                className="w-full mt-1 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded px-2 py-1.5 text-[var(--text-primary)]"
                min={1}
                max={50}
              />
            </label>
            <label className="text-xs text-[var(--text-muted)]">
              Contour Interval (m)
              <input
                type="number"
                step="0.1"
                value={options.contourResolution}
                onChange={e => setOptions(o => ({ ...o, contourResolution: +e.target.value }))}
                className="w-full mt-1 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded px-2 py-1.5 text-[var(--text-primary)]"
                min={0.1}
                max={10}
              />
            </label>
            <div className="flex items-center gap-3 pt-4">
              <label className="flex items-center gap-1.5 text-xs text-[var(--text-muted)] cursor-pointer">
                <input
                  type="checkbox"
                  checked={options.dsm}
                  onChange={e => setOptions(o => ({ ...o, dsm: e.target.checked }))}
                  className="rounded"
                />
                DSM
              </label>
              <label className="flex items-center gap-1.5 text-xs text-[var(--text-muted)] cursor-pointer">
                <input
                  type="checkbox"
                  checked={options.dtm}
                  onChange={e => setOptions(o => ({ ...o, dtm: e.target.checked }))}
                  className="rounded"
                />
                DTM
              </label>
            </div>
          </div>
        </div>
      )}

      {/* Progress bar (when processing) */}
      {isProcessing && (
        <div className="space-y-2 mb-4">
          <div className="flex justify-between text-xs">
            <span className="text-[var(--text-muted)]">
              {task.status === 'queued' ? 'Queued for processing...' : 'Processing photos...'}
            </span>
            <span className="text-[var(--accent)] font-semibold">{task.progress}%</span>
          </div>
          <div className="h-3 bg-[var(--bg-tertiary)] rounded-full overflow-hidden">
            <div
              className="h-full bg-gradient-to-r from-[var(--accent)] to-amber-500 transition-all duration-500"
              style={{ width: `${task.progress}%` }}
            />
          </div>
          <p className="text-[10px] text-[var(--text-muted)]">
            Processing can take 10-60 minutes depending on photo count and resolution. This page auto-refreshes every 5 seconds.
          </p>
        </div>
      )}

      {/* Error message */}
      {isFailed && task.error_message && (
        <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 mb-4">
          <p className="text-xs text-red-400 font-semibold">Processing Failed</p>
          <p className="text-xs text-[var(--text-muted)] mt-1">{task.error_message}</p>
        </div>
      )}

      {/* Start button */}
      {!isProcessing && !isCompleted && (
        <button
          onClick={startProcessing}
          disabled={processing || task.photo_count === 0}
          className="w-full py-2.5 bg-[var(--accent)] text-black font-semibold rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-40 transition-colors text-sm flex items-center justify-center gap-2"
        >
          {processing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Cloud className="w-4 h-4" />}
          {processing ? 'Starting...' : 'Start Processing'}
        </button>
      )}

      {/* Refresh button (when processing) */}
      {isProcessing && (
        <button
          onClick={fetchTask}
          className="w-full py-2 border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)] transition-colors flex items-center justify-center gap-1.5"
        >
          <RefreshCw className="w-3 h-3" /> Refresh Status
        </button>
      )}
    </div>
  )
}

// ─── Results Section ────────────────────────────────────────────────────────

function ResultsSection({ taskId }: { taskId: string }) {
  const [task, setTask] = useState<DroneTask | null>(null)

  useEffect(() => {
    fetch(`/api/drone/process?taskId=${taskId}`)
      .then(r => r.ok ? r.json() : null)
      .then((data: { task?: DroneTask } | null) => { if (data?.task) setTask(data.task) })
  }, [taskId])

  if (!task || task.status !== 'completed') return null

  const outputs = [
    { label: 'Orthophoto', path: task.orthophoto_path, icon: MapIcon, href: '/tools/orthophoto-viewer', desc: 'Georeferenced aerial image' },
    { label: 'Point Cloud', path: task.pointcloud_path, icon: Box, href: '/tools/point-cloud-import', desc: '3D LAS point cloud' },
    { label: 'DSM', path: task.dsm_path, icon: Mountain, href: '/tools/contour-generator', desc: 'Digital Surface Model' },
    { label: 'DTM', path: task.dtm_path, icon: Mountain, href: '/tools/contour-generator', desc: 'Digital Terrain Model' },
    { label: 'Contours', path: task.contour_path, icon: FileCode, href: '/tools/contour-generator', desc: 'Contour lines (GeoJSON)' },
  ].filter(o => o.path)

  if (outputs.length === 0) return null

  return (
    <div className="rounded-2xl border border-emerald-500/20 bg-emerald-500/5 p-6">
      <div className="flex items-center gap-3 mb-4">
        <CheckCircle2 className="w-5 h-5 text-emerald-400" />
        <h2 className="text-lg font-bold text-[var(--text-primary)]">3. Import Results</h2>
      </div>

      <p className="text-sm text-[var(--text-secondary)] mb-4">
        Processing complete. {outputs.length} output{outputs.length !== 1 ? 's' : ''} available.
        Click any result to open it in the corresponding METARDU tool.
      </p>

      <div className="grid gap-3 sm:grid-cols-2">
        {outputs.map(output => {
          const Icon = output.icon
          return (
            <Link
              key={output.label}
              href={output.href}
              className="group flex items-center gap-3 rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-3 hover:border-emerald-500/30 transition-all"
            >
              <div className="w-10 h-10 rounded-lg bg-emerald-500/10 flex items-center justify-center shrink-0">
                <Icon className="w-5 h-5 text-emerald-400" />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-semibold text-[var(--text-primary)]">{output.label}</p>
                <p className="text-[10px] text-[var(--text-muted)] truncate">{output.desc}</p>
              </div>
              <ChevronRight className="w-4 h-4 text-[var(--text-muted)] group-hover:text-emerald-400 transition-colors" />
            </Link>
          )
        })}
      </div>
    </div>
  )
}

// ─── Task History ───────────────────────────────────────────────────────────

function TaskHistory({ refreshKey }: { refreshKey: number }) {
  const [tasks, setTasks] = useState<DroneTask[]>([])

  useEffect(() => {
    fetch('/api/drone/tasks?limit=10')
      .then(r => r.ok ? r.json() : null)
      .then((data: { tasks?: DroneTask[] } | null) => { if (data?.tasks) setTasks(data.tasks) })
  }, [refreshKey])

  if (tasks.length === 0) return null

  return (
    <div className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-card)] p-6">
      <h2 className="text-lg font-bold text-[var(--text-primary)] mb-4">Recent Drone Surveys</h2>
      <div className="space-y-2">
        {tasks.map(task => (
          <div
            key={task.id}
            className="flex items-center justify-between rounded-lg border border-[var(--border-color)] p-3 hover:bg-[var(--bg-tertiary)] transition-colors"
          >
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-[var(--text-primary)] truncate">{task.name}</p>
              <p className="text-xs text-[var(--text-muted)]">
                {task.photo_count} photos · {Math.round(task.total_size_mb)}MB · {new Date(task.created_at).toLocaleDateString()}
              </p>
            </div>
            <div className="flex items-center gap-2">
              {task.status === 'completed' && <CheckCircle2 className="w-4 h-4 text-emerald-400" />}
              {task.status === 'failed' && <XCircle className="w-4 h-4 text-red-400" />}
              {(task.status === 'queued' || task.status === 'running') && <Loader2 className="w-4 h-4 text-amber-400 animate-spin" />}
              <span className="text-xs capitalize text-[var(--text-muted)]">{task.status}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

// ─── Main Page ──────────────────────────────────────────────────────────────

export default function DronePage() {
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null)
  const [refreshKey, setRefreshKey] = useState(0)

  return (
    <div className="max-w-4xl mx-auto px-4 py-8">
      <PageHeader
        title="Drone Photogrammetry"
        subtitle="Upload drone photos → process to orthophoto + point cloud + contours → import to METARDU tools"
        reference="WebODM integration · Orthophoto · Point Cloud · DSM/DTM · Contours"
      />

      <div className="mt-6 space-y-6">
        {/* Info banner */}
        <div className="rounded-xl bg-[var(--accent)]/10 border border-[var(--accent)]/20 p-4 text-sm text-[var(--text-secondary)]">
          <p>
            <span className="font-semibold text-[var(--accent)]">How it works:</span>{' '}
            Upload your drone photos (JPG/PNG/TIFF), then METARDU sends them to WebODM
            for photogrammetry processing. Results (orthophoto, point cloud, DSM/DTM, contours)
            are automatically downloaded and can be opened in METARDU&apos;s existing tools.
          </p>
        </div>

        {/* Step 1: Upload */}
        <UploadSection onTaskCreated={(taskId) => {
          setActiveTaskId(taskId)
          setRefreshKey(k => k + 1)
        }} />

        {/* Step 2: Process (only show if a task is active) */}
        {activeTaskId && (
          <ProcessingSection taskId={activeTaskId} />
        )}

        {/* Step 3: Results (only show if completed) */}
        {activeTaskId && (
          <ResultsSection taskId={activeTaskId} />
        )}

        {/* Task history */}
        <TaskHistory refreshKey={refreshKey} />
      </div>
    </div>
  )
}

'use client';
import { useState, useRef, useCallback } from 'react';
import { MapLayer, GeoPDFLayer, MBTilesSession } from '@/types/field';
import { parseKML, parseKMZ } from '@/lib/field/kml';
import { uploadMBTiles } from '@/lib/field/mbtiles';
import type { MapHandle } from '@/components/field/MapViewer';
import {
  ArrowLeft,
  Plus,
  Minus,
  MapPin,
  Navigation,
  Upload,
  FileText,
  Database,
  Eye,
  EyeOff,
  Download,
  X,
  ChevronLeft,
  Layers,
} from 'lucide-react';
import Link from 'next/link';
import dynamic from 'next/dynamic';

import MapViewer from '@/components/field/MapViewer';

/* ── Non-OL imports (safe to import at module level) ──────────────── */
const GeoPDFImport = dynamic(() => import('@/components/field/GeoPDFImport'), {
  ssr: false,
  loading: () => (
    <div className="p-4 text-white/50 text-sm">Loading GeoPDF importer…</div>
  ),
});

/* ================================================================== */
/*  FIELD MAP PAGE — Full-bleed map with zero-obstruction overlays      */
/* ================================================================== */

export default function FieldMapPage() {
  /* ── State ──────────────────────────────────────────────────────── */
  const mapRef = useRef<MapHandle>(null);
  const [layers, setLayers] = useState<MapLayer[]>([]);
  const [geoPDFLayers, setGeoPDFLayers] = useState<GeoPDFLayer[]>([]);
  const [mbtilesSessions, setMBTilesSessions] = useState<MBTilesSession[]>([]);
  const [mbtilesLoading, setMBTilesLoading] = useState(false);
  const [geoPDFOpen, setGeoPDFOpen] = useState(false);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [gpsActive, setGpsActive] = useState(false);
  const [gpsAccuracy, setGpsAccuracy] = useState<number | null>(null);
  const [gpsLocation, setGpsLocation] = useState<{lat: number, lng: number} | null>(null);
  const [gpsWatchId, setGpsWatchId] = useState<number | null>(null);
  const [tooltip, setTooltip] = useState<string | null>(null);
  const kmlInputRef = useRef<HTMLInputElement>(null);
  const drawerTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  /* ── KML / KMZ import handler ──────────────────────────────────── */
  const handleKMLImport = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const ext = file.name.split('.').pop()?.toLowerCase();
    try {
      let geojson: GeoJSON.FeatureCollection;
      if (ext === 'kml') geojson = await parseKML(await file.text());
      else if (ext === 'kmz') geojson = await parseKMZ(await file.arrayBuffer());
      else return;
      setLayers(prev => [...prev, {
        id: `layer_${Date.now()}`, name: file.name,
        type: ext as 'kml' | 'kmz', geojson, visible: true, loadedAt: Date.now(),
      }]);
    } catch (err) {
      alert(`Parse error: ${(err as Error).message}`);
    }
    // Reset input so same file can be re-imported
    e.target.value = '';
  }, []);

  /* ── MBTiles import handler ─────────────────────────────────────── */
  const handleMBTilesImport = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setMBTilesLoading(true);
    try {
      const session = await uploadMBTiles(file);
      setMBTilesSessions(prev => [...prev, session]);
    } catch (err) {
      alert(`MBTiles error: ${(err as Error).message}`);
    } finally {
      setMBTilesLoading(false);
    }
    e.target.value = '';
  }, []);

  /* ── GeoPDF layer ready callback ───────────────────────────────── */
  const handleGeoPDFReady = useCallback((layer: GeoPDFLayer) => {
    setGeoPDFLayers(prev => [...prev, layer]);
    setGeoPDFOpen(false);
  }, []);

  /* ── Layer visibility toggle ────────────────────────────────────── */
  const toggleLayer = useCallback((id: string) => {
    setLayers(prev => prev.map(l => l.id === id ? { ...l, visible: !l.visible } : l));
  }, []);

  /* ── Export handlers ───────────────────────────────────────────── */
  const exportKML = useCallback(() => {
    const visibleLayers = layers.filter(l => l.visible && l.geojson);
    if (visibleLayers.length === 0) { alert('No visible layers to export.'); return; }
    const geojson = visibleLayers[0].geojson!;
    const kmlContent = jsonToKML(geojson);
    const blob = new Blob([kmlContent], { type: 'application/vnd.google-earth.kml+xml' });
    downloadBlob(blob, 'metardu-export.kml');
    setDrawerOpen(false);
  }, [layers]);

  const exportCSV = useCallback(() => {
    const visibleLayers = layers.filter(l => l.visible && l.geojson);
    if (visibleLayers.length === 0) { alert('No visible layers to export.'); return; }
    const features = visibleLayers[0].geojson!.features;
    const header = 'name,latitude,longitude\n';
    const rows = features.map((f: GeoJSON.Feature) => {
      const coords = f.geometry && f.geometry.type === 'Point' ? (f.geometry as GeoJSON.Point).coordinates : null;
      const props = (f.properties || {}) as Record<string, unknown>;
      const name = String(props.name || props.Name || '');
      return coords ? `${name},${coords[1]?.toFixed(8)},${coords[0]?.toFixed(8)}` : '';
    }).join('\n');
    const blob = new Blob([header + rows], { type: 'text/csv' });
    downloadBlob(blob, 'metardu-export.csv');
    setDrawerOpen(false);
  }, [layers]);

  /* ── GPS toggle ────────────────────────────────────────────────── */
  const toggleGPS = useCallback(() => {
    if (gpsActive && gpsWatchId !== null) {
      navigator.geolocation.clearWatch(gpsWatchId);
      setGpsWatchId(null);
      setGpsActive(false);
      setGpsAccuracy(null);
      return;
    }
    if (!navigator.geolocation) { alert('Geolocation not available.'); return; }
    setGpsActive(true);
    const id = navigator.geolocation.watchPosition(
      (pos) => {
        setGpsAccuracy(pos.coords.accuracy);
        setGpsLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
      },
      () => { setGpsActive(false); setGpsAccuracy(null); setGpsLocation(null); },
      { enableHighAccuracy: true, maximumAge: 2000 },
    );
    setGpsWatchId(id);
  }, [gpsActive, gpsWatchId]);

  /* ── Cleanup GPS on unmount ───────────────────────────────────── */
  useState(() => {
    return () => {
      if (gpsWatchId !== null) navigator.geolocation.clearWatch(gpsWatchId);
    };
  });

  /* ── Tooltip helpers (accessible: hover + long-press fallback) ───── */
  const showTooltip = useCallback((label: string) => setTooltip(label), []);
  const hideTooltip = useCallback(() => setTooltip(null), []);

  /* ── Drawer open/close with safe timeout ───────────────────────── */
  const openDrawer = useCallback(() => {
    if (drawerTimeoutRef.current) clearTimeout(drawerTimeoutRef.current);
    setDrawerOpen(true);
  }, []);
  const closeDrawer = useCallback(() => {
    if (drawerTimeoutRef.current) clearTimeout(drawerTimeoutRef.current);
    drawerTimeoutRef.current = setTimeout(() => setDrawerOpen(false), 220);
  }, []);

  /* ── Render ───────────────────────────────────────────────────── */
  return (
    <div className="relative w-full overflow-hidden bg-[var(--bg-primary)]" style={{ height: '100dvh' }}>
      {/* ═══════════════════════════════════════════════════════════ */}
      {/*  MAP — FULL BLEED (absolute, no padding)                    */}
      {/* ═══════════════════════════════════════════════════════════ */}
      <div className="absolute inset-0">
        <MapViewer
          ref={mapRef}
          layers={layers}
          beacons={[]}
          parcels={[]}
          geoPDFLayers={geoPDFLayers}
          mbtilesSessions={mbtilesSessions}
          gpsLocation={gpsLocation}
          gpsAccuracy={gpsAccuracy}
        />
      </div>

      {/* ═══════════════════════════════════════════════════════════ */}
      {/*  TOP-LEFT — Project title bar (max 48px, semi-transparent)   */}
      {/* ═══════════════════════════════════════════════════════════ */}
      <div
        className="absolute top-0 left-0 z-10 flex items-center gap-2 px-3 text-white"
        style={{
          paddingTop: 'env(safe-area-inset-top, 0px)',
          height: 'calc(48px + env(safe-area-inset-top, 0px))',
          background: 'rgba(0,0,0,0.55)',
          backdropFilter: 'blur(12px)',
          WebkitBackdropFilter: 'blur(12px)',
        }}
      >
        <Link href="/field" aria-label="Back to Field Hub">
          <ArrowLeft className="w-5 h-5 text-white/80 hover:text-white transition-colors" />
        </Link>
        <span className="text-sm font-semibold truncate max-w-[200px]">Field Map</span>
      </div>

      {/* ═══════════════════════════════════════════════════════════ */}
      {/*  TOP-RIGHT — Zoom controls + Kenya reset                    */}
      {/* ═══════════════════════════════════════════════════════════ */}
      <div
        className="absolute z-10 flex flex-col items-center gap-1.5"
        style={{
          top: 'calc(16px + env(safe-area-inset-top, 0px))',
          right: 16,
        }}
      >
        {/* Zoom In */}
        <button
          onClick={() => mapRef.current?.zoomIn()}
          onMouseEnter={() => showTooltip('Zoom In')}
          onMouseLeave={hideTooltip}
          onTouchStart={() => showTooltip('Zoom In')}
          onTouchEnd={() => { hideTooltip(); }}
          className="w-12 h-12 flex items-center justify-center rounded-xl bg-slate-900 text-white hover:bg-slate-800 active:scale-95 transition-all shadow-md"
          aria-label="Zoom In"
        >
          <Plus className="w-5 h-5" />
        </button>
        {/* Zoom Out */}
        <button
          onClick={() => mapRef.current?.zoomOut()}
          onMouseEnter={() => showTooltip('Zoom Out')}
          onMouseLeave={hideTooltip}
          className="w-12 h-12 flex items-center justify-center rounded-xl bg-slate-900 text-white hover:bg-slate-800 active:scale-95 transition-all shadow-md"
          aria-label="Zoom Out"
        >
          <Minus className="w-5 h-5" />
        </button>
        {/* Kenya Reset */}
        <button
          onClick={() => mapRef.current?.resetToKenya()}
          onMouseEnter={() => showTooltip('Reset to Kenya')}
          onMouseLeave={hideTooltip}
          onTouchStart={() => showTooltip('Reset to Kenya')}
          onTouchEnd={() => { hideTooltip(); }}
          className="w-12 h-12 flex items-center justify-center rounded-xl bg-[#D17B47] text-white hover:bg-[#b06335] active:scale-95 transition-all font-bold text-xs shadow-md"
          aria-label="Reset to Kenya view"
        >
          KEN
        </button>
      </div>

      {/* ═══════════════════════════════════════════════════════════ */}
      {/*  BOTTOM-LEFT — GPS status badge                              */}
      {/* ═══════════════════════════════════════════════════════════ */}
      {gpsActive && gpsAccuracy !== null && (
        <div
          className="absolute z-10 flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-slate-900 text-white text-xs font-mono shadow-md"
          style={{
            bottom: 'calc(16px + env(safe-area-inset-bottom, 0px))',
            left: 16,
          }}
        >
          <span className="relative flex h-2 w-2">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75" />
            <span className="relative inline-flex rounded-full h-2 w-2 bg-green-400" />
          </span>
          GPS &plusmn;{gpsAccuracy.toFixed(1)}m
        </div>
      )}

      {/* ═══════════════════════════════════════════════════════════ */}
      {/*  BOTTOM-RIGHT — FAB stack: Perimeter → GPS Beacon → Import   */}
      {/* ═══════════════════════════════════════════════════════════ */}
      <div
        className="absolute z-10 flex flex-col items-center gap-3"
        style={{
          bottom: 'calc(16px + env(safe-area-inset-bottom, 0px))',
          right: 16,
        }}
      >
        {/* Perimeter Walk */}
        <button
          onClick={() => {
            /* Navigate to the walk page */
            window.location.href = '/field/walk';
          }}
          onMouseEnter={() => showTooltip('Perimeter Walk')}
          onMouseLeave={hideTooltip}
          onTouchStart={() => showTooltip('Perimeter Walk')}
          onTouchEnd={() => { hideTooltip(); }}
          className="w-12 h-12 flex items-center justify-center rounded-full bg-[#D17B47] text-white shadow-lg shadow-orange-900/30 hover:shadow-orange-800/40 active:scale-95 transition-all"
          aria-label="Perimeter Walk"
        >
          <MapPin className="w-5 h-5" />
        </button>
        {/* GPS Beacon */}
        <button
          onClick={toggleGPS}
          onMouseEnter={() => showTooltip(gpsActive ? 'Stop GPS' : 'GPS Beacon')}
          onMouseLeave={hideTooltip}
          onTouchStart={() => showTooltip(gpsActive ? 'Stop GPS' : 'GPS Beacon')}
          onTouchEnd={() => { hideTooltip(); }}
          className={`w-12 h-12 flex items-center justify-center rounded-full shadow-lg transition-all active:scale-95 ${
            gpsActive
              ? 'bg-green-600 text-white shadow-green-900/30'
              : 'bg-slate-900 text-white hover:bg-slate-800'
          }`}
          aria-label={gpsActive ? 'Stop GPS' : 'Start GPS'}
        >
          <Navigation className="w-5 h-5" />
        </button>
        {/* Import KML */}
        <button
          onClick={() => kmlInputRef.current?.click()}
          onMouseEnter={() => showTooltip('Import KML')}
          onMouseLeave={hideTooltip}
          onTouchStart={() => showTooltip('Import KML')}
          onTouchEnd={() => { hideTooltip(); }}
          className="w-12 h-12 flex items-center justify-center rounded-full bg-slate-900 text-white hover:bg-slate-800 shadow-lg active:scale-95 transition-all"
          aria-label="Import KML"
        >
          <Upload className="w-5 h-5" />
        </button>
        {/* Hidden file input for KML */}
        <input
          ref={kmlInputRef}
          type="file"
          accept=".kml,.kmz"
          className="hidden"
          onChange={handleKMLImport}
        />
      </div>

      {/* ═══════════════════════════════════════════════════════════ */}
      {/*  LEFT EDGE — Export drawer (24px tab → 240px panel)          */}
      {/* ═══════════════════════════════════════════════════════════ */}

      {/* Backdrop — only visible when drawer is open */}
      {drawerOpen && (
        <div
          className="absolute inset-0 z-20"
          style={{ backgroundColor: 'transparent' }}
          onClick={closeDrawer}
        />
      )}

      {/* Drawer panel */}
      <div
        className="absolute z-30 top-0 left-0 h-full transition-transform duration-300 ease-out"
        style={{
          transform: drawerOpen ? 'translateX(0)' : 'translateX(-240px)',
          paddingTop: 'env(safe-area-inset-top, 0px)',
          paddingBottom: 'env(safe-area-inset-bottom, 0px)',
        }}
      >
        {/* Drawer body */}
        <div
          className="h-full flex flex-col bg-slate-900 border-r border-white/[0.08] text-white"
          style={{ width: 'min(240px, 65vw)' }}
        >
          {/* Drawer header */}
          <div className="flex items-center justify-between px-3 py-2.5 border-b border-white/[0.08]">
            <span className="text-xs font-semibold uppercase tracking-wider text-white/70">Export &amp; Layers</span>
            <button
              onClick={closeDrawer}
              className="w-10 h-10 flex items-center justify-center rounded-lg text-white/50 hover:text-white hover:bg-white/[0.08] transition-colors"
              aria-label="Close drawer"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {/* Drawer content */}
          <div className="flex-1 overflow-y-auto p-3 space-y-4">
            {/* Export section */}
            <div>
              <p className="text-[10px] font-semibold text-white/40 uppercase tracking-wider mb-2">Export</p>
              <button
                onClick={exportKML}
                className="w-full flex items-center gap-2.5 px-3 py-2.5 rounded-lg bg-white/[0.04] hover:bg-white/[0.08] text-sm text-white/80 hover:text-white transition-colors"
              >
                <Download className="w-4 h-4 text-blue-400" />
                <span>Export as KML</span>
              </button>
              <button
                onClick={exportCSV}
                className="w-full flex items-center gap-2.5 px-3 py-2.5 rounded-lg bg-white/[0.04] hover:bg-white/[0.08] text-sm text-white/80 hover:text-white transition-colors mt-1"
              >
                <Download className="w-4 h-4 text-green-400" />
                <span>Export as CSV</span>
              </button>
            </div>

            {/* Import section */}
            <div>
              <p className="text-[10px] font-semibold text-white/40 uppercase tracking-wider mb-2">Import</p>
              <label className="flex items-center gap-2.5 px-3 py-2.5 rounded-lg bg-white/[0.04] hover:bg-white/[0.08] text-sm text-white/80 hover:text-white cursor-pointer transition-colors">
                <Upload className="w-4 h-4 text-orange-400" />
                <span>Import MBTiles</span>
                <input type="file" accept=".mbtiles" className="hidden" onChange={handleMBTilesImport} disabled={mbtilesLoading} />
              </label>
              <button
                onClick={() => { setGeoPDFOpen(true); setDrawerOpen(false); }}
                className="w-full flex items-center gap-2.5 px-3 py-2.5 rounded-lg bg-white/[0.04] hover:bg-white/[0.08] text-sm text-white/80 hover:text-white transition-colors mt-1"
              >
                <FileText className="w-4 h-4 text-purple-400" />
                <span>Import GeoPDF</span>
              </button>
            </div>

            {/* Layer list */}
            {layers.length > 0 && (
              <div>
                <p className="text-[10px] font-semibold text-white/40 uppercase tracking-wider mb-2">Layers ({layers.length})</p>
                <div className="space-y-1">
                  {layers.map(l => (
                    <button
                      key={l.id}
                      onClick={() => toggleLayer(l.id)}
                      className={`w-full flex items-center gap-2 px-3 py-2 rounded-lg text-xs transition-colors ${
                        l.visible
                          ? 'bg-blue-500/10 text-blue-300'
                          : 'bg-white/[0.02] text-white/40'
                      }`}
                    >
                      {l.visible ? <Eye className="w-3.5 h-3.5 flex-shrink-0" /> : <EyeOff className="w-3.5 h-3.5 flex-shrink-0" />}
                      <span className="truncate">{l.name}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* MBTiles sessions */}
            {mbtilesSessions.length > 0 && (
              <div>
                <p className="text-[10px] font-semibold text-white/40 uppercase tracking-wider mb-2">Tile Sessions</p>
                <div className="space-y-1">
                  {mbtilesSessions.map(s => (
                    <div key={s.key} className="flex items-center gap-2 px-3 py-2 rounded-lg bg-orange-500/10 text-orange-300 text-xs">
                      <Database className="w-3.5 h-3.5 flex-shrink-0" />
                      <span className="truncate">{s.name}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* GeoPDF sessions */}
            {geoPDFLayers.length > 0 && (
              <div>
                <p className="text-[10px] font-semibold text-white/40 uppercase tracking-wider mb-2">GeoPDF Layers</p>
                <div className="space-y-1">
                  {geoPDFLayers.map(g => (
                    <div key={g.id} className="flex items-center gap-2 px-3 py-2 rounded-lg bg-purple-500/10 text-purple-300 text-xs">
                      <FileText className="w-3.5 h-3.5 flex-shrink-0" />
                      <span className="truncate">{g.name}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Collapsed drawer tab — visible when drawer is closed */}
      {!drawerOpen && (
        <button
          onClick={openDrawer}
          className="absolute z-10 top-1/2 -translate-y-1/2 w-10 flex items-center justify-center rounded-r-lg bg-slate-900 hover:bg-slate-800 text-white/60 hover:text-white transition-all py-4 shadow-md"
          style={{ left: 0 }}
          aria-label="Open export drawer"
        >
          <ChevronLeft className="w-4 h-4 rotate-180" />
        </button>
      )}

      {/* ═══════════════════════════════════════════════════════════ */}
      {/*  GEOPDF PANEL — slim banner, NOT a full-width bottom sheet    */}
      {/* ═══════════════════════════════════════════════════════════ */}
      {geoPDFOpen && (
        <div
          className="absolute z-20 left-0 right-0 bg-slate-900 border-t border-white/[0.08]"
          style={{ bottom: 'env(safe-area-inset-bottom, 0px)' }}
        >
          <div className="flex items-center gap-2 px-3 py-2">
            <FileText className="w-4 h-4 text-purple-400 flex-shrink-0" />
            <span className="text-xs text-white/80 flex-1">GeoPDF Import</span>
            <button
              onClick={() => setGeoPDFOpen(false)}
              className="w-8 h-8 flex items-center justify-center rounded-lg text-white/50 hover:text-white hover:bg-white/[0.08] transition-colors"
              aria-label="Close GeoPDF import"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
          <GeoPDFImport onLayerReady={handleGeoPDFReady} />
        </div>
      )}

      {/* ═══════════════════════════════════════════════════════════ */}
      {/*  TOOLTIP — accessible, positioned near FAB stack               */}
      {/* ═══════════════════════════════════════════════════════════ */}
      {tooltip && (
        <div
          className="absolute z-40 px-2.5 py-1 rounded-lg bg-slate-900 text-white text-[10px] font-medium pointer-events-none whitespace-nowrap shadow-md"
          style={{ bottom: 'calc(200px + env(safe-area-inset-bottom, 0px))', right: 72 }}
        >
          {tooltip}
        </div>
      )}
    </div>
  );
}

/* ── Helpers ─────────────────────────────────────────────────────── */

function downloadBlob(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function jsonToKML(geojson: GeoJSON.FeatureCollection): string {
  const pts = geojson.features
    .filter((f): f is GeoJSON.Feature<GeoJSON.Point> => f.geometry?.type === 'Point')
    .map((f) => {
      const [lng, lat] = f.geometry.coordinates;
      const props = (f.properties || {}) as Record<string, unknown>;
      const name = String(props.name || props.Name || 'Point');
      return `  <Placemark><name>${escapeXml(name)}</name><Point><coordinates>${lng},${lat},0</coordinates></Point></Placemark>`;
    })
    .join('\n');

  const lines = geojson.features
    .filter((f): f is GeoJSON.Feature<GeoJSON.LineString> => f.geometry?.type === 'LineString')
    .map((f) => {
      const coords = f.geometry.coordinates.map((c: number[]) => `${c[0]},${c[1]},0`).join(' ');
      const props = (f.properties || {}) as Record<string, unknown>;
      const name = String(props.name || props.Name || 'Line');
      return `  <Placemark><name>${escapeXml(name)}</name><LineString><coordinates>${coords}</coordinates></LineString></Placemark>`;
    })
    .join('\n');

  const polys = geojson.features
    .filter((f): f is GeoJSON.Feature<GeoJSON.Polygon> => f.geometry?.type === 'Polygon')
    .map((f) => {
      const rings = f.geometry.coordinates.map(
        (ring: number[][]) => ring.map((c: number[]) => `${c[0]},${c[1]},0`).join(' ')
      ).join(' ');
      const props = (f.properties || {}) as Record<string, unknown>;
      const name = String(props.name || props.Name || 'Polygon');
      return `  <Placemark><name>${escapeXml(name)}</name><Polygon><outerBoundaryIs><LinearRing><coordinates>${rings}</coordinates></LinearRing></outerBoundaryIs></Polygon></Placemark>`;
    })
    .join('\n');

  return `<?xml version="1.0" encoding="UTF-8"?>
<kml xmlns="http://www.opengis.net/kml/2.2">
<Document>
  <name>Metardu Export</name>
${pts}${lines}${polys}
</Document>
</kml>`;
}

function escapeXml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

'use client';

import { useState, useEffect, useCallback, useMemo } from 'react'
import { createClient } from '@/lib/api-client/client'
import dynamic from 'next/dynamic'
// ponytail: lazy-load instrument connection panel (heavy component with Web Serial API)
const InstrumentConnectionPanel = dynamic(() => import('@/components/InstrumentConnectionPanel').then(m => ({ default: m.InstrumentConnectionPanel })), {
  ssr: false,
  loading: () => <div className='text-xs text-gray-500'>Loading instrument panel...</div>,
})
import { useRouter } from 'next/navigation'
import { useLanguage } from '@/lib/i18n/LanguageContext'
import {
  MapPin,
  RefreshCw,
  Scale,
  Radio,
  X,
  Plus,
  CheckCircle2,
  Upload,
  LucideIcon,
} from 'lucide-react'
import { FieldBookMobile } from '@/components/fieldbook/FieldBookMobile'
import { ToleranceBadge } from '@/components/survey/ToleranceBadge'
import { checkTolerance, type ToleranceCheckResult, type SurveyType } from '@/lib/survey/liveToleranceChecker'
import type { RawObservation } from '@/lib/computations/traverseEngine'
import { logger } from '@/lib/logger'

type Tab = 'points' | 'traverse' | 'leveling' | 'radiation' | 'offline' | 'map'
type SyncStatus = 'synced' | 'pending' | 'offline'

const STORAGE_KEY = 'metardu_pending_observations'

interface FieldProject { id: string; name: string; survey_type?: string }
interface FieldPoint { id?: string; name: string; easting: number; northing: number; is_control?: boolean }
interface BatchResult { name: string; easting: number | string; northing: number | string; elevation?: number | null; is_control?: boolean }
interface FieldTraverseLeg { id: string; fromStation: string; toStation: string; distance: number; bearing: { deg: number; min: number; sec: number } }
interface LevelReading { id: string; station: string; bs?: number; is?: number; fs?: number }
interface RadiationPoint { id: string; pointName: string; bearing: { deg: string; min: string; sec: string }; distance: number }

export default function FieldPage() {
  const router = useRouter()
  const { t } = useLanguage()
  const [msg, setMsg] = useState<string | null>(null)
  const [activeTab, setActiveTab] = useState<Tab>('traverse')
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('offline')
  const [projects, setProjects] = useState<FieldProject[]>([])
  const [selectedProject, setSelectedProject] = useState<string>('')
  const [loading, setLoading] = useState(true)
  const [user, setUser] = useState<{ id: string } | null>(null)
  
  // Points state
  const [points, setPoints] = useState<FieldPoint[]>([])
  const [showBatch, setShowBatch] = useState(false)
  const [batchCSV, setBatchCSV] = useState('')
  const [batchParseResults, setBatchParseResults] = useState<BatchResult[]>([])
  const [batchErrors, setBatchErrors] = useState<string[]>([])

  // Single point form
  const [pName, setPName] = useState('')
  const [pE, setPE] = useState('')
  const [pN, setPN] = useState('')
  const [pZ, setPZ] = useState('')
  const [pCtrl, setPCtrl] = useState(false)

  // Traverse state
  const [tStation, setTStation] = useState('')
  const [tDist, setTDist] = useState('')
  const [tDeg, setTDeg] = useState('')
  const [tMin, setTMin] = useState('')
  const [tSec, setTSec] = useState('')
  const [tLegs, setTLegs] = useState<FieldTraverseLeg[]>([])
  const [tTotal, setTTotal] = useState(0)

  // Tolerance check state (Phase 1 — live field-side closure checking)
  const [toleranceResult, setToleranceResult] = useState<ToleranceCheckResult | null>(null)

  // Leveling state
  const [lStation, setLStation] = useState('')
  const [lReading, setLReading] = useState('')
  const [lType, setLType] = useState<'BS' | 'IS' | 'FS'>('BS')
  const [lReadings, setLReadings] = useState<LevelReading[]>([])

  // Radiation state
  const [rStation, setRStation] = useState('')
  const [rInstH, setRInstH] = useState('1.500')
  const [rPoints, setRPoints] = useState<RadiationPoint[]>([])
  const [rNewName, setRNewName] = useState('')
  const [rBearingDeg, setRBearingDeg] = useState('')
  const [rBearingMin, setRBearingMin] = useState('')
  const [rBearingSec, setRBearingSec] = useState('')
  const [rDist, setRDist] = useState('')

  // AUDIT FIX (H-007, 2026-07-27): useMemo prevents infinite loop.
  const dbClient = useMemo(() => createClient(), [])

  const fetchProjects = useCallback(async (userId: string) => {
    const { data } = (await dbClient
      .from('projects')
      .select('id, name, survey_type')
      .eq('user_id', userId)
      .order('created_at', { ascending: false })) as { data: FieldProject[] | null; error: unknown }
    if (data) setProjects(data)
    if (data) setProjects(data)
  }, [dbClient])

  const fetchProjectPoints = useCallback(async (projectId: string) => {
    if (!projectId) return
    const { data } = (await dbClient
      .from('survey_points')
      .select('*')
      .eq('project_id', projectId)
      .order('created_at', { ascending: false })) as { data: FieldPoint[] | null; error: unknown }
    if (data) setPoints(data)
  }, [dbClient])

  // Auth check
  useEffect(() => {
    const checkAuth = async () => {
      const authRes = await dbClient.auth.getSession()
      const session = authRes.data?.session
      const user = (session as unknown as { user?: { id: string } } | null)?.user
      if (!user) {
        window.location.replace('/login?next=%2Ffield')
        return
      }
      setUser(user as { id: string })
      setLoading(false)
      fetchProjects((user as { id: string }).id)
      fetchProjectPoints(selectedProject)
    }
    checkAuth()
  }, [router, dbClient, selectedProject, fetchProjects, fetchProjectPoints])

  useEffect(() => {
    if (!user) return
    
    const subRes = dbClient.auth.onAuthStateChange((_event, session) => {
      if (!session) {
        setUser(null)
        window.location.replace('/login?next=%2Ffield')
      } else {
        setUser((session as Record<string, unknown>).user as { id: string } | null)
      }
    })
    return () => subRes.data.subscription.unsubscribe()
  }, [user, dbClient, router])

  // Point batch parser
  const parseBatchCSV = () => {
    const lines = batchCSV.trim().split('\n')
    const results: BatchResult[] = []
    const errors: string[] = []
    let lineNum = 0

    for (const line of lines) {
      lineNum++
      const parts = line.split(',').map((p) => p.trim())
      if (parts.length < 3) {
        errors.push(`Line ${lineNum}: Need at least 3 columns`)
        continue
      }

      const [name, easting, northing, elevation] = parts
      const e = parseFloat(easting)
      const n = parseFloat(northing)
      const z = elevation ? parseFloat(elevation) : null

      if (isNaN(e) || e < 100000 || e > 900000) {
        errors.push(`Line ${lineNum}: Invalid easting`)
        continue
      }
      if (isNaN(n) || n < 0) {
        errors.push(`Line ${lineNum}: Invalid northing`)
        continue
      }

      results.push({
        name: name.trim() || `PT${results.length + 1}`,
        easting: e,
        northing: n,
        elevation: z,
        is_control: false
      })
    }

    setBatchParseResults(results)
    setBatchErrors(errors)
  }

  const saveBatchPoints = async () => {
    if (!selectedProject || batchParseResults.length === 0) return

    try {
      // T1.5d FIX (2026-07-10): Map 'name' to 'point_name' (the actual DB column).
      // The local type uses 'name' for convenience, but the DB column is 'point_name'.
      await dbClient.from('survey_points').insert(
        batchParseResults.map((p) => ({
          project_id: selectedProject,
          point_name: p.name,  // T1.5d: was 'name' (column doesn't exist)
          easting: p.easting,
          northing: p.northing,
          elevation: p.elevation,
          is_control: p.is_control ?? false,
        }))
      )
      setBatchCSV('')
      setBatchParseResults([])
      setBatchErrors([])
      setShowBatch(false)
      fetchProjectPoints(selectedProject)
      setMsg(` Saved ${batchParseResults.length} points successfully`)
    } catch (e: unknown) {
      setMsg('Error: ' + (e instanceof Error ? (e as Error).message : String(e)))
    }
  }

  // Single point save
  const savePoint = async () => {
    if (!pName || !pE || !pN || !selectedProject) return

    try {
      await dbClient.from('survey_points').insert({
        point_name: pName,  // T1.5d FIX: was 'name' (column doesn't exist)
        easting: parseFloat(pE),
        northing: parseFloat(pN),
        elevation: pZ ? parseFloat(pZ) : null,
        is_control: pCtrl,
        project_id: selectedProject
      })
      setPName('')
      setPE('')
      setPN('')
      setPZ('')
      setPCtrl(false)
      fetchProjectPoints(selectedProject)
    } catch (e) {
      logger.error(e instanceof Error ? e.message : String(e))
    }
  }

  // Traverse
  const addTraverseLeg = () => {
    if (!tStation || !tDist || !tDeg) return
    const toStation = tStation
    const fromStation = tLegs.length > 0 ? tLegs[tLegs.length - 1].toStation : 'A'
    const bearing = {
      deg: parseInt(tDeg) || 0,
      min: parseInt(tMin) || 0,
      sec: parseFloat(tSec) || 0
    }

    setTLegs([...tLegs, {
      id: Date.now().toString(),
      fromStation,
      toStation,
      distance: parseFloat(tDist),
      bearing
    }])

    setTStation('')
    setTDist('')
    setTDeg('')
    setTMin('')
    setTSec('')
  }

  const traverseTotal = tLegs.reduce((sum, l) => sum + l.distance, 0)

  // Phase 1: Live tolerance check — recompute whenever traverse legs change
  useEffect(() => {
    if (tLegs.length < 3 || !selectedProject) {
      setToleranceResult(null)
      return
    }

    try {
      // Convert field page traverse legs to RawObservation format
      const observations: RawObservation[] = tLegs.map((leg) => ({
        station: leg.toStation,
        bs: leg.fromStation,
        fs: leg.toStation,
        hclDeg: String(leg.bearing.deg),
        hclMin: String(leg.bearing.min),
        hclSec: String(leg.bearing.sec),
        hcrDeg: String((leg.bearing.deg + 180) % 360),
        hcrMin: String(leg.bearing.min),
        hcrSec: String(leg.bearing.sec),
        slopeDist: String(leg.distance),
        vaDeg: '90', vaMin: '00', vaSec: '00',
        ih: '1.5', th: '1.5',
      }))

      // Get project survey type
      const project = projects.find(p => p.id === selectedProject)
      const surveyType = (project?.survey_type as string) || 'cadastral'

      // T1.5i FIX (2026-07-10): Use control points from the project for
      // opening/closing coordinates. Fall back to a loop traverse (same
      // opening = closing) if no control points are available — the closure
      // check still works, it just checks internal misclosure.
      const controlPoints = points.filter((p) => p.is_control)
      const openingPoint = controlPoints[0]
      const closingPoint = controlPoints[controlPoints.length - 1] || controlPoints[0]

      const openingE = openingPoint?.easting || 0
      const openingN = openingPoint?.northing || 0
      const closingE = closingPoint?.easting || openingE
      const closingN = closingPoint?.northing || openingN

      const result = checkTolerance({
        surveyType: surveyType as SurveyType,
        observations,
        openingEasting: openingE,
        openingNorthing: openingN,
        openingStation: tLegs[0]?.fromStation || 'A',
        closingEasting: closingE,
        closingNorthing: closingN,
        closingStation: tLegs[0]?.fromStation || 'A',
        backsightBearingDeg: tLegs[0]?.bearing?.deg || 0,
        backsightBearingMin: tLegs[0]?.bearing?.min || 0,
        backsightBearingSec: tLegs[0]?.bearing?.sec || 0,
      })
      setToleranceResult(result)
    } catch {
      // Tolerance check may fail if data is incomplete — that's OK
      setToleranceResult(null)
    }
  }, [tLegs, selectedProject, projects, points])

  const renderTabButton = (tab: Tab, Icon: LucideIcon, label: string) => (
    <button
      onClick={() => setActiveTab(tab)}
      className={`flex-1 py-2 text-xs font-medium flex flex-col items-center gap-1 ${
        activeTab === tab ? 'text-[var(--accent)]' : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]'
      }`}
    >
      <Icon className="w-5 h-5" />
      <span>{label}</span>
    </button>
  )

  const renderOfflineTabButton = (tab: Tab, Icon: LucideIcon, label: string) => (
    <button
      onClick={() => setActiveTab(tab)}
      className={`flex-1 py-2 text-xs font-medium flex flex-col items-center gap-1 ${
        activeTab === tab ? 'text-[var(--accent)]' : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]'
      }`}
    >
      <Icon className="w-5 h-5" />
      <span className="text-[10px]">{label}</span>
    </button>
  )

  const inputClass = "w-full px-3 py-2 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded text-sm text-[var(--text-primary)] focus:border-[var(--accent)] focus:outline-none"
  const inputNumberClass = `${inputClass} font-mono text-right`

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-[var(--text-secondary)] text-sm">Loading...</div>
      </div>
    )
  }

  if (!user) {
    return null
  }

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
      <header className="bg-[var(--bg-secondary)] border-b border-[var(--border-color)] p-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <h1 className="text-sm font-bold text-[var(--text-primary)]">{t('field.fieldMode')}</h1>
            <select
              value={selectedProject}
              onChange={(e) => setSelectedProject(e.target.value)}
              className="bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-2 py-1 text-xs text-[var(--text-primary)] w-36"
            >
              <option value="">Select Project</option>
              {projects.map((p) => (
                <option key={p.id} value={p.id}>{p.name}</option>
              ))}
            </select>
          </div>
          <div className="flex items-center gap-2">
            {syncStatus === 'synced' && <CheckCircle2 className="w-4 h-4 text-green-400" />}
            {syncStatus === 'pending' && <RefreshCw className="w-4 h-4 text-yellow-400 animate-spin" />}
            {syncStatus === 'offline' && <X className="w-4 h-4 text-[var(--text-muted)]" />}
          </div>
        </div>
      </header>
      {/* Instrument Connection Panel */}
      <div className="p-3 border-b border-[var(--border-color)]">
        <InstrumentConnectionPanel onImportPoints={(points) => {
          // Auto-add imported points to the field book
          setBatchParseResults(prev => [...prev, ...points.map(p => ({
            name: p.id || `P${Date.now()}`,
            easting: String(p.easting),
            northing: String(p.northing),
          }))])
        }} />
      </div>

      {/* Main */}
      <main className="flex-1 overflow-y-auto p-3 pb-20">
        <div className="mb-3 rounded-lg border border-[var(--border-color)] bg-[var(--bg-secondary)]/20 p-3">
          <div className="text-[10px] uppercase tracking-wider text-[var(--text-muted)]">Workflow</div>
          <div className="text-sm text-[var(--text-primary)] mt-1">Field Mode = quick capture (phone/tablet). Field Book = textbook tables + checks + exports.</div>
          <div className="mt-2 flex flex-wrap gap-2">
            <button
              onClick={() => router.push('/fieldbook')}
              className="text-[10px] bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] px-2 py-1.5 rounded"
            >
              Open Field Book
            </button>
            <button
              onClick={() => router.push('/field/gnss')}
              className="text-[10px] bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] px-2 py-1.5 rounded"
            >
              GNSS Receiver
            </button>
            <button
              onClick={() => router.push('/guide')}
              className="text-[10px] bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] px-2 py-1.5 rounded"
            >
              Field Guides
            </button>
            <button
              onClick={() => setActiveTab('map')}
              className="text-[10px] bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black px-2 py-1.5 rounded"
            >
              GPS Map & Collection
            </button>
          </div>
        </div>

        {activeTab === 'points' && (
          <div className="space-y-3">
            {/* Quick batch entry button */}
            <div className="flex justify-between items-center">
              <h2 className="text-xs font-semibold text-white uppercase tracking-wide">{t('field.points')}</h2>
              <button
                onClick={() => setShowBatch(!showBatch)}
                className="text-[10px] bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] px-2 py-1 rounded flex items-center gap-1"
              >
                {showBatch ? t('common.close') : <><Plus className="w-3 h-3" /> {t('field.batchCSV')}</>}
              </button>
            </div>

            {/* Batch CSV input */}
            {showBatch && (
              <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded p-3 space-y-2">
                <div>
                  <label htmlFor="field-batch-csv" className="text-[10px] text-[var(--text-muted)]">CSV: Name, Easting, Northing, Elevation (optional)</label>
                  <textarea
                    id="field-batch-csv"
                    value={batchCSV}
                    onChange={(e) => setBatchCSV(e.target.value)}
                    placeholder="PT1,500000,4500000,100&#10;PT2,500100,4500100,101"
                    className={`${inputClass} h-20 text-xs font-mono mt-1`}
                  />
                </div>
                <div className="flex gap-2">
                  <button onClick={parseBatchCSV} className="flex-1 text-[10px] bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] py-1.5 rounded">
                    {t('field.parse')}
                  </button>
                  <button onClick={saveBatchPoints} disabled={batchParseResults.length === 0} className="flex-1 text-[10px] bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black py-1.5 rounded disabled:opacity-50">
                    {t('common.save')} {batchParseResults.length}
                  </button>
                </div>
                {batchErrors.length > 0 && (
                  <div className="text-[10px] text-red-400">
                    {batchErrors.map((e, i) => <div key={`${e}-${i}`}>{e}</div>)}
                  </div>
                )}
                {batchParseResults.length > 0 && (
                  <div className="text-[10px] text-green-400">
                    Parsed {batchParseResults.length} ready
                  </div>
                )}
              </div>
            )}

            {/* Single point form */}
            <div className="grid grid-cols-2 gap-2">
              <div>
<label htmlFor="field-point-name" className="text-[10px] text-[var(--text-muted)] mb-1 block">{t('field.name')}</label>
              <input id="field-point-name" value={pName} onChange={e => setPName(e.target.value)} placeholder="P1" className={inputNumberClass} />
            </div>
            <div>
              <label htmlFor="field-point-easting" className="text-[10px] text-[var(--text-muted)] mb-1 block">{t('common.easting')}</label>
              <input id="field-point-easting" value={pE} onChange={e => setPE(e.target.value)} placeholder="500000" className={inputNumberClass} />
            </div>
            <div>
              <label htmlFor="field-point-northing" className="text-[10px] text-[var(--text-muted)] mb-1 block">{t('common.northing')}</label>
              <input id="field-point-northing" value={pN} onChange={e => setPN(e.target.value)} placeholder="4500000" className={inputNumberClass} />
            </div>
            <div>
              <label htmlFor="field-point-elevation" className="text-[10px] text-[var(--text-muted)] mb-1 block">{t('common.elevation')}</label>
              <input id="field-point-elevation" value={pZ} onChange={e => setPZ(e.target.value)} placeholder="0" className={inputNumberClass} />
            </div>
          </div>

          <div className="flex items-center justify-between py-2 px-3 bg-[var(--bg-secondary)]/50 rounded border border-[var(--border-color)]">
            <label className="text-[10px] text-[var(--text-secondary)]">{t('field.controlPoint')}</label>
              <button
                onClick={() => setPCtrl(!pCtrl)}
                className={`w-8 h-4 rounded-full relative ${pCtrl ? 'bg-[var(--accent)]' : 'bg-gray-600'}`}
              >
                <div className={`absolute top-0.5 w-3.5 h-3.5 bg-[var(--bg-card)] border border-[var(--border-color)] rounded transition-transform ${pCtrl ? 'left-4' : 'left-0.5'}`} />
              </button>
            </div>

            <button
