    answer: 'Visit /pricing to compare plans. Click "Upgrade" and complete payment via M-Pesa, card, or PayPal. Your subscription activates immediately. Admins can also promote any user via the admin dashboard.',
  },
  {
    category: 'Compliance',
    question: 'Is METARDU compliant with Kenyan survey law?',
    answer: 'Yes. METARDU follows the Survey Act (Cap 299), Land Registration Act (2012), Sectional Properties Act (2012), and Data Protection Act (2019). All document templates use official SoK formats. Traverse precision thresholds match statutory requirements (1:10,000 urban, 1:5,000 rural).',
  },
]

const CATEGORIES = ['All', 'Getting Started', 'Map', 'Fieldbook', 'Documents', 'Tools', 'Subscription', 'Compliance']

const CATEGORY_ICONS: Record<string, typeof BookOpen> = {
  'Getting Started': BookOpen,
  'Map': Map,
  'Fieldbook': FileText,
  'Documents': FileText,
  'Tools': Calculator,
  'Subscription': CreditCard,
  'Compliance': ShieldCheck,
}

export default function HelpPage() {
  const [query, setQuery] = useState('')
  const [activeCategory, setActiveCategory] = useState('All')
  const [expandedId, setExpandedId] = useState<string | null>(null)

  const filteredFaqs = useMemo(() => {
    let result = FAQS
    if (activeCategory !== 'All') {
      result = result.filter(f => f.category === activeCategory)
    }
    if (query.trim()) {
      const q = query.toLowerCase()
      result = result.filter(f =>
        f.question.toLowerCase().includes(q) ||
        f.answer.toLowerCase().includes(q)
      )
    }
    return result
  }, [query, activeCategory])

  return (
    <div className="max-w-4xl mx-auto px-4 py-8">
      {/* Header */}
      <div className="text-center mb-8">
        <div className="inline-flex items-center justify-center w-14 h-14 rounded-2xl bg-[var(--accent)]/10 mb-4">
          <BookOpen className="w-7 h-7 text-[var(--accent)]" />
        </div>
        <h1 className="text-3xl font-bold text-[var(--text-primary)]">Help & Support</h1>
        <p className="text-sm text-[var(--text-muted)] mt-2">
          Find answers, learn workflows, and get the most out of METARDU
        </p>
      </div>

      {/* Search */}
      <div className="relative mb-6">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-500" />
        <input
          type="text"
          value={query}
          onChange={e => setQuery(e.target.value)}
          aria-label="Search for help..."
          className="w-full h-12 pl-10 pr-4 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-xl text-sm text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
        />
      </div>

      {/* Category filter */}
      <div className="flex flex-wrap gap-2 mb-6">
        {CATEGORIES.map(cat => {
          const Icon = cat === 'All' ? BookOpen : CATEGORY_ICONS[cat]
          return (
            <button
              key={cat}
              onClick={() => setActiveCategory(cat)}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                activeCategory === cat
                  ? 'bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)]'
                  : 'bg-[var(--bg-tertiary)]/50 border border-[var(--border-color)] text-gray-400 hover:text-gray-300'
              }`}
            >
              {Icon && <Icon className="w-3.5 h-3.5" />}
              {cat}
            </button>
          )
        })}
      </div>

      {/* FAQ list */}
      <div className="space-y-2">
        {filteredFaqs.length === 0 ? (
          <div className="text-center py-12">
            <Search className="w-8 h-8 text-gray-600 mx-auto mb-2" />
            <p className="text-sm text-gray-500">No results found</p>
            <p className="text-xs text-gray-600 mt-1">Try a different search term or category</p>
          </div>
        ) : (
          filteredFaqs.map((faq, idx) => {
            const id = `${faq.category}-${idx}`
            const isExpanded = expandedId === id
            const Icon = CATEGORY_ICONS[faq.category] || BookOpen
            return (
              <div
                key={id}
                className="rounded-lg border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden"
              >
                <button
                  onClick={() => setExpandedId(isExpanded ? null : id)}
                  className="w-full flex items-center gap-3 px-4 py-3 hover:bg-[var(--bg-tertiary)]/50 transition-colors text-left"
                >
                  <Icon className="w-4 h-4 text-[var(--accent)] shrink-0" />
                  <span className="flex-1 text-sm font-medium text-[var(--text-primary)]">{faq.question}</span>
                  {isExpanded ? <ChevronDown className="w-4 h-4 text-gray-500" /> : <ChevronRight className="w-4 h-4 text-gray-500" />}
                </button>
                {isExpanded && (
                  <div className="px-4 pb-4 pt-1">
                    <div className="flex gap-3">
                      <div className="w-4 shrink-0" />
                      <p className="text-xs text-[var(--text-secondary)] leading-relaxed">{faq.answer}</p>
                    </div>
                  </div>
                )}
              </div>
            )
          })
        )}
      </div>

      {/* Quick links */}
      <div className="mt-12 grid grid-cols-2 md:grid-cols-4 gap-3">
        <QuickLink href="/docs" icon={BookOpen} label="Documentation" />
        <QuickLink href="/docs/quick-start" icon={Compass} label="Quick Start" />
        <QuickLink href="/docs/api" icon={FileText} label="API Reference" />
        <QuickLink href="/community" icon={MessageSquare} label="Community" />
      </div>

      {/* Contact support */}
      <div className="mt-8 rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-5">
        <h3 className="text-sm font-semibold text-[var(--text-primary)] mb-3">Still need help?</h3>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          <a href="mailto:support@metardu.com" className="flex items-center gap-2 p-3 rounded-lg bg-[var(--bg-tertiary)]/50 border border-[var(--border-color)] hover:border-[var(--accent)]/30 transition-colors">
            <Mail className="w-4 h-4 text-[var(--accent)] shrink-0" />
            <div>
              <p className="text-xs font-medium text-[var(--text-primary)]">Email Support</p>
              <p className="text-[10px] text-gray-500">support@metardu.com</p>
            </div>
          </a>
          <a href="/community" className="flex items-center gap-2 p-3 rounded-lg bg-[var(--bg-tertiary)]/50 border border-[var(--border-color)] hover:border-[var(--accent)]/30 transition-colors">
            <MessageSquare className="w-4 h-4 text-[var(--accent)] shrink-0" />
            <div>
              <p className="text-xs font-medium text-[var(--text-primary)]">Community Forum</p>
              <p className="text-[10px] text-gray-500">Ask other surveyors</p>
            </div>
          </a>
          <div className="flex items-center gap-2 p-3 rounded-lg bg-[var(--bg-tertiary)]/50 border border-[var(--border-color)]">
            <Phone className="w-4 h-4 text-gray-500 shrink-0" />
            <div>
              <p className="text-xs font-medium text-[var(--text-primary)]">Enterprise</p>
              <p className="text-[10px] text-gray-500">Priority support</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

function QuickLink({ href, icon: Icon, label }: { href: string; icon: typeof BookOpen; label: string }) {
  return (
    <Link
      href={href}
      className="flex items-center gap-2 p-3 rounded-lg border border-[var(--border-color)] bg-[var(--bg-card)] hover:border-[var(--accent)]/30 hover:bg-[var(--bg-tertiary)]/30 transition-colors"
    >
      <Icon className="w-4 h-4 text-[var(--accent)]" />
      <span className="text-xs font-medium text-[var(--text-primary)]">{label}</span>
    </Link>
  )
}

'use client';
import { useState, useCallback, useEffect } from 'react'
import { AlertTriangle } from 'lucide-react'
import { createClient } from '@/lib/api-client/client'
import { detectTotalStationFormat, TotalStationFormat } from '@/lib/import/totalStation/detectFormat'
import { parseGSI } from '@/lib/import/totalStation/parseGSI'
import { parseJobXML } from '@/lib/import/totalStation/parseJobXML'
import { parseTopcon } from '@/lib/import/totalStation/parseTopcon'
import { parseSDR } from '@/lib/import/totalStation/parseSDR'
import { logger } from '@/lib/logger'

interface ParsedPoint {
  pointId: string
  easting?: number
  northing?: number
  elevation?: number
  selected: boolean
}

interface Project {
  id: string
  name: string
}

export default function ImportPage() {
  const dbClient = createClient()
  const [file, setFile] = useState<File | null>(null)
  const [content, setContent] = useState<string>('')
  const [format, setFormat] = useState<TotalStationFormat>('unknown')
  const [points, setPoints] = useState<ParsedPoint[]>([])
  const [warnings, setWarnings] = useState<string[]>([])
  const [projects, setProjects] = useState<Project[]>([])
  const [selectedProject, setSelectedProject] = useState<string>('')
  const [importing, setImporting] = useState(false)
  const [imported, setImported] = useState<number | null>(null)
  const [loadingProjects, setLoadingProjects] = useState(true)

  useEffect(() => {
    async function loadProjects() {
      const { data: { session } } = await dbClient.auth.getSession()
      const user = session?.user
      if (!user) return

      const { data } = await dbClient
        .from('projects')
        .select('id, name')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false })
                .limit(20) as unknown as { data: Project[] | null }

      if (data) setProjects(data as Project[])
      setLoadingProjects(false)
    }
    loadProjects()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const handleFileChange = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0]
    if (!selectedFile) return

    setFile(selectedFile)
    setImported(null)

    const text = await selectedFile.text()
    setContent(text)

    const detectedFormat = detectTotalStationFormat(text, selectedFile.name)
    setFormat(detectedFormat)

    interface TotalStationRecord { pointId: string; easting?: number; northing?: number; elevation?: number }
    let parsed: { records: TotalStationRecord[]; warnings: string[] } = { records: [], warnings: [] }

    switch (detectedFormat) {
      case 'gsi':
        parsed = parseGSI(text)
        break
      case 'jobxml':
        parsed = parseJobXML(text)
        break
      case 'topcon':
        parsed = parseTopcon(text)
        break
      case 'sokkia':
        parsed = parseSDR(text)
        break
      default:
        setWarnings(['Unknown format. Please try CSV import instead.'])
        return
    }

    setWarnings(parsed.warnings || [])
    setPoints(parsed.records.map((r) => ({
      pointId: r.pointId,
      easting: r.easting,
      northing: r.northing,
      elevation: r.elevation,
      selected: true
    })))
  }, [])

  const toggleAll = (select: boolean) => {
    setPoints(points.map((p) => ({ ...p, selected: select })))
  }

  const togglePoint = (idx: number) => {
    setPoints(points.map((p, i) => i === idx ? { ...p, selected: !p.selected } : p))
  }

  const handleImport = async () => {
    if (!selectedProject) return

    setImporting(true)
    const selectedPoints = points.filter((p) => p.selected)

    const insertData = selectedPoints.map((p) => ({
      project_id: selectedProject,
      name: p.pointId,
      easting: p.easting || 0,
      northing: p.northing || 0,
      elevation: p.elevation || 0,
      is_control: false
    }))

    const { error } = await dbClient.from('survey_points').insert(insertData)

    if (error) {
      logger.error('Import error:', { error: error })
      setImporting(false)
      return
    }

    setImported(selectedPoints.length)
    setImporting(false)
  }

  const formatNames: Record<TotalStationFormat, string> = {
    gsi: 'Leica GSI',
    jobxml: 'Trimble JobXML',
    topcon: 'Topcon GTS',
    sokkia: 'Sokkia SDR',
    south: 'South NTS/Galaxy',
    csv: 'CSV',
    unknown: 'Unknown'
  }

  const selectedCount = points.filter((p) => p.selected).length
  const projectName = projects.find((p) => p.id === selectedProject)?.name

  return (
    <div className="min-h-screen py-12">
      <div className="max-w-4xl mx-auto px-6">
        <div className="mb-8 pb-5 border-b border-[var(--border-color)]">
          <div className="font-mono text-[11px] text-[var(--accent)] tracking-[0.12em] uppercase mb-2">
            Field data → Metardu
          </div>
          <h1 className="font-display text-3xl text-[var(--text-primary)] tracking-[-0.025em]">Import field data</h1>
          <p className="text-sm text-[var(--text-secondary)] mt-2">
            Import from any total station, GNSS rover, or drone software. Metardu auto-detects the format.
          </p>
        </div>

        {imported !== null ? (
          <div className="bg-[var(--success)]/10 border border-[var(--success)]/30 rounded-lg p-8 text-center">
            <div className="w-12 h-12 mx-auto mb-4 border border-[var(--success)] flex items-center justify-center">
              <svg className="w-7 h-7 text-[var(--success)]" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />
              </svg>
            </div>
            <h2 className="font-display text-2xl text-[var(--success)] tracking-[-0.02em] mb-2">
              {imported} points imported
            </h2>
            <p className="text-sm text-[var(--text-secondary)] mb-6">
              Successfully imported to {projectName}
            </p>
            <div className="flex gap-3 justify-center">
              <a
                href={`/project/${selectedProject}`}
                className="px-5 py-2.5 bg-[var(--accent)] text-[var(--bg-primary)] font-medium rounded-md hover:bg-[var(--accent-dim)] transition-colors text-sm no-underline"
              >
                Open project →
              </a>
              <button
                onClick={() => { setFile(null); setPoints([]); setImported(null); }}
                className="px-5 py-2.5 border border-[var(--border-color)] text-[var(--text-primary)] font-medium rounded-md hover:bg-[var(--bg-tertiary)] transition-colors text-sm"
              >
                Import More
              </button>
            </div>
          </div>
        ) : (
          <>
            <div className="bg-[var(--bg-card)] rounded-lg border border-[var(--border-color)] p-6 mb-8">
              <h2 className="font-display text-xl text-[var(--text-primary)] tracking-[-0.015em] mb-4">Supported formats</h2>
              <p className="text-sm text-[var(--text-secondary)] mb-4">
                Import data directly from your total station, GNSS rover, or drone processing software.
                Metardu auto-detects the format.
              </p>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                <FormatBadge color="var(--accent)" name="Leica GSI (.gsi)" />
                <FormatBadge color="var(--accent)" name="Trimble JobXML (.job, .jxl)" />
                <FormatBadge color="var(--accent)" name="Trimble RW5 (.rw5)" />
                <FormatBadge color="var(--accent)" name="Sokkia SDR (.sdr)" />
                <FormatBadge color="var(--accent)" name="Topcon GTS (.gtl, .raw)" />
                <FormatBadge color="var(--accent)" name="South NTS (.dat)" />
                <FormatBadge color="var(--accent)" name="CSV / TXT (.csv, .txt)" />
                <FormatBadge color="var(--accent)" name="DXF (.dxf)" />
                <FormatBadge color="var(--accent)" name="GeoJSON (.geojson)" />
                <FormatBadge color="var(--accent)" name="KML (.kml)" />
                <FormatBadge color="var(--accent)" name="XYZ Point Cloud (.xyz)" />
                <FormatBadge color="var(--accent)" name="LAS / LAZ (.las, .laz)" />
                <FormatBadge color="var(--accent)" name="RINEX (.rnx, .obs)" />
                <FormatBadge color="var(--accent)" name="Pix4D (.p4d)" />
                <FormatBadge color="var(--accent)" name="PLY Mesh (.ply)" />
                <FormatBadge color="var(--accent)" name="XML (.xml)" />
              </div>

              <div className="mt-8">
                <label htmlFor="import-file" className="block">
                  <div aria-label="Drop your file here or click to browse" className="border-2 border-dashed border-[var(--border-hover)] rounded-lg p-12 text-center cursor-pointer hover:border-[var(--accent)] transition-colors">
                    <div className="font-mono text-[10px] text-[var(--text-muted)] tracking-[0.1em] uppercase mb-4">
                      {file ? file.name : 'Drop your file here or click to browse'}
                    </div>
                    <p className="text-sm text-[var(--text-secondary)] font-mono">
                      .gsi · .job · .jxl · .rw5 · .sdr · .csv · .txt · .dxf · .geojson · .kml · .xyz · .las · .laz · .rnx · .p4d · .ply · .xml
                    </p>
                  </div>
                  <input
                    id="import-file"
                    type="file"
                    accept=".gsi,.job,.jxl,.rw5,.sdr,.gtl,.raw,.dat,.csv,.txt,.dxf,.geojson,.json,.kml,.xyz,.las,.laz,.rnx,.obs,.p4d,.ply,.xml"
                    onChange={handleFileChange}
                    className="hidden"
                  />
                </label>
              </div>
            </div>

            {format !== 'unknown' && points.length > 0 && (
              <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6 mb-8">
                <div className="flex items-center justify-between mb-4">
                  <div>
                    <h3 className="text-[var(--text-primary)] font-semibold">
                      Format detected: {formatNames[format]}
                    </h3>
                    <p className="text-[var(--text-secondary)] text-sm">
                      {points.length} points found
                    </p>
                  </div>
                  <div className="flex gap-2">
                    <button
                      onClick={() => toggleAll(true)}
                      className="text-sm text-amber-500 hover:underline"
                    >
                      Select All
                    </button>
                    <button
                      onClick={() => toggleAll(false)}
                      className="text-sm text-[var(--text-secondary)] hover:text-[var(--text-primary)]"
                    >
                      Deselect All
                    </button>
                  </div>
                </div>

                {warnings.length > 0 && (
                  <div className="bg-amber-900/20 border border-amber-500/50 rounded p-3 mb-4">
                    {warnings.map((w, i) => (
                      <p key={`${w}-${i}`} className="text-amber-400 text-sm"><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> {w}</p>
                    ))}
                  </div>
                )}

                <div className="max-h-64 overflow-y-auto space-y-2 mb-6">
                  {points.map((p, i) => (
                    <div
                      key={`${p}-${i}`}
                      onClick={() => togglePoint(i)}
                      className={`flex items-center gap-3 p-2 rounded cursor-pointer ${
                        p.selected ? 'bg-amber-500/10' : 'bg-[var(--bg-card)]'
                      }`}
                    >
                      <input aria-label="Selected"
                        type="checkbox"
                        checked={p.selected}
                        onChange={() => togglePoint(i)}
                        className="accent-amber-500"
                      />
                      <span className="text-[var(--text-primary)] font-mono text-sm w-16">{p.pointId}</span>
                      {p.easting !== undefined ? (
                        <span className="text-[var(--text-secondary)] text-xs">
                          E: {p.easting.toFixed(4)} N: {p.northing?.toFixed(4)} Z: {p.elevation?.toFixed(3)}
                        </span>
                      ) : (
                        <span className="text-red-400 text-xs">No coordinates</span>
                      )}
                    </div>
                  ))}
                </div>

                <div className="mb-6">
                  <label htmlFor="import-project" className="block text-sm text-[var(--text-secondary)] mb-2">
                    Import to project:
                  </label>
                  <select
                    id="import-project"
                    value={selectedProject}
                    onChange={(e) => setSelectedProject(e.target.value)}
                    className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-4 py-2 text-[var(--text-primary)]"
                  >
                    <option value="">Select a project...</option>
                    {projects.map((proj) => (
                      <option key={proj.id} value={proj.id}>{proj.name}</option>
                    ))}
                  </select>
                </div>

                <button
                  onClick={handleImport}
                  disabled={!selectedProject || selectedCount === 0 || importing}
                  className="w-full py-3 bg-amber-500 text-black font-bold rounded hover:bg-amber-400 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {importing ? 'Importing...' : `Import ${selectedCount} Points`}
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  )
}

function FormatBadge({ color, name }: { color: string; name: string }) {
  return (
    <div
      className="p-3 rounded-md border text-center font-mono text-xs"
      style={{
        background: `${color}15`,
        color: color,
        borderColor: `${color}40`,
      }}
    >
      {name}
    </div>
  )
}

'use client'
/**
 * CogoInfoPanel — Survey of Kenya compliant COGO readout
 *
 * Computes and displays traverse legs (bearing + distance) between
 * consecutive parcel vertices, plus total perimeter and enclosed area.
 *
 * Uses:
 *   - distanceBearing from @/lib/engine/distance (WCB 0-360°)
 *   - coordinateArea  from @/lib/engine/area    (Shoelace method)
 *   - vertexEditingVertices from MapReactContext
 *
 * SoK formatting:
 *   - Bearings in DMS  (DDD° MM' SS.SSS")
 *   - Distances in metres (3 dp)
 *   - Area in m², Ha, Acres
 */

import React, { useMemo, useState, memo } from 'react'
import { ChevronDown, ChevronUp, X, Ruler, MapPin } from 'lucide-react'
import { useMapContext } from '@/app/map/MapReactContext'
import { distanceBearing } from '@/lib/engine/distance'
import { coordinateArea } from '@/lib/engine/area'
import type { Point2D } from '@/lib/engine/types'

// ─── Types ────────────────────────────────────────────────────────────────

interface TraverseLegDisplay {
  fromIndex: number
  toIndex: number
  bearing: number
  bearingDMS: string
  quadrant: string
  distance: number
  deltaE: number
  deltaN: number
}

// ─── Computation helpers ──────────────────────────────────────────────────

function computeTraverseLegs(
  vertices: Array<{ easting: number; northing: number }>
): TraverseLegDisplay[] {
  if (vertices.length < 2) return []

  const legs: TraverseLegDisplay[] = []
  const n = vertices.length

  for (let i = 0; i < n; i++) {
    const from: Point2D = { easting: vertices[i].easting, northing: vertices[i].northing }
    const to: Point2D = {
      easting: vertices[(i + 1) % n].easting,
      northing: vertices[(i + 1) % n].northing,
    }
    const result = distanceBearing(from, to)
    legs.push({
      fromIndex: i,
      toIndex: (i + 1) % n,
      bearing: result.bearing,
      bearingDMS: result.bearingDMS,
      quadrant: result.quadrant,
      distance: result.distance,
      deltaE: result.deltaE,
      deltaN: result.deltaN,
    })
  }

  return legs
}

function computeAreaInfo(
  vertices: Array<{ easting: number; northing: number }>
) {
  const points: Point2D[] = vertices.map(v => ({
    easting: v.easting,
    northing: v.northing,
  }))
  return coordinateArea(points)
}

// ─── Component ────────────────────────────────────────────────────────────

function CogoInfoPanelInner() {
  const { vertexEditingVertices } = useMapContext()
  const [expanded, setExpanded] = useState(true)
  const [showDetails, setShowDetails] = useState(false)

  const legs = useMemo(
    () => computeTraverseLegs(vertexEditingVertices),
    [vertexEditingVertices]
  )

  const areaInfo = useMemo(
    () => computeAreaInfo(vertexEditingVertices),
    [vertexEditingVertices]
  )

  const totalDistance = useMemo(
    () => legs.reduce((sum, leg) => sum + leg.distance, 0),
    [legs]
  )

  // ── No vertices: show minimal placeholder ──
  if (vertexEditingVertices.length === 0) {
    return (
