  // ── Vertex editing hook (Tier 1) ──
  const { state: vertexEditState } = useVertexEditing({
    map: mapInstance.current,
    vertices: vertexEditingVertices,
    enabled: vertexEditingEnabled,
    onVerticesChange: setVertexEditingVertices,
    snapTolerance,
