const BLANK: Omit<InstrumentListing, 'id' | 'postedAt' | 'sold'> = {
  type: 'sale', category: 'total_station', title: '', brand: '', model: '',
  condition: 'good', year: undefined, description: '', price: 0,
  currency: 'KES', rentPeriod: undefined, location: '', country: 'Kenya',
  sellerName: '', sellerContact: '', images: [], verified: false,
}

function PostModal({ onSave, onClose, verified }: { onSave: (l: InstrumentListing) => void; onClose: () => void; verified: boolean }) {
  const [form, setForm] = useState<typeof BLANK>({ ...BLANK })
  const [err, setErr] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const f = <V,>(k: keyof typeof form, v: V) => setForm(p => ({ ...p, [k]: v }))

  const submit = async () => {
    if (!form.title.trim())         { setErr('Give the listing a title'); return }
    if (!form.brand.trim())         { setErr('Brand is required'); return }
    if (!form.model.trim())         { setErr('Model is required'); return }
    if (!form.description.trim())   { setErr('Add a description'); return }
    if (!form.price || Number(form.price) <= 0) { setErr('Set a price'); return }
    if (!form.location.trim())      { setErr('Location is required'); return }
    if (!form.sellerName.trim())    { setErr('Your name is required'); return }
    if (!form.sellerContact.trim()) { setErr('Contact details required so buyers can reach you'); return }
    setErr('')
    setSubmitting(true)
    try {
      onSave(postListing({ ...form, price: Number(form.price), verified }))
    } catch (e: unknown) {
      setErr((e as Error).message || 'Failed to save. Try removing some photos.')
      setSubmitting(false)
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 px-4">
      <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-2xl w-full max-w-xl max-h-[92vh] flex flex-col">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-[var(--border-color)]">
          <h2 className="font-semibold text-[var(--text-primary)]">Post a listing</h2>
          <button onClick={onClose} className="text-[var(--text-muted)] hover:text-[var(--text-primary)] text-xl p-1">×</button>
        </div>

        <div className="overflow-y-auto p-6 space-y-5">
          {err && <p className="text-sm text-red-400 bg-red-900/20 border border-red-700/40 rounded-lg px-3 py-2">{err}</p>}

          {/* Listing type */}
          <div>
            <div className="block text-xs text-[var(--text-muted)] mb-2">Listing type *</div>
            <div className="flex gap-2">
              {(['sale','rent','wanted'] as ListingType[]).map((t) => (
                <button key={t} onClick={() => f('type', t)}
                  className={`flex-1 py-2 rounded-lg text-sm font-medium border transition-colors ${
                    form.type === t ? typeBadge(t) : 'bg-[var(--bg-secondary)] text-[var(--text-muted)] border-[var(--border-color)]'
                  }`}>
                  {t === 'sale' ? 'Selling' : t === 'rent' ? 'For rent' : 'Wanted'}
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label htmlFor="listing-category" className="block text-xs text-[var(--text-muted)] mb-1">Category *</label>
              <select id="listing-category" value={form.category} onChange={e => f('category', e.target.value as InstrumentCategory)} className="input w-full">
                {CATEGORIES.map((c) => <option key={c.id} value={c.id}>{c.label}</option>)}
              </select>
            </div>
            <div>
              <label htmlFor="listing-condition" className="block text-xs text-[var(--text-muted)] mb-1">Condition *</label>
              <select id="listing-condition" value={form.condition} onChange={e => f('condition', e.target.value as Condition)} className="input w-full">
                {CONDITIONS.map((c) => <option key={c.id} value={c.id}>{c.label} — {c.desc}</option>)}
              </select>
            </div>
            <div>
              <label htmlFor="listing-brand" className="block text-xs text-[var(--text-muted)] mb-1">Brand *</label>
              <input id="listing-brand" value={form.brand} onChange={e => f('brand', e.target.value)} list="brand-list"
                placeholder="Leica, Trimble…" className="input w-full" />
              <datalist id="brand-list">{BRANDS.map((b) => <option key={b} value={b} />)}</datalist>
            </div>
            <div>
              <label htmlFor="listing-model" className="block text-xs text-[var(--text-muted)] mb-1">Model *</label>
              <input id="listing-model" value={form.model} onChange={e => f('model', e.target.value)}
                placeholder="TS16, S9, DNA03…" className="input w-full" />
            </div>
            <div>
              <label htmlFor="listing-year" className="block text-xs text-[var(--text-muted)] mb-1">Year of manufacture</label>
              <input id="listing-year" type="number" min={1990} max={new Date().getFullYear()}
                value={form.year || ''} onChange={e => f('year', Number(e.target.value) || undefined)}
                placeholder="e.g. 2019" className="input w-full" />
            </div>
            <div>
              <label className="block text-xs text-[var(--text-muted)] mb-1">
                {form.type === 'wanted' ? 'Max budget' : 'Price'} *
              </label>
              <div className="flex gap-2">
                <input type="number" min={0} value={form.price || ''}
                  onChange={e => f('price', e.target.value)}
 placeholder="Amount" className="input flex-1" />
                <select value={form.currency} onChange={e => f('currency', e.target.value as Currency)} className="input w-20">
                  {CURRENCIES.map((c) => <option key={c.id} value={c.id}>{c.id}</option>)}
                </select>
              </div>
            </div>
          </div>

          {form.type === 'rent' && (
            <div>
              <label htmlFor="listing-rent-period" className="block text-xs text-[var(--text-muted)] mb-1">Rent period</label>
              <select id="listing-rent-period" value={form.rentPeriod || 'day'} onChange={e => f('rentPeriod', e.target.value)} className="input w-full">
                <option value="day">Per day</option>
                <option value="week">Per week</option>
                <option value="month">Per month</option>
              </select>
            </div>
          )}

          <div>
            <label htmlFor="listing-title" className="block text-xs text-[var(--text-muted)] mb-1">Listing title *</label>
            <input id="listing-title" value={form.title} onChange={e => f('title', e.target.value)}
              placeholder="e.g. Leica TS16 Total Station — 2019, with tribrach and case"
              className="input w-full" />
          </div>

          <div>
            <label htmlFor="listing-description" className="block text-xs text-[var(--text-muted)] mb-1">Description *</label>
            <textarea id="listing-description" value={form.description} onChange={e => f('description', e.target.value)} rows={4}
              placeholder="Describe the instrument: accessories included (case, tribrach, cables, charger), reason for selling, calibration status, any faults, original box, etc."
              className="input w-full resize-none" />
          </div>

          {/* ── Image upload ── */}
          <ImagePicker
            images={form.images}
            onChange={imgs => f('images', imgs)}
          />

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label htmlFor="listing-location" className="block text-xs text-[var(--text-muted)] mb-1">Location (town) *</label>
              <input id="listing-location" value={form.location} onChange={e => f('location', e.target.value)}
                placeholder="Nairobi, Kampala…" className="input w-full" />
            </div>
            <div>
              <label htmlFor="listing-country" className="block text-xs text-[var(--text-muted)] mb-1">Country *</label>
              <select id="listing-country" value={form.country} onChange={e => f('country', e.target.value)} className="input w-full">
                {COUNTRIES.map((c) => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
            <div>
              <label htmlFor="listing-seller-name" className="block text-xs text-[var(--text-muted)] mb-1">Your name *</label>
              <input id="listing-seller-name" value={form.sellerName} onChange={e => f('sellerName', e.target.value)}
                placeholder="Your name or company" className="input w-full" />
            </div>
            <div>
              <label htmlFor="listing-seller-contact" className="block text-xs text-[var(--text-muted)] mb-1">Contact (phone / email) *</label>
              <input id="listing-seller-contact" value={form.sellerContact} onChange={e => f('sellerContact', e.target.value)}
                placeholder="+254712345678" className="input w-full" />
            </div>
          </div>
        </div>

        <div className="flex gap-3 px-6 pb-5 pt-2 border-t border-[var(--border-color)]">
          <button onClick={onClose} className="btn btn-secondary flex-1">Cancel</button>
          <button onClick={submit} disabled={submitting} className="btn btn-primary flex-1">
            {submitting ? 'Saving…' : form.type === 'wanted' ? 'Post wanted ad' : 'Post listing'}
          </button>
        </div>
      </div>
    </div>
  )
}

// ── Listing detail drawer ─────────────────────────────────────────────────────

function ListingDetail({ listing, onClose, onRefresh }: {
  listing: InstrumentListing; onClose: () => void; onRefresh: () => void
}) {
  const [inquiries, setInquiries] = useState(getInquiriesFor(listing.id))
  const [showForm, setShowForm] = useState(false)
  const [sent, setSent] = useState(false)
  const [iqErr, setIqErr] = useState('')
  const [form, setForm] = useState({ buyerName: '', buyerContact: '', message: '' })
  const fq = (k: keyof typeof form, v: string) => setForm(p => ({ ...p, [k]: v }))

  // Close the detail drawer on Escape (document-level, works regardless of focus)
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose() }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [onClose])

  const catLabel  = CATEGORIES.find((c) => c.id === listing.category)?.label  ?? listing.category
  const condLabel = CONDITIONS.find((c) => c.id === listing.condition)?.label ?? listing.condition

  const submit = () => {
    if (!form.buyerName)      { setIqErr('Your name is required');    return }
    if (!form.buyerContact)   { setIqErr('Your contact is required'); return }
    if (!form.message.trim()) { setIqErr('Write a message to the seller'); return }
    sendInquiry({ listingId: listing.id, ...form })
    setSent(true)
    setInquiries(getInquiriesFor(listing.id))
  }

  return (
    <div className="fixed inset-0 z-40 flex">
      <button type="button" aria-label="Close dialog" tabIndex={-1} className="flex-1 cursor-pointer border-0 p-0" onClick={onClose} />
      <div
        className="w-full max-w-md bg-[var(--bg-card)] border-l border-[var(--border-color)] h-full overflow-y-auto shadow-2xl"
        role="dialog"
        aria-modal="true"
        aria-label={listing.title}
      >
        {/* Sticky header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-[var(--border-color)] sticky top-0 bg-[var(--bg-card)] z-10">
          <div className="min-w-0">
            <h2 className="font-semibold text-[var(--text-primary)] leading-snug text-sm truncate">{listing.title}</h2>
            <p className="text-xs text-[var(--text-muted)] mt-0.5">{catLabel} · {listing.location}, {listing.country}</p>
          </div>
          <button onClick={onClose} className="text-[var(--text-muted)] hover:text-[var(--text-primary)] p-1 ml-3 flex-shrink-0">×</button>
        </div>

        <div className="p-5 space-y-5">

          {/* ── Photo gallery ── */}
          <ImageGallery images={listing.images} />

          {/* Price + badges */}
          <div className="flex items-baseline justify-between">
            <span className="text-2xl font-bold text-[var(--accent)]">
              {fmtPrice(listing.price, listing.currency, listing.type === 'rent' ? listing.rentPeriod : undefined)}
            </span>
            <div className="flex gap-2 flex-wrap justify-end">
              <span className={`text-xs px-2 py-0.5 rounded-full border ${typeBadge(listing.type)}`}>{typeLabel(listing.type)}</span>
              <span className={`text-xs px-2 py-0.5 rounded-full border ${condBadge(listing.condition)}`}>{condLabel}</span>
            </div>
          </div>

          {/* Details grid */}
          <div className="grid grid-cols-2 gap-3 text-sm">
            {([
              ['Brand',    listing.brand],
              ['Model',    listing.model],
              ['Category', catLabel],
              ['Year',     listing.year ? String(listing.year) : '—'],
              ['Location', `${listing.location}, ${listing.country}`],
              ['Posted',   relTime(listing.postedAt)],
            ] as [string,string][]).map(([k, v]) => (
              <div key={k}>
                <p className="text-[10px] uppercase tracking-wider text-[var(--text-muted)]">{k}</p>
                <p className="text-[var(--text-primary)] mt-0.5">{v}</p>
              </div>
            ))}
          </div>

          {/* Description */}
          <div>
            <p className="text-xs uppercase tracking-wider text-[var(--text-muted)] mb-2">Description</p>
            <p className="text-sm text-[var(--text-secondary)] leading-relaxed whitespace-pre-wrap">
              {listing.description || 'No description provided.'}
            </p>
          </div>

          {/* Seller */}
          <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-4">
            <p className="text-xs uppercase tracking-wider text-[var(--text-muted)] mb-2">
              {listing.type === 'wanted' ? 'Posted by' : 'Seller'}
            </p>
            <div className="flex items-center gap-2 flex-wrap">
              <p className="text-sm font-medium text-[var(--text-primary)]">{listing.sellerName}</p>
              {listing.verified && <VerifiedBadge />}
            </div>
            <p className="text-sm text-[var(--accent)] mt-0.5">{listing.sellerContact}</p>
          </div>

          {/* Contact form */}
          {!sent && !showForm && (
            <button onClick={() => setShowForm(true)} className="btn btn-primary w-full">
              {listing.type === 'wanted' ? 'I have this instrument' : 'Contact seller'}
            </button>
          )}
          {sent && (
            <div className="bg-green-900/20 border border-green-700/30 rounded-xl p-4 text-center">
              <p className="text-green-400 font-semibold text-sm">Message sent</p>
              <p className="text-xs text-green-500 mt-1">
                The {listing.type === 'wanted' ? 'buyer' : 'seller'} will contact you at the details you provided.
              </p>
            </div>
          )}
          {showForm && !sent && (
            <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-4 space-y-3">
              <h3 className="text-sm font-semibold text-[var(--text-primary)]">
                {listing.type === 'wanted' ? 'Offer your instrument' : 'Send message to seller'}
              </h3>
              {iqErr && <p className="text-xs text-red-400">{iqErr}</p>}
              <div>
                <label htmlFor="inquiry-name" className="block text-xs text-[var(--text-muted)] mb-1">Your name *</label>
                <input id="inquiry-name" value={form.buyerName} onChange={e => fq('buyerName', e.target.value)}
                  placeholder="Your full name" className="input w-full text-sm py-1.5" />
              </div>
              <div>
                <label htmlFor="inquiry-contact" className="block text-xs text-[var(--text-muted)] mb-1">Your contact *</label>
                <input id="inquiry-contact" value={form.buyerContact} onChange={e => fq('buyerContact', e.target.value)}
                  placeholder="+254712345678 or email" className="input w-full text-sm py-1.5" />
              </div>
              <div>
                <label htmlFor="inquiry-message" className="block text-xs text-[var(--text-muted)] mb-1">Message *</label>
                <textarea id="inquiry-message" value={form.message} onChange={e => fq('message', e.target.value)} rows={3}
                  placeholder={listing.type === 'wanted'
                    ? 'Describe your instrument — brand, model, condition, year, asking price…'
                    : 'Ask questions, propose a price, arrange to inspect the instrument…'}
                  className="input w-full resize-none text-sm" />
              </div>
              <div className="flex gap-2">
                <button onClick={() => setShowForm(false)} className="btn btn-secondary flex-1 text-sm py-2">Cancel</button>
                <button onClick={submit} className="btn btn-primary flex-1 text-sm py-2">Send</button>
              </div>
            </div>
          )}

          {/* Inquiries received */}
          {inquiries.length > 0 && (
            <div>
              <p className="text-xs uppercase tracking-wider text-[var(--text-muted)] mb-3">
                Messages received ({inquiries.length})
              </p>
              <div className="space-y-2">
                {inquiries.map((iq) => (
                  <div key={iq.id} className="bg-[var(--bg-secondary)] rounded-lg border border-[var(--border-color)] p-3 text-sm">
                    <div className="flex justify-between items-baseline mb-1">
                      <span className="font-medium text-[var(--text-primary)]">{iq.buyerName}</span>
                      <span className="text-xs text-[var(--text-muted)]">{relTime(iq.sentAt)}</span>
                    </div>
                    <p className="text-xs text-[var(--accent)] mb-1">{iq.buyerContact}</p>
                    <p className="text-xs text-[var(--text-secondary)] leading-relaxed">{iq.message}</p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

// ── Listing card ─────────────────────────────────────────────────────────────

function ListingCard({ listing, onClick }: { listing: InstrumentListing; onClick: () => void }) {
  const catLabel  = CATEGORIES.find((c) => c.id === listing.category)?.label  ?? listing.category
  const condLabel = CONDITIONS.find((c) => c.id === listing.condition)?.label ?? listing.condition
  const cover     = listing.images[0]

  return (
    <div role="button" tabIndex={0} onClick={onClick}
      onKeyDown={(e) => { if (e.key === 'Enter') onClick() }}
      className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl overflow-hidden hover:border-[var(--accent)]/30 transition-colors cursor-pointer group">

      {/* Cover photo or placeholder */}
      <div className="h-44 bg-[var(--bg-secondary)] overflow-hidden relative flex-shrink-0">
        {cover ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img src={cover} alt={listing.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300" loading="lazy" decoding="async" />
        ) : (
          <div className="w-full h-full flex items-center justify-center">
            <svg className="w-10 h-10 text-[var(--border-color)]" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M2.25 15.75l5.159-5.159a2.25 2.25 0 013.182 0l5.159 5.159m-1.5-1.5l1.409-1.409a2.25 2.25 0 013.182 0l2.909 2.909m-18 3.75h16.5a1.5 1.5 0 001.5-1.5V6a1.5 1.5 0 00-1.5-1.5H3.75A1.5 1.5 0 002.25 6v12a1.5 1.5 0 001.5 1.5zm10.5-11.25h.008v.008h-.008V8.25zm.375 0a.375.375 0 11-.75 0 .375.375 0 01.75 0z" />
            </svg>
          </div>
        )}
        {/* Photo count badge */}
        {listing.images.length > 1 && (
          <div className="absolute bottom-2 right-2 bg-black/60 text-white text-[10px] px-2 py-0.5 rounded-full flex items-center gap-1">
            <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M2.25 15.75l5.159-5.159a2.25 2.25 0 013.182 0l5.159 5.159m-1.5-1.5l1.409-1.409a2.25 2.25 0 013.182 0l2.909 2.909M3.75 21h16.5M16.5 3.75h.008v.008h-.008V3.75z" /></svg>
            {listing.images.length}
          </div>
        )}
        {/* Type badge overlay */}
        <div className={`absolute top-2 left-2 text-[10px] px-2 py-0.5 rounded-full border font-medium ${typeBadge(listing.type)}`}>
          {typeLabel(listing.type)}
        </div>
      </div>

      <div className="p-4">
        <div className="flex items-start gap-2 mb-2">
          <h3 className="font-semibold text-[var(--text-primary)] leading-snug group-hover:text-[var(--accent)] transition-colors text-sm flex-1">
            {listing.title}
          </h3>
          <span className={`text-[10px] px-1.5 py-0.5 rounded border flex-shrink-0 ${condBadge(listing.condition)}`}>
            {condLabel}
          </span>
        </div>

        <p className="text-xs text-[var(--text-muted)] mb-3">
          {catLabel} · {listing.location}, {listing.country}
        </p>

        {listing.description && (
          <p className="text-xs text-[var(--text-secondary)] line-clamp-2 mb-3 leading-relaxed">
            {listing.description}
          </p>
        )}

        <div className="flex items-center justify-between pt-3 border-t border-[var(--border-color)]">
          <span className="text-base font-bold text-[var(--accent)]">
            {fmtPrice(listing.price, listing.currency, listing.type === 'rent' ? listing.rentPeriod : undefined)}
          </span>
          <div className="text-right">
            <div className="flex items-center gap-1 justify-end">
              {listing.verified && <VerifiedBadge small />}
              <p className="text-xs text-[var(--text-muted)]">{listing.sellerName}</p>
            </div>
            <p className="text-[10px] text-[var(--text-muted)]">{relTime(listing.postedAt)}</p>
          </div>
        </div>
      </div>
    </div>
  )
}

// ── Main page ─────────────────────────────────────────────────────────────────

export default function MarketplacePage() {
  const { plan, isAdmin, isTrialing, loading: subLoading } = useSubscription()
  const isPro = isAdmin || plan === 'pro' || plan === 'team' || plan === 'firm' || plan === 'enterprise' || isTrialing

  const [listings, setListings]       = useState<InstrumentListing[]>([])
  const [search, setSearch]           = useState('')
  const [filterType, setFilterType]   = useState<'' | ListingType>('sale')
  const [filterCat, setFilterCat]     = useState<'' | InstrumentCategory>('')
  const [filterCountry, setFilterCountry] = useState('')
  const [showPost, setShowPost]       = useState(false)
  const [showUpgrade, setShowUpgrade] = useState(false)
  const [active, setActive]           = useState<InstrumentListing | null>(null)

  const reload = useCallback(() => {
    if (search.trim()) {
      setListings(searchListings(search))
    } else {
      setListings(getListings({
        type: filterType || undefined,
        category: filterCat || undefined,
        country: filterCountry || undefined,
      }))
    }
  }, [search, filterType, filterCat, filterCountry])

  useEffect(() => { reload() }, [reload])

  const counts = {
    sale:   getListings({ type: 'sale'   }).length,
    rent:   getListings({ type: 'rent'   }).length,
    wanted: getListings({ type: 'wanted' }).length,
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)]">
      <div className="max-w-6xl mx-auto px-4 py-8">

        {/* Header */}
        <div className="flex items-start justify-between mb-8">
          <div>
            <h1 className="text-2xl font-bold text-[var(--text-primary)]">Equipment marketplace</h1>
            <p className="text-sm text-[var(--text-muted)] mt-1">
              Buy, sell and rent survey instruments — directly between surveyors.
            </p>
          </div>
          <button
            onClick={() => isPro ? setShowPost(true) : setShowUpgrade(true)}
            className="btn btn-primary flex-shrink-0 flex items-center gap-2"
          >
            {!isPro && !subLoading && (
              <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M16.5 10.5V6.75a4.5 4.5 0 10-9 0v3.75m-.75 11.25h10.5a2.25 2.25 0 002.25-2.25v-6.75a2.25 2.25 0 00-2.25-2.25H6.75a2.25 2.25 0 00-2.25 2.25v6.75a2.25 2.25 0 002.25 2.25z" />
              </svg>
            )}
            + Post listing
          </button>
        </div>

        {/* Type tabs */}
        <div className="flex gap-2 mb-5 flex-wrap">
          {([
            { key: '',       label: 'All',        count: counts.sale + counts.rent + counts.wanted },
            { key: 'sale',   label: 'For sale',   count: counts.sale },
            { key: 'rent',   label: 'For rent',   count: counts.rent },
            { key: 'wanted', label: 'Wanted',     count: counts.wanted },
          ] as const).map(({ key, label, count }) => (
            <button key={key} onClick={() => setFilterType(key as ListingType)}
              className={`px-4 py-1.5 rounded-full text-sm font-medium transition-colors border ${
                filterType === key
                  ? 'bg-[var(--accent)] text-black border-[var(--accent)]'
                  : 'bg-[var(--bg-secondary)] text-[var(--text-muted)] border-[var(--border-color)] hover:border-[var(--accent)]/40'
              }`}>
              {label}{count > 0 && <span className="ml-1.5 text-xs opacity-70">({count})</span>}
            </button>
          ))}
        </div>

        {/* Filters */}
        <div className="flex flex-wrap gap-2 mb-6">
          <input value={search} onChange={e => setSearch(e.target.value)}
            aria-label="Search by brand, model, location…"
            className="bg-[var(--bg-secondary)] border border-[var(--border-color)] text-[var(--text-primary)] rounded-lg px-3 py-2 text-sm flex-1 min-w-48 focus:outline-none focus:border-[var(--accent)]" />
          <select value={filterCat} onChange={e => setFilterCat(e.target.value as InstrumentCategory)}
            className="bg-[var(--bg-secondary)] border border-[var(--border-color)] text-[var(--text-secondary)] rounded-lg px-3 py-2 text-sm">
            <option value="">All categories</option>
            {CATEGORIES.map((c) => <option key={c.id} value={c.id}>{c.label}</option>)}
          </select>
          <select value={filterCountry} onChange={e => setFilterCountry(e.target.value)}
            className="bg-[var(--bg-secondary)] border border-[var(--border-color)] text-[var(--text-secondary)] rounded-lg px-3 py-2 text-sm">
            <option value="">All countries</option>
            {COUNTRIES.map((c) => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>

        {/* Empty state */}
        {listings.length === 0 && (
          <div className="text-center py-24 border border-dashed border-[var(--border-color)] rounded-2xl">
            <div className="w-14 h-14 rounded-xl bg-[var(--bg-secondary)] border border-[var(--border-color)] flex items-center justify-center mx-auto mb-5">
              <svg className="w-7 h-7 text-[var(--text-muted)]" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M2.25 15.75l5.159-5.159a2.25 2.25 0 013.182 0l5.159 5.159m-1.5-1.5l1.409-1.409a2.25 2.25 0 013.182 0l2.909 2.909m-18 3.75h16.5a1.5 1.5 0 001.5-1.5V6a1.5 1.5 0 00-1.5-1.5H3.75A1.5 1.5 0 002.25 6v12a1.5 1.5 0 001.5 1.5zm10.5-11.25h.008v.008h-.008V8.25zm.375 0a.375.375 0 11-.75 0 .375.375 0 01.75 0z" />
              </svg>
            </div>
            <h2 className="text-xl font-semibold text-[var(--text-primary)] mb-2">
              {search || filterCat || filterCountry ? 'No matching listings' : 'No listings yet'}
            </h2>
            <p className="text-sm text-[var(--text-muted)] mb-6 max-w-sm mx-auto">
              {search || filterCat || filterCountry
                ? 'Try adjusting your filters'
                : 'Be the first to list a survey instrument. Sell, rent out, or post a wanted ad.'}
            </p>
            {!search && !filterCat && !filterCountry && (
              <button onClick={() => isPro ? setShowPost(true) : setShowUpgrade(true)} className="btn btn-primary">Post a listing</button>
            )}
          </div>
        )}

        {/* Grid */}
        {listings.length > 0 && (
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {listings.map((l) => (
              <ListingCard key={l.id} listing={l} onClick={() => setActive(l)} />
            ))}
          </div>
        )}
      </div>

      {showUpgrade && <UpgradeToPost onClose={() => setShowUpgrade(false)} />}

      {showPost && (
        <PostModal
          verified={isPro}
          onSave={l => { reload(); setShowPost(false); setActive(l) }}
          onClose={() => setShowPost(false)}
        />
      )}

      {active && (
        <ListingDetail
          listing={listings.find((l) => l.id === active.id) ?? active}
          onClose={() => setActive(null)}
          onRefresh={reload}
        />
      )}
    </div>
  )
}

'use client';

/**
 * Mobile Field Collection Page — Upgraded
 * ═══════════════════════════════════════
 * Integrates:
 *   - UniversalMobileObservationForm (multi-survey-type entry)
 *   - GNSSConnectionPanel (BLE/Web Bluetooth instrument streaming)
 *   - BeaconPhotoCapture (evidence-chain photos with EXIF GPS)
 *   - offlineStorage + syncService (IndexedDB offline-first + auto sync)
 *   - instrumentStore (reactive instrument connection state)
 *
 * Replaces the old basic GPS-only field page with a professional
 * surveyor workflow supporting traverse, leveling, control,
 * hydrographic, and mining observations.
 */

import { Suspense, useState, useEffect, useCallback } from 'react'
import type { CapturedBeaconPhoto } from '@/components/fieldbook/BeaconPhotoCapture'
import { useSearchParams } from 'next/navigation'
import Link from 'next/link'
import {
  Bluetooth, MapPin, Ruler, Compass,
  RefreshCw, Wifi, WifiOff, Plus,
  ArrowLeft, Satellite,
} from 'lucide-react'
import { offlineStorage, type FieldObservation } from '@/lib/mobile/offlineStorage'
import { syncService } from '@/lib/mobile/syncService'
import { createClient } from '@/lib/api-client/client'
import {
  UniversalMobileObservationForm,
  type MobileSurveyType,
} from '@/components/fieldbook/UniversalMobileObservationForm'
import { GNSSConnectionPanel } from '@/components/gnss/GNSSConnectionPanel'
import { useInstrumentStore } from '@/stores/instrumentStore'
import type { NMEAPosition } from '@/lib/gnss/nmea-parser'
import { logger } from '@/lib/logger'

// ─── Survey type metadata ───────────────────────────────────────

const SURVEY_TYPES: Record<MobileSurveyType, { label: string; icon: typeof Compass; color: string }> = {
  leveling:     { label: 'Leveling',     icon: Ruler,    color: 'bg-sky-500' },
  traverse:     { label: 'Traverse',     icon: Compass,  color: 'bg-amber-500' },
  control:      { label: 'Control',      icon: MapPin,   color: 'bg-emerald-500' },
}

// ─── Main Component ─────────────────────────────────────────────

function MobileFieldContent() {
  const searchParams = useSearchParams()
  const projectId = searchParams.get('project') || ''

  // ─── State ────────────────────────────────────────────
  const [projectName, setProjectName] = useState('Unknown Project')
  const [isOnline, setIsOnline] = useState(true)
  const [isSyncing, setIsSyncing] = useState(false)
  const [pendingCount, setPendingCount] = useState(0)
  const [lastSync, setLastSync] = useState<string | null>(null)

  // Survey mode
  const [activeSurveyType, setActiveSurveyType] = useState<MobileSurveyType>('traverse')
  const [showForm, setShowForm] = useState(false)
  const [showGNSS, setShowGNSS] = useState(false)

  // Observations
  const [recentObservations, setRecentObservations] = useState<FieldObservation[]>([])

  // Instrument store
  const isConnected = useInstrumentStore((s) => s.status === 'connected' || s.status === 'streaming')

  // ─── Initialize ───────────────────────────────────────
  useEffect(() => {
    if (projectId) {
      loadProject()
      loadObservations()
      loadStats()
    }

    setIsOnline(navigator.onLine)

    const handleOnline = () => setIsOnline(true)
    const handleOffline = () => setIsOnline(false)

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    syncService.startAutoSync()

    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
      syncService.stopAutoSync()
    }
  }, [projectId])

  // ─── Data loading ─────────────────────────────────────
  const loadProject = async () => {
    try {
      const dbClient = createClient()
            const { data } = await dbClient.from('projects').select('name').eq('id', projectId).single() as unknown as { data: { name: string } | null }
      if ((data as { name?: string } | null)?.name) setProjectName((data as { name: string }).name)
    } catch {
      // Project might not exist or DB unreachable
    }
  }

  const loadObservations = async () => {
    if (!projectId) return
    const observations = await offlineStorage.getFieldObservations(projectId)
    setRecentObservations(observations.slice(-10).reverse())
  }

  const loadStats = async () => {
    const stats = await offlineStorage.getStorageStats()
    setPendingCount(stats.pendingSync)
  }

  // ─── Sync ─────────────────────────────────────────────
  const handleSync = async () => {
    if (!isOnline) return
    setIsSyncing(true)
    try {
      const { synced, failed } = await syncService.forceSync()
      setLastSync(new Date().toLocaleTimeString())
      await loadStats()
      await loadObservations()
      if (failed > 0) {
        alert(`Synced: ${synced}, Failed: ${failed}`)
      }
    } catch {
      // Sync will retry automatically
    } finally {
      setIsSyncing(false)
    }
  }

  // ─── Observation handling ─────────────────────────────
  const handleAddObservation = useCallback(async (row: Record<string, string>, _photos: CapturedBeaconPhoto[]) => {
    if (!projectId) return

    const observation: FieldObservation = {
      projectId,
      pointName: row.station || row.pointId || row.soundingId || `PT${Date.now()}`,
      observationType: activeSurveyType === 'leveling' ? 'level' : 'gps',
      northing: parseFloat(row.northing || row.easting || '0'),
      easting: parseFloat(row.easting || '0'),
      elevation: parseFloat(row.elevation || row.depth || '0') || undefined,
      latitude: undefined,
      longitude: undefined,
      accuracy: undefined,
      rodHeight: parseFloat(row.ih || row.instrumentHeight || row.th || row.targetHeight || '0') || undefined,
      notes: row.remarks || undefined,
    }

    try {
      await offlineStorage.saveFieldObservation(observation)
      await loadObservations()
      await loadStats()
    } catch (error) {
      logger.error('Save error:', { error: error })
      alert('Failed to save observation')
    }
  }, [projectId, activeSurveyType])

  // ─── Pull from instrument ─────────────────────────────
  const handlePullFromInstrument = useCallback(async (): Promise<Partial<Record<string, string>>> => {
    const latest = useInstrumentStore.getState().latestPoint
    if (!latest) return {}

    const reading: Partial<Record<string, string>> = {}
    if (latest.northing) reading.northing = latest.northing.toFixed(4)
    if (latest.easting) reading.easting = latest.easting.toFixed(4)
    if (latest.elevation !== null) reading.elevation = latest.elevation.toFixed(4)
    if (latest.latitude) reading.bearing = latest.latitude.toFixed(7)
    if (latest.longitude) reading.slopeDist = latest.longitude.toFixed(7)
    return reading
  }, [])

  // ─── GNSS position callback ───────────────────────────
  const handleGNSSPosition = useCallback((_pos: NMEAPosition) => {
    // Update instrument store via the panel — already handled inside GNSSConnectionPanel
    // This callback is for any additional side effects
  }, [])

  // ─── Render ───────────────────────────────────────────

  return (
    <div className="min-h-screen bg-gray-950 text-white flex flex-col">
      {/* Header */}
      <header className="bg-gray-900 border-b border-gray-800 px-4 py-3 flex items-center justify-between sticky top-0 z-20">
        <div className="flex items-center gap-3">
          <Link href="/dashboard" className="text-gray-400 hover:text-white">
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <div>
            <h1 className="text-base font-bold">Field Collection</h1>
            <p className="text-xs text-gray-400 truncate max-w-[180px]">{projectName}</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {/* GNSS toggle */}
          <button
            onClick={() => setShowGNSS(!showGNSS)}
            className={`p-2 rounded-lg transition-colors ${
              isConnected
                ? 'bg-green-900/40 text-green-400 ring-1 ring-green-500/30'
                : 'bg-gray-800 text-gray-400'
            }`}
            title="GNSS Connection"
          >
            <Satellite className="w-5 h-5" />
          </button>
          {/* Sync */}
          <button
            onClick={handleSync}
            disabled={isSyncing || !isOnline}
            className={`p-2 rounded-lg transition-colors ${
              isSyncing ? 'bg-blue-900/40 text-blue-400' : isOnline ? 'bg-gray-800 text-gray-400' : 'bg-red-900/40 text-red-400'
            }`}
            title="Sync"
          >
            <RefreshCw className={`w-5 h-5 ${isSyncing ? 'animate-spin' : ''}`} />
          </button>
          {/* Online status */}
          {isOnline ? (
            <Wifi className="w-5 h-5 text-green-500" />
          ) : (
            <WifiOff className="w-5 h-5 text-red-500" />
          )}
        </div>
      </header>

      {/* GNSS Panel (slide-down) */}
      {showGNSS && (
        <div className="border-b border-gray-800 bg-gray-900/50 backdrop-blur-md">
          <GNSSConnectionPanel
            onPosition={handleGNSSPosition}
            showCoordinateSystem={true}
            autoReconnect={true}
            className="border-0 rounded-none shadow-none"
          />
        </div>
      )}

      {/* Stats Bar */}
      <div className="bg-gray-900/50 px-4 py-2 flex justify-between items-center text-xs border-b border-gray-800">
        <div className="flex items-center gap-3">
          <span className="text-gray-500">
            Pending: <span className="text-yellow-400 font-mono">{pendingCount}</span>
          </span>
          {isConnected && (
            <span className="flex items-center gap-1 text-green-400">
              <span className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse" />
              Instrument connected
            </span>
          )}
        </div>
        {lastSync && (
          <span className="text-gray-600">
            Synced: {lastSync}
          </span>
        )}
      </div>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto">
        {/* Survey Type Selector */}
        <div className="p-4">
          <div className="text-xs text-gray-500 uppercase tracking-wider font-medium mb-2">Survey Type</div>
          <div className="flex gap-2 overflow-x-auto pb-1">
            {(Object.entries(SURVEY_TYPES) as [MobileSurveyType, typeof SURVEY_TYPES[MobileSurveyType]][]).map(([key, meta]) => {
              const Icon = meta.icon
              return (
                <button
                  key={key}
                  onClick={() => setActiveSurveyType(key)}
                  className={[
                    'flex items-center gap-1.5 px-4 py-2.5 rounded-xl text-sm font-medium whitespace-nowrap transition-all',
                    activeSurveyType === key
                      ? `${meta.color} text-white shadow-lg`
                      : 'bg-gray-800 text-gray-400 hover:bg-gray-750',
                  ].join(' ')}
                >
                  <Icon className="w-4 h-4" />
                  {meta.label}
                </button>
              )
            })}
          </div>
        </div>

        {/* Add Observation FAB */}
        <div className="px-4 mb-4">
          <button
            onClick={() => setShowForm(true)}
            className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-semibold text-base flex items-center justify-center gap-2 active:scale-[0.98] transition-transform shadow-lg shadow-blue-600/20"
          >
            <Plus className="w-5 h-5" />
            New {SURVEY_TYPES[activeSurveyType].label} Reading
          </button>
        </div>

        {/* Quick Instrument Read */}
        {isConnected && (
          <div className="px-4 mb-4">
            <button
              onClick={() => setShowForm(true)}
              className="w-full py-3 border border-green-500/30 bg-green-900/10 text-green-400 rounded-xl font-medium text-sm flex items-center justify-center gap-2 hover:bg-green-900/20 transition-colors"
            >
              <Bluetooth className="w-4 h-4" />
              Pull from Instrument →
            </button>
          </div>
        )}

        {/* Recent Observations */}
        {recentObservations.length > 0 && (
          <div className="px-4 pb-4">
            <div className="text-xs text-gray-500 uppercase tracking-wider font-medium mb-2">Recent Observations</div>
            <div className="space-y-1.5">
              {recentObservations.map((obs) => (
                <div
                  key={obs.id}
                  className="flex items-center justify-between py-2.5 px-3 bg-gray-900 rounded-lg border border-gray-800"
                >
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-xs font-bold ${
                      obs.observationType === 'gps'
                        ? 'bg-blue-900/40 text-blue-400'
                        : obs.observationType === 'level'
                        ? 'bg-sky-900/40 text-sky-400'
                        : 'bg-purple-900/40 text-purple-400'
                    }`}>
                      {obs.observationType === 'gps' ? 'GPS' : obs.observationType === 'level' ? 'LV' : 'TS'}
                    </div>
                    <div>
                      <p className="font-medium text-sm text-gray-200">{obs.pointName}</p>
                      <p className="text-xs text-gray-500">
                        {new Date(obs.timestamp || 0).toLocaleTimeString()}
                      </p>
                    </div>
                  </div>
                  <span className={`text-xs px-2 py-0.5 rounded-full ${
                    obs.synced
                      ? 'bg-green-900/30 text-green-400'
                      : 'bg-yellow-900/30 text-yellow-400'
                  }`}>
                    {obs.synced ? 'Synced' : 'Pending'}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Empty state */}
        {recentObservations.length === 0 && (
          <div className="px-4 py-12 text-center">
            <MapPin className="w-12 h-12 text-gray-700 mx-auto mb-3" />
            <p className="text-gray-500 text-sm">No observations yet</p>
            <p className="text-gray-600 text-xs mt-1">
              Tap &ldquo;New Reading&rdquo; to start collecting data
            </p>
          </div>
        )}
      </main>

      {/* Universal Mobile Observation Form (bottom sheet) */}
      {showForm && (
        <UniversalMobileObservationForm
          surveyType={activeSurveyType}
          stationName={recentObservations[0]?.pointName}
          onAdd={handleAddObservation}
          onClose={() => setShowForm(false)}
          lastStation={recentObservations[0]?.pointName}
          onPullInstrumentReading={isConnected ? handlePullFromInstrument : undefined}
        />
      )}
    </div>
  )
}

export default function MobileFieldPage() {
  return (
    <Suspense
      fallback={
        <div className="min-h-screen bg-gray-950 p-4 text-sm text-gray-400 flex items-center justify-center">
          <RefreshCw className="w-5 h-5 animate-spin mr-2" />
          Loading field collection…
        </div>
      }
    >
      <MobileFieldContent />
    </Suspense>
  )
}

'use client';

import { useState, useEffect } from 'react'
import { logger } from '@/lib/logger'
import { transformCoordinates, getSupportedSystems, type CoordinateSystem, type TransformResult } from '@/lib/online/coordinates'
import { calculateEDMCorrection } from '@/lib/online/weather'
import { searchBenchmarks, getAvailableCountries, getBenchmarkTypes, Benchmark } from '@/lib/online/benchmarks'
import GNSSProcessor from '@/components/online/GNSSProcessor'
import CoordinateTransformer from '@/components/online/CoordinateTransformer'
import ImageryViewer from '@/components/online/ImageryViewer'

export default function OnlineServicesPage() {
  const [activeTab, setActiveTab] = useState<'gnss' | 'transform' | 'edm' | 'benchmarks' | 'imagery'>('gnss')
  const [transformResult, setTransformResult] = useState<TransformResult | null>(null)
  const [benchmarkResults, setBenchmarkResults] = useState<Benchmark[]>([])
  const [weatherResult, setWeatherResult] = useState<ReturnType<typeof calculateEDMCorrection> | null>(null)
  const [loading, setLoading] = useState(false)
  const [onlineStatus, setOnlineStatus] = useState<'online' | 'offline'>('online')

  useEffect(() => {
    const handleOnline = () => setOnlineStatus('online')
    const handleOffline = () => setOnlineStatus('offline')
    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)
    setOnlineStatus(navigator.onLine ? 'online' : 'offline')
    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])

  const [transformInput, setTransformInput] = useState({
    latitude: '',
    longitude: '',
    easting: '',
    northing: '',
    zone: '',
    hemisphere: 'N' as 'N' | 'S',
    fromSystem: 'WGS84',
    toSystem: 'UTM'
  })

  const [benchmarkSearch, setBenchmarkSearch] = useState({
    country: '',
    type: 'ALL' as 'ALL' | 'BM' | 'CP' | 'TRIG' | 'TIDAL'
  })

  const [weatherInput, setWeatherInput] = useState({
    temperature: '25',
    pressure: '1013.25',
    humidity: '50',
    elevation: ''
  })

  const systems = getSupportedSystems()
  const countries = getAvailableCountries()
  const benchmarkTypes = getBenchmarkTypes()

  const handleTransform = async () => {
    setLoading(true)
    try {
      const result = await transformCoordinates(
        {
          latitude: transformInput.latitude ? parseFloat(transformInput.latitude) : undefined,
          longitude: transformInput.longitude ? parseFloat(transformInput.longitude) : undefined,
          easting: transformInput.easting ? parseFloat(transformInput.easting) : undefined,
          northing: transformInput.northing ? parseFloat(transformInput.northing) : undefined,
          zone: transformInput.zone ? parseInt(transformInput.zone) : undefined,
          hemisphere: transformInput.hemisphere
        },
        transformInput.fromSystem as CoordinateSystem,
        transformInput.toSystem as CoordinateSystem
      )
      setTransformResult(result)
    } catch (e) {
      logger.error('Coordinate transform error:', { error: e })
    }
    setLoading(false)
  }

  const handleBenchmarkSearch = async () => {
    setLoading(true)
    try {
      const result = await searchBenchmarks(benchmarkSearch)
      setBenchmarkResults(result.benchmarks)
    } catch (e) {
      logger.error('Benchmark search error:', { error: e })
    }
    setLoading(false)
  }

  const handleWeatherCalc = () => {
    const result = calculateEDMCorrection({
      temperature: parseFloat(weatherInput.temperature),
      pressure: parseFloat(weatherInput.pressure),
      humidity: parseFloat(weatherInput.humidity),
      elevation: weatherInput.elevation ? parseFloat(weatherInput.elevation) : undefined
    })
    setWeatherResult(result)
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)]">
      <div className="max-w-6xl mx-auto px-4 py-8">
        <div className="flex justify-between items-start mb-2">
          <h1 className="text-3xl font-bold text-[var(--text-primary)]">Online Services</h1>
          <div className={`flex items-center gap-2 px-3 py-1 rounded-full text-sm ${
            onlineStatus === 'online' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
          }`}>
            <span className={`w-2 h-2 rounded-full ${onlineStatus === 'online' ? 'bg-green-500' : 'bg-red-500'}`}></span>
            {onlineStatus === 'online' ? 'Connected' : 'Offline'}
          </div>
        </div>
        <p className="text-[var(--text-muted)] mb-8">Live coordinate transformations, benchmark lookup, GNSS processing, and atmospheric corrections</p>

        <div className="flex flex-wrap gap-2 mb-6">
          {[
            { id: 'gnss', label: 'GNSS Baseline' },
            { id: 'transform', label: 'Coordinate Transform' },
            { id: 'edm', label: 'EDM Corrections' },
            { id: 'benchmarks', label: 'Benchmarks' },
            { id: 'imagery', label: 'Satellite Imagery' }
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as 'gnss' | 'transform' | 'edm' | 'benchmarks' | 'imagery')}
              className={`px-4 py-2 rounded-lg font-medium transition ${
                activeTab === tab.id
                  ? 'bg-sky-600 text-white'
                  : 'bg-[var(--bg-secondary)] text-[var(--text-muted)] hover:bg-[var(--bg-tertiary)] border border-[var(--border-color)]'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {activeTab === 'gnss' && (
          <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold mb-4">GNSS Baseline Processing</h2>
            <p className="text-sm text-[var(--text-muted)] mb-6">
              Process GNSS baseline observations for high-precision control network adjustments
            </p>
            <GNSSProcessor />
          </div>
        )}

        {activeTab === 'imagery' && (
          <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold mb-4">Satellite Imagery Overlay</h2>
            <p className="text-sm text-[var(--text-muted)] mb-6">
              Access Sentinel-2 satellite imagery for survey planning and verification
            </p>
            <ImageryViewer />
          </div>
        )}

        {activeTab === 'transform' && (
          <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold mb-4">Coordinate Transformation</h2>
            <div className="grid md:grid-cols-2 gap-6">
              <div>
                <label htmlFor="from-system" className="block text-sm font-medium text-[var(--text-muted)] mb-1">From System</label>
                <select
                  id="from-system"
                  value={transformInput.fromSystem}
                  onChange={e => setTransformInput({ ...transformInput, fromSystem: e.target.value })}
                  className="w-full p-2 border rounded-lg"
                >
                  {systems.map((s) => (
                    <option key={s.id} value={s.id}>{s.name}</option>
                  ))}
                </select>

                <div className="mt-4 space-y-3">
                  {transformInput.fromSystem === 'WGS84' ? (
                    <>
                      <div>
                        <label htmlFor="transform-latitude" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Latitude</label>
                        <input
                          id="transform-latitude"
                          type="number"
                          step="any"
                          value={transformInput.latitude}
                          onChange={e => setTransformInput({ ...transformInput, latitude: e.target.value })}
                          aria-label="Latitude" placeholder="e.g., -1.2921"
                          className="w-full p-2 border rounded-lg"
                        />
                      </div>
                      <div>
                        <label htmlFor="transform-longitude" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Longitude</label>
                        <input
                          id="transform-longitude"
                          type="number"
                          step="any"
                          value={transformInput.longitude}
                          onChange={e => setTransformInput({ ...transformInput, longitude: e.target.value })}
                          aria-label="Longitude" placeholder="e.g., 36.8219"
                          className="w-full p-2 border rounded-lg"
                        />
                      </div>
                    </>
                  ) : (
                    <>
                      <div>
                        <label htmlFor="transform-easting" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Easting (m)</label>
                        <input
                          id="transform-easting"
                          type="number"
                          step="any"
                          value={transformInput.easting}
                          onChange={e => setTransformInput({ ...transformInput, easting: e.target.value })}
                          aria-label="Easting (m)" placeholder="e.g., 250000"
                          className="w-full p-2 border rounded-lg"
                        />
                      </div>
                      <div>
                        <label htmlFor="transform-northing" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Northing (m)</label>
                        <input
                          id="transform-northing"
                          type="number"
                          step="any"
                          value={transformInput.northing}
                          onChange={e => setTransformInput({ ...transformInput, northing: e.target.value })}
                          aria-label="Northing (m)" placeholder="e.g., 9850000"
                          className="w-full p-2 border rounded-lg"
                        />
                      </div>
                      <div className="grid grid-cols-2 gap-3">
                        <div>
                          <label htmlFor="transform-zone" className="block text-sm font-medium text-[var(--text-muted)] mb-1">UTM Zone</label>
                          <input
                            id="transform-zone"
                            type="number"
                            value={transformInput.zone}
                            onChange={e => setTransformInput({ ...transformInput, zone: e.target.value })}
                            placeholder="e.g., 37"
                            className="w-full p-2 border rounded-lg"
                          />
                        </div>
                        <div>
                          <label htmlFor="transform-hemisphere" className="block text-sm font-medium text-[var(--text-muted)] mb-1">Hemisphere</label>
                          <select
                            id="transform-hemisphere"
                            value={transformInput.hemisphere}
                            onChange={e => setTransformInput({ ...transformInput, hemisphere: e.target.value as 'N' | 'S' })}
                            className="w-full p-2 border rounded-lg"
                          >
                            <option value="N">Northern</option>
                            <option value="S">Southern</option>
                          </select>
                        </div>
                      </div>
                    </>
                  )}
                </div>
              </div>

              <div>
                <label htmlFor="to-system" className="block text-sm font-medium text-[var(--text-muted)] mb-1">To System</label>
                <select
                  id="to-system"
                  value={transformInput.toSystem}
