'use client';
import { useState, useEffect, useRef } from 'react'
import { ModernPricingPage, PricingCardProps } from '@/components/ui/animated-glassy-pricing'
import { PLAN_CATALOG, getPlanPrice, SUPPORTED_CURRENCIES, type CurrencyCode } from '@/lib/subscription/catalog'
import { logger } from '@/lib/logger'

// Minimal typed surface for the PayPal v6 SDK global (window.paypal)
interface PayPalV6PaymentSession {
  start(opts: { presentationMode: string }, createOrder: () => Promise<{ orderId: string }>): Promise<void>
}
interface PayPalV6SDKInstance {
  createPayPalOneTimePaymentSession(options: {
    onApprove: (data: { orderId: string }) => void
    onCancel: (data: unknown) => void
    onError: (error: unknown) => void
  }): PayPalV6PaymentSession
}
interface PayPalV6SDK {
  createInstance(config: { clientId: string; components: string[]; pageType: string; currency: CurrencyCode }): Promise<PayPalV6SDKInstance>
}

declare global {
  interface Window {
    paypal?: PayPalV6SDK
  }
}


const currencyMap: Record<string, CurrencyCode> = {
  'KE': 'KES', 'UG': 'UGX', 'TZ': 'TZS', 'NG': 'NGN',
  'GH': 'GHS', 'ZA': 'ZAR', 'IN': 'INR', 'ID': 'IDR',
  'BR': 'BRL', 'AU': 'AUD', 'GB': 'GBP', 'FR': 'EUR',
  'DE': 'EUR', 'US': 'USD', 'ET': 'KES', 'RW': 'KES',
  'SD': 'KES', 'MA': 'EUR', 'EG': 'USD'
}

const formatPrice = (price: number, currency: CurrencyCode) => {
  const symbols: Record<string, string> = {
    KES: 'KSh ', UGX: 'USh ', TZS: 'TSh ', NGN: '₦ ', USD: '$ ',
    GHS: '₵ ', ZAR: 'R ', INR: '₹ ', IDR: 'Rp ', BRL: 'R$ ', AUD: 'A$ ', GBP: '£ ', EUR: '€ '
  }
  return `${symbols[currency] || ''}${price.toLocaleString()}`
}

const faqs = [
  {
    q: 'Can I change plans anytime?',
    a: 'Yes. Upgrade or downgrade at any time. Changes take effect immediately.',
  },
  {
    q: 'What payment methods do you accept?',
    a: 'M-Pesa (Kenya), Visa/Mastercard (Stripe), and PayPal for global payments.',
  },
  {
    q: 'Is there a free trial?',
    a: 'All paid plans include a 14-day free trial. No credit card required.',
  },
  {
    q: 'Do you offer student discounts?',
    a: 'Yes. Contact us with your student ID for 50% off any plan.',
  },
]

export default function PricingPage() {
  const [currency, setCurrency] = useState<CurrencyCode>('KES')
  const paypalContainerRef = useRef<HTMLDivElement>(null)
  const paypalLoadedRef = useRef(false)

  useEffect(() => { document.title = 'Pricing — METARDU' }, [])

  useEffect(() => {
    async function detectCurrency() {
      try {
        const cached = localStorage.getItem('metardu:currency')
        if (cached) {
          const { code, ts } = JSON.parse(cached) as { code: CurrencyCode; ts: number }
          if (Date.now() - ts < 86400000) { setCurrency(code); return }
        }
      } catch { /* ignore */ }
      try {
        const res = await fetch('https://ipapi.co/json/')
        const data = (await res.json()) as { country_code?: string }
        if (data.country_code && currencyMap[data.country_code]) {
          const code = currencyMap[data.country_code]
          setCurrency(code)
          try { localStorage.setItem('metardu:currency', JSON.stringify({ code, ts: Date.now() })) } catch { /* ignore */ }
        }
      } catch {
        // Use default KES
      }
    }
    detectCurrency()
  }, [])

  const [selectedPlanId, setSelectedPlanId] = useState<string>('pro')

  // Load PayPal SDK v6
  useEffect(() => {
    if (paypalLoadedRef.current) return

    const script = document.createElement('script')
    const clientId = process.env.NEXT_PUBLIC_PAYPAL_CLIENT_ID || ''
    if (!clientId) {
      return
    }
    
    script.src = `https://www.paypal.com/web-sdk/v6/core`
    script.async = true
    script.onload = async () => {
      paypalLoadedRef.current = true
      try {
        if (!window.paypal) {
          return
        }
        const sdkInstance = await window.paypal.createInstance({
          clientId,
          components: ["paypal-payments"],
          pageType: "checkout",
          currency: currency
        })

        const paymentSessionOptions = {
          async onApprove(data: { orderId: string }) {
            try {
              const res = await fetch('/api/payments/paypal/capture', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ orderId: data.orderId })
              })
              const captureData = (await res.json()) as { error?: string }
              if (captureData.error) throw new Error(captureData.error)
              alert("Payment successful! Thank you for subscribing.")
            } catch {
              alert("Payment capture failed.")
            }
          },
          onCancel() {
            /* cancelled */
          },
          onError() {
            alert("An error occurred during payment.")
          },
        }

        const paypalPaymentSession = sdkInstance.createPayPalOneTimePaymentSession(paymentSessionOptions)

        const paypalButton = document.getElementById("paypal-v6-button")
        if (paypalButton) {
          paypalButton.removeAttribute("hidden")
          paypalButton.addEventListener("click", async () => {
            try {
              await paypalPaymentSession.start(
                { presentationMode: "auto" },
                () => {
                  return fetch("/api/payments/paypal/create", {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    // Access the current selectedPlanId and currency from a mutable ref or closures if necessary,
                    // but since this is bound once, we should fetch the current value from the DOM or state.
                    // We'll use a hack to read from a data attribute or global, but easiest is reading a data-plan attribute.
                    body: JSON.stringify({ 
                      planId: document.getElementById('paypal-v6-button')?.getAttribute('data-plan') || 'pro', 
                      currency: document.getElementById('paypal-v6-button')?.getAttribute('data-currency') || 'USD' 
                    })
                  })
                  .then(response => response.json())
                  .then((data: { error?: string; orderId?: string }) => {
                    if (data.error) throw new Error(data.error)
                    if (!data.orderId) throw new Error('Missing order ID from create response')
                    return { orderId: data.orderId }
                  })
                }
              )
            } catch (error) {
              logger.error("PayPal payment start error:", { error })
            }
          })
        }
      } catch (err) {
        logger.warn('[Pricing] PayPal SDK v6 render error:', { error: err })
      }
    }
    document.body.appendChild(script)

    return () => {
      if (script.parentNode) script.parentNode.removeChild(script)
    }
  }, [currency]) // Re-bind if currency changes to ensure correct currency in createInstance (though technically sdkInstance might not re-init easily, keeping it simple for now)

  // Show Free, Pro, and Team plans on pricing page (single source of truth from PLAN_CATALOG)
  const visiblePlans = PLAN_CATALOG.filter(p => ['free', 'pro', 'team'].includes(p.id))

  const plans: PricingCardProps[] = visiblePlans.map(plan => ({
    planId: plan.id,
    planName: plan.name,
    description: plan.id === 'free'
      ? 'Perfect for students and hobbyist surveyors'
      : plan.id === 'pro'
        ? 'For professional surveyors and small firms'
        : 'Collaborate with your survey crew',
    price: formatPrice(getPlanPrice(plan.id, currency), currency),
    features: plan.features,
    buttonText: plan.id === 'free'
      ? 'Get Started Free'
      : plan.id === 'team'
        ? 'Start Free Trial'
        : 'Start Free Trial',
    buttonVariant: plan.id === 'free' ? 'secondary' as const : 'primary' as const,
    isPopular: plan.id === 'pro',
  }))

  return (
    <ModernPricingPage
      title={
        <>
          Simple, <span className="text-cyan-400">Transparent</span> Pricing
        </>
      }
      subtitle="Start free, upgrade when you need more. No hidden fees, cancel anytime."
      plans={plans}
    >
      {/* PayPal SDK v6 Web Component section */}
      <div className="w-full max-w-5xl mx-auto mt-12 mb-8">
        <div className="text-center mb-6">
          <h3 className="text-xl font-semibold text-foreground mb-2">Pay with PayPal</h3>
          <p className="text-foreground/70 text-sm mb-4">Secure checkout for one-time payments</p>
          
          <div className="flex justify-center gap-2 mb-6 items-center">
            <span className="text-sm font-medium">Select Plan:</span>
            <select 
              className="bg-black/5 dark:bg-white/10 border border-black/10 dark:border-white/20 rounded-md px-3 py-1.5 text-sm outline-none focus:ring-2 focus:ring-[var(--accent)]"
              value={selectedPlanId}
              onChange={(e) => setSelectedPlanId(e.target.value as string)}
            >
              {visiblePlans.map(p => (
                <option key={p.id} value={p.id}>{p.name} — {formatPrice(getPlanPrice(p.id, currency), currency)}</option>
              ))}
            </select>
          </div>
        </div>
        <div className="flex justify-center">
          <div className="min-h-[200px] flex items-center justify-center w-full max-w-xs">
            {/* @ts-expect-error custom web component */}
            <paypal-button 
              id="paypal-v6-button" 
              hidden 
              data-plan={selectedPlanId}
              data-currency={currency}
            />
          </div>
        </div>
      </div>
    </ModernPricingPage>
  )
}

'use client';

import { useState, useRef, useEffect, useCallback, useMemo } from 'react'
import { AlertTriangle } from 'lucide-react'
import { interpretCSV, CSVInterpretResult } from '@/lib/parsers/csvSurveyInterpreter'
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer'
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder'
import { bowditchAdjustmentSolvedFromResult } from '@/lib/engine/solution/wrappers/traverse'
import type { TraverseAdjustmentSolvedResult } from '@/lib/engine/solution/wrappers/traverse'
import { levelingSolved } from '@/lib/engine/solution/wrappers/leveling'
import type { LevelingResult } from '@/lib/engine/types'
import { radiationSolved } from '@/lib/engine/solution/wrappers/radiation'
import { 
  detectSurveyType,
  SurveyDataset,
  SurveyObservation, 
  runWorkflow, 
  TraverseWorkflowData, 
  LevelingWorkflowData,
  RadiationWorkflowData,
  WorkflowResult 
} from '@/lib/workflows/workflowEngine'
import { 
  checkTolerance, 
  ToleranceProfile, 
  getToleranceConfig,
  getAllToleranceProfiles,
  ToleranceCheckResult 
} from '@/lib/validation/toleranceEngine'
interface ProjectRow { id: string; name: string }
interface TraverseLegLike {
  from: string
  to: string
  distance?: number
  bearingDMS?: string
  adjEasting: number
  adjNorthing: number
  adjDeltaE: number
  adjDeltaN: number
}
interface RadiationPoint { name: string; easting: number; northing: number }
interface LevelingReading {
  station: string
  bs?: number
  is?: number
  fs?: number
  rise?: number
  fall?: number
  reducedLevel?: number
}
type SurveyPointRow = {
  project_id: string
  name: string
  easting: number
  northing: number
  elevation: null
  is_control: boolean
  control_order?: string
  locked?: boolean
}

import Link from 'next/link'
import { createClient } from '@/lib/api-client/client'
import { logger } from '@/lib/logger'

export default function ProcessPage() {
  const [processError, setProcessError] = useState<string | null>(null)
  const [dragActive, setDragActive] = useState(false)
  const [fileContent, setFileContent] = useState<string | null>(null)
  const [interpretResult, setInterpretResult] = useState<CSVInterpretResult | null>(null)
  const [processing, setProcessing] = useState(false)
  const [processed, setProcessed] = useState(false)
  const [manualType, setManualType] = useState<string>('')
  const [selectedProfile, setSelectedProfile] = useState<ToleranceProfile>('cadastral')
  const [workflowResult, setWorkflowResult] = useState<WorkflowResult | null>(null)
  const [workflowSolutions, setWorkflowSolutions] = useState<Array<{ title?: string; steps: SolutionStep[] }>>([])
  const [toleranceResult, setToleranceResult] = useState<ToleranceCheckResult | null>(null)
  const [projects, setProjects] = useState<ProjectRow[]>([])
  const [selectedProjectId, setSelectedProjectId] = useState<string>('')
  const [saveLoading, setSaveLoading] = useState(false)
  const [saveSuccess, setSaveSuccess] = useState(false)
  
  const fileInputRef = useRef<HTMLInputElement>(null)
  // AUDIT FIX (H-007, 2026-07-27): useMemo to prevent infinite loop on /process.
  const dbClient = useMemo(() => createClient(), [])

  const fetchProjects = useCallback(async () => {
    const { data: { session } } = await dbClient.auth.getSession()
    const user = session?.user
    if (!user) return

    const { data } = await dbClient
      .from('projects')
      .select('*')
      .eq('user_id', user.id)
      .order('created_at', { ascending: false })
            .limit(20) as unknown as { data: ProjectRow[] | null }

    if (data) {
      setProjects(data as ProjectRow[])
    }
  }, [dbClient])

  useEffect(() => {
    fetchProjects()
  }, [fetchProjects])

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true)
    } else if (e.type === 'dragleave') {
      setDragActive(false)
    }
  }

  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setDragActive(false)
    
    const files = e.dataTransfer.files
    if (files && files[0]) {
      const content = await files[0].text()
      setFileContent(content)
      const result = interpretCSV(content)
      setInterpretResult(result)
      
      if (result.ok && result.dataset) {
        const detected = detectSurveyTypeFromDataset(result.dataset)
        // survey type detected
      }
    }
  }

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (files && files[0]) {
      const content = await files[0].text()
      setFileContent(content)
      const result = interpretCSV(content)
      setInterpretResult(result)
    }
  }

  const detectSurveyTypeFromDataset = (dataset: SurveyDataset): string => {
    if (dataset?.surveyType && dataset.surveyType !== 'unknown') return dataset.surveyType
    if (!dataset?.observations) return 'unknown'
    const obs = dataset.observations
    const types = new Set(obs.map((o: SurveyObservation) => o.type))
    
    if (types.has('BS') || types.has('IS') || types.has('FS')) return 'leveling'
    if (types.has('BEARING') && types.has('DISTANCE')) return 'traverse'
    if (types.has('ANGLE') && types.has('DISTANCE')) return 'radiation'
    if (types.has('COORDINATE')) return 'coordinates'
    return 'unknown'
  }

  const processSurvey = () => {
    setProcessing(true)
    
    setTimeout(() => {
      setProcessing(false)
      setProcessed(true)
    }, 1500)
  }

  const runProcessWithWorkflow = () => {
    if (!interpretResult?.ok || !interpretResult.dataset) return

    setProcessing(true)

    try {
      const dataset = interpretResult.dataset
      const surveyType = detectSurveyTypeFromDataset(dataset)
      let result: WorkflowResult

      const solutions: Array<{ title?: string; steps: SolutionStep[] }> = []

      if (surveyType === 'traverse') {
        const traverseData: TraverseWorkflowData = {
          legs: dataset.observations.map((obs: SurveyObservation, i: number) => ({
            fromStation: obs.station,
            toStation: dataset.observations[i + 1]?.station || `P${i + 2}`,
            bearing: obs.value1 || 0,
            distance: obs.value2 || 0
          })),
          openingPoint: {
            name: dataset.observations[0]?.station || 'A',
            easting: (dataset.metadata as { openingEasting?: number })?.openingEasting || 500000,
            northing: (dataset.metadata as { openingNorthing?: number })?.openingNorthing || 4500000
          }
        }
        result = runWorkflow('traverse', traverseData)
        if (result.success && (result.results as TraverseAdjustmentSolvedResult | undefined)?.legs) {
          try {
            const s = bowditchAdjustmentSolvedFromResult(result.results as TraverseAdjustmentSolvedResult)
            solutions.push({ title: s.solution.title, steps: s.steps })
          } catch {}
        }
      } else if (surveyType === 'leveling') {
        const levelingData: LevelingWorkflowData = {
          readings: dataset.observations.map((obs: SurveyObservation) => ({
            station: obs.station,
            bs: obs.type === 'BS' ? obs.value1 : undefined,
            is: obs.type === 'IS' ? obs.value1 : undefined,
            fs: obs.type === 'FS' ? obs.value1 : undefined
          })),
          openingRL: (dataset.metadata as { openingRL?: number })?.openingRL || 100
        }
        result = runWorkflow('leveling', levelingData)
        if (result.success && (result.results as LevelingResult | undefined)?.readings) {
          try {
            const s = levelingSolved(
              { readings: levelingData.readings, openingRL: levelingData.openingRL, closingRL: levelingData.closingRL, method: 'rise_and_fall', distanceKm: 1 },
              result.results as LevelingResult
            )
            solutions.push({ title: s.solution.title, steps: s.steps })
          } catch {}
        }
      } else if (surveyType === 'radiation') {
        const radiationData: RadiationWorkflowData = {
          station: {
            name: (dataset.metadata as { stationName?: string })?.stationName || 'STN1',
            easting: (dataset.metadata as { stationEasting?: number })?.stationEasting || 500000,
            northing: (dataset.metadata as { stationNorthing?: number })?.stationNorthing || 4500000
          },
          observations: dataset.observations.map((obs: SurveyObservation) => ({
            pointName: obs.station,
            bearing: obs.value1 || 0,
            distance: obs.value2 || 0
          }))
        }
        result = runWorkflow('radiation', radiationData)
        if (radiationData.observations.length > 0) {
          for (const obs of radiationData.observations.slice(0, 3)) {
            try {
              const s = radiationSolved({
                station: { easting: radiationData.station.easting, northing: radiationData.station.northing },
                bearingDeg: obs.bearing,
                distance: obs.distance,
              })
              solutions.push({ title: s.solution.title, steps: s.steps })
            } catch {}
          }
        }
      } else {
        result = {
          success: false,
          surveyType: 'unknown',
          results: null,
          validation: { passed: false, checks: [] },
          warnings: [],
          errors: ['Unknown survey type - cannot process']
        }
      }

      setWorkflowResult(result)
      setWorkflowSolutions(solutions)

      if (result.success && result.results) {
        const config = getToleranceConfig(selectedProfile)
        
        if (surveyType === 'traverse' && result.results) {
          const res = result.results as {
            legs?: TraverseLegLike[]
            precisionRatio?: number
            closingErrorE?: number
            closingErrorN?: number
            totalDistance?: number
          }
          if (res.legs) {
            const traverseTol = checkTolerance({
              traverse: {
                precisionRatio: res.precisionRatio || 0,
                angularMisclosure: null,
                linearError: Math.sqrt((res.closingErrorE || 0) ** 2 + (res.closingErrorN || 0) ** 2),
                totalDistance: res.totalDistance || 0,
                numStations: res.legs.length
              }
            }, selectedProfile)
            setToleranceResult(traverseTol)
          }
        } else if (surveyType === 'leveling' && result.results) {
          const res = result.results as {
            readings?: LevelingReading[]
            arithmeticCheck?: boolean
            misclosure?: number
          }
          if (res.readings) {
            const levelingTol = checkTolerance({
              leveling: {
                arithmeticCheckPassed: res.arithmeticCheck || false,
                arithmeticDiff: res.misclosure || 0,
                closingError: res.misclosure || 0,
                distanceKm: (res.readings.length || 0) * 0.1 || 1
              }
            }, selectedProfile)
            setToleranceResult(levelingTol)
          }
        }
      }

      setProcessing(false)
      setProcessed(true)
    } catch (e) {
      logger.error('Processing error:', { error: e })
      setProcessing(false)
    }
  }

  const handleSaveToProject = async () => {
    if (!selectedProjectId || !workflowResult?.results) {
      setProcessError('Please select a project first.')
      return
    }

    setSaveLoading(true)

    try {
      const res = workflowResult.results as { legs?: TraverseLegLike[]; points?: RadiationPoint[] }
      if (workflowResult.surveyType === 'traverse' && res.legs) {
        const points: SurveyPointRow[] = res.legs.map((leg: TraverseLegLike) => ({
          project_id: selectedProjectId,
          name: leg.to,
          easting: leg.adjEasting,
          northing: leg.adjNorthing,
          elevation: null,
          is_control: false
        }))

        if (res.legs[0]) {
          points.unshift({
            project_id: selectedProjectId,
            name: res.legs[0].from,
            easting: res.legs[0].adjEasting - res.legs[0].adjDeltaE,
            northing: res.legs[0].adjNorthing - res.legs[0].adjDeltaN,
            elevation: null,
            is_control: true,
            control_order: 'primary',
            locked: true
          })
        }

        const { error: insertError } = await dbClient.from('survey_points').insert(points)
        if (insertError) {
          throw new Error(`Failed to save points: ${insertError.message}`)
        }
      } 
      else if (workflowResult.surveyType === 'radiation' && res.points) {
        const points = res.points.map((pt: RadiationPoint) => ({
          project_id: selectedProjectId,
          name: pt.name,
          easting: pt.easting,
          northing: pt.northing,
          elevation: null,
          is_control: false
        }))

        const { error: insertError } = await dbClient.from('survey_points').insert(points)
        if (insertError) {
          throw new Error(`Failed to save points: ${insertError.message}`)
        }
      }

      setSaveSuccess(true)
      setTimeout(() => setSaveSuccess(false), 3000)
    } catch (e) {
      logger.error('Save error:', { error: e })
      setProcessError('Error saving points to project. Please try again.')
    }

    setSaveLoading(false)
  }

  const detectLabel = (type: string) => {
    switch (type) {
      case 'leveling': return 'Leveling Run'
      case 'traverse': return 'Traverse Survey'
      case 'radiation': return 'Radiation / Detail Survey'
      case 'boundary': return 'Boundary / Parcel'
      default: return 'Unknown Survey Type'
    }
  }

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">
      <h1 className="text-3xl font-bold mb-2">Process Field Notes</h1>
      <p className="text-sm text-[var(--text-muted)] mb-8">
        Upload your CSV field notes — METARDU detects the survey type and processes automatically
      </p>

      {!fileContent ? (
        <>
          <div
            className={`border-2 border-dashed rounded-xl p-12 text-center cursor-pointer transition-colors ${
              dragActive 
                ? 'border-[var(--accent)] bg-[var(--accent)]/10' 
                : 'border-[var(--border-color)] hover:border-gray-600'
            }`}
            onDragEnter={handleDrag}
            onDragLeave={handleDrag}
            onDragOver={handleDrag}
            onDrop={handleDrop}
            onClick={() => fileInputRef.current?.click()}
          >
            <div className="text-6xl mb-4">[Clip]</div>
            <p className="text-lg font-semibold text-[var(--text-primary)] mb-2">
              Drop your field notes here or click to upload
            </p>
            <p className="text-sm text-[var(--text-muted)]">
              Accepts: .csv, .txt files
            </p>
            <input
              ref={fileInputRef}
              type="file"
              accept=".csv,.txt"
              className="hidden"
              onChange={handleFileSelect}
            />
          </div>

          <div className="mt-8 p-6 bg-[var(--bg-secondary)]/50 rounded-xl border border-[var(--border-color)]">
            <h3 className="text-sm font-semibold text-[var(--text-secondary)] mb-4">Download Sample Files</h3>
            <div className="flex flex-wrap gap-3">
              <a href="/sample-files/traverse_sample.csv" className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded text-sm">
                 Traverse Sample
              </a>
              <a href="/sample-files/leveling_sample.csv" className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded text-sm">
                 Leveling Sample
              </a>
              <a href="/sample-files/radiation_sample.csv" className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded text-sm">
                 Radiation Sample
              </a>
            </div>
          </div>
        </>
      ) : interpretResult?.ok && interpretResult.dataset ? (
        <div className="space-y-6">
          <div className="card border border-[var(--border-color)]">
            <div className="card-header flex items-center gap-3">
              <span className="text-2xl"></span>
              <span className="font-semibold">
                {detectLabel(detectSurveyTypeFromDataset(interpretResult.dataset!))} Detected
              </span>
            </div>
            <div className="card-body">
              <p className="text-sm text-[var(--text-primary)] mb-4">
                {interpretResult.dataset!.observations.length} observations found
              </p>

              <div className="bg-[var(--bg-tertiary)] rounded p-3 overflow-x-auto">
                <table className="text-xs w-full">
                  <thead>
                    <tr className="text-[var(--text-muted)]">
                      <th className="px-2 py-1 text-left">Station</th>
                      <th className="px-2 py-1 text-left">Type</th>
                      <th className="px-2 py-1 text-right">Value</th>
                    </tr>
                  </thead>
                  <tbody>
                    {interpretResult.dataset!.observations.slice(0, 5).map((obs: SurveyObservation, i: number) => (
                      <tr key={obs.station || i} className="border-t border-[var(--border-color)]">
                        <td className="px-2 py-1">{obs.station}</td>
                        <td className="px-2 py-1 text-[var(--accent)]">{obs.type}</td>
                        <td className="px-2 py-1 text-right font-mono">{obs.value1}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {interpretResult.warnings.length > 0 && (
                <div className="mt-4 p-3 bg-yellow-900/20 border border-yellow-700 rounded">
                  {interpretResult.warnings.map((w, i) => (
                    <p key={`warn-${i}`} className="text-sm text-yellow-400"><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> {w}</p>
                  ))}
                </div>
              )}

              {!processed && (
                <>
                  <div className="mt-6">
                    <div className="block text-sm text-[var(--text-secondary)] mb-2">Tolerance Profile</div>
                    <div className="grid grid-cols-3 gap-3">
                      {getAllToleranceProfiles().map((profile) => (
                        <button
                          key={profile}
                          onClick={() => setSelectedProfile(profile)}
                          className={`p-3 rounded-lg border text-left transition-colors ${
                            selectedProfile === profile
                              ? 'border-[var(--accent)] bg-[var(--accent)]/10'
                              : 'border-[var(--border-color)] hover:border-gray-600'
                          }`}
                        >
                          <div className="font-medium text-[var(--text-primary)] capitalize">{getToleranceConfig(profile).name}</div>
                          <div className="text-xs text-[var(--text-muted)] mt-1">{getToleranceConfig(profile).description}</div>
                          <div className="text-xs text-[var(--text-muted)] mt-2">1:{getToleranceConfig(profile).linearPrecision}</div>
                        </button>
                      ))}
                    </div>
                  </div>

                  <div className="mt-6 flex gap-3">
                    <button
                      onClick={runProcessWithWorkflow}
                      disabled={processing}
                      className="px-6 py-3 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded-lg"
                    >
                      {processing ? 'Processing...' : 'Process Survey'}
                    </button>
                    <button
                      onClick={() => {
                        setFileContent(null)
                        setInterpretResult(null)
                        setProcessed(false)
                        setWorkflowResult(null)
                        setWorkflowSolutions([])
                        setToleranceResult(null)
                      }}
                      className="px-6 py-3 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded-lg"
                    >
                      Upload Different File
                    </button>
                  </div>
                </>
              )}
            </div>
          </div>

          {processed && workflowResult && (
            <>
              <div className={`card border-2 ${toleranceResult?.passed ? 'border-green-700' : 'border-red-700'}`}>
                <div className="card-header flex items-center gap-3">
                  <span className="text-2xl">{toleranceResult?.passed ? '' : '[x]'}</span>
                  <span className="font-semibold">
                    Tolerance Check: {toleranceResult?.passed ? 'PASS' : 'FAIL'}
                  </span>
                  <span className="text-sm text-[var(--text-muted)] ml-auto">
                    {toleranceResult?.precisionGrade}
                  </span>
                </div>
                <div className="card-body">
                  {toleranceResult?.checks.map((check, i) => (
                    <div key={`check-${check.name || i}`} className={`flex items-center justify-between py-2 border-b border-[var(--border-color)] last:border-0 ${check.passed ? 'text-green-400' : 'text-red-400'}`}>
                      <span>{check.passed ? '' : '[x]'} {check.name}</span>
                      <span className="text-sm">{check.message}</span>
                    </div>
                  ))}
                  
                  {toleranceResult?.recommendations && toleranceResult.recommendations.length > 0 && (
                    <div className="mt-4 p-3 bg-yellow-900/20 border border-yellow-700 rounded">
                      <div className="text-sm text-yellow-400 mb-2">Recommendations:</div>
                      {toleranceResult.recommendations.map((rec, i) => (
                        <p key={`rec-${i}`} className="text-xs text-yellow-300">• {rec}</p>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              {workflowSolutions.length > 0 ? (
                <div className="space-y-6">
                  {workflowSolutions.map((s, i) => (
                    <SolutionStepsRenderer key={`sol-${i}`} title={s.title} steps={s.steps} />
                  ))}
                </div>
              ) : null}

              {workflowResult.surveyType === 'traverse' && (workflowResult.results as TraverseAdjustmentSolvedResult | undefined)?.legs && (
                <div className="card border border-[var(--border-color)]">
                  <div className="card-header">
                    <span className="font-semibold">Gale's Table</span>
                  </div>
                  <div className="card-body overflow-x-auto">
                    <table className="text-xs w-full">
                      <thead>
                        <tr className="text-[var(--text-muted)] border-b border-[var(--border-color)]">
                          <th className="px-2 py-2 text-left">From</th>
                          <th className="px-2 py-2 text-left">To</th>
                          <th className="px-2 py-2 text-right">Dist</th>
                          <th className="px-2 py-2 text-right">Bearing</th>
                          <th className="px-2 py-2 text-right">Easting</th>
                          <th className="px-2 py-2 text-right">Northing</th>
                        </tr>
                      </thead>
                      <tbody>
                        {(workflowResult.results as TraverseAdjustmentSolvedResult).legs.map((leg: TraverseLegLike, i: number) => (
                          <tr key={`leg-${leg.from}-${leg.to}-${i}`} className="border-b border-[var(--border-color)]">
                            <td className="px-2 py-2">{leg.from}</td>
                            <td className="px-2 py-2">{leg.to}</td>
                            <td className="px-2 py-2 text-right font-mono">{leg.distance?.toFixed(3)}</td>
                            <td className="px-2 py-2 text-right font-mono">{leg.bearingDMS}</td>
                            <td className="px-2 py-2 text-right font-mono">{leg.adjEasting?.toFixed(4)}</td>
                            <td className="px-2 py-2 text-right font-mono">{leg.adjNorthing?.toFixed(4)}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}

              {workflowResult.surveyType === 'leveling' && (workflowResult.results as LevelingResult | undefined)?.readings && (
                <div className="card border border-[var(--border-color)]">
                  <div className="card-header">
                    <span className="font-semibold">Leveling Results</span>
                  </div>
                  <div className="card-body overflow-x-auto">
                    <table className="text-xs w-full">
                      <thead>
                        <tr className="text-[var(--text-muted)] border-b border-[var(--border-color)]">
                          <th className="px-2 py-2 text-left">Station</th>
                          <th className="px-2 py-2 text-right">BS</th>
                          <th className="px-2 py-2 text-right">IS</th>
                          <th className="px-2 py-2 text-right">FS</th>
                          <th className="px-2 py-2 text-right">Rise</th>
                          <th className="px-2 py-2 text-right">Fall</th>
                          <th className="px-2 py-2 text-right">RL</th>
                        </tr>
                      </thead>
                      <tbody>
                        {(workflowResult.results as LevelingResult).readings.map((r: LevelingReading, i: number) => (
                          <tr key={`reading-${r.station}-${i}`} className="border-b border-[var(--border-color)]">
                            <td className="px-2 py-2">{r.station}</td>
                            <td className="px-2 py-2 text-right font-mono">{r.bs?.toFixed(3) || '—'}</td>
                            <td className="px-2 py-2 text-right font-mono">{r.is?.toFixed(3) || '—'}</td>
                            <td className="px-2 py-2 text-right font-mono">{r.fs?.toFixed(3) || '—'}</td>
                            <td className="px-2 py-2 text-right font-mono">{r.rise?.toFixed(3) || '—'}</td>
                            <td className="px-2 py-2 text-right font-mono">{r.fall?.toFixed(3) || '—'}</td>
                            <td className="px-2 py-2 text-right font-mono">{r.reducedLevel?.toFixed(4) || '—'}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}

              <div className="card border border-[var(--border-color)]">
                <div className="card-body space-y-4">
                  <h3 className="font-semibold">Save to Project</h3>
                  
                  <div className="flex gap-3">
                    <select
                      value={selectedProjectId}
                      onChange={(e) => setSelectedProjectId(e.target.value)}
                      className="flex-1 px-4 py-3 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)]"
                    >
                      <option value="">Select a project...</option>
                      {projects.map((p) => (
                        <option key={p.id} value={p.id}>{p.name}</option>
                      ))}
                    </select>
                    
                    <button
                      onClick={handleSaveToProject}
                      disabled={!selectedProjectId || saveLoading}
                      className="px-6 py-3 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded-lg disabled:opacity-50"
                    >
                      {saveLoading ? 'Saving...' : saveSuccess ? ' Saved!' : 'Save Points'}
                    </button>
                  </div>

                  <div className="flex gap-3 pt-2">
                    <Link href="/dashboard" className="px-6 py-3 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded-lg text-center">
                      View Projects
                    </Link>
                    <button className="px-6 py-3 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded-lg">
                      Generate PDF Report
                    </button>
                  </div>
                </div>
              </div>
            </>
          )}
        </div>
      ) : (
        <div className="card border-red-800">
          <div className="card-header">
            <span className="font-semibold text-red-400">Upload Failed</span>
          </div>
          <div className="card-body">
            <p className="text-[var(--text-primary)] mb-4">
              {interpretResult?.error || 'Could not parse the uploaded file'}
            </p>
            {interpretResult?.warnings.map((w, i) => (
              <p key={`warn2-${i}`} className="text-sm text-yellow-400"><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> {w}</p>
            ))}
            
            <div className="mt-6 p-4 bg-[var(--bg-tertiary)] rounded">
              <p className="text-sm text-[var(--text-secondary)] mb-3">Or select survey type manually:</p>
              <select
                value={manualType}
                onChange={(e) => setManualType(e.target.value)}
                className="input mb-3"
              >
                <option value="">Select type...</option>
                <option value="leveling">Leveling Run</option>
                <option value="traverse">Traverse Survey</option>
                <option value="radiation">Radiation / Detail</option>
              </select>
              {manualType && (
                <button className="btn btn-primary">
                  Process as {detectLabel(manualType)}
                </button>
              )}
            </div>

            <button
              onClick={() => {
                setFileContent(null)
                setInterpretResult(null)
              }}
              className="btn btn-secondary mt-4"
            >
              Try Again
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useEffect, useCallback } from 'react'
import { useParams, useRouter } from 'next/navigation'
import dynamic from 'next/dynamic'
import { ArrowLeft, Loader2 } from 'lucide-react'
import { db } from '@/lib/db'
import type { CADDocument } from '@/components/cad-editor/CADEditor'

// ponytail: lazy-load the CAD editor (it's a heavy SVG interaction component)
const CADEditor = dynamic(() => import('@/components/cad-editor/CADEditor'), {
  ssr: false,
  loading: () => (
    <div className="flex items-center justify-center h-screen bg-gray-900">
      <Loader2 className="w-6 h-6 animate-spin text-blue-500" />
    </div>
  ),
})

export default function CADEditorPage() {
  const params = useParams()
  const router = useRouter()
  const projectId = params.id as string
  const [doc, setDoc] = useState<CADDocument | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  // Load traverse data and build CAD document
  useEffect(() => {
    async function loadPlanData() {
      try {
        setLoading(true)

        // Fetch the adjusted traverse coordinates from the API
        const res = await fetch(`/api/project/${projectId}/fieldbook`)
        const result = (await res.json()) as {
          data?: {
            stations?: Array<{ id: string; name?: string; easting: number; northing: number }>
            observations?: Array<Record<string, unknown>>
            projectName?: string
            lrNumber?: string
            surveyor?: string
            regNo?: string
          }
        }

        if (!result.data?.stations || result.data.stations.length === 0) {
          setError('No traverse data found. Compute a traverse first.')
          return
        }

        const stations = result.data.stations
        const observations = result.data.observations || []

        // Convert UTM coordinates to SVG coordinates
        // ponytail: simple linear transform — find bounding box, scale to fit A3
        const W = 1122  // A3 landscape at 96 DPI
        const H = 794
        const PADDING = 100

        const eastings = stations.map((s: { easting: number }) => s.easting)
        const northings = stations.map((s: { northing: number }) => s.northing)
        const minE = Math.min(...eastings)
        const maxE = Math.max(...eastings)
        const minN = Math.min(...northings)
        const maxN = Math.max(...northings)

        const rangeE = maxE - minE || 1
        const rangeN = maxN - minN || 1
        const scale = Math.min((W - 2 * PADDING) / rangeE, (H - 2 * PADDING) / rangeN)

        const toX = (e: number) => PADDING + (e - minE) * scale
        // SVG Y axis is inverted (down = positive)
        const toY = (n: number) => H - PADDING - (n - minN) * scale

        // Build beacons
        const beacons: CADDocument['beacons'] = stations.map((s: { id: string; name?: string; easting: number; northing: number }, i: number) => ({
          id: s.id || `b${i}`,
          label: s.name || `P${i + 1}`,
          x: toX(s.easting),
          y: toY(s.northing),
          easting: s.easting,
          northing: s.northing,
          symbol: 'concrete_beacon',
          locked: false,
        }))

        // Build boundaries from observations (sequential traverse legs)
        const boundaries: CADDocument['boundaries'] = []
        for (let i = 0; i < stations.length - 1; i++) {
          const from = stations[i]
          const to = stations[i + 1]
          // Calculate bearing
          const dE = to.easting - from.easting
          const dN = to.northing - from.northing
          const bearing = (Math.atan2(dE, dN) * 180 / Math.PI + 360) % 360
          const dist = Math.sqrt(dE * dE + dN * dN)

          const deg = Math.floor(bearing)
          const minFloat = (bearing - deg) * 60
          const min = Math.floor(minFloat)
          const sec = ((minFloat - min) * 60).toFixed(0)

          boundaries.push({
            id: `bdy-${i}`,
            fromId: beacons[i].id,
            toId: beacons[i + 1].id,
            bearing: `${deg}°${String(min).padStart(2, '0')}'${String(sec).padStart(2, '0')}"`,
            distance: dist.toFixed(3),
            type: 'standard',
          })
        }

        const cadDoc: CADDocument = {
          beacons,
          boundaries,
          annotations: [],
          northArrow: {
            x: W - 120,
            y: 100,
            rotation: 0,
            type: 'grid',
            bearing: '0°00\'00"',
          },
          scaleBar: {
            x: 80,
            y: H - 60,
            scaleMeters: Math.round(rangeE / 5),
          },
          titleBlock: {
            projectName: result.data.projectName || 'Survey Plan',
            lrNumber: result.data.lrNumber || '',
            surveyor: result.data.surveyor || '',
            regNo: result.data.regNo || '',
            date: new Date().toLocaleDateString('en-GB'),
            scale: `1:${Math.round(rangeE / (W - 2 * PADDING) * 1000)}`,
            sheet: '1 of 1',
          },
          width: W,
          height: H,
        }

        setDoc(cadDoc)
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load plan data')
      } finally {
        setLoading(false)
      }
    }

    loadPlanData()
  }, [projectId])

  const handleSave = useCallback((savedDoc: CADDocument) => {
    // ponytail: save the CAD document to the project's engineering_data or a new cad_documents table
    // For now, save to localStorage as MVP. Phase 2: persist to DB.
    localStorage.setItem(`cad-doc-${projectId}`, JSON.stringify(savedDoc))
  }, [projectId])

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen bg-gray-900">
        <Loader2 className="w-6 h-6 animate-spin text-blue-500" />
      </div>
    )
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center h-screen bg-gray-900 text-gray-400">
        <p className="mb-4">{error}</p>
        <button onClick={() => router.push(`/project/${projectId}`)} className="text-blue-400 hover:underline">
          ← Back to project
        </button>
      </div>
    )
  }

  return (
    <div className="h-screen flex flex-col">
      <div className="flex items-center gap-3 px-4 py-2 bg-gray-800 border-b border-gray-700">
        <button
          onClick={() => router.push(`/project/${projectId}`)}
          className="text-gray-400 hover:text-white flex items-center gap-1 text-sm"
        >
          <ArrowLeft className="w-4 h-4" /> Back
        </button>
        <h1 className="text-sm font-medium text-white">CAD Editor — Survey Plan</h1>
      </div>
      <div className="flex-1">
        {doc && <CADEditor initialDocument={doc} onSave={handleSave} />}
      </div>
    </div>
  )
}

'use client';
import { useState, useEffect, use } from 'react'
import { createClient } from '@/lib/api-client/client'
import { generateContours, SpotHeight, ContourLine } from '@/lib/engine/contours'
import MobileDesktopNotice from '@/components/MobileDesktopNotice'
import { apiPost, ApiError } from '@/lib/api/client'
import { z } from 'zod'

// ponytail: response schemas — Phase 4 wave 4
const computeResponseSchema = z.object({
  contours: z.any().optional(),
  fallback: z.boolean().optional(),
  dxf: z.string().optional(),
}).passthrough()

type EngineMode = 'python' | 'typescript' | null

interface ContourSegment { elevation: number; segments: number[][][] }

interface SpotHeightRow {
  name?: string | null
  easting?: number | null
  northing?: number | null
  elevation?: number | null
}

export default function ContoursPage({ params }: { params: Promise<{ id: string }> }) {
  const { id: projectId } = use(params)
  const dbClient = createClient()

  const [points, setPoints] = useState<SpotHeight[]>([])
  const [contours, setContours] = useState<ContourLine[]>([])
  const [interval, setInterval] = useState(1)
  const [loading, setLoading] = useState(true)
  const [generating, setGenerating] = useState(false)
  const [engineMode, setEngineMode] = useState<EngineMode>(null)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    async function loadPoints() {
      const { data } = await dbClient
        .from('survey_points')
        .select('name, easting, northing, elevation')
        .eq('project_id', projectId)
                .order('name') as unknown as { data: SpotHeightRow[] | null }
      if (data) {
        setPoints((data as SpotHeightRow[]).map((p) => ({
          name: p.name ?? '',
          easting: p.easting ?? 0,
          northing: p.northing ?? 0,
          elevation: p.elevation || 0
        })))
      }
      setLoading(false)
    }
    loadPoints()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projectId])

  const handleGenerate = async () => {
    setGenerating(true)
    setError(null)

    // Try Python engine first (Delaunay triangulation — much better quality)
    try {
      const data = await apiPost('/api/compute', computeResponseSchema, {
        task: 'contours',
        payload: {
          points: points.map((p) => ({ x: p.easting, y: p.northing, z: p.elevation })),
          interval,
          base_elevation: Math.min(...points.map((p) => p.elevation)),
        },
      })

      if (data.contours && !data.fallback) {
        // Convert Python response format → ContourLine[]
        const converted: ContourLine[] = (data.contours as ContourSegment[]).flatMap(c =>
          c.segments.map((seg) => ({
            elevation: c.elevation,
            isIndex: false,
            points: seg.map((pt) => ({
              easting: pt[0],
              northing: pt[1],
              elevation: c.elevation,
            }))
          }))
        )
        setContours(converted)
        setEngineMode('python')
        setGenerating(false)
        return
      }
    } catch {
      // Python engine unavailable — fall through to TS fallback
    }

    // TypeScript fallback
    const generated = generateContours(points, interval)
    setContours(generated)
    setEngineMode('typescript')
    setGenerating(false)
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="flex items-center gap-3 text-amber-500">
          <svg className="w-5 h-5 animate-spin" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"/>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8z"/>
          </svg>
          Loading points…
        </div>
      </div>
    )
  }

  if (points.length < 3) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] py-12 px-6">
        <div className="max-w-4xl mx-auto text-center">
          <h1 className="text-2xl font-bold text-[var(--text-primary)] mb-4">Contour Map</h1>
          <div className="bg-[var(--bg-secondary)] border border-red-500/30 rounded-xl p-8">
            <p className="text-red-400 mb-2">Need at least 3 points with elevations to generate contours.</p>
            <p className="text-[var(--text-muted)] text-sm">Current points with elevation: {points.length}</p>
          </div>
        </div>
      </div>
    )
  }

  const elevations = points.map((p) => p.elevation)
  const minElev = Math.min(...elevations)
  const maxElev = Math.max(...elevations)

  return (
    <div className="min-h-screen bg-[var(--bg-primary)] py-12 px-6">
      <div className="max-w-5xl mx-auto">
        <div className="flex items-start justify-between mb-2">
          <h1 className="text-3xl font-bold text-[var(--text-primary)]">Contour Map</h1>
          {engineMode && (
            <span className={`text-xs px-2 py-1 rounded font-medium ${
              engineMode === 'python'
                ? 'bg-green-500/10 text-green-400 border border-green-500/20'
                : 'bg-yellow-500/10 text-yellow-400 border border-yellow-500/20'
            }`}>
              {engineMode === 'python' ? ' Python engine' : ' TS fallback'}
            </span>
          )}
        </div>
        <p className="text-[var(--text-secondary)] mb-8">Generate contours from spot heights using Delaunay triangulation</p>
        <MobileDesktopNotice>
          Contour generation and review involve wide tables, maps, and export options. Use desktop for full workflow; mobile is suitable for viewing and small adjustments.
        </MobileDesktopNotice>

        <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6 mb-8">
          <div className="flex items-center gap-4 mb-6 flex-wrap">
            <label className="text-[var(--text-secondary)] text-sm" htmlFor="contour-interval">Contour interval</label>
            <select
               id="contour-interval" value={interval}
              onChange={e => setInterval(Number(e.target.value))}
              className="input w-32"
            >
              <option value={0.25}>0.25 m</option>
              <option value={0.5}>0.5 m</option>
              <option value={1}>1 m</option>
              <option value={2}>2 m</option>
              <option value={5}>5 m</option>
              <option value={10}>10 m</option>
            </select>
            <button
              onClick={handleGenerate}
              disabled={generating}
              className="btn btn-primary disabled:opacity-60 disabled:cursor-not-allowed"
            >
              {generating ? (
                <>
                  <svg className="w-4 h-4 animate-spin" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"/>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8z"/>
                  </svg>
                  Generating…
                </>
              ) : 'Generate Contours'}
            </button>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-sm">
            {[
              { label: 'Points', value: points.length },
              { label: 'Min elevation', value: `${minElev.toFixed(2)} m` },
              { label: 'Max elevation', value: `${maxElev.toFixed(2)} m` },
              { label: 'Contour lines', value: contours.length },
            ].map((item) => (
              <div key={item.label} className="bg-[var(--bg-primary)] p-3 rounded-lg border border-[var(--border-color)]">
                <p className="text-[var(--text-muted)] text-xs mb-1">{item.label}</p>
                <p className="text-[var(--text-primary)] font-semibold font-mono">{item.value}</p>
              </div>
            ))}
          </div>
        </div>

        {error && (
          <div className="mb-6 p-4 rounded-lg border border-red-500/30 bg-red-500/10 text-red-400 text-sm">
            {error}
          </div>
        )}

        {contours.length > 0 && (
          <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
            <ContourMap points={points} contours={contours} />
          </div>
        )}
      </div>
    </div>
  )
}

function ContourMap({ points, contours }: { points: SpotHeight[]; contours: ContourLine[] }) {
  const width = 700
  const height = 500
  const padding = 48

  const eastings = points.map((p) => p.easting)
  const northings = points.map((p) => p.northing)
  const elevations = points.map((p) => p.elevation)

  const minE = Math.min(...eastings), maxE = Math.max(...eastings)
  const minN = Math.min(...northings), maxN = Math.max(...northings)
  const minElev = Math.min(...elevations), maxElev = Math.max(...elevations)

  const scaleE = (width - padding * 2) / (maxE - minE || 1)
  const scaleN = (height - padding * 2) / (maxN - minN || 1)
  const scale = Math.min(scaleE, scaleN)

  const toX = (e: number) => padding + (e - minE) * scale
  const toY = (n: number) => height - padding - (n - minN) * scale

  const elevColor = (elev: number): string => {
    const t = (elev - minElev) / (maxElev - minElev || 1)
    // Brown (low) → amber → green (high)
    const r = Math.round(139 - t * 39)
    const g = Math.round(90 + t * 110)
    const b = Math.round(43 - t * 43)
    return `rgb(${r},${g},${b})`
  }

  const majorInterval = (elev: number) => elev % 5 === 0

  const handleExportDXF = async () => {
    const data = await apiPost('/api/compute', computeResponseSchema, {
      task: 'export_dxf',
      payload: {
        projectName: 'Contour Export',
        points: points.map((p) => ({ name: p.name, easting: p.easting, northing: p.northing })),
      },
    })
    if (data.dxf) {
      const blob = new Blob([data.dxf], { type: 'text/plain' })
      const a = document.createElement('a')
      a.href = URL.createObjectURL(blob)
      a.download = ((data as Record<string, unknown>).filename as string) || 'contours.dxf'
      a.click()
    }
  }

  return (
    <div>
      <svg width="100%" viewBox={`0 0 ${width} ${height}`}
        className="bg-[var(--bg-primary)] rounded-lg border border-[var(--border-color)]">

        {/* Grid lines */}
                {Array.from({ length: 5 }, (_, i) => {
          const y = padding + (i / 4) * (height - padding * 2)
          return <line key={`${_}-${i}`} x1={padding} y1={y} x2={width - padding} y2={y}
            stroke="#1e1e1e" strokeWidth={0.5}/>
        })}

        {/* Contour lines */}
        {contours.map((contour, i) => {
          const isMajor = contour.elevation % 5 === 0
          const pts = contour.points
          if (pts.length < 2) return null
          const d = pts.map((p, j) =>
            `${j === 0 ? 'M' : 'L'}${toX(p.easting).toFixed(1)},${toY(p.northing).toFixed(1)}`
          ).join(' ')
          return (
            <path key={`contour-${contour.elevation}`} d={d} fill="none"
              stroke={elevColor(contour.elevation)}
              strokeWidth={isMajor ? 1.2 : 0.6}
              opacity={isMajor ? 0.9 : 0.6}
            />
          )
        })}

        {/* Elevation labels on major contours */}
        {contours
          .filter((c) => c.elevation % 5 === 0 && c.points.length > 0)
          .slice(0, 20)
          .map((contour, i) => {
            const p = contour.points[Math.floor(contour.points.length / 2)]
            if (!p) return null
            return (
              <text key={`${contour}-${i}`} x={toX(p.easting)} y={toY(p.northing)}
                fill="rgba(255,255,255,0.7)" fontSize={8} textAnchor="middle"
                style={{ paintOrder: 'stroke', stroke: '#0a0a0f', strokeWidth: 3 }}>
                {contour.elevation}
              </text>
            )
          })}

        {/* Survey points */}
        {points.map((p) => (
          <g key={p.name}>
            <circle cx={toX(p.easting)} cy={toY(p.northing)} r={3}
              fill={elevColor(p.elevation)} stroke="white" strokeWidth={0.8}/>
            <text x={toX(p.easting) + 5} y={toY(p.northing) - 5}
              fill="rgba(255,255,255,0.8)" fontSize={7}>
              {p.name}
            </text>
          </g>
        ))}

        {/* Legend */}
        <g transform={`translate(${width - 90}, 16)`}>
          <rect x={0} y={0} width={80} height={70} rx={6}
            fill="rgba(0,0,0,0.75)" stroke="#2a2a2a" strokeWidth={0.5}/>
          <text x={40} y={16} fill="rgba(255,255,255,0.7)" fontSize={8}
            textAnchor="middle" fontWeight="600">Elevation</text>
          {[maxElev, (minElev + maxElev) / 2, minElev].map((elev, i) => (
            <g key={`${elev}-${i}`} transform={`translate(8, ${28 + i * 14})`}>
              <rect x={0} y={-6} width={12} height={8} rx={2} fill={elevColor(elev)}/>
              <text x={18} y={0} fill="rgba(255,255,255,0.6)" fontSize={7}>
                {elev.toFixed(1)} m
              </text>
            </g>
          ))}
        </g>
      </svg>

      <div className="mt-4 flex gap-3 flex-wrap">
        <button onClick={handleExportDXF}
          className="btn btn-primary text-sm">
          Export DXF
        </button>
        <button className="btn btn-secondary text-sm">
          Export PNG
        </button>
      </div>
    </div>
  )
}

'use client';

import { useEffect, useState, useCallback } from 'react'
import { useParams, useRouter, useSearchParams } from 'next/navigation'
import { createClient } from '@/lib/api-client/client'
import { z } from 'zod'
import { apiGet, apiPost, ApiError } from '@/lib/api/client'
import type {
  EngineeringData,
  EngineeringMode,
  EngineeringStandard,
  RoadDesignData,
  DrainageData,
  StationData,
  IntersectionPoint,
  VerticalIP,
  CrossSectionTemplate,
} from '@/types/engineering'
import type { SurveyorProfileSubmission } from '@/lib/api-client/community'
import MobileDesktopNotice from '@/components/MobileDesktopNotice'
import type { EngineeringProject, EngineeringStepId } from './shared'
import { getEngineeringSteps } from './getEngineeringSteps'
import { renderStepContent } from './steps/renderStepContent'
import { QuickComputeTab } from './QuickComputeTab'

// ponytail: response schemas — Phase 4 wave 2 will move these to src/lib/api/schemas/

// GET /api/engineering/alignment returns { data: <alignment row or null> }.
// Use z.union([schema, z.null()]) instead of .nullable() so we keep .passthrough() on the inner object.
const alignmentRowSchema = z.object({
  id: z.union([z.string(), z.number()]),
  road_name: z.string().nullable().optional(),
  start_chainage: z.union([z.number(), z.string(), z.null()]).optional(),
  datum: z.string().nullable().optional(),
  coordinate_system: z.string().nullable().optional(),
  design_speed: z.union([z.number(), z.string(), z.null()]).optional(),
  road_class: z.string().nullable().optional(),
  standard: z.string().nullable().optional(),
  cross_section_template: z.any().optional(),
  ips: z.array(z.any()).optional(),
  vips: z.array(z.any()).optional(),
  stations: z.array(z.any()).optional(),
}).passthrough()

const alignmentResponseSchema = z.object({
  data: z.union([alignmentRowSchema, z.null()]),
}).passthrough()

// POST /api/engineering/alignment returns { data: { id, ... } }
const alignmentMutationSchema = z.object({
  data: alignmentRowSchema,
}).passthrough()

// The three sub-resource POSTs return various shapes — accept any object payload.
const subResourceMutationSchema = z.record(z.any())

interface CrossSectionTemplateRow {
  carriageway_width?: number | string | null
  carriagewayWidth?: number | string | null
  shoulder_width?: number | string | null
  shoulderWidth?: number | string | null
  cut_slope?: string | null
  cutSlope?: string | null
  fill_slope?: string | null
  fillSlope?: string | null
  camber?: number | string | null
  subgrade_depth?: number | string | null
  subgradeDepth?: number | string | null
}

interface EngineeringIpRow {
  id: string | number
  name: string | null
  easting: number | string | null
  northing: number | string | null
  radius: number | string | null
  deflection_angle?: number | string | null
  tangent_length?: number | string | null
  arc_length?: number | string | null
  chainage_tc?: number | string | null
  chainage_mc?: number | string | null
  chainage_ct?: number | string | null
  sort_order?: number | string | null
}

interface EngineeringVipRow {
  id: string | number
  chainage: number | string | null
  reduced_level: number | string | null
  k_value?: number | string | null
}

interface EngineeringStationRow {
  chainage: number | string | null
  ground_level: number | string | null
}

interface EngineeringAlignmentRow {
  id: string | number
  road_name?: string | null
  start_chainage?: number | string | null
  datum?: string | null
  coordinate_system?: string | null
  design_speed?: number | string | null
  road_class?: string | null
  standard?: string | null
  cross_section_template?: CrossSectionTemplateRow | null
  ips?: EngineeringIpRow[]
  vips?: EngineeringVipRow[]
  stations?: EngineeringStationRow[]
}

interface ProjectDbRow {
  id: string
  user_id?: string | null
  engineering_data?: unknown
  [key: string]: unknown
}

interface SurveyorProfileDbRow {
  isk_number?: string | null
  verified_isk?: boolean | null
  full_name?: string | null
  name?: string | null
  firm_name?: string | null
  company?: string | null
}

export default function EngineeringWorkspacePage() {
  const params = useParams<{ id: string }>()
  const router = useRouter()
  const searchParams = useSearchParams()
  const dbClient = createClient()

  const [project, setProject] = useState<EngineeringProject | null>(null)
  const [surveyorProfile, setSurveyorProfile] = useState<SurveyorProfileSubmission | null>(null)
  const [loading, setLoading] = useState(true)
  const [loadingEngineering, setLoadingEngineering] = useState(false)
  const [activeStep, setActiveStep] = useState<EngineeringStepId>('setup')
  const [saving, setSaving] = useState(false)
  const [quickMode, setQuickMode] = useState(false)
  const [alignmentId, setAlignmentId] = useState<string | null>(null)

  // Sub-tab for quick compute panels
  const activeTab = searchParams.get('tab') || 'workflow'

  // --- Load engineering data from the relational DB backend ---
  const loadEngineeringData = useCallback(async (projectId: string) => {
    setLoadingEngineering(true)
    try {
      const result = await apiGet(
        `/api/engineering/alignment?project_id=${projectId}`,
        alignmentResponseSchema,
        { ttlMs: 0 },
      )
      const dbData = result.data as EngineeringAlignmentRow | null

      if (!dbData) {
        // No alignment row yet — nothing to hydrate
        setLoadingEngineering(false)
        return
      }

      // Store the alignment ID for subsequent saves (IPs, VIPs, stations)
      setAlignmentId(String(dbData.id))

      // Map DB column names → TypeScript shape
      const crossSectionTemplate: CrossSectionTemplate | undefined = dbData.cross_section_template
        ? {
            carriagewayWidth: Number(dbData.cross_section_template.carriageway_width ?? dbData.cross_section_template.carriagewayWidth ?? 6.0),
            shoulderWidth: Number(dbData.cross_section_template.shoulder_width ?? dbData.cross_section_template.shoulderWidth ?? 1.0),
            cutSlope: String(dbData.cross_section_template.cut_slope ?? dbData.cross_section_template.cutSlope ?? '1:1'),
            fillSlope: String(dbData.cross_section_template.fill_slope ?? dbData.cross_section_template.fillSlope ?? '1:1.5'),
            camber: Number(dbData.cross_section_template.camber ?? 3),
            subgradeDepth: Number(dbData.cross_section_template.subgrade_depth ?? dbData.cross_section_template.subgradeDepth ?? 0.5),
          }
        : undefined

      const ips: IntersectionPoint[] = (dbData.ips || []).map((row) => ({
        id: String(row.id),
        name: String(row.name),
        easting: Number(row.easting),
        northing: Number(row.northing),
        radius: Number(row.radius),
        deflectionAngle: row.deflection_angle != null ? Number(row.deflection_angle) : undefined,
        tangentLength: row.tangent_length != null ? Number(row.tangent_length) : undefined,
        arcLength: row.arc_length != null ? Number(row.arc_length) : undefined,
        chainageTC: row.chainage_tc != null ? Number(row.chainage_tc) : undefined,
        chainageMC: row.chainage_mc != null ? Number(row.chainage_mc) : undefined,
        chainageCT: row.chainage_ct != null ? Number(row.chainage_ct) : undefined,
        sortOrder: row.sort_order != null ? Number(row.sort_order) : undefined,
      }))

      const vips: VerticalIP[] = (dbData.vips || []).map((row) => ({
        id: String(row.id),
        chainage: Number(row.chainage),
        reducedLevel: Number(row.reduced_level),
        kValue: row.k_value != null ? Number(row.k_value) : undefined,
      }))

      const stations: StationData[] = (dbData.stations || []).map((row) => ({
        chainage: Number(row.chainage),
        groundLevel: Number(row.ground_level),
      }))

      // Build a RoadDesignData object from the DB row
      const roadFromDb: RoadDesignData = {
        roadName: String(dbData.road_name || ''),
        startChainage: Number(dbData.start_chainage ?? 0),
        datum: String(dbData.datum || 'Arc 1960'),
        coordinateSystem: String(dbData.coordinate_system || 'UTM Zone 37S'),
        designSpeed: Number(dbData.design_speed ?? 60),
        roadClass: String(dbData.road_class || 'C') as RoadDesignData['roadClass'],
        standard: (dbData.standard || 'KRDM2017') as EngineeringStandard,
        ips,
        vips,
        crossSectionTemplate: crossSectionTemplate || {
          carriagewayWidth: 6.0,
          shoulderWidth: 1.0,
          cutSlope: '1:1',
          fillSlope: '1:1.5',
          camber: 3,
          subgradeDepth: 0.5,
        },
        stations,
      }

      // Merge into the existing engineering_data, preserving mode/drainage
      setProject(prev => {
        if (!prev) return prev
        const current: EngineeringData = prev.engineering_data || { mode: 'road', standard: 'KRDM2017' }
        return {
          ...prev,
          engineering_data: {
            ...current,
            road: roadFromDb,
          },
        }
      })
    } catch {
      /* ignore load error */
    } finally {
      setLoadingEngineering(false)
    }
  }, [])

  const fetchProject = useCallback(async () => {
    setLoading(true)
    const projectResult = (await dbClient
      .from('projects')
      .select('*')
      .eq('id', params.id)
      .single()) as { data: ProjectDbRow | null; error: { message: string } | null }
    const { data, error } = projectResult

    if (error || !data) {
      setLoading(false)
      return
    }

    const engData = (data?.engineering_data ?? null) as EngineeringData | null
    setProject({ ...data, engineering_data: engData } as EngineeringProject)

    const profileResult = (await dbClient
      .from('surveyor_profiles')
      .select('isk_number, verified_isk, full_name, name, firm_name, company')
      .eq('user_id', data.user_id)
      .single()) as { data: SurveyorProfileDbRow | null }
    const profile = profileResult.data

    if (profile) {
      setSurveyorProfile({
        registrationNumber: profile.isk_number ?? '',
        iskNumber: profile.isk_number ?? '',
        verifiedIsk: profile.verified_isk ?? false,
        fullName: profile.full_name ?? profile.name ?? '',
        firmName: profile.firm_name ?? profile.company ?? '',
        isKMemberActive: profile.verified_isk ?? true
      })
    }

    setLoading(false)
  }, [params.id, dbClient])

  useEffect(() => {
    fetchProject()
  }, [fetchProject])

  // Load engineering data from the relational backend after project is fetched
  const projectId = project?.id
  useEffect(() => {
    if (projectId && !loading) {
      loadEngineeringData(projectId)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projectId, loading, loadEngineeringData])

  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null)

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type })
    setTimeout(() => setToast(null), 3000)
  }

  const handleModeChange = async (newMode: EngineeringMode) => {
    if (!project) return
    setSaving(true)

    try {
      const current = project.engineering_data || { mode: 'road' as EngineeringMode, standard: 'KRDM2017' as EngineeringStandard }
      const updated: EngineeringData = {
        ...current,
        mode: newMode,
        standard: current.standard || 'KRDM2017'
      }

      await dbClient
        .from('projects')
        .update({ engineering_data: updated })
        .eq('id', project.id)

      setProject({ ...project, engineering_data: updated })
      setActiveStep('setup')
      showToast('Mode switched successfully')
    } catch {
      showToast('Failed to save. Check your connection and try again.', 'error')
    } finally {
      setSaving(false)
    }
  }

  // --- Save the entire current engineering state to the relational backend ---
  const saveToBackend = useCallback(async (engData: EngineeringData): Promise<boolean> => {
    if (!project) return false
    const road = engData.road
    if (!road) return false

    try {
      // Step 1: Upsert alignment header → get alignment_id
      const templateForDb = road.crossSectionTemplate
        ? {
            carriagewayWidth: road.crossSectionTemplate.carriagewayWidth,
            shoulderWidth: road.crossSectionTemplate.shoulderWidth,
            cutSlope: road.crossSectionTemplate.cutSlope,
            fillSlope: road.crossSectionTemplate.fillSlope,
            camber: road.crossSectionTemplate.camber,
            subgradeDepth: road.crossSectionTemplate.subgradeDepth,
          }
        : {}

      const alignResult = await apiPost(
        '/api/engineering/alignment',
        alignmentMutationSchema,
        {
          project_id: project.id,
          road_name: road.roadName || 'Unnamed Road',
          start_chainage: road.startChainage ?? 0,
          datum: road.datum || 'Arc 1960',
          coordinate_system: road.coordinateSystem || 'UTM Zone 37S',
          design_speed: road.designSpeed ?? 60,
          road_class: road.roadClass || 'C',
          standard: road.standard || 'KRDM2017',
          cross_section_template: templateForDb,
        },
      )
      const aId = alignResult.data?.id
      if (!aId) throw new Error('No alignment ID returned')
      setAlignmentId(String(aId))

      // Step 2: Save IPs (if any)
      if (road.ips && road.ips.length > 0) {
        await apiPost(
          '/api/engineering/ips',
          subResourceMutationSchema,
          {
            alignment_id: aId,
            ips: road.ips.map(ip => ({
              name: ip.name,
              easting: ip.easting,
              northing: ip.northing,
              radius: ip.radius,
            })),
          },
        )
      }

      // Step 3: Save VIPs (if any)
      if (road.vips && road.vips.length > 0) {
        await apiPost(
          '/api/engineering/vips',
          subResourceMutationSchema,
          {
            alignment_id: aId,
            vips: road.vips.map(v => ({
              chainage: v.chainage,
              reduced_level: v.reducedLevel,
              k_value: v.kValue ?? null,
            })),
          },
        )
      }

      // Step 4: Save stations (if any)
      if (road.stations && road.stations.length > 0) {
        await apiPost(
          '/api/engineering/stations',
          subResourceMutationSchema,
          {
            alignment_id: aId,
            stations: road.stations.map(s => ({
              chainage: s.chainage,
              ground_level: s.groundLevel,
            })),
          },
        )
      }

      return true
    } catch {
      return false
    }
  }, [project])

  const handleSave = async (data: Partial<EngineeringData>) => {
    if (!project) return
    setSaving(true)

    try {
      const current = project.engineering_data || { mode: 'road' as EngineeringMode, standard: 'KRDM2017' as EngineeringStandard }

      let updated: EngineeringData
      if (data.mode) {
        updated = {
          ...current,
          mode: data.mode,
          standard: data.standard || current.standard || 'KRDM2017'
        }
      } else {
        updated = {
          ...current,
          mode: current.mode || 'road',
          standard: current.standard || 'KRDM2017',
          road: { ...current.road, ...data.road } as RoadDesignData,
          drainage: { ...current.drainage, ...data.drainage } as DrainageData
        }
      }

      // Save to database (engineering_data JSONB column)
      await dbClient
        .from('projects')
        .update({ engineering_data: updated })
        .eq('id', project.id)

      setProject({ ...project, engineering_data: updated })

      // Also persist to relational backend for road mode
      if (updated.road) {
        const backendOk = await saveToBackend(updated)
        if (backendOk) {
          showToast('Saved successfully')
        } else {
          showToast('Saved locally, but backend sync failed.', 'error')
        }
      } else {
        showToast('Saved successfully')
      }
    } catch {
      showToast('Failed to save. Check your connection and try again.', 'error')
    } finally {
      setSaving(false)
    }
  }

  // Save All handler — persists the full current state to the backend
  const handleSaveAll = async () => {
    if (!project || !project.engineering_data) return
    setSaving(true)
    try {
      // First ensure local state is up to date
      await dbClient
        .from('projects')
        .update({ engineering_data: project.engineering_data })
        .eq('id', project.id)

      if (project.engineering_data.road) {
        const backendOk = await saveToBackend(project.engineering_data)
        if (backendOk) {
          showToast('All engineering data saved to backend')
        } else {
          showToast('Backend sync failed. Local data is preserved.', 'error')
        }
      } else {
        showToast('All data saved')
      }
    } catch {
      showToast('Failed to save. Check your connection and try again.', 'error')
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center">
        <div className="text-zinc-500 animate-pulse">Loading...</div>
      </div>
    )
  }

  if (!project) {
    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center">
        <div className="text-red-400">Project not found</div>
        <button onClick={() => router.push('/dashboard')} className="text-amber-500 mt-4">Back to Dashboard</button>
      </div>
    )
  }

  const steps = getEngineeringSteps(project.engineering_data || null)
  const currentStep = steps.find((s) => s.id === activeStep) || steps[0]
  const mode = project.engineering_data?.mode || 'road'

  // Quick Compute Panel Mode
  if (activeTab !== 'workflow') {
    return (
      <QuickComputeTab
        projectId={params.id}
        project={project}
        surveyorProfile={surveyorProfile}
        activeTab={activeTab}
      />
    )
  }

  return (
    <div className="min-h-screen bg-black text-white">
      <div className="border-b border-zinc-800 bg-zinc-950">
        <div className="max-w-7xl mx-auto px-4 py-3 flex items-center gap-4">
          <button onClick={() => router.push('/dashboard')} className="text-zinc-500 hover:text-zinc-300 text-sm">← Projects</button>
          <div className="flex-1">
            <h1 className="text-sm font-semibold text-white">{project.name}</h1>
            <div className="text-xs text-zinc-500">Engineering Mode • {mode === 'road' ? 'Road Design' : 'Drainage Survey'}</div>
          </div>
          <span className="text-xs px-2 py-1 bg-amber-500/20 text-amber-400 rounded">{mode === 'road' ? 'Road Design' : 'Drainage Survey'}</span>
          <button
            onClick={handleSaveAll}
            disabled={saving || loadingEngineering}
            className="text-xs px-3 py-1 bg-emerald-500/20 text-emerald-400 rounded hover:bg-emerald-500/30 disabled:opacity-40 disabled:cursor-not-allowed font-medium"
          >
            {saving ? 'Saving...' : 'Save All ↓'}
          </button>
          <button
            onClick={() => router.push(`/project/${params.id}/engineering?tab=curves`)}
            className="text-xs px-3 py-1 bg-orange-500/20 text-orange-400 rounded hover:bg-orange-500/30"
          >
            Quick Compute →
          </button>
        </div>
      </div>

      {/* Toast notification */}
      {toast && (
        <div className={`fixed top-4 right-4 z-50 px-4 py-3 rounded-lg shadow-lg text-sm font-medium transition-all ${
          toast.type === 'success' ? 'bg-green-900/90 text-green-300 border border-green-700' : 'bg-red-900/90 text-red-300 border border-red-700'
        }`}>
          {toast.type === 'success' ? ' ' : '[x] '}{toast.message}
        </div>
      )}

      {/* Saving indicator */}
      {(saving || loadingEngineering) && (
        <div className="fixed top-4 left-1/2 -translate-x-1/2 z-50 bg-zinc-800 border border-zinc-600 text-zinc-300 px-4 py-2 rounded-lg text-sm flex items-center gap-2 shadow-lg">
          <svg className="animate-spin h-4 w-4" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"/><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"/></svg>
          {loadingEngineering ? 'Loading engineering data...' : 'Saving...'}
        </div>
      )}

      <div className="max-w-7xl mx-auto flex flex-col lg:flex-row">
        <nav className="w-full lg:w-64 shrink-0 border-b lg:border-b-0 lg:border-r border-zinc-800">
          <div className="p-4">
            <div className="text-xs font-semibold text-zinc-500 uppercase tracking-widest mb-3">Workflow</div>
            <ol className="space-y-1">
              {steps.map((step, idx) => {
                const isActive = step.id === activeStep
                const isLocked = step.status === 'locked'
                return (
                  <li key={step.id}>
                    <button
                      disabled={isLocked}
                      onClick={() => setActiveStep(step.id)}
                      className={`w-full text-left rounded-lg px-3 py-2.5 flex items-start gap-3 ${
                        isActive ? 'bg-zinc-800 border border-zinc-700' :
                        isLocked ? 'opacity-40 cursor-not-allowed' :
                        'hover:bg-zinc-900 border border-transparent'
                      }`}
                    >
                      <span className={`shrink-0 w-6 h-6 rounded-full text-xs flex items-center justify-center mt-0.5 ${
                        step.status === 'complete' ? 'bg-amber-500 text-black' :
                        step.status === 'in_progress' ? 'bg-blue-500 text-white' :
                        step.status === 'locked' ? 'bg-zinc-800 text-zinc-600' :
                        'bg-zinc-700 text-zinc-300'
                      }`}>
                        {step.status === 'complete' ? '' : isLocked ? '[Lock]' : idx + 1}
                      </span>
                      <div className="min-w-0">
                        <div className={`text-sm font-medium ${isLocked ? 'text-zinc-600' : isActive ? 'text-white' : 'text-zinc-300'}`}>
                          {step.label}
                        </div>
                        <div className="text-xs text-zinc-600 truncate">{step.description}</div>
                      </div>
                    </button>
                  </li>
                )
              })}
            </ol>
          </div>
        </nav>

        <main className="flex-1 min-w-0 p-4 lg:p-8">
          <div className="mb-4">
            <MobileDesktopNotice>
              Engineering workflows are desktop-first because they include alignments, long sections, cross sections, and export review. Use mobile for quick reference only.
            </MobileDesktopNotice>
          </div>
          <div className="mb-6">
            <h2 className="text-lg font-semibold text-white">{currentStep?.label}</h2>
          </div>
          <div className="rounded-xl border border-zinc-800 bg-zinc-950 p-6">
            {renderStepContent(currentStep?.id || 'setup', project, project.engineering_data || null, handleSave, handleModeChange)}
          </div>
        </main>
      </div>
    </div>
  )
}

'use client';

import dynamic from 'next/dynamic';
import { useEffect, useState, useCallback } from 'react';
import { createClient } from '@/lib/api-client/client';
import type { AdjustedStation } from '@/lib/engine/planGeometry';

const SurveyMap = dynamic(() => import('@/components/map/SurveyMap'), { ssr: false });

interface MapPageProps {
  params: { id: string };
}

interface BoundaryStationRow {
  pointName?: string | null
  label?: string | null
  id?: string | null
  station?: number | string | null
  originalEasting?: number | null
  originalNorthing?: number | null
  adjustedEasting?: number | null
  adjustedNorthing?: number | null
  easting?: number | null
  northing?: number | null
}
interface ProjectRow {
  boundary_data?: { adjustedStations?: BoundaryStationRow[] } | null
  name?: string | null
  lr_number?: string | null
  surveyor_name?: string | null
  surveyor_license?: string | null
  client_name?: string | null
  county?: string | null
}

export default function MapPage({ params }: MapPageProps) {
  const [stations, setStations] = useState<AdjustedStation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedBeacon, setSelectedBeacon] = useState<{ label: string; easting: number; northing: number } | null>(null);
  const [editingEnabled, setEditingEnabled] = useState(false);
  const [savingVertices, setSavingVertices] = useState(false);
  const [saveMsg, setSaveMsg] = useState<string | null>(null);
  const [projectInfo, setProjectInfo] = useState<{
    name: string;
    lrNumber: string;
    surveyorName: string;
    surveyorLicense: string;
    clientName: string;
    county: string;
  } | null>(null);
  const dbClient = createClient();

  useEffect(() => {
    async function load() {
      const { data: { session } } = await dbClient.auth.getSession();
      if (!session) { setError('Not authenticated'); return; }

      const { data: project, error: projErr } = (await dbClient
        .from('projects')
        .select('boundary_data, id, name, lr_number, surveyor_name, surveyor_license, client_name, county')
        .eq('id', params.id)
        .single()) as { data: ProjectRow | null; error: { message: string; code: string; details?: string } | null };

      if (projErr || !project) {
        setError('Project not found');
        setLoading(false);
        return;
      }

      // Store project metadata for sheet layout
      setProjectInfo({
        name: project.name ?? '',
        lrNumber: project.lr_number ?? '',
        surveyorName: project.surveyor_name ?? '',
        surveyorLicense: project.surveyor_license ?? '',
        clientName: project.client_name ?? '',
        county: project.county ?? '',
      });

      const raw = project.boundary_data?.adjustedStations ?? [];
      if (raw.length < 3) {
        setError('No adjusted traverse data found. Complete the traverse computation first.');
        setLoading(false);
        return;
      }

      const mapped: AdjustedStation[] = raw.map((s: BoundaryStationRow) => ({
        pointName: s.pointName ?? s.label ?? s.id ?? String(s.station ?? ''),
        originalEasting: Number(s.originalEasting ?? s.easting ?? 0),
        originalNorthing: Number(s.originalNorthing ?? s.northing ?? 0),
        adjustedEasting: Number(s.adjustedEasting ?? s.easting ?? 0),
        adjustedNorthing: Number(s.adjustedNorthing ?? s.northing ?? 0),
      }));

      setStations(mapped);
      setLoading(false);
    }

    load();
  }, [params.id]);

  // ── Handle beacon click from the map ─────────────────────────────────────
  const handleBeaconClick = useCallback((label: string, easting: number, northing: number) => {
    setSelectedBeacon({ label, easting, northing });
    // Auto-dismiss after 5 seconds
    setTimeout(() => setSelectedBeacon(null), 5000);
  }, []);

  // ── Handle vertex edits from the map → save back to project ──────────────
  const handleVerticesChange = useCallback(async (updated: Array<{ easting: number; northing: number }>) => {
    if (stations.length === 0 || updated.length === 0) return;

    setSavingVertices(true);
    setSaveMsg(null);

    try {
      // Rebuild adjustedStations with updated coordinates
      const newStations = stations.map((s, i) => {
        if (i < updated.length) {
          return {
            ...s,
            adjustedEasting: updated[i].easting,
            adjustedNorthing: updated[i].northing,
          };
        }
        return s;
      });

      // Fetch current boundary_data to preserve other fields
      const { data: project } = (await dbClient
        .from('projects')
        .select('boundary_data')
        .eq('id', params.id)
        .single()) as { data: { boundary_data?: { adjustedStations?: BoundaryStationRow[] } | null } | null };

      const currentBoundaryData = project?.boundary_data ?? {};
      const updatedBoundaryData = {
        ...currentBoundaryData,
        adjustedStations: newStations.map(s => ({
          pointName: s.pointName,
          originalEasting: s.originalEasting,
          originalNorthing: s.originalNorthing,
          adjustedEasting: s.adjustedEasting,
          adjustedNorthing: s.adjustedNorthing,
        })),
      };

      const { error: updateErr } = await dbClient
        .from('projects')
        .update({ boundary_data: updatedBoundaryData })
        .eq('id', params.id);

      if (updateErr) {
        setSaveMsg('Failed to save vertex changes');
      } else {
        setStations(newStations);
        setSaveMsg('Vertices saved');
      }
    } catch {
      setSaveMsg('Error saving vertex changes');
    } finally {
      setSavingVertices(false);
      setTimeout(() => setSaveMsg(null), 3000);
    }
  }, [stations, params.id, dbClient]);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-full text-sm text-gray-500">
        Loading traverse data...
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-center">
          <p className="text-sm text-red-600 font-medium">{error}</p>
          <p className="text-xs text-gray-500 mt-1">
            Ensure the traverse has been computed and adjusted before viewing the map.
          </p>
        </div>
      </div>
    );
  }

  const sumE = stations.reduce((sum, s) => sum + s.adjustedEasting, 0);
  const sumN = stations.reduce((sum, s) => sum + s.adjustedNorthing, 0);
  const centroidEasting = sumE / stations.length;
  const centroidNorthing = sumN / stations.length;

  return (
    <div className="h-full flex flex-col">
      {/* ── Toolbar strip ──────────────────────────────────────────────── */}
      <div className="flex items-center gap-2 px-3 py-1.5 bg-gray-50 border-b border-gray-200 text-xs">
        <button
          onClick={() => setEditingEnabled(v => !v)}
          className={`px-3 py-1.5 rounded font-medium transition-colors ${
            editingEnabled
              ? 'bg-amber-500 text-white'
              : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-100'
          }`}
          title={editingEnabled ? 'Disable vertex editing' : 'Enable vertex editing — drag vertices to adjust parcel boundary'}
        >
          {editingEnabled ? 'Editing On' : 'Edit Vertices'}
        </button>
        {editingEnabled && (
          <span className="text-amber-600">
            Drag vertices to adjust. Changes save automatically.
          </span>
        )}
        {savingVertices && (
          <span className="text-blue-600">Saving...</span>
        )}
        {saveMsg && (
          <span className={saveMsg.includes('Failed') || saveMsg.includes('Error') ? 'text-red-600' : 'text-green-600'}>
            {saveMsg}
          </span>
        )}
        <div className="flex-1" />
        {selectedBeacon && (
          <div className="flex items-center gap-2 px-2 py-1 bg-blue-50 border border-blue-200 rounded">
            <span className="font-semibold text-blue-800">{selectedBeacon.label}</span>
            <span className="text-blue-600 font-mono">
              E {selectedBeacon.easting.toFixed(3)} | N {selectedBeacon.northing.toFixed(3)}
            </span>
          </div>
        )}
      </div>

      {/* ── Survey Map ─────────────────────────────────────────────────── */}
      <div className="flex-1">
        <SurveyMap
          projectId={params.id}
          adjustedStations={stations}
          centroidEasting={centroidEasting}
          centroidNorthing={centroidNorthing}
          readOnly={!editingEnabled}
          enableEditing={editingEnabled}
          onBeaconClick={handleBeaconClick}
          onVerticesChange={handleVerticesChange}
          lrNumber={projectInfo?.lrNumber}
          projectName={projectInfo?.name}
          surveyorName={projectInfo?.surveyorName}
          surveyorLicense={projectInfo?.surveyorLicense}
          clientName={projectInfo?.clientName}
          county={projectInfo?.county}
        />
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/api-client/client';
import Link from 'next/link';
import { computeChainageTable } from '@/lib/engine/chainage'
import { generateLongitudinalProfileSvg } from '@/lib/reports/profileSvg'
import { logger } from '@/lib/logger'

interface PageProps {
  params: { id: string }
}

interface Project {
  id: string;
  name: string;
  location: string | null;
  utm_zone: number;
  hemisphere: string;
}

interface SurveyPoint {
  id: string;
  name: string;
  easting: number;
  northing: number;
  elevation: number | null;
}

interface Alignment {
  id: string;
  name: string;
  description: string | null;
}

interface ChainagePoint {
  id: string;
  point_name: string;
  chainage: number;
  easting: number;
  northing: number;
  elevation: number;
}

interface CrossSection {
  id: string;
  chainage: number;
  offset_distance: number;
  offset_direction: string;
  elevation: number;
}

export default function ProfilesPage({ params }: PageProps) {
  const dbClient = createClient();
  const [profileError, setProfileError] = useState<string|null>(null)
  const [project, setProject] = useState<Project | null>(null);
  const [points, setPoints] = useState<SurveyPoint[]>([]);
  const [loading, setLoading] = useState(true);
  
  const [alignments, setAlignments] = useState<Alignment[]>([]);
  const [selectedAlignment, setSelectedAlignment] = useState<Alignment | null>(null);
  const [chainagePoints, setChainagePoints] = useState<ChainagePoint[]>([]);
  const [crossSections, setCrossSections] = useState<CrossSection[]>([]);
  
  const [newAlignmentName, setNewAlignmentName] = useState('');
  const [selectedPoints, setSelectedPoints] = useState<SurveyPoint[]>([]);
  const [activeTab, setActiveTab] = useState<'create' | 'profile' | 'cross-sections'>('create');

  const [svgModalOpen, setSvgModalOpen] = useState(false);
  const [svgPage, setSvgPage] = useState<'A3' | 'A4'>('A3');
  const [svgOrientation, setSvgOrientation] = useState<'landscape' | 'portrait'>('landscape');
  const [svgHScale, setSvgHScale] = useState<number>(1000);
  const [svgVScale, setSvgVScale] = useState<number>(100);

  // Close the SVG preview on Escape (document-level, works regardless of focus)
  useEffect(() => {
    if (!svgModalOpen) return
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') setSvgModalOpen(false) }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [svgModalOpen])

  const loadData = useCallback(async () => {
    setLoading(true);
    try {
      const projRes = await dbClient
        .from('projects')
        .select('*')
        .eq('id', params.id)
        .single();
      if (projRes.data) setProject((projRes.data as unknown) as Project);

      const ptsRes = await dbClient
        .from('survey_points')
        .select('*')
        .eq('project_id', params.id)
        .order('name');
      if (ptsRes.data) setPoints((ptsRes.data as unknown) as SurveyPoint[]);

      const alignRes = await dbClient
        .from('alignments')
        .select('*')
        .eq('project_id', params.id)
        .order('created_at', { ascending: false });
      if (alignRes.data) setAlignments((alignRes.data as unknown) as Alignment[]);
    } catch (err) {
      logger.error('Error loading data:', { error: err });
    } finally {
      setLoading(false);
    }
  }, [dbClient, params.id]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const loadAlignmentData = async (alignmentId: string) => {
    const cpRes = await dbClient
      .from('chainage_points')
      .select('*')
      .eq('alignment_id', alignmentId)
      .order('chainage');
    if (cpRes.data) setChainagePoints((cpRes.data as unknown) as ChainagePoint[]);

    const csRes = await dbClient
      .from('cross_sections')
      .select('*')
      .eq('alignment_id', alignmentId)
      .order('chainage');
    if (csRes.data) setCrossSections((csRes.data as unknown) as CrossSection[]);
  };

  const createAlignment = async () => {
    if (!newAlignmentName || selectedPoints.length < 2) return;

    try {
      const alignInsRes = await dbClient
        .from('alignments')
        .insert({
          project_id: params.id,
          name: newAlignmentName
        })
        .select()
        .single();

      const alignment = (alignInsRes.data as unknown) as Alignment;
      if (alignInsRes.error) throw alignInsRes.error;

      const first = selectedPoints[0]
      const table = computeChainageTable({
        start: { easting: first.easting, northing: first.northing },
        startName: first.name,
        startChainage: 0,
        alignment: selectedPoints.slice(1).map((p) => ({ name: p.name, easting: p.easting, northing: p.northing })),
      })

      const byName = new Map(selectedPoints.map((p) => [p.name, p]))
      const chainageData = table.map((row) => {
        const source = byName.get(row.pointName)
        return {
          alignment_id: (alignment as { id: string }).id,
          project_id: params.id,
          point_name: row.pointName,
          chainage: row.chainage,
          easting: row.easting,
          northing: row.northing,
          elevation: source?.elevation ?? 0,
        }
      })

      await dbClient.from('chainage_points').insert(chainageData)

      setNewAlignmentName('');
      setSelectedPoints([]);
      await loadData();
      const typedAlignment = (alignment as unknown) as Alignment;
      setSelectedAlignment(typedAlignment);
      await loadAlignmentData(typedAlignment.id);
      setActiveTab('profile');
    } catch (err) {
      logger.error('Error creating alignment:', { error: err });
      setProfileError('Failed to create alignment. Please try again.');
    }
  };

  const togglePointSelection = (point: SurveyPoint) => {
    if (selectedPoints.find((p) => p.id === point.id)) {
      setSelectedPoints(selectedPoints.filter((p) => p.id !== point.id));
    } else {
      setSelectedPoints([...selectedPoints, point]);
    }
  };

  const handleAlignmentSelect = async (alignment: Alignment) => {
    setSelectedAlignment(alignment);
    await loadAlignmentData(alignment.id);
    setActiveTab('profile');
  };

  const addCrossSection = async (chainage: number) => {
    if (!selectedAlignment) return;

    const centerPoint = chainagePoints.find((cp) => Math.abs(cp.chainage - chainage) < 0.001);
    
    await dbClient.from('cross_sections').insert({
      alignment_id: selectedAlignment.id,
      chainage,
      offset_distance: 0,
      offset_direction: 'center',
      elevation: centerPoint?.elevation || 0
    });

    await loadAlignmentData(selectedAlignment.id);
  };

  const formatChainage = (value: number): string => {
    const km = Math.floor(value / 1000);
    const m = value % 1000;
    return `${km}+${m.toFixed(3).padStart(3, '0')}`;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="text-[var(--accent)]">Loading...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)] text-[var(--text-primary)]">
      <div className="border-b border-[var(--border-color)] bg-[var(--bg-card)]">
        <div className="max-w-7xl mx-auto px-4 py-4">
          <div className="flex items-center justify-between">
            <div>
              <Link href={`/project/${params.id}`} className="text-[var(--accent)] hover:underline text-sm">
                ← Back to Project
              </Link>
              <h1 className="text-2xl font-bold mt-1">Profile Generator</h1>
              <p className="text-[var(--text-muted)] text-sm">{project?.name}</p>
            </div>
            <div className="flex gap-2">
              <button
                onClick={() => setActiveTab('create')}
                className={`px-4 py-2 rounded text-sm font-medium ${
                  activeTab === 'create' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-primary)]'
                }`}
              >
                Create Alignment
              </button>
              <button
                onClick={() => setActiveTab('profile')}
                disabled={!selectedAlignment}
                className={`px-4 py-2 rounded text-sm font-medium ${
                  activeTab === 'profile' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-primary)]'
                } disabled:opacity-50`}
              >
                Longitudinal Profile
              </button>
              <button
                onClick={() => setActiveTab('cross-sections')}
                disabled={!selectedAlignment}
                className={`px-4 py-2 rounded text-sm font-medium ${
                  activeTab === 'cross-sections' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-primary)]'
                } disabled:opacity-50`}
              >
                Cross Sections
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 py-6">
        {activeTab === 'create' && (
          <div className="space-y-6">
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <h2 className="text-lg font-semibold mb-4">Create New Alignment</h2>
              <div className="grid md:grid-cols-3 gap-4">
                <div>
                  <label className="label" htmlFor="alignment-name">Alignment Name</label>
                  <input id="alignment-name"
                    className="input"
                    value={newAlignmentName}
                    onChange={e => setNewAlignmentName(e.target.value)}
 placeholder="e.g., Main Road Centerline"
                  />
                </div>
                <div className="md:col-span-2 flex items-end">
                  <button
                    onClick={createAlignment}
                    disabled={!newAlignmentName || selectedPoints.length < 2}
                    className="px-6 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded disabled:opacity-50"
                  >
                    Create Alignment
                  </button>
                </div>
              </div>
            </div>

            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <h3 className="font-semibold mb-4">Select Points for Alignment (in order)</h3>
              <p className="text-sm text-[var(--text-muted)] mb-4">Click points in the order they appear along the centerline</p>
              <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-2 max-h-64 overflow-y-auto">
                {points.map((point) => (
                  <button
                    key={point.id}
                    onClick={() => togglePointSelection(point)}
                    className={`p-3 rounded text-left transition-colors ${
                      selectedPoints.find((p) => p.id === point.id)
                        ? 'bg-[var(--accent)] text-black'
                        : 'bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)]'
                    }`}
                  >
                    <div className="font-medium">{point.name}</div>
                    <div className="text-xs opacity-75">
                      E: {point.easting.toFixed(0)}
                    </div>
                    <div className="text-xs opacity-75">
                      N: {point.northing.toFixed(0)}
                    </div>
                    {point.elevation && (
                      <div className="text-xs opacity-75">
                        RL: {point.elevation.toFixed(2)}
                      </div>
                    )}
                  </button>
                ))}
              </div>
              {selectedPoints.length > 0 && (
                <div className="mt-4 p-3 bg-[var(--bg-tertiary)]/50 rounded">
                  <span className="text-sm text-[var(--text-secondary)]">Selected: </span>
                  <span className="text-[var(--accent)]">
                    {selectedPoints.map((p) => p.name).join(' → ')}
                  </span>
                </div>
              )}
            </div>

            {alignments.length > 0 && (
              <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
                <h3 className="font-semibold mb-4">Existing Alignments</h3>
                <div className="space-y-2">
                  {alignments.map((alignment) => (
                    <button
                      key={alignment.id}
                      onClick={() => handleAlignmentSelect(alignment)}
                      className="w-full p-3 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] rounded text-left flex justify-between items-center"
                    >
                      <span className="font-medium">{alignment.name}</span>
                      <span className="text-[var(--accent)]">View →</span>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'profile' && selectedAlignment && (
          <div className="space-y-6">
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-lg font-semibold">Longitudinal Profile - {selectedAlignment.name}</h2>
                <button
                  onClick={() => setSvgModalOpen(true)}
                  className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded text-sm"
                >
                  Export SVG
                </button>
              </div>

              {chainagePoints.length > 0 ? (
                <>
                  <ProfileChart points={chainagePoints} />

                  {svgModalOpen && (
                    <div className="fixed inset-0 z-50 bg-black/70 flex items-center justify-center p-4">
                      <button type="button" aria-label="Close preview" tabIndex={-1} className="absolute inset-0 cursor-pointer border-0 p-0" onClick={() => setSvgModalOpen(false)} />
                      <div className="relative w-full max-w-2xl rounded-2xl border border-[var(--border-color)] bg-[var(--bg-secondary)] p-5 shadow-2xl" role="dialog" aria-modal="true" aria-label="Export profile SVG">
                        <div className="flex items-center justify-between mb-4">
                          <div className="text-lg font-semibold text-[var(--text-primary)]">Export profile SVG (to-scale)</div>
                          <button onClick={() => setSvgModalOpen(false)} className="px-3 py-1 rounded bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)]">
                            [x]
                          </button>
                        </div>

                        <div className="grid md:grid-cols-2 gap-4">
                          <div className="rounded-xl bg-[var(--bg-primary)]/40 border border-[var(--border-color)] p-4">
                            <div className="text-xs text-[var(--text-muted)] uppercase tracking-wider mb-2">Page</div>
                            <div className="flex gap-2">
                              <select value={svgPage} onChange={(e) => setSvgPage(e.target.value as 'A3' | 'A4')} className="flex-1 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-[var(--text-primary)]">
                                <option value="A3">A3</option>
                                <option value="A4">A4</option>
                              </select>
                              <select value={svgOrientation} onChange={(e) => setSvgOrientation(e.target.value as 'landscape' | 'portrait')} className="flex-1 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-[var(--text-primary)]">
                                <option value="landscape">Landscape</option>
                                <option value="portrait">Portrait</option>
                              </select>
                            </div>
                            <p className="text-xs text-[var(--text-muted)] mt-2">Print at 100% for true scale.</p>
                          </div>

                          <div className="rounded-xl bg-[var(--bg-primary)]/40 border border-[var(--border-color)] p-4">
                            <div className="text-xs text-[var(--text-muted)] uppercase tracking-wider mb-2">Scales</div>
                            <div className="grid grid-cols-2 gap-2">
                              <label className="text-xs text-[var(--text-secondary)]">
                                Horizontal (1:)
                                <input aria-label="Horizontal scale" inputMode="numeric" value={svgHScale} onChange={(e) => setSvgHScale(parseInt(e.target.value || '1000', 10) || 1000)} className="mt-1 w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-[var(--text-primary)] font-mono" />
                              </label>
                              <label className="text-xs text-[var(--text-secondary)]">
                                Vertical (1:)
                                <input aria-label="Vertical scale" inputMode="numeric" value={svgVScale} onChange={(e) => setSvgVScale(parseInt(e.target.value || '100', 10) || 100)} className="mt-1 w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-[var(--text-primary)] font-mono" />
                              </label>
                            </div>
                            <p className="text-xs text-[var(--text-muted)] mt-2">If a scale won’t fit, METARDU will auto-fit to the nearest standard scale.</p>
                          </div>
                        </div>

                        <div className="mt-5 flex items-center justify-end gap-2">
                          <button onClick={() => setSvgModalOpen(false)} className="px-4 py-2 rounded bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)]">
                            Cancel
                          </button>
                          <button
                            onClick={() => {
                              const svgText = generateLongitudinalProfileSvg(
                                chainagePoints.map((p) => ({ chainage: p.chainage, elevation: p.elevation, label: p.point_name })),
                                {
                                  page: svgPage,
                                  orientation: svgOrientation,
                                  horizontalScaleDenom: svgHScale,
                                  verticalScaleDenom: svgVScale,
                                  title: 'LONGITUDINAL PROFILE',
                                  subtitle: `${project?.name ?? ''} — ${selectedAlignment.name}`.trim(),
                                }
                              );
                              const blob = new Blob([svgText], { type: 'image/svg+xml;charset=utf-8' });
                              const url = URL.createObjectURL(blob);
                              const a = document.createElement('a');
                              a.href = url;
                              a.download = `${selectedAlignment.name}_profile_${svgPage}_${svgOrientation}_H${svgHScale}_V${svgVScale}.svg`;
                              a.click();
                              URL.revokeObjectURL(url);
                              setSvgModalOpen(false);
                            }}
                            className="px-4 py-2 rounded bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold"
                          >
                            Download SVG
                          </button>
                        </div>
                      </div>
                    </div>
                  )}
                  
                  <div className="mt-6 grid grid-cols-4 gap-4">
                    <div className="bg-[var(--bg-tertiary)]/50 p-3 rounded">
                      <div className="text-xs text-[var(--text-muted)]">Start Chainage</div>
                      <div className="text-[var(--accent)] font-mono">{formatChainage(chainagePoints[0]?.chainage || 0)}</div>
                    </div>
                    <div className="bg-[var(--bg-tertiary)]/50 p-3 rounded">
                      <div className="text-xs text-[var(--text-muted)]">End Chainage</div>
                      <div className="text-[var(--accent)] font-mono">{formatChainage(chainagePoints[chainagePoints.length - 1]?.chainage || 0)}</div>
                    </div>
                    <div className="bg-[var(--bg-tertiary)]/50 p-3 rounded">
                      <div className="text-xs text-[var(--text-muted)]">Lowest Point</div>
                      <div className="text-[var(--text-primary)] font-mono">
                        {Math.min(...chainagePoints.map((p) => p.elevation)).toFixed(3)} m
                      </div>
                    </div>
                    <div className="bg-[var(--bg-tertiary)]/50 p-3 rounded">
                      <div className="text-xs text-[var(--text-muted)]">Highest Point</div>
                      <div className="text-[var(--text-primary)] font-mono">
                        {Math.max(...chainagePoints.map((p) => p.elevation)).toFixed(3)} m
                      </div>
                    </div>
                  </div>
                </>
              ) : (
                <p className="text-[var(--text-muted)]">No chainage points found</p>
              )}
            </div>

            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <h3 className="font-semibold mb-4">Chainage Points Table</h3>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-[var(--border-color)]">
                      <th className="text-left py-2 text-[var(--text-secondary)]">Point</th>
                      <th className="text-right py-2 text-[var(--text-secondary)]">Chainage</th>
                      <th className="text-right py-2 text-[var(--text-secondary)]">Easting</th>
                      <th className="text-right py-2 text-[var(--text-secondary)]">Northing</th>
                      <th className="text-right py-2 text-[var(--text-secondary)]">Elevation</th>
                    </tr>
                  </thead>
                  <tbody>
                    {chainagePoints.map((cp, idx) => (
                      <tr key={cp.id} className="border-b border-[var(--border-color)]">
                        <td className="py-2 text-[var(--text-primary)]">{cp.point_name}</td>
                        <td className="py-2 text-right font-mono text-[var(--accent)]">{formatChainage(cp.chainage)}</td>
                        <td className="py-2 text-right font-mono text-[var(--text-primary)]">{cp.easting.toFixed(3)}</td>
                        <td className="py-2 text-right font-mono text-[var(--text-primary)]">{cp.northing.toFixed(3)}</td>
                        <td className="py-2 text-right font-mono text-[var(--text-primary)]">{cp.elevation.toFixed(3)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'cross-sections' && selectedAlignment && (
          <div className="space-y-6">
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <h2 className="text-lg font-semibold mb-4">Cross Sections - {selectedAlignment.name}</h2>
              <p className="text-sm text-[var(--text-muted)] mb-4">
                Select a chainage station to add cross section observations
              </p>

              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-2 mb-6">
                {chainagePoints.map((cp) => {
                  const hasCrossSection = crossSections.some((cs) => Math.abs(cs.chainage - cp.chainage) < 0.001);
                  return (
                    <button
                      key={cp.id}
                      onClick={() => addCrossSection(cp.chainage)}
                      className={`p-3 rounded text-center transition-colors ${
                        hasCrossSection
                          ? 'bg-green-900/30 border border-green-700 text-green-400'
                          : 'bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)]'
                      }`}
                    >
                      <div className="font-mono text-[var(--accent)]">{formatChainage(cp.chainage)}</div>
                      <div className="text-xs mt-1">
                        {hasCrossSection ? 'Has Data' : 'Add XS'}
                      </div>
                    </button>
                  );
                })}
              </div>

              <CrossSectionTable crossSections={crossSections} chainagePoints={chainagePoints} />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function ProfileChart({ points }: { points: ChainagePoint[] }) {
  const width = 800;
  const height = 300;
  const padding = 60;

  if (points.length === 0) return null;

  const elevations = points.map((p) => p.elevation);
  const minElev = Math.min(...elevations);
  const maxElev = Math.max(...elevations);
  const minCh = Math.min(...points.map((p) => p.chainage));
  const maxCh = Math.max(...points.map((p) => p.chainage));
  const chRange = maxCh - minCh || 1;
  const elevRange = maxElev - minElev || 1;

  function toX(ch: number) {
    return padding + ((ch - minCh) / chRange) * (width - padding * 2);
  }

  function toY(elev: number) {
    return height - padding - ((elev - minElev) / elevRange) * (height - padding * 2);
  }

  const pathData = points
    .map((p, i) => `${i === 0 ? 'M' : 'L'} ${toX(p.chainage)} ${toY(p.elevation)}`)
    .join(' ');

  return (
    <svg
      id="profile-svg"
      viewBox={`0 0 ${width} ${height}`}
      preserveAspectRatio="xMidYMid meet"
      fontFamily={'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace'}
      className="bg-[var(--bg-secondary)] rounded border border-amber-500/30 w-full"
    >
      <defs>
        <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
          <path d="M 40 0 L 0 0 0 40" fill="none" stroke="#ffffff" strokeOpacity="0.08" strokeWidth="0.6" />
        </pattern>
      </defs>
      <rect width={width} height={height} fill="#0b1020" />
      <rect width={width} height={height} fill="url(#grid)" />
      
      <path d={pathData} stroke="#D17B47" strokeWidth={2} fill="none"/>
      
      {points.map((p) => (
        <g key={p.id}>
          <circle cx={toX(p.chainage)} cy={toY(p.elevation)} r={4} fill="#D17B47"/>
          <text x={toX(p.chainage)} y={height - 10} fill="white" fontSize={9} textAnchor="middle">
            {Math.round(p.chainage)}
          </text>
          <text x={toX(p.chainage)} y={toY(p.elevation) - 8} fill="white" fontSize={7} textAnchor="middle">
            {p.elevation.toFixed(2)}
          </text>
        </g>
      ))}
      
      <line x1={padding} y1={padding} x2={padding} y2={height - padding} stroke="white" strokeWidth={1}/>
      <line x1={padding} y1={height - padding} x2={width - padding} y2={height - padding} stroke="white" strokeWidth={1}/>
      
      <text x={width / 2} y={height - 5} fill="gray" fontSize={10} textAnchor="middle">
        Chainage (m)
      </text>
      <text x={15} y={height / 2} fill="gray" fontSize={10} textAnchor="middle" transform={`rotate(-90, 15, ${height / 2})`}>
        Elevation (m)
      </text>
      
      <text x={width - padding} y={padding} fill="#D17B47" fontSize={10} fontWeight="bold">
        PROFILE
      </text>
    </svg>
  );
}

function CrossSectionTable({ crossSections, chainagePoints }: { crossSections: CrossSection[]; chainagePoints: ChainagePoint[] }) {
  const groupedSections: { [key: number]: CrossSection[] } = {};
  
  crossSections.forEach((cs) => {
    if (!groupedSections[cs.chainage]) {
      groupedSections[cs.chainage] = [];
    }
    groupedSections[cs.chainage].push(cs);
  });

  const formatChainage = (value: number): string => {
    const km = Math.floor(value / 1000);
    const m = value % 1000;
    return `${km}+${m.toFixed(3).padStart(3, '0')}`;
  };

  if (Object.keys(groupedSections).length === 0) {
    return (
      <div className="text-center py-8 text-[var(--text-muted)]">
        <p>No cross sections added yet.</p>
        <p className="text-sm">Click on a chainage station above to add cross section data.</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {Object.entries(groupedSections).map(([ch, sections]) => {
        const center = sections.find((s) => s.offset_direction === 'center');
        const left = sections.find((s) => s.offset_direction === 'left');
        const right = sections.find((s) => s.offset_direction === 'right');
        
        return (
          <div key={ch} className="bg-[var(--bg-tertiary)]/50 rounded-lg p-4">
            <h4 className="text-[var(--accent)] font-mono mb-2">{formatChainage(parseFloat(ch))}</h4>
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-[var(--border-color)]">
                  <th className="text-left py-1 text-[var(--text-secondary)]">Position</th>
                  <th className="text-right py-1 text-[var(--text-secondary)]">Offset (m)</th>
                  <th className="text-right py-1 text-[var(--text-secondary)]">Elevation (m)</th>
                </tr>
              </thead>
              <tbody>
                <tr className="border-b border-[var(--border-color)]">
                  <td className="py-1 text-[var(--text-primary)]">Left</td>
                  <td className="py-1 text-right font-mono text-[var(--text-primary)]">
                    {left ? left.offset_distance.toFixed(3) : '—'}
                  </td>
                  <td className="py-1 text-right font-mono text-[var(--text-primary)]">
                    {left ? left.elevation.toFixed(3) : '—'}
                  </td>
                </tr>
                <tr className="border-b border-[var(--border-color)] bg-[var(--accent)]/10">
                  <td className="py-1 text-[var(--accent)] font-medium">Center</td>
                  <td className="py-1 text-right font-mono text-[var(--accent)]">0.000</td>
                  <td className="py-1 text-right font-mono text-[var(--accent)]">
                    {center ? center.elevation.toFixed(3) : '—'}
                  </td>
                </tr>
                <tr>
                  <td className="py-1 text-[var(--text-primary)]">Right</td>
                  <td className="py-1 text-right font-mono text-[var(--text-primary)]">
                    {right ? right.offset_distance.toFixed(3) : '—'}
                  </td>
                  <td className="py-1 text-right font-mono text-[var(--text-primary)]">
                    {right ? right.elevation.toFixed(3) : '—'}
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        );
      })}
    </div>
  );
}

'use client';

import { useState, useCallback, useMemo, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useSession } from 'next-auth/react';
import { createClient } from '@/lib/api-client/client';
import { SurveyType } from '@/types/project';
import { SurveyWorkflow } from '@/types/workflow';
import { nextStepIndex } from '@/lib/workflows/workflowRegistry';
import {
  getWorkflowStatus,
  getWorkflowSteps,
  type ProjectWorkflowData,
} from '@/lib/workflows/projectWorkflowEngine';
import WorkflowStepper from '@/components/workspace/WorkflowStepper';
import WorkflowStepPanel from '@/components/workspace/WorkflowStepPanel';
import EnhancedSplitLayout from '@/components/workspace/EnhancedSplitLayout';
import WorkspaceMap from '@/components/workspace/WorkspaceMap';
import ComputationLog from '@/components/workspace/ComputationLog';
import WorkflowQualityGate from '@/components/shared/WorkflowQualityGate';
import WorkflowOverviewPanel from '@/components/shared/WorkflowOverviewPanel';
import { CollaborationPanel } from '@/components/realtime/CollaborationPanel';
import { useCollaboration } from '@/lib/realtime/useCollaboration';
import { QADashboard } from '@/components/dashboard/QADashboard';
import { BatchParcelImport } from '@/components/parcels/BatchParcelImport';

interface ProjectProps {
  id: string;
  name: string;
  surveyType: SurveyType;
  workflowStep: number;
  maxUnlocked: number;
}

interface Props {
  project: ProjectProps;
  workflow: SurveyWorkflow;
}

export default function ProjectWorkspaceClient({ project, workflow }: Props) {
  const router = useRouter();
  const dbClient = createClient();
  const { data: session } = useSession();

  const [currentStep, setCurrentStep] = useState(project.workflowStep);
  const [maxUnlocked, setMaxUnlocked] = useState(project.maxUnlocked);
  const [saving, setSaving] = useState(false);

  // Workflow state machine data (fetched from API)
  const [workflowData, setWorkflowData] = useState<ProjectWorkflowData | null>(null);
  const [workflowLoading, setWorkflowLoading] = useState(true);

  // Quality gate state
  const [qualityGateTarget, setQualityGateTarget] = useState<string | null>(null);

  // Overview panel state
  const [overviewOpen, setOverviewOpen] = useState(false);

  // Collaboration state
  const [chatMessages, setChatMessages] = useState<Array<{
    id: string; userId: string; userName: string; message: string; timestamp: number;
  }>>([]);

  const userId = (session?.user as { id?: string })?.id || '';
  const userName = (session?.user as { name?: string })?.name || 'Surveyor';

  const {
    collaborators,
    isConnected,
    sendChat,
    conflictWarnings,
  } = useCollaboration({
    projectId: project.id,
    userId,
    userName,
  });

  // Handle incoming chat messages
  useEffect(() => {
    // The hook calls onChat callback — we set it via a ref pattern
    // For simplicity, we handle chat through the messages state
  }, []);

  const handleSendChat = useCallback((message: string) => {
    const newMsg = {
      id: crypto.randomUUID(),
      userId,
      userName,
      message,
      timestamp: Date.now(),
    };
    setChatMessages(prev => [...prev, newMsg]);
    sendChat(message);
  }, [userId, userName, sendChat]);

  // Fetch workflow status from API on mount
  useEffect(() => {
    let cancelled = false;
    async function fetchStatus() {
      setWorkflowLoading(true);
      try {
        const res = await fetch(`/api/project/${project.id}/workflow`);
        if (res.ok) {
          const json = (await res.json()) as {
            data?: {
              steps?: Array<{ id: string; completionPct?: number }>
            }
          };
          // The API returns the status but we need the raw data for the engine.
          // Build it from the API response + local project state.
          const data: ProjectWorkflowData = {
            id: project.id,
            name: project.name,
            surveyType: project.surveyType,
            location: null, // Not available in the current workspace props
            utmZone: null,
            hemisphere: null,
            currentStep,
            maxUnlocked,
            pointCount: 0,
            fieldbookEntryCount: 0,
            hasComputationResults: false,
            toleranceCheckPassed: null,
            toleranceAcknowledged: false,
            hasDeedPlan: false,
            hasSubmissionPackage: false,
          };

          // If the API returned status, use its computed data to infer richer data
          if (json.data?.steps) {
            // We can extract counts from the step info
            const fieldStep = json.data.steps.find((s: { id: string }) => s.id === 'field-collection');
            if (fieldStep?.completionPct === 100) {
              data.pointCount = 3; // At least 3 if complete
              data.fieldbookEntryCount = 3;
            }
            const computeStep = json.data.steps.find((s: { id: string }) => s.id === 'computation');
            if (computeStep?.completionPct === 100) {
              data.hasComputationResults = true;
            }
            const reviewStep = json.data.steps.find((s: { id: string }) => s.id === 'quality-review');
            if (reviewStep?.completionPct === 100) {
              data.toleranceCheckPassed = true;
            }
            const deedStep = json.data.steps.find((s: { id: string }) => s.id === 'map-deed-plan');
            if (deedStep?.completionPct === 100) {
              data.hasDeedPlan = true;
            }
            const subStep = json.data.steps.find((s: { id: string }) => s.id === 'submission');
            if (subStep?.completionPct === 100) {
              data.hasSubmissionPackage = true;
            }
          }

          if (!cancelled) setWorkflowData(data);
        }
      } catch {
        // API may not be available in all environments — use local fallback
        if (!cancelled) {
          setWorkflowData({
            id: project.id,
            name: project.name,
            surveyType: project.surveyType,
            location: null,
            utmZone: null,
            hemisphere: null,
            currentStep,
            maxUnlocked,
            pointCount: 0,
            fieldbookEntryCount: 0,
            hasComputationResults: false,
            toleranceCheckPassed: null,
            toleranceAcknowledged: false,
            hasDeedPlan: false,
            hasSubmissionPackage: false,
          });
        }
      } finally {
        if (!cancelled) setWorkflowLoading(false);
      }
    }
    fetchStatus();
    return () => { cancelled = true; };
  }, [project.id, project.name, project.surveyType, currentStep, maxUnlocked]);

  const workflowStatus = useMemo(() => {
    if (!workflowData) return null;
    return getWorkflowStatus(workflowData);
  }, [workflowData]);

  const handleStepChange = useCallback(async (newStep: number) => {
    // Check if the target step is unlocked
    const steps = getWorkflowSteps(project.surveyType);
    const targetStepDef = steps.find((s) => s.index === newStep);

    if (!targetStepDef) return;

    // If the step is beyond maxUnlocked, show the quality gate
    if (newStep > maxUnlocked && workflowData) {
      setQualityGateTarget(targetStepDef.id);
      return;
    }

    setSaving(true);
    const newMax = Math.max(maxUnlocked, newStep);

    await dbClient
      .from('projects')
      .update({
        workflow_step: newStep,
        workflow_max_unlocked: newMax,
      })
      .eq('id', project.id);

    setCurrentStep(newStep);
    setMaxUnlocked(newMax);
    setSaving(false);
  }, [project.id, maxUnlocked, dbClient, workflowData, project.surveyType]);

  const handleContinue = async () => {
    const next = nextStepIndex(project.surveyType, currentStep);
    if (next === null) return;

    // Check quality gate via workflow engine
    if (workflowData) {
      const steps = getWorkflowSteps(project.surveyType);
      const nextStepDef = steps.find((s) => s.index === next);
      if (nextStepDef) {
        const status = getWorkflowStatus(workflowData);
        if (!status.canAdvance && next > maxUnlocked) {
          setQualityGateTarget(nextStepDef.id);
          return;
        }
      }
    }

    await handleStepChange(next);

    const nextStepDef = workflow.steps.find((s) => s.index === next);
    if (nextStepDef?.routeSuffix) {
      router.push(`/project/${project.id}/${nextStepDef.routeSuffix}`);
    }
  };

  const handleQualityGateProceed = useCallback(() => {
    setQualityGateTarget(null);
    // User acknowledged warnings — allow the step change
    // This is handled by the quality gate component
  }, []);

  const handleQualityGateNavigate = useCallback((stepId: string) => {
    const steps = getWorkflowSteps(project.surveyType);
    const stepDef = steps.find((s) => s.id === stepId);
    if (stepDef) {
      setQualityGateTarget(null);
      setCurrentStep(stepDef.index);
      router.push(`/project/${project.id}?step=${stepDef.index}`);
    }
  }, [project.id, project.surveyType, router]);

  const handleOverviewStepClick = useCallback((stepId: string) => {
    const steps = getWorkflowSteps(project.surveyType);
    const stepDef = steps.find((s) => s.id === stepId);
    if (stepDef && stepDef.index <= maxUnlocked) {
      setCurrentStep(stepDef.index);
      if (stepDef.routeSuffix) {
        router.push(`/project/${project.id}/${stepDef.routeSuffix}`);
      }
    }
  }, [project.id, maxUnlocked, project.surveyType, router]);

  const currentStepDef = workflow.steps.find((s) => s.index === currentStep);
  const isLastStep = currentStep === workflow.steps[workflow.steps.length - 1].index;
  const nextStep = nextStepIndex(project.surveyType, currentStep);
  const nextStepDef = nextStep !== null ? workflow.steps.find((s) => s.index === nextStep) : null;

  return (
    <div className="min-h-screen bg-[var(--bg-primary)]">
      <div className="bg-[var(--bg-secondary)] border-b border-[var(--border-color)] px-4 py-4">
        <div className="max-w-5xl mx-auto">
          <div className="flex items-center justify-between mb-1">
            <div className="flex items-center gap-3">
              <div>
                <h1 className="text-lg font-bold text-[var(--text-primary)]">{project.name}</h1>
                <p className="text-xs text-[var(--text-muted)]">{workflow.label}</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              {/* Workflow overview toggle button */}
              <button
                type="button"
                onClick={() => setOverviewOpen(!overviewOpen)}
                className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg border border-[var(--border-color)] text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)] transition-colors"
                title="Workflow overview"
              >
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6A2.25 2.25 0 016 3.75h2.25A2.25 2.25 0 0110.5 6v2.25a2.25 2.25 0 01-2.25 2.25H6a2.25 2.25 0 01-2.25-2.25V6zM3.75 15.75A2.25 2.25 0 016 13.5h2.25a2.25 2.25 0 012.25 2.25V18a2.25 2.25 0 01-2.25 2.25H6A2.25 2.25 0 013.75 18v-2.25zM13.5 6a2.25 2.25 0 012.25-2.25H18A2.25 2.25 0 0120.25 6v2.25A2.25 2.25 0 0118 10.5h-2.25a2.25 2.25 0 01-2.25-2.25V6zM13.5 15.75a2.25 2.25 0 012.25-2.25H18a2.25 2.25 0 012.25 2.25V18A2.25 2.25 0 0118 20.25h-2.25A2.25 2.25 0 0113.5 18v-2.25z" />
                </svg>
                Workflow
                {workflowStatus && workflowStatus.overallPct > 0 && (
                  <span className="font-mono text-[10px] text-[var(--text-muted)]">{workflowStatus.overallPct}%</span>
                )}
              </button>
              {saving && <span className="text-xs text-[var(--text-muted)]">Saving…</span>}
            </div>
          </div>
          <div className="mt-4">
            <WorkflowStepper
              projectId={project.id}
              steps={workflow.steps}
              currentStep={currentStep}
              maxUnlocked={maxUnlocked}
              onStepChange={handleStepChange}
            />
          </div>
        </div>
      </div>

      {/* UI-4 (2026-07-24): Wire EnhancedSplitLayout — brings 1,255 LOC of
          dead workspace UI (EnhancedSplitLayout + WorkspaceMap + ComputationLog)
          to life. Desktop: resizable left (workflow 55%) / right (map 45%)
          split with a collapsible computation log at the bottom + a compact
          status bar showing misclosure/precision/area/selection. Mobile:
          stacked layout. The header (WorkflowStepper) stays above; the
          collaboration/QA/batch panels stay below. */}
      <EnhancedSplitLayout
        leftPanel={
          <div className="px-4 py-6 max-w-5xl mx-auto">
            {currentStepDef && (
              <p className="text-sm text-[var(--text-muted)] mb-4">{currentStepDef.description}</p>
            )}

            {/* Blocker warnings from workflow engine */}
            {workflowStatus && workflowStatus.blockers.length > 0 && (
              <div className="mb-4 p-3 rounded-lg bg-amber-500/5 border border-amber-500/20 text-sm">
                <div className="flex items-start gap-2">
                  <svg className="w-4 h-4 text-amber-400 shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126zM12 15.75h.007v.008H12v-.008z" />
                  </svg>
                  <div>
                    <p className="text-amber-400 font-medium mb-1">Workflow Blockers</p>
                    {workflowStatus.blockers.map((b, i) => (
                      <p key={`${b}-${i}`} className="text-amber-400/80 text-xs">{b}</p>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {currentStep < 5 && (
              <WorkflowStepPanel
                projectId={project.id}
                surveyType={project.surveyType}
                stepIndex={currentStep}
                projectName={project.name}
              />
            )}

            {!isLastStep && nextStepDef && (
              <div className="mt-6 flex justify-end">
                <button
                  onClick={handleContinue}
                  disabled={saving}
                  className="px-5 py-2 bg-[var(--accent)] text-black text-sm font-medium rounded hover:bg-[var(--accent-dim)] disabled:opacity-50 transition-colors"
                >
                  Continue to {nextStepDef.label} →
                </button>
              </div>
            )}

            {currentStep === 4 && (
              <div className="mt-6 flex justify-end gap-3">
                <button
                  onClick={() => router.push(`/mobile/field?project=${project.id}`)}
                  className="px-5 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-[var(--text-primary)] text-sm font-medium rounded hover:border-[var(--accent)]/40 transition-colors flex items-center gap-2"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 18h.01M8 21h8a2 2 0 002-2V5a2 2 0 00-2-2H8a2 2 0 00-2 2v14a2 2 0 002 2z" />
                  </svg>
                  Field Collection
                </button>
                <button
                  onClick={() => router.push(`/project/${project.id}/submission`)}
                  className="px-5 py-2 bg-[var(--accent)] text-black text-sm font-medium rounded hover:bg-[var(--accent-dim)] transition-colors"
                >
                  Go to Submission →
                </button>
              </div>
            )}
          </div>
        }
        rightPanel={
          <WorkspaceMap projectId={project.id} projectName={project.name} />
        }
        logPanel={<ComputationLog />}
      />

      {/* Quality Gate Modal */}
      {qualityGateTarget && workflowData && (
        <WorkflowQualityGate
          project={workflowData}
          targetStepId={qualityGateTarget}
          onDismiss={() => setQualityGateTarget(null)}
          onProceedAnyway={handleQualityGateProceed}
          onNavigateToStep={handleQualityGateNavigate}
        />
      )}

      {/* Workflow Overview Panel */}
      {workflowData && (
        <WorkflowOverviewPanel
          project={workflowData}
          isOpen={overviewOpen}
          onToggle={() => setOverviewOpen(!overviewOpen)}
          onStepClick={handleOverviewStepClick}
        />
      )}

      {/* Real-time Collaboration Panel */}
      <div className="max-w-5xl mx-auto px-4 py-4">
        <CollaborationPanel
          collaborators={collaborators}
          isConnected={isConnected}
          messages={chatMessages}
          onSend={handleSendChat}
          conflictWarnings={conflictWarnings}
        />
      </div>

      {/* QA Validation Dashboard */}
      <div className="max-w-5xl mx-auto px-4 py-4">
        <QADashboard projectId={project.id} />
      </div>

      {/* Batch Parcel Import */}
      <div className="max-w-5xl mx-auto px-4 py-4">
        <BatchParcelImport projectId={project.id} />
      </div>
    </div>
  );
}

'use client';

/*
 * PERFORMANCE NOTE — OpenLayers static imports (~700KB vendor-ol chunk)
 * These 14 OL modules are intentionally imported at the top level rather than
 * dynamically imported because the webpack splitChunks config already isolates
 * them into a separate `vendor-ol` chunk.  This page is only navigated to
 * explicitly (not on the initial load path), so the OL chunk is never part of
 * the critical-path bundle.  Dynamic imports would add complexity without
 * measurable benefit since the chunk is already code-split.
 */

import { useEffect, useState, useRef } from 'react'
import { useParams } from 'next/navigation'
import Link from 'next/link'
import Map from 'ol/Map'
import View from 'ol/View'
import TileLayer from 'ol/layer/Tile'
import VectorLayer from 'ol/layer/Vector'
import VectorSource from 'ol/source/Vector'
import XYZ from 'ol/source/XYZ'
import GeoJSON from 'ol/format/GeoJSON'
import { fromLonLat } from 'ol/proj'
import { Style, Fill, Stroke, Text } from 'ol/style'
import CircleStyle from 'ol/style/Circle'
import Overlay from 'ol/Overlay'
import { ArrowLeft, Download } from 'lucide-react'
import type Feature from 'ol/Feature'
import type { FeatureLike } from 'ol/Feature'
import { registerProjections } from '@/lib/map/projection'

const STATUS_COLORS: Record<string, string> = {
  pending: '#6b7280',
  field_complete: '#3b82f6',
  computed: '#22c55e',
  plan_generated: '#f59e0b',
  submitted: '#8b5cf6',
  approved: '#10b981',
}

export default function SchemeMapPage() {
  const params = useParams()
  const projectId = params.id as string
  const mapRef = useRef<HTMLDivElement>(null)
  const mapInstance = useRef<Map | null>(null)
  const popupRef = useRef<HTMLDivElement>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [parcelCount, setParcelCount] = useState(0)

  useEffect(() => {
    if (!mapRef.current || !projectId) return

    setLoading(true)

    // Register EPSG:21037 (Arc 1960 / UTM Zone 37S) before using it for GeoJSON reprojection
    registerProjections()

    // Create map
    const vectorSource = new VectorSource()

    const map = new Map({
      target: mapRef.current,
      layers: [
        new TileLayer({
          source: new XYZ({
            url: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
            maxZoom: 19,
            crossOrigin: 'anonymous',
          }),
        }),
        new VectorLayer({
          source: vectorSource,
          style: (feature: FeatureLike) => {
            const props = feature.getProperties()
            const status = (props.status as string) || 'pending'
            const color = STATUS_COLORS[status] || '#6b7280'
            const geomType = feature.getGeometry()?.getType()

            if (geomType === 'Polygon') {
              return new Style({
                fill: new Fill({ color: color + '40' }), // 25% opacity
                stroke: new Stroke({ color, width: 2.5 }),
                text: new Text({
                  text: String(props.parcel_number || ''),
                  font: 'bold 12px sans-serif',
                  fill: new Fill({ color: '#ffffff' }),
                  stroke: new Stroke({ color: '#000000', width: 3 }),
                }),
              })
            }

            if (geomType === 'Point' && props.type === 'block_label') {
              return new Style({
                text: new Text({
                  text: `Block ${String(props.block_number ?? '')}\n(${String(props.parcel_count ?? '')} parcels)`,
                  font: 'bold 14px sans-serif',
                  fill: new Fill({ color: '#1e40af' }),
                  stroke: new Stroke({ color: '#ffffff', width: 4 }),
                  textAlign: 'center',
                }),
              })
            }

            return new Style({
              image: new CircleStyle({
                radius: 5,
                fill: new Fill({ color }),
                stroke: new Stroke({ color: '#000', width: 1 }),
              }),
            })
          },
        }),
      ],
      view: new View({
        center: fromLonLat([37.0, -1.3]), // Default: central Kenya
        zoom: 15,
      }),
    })

    // Popup overlay
    const overlay = new Overlay({
      element: popupRef.current || undefined,
      autoPan: true,
    })
    map.addOverlay(overlay)

    map.on('click', (evt) => {
      const feature = map.forEachFeatureAtPixel(evt.pixel, f => f)
      if (feature && popupRef.current) {
        const props = feature.getProperties()
        // VULN-002 FIX (security review 2026-08-03): block/parcel numbers and
        // LR numbers are user-entered — render with textContent, never innerHTML.
        const el = popupRef.current
        el.replaceChildren()

        const wrap = document.createElement('div')
        wrap.style.cssText = 'font-size:12px;'

        const title = document.createElement('strong')
        title.textContent = `Block ${String(props.block_number ?? '')} — Parcel ${String(props.parcel_number || '')}`
        wrap.append(title)
        wrap.append(document.createElement('br'))

        if (props.lr_number) {
          const lr = document.createElement('div')
          lr.textContent = `LR: ${String(props.lr_number)}`
          wrap.append(lr)
        }
        if (props.area_ha) {
          const area = document.createElement('div')
          area.textContent = `Area: ${Number(props.area_ha).toFixed(4)} ha`
          wrap.append(area)
        }

        const statusRow = document.createElement('div')
        const statusLabel = document.createTextNode('Status: ')
        const statusSpan = document.createElement('span')
        statusSpan.style.color = STATUS_COLORS[props.status as string] || '#999'
        statusSpan.textContent = String(props.status || 'pending')
        statusRow.append(statusLabel, statusSpan)
        wrap.append(statusRow)

        el.append(wrap)
        el.style.display = 'block'
        overlay.setPosition(evt.coordinate)
      } else if (popupRef.current) {
        popupRef.current.style.display = 'none'
      }
    })

    mapInstance.current = map

    // Fetch scheme GeoJSON
    fetch(`/api/scheme/map?project_id=${projectId}`)
      .then(res => res.json())
      .then((data: { features?: unknown[] }) => {
        if (data.features && data.features.length > 0) {
          const format = new GeoJSON()
          const features = format.readFeatures(data, {
            dataProjection: 'EPSG:21037', // Arc 1960 / UTM Zone 37S (Kenya cadastral datum)
            featureProjection: 'EPSG:3857', // Web Mercator
          })
          vectorSource.addFeatures(features)
          setParcelCount(features.filter(f => f.getGeometry()?.getType() === 'Polygon').length)

          // Zoom to extent
          const extent = vectorSource.getExtent()
          if (extent && extent[0] !== Infinity) {
            map.getView().fit(extent, { padding: [50, 50, 50, 50], maxZoom: 18 })
          }
        }
        setLoading(false)
      })
      .catch(() => {
        setError('Failed to load scheme data')
        setLoading(false)
      })

    return () => {
      map.setTarget(undefined)
    }
  }, [projectId])

  return (
    <div className="min-h-screen bg-gray-950 text-white">
      <div className="flex items-center justify-between px-6 py-4 border-b border-gray-800">
        <div className="flex items-center gap-4">
          <Link
            href={`/project/${projectId}/scheme`}
            className="p-2 hover:bg-gray-800 rounded-lg transition-colors"
          >
            <ArrowLeft className="w-5 h-5 text-gray-400" />
          </Link>
          <div>
            <h1 className="text-xl font-bold">Scheme Map</h1>
            <p className="text-sm text-gray-400">
              {loading ? 'Loading parcels...' : `${parcelCount} parcels shown`}
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <a
            href={`/api/scheme/export/geojson?project_id=${projectId}`}
            className="inline-flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 text-white text-sm rounded-lg transition-colors"
          >
            <Download className="w-4 h-4" />
            GeoJSON
          </a>
          <a
            href={`/api/scheme/export/dxf?project_id=${projectId}`}
            className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm rounded-lg transition-colors"
          >
            <Download className="w-4 h-4" />
            DXF
          </a>
        </div>
      </div>

      {error && (
        <div className="mx-6 mt-4 p-3 bg-red-900/50 border border-red-800 rounded-lg text-red-300 text-sm">
          {error}
        </div>
      )}

      <div className="relative" style={{ height: 'calc(100vh - 80px)' }}>
        <div ref={mapRef} className="w-full h-full" />

        {loading && (
          <div className="absolute inset-0 flex items-center justify-center bg-gray-950/60">
            <div className="flex items-center gap-3 text-gray-300">
              <svg className="w-6 h-6 animate-spin" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
              </svg>
              Loading scheme parcels...
            </div>
          </div>
        )}

        <div
          ref={popupRef}
          className="absolute bg-gray-800 border border-gray-600 rounded-lg p-3 shadow-xl"
          style={{ display: 'none', minWidth: 200 }}
        />

        {/* Legend */}
        <div className="absolute bottom-4 right-4 bg-gray-900/90 backdrop-blur border border-gray-700 rounded-lg p-3">
          <h4 className="text-xs font-semibold text-gray-400 mb-2">STATUS LEGEND</h4>
          {Object.entries(STATUS_COLORS).map(([status, color]) => (
            <div key={status} className="flex items-center gap-2 mb-1">
              <div className="w-3 h-3 rounded-full" style={{ backgroundColor: color }} />
              <span className="text-xs text-gray-300 capitalize">{status.replace('_', ' ')}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

'use client';

import { useEffect, useState, useCallback } from 'react'
import { useParams, useRouter } from 'next/navigation'
import Link from 'next/link'
import {
  ArrowLeft, Plus, LayoutGrid, MapPin, FileText,
  AlertCircle, CheckCircle2, Clock, BarChart3, Download, FolderArchive, Package, Map, Users
} from 'lucide-react'
import { z } from 'zod'
import { apiGet, ApiError } from '@/lib/api/client'
import MobileDesktopNotice from '@/components/MobileDesktopNotice'
import type { SchemeDetails, Block, ParcelStatus } from '@/types/scheme'
import { SCHEME_STATUS_LABELS, PARCEL_STATUS_LABELS, PARCEL_STATUS_COLORS } from '@/types/scheme'
import { logger } from '@/lib/logger'

// ponytail: response schemas — Phase 4 wave 2 will move these to src/lib/api/schemas/

// /api/project/:id may return { data: project } | { project } | bare project
const projectRowSchema = z.object({
  id: z.union([z.number(), z.string()]),
  name: z.string(),
  survey_type: z.string().optional().default(''),
  location: z.string().optional().default(''),
  project_type: z.string().optional().default(''),
  utm_zone: z.union([z.number(), z.string()]).optional().default(37),
  hemisphere: z.string().optional().default('S'),
}).passthrough()

const projectEnvelopeSchema = z.union([
  z.object({ data: projectRowSchema }).passthrough(),
  z.object({ project: projectRowSchema }).passthrough(),
  projectRowSchema,
])

const blocksResponseSchema = z.object({
  data: z.array(z.any()),
}).passthrough()

const parcelsResponseSchema = z.object({
  data: z.array(z.any()),
}).passthrough()

const traverseSummarySchema = z.object({
  data: z.array(z.any()),
  summary: z.object({
    total: z.union([z.number(), z.string()]),
    passed: z.union([z.number(), z.string()]),
    failed: z.union([z.number(), z.string()]),
  }).passthrough(),
}).passthrough()

interface ProjectRow {
  id: number
  name: string
  survey_type: string
  location: string
  project_type: string
  utm_zone: number
  hemisphere: string
}

interface BlockWithCounts extends Block {
  parcel_count: number
  completed_count: number
}

interface TraverseSummaryRow {
  accuracy_class: string
  block_number?: string | number | null
  parcel_number?: string | number | null
  accuracy_order?: string | null
  precision_ratio?: string | number | null
  computed_area_ha?: string | number | null
  status?: string | null
}

interface ParcelStatusRow {
  status: string
}

export default function SchemeWorkspacePage() {
  const params = useParams()
  const router = useRouter()
  const projectId = params.id as string

  const [project, setProject] = useState<ProjectRow | null>(null)
  const [schemeDetails, setSchemeDetails] = useState<SchemeDetails | null>(null)
  const [blocks, setBlocks] = useState<BlockWithCounts[]>([])
  const [parcelCounts, setParcelCounts] = useState<Record<ParcelStatus, number>>({
    pending: 0, field_complete: 0, computed: 0, plan_generated: 0, submitted: 0, approved: 0
  })
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  const fetchSchemeData = useCallback(async () => {
    try {
      setLoading(true)

      // Fetch project via /api/project/:id (accepts 3 envelope shapes)
      let proj: ProjectRow | null = null
      try {
        const pj = await apiGet(`/api/project/${projectId}`, projectEnvelopeSchema, { ttlMs: 30_000 })
        proj = ('data' in pj ? pj.data : 'project' in pj ? pj.project : pj) as ProjectRow
      } catch (err) {
        // 404 / not-ok → fall through to the blocks-existence fallback below
        if (err instanceof ApiError && !err.isNotFound && !err.isUnauthorized) {
          // unexpected error — surface it, but keep trying the fallback so the page can still load
          logger.error('[scheme] project fetch failed:', { error: (err as Error).message })
        }
      }

      if (!proj) {
        // Fallback: probe blocks endpoint — if it returns ok, treat projectId as a scheme project
        try {
          await apiGet(`/api/scheme/blocks?project_id=${projectId}`, blocksResponseSchema, { ttlMs: 0 })
        } catch {
          throw new Error('Failed to load project')
        }
        setProject({ id: parseInt(projectId), name: 'Scheme Project', survey_type: '', location: '', project_type: 'scheme', utm_zone: 37, hemisphere: 'S' } as ProjectRow)
      } else {
        setProject(proj)
      }

      // Fetch blocks with counts via API
      const blocksJson = await apiGet(`/api/scheme/blocks?project_id=${projectId}`, blocksResponseSchema, { ttlMs: 30_000 })
      const blks = (blocksJson.data || []) as BlockWithCounts[]
      setBlocks(blks)

      // Fetch all parcels across all blocks for status counts
      if (blks.length > 0) {
        try {
          const parcelsJson = await apiGet(`/api/scheme/parcels?project_id=${projectId}`, parcelsResponseSchema, { ttlMs: 30_000 })
          const parcels = (parcelsJson.data || []) as ParcelStatusRow[]

          const counts: Record<ParcelStatus, number> = {
            pending: 0, field_complete: 0, computed: 0, plan_generated: 0, submitted: 0, approved: 0
          }
          for (const p of parcels) {
            counts[p.status as ParcelStatus] = (counts[p.status as ParcelStatus] || 0) + 1
          }
          setParcelCounts(counts)
        } catch {
          // Non-fatal — counts just stay zeroed
        }
      }

      // Fetch scheme details (if the API existed — for now we load via blocks endpoint context)
      // The scheme details are loaded when the project was created
    } catch (err: unknown) {
      setError(err instanceof ApiError ? (err as Error).message : ((err as Error).message || 'Failed to load scheme data'))
    } finally {
      setLoading(false)
    }
  }, [projectId])

  useEffect(() => { void fetchSchemeData() }, [fetchSchemeData])

  // Fetch traverse accuracy summary
  useEffect(() => {
    if (!project?.id) return

    apiGet(`/api/scheme/traverse/summary?project_id=${project.id}`, traverseSummarySchema, { ttlMs: 0 })
      .then(result => {
        const { summary } = result
        const rows = (result.data || []) as TraverseSummaryRow[]

        // Update stat cards
        const totalEl = document.getElementById('summary-total')
        const passedEl = document.getElementById('summary-passed')
        const warningEl = document.getElementById('summary-warning')
        const failedEl = document.getElementById('summary-failed')
        if (totalEl) totalEl.textContent = String(summary.total)
        if (passedEl) passedEl.textContent = String(summary.passed)
        if (warningEl) warningEl.textContent = String(rows.filter((r) => r.accuracy_class === 'warning').length + rows.filter((r) => r.accuracy_class === 'pending').length)
        if (failedEl) failedEl.textContent = String(summary.failed)

        // Render table
        // VULN-002 FIX (security review 2026-08-03): block/parcel numbers and
        // statuses are user-entered — build the table with createElement +
        // textContent, never innerHTML (stored-XSS guard).
        const tableEl = document.getElementById('traverse-table')
        if (tableEl && rows.length > 0) {
          tableEl.replaceChildren()

          const table = document.createElement('table')
          table.className = 'w-full text-sm'

          const thead = document.createElement('thead')
          const headRow = document.createElement('tr')
          headRow.className = 'text-left text-gray-400 border-b border-gray-700'
          for (const header of ['Block', 'Parcel', 'Order', 'Precision', 'Area (ha)', 'Status']) {
            const th = document.createElement('th')
            th.className = 'pb-2'
            th.textContent = header
            headRow.append(th)
          }
          thead.append(headRow)
          table.append(thead)

          const tbody = document.createElement('tbody')
          const colorMap: Record<string, string> = { pass: 'text-green-400', warning: 'text-yellow-400', fail: 'text-red-400', pending: 'text-gray-500' }
          for (const r of rows) {
            const color = colorMap[r.accuracy_class] || 'text-gray-500'
            const tr = document.createElement('tr')
            tr.className = 'border-b border-gray-800'

            const td = (text: string, cls: string) => {
              const cell = document.createElement('td')
              cell.className = cls
              cell.textContent = text
              return cell
            }

            tr.append(td(String(r.block_number ?? ''), 'py-2 text-white'))
            tr.append(td(String(r.parcel_number ?? ''), 'py-2 text-white'))
            tr.append(td(String(r.accuracy_order || 'Not computed'), `py-2 ${color} font-medium`))
            tr.append(td(r.precision_ratio ? '1:' + Number(r.precision_ratio).toLocaleString() : '-', 'py-2 text-gray-300'))
            tr.append(td(r.computed_area_ha ? Number(r.computed_area_ha).toFixed(4) : '-', 'py-2 text-gray-300'))

            const statusTd = document.createElement('td')
            statusTd.className = 'py-2'
            const badge = document.createElement('span')
            badge.className = `px-2 py-1 rounded text-xs ${
              r.status === 'computed' ? 'bg-green-900 text-green-300'
                : r.status === 'draft' ? 'bg-gray-700 text-gray-300'
                  : 'bg-blue-900 text-blue-300'
            }`
            badge.textContent = String(r.status || 'draft')
            statusTd.append(badge)
            tr.append(statusTd)

            tbody.append(tr)
          }
          table.append(tbody)
          tableEl.append(table)
        } else if (tableEl) {
          tableEl.replaceChildren()
          const p = document.createElement('p')
          p.className = 'text-gray-500 text-sm'
          p.textContent = 'No traverses computed yet'
          tableEl.append(p)
        }
      })
      .catch(() => {
        const tableEl = document.getElementById('traverse-table')
        if (tableEl) {
          tableEl.replaceChildren()
          const p = document.createElement('p')
          p.className = 'text-red-400 text-sm'
          p.textContent = 'Failed to load traverse summary'
          tableEl.append(p)
        }
      })
  }, [project?.id])

  if (loading) {
    return (
      <div className="min-h-[calc(100vh-8rem)] bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="flex items-center gap-3 text-[var(--text-muted)]">
          <svg className="w-6 h-6 animate-spin" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
          </svg>
          Loading scheme workspace...
        </div>
      </div>
    )
  }

  if (error && !project) {
    return (
      <div className="min-h-[calc(100vh-8rem)] bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="text-center space-y-3">
          <AlertCircle className="w-10 h-10 text-red-400 mx-auto" />
          <p className="text-[var(--text-secondary)]">{error}</p>
          <Link href="/dashboard" className="text-sm text-[var(--accent)] hover:underline">Back to Dashboard</Link>
        </div>
      </div>
    )
  }

  const totalParcels = Object.values(parcelCounts).reduce((a, b) => a + b, 0)

  return (
    <div className="min-h-[calc(100vh-8rem)] bg-[var(--bg-primary)]">
      <main className="max-w-6xl mx-auto px-4 py-8">
        <div className="mb-4">
          <MobileDesktopNotice>
            Scheme workspaces include block tables, parcel status review, batch deed plan ZIPs, and submission packages. Use mobile for monitoring; use desktop for final generation and review.
          </MobileDesktopNotice>
        </div>
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-sm text-[var(--text-muted)] mb-6">
          <Link href="/dashboard" className="hover:text-[var(--accent)] transition-colors">Dashboard</Link>
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
          <span className="text-[var(--text-primary)]">{project?.name || 'Scheme Project'}</span>
        </div>

        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4 mb-8">
          <div>
            <div className="flex items-center gap-3 mb-1">
              <h1 className="text-2xl font-bold text-[var(--text-primary)]">{project?.name}</h1>
              <span className="px-2.5 py-0.5 bg-orange-500/10 border border-orange-500/30 text-orange-400 text-xs font-medium rounded-full">
                Scheme
              </span>
            </div>
            {project?.location && (
              <p className="text-sm text-[var(--text-secondary)]">{project.location}</p>
            )}
            <div className="flex items-center gap-4 mt-2 text-xs text-[var(--text-muted)]">
              <span className="flex items-center gap-1">
                <LayoutGrid className="w-3 h-3" />
                {blocks.length} block{blocks.length !== 1 ? 's' : ''}
              </span>
              <span className="flex items-center gap-1">
                <BarChart3 className="w-3 h-3" />
                {totalParcels} parcel{totalParcels !== 1 ? 's' : ''}
              </span>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <Link
              href={`/project/${projectId}/scheme/blocks`}
              className="px-4 py-2 text-sm bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded-lg transition-all flex items-center gap-2"
            >
              <Plus className="w-4 h-4" />
              Manage Blocks
            </Link>
            <Link
              href={`/project/${projectId}/scheme/map`}
              className="inline-flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg text-sm font-medium transition-colors"
            >
              <Map className="w-4 h-4" />
              View Scheme Map
            </Link>
            <Link
              href={`/project/${projectId}/scheme/team`}
              className="inline-flex items-center gap-2 px-4 py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-lg text-sm font-medium transition-colors"
            >
              <Users className="w-4 h-4" />
              Team & Workflow
            </Link>
            {totalParcels > 0 && (
              <div className="flex items-center gap-2">
                <a
                  href={`/api/scheme/batch?project_id=${projectId}`}
                  className="px-3 py-2 text-sm border border-[var(--border-color)] rounded-lg text-[var(--text-secondary)] hover:bg-[var(--bg-secondary)] transition-colors flex items-center gap-2"
                  title="Download all deed plans as ZIP"
                >
                  <FolderArchive className="w-4 h-4" />
                  Batch Deed Plans
                </a>
                <a
                  href={`/api/scheme/rim?project_id=${projectId}`}
                  target="_blank"
                  className="px-3 py-2 text-sm border border-orange-500/30 text-orange-400 rounded-lg hover:bg-orange-500/5 transition-colors flex items-center gap-2"
                  title="Download Registry Index Map"
                >
                  <Download className="w-4 h-4" />
                  RIM
                </a>
                <a
                  href={`/api/scheme/submission?project_id=${projectId}`}
                  className="px-3 py-2 text-sm bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 rounded-lg hover:bg-emerald-500/20 transition-colors flex items-center gap-2"
                  title="Download complete submission package (ZIP with all deed plans, forms, RIM, summary)"
                >
                  <Package className="w-4 h-4" />
                  Full Submission
                </a>
              </div>
            )}
          </div>
        </div>

        {/* Stats Row */}
        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-3 mb-8">
          <StatCard
            label="Blocks"
            value={String(blocks.length)}
            icon={<LayoutGrid className="w-4 h-4" />}
            color="text-blue-400"
          />
          <StatCard
            label="Total Parcels"
            value={String(totalParcels)}
            icon={<BarChart3 className="w-4 h-4" />}
            color="text-[var(--accent)]"
          />
          {(Object.entries(PARCEL_STATUS_LABELS) as [ParcelStatus, string][]).map(([status, label]) => {
            if (parcelCounts[status] === 0) return null
            return (
              <StatCard
                key={status}
                label={label}
                value={String(parcelCounts[status])}
                icon={<CheckCircle2 className="w-4 h-4" />}
                color={status === 'approved' ? 'text-emerald-400' : status === 'submitted' ? 'text-purple-400' : status === 'plan_generated' ? 'text-green-400' : status === 'computed' ? 'text-yellow-400' : 'text-[var(--text-secondary)]'}
              />
            )
          })}
        </div>

        {/* Error Banner */}
        {error && (
          <div className="mb-6 p-3.5 bg-red-900/20 border border-red-500/30 rounded-lg text-sm text-red-400 flex items-center gap-2">
            <AlertCircle className="w-5 h-5 shrink-0" />
            {error}
          </div>
        )}

        {/* Traverse Accuracy Summary */}
        {blocks.length > 0 && (
          <div className="mt-6 bg-gray-900 border border-gray-800 rounded-xl p-6">
            <h3 className="text-lg font-semibold text-white mb-4">Traverse Accuracy Summary</h3>
            <div id="traverse-summary" className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="bg-gray-800 rounded-lg p-4 text-center">
                <div className="text-2xl font-bold text-blue-400" id="summary-total">--</div>
                <div className="text-sm text-gray-400">Total Parcels</div>
              </div>
              <div className="bg-gray-800 rounded-lg p-4 text-center">
                <div className="text-2xl font-bold text-green-400" id="summary-passed">--</div>
                <div className="text-sm text-gray-400">Passed</div>
              </div>
              <div className="bg-gray-800 rounded-lg p-4 text-center">
                <div className="text-2xl font-bold text-yellow-400" id="summary-warning">--</div>
                <div className="text-sm text-gray-400">Review Needed</div>
              </div>
