'use client';

import { ToolExportButtons } from '@/components/shared/ToolExportButtons'
import { useState } from 'react';
import { PageHeader } from '@/components/shared/PageHeader';
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer';
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder';
import { bearingSolvedFromCoords, backBearingSolved } from '@/lib/engine/solution/wrappers/bearing';
import { useLanguage } from '@/lib/i18n/LanguageContext'

export default function BearingCalculator() {
  const { t } = useLanguage()
  const [mode, setMode] = useState<'coords' | 'forward'>('coords');
  const [p1, setP1] = useState({ n: '', e: '' });
  const [p2, setP2] = useState({ n: '', e: '' });
  const [forward, setForward] = useState('');
  const [steps, setSteps] = useState<SolutionStep[] | null>(null);
  const [calcError, setCalcError] = useState<string | null>(null);
  const [solutionTitle, setSolutionTitle] = useState<string | undefined>(undefined);

  const calculate = () => {
    if (mode === 'coords') {
      const n1 = parseFloat(p1.n), e1 = parseFloat(p1.e);
      const n2 = parseFloat(p2.n), e2 = parseFloat(p2.e);
      if (isNaN(n1) || isNaN(e1) || isNaN(n2) || isNaN(e2)) return;
      const s = bearingSolvedFromCoords({ e1, n1, e2, n2 })
      setSteps(s.steps); setSolutionTitle(s.solution.title)
    } else {
      const s = backBearingSolved({ bearingDmsOrDeg: forward })
      setSteps(s.steps); setSolutionTitle(s.solution.title)
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.bearingCalc')}
        subtitle={t('tools.bearingCalcDesc')}
        reference="Survey Regulations 1994 | Survey Act Cap 299 | WCB in degrees 0–360°"
      />

      <div className="flex gap-4 mb-6">
        <button onClick={() => { setMode('coords'); setSteps(null); setSolutionTitle(undefined); }} className={`btn ${mode === 'coords' ? 'btn-primary' : 'btn-secondary'}`}>
          From Coordinates
        </button>
        <button onClick={() => { setMode('forward'); setSteps(null); setSolutionTitle(undefined); }} className={`btn ${mode === 'forward' ? 'btn-primary' : 'btn-secondary'}`}>
          Back Bearing
        </button>
      </div>

      <div className="grid md:grid-cols-2 gap-8">
        <div className="space-y-6">
          {mode === 'coords' ? (
            <div className="card">
              <div className="card-header"><span className="label">Calculate WCB A → B</span></div>
              <div className="card-body space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="label" htmlFor="point-a-northing-m">Point A Northing (m)</label>
                    <input id="point-a-northing-m" aria-label="Point A Northing (m)" className="input" value={p1.n} onChange={e => setP1({...p1, n: e.target.value})} />
                  </div>
                  <div>
                    <label className="label" htmlFor="point-a-easting-m">Point A Easting (m)</label>
                    <input id="point-a-easting-m" aria-label="Point A Easting (m)" className="input" value={p1.e} onChange={e => setP1({...p1, e: e.target.value})} />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="label" htmlFor="point-b-northing-m">Point B Northing (m)</label>
                    <input id="point-b-northing-m" aria-label="Point B Northing (m)" className="input" value={p2.n} onChange={e => setP2({...p2, n: e.target.value})} />
                  </div>
                  <div>
                    <label className="label" htmlFor="point-b-easting-m">Point B Easting (m)</label>
                    <input id="point-b-easting-m" aria-label="Point B Easting (m)" className="input" value={p2.e} onChange={e => setP2({...p2, e: e.target.value})} />
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="card">
              <div className="card-header"><span className="label">Back Bearing Calculation</span></div>
              <div className="card-body space-y-4">
                <div>
                  <label className="label" htmlFor="forward-bearing-wcb-degrees-or-dms">Forward Bearing (WCB — degrees or DMS)</label>
                  <input id="forward-bearing-wcb-degrees-or-dms" className="input" value={forward} onChange={e => setForward(e.target.value)} placeholder="45° 30' 22.5&quot; or 45.5" />
                  <p className="text-xs text-[var(--text-muted)] mt-2">Accepts: 45.5 &nbsp;|&nbsp; 45°30&apos;22.5&quot; &nbsp;|&nbsp; 45 30 22.5</p>
                </div>
              </div>
            </div>
          )}

          <button onClick={calculate} className="btn btn-primary w-full">{t('toolUI.calculate')}</button>
        </div>

        {steps ? <SolutionStepsRenderer title={solutionTitle} steps={steps} /> : null}
      </div>
    </div>
  );
}

'use client'

// State + handlers for the Cassini ↔ UTM converter tool.
//
// Extracted from src/app/tools/cassini-utm/page.tsx as a custom hook so
// the page component stays a thin orchestrator. All React state, refs and
// event handlers live here.

import { useState, useMemo, useCallback, useRef } from 'react'
import {
  KENYA_TOPO_SHEETS,
  KENYA_SUB_SHEETS,
  SHEETS_WITH_SUBSHEETS,
  cassiniFeetToUTM,
  utmToCassiniFeet,
  verifyWithCommonPoints,
  utmToWGS84,
  estimateSheetAccuracy,
  computeHelmert4Params,
  convertCassiniToUTM,
  convertUTMToCassini,
  findSubSheet,
  estimateSubSheetAccuracy,
  getUtmZone,
} from '@/lib/geo/cassini'
import type {
  CassiniFeetPoint,
  UTMPoint,
  ConversionResult,
  TopoSheetParams,
  VerificationResult,
  CommonPoint,
  SubSheetDef,
  TransformMethod,
} from '@/lib/geo/cassini'
import { CASSINI_BATCH_EXAMPLE, UTM_BATCH_EXAMPLE, r1, r3 } from './formatHelpers'

export function useCassiniUtmState() {
  // ── Direction ──
  const [direction, setDirection] = useState<'cassini-to-utm' | 'utm-to-cassini'>('cassini-to-utm')

  // ── Sheet Search ──
  const [sheetSearch, setSheetSearch] = useState('')

  // ── Topo Sheet Selection ──
  const [selectedSheetId, setSelectedSheetId] = useState<string>(KENYA_TOPO_SHEETS[0].id)
  const [useCustomParams, setUseCustomParams] = useState(false)

  // ── Filtered sheets list ──
  const filteredSheets = useMemo(() => {
    if (!sheetSearch.trim()) return KENYA_TOPO_SHEETS
    const q = sheetSearch.toLowerCase().trim()
    return KENYA_TOPO_SHEETS.filter(s =>
      s.id.toLowerCase().includes(q) ||
      s.name.toLowerCase().includes(q) ||
      s.description.toLowerCase().includes(q)
    )
  }, [sheetSearch])

  // ── Sub-sheet Selection ──
  const [selectedSubSheetId, setSelectedSubSheetId] = useState<string>('__auto__')
  const [detectedSubSheet, setDetectedSubSheet] = useState<SubSheetDef | undefined>(undefined)

  // ── Transform Method ──
  const [transformMethod, setTransformMethod] = useState<TransformMethod | 'auto'>('auto')
  const [customP, setCustomP] = useState('0.3048')
  const [customQ, setCustomQ] = useState('0')
  const [customCx, setCustomCx] = useState('277474.6')
  const [customCy, setCustomCy] = useState('10000198.4')
  const [paramsOpen, setParamsOpen] = useState(false)

  // ── Input Mode ──
  const [inputMode, setInputMode] = useState<'single' | 'batch'>('single')

  // ── Single Point Inputs ──
  const [singleE, setSingleE] = useState('')
  const [singleN, setSingleN] = useState('')

  // ── Batch Input ──
  const [batchText, setBatchText] = useState('')

  // ── Results ──
  const [singleResult, setSingleResult] = useState<ConversionResult | null>(null)
  const [batchResults, setBatchResults] = useState<ConversionResult[]>([])
  const [batchErrors, setBatchErrors] = useState<string[]>([])
  const [copied, setCopied] = useState(false)

  // ── Verification ──
  const [showVerification, setShowVerification] = useState(false)

  // ── Calibration ──
  const [calibrationOpen, setCalibrationOpen] = useState(false)
  const [calibrationCsv, setCalibrationCsv] = useState('')
  const [calibrationResult, setCalibrationResult] = useState<TopoSheetParams | null>(null)
  const [calibrationErrors, setCalibrationErrors] = useState<string[]>([])
  const [calibrationResiduals, setCalibrationResiduals] = useState<VerificationResult[]>([])
  const fileInputRef = useRef<HTMLInputElement>(null)

  // ── Derived: available sub-sheets for selected sheet ──
  const availableSubSheets = useMemo(() => {
    if (useCustomParams) return []
    return KENYA_SUB_SHEETS.filter(ss => ss.sheetId === selectedSheetId)
  }, [useCustomParams, selectedSheetId])

  const hasSubSheets = availableSubSheets.length > 0

  // ── Derived: active sub-sheet ──
  const activeSubSheet = useMemo(() => {
    if (selectedSubSheetId === '__auto__') return detectedSubSheet
    return availableSubSheets.find(ss => ss.subId === selectedSubSheetId)
  }, [selectedSubSheetId, detectedSubSheet, availableSubSheets])

  // ── Derived Sheet Params (resolves to actual params used for conversion) ──
  const activeSheet: TopoSheetParams = useMemo(() => {
    if (useCustomParams) {
      return {
        id: 'custom',
        name: 'Custom Parameters',
        description: 'User-defined Helmert transformation parameters.',
        P: parseFloat(customP) || 0.3048,
        Q: parseFloat(customQ) || 0,
        Cx: parseFloat(customCx) || 0,
        Cy: parseFloat(customCy) || 0,
        commonPoints: [],
      }
    }
    // If sub-sheet is active, use its Helmert params
    if (activeSubSheet) return activeSubSheet.helmertParams
    return KENYA_TOPO_SHEETS.find(s => s.id === selectedSheetId) ?? KENYA_TOPO_SHEETS[0]
  }, [useCustomParams, selectedSheetId, customP, customQ, customCx, customCy, activeSubSheet])

  // ── Accuracy Grade (enhanced for sub-sheets) ──
  const accuracyInfo = useMemo(() => {
    if (activeSubSheet) {
      const sa = estimateSubSheetAccuracy(activeSubSheet)
      return { rmseM: sa.rmseMM / 1000, rmseMM: sa.rmseMM, grade: sa.grade }
    }
    return estimateSheetAccuracy(activeSheet)
  }, [activeSheet, activeSubSheet])

  const accuracyColorClass = useMemo(() => {
    switch (accuracyInfo.grade) {
      case 'EXCELLENT': return 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400'
      case 'GOOD': return 'bg-green-500/10 border-green-500/20 text-green-400'
      case 'MODERATE': return 'bg-amber-500/10 border-amber-500/20 text-amber-400'
      case 'LOW': return 'bg-red-500/10 border-red-500/20 text-red-400'
      default: return 'bg-zinc-500/10 border-zinc-500/20 text-zinc-400'
    }
  }, [accuracyInfo.grade])

  const accuracyBadgeClass = useMemo(() => {
    switch (accuracyInfo.grade) {
      case 'EXCELLENT': return 'bg-emerald-500/20 text-emerald-300'
      case 'GOOD': return 'bg-green-500/20 text-green-300'
      case 'MODERATE': return 'bg-amber-500/20 text-amber-300'
      case 'LOW': return 'bg-red-500/20 text-red-300'
      default: return 'bg-zinc-500/20 text-zinc-300'
    }
  }, [accuracyInfo.grade])

  // ── WGS84 from single result (zone-aware) ──
  const singleWGS84 = useMemo(() => {
    if (!singleResult) return null
    const zone = getUtmZone(activeSheet.id)
    return utmToWGS84(singleResult.utmE, singleResult.utmN, zone)
  }, [singleResult, activeSheet.id])

  // ── Calibration Handler ──
  const handleCalibrate = useCallback(() => {
    const lines = calibrationCsv.trim().split('\n').filter(l => l.trim())
    const points: CommonPoint[] = []
    const errors: string[] = []

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim()
      const parts = line.split(',').map(s => s.trim())
      if (parts.length < 5) {
        errors.push(`Line ${i + 1}: Expected "station,cassN_ft,cassE_ft,utmN_m,utmE_m" — skipped`)
        continue
      }
      const station = parts[0]
      const cassN = parseFloat(parts[1])
      const cassE = parseFloat(parts[2])
      const utmN = parseFloat(parts[3])
      const utmE = parseFloat(parts[4])
      if ([cassN, cassE, utmN, utmE].some(isNaN)) {
        errors.push(`Line ${i + 1} (${station}): Invalid coordinates — skipped`)
        continue
      }
      points.push({ station, cassN, cassE, utmN, utmE })
    }

    setCalibrationErrors(errors)
    if (points.length < 2) {
      setCalibrationResult(null)
      setCalibrationResiduals([])
      if (errors.length === 0) {
        errors.push('Need at least 2 common points to compute parameters')
      }
      setCalibrationErrors(errors)
      return
    }

    try {
      const params = computeHelmert4Params(points)
      setCalibrationResult(params as TopoSheetParams)
      setCalibrationResiduals(verifyWithCommonPoints(params as TopoSheetParams))
    } catch (err) {
      setCalibrationResult(null)
      setCalibrationResiduals([])
      errors.push(`Computation error: ${err instanceof Error ? err.message : String(err)}`)
      setCalibrationErrors(errors)
    }
  }, [calibrationCsv])

  const handleUseCalibrationParams = useCallback(() => {
    if (!calibrationResult) return
    setCustomP(String(calibrationResult.P))
    setCustomQ(String(calibrationResult.Q))
    setCustomCx(String(calibrationResult.Cx))
    setCustomCy(String(calibrationResult.Cy))
    setUseCustomParams(true)
    setCalibrationOpen(false)
  }, [calibrationResult])

  // ── Verification Results ──
  const verificationResults = useMemo(() => {
    if (!showVerification || activeSheet.commonPoints.length === 0) return []
    return verifyWithCommonPoints(activeSheet)
  }, [showVerification, activeSheet])

  // ── Auto-detect sub-sheet from coordinates ──
  const detectSubSheetFromCoords = useCallback((e: number, n: number) => {
    if (!SHEETS_WITH_SUBSHEETS.has(selectedSheetId)) return undefined
    return findSubSheet(selectedSheetId, e, n)
  }, [selectedSheetId])

  // ── Reset results on direction change ──
  const handleDirectionChange = useCallback((dir: 'cassini-to-utm' | 'utm-to-cassini') => {
    setDirection(dir)
    setSingleResult(null)
    setBatchResults([])
    setBatchErrors([])
    setBatchText('')
    setDetectedSubSheet(undefined)
  }, [])

  // ── Single Convert ──
  const handleSingleConvert = useCallback(() => {
    const e = parseFloat(singleE)
    const n = parseFloat(singleN)
    if (isNaN(e) || isNaN(n)) return

    // Auto-detect sub-sheet if available
    const detected = detectSubSheetFromCoords(e, n)
    if (detected) setDetectedSubSheet(detected)
    const sub = selectedSubSheetId === '__auto__' ? detected : activeSubSheet

    if (direction === 'cassini-to-utm') {
      const pts: CassiniFeetPoint[] = [{ easting: e, northing: n }]
      if (sub && transformMethod !== 'helmert4') {
        const results = convertCassiniToUTM(pts, sub)
        setSingleResult(results[0])
      } else {
        const results = cassiniFeetToUTM(pts, sub ? sub.helmertParams : activeSheet)
        setSingleResult(results[0])
      }
    } else {
      const pts: UTMPoint[] = [{ easting: e, northing: n }]
      if (sub && transformMethod !== 'helmert4') {
        const results = convertUTMToCassini(pts, sub)
        setSingleResult(results[0])
      } else {
        const results = utmToCassiniFeet(pts, sub ? sub.helmertParams : activeSheet)
        setSingleResult(results[0])
      }
    }
  }, [singleE, singleN, direction, activeSheet, activeSubSheet, selectedSubSheetId, transformMethod, detectSubSheetFromCoords])

  // ── Batch Convert ──
  const handleBatchConvert = useCallback(() => {
    const lines = batchText.trim().split('\n').filter(l => l.trim())
    const validResults: ConversionResult[] = []
    const errors: string[] = []

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim()
      const parts = line.split(',').map(s => s.trim())

      if (parts.length < 3) {
        errors.push(`Line ${i + 1}: Expected "id,easting,northing" — skipped`)
        continue
      }
      const id = parts[0]
      const e = parseFloat(parts[1])
      const n = parseFloat(parts[2])
      if (isNaN(e) || isNaN(n)) {
        errors.push(`Line ${i + 1} (${id}): Invalid coordinates — skipped`)
        continue
      }

      // Auto-detect sub-sheet per point
      const detected = detectSubSheetFromCoords(e, n)
      const sub = selectedSubSheetId === '__auto__' ? detected : activeSubSheet
      const params = sub ? sub.helmertParams : activeSheet

      if (direction === 'cassini-to-utm') {
        const results = cassiniFeetToUTM([{ id, easting: e, northing: n }], params)
        validResults.push(results[0])
      } else {
        const results = utmToCassiniFeet([{ id, easting: e, northing: n }], params)
        validResults.push(results[0])
      }
    }

    setBatchResults(validResults)
    setBatchErrors(errors)
  }, [batchText, direction, activeSheet, activeSubSheet, selectedSubSheetId, detectSubSheetFromCoords])

  // ── Load Example ──
  const handleLoadExample = useCallback(() => {
    const example = direction === 'cassini-to-utm' ? CASSINI_BATCH_EXAMPLE : UTM_BATCH_EXAMPLE
    setBatchText(example)
    setBatchResults([])
    setBatchErrors([])
  }, [direction])

  // ── Copy helpers ──
  const copyToClipboard = useCallback(async (text: string) => {
    try {
      await navigator.clipboard.writeText(text)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    } catch {
      const ta = document.createElement('textarea')
      ta.value = text
      document.body.appendChild(ta)
      ta.select()
      document.execCommand('copy')
      document.body.removeChild(ta)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    }
  }, [])

  const handleCopySingle = useCallback(() => {
    if (!singleResult) return
    const srcUnit = direction === 'cassini-to-utm' ? 'ft' : 'm'
    const tgtUnit = direction === 'cassini-to-utm' ? 'm' : 'ft'
    const lines = [
      `Cassini-Soldner ↔ UTM Conversion (Helmert 4-Parameter)`,
      `Topo Sheet: ${activeSheet.name}`,
      `Datum: Arc 1960 / UTM Zone 37S`,
      ``,
      direction === 'cassini-to-utm'
        ? `Source Cassini: E = ${r1(singleResult.cassiniE)} ft, N = ${r1(singleResult.cassiniN)} ft`
        : `Source UTM: E = ${r3(singleResult.utmE)} m, N = ${r3(singleResult.utmN)} m`,
      direction === 'cassini-to-utm'
        ? `Result UTM: E = ${r3(singleResult.utmE)} m, N = ${r3(singleResult.utmN)} m`
        : `Result Cassini: E = ${r1(singleResult.cassiniE)} ft, N = ${r1(singleResult.cassiniN)} ft`,
      `Conformal E: ${r1(singleResult.conformalE)} ft`,
    ]
    if (singleResult.warning) {
      lines.push(`Warning: ${singleResult.warning}`)
    }
    copyToClipboard(lines.join('\n'))
  }, [singleResult, activeSheet, direction, copyToClipboard])

  const handleCopyBatchCsv = useCallback(() => {
    if (batchResults.length === 0) return
    const srcUnit = direction === 'cassini-to-utm' ? 'ft' : 'm'
    const tgtUnit = direction === 'cassini-to-utm' ? 'm' : 'ft'
    const header = `ID,Src_E(${srcUnit}),Src_N(${srcUnit}),Tgt_E(${tgtUnit}),Tgt_N(${tgtUnit}),Conformal_E(ft)`
    const rows = batchResults.map(r =>
      [
        r.id ?? '',
        direction === 'cassini-to-utm' ? r1(r.cassiniE) : r3(r.utmE),
        direction === 'cassini-to-utm' ? r1(r.cassiniN) : r3(r.utmN),
        direction === 'cassini-to-utm' ? r3(r.utmE) : r1(r.cassiniE),
        direction === 'cassini-to-utm' ? r3(r.utmN) : r1(r.cassiniN),
        r1(r.conformalE),
      ].join(',')
    )
    copyToClipboard([header, ...rows].join('\n'))
  }, [batchResults, direction, copyToClipboard])

  const handleDownloadCsv = useCallback(() => {
    if (batchResults.length === 0) return
    const srcUnit = direction === 'cassini-to-utm' ? 'ft' : 'm'
    const tgtUnit = direction === 'cassini-to-utm' ? 'm' : 'ft'
    const header = `ID,Src_E(${srcUnit}),Src_N(${srcUnit}),Tgt_E(${tgtUnit}),Tgt_N(${tgtUnit}),Conformal_E(ft)`
    const rows = batchResults.map(r =>
      [
        r.id ?? '',
        direction === 'cassini-to-utm' ? r1(r.cassiniE) : r3(r.utmE),
        direction === 'cassini-to-utm' ? r1(r.cassiniN) : r3(r.utmN),
        direction === 'cassini-to-utm' ? r3(r.utmE) : r1(r.cassiniE),
        direction === 'cassini-to-utm' ? r3(r.utmN) : r1(r.cassiniN),
        r1(r.conformalE),
      ].join(',')
    )
    const csv = [header, ...rows].join('\n')
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `cassini-utm-${direction}-${Date.now()}.csv`
    document.body.appendChild(a)
    a.click()
    document.body.removeChild(a)
    URL.revokeObjectURL(url)
  }, [batchResults, direction])

  return {
    // direction
    direction,
    handleDirectionChange,
    // sheet search
    sheetSearch,
    setSheetSearch,
    filteredSheets,
    // sheet selection
    selectedSheetId,
    setSelectedSheetId,
    useCustomParams,
    setUseCustomParams,
    // sub-sheet
    selectedSubSheetId,
    setSelectedSubSheetId,
    detectedSubSheet,
    setDetectedSubSheet,
    availableSubSheets,
    hasSubSheets,
    activeSubSheet,
    // transform method
    transformMethod,
    setTransformMethod,
    // custom params
    customP,
    setCustomP,
    customQ,
    setCustomQ,
    customCx,
    setCustomCx,
    customCy,
    setCustomCy,
    paramsOpen,
    setParamsOpen,
    // input mode
    inputMode,
    setInputMode,
    // single point
    singleE,
    setSingleE,
    singleN,
    setSingleN,
    singleResult,
    setSingleResult,
    singleWGS84,
    // batch
    batchText,
    setBatchText,
    batchResults,
    setBatchResults,
    batchErrors,
    setBatchErrors,
    handleBatchConvert,
    handleLoadExample,
    handleCopyBatchCsv,
    handleDownloadCsv,
    // copy state
    copied,
    handleCopySingle,
    // verification
    showVerification,
    setShowVerification,
    verificationResults,
    // calibration
    calibrationOpen,
    setCalibrationOpen,
    calibrationCsv,
    setCalibrationCsv,
    calibrationResult,
    calibrationErrors,
    calibrationResiduals,
    handleCalibrate,
    handleUseCalibrationParams,
    fileInputRef,
    // active sheet + accuracy
    activeSheet,
    accuracyInfo,
    accuracyColorClass,
    accuracyBadgeClass,
    // conversion
    handleSingleConvert,
  }
}

export type UseCassiniUtmStateReturn = ReturnType<typeof useCassiniUtmState>

'use client';

import { ToolExportButtons } from '@/components/shared/ToolExportButtons'
import { useState } from 'react';
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer'
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder'
import { chainageTableSolved, computeChainageTable, reverseChainageSolved } from '@/lib/engine/solution/wrappers/chainage'
import { PageHeader } from '@/components/shared/PageHeader'
import { useLanguage } from '@/lib/i18n/LanguageContext'

interface AlignmentPoint {
  id: string;
  name: string;
  easting: string;
  northing: string;
}

interface ChainageResult {
  pointName: string;
  easting: number;
  northing: number;
  chainage: number;
  distance: number;
}

export default function ChainageCalculator() {
  const { t } = useLanguage()
  const [startStation, setStartStation] = useState({ easting: '', northing: '' });
  const [startChainage, setStartChainage] = useState('0');
  const [alignmentPoints, setAlignmentPoints] = useState<AlignmentPoint[]>([
    { id: '1', name: 'A', easting: '', northing: '' },
    { id: '2', name: 'B', easting: '', northing: '' },
  ]);
  const [reverseChainage, setReverseChainage] = useState('');
  const [reverseResult, setReverseResult] = useState<{ easting: number; northing: number } | null>(null);
  const [results, setResults] = useState<ChainageResult[]>([]);
  const [steps, setSteps] = useState<SolutionStep[] | null>(null)
  const [solutionTitle, setSolutionTitle] = useState<string | undefined>(undefined)
  const [reverseSteps, setReverseSteps] = useState<SolutionStep[] | null>(null)
  const [reverseTitle, setReverseTitle] = useState<string | undefined>(undefined)

  const addPoint = () => {
    const newId = Date.now().toString();
    const lastPoint = alignmentPoints[alignmentPoints.length - 1];
    const newLetter = String.fromCharCode(65 + alignmentPoints.length);
    setAlignmentPoints([
      ...alignmentPoints,
      { id: newId, name: newLetter, easting: lastPoint.easting, northing: lastPoint.northing }
    ]);
  };

  const removePoint = (id: string) => {
    if (alignmentPoints.length > 2) {
      setAlignmentPoints(alignmentPoints.filter((p: AlignmentPoint) => p.id !== id));
    }
  };

  const updatePoint = (id: string, field: keyof AlignmentPoint, value: string) => {
    setAlignmentPoints(alignmentPoints.map((p: AlignmentPoint) => p.id === id ? { ...p, [field]: value } : p));
  };

  const calculate = () => {
    const startE = parseFloat(startStation.easting);
    const startN = parseFloat(startStation.northing);
    const startCh = parseFloat(startChainage) || 0;

    if (isNaN(startE) || isNaN(startN)) return;

    const alignment = alignmentPoints
      .map((p: AlignmentPoint) => ({ name: p.name, easting: parseFloat(p.easting), northing: parseFloat(p.northing) }))
      .filter((p: { easting: number; northing: number }) => !isNaN(p.easting) && !isNaN(p.northing))

    const table = computeChainageTable({
      start: { easting: startE, northing: startN },
      startChainage: startCh,
      alignment,
    })

    setResults(table)
    const s = chainageTableSolved({ startChainage: startCh, start: { easting: startE, northing: startN }, alignmentCount: alignment.length, table })
    setSteps(s.steps)
    setSolutionTitle(s.solution.title)
    setReverseResult(null)
    setReverseSteps(null)
    setReverseTitle(undefined)
  };

  const calculateReverse = () => {
    const targetCh = parseFloat(reverseChainage);
    if (isNaN(targetCh) || results.length === 0) return;

    const s = reverseChainageSolved({ targetChainage: targetCh, table: results })
    setReverseResult(s.result)
    setReverseSteps(s.steps)
    setReverseTitle(s.solution.title)
  };

  const formatChainage = (value: number): string => {
    const km = Math.floor(value / 1000);
    const m = value % 1000;
    return `${km}+${m.toFixed(3).padStart(3, '0')}`;
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.chainage')}
        subtitle={t('tools.chainageDesc')}
      />

      <div className="grid md:grid-cols-2 gap-8">
        <div className="space-y-6">
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
            <h3 className="font-semibold text-[var(--text-primary)] mb-4">Starting Station</h3>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="label" htmlFor="easting-m">Easting (m)</label>
                <input id="easting-m" aria-label="Easting" className="input" value={startStation.easting} onChange={e => setStartStation({...startStation, easting: e.target.value})} />
              </div>
              <div>
                <label className="label" htmlFor="northing-m">Northing (m)</label>
                <input id="northing-m" aria-label="Northing" className="input" value={startStation.northing} onChange={e => setStartStation({...startStation, northing: e.target.value})} />
              </div>
            </div>
            <div className="mt-4">
              <label className="label" htmlFor="starting-chainage-m">Starting Chainage (m)</label>
              <input id="starting-chainage-m" className="input" value={startChainage} onChange={e => setStartChainage(e.target.value)} placeholder="0" />
            </div>
          </div>

          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-semibold text-[var(--text-primary)]">Alignment Points</h3>
              <button onClick={addPoint} className="text-sm px-3 py-1 bg-[var(--bg-tertiary)] text-[var(--text-primary)] rounded hover:bg-[var(--border-hover)]">{t('toolUI.addPoint')}</button>
            </div>
            <div className="space-y-3">
              {alignmentPoints.map((point, idx) => (
                <div key={point.id} className="flex gap-2 items-center">
                  <input aria-label="Name" className="input w-16 text-center" value={point.name} onChange={e => updatePoint(point.id, 'name', e.target.value)} />
                  <input className="input flex-1" value={point.easting} onChange={e => updatePoint(point.id, 'easting', e.target.value)} aria-label="Easting (m)" placeholder="Easting" />
                  <input className="input flex-1" value={point.northing} onChange={e => updatePoint(point.id, 'northing', e.target.value)} aria-label="Northing (m)" placeholder="Northing" />
                  {alignmentPoints.length > 2 && (
                    <button onClick={() => removePoint(point.id)} className="text-red-400 hover:text-red-300 px-2">[x]</button>
                  )}
                </div>
              ))}
            </div>
          </div>

          <button onClick={calculate} className="w-full px-6 py-4 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-bold rounded-lg">
            Calculate Chainages
          </button>

          {results.length > 0 && (
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <h3 className="font-semibold text-[var(--text-primary)] mb-4">Reverse Calculation</h3>
              <p className="text-xs text-[var(--text-muted)] mb-3">Find coordinates at a given chainage</p>
              <div className="flex gap-2">
                <input className="input flex-1" value={reverseChainage} onChange={e => setReverseChainage(e.target.value)} aria-label="Chainage (m)" />
                <button onClick={calculateReverse} className="px-4 py-2 bg-[var(--bg-tertiary)] text-[var(--text-primary)] rounded hover:bg-[var(--border-hover)]">Find</button>
              </div>
              {reverseResult && (
                <div className="mt-4 p-3 bg-[var(--bg-tertiary)]/50 rounded-lg">
                  <p className="text-sm text-[var(--text-secondary)]">Coordinates at {reverseChainage}m:</p>
                  <p className="font-mono text-[var(--text-primary)]">E: {reverseResult.easting.toFixed(4)} m</p>
                  <p className="font-mono text-[var(--text-primary)]">N: {reverseResult.northing.toFixed(4)} m</p>
                </div>
              )}
              {reverseSteps ? (
                <div className="mt-4">
                  <SolutionStepsRenderer title={reverseTitle} steps={reverseSteps} />
                </div>
              ) : null}
            </div>
          )}
        </div>

        {results.length > 0 && (
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
            {steps ? (
              <div className="mb-6">
                <SolutionStepsRenderer title={solutionTitle} steps={steps} />
              </div>
            ) : null}
            <h3 className="font-semibold text-[var(--text-primary)] mb-4">Chainage Table</h3>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--border-color)]">
                    <th className="text-left py-2 text-[var(--text-secondary)]">Point</th>
                    <th className="text-right py-2 text-[var(--text-secondary)]">Easting</th>
                    <th className="text-right py-2 text-[var(--text-secondary)]">Northing</th>
                    <th className="text-right py-2 text-[var(--text-secondary)]">Chainage</th>
                    <th className="text-right py-2 text-[var(--text-secondary)]">Distance</th>
                  </tr>
                </thead>
                <tbody>
                  {results.map((r, idx) => (
                    <tr key={r.pointName} className="border-b border-[var(--border-color)]">
                      <td className="py-2 text-[var(--text-primary)] font-medium">{r.pointName}</td>
                      <td className="py-2 text-right font-mono text-[var(--text-primary)]">{r.easting.toFixed(3)}</td>
                      <td className="py-2 text-right font-mono text-[var(--text-primary)]">{r.northing.toFixed(3)}</td>
                      <td className="py-2 text-right font-mono text-[var(--accent)]">{formatChainage(r.chainage)}</td>
                      <td className="py-2 text-right font-mono text-[var(--text-secondary)]">
                        {r.distance > 0 ? r.distance.toFixed(3) + ' m' : '—'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <div className="mt-6 p-4 bg-[var(--bg-tertiary)]/30 rounded-lg">
              <h4 className="text-sm font-semibold text-[var(--text-primary)] mb-2">Summary</h4>
              <div className="grid grid-cols-2 gap-2 text-sm">
                <span className="text-[var(--text-secondary)]">Total Points:</span>
                <span className="text-[var(--text-primary)] font-mono">{results.length}</span>
                <span className="text-[var(--text-secondary)]">Start Chainage:</span>
                <span className="text-[var(--text-primary)] font-mono">{formatChainage(results[0].chainage)}</span>
                <span className="text-[var(--text-secondary)]">End Chainage:</span>
                <span className="text-[var(--text-primary)] font-mono">{formatChainage(results[results.length - 1].chainage)}</span>
                <span className="text-[var(--text-secondary)]">Total Length:</span>
                <span className="text-[var(--text-primary)] font-mono">{(results[results.length - 1].chainage - results[0].chainage).toFixed(3)} m</span>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react'
import { createClient } from '@/lib/api-client/client'
import { exportCivil, CIVIL_FORMATS, CivilFormat, CivilPoint } from '@/lib/export/civilHandoff'
import { PageHeader } from '@/components/shared/PageHeader'
import Link from 'next/link'
import { useLanguage } from '@/lib/i18n/LanguageContext'

interface ProjectRow { id: string; name: string; utm_zone: number; hemisphere: 'N' | 'S' }
interface SurveyPointRow {
  name?: string | null
  easting?: number | null
  northing?: number | null
  elevation?: number | null
  is_control?: boolean | null
  code?: string | null
}

function download(content: string, filename: string) {
  const a = document.createElement('a')
  a.href = URL.createObjectURL(new Blob([content], { type: 'text/plain' }))
  a.download = filename; a.click()
}

function CivilExportPage() {
  const { t } = useLanguage()
  const [projects, setProjects]   = useState<ProjectRow[]>([])
  const [projectId, setProjectId] = useState('')
  const [allPoints, setAllPoints] = useState<CivilPoint[]>([])
  const [format, setFormat]       = useState<CivilFormat>('civil3d')
  const [filter, setFilter]       = useState<'all' | 'control' | 'survey'>('all')
  const [loading, setLoading]     = useState(false)
  const [preview, setPreview]     = useState('')

  useEffect(() => {
    const sb = createClient()
    sb.auth.getSession().then(({ data: { session } }) => {
      const user = session?.user
      if (!user) return
      sb.from('projects').select('id,name,utm_zone,hemisphere').eq('user_id', user.id)
        .order('created_at', { ascending: false })
        .then(({ data }) => { if (data) setProjects(data as ProjectRow[]) })
    })
  }, [])

  useEffect(() => {
    if (!projectId) { setAllPoints([]); return }
    setLoading(true)
    const sb = createClient()
    sb.from('survey_points').select('*').eq('project_id', projectId)
      .then(({ data }) => {
        if (data) setAllPoints((data as SurveyPointRow[]).map((p) => ({
          name: p.name ?? '',
          easting: p.easting ?? 0,
          northing: p.northing ?? 0,
          elevation: p.elevation ?? 0,
          is_control: p.is_control ?? false,
          code: p.code ?? undefined,
        })))
        setLoading(false)
      })
  }, [projectId])

  const project = projects.find((p) => p.id === projectId)

  const filteredPoints = allPoints.filter((p) =>
    filter === 'all' ? true : filter === 'control' ? p.is_control : !p.is_control
  )

  useEffect(() => {
    if (!filteredPoints.length || !project) { setPreview(''); return }
    try {
      const { content } = exportCivil(filteredPoints, format, project.name, project.utm_zone, project.hemisphere)
      setPreview(content.slice(0, 1000) + (content.length > 1000 ? '\n…' : ''))
    } catch { setPreview('Error') }
  }, [filteredPoints, format, project])

  const handleExport = () => {
    if (!filteredPoints.length || !project) return
    const fmt = CIVIL_FORMATS.find((f) => f.id === format)!
    const { content, ext } = exportCivil(filteredPoints, format, project.name, project.utm_zone, project.hemisphere)
    download(content, `${project.name}_${fmt.label.replace(/[\s/]/g, '_')}.${ext}`)
  }

