// ─── Project point row shape (from /api/project/[id]/points) ───────────────
interface ProjectPointRow {
  id: string
  point_name?: string | null
  easting: number
  northing: number
  elevation: number | null
}

// ─── Component ──────────────────────────────────────────────────────────────

export default function ContourGeneratorPage() {
  const { t } = useLanguage()
  const [activeTab, setActiveTab] = useState<TabId>('import');

  // Tab 1: Import state
  const [rawText, setRawText] = useState('');
  const [fileName, setFileName] = useState('');
  const [points, setPoints] = useState<SpotHeight[]>([]);
  const [parseErrors, setParseErrors] = useState<ParseError[]>([]);
  const [importStats, setImportStats] = useState<ImportStats | null>(null);
  const [isParsing, setIsParsing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Tab 2: Settings state
  const [contourInterval, setContourInterval] = useState(1.0);
  const [indexMultiplier, setIndexMultiplier] = useState(5);
  const [isGenerating, setIsGenerating] = useState(false);
  const [generateError, setGenerateError] = useState('');
  const [generateProgress, setGenerateProgress] = useState(0);
  const [usingWorker, setUsingWorker] = useState(false);

  // Breaklines (AUDIT FIX 2026-07-03: expose engine's breakline support in UI)
  const [breaklines, setBreaklines] = useState<Breakline[]>([]);

  // Results
  const [contours, setContours] = useState<ContourLine[]>([]);
  const [tinSurface, setTinSurface] = useState<TINSurface | null>(null);
  const [volumeResult, setVolumeResult] = useState<VolumeResult | null>(null);

  // ─── Project integration: auto-load points from project survey data ──────
  const searchParams = useSearchParams();
  const projectId = searchParams.get('project');
  const [projectLoaded, setProjectLoaded] = useState(false);

  useEffect(() => {
    if (!projectId || projectLoaded) return;
    let cancelled = false;
    (async () => {
      try {
        const res = await fetch(`/api/project/${projectId}/points`)
        if (!res.ok) return
        const json = await res.json() as { data?: ProjectPointRow[] }
        const pts: SpotHeight[] = (json.data || [])
          .filter((p): p is ProjectPointRow & { elevation: number } => p.elevation != null)
          .map((p) => ({
            name: p.point_name || p.id,
            easting: p.easting,
            northing: p.northing,
            elevation: p.elevation,
          }))
        if (!cancelled && pts.length > 0) {
          setPoints(pts)
          setImportStats({
            delimiter: 'auto',
            hasHeader: false,
          })
        }
      } catch {
        // silent fail — user can import manually
      } finally {
        if (!cancelled) setProjectLoaded(true)
      }
    })()
    return () => { cancelled = true }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projectId, projectLoaded])

  // ─── Bounding box computation ────────────────────────────────────────────

  const bounds = useMemo<Bounds | null>(() => {
    if (points.length === 0) return null;
    let minE = Infinity, maxE = -Infinity, minN = Infinity, maxN = -Infinity, minZ = Infinity, maxZ = -Infinity;
    for (const p of points) {
      if (p.easting < minE) minE = p.easting;
      if (p.easting > maxE) maxE = p.easting;
      if (p.northing < minN) minN = p.northing;
      if (p.northing > maxN) maxN = p.northing;
      if (p.elevation < minZ) minZ = p.elevation;
      if (p.elevation > maxZ) maxZ = p.elevation;
    }
    return { minE, maxE, minN, maxN, minZ, maxZ };
  }, [points]);

  // ─── File upload handler ──────────────────────────────────────────────────

  const handleFileUpload = useCallback(async (file: File) => {
    setFileName(file.name);
    setIsParsing(true);
    setParseErrors([]);
    setContours([]);
    setTinSurface(null);
    setVolumeResult(null);

    try {
      const text = await file.text();
      setRawText(text);
      processText(text);
    } catch (err) {
      setParseErrors([{ row: 0, message: `Failed to read file: ${err instanceof Error ? err.message : 'Unknown error'}` }]);
    } finally {
      setIsParsing(false);
    }
  }, []);

  const processText = useCallback((text: string) => {
    setIsParsing(true);
    setParseErrors([]);
    setContours([]);
    setTinSurface(null);
    setVolumeResult(null);

    try {
      const result = parseXYZText(text);
      const spotHeights: SpotHeight[] = result.points.map(p => ({
        name: p.name,
        easting: p.easting,
        northing: p.northing,
        elevation: p.elevation,
      }));
      setPoints(spotHeights);
      setParseErrors(result.errors);
      setImportStats({
        delimiter: result.delimiter === '\t' ? 'tab' : result.delimiter === ',' ? 'comma' : result.delimiter === ';' ? 'semicolon' : 'space',
        hasHeader: result.hasHeader,
      });
    } catch (err) {
      setParseErrors([{ row: 0, message: `Parse error: ${err instanceof Error ? err.message : 'Unknown error'}` }]);
    } finally {
      setIsParsing(false);
    }
  }, []);

  const handleDropZone = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const file = e.dataTransfer.files[0];
    if (file) handleFileUpload(file);
  }, [handleFileUpload]);

  const handleFileInput = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) handleFileUpload(file);
  }, [handleFileUpload]);

  const handlePasteParse = useCallback(() => {
    if (!rawText.trim()) return;
    processText(rawText);
  }, [rawText, processText]);

  const handleLoadDemo = useCallback(() => {
    const demoPoints = generateDemoData();
    setPoints(demoPoints);
    setContours([]);
    setTinSurface(null);
    setVolumeResult(null);
    setParseErrors([]);
    setFileName('demo_terrain.csv');
    setImportStats({ delimiter: 'comma', hasHeader: true });
    // Build a demo CSV text for display
    const csvLines = ['Name,Easting,Northing,Elevation'];
    for (const p of demoPoints.slice(0, 10)) {
      csvLines.push(`${p.name},${fmt(p.easting, 3)},${fmt(p.northing, 3)},${fmt(p.elevation, 2)}`);
    }
    csvLines.push(`... (${demoPoints.length} points total)`);
    setRawText(csvLines.join('\n'));
  }, []);

  // ─── Generate contours ───────────────────────────────────────────────────

  const handleGenerate = useCallback(async () => {
    if (points.length < 3) {
      setGenerateError('At least 3 points are required to generate contours.');
      return;
    }
    if (contourInterval <= 0) {
      setGenerateError('Contour interval must be positive.');
      return;
    }

    setIsGenerating(true);
    setGenerateError('');
    setGenerateProgress(0);
    setUsingWorker(isWorkerAvailable());

    try {
      const indexInterval = contourInterval * indexMultiplier;

      // Use Web Worker with auto-fallback to sync engine.
      // For large datasets (≥ 5000 pts) this keeps the UI responsive;
      // for small datasets the worker overhead is negligible thanks to
      // the 30 s timeout + sync fallback in tinWorkerClient.
      //
      // AUDIT FIX (2026-07-05): DTM filtering — classify ground vs non-ground
      // before contour generation. Vegetation and buildings distort contours
      // if not filtered. Uses CSF algorithm (only if enough points).
      let groundPoints = points;
      try {
        if (points.length >= 20) {
          const { classifyPointCloud, extractGroundPoints } = await import('@/lib/topo/pointCloudClassification');
          const classified = classifyPointCloud(points.map(p => ({
            x: p.easting, y: p.northing, z: p.elevation,
          })));
          const ground = extractGroundPoints(classified);
          if (ground.length >= 3) {
            groundPoints = ground.map((p, i) => ({
              name: `G${i}`,
              easting: p.x, northing: p.y, elevation: p.z,
            }));
          }
        }
      } catch {
        // DTM filtering failed — use all points
      }

      // AUDIT FIX (2026-07-03): Pass breaklines to both the contour
      // generator and the TIN builder so triangles don't cross terrain
      // discontinuities.
      const result = await generateContoursAsync(groundPoints, contourInterval, {
        indexInterval,
        breaklines: breaklines.length > 0 ? breaklines : undefined,
        onProgress: p => setGenerateProgress(p),
      });
      setContours(result);

      const surface = await buildTINSurfaceAsync(
        groundPoints,
        breaklines.length > 0 ? breaklines : undefined,
        {
          onProgress: p => setGenerateProgress(p),
        },
      );
      setTinSurface(surface);

      // Compute volume relative to minimum elevation
      const minElev = Math.min(...groundPoints.map(p => p.elevation));
      const vol = computeVolumeFromTIN(surface, minElev);
      setVolumeResult(vol);
    } catch (err) {
      setGenerateError(err instanceof Error ? err.message : 'Contour generation failed.');
    } finally {
      setIsGenerating(false);
      setGenerateProgress(1);
      setUsingWorker(false);
    }
  }, [points, contourInterval, indexMultiplier, breaklines]);

  // ─── Export handlers ─────────────────────────────────────────────────────

  const exportDXF = useCallback(() => {
    if (!contours.length || !bounds) return;
    const dxf = generateDXF(contours, bounds);
    downloadBlob(dxf, 'contours.dxf', 'application/dxf');
  }, [contours, bounds]);

  const exportSVG = useCallback(() => {
    if (!contours.length || !bounds) return;
    const svg = generateSVGExport(contours, bounds, points);
    downloadBlob(svg, 'contours.svg', 'image/svg+xml');
  }, [contours, bounds, points]);

  const exportCSV = useCallback(() => {
    if (!contours.length) return;
    const csv = generateContourCSV(contours);
    downloadBlob(csv, 'contours.csv', 'text/csv');
  }, [contours]);

  const exportGeoJSON = useCallback(() => {
    if (!contours.length) return;
    const geojson = generateGeoJSON(contours);
    downloadBlob(geojson, 'contours.geojson', 'application/geo+json');
  }, [contours]);

  // ─── SVG rendering computations ──────────────────────────────────────────

  const svgElements = useMemo<SvgElements | null>(() => {
    if (!contours.length || !bounds) return null;

    const usableW = SVG_WIDTH - 2 * MARGIN;
    const usableH = SVG_HEIGHT - 2 * MARGIN;
    const minE = bounds.minE;
    const maxE = bounds.maxE;
    const minN = bounds.minN;
    const maxN = bounds.maxN;
    const rangeE = maxE - minE || 1;
    const rangeN = maxN - minN || 1;

    const contourElevations = contours.map(c => c.elevation);
    const minElev = Math.min(...contourElevations);
    const maxElev = Math.max(...contourElevations);

    function toSvgX(e: number) { return MARGIN + ((e - minE) / rangeE) * usableW; }
    function toSvgY(n: number) { return MARGIN + ((maxN - n) / rangeN) * usableH; }

    // Subsample spot height points for rendering if too many
    const spotStep = Math.max(1, Math.floor(points.length / 2000));
    const spotSampled = points.filter((_, i) => i % spotStep === 0);

    return {
      usableW, usableH, rangeE, rangeN, minElev, maxElev, toSvgX, toSvgY, spotSampled,
      viewBox: `0 0 ${SVG_WIDTH} ${SVG_HEIGHT}`,
    };
  }, [contours, bounds, points]);

  // ─── Tab definitions ──────────────────────────────────────────────────────

  const tabs: { id: TabId; label: string; disabled?: boolean }[] = [
    { id: 'import', label: 'Import Points' },
    { id: 'breaklines', label: `Breaklines${breaklines.length > 0 ? ` (${breaklines.length})` : ''}`, disabled: points.length < 3 },
    { id: 'settings', label: 'Settings & Generate', disabled: points.length < 3 },
    { id: 'map', label: 'Contour Map', disabled: contours.length === 0 },
    { id: 'export', label: 'Export', disabled: contours.length === 0 },
  ];

  // ─── Render ───────────────────────────────────────────────────────────────

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      {/* Custom header (mutation-plan pattern) */}
      <div className="flex items-center gap-3 mb-2">
        <div className="p-2 bg-emerald-500/10 rounded-lg">
          <Mountain className="h-6 w-6 text-emerald-500" />
        </div>
        <div>
          <h1 className="text-2xl font-bold">{t('tools.contourGenerator')}</h1>
          <p className="text-sm text-zinc-400">
            {t('tools.contourGeneratorDesc')}
          </p>
        </div>
      </div>

      <ComputeLimitNotice
        tool="Contour generation"
        message="The web contour engine runs in a browser worker and is tuned for typical field datasets. For very large point clouds, dense contours, or batch terrain processing, the METARDU desktop app runs the full engine locally — no size limits, no uploads."
      />

      {/* Tab bar */}
      <div className="flex gap-2 mt-6 mb-6 flex-wrap">
        {tabs.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            disabled={tab.disabled}
            className={`px-4 py-2 rounded text-sm font-medium transition-colors ${
              tab.disabled
                ? 'opacity-40 cursor-not-allowed bg-[var(--bg-tertiary)] text-zinc-600'
                : activeTab === tab.id
                  ? 'bg-[var(--accent)] text-black'
                  : 'bg-[var(--bg-card)] border border-[var(--border-color)] text-[var(--text-secondary)] hover:text-[var(--accent)]'
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* ═══════════════════ TAB 1: Import Points ═══════════════════ */}
      {activeTab === 'import' && (
        <ImportTab
          rawText={rawText}
          setRawText={setRawText}
          fileName={fileName}
          points={points}
          parseErrors={parseErrors}
          importStats={importStats}
          isParsing={isParsing}
          bounds={bounds}
          fileInputRef={fileInputRef}
          handleDropZone={handleDropZone}
          handleFileInput={handleFileInput}
          handlePasteParse={handlePasteParse}
          handleLoadDemo={handleLoadDemo}
        />
      )}

      {/* ═══════════════════ TAB 1.5: Breaklines ═══════════════════ */}
      {activeTab === 'breaklines' && (
        <BreaklineTab
          points={points}
          breaklines={breaklines}
          setBreaklines={setBreaklines}
        />
      )}

      {/* ═══════════════════ TAB 2: Settings & Generate ═══════════════════ */}
      {activeTab === 'settings' && (
        <SettingsTab
          contourInterval={contourInterval}
          setContourInterval={setContourInterval}
          indexMultiplier={indexMultiplier}
          setIndexMultiplier={setIndexMultiplier}
          points={points}
          bounds={bounds}
          isGenerating={isGenerating}
          generateError={generateError}
          handleGenerate={handleGenerate}
          contours={contours}
          tinSurface={tinSurface}
          volumeResult={volumeResult}
          generateProgress={generateProgress}
          usingWorker={usingWorker}
          breaklineCount={breaklines.length}
        />
      )}

      {/* ═══════════════════ TAB 3: Contour Map ═══════════════════ */}
      {activeTab === 'map' && svgElements && bounds && (
        <MapTab
          contours={contours}
          bounds={bounds}
          points={points}
          contourInterval={contourInterval}
          svgElements={svgElements}
        />
      )}

      {/* ═══════════════════ TAB 4: Export ═══════════════════ */}
      {activeTab === 'export' && (
        <ExportTab
          exportDXF={exportDXF}
          exportSVG={exportSVG}
          exportCSV={exportCSV}
          exportGeoJSON={exportGeoJSON}
          volumeResult={volumeResult}
          bounds={bounds}
        />
      )}
    </div>
  );
}

'use client'

import { useState, useEffect } from 'react'
import { ShieldCheck, AlertCircle, Plus, Clock, MapPin } from 'lucide-react'

interface VerificationRow {
  id: string
  point_id: string
  point_name?: string | null
  condition: string
  displacement_status?: string | null
  verification_date: string
  horizontal_displacement?: number | null
  verifier_name?: string | null
  method?: string | null
  condition_notes?: string | null
}

export default function ControlPointVerificationPage() {
  const [verifications, setVerifications] = useState<VerificationRow[]>([])
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(false)

  // Form state
  const [pointType, setPointType] = useState('survey_point')
  const [pointId, setPointId] = useState('')
  const [pointName, setPointName] = useState('')
  const [condition, setCondition] = useState('good')
  const [measuredE, setMeasuredE] = useState('')
  const [measuredN, setMeasuredN] = useState('')
  const [publishedE, setPublishedE] = useState('')
  const [publishedN, setPublishedN] = useState('')
  const [method, setMethod] = useState('gnss_rtk')
  const [notes, setNotes] = useState('')

  useEffect(() => { loadVerifications() }, [])

  const loadVerifications = async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/control-points/verifications?limit=100')
      if (res.ok) { const data = (await res.json()) as { data: VerificationRow[] }; setVerifications(data.data) }
    } catch {} finally { setLoading(false) }
  }

  const handleSubmit = async () => {
    const body: Record<string, unknown> = {
      point_type: pointType, point_id: pointId, point_name: pointName,
      verification_date: new Date().toISOString().split('T')[0],
      condition, method, condition_notes: notes,
    }
    if (measuredE) body.measured_easting = parseFloat(measuredE)
    if (measuredN) body.measured_northing = parseFloat(measuredN)
    if (publishedE) body.published_easting = parseFloat(publishedE)
    if (publishedN) body.published_northing = parseFloat(publishedN)

    await fetch('/api/control-points/verifications', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    })
    setShowForm(false); loadVerifications()
  }

  const inputCls = "w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] focus:border-[var(--accent)]/30 focus:outline-none"

  const conditionColors: Record<string, string> = {
    good: 'text-green-400 bg-green-500/10', fair: 'text-yellow-400 bg-yellow-500/10',
    poor: 'text-orange-400 bg-orange-500/10', disturbed: 'text-red-400 bg-red-500/10',
    destroyed: 'text-red-400 bg-red-500/10', missing: 'text-red-400 bg-red-500/10',
  }
  const trustColors: Record<string, string> = {
    within_tolerance: 'text-green-400', exceeds_tolerance: 'text-red-400', not_measured: 'text-gray-400',
  }

  return (
    <div className="min-h-screen p-6 max-w-4xl mx-auto">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl font-bold text-[var(--text-primary)]">Control Point Verification</h1>
          <p className="text-sm text-[var(--text-muted)]">Track on-site verification of control points — know whether to trust a point before you tie to it</p>
        </div>
        <button onClick={() => setShowForm(!showForm)} className="flex items-center gap-1.5 px-3 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)]">
          <Plus className="w-4 h-4" /> Record Verification
        </button>
      </div>

      {showForm && (
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4 grid grid-cols-2 gap-3">
          <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="point-type">Point Type</label>
            <select id="point-type" value={pointType} onChange={e => setPointType(e.target.value)} className={inputCls}>
              <option value="survey_point">Survey Point</option><option value="beacon">Beacon</option><option value="boundary_monument">Boundary Monument</option>
            </select></div>
          <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="point-id-uuid">Point ID (UUID)</label><input id="point-id-uuid" value={pointId} onChange={e => setPointId(e.target.value)} className={inputCls} placeholder="UUID" /></div>
          <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="point-name">Point Name</label><input id="point-name" value={pointName} onChange={e => setPointName(e.target.value)} className={inputCls} placeholder="CP1" /></div>
          <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="condition">Condition</label>
            <select id="condition" value={condition} onChange={e => setCondition(e.target.value)} className={inputCls}>
              <option value="good">Good</option><option value="fair">Fair</option><option value="poor">Poor</option>
              <option value="disturbed">Disturbed</option><option value="destroyed">Destroyed</option><option value="missing">Missing</option>
            </select></div>
          <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="measured-e">Measured E</label><input id="measured-e" value={measuredE} onChange={e => setMeasuredE(e.target.value)} className={inputCls} placeholder="264000.000" /></div>
          <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="measured-n">Measured N</label><input id="measured-n" value={measuredN} onChange={e => setMeasuredN(e.target.value)} className={inputCls} placeholder="9861000.000" /></div>
          <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="published-e">Published E</label><input id="published-e" value={publishedE} onChange={e => setPublishedE(e.target.value)} className={inputCls} /></div>
          <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="published-n">Published N</label><input id="published-n" value={publishedN} onChange={e => setPublishedN(e.target.value)} className={inputCls} /></div>
          <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="method">Method</label>
            <select id="method" value={method} onChange={e => setMethod(e.target.value)} className={inputCls}>
              <option value="gnss_static">GNSS Static</option><option value="gnss_rtk">GNSS RTK</option>
              <option value="total_station">Total Station</option><option value="level">Level</option>
            </select></div>
          <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="notes">Notes</label><input id="notes" value={notes} onChange={e => setNotes(e.target.value)} className={inputCls} /></div>
          <button onClick={handleSubmit} className="col-span-2 px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)]">Submit Verification</button>
        </div>
      )}

      {loading ? <div className="text-center py-8 text-sm text-[var(--text-muted)]">Loading...</div> : verifications.length === 0 ? (
        <div className="text-center py-8 text-sm text-[var(--text-muted)]">No verifications recorded. Click "Record Verification" to start.</div>
      ) : (
        <div className="space-y-3">
          {verifications.map(v => (
            <div key={v.id} className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
              <div className="flex justify-between items-start mb-2">
                <div className="flex items-center gap-2">
                  <MapPin className="w-4 h-4 text-[var(--accent)]" />
                  <span className="font-mono text-sm font-bold text-[var(--text-primary)]">{v.point_name || v.point_id.substring(0, 8)}</span>
                  <span className={`text-[9px] px-2 py-0.5 rounded-full ${conditionColors[v.condition] || ''}`}>{v.condition}</span>
                  {v.displacement_status && <span className={`text-[9px] px-2 py-0.5 rounded-full ${trustColors[v.displacement_status] || ''} bg-current/10`}>{v.displacement_status}</span>}
                </div>
                <div className="flex items-center gap-1 text-[10px] text-[var(--text-muted)]"><Clock className="w-3 h-3" /> {v.verification_date}</div>
              </div>
              <div className="grid grid-cols-3 gap-2 text-[10px] text-[var(--text-muted)]">
                {v.horizontal_displacement && <div><span className="opacity-60">Displacement:</span> <span className={`font-mono ${v.displacement_status === 'exceeds_tolerance' ? 'text-red-400' : 'text-green-400'}`}>{(v.horizontal_displacement * 1000).toFixed(1)}mm</span></div>}
                {v.verifier_name && <div><span className="opacity-60">Verifier:</span> <span className="text-[var(--text-secondary)]">{v.verifier_name}</span></div>}
                {v.method && <div><span className="opacity-60">Method:</span> <span className="text-[var(--text-secondary)]">{v.method}</span></div>}
                {v.condition_notes && <div className="col-span-3"><span className="opacity-60">Notes:</span> <span className="text-[var(--text-secondary)]">{v.condition_notes}</span></div>}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useCallback } from 'react'
import { Route, AlertCircle, Map as MapIcon } from 'lucide-react'
import { buildAlignment, enToChainageOffset, organizeShotsByChainage, formatChainage, type PIPoint, type FieldShot, type CrossSectionGroup } from '@/lib/survey/corridorEngine'

export default function CorridorPage() {
  const [piInput, setPiInput] = useState('')
  const [shotsInput, setShotsInput] = useState('')
  const [interval, setInterval] = useState('20')
  const [crossSections, setCrossSections] = useState<CrossSectionGroup[]>([])
  const [alignmentLength, setAlignmentLength] = useState(0)
  const [error, setError] = useState('')

  const handleOrganize = useCallback(() => {
    setError(''); setCrossSections([]); setAlignmentLength(0)
    try {
      // Parse PI points: id,easting,northing
      const pis: PIPoint[] = piInput.trim().split('\n').map(line => {
        const cols = line.split(',').map(c => c.trim())
        return { id: cols[0], e: parseFloat(cols[1]), n: parseFloat(cols[2]) }
      }).filter(p => p.id && !isNaN(p.e) && !isNaN(p.n))

      if (pis.length < 2) { setError('Need at least 2 PI points (format: id,easting,northing)'); return }

      // Parse field shots: easting,northing,rl
      const shots: FieldShot[] = shotsInput.trim().split('\n').map(line => {
        const cols = line.split(',').map(c => parseFloat(c.trim()))
        return { e: cols[0], n: cols[1], rl: cols[2] }
      }).filter(s => !isNaN(s.e) && !isNaN(s.n) && !isNaN(s.rl))

      if (shots.length < 3) { setError('Need at least 3 field shots (format: easting,northing,rl)'); return }

      const alignment = buildAlignment(pis)
      const groups = organizeShotsByChainage(shots, alignment, parseFloat(interval))
      setCrossSections(groups)
      setAlignmentLength(alignment.totalLength)
    } catch (e) { setError(e instanceof Error ? e.message : 'Failed') }
  }, [piInput, shotsInput, interval])

  const inputCls = "w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] focus:border-[var(--accent)]/30 focus:outline-none"

  return (
    <div className="min-h-screen p-6 max-w-6xl mx-auto">
      <h1 className="text-2xl font-bold text-[var(--text-primary)] mb-2">Corridor / Chainage Mode</h1>
      <p className="text-sm text-[var(--text-muted)] mb-6">Define an alignment from PI points → auto-organize field shots into cross-sections by chainage station. Designed for KeNHA road corridors.</p>

      <div className="grid grid-cols-2 gap-4 mb-4">
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
          <h2 className="text-sm font-semibold mb-2 flex items-center gap-2"><Route className="w-4 h-4" /> PI Points (id,easting,northing)</h2>
          <textarea value={piInput} onChange={e => setPiInput(e.target.value)} className={inputCls + ' h-40 font-mono'} placeholder="PI1,264000,9861000&#10;PI2,264100,9861100&#10;PI3,264200,9861200" />
        </div>
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
          <h2 className="text-sm font-semibold mb-2 flex items-center gap-2"><MapIcon className="w-4 h-4" /> Field Shots (easting,northing,rl)</h2>
          <textarea value={shotsInput} onChange={e => setShotsInput(e.target.value)} className={inputCls + ' h-40 font-mono'} placeholder="264000,9861000,1500&#10;264010,9861000,1500.1&#10;263990,9861000,1499.9" />
        </div>
      </div>

      <div className="flex gap-4 items-end mb-4">
        <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="cross-section-interval-m">Cross-section interval (m)</label><input id="cross-section-interval-m" value={interval} onChange={e => setInterval(e.target.value)} className={inputCls + ' w-32'} /></div>
        <button onClick={handleOrganize} className="px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)]">Organize by Chainage</button>
      </div>

      {error && <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 mb-4 text-xs text-red-400 flex items-center gap-2"><AlertCircle className="w-4 h-4" /> {error}</div>}

      {crossSections.length > 0 && (
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
          <div className="flex justify-between items-center mb-3">
            <h2 className="text-sm font-semibold">Cross-Sections ({crossSections.length} stations)</h2>
            <span className="text-[10px] text-[var(--text-muted)]">Alignment length: {alignmentLength.toFixed(1)} m</span>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead><tr className="text-[var(--text-muted)] border-b border-[var(--border-color)]">
                <th className="text-left py-2 px-1">Chainage</th><th className="text-right">Shots</th><th className="text-right">Left (m)</th><th className="text-right">Right (m)</th><th className="text-right">CL RL</th>
              </tr></thead>
              <tbody>
                {crossSections.map(cs => (
                  <tr key={cs.chainage} className="border-b border-[var(--border-color)]/30 text-[var(--text-secondary)]">
                    <td className="py-1.5 px-1 font-mono font-bold text-[var(--accent)]">{cs.label}</td>
                    <td className="text-right font-mono">{cs.shots.length}</td>
                    <td className="text-right font-mono">{cs.leftOffset.toFixed(1)}</td>
                    <td className="text-right font-mono">{cs.rightOffset.toFixed(1)}</td>
                    <td className="text-right font-mono">{cs.centrelineRL !== null ? cs.centrelineRL.toFixed(3) : '—'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="mt-3 text-[10px] text-[var(--text-muted)]">
            {crossSections.reduce((sum, cs) => sum + cs.shots.length, 0)} total shots organized into {crossSections.length} cross-sections
          </div>
        </div>
      )}
    </div>
  )
}

