'use client';

import { useState, useMemo } from 'react'
import { useSearchParams } from 'next/navigation'
import { PageHeader } from '@/components/shared/PageHeader'
import CrossSectionInput from '@/components/earthworks/CrossSectionInput'
import ProjectCrossSections from '@/components/earthworks/ProjectCrossSections'
import { useLanguage } from '@/lib/i18n/LanguageContext'

/**
 * Earthworks Calculator — extends Cross Sections with:
 * - Mass Haul Diagram (cumulative volume chart)
 * - Cut/Fill balance analysis
 * - End-Area vs Prismoidal volume comparison
 * - Free-haul and overhaul distance analysis
 */

interface SectionVolume {
  station: string
  cutArea: number
  fillArea: number
  endAreaVol: number
  prismoidalVol: number
}

function computeVolumes(sections: { station: string; cutArea: number; fillArea: number; distance: number }[]): SectionVolume[] {
  const result: SectionVolume[] = []
  for (let i = 1; i < sections.length; i++) {
    const prev = sections[i - 1]
    const curr = sections[i]
    const L = curr.distance

    const avgCutEndArea = (prev.cutArea + curr.cutArea) / 2
    const avgFillEndArea = (prev.fillArea + curr.fillArea) / 2

    // Prismoidal: V = L/6 * (A1 + 4*Am + A2) where Am = midpoint area
    // Simplified: using average as proxy for midpoint
    const midCut = (prev.cutArea + curr.cutArea) / 2
    const midFill = (prev.fillArea + curr.fillArea) / 2
    const prismCut = L / 6 * (prev.cutArea + 4 * midCut + curr.cutArea)
    const prismFill = L / 6 * (prev.fillArea + 4 * midFill + curr.fillArea)

    result.push({
      station: `${prev.station} — ${curr.station}`,
      cutArea: avgCutEndArea,
      fillArea: avgFillEndArea,
      endAreaVol: avgCutEndArea * L - avgFillEndArea * L,
      prismoidalVol: prismCut - prismFill,
    })
  }
  return result
}

export default function EarthworksPage() {
  const { t } = useLanguage()
  const searchParams = useSearchParams()
  const projectId = searchParams.get('project')
  // Remove hardcoded demo — the CrossSectionInput below handles real computation
  // The old summary panel showed fake 7600/8000 m³ regardless of input.

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.earthworks')}
        subtitle={t('tools.earthworksDesc')}
      />

      {/* Info banner replacing hardcoded demo summary */}
      <div className="mb-6 p-4 border border-[var(--accent)]/30 bg-[var(--accent)]/5 rounded-md">
        <p className="font-mono text-[10px] text-[var(--accent)] tracking-[0.08em] uppercase mb-1">How this works</p>
        <p className="text-sm text-[var(--text-secondary)]">
          Enter cross-section data below (or load from project via <code className="font-mono text-[var(--accent)]">?project=ID</code>).
          The calculator computes cut/fill volumes, mass-haul diagram, and BoQ quantities.
          Use the print button for a formal earthworks report.
        </p>
      </div>

      {/* Full cross section calculator — this is the real tool */}
      <div className="mt-8 border-t border-[var(--border-color)] pt-6">
        <h2 className="text-lg font-semibold mb-4">Cross Section Data Entry</h2>
        {projectId && projectId !== 'new' ? (
          <ProjectCrossSections projectId={projectId} />
        ) : (
          <CrossSectionInput />
        )}
      </div>
    </div>
  )
}

'use client';

import { useState, useEffect, useCallback } from 'react'
import { createClient } from '@/lib/api-client/client'
import { exportGCPs, GCP_FORMATS, GCPFormat, GCPPoint } from '@/lib/export/gcpExport'
import { PageHeader } from '@/components/shared/PageHeader'
import Link from 'next/link'
import { useLanguage } from '@/lib/i18n/LanguageContext'

interface GCPRow {
  name?: string | null
  easting?: number | null
  northing?: number | null
  elevation?: number | null
}

// ── helpers ──────────────────────────────────────────────────────────────────

function download(content: string, filename: string) {
  const a = document.createElement('a')
  a.href = URL.createObjectURL(new Blob([content], { type: 'text/plain' }))
  a.download = filename
  a.click()
}

// ── Main page ─────────────────────────────────────────────────────────────────

export default function GCPExportPage() {
  const { t } = useLanguage()
  const [projects, setProjects] = useState<{ id: string; name: string; utm_zone: number; hemisphere: string }[]>([])
  const [selectedProject, setSelectedProject] = useState('')
  const [points, setPoints] = useState<GCPPoint[]>([])
  const [selectedPoints, setSelectedPoints] = useState<Set<string>>(new Set())
  const [format, setFormat] = useState<GCPFormat>('pix4d')
  const [loading, setLoading] = useState(false)
  const [preview, setPreview] = useState('')

  // Load projects
  useEffect(() => {
    const dbClient = createClient()
    dbClient.auth.getSession().then(({ data: { session } }) => {
      const user = session?.user
      if (!user) return
      dbClient.from('projects').select('id, name, utm_zone, hemisphere')
        .eq('user_id', user.id).order('created_at', { ascending: false })
        .then(({ data }) => { if (data) setProjects(data as { id: string; name: string; utm_zone: number; hemisphere: string }[]) })
    })
  }, [])

  // Load points when project changes
  useEffect(() => {
    if (!selectedProject) { setPoints([]); return }
    setLoading(true)
    const dbClient = createClient()
    const project = projects.find((p) => p.id === selectedProject)
    dbClient.from('survey_points').select('*')
      .eq('project_id', selectedProject)
      .eq('is_control', true)
      .then(({ data }) => {
        if (data && project) {
          const pts: GCPPoint[] = (data as GCPRow[]).map((p) => ({
            name: p.name ?? '',
            easting: p.easting ?? 0,
            northing: p.northing ?? 0,
            elevation: p.elevation ?? 0,
            utmZone: project.utm_zone,
            hemisphere: project.hemisphere as 'N' | 'S',
          }))
          setPoints(pts)
          setSelectedPoints(new Set(pts.map((p) => p.name)))
        }
        setLoading(false)
      })
  }, [selectedProject, projects])

  // Update preview
  useEffect(() => {
    const selected = points.filter((p) => selectedPoints.has(p.name))
    if (selected.length === 0) { setPreview(''); return }
    try {
      const { content } = exportGCPs(selected, format)
      setPreview(content)
    } catch { setPreview('Error generating preview') }
  }, [points, selectedPoints, format])

  const project = projects.find((p) => p.id === selectedProject)
  const selectedPts = points.filter((p) => selectedPoints.has(p.name))

  const handleExport = () => {
    if (selectedPts.length === 0 || !project) return
    const { content, ext } = exportGCPs(selectedPts, format)
    const fmtLabel = GCP_FORMATS.find((f) => f.id === format)?.label ?? format
    download(content, `${project.name}_GCPs_${fmtLabel}.${ext}`)
  }

  const togglePoint = (name: string) => {
    setSelectedPoints(prev => {
      const s = new Set(Array.from(prev))
      if (s.has(name)) { s.delete(name) } else { s.add(name) }
      return s
    })
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)]">
      <div className="max-w-7xl mx-auto px-4 py-8">

        {/* Header */}
        <PageHeader
          title={t('tools.gcpExport')}
          subtitle={t('tools.gcpExportDesc')}
        />

        {/* What is a GCP? — for context */}
        <div className="bg-[var(--accent)]/5 border border-[var(--accent)]/20 rounded-xl p-4 mb-6 text-sm">
          <p className="text-[var(--text-secondary)] leading-relaxed">
            <strong className="text-[var(--text-primary)]">Ground Control Points</strong> are precisely surveyed reference points 
            placed on the ground before a drone flight. They allow the photogrammetry software to 
            georeference the orthophoto and 3D model to within centimetre accuracy.
            METARDU converts your UTM control points to WGS84 lat/lon as required by drone software.
          </p>
        </div>

        <div className="grid lg:grid-cols-2 gap-6">

          {/* Left: Configuration */}
          <div className="space-y-5">

            {/* 1. Select project */}
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-5">
              <h2 className="text-sm font-semibold text-[var(--text-primary)] mb-3 flex items-center gap-2">
                <span className="w-5 h-5 rounded-full bg-[var(--accent)] text-black text-xs font-bold flex items-center justify-center">1</span>
                Select project
              </h2>
              {projects.length === 0 ? (
                <p className="text-sm text-[var(--text-muted)]">No projects found. <Link href="/project/new" className="text-[var(--accent)] underline underline-offset-2">Create one</Link> with control points marked.</p>
              ) : (
                <select value={selectedProject} onChange={e => setSelectedProject(e.target.value)} className="input w-full">
                  <option value="">— Choose project —</option>
                  {projects.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
                </select>
              )}
            </div>

            {/* 2. Select GCPs */}
            {points.length > 0 && (
              <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-5">
                <div className="flex items-center justify-between mb-3">
                  <h2 className="text-sm font-semibold text-[var(--text-primary)] flex items-center gap-2">
                    <span className="w-5 h-5 rounded-full bg-[var(--accent)] text-black text-xs font-bold flex items-center justify-center">2</span>
                    Select GCPs ({selectedPts.length}/{points.length})
                  </h2>
                  <button onClick={() => setSelectedPoints(new Set(points.map((p) => p.name)))}
                    className="text-xs text-[var(--accent)] hover:underline">Select all</button>
                </div>
                <div className="space-y-2">
                  {points.map((pt) => (
                    <label key={pt.name} className={`flex items-center gap-3 p-2.5 rounded-lg border cursor-pointer transition-colors ${
                      selectedPoints.has(pt.name)
                        ? 'bg-[var(--accent)]/5 border-[var(--accent)]/20'
                        : 'bg-[var(--bg-secondary)] border-[var(--border-color)]'
                    }`}>
                      <input aria-label="Select point" type="checkbox" checked={selectedPoints.has(pt.name)}
                        onChange={() => togglePoint(pt.name)} className="rounded flex-shrink-0" />
                      <div className="flex-1 min-w-0">
                        <span className="text-sm font-semibold text-[var(--text-primary)]">{pt.name}</span>
                        <p className="text-xs text-[var(--text-muted)] font-mono">
                          E {pt.easting.toFixed(3)}  N {pt.northing.toFixed(3)}  Z {pt.elevation.toFixed(3)}
                        </p>
                      </div>
                    </label>
                  ))}
                </div>
                {points.length === 0 && selectedProject && !loading && (
                  <p className="text-xs text-amber-400 bg-amber-900/20 border border-amber-700/30 rounded px-3 py-2">
                    No control points in this project. In the workspace, mark points as control points first.
                  </p>
                )}
              </div>
            )}

            {selectedProject && !loading && points.length === 0 && (
              <div className="bg-amber-900/20 border border-amber-700/30 rounded-xl p-4 text-sm text-amber-400">
                No control points found in this project. Open the project workspace and mark some points as control points (tap a point → toggle Control Point).
              </div>
            )}

            {/* 3. Select format */}
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-5">
              <h2 className="text-sm font-semibold text-[var(--text-primary)] mb-3 flex items-center gap-2">
                <span className="w-5 h-5 rounded-full bg-[var(--accent)] text-black text-xs font-bold flex items-center justify-center">3</span>
                Export format
              </h2>
              <div className="space-y-2">
                {GCP_FORMATS.map((f) => (
                  <label key={f.id} className={`flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                    format === f.id
                      ? 'bg-[var(--accent)]/5 border-[var(--accent)]/30'
                      : 'bg-[var(--bg-secondary)] border-[var(--border-color)] hover:border-[var(--accent)]/20'
                  }`}>
                    <input aria-label="Format" type="radio" name="format" value={f.id} checked={format === f.id}
                      onChange={() => setFormat(f.id)} className="mt-0.5 flex-shrink-0" />
                    <div>
                      <p className="text-sm font-semibold text-[var(--text-primary)]">{f.label}</p>
                      <p className="text-xs text-[var(--text-muted)]">{f.desc}</p>
                    </div>
                    <span className="ml-auto text-xs text-[var(--text-muted)] flex-shrink-0">.{f.ext}</span>
                  </label>
                ))}
              </div>
            </div>

            {/* Export button */}
            <button
              onClick={handleExport}
              disabled={selectedPts.length === 0}
              className="btn btn-primary w-full text-base py-3 disabled:opacity-50"
            >
              Download {selectedPts.length > 0 ? `${selectedPts.length} GCPs` : 'GCPs'} — {GCP_FORMATS.find((f) => f.id === format)?.label}
            </button>

          </div>

          {/* Right: Preview + instructions */}
          <div className="space-y-5">

            {/* Preview */}
            {preview && (
              <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-5">
                <h2 className="text-sm font-semibold text-[var(--text-primary)] mb-3">File preview</h2>
                <pre className="text-xs font-mono text-[var(--text-secondary)] bg-[var(--bg-primary)] rounded-lg p-4 overflow-x-auto whitespace-pre-wrap">
                  {preview.slice(0, 800)}{preview.length > 800 ? '\n…' : ''}
                </pre>
                <p className="text-xs text-[var(--text-muted)] mt-2">
                  Coordinates converted from UTM Zone {project?.utm_zone}{project?.hemisphere} to WGS84 lat/lon
                </p>
              </div>
            )}

            {/* Usage instructions per format */}
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-5">
              <h2 className="text-sm font-semibold text-[var(--text-primary)] mb-3">How to use in your software</h2>
              <div className="space-y-4 text-sm">
                {format === 'pix4d' && (
                  <div>
                    <p className="font-medium text-[var(--text-primary)] mb-1">Pix4Dmapper</p>
                    <p className="text-[var(--text-muted)] leading-relaxed">In your project, go to <em>Project → GCP / MTP Manager</em>. Click <em>Import GCPs</em>, choose the CSV file. Set coordinate system to WGS84 (EPSG:4326). Then mark each GCP on your images.</p>
                  </div>
                )}
                {format === 'dronedeploy' && (
                  <div>
                    <p className="font-medium text-[var(--text-primary)] mb-1">DroneDeploy</p>
                    <p className="text-[var(--text-muted)] leading-relaxed">Upload the CSV in the map settings under <em>Ground Control Points</em>. DroneDeploy will match the GCP names to the targets visible in your images automatically.</p>
                  </div>
                )}
                {format === 'metashape' && (
                  <div>
                    <p className="font-medium text-[var(--text-primary)] mb-1">Agisoft Metashape</p>
                    <p className="text-[var(--text-muted)] leading-relaxed">In Metashape, go to <em>Tools → Import → Import Reference</em>. Select the .txt file. Set coordinate system to WGS84. Then mark GCPs in the photo viewer using <em>Reference</em> panel.</p>
                  </div>
                )}
                {format === 'odm' && (
                  <div>
                    <p className="font-medium text-[var(--text-primary)] mb-1">OpenDroneMap / WebODM</p>
                    <p className="text-[var(--text-muted)] leading-relaxed">Save the file as <code>gcp_list.txt</code> in the same folder as your images. ODM reads it automatically when you add it to the task.</p>
                  </div>
                )}
                {format === 'csv' && (
                  <div>
                    <p className="font-medium text-[var(--text-primary)] mb-1">QGIS</p>
                    <p className="text-[var(--text-muted)] leading-relaxed">Layer → Add Layer → Add Delimited Text Layer. Select the CSV, set Geometry as Point (X = Longitude_WGS84, Y = Latitude_WGS84), CRS = EPSG:4326 (WGS84).</p>
                  </div>
                )}
                {format === 'geojson' && (
                  <div>
                    <p className="font-medium text-[var(--text-primary)] mb-1">QGIS / ArcGIS</p>
                    <p className="text-[var(--text-muted)] leading-relaxed">Drag and drop the .geojson file directly onto the QGIS canvas. In ArcGIS Pro, use Add Data → GeoJSON. All attributes including UTM coordinates are preserved.</p>
                  </div>
                )}
              </div>
            </div>

            {/* Accuracy note */}
            <div className="bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-xl p-4 text-xs text-[var(--text-muted)] leading-relaxed">
              <strong className="text-[var(--text-secondary)]">Accuracy note:</strong> METARDU converts from UTM to WGS84 using an iterative Newton-Raphson method accurate to ±0.0001m. 
              For highest accuracy, always verify at least one GCP against an independent check measurement after import.
              For RTK/PPK surveys, use the direct WGS84 coordinates from your GNSS receiver instead.
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

// Helper utilities for parsing residual tables and computing RMSE / validation
// summaries.
//
// Extracted from src/app/tools/gcp-validation/page.tsx — pure functions,
// no React, no hooks, so this file does not need 'use client'.

import type {
  AccuracyClass,
  KnownGCP,
  ResidualFormat,
  ResidualRow,
  ValidationResult,
  ValidationSummary,
} from './types';

export function fmt(n: number, d: number = 4): string {
  return n.toFixed(d);
}

export function calculateRMSE(errors: number[]): number {
  if (errors.length === 0) return 0;
  const sumSquared = errors.reduce((sum, e) => sum + e * e, 0);
  return Math.sqrt(sumSquared / errors.length);
}

export function detectFormat(text: string): ResidualFormat {
  const trimmed = text.trim().toLowerCase();
  if (trimmed.includes('#point') || trimmed.includes('#metashape')) return 'agisoft';
  if (trimmed.includes('gcp_name') && trimmed.includes('errortotal')) return 'pix4d';
  // Fallback: if it has a lot of tab-separated fields, guess Agisoft; if comma, Pix4D
  const lines = trimmed.split('\n').filter(l => l.trim() && !l.trim().startsWith('#'));
  if (lines.length === 0) return 'auto';
  const firstDataLine = lines[0];
  const tabCount = (firstDataLine.match(/\t/g) || []).length;
  const commaCount = (firstDataLine.match(/,/g) || []).length;
  if (tabCount >= 3 && commaCount < 2) return 'agisoft';
  if (commaCount >= 5) return 'pix4d';
  return 'auto';
}

export function parseAgisoft(text: string): ResidualRow[] {
  const rows: ResidualRow[] = [];
  const lines = text.trim().split('\n');
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    // Agisoft format: name  x  y  z  error  (whitespace or tab separated)
    const parts = trimmed.split(/\s+/);
    if (parts.length >= 5) {
      const name = parts[0];
      const softwareE = parseFloat(parts[1]);
      const softwareN = parseFloat(parts[2]);
      const softwareZ = parseFloat(parts[3]);
      const reprojError = parseFloat(parts[4]);
      if (!isNaN(softwareE) && !isNaN(softwareN) && !isNaN(softwareZ)) {
        rows.push({
          id: Date.now() + Math.random(),
          name,
          softwareE,
          softwareN,
          softwareZ,
          reprojectionError: isNaN(reprojError) ? undefined : reprojError,
          source: 'agisoft',
        });
      }
    }
  }
  return rows;
}

export function parsePix4D(text: string): ResidualRow[] {
  const rows: ResidualRow[] = [];
  const lines = text.trim().split('\n');
  let headerParsed = false;
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    // Skip header row
    if (!headerParsed) {
      headerParsed = true;
      if (trimmed.toLowerCase().startsWith('gcp_name')) continue;
    }
    const parts = trimmed.split(',').map(s => s.trim());
    // Minimum expected: GCP_Name, X_photo, Y_photo, Z_photo, X_GCP, Y_GCP, Z_GCP, ErrorX, ErrorY, ErrorZ, ErrorXY, ErrorTotal
    if (parts.length >= 11) {
      const name = parts[0];
      // Pix4D columns: software coords in X_GCP, Y_GCP, Z_GCP (indices 4,5,6)
      // OR in X_photo, Y_photo, Z_photo (indices 1,2,3) - we take the GCP columns
      const softwareE = parseFloat(parts[4]);
      const softwareN = parseFloat(parts[5]);
      const softwareZ = parseFloat(parts[6]);
      const errorX = parseFloat(parts[7]);
      const errorY = parseFloat(parts[8]);
      const errorZ = parseFloat(parts[9]);
      const errorXY = parseFloat(parts[10]);
      const errorTotal = parts.length >= 12 ? parseFloat(parts[11]) : undefined;
      if (!isNaN(softwareE) && !isNaN(softwareN) && !isNaN(softwareZ)) {
        rows.push({
          id: Date.now() + Math.random(),
          name,
          softwareE,
          softwareN,
          softwareZ,
          errorX: isNaN(errorX) ? undefined : errorX,
          errorY: isNaN(errorY) ? undefined : errorY,
          errorZ: isNaN(errorZ) ? undefined : errorZ,
          errorXY: isNaN(errorXY) ? undefined : errorXY,
          errorTotal: errorTotal !== undefined && !isNaN(errorTotal) ? errorTotal : undefined,
          source: 'pix4d',
        });
      }
    }
  }
  return rows;
}

export function parseResiduals(text: string, format: ResidualFormat): ResidualRow[] {
  const detected = format === 'auto' ? detectFormat(text) : format;
  if (detected === 'pix4d') return parsePix4D(text);
  if (detected === 'agisoft') return parseAgisoft(text);
  // Try both
  const agisoft = parseAgisoft(text);
  const pix4d = parsePix4D(text);
  return agisoft.length >= pix4d.length ? agisoft : pix4d;
}

export function runValidation(
  knownGCPs: KnownGCP[],
  residuals: ResidualRow[],
  accuracyClass: AccuracyClass,
  utmZone: number
): ValidationSummary | null {
  if (knownGCPs.length === 0 || residuals.length === 0) return null;

  const knownMap = new Map<string, KnownGCP>();
  for (const g of knownGCPs) {
    knownMap.set(g.name.trim(), g);
  }

  const results: ValidationResult[] = [];
  const unmatched: string[] = [];

  for (const r of residuals) {
    const known = knownMap.get(r.name.trim());
    if (!known) {
      unmatched.push(r.name);
      continue;
    }

    const knownE = parseFloat(known.easting);
    const knownN = parseFloat(known.northing);
    const knownZ = parseFloat(known.elevation);
    if (isNaN(knownE) || isNaN(knownN) || isNaN(knownZ)) continue;

    const deltaE = r.softwareE - knownE;
    const deltaN = r.softwareN - knownN;
    const deltaZ = r.softwareZ - knownZ;
    const horizontalError = Math.sqrt(deltaE * deltaE + deltaN * deltaN);
    const error3D = Math.sqrt(deltaE * deltaE + deltaN * deltaN + deltaZ * deltaZ);

    const hPass = horizontalError <= accuracyClass.horizontal;
    const vPass = Math.abs(deltaZ) <= accuracyClass.vertical;

    results.push({
      name: r.name,
      knownE, knownN, knownZ,
      softwareE: r.softwareE, softwareN: r.softwareN, softwareZ: r.softwareZ,
      deltaE, deltaN, deltaZ,
      horizontalError, error3D,
      hPass, vPass, overallPass: hPass && vPass,
    });
  }

  if (results.length === 0) return null;

  const hErrors = results.map(r => r.horizontalError);
  const vErrors = results.map(r => Math.abs(r.deltaZ));
  const errors3D = results.map(r => r.error3D);

  const hRMSE = calculateRMSE(hErrors);
  const vRMSE = calculateRMSE(vErrors);
  const maxHorizontal = Math.max(...hErrors);
  const maxVertical = Math.max(...vErrors);
  const max3D = Math.max(...errors3D);

  const passCount = results.filter(r => r.overallPass).length;
  const failCount = results.length - passCount;

  return {
    points: results,
    hRMSE, vRMSE, maxHorizontal, maxVertical, max3D,
    hPass: hRMSE <= accuracyClass.horizontal,
    vPass: vRMSE <= accuracyClass.vertical,
    pass: (hRMSE <= accuracyClass.horizontal) && (vRMSE <= accuracyClass.vertical),
    passCount, failCount,
    totalGCPs: residuals.length,
    matchedGCPs: results.length,
    unmatchedNames: unmatched,
  };
}

