'use client';

import { useState } from 'react';
import { PageHeader } from '@/components/shared/PageHeader'
import { useLanguage } from '@/lib/i18n/LanguageContext'
import { 
  geodeticToECEF,
  ecefToGeodetic, 
  ecefToENU, 
  computeBaseline, 
  processGNSSNetwork,
  utmToGeodetic
} from '@/lib/geodesy/gnss';
import type { BaselineResult, GNSSBaseStation, GNSSNetworkResult } from '@/lib/geodesy/gnss';
import { logger } from '@/lib/logger'

interface Observation {
  id: number;
  name: string;
  lat: string;
  lon: string;
  h: string;
  sigma: string;
}

interface GNSSResult {
  baseline?: BaselineResult
  enu?: { easting: number; northing: number; up: number }
  baseECEF?: GNSSBaseStation
  obsECEF?: GNSSBaseStation
  points?: GNSSNetworkResult['points']
  adjustmentStats?: GNSSNetworkResult['adjustmentStats']
}

export default function GNSSProcessor() {
  const { t } = useLanguage()
  const [baseStation, setBaseStation] = useState({
    name: 'BASE01',
    lat: '-1.2921',
    lon: '36.8219',
    h: '1798.5'
  });
  
  const [origin, setOrigin] = useState({
    lat: '-1.2921',
    lon: '36.8219'
  });
  
  const [observations, setObservations] = useState<Observation[]>([
    { id: 1, name: 'ROVER1', lat: '-1.2915', lon: '36.8225', h: '1800.2', sigma: '0.015' },
    { id: 2, name: 'ROVER2', lat: '-1.2930', lon: '36.8210', h: '1795.8', sigma: '0.018' },
  ]);
  
  const [result, setResult] = useState<GNSSResult | null>(null);
  const [mode, setMode] = useState<'baseline' | 'network'>('baseline');

  const addObservation = () => {
    setObservations([
      ...observations,
      { id: Date.now(), name: `POINT${observations.length + 1}`, lat: '', lon: '', h: '', sigma: '0.015' }
    ]);
  };

  const updateObservation = (id: number, field: keyof Observation, value: string) => {
    setObservations(observations.map((o) => o.id === id ? { ...o, [field]: value } : o));
  };

  const removeObservation = (id: number) => {
    setObservations(observations.filter((o) => o.id !== id));
  };

  const calculate = () => {
    try {
      const baseECEF = geodeticToECEF(
        parseFloat(baseStation.lat),
        parseFloat(baseStation.lon),
        parseFloat(baseStation.h)
      );
      baseECEF.name = baseStation.name;

      if (mode === 'baseline') {
        const obs = observations[0];
        if (!obs.lat || !obs.lon) return;
        const obsECEF = geodeticToECEF(
          parseFloat(obs.lat),
          parseFloat(obs.lon),
          parseFloat(obs.h) || 0
        );
        obsECEF.name = obs.name;
        const baseline = computeBaseline(
          { pointName: baseStation.name, ...baseECEF },
          { pointName: obs.name, x: obsECEF.x, y: obsECEF.y, z: obsECEF.z, sigmaX: parseFloat(obs.sigma) }
        );
        const enu = ecefToENU(obsECEF.x, obsECEF.y, obsECEF.z, parseFloat(origin.lat), parseFloat(origin.lon), 0);
        setResult({ baseline, enu, baseECEF, obsECEF });
      } else {
        const obsData = observations.map((o) => ({
          pointName: o.name,
          x: 0, y: 0, z: 0,
          sigmaX: parseFloat(o.sigma)
        })).map((o, i) => {
          const ecef = geodeticToECEF(
            parseFloat(observations[i].lat),
            parseFloat(observations[i].lon),
            parseFloat(observations[i].h) || 0
          );
          return { ...o, x: ecef.x, y: ecef.y, z: ecef.z };
        });
        const network = processGNSSNetwork(
          baseECEF,
          obsData,
          parseFloat(origin.lat),
          parseFloat(origin.lon),
          0
        );
        setResult(network);
      }
    } catch (e) {
      logger.error(e instanceof Error ? e.message : String(e));
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader title={t('tools.gnss')} subtitle={t('tools.gnssDesc')} reference="Survey Regulations 1994  |  RDM 1.1 (2025) Section 5.6  |  WGS84 / SRID 21037" />

      <div className="flex gap-4 mb-6">
        <button onClick={() => { setMode('baseline'); setResult(null); }} className={`btn ${mode === 'baseline' ? 'btn-primary' : 'btn-secondary'}`}>
          Single Baseline
        </button>
        <button onClick={() => { setMode('network'); setResult(null); }} className={`btn ${mode === 'network' ? 'btn-primary' : 'btn-secondary'}`}>
          Network Adjustment
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="space-y-6">
          <div className="bg-[var(--card)] border border-[var(--border)] rounded-lg p-4">
            <h3 className="font-semibold mb-4">Base Station</h3>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm mb-1" htmlFor="name">Name</label>
                <input id="name" aria-label="Name" type="text" value={baseStation.name} onChange={e => setBaseStation({...baseStation, name: e.target.value})} className="input w-full" />
              </div>
              <div>
                <label className="block text-sm mb-1" htmlFor="ellipsoidal-height-m">Ellipsoidal Height (m)</label>
                <input id="ellipsoidal-height-m" aria-label="H" type="text" value={baseStation.h} onChange={e => setBaseStation({...baseStation, h: e.target.value})} className="input w-full" />
              </div>
              <div>
                <label className="block text-sm mb-1" htmlFor="latitude-decimal">Latitude (decimal °)</label>
                <input id="latitude-decimal" type="text" value={baseStation.lat} onChange={e => setBaseStation({...baseStation, lat: e.target.value})} className="input w-full" placeholder="-1.2921" />
              </div>
              <div>
                <label className="block text-sm mb-1" htmlFor="longitude-decimal">Longitude (decimal °)</label>
                <input id="longitude-decimal" type="text" value={baseStation.lon} onChange={e => setBaseStation({...baseStation, lon: e.target.value})} className="input w-full" placeholder="36.8219" />
              </div>
            </div>
          </div>

          <div className="bg-[var(--card)] border border-[var(--border)] rounded-lg p-4">
            <h3 className="font-semibold mb-4">Local Origin (for ENU)</h3>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm mb-1" htmlFor="latitude">Latitude</label>
                <input id="latitude" aria-label="Lat" type="text" value={origin.lat} onChange={e => setOrigin({...origin, lat: e.target.value})} className="input w-full" />
              </div>
              <div>
                <label className="block text-sm mb-1" htmlFor="longitude">Longitude</label>
                <input id="longitude" aria-label="Lon" type="text" value={origin.lon} onChange={e => setOrigin({...origin, lon: e.target.value})} className="input w-full" />
              </div>
            </div>
          </div>

          <div className="bg-[var(--card)] border border-[var(--border)] rounded-lg p-4">
            <div className="flex justify-between items-center mb-4">
