  // Certificate
  const [surveyorName, setSurveyorName] = useState('')
  const [surveyorLicense, setSurveyorLicense] = useState('')
  const [surveyType, setSurveyType] = useState('cadastral')
  const [locality, setLocality] = useState('')
  const [certResult, setCertResult] = useState('')

  // Elective check
  const [electiveId, setElectiveId] = useState('setting_out')
  const [electiveArea, setElectiveArea] = useState('')
  const [electiveUnits, setElectiveUnits] = useState('')
  const [electiveLinear, setElectiveLinear] = useState('')
  const [electiveResult, setElectiveResult] = useState<ElectiveCheckResult | null>(null)

  useEffect(() => { loadData() }, [])

  const loadData = async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/regulations')
      if (res.ok) { const d = (await res.json()) as { data: RegulationsData }; setData(d.data) }
    } catch {} finally { setLoading(false) }
  }

  const checkInstrument = async () => {
    const res = await fetch('/api/regulations', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ check_type: 'instrument', brand, model, requiredOrder }),
    })
    if (res.ok) { const d = (await res.json()) as { data: InstrumentCheckResult }; setInstrumentResult(d.data) }
  }

  const checkScale = async () => {
    const res = await fetch('/api/regulations', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ check_type: 'scale', areaHa: parseFloat(areaHa) }),
    })
    if (res.ok) { const d = (await res.json()) as { data: ScaleCheckResult }; setScaleResult(d.data) }
  }

  const generateCert = async () => {
    const res = await fetch('/api/regulations', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        check_type: 'certificate', surveyorName, surveyorLicense,
        surveyType, locality, areaHa: parseFloat(areaHa) || 0, scale: scaleResult?.label || '1:1250',
      }),
    })
    if (res.ok) { const d = (await res.json()) as { data: string }; setCertResult(d.data) }
  }

  const checkElective = async () => {
    const body: Record<string, unknown> = { check_type: 'elective', electiveId }
    if (electiveArea) body.areaHa = parseFloat(electiveArea)
    if (electiveUnits) body.unitCount = parseInt(electiveUnits)
    if (electiveLinear) body.linearLengthKm = parseFloat(electiveLinear)
    const res = await fetch('/api/regulations', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    })
    if (res.ok) { const d = (await res.json()) as { data: ElectiveCheckResult }; setElectiveResult(d.data) }
  }

  const inputCls = "w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] focus:border-[var(--accent)]/30 focus:outline-none"

  if (loading) return <div className="min-h-screen flex items-center justify-center text-sm text-[var(--text-muted)]">Loading...</div>

  return (
    <div className="min-h-screen p-6 max-w-5xl mx-auto">
      <h1 className="text-2xl font-bold text-[var(--text-primary)] mb-2">Regulatory Checklist</h1>
      <p className="text-sm text-[var(--text-muted)] mb-6">Survey Regulations 1994 — instrument approval, field notes, scales, areas, certificates, and elective survey types</p>

      {/* Instrument Approval (Reg 55) */}
      <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
        <h2 className="text-sm font-semibold mb-2 flex items-center gap-2"><Wrench className="w-4 h-4" /> Reg 55(2): Instrument Approval</h2>
        <div className="grid grid-cols-3 gap-2 mb-2">
          <input value={brand} onChange={e => setBrand(e.target.value)} className={inputCls} placeholder="Brand (e.g. Leica)" />
          <input value={model} onChange={e => setModel(e.target.value)} className={inputCls} placeholder="Model (e.g. TS16)" />
          <select value={requiredOrder} onChange={e => setRequiredOrder(e.target.value)} className={inputCls}>
            <option>First Order Class I</option><option>First Order Class II</option>
            <option>Second Order Class I</option><option>Second Order Class II</option>
            <option>Third Order</option><option>Fourth Order</option>
          </select>
        </div>
        <button onClick={checkInstrument} className="px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)]">Check Approval</button>
        {instrumentResult && (
          <div className={`mt-2 p-2 rounded text-xs ${instrumentResult.approved ? 'text-green-400 bg-green-500/10' : 'text-red-400 bg-red-500/10'}`}>
            {instrumentResult.approved ? '✓' : '✗'} {instrumentResult.message}
          </div>
        )}
        {data?.instruments && (
          <div className="mt-3 text-[10px] text-[var(--text-muted)]">
            <div className="font-semibold mb-1">Approved Instruments ({data.instruments.length}):</div>
            <div className="grid grid-cols-3 gap-1 max-h-32 overflow-y-auto">
              {data.instruments.map((inst, i) => (
                <div key={i} className="px-2 py-0.5 rounded bg-[var(--bg-tertiary)]">
                  {inst.brand} {inst.model} <span className="opacity-50">({inst.type})</span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Standard Scales (Reg 89) */}
      <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
        <h2 className="text-sm font-semibold mb-2 flex items-center gap-2"><Scale className="w-4 h-4" /> Reg 89: Standard Plotting Scale</h2>
        <div className="flex gap-2 items-end mb-2">
          <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="area-ha">Area (ha)</label><input id="area-ha" value={areaHa} onChange={e => setAreaHa(e.target.value)} className={inputCls + ' w-32'} placeholder="0.5" /></div>
          <button onClick={checkScale} className="px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)]">Select Scale</button>
        </div>
        {scaleResult && (
          <div className="mt-2 p-2 rounded text-xs text-green-400 bg-green-500/10">
            ✓ Recommended scale: <span className="font-bold">{scaleResult.label}</span> — {scaleResult.useCase}
          </div>
        )}
        <div className="mt-2 grid grid-cols-3 gap-1 text-[10px] text-[var(--text-muted)]">
          {data?.standardScales?.map((s) => (
            <div key={s.scale} className="px-2 py-0.5 rounded bg-[var(--bg-tertiary)]">{s.label} — ≤{s.maxAreaHa}ha</div>
          ))}
        </div>
      </div>

      {/* Surveyor Certificate (Reg 97) */}
      <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
        <h2 className="text-sm font-semibold mb-2 flex items-center gap-2"><FileCheck className="w-4 h-4" /> Reg 97: Surveyor Certificate</h2>
        <div className="grid grid-cols-2 gap-2 mb-2">
          <input value={surveyorName} onChange={e => setSurveyorName(e.target.value)} className={inputCls} placeholder="Surveyor Name" />
          <input value={surveyorLicense} onChange={e => setSurveyorLicense(e.target.value)} className={inputCls} placeholder="ISK License No." />
          <input value={locality} onChange={e => setLocality(e.target.value)} className={inputCls} placeholder="Locality" />
          <select value={surveyType} onChange={e => setSurveyType(e.target.value)} className={inputCls}>
            <option value="cadastral">Cadastral</option><option value="topographic">Topographic</option>
            <option value="engineering">Engineering</option><option value="control">Control</option>
            <option value="sectional">Sectional Property</option><option value="perimeter">Perimeter/Farm</option>
          </select>
        </div>
        <button onClick={generateCert} className="px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)]">Generate Certificate</button>
        {certResult && (
          <div className="mt-2">
            <pre className="text-[9px] text-[var(--text-secondary)] whitespace-pre-wrap font-mono bg-[var(--bg-tertiary)] p-3 rounded-lg max-h-60 overflow-y-auto">{certResult}</pre>
            <button onClick={() => { const blob = new Blob([certResult], { type: 'text/plain' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'survey_certificate.txt'; a.click(); URL.revokeObjectURL(url) }} className="mt-2 flex items-center gap-1.5 px-3 py-1.5 bg-[var(--accent)]/15 border border-[var(--accent)]/30 text-[var(--accent)] text-[10px] font-semibold rounded-lg">
              <Download className="w-3 h-3" /> Download Certificate
            </button>
          </div>
        )}
      </div>

      {/* Elective Survey Types (License Application) */}
      <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
        <h2 className="text-sm font-semibold mb-2 flex items-center gap-2"><Award className="w-4 h-4" /> License Elective Survey Types</h2>
        <div className="grid grid-cols-2 gap-2 mb-2">
          <select value={electiveId} onChange={e => setElectiveId(e.target.value)} className={inputCls}>
            {data?.electives?.map((e) => <option key={e.id} value={e.id}>{e.name}</option>)}
          </select>
          <div className="grid grid-cols-3 gap-1">
            <input value={electiveArea} onChange={e => setElectiveArea(e.target.value)} className={inputCls} placeholder="Area (ha)" />
            <input value={electiveUnits} onChange={e => setElectiveUnits(e.target.value)} className={inputCls} placeholder="Units" />
            <input value={electiveLinear} onChange={e => setElectiveLinear(e.target.value)} className={inputCls} placeholder="Linear (km)" />
          </div>
        </div>
        <button onClick={checkElective} className="px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)]">Check Requirement</button>
        {electiveResult && (
          <div className="mt-2 space-y-2">
            <div className={`p-2 rounded text-xs ${electiveResult.check.met ? 'text-green-400 bg-green-500/10' : 'text-red-400 bg-red-500/10'}`}>
              {electiveResult.check.met ? '✓' : '✗'} {electiveResult.check.details}
            </div>
            {electiveResult.elective && (
              <div className="text-[10px] text-[var(--text-muted)]">
                <div className="font-semibold">{electiveResult.elective.description}</div>
                <div className="mt-1"><span className="opacity-60">Required:</span> {electiveResult.elective.minimumRequirement}</div>
                <div className="mt-1"><span className="opacity-60">Deliverables:</span></div>
                {electiveResult.elective.deliverables.map((d: string, i: number) => <div key={i} className="ml-3">• {d}</div>)}
                <div className="mt-1"><span className="opacity-60">Regulations:</span></div>
                {electiveResult.elective.regulations.map((r: string, i: number) => <div key={i} className="ml-3">• {r}</div>)}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

'use client';

import { ToolExportButtons } from '@/components/shared/ToolExportButtons'
import { useState } from 'react'
import HorizontalCurveCalculator from '@/components/road-design/HorizontalCurveCalculator'
import { PageHeader } from '@/components/shared/PageHeader'
import VerticalCurveCalculator from '@/components/road-design/VerticalCurveCalculator'
import SuperelevationCalculator from '@/components/road-design/SuperelevationCalculator'
import SightDistanceChecker from '@/components/road-design/SightDistanceChecker'
import { useLanguage } from '@/lib/i18n/LanguageContext'

type Tab = 'horizontal' | 'vertical' | 'superelevation' | 'sight'

const TABS: Array<{ id: Tab; label: string; desc: string }> = [
  { id: 'horizontal', label: 'Horizontal Curve', desc: 'T, L, C, M, E, D — TC/CC/CT chainages — set-out table' },
  { id: 'vertical', label: 'Vertical Curve', desc: 'BVC/EVC chainages+RLs, RL at any point, peak/sag point' },
  { id: 'superelevation', label: 'Superelevation', desc: 'Required e, design e (capped 8%), transition length Ls' },
  { id: 'sight', label: 'Sight Distance', desc: 'SSD, PSD, minimum radius compliance (RDM 1.3 Tables 3-3 to 3-6)' },
]

export default function RoadDesignPage() {
  const { t } = useLanguage()
  const [tab, setTab] = useState<Tab>('horizontal')

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.roadDesign')}
        subtitle={t('tools.roadDesignDesc')}
      />

      <div className="flex gap-1 border-b border-[var(--border-color)] mb-6 overflow-x-auto">
        {TABS.map((t) => (
          <button key={t.id} onClick={() => setTab(t.id)}
            className={`px-4 py-2.5 text-sm font-medium whitespace-nowrap rounded-t border-b-2 transition-all ${tab === t.id ? 'border-[var(--accent)] text-[var(--accent)]' : 'border-transparent text-[var(--text-muted)] hover:text-[var(--text-primary)]'}`}>
            {t.label}
          </button>
        ))}
      </div>

      <div className="bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg p-6">
        {tab === 'horizontal' && (
          <>
            <h2 className="text-lg font-semibold mb-1">Horizontal Curve Elements &amp; Set-Out</h2>
            <p className="text-xs text-[var(--text-muted)] mb-4">Source: RDM 1.3 §5.2 | Ghilani &amp; Wolf Ch.24 | Basak Ch.14-16 | Schofield &amp; Breach Ch.11</p>
            <HorizontalCurveCalculator />
          </>
        )}
        {tab === 'vertical' && (
          <>
            <h2 className="text-lg font-semibold mb-1">Vertical Curve Design</h2>
            <p className="text-xs text-[var(--text-muted)] mb-4">Source: RDM 1.3 §5.4 | Ghilani &amp; Wolf Ch.25</p>
            <VerticalCurveCalculator />
          </>
        )}
        {tab === 'superelevation' && (
          <>
            <h2 className="text-lg font-semibold mb-1">Superelevation Design</h2>
            <p className="text-xs text-[var(--text-muted)] mb-4">Source: RDM 1.3 §5.3 | RDM 1.3 Table 3-4 (friction factors)</p>
            <SuperelevationCalculator />
          </>
        )}
        {tab === 'sight' && (
          <>
            <h2 className="text-lg font-semibold mb-1">Sight Distance &amp; Radius Compliance</h2>
            <p className="text-xs text-[var(--text-muted)] mb-4">Source: RDM 1.3 §3.3 | Tables 3-3 to 3-6</p>
            <SightDistanceChecker />
          </>
        )}
      </div>
    </div>
  )
}

'use client';

/**
 * NTRIP / RTK Corrections Client
 *
 * AUDIT FIX (2026-07-03): Real-time GNSS correction client for receiving
 * RTK corrections from CORS networks (KENCORS, TANZACORS, etc.) via NTRIP.
 */

import { useState, useEffect, useRef, useCallback } from 'react'
import { PageHeader } from '@/components/shared/PageHeader'
import { Satellite, Wifi, WifiOff, Activity, Zap } from 'lucide-react'
import { CORS_NETWORKS, RTCM_TYPE_NAMES, type RTCMMessage } from '@/lib/gnss/ntripClient'

export default function NTRIPClientPage() {
  const [network, setNetwork] = useState(CORS_NETWORKS[0].id)
  const [host, setHost] = useState(CORS_NETWORKS[0].host)
  const [port, setPort] = useState(CORS_NETWORKS[0].port)
  const [mountpoint, setMountpoint] = useState('')
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [connected, setConnected] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [messages, setMessages] = useState<RTCMMessage[]>([])
  const [messageCount, setMessageCount] = useState(0)
  const [lastMessageAt, setLastMessageAt] = useState<string | null>(null)
  const [statusMsg, setStatusMsg] = useState('')

  const eventSourceRef = useRef<EventSource | null>(null)

  useEffect(() => {
    const net = CORS_NETWORKS.find(n => n.id === network)
    if (net) { setHost(net.host); setPort(net.port) }
  }, [network])

  const connect = useCallback(() => {
    if (!host || !mountpoint) { setError('Host and mountpoint are required'); return }
    setError(null); setStatusMsg('Connecting...'); setMessages([]); setMessageCount(0)
    const params = new URLSearchParams({ host, port: String(port), mountpoint })
    if (username) params.set('user', username)
    if (password) params.set('pass', password)
    const es = new EventSource(`/api/gnss/ntrip?${params}`)
    eventSourceRef.current = es
    es.addEventListener('status', (e) => {
      const data = JSON.parse((e as MessageEvent).data as string) as { message?: string; error?: string; connected?: boolean }
      setStatusMsg(data.message || data.error || '')
      if (data.connected) { setConnected(true); setError(null) }
      else { setConnected(false); if (data.error) setError(data.error) }
    })
    es.addEventListener('rtcm', (e) => {
      const data = JSON.parse((e as MessageEvent).data as string) as { messageCount?: number; lastMessageAt?: string; type?: number; length?: number; receivedAt?: string }
      setMessageCount(data.messageCount ?? 0); setLastMessageAt(data.lastMessageAt ?? null)
      setMessages(prev => [...prev, { type: data.type ?? 0, length: data.length ?? 0, receivedAt: data.receivedAt ?? '' }].slice(-50))
    })
    es.onerror = () => { setConnected(false); setError('Connection lost'); es.close() }
  }, [host, port, mountpoint, username, password])

  const disconnect = useCallback(() => {
    if (eventSourceRef.current) { eventSourceRef.current.close(); eventSourceRef.current = null }
    setConnected(false); setStatusMsg('Disconnected')
  }, [])

  useEffect(() => { return () => { if (eventSourceRef.current) eventSourceRef.current.close() } }, [])

  const correctionAge = lastMessageAt ? Math.round((Date.now() - new Date(lastMessageAt).getTime()) / 1000) : null
  const messageTypeCounts = messages.reduce((acc, m) => { acc[m.type] = (acc[m.type] || 0) + 1; return acc }, {} as Record<number, number>)
  const selectedNetwork = CORS_NETWORKS.find(n => n.id === network)

  return (
    <div className="max-w-5xl mx-auto px-4 py-8">
      <PageHeader title="RTK Corrections (NTRIP)" subtitle="Real-time GNSS correction stream from CORS networks" reference="NTRIP v2 (RTCM 10410.1) | RTCM 3.3 | KENCORS" />
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="space-y-4">
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
            <h2 className="text-sm font-semibold text-white mb-4">Connection Settings</h2>
            <div className="space-y-3">
              <div>
                <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="cors-network">CORS Network</label>
                <select id="cors-network" value={network} onChange={e => setNetwork(e.target.value)} className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white">
                  {CORS_NETWORKS.map(n => <option key={n.id} value={n.id}>{n.name}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-3 gap-3">
                <div className="col-span-2">
                  <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="caster-host">Caster Host</label>
                  <input id="caster-host" type="text" value={host} onChange={e => setHost(e.target.value)} className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white font-mono" />
                </div>
                <div>
                  <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="port">Port</label>
                  <input id="port" type="number" value={port} onChange={e => setPort(parseInt(e.target.value) || 2101)} className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white font-mono" />
                </div>
              </div>
              <div>
                <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="mountpoint">Mountpoint</label>
                <input id="mountpoint" type="text" value={mountpoint} onChange={e => setMountpoint(e.target.value)} placeholder="NBI0" className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white font-mono" />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="username-optional">Username (optional)</label>
                  <input id="username-optional" type="text" value={username} onChange={e => setUsername(e.target.value)} className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white" />
                </div>
                <div>
                  <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="password">Password</label>
                  <input  id="password" type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white" />
                </div>
              </div>
              <div className="flex gap-2 pt-2">
                {!connected ? (
                  <button onClick={connect} disabled={!host || !mountpoint} className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg text-sm font-semibold disabled:opacity-40 hover:bg-green-700">
                    <Wifi className="w-4 h-4" /> Connect
                  </button>
                ) : (
                  <button onClick={disconnect} className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg text-sm font-semibold hover:bg-red-700">
                    <WifiOff className="w-4 h-4" /> Disconnect
                  </button>
                )}
              </div>
            </div>
          </div>
          {selectedNetwork?.description && (
            <div className="bg-blue-500/5 border border-blue-500/15 rounded-xl p-4">
              <h3 className="text-sm font-semibold text-blue-400 mb-1">{selectedNetwork.name}</h3>
              <p className="text-xs text-[var(--text-muted)] leading-relaxed">{selectedNetwork.description}</p>
            </div>
          )}
        </div>
        <div className="space-y-4">
          <div className={`rounded-xl p-6 border ${connected ? 'bg-green-500/5 border-green-500/20' : 'bg-[var(--bg-card)] border-[var(--border-color)]'}`}>
            <div className="flex items-center gap-3 mb-4">
              {connected ? <Satellite className="w-6 h-6 text-green-400 animate-pulse" /> : <Satellite className="w-6 h-6 text-[var(--text-muted)]" />}
              <div>
                <div className="text-sm font-semibold text-white">{connected ? 'Connected' : 'Disconnected'}</div>
                <div className="text-xs text-[var(--text-muted)]">{statusMsg}</div>
              </div>
            </div>
            {error && <div className="p-3 rounded-lg bg-red-900/20 border border-red-700/40 text-red-400 text-xs mb-3">{error}</div>}
            <div className="grid grid-cols-3 gap-3">
              <div className="p-3 bg-[var(--bg-tertiary)] rounded-lg text-center">
                <div className="text-2xl font-bold text-white">{messageCount}</div>
                <div className="text-[10px] text-[var(--text-muted)] uppercase">Messages</div>
              </div>
              <div className="p-3 bg-[var(--bg-tertiary)] rounded-lg text-center">
                <div className={`text-2xl font-bold ${correctionAge !== null && correctionAge > 10 ? 'text-red-400' : 'text-white'}`}>{correctionAge !== null ? `${correctionAge}s` : '—'}</div>
                <div className="text-[10px] text-[var(--text-muted)] uppercase">Corr. Age</div>
              </div>
              <div className="p-3 bg-[var(--bg-tertiary)] rounded-lg text-center">
                <div className="text-2xl font-bold text-white">{Object.keys(messageTypeCounts).length}</div>
                <div className="text-[10px] text-[var(--text-muted)] uppercase">Msg Types</div>
              </div>
            </div>
          </div>
          {messages.length > 0 && (
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-4">
              <h3 className="text-sm font-semibold text-white mb-3 flex items-center gap-2"><Activity className="w-4 h-4 text-[var(--accent)]" />RTCM Message Types</h3>
              <div className="space-y-1 max-h-[200px] overflow-y-auto">
                {Object.entries(messageTypeCounts).sort((a, b) => b[1] - a[1]).map(([type, count]) => (
                  <div key={type} className="flex items-center justify-between text-xs">
                    <span className="font-mono text-[var(--text-muted)]">Type {type}</span>
                    <span className="text-white">{RTCM_TYPE_NAMES[parseInt(type)] || 'Unknown'}</span>
                    <span className="font-mono text-[var(--accent)]">{count}×</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

'use client'
import { useState } from 'react'
import { PageHeader } from '@/components/shared/PageHeader'
import { createSectionalPlan, type SectionalFloor, type SectionalUnit } from '@/lib/cadastral/sectionalAndEncumbrance'

export default function SectionalPropertiesPage() {
  const [buildingName, setBuildingName] = useState('Riverside Apartments')
  const [lrNumber, setLrNumber] = useState('NAIROBI/BLOCK 72/1234')
  const [units, setUnits] = useState<Array<{ unitNumber: string; floor: number; type: SectionalUnit['type']; area: number; description: string }>>([
    { unitNumber: 'A1', floor: 0, type: 'residential', area: 85, description: '2-bedroom' },
    { unitNumber: 'A2', floor: 0, type: 'residential', area: 85, description: '2-bedroom' },
    { unitNumber: 'B1', floor: 1, type: 'residential', area: 90, description: '3-bedroom' },
    { unitNumber: 'P1', floor: -1, type: 'parking', area: 12, description: 'Parking bay' },
  ])
  const [plan, setPlan] = useState<ReturnType<typeof createSectionalPlan> | null>(null)

  const addUnit = () => setUnits([...units, { unitNumber: `U${units.length + 1}`, floor: 0, type: 'residential', area: 50, description: '' }])
  const removeUnit = (i: number) => setUnits(units.filter((_, idx) => idx !== i))

  const generate = () => {
    const floors: SectionalFloor[] = []
    const floorMap = new Map<number, typeof units>()
    for (const u of units) {
      if (!floorMap.has(u.floor)) floorMap.set(u.floor, [])
      floorMap.get(u.floor)!.push(u)
    }
    for (const [floor, floorUnits] of floorMap) {
      const sectionUnits: SectionalUnit[] = floorUnits.map((u, i) => ({
        id: `unit-${i}`, unitNumber: u.unitNumber, floor, type: u.type, area: u.area, description: u.description,
      }))
      const totalArea = sectionUnits.reduce((s, u) => s + u.area, 0) + 20 // +20 for common
      floors.push({ floor, name: floor === 0 ? 'Ground Floor' : floor > 0 ? `Floor ${floor}` : `Basement ${-floor}`, totalArea, units: sectionUnits })
    }
    floors.sort((a, b) => a.floor - b.floor)
    setPlan(createSectionalPlan(buildingName, lrNumber, floors))
  }

  return (
    <div className="max-w-5xl mx-auto px-4 py-8">
      <PageHeader title="Sectional Properties" subtitle="Apartment units, parking, common areas per Act 2020" reference="Sectional Properties Act 2020 (Kenya)" />
      <div className="grid lg:grid-cols-2 gap-8">
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="building-name">Building Name</label><input id="building-name" value={buildingName} onChange={e => setBuildingName(e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="lr-number">LR Number</label><input id="lr-number" value={lrNumber} onChange={e => setLrNumber(e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
          </div>
          <div>
            <div className="flex justify-between items-center mb-2"><div className="text-sm text-zinc-400">Units</div><button onClick={addUnit} className="text-xs px-2 py-1 bg-[var(--accent)] text-black rounded">+ Add Unit</button></div>
            <div className="space-y-2 max-h-64 overflow-y-auto">{units.map((u, i) => (
              <div key={i} className="flex gap-2 items-center">
                <input aria-label={`Unit ${i + 1} number`} value={u.unitNumber} onChange={e => { const v = [...units]; v[i].unitNumber = e.target.value; setUnits(v) }} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-2 py-1.5 text-white text-xs" />
                <input aria-label={`Unit ${i + 1} floor`} type="number" value={u.floor} onChange={e => { const v = [...units]; v[i].floor = +e.target.value; setUnits(v) }} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-2 py-1.5 text-white text-xs" />
                <select aria-label={`Unit ${i + 1} type`} value={u.type} onChange={e => { const v = [...units]; v[i].type = e.target.value as SectionalUnit['type']; setUnits(v) }} className="bg-zinc-800 border border-zinc-700 rounded px-2 py-1.5 text-white text-xs"><option value="residential">Residential</option><option value="commercial">Commercial</option><option value="parking">Parking</option><option value="common">Common</option></select>
                <input aria-label={`Unit ${i + 1} area (m²)`} type="number" value={u.area} onChange={e => { const v = [...units]; v[i].area = +e.target.value; setUnits(v) }} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-2 py-1.5 text-white text-xs" />
                <button aria-label={`Remove unit ${i + 1}`} onClick={() => removeUnit(i)} className="text-red-400 text-xs px-1">×</button>
              </div>
            ))}</div>
          </div>
          <button onClick={generate} className="w-full py-3 bg-[var(--accent)] hover:bg-[var(--accent)]/90 text-black font-semibold rounded-lg">Generate Sectional Plan</button>
        </div>
        <div>
          {plan ? (
            <div className="space-y-4">
              <div className="grid grid-cols-3 gap-3">
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">Total Area</div><div className="text-lg font-bold text-white">{plan.totalArea.toFixed(0)} m²</div></div>
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">Unit Area</div><div className="text-lg font-bold text-amber-400">{plan.totalUnitArea.toFixed(0)} m²</div></div>
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">Common Area</div><div className="text-lg font-bold text-blue-400">{plan.totalCommonArea.toFixed(0)} m²</div></div>
              </div>
              <div className="overflow-x-auto"><h3 className="text-sm font-semibold text-white mb-2">Participation Quotas</h3><table className="w-full text-sm"><thead><tr className="text-zinc-500 border-b border-zinc-700"><th className="text-left py-2">Unit</th><th className="text-right py-2">Quota (%)</th></tr></thead><tbody>{plan.participationQuotas.map((q, i) => (<tr key={i} className="border-b border-zinc-800"><td className="py-1.5 font-mono text-amber-400">{q.unitNumber}</td><td className="py-1.5 text-right font-mono text-white">{q.quota.toFixed(4)}%</td></tr>))}</tbody></table></div>
            </div>
          ) : <div className="p-6 bg-zinc-900 rounded-lg border border-zinc-700 text-center text-sm text-zinc-400">Add units and click Generate.</div>}
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useCallback } from 'react'
import { Upload, Download, FileSpreadsheet, AlertCircle, CheckCircle2 } from 'lucide-react'
import { getAvailableFormats, exportStakeout, type InstrumentFormat } from '@/lib/survey/instrumentWriters'
import { computeSettingOut, type SettingOutResult, type InstrumentStation, type Backsight } from '@/lib/computations/settingOutEngine'
import { extractDesignPointsFromDXF } from '@/lib/survey/dxfDesignExtractor'
import { compareAsBuiltToDesign, type ComparisonReport } from '@/lib/survey/asBuiltComparison'

export default function SettingOutPage() {
  const [dxfContent, setDxfContent] = useState('')
  const [stationE, setStationE] = useState('')
  const [stationN, setStationN] = useState('')
  const [stationRL, setStationRL] = useState('0')
  const [backsightE, setBacksightE] = useState('')
  const [backsightN, setBacksightN] = useState('')
  const [result, setResult] = useState<SettingOutResult | null>(null)
  const [warnings, setWarnings] = useState<string[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [exportFormat, setExportFormat] = useState<InstrumentFormat>('CSV')
  const [comparison, setComparison] = useState<ComparisonReport | null>(null)
  const [asBuiltInput, setAsBuiltInput] = useState('')

  const handleFileUpload = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = () => setDxfContent(reader.result as string)
    reader.readAsText(file)
  }, [])

  const handleImport = async () => {
    if (!dxfContent || !stationE || !stationN || !backsightE || !backsightN) {
      setError('DXF file and station/backsight coordinates are required')
      return
    }
    setLoading(true); setError(''); setResult(null); setWarnings([])
    try {
      // Run the parsing completely on the client (offline-first)
      const extraction = extractDesignPointsFromDXF(dxfContent, { layerFilter: [] })
      if (extraction.points.length === 0) {
        throw new Error('No design points found in DXF')
      }

      const station: InstrumentStation = {
        e: parseFloat(stationE),
        n: parseFloat(stationN),
        rl: parseFloat(stationRL || '0'),
        ih: 1.5,
      }
      const backsight: Backsight = {
        e: parseFloat(backsightE),
        n: parseFloat(backsightN),
      }

      const computedResult = computeSettingOut(station, backsight, extraction.points)
      setResult(computedResult)
      setWarnings(extraction.warnings || [])
    } catch (e) { 
      setError(e instanceof Error ? e.message : 'Failed to process DXF locally') 
    }
    finally { setLoading(false) }
  }

  const handleExport = async () => {
    if (!result) return
    try {
      // Generate export locally
      const exportData = exportStakeout(result, exportFormat, { stationName: 'STN1' })
      const blob = new Blob([exportData.content], { type: exportData.mimeType })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url; a.download = exportData.filename; a.click()
      URL.revokeObjectURL(url)
    } catch (e) { 
      setError(e instanceof Error ? e.message : 'Export failed locally') 
    }
  }

  const handleCompare = () => {
    if (!result) return
    try {
      const asBuiltPoints = asBuiltInput.trim().split('\n').map(line => {
        const cols = line.split(',').map(c => c.trim())
        return { id: cols[0], e: parseFloat(cols[1]), n: parseFloat(cols[2]), rl: parseFloat(cols[3] || '0') }
      }).filter(p => p.id && !isNaN(p.e) && !isNaN(p.n))

      const designPoints = result.rows.map(r => ({
        id: r.id, e: r.designE, n: r.designN, rl: r.designRL, th: r.TH,
      }))

      const report = compareAsBuiltToDesign({ designPoints, asBuiltPoints })
      setComparison(report)
    } catch { setError('Failed to parse as-built CSV. Use: id,easting,northing,rl') }
  }

  const inputCls = "w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"

  return (
    <div className="min-h-screen p-6 max-w-6xl mx-auto">
      <h1 className="text-2xl font-bold text-[var(--text-primary)] mb-2">Setting Out</h1>
      <p className="text-sm text-[var(--text-muted)] mb-6">Import design from DXF → compute stakeout list → export to instrument → compare as-built</p>

      {/* Step 1: Import DXF */}
      <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
        <h2 className="text-sm font-semibold text-[var(--text-primary)] mb-3">1. Import Design from DXF</h2>
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="dxf-file">DXF File</label>
            <input id="dxf-file" type="file" accept=".dxf" onChange={handleFileUpload}
              className="w-full text-xs text-[var(--text-secondary)]" />
            {dxfContent && <CheckCircle2 className="w-4 h-4 text-green-500 inline ml-2" />}
          </div>
          <div className="grid grid-cols-2 gap-2">
            <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="station-e">Station E</label><input id="station-e" value={stationE} onChange={e => setStationE(e.target.value)} className={inputCls} placeholder="264000" /></div>
            <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="station-n">Station N</label><input id="station-n" value={stationN} onChange={e => setStationN(e.target.value)} className={inputCls} placeholder="9861000" /></div>
            <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="station-rl">Station RL</label><input id="station-rl" value={stationRL} onChange={e => setStationRL(e.target.value)} className={inputCls} /></div>
            <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="ih">IH</label><input id="ih" defaultValue="1.5" className={inputCls} /></div>
            <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="backsight-e">Backsight E</label><input id="backsight-e" value={backsightE} onChange={e => setBacksightE(e.target.value)} className={inputCls} /></div>
            <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="backsight-n">Backsight N</label><input id="backsight-n" value={backsightN} onChange={e => setBacksightN(e.target.value)} className={inputCls} /></div>
          </div>
        </div>
        <button onClick={handleImport} disabled={loading} className="mt-3 px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-50">
          {loading ? 'Computing...' : 'Compute Stakeout List'}
        </button>
      </div>

      {warnings.length > 0 && (
        <div className="bg-yellow-500/10 border border-yellow-500/20 rounded-lg p-3 mb-4 text-xs text-yellow-400">
          {warnings.map((w, i) => <div key={i}>⚠ {w}</div>)}
        </div>
      )}
      {error && <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 mb-4 text-xs text-red-400 flex items-center gap-2"><AlertCircle className="w-4 h-4" /> {error}</div>}

      {/* Step 2: Stakeout List */}
      {result && (
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
          <div className="flex justify-between items-center mb-3">
            <h2 className="text-sm font-semibold text-[var(--text-primary)]">2. Stakeout List ({result.totalPoints} points)</h2>
            <div className="flex gap-2 items-center">
              <select value={exportFormat} onChange={e => setExportFormat(e.target.value as InstrumentFormat)} className={inputCls + ' w-auto'}>
                {getAvailableFormats().map(f => <option key={f.value} value={f.value}>{f.label}</option>)}
              </select>
              <button onClick={handleExport} className="flex items-center gap-1.5 px-3 py-1.5 bg-[var(--accent)]/15 border border-[var(--accent)]/30 text-[var(--accent)] text-xs font-semibold rounded-lg hover:bg-[var(--accent)]/25">
                <Download className="w-3.5 h-3.5" /> Export
              </button>
            </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead><tr className="text-[var(--text-muted)] border-b border-[var(--border-color)]">
                <th className="text-left py-2 px-1">ID</th><th className="text-right">Hz Angle</th><th className="text-right">HD (m)</th><th className="text-right">SD (m)</th><th className="text-right">Design E</th><th className="text-right">Design N</th><th className="text-right">RL</th>
              </tr></thead>
              <tbody>
                {result.rows.map((row) => (
                  <tr key={row.id} className="border-b border-[var(--border-color)]/30 text-[var(--text-secondary)]">
                    <td className="py-1.5 px-1 font-mono">{row.id}</td>
                    <td className="text-right font-mono">{row.HzAngle}</td>
                    <td className="text-right font-mono">{row.HD.toFixed(3)}</td>
                    <td className="text-right font-mono">{row.SD.toFixed(3)}</td>
                    <td className="text-right font-mono">{row.designE.toFixed(3)}</td>
                    <td className="text-right font-mono">{row.designN.toFixed(3)}</td>
                    <td className="text-right font-mono">{row.designRL.toFixed(3)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="mt-2 text-[10px] text-[var(--text-muted)]">BS bearing: {result.bsBearing} | {result.rows.length} points</div>
        </div>
      )}

      {/* Step 3: As-Built Comparison */}
      {result && (
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
          <h2 className="text-sm font-semibold text-[var(--text-primary)] mb-3">3. As-Built Comparison</h2>
          <p className="text-[10px] text-[var(--text-muted)] mb-2">Paste as-built shots (one per line: id,easting,northing,rl)</p>
          <textarea value={asBuiltInput} onChange={e => setAsBuiltInput(e.target.value)} placeholder="P1,264100.010,9861100.005,1500.002" className={inputCls + ' h-20 font-mono mb-2'} />
          <button onClick={handleCompare} className="px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)]">Compare As-Built vs Design</button>

          {comparison && (
            <div className="mt-4">
              <div className={`p-3 rounded-lg mb-3 text-sm font-semibold ${comparison.verdict === 'PASS' ? 'bg-green-500/10 text-green-400 border border-green-500/20' : comparison.verdict === 'FAIL' ? 'bg-red-500/10 text-red-400 border border-red-500/20' : 'bg-yellow-500/10 text-yellow-400 border border-yellow-500/20'}`}>
                {comparison.summary}
              </div>
              <table className="w-full text-xs">
                <thead><tr className="text-[var(--text-muted)] border-b border-[var(--border-color)]">
                  <th className="text-left py-1">ID</th><th className="text-right">dE (mm)</th><th className="text-right">dN (mm)</th><th className="text-right">dH (mm)</th><th className="text-right">|H| (mm)</th><th className="text-center">Status</th>
                </tr></thead>
                <tbody>
                  {comparison.rows.map((row) => (
                    <tr key={row.designId} className={`border-b border-[var(--border-color)]/30 ${row.passed ? 'text-[var(--text-secondary)]' : 'text-red-400'}`}>
                      <td className="py-1 font-mono">{row.designId}</td>
                      <td className="text-right font-mono">{(row.deltaE * 1000).toFixed(1)}</td>
                      <td className="text-right font-mono">{(row.deltaN * 1000).toFixed(1)}</td>
                      <td className="text-right font-mono">{row.deltaRL !== null ? (row.deltaRL * 1000).toFixed(1) : '—'}</td>
                      <td className="text-right font-mono">{(row.horizontalOffset * 1000).toFixed(1)}</td>
                      <td className="text-center">{row.passed ? '✓' : '✗'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

'use client'
import { useState } from 'react'
import { PageHeader } from '@/components/shared/PageHeader'
import { ToolExportButtons } from '@/components/shared/ToolExportButtons'
import { computeCurveElements, generateChainageTable, generateStakingTable, type HorizontalCurveData, type CurveElements, type ChainageTableEntry, type StakingPoint } from '@/lib/engineering/stakingTable'

export default function StakingTablePage() {
  const [ipE, setIpE] = useState(500000)
  const [ipN, setIpN] = useState(9800000)
  const [deflection, setDeflection] = useState(30)
  const [radius, setRadius] = useState(200)
  const [ipChainage, setIpChainage] = useState(1000)
  const [incomingBearing, setIncomingBearing] = useState(45)
  const [interval, setInterval] = useState(20)
  const [offsets, setOffsets] = useState('-3.5,0,3.5')
  const [computed, setComputed] = useState<{ elements: CurveElements; chainageTable: ChainageTableEntry[]; stakingTable: StakingPoint[] } | null>(null)

  const compute = () => {
    const data: HorizontalCurveData = { ipE, ipN, deflectionAngle: deflection, radius, ipChainage, incomingBearing }
    const elements = computeCurveElements(data)
    const chainageTable = generateChainageTable(data, elements, ipChainage + elements.tangent + 100)
    const offsetArr = offsets.split(',').map(s => parseFloat(s.trim())).filter(n => !isNaN(n))
    const stakingTable = generateStakingTable(data, elements, interval, undefined, undefined, offsetArr)
    setComputed({ elements, chainageTable, stakingTable })
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader title="Staking Table" subtitle="Batch staking + chainage schedule for setting out" reference="Route Surveying Ch.6 | RDM 1.3" />
      <div className="grid lg:grid-cols-2 gap-8">
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="ip-easting">IP Easting</label><input id="ip-easting" type="number" value={ipE} onChange={e => setIpE(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="ip-northing">IP Northing</label><input id="ip-northing" type="number" value={ipN} onChange={e => setIpN(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="deflection-angle">Deflection Angle (°)</label><input id="deflection-angle" type="number" step="0.1" value={deflection} onChange={e => setDeflection(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="radius-m">Radius (m)</label><input id="radius-m" type="number" value={radius} onChange={e => setRadius(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="ip-chainage-m">IP Chainage (m)</label><input id="ip-chainage-m" type="number" value={ipChainage} onChange={e => setIpChainage(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="incoming-bearing">Incoming Bearing (°)</label><input id="incoming-bearing" type="number" step="0.1" value={incomingBearing} onChange={e => setIncomingBearing(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="stake-interval-m">Stake Interval (m)</label><input id="stake-interval-m" type="number" value={interval} onChange={e => setInterval(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="offsets-comma-sep-m">Offsets (comma-sep, m)</label><input id="offsets-comma-sep-m" type="text" value={offsets} onChange={e => setOffsets(e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
          </div>
          <button onClick={compute} className="w-full py-3 bg-[var(--accent)] hover:bg-[var(--accent)]/90 text-black font-semibold rounded-lg">Generate Staking Table</button>
        </div>
        <div>
          {computed ? (
            <div className="space-y-6">
              <div className="grid grid-cols-4 gap-3">
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">T (m)</div><div className="text-lg font-bold text-amber-400">{computed.elements.tangent.toFixed(3)}</div></div>
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">L (m)</div><div className="text-lg font-bold text-blue-400">{computed.elements.curveLength.toFixed(3)}</div></div>
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">E (m)</div><div className="text-lg font-bold text-green-400">{computed.elements.external.toFixed(3)}</div></div>
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">M (m)</div><div className="text-lg font-bold text-violet-400">{computed.elements.midOrdinate.toFixed(3)}</div></div>
              </div>
              <div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="text-zinc-500 border-b border-zinc-700"><th className="text-left py-2">Point</th><th className="text-left py-2">Description</th><th className="text-right py-2">Chainage</th><th className="text-right py-2">Easting</th><th className="text-right py-2">Northing</th><th className="text-right py-2">Bearing</th></tr></thead><tbody>{computed.chainageTable.map((r, i) => (<tr key={i} className="border-b border-zinc-800"><td className="py-2 font-mono text-amber-400">{r.point}</td><td className="py-2 text-zinc-300">{r.description}</td><td className="py-2 text-right font-mono text-white">{r.chainageLabel}</td><td className="py-2 text-right font-mono text-white">{r.easting.toFixed(3)}</td><td className="py-2 text-right font-mono text-white">{r.northing.toFixed(3)}</td><td className="py-2 text-right font-mono text-white">{r.bearing.toFixed(2)}°</td></tr>))}</tbody></table></div>
              <div className="overflow-x-auto"><h3 className="text-sm font-semibold text-white mb-2">Staking Table ({computed.stakingTable.length} stakes)</h3><table className="w-full text-sm"><thead><tr className="text-zinc-500 border-b border-zinc-700"><th className="text-right py-2">Chainage</th><th className="text-right py-2">Easting</th><th className="text-right py-2">Northing</th><th className="text-right py-2">Bearing</th><th className="text-right py-2">Segment</th></tr></thead><tbody>{computed.stakingTable.map((s, i) => (<tr key={i} className="border-b border-zinc-800"><td className="py-1.5 text-right font-mono text-amber-400">{s.chainageLabel}</td><td className="py-1.5 text-right font-mono text-white">{s.easting.toFixed(3)}</td><td className="py-1.5 text-right font-mono text-white">{s.northing.toFixed(3)}</td><td className="py-1.5 text-right font-mono text-white">{s.bearing.toFixed(2)}°</td><td className="py-1.5 text-right text-zinc-400">{s.segment}</td></tr>))}</tbody></table></div>
            </div>
          ) : <div className="p-6 bg-zinc-900 rounded-lg border border-zinc-700 text-center text-sm text-zinc-400">Enter curve data and click Generate.</div>}
        </div>
      </div>
    </div>
  )
}

'use client';

import { useState } from 'react'
import { PageHeader } from '@/components/shared/PageHeader'
import { useLanguage } from '@/lib/i18n/LanguageContext'
import { superelevationDesign, type SuperelevationInput } from '@/lib/computations/roadDesignEngine'

/**
 * AUDIT FIX (2026-07-03): Replaced the simplified inline formula
 * (e = V²/(127R), capped at 10%) with the real
 * roadDesignEngine.superelevationDesign() which uses RDM 1.3:
 *   - e_max = 8% (not 10%)
 *   - e = V²/(127R) - f  (subtracts friction factor)
 *   - Computes transition length Ls = e×w×V/(3.6×p)
 *   - Includes computation steps for transparency
 */

export default function SuperelevationPage() {
  const { t } = useLanguage()
  const [designSpeed, setDesignSpeed] = useState(60)
  const [radius, setRadius] = useState(200)
  const [numLanes, setNumLanes] = useState(2)
  const [laneWidth, setLaneWidth] = useState(3.5)
  const [roadClass, setRoadClass] = useState('DR3')

  const input: SuperelevationInput = {
    designSpeed,
    radius,
    numLanes,
    laneWidth,
    roadClass,
  }

  const result = superelevationDesign(input)

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.superelevation')}
        subtitle={t('tools.superelevationDesc')}
        reference="RDM 1.3 Section 5.3 | AASHTO Green Book 2018"
      />

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm text-zinc-400 mb-2" htmlFor="design-speed-km-h">Design Speed (km/h)</label>
              <input id="design-speed-km-h" aria-label="Design Speed (km/h)"
                type="number"
                value={designSpeed}
                onChange={e => setDesignSpeed(Number(e.target.value))}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white"
                min={20}
                max={120}
              />
            </div>
            <div>
              <label className="block text-sm text-zinc-400 mb-2" htmlFor="curve-radius-m">Curve Radius (m)</label>
              <input id="curve-radius-m" aria-label="Curve Radius (m)"
                type="number"
                value={radius}
                onChange={e => setRadius(Number(e.target.value))}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white"
                min={25}
                max={5000}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm text-zinc-400 mb-2" htmlFor="number-of-lanes">Number of Lanes</label>
              <input id="number-of-lanes" aria-label="Number of Lanes"
                type="number"
                value={numLanes}
                onChange={e => setNumLanes(Number(e.target.value))}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white"
                min={1}
                max={6}
              />
            </div>
            <div>
              <label className="block text-sm text-zinc-400 mb-2" htmlFor="lane-width-m">Lane Width (m)</label>
              <input  id="lane-width-m" aria-label="Lane Width (m)"
                type="number"
                step="0.1"
                value={laneWidth}
                onChange={e => setLaneWidth(Number(e.target.value))}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white"
                min={2.5}
                max={4.0}
              />
            </div>
          </div>

          {/* Results */}
          <div className="p-4 bg-zinc-900 rounded-lg border border-zinc-700">
            <div className="text-sm text-zinc-400 mb-1">Design Superelevation</div>
            <div className="text-3xl font-bold text-amber-400">{(result.designE * 100).toFixed(2)}%</div>              <div className="text-xs text-zinc-400 mt-1">
              Max allowable: 8% per RDM 1.3 (was 10% in old code)
            </div>
            {result.isCapped && (
              <div className="text-xs text-red-400 mt-1">
                ! Required e = {(result.requiredE * 100).toFixed(2)}% exceeds max — capped to 8%
              </div>
            )}
          </div>

          {/* Transition length */}
          <div className="p-4 bg-zinc-900 rounded-lg border border-zinc-700">
            <div className="text-sm text-zinc-400 mb-1">Transition Length (Ls)</div>
            <div className="text-2xl font-bold text-blue-400">{result.transitionLength.toFixed(2)}m</div>              <div className="text-xs text-zinc-400 mt-1">
              Ls = e × w × V / (3.6 × p), where w = {laneWidth}×{numLanes} = {(laneWidth * numLanes).toFixed(1)}m
            </div>
          </div>

          {/* Compliance */}
          <div className="p-4 bg-zinc-900 rounded-lg border border-zinc-700">
            <div className={`text-lg font-medium ${result.isCompliant ? 'text-green-400' : 'text-red-400'}`}>
              {result.isCompliant ? ' Compliant with RDM 1.3' : ' Non-compliant — radius too small for speed'}
            </div>              <div className="text-xs text-zinc-400 mt-1">
              Rate of change p = {(result.rateOfChange * 100).toFixed(2)}%/m (1% per 2.4m per RDM 1.3)
            </div>
          </div>

          {/* Computation steps */}
          {result.steps.length > 0 && (
            <div className="p-4 bg-zinc-900 rounded-lg border border-zinc-700">
              <h3 className="text-sm font-semibold text-white mb-3">Computation Steps</h3>
              <div className="space-y-2">
                {result.steps.map((step, i) => (
                  <div key={i} className="text-xs">
                    <div className="text-zinc-400">{step.description}</div>
                    <div className="text-zinc-400 font-mono">{step.formula}</div>
                    <div className="text-white font-mono">→ {step.value}</div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Reference table */}
        <div className="border border-zinc-700 rounded-lg p-4">
          <h3 className="font-medium text-white mb-4">Minimum Radius (RDM 1.3)</h3>
          <table className="w-full text-sm">
            <thead>
              <tr className="text-zinc-400 border-b border-zinc-700">
                <th className="text-left py-2">Speed (km/h)</th>
                <th className="text-right py-2">Min Radius (m)</th>
                <th className="text-right py-2">Max e (%)</th>
              </tr>
            </thead>
            <tbody>
              {[
                [30, 30, 8], [40, 60, 8], [50, 100, 8], [60, 150, 8],
                [70, 230, 8], [80, 320, 8], [90, 430, 8], [100, 560, 8],
              ].map(([speed, r, e]) => (
                <tr key={speed} className={`border-b border-zinc-800 ${speed === designSpeed ? 'bg-amber-900/20' : ''}`}>
                  <td className="py-2 text-zinc-400">{speed}</td>
                  <td className="py-2 text-right text-white">{r}</td>
                  <td className="py-2 text-right text-zinc-500">{e}</td>
                </tr>
              ))}
            </tbody>
          </table>            <p className="text-xs text-zinc-400 mt-3">
            Highlighted row matches current design speed. R = {radius}m
            {radius < 150 ? ' (below minimum for most speeds — increase radius)' : ' is adequate for current speed.'}
          </p>
        </div>
      </div>
    </div>
  )
}

'use client';

import { useState, useEffect, useMemo, Suspense } from 'react'
import { useSearchParams } from 'next/navigation'
import { useSession } from 'next-auth/react'
import { createClient } from '@/lib/api-client/client'
import SurveyReportBuilder from '@/components/surveyreport/SurveyReportBuilder'
import MobileDesktopNotice from '@/components/MobileDesktopNotice'
import { PageHeader } from '@/components/shared/PageHeader'
import { useLanguage } from '@/lib/i18n/LanguageContext'

interface Project {
  id: string
  name: string
  location: string | null
}

function SurveyReportBuilderContent() {
  const params = useSearchParams()
  const projectId = params.get('projectId') || ''
  const reportId = params.get('reportId') || undefined
  const { data: session, status: sessionStatus } = useSession()
  const { t } = useLanguage()

  const [projects, setProjects] = useState<Project[]>([])
  const [selectedProjectId, setSelectedProjectId] = useState('')
  const [loading, setLoading] = useState(true)

  // AUDIT FIX (H-007, 2026-07-27): useMemo prevents infinite loop.
  const dbClient = useMemo(() => createClient(), [])

  useEffect(() => {
    if (sessionStatus === 'loading') return
    if (!session?.user) {
      setLoading(false)
      return
    }

    async function load() {
      const { data } = await dbClient
        .from('projects')
        .select('id, name, location')
        .order('created_at', { ascending: false })
                .limit(50) as unknown as { data: Project[] | null }

      setProjects((data as Project[] | null) || [])
      setLoading(false)
    }

    load()
  }, [session, sessionStatus, dbClient])

  if (sessionStatus === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  if (!session?.user) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center p-4">
        <div className="text-center max-w-sm">
          <div className="w-16 h-16 rounded-2xl bg-[var(--accent)]/10 flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8 text-[var(--accent)]" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M16.5 10.5V6.75a4.5 4.5 0 10-9 0v3.75m-.75 11.25h10.5a2.25 2.25 0 002.25-2.25v-6.75a2.25 2.25 0 00-2.25-2.25H6.75a2.25 2.25 0 00-2.25 2.25v6.75a2.25 2.25 0 002.25 2.25z" />
            </svg>
          </div>
          <h2 className="text-lg font-semibold text-[var(--text-primary)] mb-2">Sign in Required</h2>
          <p className="text-sm text-[var(--text-muted)] mb-6">
            You need to be signed in to create survey reports.
          </p>
          <a
            href="/login"
            className="inline-block px-6 py-2.5 bg-[var(--accent)] text-black font-semibold rounded-lg text-sm hover:bg-[var(--accent-dim)] transition-colors"
          >
            Sign In
          </a>
        </div>
      </div>
    )
  }

  if (!projectId) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] p-8">
        <div className="max-w-2xl mx-auto">
          <div className="mb-4">
            <MobileDesktopNotice>
              Report assembly has long forms, tables, previews, and export checks. Mobile is fine for selecting a project, but desktop is recommended before generating final documents.
            </MobileDesktopNotice>
          </div>
          <PageHeader
            title={t('tools.surveyReportBuilder')}
            subtitle={t('tools.surveyReportBuilderDesc')}
          />
          
          {projects.length === 0 ? (
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-8 text-center">
              <p className="text-[var(--text-muted)] mb-4">No projects found.</p>
              <a
                href="/project/new"
                className="inline-block px-6 py-2.5 bg-[var(--accent)] text-black font-semibold rounded-lg text-sm"
              >
                Create New Project
              </a>
            </div>
          ) : (
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <h2 className="text-lg font-semibold mb-4">Select Project</h2>
              <div className="space-y-2">
                {projects.map((p) => (
                  <button
                    key={p.id}
                    onClick={() => setSelectedProjectId(p.id)}
                    className={`w-full text-left px-4 py-3 rounded-lg border transition-colors ${
                      selectedProjectId === p.id
                        ? 'border-[var(--accent)] bg-[var(--accent)]/5'
                        : 'border-[var(--border-color)] hover:border-[var(--accent)]/50'
                    }`}
                  >
                    <div className="font-medium">{p.name}</div>
                    <div className="text-xs text-[var(--text-muted)]">{p.location || 'No location'}</div>
                  </button>
                ))}
              </div>
              <div className="flex justify-end mt-6">
                <a
                  href={`/tools/survey-report-builder?projectId=${selectedProjectId}`}
                  className={`px-6 py-2.5 bg-[var(--accent)] text-black font-semibold rounded-lg text-sm ${
                    !selectedProjectId ? 'opacity-40 pointer-events-none' : ''
                  }`}
                >
                  Continue →
                </a>
              </div>
            </div>
          )}
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      <div className="px-4 pt-4">
        <MobileDesktopNotice>
          Report assembly has long forms, tables, previews, and export checks. Use desktop before issuing final documents.
        </MobileDesktopNotice>
      </div>
      <SurveyReportBuilder projectId={projectId} existingReportId={reportId} />
    </div>
  )
}

export default function SurveyReportBuilderPage() {
  const { t } = useLanguage()
  return (
    <Suspense fallback={
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin" />
      </div>
    }>
      <SurveyReportBuilderContent />
    </Suspense>
  )
}

'use client';

import { useState } from 'react';
import { Download } from 'lucide-react';
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer'
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder'
import { tacheometrySolved } from '@/lib/engine/solution/wrappers/tacheometry'
import { PageHeader } from '@/components/shared/PageHeader'
import { generatePDF, downloadCSV, toCSV } from '@/lib/export/helpers'
import { useLanguage } from '@/lib/i18n/LanguageContext'

export default function TacheometryCalculator() {
  const { t } = useLanguage()
  const [inputs, setInputs] = useState({
    hi: '',           // instrument height above ground (h.i.)
    upper: '',        // upper staff reading
    middle: '',       // middle staff reading
    lower: '',        // lower staff reading
    vertDeg: '',      // vertical angle degrees
    vertMin: '',      // vertical angle minutes
    vertSec: '',      // vertical angle seconds
    k: '100',         // multiplying constant
    c: '0'            // additive constant
  });
  const [steps, setSteps] = useState<SolutionStep[] | null>(null);
  const [calcError, setCalcError] = useState<string | null>(null);
  const [solutionTitle, setSolutionTitle] = useState<string | undefined>(undefined);

  const calculate = () => {
    const HI = parseFloat(inputs.hi);
    const upper = parseFloat(inputs.upper);
    const middle = parseFloat(inputs.middle);
    const lower = parseFloat(inputs.lower);
    const K = parseFloat(inputs.k) || 100;
    const C = parseFloat(inputs.c) || 0;

    const deg = parseFloat(inputs.vertDeg) || 0
    const min = parseFloat(inputs.vertMin) || 0
    const sec = parseFloat(inputs.vertSec) || 0

    if (isNaN(HI) || isNaN(upper) || isNaN(middle) || isNaN(lower)) return;

    const s = tacheometrySolved({
      instrumentHeight: HI,
      upper,
      middle,
      lower,
      verticalAngle: { degrees: deg, minutes: min, seconds: sec, direction: 'N' },
      K,
      C,
    })
    setSteps(s.steps)
    setSolutionTitle(s.solution.title)
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.tacheometry')}
        subtitle={t('tools.tacheometryDesc')}
        reference="Survey Regulations 1994 | RDM 1.1 (2025) Section 5.6 | Survey Act Cap 299"
      />

      <div className="grid md:grid-cols-2 gap-8">
        <div className="card">
          <div className="card-header"><span className="label">Tacheometry Data</span></div>
          <div className="card-body space-y-4">
            <div>
              {/* h.i. = height of instrument above ground (not HPC — different context) */}
              <label className="label" htmlFor="instrument-height-above-ground-h-i-m">Instrument Height above Ground, h.i. (m)</label>
              <input id="instrument-height-above-ground-h-i-m" className="input" value={inputs.hi} onChange={e => setInputs({...inputs, hi: e.target.value})} placeholder="1.500" />
            </div>
            <div>
              <div className="label">Staff Readings (m)</div>
              <div className="grid grid-cols-3 gap-2">
                <div>
                  <label className="label text-xs" htmlFor="upper">Upper</label>
                  <input id="upper" className="input" value={inputs.upper} onChange={e => setInputs({...inputs, upper: e.target.value})} placeholder="1.850" />
                </div>
                <div>
                  <label className="label text-xs" htmlFor="middle">Middle</label>
                  <input id="middle" className="input" value={inputs.middle} onChange={e => setInputs({...inputs, middle: e.target.value})} placeholder="1.500" />
                </div>
                <div>
                  <label className="label text-xs" htmlFor="lower">Lower</label>
                  <input id="lower" className="input" value={inputs.lower} onChange={e => setInputs({...inputs, lower: e.target.value})} placeholder="1.150" />
                </div>
              </div>
            </div>
            <div>
              <div className="label">Vertical Angle (D° M&apos; S&quot;)</div>
              <div className="flex gap-2">
                <input className="input flex-1" value={inputs.vertDeg} onChange={e => setInputs({...inputs, vertDeg: e.target.value})} placeholder="05°" />
                <input className="input flex-1" value={inputs.vertMin} onChange={e => setInputs({...inputs, vertMin: e.target.value})} placeholder="30'" />
                <input className="input flex-1" value={inputs.vertSec} onChange={e => setInputs({...inputs, vertSec: e.target.value})} placeholder="00&quot;" />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="label" htmlFor="multiplying-constant-k">Multiplying Constant K</label>
                <input id="multiplying-constant-k" className="input" value={inputs.k} onChange={e => setInputs({...inputs, k: e.target.value})} placeholder="100" />
              </div>
              <div>
                <label className="label" htmlFor="additive-constant-c">Additive Constant C</label>
                <input id="additive-constant-c" className="input" value={inputs.c} onChange={e => setInputs({...inputs, c: e.target.value})} placeholder="0" />
              </div>
            </div>
            {calcError && <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{calcError}</div>}
            <button onClick={calculate} className="btn btn-primary w-full">{t('toolUI.calculate')}</button>
            {steps && (
              <div className="flex gap-2 mt-2">
                <button
                  onClick={() => {
                    generatePDF(
                      { title: 'Tacheometric Computation Sheet', reference: 'Survey Regulations 1994 | RDM 1.1 (2025) Section 5.6' },
                      [
                        { title: 'Observations', rows: [
                          { label: 'Instrument Height (h.i.)', value: `${inputs.hi} m` },
                          { label: 'Upper Staff Reading', value: `${inputs.upper} m` },
                          { label: 'Middle Staff Reading', value: `${inputs.middle} m` },
                          { label: 'Lower Staff Reading', value: `${inputs.lower} m` },
                          { label: 'Vertical Angle', value: `${inputs.vertDeg}° ${inputs.vertMin}' ${inputs.vertSec}"` },
                          { label: 'K (multiplying constant)', value: inputs.k },
                          { label: 'C (additive constant)', value: inputs.c },
                        ]},
                        { title: 'Computation Steps', rows: steps.map((s: SolutionStep) => ({ label: s.label, value: s.result || s.computation || '—' })) },
                      ],
                    )
                  }}
                  className="btn btn-secondary flex-1 inline-flex items-center justify-center gap-2"
                >
                  <Download className="w-4 h-4" /> {t('toolUI.exportPdf')}
                </button>
                <button
                  onClick={() => {
                    const csv = toCSV(
                      ['Parameter', 'Value'],
                      [
                        ['Instrument Height (m)', inputs.hi],
                        ['Upper Staff (m)', inputs.upper],
                        ['Middle Staff (m)', inputs.middle],
                        ['Lower Staff (m)', inputs.lower],
                        ['Vertical Angle', `${inputs.vertDeg}° ${inputs.vertMin}' ${inputs.vertSec}"`],
                        ['K', inputs.k],
                        ['C', inputs.c],
                        ...steps.map((s: SolutionStep) => [s.label, s.result || s.computation || '']),
                      ],
                    )
                    downloadCSV(csv, 'tacheometry-data')
                  }}
                  className="btn btn-secondary flex-1 inline-flex items-center justify-center gap-2"
                >
                  <Download className="w-4 h-4" /> {t('toolUI.exportCsv')}
                </button>
              </div>
            )}
          </div>
        </div>

        {steps ? <SolutionStepsRenderer title={solutionTitle} steps={steps} /> : null}
      </div>
    </div>
  );
}

'use client'

import { useState, useMemo, useCallback } from 'react'
import { Mountain, Download, FileSpreadsheet, AlertCircle, CheckCircle2, Layers, Search } from 'lucide-react'
import { KENYA_TOPO_CODES } from '@/lib/topo/featureCodes'

interface TopoPoint {
  pointNumber: string; easting: number; northing: number; rl: number
  code: string; description: string
}

interface BreaklineInput {
  points: Array<{ x: number; y: number; z: number }>
  type: 'hard' | 'soft' | 'ridge' | 'valley'
}

interface ContourSanityIssue {
  severity: 'error' | 'warning'
  message: string
  suggestion?: string
}

interface ContourSanity {
  passed: boolean
  summary: string
  issues: ContourSanityIssue[]
}

export default function TopographicSurveyPage() {
  const [points, setPoints] = useState<TopoPoint[]>([])
  const [breaklines, setBreaklines] = useState<BreaklineInput[]>([])
  const [pointInput, setPointInput] = useState('')
  const [breaklineInput, setBreaklineInput] = useState('')
  const [contourInterval, setContourInterval] = useState('1.0')
  const [contours, setContours] = useState<unknown[] | null>(null)
  const [sanity, setSanity] = useState<ContourSanity | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [codeFilter, setCodeFilter] = useState('')

  // Feature code lookup
  const codeMap = useMemo(() => {
    const m = new Map<string, string>()
    for (const def of KENYA_TOPO_CODES) m.set(def.code.toUpperCase(), def.description)
    return m
  }, [])

  const filteredCodes = useMemo(() => {
    if (!codeFilter) return KENYA_TOPO_CODES.slice(0, 30)
    return KENYA_TOPO_CODES.filter(c =>
      c.code.toLowerCase().includes(codeFilter.toLowerCase()) ||
      c.description.toLowerCase().includes(codeFilter.toLowerCase())
    ).slice(0, 30)
  }, [codeFilter])

  const handleParsePoints = useCallback(() => {
    const parsed = pointInput.trim().split('\n').map(line => {
      const cols = line.split(',').map(c => c.trim())
      return {
        pointNumber: cols[0] || `PT${Date.now()}`,
        easting: parseFloat(cols[1]), northing: parseFloat(cols[2]),
        rl: parseFloat(cols[3]),
        code: cols[4] || '', description: cols[5] || codeMap.get((cols[4] || '').toUpperCase()) || '',
      }
    }).filter(p => !isNaN(p.easting) && !isNaN(p.northing) && !isNaN(p.rl))
    setPoints(parsed)
  }, [pointInput, codeMap])

  const handleParseBreaklines = useCallback(() => {
    // Format: type,x1,y1,z1,x2,y2,z2,...
    const lines = breaklineInput.trim().split('\n')
    const parsed: BreaklineInput[] = []
    for (const line of lines) {
      const cols = line.split(',').map(c => c.trim())
      const type = (cols[0] as BreaklineInput['type']) || 'hard'
      const pts: Array<{ x: number; y: number; z: number }> = []
      for (let i = 1; i < cols.length - 2; i += 3) {
        const x = parseFloat(cols[i]), y = parseFloat(cols[i + 1]), z = parseFloat(cols[i + 2])
        if (!isNaN(x) && !isNaN(y) && !isNaN(z)) pts.push({ x, y, z })
      }
      if (pts.length >= 2) parsed.push({ points: pts, type })
    }
    setBreaklines(parsed)
  }, [breaklineInput])

  const handleGenerateContours = async () => {
    if (points.length < 3) { setError('Need ≥3 points'); return }
    setLoading(true); setError(''); setContours(null); setSanity(null)
    try {
      const res = await fetch('/api/topo/generate-contours', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          points: points.map(p => ({ x: p.easting, y: p.northing, z: p.rl })),
          breaklines,
          interval: parseFloat(contourInterval),
        }),
      })
      if (!res.ok) { const e = (await res.json()) as { error?: string }; throw new Error(e.error || 'Failed') }
      const data = (await res.json()) as { data: { contours: unknown[]; sanity: ContourSanity } }
      setContours(data.data.contours)
      setSanity(data.data.sanity)
    } catch (e) { setError(e instanceof Error ? e.message : 'Failed') }
    finally { setLoading(false) }
  }

  const handleExportDXF = async () => {
    if (points.length === 0) return
    try {
      const res = await fetch('/api/topo/export-dxf', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          points: points.map(p => ({
            easting: p.easting, northing: p.northing, elevation: p.rl,
            code: p.code, pointNumber: p.pointNumber,
          })),
          projectName: 'Topographic Survey',
        }),
      })
      if (!res.ok) throw new Error('Export failed')
      const data = (await res.json()) as { content: string | ArrayBuffer; mimeType: string; filename: string }
      const blob = new Blob([data.content], { type: data.mimeType })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url; a.download = data.filename; a.click()
      URL.revokeObjectURL(url)
    } catch (e) { setError(e instanceof Error ? e.message : 'Export failed') }
  }

  const handleExportSpotHeights = async () => {
    if (points.length === 0) return
    try {
      const res = await fetch('/api/topo/spot-height-schedule', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          points: points.map(p => ({
            pointNumber: p.pointNumber, easting: p.easting, northing: p.northing,
            rl: p.rl, code: p.code, description: p.description,
          })),
          projectName: 'Topographic Survey',
          surveyorName: 'METARDU User',
        }),
      })
      if (!res.ok) throw new Error('Export failed')
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url; a.download = 'spot_height_schedule.xlsx'; a.click()
      URL.revokeObjectURL(url)
    } catch (e) { setError(e instanceof Error ? e.message : 'Export failed') }
  }

  const inputCls = "w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] focus:border-[var(--accent)]/30 focus:outline-none"

  return (
    <div className="min-h-screen p-6 max-w-6xl mx-auto">
      <h1 className="text-2xl font-bold text-[var(--text-primary)] mb-2">Topographic Survey</h1>
      <p className="text-sm text-[var(--text-muted)] mb-6">Feature-coded points → breakline-aware TIN → contour generation → DXF + Spot Height Schedule export</p>

      <div className="grid grid-cols-2 gap-4 mb-4">
        {/* Point Input */}
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
          <h2 className="text-sm font-semibold mb-2">1. Survey Points</h2>
          <p className="text-[10px] text-[var(--text-muted)] mb-1">Format: point_no, easting, northing, RL, code, description</p>
          <textarea value={pointInput} onChange={e => setPointInput(e.target.value)}
            className={inputCls + ' h-40 font-mono'}
            placeholder={'1,264000,9861000,1500.00,SH,Spot height&#10;2,264010,9861000,1500.15,RD,Road edge&#10;3,264020,9861000,1500.30,RD,Road edge&#10;4,264030,9861000,1500.50,BLD,Building corner'} />
          <button onClick={handleParsePoints} className="mt-2 px-3 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-secondary)] hover:bg-[var(--border-hover)]">
            Parse Points ({points.length} loaded)
          </button>
        </div>

        {/* Breakline Input */}
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
          <h2 className="text-sm font-semibold mb-2">2. Breaklines (optional)</h2>
          <p className="text-[10px] text-[var(--text-muted)] mb-1">Format: type,x1,y1,z1,x2,y2,z2,...</p>
          <textarea value={breaklineInput} onChange={e => setBreaklineInput(e.target.value)}
            className={inputCls + ' h-40 font-mono'}
            placeholder={'hard,264010,9861000,1500.15,264020,9861000,1500.30,264030,9861000,1500.50'} />
          <button onClick={handleParseBreaklines} className="mt-2 px-3 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-secondary)] hover:bg-[var(--border-hover)]">
            Parse Breaklines ({breaklines.length} loaded)
          </button>
        </div>
      </div>

      {/* Feature Code Library */}
      <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
        <h2 className="text-sm font-semibold mb-2 flex items-center gap-2"><Layers className="w-4 h-4" /> Kenya Feature Code Library ({KENYA_TOPO_CODES.length} codes)</h2>
        <div className="flex gap-2 mb-2">
          <div className="relative flex-1">
            <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-[var(--text-muted)]" />
            <input value={codeFilter} onChange={e => setCodeFilter(e.target.value)} placeholder="Search codes..."
              className={inputCls + ' pl-7'} />
          </div>
        </div>
        <div tabIndex={0} role="region" aria-label="Survey grid" className="grid grid-cols-4 gap-1 max-h-32 overflow-y-auto">
          {filteredCodes.map(def => (
            <div key={def.code} className="text-[10px] px-2 py-1 rounded bg-[var(--bg-tertiary)] border border-[var(--border-color)]/30">
              <span className="font-mono font-bold text-[var(--accent)]">{def.code}</span>
              <span className="text-[var(--text-muted)] ml-1">{def.description}</span>
              <span className="text-[var(--text-muted)]/50 ml-1">→ {def.dxfLayer}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Contour Generation */}
      <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-sm font-semibold">3. Contour Generation</h2>
          <div className="flex gap-2 items-center">
            <label className="text-[10px] text-[var(--text-muted)]" htmlFor="interval-m">Interval (m):</label>
            <input  id="interval-m" value={contourInterval} onChange={e => setContourInterval(e.target.value)} className={inputCls + ' w-20'} />
            <button onClick={handleGenerateContours} disabled={loading || points.length < 3}
              className="px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-50">
              {loading ? 'Generating...' : 'Generate Contours'}
            </button>
          </div>
        </div>

        {error && <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 mb-3 text-xs text-red-400 flex items-center gap-2"><AlertCircle className="w-4 h-4" /> {error}</div>}

        {sanity && (
          <div className={`p-3 rounded-lg mb-3 text-xs ${sanity.passed ? 'bg-green-500/10 text-green-400 border border-green-500/20' : 'bg-red-500/10 text-red-400 border border-red-500/20'}`}>
            <div className="flex items-center gap-2 font-semibold">
              {sanity.passed ? <CheckCircle2 className="w-4 h-4" /> : <AlertCircle className="w-4 h-4" />}
              Contour Sanity Check
            </div>
            <p className="mt-1 opacity-80">{sanity.summary}</p>
            {sanity.issues.length > 0 && (
              <div className="mt-2 space-y-1">
                {sanity.issues.map((issue, i) => (
                  <div key={i} className="text-[10px]">
                    <span className={issue.severity === 'error' ? 'text-red-400' : 'text-yellow-400'}>[{issue.severity.toUpperCase()}]</span>
                    {' '}{issue.message}
                    <span className="text-[var(--text-muted)] block ml-4">→ {issue.suggestion}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {contours && (
          <div className="text-xs text-[var(--text-secondary)]">
            Generated {contours.length} contour lines at {contourInterval}m interval
          </div>
        )}
      </div>

      {/* Export */}
      <div className="flex gap-3">
        <button onClick={handleExportDXF} disabled={points.length === 0}
          className="flex items-center gap-2 px-4 py-2 bg-[var(--accent)]/15 border border-[var(--accent)]/30 text-[var(--accent)] text-xs font-semibold rounded-lg hover:bg-[var(--accent)]/25 disabled:opacity-50">
          <Download className="w-4 h-4" /> Export Topo DXF
        </button>
        <button onClick={handleExportSpotHeights} disabled={points.length === 0}
          className="flex items-center gap-2 px-4 py-2 bg-[var(--accent)]/15 border border-[var(--accent)]/30 text-[var(--accent)] text-xs font-semibold rounded-lg hover:bg-[var(--accent)]/25 disabled:opacity-50">
          <FileSpreadsheet className="w-4 h-4" /> Spot Height Schedule (Excel)
        </button>
      </div>

      {/* Points Table */}
      {points.length > 0 && (
        <div className="mt-4 bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
          <h3 className="text-sm font-semibold mb-2">Loaded Points ({points.length})</h3>
          <div className="overflow-x-auto max-h-60">
            <table className="w-full text-xs">
              <thead><tr className="text-[var(--text-muted)] border-b border-[var(--border-color)] sticky top-0 bg-[var(--bg-secondary)]">
                <th className="text-left py-1 px-1">Pt No</th><th className="text-right">Easting</th><th className="text-right">Northing</th><th className="text-right">RL</th><th className="text-left">Code</th><th className="text-left">Description</th>
              </tr></thead>
              <tbody>
                {points.map((p, i) => (
                  <tr key={i} className="border-b border-[var(--border-color)]/30 text-[var(--text-secondary)]">
                    <td className="py-1 px-1 font-mono">{p.pointNumber}</td>
                    <td className="text-right font-mono">{p.easting.toFixed(3)}</td>
                    <td className="text-right font-mono">{p.northing.toFixed(3)}</td>
                    <td className="text-right font-mono">{p.rl.toFixed(3)}</td>
                    <td className="font-mono text-[var(--accent)]">{p.code}</td>
                    <td>{p.description}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState } from 'react';
import { Download } from 'lucide-react';
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer'
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder'
import { twoPegTestSolved } from '@/lib/engine/solution/wrappers/twoPegTest'
import { PageHeader } from '@/components/shared/PageHeader'
import { generatePDF, downloadCSV, toCSV } from '@/lib/export/helpers'
import { useLanguage } from '@/lib/i18n/LanguageContext'

export default function TwoPegTestCalculator() {
  const { t } = useLanguage()
  const [inputs, setInputs] = useState({
    a1: '',  // Staff at A from position 1
    b1: '',  // Staff at B from position 1
    a2: '',  // Staff at A from position 2
    b2: '',  // Staff at B from position 2
    // AUDIT FIX (2026-07-03): Add baseline distance + tolerance inputs.
    // Previously the baseline was hardcoded to 100m and the allowable
    // error to 10mm/100m — surveyors couldn't change them for non-standard
    // setups (e.g., 50m baseline, 2mm/100m digital level tolerance).
    baseline: '100',    // Distance between pegs A and B (metres)
    allowable: '10',    // Allowable collimation error (mm per 100m)
  });
  const [steps, setSteps] = useState<SolutionStep[] | null>(null);
  const [calcError, setCalcError] = useState<string | null>(null);
  const [solutionTitle, setSolutionTitle] = useState<string | undefined>(undefined);

  const calculate = () => {
    const A1 = parseFloat(inputs.a1);
    const B1 = parseFloat(inputs.b1);
    const A2 = parseFloat(inputs.a2);
    const B2 = parseFloat(inputs.b2);
    const baseline = parseFloat(inputs.baseline) || 100;
    const allowable = parseFloat(inputs.allowable) || 10;

    if (isNaN(A1) || isNaN(B1) || isNaN(A2) || isNaN(B2)) return;

    const s = twoPegTestSolved({ A1, B1, A2, B2, baselineMeters: baseline, allowableMmPer100m: allowable })
    setSteps(s.steps)
    setSolutionTitle(s.solution.title)
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.twoPegTest')}
        subtitle={t('tools.twoPegTestDesc')}
        reference="Survey Regulations 1994 | Survey Act Cap 299 | RDM 1.1 (2025)"
      />

      <div className="grid md:grid-cols-2 gap-8">
        <div className="card">
          <div className="card-header"><span className="label">Staff Readings</span></div>
          <div className="card-body space-y-4">
            <div className="border-b border-[var(--border-color)] pb-4 mb-4">
              <div className="text-sm text-[var(--text-secondary)] mb-3">Instrument Position 1</div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="label" htmlFor="staff-at-a-m">Staff at A (m)</label>
                  <input id="staff-at-a-m" className="input" value={inputs.a1} onChange={e => setInputs({...inputs, a1: e.target.value})} placeholder="1.525" />
                </div>
                <div>
                  <label className="label" htmlFor="staff-at-b-m">Staff at B (m)</label>
                  <input id="staff-at-b-m" className="input" value={inputs.b1} onChange={e => setInputs({...inputs, b1: e.target.value})} placeholder="1.415" />
                </div>
              </div>
            </div>
            <div>
              <div className="text-sm text-[var(--text-secondary)] mb-3">Instrument Position 2</div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="label" htmlFor="staff-at-a-m-2">Staff at A (m)</label>
                  <input id="staff-at-a-m-2" className="input" value={inputs.a2} onChange={e => setInputs({...inputs, a2: e.target.value})} placeholder="1.530" />
                </div>
                <div>
                  <label className="label" htmlFor="staff-at-b-m-2">Staff at B (m)</label>
                  <input id="staff-at-b-m-2" className="input" value={inputs.b2} onChange={e => setInputs({...inputs, b2: e.target.value})} placeholder="1.420" />
                </div>
              </div>
            </div>
            {/* AUDIT FIX (2026-07-03): Baseline + tolerance inputs */}
            <div className="border-b border-[var(--border-color)] pb-4 mb-4">
              <div className="text-sm text-[var(--text-secondary)] mb-3">Setup Parameters</div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="label" htmlFor="baseline-a-b-distance-m">Baseline A–B distance (m)</label>
                  <input id="baseline-a-b-distance-m" className="input" value={inputs.baseline} onChange={e => setInputs({...inputs, baseline: e.target.value})} placeholder="100" type="number" />
                </div>
                <div>
                  <label className="label" htmlFor="allowable-error-mm-100m">Allowable error (mm/100m)</label>
                  <input id="allowable-error-mm-100m" className="input" value={inputs.allowable} onChange={e => setInputs({...inputs, allowable: e.target.value})} placeholder="10" type="number" />
                </div>
              </div>
              <p className="text-xs text-[var(--text-muted)] mt-2">
                Typical: 100m baseline, 10mm/100m for optical levels. Digital levels may use 2mm/100m. Adjust per your instrument's specs and RDM 1.1 requirements.
              </p>
            </div>
            <button onClick={calculate} className="btn btn-primary w-full">Run Two Peg Test</button>
            {steps && (
              <div className="flex gap-2 mt-2">
                <button
                  onClick={() => {
                    generatePDF(
                      { title: 'Two Peg Test Certificate', reference: 'Survey Regulations 1994 | Survey Act Cap 299 | RDM 1.1 (2025)' },
                      [
                        { title: 'Staff Readings', rows: [
                          { label: 'Staff at A (Pos 1)', value: `${inputs.a1} m` },
                          { label: 'Staff at B (Pos 1)', value: `${inputs.b1} m` },
                          { label: 'Staff at A (Pos 2)', value: `${inputs.a2} m` },
                          { label: 'Staff at B (Pos 2)', value: `${inputs.b2} m` },
                        ]},
                        { title: 'Computation Steps', rows: steps.map((s: SolutionStep) => ({ label: s.label, value: s.result || s.computation || '—' })) },
                      ],
                    )
                  }}
                  className="btn btn-secondary flex-1 inline-flex items-center justify-center gap-2"
                >
                  <Download className="w-4 h-4" /> {t('toolUI.exportPdf')}
                </button>
                <button
                  onClick={() => {
                    const csv = toCSV(
                      ['Reading', 'Value (m)'],
                      [
                        ['Staff at A (Position 1)', inputs.a1],
                        ['Staff at B (Position 1)', inputs.b1],
                        ['Staff at A (Position 2)', inputs.a2],
                        ['Staff at B (Position 2)', inputs.b2],
                        ...steps.map((s: SolutionStep) => [s.label, s.result || s.computation || '']),
                      ],
                    )
                    downloadCSV(csv, 'two-peg-test-results')
                  }}
                  className="btn btn-secondary flex-1 inline-flex items-center justify-center gap-2"
                >
                  <Download className="w-4 h-4" /> {t('toolUI.exportCsv')}
                </button>
              </div>
            )}
          </div>
        </div>

        {steps ? <SolutionStepsRenderer title={solutionTitle} steps={steps} /> : null}
      </div>
    </div>
  );
}

'use client';

import type React from 'react';
import type { BBox, GridCell, Method } from './types';
import type { SurfacePoint } from '@/lib/engine/volume';

interface AnalysisTabProps {
  surveyAPoints: SurfacePoint[];
  surveyBPoints: SurfacePoint[];
  overlapBBox: BBox | null;
  gridSpacing: number;
  setGridSpacing: (n: number) => void;
  method: Method;
  setMethod: (m: Method) => void;
  computing: boolean;
  handleCompute: () => void;
  computeErrors: string[];
  computeWarnings: string[];
  cutVolume: number | null;
  fillVolume: number | null;
  netVolume: number | null;
  overlapArea: number | null;
  balancePoint: number | null;
  gridCells: GridCell[];
  gridBBox: BBox;
  showGrid: boolean;
  setShowGrid: (b: boolean) => void;
  hasComputedRef: React.MutableRefObject<boolean>;
  inputClass: string;
}

export default function AnalysisTab({
  surveyAPoints,
  surveyBPoints,
  overlapBBox,
  gridSpacing,
  setGridSpacing,
  method,
  setMethod,
  computing,
  handleCompute,
  computeErrors,
  computeWarnings,
  cutVolume,
  fillVolume,
  netVolume,
  overlapArea,
  balancePoint,
  gridCells,
  gridBBox,
  showGrid,
  setShowGrid,
  hasComputedRef,
  inputClass,
}: AnalysisTabProps) {
  const total = (cutVolume ?? 0) + (fillVolume ?? 0);
  const cutPct = total > 0 ? ((cutVolume ?? 0) / total) * 100 : 0;
  const fillPct = total > 0 ? ((fillVolume ?? 0) / total) * 100 : 0;
  const maxAbsDiff = gridCells.length > 0 ? Math.max(...gridCells.map(c => Math.abs(c.diff)), 0.001) : 1;

  return (
    <div className="space-y-6">
      {/* Configuration panel */}
      <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
        <h3 className="text-lg font-semibold mb-4">Computation Settings</h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-end">
          <div>
            <label className="block text-sm text-[var(--text-secondary)] mb-2" htmlFor="grid-spacing-m">Grid Spacing (m)</label>
            <input id="grid-spacing-m" aria-label="Grid Spacing (m)"
              type="number"
              min={0.1}
              max={5.0}
              step={0.1}
              value={gridSpacing}
              onChange={e => setGridSpacing(Math.max(0.1, Math.min(5.0, Number(e.target.value))))}
              className={inputClass}
            />
            <p className="text-xs text-[var(--text-muted)] mt-1">Range: 0.1 — 5.0 m (default: 1.0)</p>
          </div>
          <div>
            <div className="block text-sm text-[var(--text-secondary)] mb-2">Method</div>
            <div className="flex gap-2">
              <button
                onClick={() => setMethod('tin')}
                className={`flex-1 px-4 py-3 rounded-lg text-sm font-medium transition-colors ${method === 'tin' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-card)] border border-[var(--border-color)] text-[var(--text-secondary)]'}`}
              >
                TIN Interpolation
              </button>
              <button
                onClick={() => setMethod('idw')}
                className={`flex-1 px-4 py-3 rounded-lg text-sm font-medium transition-colors ${method === 'idw' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-card)] border border-[var(--border-color)] text-[var(--text-secondary)]'}`}
              >
                IDW Grid
              </button>
            </div>
            <p className="text-xs text-[var(--text-muted)] mt-1">
              {method === 'tin' ? 'Delaunay TIN with barycentric interpolation' : 'Inverse Distance Weighting (power=2)'}
            </p>
          </div>
          <div>
            <button
              onClick={handleCompute}
              disabled={computing || surveyAPoints.length < 3 || surveyBPoints.length < 3 || !overlapBBox}
              className="w-full px-4 py-3 bg-[var(--accent)] text-black rounded-lg text-sm font-bold hover:opacity-90 transition-opacity disabled:opacity-40 disabled:cursor-not-allowed"
            >
              {computing ? 'Computing...' : 'Compute Volume'}
            </button>
            {!overlapBBox && surveyAPoints.length >= 3 && surveyBPoints.length >= 3 && (
              <p className="text-xs text-red-400 mt-1">Surveys do not overlap.</p>
            )}
          </div>
        </div>
      </div>

      {/* Errors */}
      {computeErrors.length > 0 && (
        <div className="p-4 bg-red-900/20 border border-red-800/30 rounded-lg">
          <h4 className="text-sm font-medium text-red-400 mb-1">Computation Errors</h4>
          <ul className="text-xs text-red-300/80 space-y-0.5">
            {computeErrors.map((err, i) => <li key={`${err}-${i}`}>{err}</li>)}
          </ul>
        </div>
      )}

      {/* Warnings */}
      {computeWarnings.length > 0 && (
        <div className="p-4 bg-amber-900/20 border border-amber-800/30 rounded-lg">
          <h4 className="text-sm font-medium text-amber-400 mb-1">Warnings</h4>
          <ul className="text-xs text-amber-300/80 space-y-0.5">
            {computeWarnings.map((w, i) => <li key={`${w}-${i}`}>{w}</li>)}
          </ul>
        </div>
      )}

      {/* Results */}
      {cutVolume !== null && fillVolume !== null && netVolume !== null && (
        <>
          {/* Volume Summary Cards */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="p-4 bg-[#8B4513]/15 border border-[#8B4513]/40 rounded-lg">
              <div className="text-xs text-[#D2691E] mb-1">Cut Volume</div>
              <div className="text-2xl font-bold font-mono text-[#D2691E]">{cutVolume.toFixed(2)} m³</div>
              <div className="text-xs text-[var(--text-muted)] mt-0.5">
                Material removed ({cutPct.toFixed(1)}%)
              </div>
            </div>
            <div className="p-4 bg-[#4169E1]/15 border border-[#4169E1]/40 rounded-lg">
              <div className="text-xs text-[#6495ED] mb-1">Fill Volume</div>
              <div className="text-2xl font-bold font-mono text-[#6495ED]">{fillVolume.toFixed(2)} m³</div>
              <div className="text-xs text-[var(--text-muted)] mt-0.5">
                Material added ({fillPct.toFixed(1)}%)
              </div>
            </div>
            <div className={`p-4 border rounded-lg ${netVolume >= 0 ? 'bg-amber-900/20 border-amber-800/30' : 'bg-blue-900/20 border-blue-800/30'}`}>
              <div className={`text-xs mb-1 ${netVolume >= 0 ? 'text-amber-400' : 'text-blue-400'}`}>Net Volume</div>
              <div className={`text-2xl font-bold font-mono ${netVolume >= 0 ? 'text-amber-400' : 'text-blue-400'}`}>
                {netVolume >= 0 ? '+' : ''}{netVolume.toFixed(2)} m³
              </div>
              <div className="text-xs text-[var(--text-muted)] mt-0.5">
