}

'use client';

import { useState, useId } from 'react'
import { Download , AlertTriangle } from 'lucide-react'
import { inverseComputation, polarComputation, intersectionComputation, resectionComputation, areaComputation, joinComputation, distanceDistanceIntersection, bearingDistanceIntersection, arcByRadiusAndChord, type InverseStep, type DistDistResult, type BearingDistResult, type ArcResult } from '@/lib/computations/cogoEngine'
import { downloadCSV, toCSV } from '@/lib/export/helpers'
import { logger } from '@/lib/logger'

type Tab = 'inverse' | 'polar' | 'intersection' | 'distDist' | 'bearingDist' | 'arcBoundary' | 'resection' | 'area' | 'join'

interface Props {
  compact?: boolean
}

function DMSField({ label, deg, min, sec, onChange }: { label: string; deg: string; min: string; sec: string; onChange: (f: 'd' | 'm' | 's', v: string) => void }) {
  const degId = useId()
  return (
    <div>
      <label htmlFor={degId} className="block text-xs text-[var(--text-muted)] mb-1">{label}</label>
      <div className="flex gap-1">
        <input id={degId} value={deg} onChange={e => onChange('d', e.target.value)} type="number" min="0" max="359" placeholder="Deg"
          className="w-10 md:w-14 px-1 md:px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-xs md:text-sm" />
        <input value={min} onChange={e => onChange('m', e.target.value)} type="number" min="0" max="59" aria-label={`${label} — minutes`} placeholder="Min"
          className="w-8 md:w-12 px-1 md:px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-xs md:text-sm" />
        <input value={sec} onChange={e => onChange('s', e.target.value)} type="number" step="0.001" min="0" max="59.999" aria-label={`${label} — seconds`} placeholder="Sec"
          className="flex-1 min-w-[50px] px-1 md:px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-xs md:text-sm" />
      </div>
    </div>
  )
}

function DMSState() {
  return { d: '', m: '', s: '' }
}

function DMSGet(d: ReturnType<typeof DMSState>) {
  return { deg: parseInt(d.d) || 0, min: parseInt(d.m) || 0, sec: parseFloat(d.s) || 0 }
}

function StepsDisplay({ steps, title }: { steps: InverseStep[]; title?: string }) {
  if (!steps || steps.length === 0) return null
  return (
    <div className="space-y-2">
      {title && <h3 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider">{title}</h3>}
      <div className="space-y-1">
        {steps.map((step, i) => (
          <div key={step.value} className="grid grid-cols-[1fr_auto_1fr] md:grid-cols-[1fr_auto_1fr_auto] gap-x-1 md:gap-x-2 text-xs font-mono py-1 border-b border-[var(--border-color)]/20">
            <span className="text-[var(--text-secondary)]">{step.description}</span>
            <span className="text-[var(--text-muted)]">=</span>
            <span className="text-[var(--text-primary)] text-right">{step.value}</span>
            <span className="hidden md:block text-[var(--text-muted)] text-right min-w-[120px] text-right">{step.formula}</span>
          </div>
        ))}
      </div>
    </div>
  )
}

function CoordField({ label, value, onChange }: { label: string; value: string; onChange: (v: string) => void }) {
  const id = useId()
  return (
    <div>
      <label htmlFor={id} className="block text-xs text-[var(--text-muted)] mb-1">{label}</label>
      <input id={id} value={value} onChange={e => onChange(e.target.value)} type="number" step="0.001"
        className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
    </div>
  )
}

function ResultCard({ label, value, accent }: { label: string; value: string; accent?: boolean }) {
  return (
    <div className={`px-3 py-2 rounded border ${accent ? 'border-[var(--accent)] bg-[var(--accent)]/10' : 'border-[var(--border-color)] bg-[var(--bg-tertiary)]/50'}`}>
      <p className="text-xs text-[var(--text-secondary)]">{label}</p>
      <p className={`text-sm font-mono font-semibold ${accent ? 'text-[var(--accent)]' : 'text-[var(--text-primary)]'}`}>{value}</p>
    </div>
  )
}

export default function COGOCalculator({ compact = false }: Props) {
  const [activeTab, setActiveTab] = useState<Tab>('inverse')
  const [error, setError] = useState('')

  // ── INVERSE ──────────────────────────────────────────────────────────────────
  const [invE1, setInvE1] = useState('')
  const [invN1, setInvN1] = useState('')
  const [invE2, setInvE2] = useState('')
  const [invN2, setInvN2] = useState('')
  const [invL1, setInvL1] = useState('A')
  const [invL2, setInvL2] = useState('B')
  const [invResult, setInvResult] = useState<ReturnType<typeof inverseComputation> | null>(null)

  // ── POLAR ───────────────────────────────────────────────────────────────────
  const [polE1, setPolE1] = useState('')
  const [polN1, setPolN1] = useState('')
  const [polD, setPolD] = useState('')
  const [polBear, setPolBear] = useState(DMSState())
  const [polResult, setPolResult] = useState<ReturnType<typeof polarComputation> | null>(null)

  // ── INTERSECTION ─────────────────────────────────────────────────────────────
  const [intE1, setIntE1] = useState('')
  const [intN1, setIntN1] = useState('')
  const [intE2, setIntE2] = useState('')
  const [intN2, setIntN2] = useState('')
  const [intBear1, setIntBear1] = useState(DMSState())
  const [intBear2, setIntBear2] = useState(DMSState())
  const [intResult, setIntResult] = useState<ReturnType<typeof intersectionComputation> | null>(null)

  // ── RESECTION ────────────────────────────────────────────────────────────────
  const [resEA, setResEA] = useState(''); const [resNA, setResNA] = useState('')
  const [resEB, setResEB] = useState(''); const [resNB, setResNB] = useState('')
  const [resEC, setResEC] = useState(''); const [resNC, setResNC] = useState('')
  const [resAlpha, setResAlpha] = useState(DMSState())
  const [resBeta, setResBeta] = useState(DMSState())
  const [resResult, setResResult] = useState<ReturnType<typeof resectionComputation> | null>(null)

  // ── AREA ────────────────────────────────────────────────────────────────────
  const [areaText, setAreaText] = useState('')
  const [areaResult, setAreaResult] = useState<ReturnType<typeof areaComputation> | null>(null)

  // ── JOIN ────────────────────────────────────────────────────────────────────
  const [joinText, setJoinText] = useState('')
  const [joinResult, setJoinResult] = useState<ReturnType<typeof joinComputation> | null>(null)

  // ── DISTANCE-DISTANCE ──────────────────────────────────────────────────────
  const [ddE1, setDdE1] = useState(''); const [ddN1, setDdN1] = useState('')
  const [ddE2, setDdE2] = useState(''); const [ddN2, setDdN2] = useState('')
  const [ddD1, setDdD1] = useState(''); const [ddD2, setDdD2] = useState('')
  const [ddResult, setDdResult] = useState<DistDistResult | null>(null)
  const [ddSel, setDdSel] = useState(0)

  // ── BEARING-DISTANCE ───────────────────────────────────────────────────────
  const [bdE1, setBdE1] = useState(''); const [bdN1, setBdN1] = useState('')
  const [bdE2, setBdE2] = useState(''); const [bdN2, setBdN2] = useState('')
  const [bdBear, setBdBear] = useState(DMSState())
  const [bdDist, setBdDist] = useState('')
  const [bdResult, setBdResult] = useState<BearingDistResult | null>(null)
  const [bdSel, setBdSel] = useState(0)

  // ── ARC BOUNDARY ──────────────────────────────────────────────────────────
  const [arcSE, setArcSE] = useState(''); const [arcSN, setArcSN] = useState('')
  const [arcEE, setArcEE] = useState(''); const [arcEN, setArcEN] = useState('')
  const [arcR, setArcR] = useState(''); const [arcCW, setArcCW] = useState(true)
  const [arcResult, setArcResult] = useState<ArcResult | null>(null)

  // ── COMPUTE HANDLERS ────────────────────────────────────────────────────────
  const handleInverse = () => {
    setError('')
    if (!invE1 || !invN1 || !invE2 || !invN2) { setError('Enter all coordinates'); return }
    try {
      setInvResult(inverseComputation({
        e1: parseFloat(invE1), n1: parseFloat(invN1),
        e2: parseFloat(invE2), n2: parseFloat(invN2),
        label1: invL1, label2: invL2,
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handlePolar = () => {
    setError('')
    if (!polE1 || !polN1 || !polD) { setError('Enter all fields'); return }
    const b = DMSGet(polBear)
    try {
      setPolResult(polarComputation({
        e1: parseFloat(polE1), n1: parseFloat(polN1),
        bearingDeg: b.deg, bearingMin: b.min, bearingSec: b.sec,
        distance: parseFloat(polD),
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleIntersection = () => {
    setError('')
    const b1 = DMSGet(intBear1)
    const b2 = DMSGet(intBear2)
    try {
      setIntResult(intersectionComputation({
        e1: parseFloat(intE1), n1: parseFloat(intN1),
        e2: parseFloat(intE2), n2: parseFloat(intN2),
        bearingDeg1: b1.deg, bearingMin1: b1.min, bearingSec1: b1.sec,
        bearingDeg2: b2.deg, bearingMin2: b2.min, bearingSec2: b2.sec,
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleResection = () => {
    setError('')
    const a = DMSGet(resAlpha)
    const b = DMSGet(resBeta)
    try {
      setResResult(resectionComputation({
        eA: parseFloat(resEA), nA: parseFloat(resNA),
        eB: parseFloat(resEB), nB: parseFloat(resNB),
        eC: parseFloat(resEC), nC: parseFloat(resNC),
        alphaDeg: a.deg, alphaMin: a.min, alphaSec: a.sec,
        betaDeg: b.deg, betaMin: b.min, betaSec: b.sec,
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleArea = () => {
    setError('')
    const lines = areaText.trim().split('\n').filter((l) => l.trim())
    const points = lines.map((line) => {
      const parts = line.split(/[,\t]+/)
      if (parts.length < 3) return null
      return { label: parts[0].trim(), easting: parseFloat(parts[1]), northing: parseFloat(parts[2]) }
    }).filter(Boolean) as Array<{ label: string; easting: number; northing: number }>
    if (points.length < 3) { setError('At least 3 points required'); return }
    try {
      setAreaResult(areaComputation({ points }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleJoin = () => {
    setError('')
    const lines = joinText.trim().split('\n').filter((l) => l.trim())
    const points = lines.map((line) => {
      const parts = line.split(/[,\t]+/)
      if (parts.length < 3) return null
      return { label: parts[0].trim(), easting: parseFloat(parts[1]), northing: parseFloat(parts[2]) }
    }).filter(Boolean) as Array<{ label: string; easting: number; northing: number }>
    if (points.length < 2) { setError('At least 2 points required'); return }
    try {
      setJoinResult(joinComputation({ points }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleDistDist = () => {
    setError('')
    if (!ddE1 || !ddN1 || !ddE2 || !ddN2 || !ddD1 || !ddD2) { setError('Enter all fields'); return }
    try {
      setDdResult(distanceDistanceIntersection({
        e1: parseFloat(ddE1), n1: parseFloat(ddN1),
        e2: parseFloat(ddE2), n2: parseFloat(ddN2),
        distance1: parseFloat(ddD1), distance2: parseFloat(ddD2),
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleBearingDist = () => {
    setError('')
    const b = DMSGet(bdBear)
    if (!bdE1 || !bdN1 || !bdE2 || !bdN2 || !bdDist) { setError('Enter all fields'); return }
    try {
      setBdResult(bearingDistanceIntersection({
        e1: parseFloat(bdE1), n1: parseFloat(bdN1),
        e2: parseFloat(bdE2), n2: parseFloat(bdN2),
        bearingDeg: b.deg, bearingMin: b.min, bearingSec: b.sec,
        distance: parseFloat(bdDist),
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleArcBoundary = () => {
    setError('')
    if (!arcSE || !arcSN || !arcEE || !arcEN || !arcR) { setError('Enter all fields'); return }
    try {
      setArcResult(arcByRadiusAndChord({
        startPoint: { easting: parseFloat(arcSE), northing: parseFloat(arcSN) },
        endPoint: { easting: parseFloat(arcEE), northing: parseFloat(arcEN) },
        radius: parseFloat(arcR),
        isClockwise: arcCW,
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const clearAll = () => {
    setError('')
    setInvResult(null); setPolResult(null); setIntResult(null)
    setResResult(null); setAreaResult(null); setJoinResult(null)
    setDdResult(null); setBdResult(null); setArcResult(null)
  }

  const handleExportPDF = async () => {
    try {
      const { default: jsPDF } = await import('jspdf')
      const { default: autoTable } = await import('jspdf-autotable')
      const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' })

      doc.setFontSize(16)
      doc.text('METARDU — COGO Computation Report', 14, 14)
      doc.setFontSize(10)
      doc.text(`Computation Type: ${TABS.find((t) => t.id === activeTab)?.label || activeTab}`, 14, 22)
      doc.setFontSize(8)
      doc.text(`Generated: ${new Date().toLocaleString()} | Survey Act Cap. 299 | RDM 1.1 (2025)`, 14, 28)
      doc.setDrawColor(150)
      doc.line(14, 30, 196, 30)

      if (activeTab === 'inverse' && invResult) {
        autoTable(doc, {
          startY: 34,
          head: [['Parameter', 'Value', 'Formula']],
          body: [
            ['Point 1', invL1, ''],
            ['Point 2', invL2, ''],
            ['Delta Easting', `${invResult.deltaE.toFixed(4)} m`, ''],
            ['Delta Northing', `${invResult.deltaN.toFixed(4)} m`, ''],
            ['WCB', invResult.wcbDMS, ''],
            ['Distance', `${invResult.distance.toFixed(4)} m`, ''],
            ['Reduced Bearing', invResult.reducedBearing, ''],
            ['Back Bearing', invResult.backBearingDMS, ''],
            ['Quadrant', invResult.quadrant, ''],
            ['Arithmetic Check', invResult.arithmeticCheck.passed ? 'PASS' : 'FAIL', invResult.arithmeticCheck.value.toFixed(6)],
          ],
          styles: { fontSize: 9 },
          columnStyles: { 2: { cellWidth: 60 } },
          headStyles: { fillColor: [34, 197, 94] },
        })
      } else if (activeTab === 'polar' && polResult) {
        autoTable(doc, {
          startY: 34,
          head: [['Parameter', 'Value']],
          body: [
            ['WCB Used', polResult.wcbDMS],
            ['E2 (m)', polResult.e2.toFixed(4)],
            ['N2 (m)', polResult.n2.toFixed(4)],
          ],
          styles: { fontSize: 9 },
          headStyles: { fillColor: [34, 197, 94] },
        })
      } else if (activeTab === 'intersection' && intResult) {
        autoTable(doc, {
          startY: 34,
          head: [['Parameter', 'Value']],
          body: [
            ['Intersection Easting E3 (m)', intResult.e3.toFixed(4)],
            ['Intersection Northing N3 (m)', intResult.n3.toFixed(4)],
            ['Distance from P1 (m)', intResult.distanceFrom1.toFixed(4)],
            ['Distance from P2 (m)', intResult.distanceFrom2.toFixed(4)],
            ['Check Difference (m)', intResult.checkDiff.toFixed(4)],
            ['Within Tolerance', intResult.isWithinTolerance ? 'PASS' : 'FLAG'],
          ],
          styles: { fontSize: 9 },
          headStyles: { fillColor: [34, 197, 94] },
        })
      } else if (activeTab === 'resection' && resResult) {
        autoTable(doc, {
          startY: 34,
          head: [['Parameter', 'Value']],
          body: [
            ['Station E (m)', resResult.eP.toFixed(4)],
            ['Station N (m)', resResult.nP.toFixed(4)],
            ['Distance to A (m)', resResult.distToA.toFixed(4)],
            ['Distance to B (m)', resResult.distToB.toFixed(4)],
            ['Distance to C (m)', resResult.distToC.toFixed(4)],
            ['Danger Circle', resResult.isDangerCircle ? 'WARNING' : 'No'],
          ],
          styles: { fontSize: 9 },
          headStyles: { fillColor: [34, 197, 94] },
        })
      } else if (activeTab === 'area' && areaResult) {
        autoTable(doc, {
          startY: 34,
          head: [['Parameter', 'Value']],
          body: [
            ['Area (m\u00B2)', areaResult.areaSqm.toFixed(4)],
            ['Area (ha)', areaResult.areaHa.toFixed(4)],
            ['Perimeter (m)', areaResult.perimeter.toFixed(4)],
            ['Centroid E (m)', areaResult.centroid.easting.toFixed(4)],
            ['Centroid N (m)', areaResult.centroid.northing.toFixed(4)],
            ['Arithmetic Check', areaResult.arithmeticCheck.passed ? 'PASS' : 'FAIL'],
          ],
          styles: { fontSize: 9 },
          headStyles: { fillColor: [34, 197, 94] },
        })
      } else if (activeTab === 'join' && joinResult) {
        autoTable(doc, {
          startY: 34,
          head: [['From', 'To', 'Delta E (m)', 'Delta N (m)', 'Distance (m)', 'WCB', 'Back Bearing']],
          body: joinResult.rows.map((r) => [r.from, r.to, r.deltaE.toFixed(4), r.deltaN.toFixed(4), r.distance.toFixed(4), r.wcbDMS, r.backBearingDMS]),
          styles: { fontSize: 8 },
          headStyles: { fillColor: [34, 197, 94] },
        })
        const finalY = ((doc as unknown as { lastAutoTable?: { finalY: number } }).lastAutoTable?.finalY ?? 34) + 6
        doc.setFontSize(9)
        doc.text(`Total Perimeter: ${joinResult.totalPerimeter.toFixed(4)} m`, 14, finalY)
      } else {
        doc.setFontSize(10)
        doc.text('No computation results to export. Run a calculation first.', 14, 34)
      }

      doc.setFontSize(7)
      doc.setTextColor(120)
      doc.text('Source: Ghilani & Wolf, Elementary Surveying 16th Ed. | N.N. Basak, Surveying and Levelling | Survey Act Cap. 299 | RDM 1.1 (2025)', 14, doc.internal.pageSize.height - 8)
      doc.setTextColor(0)

      const date = new Date().toISOString().slice(0, 10)
      const tabName = TABS.find((t) => t.id === activeTab)?.label.replace(/[^a-zA-Z]/g, '_') || activeTab
      doc.save(`METARDU_COGO_${tabName}_${date}.pdf`)
    } catch (err) {
      logger.error('PDF export error:', { error: err })
      setError('Failed to export PDF. Please try again.')
    }
  }

  const handleExportCSV = () => {
    try {
      let headers: string[] = ['Parameter', 'Value']
      let rows: string[][] = []

      if (activeTab === 'inverse' && invResult) {
        headers = ['Parameter', 'Value', 'Formula']
        rows = [
          ['Point 1', invL1, ''],
          ['Point 2', invL2, ''],
          ['Delta Easting (m)', invResult.deltaE.toFixed(4), ''],
          ['Delta Northing (m)', invResult.deltaN.toFixed(4), ''],
          ['WCB', invResult.wcbDMS, ''],
          ['Distance (m)', invResult.distance.toFixed(4), ''],
          ['Reduced Bearing', invResult.reducedBearing, ''],
          ['Back Bearing', invResult.backBearingDMS, ''],
          ['Quadrant', invResult.quadrant, ''],
          ['Arithmetic Check', invResult.arithmeticCheck.passed ? 'PASS' : 'FAIL', invResult.arithmeticCheck.value.toFixed(6)],
        ]
      } else if (activeTab === 'polar' && polResult) {
        rows = [
          ['WCB Used', polResult.wcbDMS],
          ['E2 (m)', polResult.e2.toFixed(4)],
          ['N2 (m)', polResult.n2.toFixed(4)],
        ]
      } else if (activeTab === 'intersection' && intResult) {
        rows = [
          ['Intersection E3 (m)', intResult.e3.toFixed(4)],
          ['Intersection N3 (m)', intResult.n3.toFixed(4)],
          ['Distance from P1 (m)', intResult.distanceFrom1.toFixed(4)],
          ['Distance from P2 (m)', intResult.distanceFrom2.toFixed(4)],
        ]
      } else if (activeTab === 'resection' && resResult) {
        rows = [
          ['Station E (m)', resResult.eP.toFixed(4)],
          ['Station N (m)', resResult.nP.toFixed(4)],
          ['Distance to A (m)', resResult.distToA.toFixed(4)],
          ['Distance to B (m)', resResult.distToB.toFixed(4)],
          ['Distance to C (m)', resResult.distToC.toFixed(4)],
        ]
      } else if (activeTab === 'area' && areaResult) {
        rows = [
          ['Area (m²)', areaResult.areaSqm.toFixed(4)],
          ['Area (ha)', areaResult.areaHa.toFixed(4)],
          ['Perimeter (m)', areaResult.perimeter.toFixed(4)],
          ['Centroid E (m)', areaResult.centroid.easting.toFixed(4)],
          ['Centroid N (m)', areaResult.centroid.northing.toFixed(4)],
        ]
      } else if (activeTab === 'join' && joinResult) {
        headers = ['From', 'To', 'Delta E (m)', 'Delta N (m)', 'Distance (m)', 'WCB', 'Back Bearing']
        rows = joinResult.rows.map(r => [r.from, r.to, r.deltaE.toFixed(4), r.deltaN.toFixed(4), r.distance.toFixed(4), r.wcbDMS, r.backBearingDMS])
      } else {
        setError('No data to export')
        return
      }

      const csv = toCSV(headers, rows)
      const tabName = TABS.find(t => t.id === activeTab)?.label.replace(/[^a-zA-Z]/g, '_') || activeTab
      downloadCSV(csv, `METARDU_COGO_${tabName}`)
    } catch (err) {
      logger.error('CSV export error:', { error: err })
      setError('Failed to export CSV. Please try again.')
    }
  }

  const TABS: { id: Tab; label: string }[] = [
    { id: 'inverse', label: 'Distance & Bearing' },
    { id: 'polar', label: 'Radiation' },
    { id: 'intersection', label: 'Brg-Brg Intersection' },
    { id: 'distDist', label: 'Dist-Dist Intersection' },
    { id: 'bearingDist', label: 'Brg-Dist Intersection' },
    { id: 'arcBoundary', label: 'Arc Boundary' },
    { id: 'resection', label: 'Resection' },
    { id: 'area', label: 'Area by Coordinates' },
    { id: 'join', label: 'Missing Line' },
  ]

  return (
    <div className={compact ? '' : 'w-full max-w-7xl mx-auto px-3 md:px-4 py-4 md:py-8'}>
      {!compact && (
        <>
          <h1 className="text-3xl font-bold mb-2">COGO Calculator</h1>
          <p className="text-sm text-[var(--text-muted)] mb-6">
            Coordinate Geometry — Inverse, Polar, Intersection, Resection, Area, Join | Survey Act Cap 299 | RDM 1.1 (2025)
          </p>
        </>
      )}

      {/* Tab Bar */}
      <div className="flex items-center gap-1 border-b border-[var(--border-color)] mb-4 overflow-x-auto">
        {TABS.map((tab) => (
          <button key={tab.id} onClick={() => { setActiveTab(tab.id); clearAll() }}
            className={`px-4 py-2 text-sm font-medium whitespace-nowrap border-b-2 transition-colors ${
              activeTab === tab.id
                ? 'border-[var(--accent)] text-[var(--accent)]'
                : 'border-transparent text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
            }`}>
            {tab.label}
          </button>
        ))}
        <div className="flex-1" />
        <button onClick={handleExportPDF}
          className="px-3 py-1.5 text-xs text-[var(--text-secondary)] hover:text-[var(--accent)] border border-[var(--border-color)] hover:border-[var(--accent)] rounded inline-flex items-center gap-1">
          <Download className="w-3 h-3" /> PDF
        </button>
        <button onClick={handleExportCSV}
          className="px-3 py-1.5 text-xs text-[var(--text-secondary)] hover:text-[var(--accent)] border border-[var(--border-color)] hover:border-[var(--accent)] rounded inline-flex items-center gap-1">
          <Download className="w-3 h-3" /> CSV
        </button>
        <button onClick={clearAll}
          className="px-3 py-1.5 text-xs text-[var(--text-muted)] hover:text-[var(--text-secondary)]">
          Clear
        </button>
      </div>

      {error && <div className="mb-4 p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{error}</div>}

      <div className="grid md:grid-cols-2 gap-6">
        {/* ── INPUT PANEL ── */}
        <div className="space-y-4">
          {/* INVERSE */}
          {activeTab === 'inverse' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Inverse Computation — Given two points, compute bearing and distance</h2>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="Point 1 Easting (m)" value={invE1} onChange={setInvE1} />
                <CoordField label="Point 1 Northing (m)" value={invN1} onChange={setInvN1} />
                <div>
                  <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="point-1-label">Point 1 Label</label>
                  <input id="point-1-label" value={invL1} onChange={e => setInvL1(e.target.value)}
                    className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="Point 2 Easting (m)" value={invE2} onChange={setInvE2} />
                <CoordField label="Point 2 Northing (m)" value={invN2} onChange={setInvN2} />
                <div>
                  <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="point-2-label">Point 2 Label</label>
                  <input id="point-2-label" value={invL2} onChange={e => setInvL2(e.target.value)}
                    className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                </div>
              </div>
              <button onClick={handleInverse} className="btn btn-primary w-full">Compute Inverse →</button>
            </div>
          )}

          {/* RADIATION */}
          {activeTab === 'polar' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Radiation — Station + bearing/dist → coordinates</h2>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="Known Easting (m)" value={polE1} onChange={setPolE1} />
                <CoordField label="Known Northing (m)" value={polN1} onChange={setPolN1} />
              </div>
              <DMSField label="WCB Bearing" deg={polBear.d} min={polBear.m} sec={polBear.s}
                onChange={(f, v) => setPolBear(p => ({ ...p, [f]: v }))} />
              <CoordField label="Distance (m)" value={polD} onChange={setPolD} />
              <button onClick={handlePolar} className="btn btn-primary w-full">Compute Polar →</button>
            </div>
          )}

          {/* INTERSECTION */}
          {activeTab === 'intersection' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Bearing Intersection — Compute intersection of two bearings</h2>
              <p className="text-xs text-[var(--text-muted)]">Known Point 1</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="Easting (m)" value={intE1} onChange={setIntE1} />
                <CoordField label="Northing (m)" value={intN1} onChange={setIntN1} />
              </div>
              <DMSField label="Bearing from Point 1 (DMS)" deg={intBear1.d} min={intBear1.m} sec={intBear1.s}
                onChange={(f, v) => setIntBear1(p => ({ ...p, [f]: v }))} />
              <p className="text-xs text-[var(--text-muted)]">Known Point 2</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="Easting (m)" value={intE2} onChange={setIntE2} />
                <CoordField label="Northing (m)" value={intN2} onChange={setIntN2} />
              </div>
              <DMSField label="Bearing from Point 2 (DMS)" deg={intBear2.d} min={intBear2.m} sec={intBear2.s}
                onChange={(f, v) => setIntBear2(p => ({ ...p, [f]: v }))} />
              <button onClick={handleIntersection} className="btn btn-primary w-full">Compute Intersection →</button>
            </div>
          )}

          {/* RESECTION */}
          {activeTab === 'resection' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Three-Point Resection (Tienstra/Pothenot)</h2>
              <div className="grid grid-cols-3 gap-2">
                <div />
                <div className="text-xs text-center font-semibold text-[var(--text-secondary)]">Easting</div>
                <div className="text-xs text-center font-semibold text-[var(--text-secondary)]">Northing</div>
                <div className="text-xs text-[var(--text-secondary)] flex items-center">Point A</div>
                <input aria-label="Result easting A" value={resEA} onChange={e => setResEA(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                <input aria-label="Result northing A" value={resNA} onChange={e => setResNA(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                <div className="text-xs text-[var(--text-secondary)] flex items-center">Point B</div>
                <input aria-label="Result easting B" value={resEB} onChange={e => setResEB(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                <input aria-label="Result northing B" value={resNB} onChange={e => setResNB(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                <div className="text-xs text-[var(--text-secondary)] flex items-center">Point C</div>
                <input aria-label="Result easting C" value={resEC} onChange={e => setResEC(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                <input aria-label="Result northing C" value={resNC} onChange={e => setResNC(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
              </div>
              <DMSField label="Angle α = ∠APB (DMS)" deg={resAlpha.d} min={resAlpha.m} sec={resAlpha.s}
                onChange={(f, v) => setResAlpha(p => ({ ...p, [f]: v }))} />
              <DMSField label="Angle β = ∠BPC (DMS)" deg={resBeta.d} min={resBeta.m} sec={resBeta.s}
                onChange={(f, v) => setResBeta(p => ({ ...p, [f]: v }))} />
              <button onClick={handleResection} className="btn btn-primary w-full">Compute Resection →</button>
            </div>
          )}

          {/* AREA */}
          {activeTab === 'area' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Area by Coordinates (Shoelace)</h2>
              <p className="text-xs text-[var(--text-muted)]">Enter one point per line: Label, Easting, Northing</p>
              <textarea value={areaText} onChange={e => setAreaText(e.target.value)}
                className="w-full h-48 px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm font-mono"
                placeholder='Label, Easting, Northing (one point per line)' />
              <button onClick={handleArea} className="btn btn-primary w-full">Compute Area →</button>
            </div>
          )}

          {/* DISTANCE-DISTANCE */}
          {activeTab === 'distDist' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Distance-Distance Intersection — Circle-circle</h2>
              <p className="text-xs text-[var(--text-muted)]">Known Point 1</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E₁ (m)" value={ddE1} onChange={setDdE1} />
                <CoordField label="N₁ (m)" value={ddN1} onChange={setDdN1} />
              </div>
              <CoordField label="Distance from P1 (m)" value={ddD1} onChange={setDdD1} />
              <p className="text-xs text-[var(--text-muted)]">Known Point 2</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E₂ (m)" value={ddE2} onChange={setDdE2} />
                <CoordField label="N₂ (m)" value={ddN2} onChange={setDdN2} />
              </div>
              <CoordField label="Distance from P2 (m)" value={ddD2} onChange={setDdD2} />
              <button onClick={handleDistDist} className="btn btn-primary w-full">Compute Intersection →</button>
            </div>
          )}

          {/* BEARING-DISTANCE */}
          {activeTab === 'bearingDist' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Bearing-Distance Intersection — Ray meets circle</h2>
              <p className="text-xs text-[var(--text-muted)]">Bearing from Point 1</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E₁ (m)" value={bdE1} onChange={setBdE1} />
                <CoordField label="N₁ (m)" value={bdN1} onChange={setBdN1} />
              </div>
              <DMSField label="WCB Bearing from P1" deg={bdBear.d} min={bdBear.m} sec={bdBear.s}
                onChange={(f, v) => setBdBear(p => ({ ...p, [f]: v }))} />
              <p className="text-xs text-[var(--text-muted)]">Distance from Point 2</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E₂ (m)" value={bdE2} onChange={setBdE2} />
                <CoordField label="N₂ (m)" value={bdN2} onChange={setBdN2} />
              </div>
              <CoordField label="Distance from P2 (m)" value={bdDist} onChange={setBdDist} />
              <button onClick={handleBearingDist} className="btn btn-primary w-full">Compute Intersection →</button>
            </div>
          )}

          {/* ARC BOUNDARY */}
          {activeTab === 'arcBoundary' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Arc Boundary — Radius + Chord endpoints</h2>
              <p className="text-xs text-[var(--text-muted)]">Start Point</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E start (m)" value={arcSE} onChange={setArcSE} />
                <CoordField label="N start (m)" value={arcSN} onChange={setArcSN} />
              </div>
              <p className="text-xs text-[var(--text-muted)]">End Point</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E end (m)" value={arcEE} onChange={setArcEE} />
                <CoordField label="N end (m)" value={arcEN} onChange={setArcEN} />
              </div>
              <CoordField label="Radius (m)" value={arcR} onChange={setArcR} />
              <label className="flex items-center gap-2 text-sm text-[var(--text-secondary)]">
                <input type="checkbox" checked={arcCW} onChange={e => setArcCW(e.target.checked)} /> Clockwise arc
              </label>
              <button onClick={handleArcBoundary} className="btn btn-primary w-full">Compute Arc →</button>
            </div>
          )}

          {/* JOIN */}
          {activeTab === 'join' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Join Computation — Traverse summary table</h2>
              <p className="text-xs text-[var(--text-muted)]">Enter points in order: Label, Easting, Northing</p>
              <textarea value={joinText} onChange={e => setJoinText(e.target.value)}
                className="w-full h-48 px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm font-mono"
                placeholder='Label, Easting, Northing (one point per line)' />
              <button onClick={handleJoin} className="btn btn-primary w-full">Compute Joins →</button>
            </div>
          )}
        </div>

        {/* ── RESULTS PANEL ── */}
        <div className="space-y-4">
          {/* INVERSE RESULTS */}
          {activeTab === 'inverse' && invResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Inverse</h2>
              <StepsDisplay steps={invResult.steps} />
              <div className="border-t border-[var(--border-color)] pt-4">
                <h3 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">Result</h3>
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="ΔE" value={`${invResult.deltaE.toFixed(4)} m`} />
                  <ResultCard label="ΔN" value={`${invResult.deltaN.toFixed(4)} m`} />
                  <ResultCard label="WCB" value={invResult.wcbDMS} accent />
                  <ResultCard label="Distance" value={`${invResult.distance.toFixed(4)} m`} accent />
                  <ResultCard label="Reduced Bearing θ" value={invResult.reducedBearing} />
                  <ResultCard label="Back Bearing" value={invResult.backBearingDMS} />
                  <ResultCard label="Quadrant" value={invResult.quadrant} />
                  <ResultCard label="Arithmetic Check"
                    value={`${invResult.arithmeticCheck.passed ? 'PASS ' : 'FAIL [x]'} (${invResult.arithmeticCheck.value.toFixed(6)})`}
                    accent={invResult.arithmeticCheck.passed} />
                </div>
              </div>
            </div>
          )}

          {/* POLAR RESULTS */}
          {activeTab === 'polar' && polResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Polar</h2>
              <StepsDisplay steps={polResult.steps} />
              <div className="border-t border-[var(--border-color)] pt-4">
                <h3 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">Result</h3>
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="WCB Used" value={polResult.wcbDMS} accent />
                  <ResultCard label="E₂ (m)" value={polResult.e2.toFixed(4)} accent />
                  <ResultCard label="N₂ (m)" value={polResult.n2.toFixed(4)} accent />
                </div>
              </div>
            </div>
          )}

          {/* INTERSECTION RESULTS */}
          {activeTab === 'intersection' && intResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Bearing Intersection</h2>
              <StepsDisplay steps={intResult.steps} />
              <div className="border-t border-[var(--border-color)] pt-4">
                <h3 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">Result</h3>
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="E₃ (m)" value={intResult.e3.toFixed(4)} accent />
                  <ResultCard label="N₃ (m)" value={intResult.n3.toFixed(4)} accent />
                  <ResultCard label="Dist from P1" value={`${intResult.distanceFrom1.toFixed(4)} m`} />
                  <ResultCard label="Dist from P2" value={`${intResult.distanceFrom2.toFixed(4)} m`} />
                  <ResultCard label="Check Difference"
                    value={`${intResult.checkDiff.toFixed(4)} m  ${intResult.isWithinTolerance ? ' PASS' : '[x] FLAG'}`}
                    accent={intResult.isWithinTolerance} />
                </div>
              </div>
            </div>
          )}

          {/* RESECTION RESULTS */}
          {activeTab === 'resection' && resResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Tienstra Resection</h2>
              {resResult.isDangerCircle && (
                <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">
                  <AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> DANGER CIRCLE WARNING — K₁+K₂+K₃ ≈ 0. Point P is approximately on the circumcircle of triangle ABC. Results may be unreliable. Consider changing observation setup.
                </div>
              )}
              <StepsDisplay steps={resResult.steps} />
              <div className="border-t border-[var(--border-color)] pt-4">
                <h3 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">Result</h3>
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="Eₚ (m)" value={resResult.eP.toFixed(4)} accent />
                  <ResultCard label="Nₚ (m)" value={resResult.nP.toFixed(4)} accent />
                  <ResultCard label="Dist to A" value={`${resResult.distToA.toFixed(4)} m`} />
                  <ResultCard label="Dist to B" value={`${resResult.distToB.toFixed(4)} m`} />
                  <ResultCard label="Dist to C" value={`${resResult.distToC.toFixed(4)} m`} />
                </div>
              </div>
            </div>
          )}

          {/* AREA RESULTS */}
          {activeTab === 'area' && areaResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Area by Coordinates</h2>
              {!areaResult.arithmeticCheck.passed && (
                <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">
                  Arithmetic check failed. Difference: {areaResult.arithmeticCheck.diff.toFixed(4)} m². Recheck coordinate entries.
                </div>
              )}
              <div className="overflow-x-auto">
                <table className="w-full text-xs font-mono">
                  <thead>
                    <tr className="border-b border-[var(--border-color)] bg-[var(--bg-tertiary)]/30">
                      <th className="px-2 py-1.5 text-left text-[var(--text-secondary)]">From</th>
                      <th className="px-2 py-1.5 text-left text-[var(--text-secondary)]">To</th>
                      <th className="px-2 py-1.5 text-right text-[var(--text-secondary)]">E×Nₙ₊₁</th>
                      <th className="px-2 py-1.5 text-right text-[var(--text-secondary)]">N×Eₙ₊₁</th>
                    </tr>
                  </thead>
                  <tbody>
                    {areaResult.diagonalRows.map((row, i) => (
                      <tr key={`${row}-${i}`} className="border-b border-[var(--border-color)]/20">
                        <td className="px-2 py-1 text-[var(--text-primary)]">{row.from}</td>
                        <td className="px-2 py-1 text-[var(--text-primary)]">{row.to}</td>
                        <td className="px-2 py-1 text-right text-[var(--text-secondary)]">{row.posProduct.toFixed(2)}</td>
                        <td className="px-2 py-1 text-right text-[var(--text-secondary)]">{row.negProduct.toFixed(2)}</td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot>
                    <tr className="font-semibold">
                      <td colSpan={2} className="px-2 py-1 text-[var(--text-primary)]">Σ</td>
                      <td className="px-2 py-1 text-right text-[var(--text-primary)]">{areaResult.positiveSum.toFixed(2)}</td>
                      <td className="px-2 py-1 text-right text-[var(--text-primary)]">{areaResult.negativeSum.toFixed(2)}</td>
                    </tr>
                  </tfoot>
                </table>
              </div>
              <div className="grid grid-cols-2 gap-2">
                <ResultCard label="Area (m²)" value={areaResult.areaSqm.toFixed(4)} accent />
                <ResultCard label="Area (ha)" value={areaResult.areaHa.toFixed(4)} accent />
                <ResultCard label="Perimeter (m)" value={areaResult.perimeter.toFixed(4)} />
                <ResultCard label="Arithmetic Check"
                  value={`${areaResult.arithmeticCheck.passed ? 'PASS ' : 'FAIL [x]'} (${areaResult.arithmeticCheck.diff.toFixed(6)} m²)`}
                  accent={areaResult.arithmeticCheck.passed} />
                <ResultCard label="Centroid E" value={areaResult.centroid.easting.toFixed(4)} />
                <ResultCard label="Centroid N" value={areaResult.centroid.northing.toFixed(4)} />
              </div>
            </div>
          )}

          {/* JOIN RESULTS */}
          {activeTab === 'join' && joinResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Join Table</h2>
              <div className="overflow-x-auto">
                <table className="min-w-[600px] w-full text-xs font-mono">
                  <thead>
                    <tr className="border-b border-[var(--border-color)] bg-[var(--bg-tertiary)]/30">
                      <th className="px-2 py-1.5 text-left text-[var(--text-secondary)]">From</th>
                      <th className="px-2 py-1.5 text-left text-[var(--text-secondary)]">To</th>
                      <th className="px-2 py-1.5 text-right text-[var(--text-secondary)]">ΔE</th>
                      <th className="px-2 py-1.5 text-right text-[var(--text-secondary)]">ΔN</th>
                      <th className="px-2 py-1.5 text-right text-[var(--text-secondary)]">Dist (m)</th>
                      <th className="px-2 py-1.5 text-center text-[var(--text-secondary)]">WCB</th>
                      <th className="px-2 py-1.5 text-center text-[var(--text-secondary)]">Back Brg</th>
                    </tr>
                  </thead>
                  <tbody>
                    {joinResult.rows.map((row, i) => (
                      <tr key={`${row}-${i}`} className="border-b border-[var(--border-color)]/20">
                        <td className="px-2 py-1 text-[var(--text-primary)]">{row.from}</td>
                        <td className="px-2 py-1 text-[var(--text-primary)]">{row.to}</td>
                        <td className="px-2 py-1 text-right text-[var(--text-secondary)]">{row.deltaE >= 0 ? '+' : ''}{row.deltaE.toFixed(4)}</td>
                        <td className="px-2 py-1 text-right text-[var(--text-secondary)]">{row.deltaN >= 0 ? '+' : ''}{row.deltaN.toFixed(4)}</td>
                        <td className="px-2 py-1 text-right text-[var(--text-primary)]">{row.distance.toFixed(4)}</td>
                        <td className="px-2 py-1 text-center text-[var(--accent)]">{row.wcbDMS}</td>
                        <td className="px-2 py-1 text-center text-[var(--text-secondary)]">{row.backBearingDMS}</td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot>
                    <tr className="font-semibold border-t border-[var(--border-color)]">
                      <td colSpan={4} className="px-2 py-1 text-[var(--text-primary)]">Total Perimeter</td>
                      <td className="px-2 py-1 text-right text-[var(--accent)]">{joinResult.totalPerimeter.toFixed(4)}</td>
                      <td colSpan={2}></td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            </div>
          )}

          {/* DIST-DIST RESULTS */}
          {activeTab === 'distDist' && ddResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Distance-Distance Intersection</h2>
              {ddResult.error && <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{ddResult.error}</div>}
              <StepsDisplay steps={ddResult.steps} />
              {ddResult.hasSolution && ddResult.solutions.length > 1 && (
                <div className="flex gap-2">
                  <button onClick={() => setDdSel(0)} className={`px-3 py-1.5 rounded text-sm ${ddSel === 0 ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'}`}>Solution 1</button>
                  <button onClick={() => setDdSel(1)} className={`px-3 py-1.5 rounded text-sm ${ddSel === 1 ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'}`}>Solution 2</button>
                </div>
              )}
              {ddResult.hasSolution && (
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="E (m)" value={ddResult.solutions[ddSel]?.easting.toFixed(4) ?? '-'} accent />
                  <ResultCard label="N (m)" value={ddResult.solutions[ddSel]?.northing.toFixed(4) ?? '-'} accent />
                </div>
              )}
            </div>
          )}

          {/* BEARING-DIST RESULTS */}
          {activeTab === 'bearingDist' && bdResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Bearing-Distance Intersection</h2>
              {bdResult.error && <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{bdResult.error}</div>}
              <StepsDisplay steps={bdResult.steps} />
              {bdResult.hasSolution && bdResult.solutions.length > 1 && (
                <div className="flex gap-2">
                  <button onClick={() => setBdSel(0)} className={`px-3 py-1.5 rounded text-sm ${bdSel === 0 ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'}`}>Solution 1</button>
                  <button onClick={() => setBdSel(1)} className={`px-3 py-1.5 rounded text-sm ${bdSel === 1 ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'}`}>Solution 2</button>
                </div>
              )}
              {bdResult.hasSolution && (
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="E (m)" value={bdResult.solutions[bdSel]?.easting.toFixed(4) ?? '-'} accent />
                  <ResultCard label="N (m)" value={bdResult.solutions[bdSel]?.northing.toFixed(4) ?? '-'} accent />
                </div>
              )}
            </div>
          )}

          {/* ARC BOUNDARY RESULTS */}
          {activeTab === 'arcBoundary' && arcResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Arc Boundary</h2>
              <StepsDisplay steps={arcResult.steps} />
              <div className="grid grid-cols-2 gap-2">
                <ResultCard label="Center E (m)" value={arcResult.center.easting.toFixed(4)} />
                <ResultCard label="Center N (m)" value={arcResult.center.northing.toFixed(4)} />
                <ResultCard label="Arc Length" value={`${arcResult.arcLength.toFixed(4)} m`} accent />
                <ResultCard label="Chord Length" value={`${arcResult.chordLength.toFixed(4)} m`} />
                <ResultCard label="Subtended Angle" value={`${arcResult.subtendedAngle.toFixed(4)}°`} accent />
                <ResultCard label="Segment Area" value={`${arcResult.segmentArea.toFixed(4)} m²`} />
                <ResultCard label="Chord Bearing" value={arcResult.chordBearingDMS} />
                <ResultCard label="Arc Points" value={`${arcResult.points.length} pts`} />
              </div>
            </div>
          )}

          {!invResult && !polResult && !intResult && !resResult && !areaResult && !joinResult && !ddResult && !bdResult && !arcResult && (
            <div className="flex items-center justify-center h-64 border border-dashed border-[var(--border-color)] rounded">
              <p className="text-sm text-[var(--text-muted)]">Enter values and click Compute</p>
            </div>
          )}
        </div>
      </div>

      <div className="mt-4 text-center text-xs text-[var(--text-muted)]">
        Source: Ghilani &amp; Wolf, Elementary Surveying 16th Ed., Sections 10.3–10.7, 12.5 | N.N. Basak, Surveying and Levelling
      </div>
    </div>
  )
}

'use client';

import { useState } from 'react'
import type { SurveyPlanData } from '@/lib/reports/surveyPlan/types'

interface ComplianceItem {
  key: string
  label: string
  pass: boolean
}

interface ComplianceChecklistModalProps {
  isOpen: boolean
  onClose: () => void
  data: SurveyPlanData
  onExport: () => void
}

export default function ComplianceChecklistModal({
  isOpen,
  onClose,
  data,
  onExport,
}: ComplianceChecklistModalProps) {
  if (!isOpen) return null

  const p = data.project
  const parcel = data.parcel
  const pts = parcel?.boundaryPoints || []

  const items: ComplianceItem[] = [
    {
      key: 'beacons',
      label: 'Boundary beacons are present (minimum 3 corners)',
      pass: pts.length >= 3,
    },
    {
      key: 'coordinates',
      label: 'All boundary coordinates tabulated in schedule',
      pass: pts.length >= 3,
    },
    {
      key: 'area',
      label: 'Parcel area is inscribed on the plan',
      pass: (p.area_sqm || 0) > 0,
    },
    {
      key: 'north',
      label: 'North point / arrow is shown',
      pass: true,
    },
    {
      key: 'scale',
      label: 'Scale bar and numeric scale are shown',
      pass: true,
    },
    {
      key: 'boundary',
      label: 'Boundary lengths and bearings are labeled',
      pass: (p.bearingSchedule?.length || 0) >= 3,
    },
    {
      key: 'adjacent',
      label: 'Adjacent lot references are noted',
      pass: !!(p.reference || p.plan_title),
    },
    {
      key: 'surveyor',
      label: 'Surveyor name and LSK licence number are shown',
      pass: !!(p.surveyor_name && p.surveyor_licence),
    },
    {
      key: 'authentication',
      label: 'Authentication space is reserved on the plan',
      pass: true,
    },
    {
      key: 'drawing_no',
      label: 'Drawing number / plan reference is assigned',
      pass: !!p.drawing_no,
    },
    {
      key: 'datum',
      label: 'Datum set to ARC1960 (required for KeNHA submissions per RDM 1.1 §5.2)',
      pass: p.datum === 'ARC1960' || !p.datum,
    },
  ]

  const passed = items.filter((i) => i.pass).length
  const total = items.length
  const allPassed = passed === total

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/70" onClick={onClose} />
      <div className="relative bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-xl p-6 w-full max-w-lg max-h-[90vh] overflow-y-auto shadow-2xl">
        <div className="flex items-center justify-between mb-5">
          <div>
            <h2 className="text-lg font-bold text-[var(--text-primary)]">
              METARDU Compliance Checklist
            </h2>
            <p className="text-xs text-[var(--text-muted)] mt-0.5">
              RDM 1.1 — Boundary Identification Plan
            </p>
          </div>
          <button
            onClick={onClose}
            className="text-[var(--text-muted)] hover:text-[var(--text-primary)] text-xl leading-none"
          >
            ×
          </button>
        </div>

        {/* Progress bar */}
        <div className="mb-4">
          <div className="flex items-center justify-between text-xs mb-1.5">
            <span className="text-[var(--text-secondary)]">
              {passed}/{total} items compliant
            </span>
            <span className={`font-semibold ${allPassed ? 'text-green-400' : 'text-amber-400'}`}>
              {allPassed ? 'READY TO EXPORT' : 'ACTION REQUIRED'}
            </span>
          </div>
          <div className="h-2 bg-[var(--bg-tertiary)] rounded-full overflow-hidden">
            <div
              className={`h-full transition-all duration-300 ${allPassed ? 'bg-green-500' : 'bg-amber-500'}`}
              style={{ width: `${(passed / total) * 100}%` }}
            />
          </div>
        </div>

        {/* Checklist items */}
        <div className="space-y-2 mb-6">
          {items.map((item) => (
            <div
              key={item.key}
              className={`flex items-start gap-3 px-3 py-2.5 rounded-lg border transition-colors ${
                item.pass
                  ? 'border-green-800/40 bg-green-900/10'
                  : 'border-amber-800/40 bg-amber-900/10'
              }`}
            >
              <div className={`mt-0.5 w-5 h-5 rounded-full flex items-center justify-center flex-shrink-0 ${
                item.pass
                  ? 'bg-green-900/50 border border-green-600'
                  : 'bg-amber-900/50 border border-amber-600'
              }`}>
                {item.pass ? (
                  <svg className="w-3 h-3 text-green-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />
                  </svg>
                ) : (
                  <svg className="w-3 h-3 text-amber-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3m0 3h.01M12 3a9 9 0 100 18A9 9 0 0012 3z" />
                  </svg>
                )}
              </div>
              <span className={`text-sm flex-1 ${
                item.pass ? 'text-green-300' : 'text-amber-300'
              }`}>
                {item.label}
              </span>
            </div>
          ))}
        </div>

        {/* Warning for non-compliant items */}
        {!allPassed && (
          <div className="mb-4 p-3 bg-amber-900/20 border border-amber-700/30 rounded-lg">
            <p className="text-xs text-amber-300">
              <strong>Note:</strong> The plan can still be exported, but may not meet KeNHA submission requirements. Address the flagged items above before formal submission.
            </p>
          </div>
        )}

        {/* Actions */}
        <div className="flex gap-3">
          <button
            onClick={onClose}
            className="flex-1 px-4 py-2.5 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded-lg text-sm font-medium transition-colors"
          >
            Cancel
          </button>
          <button
            onClick={() => {
              onExport()
              onClose()
            }}
            disabled={false}
            className="flex-1 px-4 py-2.5 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded-lg text-sm transition-colors disabled:opacity-50"
          >
            {allPassed ? 'Export Plan' : 'Export Anyway'}
          </button>
        </div>
      </div>
    </div>
  )
}

'use client';

import { useState } from 'react';
import { Save, CheckCircle, TrendingUp, Layers, Target } from 'lucide-react';
import { logger } from '@/lib/logger'

interface AsBuiltPoint {
  id: string;
  name: string;
  designE: number;
  designN: number;
  designZ: number;
  asbuiltE: number;
  asbuiltN: number;
  asbuiltZ: number;
}

interface SettingOutPoint {
  id: string;
  name: string;
  stationE: number;
  stationN: number;
  stationZ: number;
  offsetE: number;
  offsetN: number;
  designE: number;
  designN: number;
  designZ: number;
}

const DEMO_ASBUILT: AsBuiltPoint[] = [
  { id: '1', name: 'FND-01', designE: 500100.000, designN: 9980100.000, designZ: 1250.000, asbuiltE: 500100.008, asbuiltN: 9980100.005, asbuiltZ: 1249.992 },
  { id: '2', name: 'FND-02', designE: 500110.000, designN: 9980100.000, designZ: 1250.000, asbuiltE: 500109.995, asbuiltN: 9980100.012, asbuiltZ: 1250.008 },
  { id: '3', name: 'FND-03', designE: 500110.000, designN: 9980110.000, designZ: 1250.000, asbuiltE: 500110.003, asbuiltN: 9980109.998, asbuiltZ: 1249.995 },
  { id: '4', name: 'FND-04', designE: 500100.000, designN: 9980110.000, designZ: 1250.000, asbuiltE: 500100.010, asbuiltN: 9980110.008, asbuiltZ: 1250.015 },
];

const DEMO_SETTINGOUT: SettingOutPoint[] = [
  { id: '1', name: 'S1', stationE: 500050.000, stationN: 9980050.000, stationZ: 1252.000, offsetE: 500100.000, offsetN: 9980100.000, designE: 500100.000, designN: 9980100.000, designZ: 1250.000 },
  { id: '2', name: 'S2', stationE: 500050.000, stationN: 9980050.000, stationZ: 1252.000, offsetE: 500110.000, offsetN: 9980100.000, designE: 500110.000, designN: 9980100.000, designZ: 1250.000 },
];

export default function ConstructionComputePanel({ projectId }: { projectId: string }) {
  const [activeTab, setActiveTab] = useState<'asbuilt' | 'settingout'>('asbuilt');
  const [asbuilt, setAsbuilt] = useState<AsBuiltPoint[]>(DEMO_ASBUILT);
  const [settingOut, setSettingOut] = useState<SettingOutPoint[]>(DEMO_SETTINGOUT);
  const [toleranceH, setToleranceH] = useState(0.020);
  const [toleranceV, setToleranceV] = useState(0.010);
  const [saved, setSaved] = useState(false);

  // As-built results
  const asbuiltResults = asbuilt.map(p => {
    const dE = p.asbuiltE - p.designE;
    const dN = p.asbuiltN - p.designN;
    const dZ = p.asbuiltZ - p.designZ;
    const horiz = Math.sqrt(dE * dE + dN * dN);
    const total3D = Math.sqrt(dE * dE + dN * dN + dZ * dZ);
    const hPass = horiz <= toleranceH;
    const vPass = Math.abs(dZ) <= toleranceV;
    return { ...p, dE, dN, dZ, horiz, total3D, hPass, vPass, pass: hPass && vPass };
  });

  const failCount = asbuiltResults.filter(r => !r.pass).length;

  // Setting-out results
  const settingOutResults = settingOut.map(p => {
    const dE = p.offsetE - p.stationE;
    const dN = p.offsetN - p.stationN;
    const distance = Math.sqrt(dE * dE + dN * dN);
    const bearing = (Math.atan2(dE, dN) * 180) / Math.PI;
    const bearingNorm = bearing < 0 ? bearing + 360 : bearing;
    const dZ = p.designZ - p.stationZ;
    return { ...p, distance, bearing: bearingNorm, dZ, horizDist: distance };
  });

  const updateAsbuilt = (id: string, field: keyof AsBuiltPoint, value: number) => {
    setAsbuilt(prev => prev.map(p => p.id === id ? { ...p, [field]: value } : p));
  };

  const handleSave = async () => {
    try {
      await fetch(`/api/project/${projectId}/compute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'construction',
          results: activeTab === 'asbuilt'
            ? { asbuiltResults, failCount }
            : { settingOutResults },
        }),
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch (e) { logger.error(e instanceof Error ? e.message : String(e)); }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-semibold"><TrendingUp className="w-4 h-4 inline mr-1" />Construction Computations</h3>
        <div className="flex gap-2">
          {(['asbuilt', 'settingout'] as const).map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab)}
              className={`px-3 py-1 rounded text-xs font-medium ${activeTab === tab ? 'bg-amber-500/20 border border-amber-500 text-amber-400' : 'border border-zinc-700 text-zinc-400'}`}>
              {tab === 'asbuilt' ? <Layers className="w-3 h-3 inline mr-1" /> : <Target className="w-3 h-3 inline mr-1" />}
              {tab === 'asbuilt' ? 'As-Built Check' : 'Setting-Out'}
            </button>
          ))}
        </div>
      </div>

      {activeTab === 'asbuilt' && (
        <>
          <div className="flex gap-4 text-xs">
            <div><label className="text-zinc-500" htmlFor="h-tol">H Tol:</label> <input id="h-tol" aria-label="H Tol:" type="number" step="0.001" value={toleranceH} onChange={e => setToleranceH(Number(e.target.value))} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" />m</div>
            <div><label className="text-zinc-500" htmlFor="v-tol">V Tol:</label> <input id="v-tol" aria-label="V Tol:" type="number" step="0.001" value={toleranceV} onChange={e => setToleranceV(Number(e.target.value))} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" />m</div>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
            <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
              <div className="text-xs text-zinc-500">Points</div>
              <div className="text-sm font-bold text-white">{asbuilt.length}</div>
            </div>
            <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
              <div className="text-xs text-zinc-500">Max Offset</div>
              <div className="text-sm font-bold text-red-400">{Math.max(...asbuiltResults.map(r => r.horiz)).toFixed(4)} m</div>
            </div>
            <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
              <div className="text-xs text-zinc-500">Max ΔZ</div>
              <div className="text-sm font-bold text-blue-400">{Math.max(...asbuiltResults.map(r => Math.abs(r.dZ))).toFixed(4)} m</div>
            </div>
            <div className={`p-2 rounded border text-center ${failCount === 0 ? 'bg-green-500/10 border-green-500/30' : 'bg-red-500/10 border-red-500/30'}`}>
              <div className="text-xs text-zinc-500">Failures</div>
              <div className={`text-sm font-bold ${failCount === 0 ? 'text-green-400' : 'text-red-400'}`}>{failCount}</div>
            </div>
          </div>

          <div className="bg-zinc-900 rounded border border-zinc-700 overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-zinc-700 bg-zinc-800/50">
                  <th className="px-2 py-1.5 text-left text-zinc-400">Name</th>
                  <th className="px-2 py-1.5 text-left text-zinc-400">dE</th>
                  <th className="px-2 py-1.5 text-left text-zinc-400">dN</th>
                  <th className="px-2 py-1.5 text-left text-zinc-400">dZ</th>
                  <th className="px-2 py-1.5 text-left text-zinc-400">Horiz</th>
                  <th className="px-2 py-1.5 text-left text-zinc-400">H</th>
                  <th className="px-2 py-1.5 text-left text-zinc-400">V</th>
                  <th className="px-2 py-1.5 text-left text-zinc-400">Status</th>
                </tr>
              </thead>
              <tbody>
                {asbuiltResults.map(r => (
                  <tr key={r.id} className={`border-b border-zinc-800 ${!r.pass ? 'bg-red-500/5' : ''}`}>
                    <td className="px-2 py-1 font-mono font-semibold">{r.name}</td>
                    <td className="px-2 py-1 font-mono">{r.dE >= 0 ? '+' : ''}{r.dE.toFixed(4)}</td>
                    <td className="px-2 py-1 font-mono">{r.dN >= 0 ? '+' : ''}{r.dN.toFixed(4)}</td>
                    <td className="px-2 py-1 font-mono">{r.dZ >= 0 ? '+' : ''}{r.dZ.toFixed(4)}</td>
                    <td className="px-2 py-1 font-mono font-semibold">{r.horiz.toFixed(4)}</td>
                    <td className="px-2 py-1">{r.hPass ? <span className="text-green-400">OK</span> : <span className="text-red-400">FAIL</span>}</td>
                    <td className="px-2 py-1">{r.vPass ? <span className="text-green-400">OK</span> : <span className="text-red-400">FAIL</span>}</td>
                    <td className="px-2 py-1">{r.pass ? <span className="text-green-400 font-semibold">PASS</span> : <span className="text-red-400 font-semibold">FAIL</span>}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}

      {activeTab === 'settingout' && (
        <div className="bg-zinc-900 rounded border border-zinc-700 overflow-x-auto">
          <table className="w-full text-xs">
            <thead>
              <tr className="border-b border-zinc-700 bg-zinc-800/50">
                <th className="px-2 py-1.5 text-left text-zinc-400">Point</th>
                <th className="px-2 py-1.5 text-left text-zinc-400">Distance</th>
                <th className="px-2 py-1.5 text-left text-zinc-400">Bearing</th>
                <th className="px-2 py-1.5 text-left text-zinc-400">ΔZ</th>
                <th className="px-2 py-1.5 text-left text-zinc-400">Vertical Angle</th>
              </tr>
            </thead>
            <tbody>
              {settingOutResults.map(r => {
                const vAngle = (Math.atan2(r.dZ, r.distance) * 180) / Math.PI;
                return (
                  <tr key={r.id} className="border-b border-zinc-800">
                    <td className="px-2 py-1 font-mono font-semibold">{r.name}</td>
