'use client';

import { useState, useMemo } from 'react';
import { Plane, Save, CheckCircle, BarChart3 } from 'lucide-react';
import { logger } from '@/lib/logger'

interface GCPResult {
  name: string;
  dE: number;
  dN: number;
  dZ: number;
  horizontal: number;
  total3D: number;
}

interface GCPInput {
  id: string;
  name: string;
  knownE: number;
  knownN: number;
  knownZ: number;
  measE: number;
  measN: number;
  measZ: number;
}

const DEMO_GCPS: GCPInput[] = [
  { id: '1', name: 'GCP-01', knownE: 500000.123, knownN: 9980000.456, knownZ: 1520.10, measE: 500000.138, measN: 9980000.441, measZ: 1520.15 },
  { id: '2', name: 'GCP-02', knownE: 500010.789, knownN: 9980010.012, knownZ: 1518.35, measE: 500010.775, measN: 9980010.028, measZ: 1518.32 },
  { id: '3', name: 'GCP-03', knownE: 500025.456, knownN: 9979995.678, knownZ: 1522.80, measE: 500025.470, measN: 9979995.663, measZ: 1522.85 },
];

export default function DroneComputePanel({ projectId }: { projectId: string }) {
  const [gcps, setGcps] = useState<GCPInput[]>(DEMO_GCPS);
  const [gridPoints, setGridPoints] = useState('0,0,1.2\n5,0,1.5\n10,0,1.3\n0,5,1.4\n5,5,1.8\n10,5,1.6');
  const [refPlane, setRefPlane] = useState(1.0);
  const [saved, setSaved] = useState(false);

  const residuals = useMemo(() => gcps.map(g => {
    const dE = g.measE - g.knownE;
    const dN = g.measN - g.knownN;
    const dZ = g.measZ - g.knownZ;
    const horiz = Math.sqrt(dE * dE + dN * dN);
    const total3D = Math.sqrt(dE * dE + dN * dN + dZ * dZ);
    return { name: g.name, dE, dN, dZ, horizontal: horiz, total3D };
  }), [gcps]);

  const n = residuals.length || 1;
  const hRMSE = Math.sqrt(residuals.reduce((s, r) => s + r.horizontal ** 2, 0) / n);
  const vRMSE = Math.sqrt(residuals.reduce((s, r) => s + r.dZ ** 2, 0) / n);
  const totalRMSE = Math.sqrt(residuals.reduce((s, r) => s + r.total3D ** 2, 0) / n);

  // Volume
  const volume = useMemo(() => {
    const lines = gridPoints.trim().split('\n').filter(l => l.trim());
    const pts = lines.map(l => l.split(',').map(Number)).filter(p => !p.some(isNaN));
    if (pts.length < 4) return null;
    const uniqueX = Array.from(new Set(pts.map(p => p[0]))).sort((a, b) => a - b);
    const uniqueY = Array.from(new Set(pts.map(p => p[1]))).sort((a, b) => a - b);
    const grid = new Map(pts.map(p => [`${p[0]},${p[1]}`, p]));
    let vol = 0;
    for (let i = 0; i < uniqueX.length - 1; i++) {
      for (let j = 0; j < uniqueY.length - 1; j++) {
        const c = [grid.get(`${uniqueX[i]},${uniqueY[j]}`), grid.get(`${uniqueX[i+1]},${uniqueY[j]}`), grid.get(`${uniqueX[i+1]},${uniqueY[j+1]}`), grid.get(`${uniqueX[i]},${uniqueY[j+1]}`)];
        if (c.every(Boolean)) {
          const cellArea = Math.abs(uniqueX[i+1] - uniqueX[i]) * Math.abs(uniqueY[j+1] - uniqueY[j]);
          const avgH = c.reduce((s, p) => s + Math.max(p![2] - refPlane, 0), 0) / 4;
          vol += avgH * cellArea;
        }
      }
    }
    return vol;
  }, [gridPoints, refPlane]);

  const handleSave = async () => {
    try {
      await fetch(`/api/project/${projectId}/compute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'drone', results: { residuals, hRMSE, vRMSE, totalRMSE, volume } }),
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch (e) { logger.error(e instanceof Error ? e.message : String(e)); }
  };

  return (
    <div className="space-y-4">
      <h3 className="text-sm font-semibold"><Plane className="w-4 h-4 inline mr-1" />Drone Survey QA</h3>

      {/* RMSE Stats */}
      <div className="grid grid-cols-3 gap-2">
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">H RMSE</div>
          <div className="text-sm font-bold text-amber-400">{hRMSE.toFixed(4)} m</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">V RMSE</div>
          <div className="text-sm font-bold text-blue-400">{vRMSE.toFixed(4)} m</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">3D RMSE</div>
          <div className="text-sm font-bold text-white">{totalRMSE.toFixed(4)} m</div>
        </div>
      </div>

      {/* GCP Table */}
      <div className="bg-zinc-900 rounded border border-zinc-700 overflow-x-auto">
        <table className="w-full text-xs">
          <thead>
            <tr className="border-b border-zinc-700 bg-zinc-800/50">
              <th className="px-2 py-1.5 text-left text-zinc-400">Name</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">dE</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">dN</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">dZ</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">H</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">3D</th>
            </tr>
          </thead>
          <tbody>
            {residuals.map((r, i) => (
              <tr key={r.name} className="border-b border-zinc-800">
                <td className="px-2 py-1 font-mono">{r.name}</td>
                <td className="px-2 py-1 font-mono">{r.dE >= 0 ? '+' : ''}{r.dE.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{r.dN >= 0 ? '+' : ''}{r.dN.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{r.dZ >= 0 ? '+' : ''}{r.dZ.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{r.horizontal.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono font-semibold text-amber-400">{r.total3D.toFixed(4)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Volume Section */}
      <div className="grid grid-cols-2 gap-3">
        <div className="space-y-2">
          <label className="block text-xs text-zinc-500" htmlFor="grid-points-x-y-z-one-per-line">Grid Points (X,Y,Z) — one per line</label>
          <textarea  id="grid-points-x-y-z-one-per-line" value={gridPoints} onChange={e => setGridPoints(e.target.value)} rows={5} className="w-full bg-zinc-800 border border-zinc-700 rounded px-2 py-1 text-white text-xs font-mono" />
          <div className="flex gap-2 text-xs">
            <span className="text-zinc-500">Ref Plane:</span>
            <input aria-label="Grid Points (X,Y,Z) — one per line" type="number" step="0.1" value={refPlane} onChange={e => setRefPlane(Number(e.target.value))} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" />
          </div>
        </div>
        <div className="p-3 bg-zinc-900 rounded border border-zinc-700 h-fit">
          <h4 className="text-xs font-semibold text-zinc-400 mb-2"><BarChart3 className="w-3 h-3 inline mr-1" />Volume Result</h4>
          <div className="text-lg font-bold text-amber-400">{volume !== null ? `${volume.toFixed(2)} m³` : 'Need 4+ points'}</div>
        </div>
      </div>

      <button onClick={handleSave} disabled={saved} className="inline-flex items-center gap-1 px-3 py-1 bg-[var(--accent)] text-black text-xs rounded hover:bg-[var(--accent-dim)] disabled:opacity-50">
        {saved ? <CheckCircle className="w-3 h-3" /> : <Save className="w-3 h-3" />}{saved ? 'Saved' : 'Save Results'}
      </button>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { Calculator, Loader2, Save, CheckCircle } from 'lucide-react';
import { logger } from '@/lib/logger'

interface FieldBookRow {
  fromStation: string;
  toStation: string;
  angle?: string;
  bearing?: number;
  distance?: number;
  bs?: number;
  is?: number;
  fs?: number;
}

interface LevelRow {
  id: number;
  fromStation: string;
  bs: number | null;
  is: number | null;
  fs: number | null;
  distance: number;
  rise?: number;
  fall?: number;
  rl?: number;
  adjustment?: number;
  adjRL?: number;
}

export default function LevellingComputePanel({ projectId }: { projectId: string }) {
  const [rows, setRows] = useState<LevelRow[]>([
    { id: 1, fromStation: 'TBM1', bs: 1.525, is: null, fs: null, distance: 0.050 },
    { id: 2, fromStation: 'CP1', bs: 2.310, is: 1.845, fs: null, distance: 0.030 },
    { id: 3, fromStation: 'CP1', bs: null, is: 1.925, fs: null, distance: 0.030 },
    { id: 4, fromStation: 'A', bs: null, is: null, fs: 0.655, distance: 0.040 },
    { id: 5, fromStation: 'A', bs: 1.780, is: null, fs: null, distance: 0.030 },
    { id: 6, fromStation: 'B', bs: null, is: 2.150, fs: null, distance: 0.035 },
    { id: 7, fromStation: 'TBM1', bs: null, is: null, fs: 3.420, distance: 0.045 },
  ]);
  const [tbmRL, setTbmRL] = useState<number>(150.000);
  const [saved, setSaved] = useState(false);

  const compute = useCallback(() => {
    let cumulativeRL = tbmRL;
    return rows.map((row, i) => {
      const rise = row.bs !== null && i > 0 ? null : null; // computed differently
      let rise2 = 0, fall2 = 0;

      if (row.bs !== null) {
        // BS reading: rise from previous to this
        const prevFS = rows[i - 1]?.fs;
        if (prevFS !== null && prevFS !== undefined) {
          if (row.bs > prevFS) rise2 = row.bs - prevFS;
          else fall2 = prevFS - row.bs;
        }
      }
      if (row.fs !== null && row.bs === null) {
        // FS reading on same station or IS→FS transition
        const prevBS = rows[i - 1]?.bs;
        const prevIS = rows[i - 1]?.is;
        if (prevIS !== null && prevIS !== undefined) {
          if (prevIS > row.fs) rise2 = prevIS - row.fs;
          else fall2 = row.fs - prevIS;
        }
      }
      if (row.is !== null && row.bs === null && row.fs === null) {
        const prev = rows[i - 1];
        const prevVal = prev?.is || prev?.bs;
        if (prevVal !== null && prevVal !== undefined) {
          if (prevVal > row.is) rise2 = prevVal - row.is;
          else fall2 = row.is - prevVal;
        }
      }

      const rl = cumulativeRL + rise2 - fall2;
      cumulativeRL = rl;

      return { ...row, rise: rise2 || 0, fall: fall2 || 0, rl };
    });
  }, [rows, tbmRL]);

  const computedRows = compute();
  const lastRow = computedRows[computedRows.length - 1];
  const misclosure = lastRow ? (lastRow.rl || 0) - tbmRL : 0;
  const totalDistance = rows.reduce((s, r) => s + r.distance, 0);
  const allowableMisclosure = 10 * Math.sqrt(totalDistance * 1000) / 1000; // 10√K mm → m
  const passesCheck = Math.abs(misclosure) <= allowableMisclosure;

  // Distribute adjustment proportionally
  const adjustedRows = computedRows.map((row, i) => {
    const proportion = totalDistance > 0 ? (row.distance / totalDistance) : 0;
    const adjustment = -misclosure * proportion;
    return { ...row, adjustment, adjRL: (row.rl || 0) + adjustment };
  });

  const updateRow = (id: number, field: keyof LevelRow, value: number | null) => {
    setRows(prev => prev.map(r => r.id === id ? { ...r, [field]: value } : r));
  };

  const addRow = () => {
    setRows(prev => [...prev, { id: prev.length + 1, fromStation: `P${prev.length + 1}`, bs: null, is: null, fs: null, distance: 0.030 }]);
  };

  const handleSave = async () => {
    try {
      await fetch(`/api/project/${projectId}/compute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'levelling',
          results: { rows: adjustedRows, misclosure, allowableMisclosure, passesCheck, tbmRL },
        }),
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch (e) { logger.error(e instanceof Error ? e.message : String(e)); }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between mb-2">
        <h3 className="text-sm font-semibold"><Calculator className="w-4 h-4 inline mr-1" />Rise & Fall Levelling</h3>
        <div className="flex gap-2">
          <div className="text-xs">
            <label className="text-zinc-500 mr-1" htmlFor="tbm-rl">TBM RL:</label>
            <input  id="tbm-rl" aria-label="TBM RL:" type="number" step="0.001" value={tbmRL} onChange={e => setTbmRL(Number(e.target.value))} className="w-24 bg-zinc-800 border border-zinc-700 rounded px-2 py-0.5 text-white text-xs" />
          </div>
          <button onClick={addRow} className="px-2 py-0.5 text-xs bg-zinc-800 border border-zinc-700 rounded text-zinc-400 hover:text-white">+ Row</button>
        </div>
      </div>

      <div className="bg-zinc-900 rounded border border-zinc-700 overflow-x-auto">
        <table className="w-full text-xs">
          <thead>
            <tr className="border-b border-zinc-700 bg-zinc-800/50">
              <th className="px-2 py-1.5 text-left text-zinc-400">Station</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">BS</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">IS</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">FS</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Rise</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Fall</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">RL</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Dist (km)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Adj</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Adj RL</th>
            </tr>
          </thead>
          <tbody>
            {adjustedRows.map(r => (
              <tr key={r.id} className="border-b border-zinc-800">
                <td className="px-2 py-1 font-mono text-zinc-300">{r.fromStation}</td>
                <td className="px-2 py-1"><input aria-label="Bs" type="number" step="0.001" value={r.bs ?? ''} onChange={e => updateRow(r.id, 'bs', e.target.value ? Number(e.target.value) : null)} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" /></td>
                <td className="px-2 py-1"><input aria-label="Is" type="number" step="0.001" value={r.is ?? ''} onChange={e => updateRow(r.id, 'is', e.target.value ? Number(e.target.value) : null)} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" /></td>
                <td className="px-2 py-1"><input aria-label="Fs" type="number" step="0.001" value={r.fs ?? ''} onChange={e => updateRow(r.id, 'fs', e.target.value ? Number(e.target.value) : null)} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" /></td>
                <td className="px-2 py-1 font-mono">{r.rise ? r.rise.toFixed(3) : ''}</td>
                <td className="px-2 py-1 font-mono">{r.fall ? r.fall.toFixed(3) : ''}</td>
                <td className="px-2 py-1 font-mono text-white">{(r.rl ?? 0).toFixed(3)}</td>
                <td className="px-2 py-1"><input aria-label="Distance" type="number" step="0.001" value={r.distance} onChange={e => updateRow(r.id, 'distance', Number(e.target.value))} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" /></td>
                <td className="px-2 py-1 font-mono text-blue-400">{(r.adjustment ?? 0).toFixed(4)}</td>
                <td className="px-2 py-1 font-mono font-semibold text-amber-400">{(r.adjRL ?? 0).toFixed(3)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Summary */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <div className={`p-3 rounded-lg border ${passesCheck ? 'bg-green-500/10 border-green-500/30' : 'bg-red-500/10 border-red-500/30'}`}>
          <div className="text-xs text-zinc-500">Misclosure</div>
          <div className={`text-sm font-bold ${passesCheck ? 'text-green-400' : 'text-red-400'}`}>{misclosure >= 0 ? '+' : ''}{misclosure.toFixed(4)} m</div>
        </div>
        <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700">
          <div className="text-xs text-zinc-500">Allowable (10√K)</div>
          <div className="text-sm font-bold text-white">{allowableMisclosure.toFixed(4)} m</div>
        </div>
        <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700">
          <div className="text-xs text-zinc-500">Total Distance</div>
          <div className="text-sm font-bold text-white">{(totalDistance * 1000).toFixed(0)} m</div>
        </div>
        <div className={`p-3 rounded-lg border ${passesCheck ? 'bg-green-500/10 border-green-500/30' : 'bg-red-500/10 border-red-500/30'}`}>
          <div className="text-xs text-zinc-500">Result</div>
          <div className={`text-sm font-bold ${passesCheck ? 'text-green-400' : 'text-red-400'}`}>{passesCheck ? 'PASS' : 'FAIL'}</div>
        </div>
      </div>

      <button onClick={handleSave} disabled={saved}
        className="inline-flex items-center gap-1 px-3 py-1.5 bg-[var(--accent)] text-black text-xs rounded hover:bg-[var(--accent-dim)] disabled:opacity-50">
        {saved ? <CheckCircle className="w-3 h-3" /> : <Save className="w-3 h-3" />}
        {saved ? 'Saved' : 'Save Results'}
      </button>
    </div>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { BarChart3, AlertTriangle, Save, CheckCircle } from 'lucide-react';
import { logger } from '@/lib/logger'

interface EpochPoint {
  name: string;
  easting: number;
  northing: number;
  elevation: number;
}

interface EpochData {
  epochName: string;
  date: string;
  points: EpochPoint[];
}

interface Displacement {
  name: string;
  dE: number;
  dN: number;
  dZ: number;
  horizontal: number;
  total3D: number;
  bearing: number;
  exceedsThreshold: boolean;
}

function computeDisplacements(epoch1: EpochPoint[], epoch2: EpochPoint[]): Displacement[] {
  const map2 = new Map(epoch2.map(p => [p.name, p]));
  return epoch1.map(p1 => {
    const p2 = map2.get(p1.name);
    if (!p2) return null;
    const dE = p2.easting - p1.easting;
    const dN = p2.northing - p1.northing;
    const dZ = p2.elevation - p1.elevation;
    const horizontal = Math.sqrt(dE * dE + dN * dN);
    const total3D = Math.sqrt(dE * dE + dN * dN + dZ * dZ);
    const bearing = (Math.atan2(dE, dN) * 180) / Math.PI;
    const bearingNorm = bearing < 0 ? bearing + 360 : bearing;
    return { name: p1.name, dE, dN, dZ, horizontal, total3D, bearing: bearingNorm, exceedsThreshold: false };
  }).filter(Boolean) as Displacement[];
}

const DEMO_EPOCH1: EpochPoint[] = [
  { name: 'P1', easting: 500000.000, northing: 9980000.000, elevation: 1520.000 },
  { name: 'P2', easting: 500010.000, northing: 9980010.000, elevation: 1518.500 },
  { name: 'P3', easting: 500025.000, northing: 9979995.000, elevation: 1522.800 },
  { name: 'P4', easting: 500015.000, northing: 9979985.000, elevation: 1515.900 },
  { name: 'P5', easting: 500035.000, northing: 9980005.000, elevation: 1519.550 },
];

const DEMO_EPOCH2: EpochPoint[] = [
  { name: 'P1', easting: 500000.005, northing: 9980000.003, elevation: 1520.008 },
  { name: 'P2', easting: 500010.012, northing: 9980009.995, elevation: 1518.502 },
  { name: 'P3', easting: 500024.995, northing: 9979995.010, elevation: 1522.805 },
  { name: 'P4', easting: 500015.008, northing: 9979985.002, elevation: 1515.895 },
  { name: 'P5', easting: 500035.003, northing: 9980005.006, elevation: 1519.558 },
];

export default function MonitoringComputePanel({ projectId }: { projectId: string }) {
  const [epochs, setEpochs] = useState<EpochData[]>([
    { epochName: 'Epoch 1', date: '2025-01-15', points: DEMO_EPOCH1 },
    { epochName: 'Epoch 2', date: '2025-06-15', points: DEMO_EPOCH2 },
  ]);
  const [compareIndex1, setCompareIndex1] = useState(0);
  const [compareIndex2, setCompareIndex2] = useState(1);
  const [threshold, setThreshold] = useState(0.010);
  const [saved, setSaved] = useState(false);

  const displacements = useMemo(() => {
    if (compareIndex1 === compareIndex2 || !epochs[compareIndex1] || !epochs[compareIndex2]) return [];
    const ds = computeDisplacements(epochs[compareIndex1].points, epochs[compareIndex2].points);
    return ds.map(d => ({ ...d, exceedsThreshold: d.total3D > threshold }));
  }, [epochs, compareIndex1, compareIndex2, threshold]);

  const alertCount = displacements.filter(d => d.exceedsThreshold).length;

  const maxDisp = displacements.length > 0 ? Math.max(...displacements.map(d => d.total3D)) : 0;
  const avgDisp = displacements.length > 0 ? displacements.reduce((s, d) => s + d.total3D, 0) / displacements.length : 0;
  const rmsH = Math.sqrt(displacements.reduce((s, d) => s + d.horizontal ** 2, 0) / (displacements.length || 1));
  const rmsV = Math.sqrt(displacements.reduce((s, d) => s + d.dZ ** 2, 0) / (displacements.length || 1));

  const handleSave = async () => {
    try {
      await fetch(`/api/project/${projectId}/compute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'monitoring', results: { displacements, rmsH, rmsV, maxDisp, avgDisp, alertCount } }),
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch (e) { logger.error(e instanceof Error ? e.message : String(e)); }
  };

  return (
    <div className="space-y-4">
      <h3 className="text-sm font-semibold"><BarChart3 className="w-4 h-4 inline mr-1" />Multi-Epoch Displacement Monitoring</h3>

      {/* Controls */}
      <div className="flex gap-4 items-end flex-wrap">
        <div>
          <label className="block text-xs text-zinc-500 mb-1" htmlFor="base-epoch">Base Epoch</label>
          <select id="base-epoch" value={compareIndex1} onChange={e => setCompareIndex1(Number(e.target.value))} className="bg-zinc-800 border border-zinc-700 rounded px-2 py-1 text-white text-xs">
            {epochs.map((ep, i) => <option key={`${ep}-${i}`} value={i}>{ep.epochName} ({ep.date})</option>)}
          </select>
        </div>
        <div>
          <label className="block text-xs text-zinc-500 mb-1" htmlFor="latest-epoch">Latest Epoch</label>
          <select id="latest-epoch" value={compareIndex2} onChange={e => setCompareIndex2(Number(e.target.value))} className="bg-zinc-800 border border-zinc-700 rounded px-2 py-1 text-white text-xs">
            {epochs.map((ep, i) => <option key={`${ep}-${i}`} value={i}>{ep.epochName} ({ep.date})</option>)}
          </select>
        </div>
        <div>
          <label className="block text-xs text-zinc-500 mb-1" htmlFor="alert-threshold-m">Alert Threshold (m)</label>
          <input aria-label="Alert Threshold (m)" type="number" step="0.001" value={threshold} onChange={e => setThreshold(Number(e.target.value))} className="w-24 bg-zinc-800 border border-zinc-700 rounded px-2 py-1 text-white text-xs" />
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">Points</div>
          <div className="text-sm font-bold text-white">{displacements.length}</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">Max 3D</div>
          <div className="text-sm font-bold text-red-400">{maxDisp.toFixed(4)} m</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">Avg 3D</div>
          <div className="text-sm font-bold text-amber-400">{avgDisp.toFixed(4)} m</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">RMS H</div>
          <div className="text-sm font-bold text-blue-400">{rmsH.toFixed(4)} m</div>
        </div>
        <div className={`p-2 rounded border text-center ${alertCount > 0 ? 'bg-red-500/10 border-red-500/30' : 'bg-green-500/10 border-green-500/30'}`}>
          <div className="text-xs text-zinc-500">Alerts</div>
          <div className={`text-sm font-bold ${alertCount > 0 ? 'text-red-400' : 'text-green-400'}`}>{alertCount}</div>
        </div>
      </div>

      {/* Displacement Table */}
      <div className="bg-zinc-900 rounded border border-zinc-700 overflow-x-auto">
        <table className="w-full text-xs">
          <thead>
            <tr className="border-b border-zinc-700 bg-zinc-800/50">
              <th className="px-2 py-1.5 text-left text-zinc-400">Point</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">dE (m)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">dN (m)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">dZ (m)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Horiz (m)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">3D (m)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Bearing</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Status</th>
            </tr>
          </thead>
          <tbody>
            {displacements.map(d => (
              <tr key={d.name} className={`border-b border-zinc-800 ${d.exceedsThreshold ? 'bg-red-500/5' : ''}`}>
                <td className="px-2 py-1 font-mono font-semibold">{d.name}</td>
                <td className="px-2 py-1 font-mono">{d.dE >= 0 ? '+' : ''}{d.dE.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{d.dN >= 0 ? '+' : ''}{d.dN.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{d.dZ >= 0 ? '+' : ''}{d.dZ.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{d.horizontal.toFixed(4)}</td>
                <td className={`px-2 py-1 font-mono font-semibold ${d.exceedsThreshold ? 'text-red-400' : 'text-white'}`}>{d.total3D.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{d.bearing.toFixed(1)}°</td>
                <td className="px-2 py-1">
                  {d.exceedsThreshold ? (
                    <span className="flex items-center gap-1 text-red-400"><AlertTriangle className="w-3 h-3" />ALERT</span>
                  ) : (
                    <span className="text-green-400">OK</span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <button onClick={handleSave} disabled={saved}
        className="inline-flex items-center gap-1 px-3 py-1.5 bg-[var(--accent)] text-black text-xs rounded hover:bg-[var(--accent-dim)] disabled:opacity-50">
        {saved ? <CheckCircle className="w-3 h-3" /> : <Save className="w-3 h-3" />}
        {saved ? 'Saved' : 'Save Results'}
      </button>
    </div>
  );
}

'use client';

import { useState, useCallback } from 'react'
import { AlertTriangle, CheckCircle2, ShieldAlert, Zap, Compass, Folder, Lock } from 'lucide-react'
import { adjustNetwork, Station, Observation, AdjustmentResult } from '@/lib/survey/networkAdjustment'
import { adjustNetworkRobust, type RobustLSAResult, type WeightFunction } from '@/lib/survey/robustEstimation'
import { generateNetworkDXF } from '@/lib/survey/networkAdjustmentDXF'
import { ErrorEllipseCanvas } from './ErrorEllipseCanvas'
import { z } from 'zod'
import { apiGet, apiPost, ApiError } from '@/lib/api/client'

// ─── API response schemas (Zod) ────────────────────────────────────────────
const traverseImportResponseSchema = z.object({
  coordinates: z.array(z.object({}).passthrough()).optional(),
  legs: z.array(z.object({}).passthrough()).optional(),
}).passthrough()

const networkAdjustmentSaveResponseSchema = z.object({
  ok: z.boolean().optional(),
}).passthrough()

interface Props {
  projectId: string
  projectData: Record<string, unknown>
  surveyorProfile?: { fullName: string; registrationNumber: string; firmName: string } | null
}

const EMPTY_STATION: Omit<Station, 'id'> = {
  name: '', easting: 0, northing: 0, elevation: 0, isFixed: false,
}

const EMPTY_OBS: Omit<Observation, 'from' | 'to'> = {
  deltaE: 0, deltaN: 0, deltaH: 0, stdDevE: 0.005, stdDevN: 0.005, stdDevH: 0.010,
}

export function NetworkAdjustmentPanel({ projectId, projectData, surveyorProfile }: Props) {
  const [stations, setStations] = useState<Station[]>([])
  const [observations, setObservations] = useState<Observation[]>([])
  const [result, setResult] = useState<AdjustmentResult | null>(null)
  const [robustResult, setRobustResult] = useState<RobustLSAResult | null>(null)
  const [robustMode, setRobustMode] = useState(false)
  const [weightFunction, setWeightFunction] = useState<WeightFunction>('huber')
  const [error, setError] = useState<string | null>(null)
  const [saving, setSaving] = useState(false)
  const [importStatus, setImportStatus] = useState('')

  // ─── Import from Traverse ────────────────────────────────────────────────
  const handleImportFromTraverse = useCallback(async () => {
    try {
      setImportStatus('Loading traverse data...')
      const data = await apiGet(
        `/api/project/${projectId}/traverse`,
        traverseImportResponseSchema,
        { ttlMs: 0 },
      )
      const coords = (data.coordinates as unknown as Array<Record<string, unknown>>) || []
      const legs = (data.legs as unknown as Array<Record<string, unknown>>) || []

      if (coords.length < 2) {
        setImportStatus('')
        setError('Traverse has fewer than 2 stations.')
        return
      }

      // Convert traverse stations → LSQ stations
      const newStations: Station[] = coords.map((c, i: number) => ({
        id: `trv-${c.station}`,
        name: c.station as string,
        easting: c.easting as number,
        northing: c.northing as number,
        elevation: (c.rl as number) ?? 0,
        isFixed: i === 0 || i === coords.length - 1, // first and last are fixed
      }))

      // Convert traverse legs → LSQ observations
      const newObs: Observation[] = legs.map((leg) => {
        const fromStn = newStations.find((s: Station) => s.name === leg.from)
        const toStn = newStations.find((s: Station) => s.name === leg.to)
        if (!fromStn || !toStn) return null
        return {
          from: fromStn.id,
          to: toStn.id,
          deltaE: (leg.adjDep as number) ?? (leg.departure as number) ?? 0,
          deltaN: (leg.adjLat as number) ?? (leg.latitude as number) ?? 0,
          deltaH: 0,
          stdDevE: 0.005 + (leg.hd as number ?? 100) * 0.00001, stdDevN: 0.005 + (leg.hd as number ?? 100) * 0.00001, stdDevH: (0.005 + (leg.hd as number ?? 100) * 0.00001) * 2, // 5mm + 10ppm
        }
      }).filter(Boolean) as Observation[]

      setStations(newStations)
      setObservations(newObs)
      setResult(null)
      setError(null)
      setImportStatus(`Imported ${newStations.length} stations and ${newObs.length} observations from traverse.`)
      setTimeout(() => setImportStatus(''), 4000)
    } catch (err: unknown) {
      if (err instanceof ApiError) {
        // 404 / not-found → no traverse data yet; anything else → surface message
        setError(err.isNotFound
          ? 'No traverse data found for this project. Run a traverse computation first.'
          : err.message)
      } else {
        setError((err as Error).message ?? 'Failed to import traverse data.')
      }
      setImportStatus('')
    }
  }, [projectId])

  // ─── Import from GSI File ─────────────────────────────────────────────────
  const handleImportGSI = useCallback(async () => {
    const input = document.createElement('input')
    input.type = 'file'
    input.accept = '.gsi,.GSI'
    input.onchange = async (e) => {
      const file = (e.target as HTMLInputElement).files?.[0]
      if (!file) return
      try {
        setImportStatus('Parsing GSI file...')
        const content = await file.text()
        const { parseGSI, pairFaces } = await import('@/lib/import/totalStation/parseGSI')
        const parsed = parseGSI(content)

        if (!parsed.ok || parsed.records.length === 0) {
          setError('GSI file parsed but no valid records found.')
          setImportStatus('')
          return
        }

        // Extract coordinate records as stations
        const coordRecords = parsed.records.filter(r => r.easting !== undefined && r.northing !== undefined)
        const obsRecords = parsed.records.filter(r => r.horizontalAngle !== undefined || r.slopeDistance !== undefined)

        if (coordRecords.length >= 2) {
          const newStations: Station[] = coordRecords.map((r, i) => ({
            id: `gsi-${r.pointId}`,
            name: r.pointId,
            easting: r.easting!,
            northing: r.northing!,
            elevation: r.elevation ?? 0,
            isFixed: i === 0,
          }))
          setStations(newStations)

          // Create observations from consecutive coordinate pairs
          const newObs: Observation[] = []
          for (let i = 0; i < newStations.length - 1; i++) {
            newObs.push({
              from: newStations[i].id,
              to: newStations[i + 1].id,
              deltaE: newStations[i + 1].easting - newStations[i].easting,
              deltaN: newStations[i + 1].northing - newStations[i].northing,
              deltaH: newStations[i + 1].elevation - newStations[i].elevation,
              stdDevE: 0.005, stdDevN: 0.005, stdDevH: 0.010,
            })
          }
          setObservations(newObs)
        }

        setResult(null)
        setError(null)
        setImportStatus(
          `GSI ${parsed.format}: ${parsed.statistics.totalRecords} records, ` +
          `${parsed.statistics.coordinateRecords} coords, ` +
          `${parsed.statistics.faceLeftCount} FL / ${parsed.statistics.faceRightCount} FR`
        )
        setTimeout(() => setImportStatus(''), 6000)
      } catch (err: unknown) {
        setError((err as Error).message ?? 'Failed to parse GSI file.')
        setImportStatus('')
      }
    }
    input.click()
  }, [])

  const addStation = () => {
    setStations(prev => [...prev, {
      ...EMPTY_STATION,
      id: `stn-${Date.now()}`,
    }])
  }

  const updateStation = (id: string, field: keyof Station, value: string | number | boolean) => {
    setStations(prev => prev.map(s => s.id === id ? { ...s, [field]: value } : s))
  }

  const removeStation = (id: string) => {
    setStations(prev => prev.filter(s => s.id !== id))
    setObservations(prev => prev.filter(o => o.from !== id && o.to !== id))
  }

  const addObservation = () => {
    if (stations.length < 2) return
    setObservations(prev => [...prev, {
      ...EMPTY_OBS,
      from: stations[0].id,
      to: stations[1].id,
    }])
  }

  const updateObservation = (idx: number, field: keyof Observation, value: string | number) => {
    setObservations(prev => prev.map((o, i) => i === idx ? { ...o, [field]: value } : o))
  }

  const removeObservation = (idx: number) => {
    setObservations(prev => prev.filter((_, i) => i !== idx))
  }

  const handleCompute = () => {
    setError(null)
    setResult(null)
    setRobustResult(null)
    try {
      if (robustMode) {
        // Convert Station/Observation to the format expected by adjustNetworkRobust
        const robustStations = stations.map(s => ({
          id: s.id, name: s.name,
          easting: s.easting, northing: s.northing, elevation: s.elevation,
          isFixed: s.isFixed,
        }))
        const robustObs = observations.map(o => ({
          type: 'coordinate_diff' as const,
          from: o.from, to: o.to,
          deltaE: o.deltaE, deltaN: o.deltaN, deltaH: o.deltaH,
          stdDevE: o.stdDevE, stdDevN: o.stdDevN, stdDevH: o.stdDevH,
        }))
        const res = adjustNetworkRobust(robustStations, robustObs, {
          weightFunction,
          maxIterations: 30,
        })
        setRobustResult(res)
        // Also set the standard result (for the adjusted coordinates table + error ellipses)
        setResult({
          adjustedStations: res.adjustedStations,
          sigmaZero: res.sigmaZero,
          degreesOfFreedom: res.degreesOfFreedom,
          iterations: res.iterations,
          passedTolerance: res.blunders.length === 0,
          warnings: [...res.warnings, ...res.blunders.map(b =>
            `BLUNDER: ${b.from || '?'}→${b.to || '?'} (${b.type}) — residual=${b.residual.toFixed(4)}m, weight=${b.finalWeight.toFixed(3)}`,
          )],
        })
        saveResult({
          adjustedStations: res.adjustedStations,
          sigmaZero: res.sigmaZero,
          degreesOfFreedom: res.degreesOfFreedom,
          iterations: res.iterations,
          passedTolerance: res.blunders.length === 0,
          warnings: res.warnings,
        })
      } else {
        const res = adjustNetwork(stations, observations)
        setResult(res)
        saveResult(res)
      }
    } catch (err: unknown) {
      setError((err as Error).message ?? 'Adjustment failed.')
    }
  }

  const saveResult = async (res: AdjustmentResult) => {
    setSaving(true)
    try {
      await apiPost(
        `/api/project/${projectId}/network-adjustment`,
        networkAdjustmentSaveResponseSchema,
        {
          stations,
          observations,
          adjusted_stations: res.adjustedStations,
          summary: {
            iterations: res.iterations,
            sigma_zero: res.sigmaZero,
            dof: res.degreesOfFreedom,
            passed_tolerance: res.passedTolerance,
          },
          status: res.passedTolerance ? 'adjusted' : 'failed',
        },
      )
    } catch {
      // non-fatal
    } finally {
      setSaving(false)
    }
  }

  const handleExportDXF = async () => {
    if (!result) return
    const profile = surveyorProfile ?? { fullName: 'Unknown', registrationNumber: 'N/A', firmName: 'N/A' }
    const dxfString = generateNetworkDXF({
      adjustedStations: result.adjustedStations,
      observations,
      projectData,
      surveyorProfile: profile,
    })
    const blob = new Blob([dxfString], { type: 'application/dxf' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `network-adjustment-${projectId}.dxf`
    a.click()
    URL.revokeObjectURL(url)
  }

  return (
    <div className="space-y-8">
      <div>
        <h2 className="text-lg font-semibold text-white mb-1">GPS Network Adjustment</h2>
        <p className="text-sm text-zinc-400">
          Least squares adjustment of GPS/GNSS baselines. Arc 1960 / UTM Zone 37S.
          At least one fixed control station required.
        </p>
      </div>

      {importStatus && (
        <div className="bg-blue-900/30 border border-blue-700 text-blue-300 px-4 py-3 rounded-lg text-sm">
          {importStatus}
        </div>
      )}

      {/* Import Actions */}
      <div className="flex flex-wrap gap-2">
        <button
          onClick={handleImportFromTraverse}
          className="text-sm bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 font-medium flex items-center gap-1.5"
        >
          <Compass className="w-4 h-4" /> Import from Traverse
        </button>
        <button
          onClick={handleImportGSI}
          className="text-sm bg-purple-600 text-white px-4 py-2 rounded-lg hover:bg-purple-700 font-medium flex items-center gap-1.5"
        >
          <Folder className="w-4 h-4" /> Import GSI File
        </button>
      </div>

      <section>
        <div className="flex items-center justify-between mb-3">
          <h3 className="font-medium text-zinc-300">Control Stations</h3>
          <button
            onClick={addStation}
            className="text-sm bg-blue-600 text-white px-3 py-1.5 rounded hover:bg-blue-700"
          >
            + Add Station
          </button>
        </div>

        {stations.length === 0 && (
          <p className="text-sm text-zinc-500 italic">No stations added yet.</p>
        )}

        <div className="space-y-3">
          {stations.map(s => (
            <div key={s.id} className="grid grid-cols-7 gap-2 items-center bg-zinc-800 p-3 rounded-lg">
              <input
                className="col-span-1 bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                aria-label="Name" placeholder="e.g. TBM1"
                value={s.name}
                onChange={e => updateStation(s.id, 'name', e.target.value)}
              />
              <input
                type="number" step="0.001"
                className="col-span-2 bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                aria-label="Easting (m)" placeholder="e.g. 500000.000"
                value={s.easting || ''}
                onChange={e => updateStation(s.id, 'easting', parseFloat(e.target.value) || 0)}
              />
              <input
                type="number" step="0.001"
                className="col-span-2 bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                aria-label="Northing (m)" placeholder="e.g. 9900000.000"
                value={s.northing || ''}
                onChange={e => updateStation(s.id, 'northing', parseFloat(e.target.value) || 0)}
              />
              <label className="flex items-center gap-1 text-sm text-zinc-300">
                <input aria-label="Isfixed"
                  type="checkbox"
                  checked={s.isFixed}
                  onChange={e => updateStation(s.id, 'isFixed', e.target.checked)}
                />
                Fixed
              </label>
              <button
                onClick={() => removeStation(s.id)}
                className="text-red-400 text-sm hover:underline"
              >
                Remove
              </button>
            </div>
          ))}
        </div>
      </section>

      <section>
        <div className="flex items-center justify-between mb-3">
          <h3 className="font-medium text-zinc-300">Baseline Observations</h3>
          <button
            onClick={addObservation}
            disabled={stations.length < 2}
            className="text-sm bg-blue-600 text-white px-3 py-1.5 rounded hover:bg-blue-700 disabled:opacity-40"
          >
            + Add Baseline
          </button>
        </div>

        {observations.length === 0 && (
          <p className="text-sm text-zinc-500 italic">No baselines added yet.</p>
        )}

        <div className="space-y-3">
          {observations.map((obs, idx) => (
            <div key={`${obs}-${idx}`} className="grid grid-cols-7 gap-2 items-center bg-zinc-800 p-3 rounded-lg">
              <select
                className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                value={obs.from}
                onChange={e => updateObservation(idx, 'from', e.target.value)}
              >
                {stations.map(s => <option key={s.id} value={s.id}>{s.name || s.id}</option>)}
              </select>
              <select
                className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                value={obs.to}
                onChange={e => updateObservation(idx, 'to', e.target.value)}
              >
                {stations.map(s => <option key={s.id} value={s.id}>{s.name || s.id}</option>)}
              </select>
              <input
                type="number" step="0.001"
                className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                aria-label="ΔE (m)" placeholder="e.g. 0.002"
                value={obs.deltaE || ''}
                onChange={e => updateObservation(idx, 'deltaE', parseFloat(e.target.value) || 0)}
              />
              <input
                type="number" step="0.001"
                className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                aria-label="ΔN (m)" placeholder="e.g. 0.003"
                value={obs.deltaN || ''}
                onChange={e => updateObservation(idx, 'deltaN', parseFloat(e.target.value) || 0)}
              />
              <input
                type="number" step="0.001"
                className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                aria-label="ΔH (m)" placeholder="e.g. 0.001"
                value={obs.deltaH || ''}
                onChange={e => updateObservation(idx, 'deltaH', parseFloat(e.target.value) || 0)}
              />
              <input
                type="number" step="0.0001"
                className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                aria-label="σ (m)" placeholder="e.g. 0.005"
                value={obs.stdDevE || ''}
                onChange={e => {
                  const v = parseFloat(e.target.value) || 0.005
                  updateObservation(idx, 'stdDevE', v)
                  updateObservation(idx, 'stdDevN', v)
                  updateObservation(idx, 'stdDevH', v * 2)
                }}
              />
              <button
                onClick={() => removeObservation(idx)}
                className="text-red-400 text-sm hover:underline"
              >
                Remove
              </button>
            </div>
          ))}
        </div>
      </section>

      {/* Robust Estimation Controls */}
      <section className="bg-zinc-900/50 border border-zinc-700 rounded-lg p-4 space-y-3">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="font-medium text-white flex items-center gap-2">
              <ShieldAlert className="w-4 h-4 text-amber-400" />
              Robust Estimation (Blunder Detection)
            </h3>
            <p className="text-xs text-zinc-500 mt-1">
              Down-weights observations with large residuals using IRLS. Detects blunders that standard LSA misses.
            </p>
          </div>
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={robustMode}
              onChange={e => { setRobustMode(e.target.checked); setResult(null); setRobustResult(null) }}
              className="w-4 h-4 accent-green-600"
            />
            <span className="text-sm text-zinc-300">Enable Robust Mode</span>
          </label>
        </div>
        {robustMode && (
          <div className="flex items-center gap-4 text-sm">
            <label className="text-zinc-400" htmlFor="weight-function">Weight Function:</label>
            <select
               id="weight-function" value={weightFunction}
              onChange={e => setWeightFunction(e.target.value as WeightFunction)}
              className="bg-zinc-800 border border-zinc-700 rounded px-2 py-1 text-white"
            >
              <option value="huber">Huber (gentle, 95% efficient)</option>
              <option value="igg3">IGG3 (Chinese standard, hard reject at 2.5σ)</option>
              <option value="tukey">Tukey Biweight (most aggressive)</option>
            </select>
          </div>
        )}
      </section>

      <div className="flex gap-3">
        <button
          onClick={handleCompute}
          disabled={stations.length < 2 || observations.length === 0}
          className="bg-green-600 text-white px-5 py-2 rounded-lg hover:bg-green-700 disabled:opacity-40 font-medium flex items-center gap-2"
        >
          {robustMode && <Zap className="w-4 h-4" />}
          {robustMode ? 'Run Robust Adjustment' : 'Run Adjustment'}
        </button>
        {result && (
          <button
            onClick={handleExportDXF}
            className="bg-gray-700 text-white px-5 py-2 rounded-lg hover:bg-gray-600 font-medium"
          >
            Export DXF
          </button>
        )}
      </div>

      {error && (
        <div className="bg-red-900/50 border border-red-700 text-red-300 px-4 py-3 rounded-lg text-sm">
          {error}
        </div>
      )}

      {result && (
        <section className="space-y-5">
          <div className={`p-4 rounded-lg border ${result.passedTolerance ? 'bg-green-900/30 border-green-700' : 'bg-amber-900/30 border-amber-700'}`}>
            <h3 className="font-semibold mb-2 text-white flex items-center gap-2">
              {result.passedTolerance
                ? <><CheckCircle2 className="w-4 h-4" /> Adjustment Passed</>
                : <><AlertTriangle className="w-4 h-4" /> Adjustment — Check Residuals</>
              }
            </h3>
            <div className="grid grid-cols-3 gap-4 text-sm text-zinc-300">
              <div><span className="text-zinc-500">σ₀ (ref std dev)</span><br /><strong>{result.sigmaZero.toFixed(4)}</strong></div>
              <div><span className="text-zinc-500">Degrees of freedom</span><br /><strong>{result.degreesOfFreedom}</strong></div>
              <div><span className="text-zinc-500">Iterations</span><br /><strong>{result.iterations}</strong></div>
            </div>
            {result.warnings.length > 0 && (
              <ul className="mt-3 text-sm text-amber-400 list-disc list-inside space-y-1">
                {result.warnings.map((w, i) => <li key={`${w}-${i}`}>{w}</li>)}
              </ul>
            )}
          </div>

          <div>
            <h3 className="font-medium text-zinc-300 mb-2">Adjusted Coordinates</h3>
            <div className="overflow-x-auto">
              <table className="w-full text-sm border-collapse text-zinc-300">
                <thead>
                  <tr className="bg-zinc-800 text-left">
                    <th className="px-3 py-2 border border-zinc-700">Station</th>
                    <th className="px-3 py-2 border border-zinc-700">Easting (m)</th>
                    <th className="px-3 py-2 border border-zinc-700">Northing (m)</th>
                    <th className="px-3 py-2 border border-zinc-700">Residual E (m)</th>
                    <th className="px-3 py-2 border border-zinc-700">Residual N (m)</th>
                    <th className="px-3 py-2 border border-zinc-700">Semi-major (m)</th>
                    <th className="px-3 py-2 border border-zinc-700">Type</th>
                  </tr>
                </thead>
                <tbody>
                  {result.adjustedStations.map(s => (
                    <tr key={s.id} className="hover:bg-zinc-800/50">
                      <td className="px-3 py-2 border border-zinc-700 font-medium">{s.name || s.id}</td>
                      <td className="px-3 py-2 border border-zinc-700 font-mono">{s.easting.toFixed(4)}</td>
                      <td className="px-3 py-2 border border-zinc-700 font-mono">{s.northing.toFixed(4)}</td>
                      <td className="px-3 py-2 border border-zinc-700 font-mono">{s.residualE.toFixed(5)}</td>
                      <td className="px-3 py-2 border border-zinc-700 font-mono">{s.residualN.toFixed(5)}</td>
                      <td className="px-3 py-2 border border-zinc-700 font-mono">{s.semiMajor.toFixed(5)}</td>
                      <td className="px-3 py-2 border border-zinc-700">{s.isFixed ? <span className="flex items-center gap-1"><Lock className="w-3 h-3" /> Fixed</span> : 'Free'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Error Ellipse Diagram */}
          <ErrorEllipseCanvas
            stations={result.adjustedStations}
            observations={observations}
            width={700}
            height={450}
          />

          {/* Robust Adjustment: Blunder Detection Panel */}
          {robustResult && (
            <div className={`p-4 rounded-lg border ${robustResult.blunders.length === 0 ? 'bg-green-900/30 border-green-700' : 'bg-red-900/30 border-red-700'}`}>
              <h3 className="font-semibold mb-2 text-white flex items-center gap-2">
                {robustResult.blunders.length === 0
                  ? <><CheckCircle2 className="w-4 h-4" /> No Blunders Detected</>
                  : <><AlertTriangle className="w-4 h-4" /> {robustResult.blunders.length} Blunder(s) Detected</>
                }
                <span className="text-xs font-normal text-zinc-400 ml-2">
                  ({robustResult.method.toUpperCase()} IRLS, {robustResult.iterations} iterations)
                </span>
              </h3>
              <p className="text-sm text-zinc-300 mb-3">{robustResult.summary}</p>

              {/* Per-observation weights table */}
              <div className="overflow-x-auto">
                <table className="w-full text-sm border-collapse text-zinc-300">
                  <thead>
                    <tr className="bg-zinc-800 text-left">
                      <th className="px-3 py-2 border border-zinc-700">#</th>
                      <th className="px-3 py-2 border border-zinc-700">From → To</th>
                      <th className="px-3 py-2 border border-zinc-700">Type</th>
                      <th className="px-3 py-2 border border-zinc-700">Residual (m)</th>
                      <th className="px-3 py-2 border border-zinc-700">Std. Residual</th>
                      <th className="px-3 py-2 border border-zinc-700">Final Weight</th>
                      <th className="px-3 py-2 border border-zinc-700">Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {robustResult.blunders.map((b, i) => (
                      <tr key={i} className="bg-red-950/30">
                        <td className="px-3 py-2 border border-zinc-700">{b.index + 1}</td>
                        <td className="px-3 py-2 border border-zinc-700 font-medium">{b.from || '?'} → {b.to || '?'}</td>
                        <td className="px-3 py-2 border border-zinc-700">{b.type}</td>
                        <td className="px-3 py-2 border border-zinc-700 font-mono">{b.residual.toFixed(4)}</td>
                        <td className="px-3 py-2 border border-zinc-700 font-mono">{b.standardizedResidual.toFixed(2)}σ</td>
                        <td className="px-3 py-2 border border-zinc-700 font-mono text-red-400">{b.finalWeight.toFixed(3)}</td>
                        <td className="px-3 py-2 border border-zinc-700 text-red-400 font-medium">BLUNDER</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {robustResult.blunders.length > 0 && (
                <p className="text-xs text-zinc-400 mt-3">
                  💡 Blunders are down-weighted automatically. Re-check the observation field notes for the flagged legs —
                  look for swapped face, wrong target height, or transcription errors. After correcting, re-run the adjustment.
                </p>
              )}
            </div>
          )}

          {saving && <p className="text-sm text-zinc-500 italic">Saving results…</p>}
        </section>
      )}
    </div>
  )
}

'use client';

import { useState, useRef } from 'react'
import { createClient } from '@/lib/api-client/client'
import { parseDelimitedFile, validatePoints } from '@/lib/engine/parser'

interface CSVUploadModalProps {
  isOpen: boolean
  onClose: () => void
  projectId: string
  onUploadComplete: () => void
}

interface ParsedPoint {
  name: string
  easting: number
  northing: number
  elevation: number
}

export default function CSVUploadModal({
  isOpen,
  onClose,
  projectId,
  onUploadComplete
}: CSVUploadModalProps) {
  const [parsedPoints, setParsedPoints] = useState<ParsedPoint[]>([])
  const [warnings, setWarnings] = useState<string[]>([])
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const [step, setStep] = useState<'upload' | 'preview' | 'importing'>('upload')
  const fileInputRef = useRef<HTMLInputElement>(null)
  const dbClient = createClient()

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    setError('')
    setLoading(true)

    try {
      const content = await file.text()
      const result = parseDelimitedFile(content, ',')
      
      if (result.points.length === 0) {
        setError('No valid points found in file')
        setLoading(false)
        return
      }

      const validationWarnings = validatePoints(result.points)
      setParsedPoints(result.points.map((p) => ({
        name: p.name,
        easting: p.easting,
        northing: p.northing,
        elevation: p.elevation || 0
      })))
      setWarnings([...result.warnings, ...validationWarnings])
      setStep('preview')
    } catch (err) {
      // AUDIT FIX (M15, 2026-07-02): Actionable error message.
      const msg = err instanceof Error ? err.message : String(err)
      setError(`Could not parse the file. ${msg}. Check that the file is a valid CSV with columns: name, easting, northing, elevation (or N, E, Z). If the file uses a different delimiter (tab, semicolon), try converting to comma-separated first.`)
    }

    setLoading(false)
  }

  const handleImport = async () => {
    setStep('importing')
    setLoading(true)

    try {
      const pointsToInsert = parsedPoints.map((p) => ({
        project_id: projectId,
        point_name: p.name,  // T1.5d FIX: was 'name' (column doesn't exist)
        easting: p.easting,
        northing: p.northing,
        elevation: p.elevation,
        is_control: false
      }))

      const { error } = await dbClient.from('survey_points').insert(pointsToInsert)

      if (error) {
        setError(error.message)
        setLoading(false)
        return
      }

      onUploadComplete()
      handleClose()
    } catch (err) {
      setError('Failed to import points')
    }

    setLoading(false)
  }

  const handleClose = () => {
    setParsedPoints([])
    setWarnings([])
    setError('')
    setStep('upload')
    if (fileInputRef.current) {
      fileInputRef.current.value = ''
    }
    onClose()
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/70" onClick={handleClose}></div>
      <div className="relative bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg p-6 w-full max-w-2xl max-h-[80vh] overflow-hidden flex flex-col">
        <h2 className="text-xl font-bold text-[var(--text-primary)] mb-4">Upload CSV</h2>

        {error && (
          <div className="mb-4 p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">
            {error}
          </div>
        )}

        {step === 'upload' && (
          <div className="space-y-4">
            <p className="text-[var(--text-secondary)] text-sm">
              Upload a CSV file with columns: Point Name, Easting, Northing, Elevation (optional)
            </p>
            <div className="border-2 border-dashed border-[var(--border-color)] rounded-lg p-8 text-center">
              <input
                ref={fileInputRef}
                type="file"
                accept=".csv,.txt"
                onChange={handleFileChange}
                className="hidden"
                id="csv-upload"
              />
              <label
                htmlFor="csv-upload"
                className="cursor-pointer inline-flex items-center gap-2 px-4 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded transition-colors"
              >
                {loading ? 'Parsing...' : 'Choose File'}
              </label>
              <p className="text-[var(--text-muted)] text-sm mt-2">or drag and drop</p>
            </div>
            <div className="text-xs text-[var(--text-muted)]">
              <p className="font-semibold text-[var(--text-secondary)] mb-1">Expected format:</p>
              <code className="block bg-[var(--bg-tertiary)] p-2 rounded">
                POINT,EASTING,NORTHING,ELEVATION<br />
                TP01,123456.7890,9876543.210,100.5<br />
                TP02,123478.9012,9876565.432,101.2
              </code>
            </div>
          </div>
        )}

        {step === 'preview' && (
          <div className="space-y-4 flex-1 overflow-hidden flex flex-col">
            <div className="flex items-center justify-between">
              <p className="text-[var(--text-primary)]">
                Found <span className="text-[var(--accent)] font-bold">{parsedPoints.length}</span> points
              </p>
              <button
                onClick={handleClose}
                className="text-[var(--text-secondary)] hover:text-[var(--text-primary)]"
              >
                ×
              </button>
            </div>

            {warnings.length > 0 && (
              <div className="bg-yellow-900/30 border border-yellow-600 rounded p-3 max-h-24 overflow-y-auto">
                <p className="text-yellow-400 text-sm font-semibold mb-1">Warnings:</p>
                {warnings.slice(0, 5).map((w, i) => (
                  <p key={`${w}-${i}`} className="text-yellow-300 text-xs">{w}</p>
                ))}
                {warnings.length > 5 && (
                  <p className="text-yellow-300 text-xs">...and {warnings.length - 5} more</p>
                )}
              </div>
            )}

            <div className="flex-1 overflow-auto border border-[var(--border-color)] rounded">
              <table className="w-full text-sm">
                <thead className="bg-[var(--bg-tertiary)] sticky top-0">
                  <tr>
                    <th className="px-3 py-2 text-left text-[var(--text-primary)] font-semibold">Point</th>
                    <th className="px-3 py-2 text-left text-[var(--text-primary)] font-semibold">Easting</th>
                    <th className="px-3 py-2 text-left text-[var(--text-primary)] font-semibold">Northing</th>
                    <th className="px-3 py-2 text-left text-[var(--text-primary)] font-semibold">Elevation</th>
                  </tr>
                </thead>
                <tbody>
                  {parsedPoints.slice(0, 50).map((point, idx) => (
                    <tr key={point.name} className="border-t border-[var(--border-color)]">
                      <td className="px-3 py-2 font-mono text-[var(--text-primary)]">{point.name}</td>
                      <td className="px-3 py-2 font-mono text-[var(--text-primary)]">{point.easting.toFixed(4)}</td>
                      <td className="px-3 py-2 font-mono text-[var(--text-primary)]">{point.northing.toFixed(4)}</td>
                      <td className="px-3 py-2 font-mono text-[var(--text-primary)]">{point.elevation.toFixed(3)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {parsedPoints.length > 50 && (
                <p className="text-center text-[var(--text-muted)] py-2 text-sm">
                  ...and {parsedPoints.length - 50} more points
                </p>
              )}
            </div>

            <div className="flex gap-3">
              <button
                onClick={handleClose}
                className="flex-1 px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={handleImport}
                disabled={loading}
                className="flex-1 px-4 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded transition-colors disabled:opacity-50"
              >
                Import {parsedPoints.length} Points
              </button>
            </div>
          </div>
        )}

        {step === 'importing' && (
          <div className="py-12 text-center">
            <div className="animate-spin w-8 h-8 border-2 border-[var(--accent)] border-t-transparent rounded-full mx-auto mb-4"></div>
            <p className="text-[var(--text-primary)]">Importing points...</p>
          </div>
        )}
      </div>
    </div>
  )
}

'use client';

import {
  useState,
  useEffect,
  useRef,
  useCallback,
  type KeyboardEvent as ReactKeyboardEvent,
} from 'react';
import { useRouter } from 'next/navigation';
import { Search, X, Loader2 } from 'lucide-react';
import { cn } from '@/lib/utils';
import { logger } from '@/lib/logger'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface ProjectResult {
  id: string;
  name: string;
  description: string;
  relevance: number;
}

interface SubmissionResult {
  id: string;
  title: string;
  status: string;
  relevance: number;
}

interface SurveyorResult {
  id: string;
  full_name: string;
  isk_number: string;
  relevance: number;
}

interface SearchResults {
  projects: ProjectResult[];
  submissions: SubmissionResult[];
  surveyors: SurveyorResult[];
}

interface SearchResponse {
  results: SearchResults;
  total: number;
  query: string;
}

type ResultType = 'projects' | 'submissions' | 'surveyors';

/** Flattened item for keyboard navigation */
interface FlatItem {
  type: ResultType;
  data: ProjectResult | SubmissionResult | SurveyorResult;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const DEBOUNCE_MS = 300;

const GROUP_LABELS: Record<ResultType, string> = {
  projects: 'Projects',
  submissions: 'Submissions',
  surveyors: 'Surveyors',
};

const GROUP_ICONS: Record<ResultType, React.ReactNode> = {
  projects: (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z" />
    </svg>
  ),
  submissions: (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z" />
      <polyline points="14 2 14 8 20 8" />
      <line x1="16" y1="13" x2="8" y2="13" />
      <line x1="16" y1="17" x2="8" y2="17" />
    </svg>
  ),
  surveyors: (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2" />
      <circle cx="12" cy="7" r="4" />
    </svg>
  ),
};

function getRoute(type: ResultType, id: string): string {
  switch (type) {
    case 'projects':
      return `/dashboard/projects/${id}`;
    case 'submissions':
      return `/dashboard/submissions/${id}`;
    case 'surveyors':
      return `/dashboard/surveyors/${id}`;
  }
}

function getPrimaryLabel(item: FlatItem['data']): string {
  if ('name' in item) return item.name;
  if ('title' in item) return item.title;
  if ('full_name' in item) return item.full_name;
  return '';
}

function getSecondaryLabel(item: FlatItem['data']): string | null {
  if ('description' in item && item.description) return item.description;
  if ('status' in item && item.status) return item.status;
  if ('isk_number' in item && item.isk_number) return `ISK ${item.isk_number}`;
  return null;
}

function getStatusColor(status: string): string {
  switch (status.toLowerCase()) {
    case 'approved':
      return 'text-[var(--success)]';
    case 'pending':
    case 'under_review':
      return 'text-[var(--warning)]';
    case 'rejected':
      return 'text-[var(--error)]';
    default:
      return 'text-[var(--text-muted)]';
  }
}

function flattenResults(results: SearchResults): FlatItem[] {
  const items: FlatItem[] = [];
  // Sort each group by relevance descending
  const sortedProjects = [...results.projects].sort((a, b) => b.relevance - a.relevance);
  const sortedSubmissions = [...results.submissions].sort((a, b) => b.relevance - a.relevance);
  const sortedSurveyors = [...results.surveyors].sort((a, b) => b.relevance - a.relevance);

  for (const project of sortedProjects) items.push({ type: 'projects', data: project });
  for (const submission of sortedSubmissions) items.push({ type: 'submissions', data: submission });
  for (const surveyor of sortedSurveyors) items.push({ type: 'surveyors', data: surveyor });
  return items;
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function DashboardSearch() {
  const router = useRouter();

  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResults | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isOpen, setIsOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);

  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  // ------ Flatten items for keyboard navigation ------
  const flatItems = results ? flattenResults(results) : [];
  const hasResults = flatItems.length > 0;

  // ------ Group tracking (which type starts at which flat index) ------
  const groupBoundaries = useRef<Map<number, ResultType>>(new Map());

  useEffect(() => {
    groupBoundaries.current.clear();
    if (!results) return;

    let idx = 0;
    const order: ResultType[] = ['projects', 'submissions', 'surveyors'];
    for (const type of order) {
      const arr = results[type];
      if (arr.length > 0) {
        groupBoundaries.current.set(idx, type);
        idx += arr.length;
      }
    }
  }, [results]);

  // ------ Search API call ------
  const performSearch = useCallback(async (q: string) => {
    // Cancel any in-flight request
    if (abortRef.current) abortRef.current.abort();
    const controller = new AbortController();
    abortRef.current = controller;

    if (!q.trim()) {
      setResults(null);
      setIsLoading(false);
      return;
    }

    setIsLoading(true);
    try {
      const res = await fetch(`/api/search?q=${encodeURIComponent(q.trim())}`, {
        signal: controller.signal,
      });
      if (!res.ok) throw new Error(`Search failed: ${res.status}`);
            const data: SearchResponse = await res.json() as unknown as SearchResponse;
      // Only update if this wasn't aborted
      if (!controller.signal.aborted) {
        setResults(data.results);
      }
    } catch (err) {
      // Ignore abort errors
      if (err instanceof DOMException && err.name === 'AbortError') return;
      logger.error('Search error:', { error: err });
      setResults(null);
    } finally {
      if (!controller.signal.aborted) {
        setIsLoading(false);
      }
    }
  }, []);

  // ------ Input change with debounce ------
  const handleInputChange = useCallback(
    (value: string) => {
      setQuery(value);
      setActiveIndex(-1);

      if (debounceRef.current) clearTimeout(debounceRef.current);

      if (!value.trim()) {
        setResults(null);
        setIsLoading(false);
        setIsOpen(false);
        return;
      }

      setIsOpen(true);
      setIsLoading(true);
      debounceRef.current = setTimeout(() => {
        performSearch(value);
      }, DEBOUNCE_MS);
    },
    [performSearch],
  );

  // ------ Clear search ------
  const handleClear = useCallback(() => {
    setQuery('');
    setResults(null);
    setIsLoading(false);
    setIsOpen(false);
    setActiveIndex(-1);
    inputRef.current?.focus();
  }, []);

  // ------ Click outside to close ------
  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // ------ Escape to close ------
  useEffect(() => {
    function handleEscape(e: globalThis.KeyboardEvent) {
      if (e.key === 'Escape') {
        setIsOpen(false);
        inputRef.current?.blur();
      }
    }
    document.addEventListener('keydown', handleEscape);
    return () => document.removeEventListener('keydown', handleEscape);
  }, []);

  // ------ Cleanup on unmount ------
  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
      if (abortRef.current) abortRef.current.abort();
    };
  }, []);

  // ------ Navigate to result ------
  const navigateTo = useCallback(
    (item: FlatItem) => {
      const route = getRoute(item.type, item.data.id);
      setIsOpen(false);
      router.push(route);
    },
    [router],
  );

  // ------ Keyboard navigation ------
  const handleKeyDown = useCallback(
    (e: ReactKeyboardEvent<HTMLInputElement>) => {
      if (!isOpen) {
        if (e.key === 'ArrowDown' && query.trim()) {
          setIsOpen(true);
        }
        return;
      }

      switch (e.key) {
        case 'ArrowDown': {
          e.preventDefault();
          setActiveIndex((prev) => (prev < flatItems.length - 1 ? prev + 1 : 0));
          break;
        }
        case 'ArrowUp': {
          e.preventDefault();
          setActiveIndex((prev) => (prev > 0 ? prev - 1 : flatItems.length - 1));
          break;
        }
        case 'Enter': {
          e.preventDefault();
          if (activeIndex >= 0 && activeIndex < flatItems.length) {
            navigateTo(flatItems[activeIndex]);
          }
          break;
        }
        case 'Escape': {
          setIsOpen(false);
          break;
        }
      }
    },
    [isOpen, flatItems, activeIndex, navigateTo, query],
  );

  // ------ Scroll active item into view ------
  useEffect(() => {
    if (activeIndex < 0 || !isOpen) return;
    const el = containerRef.current?.querySelector(
      `[data-search-index="${activeIndex}"]`,
    ) as HTMLElement | null;
    el?.scrollIntoView({ block: 'nearest' });
  }, [activeIndex, isOpen]);

  // ------ Focus input on Cmd/Ctrl+K ------
  useEffect(() => {
    function handleGlobalShortcut(e: globalThis.KeyboardEvent) {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        inputRef.current?.focus();
        if (query.trim()) setIsOpen(true);
      }
    }
    document.addEventListener('keydown', handleGlobalShortcut);
    return () => document.removeEventListener('keydown', handleGlobalShortcut);
  }, [query]);

  // ------ Render grouped results ------
  const renderResults = () => {
    if (!isOpen) return null;

    if (isLoading && !results) {
      return (
        <div className="absolute top-full left-0 right-0 z-50 mt-2 rounded-2xl border border-[var(--border-color)] bg-[var(--bg-card)]/80 backdrop-blur-2xl shadow-[0_16px_40px_rgba(0,0,0,0.5)] overflow-hidden transition-all duration-300">
          <div className="flex items-center justify-center gap-2 px-4 py-8 text-sm text-[var(--text-muted)]">
            <Loader2 className="h-4 w-4 animate-spin" />
            <span>Searching...</span>
          </div>
        </div>
      );
    }

    if (results && !hasResults && query.trim()) {
      return (
        <div className="absolute top-full left-0 right-0 z-50 mt-2 rounded-2xl border border-[var(--border-color)] bg-[var(--bg-card)]/80 backdrop-blur-2xl shadow-[0_16px_40px_rgba(0,0,0,0.5)] overflow-hidden transition-all duration-300">
          <div className="flex flex-col items-center justify-center px-4 py-8">
            <Search className="h-8 w-8 text-[var(--text-muted)] mb-2 opacity-50" />
            <p className="text-sm text-[var(--text-secondary)]">No results found</p>
            <p className="text-xs text-[var(--text-muted)] mt-1">
              Try a different search term
            </p>
          </div>
        </div>
      );
    }

    if (!results || !hasResults) return null;

    const order: ResultType[] = ['projects', 'submissions', 'surveyors'];
    let flatIdx = 0;

    return (
      <div className="absolute top-full left-0 right-0 z-50 mt-2 rounded-2xl border border-[var(--border-color)] bg-[var(--bg-card)]/80 backdrop-blur-2xl shadow-[0_16px_40px_rgba(0,0,0,0.5)] overflow-hidden transition-all duration-300">
        <div className="max-h-80 overflow-y-auto overscroll-contain">
          {order.map((type) => {
            const items = results[type];
            if (!items.length) return null;

            // Sort by relevance
            const sorted = [...items].sort((a, b) => b.relevance - a.relevance);
            const startIdx = flatIdx;

            const group = (
              <div key={type}>
                {/* Group header */}
                <div className="flex items-center gap-2 px-3 py-2 text-xs font-semibold uppercase tracking-wider text-[var(--text-muted)] bg-[var(--bg-primary)]/50 border-b border-[var(--border-color)]">
                  {GROUP_ICONS[type]}
                  {GROUP_LABELS[type]}
                  <span className="ml-auto text-[10px] font-normal text-[var(--text-muted)] opacity-70">
                    {sorted.length}
                  </span>
                </div>

                {/* Items */}
                {sorted.map((item, i) => {
                  const currentFlatIdx = startIdx + i;
                  const isActive = activeIndex === currentFlatIdx;
                  const primary = getPrimaryLabel(item);
                  const secondary = getSecondaryLabel(item);

                  return (
                    <button
                      key={`${type}-${item.id}`}
                      data-search-index={currentFlatIdx}
                      type="button"
                      className={cn(
                        'w-full flex items-center gap-3 px-3 py-2.5 text-left transition-colors duration-100 border-b border-[var(--border-color)] last:border-b-0',
                        isActive
                          ? 'bg-[var(--accent-subtle)] text-[var(--accent)]'
                          : 'text-[var(--text-secondary)] hover:bg-[var(--glass-bg)] hover:text-[var(--text-primary)]',
                      )}
                      onClick={() => navigateTo({ type, data: item })}
                      onMouseEnter={() => setActiveIndex(currentFlatIdx)}
                    >
                      {/* Icon */}
                      <div
                        className={cn(
                          'shrink-0 flex items-center justify-center w-8 h-8 rounded-md border',
                          isActive
                            ? 'border-[var(--accent)]/30 bg-[var(--accent)]/10 text-[var(--accent)]'
                            : 'border-[var(--border-color)] bg-[var(--bg-tertiary)] text-[var(--text-muted)]',
                        )}
                      >
                        {GROUP_ICONS[type]}
                      </div>

                      {/* Text */}
                      <div className="min-w-0 flex-1">
                        <p
                          className={cn(
                            'text-sm font-medium truncate',
                            isActive ? 'text-[var(--accent)]' : 'text-[var(--text-primary)]',
                          )}
                        >
                          {primary}
                        </p>
                        {secondary && (
                          <p
                            className={cn(
                              'text-xs truncate mt-0.5',
                              'status' in item
                                ? getStatusColor(item.status as string)
                                : 'text-[var(--text-muted)]',
                            )}
                          >
                            {secondary}
                          </p>
                        )}
                      </div>

                      {/* Relevance indicator */}
                      <div className="shrink-0 w-10 text-right">
                        <span className="text-[10px] text-[var(--text-muted)] opacity-60">
                          {Math.round(item.relevance * 100)}%
                        </span>
                      </div>
                    </button>
                  );
                })}
              </div>
            );

            flatIdx += sorted.length;
            return group;
          })}
        </div>

        {/* Footer hint */}
        <div className="flex items-center justify-between px-4 py-3 border-t border-[var(--border-color)] bg-[var(--bg-primary)]/40 text-[10px] text-[var(--text-muted)]">
          <span>{results ? Object.values(results).reduce<number>((sum, arr) => sum + (arr as unknown[]).length, 0) : 0} results</span>
          <div className="flex items-center gap-2">
            <kbd className="px-1 py-0.5 rounded border border-[var(--border-color)] bg-[var(--bg-tertiary)] text-[9px]">
              ↑↓
            </kbd>
            <span>navigate</span>
            <kbd className="px-1 py-0.5 rounded border border-[var(--border-color)] bg-[var(--bg-tertiary)] text-[9px]">
              ↵
            </kbd>
            <span>open</span>
            <kbd className="px-1 py-0.5 rounded border border-[var(--border-color)] bg-[var(--bg-tertiary)] text-[9px]">
              esc
            </kbd>
            <span>close</span>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div ref={containerRef} className="relative w-full max-w-md">
      {/* Search input */}
      <div
        className={cn(
          'flex items-center gap-3 rounded-full border bg-[var(--bg-secondary)] px-5 py-3 transition-all duration-500 ease-[cubic-bezier(0.32,0.72,0,1)]',
          isOpen
            ? 'border-[var(--accent)] shadow-[0_0_0_3px_var(--accent-subtle)] bg-[var(--bg-card)]'
            : 'border-[var(--border-color)] hover:border-[var(--border-hover)]',
        )}
      >
        {isLoading ? (
          <Loader2 className="h-4 w-4 shrink-0 animate-spin text-[var(--accent)]" />
        ) : (
          <Search className="h-4 w-4 shrink-0 text-[var(--text-muted)]" />
        )}

        <input
          ref={inputRef}
          type="text"
          value={query}
          onChange={(e) => handleInputChange(e.target.value)}
          onKeyDown={handleKeyDown}
          onFocus={() => {
            if (query.trim()) setIsOpen(true);
          }}
          aria-label="Search projects, submissions, surveyors..."
          className="flex-1 bg-transparent text-sm text-[var(--text-primary)] placeholder-[var(--text-muted)] outline-none min-w-0"
          autoComplete="off"
          spellCheck={false}
        />

        {query && (
          <button
            type="button"
            onClick={handleClear}
            className="shrink-0 flex items-center justify-center w-5 h-5 rounded-sm text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)] transition-colors"
            aria-label="Clear search"
          >
            <X className="h-3.5 w-3.5" />
          </button>
        )}

        {!query && (
          <kbd className="hidden sm:inline-flex items-center gap-0.5 rounded border border-[var(--border-color)] bg-[var(--bg-tertiary)] px-1.5 py-0.5 text-[10px] font-medium text-[var(--text-muted)] shrink-0">
            <span className="text-[9px]">⌘</span>K
          </kbd>
        )}
      </div>

      {/* Results dropdown */}
      {renderResults()}
    </div>
  );
}

'use client'

/**
 * QADashboard — Single view of all quality checks for a project
 *
 * Shows:
 * - Topology check results (overlaps, slivers, self-intersections)
 * - Area reconciliation (parent vs sum of parts)
 * - Traverse precision (linear + angular closure)
 * - Beacon validation (duplicates, missing coordinates)
 * - Document compliance (SoK standards)
 * - NLIMS readiness
 *
 * Green = pass, Amber = warning, Red = fail
 */

import { useState, useCallback, useMemo } from 'react'
import {
  ShieldCheck, AlertTriangle, AlertCircle, CheckCircle2,
  Loader2, RefreshCw, FileText, MapPin, Ruler, Calculator,
  Layers, Building2, Download,
} from 'lucide-react'
import { runTopologyCheck, type ExistingParcel } from '@/lib/survey/topologyChecker'
import { evaluateTraversePrecision, type TraverseCategory } from '@/lib/engine/computationalAccuracy'
import { computeAreaWithPrecision } from '@/lib/engine/computationalAccuracy'
import { memoize } from '@/lib/performance'

// Memoized area computation — caches results for same vertex sets
const memoizedComputeArea = memoize(computeAreaWithPrecision, {
  keyFn: (vertices) => JSON.stringify(vertices[0]),
  maxSize: 200,
})

interface QACheck {
  id: string
  category: 'topology' | 'area' | 'traverse' | 'beacons' | 'documents' | 'nlims'
  name: string
  status: 'pass' | 'warning' | 'fail' | 'pending'
  message: string
  details?: string
  count?: number
}

interface QADashboardProps {
  projectId: string
  parcels?: ExistingParcel[]
  traverseData?: {
    linearErrorM: number
    totalDistanceM: number
    angularMisclosureSec: number
    stationCount: number
  }
  parentAreaHa?: number
  surveyCategory?: TraverseCategory
}

const CATEGORY_ICONS = {
  topology: Layers,
  area: Calculator,
  traverse: Ruler,
  beacons: MapPin,
  documents: FileText,
  nlims: Building2,
}

const STATUS_CONFIG = {
  pass: { icon: CheckCircle2, color: 'text-emerald-400', bg: 'bg-emerald-500/10', border: 'border-emerald-500/30', label: 'PASS' },
  warning: { icon: AlertTriangle, color: 'text-amber-400', bg: 'bg-amber-500/10', border: 'border-amber-500/30', label: 'WARNING' },
  fail: { icon: AlertCircle, color: 'text-red-400', bg: 'bg-red-500/10', border: 'border-red-500/30', label: 'FAIL' },
  pending: { icon: Loader2, color: 'text-gray-400', bg: 'bg-gray-500/10', border: 'border-gray-500/30', label: 'PENDING' },
}

export function QADashboard({
  projectId,
  parcels = [],
  traverseData,
  parentAreaHa,
  surveyCategory = 'urban',
}: QADashboardProps) {
  const [checks, setChecks] = useState<QACheck[]>([])
  const [running, setRunning] = useState(false)

  const runAllChecks = useCallback(async () => {
    setRunning(true)

    const results: QACheck[] = []

    // ─── 1. Topology Checks ──────────────────────────────────
    if (parcels.length > 0) {
      let totalOverlaps = 0
      let totalSlivers = 0
      let totalSelfIntersections = 0

      for (const parcel of parcels) {
        const otherParcels = parcels.filter(p => p.id !== parcel.id)
        const topoResult = await runTopologyCheck({
          newVertices: parcel.vertices,
          existingParcels: otherParcels,
        })

        totalOverlaps += topoResult.issues.filter(i => i.type === 'overlap').length
        totalSlivers += topoResult.issues.filter(i => i.type === 'sliver').length
        totalSelfIntersections += topoResult.issues.filter(i => i.type === 'self_intersection').length
      }

      results.push({
        id: 'topo-overlap',
        category: 'topology',
        name: 'Parcel Overlaps',
        status: totalOverlaps === 0 ? 'pass' : 'fail',
        message: totalOverlaps === 0 ? 'No overlapping parcels detected' : `${totalOverlaps} overlap(s) found`,
        details: 'Overlapping parcels will be rejected by the registry',
        count: totalOverlaps,
      })

      results.push({
        id: 'topo-sliver',
        category: 'topology',
        name: 'Sliver Gaps',
        status: totalSlivers === 0 ? 'pass' : 'warning',
        message: totalSlivers === 0 ? 'No sliver gaps detected' : `${totalSlivers} sliver gap(s) found`,
        details: 'Micro-gaps between adjacent parcels may cause registration issues',
        count: totalSlivers,
      })

      results.push({
        id: 'topo-self-int',
        category: 'topology',
        name: 'Self-Intersections',
        status: totalSelfIntersections === 0 ? 'pass' : 'fail',
        message: totalSelfIntersections === 0 ? 'All parcel boundaries are valid' : `${totalSelfIntersections} self-intersection(s) found`,
        details: 'A boundary that crosses itself produces an invalid parcel',
        count: totalSelfIntersections,
      })
    } else {
      results.push({
        id: 'topo-empty',
        category: 'topology',
        name: 'Parcel Data',
        status: 'pending',
        message: 'No parcels to check — import parcels first',
      })
    }

    // ─── 2. Area Reconciliation ──────────────────────────────
    if (parentAreaHa && parcels.length > 0) {
      const sumOfParts = parcels.reduce((sum, p) => {
        const area = memoizedComputeArea(p.vertices)
        return sum + area.areaHectares
      }, 0)

      const difference = Math.abs(parentAreaHa - sumOfParts)
      const tolerance = 0.001 // 10 m²

      results.push({
        id: 'area-recon',
        category: 'area',
        name: 'Area Reconciliation',
        status: difference <= tolerance ? 'pass' : 'fail',
        message: difference <= tolerance
          ? `Sum of parts (${sumOfParts.toFixed(4)} ha) matches parent (${parentAreaHa.toFixed(4)} ha)`
          : `Mismatch: parent ${parentAreaHa.toFixed(4)} ha vs parts ${sumOfParts.toFixed(4)} ha (diff ${difference.toFixed(4)} ha)`,
        details: 'Sum of subdivision parts must equal parent title area within ±0.001 ha',
      })
    }

    // ─── 3. Traverse Precision ───────────────────────────────
    if (traverseData) {
      const precision = evaluateTraversePrecision(
        traverseData.linearErrorM,
        traverseData.totalDistanceM,
        traverseData.angularMisclosureSec,
        traverseData.stationCount,
        surveyCategory,
      )

      results.push({
        id: 'trav-linear',
        category: 'traverse',
        name: 'Linear Precision',
        status: precision.passesLinear ? 'pass' : 'fail',
        message: `1:${precision.linearPrecision.toLocaleString()} (min 1:${precision.minRequiredLinear})`,
        details: `Survey Act Cap 299 requires 1:${precision.minRequiredLinear} for ${surveyCategory} surveys`,
      })

      results.push({
        id: 'trav-angular',
        category: 'traverse',
        name: 'Angular Closure',
        status: precision.passesAngular ? 'pass' : 'fail',
        message: `${precision.angularMisclosure.toFixed(1)}" (max ${precision.maxAllowedAngular.toFixed(1)}")`,
        details: `Maximum allowed: ${precision.maxAllowedAngular.toFixed(1)}" for ${precision.stationCount} stations`,
      })
    }

    // ─── 4. Beacon Validation ────────────────────────────────
    if (parcels.length > 0) {
      const allBeacons = parcels.flatMap(p => p.vertices)
      let duplicates = 0

      for (let i = 0; i < allBeacons.length; i++) {
        for (let j = i + 1; j < allBeacons.length; j++) {
          const dE = allBeacons[i].easting - allBeacons[j].easting
          const dN = allBeacons[i].northing - allBeacons[j].northing
          if (Math.sqrt(dE * dE + dN * dN) < 0.1) duplicates++
        }
      }

      results.push({
        id: 'beacon-dup',
        category: 'beacons',
        name: 'Duplicate Beacons',
        status: duplicates === 0 ? 'pass' : 'warning',
        message: duplicates === 0 ? 'No duplicate beacons' : `${duplicates} potential duplicate(s) found`,
        details: 'Beacons less than 0.1m apart may be the same physical beacon',
        count: duplicates,
      })
    }

    // ─── 5. Document Compliance ──────────────────────────────
    results.push({
      id: 'doc-sok',
      category: 'documents',
      name: 'SoK Standards Compliance',
      status: 'pass',
      message: 'All document templates use SoK 2020 line weights and text sizes',
      details: 'Line weights: 0.3mm parcels, 0.5mm scheme, 0.7mm title. Text: 2.5mm coordinates, 2mm bearings',
    })

    // ─── 6. NLIMS Readiness ──────────────────────────────────
    const hasAllFields = parcels.every(p => p.id && p.vertices.length >= 3)
    results.push({
      id: 'nlims-ready',
      category: 'nlims',
      name: 'NLIMS/ArdhiSasa Readiness',
      status: hasAllFields && parcels.length > 0 ? 'pass' : 'pending',
      message: hasAllFields && parcels.length > 0
        ? 'All parcels have required fields for NLIMS submission'
        : 'Missing required parcel data for NLIMS export',
      details: 'Requires: parcel number, 3+ vertices, owner data',
    })

    setChecks(results)
    setRunning(false)
  }, [parcels, parentAreaHa, traverseData, surveyCategory])

  // Auto-run on mount
  useMemo(() => {
    runAllChecks()
  }, [runAllChecks])

  const stats = useMemo(() => {
    return {
      total: checks.length,
      pass: checks.filter(c => c.status === 'pass').length,
      warning: checks.filter(c => c.status === 'warning').length,
      fail: checks.filter(c => c.status === 'fail').length,
      pending: checks.filter(c => c.status === 'pending').length,
    }
  }, [checks])

  const overallStatus = stats.fail > 0 ? 'fail' : stats.warning > 0 ? 'warning' : stats.pass > 0 ? 'pass' : 'pending'

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="card p-4">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${
              overallStatus === 'pass' ? 'bg-emerald-500/10' :
              overallStatus === 'warning' ? 'bg-amber-500/10' :
              overallStatus === 'fail' ? 'bg-red-500/10' : 'bg-gray-500/10'
            }`}>
              <ShieldCheck className={`w-5 h-5 ${
                overallStatus === 'pass' ? 'text-emerald-400' :
                overallStatus === 'warning' ? 'text-amber-400' :
                overallStatus === 'fail' ? 'text-red-400' : 'text-gray-400'
              }`} />
            </div>
            <div>
              <h2 className="text-sm font-semibold text-[var(--text-primary)]">QA Validation Dashboard</h2>
              <p className="text-[10px] text-gray-500">All quality checks in one view</p>
            </div>
          </div>
          <button
            onClick={runAllChecks}
            disabled={running}
            className="flex items-center gap-1.5 px-3 h-8 rounded-lg bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)] text-xs font-medium hover:bg-[var(--accent)]/20 disabled:opacity-50"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${running ? 'animate-spin' : ''}`} />
            Re-run Checks
          </button>
        </div>

        {/* Summary stats */}
        <div className="grid grid-cols-4 gap-2">
          <StatBox label="Passed" value={stats.pass} color="text-emerald-400" bg="bg-emerald-500/10" />
          <StatBox label="Warnings" value={stats.warning} color="text-amber-400" bg="bg-amber-500/10" />
          <StatBox label="Failed" value={stats.fail} color="text-red-400" bg="bg-red-500/10" />
          <StatBox label="Pending" value={stats.pending} color="text-gray-400" bg="bg-gray-500/10" />
        </div>
      </div>

      {/* Checks by category */}
      {Object.entries(CATEGORY_ICONS).map(([cat, CatIcon]) => {
        const catChecks = checks.filter(c => c.category === cat)
        if (catChecks.length === 0) return null

        return (
          <div key={cat} className="card p-4">
            <div className="flex items-center gap-2 mb-3">
              <CatIcon className="w-4 h-4 text-[var(--accent)]" />
              <span className="text-xs font-semibold text-[var(--text-primary)] uppercase tracking-wider">
                {cat}
              </span>
            </div>
            <div className="space-y-2">
              {catChecks.map(check => {
                const cfg = STATUS_CONFIG[check.status]
                const StatusIcon = cfg.icon
                return (
                  <div
                    key={check.id}
                    className={`flex items-start gap-3 p-2.5 rounded-lg border ${cfg.bg} ${cfg.border}`}
                  >
                    <StatusIcon className={`w-4 h-4 ${cfg.color} shrink-0 mt-0.5 ${check.status === 'pending' ? 'animate-spin' : ''}`} />
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="text-xs font-medium text-[var(--text-primary)]">{check.name}</span>
                        <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded ${cfg.bg} ${cfg.color}`}>
                          {cfg.label}
                        </span>
                        {check.count != null && check.count > 0 && (
                          <span className="text-[9px] text-gray-500">({check.count})</span>
                        )}
                      </div>
                      <p className="text-[11px] text-gray-400 mt-0.5">{check.message}</p>
                      {check.details && (
                        <p className="text-[10px] text-gray-600 mt-0.5">{check.details}</p>
                      )}
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        )
      })}

      {/* Overall verdict */}
      {checks.length > 0 && (
        <div className={`card p-4 ${
          overallStatus === 'pass' ? 'border-emerald-500/30' :
          overallStatus === 'warning' ? 'border-amber-500/30' :
          'border-red-500/30'
        }`}>
          <div className="flex items-center gap-2">
            {overallStatus === 'pass' && <CheckCircle2 className="w-5 h-5 text-emerald-400" />}
            {overallStatus === 'warning' && <AlertTriangle className="w-5 h-5 text-amber-400" />}
            {overallStatus === 'fail' && <AlertCircle className="w-5 h-5 text-red-400" />}
            <div>
              <span className={`text-sm font-bold ${
                overallStatus === 'pass' ? 'text-emerald-400' :
                overallStatus === 'warning' ? 'text-amber-400' :
                'text-red-400'
              }`}>
                {overallStatus === 'pass' ? 'READY FOR SUBMISSION' :
                 overallStatus === 'warning' ? 'READY WITH WARNINGS' :
                 'NOT READY — FIX ERRORS'}
              </span>
              <p className="text-[10px] text-gray-500 mt-0.5">
                {stats.fail > 0 ? `${stats.fail} error(s) must be fixed before registry submission` :
                 stats.warning > 0 ? `${stats.warning} warning(s) — review recommended` :
                 'All quality checks passed'}
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

function StatBox({ label, value, color, bg }: { label: string; value: number; color: string; bg: string }) {
  return (
    <div className={`p-2 rounded-lg ${bg} border border-white/[0.04] text-center`}>
      <div className={`text-lg font-bold ${color}`}>{value}</div>
      <div className="text-[9px] text-gray-500 uppercase tracking-wider">{label}</div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import DeedPlanGenerator from '@/components/deedplan/DeedPlanGenerator'
import type { BoundaryPoint } from '@/types/deedPlan'
import type { BeaconType, BeaconStatus } from '@/types/deedPlan'

/**
 * ProjectDeedPlan — wrapper that connects DeedPlanGenerator to a real project.
 *
 * Fetches the project's survey points from /api/project/[id]/points and
 * converts them to BoundaryPoint[] format for DeedPlanGenerator's initialPoints.
 *
 * This is the "missing wire" — previously the deed plan page used
 * projectId="new" with no project data. Now a surveyor can:
 * 1. Run traverse adjustment in their project
 * 2. Go to the deed plan step
 * 3. See their adjusted coordinates auto-populated
 *
 * Usage:
 *   <ProjectDeedPlan projectId="abc-123" />
 *   // or as a route: /deed-plan?project=abc-123
 */

interface ProjectDeedPlanProps {
  projectId: string
}

interface SurveyPoint {
  id: string
  point_name: string
  easting: number
  northing: number
  elevation: number | null
  code: string | null
  description: string | null
  is_control: boolean
}

// Default beacon type/status when converting survey points to boundary points
const DEFAULT_MARK_TYPE: BeaconType = 'CONCRETE_BEACON'
const DEFAULT_MARK_STATUS: BeaconStatus = 'SET'

function surveyPointToBoundaryPoint(p: SurveyPoint): BoundaryPoint {
  return {
    id: p.point_name || p.id,
    easting: p.easting,
    northing: p.northing,
    elevation: p.elevation ?? undefined,
    markType: DEFAULT_MARK_TYPE,
    markStatus: DEFAULT_MARK_STATUS,
    description: p.description || p.code || undefined,
  }
}

export default function ProjectDeedPlan({ projectId }: ProjectDeedPlanProps) {
  const [points, setPoints] = useState<BoundaryPoint[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false

    async function fetchPoints() {
      try {
        setLoading(true)
        setError(null)
        const res = await fetch(`/api/project/${projectId}/points`)
        if (!res.ok) {
          throw new Error(`Failed to load project points (${res.status})`)
        }
        const json = await res.json() as { data?: SurveyPoint[] }
        const surveyPoints: SurveyPoint[] = json.data || []
        const boundaryPoints = surveyPoints.map(surveyPointToBoundaryPoint)
        if (!cancelled) {
          setPoints(boundaryPoints)
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : 'Failed to load project points')
        }
      } finally {
        if (!cancelled) {
          setLoading(false)
        }
      }
    }

    if (projectId && projectId !== 'new') {
      fetchPoints()
    } else {
      setLoading(false)
    }

    return () => {
      cancelled = true
    }
  }, [projectId])

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-12">
        <div className="font-mono text-xs text-[var(--text-muted)] tracking-[0.04em] uppercase">
          Loading project coordinates...
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-12">
        <div className="border border-[var(--error)]/30 bg-[var(--error)]/5 p-4 rounded-md">
          <p className="font-mono text-xs text-[var(--error)] tracking-[0.04em] uppercase mb-2">
            Could not load project points
          </p>
          <p className="text-sm text-[var(--text-secondary)] mb-4">{error}</p>
          <p className="text-xs text-[var(--text-muted)]">
            You can still create a deed plan manually — your project coordinates
            will not be auto-populated.
          </p>
        </div>
        <div className="mt-6">
          <DeedPlanGenerator projectId={projectId} initialPoints={[]} />
        </div>
      </div>
    )
  }

  return (
    <div>
      {points.length > 0 && (
        <div className="max-w-7xl mx-auto px-4 mb-4">
          <div className="border border-[var(--accent)]/30 bg-[var(--accent)]/5 p-3 rounded-md flex items-center gap-3">
            <svg className="w-4 h-4 text-[var(--accent)] shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <p className="text-xs text-[var(--text-secondary)]">
              <span className="font-mono text-[var(--accent)]">{points.length} points</span>{' '}
              auto-populated from project survey data. Adjust beacon types and statuses
              below before generating the plan.
            </p>
          </div>
        </div>
      )}
      <DeedPlanGenerator projectId={projectId} initialPoints={points} />
    </div>
  )
}

'use client';

/**
 * LogoUpload Component
 *
 * Drag & drop or click to upload company logo.
 * - Shows plan restriction for free users (upgrade CTA)
 * - Preview current logo
 * - Remove logo button
 * - Validates: max 2MB, PNG/JPG/SVG only
 * - Crop/resize to fit document header (max 200x60px in document)
 */

import { useCallback, useRef, useState } from 'react';
import type { PlanId } from '@/lib/subscription/catalog';
import SubscriptionBadge from '@/components/SubscriptionBadge';
import { logger } from '@/lib/logger'

interface LogoInfo {
  id: string;
  filename: string;
  mimeType: string;
  fileSize: number;
  widthPx?: number;
  heightPx?: number;
  createdAt: string;
}

interface LogoUploadProps {
  /** Current plan of the user */
  plan: PlanId;
  /** Existing logo (if any), fetched server-side */
  existingLogo?: LogoInfo | null;
  /** Callback after successful upload */
  onUploadSuccess?: (logo: LogoInfo) => void;
  /** Callback after successful delete */
  onDeleteSuccess?: () => void;
}

const MAX_FILE_SIZE = 2 * 1024 * 1024; // 2MB
const ALLOWED_TYPES = ['image/png', 'image/jpeg', 'image/svg+xml'];
const ALLOWED_EXTENSIONS = '.png, .jpg, .jpeg, .svg';

export default function LogoUpload({
  plan,
  existingLogo,
  onUploadSuccess,
  onDeleteSuccess,
}: LogoUploadProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [logo, setLogo] = useState<LogoInfo | null>(existingLogo ?? null);
  const [preview, setPreview] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isFree = plan === 'free';

  // Read file and create preview
  const processFile = useCallback((file: File) => {
    setError(null);

    if (!ALLOWED_TYPES.includes(file.type)) {
      setError(`Invalid format. Allowed: ${ALLOWED_EXTENSIONS}`);
      return;
    }

    if (file.size > MAX_FILE_SIZE) {
      setError('File too large. Maximum size: 2MB.');
      return;
    }

    // Create preview URL
    const reader = new FileReader();
    reader.onload = (e) => {
      setPreview(e.target?.result as string);
    };
    reader.readAsDataURL(file);

    // Upload the file
    uploadLogo(file);
  }, []);

  const uploadLogo = async (file: File) => {
    setUploading(true);
    setError(null);

    try {
      const formData = new FormData();
      formData.append('logo', file);

      const res = await fetch('/api/documents/logo', {
        method: 'POST',
        body: formData,
      });

      const data = (await res.json()) as { upgradeRequired?: boolean; error?: string };

      if (!res.ok) {
        if (data.upgradeRequired) {
          setError('Upgrade to Pro or higher to upload your company logo.');
        } else {
          setError(data.error || 'Upload failed');
        }
        setPreview(null);
        return;
      }

      // Fetch the updated logo metadata
      const metaRes = await fetch('/api/documents/logo');
      const metaData = (await metaRes.json()) as { logo?: LogoInfo };

      if (metaData.logo) {
        setLogo(metaData.logo);
        onUploadSuccess?.(metaData.logo);
      }
    } catch (err) {
      logger.error('[LogoUpload] Upload error:', { error: err });
      setError('Upload failed. Please try again.');
      setPreview(null);
    } finally {
      setUploading(false);
    }
  };

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      setDragOver(false);

      if (isFree) return;

      const file = e.dataTransfer.files[0];
      if (file) processFile(file);
    },
    [isFree, processFile]
  );

  const handleDragOver = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      if (!isFree) setDragOver(true);
    },
    [isFree]
  );

  const handleDragLeave = useCallback(() => {
    setDragOver(false);
  }, []);

  const handleFileChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) processFile(file);
    },
    [processFile]
  );

  const handleDelete = async () => {
    setDeleting(true);
    setError(null);

    try {
      const res = await fetch('/api/documents/logo', { method: 'DELETE' });

      if (!res.ok) {
        const data = (await res.json()) as { error?: string };
        setError(data.error || 'Delete failed');
        return;
      }

      setLogo(null);
      setPreview(null);
      onDeleteSuccess?.();
    } catch (err) {
      logger.error('[LogoUpload] Delete error:', { error: err });
      setError('Delete failed. Please try again.');
    } finally {
      setDeleting(false);
    }
  };

  const formatFileSize = (bytes: number): string => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  // ─── Free tier: locked state ─────────────────────────────────────
  if (isFree) {
    return (
      <div className="rounded-lg border border-dashed border-[var(--border-color)] p-6 text-center">
        <div className="flex items-center justify-center gap-2 mb-3">
          <svg
            className="w-8 h-8 text-[var(--text-secondary)]"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
            aria-hidden="true"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={1.5}
              d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
            />
          </svg>
          <SubscriptionBadge plan={plan} compact />
        </div>
        <p className="text-sm text-[var(--text-secondary)] mb-2">
          Custom company logos are available on Pro and higher plans.
        </p>
        <p className="text-xs text-[var(--text-tertiary)] mb-4">
          Free tier documents use the METARDU watermark.
        </p>
        <a
          href="/pricing"
          className="inline-flex items-center gap-1 px-4 py-2 text-sm font-semibold rounded-lg bg-emerald-600 text-white hover:bg-emerald-700 transition-colors"
        >
          Upgrade to Pro
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
        </a>
      </div>
    );
  }

  // ─── Paid tier: upload interface ──────────────────────────────────
  const displaySrc = preview || (logo ? `/api/documents/logo/data` : null);

  return (
    <div className="space-y-4">
      {/* Current logo preview */}
      {displaySrc && (
        <div className="flex items-center gap-4 p-4 rounded-lg bg-[var(--bg-secondary)] border border-[var(--border-color)]">
          <div className="flex-shrink-0 w-[200px] h-[60px] bg-white rounded border border-gray-200 flex items-center justify-center overflow-hidden">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={displaySrc}
              alt="Company logo preview"
              className="max-w-full max-h-full object-contain"
              style={{ maxWidth: '200px', maxHeight: '60px' }}
            />
          </div>
          <div className="flex-1 min-w-0">
            {logo && (
              <div className="text-sm">
                <p className="font-medium truncate">{logo.filename}</p>
                <p className="text-xs text-[var(--text-secondary)]">
                  {formatFileSize(logo.fileSize)}
                  {logo.widthPx && logo.heightPx && (
                    <> &middot; {logo.widthPx}×{logo.heightPx}px</>
                  )}
                </p>
              </div>
            )}
            <p className="text-xs text-[var(--text-tertiary)] mt-1">
              Document size: 200×60px max
            </p>
          </div>
          <button
            type="button"
            onClick={handleDelete}
            disabled={deleting}
            className="flex-shrink-0 px-3 py-1.5 text-sm rounded-md border border-red-300 text-red-600 hover:bg-red-50 dark:hover:bg-red-950/30 transition-colors disabled:opacity-50"
          >
            {deleting ? 'Removing…' : 'Remove'}
          </button>
        </div>
      )}

      {/* Drop zone */}
      {!displaySrc && (
        <div
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onClick={() => fileInputRef.current?.click()}
          className={`
            rounded-lg border-2 border-dashed p-8 text-center cursor-pointer transition-colors
            ${dragOver
              ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-950/20'
              : 'border-[var(--border-color)] hover:border-emerald-400 hover:bg-[var(--bg-secondary)]'
            }
          `}
          role="button"
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              fileInputRef.current?.click();
            }
          }}
          aria-label="Upload company logo"
        >
          <svg
            className="w-10 h-10 mx-auto text-[var(--text-secondary)] mb-3"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
            aria-hidden="true"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={1.5}
              d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
            />
          </svg>
          <p className="text-sm font-medium text-[var(--text-primary)]">
            {uploading ? 'Uploading…' : 'Drop your logo here or click to browse'}
          </p>
          <p className="text-xs text-[var(--text-secondary)] mt-1">
            PNG, JPG, or SVG &middot; Max 2MB
          </p>
        </div>
      )}

      {/* Change logo link when logo exists */}
      {displaySrc && (
        <button
          type="button"
          onClick={() => fileInputRef.current?.click()}
          disabled={uploading}
          className="text-sm text-emerald-600 hover:text-emerald-700 font-medium disabled:opacity-50"
        >
          {uploading ? 'Uploading…' : 'Change logo'}
        </button>
      )}

      {/* Hidden file input */}
      <input
        ref={fileInputRef}
        type="file"
        accept={ALLOWED_EXTENSIONS}
        onChange={handleFileChange}
        className="hidden"
        aria-hidden="true"
      />

      {/* Error display */}
      {error && (
        <div className="flex items-start gap-2 p-3 rounded-md bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-800">
          <svg
            className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
            aria-hidden="true"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
          <p className="text-sm text-red-700 dark:text-red-400">{error}</p>
        </div>
      )}
    </div>
  );
}

'use client'

/**
 * VersionHistory — Survey plan version tracking with diff viewer
 *
 * Features:
 * - Shows chronological list of document/plan versions
 * - Compare two versions side-by-side
 * - Highlights what changed (added/removed/modified fields)
 * - Restore previous version
 *
 * Each version tracks:
 * - Version number, timestamp, author
 * - What changed (area, boundaries, beacons, surveyor)
 * - PDF preview link
 */

import { useState, useMemo, useCallback } from 'react'
import {
  History, GitBranch, FileText, Clock, Check, X,
  ArrowRight, Loader2, Download, RotateCcw, Eye,
  Plus, Minus, Edit3,
} from 'lucide-react'

export interface PlanVersion {
  id: string
  versionNumber: number
  timestamp: string
  author: string
  changes: string[]
  // Document data at this version
  data: {
    parcelNumber?: string
    areaHectares?: number
    surveyorName?: string
    surveyorLicense?: string
    beaconCount?: number
    boundaryLength?: number
    status?: string
  }
  pdfUrl?: string
}

interface VersionHistoryProps {
  versions: PlanVersion[]
  onRestore?: (version: PlanVersion) => void
}

export function VersionHistory({ versions, onRestore }: VersionHistoryProps) {
  const [selectedVersions, setSelectedVersions] = useState<[string | null, string | null]>([null, null])
  const [showDiff, setShowDiff] = useState(false)

  const sortedVersions = useMemo(() =>
    [...versions].sort((a, b) => b.versionNumber - a.versionNumber),
    [versions]
  )

  const handleSelect = useCallback((id: string) => {
    setSelectedVersions(prev => {
      if (prev[0] === null) return [id, null]
      if (prev[1] === null && prev[0] !== id) return [prev[0], id]
      if (prev[0] === id) return [null, prev[1]]
      if (prev[1] === id) return [prev[0], null]
      return [id, null]
    })
  }, [])

  const canCompare = selectedVersions[0] && selectedVersions[1]

  const v1 = sortedVersions.find(v => v.id === selectedVersions[0])
  const v2 = sortedVersions.find(v => v.id === selectedVersions[1])

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="card p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
              <History className="w-4 h-4 text-[var(--accent)]" />
            </div>
            <div>
              <h2 className="text-sm font-semibold text-[var(--text-primary)]">Version History</h2>
              <p className="text-[10px] text-gray-500">{versions.length} versions — select 2 to compare</p>
            </div>
          </div>
          {canCompare && (
            <button
              onClick={() => setShowDiff(!showDiff)}
              className="flex items-center gap-1.5 px-3 h-8 rounded-lg bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)] text-xs font-medium hover:bg-[var(--accent)]/20"
            >
              <GitBranch className="w-3.5 h-3.5" />
              {showDiff ? 'Hide Diff' : 'Compare'}
            </button>
          )}
        </div>
      </div>

      {/* Diff viewer */}
      {showDiff && v1 && v2 && (
        <VersionDiff v1={v1} v2={v2} />
      )}

      {/* Version list */}
      <div className="card p-4">
        {sortedVersions.length === 0 ? (
          <div className="text-center py-8">
            <History className="w-8 h-8 text-gray-600 mx-auto mb-2" />
            <p className="text-sm text-gray-500">No version history yet</p>
            <p className="text-[10px] text-gray-600 mt-1">Versions are created when you save changes to a plan.</p>
          </div>
        ) : (
          <div className="space-y-2">
            {sortedVersions.map((version, idx) => {
              const isSelected = selectedVersions.includes(version.id)
              const isLatest = idx === 0
              return (
                <div
                  key={version.id}
                  onClick={() => handleSelect(version.id)}
                  className={`flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-all ${
                    isSelected
                      ? 'border-[var(--accent)]/30 bg-[var(--accent)]/5'
                      : 'border-[var(--border-color)] hover:border-[var(--accent)]/20'
                  }`}
                >
                  {/* Version badge */}
                  <div className={`shrink-0 w-10 h-10 rounded-lg flex items-center justify-center ${
                    isLatest ? 'bg-emerald-500/10' : 'bg-[var(--bg-tertiary)]'
                  }`}>
                    <span className={`text-xs font-bold ${isLatest ? 'text-emerald-400' : 'text-gray-400'}`}>
                      v{version.versionNumber}
                    </span>
                  </div>

                  {/* Content */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      {isLatest && (
                        <span className="text-[9px] px-1.5 py-0.5 rounded bg-emerald-500/10 text-emerald-400 font-medium uppercase">
                          Current
                        </span>
                      )}
                      <span className="text-xs font-medium text-[var(--text-primary)]">
                        {version.author}
                      </span>
                      <span className="text-[10px] text-gray-500 flex items-center gap-0.5">
                        <Clock className="w-2.5 h-2.5" />
                        {new Date(version.timestamp).toLocaleDateString('en-KE', {
                          month: 'short', day: 'numeric', year: 'numeric',
                          hour: '2-digit', minute: '2-digit',
                        })}
                      </span>
                    </div>

                    {/* Changes */}
                    {version.changes.length > 0 && (
                      <div className="mt-1 space-y-0.5">
                        {version.changes.map((change, i) => (
                          <div key={`${change}-${i}`} className="flex items-center gap-1 text-[10px] text-gray-500">
                            <Edit3 className="w-2.5 h-2.5 text-gray-600" />
                            {change}
                          </div>
                        ))}
                      </div>
                    )}

                    {/* Data summary */}
                    <div className="flex items-center gap-3 mt-1.5 text-[10px] text-gray-600">
                      {version.data.areaHectares != null && (
                        <span>{version.data.areaHectares.toFixed(4)} ha</span>
                      )}
                      {version.data.beaconCount != null && (
                        <span>{version.data.beaconCount} beacons</span>
                      )}
                      {version.data.surveyorName && (
                        <span className="truncate">{version.data.surveyorName}</span>
                      )}
                    </div>
                  </div>

                  {/* Actions */}
                  <div className="flex items-center gap-1 shrink-0">
                    {version.pdfUrl && (
                      <a
                        href={version.pdfUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        onClick={e => e.stopPropagation()}
                        className="w-7 h-7 flex items-center justify-center rounded text-gray-400 hover:text-[var(--accent)]"
                        title="View PDF"
                      >
                        <Eye className="w-3.5 h-3.5" />
                      </a>
                    )}
                    {!isLatest && onRestore && (
                      <button
                        onClick={(e) => { e.stopPropagation(); onRestore(version) }}
                        className="w-7 h-7 flex items-center justify-center rounded text-gray-400 hover:text-amber-400"
                        title="Restore this version"
                      >
                        <RotateCcw className="w-3.5 h-3.5" />
                      </button>
                    )}
                    {isSelected && (
                      <Check className="w-3.5 h-3.5 text-[var(--accent)]" />
                    )}
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

// ─── Version Diff Viewer ─────────────────────────────────────────────

function VersionDiff({ v1, v2 }: { v1: PlanVersion; v2: PlanVersion }) {
  const diffs = useMemo(() => {
    const result: Array<{
      field: string
      v1Value: string
      v2Value: string
      type: 'added' | 'removed' | 'modified'
    }> = []

    const fields: Array<{ key: keyof PlanVersion['data']; label: string; format?: (v: string | number | undefined) => string }> = [
      { key: 'parcelNumber', label: 'Parcel Number' },
      { key: 'areaHectares', label: 'Area (ha)', format: (v) => (typeof v === 'number' ? v.toFixed(4) : String(v)) },
      { key: 'surveyorName', label: 'Surveyor' },
      { key: 'surveyorLicense', label: 'License' },
      { key: 'beaconCount', label: 'Beacons' },
      { key: 'boundaryLength', label: 'Boundary Length (m)', format: (v) => (typeof v === 'number' ? v.toFixed(2) : String(v)) },
      { key: 'status', label: 'Status' },
    ]

    for (const field of fields) {
      const val1 = v1.data[field.key]
      const val2 = v2.data[field.key]
      const fmt = field.format || ((v: unknown) => String(v))

      if (val1 === val2) continue

      if (val1 == null && val2 != null) {
        result.push({ field: field.label, v1Value: '—', v2Value: fmt(val2), type: 'added' })
      } else if (val1 != null && val2 == null) {
        result.push({ field: field.label, v1Value: fmt(val1), v2Value: '—', type: 'removed' })
      } else if (val1 != null && val2 != null) {
        result.push({ field: field.label, v1Value: fmt(val1), v2Value: fmt(val2), type: 'modified' })
      }
    }

    return result
  }, [v1, v2])

  // Ensure v2 is the newer version
  const newer = v2.versionNumber > v1.versionNumber ? v2 : v1
  const older = v2.versionNumber > v1.versionNumber ? v1 : v2

  return (
    <div className="card p-4">
      <div className="flex items-center gap-2 mb-3">
        <GitBranch className="w-4 h-4 text-[var(--accent)]" />
        <span className="text-sm font-semibold text-[var(--text-primary)]">
          Comparing v{older.versionNumber} → v{newer.versionNumber}
        </span>
      </div>

      {diffs.length === 0 ? (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-emerald-500/5 border border-emerald-500/20">
          <Check className="w-4 h-4 text-emerald-400" />
          <p className="text-xs text-emerald-400">No differences — versions are identical</p>
        </div>
      ) : (
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-[var(--border-color)]">
                <th className="px-3 py-2 text-left text-[9px] text-gray-500 uppercase tracking-wider">Field</th>
                <th className="px-3 py-2 text-left text-[9px] text-gray-500 uppercase tracking-wider">v{older.versionNumber}</th>
                <th className="px-3 py-2 text-left text-[9px] text-gray-500 uppercase tracking-wider">v{newer.versionNumber}</th>
                <th className="px-3 py-2 text-center text-[9px] text-gray-500 uppercase tracking-wider">Change</th>
              </tr>
            </thead>
            <tbody>
              {diffs.map((diff, i) => (
                <tr key={diff.field} className="border-b border-[var(--border-color)]/50">
                  <td className="px-3 py-2 text-xs text-[var(--text-primary)] font-medium">{diff.field}</td>
                  <td className="px-3 py-2 text-xs text-gray-400 font-mono">
                    {diff.type === 'added' ? '—' : diff.v1Value}
                  </td>
                  <td className="px-3 py-2 text-xs text-[var(--text-primary)] font-mono">
                    {diff.type === 'removed' ? '—' : diff.v2Value}
                  </td>
                  <td className="px-3 py-2 text-center">
                    {diff.type === 'added' && (
                      <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded bg-emerald-500/10 text-emerald-400 text-[9px] font-medium">
                        <Plus className="w-2.5 h-2.5" /> Added
                      </span>
                    )}
                    {diff.type === 'removed' && (
                      <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded bg-red-500/10 text-red-400 text-[9px] font-medium">
                        <Minus className="w-2.5 h-2.5" /> Removed
                      </span>
                    )}
                    {diff.type === 'modified' && (
                      <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded bg-amber-500/10 text-amber-400 text-[9px] font-medium">
                        <Edit3 className="w-2.5 h-2.5" /> Modified
                      </span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useRef, useEffect, useMemo } from 'react';
import { z } from 'zod';
import Konva from 'konva';
import { logEngineeringCompute } from '@/lib/engineering/compute';
import { initialiseDXFLayers, addStandardTitleBlock, DXF_LAYERS } from '@/lib/drawing/dxfLayers';

const CrossSectionSchema = z.object({
  stations: z.array(z.object({
    chainage: z.number(),
    groundLevel: z.number(),
    formationLevel: z.number(),
  })),
  sideSlope: z.number().min(1).default(1.5),
});

export interface CrossSectionProps {
  stations: Array<{ chainage: number; groundLevel: number; formationLevel: number }>;
  projectId?: string;
  sideSlope?: number;
  width?: number;
  height?: number;
  projectData?: {
    lr_number?: string;
    county?: string;
    district?: string;
    locality?: string;
  };
  surveyorProfile?: {
    fullName: string;
    registrationNumber: string;
    firmName: string;
  } | null;
}

export function CrossSection({
  stations,
  projectId,
  sideSlope = 1.5,
  width = 920,
  height = 520,
  projectData,
  surveyorProfile,
}: CrossSectionProps) {
  const [selectedStation, setSelectedStation] = useState<number | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const validated = useMemo(() => {
    try {
      return CrossSectionSchema.parse({ stations, sideSlope });
    } catch {
      return null;
    }
  }, [stations, sideSlope]);

  const sections = useMemo(() => {
    if (!validated) return [];
    
    return validated.stations.map((station, i) => {
      const prev = validated.stations[i - 1];
      if (!prev) return { ...station, cutFillArea: 0, cutVolume: 0, fillVolume: 0 };

      const leftCut = Math.max(0, prev.groundLevel - prev.formationLevel);
      const rightCut = Math.max(0, station.groundLevel - station.formationLevel);

      const area = ((leftCut + rightCut) / 2) * (station.chainage - prev.chainage);
      const cutVolume = Math.max(0, area);
      const fillVolume = Math.max(0, -area);

      return { 
        ...station, 
        cutFillArea: area, 
        cutVolume, 
        fillVolume 
      };
    });
  }, [validated]);

  const totalCut = useMemo(() => sections.reduce((sum, s) => sum + s.cutVolume, 0), [sections]);
  const totalFill = useMemo(() => sections.reduce((sum, s) => sum + s.fillVolume, 0), [sections]);

  useEffect(() => {
    if (!containerRef.current || stations.length === 0 || !validated) return;

    const stage = new Konva.Stage({
      container: containerRef.current,
      width,
      height,
    });
    const layer = new Konva.Layer();
    stage.add(layer);

    const spacing = width / stations.length;
    const baseLevel = 1600;
    const vScale = 8;

    stations.forEach((station, i) => {
      const x = spacing * i + spacing / 2;
      const groundY = height / 2 - (station.groundLevel - baseLevel) * vScale;
      const formationY = height / 2 - (station.formationLevel - baseLevel) * vScale;

      layer.add(new Konva.Line({
        points: [x - 40, groundY, x + 40, groundY],
        stroke: '#22c55e',
        strokeWidth: 3,
      }));

      layer.add(new Konva.Line({
        points: [x - 40, formationY, x + 40, formationY],
        stroke: '#eab308',
        strokeWidth: 3,
      }));

      const slopeOffset = 40 / sideSlope;
      layer.add(new Konva.Line({
        points: [x - 40, groundY, x - 40 - slopeOffset, formationY],
        stroke: '#666',
        strokeWidth: 2,
      }));
      layer.add(new Konva.Line({
        points: [x + 40, groundY, x + 40 + slopeOffset, formationY],
        stroke: '#666',
        strokeWidth: 2,
      }));

      layer.add(new Konva.Text({
        x: x - 25,
        y: height - 40,
        text: `CH ${station.chainage.toFixed(0)}`,
        fontSize: 11,
        fill: '#aaa',
      }));
    });

    layer.draw();
    return () => {
      stage.destroy();
    };
  }, [stations, sideSlope, width, height, validated]);

  const exportBatchDXF = async () => {
    const { default: Drawing } = await import('dxf-writer');
    const drawing = new Drawing();
    initialiseDXFLayers(drawing);

    addStandardTitleBlock(drawing, {
      drawingTitle: 'CROSS SECTION SURVEY',
      lrNumber: projectData?.lr_number ?? 'N/A',
      county: projectData?.county ?? 'N/A',
      district: projectData?.district ?? 'N/A',
      locality: projectData?.locality ?? 'N/A',
      areaHa: 0,
      perimeterM: 0,
      surveyorName: surveyorProfile?.fullName ?? 'N/A',
      registrationNumber: surveyorProfile?.registrationNumber ?? 'N/A',
      firmName: surveyorProfile?.firmName ?? 'N/A',
      date: new Date().toLocaleDateString('en-KE'),
      submissionRef: 'N/A',
      coordinateSystem: 'Arc 1960 / UTM Zone 37S (SRID: 21037)',
      scale: '1:2500',
      sheetNumber: '1 of 1',
      revision: 'R00',
    });

    const baseLevel = 1600;
    const hScale = 1 / 100;
    const vScale = 1 / 100;

    sections.forEach((station, i) => {
      const xOffset = i * 50;
      const groundY = (station.groundLevel - baseLevel) * vScale;
      const formationY = (station.formationLevel - baseLevel) * vScale;

      drawing.setActiveLayer(DXF_LAYERS.PROFILE.name);
      drawing.drawLine(
        xOffset, groundY,
        xOffset + 20, groundY
      );

      drawing.setActiveLayer(DXF_LAYERS.CENTRELINE.name);
      drawing.drawLine(
        xOffset, formationY,
        xOffset + 20, formationY
      );

      drawing.setActiveLayer(DXF_LAYERS.CHAIN.name);
      drawing.drawText(
        xOffset, groundY + 1,
        0.15, 0,
        `CH${station.chainage.toFixed(0)}`
      );
    });

    logEngineeringCompute('cross_section_batch', { stations: stations.length, sideSlope },
      { totalCut, totalFill }, { projectId });

    const dxfString = drawing.toDxfString();
    const blob = new Blob([dxfString], { type: 'application/dxf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `cross_sections_batch_${projectId || 'export'}.dxf`;
    a.click();
    URL.revokeObjectURL(url);
  };

  if (!validated) {
    return <div className="p-4 text-red-400">Invalid cross-section data</div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h3 className="text-lg font-semibold text-[var(--text-primary)]">Cross-Section Batch Renderer</h3>
        <button
          onClick={exportBatchDXF}
          className="bg-orange-500 hover:bg-orange-600 px-5 py-2 rounded-lg text-white text-sm font-medium flex items-center gap-2"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
          </svg>
          Export All Stations to DXF
        </button>
      </div>

      <div ref={containerRef} className="bg-[#111] rounded-xl overflow-hidden border border-[var(--border-color)]" />

      <div className="overflow-x-auto border border-[var(--border-color)] rounded-xl">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-[var(--bg-secondary)]">
              <th className="text-left py-3 px-6 text-[var(--text-muted)]">Chainage</th>
              <th className="text-right py-3 px-6 text-[var(--text-muted)]">Ground RL</th>
              <th className="text-right py-3 px-6 text-[var(--text-muted)]">Formation RL</th>
              <th className="text-right py-3 px-6 text-[var(--text-muted)]">Cut (m³)</th>
              <th className="text-right py-3 px-6 text-[var(--text-muted)]">Fill (m³)</th>
            </tr>
          </thead>
          <tbody>
            {sections.map((s, i) => (
              <tr key={`${s}-${i}`} 
                className="border-t border-[var(--border-color)] hover:bg-[var(--bg-secondary)] cursor-pointer"
                onClick={() => setSelectedStation(i)}
              >
                <td className="py-3 px-6 font-medium">{s.chainage.toFixed(0)}</td>
                <td className="py-3 px-6 text-right">{s.groundLevel.toFixed(3)}</td>
                <td className="py-3 px-6 text-right">{s.formationLevel.toFixed(3)}</td>
                <td className="py-3 px-6 text-right text-red-400">{s.cutVolume.toFixed(2)}</td>
                <td className="py-3 px-6 text-right text-green-400">{s.fillVolume.toFixed(2)}</td>
              </tr>
            ))}
          </tbody>
          {sections.length > 0 && (
            <tfoot>
              <tr className="bg-[var(--bg-secondary)] font-semibold">
                <td className="py-3 px-6">Total</td>
                <td></td>
                <td></td>
                <td className="py-3 px-6 text-right text-red-400">{totalCut.toFixed(2)}</td>
                <td className="py-3 px-6 text-right text-green-400">{totalFill.toFixed(2)}</td>
              </tr>
            </tfoot>
          )}
        </table>
      </div>

      <div className="text-xs text-[var(--text-muted)]">
        Side slope 1:{sideSlope} • Prismoidal + end-area method • RDM 1.1 compliant
      </div>
    </div>
  );
}

'use client';

import { useMemo } from 'react'
import dynamic from 'next/dynamic'
import type { CanvasPoint, CanvasLine } from './CoordinateCanvas'
import type { SubmissionPackage } from '@/lib/submission/types'

import { formatPlanDate, formatBearingDMS, formatDistanceM } from '@/lib/drawing/dxfLayers'

const CoordinateCanvas = dynamic(() => import('./CoordinateCanvas').then(m => ({ default: m.CoordinateCanvas })), {
  ssr: false,
  loading: () => <div className="animate-pulse bg-gray-200 rounded h-64" />,
})

interface FormNo4PreviewProps {
  pkg: SubmissionPackage
  width?: number
  height?: number
}

function formatPlanDateLocal(date: string): string {
  return formatPlanDate(date)
}

export function FormNo4Preview({
  pkg,
  width = 800,
  height = 600
}: FormNo4PreviewProps) {
  const adjustedAreaHa = pkg.traverse.areaM2 / 10000
  const scale = useMemo(() => {
    const pts = pkg.traverse.points
    if (pts.length < 2) return 2500
    let minE = Infinity, maxE = -Infinity, minN = Infinity, maxN = -Infinity
    pts.forEach(p => {
      minE = Math.min(minE, p.adjustedEasting)
      maxE = Math.max(maxE, p.adjustedEasting)
      minN = Math.min(minN, p.adjustedNorthing)
      maxN = Math.max(maxN, p.adjustedNorthing)
    })
    const w = maxE - minE, h = maxN - minN
    const scales = [500, 1000, 2500, 5000, 10000, 25000]
    for (const s of scales) {
      if (w / s <= 0.315 && h / s <= 0.222) return s
    }
    return 25000
  }, [pkg.traverse.points])

  const { points, lines } = useMemo(() => {
    const pts: CanvasPoint[] = pkg.traverse.points.map(p => ({
      id: p.pointName,
      name: p.pointName,
      easting: p.adjustedEasting,
      northing: p.adjustedNorthing,
      type: 'beacon' as const
    }))

    const lns: CanvasLine[] = pts.map((pt, i) => ({
      from: pt.id,
      to: pts[(i + 1) % pts.length].id,
      style: 'solid' as const
    }))

    return { points: pts, lines: lns }
  }, [pkg])

  const legs = useMemo(() => {
    return pkg.traverse.points.map((from, i) => {
      const to = pkg.traverse.points[(i + 1) % pkg.traverse.points.length]
      const dE = to.adjustedEasting - from.adjustedEasting
      const dN = to.adjustedNorthing - from.adjustedNorthing
      let bearing = Math.atan2(dE, dN) * (180 / Math.PI)
      if (bearing < 0) bearing += 360
      const distance = Math.sqrt(dE * dE + dN * dN)
      return {
        from: from.pointName,
        to: to.pointName,
        bearing,
        distance,
        midE: (from.adjustedEasting + to.adjustedEasting) / 2,
        midN: (from.adjustedNorthing + to.adjustedNorthing) / 2
      }
    })
  }, [pkg.traverse.points])

  return (
    <div className="space-y-3">
      <div className="bg-[#1a1a1a] border rounded-t-lg px-4 py-3 flex items-center justify-between text-sm">
        <div>
          <p className="font-semibold">FORM NO. 4 — SURVEY PLAN</p>
          <p className="text-[var(--text-muted)] text-xs mt-0.5">
            LR No: {pkg.parcel.lrNumber} · Parcel No: {pkg.parcel.parcelNumber || pkg.parcel.lrNumber}
          </p>
          <p className="text-[var(--text-muted)] text-xs">
            {pkg.parcel.county} · {pkg.parcel.division || '-'} · {pkg.parcel.district}
          </p>
        </div>
        <div className="text-right text-xs text-[var(--text-muted)]">
          <p>{pkg.surveyor.fullName}</p>
          <p>ISK No: {pkg.surveyor.iskNumber || pkg.surveyor.registrationNumber}</p>
          <p>{pkg.surveyor.firmName}</p>
          <p>Date: {formatPlanDateLocal(pkg.generatedAt)}</p>
        </div>
      </div>

      <CoordinateCanvas
        points={points}
        lines={lines}
        width={width}
        height={height}
        showNorthArrow
        showScaleBar
        showGrid
        showAreaAnnotation
        areaAnnotation={`Area = ${adjustedAreaHa.toFixed(4)} Ha`}
        legs={legs.map(l => ({
          from: l.from,
          to: l.to,
          bearing: l.bearing,
          distance: l.distance,
          midX: l.midE,
          midY: l.midN
        }))}
      />

      <div className="bg-[#1a1a1a] border rounded-b-lg px-4 py-3 grid grid-cols-4 gap-4 text-sm">
        <div>
          <p className="text-[var(--text-muted)] text-xs">Area</p>
          <p className="font-medium">{adjustedAreaHa.toFixed(4)} Ha</p>
          <p className="text-[var(--text-muted)] text-xs">{pkg.traverse.areaM2.toFixed(2)} m²</p>
        </div>
        <div>
          <p className="text-[var(--text-muted)] text-xs">Perimeter</p>
          <p className="font-medium">{pkg.traverse.perimeterM.toFixed(3)} m</p>
        </div>
        <div>
          <p className="text-[var(--text-muted)] text-xs">Scale</p>
          <p className="font-medium">1:{scale}</p>
        </div>
        <div>
          <p className="text-[var(--text-muted)] text-xs">Ref</p>
          <p className="font-medium">{pkg.submissionRef}</p>
          <p className="text-[var(--text-muted)] text-xs">R{pkg.revision.toString().padStart(2, '0')}</p>
        </div>
        {pkg.scaleFactor && (
          <div>
            <p className="text-[var(--text-muted)] text-xs">Scale Factor</p>
            <p className="font-medium">{pkg.scaleFactor.toFixed(6)}</p>
          </div>
        )}
        {pkg.meanElevation != null && (
          <div>
            <p className="text-[var(--text-muted)] text-xs">Mean Elevation</p>
            <p className="font-medium">{pkg.meanElevation.toFixed(2)} m</p>
          </div>
        )}
        {pkg.controlClass && (
          <div>
            <p className="text-[var(--text-muted)] text-xs">Control Class</p>
            <p className="font-medium">{pkg.controlClass} Order</p>
          </div>
        )}
      </div>
    </div>
  )
}

'use client';

import { useEffect, useRef, useMemo, useState } from 'react'
import Konva from 'konva'
import { logEngineeringCompute } from '@/lib/engineering/compute'
import { initialiseDXFLayers, addStandardTitleBlock, DXF_LAYERS } from '@/lib/drawing/dxfLayers'

export interface ProfilePoint {
  chainage: number
  groundLevel: number
  formationLevel?: number
}

export interface StationLevel {
  chainage: number
  groundLevel: number
  formationLevel: number
  cut: number
  fill: number
}

interface LongitudinalSectionProps {
  points: ProfilePoint[]
  title?: string
  hScale?: number
  vScale?: number
  width?: number
  height?: number
  showTable?: boolean
  projectId?: string
  editable?: boolean
  projectData?: {
    lr_number?: string;
    county?: string;
    district?: string;
    locality?: string;
  };
  surveyorProfile?: {
    fullName: string;
    registrationNumber: string;
    firmName: string;
  } | null;
}

export function LongitudinalSection({
  points,
  title = 'LONGITUDINAL SECTION',
  hScale = 2000,
  vScale = 200,
  width = 900,
  height = 500,
  showTable = false,
  projectId,
  editable = false,
  projectData,
  surveyorProfile,
}: LongitudinalSectionProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const [designLevels, setDesignLevels] = useState<number[]>(
    points.map(p => p.formationLevel ?? p.groundLevel)
  )

  const pointsWithDesign = useMemo(() => {
    return points.map((p, i) => ({
      ...p,
      formationLevel: designLevels[i]
    }))
  }, [points, designLevels])

  const stationLevels: StationLevel[] = useMemo(() => {
    return pointsWithDesign.map(p => ({
      chainage: p.chainage,
      groundLevel: p.groundLevel,
      formationLevel: p.formationLevel ?? p.groundLevel,
      cut: p.formationLevel != null ? Math.max(0, p.groundLevel - p.formationLevel) : 0,
      fill: p.formationLevel != null ? Math.max(0, p.formationLevel - p.groundLevel) : 0
    }))
  }, [pointsWithDesign])

  const totalCut = useMemo(() => stationLevels.reduce((sum, s) => sum + s.cut, 0), [stationLevels])
  const totalFill = useMemo(() => stationLevels.reduce((sum, s) => sum + s.fill, 0), [stationLevels])

  useEffect(() => {
    setDesignLevels(points.map(p => p.formationLevel ?? p.groundLevel))
  }, [points])

  useEffect(() => {
    if (!containerRef.current || pointsWithDesign.length < 2) return

    const stage = new Konva.Stage({ container: containerRef.current, width, height })
    const layer = new Konva.Layer()
    stage.add(layer)

    const marginLeft = 80
    const marginRight = 40
    const marginTop = 40
    const drawHeight = height - 80

    const minCh = Math.min(...pointsWithDesign.map(p => p.chainage))
    const maxCh = Math.max(...pointsWithDesign.map(p => p.chainage))
    const minGL = Math.min(...pointsWithDesign.map(p => Math.min(p.groundLevel, p.formationLevel ?? p.groundLevel)))
    const maxGL = Math.max(...pointsWithDesign.map(p => Math.max(p.groundLevel, p.formationLevel ?? p.groundLevel)))
    const glRange = maxGL - minGL || 1

    const drawWidth = width - marginLeft - marginRight
    const chRange = maxCh - minCh || 1

    const hPPM = drawWidth / chRange
    const vPPM = drawHeight / (glRange * (hScale / vScale))

    function toCanvas(chainage: number, elevation: number) {
      return {
        x: marginLeft + (chainage - minCh) * hPPM,
        y: marginTop + drawHeight - (elevation - minGL) * vPPM * (hScale / vScale)
      }
    }

    const elevStep = 5
    const firstElev = Math.ceil(minGL / elevStep) * elevStep
    for (let el = firstElev; el <= maxGL + elevStep; el += elevStep) {
      const { y } = toCanvas(minCh, el)
      if (y < marginTop || y > marginTop + drawHeight) continue
      layer.add(new Konva.Line({
        points: [marginLeft, y, marginLeft + drawWidth, y],
        stroke: '#2a2a2a', strokeWidth: 0.5, dash: [4, 4]
      }))
      layer.add(new Konva.Text({
        x: 2, y: y - 6,
        text: `${el.toFixed(0)}`,
        fontSize: 9, fill: '#666'
      }))
    }

    layer.add(new Konva.Line({
      points: [marginLeft, marginTop, marginLeft, marginTop + drawHeight],
      stroke: '#555', strokeWidth: 1
    }))
    layer.add(new Konva.Line({
      points: [marginLeft, marginTop + drawHeight, marginLeft + drawWidth, marginTop + drawHeight],
      stroke: '#555', strokeWidth: 1
    }))

    const groundPts: number[] = []
    pointsWithDesign.forEach(p => {
      const { x, y } = toCanvas(p.chainage, p.groundLevel)
      groundPts.push(x, y)
    })
    layer.add(new Konva.Line({
      points: groundPts, stroke: '#66cc66', strokeWidth: 2
    }))

    const formationPts = pointsWithDesign.filter(p => p.formationLevel != null)
    if (formationPts.length >= 2) {
      const fPts: number[] = []
      formationPts.forEach(p => {
        const { x, y } = toCanvas(p.chainage, p.formationLevel!)
        fPts.push(x, y)
      })
      layer.add(new Konva.Line({
        points: fPts, stroke: '#e8a020', strokeWidth: 1.5, dash: [6, 3]
      }))
    }

    for (let i = 0; i < pointsWithDesign.length - 1; i++) {
      const p1 = pointsWithDesign[i]
      const p2 = pointsWithDesign[i + 1]
      if (p1.formationLevel == null || p2.formationLevel == null) continue

      const g1 = toCanvas(p1.chainage, p1.groundLevel)
      const f1 = toCanvas(p1.chainage, p1.formationLevel)
      const g2 = toCanvas(p2.chainage, p2.groundLevel)
      const f2 = toCanvas(p2.chainage, p2.formationLevel)

      const isCut = p1.groundLevel > p1.formationLevel

      layer.add(new Konva.Line({
        points: [g1.x, g1.y, g2.x, g2.y, f2.x, f2.y, f1.x, f1.y],
        closed: true,
        fill: isCut ? 'rgba(255,100,0,0.15)' : 'rgba(80,160,255,0.15)',
        stroke: 'transparent'
      }))
    }

    const tableY = marginTop + drawHeight + 10
    const chainStep = Math.ceil(chRange / 10 / 100) * 100
    for (let ch = Math.ceil(minCh / chainStep) * chainStep; ch <= maxCh; ch += chainStep) {
      const { x } = toCanvas(ch, minGL)
      layer.add(new Konva.Line({
        points: [x, marginTop, x, marginTop + drawHeight],
        stroke: '#1a1a1a', strokeWidth: 0.5
      }))
      layer.add(new Konva.Text({
        x: x - 15, y: tableY,
        text: `${ch.toFixed(0)}`,
        fontSize: 9, fill: '#888'
      }))
    }

    layer.add(new Konva.Text({
      x: marginLeft, y: 8,
      text: `${title}  |  H: 1:${hScale}  V: 1:${vScale}`,
      fontSize: 11, fill: '#aaa', fontStyle: 'bold'
    }))

    layer.add(new Konva.Line({
      points: [marginLeft, height - 15, marginLeft + 20, height - 15],
      stroke: '#66cc66', strokeWidth: 2
    }))
    layer.add(new Konva.Text({
      x: marginLeft + 24, y: height - 21,
      text: 'Ground', fontSize: 9, fill: '#66cc66'
    }))
    layer.add(new Konva.Line({
      points: [marginLeft + 80, height - 15, marginLeft + 100, height - 15],
      stroke: '#e8a020', strokeWidth: 1.5, dash: [6, 3]
    }))
    layer.add(new Konva.Text({
      x: marginLeft + 104, y: height - 21,
      text: 'Formation', fontSize: 9, fill: '#e8a020'
    }))
    layer.add(new Konva.Rect({
      x: marginLeft + 180, y: height - 19,
      width: 12, height: 8,
      fill: 'rgba(255,100,0,0.3)'
    }))
    layer.add(new Konva.Text({
      x: marginLeft + 196, y: height - 21,
      text: 'Cut', fontSize: 9, fill: '#ffaa66'
    }))
    layer.add(new Konva.Rect({
      x: marginLeft + 230, y: height - 19,
      width: 12, height: 8,
      fill: 'rgba(80,160,255,0.3)'
    }))
    layer.add(new Konva.Text({
      x: marginLeft + 246, y: height - 21,
      text: 'Fill', fontSize: 9, fill: '#66aaff'
    }))

    layer.draw()
    return () => { stage.destroy() }
  }, [pointsWithDesign, title, hScale, vScale, width, height])

  const exportDXF = async () => {
    const { default: Drawing } = await import('dxf-writer')
    const drawing = new Drawing()
    initialiseDXFLayers(drawing)

    addStandardTitleBlock(drawing, {
      drawingTitle: 'LONGITUDINAL SECTION SURVEY',
      lrNumber: projectData?.lr_number ?? 'N/A',
      county: projectData?.county ?? 'N/A',
      district: projectData?.district ?? 'N/A',
      locality: projectData?.locality ?? 'N/A',
      areaHa: 0,
      perimeterM: 0,
      surveyorName: surveyorProfile?.fullName ?? 'N/A',
      registrationNumber: surveyorProfile?.registrationNumber ?? 'N/A',
      firmName: surveyorProfile?.firmName ?? 'N/A',
      date: new Date().toLocaleDateString('en-KE'),
      submissionRef: 'N/A',
      coordinateSystem: 'Arc 1960 / UTM Zone 37S (SRID: 21037)',
      scale: '1:2500',
      sheetNumber: '1 of 1',
      revision: 'R00',
    })

    const minCh = Math.min(...pointsWithDesign.map(p => p.chainage))
    const minGL = Math.min(...pointsWithDesign.map(p => p.groundLevel))
    const hScaleFactor = 1 / hScale
    const vScaleFactor = 1 / vScale

    drawing.setActiveLayer(DXF_LAYERS.PROFILE.name)
    for (let i = 0; i < pointsWithDesign.length - 1; i++) {
      const p1 = pointsWithDesign[i]
      const p2 = pointsWithDesign[i + 1]
      drawing.drawLine(
        (p1.chainage - minCh) * hScaleFactor,
        (p1.groundLevel - minGL) * vScaleFactor,
        (p2.chainage - minCh) * hScaleFactor,
        (p2.groundLevel - minGL) * vScaleFactor
      )
    }

    const formPts = pointsWithDesign.filter(p => p.formationLevel != null)
    if (formPts.length >= 2) {
      drawing.setActiveLayer(DXF_LAYERS.CENTRELINE.name)
      for (let i = 0; i < formPts.length - 1; i++) {
        const p1 = formPts[i]
        const p2 = formPts[i + 1]
        drawing.drawLine(
          (p1.chainage - minCh) * hScaleFactor,
          (p1.formationLevel! - minGL) * vScaleFactor,
          (p2.chainage - minCh) * hScaleFactor,
          (p2.formationLevel! - minGL) * vScaleFactor
        )
      }
    }

    drawing.setActiveLayer(DXF_LAYERS.CHAIN.name)
    pointsWithDesign.forEach(p => {
      drawing.drawText(
        (p.chainage - minCh) * hScaleFactor,
        -0.005,
        0.002,
        0,
        `${p.chainage.toFixed(0)}`
      )
    })

    logEngineeringCompute('longitudinal_section', { points: pointsWithDesign.length }, 
      { totalCut, totalFill }, { projectId })

    const dxfString = drawing.toDxfString()
    const blob = new Blob([dxfString], { type: 'application/dxf' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `profile_${projectId || 'export'}.dxf`
    a.click()
    URL.revokeObjectURL(url)
  }

  const updateDesignLevel = (index: number, value: number) => {
    const newLevels = [...designLevels]
    newLevels[index] = value
    setDesignLevels(newLevels)
  }

  return (
    <div className="space-y-2">
      <div className="flex justify-between items-center">
        <div ref={containerRef} className="rounded-lg overflow-hidden bg-[#111]" style={{ width, height }} />
      </div>
      
      <div className="flex justify-end gap-2">
        <button
          onClick={exportDXF}
          className="bg-orange-500 hover:bg-orange-600 px-4 py-2 rounded-lg text-white text-sm font-medium flex items-center gap-2"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
          </svg>
          Export DXF
        </button>
      </div>

      {showTable && stationLevels.length > 0 && (
        <div className="overflow-x-auto border border-[var(--border-color)] rounded-lg">
          <div className="flex justify-between items-center px-3 py-2 bg-[var(--bg-secondary)] border-b border-[var(--border-color)]">
            <span className="text-sm font-medium">Station Levels</span>
            <div className="flex gap-4 text-xs">
              <span className="text-orange-400">Total Cut: {totalCut.toFixed(2)} m³/area</span>
              <span className="text-blue-400">Total Fill: {totalFill.toFixed(2)} m³/area</span>
            </div>
          </div>
          <table className="w-full text-sm font-mono">
            <thead>
              <tr className="border-b border-[var(--border-color)] text-[var(--text-muted)] text-xs">
                <th className="text-left py-1.5 px-3">Ch.</th>
                <th className="text-right py-1.5 px-3">G.L.</th>
                <th className="text-right py-1.5 px-3">F.L.</th>
                <th className="text-right py-1.5 px-3">Cut</th>
                <th className="text-right py-1.5 px-3">Fill</th>
              </tr>
            </thead>
            <tbody>
              {stationLevels.slice(0, 15).map((row, i) => (
                <tr key={`${row}-${i}`} className="border-b border-[var(--border-color)]/30">
                  <td className="py-1.5 px-3">{row.chainage.toFixed(0)}</td>
                  <td className="py-1.5 px-3 text-right">{row.groundLevel.toFixed(2)}</td>
                  <td className="py-1.5 px-3 text-right">
                    {editable ? (
                      <input aria-label="Design level (F.L.)"
                        type="number"
                        step={0.01}
                        value={designLevels[i]}
                        onChange={(e) => updateDesignLevel(i, Number(e.target.value))}
                        className="w-20 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded px-1 py-0.5 text-right text-sm"
                      />
                    ) : (
                      row.formationLevel.toFixed(2)
                    )}
                  </td>
                  <td className="py-1.5 px-3 text-right text-orange-400">{row.cut > 0 ? row.cut.toFixed(2) : '-'}</td>
                  <td className="py-1.5 px-3 text-right text-blue-400">{row.fill > 0 ? row.fill.toFixed(2) : '-'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useRef, Fragment, useId } from 'react'
import { computeCrossSection, computeEarthwork, parseEarthworkCSV, type CrossSectionInput, type CrossSectionComputed, type RoadTemplate, type EarthworkResult, type GroundShot } from '@/lib/computations/earthworksEngine'
import CrossSectionDrawing from './CrossSectionDrawing'
import EarthworkQuantitiesTable from './EarthworkQuantitiesTable'
import MassHaulDiagram from './MassHaulDiagram'
import { printEarthworksBoQ, type EarthworksBoQInput } from '@/lib/print/earthworksBoQ'
import { PrintMetaPanel, type PrintMeta } from '@/components/shared/PrintMetaPanel'

const DEFAULT_TEMPLATE: RoadTemplate = {
  carriagewayWidth: 7.0,
  shoulderWidth: 1.5,
  camber: 2.5,
  cutSlopeH: 1,
  fillSlopeH: 1.5,
}

interface SectionRow {
  id: string
  chainageKm: string
  chainageM: string
  clRL: string
  formRL: string
  leftShots: Array<{ off: string; rl: string }>
  rightShots: Array<{ off: string; rl: string }>
}

const EMPTY_ROW = (): SectionRow => ({
  id: crypto.randomUUID(),
  chainageKm: '0',
  chainageM: '0',
  clRL: '',
  formRL: '',
  leftShots: [{ off: '', rl: '' }, { off: '', rl: '' }],
  rightShots: [{ off: '', rl: '' }, { off: '', rl: '' }],
})

export default function EarthworksCalculator() {
  const uid = useId()
  const [sections, setSections] = useState<SectionRow[]>([EMPTY_ROW()])
  const [template, setTemplate] = useState<RoadTemplate>(DEFAULT_TEMPLATE)
  const [shrinkage, setShrinkage] = useState('0.85')
  const [computedSections, setComputedSections] = useState<CrossSectionComputed[]>([])
  const [earthworkResult, setEarthworkResult] = useState<EarthworkResult | null>(null)
  const [activeSection, setActiveSection] = useState(0)
  const [csvError, setCsvError] = useState('')
  const fileRef = useRef<HTMLInputElement>(null)
  const [printMeta, setPrintMeta] = useState<PrintMeta>({
    projectName: '', clientName: '', surveyorName: '', surveyorEmail: '', clientEmail: '', regNo: '', iskNo: '',
    date: new Date().toISOString().split('T')[0], instrument: '', weather: '', observer: '', submissionNo: '',
  })
  const [roadName, setRoadName] = useState('')

  function chainageToNum(row: SectionRow): number {
    return (parseFloat(row.chainageKm) || 0) * 1000 + (parseFloat(row.chainageM) || 0)
  }

  function toInput(row: SectionRow): CrossSectionInput {
    return {
      chainage: chainageToNum(row),
      centrelineRL: parseFloat(row.clRL) || 0,
      formationRL: parseFloat(row.formRL) || 0,
      leftShots: row.leftShots
        .filter((s) => s.off && s.rl)
        .map((s) => ({ offset: -(parseFloat(s.off) || 0), rl: parseFloat(s.rl) || 0 }))
        .sort((a, b) => a.offset - b.offset),
      rightShots: row.rightShots
        .filter((s) => s.off && s.rl)
        .map((s) => ({ offset: parseFloat(s.off) || 0, rl: parseFloat(s.rl) || 0 }))
        .sort((a, b) => a.offset - b.offset),
    }
  }

  function compute() {
    const inputs = sections.map(toInput).sort((a, b) => a.chainage - b.chainage)
    const computed = inputs.map((s) => computeCrossSection(s, template))
    const ew = computeEarthwork(computed, parseFloat(shrinkage) || 0.85)
    setComputedSections(computed)
    setEarthworkResult(ew)
  }

  function handlePrintBoQ() {
    if (!earthworkResult || computedSections.length === 0) return
    const inp: EarthworksBoQInput = {
      sections: computedSections,
      result: earthworkResult,
      template,
      roadName,
      startChainage: '',
      endChainage: '',
      meta: { ...printMeta, title: 'Earthworks Bill of Quantities' },
    }
    printEarthworksBoQ(inp)
  }

  function addRow() {
    setSections(prev => [...prev, EMPTY_ROW()])
  }

  function removeRow(id: string) {
    setSections(prev => prev.filter((r) => r.id !== id))
  }

  function updateRow(id: string, field: keyof SectionRow, value: unknown) {
    setSections(prev => prev.map((r) => r.id === id ? { ...r, [field]: value } : r))
  }

  function updateShot(id: string, side: 'left' | 'right', idx: number, field: 'off' | 'rl', value: string) {
    setSections(prev => prev.map((r) => {
      if (r.id !== id) return r
      const shots = [...r[(side + 'Shots') as 'leftShots' | 'rightShots']]
      shots[idx] = { ...shots[idx], [field]: value }
      return { ...r, [side + 'Shots']: shots }
    }))
  }

  function handleCSVUpload(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]
    if (!file) return
    setCsvError('')
    const reader = new FileReader()
    reader.onload = ev => {
      try {
        const text = ev.target?.result as string
        const parsed = parseEarthworkCSV(text)
        if (parsed.length === 0) { setCsvError('No valid sections found in CSV'); return }
          const rows: SectionRow[] = parsed.map((s) => {
            const km = Math.floor(s.chainage / 1000)
            const m = s.chainage % 1000
            return {
              id: crypto.randomUUID(),
              chainageKm: String(km),
              chainageM: m.toFixed(3),
              clRL: s.centrelineRL.toFixed(3),
              formRL: s.formationRL.toFixed(3),
              leftShots: s.leftShots.map((sh) => ({ off: Math.abs(sh.offset).toFixed(3), rl: sh.rl.toFixed(3) })),
              rightShots: s.rightShots.map((sh) => ({ off: sh.offset.toFixed(3), rl: sh.rl.toFixed(3) })),
            }
          })
        setSections(rows)
      } catch {
        setCsvError('Failed to parse CSV. Check format.')
      }
    }
    reader.readAsText(file)
  }

  function fmtCh(ch: number) {
    const km = Math.floor(ch / 1000)
    const m = ch % 1000
    return km > 0 ? `${km}+${m.toFixed(3)}` : `${m.toFixed(3)}`
  }

  return (
    <div className="space-y-8">
      {/* Template Settings */}
      <div className="bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg p-4">
        <h3 className="text-sm font-semibold mb-3">Road Template Settings</h3>
        <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
          {[
            { label: 'Carriageway Width (m)', key: 'carriagewayWidth' as keyof RoadTemplate },
            { label: 'Shoulder Width (m)', key: 'shoulderWidth' as keyof RoadTemplate },
            { label: 'Camber (%)', key: 'camber' as keyof RoadTemplate },
            { label: 'Cut Slope H:V', key: 'cutSlopeH' as keyof RoadTemplate },
            { label: 'Fill Slope H:V', key: 'fillSlopeH' as keyof RoadTemplate },
          ].map(({ label, key }) => (
            <div key={key}>
              <label htmlFor={`${uid}-tpl-${key}`} className="block text-xs text-[var(--text-muted)] mb-1">{label}</label>
              <input id={`${uid}-tpl-${key}`}
                type="number"
                step="0.01"
                value={template[key] as number}
                onChange={e => setTemplate(prev => ({ ...prev, [key]: parseFloat(e.target.value) || 0 }))}
                className="w-full px-3 py-2 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm"
              />
            </div>
          ))}
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="shrinkage-factor">Shrinkage Factor</label>
            <input id="shrinkage-factor" type="number" step="0.01" value={shrinkage} onChange={e => setShrinkage(e.target.value)}
              className="w-full px-3 py-2 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
          </div>
        </div>
      </div>

      {/* Data Entry Table */}
      <div className="overflow-x-auto">
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-sm font-semibold">Cross Section Data</h3>
          <div className="flex gap-2">
            <input ref={fileRef} type="file" accept=".csv" onChange={handleCSVUpload} className="hidden" />
            <button onClick={() => fileRef.current?.click()} className="px-3 py-1.5 text-xs border border-[var(--border-color)] rounded hover:bg-[var(--bg-tertiary)] text-[var(--text-muted)]">
              Import CSV
            </button>
            <button onClick={addRow} className="px-3 py-1.5 text-xs bg-[var(--accent)] text-black rounded hover:opacity-90">
              + Add Section
            </button>
            <button onClick={compute} className="px-4 py-1.5 text-xs bg-[var(--accent)] text-black rounded font-medium hover:opacity-90">
              Compute All
            </button>
            {earthworkResult && (
              <button onClick={handlePrintBoQ} className="px-4 py-1.5 text-xs bg-amber-600 text-black rounded font-medium hover:bg-amber-700">
                 Print BoQ
              </button>
            )}
          </div>
        </div>
        {csvError && <p className="text-xs text-red-400 mb-2">{csvError}</p>}
        <p className="text-xs text-[var(--text-muted)] mb-2">
          Format: Chainage (km), Chainage (m), CL RL, Form RL, then L4_off, L4_rl, L3_off, L3_rl, L2_off, L2_rl, L1_off, L1_rl, R1_off, R1_rl, R2_off, R2_rl, R3_off, R3_rl, R4_off, R4_rl
        </p>
