                <input id="road-name-description" value={roadName} onChange={e => setRoadName(e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm"
 placeholder="e.g. Kitengela Access Road — A104" />
              </div>
              <button onClick={handlePrintBoQ}
                className="px-5 py-2 bg-amber-600 text-black rounded-lg font-medium hover:bg-amber-700 text-sm whitespace-nowrap mt-5">
                 Print Earthworks BoQ
              </button>
            </div>
            <PrintMetaPanel meta={printMeta} onChange={setPrintMeta} />
          </div>

          {/* Section drawings + quantities */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div>
              <div className="flex gap-2 mb-3 overflow-x-auto pb-1">
                {computedSections.map((s, i) => (
                  <button key={`${s}-${i}`} onClick={() => setActiveSection(i)}
                    className={`px-3 py-1.5 text-xs rounded whitespace-nowrap ${i === activeSection ? 'bg-[var(--accent)] text-black' : 'border border-[var(--border-color)] text-[var(--text-muted)]'}`}>
                    {fmtCh(s.chainage)}
                  </button>
                ))}
              </div>
              {computedSections[activeSection] && (
                <CrossSectionDrawing section={computedSections[activeSection]} template={template} />
              )}
            </div>

            <div>
              <EarthworkQuantitiesTable result={earthworkResult} sections={computedSections} />
            </div>
          </div>

          {/* Mass Haul Diagram */}
          {earthworkResult && earthworkResult.massOrdinates.length > 1 && (
            <MassHaulDiagram result={earthworkResult} />
          )}
        </>
      )}
    </div>
  )
}

'use client';

import { type EarthworkResult } from '@/lib/computations/earthworksEngine'

interface Props {
  result: EarthworkResult
}

export default function MassHaulDiagram({ result }: Props) {
  const { massOrdinates, shrinkageFactor } = result

  if (massOrdinates.length < 2) return null

  const minCh = massOrdinates[0].chainage
  const maxCh = massOrdinates[massOrdinates.length - 1].chainage
  const chRange = maxCh - minCh || 1

  const maxOrd = Math.max(...massOrdinates.map((o) => o.ordinate), 0)
  const minOrd = Math.min(...massOrdinates.map((o) => o.ordinate), 0)
  const ordRange = Math.max(maxOrd - minOrd, 1)

  const svgW = 800
  const svgH = 300
  const padX = 60
  const padY = 30
  const plotW = svgW - padX * 2
  const plotH = svgH - padY * 2

  function toSvgX(ch: number): number {
    return padX + ((ch - minCh) / chRange) * plotW
  }
  function toSvgY(ord: number): number {
    return padY + ((maxOrd - ord) / ordRange) * plotH
  }

  // Build path
  const pathPts = massOrdinates.map((o, i) =>
    `${i === 0 ? 'M' : 'L'} ${toSvgX(o.chainage).toFixed(1)} ${toSvgY(o.ordinate).toFixed(1)}`
  ).join(' ')

  // Balance line (zero)
  const zeroY = toSvgY(0)

  // Fill surplus (above zero)
  let surplusPath = `M ${toSvgX(minCh).toFixed(1)} ${zeroY.toFixed(1)} `
  for (const o of massOrdinates) {
    if (o.ordinate >= 0) {
      surplusPath += `L ${toSvgX(o.chainage).toFixed(1)} ${toSvgY(o.ordinate).toFixed(1)} `
    }
  }
  surplusPath += `L ${toSvgX(maxCh).toFixed(1)} ${zeroY.toFixed(1)} Z`

  // Fill deficit (below zero)
  let deficitPath = `M ${toSvgX(minCh).toFixed(1)} ${zeroY.toFixed(1)} `
  for (const o of massOrdinates) {
    if (o.ordinate <= 0) {
      deficitPath += `L ${toSvgX(o.chainage).toFixed(1)} ${toSvgY(o.ordinate).toFixed(1)} `
    }
  }
  deficitPath += `L ${toSvgX(maxCh).toFixed(1)} ${zeroY.toFixed(1)} Z`

  // X axis ticks
  const numTicks = Math.min(10, massOrdinates.length)
  const tickStep = chRange / numTicks
  const xTicks: number[] = []
  for (let i = 0; i <= numTicks; i++) {
    xTicks.push(minCh + (i / numTicks) * chRange)
  }

  // Y axis ticks
  const ordStep = ordRange / 5
  const yTicks: number[] = []
  for (let i = 0; i <= 5; i++) {
    yTicks.push(minOrd + i * ordStep)
  }

  const fmtCh = (ch: number) => {
    const km = Math.floor(ch / 1000)
    const m = ch % 1000
    return km > 0 ? `${km}+${m.toFixed(0)}` : `${m.toFixed(0)}`
  }

  const maxIdx = massOrdinates.reduce((maxI, o, i, arr) => o.ordinate > arr[maxI].ordinate ? i : maxI, 0)
  const minIdx = massOrdinates.reduce((minI, o, i, arr) => o.ordinate < arr[minI].ordinate ? i : minI, 0)
  const peakOrd = massOrdinates[maxIdx]
  const troughOrd = massOrdinates[minIdx]

  return (
    <div className="bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg overflow-hidden">
      <div className="px-3 py-2 bg-[var(--bg-tertiary)] border-b border-[var(--border-color)]">
        <h3 className="text-sm font-semibold">Mass Haul Diagram</h3>
        <p className="text-xs text-[var(--text-muted)]">
          Adjusted cut (&times; {shrinkageFactor} shrinkage) &minus; fill | Source: Ghilani &amp; Wolf Ch.26, Section 26.6
        </p>
      </div>

      <div className="p-4">
        <svg viewBox={`0 0 ${svgW} ${svgH}`} className="w-full" style={{ background: '#fafafa' }}>
          {/* Y axis */}
          <line x1={padX} y1={padY} x2={padX} y2={svgH - padY} stroke="#333" strokeWidth="1" />
          {/* X axis */}
          <line x1={padX} y1={svgH - padY} x2={svgW - padX} y2={svgH - padY} stroke="#333" strokeWidth="1" />

          {/* Balance line */}
          <line x1={padX} y1={zeroY} x2={svgW - padX} y2={zeroY} stroke="#888" strokeWidth="1" strokeDasharray="5,3" />

          {/* Surplus area */}
          <path d={surplusPath} fill="#ff660018" stroke="none" />
          {/* Deficit area */}
          <path d={deficitPath} fill="#0066ff18" stroke="none" />

          {/* Curve */}
          <path d={pathPts} fill="none" stroke="#333" strokeWidth="2" />

          {/* Peak annotation */}
          <circle cx={toSvgX(peakOrd.chainage)} cy={toSvgY(peakOrd.ordinate)} r="4" fill="#ff6600" />
          <text x={toSvgX(peakOrd.chainage) + 5} y={toSvgY(peakOrd.ordinate) - 5} fontSize="9" fill="#ff6600" fontFamily="monospace">
            Max: {peakOrd.ordinate.toFixed(1)} m&sup3;
          </text>

          {/* Trough annotation */}
          <circle cx={toSvgX(troughOrd.chainage)} cy={toSvgY(troughOrd.ordinate)} r="4" fill="#0066ff" />
          <text x={toSvgX(troughOrd.chainage) + 5} y={toSvgY(troughOrd.ordinate) + 14} fontSize="9" fill="#0066ff" fontFamily="monospace">
            Min: {troughOrd.ordinate.toFixed(1)} m&sup3;
          </text>

          {/* X axis ticks */}
          {xTicks.map((ch, i) => (
            <g key={`${ch}-${i}`}>
              <line x1={toSvgX(ch)} y1={svgH - padY} x2={toSvgX(ch)} y2={svgH - padY + 5} stroke="#333" strokeWidth="0.5" />
              <text x={toSvgX(ch)} y={svgH - padY + 15} fontSize="8" fill="#666" textAnchor="middle" fontFamily="monospace">
                {fmtCh(ch)}
              </text>
            </g>
          ))}

          {/* Y axis ticks */}
          {yTicks.map((ord, i) => (
            <g key={`${ord}-${i}`}>
              <line x1={padX - 5} y1={toSvgY(ord)} x2={padX} y2={toSvgY(ord)} stroke="#333" strokeWidth="0.5" />
              <text x={padX - 8} y={toSvgY(ord) + 3} fontSize="8" fill="#666" textAnchor="end" fontFamily="monospace">
                {ord >= 1000 ? `${(ord / 1000).toFixed(1)}k` : ord.toFixed(0)}
              </text>
            </g>
          ))}

          {/* Axis labels */}
          <text x={svgW / 2} y={svgH - 2} fontSize="9" fill="#333" textAnchor="middle" fontFamily="monospace">
            Chainage
          </text>
          <text x={12} y={svgH / 2} fontSize="9" fill="#333" textAnchor="middle" fontFamily="monospace" transform={`rotate(-90, 12, ${svgH / 2})`}>
            Mass Ordinate (m&sup3;)
          </text>
        </svg>

        <div className="mt-3 grid grid-cols-2 md:grid-cols-4 gap-3 text-xs font-mono">
          <div className="bg-[var(--bg-tertiary)] rounded p-2">
            <p className="text-[var(--text-muted)]">Peak Ordinate</p>
            <p className="text-orange-400 text-sm">{peakOrd.ordinate.toFixed(2)} m&sup3;</p>
            <p className="text-[var(--text-muted)] text-[10px]">at {fmtCh(peakOrd.chainage)}</p>
          </div>
          <div className="bg-[var(--bg-tertiary)] rounded p-2">
            <p className="text-[var(--text-muted)]">Trough Ordinate</p>
            <p className="text-blue-400 text-sm">{troughOrd.ordinate.toFixed(2)} m&sup3;</p>
            <p className="text-[var(--text-muted)] text-[10px]">at {fmtCh(troughOrd.chainage)}</p>
          </div>
          <div className="bg-[var(--bg-tertiary)] rounded p-2">
            <p className="text-[var(--text-muted)]">Free Haul Distance</p>
            <p className="text-[var(--text-primary)] text-sm">100 m (RDM 1.3)</p>
          </div>
          <div className="bg-[var(--bg-tertiary)] rounded p-2">
            <p className="text-[var(--text-muted)]">Net Balance</p>
            <p className={`text-sm ${peakOrd.ordinate - Math.abs(troughOrd.ordinate) >= 0 ? 'text-yellow-400' : 'text-blue-400'}`}>
              {(peakOrd.ordinate - Math.abs(troughOrd.ordinate)).toFixed(2)} m&sup3;
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import CrossSectionInput from '@/components/earthworks/CrossSectionInput'

/**
 * ProjectCrossSections — wrapper that connects CrossSectionInput to a project.
 *
 * Fetches the project's survey points and attempts to match point names to
 * chainage stations (e.g. "0+020", "20", "STA 20" → chainage 20m).
 * Uses the elevation as the centreline reduced level (clRL).
 *
 * Limitation: full cross-section auto-population (with left/right offset shots)
 * requires the baseline alignment geometry, which is a future feature.
 * For now, this populates centreline levels only — the surveyor still enters
 * offset shots manually or via CSV.
 *
 * Usage:
 *   <ProjectCrossSections projectId="abc-123" />
 *   // or as a route: /tools/cross-sections?project=abc-123
 */

interface ProjectCrossSectionsProps {
  projectId: string
}

interface SurveyPoint {
  id: string
  point_name: string
  easting: number
  northing: number
  elevation: number | null
  code: string | null
  description: string | null
}

/**
 * Attempt to extract a chainage value (in metres) from a point name.
 * Handles formats: "0+020", "0+020.5", "20", "STA 20", "CH 1200"
 */
function parseChainageFromName(name: string): number | null {
  if (!name) return null
  const upper = name.toUpperCase().trim()

  // Format: "0+020" or "1+200.5" (km+m)
  const kmMatch = upper.match(/(\d+)\+(\d+(?:\.\d+)?)/)
  if (kmMatch) {
    return parseInt(kmMatch[1]) * 1000 + parseFloat(kmMatch[2])
  }

  // Format: "STA 20" or "CH 1200" or just "20"
  const staMatch = upper.match(/(?:STA|CH|CHAINAGE)?\s*(\d+(?:\.\d+)?)/)
  if (staMatch) {
    return parseFloat(staMatch[1])
  }

  return null
}

export default function ProjectCrossSections({ projectId }: ProjectCrossSectionsProps) {
  const [loading, setLoading] = useState(true)
  const [matchedCount, setMatchedCount] = useState(0)
  const [loaded, setLoaded] = useState(false)
  const inputRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    let cancelled = false

    async function fetchPoints() {
      try {
        const res = await fetch(`/api/project/${projectId}/points`)
        if (!res.ok) return
        const json = await res.json() as { data?: SurveyPoint[] }
        const points: SurveyPoint[] = json.data || []

        // Try to match points to chainage stations
        const matched: { chainage: number; rl: number; name: string }[] = []
        for (const p of points) {
          if (p.elevation == null) continue
          const ch = parseChainageFromName(p.point_name)
          if (ch !== null) {
            matched.push({ chainage: ch, rl: p.elevation, name: p.point_name })
          }
        }

        if (!cancelled && matched.length > 0) {
          // Sort by chainage
          matched.sort((a, b) => a.chainage - b.chainage)
          // Store in sessionStorage as CSV for the CrossSectionInput's CSV import
          // Format: chainage,centrelineRL,formationRL,leftOffsets,rightOffsets
          // We only have centreline RL — formation RL and offsets are blank
          const csvLines = matched.map(m => {
            const km = Math.floor(m.chainage / 1000)
            const m2 = m.chainage % 1000
            return `${km}+${m2.toFixed(3)},${m.rl.toFixed(3)},,,`
          })
          const csv = `chainage,centrelineRL,formationRL,left,right\n` + csvLines.join('\n')
          sessionStorage.setItem(`metardu:cross-sections:csv:${projectId}`, csv)
          setMatchedCount(matched.length)
        }
      } catch {
        // silent fail
      } finally {
        if (!cancelled) {
          setLoading(false)
          setLoaded(true)
        }
      }
    }

    if (projectId && projectId !== 'new') {
      fetchPoints()
    } else {
      setLoading(false)
      setLoaded(true)
    }

    return () => { cancelled = true }
  }, [projectId])

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="font-mono text-xs text-[var(--text-muted)] tracking-[0.04em] uppercase">
          Loading project data...
        </div>
      </div>
    )
  }

  return (
    <div ref={inputRef}>
      {matchedCount > 0 && (
        <div className="max-w-7xl mx-auto px-4 mb-4">
          <div className="border border-[var(--accent)]/30 bg-[var(--accent)]/5 p-3 rounded-md flex items-center gap-3">
            <svg className="w-4 h-4 text-[var(--accent)] shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <p className="text-xs text-[var(--text-secondary)]">
              <span className="font-mono text-[var(--accent)]">{matchedCount} centreline levels</span>{' '}
              matched from project survey points (by chainage name). Use the CSV import
              below to load them. Offset shots and formation levels need manual entry.
            </p>
          </div>
        </div>
      )}
      {loaded && matchedCount === 0 && projectId !== 'new' && (
        <div className="max-w-7xl mx-auto px-4 mb-4">
          <div className="border border-[var(--border-color)] bg-[var(--bg-card)] p-3 rounded-md flex items-center gap-3">
            <svg className="w-4 h-4 text-[var(--text-muted)] shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M11.25 11.25l.041-.02a.75.75 0 011.063.852l-.708 2.836a.75.75 0 001.063.853l.041-.021M21 12a9 9 0 11-18 0 9 9 0 0118 0zm-9-3.75h.008v.008H12V8.25z" />
            </svg>
            <p className="text-xs text-[var(--text-muted)]">
              No chainage-matched points found in project. Name your survey points
              as &quot;0+020&quot; or &quot;20&quot; (chainage in metres) to auto-populate centreline levels.
            </p>
          </div>
        </div>
      )}
      <CrossSectionInput />
    </div>
  )
}

'use client';

import React, { useState, useMemo, useRef } from 'react'
import type { DesignPoint, AsBuiltPoint, ToleranceBand, AsBuiltSurveyResult } from '@/lib/engineering/asBuiltSurvey'
import { compareDesignVsAsBuilt, parseAsBuiltCSV, TOLERANCE_BANDS } from '@/lib/engineering/asBuiltSurvey'

interface AsBuiltSurveyPanelProps {
  projectId?: string
  roadClass?: string
  surfaceType?: 'paved' | 'gravel' | 'earth'
  designPoints?: DesignPoint[]
  onImport?: (points: AsBuiltPoint[]) => void
}

const SURFACE_TYPES: Array<{ key: 'paved' | 'gravel' | 'earth'; label: string; tolerance: ToleranceBand }> = [
  { key: 'paved', label: 'Paved (Asphalt/Concrete)', tolerance: TOLERANCE_BANDS.paved },
  { key: 'gravel', label: 'Gravel', tolerance: TOLERANCE_BANDS.gravel },
  { key: 'earth', label: 'Earth', tolerance: TOLERANCE_BANDS.earth },
]

export default function AsBuiltSurveyPanel({ roadClass, surfaceType = 'paved', designPoints = [] }: AsBuiltSurveyPanelProps) {
  const [activeSurface, setActiveSurface] = useState<'paved' | 'gravel' | 'earth'>(surfaceType)
  const [csvInput, setCsvInput] = useState('')
  const [asBuiltPoints, setAsBuiltPoints] = useState<AsBuiltPoint[]>([])
  const [result, setResult] = useState<AsBuiltSurveyResult | null>(null)
  const [csvError, setCsvError] = useState<string | null>(null)
  const [nanWarning, setNanWarning] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const tolerance = SURFACE_TYPES.find(s => s.key === activeSurface)!.tolerance

  const handleImport = () => {
    setCsvError(null)
    const points = parseAsBuiltCSV(csvInput)
    if (points.length === 0) {
      setCsvError('Invalid CSV format. Expected: chainage, level, easting, northing (E/N optional).')
      return
    }
    setAsBuiltPoints(points)
    setNanWarning(false)
    const r = compareDesignVsAsBuilt(designPoints, points, tolerance)
    setResult(r)
  }

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    const reader = new FileReader()
    reader.onload = (event) => {
      const text = event.target?.result as string
      setCsvInput(text)
      setCsvError(null)
      const points = parseAsBuiltCSV(text)
      if (points.length === 0) {
        setCsvError('Invalid CSV format. Expected: chainage, level, easting, northing (E/N optional).')
        return
      }
      setAsBuiltPoints(points)
      setNanWarning(false)
      const r = compareDesignVsAsBuilt(designPoints, points, tolerance)
      setResult(r)
    }
    reader.readAsText(file)
    // Reset so same file can be re-uploaded
    e.target.value = ''
  }

  const handleExportCSV = () => {
    if (!result) return
    const header = 'chainage,design_level,as_built_level,deviation,tolerance,status'
    const rows = result.comparisons.map(r =>
      `${r.chainage},${r.designLevel.toFixed(4)},${r.asBuiltLevel.toFixed(4)},${r.deviation.toFixed(1)},${r.tolerance},${r.pass ? 'PASS' : 'FAIL'}`
    )
    const csvContent = [header, ...rows].join('\n')
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = `as_built_survey_results_${Date.now()}.csv`
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
    URL.revokeObjectURL(url)
  }

  // Generate synthetic design points for demo
  const demoDesignPoints = useMemo(() => {
    if (designPoints.length > 0) return designPoints
    return Array.from({ length: 51 }, (_, i) => ({
      chainage: i * 20,
      designLevel: 100 + Math.sin(i * 0.15) * 3,
    }))
  }, [designPoints])

  const runComparison = () => {
    if (asBuiltPoints.length < 2) return
    setNanWarning(false)
    const r = compareDesignVsAsBuilt(demoDesignPoints, asBuiltPoints, tolerance)
    // Check for NaN deviations
    const hasNan = r.comparisons.some(c => isNaN(c.deviation))
    if (hasNan) setNanWarning(true)
    setResult(r)
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
        <h3 className="text-lg font-semibold text-white">As-Built Survey Analysis</h3>
        <p className="text-sm text-zinc-400 mt-1">Compare design levels against as-built survey data</p>
      </div>

      {/* Surface Type & Tolerance */}
      <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
        <h4 className="font-medium text-white mb-3">Surface Type & Tolerances</h4>
        <div className="grid grid-cols-3 gap-3">
          {SURFACE_TYPES.map(st => (
            <button
              key={st.key}
              onClick={() => setActiveSurface(st.key)}
              className={`p-3 rounded-lg border-2 text-left transition-colors ${
                activeSurface === st.key
                  ? 'border-blue-500 bg-blue-900/30'
                  : 'border-zinc-700 hover:border-zinc-600'
              }`}
            >
              <div className="font-medium text-sm text-white">{st.label}</div>
              <div className="text-xs text-zinc-400 mt-1">
                Level: ±{st.tolerance.level}mm | Horiz: ±{st.tolerance.horizontal}mm
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* CSV Import */}
      <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
        <h4 className="font-medium text-white mb-3">Import As-Built Data (CSV)</h4>
        <p className="text-xs text-zinc-400 mb-2">Format: chainage, level, easting, northing (one point per line)</p>

        {/* File upload button */}
        <div className="mb-3">
          <input
            ref={fileInputRef}
            type="file"
            accept=".csv,.txt"
            onChange={handleFileUpload}
            className="hidden"
          />
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            className="inline-flex items-center gap-2 px-4 py-2 bg-zinc-800 border border-zinc-600 text-zinc-300 rounded-lg text-sm font-medium hover:bg-zinc-700 hover:text-white transition-colors"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
            </svg>
            Upload CSV File
          </button>
        </div>

        {/* Textarea fallback */}
        <textarea
          className="w-full h-32 bg-zinc-800 border border-zinc-600 rounded-lg p-3 font-mono text-sm text-zinc-200 placeholder-zinc-500 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
          placeholder={`0, 100.025, 123456.789, 9876543.210\n20, 100.032, 123466.521, 9876550.102\n40, 99.988, 123476.213, 9876556.834\n...`}
          value={csvInput}
          onChange={e => setCsvInput(e.target.value)}
        />

        {/* CSV error message */}
        {csvError && (
          <div className="mt-2 px-3 py-2 bg-red-900/30 border border-red-700 rounded-lg text-sm text-red-400">
            <span className="font-medium">Import Error:</span> {csvError}
          </div>
        )}

        <div className="flex gap-3 mt-3">
          <button
            onClick={handleImport}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700"
          >
            Import & Compare
          </button>
          {designPoints.length === 0 && (
            <button
              onClick={() => {
                const demoAB = demoDesignPoints.map(d => ({
                  chainage: d.chainage,
                  surveyedLevel: d.designLevel + (Math.random() - 0.5) * 0.06,
                  surveyedEasting: 123456.789 + d.chainage * 0.5,
                  surveyedNorthing: 9876543.21 + d.chainage * 0.7,
                }))
                setAsBuiltPoints(demoAB)
                setNanWarning(false)
                const r = compareDesignVsAsBuilt(demoDesignPoints, demoAB, tolerance)
                setResult(r)
              }}
              className="px-4 py-2 bg-zinc-700 text-zinc-200 rounded-lg text-sm font-medium hover:bg-zinc-600 transition-colors"
            >
              Load Demo Data
            </button>
          )}
        </div>
      </div>

      {/* Validation: Compare button area */}
      {asBuiltPoints.length > 0 && (
        <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
          <div className="flex items-center gap-4">
            <div>
              <span className="text-sm text-zinc-400">
                {asBuiltPoints.length} as-built point{asBuiltPoints.length !== 1 ? 's' : ''} loaded
              </span>
              {asBuiltPoints.length < 2 && (
                <span className="ml-2 text-xs text-amber-400">
                  — Need at least 2 points to compare
                </span>
              )}
            </div>
            <button
              onClick={runComparison}
              disabled={asBuiltPoints.length < 2}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                asBuiltPoints.length >= 2
                  ? 'bg-blue-600 text-white hover:bg-blue-700'
                  : 'bg-zinc-800 text-zinc-500 cursor-not-allowed'
              }`}
            >
              Compare
            </button>
          </div>
        </div>
      )}

      {/* Results */}
      {result && (
        <>
          {/* Summary Cards */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className={`rounded-xl border-2 p-4 ${result.summary.isCompliant ? 'border-green-500 bg-green-900/20' : 'border-red-500 bg-red-900/20'}`}>
              <div className="text-xs text-zinc-400 uppercase tracking-wider">Pass Rate</div>
              <div className={`text-2xl font-bold ${result.summary.isCompliant ? 'text-green-400' : 'text-red-400'}`}>
                {result.summary.passRate.toFixed(1)}%
              </div>
              <div className="text-xs text-zinc-400">{result.summary.passCount} / {result.summary.totalPoints} points</div>
            </div>
            <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-4">
              <div className="text-xs text-zinc-400 uppercase tracking-wider">Max Deviation</div>
              <div className="text-2xl font-bold text-white">{result.summary.maxLevelDeviation.toFixed(1)} mm</div>
              <div className="text-xs text-zinc-400">Tolerance: ±{tolerance.level}mm</div>
            </div>
            <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-4">
              <div className="text-xs text-zinc-400 uppercase tracking-wider">RMS Error</div>
              <div className="text-2xl font-bold text-white">{result.summary.rmsError.toFixed(1)} mm</div>
              <div className="text-xs text-zinc-400">Root Mean Square</div>
            </div>
            <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-4">
              <div className="text-xs text-zinc-400 uppercase tracking-wider">Mean Deviation</div>
              <div className="text-2xl font-bold text-white">{result.summary.meanLevelDeviation.toFixed(1)} mm</div>
              <div className="text-xs text-zinc-400">Std Dev: {result.summary.standardDeviation.toFixed(1)}mm</div>
            </div>
          </div>

          {/* Compliance Badge */}
          <div className={`rounded-xl p-4 flex items-center gap-3 ${result.summary.certificationReady ? 'bg-green-900/20 border border-green-800' : 'bg-amber-900/20 border border-amber-800'}`}>
            {result.summary.certificationReady ? (
              <svg className="w-6 h-6 text-green-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            ) : (
              <svg className="w-6 h-6 text-amber-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L4.082 16.5c-.77.833.192 2.5 1.732 2.5z" /></svg>
            )}
            <div>
              <div className={`font-medium ${result.summary.certificationReady ? 'text-green-400' : 'text-amber-400'}`}>
                {result.summary.certificationReady ? 'Certificate Ready' : 'Not Ready for Certification'}
              </div>
              {result.summary.issues.length > 0 && (
                <ul className="text-xs text-zinc-300 mt-1">
                  {result.summary.issues.map((issue, i) => <li key={`${issue}-${i}`}>• {issue}</li>)}
                </ul>
              )}
            </div>
          </div>

          {/* Deviation Profile SVG */}
          <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
            <div className="flex items-center justify-between mb-3">
              <h4 className="font-medium text-white">Deviation Profile</h4>
              <button
                onClick={handleExportCSV}
                className="inline-flex items-center gap-2 px-3 py-1.5 bg-zinc-800 border border-zinc-600 text-zinc-300 rounded-lg text-xs font-medium hover:bg-zinc-700 hover:text-white transition-colors"
              >
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
                Download Results CSV
              </button>
            </div>
            {nanWarning && (
              <div className="mb-3 px-3 py-2 bg-amber-900/30 border border-amber-700 rounded-lg text-xs text-amber-400">
                <span className="font-medium">Warning:</span> Some deviation values contained NaN and were replaced with 0.
              </div>
            )}
            <DeviationProfileSvg comparisons={result.comparisons} tolerance={tolerance.level} />
          </div>

          {/* Data Table */}
          <div className="bg-zinc-900 rounded-xl border border-zinc-700 overflow-hidden">
            <div className="px-6 py-4 border-b border-zinc-700 flex items-center justify-between">
              <h4 className="font-medium text-white">As-Built Comparison Table</h4>
              <span className="text-xs text-zinc-400">{result.comparisons.length} rows</span>
            </div>
            <div className="overflow-x-auto max-h-96 overflow-y-auto">
              <table className="w-full text-sm">
                <thead className="bg-zinc-800 sticky top-0">
                  <tr>
                    <th className="px-4 py-2 text-left text-xs font-medium text-zinc-400">Chainage</th>
                    <th className="px-4 py-2 text-right text-xs font-medium text-zinc-400">Design RL</th>
                    <th className="px-4 py-2 text-right text-xs font-medium text-zinc-400">As-Built RL</th>
                    <th className="px-4 py-2 text-right text-xs font-medium text-zinc-400">Deviation</th>
                    <th className="px-4 py-2 text-center text-xs font-medium text-zinc-400">Tolerance</th>
                    <th className="px-4 py-2 text-center text-xs font-medium text-zinc-400">Status</th>
                  </tr>
                </thead>
                <tbody>
                  {result.comparisons.map((row, i) => (
                    <tr key={`${row}-${i}`} className={`border-t border-zinc-800 ${row.pass ? 'bg-zinc-900' : 'bg-red-900/15'}`}>
                      <td className="px-4 py-2 font-mono text-xs text-zinc-300">{row.chainage.toFixed(0)}</td>
                      <td className="px-4 py-2 text-right font-mono text-xs text-zinc-300">{row.designLevel.toFixed(4)}</td>
                      <td className="px-4 py-2 text-right font-mono text-xs text-zinc-300">{row.asBuiltLevel.toFixed(4)}</td>
                      <td className="px-4 py-2 text-right font-mono text-xs text-zinc-300">{row.deviation > 0 ? '+' : ''}{row.deviation.toFixed(1)} mm</td>
                      <td className="px-4 py-2 text-center text-xs text-zinc-400">±{row.tolerance}</td>
                      <td className="px-4 py-2 text-center">
                        <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${row.pass ? 'bg-green-900/40 text-green-400' : 'bg-red-900/40 text-red-400'}`}>
                          {row.pass ? 'PASS' : 'FAIL'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </div>
  )
}

// ─── DEVIATION PROFILE SVG ────────────────────────────────────────────────────

function DeviationProfileSvg({ comparisons, tolerance }: { comparisons: Array<{ chainage: number; deviation: number; pass: boolean }>; tolerance: number }) {
  if (comparisons.length === 0) return null

  // NaN guard: replace NaN deviations with 0
  const sanitizedComparisons = comparisons.map(c => ({
    ...c,
    deviation: isNaN(c.deviation) ? 0 : c.deviation,
  }))

  const width = 900
  const height = 200
  const margin = { top: 20, right: 20, bottom: 40, left: 60 }

  const plotW = width - margin.left - margin.right
  const plotH = height - margin.top - margin.bottom

  const maxCh = Math.max(...sanitizedComparisons.map(c => c.chainage))
  const minCh = Math.min(...sanitizedComparisons.map(c => c.chainage))
  const maxDev = Math.max(tolerance * 1.5, Math.max(...sanitizedComparisons.map(c => Math.abs(c.deviation))))

  const scaleX = (ch: number) => margin.left + ((ch - minCh) / (maxCh - minCh || 1)) * plotW
  const scaleY = (dev: number) => margin.top + plotH / 2 - (dev / maxDev) * (plotH / 2)

  const polyline = sanitizedComparisons.map(c => `${scaleX(c.chainage)},${scaleY(c.deviation)}`).join(' ')

  return (
    <svg viewBox={`0 0 ${width} ${height}`} className="w-full">
      {/* Tolerance band */}
      <rect x={margin.left} y={scaleY(tolerance)} width={plotW} height={scaleY(-tolerance) - scaleY(tolerance)} fill="rgba(34,197,94,0.15)" />
      <line x1={margin.left} y1={scaleY(0)} x2={width - margin.right} y2={scaleY(0)} stroke="#71717a" strokeWidth={1} strokeDasharray="4,2" />
      <line x1={margin.left} y1={scaleY(tolerance)} x2={width - margin.right} y2={scaleY(tolerance)} stroke="#16a34a" strokeWidth={1} strokeDasharray="4,2" />
      <line x1={margin.left} y1={scaleY(-tolerance)} x2={width - margin.right} y2={scaleY(-tolerance)} stroke="#16a34a" strokeWidth={1} strokeDasharray="4,2" />

      {/* Data line */}
      <polyline fill="none" stroke="#3b82f6" strokeWidth={1.5} points={polyline} />

      {/* Points */}
      {sanitizedComparisons.map((c, i) => (
        <circle key={`${c}-${i}`} cx={scaleX(c.chainage)} cy={scaleY(c.deviation)} r={3}
          fill={c.pass ? '#16a34a' : '#dc2626'} />
      ))}

      {/* Labels */}
      <text x={width / 2} y={height - 5} textAnchor="middle" className="text-xs" fill="#a1a1aa">Chainage (m)</text>
      <text x={10} y={height / 2} textAnchor="middle" className="text-xs" fill="#a1a1aa" transform={`rotate(-90, 10, ${height / 2})`}>Deviation (mm)</text>
      <text x={margin.left + 4} y={scaleY(tolerance) - 4} className="text-xs" fill="#16a34a">+{tolerance}</text>
      <text x={margin.left + 4} y={scaleY(-tolerance) + 12} className="text-xs" fill="#16a34a">-{tolerance}</text>
    </svg>
  )
}

'use client';

import React, { useMemo } from 'react'
import {
  computeCamberProfile,
  computeDetailedFormationLine,
  computeCutFillArea,
  parseSlopeRatio,
  determineSectionType,
  interpolateGroundAtCentre,
  formatChainage,
  type ProfilePoint,
  type RoadTemplate,
} from '@/lib/engineering/crossSectionGeometry'

// ─── TYPES ─────────────────────────────────────────────────────────────────────

export interface CrossSectionProps {
  chainage: number
  groundPoints: Array<{ offset: number; level: number }>
  template: RoadTemplate
  formationLevel?: number
  cutArea?: number
  fillArea?: number
  width?: number
  height?: number
  showLabels?: boolean
}

// ─── COLOUR CONSTANTS ──────────────────────────────────────────────────────────

const COLORS = {
  groundLine: '#92400E',         // brown
  groundFill: '#FEF3C7',         // tan
  carriageway: '#374151',        // dark grey
  shoulder: '#6B7280',           // lighter grey
  cutSlope: '#92400E',           // red-brown
  fillSlope: '#1E40AF',          // blue-grey
  subgrade: '#9CA3AF',           // grey dashed
  centreLine: '#6B7280',         // grey dashed
  cutFill: '#DC2626',            // red
  gridLine: '#E5E7EB',          // light grey
  offsetMarker: '#D1D5DB',       // light grey
  labelPrimary: '#111827',       // near black
  labelSecondary: '#6B7280',     // grey
  cutLabel: '#DC2626',           // red
  fillLabel: '#2563EB',          // blue
  dimensionLine: '#4B5563',      // medium grey
  dimensionArrow: '#374151',     // dark grey
  background: '#FAFAFA',         // near white
} as const

// ─── ARROW HEAD COMPONENT ──────────────────────────────────────────────────────

function ArrowHead({
  id,
  color = COLORS.dimensionArrow,
}: {
  id: string
  color?: string
}) {
  return (
    <defs>
      <marker
        id={id}
        viewBox="0 0 10 10"
        refX="5"
        refY="5"
        markerWidth="6"
        markerHeight="6"
        orient="auto-start-reverse"
      >
        <path d="M 0 0 L 10 5 L 0 10 z" fill={color} />
      </marker>
    </defs>
  )
}

// ─── DIMENSION LINE ────────────────────────────────────────────────────────────

function DimensionLine({
  x1,
  y1,
  x2,
  y2,
  label,
  offsetDir = 15,
  id,
}: {
  x1: number
  y1: number
  x2: number
  y2: number
  label: string
  offsetDir?: number
  id: string
}) {
  const dx = x2 - x1
  const dy = y2 - y1
  const len = Math.sqrt(dx * dx + dy * dy)
  if (len < 1) return null

  // Perpendicular direction for label offset
  const nx = -dy / len
  const ny = dx / len

  const midX = (x1 + x2) / 2 + nx * offsetDir
  const midY = (y1 + y2) / 2 + ny * offsetDir

  return (
    <g>
      <line
        x1={x1 + nx * 4}
        y1={y1 + ny * 4}
        x2={x2 + nx * 4}
        y2={y2 + ny * 4}
        stroke={COLORS.dimensionLine}
        strokeWidth={0.5}
        markerStart={`url(#arrow-${id})`}
        markerEnd={`url(#arrow-${id})`}
      />
      <text
        x={midX}
        y={midY + 2.5}
        fontSize="7"
        fill={COLORS.dimensionArrow}
        textAnchor="middle"
        fontFamily="monospace"
      >
        {label}
      </text>
    </g>
  )
}

// ─── MAIN COMPONENT ────────────────────────────────────────────────────────────

export function CrossSectionRenderer({
  chainage,
  groundPoints,
  template,
  formationLevel: propFormationLevel,
  cutArea: propCutArea,
  fillArea: propFillArea,
  width = 800,
  height = 400,
  showLabels = true,
}: CrossSectionProps) {
  const sectionType = useMemo(
    () => determineSectionType(groundPoints, propFormationLevel ?? 0),
    [groundPoints, propFormationLevel]
  )

  const computedFormationLevel = useMemo(() => {
    if (propFormationLevel !== undefined) return propFormationLevel
    // Default: ground level at centre
    const gl = interpolateGroundAtCentre(groundPoints)
    return gl !== null ? gl + 0.5 : 100
  }, [propFormationLevel, groundPoints])

  const isCut = sectionType === 'cut' || sectionType === 'mixed'
  const isFill = sectionType === 'fill' || sectionType === 'mixed'

  // Compute formation line
  const formationLine = useMemo(
    () =>
      computeDetailedFormationLine(
        template,
        computedFormationLevel,
        groundPoints,
        isCut
      ),
    [template, computedFormationLevel, groundPoints, isCut]
  )

  // Compute camber profile for carriageway detail
  const camberProfile = useMemo(
    () => computeCamberProfile(template.carriagewayWidth, template.camber, computedFormationLevel),
    [template.carriagewayWidth, template.camber, computedFormationLevel]
  )

  // Compute areas
  const areas = useMemo(() => {
    if (propCutArea !== undefined && propFillArea !== undefined) {
      return { cutArea: propCutArea, fillArea: propFillArea }
    }
    const netArea = computeCutFillArea(groundPoints, formationLine)
    if (netArea >= 0) {
      return { cutArea: netArea, fillArea: 0 }
    }
    return { cutArea: 0, fillArea: -netArea }
  }, [propCutArea, propFillArea, groundPoints, formationLine])

  // Compute subgrade line
  const subgradeLevel = computedFormationLevel - template.subgradeDepth

  // Auto-scale computation
  const { viewBox, toSvgX, toSvgY } = useMemo(() => {
    const allPoints: ProfilePoint[] = [
      ...groundPoints,
      ...formationLine,
    ]

    // Also consider subgrade
    const minOffset = Math.min(...allPoints.map(p => p.offset)) - 3
    const maxOffset = Math.max(...allPoints.map(p => p.offset)) + 3
    const minLevel = Math.min(
      ...allPoints.map(p => p.level),
      subgradeLevel
    ) - 1.5
    const maxLevel = Math.max(...allPoints.map(p => p.level)) + 1.5

    const dataWidth = maxOffset - minOffset
    const dataHeight = maxLevel - minLevel

    // Add 15% padding
    const padding = 0.15
    const paddedWidth = dataWidth * (1 + padding)
    const paddedHeight = dataHeight * (1 + padding)

    const vbX = minOffset - dataWidth * padding / 2
    const vbY = minLevel - dataHeight * padding / 2

    // Maintain aspect ratio matching the SVG element
    const aspectRatio = width / height
    const dataAspect = paddedWidth / paddedHeight

    let finalVbW: number
    let finalVbH: number
    if (dataAspect > aspectRatio) {
      // Data is wider — fit width, expand height
      finalVbW = paddedWidth
      finalVbH = paddedWidth / aspectRatio
    } else {
      // Data is taller — fit height, expand width
      finalVbH = paddedHeight
      finalVbW = paddedHeight * aspectRatio
    }

    // Centre the data in the viewBox
    const centerX = vbX + dataWidth / 2
    const centerY = vbY + dataHeight / 2
    const finalVbX = centerX - finalVbW / 2
    const finalVbY = centerY - finalVbH / 2

    const scaleX = (offset: number) =>
      ((offset - finalVbX) / finalVbW) * width
    const scaleY = (level: number) =>
      height - ((level - finalVbY) / finalVbH) * height

    return {
      viewBox: `${finalVbX} ${finalVbY} ${finalVbW} ${finalVbH}`,
      toSvgX: scaleX,
      toSvgY: scaleY,
    }
  }, [groundPoints, formationLine, subgradeLevel, width, height])

  // Sorted ground points for polyline
  const sortedGround = useMemo(
    () => [...groundPoints].sort((a, b) => a.offset - b.offset),
    [groundPoints]
  )

  // Centre ground level for cut/fill depth computation
  const centreGroundLevel = interpolateGroundAtCentre(groundPoints)
  const centreDepth =
    centreGroundLevel !== null
      ? centreGroundLevel - computedFormationLevel
      : 0

  // Formation template offsets
  const halfCW = template.carriagewayWidth / 2
  const shoulderEndOffset = halfCW + template.shoulderWidth

  // Slope ratios for labels
  const activeSlopeStr = isCut ? template.cutSlope : template.fillSlope
  let activeSlopeRatio = 0
  try {
    activeSlopeRatio = parseSlopeRatio(activeSlopeStr)
  } catch {
    // fallback
  }

  // Ground polygon points for fill below ground line
  const groundFillPoints = useMemo(() => {
    if (sortedGround.length < 2) return ''
    const yBottom = toSvgY(
      Math.min(...sortedGround.map(p => p.level)) - 2
    )
    const pts = sortedGround
      .map(p => `${toSvgX(p.offset).toFixed(1)},${toSvgY(p.level).toFixed(1)}`)
      .join(' ')
    // Close the polygon at the bottom
    return `${pts} ${toSvgX(sortedGround[sortedGround.length - 1].offset).toFixed(1)},${yBottom.toFixed(1)} ${toSvgX(sortedGround[0].offset).toFixed(1)},${yBottom.toFixed(1)}`
  }, [sortedGround, toSvgX, toSvgY])

  // Ground polyline points
  const groundPolyline = useMemo(
    () =>
      sortedGround
        .map(p => `${toSvgX(p.offset).toFixed(1)},${toSvgY(p.level).toFixed(1)}`)
        .join(' '),
    [sortedGround, toSvgX, toSvgY]
  )

  // Formation polyline points (carriageway only)
  const carriagewayPolyline = useMemo(
    () =>
      camberProfile
        .map(p => `${toSvgX(p.offset).toFixed(1)},${toSvgY(p.level).toFixed(1)}`)
        .join(' '),
    [camberProfile, toSvgX, toSvgY]
  )

  // Full formation line polyline
  const formationPolyline = useMemo(
    () =>
      formationLine
        .map(p => `${toSvgX(p.offset).toFixed(1)},${toSvgY(p.level).toFixed(1)}`)
        .join(' '),
    [formationLine, toSvgX, toSvgY]
  )

  // Slope lines — separate left and right slope segments
  const leftSlopePoints = useMemo(() => {
    const leftShoulder = formationLine.find(
      p => Math.abs(p.offset - (-(halfCW + template.shoulderWidth))) < 0.01
    )
    const leftIntercept = formationLine[0]
    if (!leftShoulder || !leftIntercept) return null
    return {
      x1: toSvgX(leftShoulder.offset),
      y1: toSvgY(leftShoulder.level),
      x2: toSvgX(leftIntercept.offset),
      y2: toSvgY(leftIntercept.level),
    }
  }, [formationLine, halfCW, template.shoulderWidth, toSvgX, toSvgY])

  const rightSlopePoints = useMemo(() => {
    const rightShoulder = formationLine.find(
      p => Math.abs(p.offset - (halfCW + template.shoulderWidth)) < 0.01
    )
    const rightIntercept = formationLine[formationLine.length - 1]
    if (!rightShoulder || !rightIntercept) return null
    return {
      x1: toSvgX(rightShoulder.offset),
      y1: toSvgY(rightShoulder.level),
      x2: toSvgX(rightIntercept.offset),
      y2: toSvgY(rightIntercept.level),
    }
  }, [formationLine, halfCW, template.shoulderWidth, toSvgX, toSvgY])

  // Shoulder lines
  const leftShoulderLine = useMemo(() => {
    const edge = camberProfile.find(p => Math.abs(p.offset - (-halfCW)) < 0.01)
    const shoulder = formationLine.find(
      p => Math.abs(p.offset - (-(halfCW + template.shoulderWidth))) < 0.01
    )
    if (!edge || !shoulder) return null
    return {
      x1: toSvgX(edge.offset),
      y1: toSvgY(edge.level),
      x2: toSvgX(shoulder.offset),
      y2: toSvgY(shoulder.level),
    }
  }, [camberProfile, formationLine, halfCW, template.shoulderWidth, toSvgX, toSvgY])

  const rightShoulderLine = useMemo(() => {
    const edge = camberProfile.find(p => Math.abs(p.offset - halfCW) < 0.01)
    const shoulder = formationLine.find(
      p => Math.abs(p.offset - (halfCW + template.shoulderWidth)) < 0.01
    )
    if (!edge || !shoulder) return null
    return {
      x1: toSvgX(edge.offset),
      y1: toSvgY(edge.level),
      x2: toSvgX(shoulder.offset),
      y2: toSvgY(shoulder.level),
    }
  }, [camberProfile, formationLine, halfCW, template.shoulderWidth, toSvgX, toSvgY])

  // Centreline SVG X position
  const clX = toSvgX(0)
  const formSvgY = toSvgY(computedFormationLevel)
  const subgradeSvgY = toSvgY(subgradeLevel)

  // Section type label
  const sectionLabel = useMemo(() => {
    if (areas.cutArea > 0.01 && areas.fillArea > 0.01) {
      return 'CUT/FILL'
    }
    if (areas.cutArea > 0.01) {
      return 'CUT'
    }
    if (areas.fillArea > 0.01) {
      return 'FILL'
    }
    return 'LEVEL'
  }, [areas])

  const sectionLabelColor = useMemo(() => {
    if (areas.cutArea > 0.01 && areas.fillArea > 0.01) return '#7C3AED'
    if (areas.cutArea > 0.01) return COLORS.cutLabel
    if (areas.fillArea > 0.01) return COLORS.fillLabel
    return COLORS.labelSecondary
  }, [areas])

  return (
    <svg
      width={width}
      height={height}
      viewBox={viewBox}
      className="block"
      style={{ background: COLORS.background }}
      role="img"
      aria-label={`Cross-section at chainage ${formatChainage(chainage)}`}
    >
      {/* Arrow markers for dimensions */}
      <ArrowHead id="dim-start" />
      <ArrowHead id="dim-end" />
      <ArrowHead id="dim-v-start" />
      <ArrowHead id="dim-v-end" />

      {/* ── Grid: centreline ── */}
      <line
        x1={clX}
        y1={0}
        x2={clX}
        y2={height}
        stroke={COLORS.centreLine}
        strokeWidth={0.5}
        strokeDasharray="6,4"
      />

      {/* ── Offset markers ── */}
      {showLabels && (
        <>
          {[10, 20, 30, 40, 50].forEach(offset => {
            // Only render if within the view
            const svgXLeft = toSvgX(-offset)
            const svgXRight = toSvgX(offset)
            if (svgXLeft < 0 && svgXRight > width) return
            return (
              <g key={offset}>
                {svgXLeft > 0 && (
                  <>
                    <line
                      x1={svgXLeft}
                      y1={height - 8}
                      x2={svgXLeft}
                      y2={height - 2}
                      stroke={COLORS.offsetMarker}
                      strokeWidth={0.5}
                    />
                    <text
                      x={svgXLeft}
                      y={height - 0.5}
                      fontSize="5"
                      fill={COLORS.labelSecondary}
                      textAnchor="middle"
                      fontFamily="monospace"
                    >
                      {offset}
                    </text>
                  </>
                )}
                {svgXRight < width && (
                  <>
                    <line
                      x1={svgXRight}
                      y1={height - 8}
                      x2={svgXRight}
                      y2={height - 2}
                      stroke={COLORS.offsetMarker}
                      strokeWidth={0.5}
                    />
                    <text
                      x={svgXRight}
                      y={height - 0.5}
                      fontSize="5"
                      fill={COLORS.labelSecondary}
                      textAnchor="middle"
                      fontFamily="monospace"
                    >
                      {offset}
                    </text>
                  </>
                )}
              </g>
            )
          })}
        </>
      )}

      {/* ── Ground profile fill (below ground line) ── */}
      {groundFillPoints && (
        <polygon
          points={groundFillPoints}
          fill={COLORS.groundFill}
          stroke="none"
        />
      )}

      {/* ── Ground profile line ── */}
      <polyline
        points={groundPolyline}
        fill="none"
        stroke={COLORS.groundLine}
        strokeWidth={2}
        strokeLinejoin="round"
      />

      {/* ── Fill slope (right side if fill) ── */}
      {isFill && rightSlopePoints && (
        <line
          x1={rightSlopePoints.x1}
          y1={rightSlopePoints.y1}
          x2={rightSlopePoints.x2}
          y2={rightSlopePoints.y2}
          stroke={COLORS.fillSlope}
          strokeWidth={1.5}
          strokeDasharray="4,2"
        />
      )}
      {isFill && leftSlopePoints && (
        <line
          x1={leftSlopePoints.x1}
          y1={leftSlopePoints.y1}
          x2={leftSlopePoints.x2}
          y2={leftSlopePoints.y2}
          stroke={COLORS.fillSlope}
          strokeWidth={1.5}
          strokeDasharray="4,2"
        />
      )}

      {/* ── Cut slope (left side if cut) ── */}
      {isCut && leftSlopePoints && (
        <line
          x1={leftSlopePoints.x1}
          y1={leftSlopePoints.y1}
          x2={leftSlopePoints.x2}
          y2={leftSlopePoints.y2}
          stroke={COLORS.cutSlope}
          strokeWidth={1.5}
          strokeDasharray="4,2"
        />
      )}
      {isCut && rightSlopePoints && (
        <line
          x1={rightSlopePoints.x1}
          y1={rightSlopePoints.y1}
          x2={rightSlopePoints.x2}
          y2={rightSlopePoints.y2}
          stroke={COLORS.cutSlope}
          strokeWidth={1.5}
          strokeDasharray="4,2"
        />
      )}

      {/* ── Shoulders ── */}
      {leftShoulderLine && (
        <line
          x1={leftShoulderLine.x1}
          y1={leftShoulderLine.y1}
          x2={leftShoulderLine.x2}
          y2={leftShoulderLine.y2}
          stroke={COLORS.shoulder}
          strokeWidth={2.5}
          strokeLinecap="round"
        />
      )}
      {rightShoulderLine && (
        <line
          x1={rightShoulderLine.x1}
          y1={rightShoulderLine.y1}
          x2={rightShoulderLine.x2}
          y2={rightShoulderLine.y2}
          stroke={COLORS.shoulder}
          strokeWidth={2.5}
          strokeLinecap="round"
        />
      )}

      {/* ── Carriageway with camber ── */}
      <polyline
        points={carriagewayPolyline}
        fill="none"
        stroke={COLORS.carriageway}
        strokeWidth={3}
        strokeLinejoin="round"
        strokeLinecap="round"
      />

      {/* ── Subgrade (dashed) ── */}
      {template.subgradeDepth > 0 && (
        <line
          x1={toSvgX(-shoulderEndOffset - 2)}
          y1={subgradeSvgY}
          x2={toSvgX(shoulderEndOffset + 2)}
          y2={subgradeSvgY}
          stroke={COLORS.subgrade}
          strokeWidth={0.8}
          strokeDasharray="6,3"
        />
      )}

      {/* ── DIMENSIONS ── */}
      {showLabels && (
        <>
          {/* Carriageway width dimension */}
          <DimensionLine
            x1={toSvgX(-halfCW)}
            y1={formSvgY}
            x2={toSvgX(halfCW)}
            y2={formSvgY}
            label={`${template.carriagewayWidth.toFixed(1)}m`}
            offsetDir={12}
            id="cw"
          />

          {/* Left shoulder width dimension */}
          <DimensionLine
            x1={toSvgX(-halfCW)}
            y1={formSvgY}
            x2={toSvgX(-(halfCW + template.shoulderWidth))}
            y2={formSvgY}
            label={`${template.shoulderWidth.toFixed(1)}m`}
            offsetDir={-10}
            id="ls"
          />

          {/* Right shoulder width dimension */}
          <DimensionLine
            x1={toSvgX(halfCW)}
            y1={formSvgY}
            x2={toSvgX(halfCW + template.shoulderWidth)}
            y2={formSvgY}
            label={`${template.shoulderWidth.toFixed(1)}m`}
            offsetDir={10}
            id="rs"
          />

          {/* Cut/fill depth arrow at centreline */}
          {centreGroundLevel !== null && Math.abs(centreDepth) > 0.01 && (
            <g>
              <line
                x1={clX}
                y1={toSvgY(centreGroundLevel)}
                x2={clX}
                y2={formSvgY}
                stroke={centreDepth > 0 ? COLORS.cutLabel : COLORS.fillLabel}
                strokeWidth={0.8}
                markerStart={
                  centreDepth > 0
                    ? 'url(#dim-v-start)'
                    : 'url(#dim-v-end)'
                }
                markerEnd={
                  centreDepth > 0
                    ? 'url(#dim-v-end)'
                    : 'url(#dim-v-start)'
                }
              />
              <text
                x={clX + 6}
                y={(toSvgY(centreGroundLevel) + formSvgY) / 2 + 2.5}
                fontSize="7"
                fill={centreDepth > 0 ? COLORS.cutLabel : COLORS.fillLabel}
                fontFamily="monospace"
              >
                {Math.abs(centreDepth).toFixed(3)}m
              </text>
            </g>
          )}
        </>
      )}

      {/* ── LABELS ── */}
      {showLabels && (
        <>
          {/* Chainage label (top-left) */}
          <g>
            <rect
              x={8}
              y={8}
              width={90}
              height={18}
              rx={3}
              fill="white"
              fillOpacity={0.9}
              stroke="#E5E7EB"
              strokeWidth={0.5}
            />
            <text
              x={14}
              y={21}
              fontSize="9"
              fill={COLORS.labelPrimary}
              fontFamily="monospace"
              fontWeight="600"
            >
              CH {formatChainage(chainage)}
            </text>
          </g>

          {/* Cut/Fill area label (top-right) */}
          <g>
            <rect
              x={width - 140}
              y={8}
              width={132}
              height={18}
              rx={3}
              fill={sectionLabelColor}
              fillOpacity={0.1}
              stroke={sectionLabelColor}
              strokeWidth={0.5}
            />
            <text
              x={width - 134}
              y={21}
              fontSize="9"
              fill={sectionLabelColor}
              fontFamily="monospace"
              fontWeight="600"
            >
              {sectionLabel}{' '}
              {(sectionLabel === 'CUT' || sectionLabel === 'CUT/FILL') &&
                areas.cutArea.toFixed(2) + 'm\u00B2'}
              {sectionLabel === 'CUT/FILL' && ' / '}
              {(sectionLabel === 'FILL' || sectionLabel === 'CUT/FILL') &&
                areas.fillArea.toFixed(2) + 'm\u00B2'}
            </text>
          </g>

          {/* Formation level label */}
          <text
            x={clX + 4}
            y={formSvgY - 4}
            fontSize="6"
            fill={COLORS.labelSecondary}
            fontFamily="monospace"
          >
            FL {computedFormationLevel.toFixed(3)}
          </text>

          {/* Subgrade level label */}
          {template.subgradeDepth > 0 && (
            <text
              x={toSvgX(shoulderEndOffset + 3)}
              y={subgradeSvgY + 3}
              fontSize="6"
              fill={COLORS.labelSecondary}
              fontFamily="monospace"
            >
              SG {subgradeLevel.toFixed(3)}
            </text>
          )}

          {/* Slope ratio labels */}
          {leftSlopePoints && activeSlopeRatio > 0 && (
            <text
              x={(leftSlopePoints.x1 + leftSlopePoints.x2) / 2}
              y={Math.min(leftSlopePoints.y1, leftSlopePoints.y2) - 4}
              fontSize="6"
              fill={COLORS.labelSecondary}
              textAnchor="middle"
              fontFamily="monospace"
            >
              {activeSlopeStr}
            </text>
          )}
          {rightSlopePoints && activeSlopeRatio > 0 && (
            <text
              x={(rightSlopePoints.x1 + rightSlopePoints.x2) / 2}
              y={Math.min(rightSlopePoints.y1, rightSlopePoints.y2) - 4}
              fontSize="6"
              fill={COLORS.labelSecondary}
              textAnchor="middle"
              fontFamily="monospace"
            >
              {activeSlopeStr}
            </text>
          )}

          {/* Camber label */}
          <text
            x={clX}
            y={formSvgY + 12}
            fontSize="6"
            fill={COLORS.labelSecondary}
            textAnchor="middle"
            fontFamily="monospace"
          >
            {template.camber}% camber
          </text>

          {/* Ground level at centreline */}
          {centreGroundLevel !== null && (
            <text
              x={clX - 4}
              y={toSvgY(centreGroundLevel) - 4}
              fontSize="6"
              fill={COLORS.groundLine}
              textAnchor="end"
              fontFamily="monospace"
            >
              GL {centreGroundLevel.toFixed(3)}
            </text>
          )}

          {/* CL label */}
          <text
            x={clX}
            y={height - 12}
            fontSize="6"
            fill={COLORS.labelSecondary}
            textAnchor="middle"
            fontFamily="monospace"
            fontWeight="500"
          >
            CL
          </text>
        </>
      )}
    </svg>
  )
}

export default CrossSectionRenderer

'use client'

/**
 * CutFillPanel — Earthwork cut/fill visualization
 *
 * Lets surveyors:
 * - Import existing ground surface (CSV: E, N, Z)
 * - Import design grade surface (CSV: E, N, Z)
 * - Compute cut/fill volumes
 * - View heat map (red=cut, green=fill)
 * - Export CSV report
 */

import { useState, useCallback, useMemo } from 'react'
import {
  Mountain, Upload, Download, Loader2, CheckCircle2,
  AlertTriangle, Table,
} from 'lucide-react'
import {
  computeCutFill,
  getHeatMapColor,
  generateCutFillReport,
  type GridSurface,
  type GridPoint,
  type CutFillResult,
} from '@/lib/engine/cutFillEngine'

export function CutFillPanel() {
  const [existingSurface, setExistingSurface] = useState<GridSurface | null>(null)
  const [designSurface, setDesignSurface] = useState<GridSurface | null>(null)
  const [result, setResult] = useState<CutFillResult | null>(null)
  const [computing, setComputing] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const parseSurfaceCSV = useCallback((text: string): GridSurface => {
    const lines = text.split('\n').filter(l => l.trim())
    const points: GridPoint[] = []
    let minE = Infinity, maxE = -Infinity, minN = Infinity, maxN = -Infinity

    for (const line of lines) {
      const cols = line.split(',').map(c => c.trim())
      if (cols.length < 3) continue
      const e = parseFloat(cols[0])
      const n = parseFloat(cols[1])
      const z = parseFloat(cols[2])
      if (!isFinite(e) || !isFinite(n) || !isFinite(z)) continue
      points.push({ easting: e, northing: n, elevation: z })
      minE = Math.min(minE, e)
      maxE = Math.max(maxE, e)
      minN = Math.min(minN, n)
      maxN = Math.max(maxN, n)
    }

    // Infer grid spacing
    const spacing = points.length > 1 ? Math.sqrt(Math.abs((maxE - minE) * (maxN - minN)) / points.length) : 1
    const cols_count = Math.round((maxE - minE) / spacing) + 1
    const rows = Math.round((maxN - minN) / spacing) + 1

    return { points, spacing, rows, cols: cols_count }
  }, [])

  const handleFileUpload = useCallback(async (file: File, type: 'existing' | 'design') => {
    try {
      const text = await file.text()
      const surface = parseSurfaceCSV(text)
      if (type === 'existing') setExistingSurface(surface)
      else setDesignSurface(surface)
      setResult(null)
    } catch (err) {
      setError('Failed to parse CSV file')
    }
  }, [parseSurfaceCSV])

  const handleCompute = useCallback(() => {
    if (!existingSurface || !designSurface) return
    setComputing(true)
    setError(null)
    try {
      const res = computeCutFill(existingSurface, designSurface)
      setResult(res)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Computation failed')
    } finally {
      setComputing(false)
    }
  }, [existingSurface, designSurface])

  const handleExport = useCallback(() => {
    if (!result) return
    const csv = generateCutFillReport(result)
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = 'cut-fill-report.csv'
    a.click()
    URL.revokeObjectURL(url)
  }, [result])

  return (
    <div className="space-y-4">
      {/* Surface imports */}
      <div className="grid grid-cols-2 gap-3">
        <SurfaceImportCard
          label="Existing Ground"
          surface={existingSurface}
          onUpload={(file) => handleFileUpload(file, 'existing')}
        />
        <SurfaceImportCard
          label="Design Grade"
          surface={designSurface}
          onUpload={(file) => handleFileUpload(file, 'design')}
        />
      </div>

      {/* Compute button */}
      <button
        onClick={handleCompute}
        disabled={!existingSurface || !designSurface || computing}
        className="w-full flex items-center justify-center gap-2 h-10 rounded-lg bg-[var(--accent)] text-black text-sm font-semibold hover:bg-[var(--accent-dim)] disabled:opacity-40"
      >
        {computing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Mountain className="w-4 h-4" />}
        {computing ? 'Computing...' : 'Compute Cut & Fill'}
      </button>

      {error && (
        <div className="p-3 rounded-lg bg-red-500/5 border border-red-500/20 text-xs text-red-400">{error}</div>
      )}

      {/* Results */}
      {result && (
        <>
          {/* Summary */}
          <div className="grid grid-cols-3 gap-2">
            <div className="p-3 rounded-lg bg-red-500/5 border border-red-500/20 text-center">
              <div className="text-lg font-bold text-red-400">{result.totalCutVolume.toFixed(1)}</div>
              <div className="text-[9px] text-gray-500 uppercase">Cut (m³)</div>
            </div>
            <div className="p-3 rounded-lg bg-emerald-500/5 border border-emerald-500/20 text-center">
              <div className="text-lg font-bold text-emerald-400">{result.totalFillVolume.toFixed(1)}</div>
              <div className="text-[9px] text-gray-500 uppercase">Fill (m³)</div>
            </div>
            <div className={`p-3 rounded-lg border text-center ${
              result.netVolume < 0 ? 'bg-red-500/5 border-red-500/20' : 'bg-emerald-500/5 border-emerald-500/20'
            }`}>
              <div className={`text-lg font-bold ${result.netVolume < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                {result.netVolume > 0 ? '+' : ''}{result.netVolume.toFixed(1)}
              </div>
              <div className="text-[9px] text-gray-500 uppercase">Net (m³)</div>
            </div>
          </div>

          {/* Heat map grid */}
          <div className="card p-4">
            <div className="flex items-center justify-between mb-2">
              <span className="text-xs font-semibold text-[var(--text-primary)]">Heat Map</span>
              <button
                onClick={handleExport}
                className="flex items-center gap-1 px-2 h-7 rounded bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-[10px] text-gray-400 hover:text-gray-200"
              >
                <Download className="w-3 h-3" />
                Export CSV
              </button>
            </div>
            <div
              className="grid gap-px overflow-hidden rounded-lg"
              style={{
                gridTemplateColumns: `repeat(${Math.min(result.cells.length, 20)}, 1fr)`,
                maxHeight: '200px',
              }}
            >
              {result.cells.slice(0, 400).map((cell, i) => (
                <div
                  key={`${cell}-${i}`}
                  className="aspect-square"
                  style={{ backgroundColor: getHeatMapColor(cell.deltaZ) }}
                  title={`E:${cell.easting.toFixed(1)} N:${cell.northing.toFixed(1)} ΔZ:${cell.deltaZ.toFixed(2)}m`}
                />
              ))}
            </div>
            <div className="flex items-center justify-between mt-2 text-[9px] text-gray-500">
              <span className="flex items-center gap-1"><span className="w-3 h-3 bg-red-500 rounded-sm" /> Cut</span>
              <span className="flex items-center gap-1"><span className="w-3 h-3 bg-gray-500 rounded-sm" /> No change</span>
              <span className="flex items-center gap-1"><span className="w-3 h-3 bg-emerald-500 rounded-sm" /> Fill</span>
            </div>
          </div>

          {/* Additional stats */}
          <div className="grid grid-cols-2 gap-2 text-xs">
            <div className="p-2 rounded-lg bg-[var(--bg-tertiary)]/50">
              <span className="text-gray-500">Cut area:</span> <span className="text-red-400">{result.cutArea.toFixed(0)} m²</span>
            </div>
            <div className="p-2 rounded-lg bg-[var(--bg-tertiary)]/50">
              <span className="text-gray-500">Fill area:</span> <span className="text-emerald-400">{result.fillArea.toFixed(0)} m²</span>
            </div>
            <div className="p-2 rounded-lg bg-[var(--bg-tertiary)]/50">
              <span className="text-gray-500">Max cut:</span> <span className="text-red-400">{result.maxCutDepth.toFixed(2)} m</span>
            </div>
            <div className="p-2 rounded-lg bg-[var(--bg-tertiary)]/50">
              <span className="text-gray-500">Max fill:</span> <span className="text-emerald-400">{result.maxFillDepth.toFixed(2)} m</span>
            </div>
          </div>
        </>
      )}
    </div>
  )
}

function SurfaceImportCard({ label, surface, onUpload }: {
  label: string
  surface: GridSurface | null
  onUpload: (file: File) => void
}) {
  return (
    <div className="card p-3">
      <div className="text-[10px] font-semibold text-gray-500 uppercase tracking-wider mb-2">{label}</div>
      {surface ? (
        <div className="flex items-center gap-2">
          <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0" />
          <div className="flex-1 min-w-0">
            <div className="text-xs text-[var(--text-primary)]">{surface.points.length} points</div>
            <div className="text-[9px] text-gray-500">Grid: {surface.rows}×{surface.cols} @ {surface.spacing.toFixed(1)}m</div>
          </div>
        </div>
      ) : (
        <label className="flex flex-col items-center justify-center h-16 border-2 border-dashed border-[var(--border-color)] rounded-lg cursor-pointer hover:border-[var(--accent)]/30">
          <Upload className="w-4 h-4 text-gray-500 mb-1" />
          <span className="text-[10px] text-gray-500">Upload CSV (E,N,Z)</span>
