'use client';

import React, { useState, useCallback } from 'react'
import { AlertTriangle } from 'lucide-react'
import { manningPipeCapacity, rationalMethodCatchment, manningChannelCapacity, sizePipe, MANNING_N, RUNOFF_COEFFICIENTS, STANDARD_PIPE_SIZES } from '@/lib/engineering/drainageDesign'

type Tab = 'pipe' | 'catchment' | 'channel'

// ─── HELPERS ──────────────────────────────────────────────────────────────────

/** Returns formatted number or "—" when value is NaN / Infinity / negative-where-invalid */
function safeNum(value: number, decimals: number = 4): string {
  if (value === null || value === undefined || !Number.isFinite(value) || Number.isNaN(value)) return '—'
  return value.toFixed(decimals)
}

/** Returns a boolean — true when value is usable for display */
function isValid(v: number): boolean {
  return Number.isFinite(v) && !Number.isNaN(v)
}

function downloadCsv(filename: string, rows: string[][]) {
  const csv = rows.map(r => r.map(c => `"${c}"`).join(',')).join('\n')
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = filename
  a.click()
  URL.revokeObjectURL(url)
}

// ─── INLINE ERROR COMPONENT ───────────────────────────────────────────────────

function FieldError({ message }: { message: string | undefined }) {
  if (!message) return null
  return <p className="text-xs text-red-400 mt-1">{message}</p>
}

// ─── SHARED INPUT CLASSES ─────────────────────────────────────────────────────

const inputCls = 'w-full border border-zinc-700 rounded-lg px-3 py-2 text-sm bg-zinc-800 text-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent'
const selectCls = 'w-full border border-zinc-700 rounded-lg px-3 py-2 text-sm bg-zinc-800 text-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent'

// ─── MAIN PANEL ───────────────────────────────────────────────────────────────

export default function DrainageDesignPanel({ roadLength = 1000 }: { roadLength?: number }) {
  const [tab, setTab] = useState<Tab>('pipe')

  return (
    <div className="space-y-6">
      <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
        <h3 className="text-lg font-semibold text-white">Drainage Design</h3>
        <p className="text-sm text-zinc-400 mt-1">Manning&apos;s equation, Rational Method, pipe &amp; channel sizing — RDM 1.3</p>
      </div>

      {/* Tabs */}
      <div className="flex gap-1 bg-zinc-800 rounded-lg p-1">
        {([['pipe', 'Pipe Sizing'], ['catchment', 'Catchment'], ['channel', 'Channel']] as const).map(([k, l]) => (
          <button key={k} onClick={() => setTab(k)}
            className={`flex-1 py-2 px-4 rounded-md text-sm font-medium transition-colors ${tab === k ? 'bg-zinc-700 shadow text-white' : 'text-zinc-400 hover:text-white'}`}>
            {l}
          </button>
        ))}
      </div>

      {tab === 'pipe' && <PipeSizingTab />}
      {tab === 'catchment' && <CatchmentTab />}
      {tab === 'channel' && <ChannelTab />}
    </div>
  )
}

// ─── PIPE SIZING TAB ──────────────────────────────────────────────────────────

function PipeSizingTab() {
  const [peakFlow, setPeakFlow] = useState(0.5)
  const [slope, setSlope] = useState(0.5)
  const [material, setMaterial] = useState('Concrete pipe')
  const [customDiameter, setCustomDiameter] = useState(300)
  const [showResult, setShowResult] = useState(false)

  const manningN = MANNING_N[material] || 0.013
  const slopeDecimal = slope / 100

  // ── Validation ──
  const errors = {
    peakFlow: peakFlow <= 0 ? 'Peak flow must be > 0' : undefined,
    slope: slope <= 0 ? 'Slope must be > 0' : undefined,
  }

  const hasAnyError = Object.values(errors).some(Boolean)

  // ── Computed results (NaN-safe) ──
  const sizing = peakFlow > 0 && slopeDecimal > 0 ? sizePipe(peakFlow, manningN, slopeDecimal) : null
  const customResult = customDiameter > 0 && slopeDecimal > 0
    ? manningPipeCapacity({ diameter: customDiameter, manningN, slope: slopeDecimal })
    : null
  const minSlopeForCustom = (manningN && customDiameter > 0)
    ? Math.pow(0.6 * manningN / Math.pow((customDiameter / 1000) / 4, 2 / 3), 2) * 100
    : NaN

  const hasWarning = slope <= 0 || peakFlow <= 0 || customDiameter <= 0

  // ── CSV Export ──
  const handleExport = useCallback(() => {
    const rows: string[][] = [
      ['Drainage Design — Pipe Sizing Summary'],
      [],
      ['Parameter', 'Value'],
      ['Peak Flow (m³/s)', String(peakFlow)],
      ['Slope (%)', String(slope)],
      ['Slope (m/m)', String(slopeDecimal)],
      ['Material', material],
      ["Manning's n", String(manningN)],
      ['Custom Diameter (mm)', String(customDiameter)],
      [],
      ['Result', 'Value'],
      ['Full Bore Capacity (m³/s)', customResult ? String(customResult.fullBoreCapacity) : '—'],
      ['Full Bore Velocity (m/s)', customResult ? String(customResult.fullBoreVelocity) : '—'],
      ['Self-Cleansing', customResult ? String(customResult.isSelfCleansing) : '—'],
      ['Velocity Acceptable', customResult ? String(customResult.isVelocityAcceptable) : '—'],
      ['Min Slope for Self-Cleansing (%)', isValid(minSlopeForCustom) ? String(minSlopeForCustom) : '—'],
    ]
    if (sizing) {
      rows.push([], ['Recommended Pipe', 'Value'])
      rows.push(['Diameter (mm)', String(sizing.diameter)])
      rows.push(['Capacity (m³/s)', String(sizing.capacity)])
      rows.push(['Velocity (m/s)', String(sizing.velocity)])
    }
    downloadCsv('drainage_pipe_sizing.csv', rows)
  }, [peakFlow, slope, slopeDecimal, material, manningN, customDiameter, customResult, minSlopeForCustom, sizing])

  return (
    <div className="space-y-6">
      {/* Warning banner */}
      {hasWarning && (
        <div className="bg-amber-950/50 border border-amber-700 rounded-lg p-3 text-sm text-amber-300">
          <AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> Invalid inputs detected — computed results may be unavailable. Fix highlighted fields below.
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Left: Inputs */}
        <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6 space-y-4">
          <h4 className="font-medium text-white">Pipe Sizing</h4>
          <div>
            <label className="block text-xs text-zinc-400 mb-1" htmlFor="peak-flow-m-s">Peak Flow (m³/s)</label>
            <input id="peak-flow-m-s" aria-label="Peak Flow (m³/s)" type="number" step="0.01" className={`${inputCls} ${errors.peakFlow ? 'border-red-500' : ''}`}
              value={peakFlow} onChange={e => { setPeakFlow(parseFloat(e.target.value) || 0); setShowResult(false) }} />
            <FieldError message={errors.peakFlow} />
          </div>
          <div>
            <label className="block text-xs text-zinc-400 mb-1" htmlFor="pipe-slope">Pipe Slope (%)</label>
            <input id="pipe-slope" aria-label="Pipe Slope (%)" type="number" step="0.1" className={`${inputCls} ${errors.slope ? 'border-red-500' : ''}`}
              value={slope} onChange={e => { setSlope(parseFloat(e.target.value) || 0); setShowResult(false) }} />
            <FieldError message={errors.slope} />
          </div>
          <div>
            <label className="block text-xs text-zinc-400 mb-1">Material (Manning&apos;s n = {manningN})</label>
            <select className={selectCls}
              value={material} onChange={e => setMaterial(e.target.value)}>
              {Object.entries(MANNING_N).map(([name, n]) => (
                <option key={name} value={name}>{name} (n={n})</option>
              ))}
            </select>
          </div>
          <button onClick={() => setShowResult(true)}
            disabled={hasAnyError}
            className="w-full px-4 py-3 bg-blue-600 text-white rounded-lg font-medium hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed">
            Size Pipe
          </button>
        </div>

        {/* Right: Custom Pipe Check */}
        <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6 space-y-4">
          <div className="flex items-center justify-between">
            <h4 className="font-medium text-white">Custom Pipe Check</h4>
            <button onClick={handleExport}
              className="text-xs px-3 py-1.5 border border-zinc-600 rounded-md text-zinc-300 hover:text-white hover:border-zinc-400 transition-colors">
              ↓ Download CSV
            </button>
          </div>
          <div>
            <label className="block text-xs text-zinc-400 mb-1" htmlFor="diameter-mm">Diameter (mm)</label>
            <select id="diameter-mm" className={selectCls}
              value={customDiameter} onChange={e => setCustomDiameter(parseInt(e.target.value))}>
              {STANDARD_PIPE_SIZES.map(d => <option key={d} value={d}>{d} mm</option>)}
            </select>
          </div>
          {customResult ? (
            <div className="space-y-2 pt-2">
              <div className="flex justify-between text-sm">
                <span className="text-zinc-400">Full Bore Capacity</span>
                <span className="font-mono font-medium text-white">{safeNum(customResult.fullBoreCapacity)} m³/s</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-zinc-400">Full Bore Velocity</span>
                <span className={`font-mono font-medium ${customResult.isSelfCleansing ? 'text-emerald-400' : 'text-red-400'}`}>
                  {safeNum(customResult.fullBoreVelocity, 2)} m/s
                </span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-zinc-400">Self-Cleansing (≥0.6 m/s)</span>
                <span className={customResult.isSelfCleansing ? 'text-emerald-400' : 'text-red-400'}>
                  {customResult.isSelfCleansing ? 'YES' : 'NO'}
                </span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-zinc-400">Velocity Acceptable</span>
                <span className={customResult.isVelocityAcceptable ? 'text-emerald-400' : 'text-amber-400'}>
                  {customResult.isVelocityAcceptable ? 'YES' : 'NO (check lining)'}
                </span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-zinc-400">Min Slope for Self-Cleansing</span>
                <span className="font-mono">{safeNum(minSlopeForCustom, 2)}%</span>
              </div>
            </div>
          ) : (
            <div className="pt-2 text-sm text-zinc-500">Enter valid slope and diameter to see results.</div>
          )}
        </div>
      </div>

      {/* Sizing result */}
      {showResult && sizing && (
        <div className={`rounded-xl border-2 p-6 border-emerald-500 bg-emerald-950/30`}>
          <h4 className="font-medium text-white mb-3">Recommended Pipe Size</h4>
          <div className="grid grid-cols-3 gap-4">
            <div>
              <div className="text-xs text-zinc-400">Diameter</div>
              <div className="text-xl font-bold text-white">{sizing.diameter} mm</div>
            </div>
            <div>
              <div className="text-xs text-zinc-400">Capacity</div>
              <div className="text-xl font-bold text-white">{safeNum(sizing.capacity)} m³/s</div>
            </div>
            <div>
              <div className="text-xs text-zinc-400">Velocity</div>
              <div className="text-xl font-bold text-white">{safeNum(sizing.velocity, 2)} m/s</div>
            </div>
          </div>
        </div>
      )}

      {/* No sizing result warning */}
      {showResult && !sizing && (
        <div className="rounded-xl border-2 p-6 border-amber-500 bg-amber-950/30">
          <h4 className="font-medium text-amber-300 mb-2">No Suitable Standard Size Found</h4>
          <p className="text-sm text-zinc-400">No standard pipe size meets both the capacity and self-cleansing requirements. Try increasing slope or using a non-standard diameter.</p>
        </div>
      )}
    </div>
  )
}

// ─── CATCHMENT TAB ────────────────────────────────────────────────────────────

function CatchmentTab() {
  const [area, setArea] = useState(10)
  const [landUse, setLandUse] = useState('Grass/Park')
  const [intensity, setIntensity] = useState(50)

  const C = RUNOFF_COEFFICIENTS[landUse]?.typical || 0.15

  // ── Validation ──
  const errors = {
    area: area <= 0 ? 'Catchment area must be > 0' : undefined,
    intensity: intensity <= 0 ? 'Rainfall intensity must be > 0' : undefined,
  }

  const hasAnyError = Object.values(errors).some(Boolean)

  // ── Computed (NaN-safe) ──
  const result = area > 0 && intensity > 0
    ? rationalMethodCatchment({ area, runoffCoefficient: C, rainfallIntensity: intensity, timeOfConcentration: 10 })
    : null

  const hasWarning = area <= 0 || intensity <= 0

  // ── CSV Export ──
  const handleExport = useCallback(() => {
    const rows: string[][] = [
      ['Drainage Design — Catchment Analysis Summary'],
      [],
      ['Parameter', 'Value'],
      ['Catchment Area (ha)', String(area)],
      ['Land Use', landUse],
      ['Runoff Coefficient (C)', String(C)],
      ['Rainfall Intensity (mm/hr)', String(intensity)],
      ['Time of Concentration (min)', '10'],
      [],
      ['Result', 'Value'],
      ['Peak Flow (m³/s)', result ? String(result.peakFlow) : '—'],
      ['Effective Area (ha)', result ? String(result.effectiveArea) : '—'],
      ['Return Period', result ? result.returnPeriod : '—'],
    ]
    downloadCsv('drainage_catchment.csv', rows)
  }, [area, landUse, C, intensity, result])

  return (
    <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6 space-y-6">
      {/* Warning banner */}
      {hasWarning && (
        <div className="bg-amber-950/50 border border-amber-700 rounded-lg p-3 text-sm text-amber-300">
          <AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> Invalid inputs detected — computed results may be unavailable. Fix highlighted fields below.
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Left: Inputs */}
        <div className="space-y-4">
          <h4 className="font-medium text-white">Catchment Analysis (Rational Method)</h4>
          <div>
            <label className="block text-xs text-zinc-400 mb-1" htmlFor="catchment-area-hectares">Catchment Area (hectares)</label>
            <input id="catchment-area-hectares" aria-label="Catchment Area (hectares)" type="number" step="0.1" className={`${inputCls} ${errors.area ? 'border-red-500' : ''}`}
              value={area} onChange={e => setArea(parseFloat(e.target.value) || 0)} />
            <FieldError message={errors.area} />
          </div>
          <div>
            <label className="block text-xs text-zinc-400 mb-1">Land Use (C = {C})</label>
            <select className={selectCls} value={landUse} onChange={e => setLandUse(e.target.value)}>
              {Object.entries(RUNOFF_COEFFICIENTS).map(([name, val]) => (
                <option key={name} value={name}>{name} (C: {val.min}–{val.max}, typical {val.typical})</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-xs text-zinc-400 mb-1" htmlFor="rainfall-intensity-mm-hr">Rainfall Intensity (mm/hr)</label>
            <input id="rainfall-intensity-mm-hr" aria-label="Rainfall Intensity (mm/hr)" type="number" step="1" className={`${inputCls} ${errors.intensity ? 'border-red-500' : ''}`}
              value={intensity} onChange={e => setIntensity(parseFloat(e.target.value) || 0)} />
            <FieldError message={errors.intensity} />
          </div>
        </div>

        {/* Right: Results */}
        <div className="bg-zinc-800 rounded-xl p-6 space-y-3">
          <div className="flex items-center justify-between">
            <h4 className="font-medium text-white">Results</h4>
            <button onClick={handleExport}
              className="text-xs px-3 py-1.5 border border-zinc-600 rounded-md text-zinc-300 hover:text-white hover:border-zinc-400 transition-colors">
              ↓ Download CSV
            </button>
          </div>
          {result ? (
            <>
              <div className="flex justify-between text-sm">
                <span className="text-zinc-400">Peak Flow (Q = CIA/360)</span>
                <span className="font-mono font-bold text-blue-400">{safeNum(result.peakFlow)} m³/s</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-zinc-400">Catchment Area</span>
                <span className="font-mono text-white">{result.catchmentArea} ha</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-zinc-400">Effective Area (C × A)</span>
                <span className="font-mono text-white">{safeNum(result.effectiveArea, 2)} ha</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-zinc-400">Recommended Return Period</span>
                <span className="font-medium text-white">{result.returnPeriod}</span>
              </div>
              <div className="mt-4 p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-xs text-zinc-400">
                <strong className="text-white">Formula:</strong> Q = (C × I × A) / 360 = ({C} × {intensity} × {area}) / 360 = {safeNum(result.peakFlow)} m³/s
              </div>
            </>
          ) : (
            <p className="text-sm text-zinc-500">Enter valid area and intensity to see results.</p>
          )}
        </div>
      </div>
    </div>
  )
}

// ─── CHANNEL TAB ─────────────────────────────────────────────────────────────

function ChannelTab() {
  const [bedWidth, setBedWidth] = useState(1.0)
  const [sideSlope, setSideSlope] = useState(1.5)
  const [manningN, setManningN] = useState(0.015)
  const [slope, setSlope] = useState(0.5)
  const [flowDepth, setFlowDepth] = useState(0.5)

  const slopeDecimal = slope / 100

  // ── Validation ──
  const errors = {
    bedWidth: bedWidth <= 0 ? 'Bed width must be > 0' : undefined,
    slope: slope <= 0 ? 'Slope must be > 0' : undefined,
    manningN: manningN <= 0 ? "Manning's n must be > 0" : undefined,
    flowDepth: flowDepth <= 0 ? 'Flow depth must be > 0' : undefined,
  }

  const hasAnyError = Object.values(errors).some(Boolean)
  const hasWarning = hasAnyError

  // ── Computed (NaN-safe) ──
  const allValid = bedWidth > 0 && slopeDecimal > 0 && manningN > 0 && flowDepth > 0 && sideSlope > 0
  const result = allValid
    ? manningChannelCapacity({ bedWidth, sideSlope, manningN, slope: slopeDecimal, flowDepth })
    : null

  // ── CSV Export ──
  const handleExport = useCallback(() => {
    const rows: string[][] = [
      ['Drainage Design — Trapezoidal Channel Summary'],
      [],
      ['Parameter', 'Value'],
      ['Bed Width (m)', String(bedWidth)],
      ['Side Slope (H:V)', String(sideSlope)],
      ["Manning's n", String(manningN)],
      ['Slope (%)', String(slope)],
      ['Slope (m/m)', String(slopeDecimal)],
      ['Flow Depth (m)', String(flowDepth)],
      [],
      ['Result', 'Value'],
      ['Flow Area (m²)', result ? String(result.flowArea) : '—'],
      ['Wetted Perimeter (m)', result ? String(result.wettedPerimeter) : '—'],
      ['Hydraulic Radius (m)', result ? String(result.hydraulicRadius) : '—'],
      ['Velocity (m/s)', result ? String(result.velocity) : '—'],
      ['Discharge (m³/s)', result ? String(result.discharge) : '—'],
      ['Top Width (m)', result ? String(result.topWidth) : '—'],
      ['Self-Cleansing', result ? String(result.isSelfCleansing) : '—'],
    ]
    downloadCsv('drainage_channel.csv', rows)
  }, [bedWidth, sideSlope, manningN, slope, slopeDecimal, flowDepth, result])

  return (
    <div className="space-y-6">
      {/* Warning banner */}
      {hasWarning && (
        <div className="bg-amber-950/50 border border-amber-700 rounded-lg p-3 text-sm text-amber-300">
          <AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> Invalid inputs detected — computed results may be unavailable. Fix highlighted fields below.
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Left: Inputs */}
        <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6 space-y-4">
          <h4 className="font-medium text-white">Trapezoidal Channel Design</h4>
          <div>
            <label className="block text-xs text-zinc-400 mb-1" htmlFor="bed-width-m">Bed Width (m)</label>
            <input id="bed-width-m" aria-label="Bed Width (m)" type="number" step="0.1" className={`${inputCls} ${errors.bedWidth ? 'border-red-500' : ''}`}
              value={bedWidth} onChange={e => setBedWidth(parseFloat(e.target.value) || 0)} />
            <FieldError message={errors.bedWidth} />
          </div>
          <div>
            <label className="block text-xs text-zinc-400 mb-1" htmlFor="side-slope-h-v">Side Slope (H:V)</label>
            <input id="side-slope-h-v" aria-label="Side Slope (H:V)" type="number" step="0.1" className={inputCls}
              value={sideSlope} onChange={e => setSideSlope(parseFloat(e.target.value) || 0)} />
          </div>
          <div>
            <label className="block text-xs text-zinc-400 mb-1" htmlFor="manning-apos-s-n">Manning&apos;s n</label>
            <input id="manning-apos-s-n" aria-label="Mannings n" type="number" step="0.001" className={`${inputCls} ${errors.manningN ? 'border-red-500' : ''}`}
              value={manningN} onChange={e => setManningN(parseFloat(e.target.value) || 0)} />
            <FieldError message={errors.manningN} />
          </div>
          <div>
            <label className="block text-xs text-zinc-400 mb-1" htmlFor="slope">Slope (%)</label>
            <input id="slope" aria-label="Slope (%)" type="number" step="0.1" className={`${inputCls} ${errors.slope ? 'border-red-500' : ''}`}
              value={slope} onChange={e => setSlope(parseFloat(e.target.value) || 0)} />
            <FieldError message={errors.slope} />
          </div>
          <div>
            <label className="block text-xs text-zinc-400 mb-1" htmlFor="flow-depth-m">Flow Depth (m)</label>
            <input  id="flow-depth-m" aria-label="Flow Depth (m)" type="number" step="0.1" className={`${inputCls} ${errors.flowDepth ? 'border-red-500' : ''}`}
              value={flowDepth} onChange={e => setFlowDepth(parseFloat(e.target.value) || 0)} />
            <FieldError message={errors.flowDepth} />
          </div>
        </div>

        {/* Right: Cross-section SVG + Results */}
        <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
          <div className="flex items-center justify-between mb-4">
            <h4 className="font-medium text-white">Channel Cross-Section</h4>
            <button onClick={handleExport}
              className="text-xs px-3 py-1.5 border border-zinc-600 rounded-md text-zinc-300 hover:text-white hover:border-zinc-400 transition-colors">
              ↓ Download CSV
            </button>
          </div>
          <ChannelCrossSectionSvg bedWidth={bedWidth} sideSlope={sideSlope} flowDepth={flowDepth} />
          <div className="mt-4 space-y-2">
            {result ? (
              <>
                <div className="flex justify-between text-sm">
                  <span className="text-zinc-400">Flow Area</span>
                  <span className="font-mono text-white">{safeNum(result.flowArea)} m²</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-zinc-400">Wetted Perimeter</span>
                  <span className="font-mono text-white">{safeNum(result.wettedPerimeter)} m</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-zinc-400">Hydraulic Radius</span>
                  <span className="font-mono text-white">{safeNum(result.hydraulicRadius)} m</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-zinc-400">Velocity</span>
                  <span className={`font-mono font-bold ${result.isSelfCleansing ? 'text-emerald-400' : 'text-red-400'}`}>
                    {safeNum(result.velocity, 3)} m/s
                  </span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-zinc-400">Discharge</span>
                  <span className="font-mono font-bold text-blue-400">{safeNum(result.discharge)} m³/s</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-zinc-400">Top Width</span>
                  <span className="font-mono text-white">{safeNum(result.topWidth, 2)} m</span>
                </div>
              </>
            ) : (
              <p className="text-sm text-zinc-500">Enter valid inputs to see computed results.</p>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

// ─── CHANNEL CROSS-SECTION SVG ────────────────────────────────────────────────

function ChannelCrossSectionSvg({ bedWidth, sideSlope, flowDepth }: { bedWidth: number; sideSlope: number; flowDepth: number }) {
  const svgW = 350
  const svgH = 200
  const scale = 40 // px per metre
  const cx = svgW / 2
  const groundY = 40
  const channelBottom = groundY + 80

  const bw = Math.max(0, bedWidth) * scale
  const z = Math.max(0, sideSlope)
  const fd = Math.max(0, flowDepth) * scale
  const y = fd

  const leftToeX = cx - bw / 2 - z * y
  const rightToeX = cx + bw / 2 + z * y
  const waterY = channelBottom - y
  const leftWaterX = cx - bw / 2 - z * y
  const rightWaterX = cx + bw / 2 + z * y

  return (
    <svg viewBox={`0 0 ${svgW} ${svgH}`} className="w-full rounded-lg">
      {/* Ground */}
      <rect x={0} y={groundY} width={svgW} height={svgH - groundY} fill="#27272a" />
      {/* Channel excavation */}
      <polygon points={`${leftToeX},${channelBottom} ${cx - bw / 2},${channelBottom} ${cx + bw / 2},${channelBottom} ${rightToeX},${channelBottom}`} fill="#3f3f46" />
      {/* Channel sides */}
      <line x1={leftToeX} y1={groundY} x2={cx - bw / 2} y2={channelBottom} stroke="#71717a" strokeWidth={2} />
      <line x1={rightToeX} y1={groundY} x2={cx + bw / 2} y2={channelBottom} stroke="#71717a" strokeWidth={2} />
      <line x1={cx - bw / 2} y1={channelBottom} x2={cx + bw / 2} y2={channelBottom} stroke="#71717a" strokeWidth={2} />
      {/* Water */}
      <polygon
        points={`${leftWaterX},${channelBottom} ${cx - bw / 2},${channelBottom} ${cx + bw / 2},${channelBottom} ${rightWaterX},${channelBottom} ${rightWaterX},${waterY} ${cx + bw / 2},${waterY} ${cx - bw / 2},${waterY} ${leftWaterX},${waterY}`}
        fill="rgba(59,130,246,0.2)" stroke="#3b82f6" strokeWidth={1}
      />
      {/* Flow depth arrow */}
      <line x1={cx + bw / 2 + 15} y1={channelBottom} x2={cx + bw / 2 + 15} y2={waterY} stroke="#60a5fa" strokeWidth={1.5} markerEnd="url(#arrowUp)" />
      <text x={cx + bw / 2 + 25} y={(channelBottom + waterY) / 2 + 4} fill="#60a5fa" fontSize="10">{flowDepth.toFixed(2)}m</text>
      {/* Bed width */}
      <text x={cx} y={channelBottom + 15} textAnchor="middle" fill="#a1a1aa" fontSize="10">{bedWidth.toFixed(1)}m</text>
      <defs>
        <marker id="arrowUp" viewBox="0 0 10 10" refX="5" refY="10" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
          <path d="M 0 10 L 5 0 L 10 10" fill="none" stroke="#60a5fa" strokeWidth="1.5" />
        </marker>
      </defs>
    </svg>
  )
}

'use client';

import { useState, useMemo } from 'react';
import { AlertTriangle } from 'lucide-react'
import { z } from 'zod';
import { horizontalCurve, logEngineeringCompute } from '@/lib/engineering/compute';
import { initialiseDXFLayers, DXF_LAYERS, TitleBlockData, TITLE_BLOCK_TEMPLATES } from '@/lib/drawing/dxfLayers';
import { getMinRadius, getMinSSD, getMinSuperelevation } from '@/lib/standards/engineering';

const HorizontalCurveInputSchema = z.object({
  R: z.number().positive().min(30).max(2000),
  deltaDeg: z.number().positive().min(1).max(180),
  chainageStart: z.number().min(0).default(0),
  designSpeed: z.number().min(20).max(120).default(60),
});

interface HorizontalCurvePanelProps {
  projectId?: string;
  projectData?: {
    lr_number?: string;
    county?: string;
    district?: string;
    locality?: string;
  };
  surveyorProfile?: {
    fullName: string;
    registrationNumber: string;
    firmName: string;
  } | null;
  standard?: 'KRDM2017' | 'KeRRA';
  designSpeed?: number;
}

export function HorizontalCurvePanel({ projectId, projectData, surveyorProfile, standard = 'KRDM2017', designSpeed = 60 }: HorizontalCurvePanelProps) {
  const [R, setR] = useState(200);
  const [deltaDeg, setDeltaDeg] = useState(35);
  const [chainageStart, setChainageStart] = useState(1000);
  const [error, setError] = useState<string | null>(null);

  const minRadius = getMinRadius(standard, designSpeed);
  const minSSD = getMinSSD(standard, designSpeed);
  const minE = getMinSuperelevation(designSpeed, R);

  const validations = useMemo(() => {
    const issues: string[] = [];
    const passes: string[] = [];

    if (R < minRadius) {
      issues.push(`Radius ${R}m < minimum ${minRadius}m for ${designSpeed}km/h (RDM 1.1)`);
    } else {
      passes.push(`Radius ${R}m ≥ minimum ${minRadius}m `);
    }

    const ssdCheck = R >= minSSD * 0.5;
    if (!ssdCheck) {
      issues.push(`Insufficient sight distance for ${designSpeed}km/h (min SSD: ${minSSD}m)`);
    } else {
      passes.push(`Sight distance adequate (min SSD: ${minSSD}m) `);
    }

    if (minE > 7) {
      issues.push(`Required superelevation ${minE.toFixed(1)}% exceeds 7% max — consider larger radius`);
    } else {
      passes.push(`Superelevation ${minE.toFixed(1)}% within 7% limit `);
    }

    return { issues, passes };
  }, [R, designSpeed, minRadius, minSSD, minE]);

  const result = useMemo(() => {
    try {
      const input = HorizontalCurveInputSchema.parse({ R, deltaDeg, chainageStart, designSpeed });
      setError(null);
      const res = horizontalCurve(input);
      logEngineeringCompute('horizontal_curve', input, {
        T: res.T, L: res.L, LC: res.LC, M: res.M
      }, { projectId });
      return res;
    } catch (e) {
      if (e instanceof z.ZodError) {
        setError(e.errors[0]?.message);
      }
      return null;
    }
  }, [R, deltaDeg, chainageStart, projectId, designSpeed]);

  const exportDXF = async () => {
    if (!result) return;

    const { default: Drawing } = await import('dxf-writer');
    const drawing = new Drawing();
    initialiseDXFLayers(drawing);
    const tb: TitleBlockData = {
      drawingTitle: TITLE_BLOCK_TEMPLATES.eng_horizontal_curve.drawingTitle,
      lrNumber: projectData?.lr_number ?? 'N/A',
      county: projectData?.county ?? 'N/A',
      district: projectData?.district ?? 'N/A',
      locality: projectData?.locality ?? 'N/A',
      areaHa: 0,
      perimeterM: 0,
      surveyorName: surveyorProfile?.fullName ?? 'N/A',
      registrationNumber: surveyorProfile?.registrationNumber ?? 'N/A',
      firmName: surveyorProfile?.firmName ?? 'N/A',
      date: new Date().toLocaleDateString('en-KE'),
      submissionRef: 'N/A',
      coordinateSystem: 'Arc 1960 / UTM Zone 37S (SRID: 21037)',
      scale: '1:2500',
      sheetNumber: '1 of 1',
      revision: 'R00'
    }
    // renderTitleBlock(drawing, 'eng_horizontal_curve', tb)

    drawing.setActiveLayer(DXF_LAYERS.CENTRELINE.name);
    
    const centerY = 100;
    const scale = 0.5;

    drawing.drawLine(
      50, centerY - result.T * scale,
      50 + result.L * scale, centerY
    );

    drawing.setActiveLayer(DXF_LAYERS.CHAIN.name);
    drawing.drawText(50, centerY + 20, 0.2, 0, `TC @ ${result.chainage_TC.toFixed(3)}m`);
    drawing.drawText(50 + result.L * scale, centerY + 20, 0.2, 0, `CT @ ${result.chainage_CT.toFixed(3)}m`);
    drawing.drawText(50 + result.T * scale, centerY + 40, 0.2, 0, `IP @ ${chainageStart.toFixed(3)}m`);
    drawing.drawText(50, centerY - 30, 0.25, 0, `R=${R}m Δ=${deltaDeg}°`);
    drawing.drawText(50, centerY - 20, 0.2, 0, `T=${result.T.toFixed(3)}m L=${result.L.toFixed(3)}m`);

    const dxfString = drawing.toDxfString();
    const blob = new Blob([dxfString], { type: 'application/dxf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `horizontal_curve_R${R}_Delta${deltaDeg}.dxf`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-start">
        <div>
          <h3 className="text-lg font-semibold text-[var(--text-primary)]">Horizontal Curve Calculator</h3>
          <p className="text-sm text-[var(--text-muted)]">
            Per RDM 1.1 Volume 2, Chapter 3 — Circular Curves
          </p>
        </div>
        {result && (
          <button
            onClick={exportDXF}
            className="bg-orange-500 hover:bg-orange-600 px-4 py-2 rounded-lg text-white text-sm font-medium flex items-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            Export DXF
          </button>
        )}
      </div>

      {error && (
        <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-sm">
          {error}
        </div>
      )}

      {validations.issues.length > 0 && (
        <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-lg">
          <p className="text-red-400 text-sm font-semibold mb-1">Standards Violations</p>
          <ul className="text-red-400 text-xs space-y-0.5">
            {validations.issues.map((issue, i) => (
              <li key={`${issue}-${i}`}><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> {issue}</li>
            ))}
          </ul>
        </div>
      )}

      {validations.passes.length > 0 && (
        <div className="p-3 bg-green-500/10 border border-green-500/30 rounded-lg">
          <ul className="text-green-400 text-xs space-y-0.5">
            {validations.passes.map((pass, i) => (
              <li key={`${pass}-${i}`}> {pass}</li>
            ))}
          </ul>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="radius-r-m">Radius R (m)</label>
          <input id="radius-r-m" aria-label="Radius R (m)"
            type="number"
            min={30}
            max={2000}
            value={R}
            onChange={(e) => setR(Number(e.target.value) || 50)}
            className={`w-full bg-[var(--bg-secondary)] border rounded px-3 py-2 text-sm font-mono ${R < minRadius ? 'border-red-500 text-red-400' : 'border-[var(--border-color)]'}`}
          />
          <p className="text-xs text-[var(--text-muted)] mt-0.5">Min: {minRadius}m for {designSpeed}km/h</p>
        </div>
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="deflection-angle">Deflection Angle Δ (°)</label>
          <input id="deflection-angle" aria-label="Deflection Angle Δ (°)"
            type="number"
            min={1}
            max={180}
            value={deltaDeg}
            onChange={(e) => setDeltaDeg(Number(e.target.value) || 35)}
            className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-sm font-mono"
          />
        </div>
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="chainage-at-ip-m">Chainage at IP (m)</label>
          <input  id="chainage-at-ip-m" aria-label="Chainage at IP (m)"
            type="number"
            min={0}
            value={chainageStart}
            onChange={(e) => setChainageStart(Number(e.target.value) || 0)}
            className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-sm font-mono"
          />
        </div>
      </div>

      {result && (
        <>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Tangent Length (T)</p>
              <p className="font-mono font-semibold text-orange-400">{result.T.toFixed(3)} m</p>
            </div>
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Curve Length (L)</p>
              <p className="font-mono font-semibold">{result.L.toFixed(3)} m</p>
            </div>
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Long Chord (LC)</p>
              <p className="font-mono font-semibold">{result.LC.toFixed(3)} m</p>
            </div>
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Mid-Ordinate (M)</p>
              <p className="font-mono font-semibold">{result.M.toFixed(3)} m</p>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4 text-sm">
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Chainage TC</p>
              <p className="font-mono font-semibold">{result.chainage_TC.toFixed(3)} m</p>
            </div>
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Chainage CT</p>
              <p className="font-mono font-semibold">{result.chainage_CT.toFixed(3)} m</p>
            </div>
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">External (E)</p>
              <p className="font-mono font-semibold">{result.E?.toFixed(3) ?? '-'} m</p>
            </div>
          </div>

          <div className="overflow-x-auto border border-[var(--border-color)] rounded-lg">
            <div className="bg-[var(--bg-secondary)] px-4 py-2 border-b border-[var(--border-color)]">
              <h4 className="font-semibold text-sm">Setting Out Table (20m intervals)</h4>
            </div>
            <table className="w-full text-sm font-mono">
              <thead>
                <tr className="border-b border-[var(--border-color)] text-[var(--text-muted)] text-xs">
                  <th className="text-left py-2 px-4">Chainage</th>
                  <th className="text-right py-2 px-4">Deflection (°)</th>
                  <th className="text-right py-2 px-4">Chord (m)</th>
                  <th className="text-right py-2 px-4">Increment (m)</th>
                </tr>
              </thead>
              <tbody>
                {result.settingOutTable.slice(0, 15).map((row, i) => (
                  <tr key={`${row}-${i}`} className="border-b border-[var(--border-color)]/30">
                    <td className="py-1.5 px-4">{row.chainage.toFixed(3)}</td>
                    <td className="py-1.5 px-4 text-right">{row.deflectionFromTC.toFixed(4)}°</td>
                    <td className="py-1.5 px-4 text-right">{row.chordFromTC.toFixed(4)}</td>
                    <td className="py-1.5 px-4 text-right">{row.chordIncrement.toFixed(4)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            {result.settingOutTable.length > 15 && (
              <div className="px-4 py-2 text-xs text-[var(--text-muted)] text-center">
                ... and {result.settingOutTable.length - 15} more points
              </div>
            )}
          </div>
        </>
      )}

      <div className="text-xs text-[var(--text-muted)]">
        <p><strong>Reference:</strong> RDM 1.1 Equation 3.1 — T = R × tan(Δ/2)</p>
      </div>
    </div>
  );
}

'use client';

import React, { useMemo } from 'react'

/* -------------------------------------------------------------------------- */
/*  Types                                                                     */
/* -------------------------------------------------------------------------- */

interface Station {
  chainage: number
  groundLevel: number
  designLevel?: number
}

interface DesignStation extends Station {
  designLevel: number
}

interface VerticalIP {
  chainage: number
  reducedLevel: number
  kValue?: number
  gradientIn?: number
  gradientOut?: number
  curveLength?: number
}

interface ProjectInfo {
  roadName: string
  roadClass: string
  designSpeed: number
  startChainage: number
  datum: string
}

interface LongSectionProps {
  stations: Station[]
  verticalIPs?: VerticalIP[]
  projectInfo?: ProjectInfo
  width?: number
  height?: number
  chainageInterval?: number
}

/* -------------------------------------------------------------------------- */
/*  Helpers                                                                   */
/* -------------------------------------------------------------------------- */

/** Format chainage as "K+MMM" e.g. 120 → "0+120", 1020 → "1+020" */
function formatChainage(c: number): string {
  const km = Math.floor(c / 1000)
  const m = Math.round(c % 1000)
  return `${km}+${m.toString().padStart(3, '0')}`
}

/** Round a raw scale ratio to a "nice" engineering number (1, 2, 5, 10 …) */
function niceScale(raw: number): number {
  if (raw <= 0) return 1
  const log = Math.floor(Math.log10(raw))
  const base = Math.pow(10, log)
  const norm = raw / base
  if (norm <= 1.5) return Math.round(base)
  if (norm <= 3.5) return Math.round(2 * base)
  if (norm <= 7.5) return Math.round(5 * base)
  return Math.round(10 * base)
}

/* -------------------------------------------------------------------------- */
/*  Component                                                                 */
/* -------------------------------------------------------------------------- */

export default function LongSectionRenderer({
  stations,
  verticalIPs = [],
  projectInfo,
  width = 1200,
  height = 500,
  chainageInterval = 20,
}: LongSectionProps) {
  /* ---- layout constants ---- */
  const ML = 70          // left margin  (elevation labels)
  const MR = 30          // right margin
  const MT = 60          // top margin   (title block)
  const MB = 90          // bottom margin(chainage labels)
  const plotW = width - ML - MR
  const plotH = height - MT - MB
  const plotBottom = MT + plotH
  const plotRight = ML + plotW

  /* ---- data ranges (always computed so hooks are stable) ---- */
  const { minC, maxC, minE, maxE, rangeC, rangeE } = useMemo(() => {
    if (stations.length === 0) return { minC: 0, maxC: 100, minE: 0, maxE: 10, rangeC: 100, rangeE: 10 }
    const cs = stations.map(s => s.chainage)
    const es = stations.flatMap(s =>
      [s.groundLevel, s.designLevel].filter((v): v is number => v !== undefined),
    )
    const lo = Math.floor(Math.min(...es)) - 1
    const hi = Math.ceil(Math.max(...es)) + 1
    return { minC: Math.min(...cs), maxC: Math.max(...cs), minE: lo, maxE: hi, rangeC: Math.max(...cs) - Math.min(...cs) || 1, rangeE: hi - lo || 1 }
  }, [stations])

  const xS = (c: number) => ML + ((c - minC) / rangeC) * plotW
  const yS = (e: number) => MT + plotH - ((e - minE) / rangeE) * plotH

  /* ---- vertical curve derivations ---- */
  const curves = useMemo(() =>
    verticalIPs.map(vip => {
      const g1 = vip.gradientIn ?? 0
      const g2 = vip.gradientOut ?? 0
      const aDiff = Math.abs(g2 - g1)
      const K = vip.kValue ?? (vip.curveLength != null ? vip.curveLength / (aDiff || 1) : 50)
      const L = vip.curveLength ?? K * aDiff

      const bvcC = vip.chainage - L / 2
      const evcC = vip.chainage + L / 2
      // gradients treated as percent → divide by 100 for ratio
      const bvcE = vip.reducedLevel - (g1 / 100) * (L / 2)
      const evcE = vip.reducedLevel + (g2 / 100) * (L / 2)

      return { bvcC, bvcE, evcC, evcE, vipC: vip.chainage, vipE: vip.reducedLevel, L, K, g1, g2 }
    }),
    [verticalIPs],
  )

  /* ---- grid lines ---- */
  const { hLines, vLines } = useMemo(() => {
    const hl: { y: number; major: boolean; elev: number }[] = []
    for (let e = Math.ceil(minE); e <= Math.floor(maxE); e++)
      hl.push({ y: yS(e), major: e % 5 === 0, elev: e })

    const vl: { x: number; major: boolean; chainage: number }[] = []
    const first = Math.ceil(minC / chainageInterval) * chainageInterval
    for (let c = first; c <= maxC; c += chainageInterval)
      vl.push({ x: xS(c), major: c % 100 === 0, chainage: c })

    return { hLines: hl, vLines: vl }
  }, [minE, maxE, minC, maxC, chainageInterval])

  /* ---- SVG path data ---- */
  const {
    groundPoly,
    groundFill,
    designPoly,
    cutFillSegs,
    cfAnnotations,
    transitions,
    groundRLLabels,
  } = useMemo(() => {
    const gp = stations.map(s => `${xS(s.chainage)},${yS(s.groundLevel)}`).join(' ')
    const gf = stations.length
      ? `M${xS(stations[0].chainage)},${plotBottom} L${gp} L${xS(stations[stations.length - 1].chainage)},${plotBottom} Z`
      : ''

    const ds = stations.filter((s): s is DesignStation => s.designLevel != null)
    const dp = ds.map(s => `${xS(s.chainage)},${yS(s.designLevel)}`).join(' ')

    /* cut / fill quads */
    const cfs: { type: 'cut' | 'fill'; path: string }[] = []
    for (let i = 0; i < ds.length - 1; i++) {
      const a = ds[i], b = ds[i + 1]
      const ax = xS(a.chainage), ayg = yS(a.groundLevel), ayd = yS(a.designLevel)
      const bx = xS(b.chainage), byg = yS(b.groundLevel), byd = yS(b.designLevel)
      cfs.push({
        path: `M${ax},${ayg} L${bx},${byg} L${bx},${byd} L${ax},${ayd} Z`,
        type: ((a.groundLevel - a.designLevel) + (b.groundLevel - b.designLevel)) / 2 >= 0 ? 'cut' : 'fill',
      })
    }

    /* cut / fill text annotations */
    const cfa = ds.map(s => {
      const diff = s.groundLevel - s.designLevel
      return {
        x: xS(s.chainage),
        gy: yS(s.groundLevel),
        dy: yS(s.designLevel),
        my: (yS(s.groundLevel) + yS(s.designLevel)) / 2,
        type: diff >= 0 ? ('cut' as const) : ('fill' as const),
        amt: Math.abs(diff),
        ch: s.chainage,
      }
    })

    /* transition points (cut ↔ fill) */
    const tr: { x: number; y: number; type: 'cut' | 'fill' }[] = []
    for (let i = 1; i < ds.length; i++) {
      const prev = ds[i - 1], cur = ds[i]
      const pd = prev.groundLevel - prev.designLevel
      const cd = cur.groundLevel - cur.designLevel
      if ((pd >= 0) !== (cd >= 0)) {
        const t = Math.abs(pd) / (Math.abs(pd) + Math.abs(cd))
        const tc = prev.chainage + t * (cur.chainage - prev.chainage)
        const te = prev.groundLevel + t * (cur.groundLevel - prev.groundLevel)
        tr.push({ x: xS(tc), y: yS(te), type: cd >= 0 ? 'cut' : 'fill' })
      }
    }

    /* ground RL labels every 100 m */
    const grl = stations
      .filter(s => s.chainage % 100 === 0)
      .map(s => ({ x: xS(s.chainage), y: yS(s.groundLevel), rl: s.groundLevel }))

    return { groundPoly: gp, groundFill: gf, designPoly: dp, cutFillSegs: cfs, cfAnnotations: cfa, transitions: tr, groundRLLabels: grl }
  }, [stations, minC, maxC, minE, maxE])

  /* ---- table rows ---- */
  const tableRows = useMemo(() => {
    const ds = stations.filter((s): s is DesignStation => s.designLevel != null)
    return ds.map((s, i) => {
      let grade = ''
      if (i > 0) {
        const prev = ds[i - 1]
        const dist = s.chainage - prev.chainage
        if (dist > 0) grade = ((s.designLevel - prev.designLevel) / dist * 100).toFixed(2) + '%'
      }
      const diff = s.groundLevel - s.designLevel
      return {
        chainage: s.chainage,
        groundRL: s.groundLevel.toFixed(3),
        designRL: s.designLevel.toFixed(3),
        grade,
        cut: diff > 0 ? diff.toFixed(3) : '',
        fill: diff < 0 ? Math.abs(diff).toFixed(3) : '',
      }
    })
  }, [stations])

  /* ---- indicative scales (assuming A1 plot area ≈ 700 × 500 mm) ---- */
  const hScaleNum = niceScale((rangeC * 1000) / 700)
  const vScaleNum = niceScale((rangeE * 1000) / 500)

  /* ------------------------------------------------------------------ */
  /*  Empty state                                                        */
  /* ------------------------------------------------------------------ */
  if (stations.length === 0) {
    return (
      <div
        className="flex items-center justify-center rounded-lg border border-dashed border-gray-300 text-muted-foreground"
        style={{ minHeight: height }}
      >
        <div className="text-center">
          <p className="text-lg font-medium">No survey station data</p>
          <p className="text-sm mt-1">Provide station chainage and ground levels to render the long section.</p>
        </div>
      </div>
    )
  }

  const hasDesign = stations.some(s => s.designLevel != null)

  /* ------------------------------------------------------------------ */
  /*  Render                                                             */
  /* ------------------------------------------------------------------ */
  return (
    <div className="w-full space-y-4">
      {/* ============ SVG Drawing ============ */}
      <div className="overflow-x-auto rounded-lg border border-gray-300 bg-white">
        <svg
          viewBox={`0 0 ${width} ${height}`}
          className="w-full"
          style={{ minWidth: 800 }}
          xmlns="http://www.w3.org/2000/svg"
          fontFamily="'Inter', 'Segoe UI', system-ui, sans-serif"
        >
          {/* ---- clip region ---- */}
          <defs>
            <clipPath id="ls-plot">
              <rect x={ML} y={MT} width={plotW} height={plotH} />
            </clipPath>
          </defs>

          {/* ---- plot background ---- */}
          <rect x={ML} y={MT} width={plotW} height={plotH} fill="#f9fafb" />

          {/* ---- grid ---- */}
          <g>
            {hLines.map((l, i) => (
              <line key={`hg${i}`} x1={ML} y1={l.y} x2={plotRight} y2={l.y}
                stroke={l.major ? '#d1d5db' : '#e5e7eb'} strokeWidth={l.major ? 1 : 0.5} />
            ))}
            {vLines.map((l, i) => (
              <line key={`vg${i}`} x1={l.x} y1={MT} x2={l.x} y2={plotBottom}
                stroke={l.major ? '#d1d5db' : '#e5e7eb'} strokeWidth={l.major ? 1 : 0.5} />
            ))}
          </g>

          {/* ---- clipped drawing content ---- */}
          <g clipPath="url(#ls-plot)">
            {/* ground profile fill */}
            <path d={groundFill} fill="rgba(210,180,140,0.3)" />

            {/* cut / fill fills */}
            {cutFillSegs.map((s, i) => (
              <path key={`cf${i}`} d={s.path}
                fill={s.type === 'cut' ? 'rgba(239,68,68,0.13)' : 'rgba(59,130,246,0.13)'} />
            ))}

            {/* vertical curve highlights */}
            {curves.map((cv, i) => {
              const bx = xS(cv.bvcC), by = yS(cv.bvcE)
              const vx = xS(cv.vipC), vy = yS(cv.vipE)
              const ex = xS(cv.evcC), ey = yS(cv.evcE)
              return (
                <g key={`vc${i}`}>
                  <path d={`M${bx},${by} Q${vx},${vy} ${ex},${ey} L${ex},${plotBottom} L${bx},${plotBottom} Z`}
                    fill="rgba(34,197,94,0.07)" />
                  <path d={`M${bx},${by} Q${vx},${vy} ${ex},${ey}`}
                    fill="none" stroke="#16a34a" strokeWidth={2.5} strokeLinecap="round" />
                  <circle cx={bx} cy={by} r={4} fill="#16a34a" stroke="#fff" strokeWidth={1.5} />
                  <circle cx={ex} cy={ey} r={4} fill="#16a34a" stroke="#fff" strokeWidth={1.5} />
                  <circle cx={vx} cy={vy} r={3} fill="#fff" stroke="#16a34a" strokeWidth={2} />
                </g>
              )
            })}

            {/* ground profile polyline */}
            <polyline points={groundPoly} fill="none" stroke="#8B4513" strokeWidth={2}
              strokeLinejoin="round" strokeLinecap="round" />

            {/* design grade line */}
            {hasDesign && (
              <polyline points={designPoly} fill="none" stroke="#2563EB" strokeWidth={1.5}
                strokeDasharray="8,4" strokeLinejoin="round" strokeLinecap="round" />
            )}

            {/* cut / fill annotations */}
            {cfAnnotations
              .filter(a => a.amt > 0.05)
              .map((a, i) => (
                <text key={`a${i}`} x={a.x} y={a.my + 3} textAnchor="middle" fontSize={9}
                  fontWeight={600} fill={a.type === 'cut' ? '#dc2626' : '#2563eb'}>
                  {a.type === 'cut' ? 'C' : 'F'} {a.amt.toFixed(2)}m
                </text>
              ))}

            {/* transition triangles */}
            {transitions.map((t, i) => (
              <polygon key={`tr${i}`}
                points={`${t.x},${t.y - 6} ${t.x - 4},${t.y + 4} ${t.x + 4},${t.y + 4}`}
                fill={t.type === 'fill' ? '#2563eb' : '#dc2626'} stroke="#fff" strokeWidth={1} />
            ))}
          </g>

          {/* ---- ground RL labels every 100 m ---- */}
          {groundRLLabels.map((l, i) => (
            <g key={`gl${i}`}>
              <circle cx={l.x} cy={l.y} r={2.5} fill="#8B4513" />
              <text x={l.x + 6} y={l.y - 4} fontSize={8} fill="#8B4513" fontFamily="monospace">
                {l.rl.toFixed(2)}
              </text>
            </g>
          ))}

          {/* ---- plot border ---- */}
          <rect x={ML} y={MT} width={plotW} height={plotH} fill="none" stroke="#374151" strokeWidth={1.5} />

          {/* ---- elevation labels (left axis) ---- */}
          {hLines.map((l, i) => (
            <text key={`el${i}`} x={ML - 8} y={l.y + 4} textAnchor="end"
              fontSize={l.major ? 10 : 8} fill={l.major ? '#374151' : '#9ca3af'}
              fontFamily="monospace">
              {l.elev.toFixed(1)}
            </text>
          ))}

          {/* ---- chainage labels + ticks (bottom) ---- */}
          {vLines.map((l, i) => (
            <g key={`cl${i}`}>
              <line x1={l.x} y1={plotBottom} x2={l.x} y2={plotBottom + (l.major ? 8 : 4)}
                stroke="#374151" strokeWidth={l.major ? 1 : 0.5} />
              {l.major ? (
                <text x={l.x} y={plotBottom + 22} textAnchor="middle" fontSize={10}
                  fill="#374151" fontFamily="monospace">
                  {formatChainage(l.chainage)}
                </text>
              ) : (
                <text x={l.x} y={plotBottom + 16} textAnchor="middle" fontSize={8}
                  fill="#9ca3af" fontFamily="monospace">
                  {(l.chainage % 100).toString().padStart(2, '0')}
                </text>
              )}
            </g>
          ))}

          {/* ---- vertical curve annotations ---- */}
          {curves.map((cv, i) => {
            const vx = xS(cv.vipC)
            const vy = yS(cv.vipE)
            const labelY = Math.max(vy - 20, MT + 14)
            return (
              <g key={`va${i}`}>
                <rect x={vx - 72} y={labelY - 20} width={144} height={28} rx={3}
                  fill="rgba(255,255,255,0.85)" stroke="#bbf7d0" strokeWidth={0.8} />
                <text x={vx} y={labelY - 6} textAnchor="middle" fontSize={8} fontWeight={600} fill="#15803d">
                  VPI {formatChainage(cv.vipC)} &nbsp; RL {cv.vipE.toFixed(2)}
                </text>
                <text x={vx} y={labelY + 5} textAnchor="middle" fontSize={7} fill="#16a34a">
                  K={cv.K.toFixed(0)} &nbsp; L={cv.L.toFixed(0)}m &nbsp; {cv.g1.toFixed(2)}% → {cv.g2.toFixed(2)}%
                </text>
                {/* BVC / EVC labels */}
                <text x={xS(cv.bvcC)} y={yS(cv.bvcE) - 8} textAnchor="middle" fontSize={7} fontWeight={600} fill="#16a34a">
                  BVC
                </text>
                <text x={xS(cv.evcC)} y={yS(cv.evcE) - 8} textAnchor="middle" fontSize={7} fontWeight={600} fill="#16a34a">
                  EVC
                </text>
              </g>
            )
          })}

          {/* ---- title block ---- */}
          <g>
            <rect x={3} y={3} width={width - 6} height={50} rx={4}
              fill="rgba(255,255,255,0.92)" stroke="#e5e7eb" strokeWidth={1} />
            {/* road name */}
            <text x={14} y={22} fontSize={15} fontWeight={700} fill="#111827" letterSpacing={0.5}>
              {(projectInfo?.roadName ?? 'Unnamed Road').toUpperCase()}
            </text>
            {/* class / speed */}
            <text x={14} y={38} fontSize={10} fill="#6b7280">
              {projectInfo?.roadClass ?? '—'}&ensp;|&ensp;Design Speed: {projectInfo?.designSpeed ?? '—'} km/h
            </text>
            {/* datum / scale */}
            <text x={14} y={50} fontSize={9} fill="#9ca3af">
              Datum: {projectInfo?.datum ?? '—'}&ensp;|&ensp;Scale: H 1:{hScaleNum}&ensp;V 1:{vScaleNum}
            </text>
            {/* LONG SECTION title */}
            <text x={plotRight - 4} y={22} textAnchor="end" fontSize={14} fontWeight={700} fill="#374151">
              LONG SECTION
            </text>
            {/* date */}
            <text x={plotRight - 4} y={38} textAnchor="end" fontSize={9} fill="#9ca3af">
              {new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })}
            </text>
            {/* station count */}
            <text x={plotRight - 4} y={50} textAnchor="end" fontSize={9} fill="#9ca3af">
              {stations.length} stations &ensp;|&ensp; {formatChainage(minC)} – {formatChainage(maxC)}
            </text>
          </g>

          {/* ---- axis titles ---- */}
          <text x={ML + plotW / 2} y={height - 8} textAnchor="middle" fontSize={11}
            fontWeight={600} fill="#6b7280" letterSpacing={1}>
            CHAINAGE (m)
          </text>
          <text x={16} y={MT + plotH / 2} textAnchor="middle" fontSize={11}
            fontWeight={600} fill="#6b7280" letterSpacing={1}
            transform={`rotate(-90,16,${MT + plotH / 2})`}>
            REDUCED LEVEL (m)
          </text>

          {/* ---- legend (bottom-right) ---- */}
          <g transform={`translate(${plotRight - 150},${MT + 8})`}>
            <rect x={0} y={0} width={145} height={56} rx={3} fill="rgba(255,255,255,0.9)" stroke="#e5e7eb" />
            <line x1={8} y1={12} x2={28} y2={12} stroke="#8B4513" strokeWidth={2} />
            <text x={34} y={15} fontSize={8} fill="#374151">Ground Profile</text>
            <line x1={8} y1={26} x2={28} y2={26} stroke="#2563EB" strokeWidth={1.5} strokeDasharray="6,3" />
            <text x={34} y={29} fontSize={8} fill="#374151">Design Grade Line</text>
            <line x1={8} y1={40} x2={28} y2={40} stroke="#16a34a" strokeWidth={2.5} />
            <text x={34} y={43} fontSize={8} fill="#374151">Vertical Curve</text>
            <rect x={8} y={48} width={20} height={4} rx={1} fill="rgba(239,68,68,0.3)" />
            <text x={34} y={53} fontSize={7} fill="#9ca3af">Cut</text>
            <rect x={68} y={48} width={20} height={4} rx={1} fill="rgba(59,130,246,0.3)" />
            <text x={94} y={53} fontSize={7} fill="#9ca3af">Fill</text>
          </g>
        </svg>
      </div>

      {/* ============ Data Table ============ */}
      {hasDesign && tableRows.length > 0 && (
        <div className="overflow-x-auto rounded-lg border border-gray-200">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-gray-100 text-left text-xs uppercase tracking-wide text-gray-600">
                <th className="px-4 py-2.5 font-semibold">Chainage</th>
                <th className="px-4 py-2.5 font-semibold">Ground RL</th>
                <th className="px-4 py-2.5 font-semibold">Design RL</th>
                <th className="px-4 py-2.5 font-semibold">Grade</th>
                <th className="px-4 py-2.5 font-semibold text-red-600">Cut (m)</th>
                <th className="px-4 py-2.5 font-semibold text-blue-600">Fill (m)</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {tableRows.map((r, i) => (
                <tr key={`${r}-${i}`} className={i % 2 === 0 ? 'bg-white' : 'bg-gray-50/60'}>
                  <td className="px-4 py-1.5 font-mono text-xs">{formatChainage(r.chainage)}</td>
                  <td className="px-4 py-1.5 font-mono text-xs">{r.groundRL}</td>
                  <td className="px-4 py-1.5 font-mono text-xs">{r.designRL}</td>
                  <td className="px-4 py-1.5 font-mono text-xs text-gray-500">{r.grade}</td>
                  <td className={`px-4 py-1.5 font-mono text-xs font-semibold ${r.cut ? 'text-red-600' : 'text-gray-300'}`}>
                    {r.cut || '—'}
                  </td>
                  <td className={`px-4 py-1.5 font-mono text-xs font-semibold ${r.fill ? 'text-blue-600' : 'text-gray-300'}`}>
                    {r.fill || '—'}
                  </td>
                </tr>
              ))}
            </tbody>
            {/* summary footer */}
            <tfoot>
              <tr className="bg-gray-100 text-xs font-semibold">
                <td colSpan={4} className="px-4 py-2 text-gray-600">Totals</td>
                <td className="px-4 py-2 font-mono text-red-600">
                  {tableRows.reduce((s, r) => s + parseFloat(r.cut || '0'), 0).toFixed(3)}
                </td>
                <td className="px-4 py-2 font-mono text-blue-600">
                  {tableRows.reduce((s, r) => s + parseFloat(r.fill || '0'), 0).toFixed(3)}
                </td>
              </tr>
            </tfoot>
          </table>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState } from 'react';
import { AlertTriangle } from 'lucide-react'
import { ENGINEERING_QA, type EngineeringSubtype } from '@/lib/engine/engineering';

interface EngineeringPanelProps {
  projectId: string;
  subtype: EngineeringSubtype;
}

export function BridgePanel({ projectId, subtype }: EngineeringPanelProps) {
  const [activeTab, setActiveTab] = useState<'control' | 'spans' | 'structure' | 'settingout'>('control');
  const qa = ENGINEERING_QA.bridge;

  const [centreLine, setCentreLine] = useState<Array<{ easting: number; northing: number; elevation?: number }>>([]);
  const [spanCount, setSpanCount] = useState(1);
  const [spanLengths, setSpanLengths] = useState<number[]>([30]);
  const [widthM, setWidthM] = useState(10);
  const [approachLength, setApproachLength] = useState(30);
  const [waterLevel, setWaterLevel] = useState<number | undefined>();
  const [bedLevel, setBedLevel] = useState<number | undefined>();
  const [clearanceM, setClearanceM] = useState<number | undefined>();
  const [skewAngle, setSkewAngle] = useState(0);

  const totalLength = spanLengths.reduce((a, b) => a + b, 0);

  const clearanceWarning = clearanceM !== undefined && clearanceM < 1.5;

  // ── Setting-out helpers ──────────────────────────────────────────
  function computeBearing(from: { easting: number; northing: number }, to: { easting: number; northing: number }): number {
    const dE = to.easting - from.easting;
    const dN = to.northing - from.northing;
    return (Math.atan2(dE, dN) * 180 / Math.PI + 360) % 360;
  }

  function computeDistance(from: { easting: number; northing: number }, to: { easting: number; northing: number }): number {
    return Math.sqrt((to.easting - from.easting) ** 2 + (to.northing - from.northing) ** 2);
  }

  function formatDMS(bearingDeg: number): string {
    const d = Math.floor(bearingDeg);
    const mFull = (bearingDeg - d) * 60;
    const m = Math.floor(mFull);
    const s = ((mFull - m) * 60).toFixed(1);
    return `${d}\u00B0${String(m).padStart(2, '0')}'${s.padStart(4, '0')}"`;
  }

  function pointFromBearingAndDist(
    origin: { easting: number; northing: number },
    bearingDeg: number,
    dist: number,
  ): { easting: number; northing: number } {
    const rad = (bearingDeg * Math.PI) / 180;
    return {
      easting: origin.easting + dist * Math.sin(rad),
      northing: origin.northing + dist * Math.cos(rad),
    };
  }

  function nearestControlPoint(
    pt: { easting: number; northing: number },
  ): { label: string; bearing: number; distance: number } | null {
    if (centreLine.length === 0) return null;
    let best = 0;
    let bestD = Infinity;
    for (let i = 0; i < centreLine.length; i++) {
      const d = computeDistance(pt, centreLine[i]);
      if (d < bestD) { bestD = d; best = i; }
    }
    return {
      label: `CP${best + 1}`,
      bearing: computeBearing(centreLine[best], pt),
      distance: bestD,
    };
  }

  // ── Derived setting-out data ─────────────────────────────────────
  const alignmentBearing = centreLine.length >= 2
    ? computeBearing(centreLine[0], centreLine[1])
    : 0;

  const skewAdjustedBearing = (alignmentBearing + skewAngle + 360) % 360;
  const perpBearing = (skewAdjustedBearing + 90) % 360;
  const halfWidth = widthM / 2;

  interface SettingOutRow {
    id: string;
    label: string;
    fromCP: string;
    bearing: number;
    distance: number;
    easting: number;
    northing: number;
  }

  const settingOutRows: SettingOutRow[] = [];

  if (centreLine.length >= 2) {
    const startPt = centreLine[0];

    const addRow = (label: string, pt: { easting: number; northing: number }) => {
      const info = nearestControlPoint(pt);
      if (info) {
        settingOutRows.push({
          id: `${label}-${pt.easting.toFixed(2)}-${pt.northing.toFixed(2)}`,
          label,
          fromCP: info.label,
          bearing: info.bearing,
          distance: info.distance,
          easting: pt.easting,
          northing: pt.northing,
        });
      }
    };

    // Abutment 1 – Left & Right corners
    const a1Left = pointFromBearingAndDist(startPt, perpBearing, halfWidth);
    const a1Right = pointFromBearingAndDist(startPt, (perpBearing + 180) % 360, halfWidth);
    addRow('Abut 1 Left', a1Left);
    addRow('Abut 1 Right', a1Right);

    // Pier positions at span boundaries
    let cumDist = 0;
    for (let i = 0; i < spanLengths.length; i++) {
      cumDist += spanLengths[i];
      if (i < spanLengths.length - 1) {
        const pierCenter = pointFromBearingAndDist(startPt, skewAdjustedBearing, cumDist);
        addRow(`Pier ${i + 1}`, pierCenter);
      }
    }

    // Abutment 2 – Left & Right corners at end of bridge
    const endPt = pointFromBearingAndDist(startPt, skewAdjustedBearing, totalLength);
    const a2Left = pointFromBearingAndDist(endPt, perpBearing, halfWidth);
    const a2Right = pointFromBearingAndDist(endPt, (perpBearing + 180) % 360, halfWidth);
    addRow('Abut 2 Left', a2Left);
    addRow('Abut 2 Right', a2Right);
  }

  const tabs = [
    { id: 'control', label: 'Control Survey' },
    { id: 'spans', label: 'Span Layout' },
    { id: 'structure', label: 'Structure Data' },
    { id: 'settingout', label: 'Setting Out' },
  ] as const;

  return (
    <div className="p-4">
      <div className="mb-4 p-3 bg-zinc-800 rounded-lg">
        <div className="text-sm text-zinc-400">QA Standards</div>
        <div className="flex gap-4 mt-1 text-xs">
          <span>Traverse: 1:{qa.traversePrecision}</span>
          <span>Levelling: {qa.levellingClosureMM}</span>
          <span>Angular: {qa.angularClosureSec}</span>
          <span>Horizontal: ±{qa.horizontalClosureMM}mm/km</span>
        </div>
      </div>

      <div className="flex border-b border-zinc-700 mb-4">
        {tabs.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as typeof activeTab)}
            className={`px-4 py-2 text-sm ${activeTab === tab.id ? 'text-amber-500 border-b-2 border-amber-500' : 'text-zinc-400'}`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {activeTab === 'control' && (
        <div>
          <div className="text-lg font-medium mb-3">Control Points (min 4 required)</div>
          <table className="w-full text-sm">
            <thead>
              <tr className="text-zinc-400 border-b border-zinc-700">
                <th className="text-left py-2">Point</th>
                <th className="text-left py-2">Easting</th>
                <th className="text-left py-2">Northing</th>
                <th className="text-left py-2">Elevation</th>
              </tr>
            </thead>
            <tbody>
              {centreLine.map((pt, i) => (
                <tr key={`${pt}-${i}`} className="border-b border-zinc-800">
                  <td className="py-2">CP{i + 1}</td>
                  <td className="py-2">{pt.easting.toFixed(3)}</td>
                  <td className="py-2">{pt.northing.toFixed(3)}</td>
                  <td className="py-2">{pt.elevation?.toFixed(3) || '-'}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <button
            onClick={() => setCentreLine([...centreLine, { easting: 0, northing: 0 }])}
            className="mt-3 px-3 py-1.5 text-sm bg-amber-600 hover:bg-amber-700 rounded"
          >
            Add Control Point
          </button>
        </div>
      )}

      {activeTab === 'spans' && (
        <div>
          <div className="text-lg font-medium mb-3">Span Layout</div>
          <div className="grid grid-cols-2 gap-4 mb-4">
            <div>
              <label className="text-sm text-zinc-400" htmlFor="number-of-spans">Number of Spans</label>
              <input id="number-of-spans" aria-label="Number of Spans"
                type="number"
                min={1}
                value={spanCount}
                onChange={(e) => {
                  const n = parseInt(e.target.value) || 1;
                  setSpanCount(n);
                  while (spanLengths.length < n) setSpanLengths([...spanLengths, 30]);
                  while (spanLengths.length > n) spanLengths.pop();
                }}
                className="w-full mt-1 px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm"
              />
            </div>
            <div>
              <div className="text-sm text-zinc-400">Total Bridge Length</div>
              <div className="mt-1 text-lg text-amber-500">{totalLength.toFixed(3)} m</div>
            </div>
          </div>
          <div className="space-y-2">
            {spanLengths.map((len, i) => (
              <div key={`${len}-${i}`} className="flex gap-2">
                <span className="text-sm text-zinc-400 w-20">Span {i + 1}:</span>
                <input aria-label="Total Bridge Length"
                  type="number"
                  value={len}
                  onChange={(e) => {
                    const newLengths = [...spanLengths];
                    newLengths[i] = parseFloat(e.target.value) || 0;
                    setSpanLengths(newLengths);
                  }}
                  className="flex-1 px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm"
                />
                <span className="text-sm text-zinc-400">m</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'structure' && (
        <div>
          <div className="text-lg font-medium mb-3">Structure Data</div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-sm text-zinc-400" htmlFor="bridge-width-m">Bridge Width (m)</label>
              <input id="bridge-width-m" aria-label="Bridge Width (m)"
                type="number"
                value={widthM}
                onChange={(e) => setWidthM(parseFloat(e.target.value) || 0)}
                className="w-full mt-1 px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm"
              />
            </div>
            <div>
              <label className="text-sm text-zinc-400" htmlFor="approach-length-m-each">Approach Length (m each)</label>
              <input id="approach-length-m-each" aria-label="Approach Length (m each)"
                type="number"
                value={approachLength}
                onChange={(e) => setApproachLength(parseFloat(e.target.value) || 0)}
                className="w-full mt-1 px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm"
              />
            </div>
            <div>
              <label className="text-sm text-zinc-400" htmlFor="skew-angle">Skew Angle (°)</label>
              <input id="skew-angle" aria-label="Skew Angle (°)"
