'use client';

import { useState } from 'react';
import { AlertTriangle } from 'lucide-react'
import { ENGINEERING_QA, type EngineeringSubtype, computeHorizontalCurve, computeVerticalCurve, crossSectionCutFill, prismoidalVolume } from '@/lib/engine/engineering';

interface EngineeringPanelProps {
  projectId: string;
  subtype: EngineeringSubtype;
}

export function RailwayPanel({ projectId, subtype }: EngineeringPanelProps) {
  const [activeTab, setActiveTab] = useState<'alignment' | 'horizontal' | 'vertical' | 'cross' | 'earthworks'>('alignment');
  const qa = ENGINEERING_QA.railway;

  const [alignment, setAlignment] = useState<Array<{ chainage: number; easting: number; northing: number; elevation?: number }>>([]);
  const [horizontalCurves, setHorizontalCurves] = useState<Array<{ radius: number; delta: number; piChainage: number }>>([]);
  const [verticalCurves, setVerticalCurves] = useState<Array<{ pvIChainage: number; pvIElevation: number; gradeIn: number; gradeOut: number; length: number }>>([]);
  const [crossSections, setCrossSections] = useState<Array<{ chainage: number; designLevel: number; levels: Array<{ offset: number; elevation: number }> }>>([]);
  const [trackGaugeMM, setTrackGaugeMM] = useState(1000);
  const [designSpeedKmh, setDesignSpeedKmh] = useState(80);
  const [maxGradientPercent, setMaxGradientPercent] = useState(2);

  const computedHorizontal = horizontalCurves.map(c => computeHorizontalCurve(c.radius, c.delta, c.piChainage));
  const computedVertical = verticalCurves.map(v => computeVerticalCurve(v.pvIChainage, v.pvIElevation, v.gradeIn, v.gradeOut, v.length));

  const minRadiusWarning = designSpeedKmh <= 60 && horizontalCurves.some(c => c.radius < 200);

  const gradientWarning = computedVertical.some(vc => Math.abs(vc.gradeIn) > maxGradientPercent || Math.abs(vc.gradeOut) > maxGradientPercent);

  const tabs = [
    { id: 'alignment', label: 'Alignment' },
    { id: 'horizontal', label: 'Horizontal Curves' },
    { id: 'vertical', label: 'Vertical Curves' },
    { id: 'cross', label: 'Cross Sections' },
    { id: 'earthworks', label: 'Earthworks' },
  ] as const;

  return (
    <div className="p-4">
      <div className="mb-4 p-3 bg-zinc-800 rounded-lg">
        <div className="text-sm text-zinc-400">QA Standards</div>
        <div className="flex gap-4 mt-1 text-xs">
          <span>Traverse: 1:{qa.traversePrecision}</span>
          <span>Levelling: {qa.levellingClosureMM}</span>
          <span>Angular: {qa.angularClosureSec}</span>
          <span>Horizontal: ±{qa.horizontalClosureMM}mm/km</span>
        </div>
      </div>

      <div className="flex overflow-x-auto border-b border-zinc-700 mb-4">
        {tabs.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as typeof activeTab)}
            className={`px-4 py-2 text-sm whitespace-nowrap ${activeTab === tab.id ? 'text-amber-500 border-b-2 border-amber-500' : 'text-zinc-400'}`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {activeTab === 'alignment' && (
        <div>
          <div className="text-lg font-medium mb-3">Alignment Points</div>
          <div className="grid grid-cols-3 gap-4 mb-4">
            <div>
              <label className="text-sm text-zinc-400" htmlFor="track-gauge-mm">Track Gauge (mm)</label>
              <select id="track-gauge-mm"
                value={trackGaugeMM}
                onChange={(e) => setTrackGaugeMM(parseInt(e.target.value))}
                className="w-full mt-1 px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm"
              >
                <option value={1000}>1000 (Metre Gauge)</option>
                <option value={1435}>1435 (Standard)</option>
                <option value={1067}>1067 (Cape Gauge)</option>
              </select>
            </div>
            <div>
              <label className="text-sm text-zinc-400" htmlFor="design-speed-km-h">Design Speed (km/h)</label>
              <input id="design-speed-km-h" aria-label="Design Speed (km/h)"
                type="number"
                value={designSpeedKmh}
                onChange={(e) => setDesignSpeedKmh(parseInt(e.target.value) || 0)}
                className="w-full mt-1 px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm"
              />
            </div>
            <div>
              <label className="text-sm text-zinc-400" htmlFor="max-gradient">Max Gradient (%)</label>
              <input  id="max-gradient" aria-label="Max Gradient (%)"
                type="number"
                step={0.1}
                value={maxGradientPercent}
                onChange={(e) => setMaxGradientPercent(parseFloat(e.target.value) || 0)}
                className="w-full mt-1 px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm"
              />
            </div>
          </div>
          <div className="overflow-x-auto">
          <table className="w-full text-sm min-w-[400px]">
            <thead>
              <tr className="text-zinc-400 border-b border-zinc-700">
                <th className="text-left py-2">Chainage</th>
                <th className="text-left py-2">Easting</th>
                <th className="text-left py-2">Northing</th>
                <th className="text-left py-2">Elevation</th>
              </tr>
            </thead>
            <tbody>
              {alignment.map((pt, i) => (
                <tr key={`${pt}-${i}`} className="border-b border-zinc-800">
                  <td className="py-2">{pt.chainage.toFixed(3)}</td>
                  <td className="py-2">{pt.easting.toFixed(3)}</td>
                  <td className="py-2">{pt.northing.toFixed(3)}</td>
                  <td className="py-2">{pt.elevation?.toFixed(3) || '-'}</td>
                </tr>
              ))}
            </tbody>
          </table>
          </div>
          <button
            onClick={() => setAlignment([...alignment, { chainage: alignment.length > 0 ? alignment[alignment.length-1].chainage + 20 : 0, easting: 0, northing: 0 }])}
            className="mt-3 px-3 py-1.5 text-sm bg-amber-600 hover:bg-amber-700 rounded"
          >
            Add Point
          </button>
        </div>
      )}

      {activeTab === 'horizontal' && (
        <div>
          <div className="text-lg font-medium mb-3">Horizontal Curves</div>
          {computedHorizontal.map((curve, i) => (
            <div key={`${curve}-${i}`} className="mb-4 p-3 bg-zinc-800 rounded-lg">
              <div className="text-sm text-amber-500 mb-2">Curve {i + 1}</div>
              <div className="grid grid-cols-3 gap-2 text-sm">
                <div><span className="text-zinc-400">Radius:</span> {horizontalCurves[i].radius}m</div>
                <div><span className="text-zinc-400">Δ:</span> {horizontalCurves[i].delta.toFixed(2)}°</div>
                <div><span className="text-zinc-400">T:</span> {curve.tangentLength.toFixed(3)}m</div>
              </div>
            </div>
          ))}
          {minRadiusWarning && (
            <div className="mt-2 p-2 bg-amber-900/50 border border-amber-700 rounded-lg text-sm text-amber-400">
              <AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> Minimum curve radius R &lt; 200m for V ≤ 60km/h
            </div>
          )}
        </div>
      )}

      {activeTab === 'vertical' && (
        <div>
          <div className="text-lg font-medium mb-3">Vertical Curves</div>
          {computedVertical.map((vc, i) => (
            <div key={`${vc}-${i}`} className="mb-4 p-3 bg-zinc-800 rounded-lg">
              <div className="text-sm text-amber-500 mb-2">VC {i + 1}</div>
              <div className="grid grid-cols-2 gap-2 text-sm">
                <div><span className="text-zinc-400">Grade In:</span> {verticalCurves[i].gradeIn.toFixed(2)}%</div>
                <div><span className="text-zinc-400">Grade Out:</span> {verticalCurves[i].gradeOut.toFixed(2)}%</div>
              </div>
            </div>
          ))}
          {gradientWarning && (
            <div className="mt-2 p-2 bg-amber-900/50 border border-amber-700 rounded-lg text-sm text-amber-400">
              <AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> Gradient exceeds maximum {maxGradientPercent}%
            </div>
          )}
        </div>
      )}

      {activeTab === 'cross' && (
        <div>
          <div className="text-lg font-medium mb-3">Cross Sections</div>
        </div>
      )}

      {activeTab === 'earthworks' && (
        <div>
          <div className="text-lg font-medium mb-3">Earthworks</div>
        </div>
      )}
    </div>
  );
}

export default RailwayPanel;

'use client';

import { useState, useMemo } from 'react';
import { ENGINEERING_QA, type EngineeringSubtype, computeHorizontalCurve, computeVerticalCurve, computeVerticalCurve as verticalCurveElevation, crossSectionCutFill, prismoidalVolume, curveStakeoutPoint } from '@/lib/engine/engineering';
import { formatBearingDMS, formatDistanceM } from '@/lib/drawing/dxfLayers';

interface EngineeringPanelProps {
  projectId: string;
  subtype: EngineeringSubtype;
}

export function RoadPanel({ projectId, subtype }: EngineeringPanelProps) {
  const [activeTab, setActiveTab] = useState<'alignment' | 'horizontal' | 'vertical' | 'cross' | 'earthworks' | 'settingout'>('alignment');
  const qa = ENGINEERING_QA.road;

  const [alignment, setAlignment] = useState<Array<{ chainage: number; easting: number; northing: number; elevation?: number; label: string }>>([]);
  const [horizontalCurves, setHorizontalCurves] = useState<Array<{ radius: number; delta: number; piChainage: number }>>([]);
  const [verticalCurves, setVerticalCurves] = useState<Array<{ pvIChainage: number; pvIElevation: number; gradeIn: number; gradeOut: number; length: number }>>([]);
  const [crossSections, setCrossSections] = useState<Array<{ chainage: number; designLevel: number; levels: Array<{ offset: number; elevation: number }> }>>([]);

  const computedHorizontal = useMemo(() => {
    return horizontalCurves.map(c => computeHorizontalCurve(c.radius, c.delta, c.piChainage));
  }, [horizontalCurves]);

  const computedVertical = useMemo(() => {
    return verticalCurves.map(v => computeVerticalCurve(v.pvIChainage, v.pvIElevation, v.gradeIn, v.gradeOut, v.length));
  }, [verticalCurves]);

  const earthworks = useMemo(() => {
    let totalCut = 0;
    let totalFill = 0;
    crossSections.forEach((cs, i) => {
      if (i > 0) {
        const prev = crossSections[i - 1];
        const { cutArea, fillArea } = crossSectionCutFill(cs.designLevel, cs.levels);
        const dist = cs.chainage - prev.chainage;
        totalCut += prismoidalVolume(cutArea, crossSectionCutFill(prev.designLevel, prev.levels).cutArea, dist);
        totalFill += prismoidalVolume(fillArea, crossSectionCutFill(prev.designLevel, prev.levels).fillArea, dist);
      }
    });
    return { totalCut, totalFill, net: totalCut - totalFill };
  }, [crossSections]);

  const tabs = [
    { id: 'alignment', label: 'Alignment' },
    { id: 'horizontal', label: 'Horizontal Curves' },
    { id: 'vertical', label: 'Vertical Curves' },
    { id: 'cross', label: 'Cross Sections' },
    { id: 'earthworks', label: 'Earthworks' },
    { id: 'settingout', label: 'Setting Out' },
  ] as const;

  return (
    <div className="p-4">
      <div className="mb-4 p-3 bg-zinc-800 rounded-lg">
        <div className="text-sm text-zinc-400">QA Standards</div>
        <div className="flex gap-4 mt-1 text-xs">
          <span>Traverse: 1:{qa.traversePrecision}</span>
          <span>Levelling: {qa.levellingClosureMM}</span>
          <span>Angular: {qa.angularClosureSec}</span>
          <span>Horizontal: ±{qa.horizontalClosureMM}mm/km</span>
        </div>
      </div>

      <div className="flex border-b border-zinc-700 mb-4">
        {tabs.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as typeof activeTab)}
            className={`px-4 py-2 text-sm ${activeTab === tab.id ? 'text-amber-500 border-b-2 border-amber-500' : 'text-zinc-400'}`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {activeTab === 'alignment' && (
        <div>
          <div className="text-lg font-medium mb-3">Alignment Points</div>
          <table className="w-full text-sm">
            <thead>
              <tr className="text-zinc-400 border-b border-zinc-700">
                <th className="text-left py-2">Chainage</th>
                <th className="text-left py-2">Easting</th>
                <th className="text-left py-2">Northing</th>
                <th className="text-left py-2">Elevation</th>
                <th className="text-left py-2">Label</th>
              </tr>
            </thead>
            <tbody>
              {alignment.map((pt, i) => (
                <tr key={pt.label} className="border-b border-zinc-800">
                  <td className="py-2">{pt.chainage.toFixed(3)}</td>
                  <td className="py-2">{pt.easting.toFixed(3)}</td>
                  <td className="py-2">{pt.northing.toFixed(3)}</td>
                  <td className="py-2">{pt.elevation?.toFixed(3) || '-'}</td>
                  <td className="py-2">{pt.label}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <button
            onClick={() => setAlignment([...alignment, { chainage: alignment.length > 0 ? alignment[alignment.length - 1].chainage + 20 : 0, easting: 0, northing: 0, label: `P${alignment.length + 1}` }])}
            className="mt-3 px-3 py-1.5 text-sm bg-amber-600 hover:bg-amber-700 rounded"
          >
            Add Point
          </button>
        </div>
      )}

      {activeTab === 'horizontal' && (
        <div>
          <div className="text-lg font-medium mb-3">Horizontal Curves</div>
          {computedHorizontal.map((curve, i) => (
            <div key={`${curve}-${i}`} className="mb-4 p-3 bg-zinc-800 rounded-lg">
              <div className="text-sm text-amber-500 mb-2">Curve {i + 1}</div>
              <div className="grid grid-cols-2 gap-2 text-sm">
                <div><span className="text-zinc-400">Radius:</span> {horizontalCurves[i].radius}m</div>
                <div><span className="text-zinc-400">Δ:</span> {horizontalCurves[i].delta.toFixed(2)}°</div>
                <div><span className="text-zinc-400">T (Tangent):</span> {curve.tangentLength.toFixed(3)}m</div>
                <div><span className="text-zinc-400">L (Curve):</span> {curve.curveLength.toFixed(3)}m</div>
                <div><span className="text-zinc-400">E (External):</span> {curve.externalDistance.toFixed(3)}m</div>
                <div><span className="text-zinc-400">M (Mid-ord):</span> {curve.midOrdinate.toFixed(3)}m</div>
                <div><span className="text-zinc-400">LC (Long Chord):</span> {curve.longChord.toFixed(3)}m</div>
                <div><span className="text-zinc-400">PC:</span> {curve.pcChainage.toFixed(3)}m</div>
                <div><span className="text-zinc-400">PT:</span> {curve.ptChainage.toFixed(3)}m</div>
              </div>
            </div>
          ))}
          <div className="flex gap-2 mt-3">
            <input
              type="number"
              aria-label="Radius (m)" placeholder="e.g. 250"
              value={horizontalCurves[horizontalCurves.length - 1]?.radius || ''}
              onChange={(e) => {
                const newCurves = [...horizontalCurves];
                if (!newCurves[newCurves.length - 1]) newCurves[newCurves.length - 1] = { radius: 0, delta: 0, piChainage: 0 };
                newCurves[newCurves.length - 1].radius = parseFloat(e.target.value) || 0;
                setHorizontalCurves(newCurves);
              }}
              className="px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm w-32"
            />
            <input
              type="number"
              aria-label="Delta (°)" placeholder="e.g. 12.5"
              value={horizontalCurves[horizontalCurves.length - 1]?.delta || ''}
              onChange={(e) => {
                const newCurves = [...horizontalCurves];
                if (!newCurves[newCurves.length - 1]) newCurves[newCurves.length - 1] = { radius: 0, delta: 0, piChainage: 0 };
                newCurves[newCurves.length - 1].delta = parseFloat(e.target.value) || 0;
                setHorizontalCurves(newCurves);
              }}
              className="px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm w-32"
            />
            <input
              type="number"
              aria-label="PI Chainage" placeholder="e.g. 1+250"
              value={horizontalCurves[horizontalCurves.length - 1]?.piChainage || ''}
              onChange={(e) => {
                const newCurves = [...horizontalCurves];
                if (!newCurves[newCurves.length - 1]) newCurves[newCurves.length - 1] = { radius: 0, delta: 0, piChainage: 0 };
                newCurves[newCurves.length - 1].piChainage = parseFloat(e.target.value) || 0;
                setHorizontalCurves(newCurves);
              }}
              className="px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm w-32"
            />
            <button
              onClick={() => setHorizontalCurves([...horizontalCurves, { radius: 200, delta: 20, piChainage: 500 }])}
              className="px-3 py-1.5 text-sm bg-amber-600 hover:bg-amber-700 rounded"
            >
              Add Curve
            </button>
          </div>
        </div>
      )}

      {activeTab === 'vertical' && (
        <div>
          <div className="text-lg font-medium mb-3">Vertical Curves</div>
          {computedVertical.map((vc, i) => (
            <div key={`${vc}-${i}`} className="mb-4 p-3 bg-zinc-800 rounded-lg">
              <div className="text-sm text-amber-500 mb-2">Vertical Curve {i + 1}</div>
              <div className="grid grid-cols-2 gap-2 text-sm">
                <div><span className="text-zinc-400">PVI Chainage:</span> {verticalCurves[i].pvIChainage.toFixed(3)}m</div>
                <div><span className="text-zinc-400">PVI Elevation:</span> {verticalCurves[i].pvIElevation.toFixed(3)}m</div>
                <div><span className="text-zinc-400">Grade In:</span> {verticalCurves[i].gradeIn.toFixed(2)}%</div>
                <div><span className="text-zinc-400">Grade Out:</span> {verticalCurves[i].gradeOut.toFixed(2)}%</div>
                <div><span className="text-zinc-400">Length:</span> {verticalCurves[i].length.toFixed(3)}m</div>
                {vc.highLowPoint && (
                  <>
                    <div><span className="text-zinc-400">HL Chainage:</span> {vc.highLowPoint.chainage.toFixed(3)}m</div>
                    <div><span className="text-zinc-400">HL Elevation:</span> {vc.highLowPoint.elevation.toFixed(3)}m</div>
                  </>
                )}
              </div>
            </div>
          ))}
          <div className="flex gap-2 mt-3">
            <input
              type="number"
              aria-label="PVI Chainage" placeholder="e.g. 1+250"
              className="px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm w-32"
            />
            <input
              type="number"
              aria-label="PVI Elev" placeholder="e.g. 1580.00"
              className="px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm w-32"
            />
            <input
              type="number"
              aria-label="Grade In %" placeholder="e.g. -3.5"
              className="px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm w-24"
            />
            <input
              type="number"
              aria-label="Grade Out %" placeholder="e.g. 2.5"
              className="px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm w-24"
            />
            <input
              type="number"
              aria-label="Length" placeholder="e.g. 120"
              className="px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm w-24"
            />
            <button
              onClick={() => setVerticalCurves([...verticalCurves, { pvIChainage: 1000, pvIElevation: 1500, gradeIn: 3, gradeOut: -2, length: 200 }])}
              className="px-3 py-1.5 text-sm bg-amber-600 hover:bg-amber-700 rounded"
            >
              Add
            </button>
          </div>
        </div>
      )}

      {activeTab === 'cross' && (
        <div>
          <div className="text-lg font-medium mb-3">Cross Sections</div>
          <table className="w-full text-sm">
            <thead>
              <tr className="text-zinc-400 border-b border-zinc-700">
                <th className="text-left py-2">Chainage</th>
                <th className="text-left py-2">Design Level</th>
                <th className="text-left py-2">Cut (m²)</th>
                <th className="text-left py-2">Fill (m²)</th>
              </tr>
            </thead>
            <tbody>
              {crossSections.map((cs, i) => {
                const { cutArea, fillArea } = crossSectionCutFill(cs.designLevel, cs.levels);
                return (
                  <tr key={`${cs}-${i}`} className="border-b border-zinc-800">
                    <td className="py-2">{cs.chainage.toFixed(3)}</td>
                    <td className="py-2">{cs.designLevel.toFixed(3)}</td>
                    <td className="py-2">{cutArea.toFixed(3)}</td>
                    <td className="py-2">{fillArea.toFixed(3)}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === 'earthworks' && (
        <div>
          <div className="text-lg font-medium mb-3">Earthworks Summary</div>
          <div className="grid grid-cols-3 gap-4">
            <div className="p-4 bg-zinc-800 rounded-lg">
              <div className="text-sm text-zinc-400">Total Cut</div>
              <div className="text-xl text-red-400">{earthworks.totalCut.toFixed(2)} m³</div>
            </div>
            <div className="p-4 bg-zinc-800 rounded-lg">
              <div className="text-sm text-zinc-400">Total Fill</div>
              <div className="text-xl text-blue-400">{earthworks.totalFill.toFixed(2)} m³</div>
            </div>
            <div className="p-4 bg-zinc-800 rounded-lg">
              <div className="text-sm text-zinc-400">Net</div>
              <div className={`text-xl ${earthworks.net >= 0 ? 'text-blue-400' : 'text-red-400'}`}>
                {earthworks.net.toFixed(2)} m³
              </div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'settingout' && (
        <div>
          <div className="text-lg font-medium mb-3">Setting Out</div>
          <div className="p-4 bg-zinc-800 rounded-lg text-sm">
            <div className="text-zinc-400 mb-2">Stakeout Point Calculator</div>
            <div className="flex gap-2">
              <input
                type="number"
                aria-label="PC Easting" placeholder="e.g. 500000"
                className="px-2 py-1.5 bg-zinc-700 border border-zinc-600 rounded text-sm w-28"
              />
              <input
                type="number"
                aria-label="PC Northing" placeholder="e.g. 9900000"
                className="px-2 py-1.5 bg-zinc-700 border border-zinc-600 rounded text-sm w-28"
              />
              <input
                type="number"
                aria-label="Initial Bearing" placeholder="e.g. 45°"
                className="px-2 py-1.5 bg-zinc-700 border border-zinc-600 rounded text-sm w-28"
              />
              <input
                type="number"
                aria-label="Radius" placeholder="e.g. 250"
                className="px-2 py-1.5 bg-zinc-700 border border-zinc-600 rounded text-sm w-24"
              />
              <input
                type="number"
                aria-label="Chainage" placeholder="e.g. 1+250"
                className="px-2 py-1.5 bg-zinc-700 border border-zinc-600 rounded text-sm w-24"
              />
              <select className="px-2 py-1.5 bg-zinc-700 border border-zinc-600 rounded text-sm">
                <option value="right">Right</option>
                <option value="left">Left</option>
              </select>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default RoadPanel;

'use client';

import { useState } from 'react';
import { ENGINEERING_QA, type EngineeringSubtype } from '@/lib/engine/engineering';

interface EngineeringPanelProps {
  projectId: string;
  subtype: EngineeringSubtype;
}

function computeBearing(from: { easting: number; northing: number }, to: { easting: number; northing: number }): number {
  const dE = to.easting - from.easting;
  const dN = to.northing - from.northing;
  return (Math.atan2(dE, dN) * 180 / Math.PI + 360) % 360;
}

function formatBearingDDMSS(bearing: number): string {
  const deg = Math.floor(bearing);
  const minFloat = (bearing - deg) * 60;
  const min = Math.floor(minFloat);
  const sec = ((minFloat - min) * 60).toFixed(1);
  return `${deg}°${String(min).padStart(2, '0')}'${sec}"`;
}

export function TunnelPanel({ projectId, subtype }: EngineeringPanelProps) {
  const [activeTab, setActiveTab] = useState<'control' | 'geometry' | 'profile' | 'convergence'>('control');
  const qa = ENGINEERING_QA.tunnel;

  const [portalPoints, setPortalPoints] = useState<Array<{ easting: number; northing: number; elevation: number }>>([]);
  const [excavatedWidthM, setExcavatedWidthM] = useState(10);
  const [excavatedHeightM, setExcavatedHeightM] = useState(8);
  const [gradientPercent, setGradientPercent] = useState(0.5);
  const [convergencePoints, setConvergencePoints] = useState<Array<{ chainage: number; label: string }>>([]);

  const totalLengthM = portalPoints.length >= 2
    ? Math.sqrt(
        Math.pow(portalPoints[1].easting - portalPoints[0].easting, 2) +
        Math.pow(portalPoints[1].northing - portalPoints[0].northing, 2)
      )
    : 0;

  const crossSectionArea = excavatedWidthM * excavatedHeightM + (Math.PI * Math.pow(excavatedWidthM / 2, 2) / 2);

  const tabs = [
    { id: 'control', label: 'Control Survey' },
    { id: 'geometry', label: 'Tunnel Geometry' },
    { id: 'profile', label: 'Profile' },
    { id: 'convergence', label: 'Convergence Monitoring' },
  ] as const;

  return (
    <div className="p-4">
      <div className="mb-4 p-3 bg-zinc-800 rounded-lg">
        <div className="text-sm text-zinc-400">QA Standards</div>
        <div className="flex gap-4 mt-1 text-xs">
          <span>Traverse: 1:{qa.traversePrecision}</span>
          <span>Levelling: {qa.levellingClosureMM}</span>
          <span>Angular: {qa.angularClosureSec}</span>
          <span>Horizontal: ±{qa.horizontalClosureMM}mm/km</span>
        </div>
      </div>

      <div className="flex border-b border-zinc-700 mb-4">
        {tabs.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as typeof activeTab)}
            className={`px-4 py-2 text-sm ${activeTab === tab.id ? 'text-amber-500 border-b-2 border-amber-500' : 'text-zinc-400'}`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {activeTab === 'control' && (
        <div>
          <div className="text-lg font-medium mb-3">Portal Coordinates</div>
          <table className="w-full text-sm">
            <thead>
              <tr className="text-zinc-400 border-b border-zinc-700">
                <th className="text-left py-2">Portal</th>
                <th className="text-left py-2">Easting</th>
                <th className="text-left py-2">Northing</th>
                <th className="text-left py-2">Elevation</th>
              </tr>
            </thead>
            <tbody>
              <tr className="border-b border-zinc-800">
                <td className="py-2">Portal 1 (Inlet)</td>
                <td className="py-2">{portalPoints[0]?.easting.toFixed(3) || '—'}</td>
                <td className="py-2">{portalPoints[0]?.northing.toFixed(3) || '—'}</td>
                <td className="py-2">{portalPoints[0]?.elevation.toFixed(3) || '—'}</td>
              </tr>
              <tr className="border-b border-zinc-800">
                <td className="py-2">Portal 2 (Outlet)</td>
                <td className="py-2">{portalPoints[1]?.easting.toFixed(3) || '—'}</td>
                <td className="py-2">{portalPoints[1]?.northing.toFixed(3) || '—'}</td>
                <td className="py-2">{portalPoints[1]?.elevation.toFixed(3) || '—'}</td>
              </tr>
            </tbody>
          </table>
          <button
            onClick={() => setPortalPoints([{ easting: 0, northing: 0, elevation: 0 }, { easting: 0, northing: 0, elevation: 0 }])}
            className="mt-3 px-3 py-1.5 text-sm bg-amber-600 hover:bg-amber-700 rounded"
          >
            Add Portals
          </button>
          {portalPoints.length >= 2 && (
            <div className="mt-4 p-3 bg-zinc-800 rounded-lg">
              <div className="text-sm text-zinc-400">Tunnel Bearing</div>
              <div className="text-lg text-amber-500">{formatBearingDDMSS(computeBearing(portalPoints[0], portalPoints[1]))}</div>
              <div className="text-sm text-zinc-400 mt-2">True Length</div>
              <div className="text-lg">{totalLengthM.toFixed(3)} m</div>
            </div>
          )}
        </div>
      )}

      {activeTab === 'geometry' && (
        <div>
          <div className="text-lg font-medium mb-3">Tunnel Geometry</div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-sm text-zinc-400" htmlFor="excavated-width-m">Excavated Width (m)</label>
              <input id="excavated-width-m" aria-label="Excavated Width (m)"
                type="number"
                value={excavatedWidthM}
                onChange={(e) => setExcavatedWidthM(parseFloat(e.target.value) || 0)}
                className="w-full mt-1 px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm"
              />
            </div>
            <div>
              <label className="text-sm text-zinc-400" htmlFor="excavated-height-m">Excavated Height (m)</label>
              <input id="excavated-height-m" aria-label="Excavated Height (m)"
                type="number"
                value={excavatedHeightM}
                onChange={(e) => setExcavatedHeightM(parseFloat(e.target.value) || 0)}
                className="w-full mt-1 px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm"
              />
            </div>
            <div>
              <label className="text-sm text-zinc-400" htmlFor="gradient">Gradient (%)</label>
              <input  id="gradient" aria-label="Gradient (%)"
                type="number"
                step={0.1}
                value={gradientPercent}
                onChange={(e) => setGradientPercent(parseFloat(e.target.value) || 0)}
                className="w-full mt-1 px-2 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-sm"
              />
            </div>
            <div className="p-4 bg-zinc-800 rounded-lg">
              <div className="text-sm text-zinc-400">Cross-Section Area</div>
              <div className="text-lg text-amber-500">{crossSectionArea.toFixed(2)} m²</div>
            </div>
            <div className="p-4 bg-zinc-800 rounded-lg col-span-2">
              <div className="text-sm text-zinc-400">Excavated Volume</div>
              <div className="text-lg">{(crossSectionArea * totalLengthM / 1000).toFixed(2)} m³</div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'profile' && (
        <div>
          <div className="text-lg font-medium mb-3">Profile</div>
          {portalPoints.length >= 2 && totalLengthM > 0 ? (() => {
            const inletElev = portalPoints[0].elevation;
            const outletElev = inletElev - (totalLengthM * gradientPercent / 100);
            const interval = 50;
            const profileRows: Array<{ chainage: number; elevation: number }> = [];
            for (let ch = 0; ch <= totalLengthM + 0.001; ch += interval) {
              const clampedCh = Math.min(ch, totalLengthM);
              profileRows.push({
                chainage: clampedCh,
                elevation: inletElev - (clampedCh * gradientPercent / 100),
              });
            }
            if (profileRows[profileRows.length - 1].chainage < totalLengthM) {
              profileRows.push({ chainage: totalLengthM, elevation: outletElev });
            }
            const minElev = Math.min(inletElev, outletElev);
            const maxElev = Math.max(inletElev, outletElev);
            const elevRange = maxElev - minElev || 1;
            const svgW = 480;
            const svgH = 160;
            const padX = 50;
            const padY = 20;
            const plotW = svgW - padX - 20;
            const plotH = svgH - padY * 2;
            const xScale = (ch: number) => padX + (ch / totalLengthM) * plotW;
            const yScale = (e: number) => padY + plotH - ((e - minElev) / elevRange) * plotH;

            return (
              <>
                <div className="grid grid-cols-4 gap-3 mb-4">
                  <div className="p-3 bg-zinc-800 rounded-lg">
                    <div className="text-xs text-zinc-400">Inlet Elevation</div>
                    <div className="text-sm font-medium text-amber-500">{inletElev.toFixed(3)} m</div>
                  </div>
                  <div className="p-3 bg-zinc-800 rounded-lg">
                    <div className="text-xs text-zinc-400">Outlet Elevation</div>
                    <div className="text-sm font-medium text-amber-500">{outletElev.toFixed(3)} m</div>
                  </div>
                  <div className="p-3 bg-zinc-800 rounded-lg">
                    <div className="text-xs text-zinc-400">Total Length</div>
                    <div className="text-sm font-medium">{totalLengthM.toFixed(2)} m</div>
                  </div>
                  <div className="p-3 bg-zinc-800 rounded-lg">
                    <div className="text-xs text-zinc-400">Gradient</div>
                    <div className="text-sm font-medium">{gradientPercent}%</div>
                  </div>
                </div>

                <div className="mb-4 p-3 bg-zinc-800 rounded-lg overflow-x-auto">
                  <svg viewBox={`0 0 ${svgW} ${svgH}`} className="w-full h-40" preserveAspectRatio="xMidYMid meet">
                    <rect x={padX} y={padY} width={plotW} height={plotH} fill="none" stroke="#3f3f46" strokeWidth={0.5} />
                    {[0, 0.25, 0.5, 0.75, 1].map((frac) => {
                      const y = padY + plotH * (1 - frac);
                      const elev = minElev + elevRange * frac;
                      return (
                        <g key={frac}>
                          <line x1={padX} y1={y} x2={padX + plotW} y2={y} stroke="#3f3f46" strokeWidth={0.5} strokeDasharray={frac === 0 || frac === 1 ? 'none' : '3,3'} />
                          <text x={padX - 4} y={y + 3} textAnchor="end" fill="#a1a1aa" fontSize={8}>{elev.toFixed(1)}</text>
                        </g>
                      );
                    })}
                    {profileRows.map((_, i) => {
                      const frac = i / (profileRows.length - 1);
                      const x = padX + plotW * frac;
                      return (
                        <text key={`xl${i}`} x={x} y={svgH - 2} textAnchor="middle" fill="#a1a1aa" fontSize={7}>{profileRows[i].chainage.toFixed(0)}</text>
                      );
                    })}
                    <polyline
                      points={profileRows.map((r) => `${xScale(r.chainage).toFixed(1)},${yScale(r.elevation).toFixed(1)}`).join(' ')}
                      fill="none"
                      stroke="#f59e0b"
                      strokeWidth={2}
                    />
                    {profileRows.map((r, i) => (
                      <circle key={`${r}-${i}`} cx={xScale(r.chainage)} cy={yScale(r.elevation)} r={3} fill="#f59e0b" stroke="#18181b" strokeWidth={1} />
                    ))}
                    <text x={padX + plotW / 2} y={12} textAnchor="middle" fill="#a1a1aa" fontSize={9}>Design Profile</text>
                    <text x={svgW / 2} y={svgH - 0} textAnchor="middle" fill="#71717a" fontSize={8}>Chainage (m)</text>
                  </svg>
                </div>

                <div className="text-sm text-zinc-400 mb-2">Chainage Elevations (every {interval}m)</div>
                <table className="w-full text-sm">
                  <thead>
                    <tr className="text-zinc-400 border-b border-zinc-700">
                      <th className="text-left py-2">Chainage (m)</th>
                      <th className="text-left py-2">Design Elevation (m)</th>
                      <th className="text-left py-2">Distance from Inlet (m)</th>
                    </tr>
                  </thead>
                  <tbody>
                    {profileRows.map((row, i) => (
                      <tr key={`${row}-${i}`} className="border-b border-zinc-800 hover:bg-zinc-800/50">
                        <td className="py-1.5">{row.chainage.toFixed(1)}</td>
                        <td className="py-1.5">{row.elevation.toFixed(3)}</td>
                        <td className="py-1.5">{row.chainage.toFixed(1)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </>
            );
          })() : (
            <div className="text-sm text-zinc-400">Add portal points in the Control Survey tab to view the tunnel profile.</div>
          )}
        </div>
      )}

      {activeTab === 'convergence' && (
        <div>
          <div className="text-lg font-medium mb-3">Convergence Monitoring Points</div>
          <table className="w-full text-sm">
            <thead>
              <tr className="text-zinc-400 border-b border-zinc-700">
                <th className="text-left py-2">Chainage</th>
                <th className="text-left py-2">Label</th>
              </tr>
            </thead>
            <tbody>
              {convergencePoints.map((pt, i) => (
                <tr key={pt.label} className="border-b border-zinc-800">
                  <td className="py-2">{pt.chainage.toFixed(3)}</td>
                  <td className="py-2">{pt.label}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <button
            onClick={() => setConvergencePoints([...convergencePoints, { chainage: convergencePoints.length * 50, label: `C${convergencePoints.length + 1}` }])}
            className="mt-3 px-3 py-1.5 text-sm bg-amber-600 hover:bg-amber-700 rounded"
          >
            Add Point
          </button>
        </div>
      )}
    </div>
  );
}

export default TunnelPanel;

'use client';

import React, { useState, useMemo, useCallback } from 'react'
import { designPavement, computeLayerQuantities, classifySubgrade } from '@/lib/engineering/pavementDesign'
import type { TrafficData, SubgradeData, PavementDesignResult, PavementLayer } from '@/lib/engineering/pavementDesign'

interface PavementDesignPanelProps {
  roadClass?: string
  carriagewayWidth?: number
  roadLength?: number
  onLayersChange?: (layers: PavementLayer[]) => void
}

interface ValidationErrors {
  aadt?: string
  cbr?: string
  growthRate?: string
  designPeriod?: string
  heavyVehiclePercentage?: string
  roadLength?: string
}

function validate(data: { traffic: TrafficData; subgrade: SubgradeData; roadLength: number }): ValidationErrors {
  const errors: ValidationErrors = {}
  const { traffic, subgrade, roadLength } = data

  if (traffic.aadt <= 0) {
    errors.aadt = 'AADT must be greater than 0'
  }
  if (subgrade.cbr < 2 || subgrade.cbr > 100) {
    errors.cbr = 'CBR must be between 2 and 100'
  }
  if (traffic.growthRate < 0) {
    errors.growthRate = 'Growth rate must be >= 0'
  }
  if (traffic.designPeriod < 10 || traffic.designPeriod > 40) {
    errors.designPeriod = 'Design period must be between 10 and 40 years'
  }
  if (traffic.heavyVehiclePercentage < 0 || traffic.heavyVehiclePercentage > 100) {
    errors.heavyVehiclePercentage = 'Heavy vehicle % must be between 0 and 100'
  }
  if (roadLength <= 0) {
    errors.roadLength = 'Road length must be greater than 0'
  }

  return errors
}

const safeNum = (v: number, fallback: string = '—') =>
  Number.isFinite(v) && !Number.isNaN(v) ? v : fallback

export default function PavementDesignPanel({
  roadClass,
  carriagewayWidth = 7.0,
  roadLength: roadLengthProp = 1000,
}: PavementDesignPanelProps) {
  const [traffic, setTraffic] = useState<TrafficData>({
    aadt: 5000, heavyVehiclePercentage: 15, growthRate: 4, designPeriod: 20,
    directionalSplit: 0.5, laneFactor: 0.85, numberOfLanes: 2, vehicleDamageFactor: 1.5,
  })
  const [subgrade, setSubgrade] = useState<SubgradeData>({ cbr: 8 })
  const [roadLength, setRoadLength] = useState(roadLengthProp)
  const [result, setResult] = useState<PavementDesignResult | null>(null)
  const [errors, setErrors] = useState<ValidationErrors>({})

  const quantities = useMemo(() => {
    if (!result) return []
    return computeLayerQuantities(result.layers, roadLength, carriagewayWidth)
  }, [result, roadLength, carriagewayWidth])

  const handleDesign = () => {
    const validationErrors = validate({ traffic, subgrade, roadLength })
    setErrors(validationErrors)
    if (Object.keys(validationErrors).length > 0) return

    const r = designPavement(traffic, subgrade)
    setResult(r)
  }

  const handleExportCSV = useCallback(() => {
    if (!result || quantities.length === 0) return

    const header = 'layer_name,thickness_mm,material,volume_m3,tonnage'
    const rows = quantities.map(q =>
      [
        `"${q.layer}"`,
        q.volumeM3 > 0
          ? result.layers.find(l => l.name === q.layer)?.thicknessMm ?? ''
          : '',
        `"${q.material}"`,
        safeNum(q.volumeM3, ''),
        safeNum(q.tonnage, ''),
      ].join(',')
    )

    const csv = [header, ...rows].join('\n')
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = `pavement_layer_report_${Date.now()}.csv`
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
    URL.revokeObjectURL(url)
  }, [result, quantities])

  const inputCls =
    'w-full border border-zinc-600 rounded-lg px-3 py-2 text-sm bg-zinc-800 text-white placeholder-zinc-500 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500'
  const labelCls = 'block text-xs text-zinc-400 mb-1'
  const errorCls = 'text-xs text-red-400 mt-1'

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
        <h3 className="text-lg font-semibold text-white">Pavement Layer Design</h3>
        <p className="text-sm text-zinc-400 mt-1">KeNHA Pavement &amp; Materials Design Manual — CBR-based method</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Traffic Data */}
        <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
          <h4 className="font-medium text-white mb-4">Traffic Data</h4>
          <div className="space-y-3">
            {/* AADT */}
            <div>
              <label className={labelCls} htmlFor="aadt-veh-day">AADT (veh/day)</label>
              <input id="aadt-veh-day" aria-label="Aadt"
                type="number"
                step="any"
                className={`${inputCls}${errors.aadt ? ' border-red-500' : ''}`}
                value={traffic.aadt}
                onChange={e => setTraffic({ ...traffic, aadt: parseFloat(e.target.value) || 0 })}
              />
              {errors.aadt && <p className={errorCls}>{errors.aadt}</p>}
            </div>

            {/* Heavy Vehicle % */}
            <div>
              <label className={labelCls} htmlFor="heavy-vehicles">Heavy Vehicles (%)</label>
              <input id="heavy-vehicles" aria-label="Heavyvehiclepercentage"
                type="number"
                step="any"
                className={`${inputCls}${errors.heavyVehiclePercentage ? ' border-red-500' : ''}`}
                value={traffic.heavyVehiclePercentage}
                onChange={e => setTraffic({ ...traffic, heavyVehiclePercentage: parseFloat(e.target.value) || 0 })}
              />
              {errors.heavyVehiclePercentage && <p className={errorCls}>{errors.heavyVehiclePercentage}</p>}
            </div>

            {/* Growth Rate */}
            <div>
              <label className={labelCls} htmlFor="growth-rate-yr">Growth Rate (%/yr)</label>
              <input id="growth-rate-yr" aria-label="Growthrate"
                type="number"
                step="any"
                className={`${inputCls}${errors.growthRate ? ' border-red-500' : ''}`}
                value={traffic.growthRate}
                onChange={e => setTraffic({ ...traffic, growthRate: parseFloat(e.target.value) || 0 })}
              />
              {errors.growthRate && <p className={errorCls}>{errors.growthRate}</p>}
            </div>

            {/* Design Period */}
            <div>
              <label className={labelCls} htmlFor="design-period-years">Design Period (years)</label>
              <input id="design-period-years" aria-label="Designperiod"
                type="number"
                step="any"
                className={`${inputCls}${errors.designPeriod ? ' border-red-500' : ''}`}
                value={traffic.designPeriod}
                onChange={e => setTraffic({ ...traffic, designPeriod: parseFloat(e.target.value) || 0 })}
              />
              {errors.designPeriod && <p className={errorCls}>{errors.designPeriod}</p>}
            </div>

            {/* Directional Split */}
            <div>
              <label className={labelCls} htmlFor="directional-split">Directional Split</label>
              <input id="directional-split" aria-label="Directionalsplit"
                type="number"
                step="any"
                className={inputCls}
                value={traffic.directionalSplit}
                onChange={e => setTraffic({ ...traffic, directionalSplit: parseFloat(e.target.value) || 0 })}
              />
            </div>

            {/* Lane Factor */}
            <div>
              <label className={labelCls} htmlFor="lane-factor">Lane Factor</label>
              <input id="lane-factor" aria-label="Lanefactor"
                type="number"
                step="any"
                className={inputCls}
                value={traffic.laneFactor}
                onChange={e => setTraffic({ ...traffic, laneFactor: parseFloat(e.target.value) || 0 })}
              />
            </div>

            {/* Number of Lanes */}
            <div>
              <label className={labelCls} htmlFor="no-of-lanes">No. of Lanes</label>
              <input id="no-of-lanes" aria-label="Numberoflanes"
                type="number"
                step="any"
                className={inputCls}
                value={traffic.numberOfLanes}
                onChange={e => setTraffic({ ...traffic, numberOfLanes: parseFloat(e.target.value) || 0 })}
              />
            </div>

            {/* Vehicle Damage Factor */}
            <div>
              <label className={labelCls} htmlFor="vehicle-damage-factor">Vehicle Damage Factor</label>
              <input id="vehicle-damage-factor" aria-label="Vehicle Damage Factor"
                type="number"
                step="any"
                className={inputCls}
                value={traffic.vehicleDamageFactor ?? 1.0}
                onChange={e => setTraffic({ ...traffic, vehicleDamageFactor: parseFloat(e.target.value) || 0 })}
              />
            </div>
          </div>
        </div>

        {/* Subgrade Data */}
        <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
          <h4 className="font-medium text-white mb-4">Subgrade Data</h4>
          <div className="space-y-3">
            {/* CBR */}
            <div>
              <label className={labelCls}>CBR (%) — {classifySubgrade(subgrade.cbr)}</label>
              <input aria-label="Cbr"
                type="range"
                min={1}
                max={100}
                className="w-full"
                value={subgrade.cbr}
                onChange={e => setSubgrade({ ...subgrade, cbr: parseInt(e.target.value) })}
              />
              <div className="flex justify-between text-xs text-zinc-500">
                <span>1% (SG4)</span>
                <span className="font-medium text-zinc-200">{subgrade.cbr}%</span>
                <span>100% (SG1)</span>
              </div>
              {errors.cbr && <p className={errorCls}>{errors.cbr}</p>}
            </div>

            {/* Soil Type */}
            <div>
              <label className={labelCls} htmlFor="soil-type">Soil Type</label>
              <select id="soil-type"
                className={`${inputCls}${errors.cbr ? ' border-red-500' : ''}`}
                value={subgrade.soilType || ''}
                onChange={e => setSubgrade({ ...subgrade, soilType: e.target.value })}
              >
                <option value="">Select...</option>
                <option value="granular">Granular</option>
                <option value="clay">Clay</option>
                <option value="silt">Silt</option>
                <option value="sand">Sand</option>
                <option value="rock">Rock</option>
              </select>
            </div>

            {/* Road Length — now editable */}
            <div>
              <label className={labelCls} htmlFor="road-length-m">Road Length (m)</label>
              <input  id="road-length-m" aria-label="Road Length (m)"
                type="number"
                className={`${inputCls}${errors.roadLength ? ' border-red-500' : ''}`}
                value={roadLength}
                onChange={e => setRoadLength(parseFloat(e.target.value) || 0)}
              />
              {errors.roadLength && <p className={errorCls}>{errors.roadLength}</p>}
            </div>
          </div>

          <button
            onClick={handleDesign}
            className="w-full mt-6 px-4 py-3 bg-blue-600 text-white rounded-lg font-medium hover:bg-blue-700 transition-colors"
          >
            Design Pavement
          </button>
        </div>
      </div>

      {/* Results */}
      {result && (
        <>
          {/* Summary Cards */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="bg-blue-950/40 rounded-xl border border-blue-800 p-4">
              <div className="text-xs text-blue-400 uppercase tracking-wider">ESA</div>
              <div className="text-2xl font-bold text-blue-300">
                {safeNum(result.esaMillions, '—') !== '—'
                  ? `${result.esaMillions.toFixed(3)}M`
                  : '—'}
              </div>
            </div>
            <div className="bg-purple-950/40 rounded-xl border border-purple-800 p-4">
              <div className="text-xs text-purple-400 uppercase tracking-wider">Traffic Class</div>
              <div className="text-2xl font-bold text-purple-300">{result.trafficClass}</div>
            </div>
            <div className="bg-amber-950/40 rounded-xl border border-amber-800 p-4">
              <div className="text-xs text-amber-400 uppercase tracking-wider">Subgrade Class</div>
              <div className="text-2xl font-bold text-amber-300">{result.subgradeClass}</div>
            </div>
            <div className="bg-green-950/40 rounded-xl border border-green-800 p-4">
              <div className="text-xs text-green-400 uppercase tracking-wider">Total Thickness</div>
              <div className="text-2xl font-bold text-green-300">
                {safeNum(result.totalThickness, '—') !== '—'
                  ? `${result.totalThickness} mm`
                  : '—'}
              </div>
            </div>
          </div>

          {/* Pavement Structure Diagram */}
          <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
            <h4 className="font-medium text-white mb-3">Pavement Structure</h4>
            <PavementStructureDiagram layers={result.layers} />
          </div>

          {/* Layer Table */}
          <div className="bg-zinc-900 rounded-xl border border-zinc-700 overflow-hidden">
            <div className="px-6 py-4 border-b border-zinc-700">
              <h4 className="font-medium text-white">Layer Schedule</h4>
            </div>
            <table className="w-full text-sm">
              <thead className="bg-zinc-800">
                <tr>
                  <th className="px-4 py-2 text-left text-xs font-medium text-zinc-400">Layer</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-zinc-400">Material</th>
                  <th className="px-4 py-2 text-right text-xs font-medium text-zinc-400">Thickness</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-zinc-400">Description</th>
                </tr>
              </thead>
              <tbody>
                {result.layers.map((layer, i) => (
                  <tr key={layer.name} className="border-t border-zinc-800">
                    <td className="px-4 py-2 font-medium text-white">
                      <span className="inline-block w-3 h-3 rounded-sm mr-2" style={{ backgroundColor: layer.color }} />
                      {layer.name}
                    </td>
                    <td className="px-4 py-2 text-zinc-300">{layer.material}</td>
                    <td className="px-4 py-2 text-right font-mono text-white">{layer.thicknessMm} mm</td>
                    <td className="px-4 py-2 text-zinc-400 text-xs">{layer.description}</td>
                  </tr>
                ))}
                <tr className="bg-zinc-800 font-semibold">
                  <td className="px-4 py-2 text-white" colSpan={2}>Total</td>
                  <td className="px-4 py-2 text-right font-mono text-white">
                    {safeNum(result.totalThickness, '—') !== '—'
                      ? `${result.totalThickness} mm`
                      : '—'}
                  </td>
                  <td className="px-4 py-2"></td>
                </tr>
              </tbody>
            </table>
          </div>

          {/* Material Quantities */}
          {quantities.length > 0 && (
            <div className="bg-zinc-900 rounded-xl border border-zinc-700 overflow-hidden">
              <div className="px-6 py-4 border-b border-zinc-700 flex items-center justify-between">
                <h4 className="font-medium text-white">
                  Material Quantities (L={roadLength}m &times; W={carriagewayWidth}m)
                </h4>
                <button
                  onClick={handleExportCSV}
                  className="px-4 py-2 bg-emerald-600 text-white text-sm rounded-lg font-medium hover:bg-emerald-700 transition-colors"
                >
                  Download Layer Report
                </button>
              </div>
              <table className="w-full text-sm">
                <thead className="bg-zinc-800">
                  <tr>
                    <th className="px-4 py-2 text-left text-xs font-medium text-zinc-400">Layer</th>
                    <th className="px-4 py-2 text-right text-xs font-medium text-zinc-400">Volume (m&sup3;)</th>
                    <th className="px-4 py-2 text-right text-xs font-medium text-zinc-400">Tonnage</th>
                    <th className="px-4 py-2 text-right text-xs font-medium text-zinc-400">Density (kg/m&sup3;)</th>
                  </tr>
                </thead>
                <tbody>
                  {quantities.map((q, i) => (
                    <tr key={`${q}-${i}`} className="border-t border-zinc-800">
                      <td className="px-4 py-2 font-medium text-white">{q.layer}</td>
                      <td className="px-4 py-2 text-right font-mono text-zinc-300">
                        {safeNum(q.volumeM3, '—') !== '—' ? q.volumeM3.toLocaleString() : '—'}
                      </td>
                      <td className="px-4 py-2 text-right font-mono text-zinc-300">
                        {safeNum(q.tonnage, '—') !== '—' ? q.tonnage.toLocaleString() : '—'}
                      </td>
                      <td className="px-4 py-2 text-right text-zinc-400">
                        {safeNum(q.density, '—') !== '—' ? q.density : '—'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}
    </div>
  )
}

// ─── PAVEMENT STRUCTURE SVG ───────────────────────────────────────────────────

function PavementStructureDiagram({ layers }: { layers: PavementLayer[] }) {
  const width = 400
  const layerHeight = 50
  const subgradeHeight = 60
  const height = layers.length * layerHeight + subgradeHeight + 60
  const padX = 80
  const padY = 30
  const layerWidth = width - padX * 2

  const totalThickness = layers.reduce((s, l) => s + l.thicknessMm, 0)

  let y = padY

  return (
    <svg viewBox={`0 0 ${width} ${height}`} className="w-full max-w-md mx-auto">
      {layers.map((layer, i) => {
        const currentY = y
        y += layerHeight
        return (
          <g key={layer.name}>
            <rect x={padX} y={currentY} width={layerWidth} height={layerHeight} fill={layer.color} rx={i === 0 ? 6 : 0} />
            {i > 0 && <line x1={padX} y1={currentY} x2={padX + layerWidth} y2={currentY} stroke="rgba(255,255,255,0.3)" strokeWidth={1} />}
            <text x={padX + layerWidth / 2} y={currentY + layerHeight / 2 + 4} textAnchor="middle" fill="white" fontSize="11" fontWeight="500">
              {layer.name}
            </text>
            <text x={padX - 8} y={currentY + layerHeight / 2 + 4} textAnchor="end" fill="#d4d4d8" fontSize="10" fontWeight="500">
              {layer.thicknessMm}
            </text>
          </g>
        )
      })}
      {/* Subgrade */}
      <rect x={padX} y={y} width={layerWidth} height={subgradeHeight} fill="#52525b" rx={0} />
      <text x={padX + layerWidth / 2} y={y + subgradeHeight / 2 + 4} textAnchor="middle" fill="#d4d4d8" fontSize="11">Subgrade</text>
      {/* Total annotation */}
      <text x={padX - 8} y={padY - 10} textAnchor="end" fill="#d4d4d8" fontSize="12" fontWeight="600">
        {Number.isFinite(totalThickness) ? `${totalThickness} mm` : '—'}
      </text>
      <line x1={padX - 25} y1={padY} x2={padX - 25} y2={y} stroke="#d4d4d8" strokeWidth={1.5} />
      <line x1={padX - 30} y1={padY} x2={padX - 20} y2={padY} stroke="#d4d4d8" strokeWidth={1.5} />
      <line x1={padX - 30} y1={y} x2={padX - 20} y2={y} stroke="#d4d4d8" strokeWidth={1.5} />
    </svg>
  )
}

