                    <>
                      <svg className="animate-spin w-4 h-4 mr-1.5" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2">
                        <circle cx="8" cy="8" r="6" strokeOpacity="0.3" />
                        <path d="M14 8a6 6 0 01-6 6" />
                      </svg>
                      Computing...
                    </>
                  ) : (
                    'Run Cut/Fill Analysis'
                  )}
                </Button>
                {cutFillResult && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={handleExportCutFillCSV}
                    className="border-zinc-600 text-zinc-300 hover:bg-zinc-700 hover:text-blue-400"
                  >
                    Export CSV
                  </Button>
                )}
              </div>
            </CardContent>
          </Card>

          {cutFillResult && (
            <>
              {/* ── Summary Cards ── */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                <SummaryCard
                  label="Cut Volume"
                  value={`${fmtShort(cutFillResult.totalCutVolume)} m³`}
                  accent
                />
                <SummaryCard
                  label="Fill Volume"
                  value={`${fmtShort(cutFillResult.totalFillVolume)} m³`}
                  accent
                />
                <SummaryCard
                  label="Net Volume"
                  value={`${fmtShort(cutFillResult.netVolume)} m³`}
                  accent
                  valueColor={cutFillResult.netVolume > 0 ? 'text-green-400' : cutFillResult.netVolume < 0 ? 'text-red-400' : 'text-zinc-200'}
                />
                <SummaryCard
                  label="Balance Point"
                  value={`${fmt(cutFillResult.balancePoint, 3)} m`}
                  accent
                />
              </div>

              {/* ── Area Breakdown ── */}
              <div className="grid grid-cols-2 gap-3">
                <Card className="border-zinc-700 bg-zinc-800/50">
                  <CardContent className="p-4">
                    <p className="text-xs text-zinc-500 mb-1">Cut Area</p>
                    <p className="text-lg font-bold font-mono text-amber-400">
                      {fmt(cutFillResult.cutArea)} m²
                    </p>
                  </CardContent>
                </Card>
                <Card className="border-zinc-700 bg-zinc-800/50">
                  <CardContent className="p-4">
                    <p className="text-xs text-zinc-500 mb-1">Fill Area</p>
                    <p className="text-lg font-bold font-mono text-blue-400">
                      {fmt(cutFillResult.fillArea)} m²
                    </p>
                  </CardContent>
                </Card>
              </div>

              {/* ── Sample Points Table ── */}
              <Card className="border-zinc-700 bg-zinc-800/50">
                <CardHeader>
                  <CardTitle className="text-zinc-100 text-sm">
                    Grid Points ({cutFillResult.points.length} total{cutFillSample.length < cutFillResult.points.length ? `, showing ${cutFillSample.length}` : ''})
                  </CardTitle>
                </CardHeader>
                <CardContent className="max-h-80 overflow-y-auto">
                  <Table>
                    <TableHeader>
                      <TableRow className="border-zinc-700 hover:bg-transparent">
                        <TableHead className="text-zinc-400 text-xs">Easting</TableHead>
                        <TableHead className="text-zinc-400 text-xs">Northing</TableHead>
                        <TableHead className="text-zinc-400 text-xs text-right">Existing RL</TableHead>
                        <TableHead className="text-zinc-400 text-xs text-right">Design RL</TableHead>
                        <TableHead className="text-zinc-400 text-xs text-right">Difference</TableHead>
                        <TableHead className="text-zinc-400 text-xs">Class</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {cutFillSample.map((p, i) => {
                        const cls = p.difference > 0 ? 'Cut' : p.difference < 0 ? 'Fill' : 'On Grade';
                        return (
                          <TableRow key={`${p}-${i}`} className="border-zinc-700/50">
                            <TableCell className="font-mono text-xs text-zinc-300">
                              {p.easting.toFixed(3)}
                            </TableCell>
                            <TableCell className="font-mono text-xs text-zinc-300">
                              {p.northing.toFixed(3)}
                            </TableCell>
                            <TableCell className="font-mono text-xs text-zinc-300 text-right">
                              {p.existingRL.toFixed(3)}
                            </TableCell>
                            <TableCell className="font-mono text-xs text-zinc-300 text-right">
                              {p.designRL.toFixed(3)}
                            </TableCell>
                            <TableCell className={`font-mono text-xs text-right font-semibold ${p.difference > 0 ? 'text-amber-400' : p.difference < 0 ? 'text-blue-400' : 'text-zinc-400'}`}>
                              {p.difference > 0 ? '+' : ''}{p.difference.toFixed(3)}
                            </TableCell>
                            <TableCell>
                              <Badge
                                variant="outline"
                                className={`text-[10px] font-mono ${
                                  cls === 'Cut'
                                    ? 'border-amber-500/40 text-amber-400 bg-amber-500/10'
                                    : cls === 'Fill'
                                    ? 'border-blue-500/40 text-blue-400 bg-blue-500/10'
                                    : 'border-zinc-600 text-zinc-400'
                                }`}
                              >
                                {cls}
                              </Badge>
                            </TableCell>
                          </TableRow>
                        );
                      })}
                    </TableBody>
                  </Table>
                </CardContent>
              </Card>
            </>
          )}

          {!cutFillResult && !cutFillLoading && (
            <div className="flex flex-col items-center justify-center py-16 text-zinc-500">
              <svg viewBox="0 0 48 48" className="w-12 h-12 mb-3 opacity-40" fill="none" stroke="currentColor" strokeWidth="1.5">
                <rect x="8" y="12" width="32" height="24" rx="2" />
                <line x1="8" y1="24" x2="40" y2="24" strokeDasharray="4 2" />
                <path d="M8 24l6-6 4 4 4-8 6 10 14-10" strokeLinejoin="round" />
              </svg>
              <p className="text-sm">Enter a datum RL and run analysis to view cut/fill results</p>
            </div>
          )}
        </TabsContent>

        {/* ══════════════════════════════════════════════════════════════════ */}
        {/*  TAB 3: AREA COMPUTATION                                         */}
        {/* ══════════════════════════════════════════════════════════════════ */}
        <TabsContent value="area" className="space-y-6">
          <Card className="border-zinc-700 bg-zinc-800/50">
            <CardHeader>
              <CardTitle className="text-zinc-100 text-base">Polygon Points</CardTitle>
              <CardDescription className="text-zinc-400">
                Paste or import polygon vertices (Easting,Northing) — minimum 3 points
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex gap-3">
                <input
                  type="file"
                  accept=".csv,.txt"
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (!file) return;
                    const reader = new FileReader();
                    reader.onload = (ev) => setPolyText(ev.target?.result as string || '');
                    reader.readAsText(file);
                    e.target.value = '';
                  }}
                  className="hidden"
                  id="poly-file"
                />
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => document.getElementById('poly-file')?.click()}
                  className="border-zinc-600 text-zinc-300 hover:bg-zinc-700 hover:text-blue-400"
                >
                  Import Polygon CSV
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={handleAreaCompute}
                  disabled={!polyText.trim()}
                  className="border-zinc-600 text-zinc-300 hover:bg-zinc-700 hover:text-blue-400"
                >
                  Compute Area
                </Button>
              </div>
              <Textarea
                value={polyText}
                onChange={(e) => setPolyText(e.target.value)}
                placeholder="Easting,Northing&#10;100.0,100.0&#10;200.0,100.0&#10;200.0,200.0&#10;100.0,200.0"
                className="font-mono text-xs bg-zinc-900 border-zinc-600 text-zinc-300 min-h-[120px] max-h-[200px]"
              />
            </CardContent>
          </Card>

          {areaConversions && (
            <>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <SummaryCard label="Area" value={`${fmt(areaConversions.sqm, 2)} m²`} accent />
                <SummaryCard label="Area" value={`${fmt(areaConversions.hectares, 4)} ha`} accent />
                <SummaryCard label="Area" value={`${fmt(areaConversions.acres, 4)} acres`} accent />
              </div>

              <Card className="border-zinc-700 bg-zinc-800/50">
                <CardHeader>
                  <CardTitle className="text-zinc-100 text-sm">
                    Polygon Vertices ({polyPoints.length} points)
                  </CardTitle>
                </CardHeader>
                <CardContent className="max-h-60 overflow-y-auto">
                  <Table>
                    <TableHeader>
                      <TableRow className="border-zinc-700 hover:bg-transparent">
                        <TableHead className="text-zinc-400 text-xs w-12">#</TableHead>
                        <TableHead className="text-zinc-400 text-xs">Easting</TableHead>
                        <TableHead className="text-zinc-400 text-xs">Northing</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {polyPoints.map((p, i) => (
                        <TableRow key={`${p}-${i}`} className="border-zinc-700/50">
                          <TableCell className="font-mono text-xs text-zinc-500">{i + 1}</TableCell>
                          <TableCell className="font-mono text-xs text-zinc-300">{p.easting.toFixed(4)}</TableCell>
                          <TableCell className="font-mono text-xs text-zinc-300">{p.northing.toFixed(4)}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </CardContent>
              </Card>
            </>
          )}

          {!areaConversions && (
            <div className="flex flex-col items-center justify-center py-16 text-zinc-500">
              <svg viewBox="0 0 48 48" className="w-12 h-12 mb-3 opacity-40" fill="none" stroke="currentColor" strokeWidth="1.5">
                <polygon points="24,6 42,16 38,38 10,38 6,16" />
                <text x="24" y="26" textAnchor="middle" fontSize="10" fill="currentColor" stroke="none">m²</text>
              </svg>
              <p className="text-sm">Enter polygon points and compute area to see results</p>
            </div>
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
}

// ─── Sub-components ─────────────────────────────────────────────────────────

interface SummaryCardProps {
  label: string;
  value: string;
  accent?: boolean;
  valueColor?: string;
}

function SummaryCard({ label, value, accent, valueColor }: SummaryCardProps) {
  return (
    <Card className="border-zinc-700 bg-zinc-800/50">
      <CardContent className="p-4">
        <p className="text-[11px] uppercase tracking-wider text-zinc-500 mb-1">{label}</p>
        <p className={`text-lg font-bold font-mono ${valueColor || (accent ? 'text-blue-400' : 'text-zinc-200')}`}>
          {value}
        </p>
      </CardContent>
    </Card>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { AlertTriangle } from 'lucide-react'
import { superelevationCalc, type SuperelevationResult, logEngineeringCompute } from '@/lib/engineering/compute';
import { z } from 'zod';
import { initialiseDXFLayers, DXF_LAYERS, TitleBlockData, TITLE_BLOCK_TEMPLATES } from '@/lib/drawing/dxfLayers';

const SuperelevationInputSchema = z.object({
  R: z.number().positive().min(50).max(2000),
  V: z.number().positive().min(20).max(120),
  eMax: z.number().positive().max(0.12).default(0.07),
});

interface SuperelevationPanelProps {
  initialRadius?: number;
  initialSpeed?: number;
  projectId?: string;
  projectData?: {
    lr_number?: string;
    county?: string;
    district?: string;
    locality?: string;
  };
  surveyorProfile?: {
    fullName: string;
    registrationNumber: string;
    firmName: string;
  } | null;
  standard?: 'KRDM2017' | 'KeRRA';
}

export default function SuperelevationPanel({ 
  initialRadius = 200, 
  initialSpeed = 80,
  projectId,
  projectData,
  surveyorProfile,
  standard = 'KRDM2017'
}: SuperelevationPanelProps) {
  const [R, setR] = useState(initialRadius);
  const [V, setV] = useState(initialSpeed);
  const [eMax, setEmax] = useState(0.07);
  const [error, setError] = useState<string | null>(null);

  const eRequired = (V * V) / (225 * R);
  const ePercent = eRequired * 100;
  const minTransition = Math.max(0.6 * (V * V) / R, 30);

  const validations = useMemo(() => {
    const issues: string[] = [];
    const passes: string[] = [];

    if (ePercent > 12) {
      issues.push(`Required e ${ePercent.toFixed(1)}% exceeds absolute max 12%`);
    } else if (ePercent > 7) {
      issues.push(`Required e ${ePercent.toFixed(1)}% exceeds KeRRA rural max 7%`);
    } else {
      passes.push(`e ${ePercent.toFixed(1)}% within 7% limit `);
    }

    if (minTransition < 30) {
      issues.push(`Transition length ${minTransition.toFixed(1)}m < absolute minimum 30m`);
    } else {
      passes.push(`Transition length ${minTransition.toFixed(1)}m ≥ 30m minimum `);
    }

    if (standard === 'KeRRA' && ePercent > 7) {
      issues.push(`KeRRA rural roads: max e = 7%. Consider larger radius or lower speed.`);
    }

    return { issues, passes };
  }, [R, V, ePercent, minTransition, standard]);

  const result: SuperelevationResult | null = useMemo(() => {
    try {
      const input = SuperelevationInputSchema.parse({ R, V, eMax });
      setError(null);
      const res = superelevationCalc(input);
      
      logEngineeringCompute('superelevation', input, res, { projectId });
      
      return res;
    } catch (e) {
      if (e instanceof z.ZodError) {
        setError(e.errors[0]?.message || 'Invalid input');
      }
      return null;
    }
  }, [R, V, eMax, projectId]);

  const exportToDXF = async () => {
    if (!result) return;
    
    const { default: Drawing } = await import('dxf-writer');
    const drawing = new Drawing();
    initialiseDXFLayers(drawing);
    // Render title block via template system
    const tb: TitleBlockData = {
      drawingTitle: TITLE_BLOCK_TEMPLATES.eng_superelevation.drawingTitle,
      lrNumber: projectData?.lr_number ?? 'N/A',
      county: projectData?.county ?? 'N/A',
      district: projectData?.district ?? 'N/A',
      locality: projectData?.locality ?? 'N/A',
      areaHa: 0,
      perimeterM: 0,
      surveyorName: surveyorProfile?.fullName ?? 'N/A',
      registrationNumber: surveyorProfile?.registrationNumber ?? 'N/A',
      firmName: surveyorProfile?.firmName ?? 'N/A',
      date: new Date().toLocaleDateString('en-KE'),
      submissionRef: 'N/A',
      coordinateSystem: 'Arc 1960 / UTM Zone 37S (SRID: 21037)',
      scale: '1:2500',
      sheetNumber: '1 of 1',
      revision: 'R00'
    }
    // renderTitleBlock(drawing, 'eng_superelevation', tb);
    
    drawing.setActiveLayer(DXF_LAYERS.PROFILE.name);
    
    const width = 30;
    const e = result.eDesign / 100;
    const angleRad = Math.atan(e);
    const rise = width * Math.tan(angleRad);
    
    drawing.drawLine(0, 0, width, rise);
    drawing.drawLine(0, 0, width, 0);
    drawing.drawLine(width, rise, width, rise + 0.3);
    
    drawing.setActiveLayer(DXF_LAYERS.CHAIN.name);
    drawing.drawText(1, 0.5, 0.15, 0, `R=${R}m V=${V}km/h e=${result.eDesign.toFixed(1)}%`);
    drawing.drawText(1, 1.5, 0.15, 0, `Transition: ${result.transitionLength.toFixed(1)}m`);
    
    const dxfString = drawing.toDxfString();
    const blob = new Blob([dxfString], { type: 'application/dxf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `superelevation_R${R}_V${V}.dxf`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-start">
        <div>
          <h3 className="text-lg font-semibold text-[var(--text-primary)]">Superelevation Calculation</h3>
          <p className="text-sm text-[var(--text-muted)]">
            Per RDM 1.1 Section 3.4 and KeRRA Rural Roads Design Manual
          </p>
        </div>
        {result && (
          <button
            onClick={exportToDXF}
            className="bg-orange-500 hover:bg-orange-600 px-4 py-2 rounded-lg text-white text-sm font-medium flex items-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            Export DXF
          </button>
        )}
      </div>

      {error && (
        <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-sm">
          {error}
        </div>
      )}

      {validations.issues.length > 0 && (
        <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-lg">
          <p className="text-red-400 text-sm font-semibold mb-1">Standards Violations</p>
          <ul className="text-red-400 text-xs space-y-0.5">
            {validations.issues.map((issue, i) => (
              <li key={`${issue}-${i}`}><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> {issue}</li>
            ))}
          </ul>
        </div>
      )}

      {validations.passes.length > 0 && (
        <div className="p-3 bg-green-500/10 border border-green-500/30 rounded-lg">
          <ul className="text-green-400 text-xs space-y-0.5">
            {validations.passes.map((pass, i) => (
              <li key={`${pass}-${i}`}> {pass}</li>
            ))}
          </ul>
        </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="curve-radius-r-m">Curve Radius R (m)</label>
          <input id="curve-radius-r-m" aria-label="Curve Radius R (m)"
            type="number"
            min={30}
            max={2000}
            value={R}
            onChange={(e) => setR(Number(e.target.value) || 50)}
            className={`w-full bg-[var(--bg-secondary)] border rounded px-3 py-2 text-sm font-mono ${ePercent > 7 ? 'border-red-500 text-red-400' : 'border-[var(--border-color)]'}`}
          />
          <p className="text-xs text-[var(--text-muted)] mt-0.5">e required: {ePercent.toFixed(1)}%</p>
        </div>
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="design-speed-v-km-h">Design Speed V (km/h)</label>
          <input id="design-speed-v-km-h" aria-label="Design Speed V (km/h)"
            type="number"
            min={20}
            max={120}
            value={V}
            onChange={(e) => setV(Number(e.target.value) || 80)}
            className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-sm font-mono"
          />
        </div>
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="max-superelevation-e-max">Max Superelevation e<sub>max</sub></label>
          <select
             id="max-superelevation-e-max" value={eMax}
            onChange={(e) => setEmax(Number(e.target.value))}
            className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-sm font-mono"
          >
            <option value={0.04}>4%</option>
            <option value={0.05}>5%</option>
            <option value={0.06}>6%</option>
            <option value={0.07}>7% (KeRRA default)</option>
            <option value={0.08}>8%</option>
            <option value={0.10}>10%</option>
            <option value={0.12}>12%</option>
          </select>
          <p className="text-xs text-[var(--text-muted)] mt-0.5">Min transition: {minTransition.toFixed(1)}m</p>
        </div>
      </div>

      {/* Results Summary */}
      {result && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
            <p className="text-xs text-[var(--text-muted)]">Design e</p>
            <p className="font-mono font-semibold text-orange-400">{result.eDesign.toFixed(2)}%</p>
          </div>
          <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
            <p className="text-xs text-[var(--text-muted)]">Transition Length</p>
            <p className="font-mono font-semibold">{result.transitionLength.toFixed(1)} m</p>
          </div>
          <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
            <p className="text-xs text-[var(--text-muted)]">Rate</p>
            <p className="font-mono font-semibold">{result.rate.toFixed(4)}%/m</p>
          </div>
          <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
            <p className="text-xs text-[var(--text-muted)]">Max e</p>
            <p className="font-mono font-semibold">{result.eMax.toFixed(2)}%</p>
          </div>
        </div>
      )}

      {/* Transition Table */}
      {result && (
        <div>
          <h4 className="font-semibold mb-2 text-sm">Superelevation Transition Table</h4>
          <div className="overflow-x-auto">
            <table className="w-full text-sm font-mono">
              <thead>
                <tr className="border-b border-[var(--border-color)] text-[var(--text-muted)] text-xs">
                  <th className="text-left py-2 pr-4">Offset (m)</th>
                  <th className="text-left py-2 pr-4">e Applied (%)</th>
                  <th className="text-left py-2">Progress</th>
                </tr>
              </thead>
              <tbody>
                {result.table.map((row, i) => (
                  <tr key={`${row}-${i}`} className="border-b border-[var(--border-color)]/30">
                    <td className="py-1.5 pr-4">{row.chainageOffset.toFixed(2)}</td>
                    <td className="py-1.5 pr-4">{row.eApplied.toFixed(2)}</td>
                    <td className="py-1.5">
                      <div className="w-24 h-2 bg-[var(--bg-secondary)] rounded-full overflow-hidden">
                        <div 
                          className="h-full bg-orange-500 transition-all" 
                          style={{ width: `${(i / result.table.length) * 100}%` }}
                        />
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Visual Diagram - Simple SVG representation */}
      {result && (
        <div className="mt-4">
          <h4 className="font-semibold mb-2 text-sm">Transition Diagram</h4>
          <svg viewBox="0 0 400 120" className="w-full h-32 bg-[var(--bg-secondary)] rounded-lg">
            {/* Center line */}
            <line x1="20" y1="60" x2="380" y2="60" stroke="#444" strokeWidth="1" strokeDasharray="4 2" />
            
            {/* Normal crown (before transition) */}
            <line x1="20" y1="50" x2="60" y2="50" stroke="#666" strokeWidth="3" />
            
            {/* Transition curve */}
            <path 
              d={`M 60 50 Q ${60 + result.transitionLength * 0.5} 30 ${Math.min(60 + result.transitionLength, 380)} 30`}
              stroke="#e8a020"
              strokeWidth="3"
              fill="none"
            />
            
            {/* Full superelevation (after transition) */}
            <line 
              x1={Math.min(60 + result.transitionLength, 380)} 
              y1="30" 
              x2="380" 
              y2="30" 
              stroke="#e8a020" 
              strokeWidth="3" 
            />

            {/* Labels */}
            <text x="40" y="75" fill="#666" fontSize="10">Normal Crown</text>
            <text x="140" y="25" fill="#e8a020" fontSize="10">Transition</text>
            <text x="300" y="25" fill="#e8a020" fontSize="10">Full e = {result.eDesign}%</text>
          </svg>
        </div>
      )}

      {/* Formula Reference */}
      <div className="mt-4 p-3 bg-[var(--bg-secondary)] rounded-lg">
        <p className="text-xs text-[var(--text-muted)]">
          <strong>Reference:</strong> RDM 1.1 Equation 3.1 — e = V²/(225R) - 0.01
        </p>
        <p className="text-xs text-[var(--text-muted)] mt-1">
          <strong>KeRRA:</strong> Minimum transition L = 0.6V²/R (minimum 30m)
        </p>
      </div>
    </div>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { z } from 'zod';
import { crossSectionVolume, massHaulDiagram, logEngineeringCompute } from '@/lib/engineering/compute';
import { initialiseSokDXFLayers, DXF_LAYERS, TitleBlockData, TITLE_BLOCK_TEMPLATES } from '@/lib/drawing/dxfLayers';

const VolumeInputSchema = z.object({
  areas: z.array(z.number()).min(2),
  stationInterval: z.number().positive().max(100).default(20),
  method: z.enum(['prismoidal', 'end-area']).default('prismoidal'),
});

interface MassHaulPoint {
  station: number;
  volume: number;
  cumulative: number;
  zone: 'cut' | 'fill' | 'balance';
}

function MassHaulDiagramSVG({ diagram, balancePoint }: { diagram: MassHaulPoint[]; balancePoint: number | null }) {
  const padding = { top: 30, right: 40, bottom: 50, left: 70 };
  const chartW = Math.max(diagram.length * 60, 600);
  const chartH = 320;
  const totalW = chartW + padding.left + padding.right;
  const totalH = chartH + padding.top + padding.bottom;

  const stations = diagram.map(d => d.station);
  const cumulatives = diagram.map(d => d.cumulative);
  const minStation = Math.min(...stations);
  const maxStation = Math.max(...stations);
  const minCum = Math.min(...cumulatives, 0);
  const maxCum = Math.max(...cumulatives, 0);
  const rangeX = maxStation - minStation || 1;
  const rangeY = maxCum - minCum || 1;

  const scaleX = (v: number) => padding.left + ((v - minStation) / rangeX) * chartW;
  const scaleY = (v: number) => padding.top + chartH - ((v - minCum) / rangeY) * chartH;
  const zeroY = scaleY(0);

  // Build polyline points
  const linePoints = diagram.map(d => `${scaleX(d.station)},${scaleY(d.cumulative)}`).join(' ');

  // Build filled polygons: surplus (green above zero) and deficit (red below zero)
  const surplusParts: string[] = [];
  const deficitParts: string[] = [];

  for (let i = 0; i < diagram.length - 1; i++) {
    const d0 = diagram[i];
    const d1 = diagram[i + 1];
    const x0 = scaleX(d0.station);
    const x1 = scaleX(d1.station);
    const y0 = scaleY(d0.cumulative);
    const y1 = scaleY(d1.cumulative);

    if (d0.cumulative >= 0 && d1.cumulative >= 0) {
      // Both above zero
      surplusParts.push(`M${x0},${zeroY} L${x0},${y0} L${x1},${y1} L${x1},${zeroY} Z`);
    } else if (d0.cumulative <= 0 && d1.cumulative <= 0) {
      // Both below zero
      deficitParts.push(`M${x0},${zeroY} L${x0},${y0} L${x1},${y1} L${x1},${zeroY} Z`);
    } else {
      // Crosses zero — interpolate crossing point
      const t = Math.abs(d0.cumulative) / (Math.abs(d0.cumulative) + Math.abs(d1.cumulative));
      const crossX = x0 + t * (x1 - x0);

      if (d0.cumulative > 0) {
        surplusParts.push(`M${x0},${zeroY} L${x0},${y0} L${crossX},${zeroY} Z`);
        deficitParts.push(`M${crossX},${zeroY} L${crossX},${zeroY} L${x1},${y1} L${x1},${zeroY} Z`);
      } else {
        deficitParts.push(`M${x0},${zeroY} L${x0},${y0} L${crossX},${zeroY} Z`);
        surplusParts.push(`M${crossX},${zeroY} L${crossX},${zeroY} L${x1},${y1} L${x1},${zeroY} Z`);
      }
    }
  }

  // Grid lines
  const gridLines: { x?: number; y?: number; label: string; axis: 'x' | 'y' }[] = [];
  const numXGrid = Math.min(diagram.length, 10);
  for (let i = 0; i <= numXGrid; i++) {
    const val = minStation + (rangeX * i) / numXGrid;
    gridLines.push({ x: scaleX(val), label: val.toFixed(0), axis: 'x' });
  }
  const numYGrid = 6;
  for (let i = 0; i <= numYGrid; i++) {
    const val = minCum + (rangeY * i) / numYGrid;
    gridLines.push({ y: scaleY(val), label: val.toFixed(0), axis: 'y' });
  }

  return (
    <div className="border border-[var(--border-color)] rounded-lg overflow-hidden">
      <div className="bg-[var(--bg-secondary)] px-4 py-2 border-b border-[var(--border-color)]">
        <h4 className="font-semibold text-sm flex items-center gap-2">
          Mass Haul Diagram
          <span className="flex items-center gap-1 ml-3 text-xs font-normal text-[var(--text-muted)]">
            <span className="inline-block w-3 h-2 bg-green-500/40 rounded-sm border border-green-500/60" />
            Surplus (Cut)
          </span>
          <span className="flex items-center gap-1 text-xs font-normal text-[var(--text-muted)]">
            <span className="inline-block w-3 h-2 bg-red-500/40 rounded-sm border border-red-500/60" />
            Deficit (Fill)
          </span>
        </h4>
      </div>
      <div className="bg-white p-2" style={{ maxHeight: 400 }}>
        <svg
          viewBox={`0 0 ${totalW} ${totalH}`}
          className="w-full h-auto"
          style={{ maxHeight: 380 }}
          preserveAspectRatio="xMidYMid meet"
        >
          <defs>
            <pattern id="mhd-grid" width="40" height="40" patternUnits="userSpaceOnUse">
              <path d="M 40 0 L 0 0 0 40" fill="none" stroke="#e5e7eb" strokeWidth="0.5" />
            </pattern>
          </defs>

          {/* Background grid */}
          <rect x={padding.left} y={padding.top} width={chartW} height={chartH} fill="url(#mhd-grid)" />

          {/* Zero line */}
          <line
            x1={padding.left} y1={zeroY} x2={padding.left + chartW} y2={zeroY}
            stroke="#374151" strokeWidth="1.5" strokeDasharray="6 3"
          />

          {/* Surplus fill (green) */}
          {surplusParts.map((d, i) => (
            <path key={`surplus-${i}`} d={d} fill="rgba(34,197,94,0.2)" stroke="rgba(34,197,94,0.4)" strokeWidth="0.5" />
          ))}

          {/* Deficit fill (red) */}
          {deficitParts.map((d, i) => (
            <path key={`deficit-${i}`} d={d} fill="rgba(239,68,68,0.2)" stroke="rgba(239,68,68,0.4)" strokeWidth="0.5" />
          ))}

          {/* Cumulative volume line */}
          <polyline points={linePoints} fill="none" stroke="#1f2937" strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" />

          {/* Data points */}
          {diagram.map((d, i) => (
            <circle
              key={d.station}
              cx={scaleX(d.station)} cy={scaleY(d.cumulative)}
              r="3"
              fill={d.cumulative >= 0 ? '#16a34a' : '#dc2626'}
              stroke="white" strokeWidth="1.5"
            />
          ))}

          {/* Balance point marker */}
          {balancePoint !== null && (
            <line
              x1={scaleX(balancePoint)} y1={padding.top}
              x2={scaleX(balancePoint)} y2={padding.top + chartH}
              stroke="#d97706" strokeWidth="2" strokeDasharray="8 4"
            />
          )}
          {balancePoint !== null && (
            <text
              x={scaleX(balancePoint)} y={padding.top - 8}
              textAnchor="middle"
              className="text-[10px]"
              fill="#d97706" fontWeight="600"
            >
              Balance @{balancePoint.toFixed(0)}m
            </text>
          )}

          {/* X axis labels */}
          {gridLines.filter(g => g.axis === 'x').map((g, i) => (
            <text key={`xl-${i}`} x={g.x} y={totalH - 8} textAnchor="middle" className="text-[10px]" fill="#6b7280">
              {g.label}m
            </text>
          ))}

          {/* Y axis labels */}
          {gridLines.filter(g => g.axis === 'y').map((g, i) => (
            <g key={`yl-${i}`}>
              <line
                x1={padding.left} y1={g.y} x2={padding.left + chartW} y2={g.y}
                stroke="#e5e7eb" strokeWidth="0.5" strokeDasharray="2 4"
              />
              <text x={padding.left - 8} y={(g.y ?? 0) + 3} textAnchor="end" className="text-[10px]" fill="#6b7280">
                {g.label}
              </text>
            </g>
          ))}

          {/* Axis titles */}
          <text x={totalW / 2} y={totalH - 0} textAnchor="middle" className="text-[11px]" fill="#374151" fontWeight="500">
            Chainage (m)
          </text>
          <text
            x={12} y={padding.top + chartH / 2}
            textAnchor="middle"
            className="text-[11px]"
            fill="#374151"
            fontWeight="500"
            transform={`rotate(-90, 12, ${padding.top + chartH / 2})`}
          >
            Cumulative Volume (m³)
          </text>
        </svg>
      </div>
    </div>
  );
}

interface VolumesPanelProps {
  projectId?: string;
  projectData?: {
    lr_number?: string;
    county?: string;
    district?: string;
    locality?: string;
  };
  surveyorProfile?: {
    fullName: string;
    registrationNumber: string;
    firmName: string;
  } | null;
}

export function VolumesPanel({ projectId, projectData, surveyorProfile }: VolumesPanelProps) {
  const [areas, setAreas] = useState<number[]>([5, 8, 12, 15, 10, 5, 3, -2, -5, -3]);
  const [stationInterval, setStationInterval] = useState(20);
  const [method, setMethod] = useState<'prismoidal' | 'end-area'>('prismoidal');
  const [error, setError] = useState<string | null>(null);

  const result = useMemo(() => {
    try {
      const input = VolumeInputSchema.parse({ areas, stationInterval, method });
      setError(null);
      const res = crossSectionVolume(input);
      logEngineeringCompute('cross_section_volume', input, res, { projectId });
      return res;
    } catch (e) {
      if (e instanceof z.ZodError) {
        setError(e.errors[0]?.message);
      }
      return null;
    }
  }, [areas, stationInterval, method, projectId]);

  const massHaul = useMemo(() => {
    if (!result) return null;
    const cumulative = areas.map((a, i) => {
      let sum = 0;
      for (let j = 0; j <= i; j++) sum += areas[j];
      return sum;
    });
    return massHaulDiagram({ cumulativeVolumes: cumulative, stationInterval });
  }, [areas, stationInterval, result]);

  const updateArea = (index: number, value: number) => {
    const newAreas = [...areas];
    newAreas[index] = value;
    setAreas(newAreas);
  };

  const exportDXF = async () => {
    if (!result) return;

    const { default: Drawing } = await import('dxf-writer');
    const drawing = new Drawing();
    initialiseSokDXFLayers(drawing);

    const tb: TitleBlockData = {
      drawingTitle: TITLE_BLOCK_TEMPLATES.eng_volumes.drawingTitle,
      lrNumber: projectData?.lr_number ?? 'N/A',
      county: projectData?.county ?? 'N/A',
      district: projectData?.district ?? 'N/A',
      locality: projectData?.locality ?? 'N/A',
      areaHa: 0,
      perimeterM: 0,
      surveyorName: surveyorProfile?.fullName ?? 'N/A',
      registrationNumber: surveyorProfile?.registrationNumber ?? 'N/A',
      firmName: surveyorProfile?.firmName ?? 'N/A',
      date: new Date().toLocaleDateString('en-KE'),
      submissionRef: 'N/A',
      coordinateSystem: 'Arc 1960 / UTM Zone 37S (SRID: 21037)',
      scale: '1:2500',
      sheetNumber: '1 of 1',
      revision: 'R00'
    }
    // renderTitleBlock(drawing, 'eng_volumes', tb)

    const baseY = 100;
    const scale = 2;

    drawing.setActiveLayer(DXF_LAYERS.PROFILE.name);
    
    let prevX = 50;
    let prevY = baseY;
    
    areas.forEach((area, i) => {
      const x = 50 + i * 20 * scale;
      const y = baseY - area * scale;
      drawing.drawLine(prevX, prevY, x, y);
      prevX = x;
      prevY = y;
    });

    drawing.setActiveLayer(DXF_LAYERS.CHAIN.name);
    drawing.drawText(50, baseY + 30, 0.2, 0, `Total Cut: ${result.totalCut.toFixed(2)} m³`);
    drawing.drawText(50, baseY + 50, 0.2, 0, `Total Fill: ${result.totalFill.toFixed(2)} m³`);

    const dxfString = drawing.toDxfString();
    const blob = new Blob([dxfString], { type: 'application/dxf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `volumes_${projectId || 'export'}.dxf`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-start">
        <div>
          <h3 className="text-lg font-semibold text-[var(--text-primary)]">Cross-Section Volumes & Mass Haul</h3>
          <p className="text-sm text-[var(--text-muted)]">
            Per RDM 1.1 Volume 3, Chapter 2 — Earthworks
          </p>
        </div>
        {result && (
          <button
            onClick={exportDXF}
            className="bg-orange-500 hover:bg-orange-600 px-4 py-2 rounded-lg text-white text-sm font-medium flex items-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            Export DXF
          </button>
        )}
      </div>

      {error && (
        <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-sm">
          {error}
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="station-interval-m">Station Interval (m)</label>
          <input id="station-interval-m" aria-label="Station Interval (m)"
            type="number"
            min={5}
            max={100}
            value={stationInterval}
            onChange={(e) => setStationInterval(Number(e.target.value) || 20)}
            className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-sm font-mono"
          />
        </div>
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="method">Method</label>
          <select
             id="method" value={method}
            onChange={(e) => setMethod(e.target.value as 'prismoidal' | 'end-area')}
            className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-sm"
          >
            <option value="prismoidal">Prismoidal (RDM 1.1 preferred)</option>
            <option value="end-area">End-Area (simple)</option>
          </select>
        </div>
      </div>

      <div className="overflow-x-auto border border-[var(--border-color)] rounded-lg">
        <div className="bg-[var(--bg-secondary)] px-4 py-2 border-b border-[var(--border-color)]">
          <h4 className="font-semibold text-sm">Cross-Section Areas (positive = cut, negative = fill)</h4>
        </div>
        <div className="p-4">
          <div className="flex flex-wrap gap-2">
            {areas.map((area, i) => (
              <div key={`${area}-${i}`} className="flex items-center gap-1">
                <span className="text-xs text-[var(--text-muted)] w-8">{i * stationInterval}</span>
                <input aria-label="Area"
                  type="number"
                  value={area}
                  onChange={(e) => updateArea(i, Number(e.target.value) || 0)}
                  className={`w-16 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded px-2 py-1 text-sm font-mono text-right ${area > 0 ? 'text-red-400' : 'text-green-400'}`}
                />
              </div>
            ))}
          </div>
        </div>
      </div>

      {result && (
        <>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Total Cut</p>
              <p className="font-mono font-semibold text-red-400">{result.totalCut.toFixed(2)} m³</p>
            </div>
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Total Fill</p>
              <p className="font-mono font-semibold text-green-400">{result.totalFill.toFixed(2)} m³</p>
            </div>
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Net Volume</p>
              <p className={`font-mono font-semibold ${result.netVolume >= 0 ? 'text-red-400' : 'text-green-400'}`}>
                {result.netVolume.toFixed(2)} m³
              </p>
            </div>
            <div className="bg-[var(--bg-secondary)] rounded-lg p-3">
              <p className="text-xs text-[var(--text-muted)]">Balanced?</p>
              <p className={`font-mono font-semibold ${result.isBalanced ? 'text-green-400' : 'text-yellow-400'}`}>
                {result.isBalanced ? 'Yes' : 'No'}
              </p>
            </div>
          </div>

          {massHaul && (
            <div className="overflow-x-auto border border-[var(--border-color)] rounded-lg">
              <div className="bg-[var(--bg-secondary)] px-4 py-2 border-b border-[var(--border-color)]">
                <h4 className="font-semibold text-sm">Volume Table</h4>
              </div>
              <table className="w-full text-sm font-mono">
                <thead>
                  <tr className="border-b border-[var(--border-color)] text-[var(--text-muted)] text-xs">
                    <th className="text-left py-2 px-4">Station</th>
                    <th className="text-right py-2 px-4">Cut Area</th>
                    <th className="text-right py-2 px-4">Fill Area</th>
                    <th className="text-right py-2 px-4">Cut Vol</th>
                    <th className="text-right py-2 px-4">Fill Vol</th>
                    <th className="text-right py-2 px-4">Cum. Cut</th>
                    <th className="text-right py-2 px-4">Cum. Fill</th>
                  </tr>
                </thead>
                <tbody>
                  {result.volumeTable.slice(0, 15).map((row, i) => (
                    <tr key={row.station} className="border-b border-[var(--border-color)]/30">
                      <td className="py-1.5 px-4">{row.station.toFixed(0)}</td>
                      <td className="py-1.5 px-4 text-right text-red-400">{row.cutArea.toFixed(2)}</td>
                      <td className="py-1.5 px-4 text-right text-green-400">{row.fillArea.toFixed(2)}</td>
                      <td className="py-1.5 px-4 text-right">{row.cutVolume.toFixed(2)}</td>
                      <td className="py-1.5 px-4 text-right">{row.fillVolume.toFixed(2)}</td>
                      <td className="py-1.5 px-4 text-right text-red-400">{row.cumulativeCut.toFixed(2)}</td>
                      <td className="py-1.5 px-4 text-right text-green-400">{row.cumulativeFill.toFixed(2)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}

      {massHaul && massHaul.diagram.length > 0 && (
        <MassHaulDiagramSVG diagram={massHaul.diagram} balancePoint={massHaul.balancePoint} />
      )}

      <div className="text-xs text-[var(--text-muted)]">
        <p><strong>Reference:</strong> RDM 1.1 Volume 3 — Prismoidal: V = (d/6)(A₁ + 4Am + A₂)</p>
      </div>
    </div>
  );
}

'use client'

/**
 * EquipmentManager — Track survey equipment with calibration status
 *
 * Features:
 * - List equipment with current calibration status (current/expiring/overdue/never)
 * - Add new equipment
 * - View calibration history per item
 * - Add calibration record
 * - Visual alerts for expiring/overdue calibrations
 * - Per Survey Act: total stations need annual calibration
 */

import { useState, useCallback, useEffect } from 'react'
import {
  Wrench, Plus, Loader2, AlertTriangle, CheckCircle2, Clock,
  Calendar, X, ChevronDown, ChevronUp, Trash2,
} from 'lucide-react'

interface Equipment {
  id: string
  name: string
  type: string
  manufacturer?: string | null
  model?: string | null
  serial_number?: string | null
  status: string
  notes?: string | null
  last_calibrated?: string | null
  next_calibration?: string | null
  calibration_status?: string
  days_until_expiry?: number | null
}

interface Calibration {
  id: string
  calibration_date: string
  next_calibration_date: string
  calibrated_by?: string | null
  calibration_lab?: string | null
  certificate_number?: string | null
  results: string
  notes?: string | null
}

const TYPE_LABELS: Record<string, string> = {
  total_station: 'Total Station',
  gnss_rover: 'GNSS Rover',
  gnss_base: 'GNSS Base',
  auto_level: 'Auto Level',
  digital_level: 'Digital Level',
  theodolite: 'Theodolite',
  eddm: 'EDM',
  other: 'Other',
}

const CAL_STATUS_CONFIG: Record<string, { color: string; bg: string; border: string; icon: typeof CheckCircle2; label: string }> = {
  current: { color: 'text-emerald-400', bg: 'bg-emerald-500/10', border: 'border-emerald-500/30', icon: CheckCircle2, label: 'Current' },
  expiring: { color: 'text-amber-400', bg: 'bg-amber-500/10', border: 'border-amber-500/30', icon: Clock, label: 'Expiring Soon' },
  overdue: { color: 'text-red-400', bg: 'bg-red-500/10', border: 'border-red-500/30', icon: AlertTriangle, label: 'Overdue' },
  never: { color: 'text-gray-400', bg: 'bg-gray-500/10', border: 'border-gray-500/30', icon: Clock, label: 'Never Calibrated' },
}

export function EquipmentManager() {
  const [equipment, setEquipment] = useState<Equipment[]>([])
  const [loading, setLoading] = useState(true)
  const [showAddForm, setShowAddForm] = useState(false)
  const [expandedId, setExpandedId] = useState<string | null>(null)
  const [calibrations, setCalibrations] = useState<Calibration[]>([])
  const [loadingCal, setLoadingCal] = useState(false)
  const [showCalForm, setShowCalForm] = useState(false)

  const fetchEquipment = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/equipment?include_calibration=true')
      if (!res.ok) return
      const data = (await res.json()) as { data?: { equipment: Equipment[] } }
      setEquipment(data.data?.equipment || [])
    } catch {} finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    fetchEquipment()
  }, [fetchEquipment])

  const handleExpand = useCallback(async (equipId: string) => {
    if (expandedId === equipId) {
      setExpandedId(null)
      return
    }
    setExpandedId(equipId)
    setShowCalForm(false)
    setLoadingCal(true)
    try {
      const res = await fetch(`/api/equipment/${equipId}/calibration`)
      if (res.ok) {
        const data = (await res.json()) as { data?: { calibrations: Calibration[] } }
        setCalibrations(data.data?.calibrations || [])
      }
    } catch {} finally {
      setLoadingCal(false)
    }
  }, [expandedId])

  const handleDelete = useCallback(async (id: string, e: React.MouseEvent) => {
    e.stopPropagation()
    if (!confirm('Delete this equipment and all calibration records?')) return
    try {
      await fetch(`/api/equipment?id=${id}`, { method: 'DELETE' })
      setEquipment(prev => prev.filter(e => e.id !== id))
    } catch {}
  }, [])

  // Summary stats
  const stats = {
    total: equipment.length,
    current: equipment.filter(e => e.calibration_status === 'current').length,
    expiring: equipment.filter(e => e.calibration_status === 'expiring').length,
    overdue: equipment.filter(e => e.calibration_status === 'overdue').length,
    never: equipment.filter(e => e.calibration_status === 'never').length,
  }

  return (
    <div className="space-y-4">
      {/* Header + Summary */}
      <div className="card p-4">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
              <Wrench className="w-4 h-4 text-[var(--accent)]" />
            </div>
            <div>
              <h2 className="text-sm font-semibold text-[var(--text-primary)]">Equipment & Calibration</h2>
              <p className="text-[10px] text-gray-500">Track calibration dates per Survey Act Cap 299</p>
            </div>
          </div>
          <button
            onClick={() => setShowAddForm(!showAddForm)}
            className="flex items-center gap-1.5 px-3 h-8 rounded-lg bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)] text-xs font-medium hover:bg-[var(--accent)]/20"
          >
            <Plus className="w-3.5 h-3.5" />
            Add Equipment
          </button>
        </div>

        {/* Summary stats */}
        <div className="grid grid-cols-4 gap-2">
          <StatCard label="Total" value={stats.total} color="text-gray-300" bg="bg-white/[0.04]" />
          <StatCard label="Current" value={stats.current} color="text-emerald-400" bg="bg-emerald-500/10" />
          <StatCard label="Expiring" value={stats.expiring} color="text-amber-400" bg="bg-amber-500/10" />
          <StatCard label="Overdue" value={stats.overdue} color="text-red-400" bg="bg-red-500/10" />
        </div>
      </div>

      {/* Add form */}
      {showAddForm && (
        <AddEquipmentForm
          onClose={() => setShowAddForm(false)}
          onAdded={() => { setShowAddForm(false); fetchEquipment() }}
        />
      )}

      {/* Equipment list */}
      {loading ? (
        <div className="flex items-center justify-center py-8">
          <Loader2 className="w-6 h-6 text-gray-500 animate-spin" />
        </div>
      ) : equipment.length === 0 ? (
        <div className="card p-8 flex flex-col items-center justify-center text-center">
          <Wrench className="w-8 h-8 text-gray-600 mb-2" />
          <p className="text-sm text-gray-500">No equipment registered</p>
          <p className="text-[10px] text-gray-600 mt-1">
            Add your total station, GNSS rover, or level to track calibration dates.
          </p>
        </div>
      ) : (
        <div className="space-y-2">
          {equipment.map(equip => {
            const calStatus = equip.calibration_status || 'never'
            const cfg = CAL_STATUS_CONFIG[calStatus] || CAL_STATUS_CONFIG.never
            const StatusIcon = cfg.icon
            const isExpanded = expandedId === equip.id

            return (
              <div key={equip.id} className="card overflow-hidden">
                {/* Equipment row */}
                <div
                  onClick={() => handleExpand(equip.id)}
                  className="flex items-start gap-3 p-4 cursor-pointer hover:bg-white/[0.02] transition-colors"
                >
                  <div className={`shrink-0 w-10 h-10 rounded-lg flex items-center justify-center ${cfg.bg} ${cfg.border} border`}>
                    <StatusIcon className={`w-4 h-4 ${cfg.color}`} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className="text-sm font-medium text-[var(--text-primary)]">{equip.name}</span>
                      <span className="text-[9px] px-1.5 py-0.5 rounded bg-white/[0.04] text-gray-400 uppercase">
                        {TYPE_LABELS[equip.type] || equip.type}
                      </span>
                    </div>
                    <div className="text-[10px] text-gray-500 mt-0.5">
                      {equip.manufacturer} {equip.model}
                      {equip.serial_number && ` (S/N: ${equip.serial_number})`}
                    </div>
                    <div className="flex items-center gap-3 mt-1">
                      <span className={`text-[10px] font-medium ${cfg.color}`}>{cfg.label}</span>
                      {equip.days_until_expiry != null && equip.days_until_expiry >= 0 && (
                        <span className="text-[10px] text-gray-600 flex items-center gap-0.5">
                          <Calendar className="w-2.5 h-2.5" />
                          {equip.days_until_expiry} days left
                        </span>
                      )}
                      {equip.days_until_expiry != null && equip.days_until_expiry < 0 && (
                        <span className="text-[10px] text-red-400 flex items-center gap-0.5">
                          <AlertTriangle className="w-2.5 h-2.5" />
                          {Math.abs(equip.days_until_expiry)} days overdue
                        </span>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center gap-1">
                    <button
                      onClick={(e) => handleDelete(equip.id, e)}
                      className="w-7 h-7 flex items-center justify-center rounded text-gray-500 hover:text-red-400"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                    {isExpanded ? <ChevronUp className="w-4 h-4 text-gray-500" /> : <ChevronDown className="w-4 h-4 text-gray-500" />}
                  </div>
                </div>

                {/* Expanded calibration history */}
                {isExpanded && (
                  <div className="border-t border-[var(--border-color)] p-4 bg-[var(--bg-tertiary)]/30">
                    <div className="flex items-center justify-between mb-3">
                      <span className="text-xs font-semibold text-[var(--text-primary)]">Calibration History</span>
                      <button
                        onClick={() => setShowCalForm(!showCalForm)}
                        className="flex items-center gap-1 px-2 h-7 rounded bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)] text-[10px] font-medium"
                      >
                        <Plus className="w-3 h-3" />
                        Add Calibration
                      </button>
                    </div>

                    {showCalForm && (
                      <AddCalibrationForm
                        equipmentId={equip.id}
                        onClose={() => setShowCalForm(false)}
                        onAdded={() => {
                          setShowCalForm(false)
                          handleExpand(equip.id)
                          fetchEquipment()
                        }}
                      />
                    )}

                    {loadingCal ? (
                      <div className="flex justify-center py-4">
                        <Loader2 className="w-5 h-5 text-gray-500 animate-spin" />
                      </div>
                    ) : calibrations.length === 0 ? (
                      <p className="text-xs text-gray-500 text-center py-4">No calibration records yet</p>
                    ) : (
                      <div className="space-y-2">
                        {calibrations.map(cal => (
                          <div key={cal.id} className="flex items-start gap-3 p-2.5 rounded-lg bg-white/[0.02] border border-[var(--border-color)]">
                            <div className={`shrink-0 w-7 h-7 rounded flex items-center justify-center ${
                              cal.results === 'pass' ? 'bg-emerald-500/10' : 'bg-red-500/10'
                            }`}>
                              {cal.results === 'pass' ? (
                                <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />
                              ) : (
                                <AlertTriangle className="w-3.5 h-3.5 text-red-400" />
                              )}
                            </div>
                            <div className="flex-1 min-w-0">
                              <div className="text-xs text-[var(--text-primary)]">
                                {new Date(cal.calibration_date).toLocaleDateString('en-KE', { year: 'numeric', month: 'short', day: 'numeric' })}
                                <span className="text-gray-500 ml-2">→ expires {new Date(cal.next_calibration_date).toLocaleDateString('en-KE', { year: 'numeric', month: 'short', day: 'numeric' })}</span>
                              </div>
                              {cal.calibration_lab && (
                                <div className="text-[10px] text-gray-500 mt-0.5">Lab: {cal.calibration_lab}</div>
                              )}
                              {cal.certificate_number && (
                                <div className="text-[10px] text-gray-500 font-mono">Cert: {cal.certificate_number}</div>
                              )}
                              {cal.notes && (
                                <div className="text-[10px] text-gray-600 mt-0.5">{cal.notes}</div>
                              )}
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                )}
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

function StatCard({ label, value, color, bg }: { label: string; value: number; color: string; bg: string }) {
  return (
    <div className={`p-2 rounded-lg ${bg} border border-white/[0.04] text-center`}>
      <div className={`text-lg font-bold ${color}`}>{value}</div>
      <div className="text-[9px] text-gray-500 uppercase tracking-wider">{label}</div>
    </div>
  )
}

function AddEquipmentForm({ onClose, onAdded }: { onClose: () => void; onAdded: () => void }) {
  const [name, setName] = useState('')
  const [type, setType] = useState('total_station')
  const [manufacturer, setManufacturer] = useState('')
  const [model, setModel] = useState('')
  const [serialNumber, setSerialNumber] = useState('')
  const [notes, setNotes] = useState('')
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const handleSave = useCallback(async () => {
    setSaving(true)
    setError(null)
    try {
      const res = await fetch('/api/equipment', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, type, manufacturer, model, serialNumber, notes }),
      })
      if (!res.ok) {
        const data = (await res.json()) as { error?: string }
        throw new Error(data.error || 'Failed')
      }
      onAdded()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed')
    } finally {
      setSaving(false)
    }
  }, [name, type, manufacturer, model, serialNumber, notes, onAdded])

  return (
    <div className="card p-4 space-y-3">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-semibold text-[var(--text-primary)]">Add Equipment</h3>
        <button onClick={onClose} className="w-7 h-7 flex items-center justify-center rounded text-gray-400 hover:text-white">
          <X className="w-4 h-4" />
        </button>
      </div>
      <div className="grid grid-cols-2 gap-2">
        <div>
          <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="name">Name</label>
          <input id="name" type="text" value={name} onChange={e => setName(e.target.value)} placeholder="Leica TS07" className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none" />
        </div>
        <div>
          <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="type">Type</label>
          <select id="type" value={type} onChange={e => setType(e.target.value)} className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)]">
            {Object.entries(TYPE_LABELS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
          </select>
        </div>
      </div>
      <div className="grid grid-cols-3 gap-2">
        <input type="text" value={manufacturer} onChange={e => setManufacturer(e.target.value)} placeholder="Manufacturer" className="h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none" />
        <input type="text" value={model} onChange={e => setModel(e.target.value)} placeholder="Model" className="h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none" />
        <input type="text" value={serialNumber} onChange={e => setSerialNumber(e.target.value)} placeholder="Serial No." className="h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none" />
      </div>
      {error && <p className="text-xs text-red-400">{error}</p>}
      <div className="flex gap-2">
        <button onClick={onClose} className="flex-1 h-9 rounded-lg bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-xs text-gray-400 hover:text-gray-200">Cancel</button>
        <button onClick={handleSave} disabled={saving || !name} className="flex-1 h-9 rounded-lg bg-[var(--accent)] text-black text-xs font-semibold hover:bg-[var(--accent-dim)] disabled:opacity-40">
          {saving ? 'Saving...' : 'Add Equipment'}
        </button>
      </div>
    </div>
  )
}

function AddCalibrationForm({ equipmentId, onClose, onAdded }: { equipmentId: string; onClose: () => void; onAdded: () => void }) {
  const [calDate, setCalDate] = useState(new Date().toISOString().split('T')[0])
  const [nextDate, setNextDate] = useState(new Date(Date.now() + 365 * 86400000).toISOString().split('T')[0])
  const [lab, setLab] = useState('')
  const [certNumber, setCertNumber] = useState('')
  const [results, setResults] = useState('pass')
  const [notes, setNotes] = useState('')
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const handleSave = useCallback(async () => {
    setSaving(true)
    setError(null)
    try {
      const res = await fetch(`/api/equipment/${equipmentId}/calibration`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          calibrationDate: calDate, nextCalibrationDate: nextDate,
          calibrationLab: lab, certificateNumber: certNumber,
          results, notes,
        }),
      })
      if (!res.ok) {
        const data = (await res.json()) as { error?: string }
        throw new Error(data.error || 'Failed')
      }
      onAdded()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed')
    } finally {
      setSaving(false)
    }
  }, [equipmentId, calDate, nextDate, lab, certNumber, results, notes, onAdded])

  return (
    <div className="card p-3 mb-3 space-y-2 border-[var(--accent)]/20">
      <div className="text-xs font-medium text-[var(--accent)]">Add Calibration Record</div>
      <div className="grid grid-cols-2 gap-2">
        <div>
          <label className="block text-[9px] text-gray-500 uppercase mb-1" htmlFor="calibration-date">Calibration Date</label>
          <input id="calibration-date" aria-label="Calibration Date" type="date" value={calDate} onChange={e => setCalDate(e.target.value)} className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-[var(--text-primary)]" />
        </div>
        <div>
          <label className="block text-[9px] text-gray-500 uppercase mb-1" htmlFor="next-calibration">Next Calibration</label>
          <input  id="next-calibration" aria-label="Next Calibration" type="date" value={nextDate} onChange={e => setNextDate(e.target.value)} className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-[var(--text-primary)]" />
        </div>
      </div>
      <div className="grid grid-cols-2 gap-2">
        <input type="text" value={lab} onChange={e => setLab(e.target.value)} placeholder="Calibration Lab" className="h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-[var(--text-primary)] placeholder-gray-600" />
        <input type="text" value={certNumber} onChange={e => setCertNumber(e.target.value)} placeholder="Certificate No." className="h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-[var(--text-primary)] font-mono placeholder-gray-600" />
      </div>
      <select value={results} onChange={e => setResults(e.target.value)} className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-[var(--text-primary)]">
        <option value="pass">Pass</option>
        <option value="fail">Fail</option>
        <option value="conditional">Conditional Pass</option>
      </select>
      {error && <p className="text-xs text-red-400">{error}</p>}
      <div className="flex gap-2">
        <button onClick={onClose} className="flex-1 h-8 rounded bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-xs text-gray-400">Cancel</button>
        <button onClick={handleSave} disabled={saving} className="flex-1 h-8 rounded bg-[var(--accent)] text-black text-xs font-semibold disabled:opacity-40">
          {saving ? 'Saving...' : 'Save'}
        </button>
      </div>
    </div>
  )
}

'use client'

import { useState, useCallback } from 'react'
import { useSession } from 'next-auth/react'
import {
  type FeedbackCategory,
  buildFeedbackPayload,
  markFeedbackSubmitted,
  canSubmitFeedback,
  drainStoredErrors,
} from '@/lib/feedback/feedbackCollector'
import { ChangelogPanel } from '@/components/feedback/ChangelogPanel'

type Tab = 'feedback' | 'changelog'

/**
 * FeedbackWidget — floating button that opens a feedback form.
 *
 * AUDIT FIX (2026-07-05): Complete rewrite. Previously:
 *   - Used the deprecated createClient() which tried dbClient.from('feedback')
 *     but no feedback table existed → insert failed silently
 *   - Fallback was console.warn() — feedback was lost
 *   - Screenshot capture tried to import html2canvas (not installed) → always null
 *
 * Now:
 *   - POSTs to /api/feedback (real endpoint that saves to the feedback table)
 *   - Uses useSession() for the user ID (not the deprecated auth.getSession())
 *   - Sends error logs from sessionStorage as JSON
 *   - Screenshot capture removed (was always failing silently — html2canvas
 *     not installed and is too heavy to add). Users can still describe
 *     what they see in the message field.
 *   - Rate limited server-side: 5 submissions per 15 minutes per user
 */
export default function FeedbackWidget() {
  const { data: session } = useSession()
  const [isOpen, setIsOpen] = useState(false)
  const [tab, setTab] = useState<Tab>('feedback')
  const [type, setType] = useState<FeedbackCategory>('bug')
  const [message, setMessage] = useState('')
  const [email, setEmail] = useState('')
  const [submitted, setSubmitted] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const resetForm = useCallback(() => {
    setSubmitted(false)
    setMessage('')
    setEmail('')
    setError(null)
    setType('bug')
  }, [])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!message.trim()) return
    if (!canSubmitFeedback()) {
      setError('Please wait 30 seconds before submitting again.')
      return
    }

    setLoading(true)
    setError(null)

    try {
      const payload = buildFeedbackPayload(type, message, email || undefined)

      const res = await fetch('/api/feedback', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type,
          message,
          email: email || undefined,
          includeErrors: true,
          errors: payload.errorEntries,
        }),
      })

      if (!res.ok) {
        const data = (await res.json().catch(() => ({}))) as { error?: string }
        throw new Error(data.error || `Server returned ${res.status}`)
      }

      markFeedbackSubmitted()
      setSubmitted(true)
      setTimeout(() => {
        setIsOpen(false)
        resetForm()
      }, 2500)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to submit feedback')
    } finally {
      setLoading(false)
    }
  }

  if (!isOpen) {
    return (
      <button
        onClick={() => setIsOpen(true)}
        aria-label="Send feedback"
        // AUDIT FIX (2026-07-05): Repositioned to avoid overlap with
        // QuickCompute (bottom-20 md:bottom-6 right-4) and FieldModeToggle
        // (bottom-6 right-6). The feedback button now sits ABOVE QuickCompute
        // on both mobile and desktop:
        //   Mobile:  bottom-[168px] (above MobileNav 64px + QuickCompute 104px)
        //   Desktop: bottom-32      (above QuickCompute at bottom-6 + its height)
        className="fixed bottom-[168px] right-4 md:bottom-32 bg-[var(--accent)] text-black px-3 py-2 rounded-full shadow-lg text-xs font-semibold z-40 hover:bg-[var(--accent-dim)] transition-colors flex items-center gap-1.5"
      >
        <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2.5}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M7.5 8.25h9m-9 3H12m-9.75 1.51c0 1.6 1.123 2.994 2.707 3.227 1.129.166 2.27.293 3.423.379.35.026.67.21.865.501L12 21l2.755-4.133a1.14 1.14 0 01.865-.501 48.172 48.172 0 003.423-.379c1.584-.233 2.707-1.626 2.707-3.228V6.741c0-1.602-1.123-2.995-2.707-3.228A48.394 48.394 0 0012 3c-2.392 0-4.744.175-7.043.513C3.373 3.746 2.25 5.14 2.25 6.741v6.018z" />
        </svg>
        Feedback
      </button>
    )
  }

  return (
    <div className="fixed bottom-[168px] right-4 left-4 sm:bottom-32 sm:left-auto bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-xl shadow-2xl w-[calc(100vw-2rem)] sm:w-[22rem] max-h-[70vh] z-50 flex flex-col overflow-hidden">
      {/* Header */}
      <div className="bg-[var(--accent)] px-4 py-3 flex justify-between items-center flex-shrink-0">
        <h3 className="text-black font-bold text-sm">Feedback</h3>
        <div className="flex items-center gap-2">
          <div className="flex bg-black/10 rounded-md overflow-hidden">
            <button
              onClick={() => setTab('feedback')}
              className={`px-2.5 py-1 text-xs font-medium transition-colors ${
                tab === 'feedback' ? 'bg-black text-[var(--accent)]' : 'text-black/70 hover:text-black'
              }`}
            >
              Report
            </button>
            <button
              onClick={() => setTab('changelog')}
              className={`px-2.5 py-1 text-xs font-medium transition-colors ${
                tab === 'changelog' ? 'bg-black text-[var(--accent)]' : 'text-black/70 hover:text-black'
              }`}
            >
              What&apos;s New
            </button>
          </div>
          <button onClick={() => { setIsOpen(false); resetForm() }} className="text-black hover:text-black/60 ml-1" aria-label="Close feedback">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
      </div>

      {/* Body */}
      <div className="flex-1 overflow-y-auto min-h-0">
        {tab === 'changelog' ? (
          <ChangelogPanel />
        ) : submitted ? (
          <div className="text-center py-10 px-4">
            <div className="w-12 h-12 rounded-full bg-green-500/15 flex items-center justify-center mx-auto mb-3">
              <svg className="w-6 h-6 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2.5}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />
              </svg>
            </div>
            <p className="text-green-400 font-semibold mb-1">Thank you!</p>
            <p className="text-[var(--text-muted)] text-xs">Your feedback has been submitted and will help improve METARDU.</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-4 space-y-3">
            {/* Auth notice */}
            {!session?.user && (
              <p className="text-xs text-[var(--text-muted)] bg-[var(--bg-tertiary)] rounded-lg p-2">
                You need to be signed in to submit feedback.
              </p>
            )}

            {/* Type selector */}
            <div className="flex gap-1.5">
              {([
                { key: 'bug' as FeedbackCategory, label: 'Bug' },
                { key: 'feature' as FeedbackCategory, label: 'Feature' },
                { key: 'performance' as FeedbackCategory, label: 'Slow' },
                { key: 'general' as FeedbackCategory, label: 'Other' },
              ]).map(({ key, label }) => (
                <button
                  key={key}
                  type="button"
                  onClick={() => setType(key)}
                  className={`flex-1 py-3 rounded-lg text-[10px] font-medium transition-all ${
                    type === key
                      ? 'bg-[var(--accent)] text-black shadow-md shadow-[var(--accent)]/20'
                      : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)] hover:text-white hover:bg-[var(--border-color)]'
                  }`}
                >
                  {label}
                </button>
              ))}
            </div>

            {/* Message */}
            <div>
              <textarea
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                placeholder={
                  type === 'bug'
                    ? 'What went wrong? Steps to reproduce...'
                    : type === 'feature'
                      ? 'What feature would you like?'
                      : type === 'performance'
                        ? 'What is slow? When does it happen?'
                        : 'How can we improve METARDU?'
                }
                rows={5}
                className="w-full bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-[var(--text-primary)] text-sm resize-none focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/30 outline-none transition-all"
                required
                minLength={10}
                maxLength={2000}
              />
              <p className="text-[10px] text-[var(--text-muted)] mt-1 text-right">
                {message.length}/2000
              </p>
            </div>

            {/* Email (optional) */}
            <div>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                aria-label="Email (optional — for follow-up)"

                className="w-full bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-[var(--text-primary)] text-sm focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/30 outline-none transition-all"
              />
            </div>

            {/* Error notice */}
            {error && (
              <p className="text-xs text-red-400 bg-red-500/10 rounded-lg p-2">
                {error}
              </p>
            )}

            {/* Submit */}
            <button
              type="submit"
              disabled={loading || !message.trim() || !session?.user}
              className="w-full py-2.5 bg-[var(--accent)] text-black font-bold rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-40 transition-colors text-sm"
            >
              {loading ? 'Sending...' : 'Submit Feedback'}
            </button>
          </form>
        )}
      </div>
    </div>
  )
}

'use client';

/**
 * FieldConnectionBar — top bar showing instrument connection status
 *
 * Shows:
 *   - Connection status (disconnected/connecting/connected/streaming)
 *   - Instrument type (total station / GNSS rover)
 *   - Battery/signal strength (if available)
 *   - Fix quality (for GNSS: fixed/float/dgps/single)
 *   - Online/offline sync indicator
 *
 * Designed for field use: large text, high contrast, sunlight-readable.
 */

import { memo } from 'react'
import { Wifi, WifiOff, Bluetooth, Usb, Satellite, Battery, AlertCircle, CheckCircle, Loader2 } from 'lucide-react'
import { useInstrumentStore } from '@/stores/instrumentStore'

interface FieldConnectionBarProps {
  isOnline: boolean
  isSyncing: boolean
  pendingSyncCount: number
  onSyncClick?: () => void
}

export const FieldConnectionBar = memo(function FieldConnectionBar({
  isOnline,
  isSyncing,
  pendingSyncCount,
  onSyncClick,
}: FieldConnectionBarProps) {
  const { status, transport, device, instrumentInfo, latestPoint } = useInstrumentStore()

  const isConnected = status === 'connected' || status === 'streaming'
  const isStreaming = status === 'streaming'

  // Status colors
  const statusColor = !isConnected
    ? 'bg-[var(--error)]/10 text-[var(--error)] border-[var(--error)]/30'
    : isStreaming
      ? 'bg-[var(--success)]/10 text-[var(--success)] border-[var(--success)]/30'
      : 'bg-[var(--warning)]/10 text-[var(--warning)] border-[var(--warning)]/30'

  const TransportIcon = transport === 'web-bluetooth' ? Bluetooth : transport === 'web-serial' ? Usb : Satellite

  return (
    <div className="flex items-center gap-3 px-4 py-2.5 bg-[var(--bg-secondary)] border-b border-[var(--border-color)]">
      {/* Connection Status */}
      <div className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border ${statusColor}`}>
        {status === 'connecting' || status === 'reconnecting' ? (
          <Loader2 className="w-4 h-4 animate-spin" />
        ) : isConnected ? (
          <CheckCircle className="w-4 h-4" />
        ) : (
          <AlertCircle className="w-4 h-4" />
        )}
        <span className="text-sm font-medium">
          {!isConnected ? 'Disconnected' : isStreaming ? 'Streaming' : 'Connected'}
        </span>
      </div>

      {/* Transport + Device */}
      {isConnected && (
        <div className="flex items-center gap-1.5 text-sm text-[var(--text-secondary)]">
          <TransportIcon className="w-4 h-4 text-[var(--accent)]" />
          <span>{device?.name || instrumentInfo?.model || 'Instrument'}</span>
        </div>
      )}

      {/* GNSS Fix Quality */}
      {isConnected && latestPoint?.source === 'nmea' && (
        <div className="flex items-center gap-2 text-sm">
          <span className={`px-2 py-0.5 rounded font-mono text-xs ${
            (latestPoint.quality ?? 0) >= 4
              ? 'bg-[var(--success)]/20 text-[var(--success)]'
              : (latestPoint.quality ?? 0) >= 2
                ? 'bg-[var(--warning)]/20 text-[var(--warning)]'
                : 'bg-[var(--error)]/20 text-[var(--error)]'
          }`}>
            {(latestPoint.quality ?? 0) >= 4 ? 'FIXED' : (latestPoint.quality ?? 0) >= 2 ? 'FLOAT' : 'NO FIX'}
          </span>
          {latestPoint.satellites != null && (
            <span className="text-[var(--text-muted)] font-mono text-xs">
              🛰 {latestPoint.satellites}
            </span>
          )}
          {latestPoint.hdop != null && (
            <span className="text-[var(--text-muted)] font-mono text-xs">
              HDOP {latestPoint.hdop.toFixed(1)}
            </span>
          )}
        </div>
      )}

      {/* Spacer */}
      <div className="flex-1" />

      {/* Sync Status */}
      <button
        onClick={onSyncClick}
        disabled={!isOnline || isSyncing || pendingSyncCount === 0}
        className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
        title={isOnline ? 'Sync now' : 'Offline — will sync when online'}
      >
        {isSyncing ? (
          <Loader2 className="w-3.5 h-3.5 animate-spin text-[var(--accent)]" />
        ) : isOnline ? (
          <Wifi className="w-3.5 h-3.5 text-[var(--success)]" />
        ) : (
          <WifiOff className="w-3.5 h-3.5 text-[var(--error)]" />
        )}
        <span className={isOnline ? 'text-[var(--text-secondary)]' : 'text-[var(--error)]'}>
          {isSyncing ? 'Syncing…' : isOnline ? 'Online' : 'Offline'}
        </span>
        {pendingSyncCount > 0 && (
          <span className="bg-[var(--accent)]/20 text-[var(--accent)] px-1.5 py-0.5 rounded-full text-[10px] font-mono font-bold">
            {pendingSyncCount}
          </span>
        )}
      </button>
    </div>
  )
})

'use client';

/**
 * FieldDataCollector — unified field data collection experience
 *
 * THE COMPONENT THAT MAKES METARDU BETTER THAN HI-TARGET/CHCNAV
 *
 * This is the purpose-built field data collector that orchestrates:
 *   1. Instrument connection (total station or GNSS rover)
 *   2. Station setup (IH, TH, backsight, atmospheric corrections)
 *   3. One-tap measurement capture (with haptic + audio feedback)
 *   4. Live QC (precision ratio, tolerance status per RDM 1.1)
 *   5. Stakeout mode (with audio guidance to target)
 *   6. Offline-first persistence (IndexedDB, auto-sync when online)
 *   7. Push-to-traverse (seamless handoff to adjustment)
 *
 * Why this beats Hi-Target/CHCNAV:
 *   - Works on ANY device (phone, tablet, laptop) — no Windows-only lock-in
 *   - Cloud sync — measurements appear on the office computer instantly
 *   - Rigorous QC — live tolerance checking per Survey Regulations 1994
 *   - Deed plan integration — push directly to deed plan generator
 *   - Multi-user — field crew + office crew see the same data
 *   - PWA — installable, offline-first, sunlight-readable field mode
 */

import { useState, useEffect, useCallback } from 'react'
import { Settings, Target, List, Cloud, ChevronRight, X, Camera } from 'lucide-react'
import { FieldConnectionBar } from './FieldConnectionBar'
import { FieldMeasureButton } from './FieldMeasureButton'
import { FieldObservationList } from './FieldObservationList'
import { FieldStationSetup } from './FieldStationSetup'
import { useFieldSessionState, useFieldSession } from '@/hooks/useFieldSessionState'
import { ToleranceBadge } from '@/components/survey/ToleranceBadge'
import { InstrumentConnectionPanel } from '@/components/InstrumentConnectionPanel'
import type { FieldSessionState, SurveyType } from '@/lib/field/fieldSession'

interface FieldDataCollectorProps {
  projectId: string
  surveyType?: SurveyType
}

type Panel = 'measure' | 'stakeout' | 'list' | 'sync' | null

export function FieldDataCollector({
  projectId,
  surveyType = 'cadastral',
}: FieldDataCollectorProps) {
  const sessionState = useFieldSessionState(projectId, surveyType)
  const session = useFieldSession(projectId, surveyType)

  const [showSetup, setShowSetup] = useState(!sessionState.setup)
  const [activePanel, setActivePanel] = useState<Panel>('measure')
  const [showInstrumentPanel, setShowInstrumentPanel] = useState(false)
  const [activeFeatureCode, setActiveFeatureCode] = useState<string>('')
  const [stakeoutTarget, setStakeoutTarget] = useState<{ e: number; n: number; z: number } | null>(null)
  const [isSunlightMode, setIsSunlightMode] = useState(false)
  const [audioEnabled, setAudioEnabled] = useState(true)

  // Load existing measurements on mount
  useEffect(() => {
    session.loadMeasurements()
  }, [session])

  // Voice synthesis guidance for stakeout
  const announceStakeoutGuidance = useCallback((de: number, dn: number) => {
    if (!audioEnabled || typeof window === 'undefined' || !('speechSynthesis' in window)) return
    const text = `Delta East ${de >= 0 ? 'Right' : 'Left'} ${Math.abs(de).toFixed(1)} meters. Delta North ${dn >= 0 ? 'Forward' : 'Backward'} ${Math.abs(dn).toFixed(1)} meters.`
    window.speechSynthesis.cancel() // stop prior phrase
    const utterance = new SpeechSynthesisUtterance(text)
    utterance.rate = 1.1
    window.speechSynthesis.speak(utterance)
  }, [audioEnabled])

  // Auto-sync when online
  useEffect(() => {
    if (sessionState.isOnline && sessionState.pendingSyncCount > 0 && !sessionState.isSyncing) {
      const timer = setTimeout(() => session.syncNow(), 2000)
      return () => clearTimeout(timer)
    }
  }, [sessionState.isOnline, sessionState.pendingSyncCount, sessionState.isSyncing, session])

  const handleCapture = useCallback(async (pointId: string, code?: string): Promise<boolean> => {
    const measurement = await session.captureMeasurement({ pointId, notes: code })
    return measurement !== null
  }, [session])

  const handleSetupComplete = useCallback((setup: typeof sessionState.setup) => {
    if (setup) {
      session.setupStation(setup)
      setShowSetup(false)
      setActivePanel('measure')
    }
  }, [session])

  const handleSync = useCallback(() => {
    session.syncNow()
  }, [session])

  const handleStakeout = useCallback((target: { e: number; n: number; z: number }) => {
    setStakeoutTarget(target)
    session.activateStakeout({
      easting: target.e,
      northing: target.n,
      elevation: target.z,
    })
    setActivePanel('stakeout')
    announceStakeoutGuidance(target.e, target.n)
  }, [session, announceStakeoutGuidance])

  // ─── Setup Screen ────────────────────────────────────────────────────────
  if (showSetup) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex flex-col">
        <FieldConnectionBar
          isOnline={sessionState.isOnline}
          isSyncing={sessionState.isSyncing}
          pendingSyncCount={sessionState.pendingSyncCount}
          onSyncClick={handleSync}
        />
        <div className="flex-1 overflow-y-auto p-4 max-w-2xl mx-auto w-full">
          <FieldStationSetup
            onComplete={handleSetupComplete}
            initialSetup={sessionState.setup}
          />
        </div>
      </div>
    )
  }

  // ─── Main Collector UI ───────────────────────────────────────────────────
  return (
    <div className={`min-h-screen flex flex-col ${isSunlightMode ? 'bg-white text-black font-bold border-b-4 border-black' : 'bg-[var(--bg-primary)]'}`}>
      {/* Connection Bar */}
      <FieldConnectionBar
        isOnline={sessionState.isOnline}
        isSyncing={sessionState.isSyncing}
        pendingSyncCount={sessionState.pendingSyncCount}
        onSyncClick={handleSync}
      />

      {/* Station Info Bar */}
      <div className={`flex items-center gap-3 px-4 py-2 border-b ${isSunlightMode ? 'bg-yellow-300 text-black border-black border-b-2 font-black' : 'bg-[var(--bg-secondary)] border-[var(--border-color)]'}`}>
        <div className="flex-1 flex items-center gap-3">
          <span className={`text-sm font-mono font-bold ${isSunlightMode ? 'text-black underline' : 'text-[var(--accent)]'}`}>
            {sessionState.setup?.stationName}
          </span>
          <span className="text-xs opacity-70">
            IH: {sessionState.setup?.instrumentHeight}m | TH: {sessionState.setup?.targetHeight}m
          </span>
        </div>

        <button
          onClick={() => setIsSunlightMode(!isSunlightMode)}
          className={`px-3 py-1 text-xs rounded font-bold border transition ${
            isSunlightMode ? 'bg-black text-white border-black shadow-lg' : 'bg-black/10 dark:bg-white/10 text-foreground border-white/20'
          }`}
          title="Toggle Sunlight High-Contrast Outdoor Mode"
        >
          {isSunlightMode ? '☀️ Sunlight Mode ON' : '🌤️ Outdoor Mode'}
        </button>
        <button
          onClick={() => setShowSetup(true)}
          className={`flex items-center gap-1 text-xs transition-colors ${
            isSunlightMode ? 'text-black hover:text-gray-700' : 'text-[var(--text-secondary)] hover:text-[var(--accent)]'
          }`}
        >
          <Settings className="w-3 h-3" /> Edit
        </button>
      </div>

      {/* Live QC Badge (if tolerance status available) */}
      {sessionState.toleranceStatus && (
        <div className="px-4 py-2 bg-[var(--bg-secondary)] border-b border-[var(--border-color)]">
          <ToleranceBadge result={sessionState.toleranceStatus} compact />
        </div>
      )}

      {/* Main Content Area */}
      <div className="flex-1 overflow-y-auto">
        {activePanel === 'measure' && (
          <div className="flex flex-col items-center py-8 px-4 w-full">
            {/* Measure Button */}
            <FieldMeasureButton
              onCapture={(pointId) => handleCapture(pointId, activeFeatureCode || undefined)}
              stationSetup={!!sessionState.setup}
              pointIdPrefix={surveyType === 'cadastral' ? 'BP' : 'P'}
            />

            {/* Smart Feature Coding */}
            <div className="mt-8 w-full max-w-md">
              <div className="flex items-center justify-between mb-3">
                <span className="text-sm font-semibold text-[var(--text-secondary)]">Feature Code</span>
                <button 
                  className="flex items-center gap-2 px-3 py-1.5 bg-[var(--bg-secondary)] rounded-full hover:bg-[var(--bg-tertiary)] transition-colors border border-[var(--border-color)] text-xs font-medium text-[var(--text-primary)] shadow-sm"
                  title="Attach Photo"
                >
                  <Camera className="w-4 h-4 text-[var(--accent)]" />
                  <span>Photo</span>
                </button>
              </div>
              <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide w-full">
                {['FENCE_START', 'FENCE_LINE', 'FENCE_END', 'TREE', 'WALL', 'BLDG', 'ROAD_EDGE'].map(code => (
                  <button
                    key={code}
                    onClick={() => setActiveFeatureCode(code === activeFeatureCode ? '' : code)}
                    className={`shrink-0 px-4 py-2 rounded-full text-xs font-bold border transition-colors ${
                      activeFeatureCode === code
                        ? 'bg-[var(--accent)] text-black border-[var(--accent)] shadow-md'
                        : isSunlightMode 
                          ? 'bg-white text-black border-black border-2 hover:bg-gray-100'
                          : 'bg-[var(--bg-secondary)] text-[var(--text-secondary)] border-[var(--border-color)] hover:border-[var(--accent)]'
                    }`}
                  >
                    {code}
                  </button>
                ))}
              </div>
            </div>

            {/* Instrument Connection CTA */}
            {!showInstrumentPanel && (
              <InstrumentPanelToggle onShow={() => setShowInstrumentPanel(true)} />
            )}
          </div>
        )}

        {activePanel === 'list' && (
          <FieldObservationList
            measurements={sessionState.measurements}
            onDelete={async (id) => {
              // Delete from IndexedDB
              try {
                const { deleteObservation } = await import('@/lib/offline/fieldBookDB')
                await deleteObservation(id)
              } catch {}
            }}
          />
        )}

        {activePanel === 'stakeout' && stakeoutTarget && (
          <StakeoutPanel
            target={stakeoutTarget}
            sessionState={sessionState}
            onClose={() => {
              session.deactivateStakeout()
              setStakeoutTarget(null)
              setActivePanel('measure')
            }}
          />
        )}

        {activePanel === 'sync' && (
          <SyncPanel
            sessionState={sessionState}
            onSync={handleSync}
          />
        )}
      </div>

      {/* Bottom Navigation */}
      <div className="flex items-center justify-around border-t border-[var(--border-color)] bg-[var(--bg-secondary)]">
        <NavButton
          active={activePanel === 'measure'}
          onClick={() => setActivePanel('measure')}
          icon={<Target className="w-5 h-5" />}
          label="Measure"
        />
        <NavButton
          active={activePanel === 'stakeout'}
          onClick={() => setActivePanel('stakeout')}
          icon={<Crosshair className="w-5 h-5" />}
          label="Stakeout"
          disabled={!sessionState.setup}
        />
        <NavButton
          active={activePanel === 'list'}
          onClick={() => setActivePanel('list')}
          icon={<List className="w-5 h-5" />}
          label={`Points (${sessionState.measurements.length})`}
        />
        <NavButton
          active={activePanel === 'sync'}
          onClick={() => setActivePanel('sync')}
          icon={<Cloud className="w-5 h-5" />}
          label={sessionState.isOnline ? 'Sync' : 'Offline'}
          badge={sessionState.pendingSyncCount > 0 ? sessionState.pendingSyncCount : undefined}
        />
      </div>

      {/* Instrument Connection Modal */}
      {showInstrumentPanel && (
        <div className="fixed inset-0 z-50 bg-black/60 flex items-end sm:items-center justify-center">
          <div className="bg-[var(--bg-primary)] w-full sm:max-w-2xl sm:rounded-xl rounded-t-xl max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between p-4 border-b border-[var(--border-color)]">
              <h3 className="font-semibold text-[var(--text-primary)]">Connect Instrument</h3>
              <button
                onClick={() => setShowInstrumentPanel(false)}
                className="p-1 text-[var(--text-muted)] hover:text-[var(--text-primary)]"
              >
                <X className="w-5 h-5" />
              </button>
            </div>
            <div className="p-4">
              <InstrumentConnectionPanel
                onImportPoints={() => {}}
              />
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

