          <span className="font-mono ml-1">{observation.vertical_angle.toFixed(4)}°</span>
        </div>
        <div>
          <span className="text-gray-500">Dist</span>
          <span className="font-mono ml-1">{observation.slope_distance.toFixed(3)}m</span>
