                      {[1, 2, 3, 4].map((bar) => (
                        <div
                          key={bar}
                          className={`w-1.5 rounded-sm ${
                            bar <= rssiToBars(store.device!.rssi)
                              ? rssiColor(store.device!.rssi)
                              : 'bg-gray-300 dark:bg-gray-600'
                          }`}
                          style={{ height: `${bar * 25}%` }}
                        />
                      ))}
                    </div>
                  )}
                </div>
              </div>
            </div>

            {/* Live position */}
            {position && (
              <div className="p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-200 dark:border-blue-800">
                <div className="flex items-center gap-2 mb-2">
                  <MapPin className="w-4 h-4 text-blue-600 dark:text-blue-400" />
                  <span className="font-medium text-blue-900 dark:text-blue-200">Current Position</span>
                  <span className={`ml-auto text-xs font-semibold px-2 py-0.5 rounded-full ${
                    position.fixType === 'rtk' ? 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300' :
                    position.fixType === 'float' ? 'bg-lime-100 text-lime-700 dark:bg-lime-900/40 dark:text-lime-300' :
                    position.fixType === 'dgps' ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300' :
                    'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/40 dark:text-yellow-300'
                  }`}>
                    {fixQualityLabel(position.fixType)}
                  </span>
                </div>

                <div className="grid grid-cols-2 gap-x-4 gap-y-1.5 text-sm">
                  <div>
                    <span className="text-gray-500 dark:text-gray-400">Lat:</span>
                    <span className="font-mono ml-1 text-gray-800 dark:text-gray-200">{position.latitude.toFixed(7)}°</span>
                  </div>
                  <div>
                    <span className="text-gray-500 dark:text-gray-400">Lon:</span>
                    <span className="font-mono ml-1 text-gray-800 dark:text-gray-200">{position.longitude.toFixed(7)}°</span>
                  </div>
                  <div>
                    <span className="text-gray-500 dark:text-gray-400">Alt:</span>
                    <span className="font-mono ml-1 text-gray-800 dark:text-gray-200">{position.altitude.toFixed(3)}m</span>
                  </div>
                  <div>
                    <span className="text-gray-500 dark:text-gray-400">Sats:</span>
                    <span className="font-mono ml-1 text-gray-800 dark:text-gray-200">{position.satellites}</span>
                  </div>
                  <div>
                    <span className="text-gray-500 dark:text-gray-400">HDOP:</span>
                    <span className={`font-mono ml-1 ${position.hdop <= 1 ? 'text-green-600' : position.hdop <= 2 ? 'text-yellow-600' : 'text-red-600'}`}>
                      {position.hdop.toFixed(1)}
                    </span>
                  </div>
                  <div>
                    <span className="text-gray-500 dark:text-gray-400">Quality:</span>
                    <span className={`font-mono ml-1 ${fixQualityColor(position.fixType)}`}>
                      {position.quality}
                    </span>
                  </div>
                </div>

                {/* Coordinate system conversions */}
                {showCoordinateSystem && (utmCoord || kenyaCoord) && (
                  <div className="mt-3 pt-3 border-t border-blue-200 dark:border-blue-800 space-y-2">
                    {utmCoord && (
                      <div className="text-xs">
                        <span className="text-gray-500 dark:text-gray-400 uppercase tracking-wider font-medium">UTM {utmCoord.zone}</span>
                        <div className="font-mono text-gray-700 dark:text-gray-300 mt-0.5">
                          E {utmCoord.easting.toFixed(3)} N {utmCoord.northing.toFixed(3)}
                        </div>
                      </div>
                    )}
                    {kenyaCoord && (
                      <div className="text-xs">
                        <span className="text-gray-500 dark:text-gray-400 uppercase tracking-wider font-medium">Kenya Grid</span>
                        <div className="font-mono text-gray-700 dark:text-gray-300 mt-0.5">
                          E {kenyaCoord.easting.toFixed(3)} N {kenyaCoord.northing}
                        </div>
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}

            {/* Metrics */}
            <div className="grid grid-cols-3 gap-2 text-center">
              <div className="bg-gray-50 dark:bg-gray-800 rounded-md p-2">
                <div className="text-lg font-mono font-bold text-blue-600 dark:text-blue-400">{store.points.length}</div>
                <div className="text-[10px] text-gray-500 uppercase">Points</div>
              </div>
              <div className="bg-gray-50 dark:bg-gray-800 rounded-md p-2">
                <div className="text-lg font-mono font-bold text-green-600 dark:text-green-400">{store.metrics.messagesParsed}</div>
                <div className="text-[10px] text-gray-500 uppercase">Messages</div>
              </div>
              <div className="bg-gray-50 dark:bg-gray-800 rounded-md p-2">
                <div className="text-lg font-mono font-bold text-orange-600 dark:text-orange-400">{store.metrics.errorsCount}</div>
                <div className="text-[10px] text-gray-500 uppercase">Errors</div>
              </div>
            </div>

            {/* Disconnect button */}
            <button
              onClick={handleDisconnect}
              className="w-full py-2 px-4 border border-red-300 dark:border-red-700 text-red-600 dark:text-red-400 rounded-lg text-sm font-medium hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
            >
              <BluetoothOff className="w-4 h-4 inline mr-2" />
              Disconnect
            </button>
          </>
        )}
      </div>
    </div>
  );
}

// ─── Utilities ──────────────────────────────────────────────────

function formatTimeSince(date: Date): string {
  const seconds = Math.floor((Date.now() - date.getTime()) / 1000);
  if (seconds < 60) return `${seconds}s ago`;
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  return `${hours}h ${minutes % 60}m ago`;
}

'use client';

import { useState } from 'react';
import { ParseResult, ParsedPoint } from '@/types/importer';

interface Props {
  rawContent: string;
  onMapped: (result: ParseResult) => void;
  onCancel: () => void;
}

const TARGET_FIELDS: (keyof ParsedPoint)[] = [
  'point_no', 'easting', 'northing', 'rl', 'bearing', 'distance', 'code', 'remark'
];

export default function GenericCSVMapper({ rawContent, onMapped, onCancel }: Props) {
  const lines = rawContent.trim().split('\n');
  const headers = lines[0].split(',').map((h) => h.trim());

  const [mappings, setMappings] = useState<Record<string, keyof ParsedPoint | ''>>(() => {
    const initial: Record<string, keyof ParsedPoint | ''> = {};
    headers.forEach((h) => {
      const lower = h.toLowerCase();
      if (lower.includes('east') || lower === 'e' || lower === 'x') initial[h] = 'easting';
      else if (lower.includes('north') || lower === 'n' || lower === 'y') initial[h] = 'northing';
      else if (lower.includes('rl') || lower.includes('elev') || lower.includes('height') || lower === 'z') initial[h] = 'rl';
      else if (lower.includes('point') || lower.includes('pt') || lower.includes('name')) initial[h] = 'point_no';
      else if (lower.includes('code') || lower.includes('desc')) initial[h] = 'code';
      else initial[h] = '';
    });
    return initial;
  });

  const handleApply = () => {
    const points: ParsedPoint[] = [];
    const warnings: string[] = [];

    for (let i = 1; i < lines.length; i++) {
      const values = lines[i].split(',').map((v) => v.trim());
      const point: ParsedPoint = { raw: {} };

      headers.forEach((h, idx) => {
        const target = mappings[h];
        if (!target) return;
        const val = values[idx];
        const numericFields: (keyof ParsedPoint)[] = ['easting', 'northing', 'rl', 'bearing', 'distance'];
        if (numericFields.includes(target)) {
          (point as Record<string, unknown>)[target] = parseFloat(val);
        } else {
          (point as Record<string, unknown>)[target] = val;
        }
        (point.raw as Record<string, unknown>)[h] = val;
      });

      if (Number.isNaN(point.easting!) && Number.isNaN(point.northing!)) {
        warnings.push(`Row ${i + 1}: no valid coordinates after mapping — skipped`);
        continue;
      }

      points.push(point);
    }

    onMapped({ format: 'csv', points, warnings });
  };

  return (
    <div className="space-y-4">
      <h3 className="font-semibold text-gray-800">Map Columns</h3>
      <p className="text-sm text-gray-500">
        Format not recognised. Match your file columns to survey fields.
      </p>

      <div className="grid grid-cols-2 gap-3 max-h-64 overflow-y-auto">
        {headers.map((h) => (
          <div key={h} className="flex items-center gap-2">
            <span className="text-sm text-gray-700 w-32 truncate">{h}</span>
            <select
              value={mappings[h]}
              onChange={(e) => setMappings((prev) => ({ ...prev, [h]: e.target.value as keyof ParsedPoint | '' }))}
              className="flex-1 text-sm border rounded px-2 py-1"
            >
              <option value="">— skip —</option>
              {TARGET_FIELDS.map((f) => (
                <option key={f} value={f}>{f}</option>
              ))}
            </select>
          </div>
        ))}
      </div>

      <div className="flex gap-2">
        <button onClick={onCancel} className="px-3 py-1.5 text-sm border rounded hover:bg-gray-50">
          Cancel
        </button>
        <button onClick={handleApply} className="px-3 py-1.5 text-sm bg-blue-600 text-white rounded hover:bg-blue-700">
          Apply Mapping
        </button>
      </div>
    </div>
  );
}

'use client';

import { useState, useCallback } from 'react';
import { ParseResult, SupportedFormat } from '@/types/importer';
import ImportPreviewTable from './ImportPreviewTable';
import GenericCSVMapper from './GenericCSVMapper';

import '@/lib/importers/index';
import { detectFormat, getParser } from '@/lib/importers/registry';
import { smartImport, SmartImportResult } from '@/lib/importers/universalImporter';

interface Props {
  projectId: string;
  onImportComplete: (rowCount: number) => void;
}

type ImportStep = 'idle' | 'parsing' | 'mapping' | 'preview' | 'committing' | 'done';

export default function UniversalImporter({ projectId, onImportComplete }: Props) {
  const [step, setStep] = useState<ImportStep>('idle');
  const [parseResult, setParseResult] = useState<ParseResult | null>(null);
  const [smartResult, setSmartResult] = useState<SmartImportResult | null>(null);
  const [fileName, setFileName] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isDragOver, setIsDragOver] = useState(false);

  const processFile = useCallback(async (file: File) => {
    setFileName(file.name);
    setError(null);
    setStep('parsing');

    try {
      const result = await smartImport(file);
      setSmartResult(result);
      
      if (result.success) {
        setStep('preview');
      } else {
        setError(result.errors.join(', ') || 'Import failed');
        setStep('idle');
      }
    } catch (err: unknown) {
      setError(err instanceof Error ? (err as Error).message : 'Unknown error');
      setStep('idle');
    }
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
    const file = e.dataTransfer.files[0];
    if (file) processFile(file);
  }, [processFile]);

  const handleFileInput = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) processFile(file);
  }, [processFile]);

  const handleCommit = async () => {
    if (!smartResult || smartResult.entries.length === 0) return;
    setStep('committing');

    try {
      const res = await fetch('/api/import/commit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          projectId,
          entries: smartResult.entries,
          adjustedLegs: smartResult.adjustedLegs,
          fileName,
          relativePrecision: smartResult.relativePrecision,
        }),
      });

      const data = await res.json() as { error?: string; imported: number };
      if (!res.ok) throw new Error(data.error ?? 'Commit failed');

      setStep('done');
      onImportComplete(data.imported);
    } catch (err: unknown) {
      setError(err instanceof Error ? (err as Error).message : 'Commit failed');
      setStep('preview');
    }
  };

  if (step === 'idle' || step === 'parsing') {
    return (
      <div
        onDrop={handleDrop}
        onDragOver={(e) => { e.preventDefault(); setIsDragOver(true); }}
        onDragLeave={() => setIsDragOver(false)}
        className={`border-2 border-dashed rounded-xl p-12 text-center transition-colors ${
          isDragOver ? 'border-blue-400 bg-blue-50' : 'border-gray-300 bg-gray-50'
        }`}
      >
        <p className="text-lg font-medium text-gray-700 mb-2">
          {step === 'parsing' ? 'Parsing file…' : 'Drop any survey file here'}
        </p>
        <p className="text-sm text-gray-400 mb-4">
          CSV, GSI, JobXML, RW5, DXF — or any format. Auto-detected.
        </p>
        {step === 'idle' && (
          <label className="px-4 py-2 bg-blue-600 text-white rounded cursor-pointer hover:bg-blue-700 text-sm">
            Browse Files
            <input type="file" className="hidden" onChange={handleFileInput} />
          </label>
        )}
        {error && <p className="text-red-500 text-sm mt-4">{error}</p>}
      </div>
    );
  }

  if (step === 'mapping' && parseResult) {
    return (
      <GenericCSVMapper
        rawContent={(parseResult.metadata?.rawContent as string) ?? ''}
        onMapped={(result) => { setParseResult(result); setStep('preview'); }}
        onCancel={() => setStep('idle')}
      />
    );
  }

  if ((step === 'preview' || step === 'committing') && smartResult) {
    return (
      <ImportPreviewTable
        result={{ format: 'csv', points: smartResult.entries.map((e) => ({ point_no: e.station, bearing: e.bearing, distance: e.distance, raw_data: { deltaE: e.deltaE, deltaN: e.deltaN } })), warnings: smartResult.warnings, errors: smartResult.errors }}
        fileName={fileName}
        onCommit={handleCommit}
        onCancel={() => setStep('idle')}
        committing={step === 'committing'}
        error={error}
        precision={smartResult.relativePrecision}
      />
    );
  }

  if (step === 'done') {
    return (
      <div className="text-center py-12">
        <p className="text-green-600 font-semibold text-lg">Import complete</p>
        {smartResult?.relativePrecision && (
          <p className="text-sm text-gray-600 mt-1">Precision: {smartResult.relativePrecision}</p>
        )}
        <button
          onClick={() => { setStep('idle'); setSmartResult(null); }}
          className="mt-4 px-4 py-2 text-sm bg-gray-100 rounded hover:bg-gray-200"
        >
          Import another file
        </button>
      </div>
    );
  }

  return null;
}

/**
 * METARDU — Instrument Connection Panel
 * =======================================
 * React component providing a UI to connect to surveying instruments
 * via Web Serial API or Bluetooth LE. Includes:
 *
 * - Transport selector (USB Serial / Bluetooth LE)
 * - Instrument preset selector (Leica, Trimble, Topcon, etc.)
 * - Custom baud rate / serial config
 * - Connection status indicator with live stats
 * - Real-time streaming point display
 * - Points table with count
 * - Import streamed points to current project
 *
 * The BLE path uses @capacitor-community/bluetooth-le on native
 * and Web Bluetooth API in the browser, with NUS + Location+NMEA
 * service support for surveying instruments.
 */

'use client'

import { useState, useCallback } from 'react'
import { useInstrumentConnection, type StreamedPoint } from '@/hooks/useInstrumentConnection'
import { INSTRUMENT_PRESETS, BRAND_INFO, type InstrumentBrand } from '@/lib/serial'
import {
  Cable,
  Wifi,
  WifiOff,
  Radio,
  Circle,
  Download,
  Settings,
  Trash2,
  Satellite,
  Crosshair,
  Activity,
  ChevronDown,
  ChevronUp,
  Target,
  RotateCcw,
  Ruler,
  Play,
  Square,
  Bluetooth,
  BluetoothOff,
  Usb,
} from 'lucide-react'
import { Capacitor } from '@capacitor/core'
import { WebBluetoothGNSS } from '@/lib/gnss/bluetooth'
import { CapacitorBLEGNSS, type CapacitorGNSSDevice } from '@/lib/gnss/capacitor-ble'
import { useInstrumentStore, type InstrumentDevice, type ConnectionTransport } from '@/stores/instrumentStore'
import type { NMEAPosition } from '@/lib/gnss/nmea-parser'
import { logger } from '@/lib/logger'

type TransportMode = 'serial' | 'ble'

interface InstrumentConnectionPanelProps {
  /** Called when user clicks "Import Points" to add streamed points to the project */
  onImportPoints?: (points: StreamedPoint[]) => void
  /** Called when a new point is received in real-time */
  onPointReceived?: (point: StreamedPoint) => void
  /** Default transport mode (auto-detected if not specified) */
  defaultTransport?: TransportMode
  className?: string
}

export function InstrumentConnectionPanel({
  onImportPoints,
  onPointReceived,
  defaultTransport,
  className = '',
}: InstrumentConnectionPanelProps) {
  const {
    connect,
    connectWithPreset,
    disconnect,
    status,
    isStreaming,
    isSupported: isSerialSupported,
    instrumentInfo,
    points,
    lastPoint,
    messagesParsed,
    errorCount,
    clearPoints,
    sendCommand: hookSendCommand,
    error,
  } = useInstrumentConnection()

  // Instrument store for BLE state
  const instrumentStore = useInstrumentStore()

  // Transport mode
  const isNative = typeof window !== 'undefined' && Capacitor.isNativePlatform()
  const [transportMode, setTransportMode] = useState<TransportMode>(
    defaultTransport || (isNative ? 'ble' : 'serial')
  )
  const [bleConnecting, setBleConnecting] = useState(false)
  const [bleError, setBleError] = useState<string | null>(null)
  const [bleScannedDevices, setBleScannedDevices] = useState<CapacitorGNSSDevice[]>([])
  const [bleSelectedDevice, setBleSelectedDevice] = useState<string | null>(null)
  const [bleService, setBleService] = useState<CapacitorBLEGNSS | WebBluetoothGNSS | null>(null)

  const isSupported = transportMode === 'ble' ? true : isSerialSupported

  const [showConfig, setShowConfig] = useState(false)
  const [selectedPreset, setSelectedPreset] = useState('generic-gnss')
  const [customBaud, setCustomBaud] = useState('9600')
  const [connecting, setConnecting] = useState(false)
  const [isTracking, setIsTracking] = useState(false)

  // Determine brand from preset key
  const getBrandFromPresetKey = (key: string): InstrumentBrand => {
    if (key.startsWith('leica')) return 'leica'
    if (key.startsWith('topcon')) return 'topcon'
    if (key.startsWith('trimble')) return 'trimble'
    if (key.startsWith('sokkia')) return 'sokkia'
    return 'leica'
  }

  // Send a brand-specific instrument command
  const sendCommand = useCallback(async (commandType: string, ...args: unknown[]) => {
    try {
      await hookSendCommand(commandType, ...args)
    } catch (err) {
      logger.error('Command failed:', { error: err })
    }
  }, [hookSendCommand])

  const toggleTracking = useCallback(async () => {
    const commandType = isTracking ? 'stopTracking' : 'startTracking'
    await sendCommand(commandType)
    setIsTracking(!isTracking)
  }, [isTracking, sendCommand])

  const handleConnect = async () => {
    setConnecting(true)
    try {
      await connectWithPreset(selectedPreset)
    } catch {
      // Error is handled by the hook
    } finally {
      setConnecting(false)
    }
  }

  const handleCustomConnect = async () => {
    setConnecting(true)
    try {
      await connect({ baudRate: parseInt(customBaud, 10) || 9600 })
    } catch {
      // Error is handled by the hook
    } finally {
      setConnecting(false)
    }
  }

  const handleImport = () => {
    if (points.length > 0 && onImportPoints) {
      onImportPoints(points)
    }
  }

  // Status color mapping
  const statusColors: Record<string, string> = {
    disconnected: 'text-gray-400',
    connecting: 'text-yellow-400',
    connected: 'text-blue-400',
    streaming: 'text-green-400',
    error: 'text-red-400',
    reconnecting: 'text-orange-400',
  }

  const statusBgColors: Record<string, string> = {
    disconnected: 'bg-gray-500/20 border-gray-600/30',
    connecting: 'bg-yellow-500/10 border-yellow-500/30',
    connected: 'bg-blue-500/10 border-blue-500/30',
    streaming: 'bg-green-500/10 border-green-500/30',
    error: 'bg-red-500/10 border-red-500/30',
    reconnecting: 'bg-orange-500/10 border-orange-500/30',
  }

  // ─── BLE connection handlers ──────────────────────────
  const handleBleScan = useCallback(async () => {
    setBleError(null)
    try {
      let service: CapacitorBLEGNSS | WebBluetoothGNSS
      if (isNative) {
        const ble = new CapacitorBLEGNSS()
        await ble.initialize()
        service = ble
      } else {
        service = new WebBluetoothGNSS()
      }
      setBleService(service)

      if (isNative && service instanceof CapacitorBLEGNSS) {
        const devices = await service.scanForDevices(5000)
        setBleScannedDevices(devices)
      } else if (service instanceof WebBluetoothGNSS) {
        const devices = await service.scanForDevices()
        setBleScannedDevices(
          devices.map((d) => ({
            deviceId: d.id,
            name: d.name,
            type: d.type === 'generic' ? 'unknown' as const : undefined,
          }))
        )
      }
    } catch (err) {
      setBleError((err as Error).message)
    }
  }, [isNative])

  const handleBleConnect = useCallback(async () => {
    if (!bleService || !bleSelectedDevice) return
    setBleConnecting(true)
    setBleError(null)
    try {
      // Set up position + connection callbacks before connecting
      bleService.onPosition((pos: NMEAPosition) => {
        instrumentStore.addPoint({
          id: `ble-${Date.now()}`,
          pointName: `PT${instrumentStore.points.length + 1}`,
          latitude: pos.latitude,
          longitude: pos.longitude,
          northing: 0,
          easting: 0,
          elevation: pos.altitude,
          timestamp: pos.timestamp,
          source: pos.quality >= 4 ? 'nmea' : 'nmea',
          quality: pos.quality,
          satellites: pos.satellites,
          hdop: pos.hdop,
        })
      })

      bleService.onConnectionChange((connected, err) => {
        if (connected) {
          const transport: ConnectionTransport = isNative ? 'capacitor-ble' : 'web-bluetooth'
          const device: InstrumentDevice = {
            id: bleSelectedDevice,
            name: bleScannedDevices.find(d => d.deviceId === bleSelectedDevice)?.name || 'Unknown',
            kind: 'gnss-receiver',
            transport,
          }
          instrumentStore.setConnected(device, transport)
          instrumentStore.setInstrumentInfo({
            manufacturer: device.name.split(' ')[0],
            protocol: 'nmea',
          })
        } else {
          instrumentStore.setDisconnected()
          if (err) setBleError(err)
        }
      })

      await bleService.connect(bleSelectedDevice)
    } catch (err) {
      setBleError((err as Error).message)
    } finally {
      setBleConnecting(false)
    }
  }, [bleService, bleSelectedDevice, bleScannedDevices, isNative, instrumentStore])

  const handleBleDisconnect = useCallback(async () => {
    if (bleService) {
      try {
        await bleService.disconnect()
      } catch { /* ignore */ }
    }
    instrumentStore.setDisconnected()
    setBleScannedDevices([])
    setBleSelectedDevice(null)
    setBleError(null)
  }, [bleService, instrumentStore])

  if (!isSupported && transportMode === 'serial') {
    return (
      <div className={`rounded-lg border border-yellow-600/30 bg-yellow-900/10 p-4 ${className}`}>
        <div className="flex items-center gap-2 mb-2">
          <WifiOff className="w-4 h-4 text-yellow-400" />
          <span className="text-sm font-medium text-yellow-300">Browser Not Supported</span>
        </div>
        <p className="text-xs text-yellow-200/70">
          The Web Serial API requires Google Chrome or Microsoft Edge.
          Switch to Bluetooth LE mode or use a supported browser.
        </p>
        <button
          onClick={() => setTransportMode('ble')}
          className="mt-2 text-xs text-blue-400 hover:text-blue-300"
        >
          Switch to Bluetooth LE →
        </button>
      </div>
    )
  }

  return (
    <div className={`rounded-lg border ${statusBgColors[status] || 'bg-gray-900/50 border-gray-700/50'} ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between p-3 border-b border-white/5">
        <div className="flex items-center gap-2">
          {transportMode === 'serial' ? (
            <Cable className="w-4 h-4 text-blue-400" />
          ) : (
            <Bluetooth className="w-4 h-4 text-blue-400" />
          )}
          <span className="text-sm font-medium">Instrument Connection</span>
        </div>
        <div className="flex items-center gap-2">
          {/* Transport toggle */}
          <div className="flex bg-black/20 rounded-md p-0.5">
            <button
              onClick={() => setTransportMode('serial')}
              className={`flex items-center gap-1 px-2 py-1 rounded text-[10px] transition-colors ${
                transportMode === 'serial'
                  ? 'bg-blue-600 text-white'
                  : 'text-gray-400 hover:text-gray-300'
              }`}
              title="USB Serial"
            >
              <Usb className="w-3 h-3" />
              Serial
            </button>
            <button
              onClick={() => setTransportMode('ble')}
              className={`flex items-center gap-1 px-2 py-1 rounded text-[10px] transition-colors ${
                transportMode === 'ble'
                  ? 'bg-blue-600 text-white'
                  : 'text-gray-400 hover:text-gray-300'
              }`}
              title="Bluetooth LE"
            >
              <Bluetooth className="w-3 h-3" />
              BLE
            </button>
          </div>
          <Circle
            className={`w-2 h-2 ${isStreaming ? 'fill-green-400 text-green-400 animate-pulse' : statusColors[status]}`}
          />
          <span className={`text-xs capitalize ${statusColors[status]}`}>
            {status === 'streaming' ? 'Live' : status}
          </span>
        </div>
      </div>

      <div className="p-3 space-y-3">
        {/* BLE Error */}
        {bleError && transportMode === 'ble' && (
          <p className="text-xs text-red-400 bg-red-900/20 rounded px-2 py-1">
            {bleError}
          </p>
        )}

        {/* ── BLE Mode ── */}
        {transportMode === 'ble' && status === 'disconnected' && (
          <>
            {!bleSelectedDevice && bleScannedDevices.length === 0 && (
              <button
                onClick={handleBleScan}
                className="w-full flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-500 text-white text-xs font-medium rounded-md px-4 py-2.5 transition-colors"
              >
                <Bluetooth className="w-3 h-3" />
                Scan for BLE Instruments
              </button>
            )}

            {bleScannedDevices.length > 0 && !bleSelectedDevice && (
              <div className="space-y-1.5">
                <div className="text-[9px] text-gray-400 uppercase tracking-wider">
                  Found {bleScannedDevices.length} device{bleScannedDevices.length !== 1 ? 's' : ''}
                </div>
                {bleScannedDevices.map((device) => (
                  <button
                    key={device.deviceId}
                    onClick={() => setBleSelectedDevice(device.deviceId)}
                    className="w-full p-2 text-left bg-black/20 border border-white/5 rounded-md hover:border-blue-500/30 transition-colors"
                  >
                    <div className="text-xs font-medium">{device.name}</div>
                    <div className="text-[9px] text-gray-400">
                      {device.deviceId.slice(0, 12)}… • {device.type || 'unknown'} • RSSI: {device.rssi ?? '—'}
                    </div>
                  </button>
                ))}
                <button
                  onClick={handleBleScan}
                  className="text-[9px] text-blue-400 hover:text-blue-300"
                >
                  Rescan
                </button>
              </div>
            )}

            {bleSelectedDevice && (
              <div className="space-y-2">
                <div className="p-2 bg-black/20 rounded-md">
                  <div className="text-xs font-medium">
                    {bleScannedDevices.find(d => d.deviceId === bleSelectedDevice)?.name || 'Unknown'}
                  </div>
                  <div className="text-[9px] text-gray-400">{bleSelectedDevice.slice(0, 16)}…</div>
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={handleBleConnect}
                    disabled={bleConnecting}
                    className="flex-1 flex items-center justify-center gap-1 bg-green-600 hover:bg-green-500 disabled:bg-green-600/50 text-white text-xs font-medium rounded-md px-3 py-2 transition-colors"
                  >
                    {bleConnecting ? (
                      <><Activity className="w-3 h-3 animate-spin" /> Connecting…</>
                    ) : (
                      <><Bluetooth className="w-3 h-3" /> Connect</>
                    )}
                  </button>
                  <button
                    onClick={() => setBleSelectedDevice(null)}
                    className="px-3 py-2 text-xs text-gray-400 border border-white/10 rounded-md"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            )}
          </>
        )}

        {/* BLE Connected State */}
        {transportMode === 'ble' && (status === 'connected' || status === 'streaming') && instrumentStore.device && (
          <>
            <div className="p-2 bg-green-500/10 border border-green-500/20 rounded-md">
              <div className="flex items-center gap-2">
                <Bluetooth className="w-3 h-3 text-green-400" />
                <span className="text-xs font-medium text-green-300">{instrumentStore.device.name}</span>
                <span className="text-[9px] text-gray-400 ml-auto">BLE</span>
              </div>
            </div>
            <div className="grid grid-cols-3 gap-2">
              <div className="bg-black/20 rounded-md p-2 text-center">
                <div className="text-lg font-mono font-bold text-blue-300">{instrumentStore.points.length}</div>
                <div className="text-[9px] text-gray-400 uppercase">Points</div>
              </div>
              <div className="bg-black/20 rounded-md p-2 text-center">
                <div className="text-lg font-mono font-bold text-green-300">{instrumentStore.metrics.messagesParsed}</div>
                <div className="text-[9px] text-gray-400 uppercase">Messages</div>
              </div>
              <div className="bg-black/20 rounded-md p-2 text-center">
                <div className="text-lg font-mono font-bold text-orange-300">{instrumentStore.metrics.errorsCount}</div>
                <div className="text-[9px] text-gray-400 uppercase">Errors</div>
              </div>
            </div>
            {instrumentStore.latestPoint && (
              <div className="bg-black/20 rounded-md p-2 border border-green-500/20">
                <div className="flex items-center gap-1 mb-1">
                  <Crosshair className="w-3 h-3 text-green-400" />
                  <span className="text-xs font-medium text-green-300">Latest Reading</span>
                </div>
                <div className="text-[9px] font-mono text-gray-300">
                  Lat: {instrumentStore.latestPoint.latitude.toFixed(7)} Lon: {instrumentStore.latestPoint.longitude.toFixed(7)}
                </div>
              </div>
            )}
            <div className="flex gap-2">
              <button
                onClick={() => handleBleDisconnect()}
                className="flex-1 flex items-center justify-center gap-1 bg-red-900/30 hover:bg-red-900/50 border border-red-700/30 text-red-300 text-xs rounded-md px-3 py-2 transition-colors"
              >
                <BluetoothOff className="w-3 h-3" />
                Disconnect
              </button>
              <button
                onClick={handleImport}
                disabled={instrumentStore.points.length === 0}
                className="flex-1 flex items-center justify-center gap-1 bg-green-900/30 hover:bg-green-900/50 border border-green-700/30 disabled:opacity-40 text-green-300 text-xs rounded-md px-3 py-2 transition-colors"
              >
                <Download className="w-3 h-3" />
                Import ({instrumentStore.points.length})
              </button>
            </div>
          </>
        )}

        {/* ── Serial Mode (existing UI) ── */}
        {transportMode === 'serial' && status === 'disconnected' && (
          <>
            <div>
              <label className="text-xs text-gray-400 uppercase tracking-wider mb-1 block" htmlFor="instrument-preset">
                Instrument Preset
              </label>
              <select id="instrument-preset"
                value={selectedPreset}
                onChange={(e) => setSelectedPreset(e.target.value)}
                className="w-full bg-black/30 border border-white/10 rounded-md px-3 py-2 text-xs focus:outline-none focus:border-blue-500/50"
              >
                {Object.entries(INSTRUMENT_PRESETS).map(([key, preset]) => (
                  <option key={key} value={key}>
                    {preset.name} ({preset.config.baudRate} baud)
                  </option>
                ))}
              </select>
            </div>

            {/* Custom Config Toggle */}
            <button
              onClick={() => setShowConfig(!showConfig)}
              className="flex items-center gap-1 text-xs text-gray-400 hover:text-gray-300 transition-colors"
            >
              <Settings className="w-3 h-3" />
              Advanced Configuration
              {showConfig ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
            </button>

            {showConfig && (
              <div className="space-y-2 p-2 rounded-md bg-black/20 border border-white/5">
                <div>
                  <label className="text-xs text-gray-400 mb-1 block" htmlFor="baud-rate">Baud Rate</label>
                  <select
                     id="baud-rate" value={customBaud}
                    onChange={(e) => setCustomBaud(e.target.value)}
                    className="w-full bg-black/30 border border-white/10 rounded px-2 py-1 text-xs"
                  >
                    {[4800, 9600, 19200, 38400, 57600, 115200].map(rate => (
                      <option key={rate} value={rate}>{rate}</option>
                    ))}
                  </select>
                </div>
                <button
                  onClick={handleCustomConnect}
                  disabled={connecting}
                  className="w-full text-xs text-blue-400 hover:text-blue-300 py-1"
                >
                  Connect with Custom Settings
                </button>
              </div>
            )}

            {/* Connect Button */}
            <button
              onClick={handleConnect}
              disabled={connecting}
              className="w-full flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-500 disabled:bg-blue-600/50 text-white text-xs font-medium rounded-md px-4 py-2.5 transition-colors"
            >
              {connecting ? (
                <>
                  <Activity className="w-3 h-3 animate-spin" />
                  Connecting...
                </>
              ) : (
                <>
                  <Cable className="w-3 h-3" />
                  Connect Instrument
                </>
              )}
            </button>

            {error && (
              <p className="text-xs text-red-400 bg-red-900/20 rounded px-2 py-1">
                {error}
              </p>
            )}
          </>
        )}

        {/* Connected / Streaming State — Serial mode only (BLE has its own above) */}
        {transportMode === 'serial' && (status === 'connected' || status === 'streaming') && (
          <>
            {/* Stats Grid */}
            <div className="grid grid-cols-3 gap-2">
              <div className="bg-black/20 rounded-md p-2 text-center">
                <div className="text-lg font-mono font-bold text-blue-300">{points.length}</div>
                <div className="text-[9px] text-gray-400 uppercase">Points</div>
              </div>
              <div className="bg-black/20 rounded-md p-2 text-center">
                <div className="text-lg font-mono font-bold text-green-300">{messagesParsed}</div>
                <div className="text-[9px] text-gray-400 uppercase">Messages</div>
              </div>
              <div className="bg-black/20 rounded-md p-2 text-center">
                <div className="text-lg font-mono font-bold text-orange-300">{errorCount}</div>
                <div className="text-[9px] text-gray-400 uppercase">Errors</div>
              </div>
            </div>

            {/* Instrument Info */}
            {instrumentInfo && (
              <div className="flex items-center gap-2 bg-black/20 rounded-md px-3 py-2">
                <Satellite className="w-3 h-3 text-purple-400" />
                <div>
                  <div className="text-xs font-medium">{instrumentInfo.manufacturer}</div>
                  <div className="text-[9px] text-gray-400">
                    Protocol: {instrumentInfo.protocol.toUpperCase()}
                    {instrumentInfo.model && ` / ${instrumentInfo.model}`}
                  </div>
                </div>
              </div>
            )}

            {/* Last Point Preview */}
            {lastPoint && (
              <div className="bg-black/20 rounded-md p-2 border border-green-500/20">
                <div className="flex items-center gap-1 mb-1">
                  <Crosshair className="w-3 h-3 text-green-400" />
                  <span className="text-xs font-medium text-green-300">
                    Latest: {lastPoint.pointName}
                  </span>
                </div>
                {lastPoint.source === 'nmea' ? (
                  <div className="text-[9px] font-mono text-gray-300 space-y-0.5">
                    <div>Lat: {lastPoint.latitude.toFixed(8)}&deg; Lng: {lastPoint.longitude.toFixed(8)}&deg;</div>
                    <div>Elev: {lastPoint.elevation !== null ? `${lastPoint.elevation.toFixed(3)}m` : 'N/A'}</div>
                    <div className="text-gray-400">
                      Quality: {lastPoint.quality} / Satellites: {lastPoint.satellites} / HDOP: {lastPoint.hdop?.toFixed(1)}
                    </div>
                  </div>
                ) : (
                  <div className="text-[9px] font-mono text-gray-300 space-y-0.5">
                    <div>N: {lastPoint.northing.toFixed(4)} E: {lastPoint.easting.toFixed(4)}</div>
                    {lastPoint.elevation !== null && <div>Elev: {lastPoint.elevation.toFixed(4)}m</div>}
                  </div>
                )}
              </div>
            )}

            {/* Instrument Commands */}
            <div className="space-y-1.5">
              <div className="text-[9px] text-gray-400 uppercase tracking-wider">Quick Commands</div>
              <div className="grid grid-cols-4 gap-1.5">
                <button
                  onClick={() => sendCommand('measureAndRecord')}
                  className="flex flex-col items-center gap-0.5 bg-blue-900/20 hover:bg-blue-900/40 border border-blue-700/20 text-blue-300 rounded-md px-2 py-1.5 text-[9px] transition-colors"
                  title="Measure and Record"
                >
                  <Target className="w-3.5 h-3.5" />
                  Measure
                </button>
                <button
                  onClick={() => sendCommand('getAngles')}
                  className="flex flex-col items-center gap-0.5 bg-purple-900/20 hover:bg-purple-900/40 border border-purple-700/20 text-purple-300 rounded-md px-2 py-1.5 text-[9px] transition-colors"
                  title="Read Angles"
                >
                  <RotateCcw className="w-3.5 h-3.5" />
                  Angles
                </button>
                <button
                  onClick={() => sendCommand('getCoordinate')}
                  className="flex flex-col items-center gap-0.5 bg-green-900/20 hover:bg-green-900/40 border border-green-700/20 text-green-300 rounded-md px-2 py-1.5 text-[9px] transition-colors"
                  title="Get Coordinate"
                >
                  <Ruler className="w-3.5 h-3.5" />
                  Coord
                </button>
                <button
                  onClick={() => toggleTracking()}
                  className={`flex flex-col items-center gap-0.5 rounded-md px-2 py-1.5 text-[9px] transition-colors ${
                    isTracking
                      ? 'bg-orange-900/30 border border-orange-500/30 text-orange-300'
                      : 'bg-gray-800/40 border border-gray-600/20 text-gray-300'
                  }`}
                  title={isTracking ? 'Stop Tracking' : 'Start Tracking'}
                >
                  {isTracking ? <Square className="w-3.5 h-3.5" /> : <Play className="w-3.5 h-3.5" />}
                  {isTracking ? 'Stop' : 'Track'}
                </button>
              </div>
              <div className="grid grid-cols-2 gap-1.5">
                <button
                  onClick={() => sendCommand('setPrismTarget', 0)}
                  className="bg-gray-800/30 hover:bg-gray-700/40 border border-gray-600/20 text-gray-300 rounded-md px-2 py-1 text-[9px] transition-colors"
                >
                  Prism Target
                </button>
                <button
                  onClick={() => sendCommand('setRLTarget')}
                  className="bg-gray-800/30 hover:bg-gray-700/40 border border-gray-600/20 text-gray-300 rounded-md px-2 py-1 text-[9px] transition-colors"
                >
                  Reflectorless
                </button>
              </div>
              {selectedPreset && (
                <div className="text-[8px] text-gray-500">
                  {BRAND_INFO[getBrandFromPresetKey(selectedPreset)]?.protocol || 'Auto-detect'}
                </div>
              )}
            </div>

            {/* Action Buttons */}
            <div className="flex gap-2">
              <button
                onClick={disconnect}
                className="flex-1 flex items-center justify-center gap-1 bg-red-900/30 hover:bg-red-900/50 border border-red-700/30 text-red-300 text-xs rounded-md px-3 py-2 transition-colors"
              >
                <WifiOff className="w-3 h-3" />
                Disconnect
              </button>
              <button
                onClick={handleImport}
                disabled={points.length === 0}
                className="flex-1 flex items-center justify-center gap-1 bg-green-900/30 hover:bg-green-900/50 border border-green-700/30 disabled:opacity-40 text-green-300 text-xs rounded-md px-3 py-2 transition-colors"
              >
                <Download className="w-3 h-3" />
                Import ({points.length})
              </button>
              <button
                onClick={clearPoints}
                disabled={points.length === 0}
                className="flex items-center justify-center bg-gray-800 hover:bg-gray-700 border border-gray-600/30 disabled:opacity-40 text-gray-300 text-xs rounded-md px-2 py-2 transition-colors"
                title="Clear points"
              >
                <Trash2 className="w-3 h-3" />
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  )
}

'use client';

import { useState } from 'react'
import { Calculator, Plus, Trash2, CheckCircle, XCircle, AlertCircle, Clock, FileText } from 'lucide-react'
import { computeAdversePossession, getRequiredEvidenceTypes } from '@/lib/compute/adversePossession'
import type { AdversePossessionAnalysis, AdversePossessionEvidenceInput } from '@/lib/compute/adversePossession'

export default function AdversePossessionCalc() {
  const [parcelId, setParcelId] = useState('')
  const [startDate, setStartDate] = useState('')
  const [endDate, setEndDate] = useState('')
  const [evidence, setEvidence] = useState<AdversePossessionEvidenceInput[]>([])
  const [analysis, setAnalysis] = useState<AdversePossessionAnalysis | null>(null)

  const evidenceTypes = getRequiredEvidenceTypes()

  const addEvidence = (type: AdversePossessionEvidenceInput['type']) => {
    setEvidence([
      ...evidence,
      {
        type,
        description: '',
        date: startDate || new Date().toISOString().split('T')[0]
      }
    ])
  }

  const updateEvidence = (index: number, field: keyof AdversePossessionEvidenceInput, value: string) => {
    const updated = [...evidence]
    updated[index] = { ...updated[index], [field]: value }
    setEvidence(updated)
  }

  const removeEvidence = (index: number) => {
    setEvidence(evidence.filter((_, i) => i !== index))
  }

  const handleCalculate = () => {
    if (!parcelId || !startDate) return

    const result = computeAdversePossession({
      parcelId,
      startDate,
      endDate: endDate || undefined,
      evidence
    })
    setAnalysis(result)
  }

  const getStrengthColor = (strength: string) => {
    switch (strength) {
      case 'STRONG': return 'text-green-600 bg-green-50'
      case 'MODERATE': return 'text-yellow-600 bg-yellow-50'
      case 'WEAK': return 'text-red-600 bg-red-50'
      default: return 'text-gray-600 bg-gray-50'
    }
  }

  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-r from-indigo-50 to-purple-50 rounded-lg p-4 border border-indigo-200">
        <h3 className="font-semibold text-indigo-900 flex items-center gap-2">
          <Calculator className="w-5 h-5" />
          Adverse Possession Calculator
        </h3>
        <p className="text-sm text-indigo-700 mt-1">
          Calculate whether you meet requirements for acquiring land through adverse possession under Kenyan law
        </p>
      </div>

      <div className="grid md:grid-cols-2 gap-6">
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1" htmlFor="parcel-id-lr-number">
              Parcel ID / LR Number
            </label>
            <input id="parcel-id-lr-number"
              type="text"
              value={parcelId}
              onChange={e => setParcelId(e.target.value)}
 placeholder="e.g., NAIROBI BLOCK 2/1234"
              className="w-full p-2 border rounded-lg"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1" htmlFor="possession-start-date">
                Possession Start Date
              </label>
              <input id="possession-start-date" aria-label="Possession Start Date"
                type="date"
                value={startDate}
                onChange={e => setStartDate(e.target.value)}
                className="w-full p-2 border rounded-lg"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1" htmlFor="end-date-if-ended">
                End Date (if ended)
              </label>
              <input id="end-date-if-ended" aria-label="End Date (if ended)"
                type="date"
                value={endDate}
                onChange={e => setEndDate(e.target.value)}
                className="w-full p-2 border rounded-lg"
              />
            </div>
          </div>

          <div>
            <div className="flex items-center justify-between mb-2">
              <div className="block text-sm font-medium text-gray-700">
                Evidence Collection
              </div>
              <span className="text-xs text-gray-500">Add evidence to strengthen your case</span>
            </div>

            <div className="flex flex-wrap gap-2 mb-3">
              {evidenceTypes.map((type) => (
                <button
                  key={type.type}
                  onClick={() => addEvidence(type.type as AdversePossessionEvidenceInput['type'])}
                  className={`text-xs px-2 py-1 rounded-full border ${
                    type.priority === 'HIGH'
                      ? 'border-red-300 text-red-700 hover:bg-red-50'
                      : type.priority === 'MEDIUM'
                      ? 'border-yellow-300 text-yellow-700 hover:bg-yellow-50'
                      : 'border-gray-300 text-gray-700 hover:bg-gray-50'
                  }`}
                >
                  + {type.type.replace('_', ' ')}
                </button>
              ))}
            </div>

            <div className="space-y-2 max-h-64 overflow-y-auto">
              {evidence.map((ev, index) => (
                <div key={`${ev}-${index}`} className="p-3 bg-gray-50 rounded-lg border">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-sm font-medium">{ev.type.replace('_', ' ')}</span>
                    <button
                      onClick={() => removeEvidence(index)}
                      className="text-red-500 hover:text-red-700"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    <input aria-label="Date"
                      type="date"
                      value={ev.date}
                      onChange={e => updateEvidence(index, 'date', e.target.value)}
                      className="text-sm p-1 border rounded"
                    />
                    <input
                      type="text"
                      value={ev.description}
                      onChange={e => updateEvidence(index, 'description', e.target.value)}
                      aria-label="Description of evidence"
                      className="text-sm p-1 border rounded"
                    />
                  </div>
                </div>
              ))}
            </div>
          </div>

          <button
            onClick={handleCalculate}
            disabled={!parcelId || !startDate}
            className="w-full py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50"
          >
            Calculate Adverse Possession
          </button>
        </div>

        <div>
          {analysis ? (
            <div className="space-y-4">
              <div className={`p-4 rounded-lg border ${
                analysis.meetsRequirements 
                  ? 'bg-green-50 border-green-300' 
                  : analysis.duration >= 10
                  ? 'bg-yellow-50 border-yellow-300'
                  : 'bg-red-50 border-red-300'
              }`}>
                <div className="flex items-center gap-3">
                  {analysis.meetsRequirements ? (
                    <CheckCircle className="w-8 h-8 text-green-600" />
                  ) : analysis.duration >= 10 ? (
                    <Clock className="w-8 h-8 text-yellow-600" />
                  ) : (
                    <XCircle className="w-8 h-8 text-red-600" />
                  )}
                  <div>
                    <h4 className="font-semibold">
                      {analysis.meetsRequirements 
                        ? 'Ready to File!' 
                        : analysis.duration >= 10
                        ? 'Case Developing'
                        : 'Not Eligible Yet'}
                    </h4>
                    <p className="text-sm">
                      {analysis.duration} years of possession • {analysis.yearsRemaining} years remaining
                    </p>
                  </div>
                </div>
                <p className="mt-3 text-sm">{analysis.recommendation}</p>
              </div>

              <div className="flex items-center gap-2 p-3 bg-gray-100 rounded-lg">
                <FileText className="w-5 h-5 text-gray-600" />
                <span className="text-sm font-medium">Evidence Strength: </span>
                <span className={`px-2 py-0.5 rounded text-sm font-medium ${getStrengthColor(analysis.strength)}`}>
                  {analysis.strength}
                </span>
              </div>

              <div className="space-y-2">
                <h4 className="font-medium text-gray-700">Requirements Analysis</h4>
                {analysis.requirements.map((req, index) => (
                  <div key={req.name} className="p-3 border rounded-lg">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        {req.met ? (
                          <CheckCircle className="w-4 h-4 text-green-600" />
                        ) : (
                          <XCircle className="w-4 h-4 text-red-500" />
                        )}
                        <span className="font-medium text-sm">{req.name}</span>
                      </div>
                      <span className={`text-xs px-2 py-0.5 rounded ${getStrengthColor(req.strength)}`}>
                        {req.strength}
                      </span>
                    </div>
                    {req.evidence.length > 0 && (
                      <ul className="mt-2 ml-6 text-xs text-gray-600">
                        {req.evidence.map((ev, i) => (
                          <li key={`${ev}-${i}`}>• {ev}</li>
                        ))}
                      </ul>
                    )}
                  </div>
                ))}
              </div>

              <div className="space-y-2">
                <h4 className="font-medium text-gray-700">Analysis Steps</h4>
                {analysis.steps.map((step, index) => (
                  <div key={step.title} className="flex items-start gap-3 p-2">
                    <div className={`w-6 h-6 rounded-full flex items-center justify-center text-xs ${
                      step.passed ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                    }`}>
                      {step.passed ? '' : '[x]'}
                    </div>
                    <div className="flex-1">
                      <p className="text-sm font-medium">{step.title}</p>
                      <p className="text-xs text-gray-600">{step.description}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div className="text-center py-12 text-gray-500">
              <Calculator className="w-12 h-12 mx-auto mb-3 opacity-50" />
              <p>Enter details and add evidence to calculate</p>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { useSession } from 'next-auth/react'
import {
  FolderKanban, Wrench, Compass, FileText,
  LayoutDashboard, Users, ShieldCheck, CreditCard,
  Settings2, Activity, ChevronLeft, BarChart3,
  Map, Building2, HelpCircle, LayoutTemplate, Boxes,
  RoadIcon, Mountain, Sparkles,
} from 'lucide-react'
import { cn } from '@/lib/utils'
import { OutdoorModeToggle } from '@/components/shared/OutdoorModeToggle'
import MetarduLogo from '@/components/MetarduLogo'

// ---------------------------------------------------------------------------
// Navigation items by role
// ---------------------------------------------------------------------------

interface NavItem {
  href: string
  label: string
  icon: React.ComponentType<{ className?: string }>
  exact?: boolean
  hash?: string
}

const userNavItems: NavItem[] = [
  { href: '/dashboard', label: 'Dashboard', icon: LayoutDashboard },
  { href: '/cadastral-workflow', label: 'Cadastral', icon: Compass },
  { href: '/engineering-workflow', label: 'Engineering', icon: RoadIcon },
  { href: '/topographic-workflow', label: 'Topographic', icon: Mountain },
  { href: '/projects', label: 'Projects', icon: FolderKanban },
  { href: '/process', label: 'Corrections', icon: Wrench },
  { href: '/tools/all', label: 'Toolbox', icon: Boxes },
  { href: '/tools/cogo', label: 'COGO', icon: Compass },
  { href: '/map', label: 'Map', icon: Map },
  { href: '/documents', label: 'Documents', icon: FileText },
  { href: '/report-templates', label: 'Templates', icon: LayoutTemplate },
  { href: '/sectional', label: 'Sectional', icon: Building2 },
  { href: '/analytics', label: 'Analytics', icon: BarChart3 },
  { href: '/assistant', label: 'Assistant', icon: Sparkles },
  { href: '/help', label: 'Help', icon: HelpCircle },
]

const adminNavItems: NavItem[] = [
  { href: '/admin', label: 'Dashboard', icon: LayoutDashboard, exact: true },
  { href: '/admin/users', label: 'Users', icon: Users },
  { href: '/admin/payments', label: 'Payments', icon: CreditCard },
  { href: '/audit-logs', label: 'Audit Logs', icon: ShieldCheck },
  { href: '/admin', label: 'System Health', icon: Settings2, hash: '#system' },
  { href: '/analytics', label: 'Analytics', icon: BarChart3 },
]

// ---------------------------------------------------------------------------
// Sidebar component
// ---------------------------------------------------------------------------

interface AppSidebarProps {
  variant: 'user' | 'admin'
  className?: string
  onNavigate?: () => void
}

export default function AppSidebar({ variant, className, onNavigate }: AppSidebarProps) {
  const pathname = usePathname()
  const { data: session } = useSession()

  const navItems = variant === 'admin' ? adminNavItems : userNavItems
  const userRole = (session?.user as { role?: string })?.role ?? ''

  return (
    <aside
      className={cn(
        'h-full flex flex-col bg-[var(--bg-secondary)] border-r border-[var(--border-color)]',
        className,
      )}
    >
      {/* Logo */}
      <div className="flex items-center justify-between px-4 py-4 border-b border-[var(--border-color)]">
        <Link
          href="/"
          onClick={onNavigate}
          className="flex items-center gap-2 no-underline"
        >
          <MetarduLogo size={28} showWordmark={true} color="var(--text-primary)" />
        </Link>
      </div>

      {/* Navigation */}
      <nav className="flex-1 p-3 space-y-0.5 overflow-y-auto">
        {navItems.map((item) => {
          const isActive = item.exact
            ? pathname === item.href
            : item.hash
              ? pathname === item.href && typeof window !== 'undefined' && window.location.hash === item.hash
              : pathname.startsWith(item.href)

          const href = item.hash ? `${item.href}${item.hash}` : item.href

          return (
            <Link
              key={`${item.href}${item.hash ?? ''}`}
              href={href}
              onClick={onNavigate}
              className={cn(
                'flex items-center gap-3 px-3 py-2 rounded-md text-sm transition-colors no-underline',
                isActive
                  ? 'bg-[var(--accent)] text-[var(--bg-primary)] font-medium'
                  : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)]',
              )}
            >
              <item.icon className="w-4 h-4 shrink-0" />
              {item.label}
            </Link>
          )
        })}
      </nav>

      {/* Footer */}
      <div className="p-3 border-t border-[var(--border-color)] space-y-1">
        {/* Outdoor mode toggle */}
        <div className="flex items-center justify-between px-3 py-1.5">
          <span className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider">
            Outdoor Mode
          </span>
          <OutdoorModeToggle />
        </div>
        {/* Role badge */}
        <div className="px-3 py-1.5">
          <p className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider">
            {variant === 'admin' ? 'Admin Panel' : 'Kenya Cadastral'}
          </p>
          <p className="text-xs text-[var(--text-secondary)] capitalize">{userRole || 'Surveyor'}</p>
        </div>

        {/* Switch between admin/user dashboards */}
        {variant === 'admin' ? (
          <Link
            href="/dashboard"
            onClick={onNavigate}
            className="flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)] transition-colors no-underline"
          >
            <ChevronLeft className="w-4 h-4" />
            Back to App
          </Link>
        ) : (
          (userRole === 'super_admin' || userRole === 'admin' || userRole === 'org_admin') && (
            <Link
              href="/admin"
              onClick={onNavigate}
              className="flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm text-[var(--accent)] hover:bg-[var(--accent)]/5 transition-colors no-underline"
            >
              <ShieldCheck className="w-4 h-4" />
              Admin Panel
            </Link>
          )
        )}
      </div>
    </aside>
  )
}

'use client';

import { useState } from 'react'
import { computeLevelBook } from '@/lib/computations/traverseEngine'
import { printLevelBookSheet, type LevelBookPrintInput } from '@/lib/print/levelBookPrint'
import { PrintMetaPanel, defaultPrintMeta, type PrintMeta } from '@/components/shared/PrintMetaPanel'

interface LevelBookProps {
  projectId?: string
}

export default function LevelBook({ projectId }: LevelBookProps) {
  const [rows, setRows] = useState<Array<{
    station: string; bs: string; is: string; fs: string; distance: string; remarks: string
  }>>([
    { station: 'BM1', bs: '1.523', is: '', fs: '', distance: '', remarks: 'Benchmark' },
    { station: '1',   bs: '',      is: '', fs: '1.234', distance: '', remarks: '' },
    { station: '2',   bs: '',      is: '1.456', fs: '', distance: '', remarks: 'IS' },
    { station: '3',   bs: '',      is: '', fs: '1.789', distance: '', remarks: '' },
    { station: '4',   bs: '',      is: '1.234', fs: '', distance: '', remarks: 'IS' },
    { station: '5',   bs: '',      is: '', fs: '1.567', distance: '', remarks: '' },
  ])
  const [openingRL,   setOpeningRL]   = useState('100.000')
  const [closingRL,   setClosingRL]   = useState('')
  const [distanceKm,  setDistanceKm]  = useState('0.5')
  const [method,      setMethod]      = useState<'rise_and_fall' | 'height_of_collimation'>('rise_and_fall')
  const [result,      setResult]      = useState<ReturnType<typeof computeLevelBook> | null>(null)
  const [error,       setError]       = useState('')
  const [activeTab,   setActiveTab]   = useState<'input' | 'compute' | 'print'>('input')
  const [printMeta,   setPrintMeta]   = useState<PrintMeta>(defaultPrintMeta)

  const addRow = () => setRows(prev => [
    ...prev,
    { station: String(prev.length + 1), bs: '', is: '', fs: '', distance: '', remarks: '' }
  ])

  const removeRow = (i: number) => setRows(prev => prev.filter((_, idx) => idx !== i))

  const updateRow = (i: number, field: string, value: string) =>
    setRows(prev => prev.map((r, idx) => idx === i ? { ...r, [field]: value } : r))

  const handleCompute = () => {
    setError('')
    if (!openingRL) { setError('Enter opening benchmark RL'); return }
    const obsRows = rows.map(r => ({
      station:  r.station,
      bs:       r.bs       ? parseFloat(r.bs)       : undefined,
      is:       r.is       ? parseFloat(r.is)        : undefined,
      fs:       r.fs       ? parseFloat(r.fs)        : undefined,
      distance: r.distance ? parseFloat(r.distance)  : undefined,
      remarks:  r.remarks,
    }))
    try {
      const res = computeLevelBook({
        openingRL:  parseFloat(openingRL),
        closingRL:  closingRL ? parseFloat(closingRL) : undefined,
        distanceKm: parseFloat(distanceKm) || 0.5,
        method,
        rows: obsRows,
      })
      setResult(res)
      setActiveTab('compute')
    } catch (err: unknown) {
      setError((err as Error).message || 'Computation failed')
    }
  }

  const handlePrint = () => {
    if (!result) return
    const inp: LevelBookPrintInput = {
      result,
      meta: { ...printMeta, title: `Level Book — ${method === 'rise_and_fall' ? 'Rise & Fall' : 'Height of Collimation'}` }
    }
    printLevelBookSheet(inp)
  }

  // ── RENDER ─────────────────────────────────────────────────────────────────
  return (
    <div className="space-y-4">

      {/* Tabs + Method switch */}
      <div className="flex items-center gap-2 border-b border-[var(--border-color)] pb-2 flex-wrap">
        {(['input', 'compute', 'print'] as const).map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)}
            className={`px-3 py-1.5 rounded text-sm font-medium capitalize transition-colors ${
              activeTab === tab
                ? 'bg-[var(--accent)] text-black'
                : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)] hover:bg-[var(--border-hover)]'
            }`}>
            {tab === 'input' ? 'Field Book' : tab === 'compute' ? 'Results' : 'Print'}
          </button>
        ))}
        <div className="flex-1" />
        <button
          onClick={() => { setMethod('rise_and_fall'); setResult(null) }}
          className={`px-3 py-1.5 rounded text-xs font-medium transition-colors ${
            method === 'rise_and_fall'
              ? 'bg-[var(--accent)] text-black'
              : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'
          }`}>
          Rise &amp; Fall
        </button>
        <button
          onClick={() => { setMethod('height_of_collimation'); setResult(null) }}
          className={`px-3 py-1.5 rounded text-xs font-medium transition-colors ${
            method === 'height_of_collimation'
              ? 'bg-[var(--accent)] text-black'
              : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'
          }`}>
          Height of Collimation
        </button>
      </div>

      {error && (
        <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{error}</div>
      )}

      {/* ── INPUT TAB ──────────────────────────────────────────────────────── */}
      {activeTab === 'input' && (
        <div className="space-y-4">
          {/* Setup fields */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 p-3 md:p-4 bg-[var(--bg-tertiary)]/50 rounded border border-[var(--border-color)]">
            <div>
              <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="opening-bm-rl-m">Opening BM RL (m)</label>
              <input id="opening-bm-rl-m" aria-label="Opening BM RL (m)" value={openingRL} onChange={e => setOpeningRL(e.target.value)}
                type="number" step="0.001"
                className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
            </div>
            <div>
              <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="closing-bm-rl-m">Closing BM RL (m)</label>
              <input id="closing-bm-rl-m" value={closingRL} onChange={e => setClosingRL(e.target.value)}
                type="number" step="0.001" placeholder="Optional"
                className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
            </div>
            <div>
              <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="total-distance-km">Total Distance (km)</label>
              <input  id="total-distance-km" aria-label="Total Distance (km)" value={distanceKm} onChange={e => setDistanceKm(e.target.value)}
                type="number" step="0.001"
                className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
            </div>
          </div>

          {/* Field book table */}
          <div className="overflow-x-auto -mx-4 px-4 sm:mx-0 sm:px-0">
            <table className="min-w-[700px] w-full text-xs">
              <thead>
                <tr className="border-b border-[var(--border-color)] bg-[var(--bg-tertiary)]/30">
                  <th className="px-1.5 py-2 text-left text-[var(--text-muted)] w-8">#</th>
                  <th className="px-1.5 py-2 text-left text-[var(--text-secondary)]">Station</th>
                  <th className="px-1.5 py-2 text-right text-[var(--text-secondary)]">BS</th>
                  <th className="px-1.5 py-2 text-right text-[var(--text-secondary)]">IS</th>
                  <th className="px-1.5 py-2 text-right text-[var(--text-secondary)]">FS</th>
                  <th className="px-1.5 py-2 text-right text-[var(--text-secondary)]">Dist (m)</th>
                  <th className="px-1.5 py-2 text-left text-[var(--text-secondary)]">Remarks</th>
                  <th className="w-6"></th>
                </tr>
              </thead>
              <tbody>
                {rows.map((row, i) => (
                  <tr key={row.station} className="border-b border-[var(--border-color)]/30">
                    <td className="px-1.5 py-1 text-[var(--text-muted)]">{i + 1}</td>
                    <td className="px-1 py-1">
                      <input value={row.station} onChange={e => updateRow(i, 'station', e.target.value)}
                        aria-label="Station" placeholder="BM1"
                        className="w-full px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.bs} onChange={e => updateRow(i, 'bs', e.target.value)}
                        type="number" step="0.001" aria-label="Backsight (m)" placeholder="0.000"
                        className="w-16 px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.is} onChange={e => updateRow(i, 'is', e.target.value)}
                        type="number" step="0.001" aria-label="Intermediate sight (m)" placeholder="0.000"
                        className="w-16 px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.fs} onChange={e => updateRow(i, 'fs', e.target.value)}
                        type="number" step="0.001" aria-label="Foresight (m)" placeholder="0.000"
                        className="w-16 px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.distance} onChange={e => updateRow(i, 'distance', e.target.value)}
                        type="number" step="0.01" aria-label="Distance (m)" placeholder="0.00"
                        className="w-16 px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.remarks} onChange={e => updateRow(i, 'remarks', e.target.value)}
                        aria-label="Remarks" placeholder="IS / BM / CP"
                        className="w-full px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td>
                      <button onClick={() => removeRow(i)}
                        className="text-red-400 hover:text-red-300 text-lg leading-none px-1">×</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <button onClick={addRow}
            className="px-3 py-1.5 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded text-xs">
            + Add Row
          </button>

          <div className="flex justify-end">
            <button onClick={handleCompute}
              className="px-6 py-2.5 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded text-sm">
              Compute Level Book →
            </button>
          </div>
        </div>
      )}

      {/* ── RESULTS TAB ────────────────────────────────────────────────────── */}
      {activeTab === 'compute' && result && (
        <div className="space-y-4">

          {/* Closure summary cards */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            <div className="bg-[var(--bg-tertiary)]/50 rounded p-3">
              <p className="text-xs text-[var(--text-secondary)]">ΣBS</p>
              <p className="text-lg font-mono">{result.sumBS.toFixed(3)} m</p>
            </div>
            <div className="bg-[var(--bg-tertiary)]/50 rounded p-3">
              <p className="text-xs text-[var(--text-secondary)]">ΣFS</p>
              <p className="text-lg font-mono">{result.sumFS.toFixed(3)} m</p>
            </div>
            <div className={`rounded p-3 ${result.arithmeticPass ? 'bg-green-900/30' : 'bg-red-900/30'}`}>
              <p className="text-xs text-[var(--text-secondary)]">Arithmetic Check</p>
              <p className={`text-lg font-semibold ${result.arithmeticPass ? 'text-green-400' : 'text-red-400'}`}>
                {result.arithmeticPass ? 'PASS' : 'FAIL'}
              </p>
            </div>
            <div className={`rounded p-3 ${result.isAcceptable ? 'bg-green-900/30' : 'bg-red-900/30'}`}>
              <p className="text-xs text-[var(--text-secondary)]">Closure (10√K mm)</p>
              <p className={`text-lg font-semibold ${result.isAcceptable ? 'text-green-400' : 'text-red-400'}`}>
                {result.isAcceptable ? 'OK' : 'FAIL'}
              </p>
            </div>
          </div>

          <p className="text-xs text-[var(--text-muted)] font-mono">{result.formula}</p>

          {/* Results table — HPC not HI */}
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-[var(--border-color)] bg-[var(--bg-tertiary)]/50">
                  <th className="px-2 py-2 text-left">Station</th>
                  <th className="px-2 py-2 text-right">BS</th>
                  <th className="px-2 py-2 text-right">IS</th>
                  <th className="px-2 py-2 text-right">FS</th>
                  {/* HPC = Height of Plane of Collimation — British/East African convention */}
                  <th className="px-2 py-2 text-right">HPC (m)</th>
                  {method === 'rise_and_fall' && <th className="px-2 py-2 text-right">Rise</th>}
                  {method === 'rise_and_fall' && <th className="px-2 py-2 text-right">Fall</th>}
                  <th className="px-2 py-2 text-right">RL (m)</th>
                </tr>
              </thead>
              <tbody>
                {result.rows.map((row, i) => (
                  <tr key={`item-${i}`} className="border-b border-[var(--border-color)]/30">
                    <td className="px-2 py-1.5 font-mono">{row.station}</td>
                    <td className="px-2 py-1.5 text-right font-mono text-[var(--text-secondary)]">
                      {row.bs !== undefined ? row.bs.toFixed(3) : ''}
                    </td>
                    <td className="px-2 py-1.5 text-right font-mono text-[var(--text-secondary)]">
                      {row.is !== undefined ? row.is.toFixed(3) : ''}
                    </td>
                    <td className="px-2 py-1.5 text-right font-mono text-[var(--text-secondary)]">
                      {row.fs !== undefined ? row.fs.toFixed(3) : ''}
                    </td>
                    <td className="px-2 py-1.5 text-right font-mono text-[var(--text-secondary)]">
                      {/* row.hi is the data property (Height of Collimation value); displayed as HPC */}
                      {row.hi !== undefined ? row.hi.toFixed(3) : ''}
                    </td>
                    {method === 'rise_and_fall' && (
                      <td className="px-2 py-1.5 text-right font-mono text-green-400">
                        {row.rise !== undefined ? row.rise.toFixed(3) : ''}
                      </td>
                    )}
                    {method === 'rise_and_fall' && (
                      <td className="px-2 py-1.5 text-right font-mono text-red-400">
                        {row.fall !== undefined ? row.fall.toFixed(3) : ''}
                      </td>
                    )}
                    <td className="px-2 py-1.5 text-right font-mono font-bold text-[var(--accent)]">
                      {row.rl !== undefined ? row.rl.toFixed(3) : ''}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="flex justify-between">
            <button onClick={() => setActiveTab('input')}
              className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded text-sm">
              ← Back to Input
            </button>
            <button onClick={() => setActiveTab('print')}
              className="px-5 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded text-sm">
              Print Sheet →
            </button>
          </div>
        </div>
      )}

      {/* ── PRINT TAB ──────────────────────────────────────────────────────── */}
      {activeTab === 'print' && (
        <div className="space-y-4">
          {!result && (
            <div className="p-4 bg-amber-900/20 border border-amber-700 rounded text-amber-300 text-sm">
              Compute the level book first (Field Book tab) before printing.
            </div>
          )}

          <PrintMetaPanel meta={printMeta} onChange={setPrintMeta} />

          <div className="p-4 bg-[var(--bg-tertiary)]/50 rounded border border-[var(--border-color)] text-sm space-y-1.5">
            <p className="font-semibold text-[var(--text-primary)]">The printed sheet will include:</p>
            <ul className="text-[var(--text-muted)] text-xs space-y-0.5 list-disc list-inside">
              <li>Standard 6-field document header (project · client · date · surveyor · reg/ISK · instrument)</li>
              <li>Table 1 — Field Observations (Station, BS, IS, FS, HPC, Rise, Fall, RL, Dist, Remarks)</li>
              <li>Table 2 — Arithmetic Checks &amp; Closure (ΣBS, ΣFS, ΣRise, ΣFall, 10√K misclosure)</li>
              <li>Surveyor&apos;s Certificate block — Survey Regulations 1994, Regulation 3(2)</li>
            </ul>
            <p className="text-xs text-[var(--text-muted)] font-mono mt-2">
              HPC = Height of Plane of Collimation (British/East African convention)
            </p>
          </div>

          <button
            onClick={handlePrint}
            disabled={!result}
            className="w-full py-3 bg-[var(--accent)] hover:bg-[var(--accent-dim)] disabled:opacity-40 disabled:cursor-not-allowed text-black font-bold rounded text-sm">
            Print Level Book Computation Sheet
          </button>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState } from 'react';
import { Ruler, Square, Compass, MapPin, X, Check } from 'lucide-react';
import { useMeasurement, type MeasurementMode } from '@/hooks/useMeasurement';
import type Map from 'ol/Map';

interface MeasurementToolProps {
  map: Map | null;
}

export function MeasurementTool({ map }: MeasurementToolProps) {
  const {
    state,
    startMeasurement,
    finishAreaMeasurement,
    cancelMeasurement,
    clearMeasurement,
    getFormattedResult,
  } = useMeasurement(map);

  const [hoverTool, setHoverTool] = useState<MeasurementMode | null>(null);

  const tools: Array<{
    mode: MeasurementMode;
    icon: React.ReactNode;
    label: string;
    description: string;
  }> = [
    {
      mode: 'distance',
      icon: <Ruler className="w-5 h-5" />,
      label: 'Distance',
      description: 'Click two points to measure distance',
    },
    {
      mode: 'area',
      icon: <Square className="w-5 h-5" />,
      label: 'Area',
      description: 'Click points to draw polygon, then finish',
    },
    {
      mode: 'bearing',
      icon: <Compass className="w-5 h-5" />,
      label: 'Bearing',
      description: 'Click two points to measure bearing',
    },
    {
      mode: 'coordinate',
      icon: <MapPin className="w-5 h-5" />,
      label: 'Coordinate',
      description: 'Click to get coordinate',
    },
  ];

  const handleToolClick = (mode: MeasurementMode) => {
    if (state.isActive && state.mode !== mode) {
      cancelMeasurement();
    }
    startMeasurement(mode);
  };

  const result = getFormattedResult();

  return (
    <div className="bg-white rounded-lg shadow-lg border w-56">
      <div className="flex items-center border-b">
        {tools.map((tool) => (
          <button
            key={tool.mode}
            onClick={() => handleToolClick(tool.mode)}
            onMouseEnter={() => setHoverTool(tool.mode)}
            onMouseLeave={() => setHoverTool(null)}
            className={[
              'flex-1 p-2 flex flex-col items-center gap-1 transition-colors',
              state.mode === tool.mode && state.isActive
                ? 'bg-blue-600 text-white'
                : 'hover:bg-gray-100',
            ].join(' ')}
            title={tool.description}
          >
            {tool.icon}
            <span className="text-[10px]">{tool.label}</span>
          </button>
        ))}
      </div>

      {state.isActive && (
        <div className="px-3 py-2 bg-blue-50 text-xs text-blue-700">
          {state.mode === 'distance' && state.points.length === 0 && 'Click first point'}
          {state.mode === 'distance' && state.points.length === 1 && 'Click second point'}
          {state.mode === 'area' && state.points.length < 3 && `Click points (${state.points.length}/3 min)`}
          {state.mode === 'area' && state.points.length >= 3 && `${state.points.length} pts - Finish or add`}
          {state.mode === 'bearing' && state.points.length === 0 && 'Click first point'}
          {state.mode === 'bearing' && state.points.length === 1 && 'Click second point'}
          {state.mode === 'coordinate' && 'Click to get coordinate'}
        </div>
      )}

      {result && (
        <div className="px-4 py-3 border-t">
          <div className="flex items-center justify-between">
            <div>
              <div className="text-[10px] text-gray-500 uppercase">{result.type}</div>
              <div className="text-base font-semibold font-mono">
                {result.formatted}
              </div>
            </div>
            <button
              onClick={clearMeasurement}
              className="p-1.5 hover:bg-gray-100 rounded"
              title="Clear"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {state.points.length > 0 && (
            <div className="mt-2 text-[10px] text-gray-500">
              {state.points.map((p, i) => (
                <div key={`${p}-${i}`}>Pt {i + 1}: E {p.easting.toFixed(0)} N {p.northing.toFixed(0)}</div>
              ))}
            </div>
          )}
        </div>
      )}

      {state.isActive && !result && (
        <div className="px-4 py-2 border-t">
          {state.mode === 'area' && state.points.length >= 3 ? (
            <button
              onClick={finishAreaMeasurement}
              className="w-full py-1.5 bg-green-600 text-white text-sm rounded flex items-center justify-center gap-1"
            >
              <Check className="w-4 h-4" />
              Finish
            </button>
          ) : (
            <button
              onClick={cancelMeasurement}
              className="w-full py-1.5 text-sm text-red-600 hover:bg-red-50 rounded"
            >
              Cancel
            </button>
          )}
        </div>
      )}
    </div>
  );
}

'use client'

/**
 * AttributeTable — Spreadsheet view of parcel/beacon data
 *
 * Inspired by QGIS Attribute Table. Shows all features in a project
 * as rows with their attributes as columns. Supports:
 * - Inline editing of attribute values
 * - Sort by any column
 * - Filter/search
 * - Select row to highlight on map
 * - Bulk operations (delete, export)
 * - Add new parcels from the table
 */

import { useState, useMemo, useCallback } from 'react'
import {
  Search, ArrowUpDown, Trash2, Download, Plus,
  CheckCircle2, AlertTriangle, MapPin,
} from 'lucide-react'

export interface AttributeRow {
  id: string
  parcelNumber: string
  ownerName: string
  lrNumber: string
  areaHa: number
  perimeterM: number
  beaconCount: number
  status: 'registered' | 'pending' | 'disputed' | 'cancelled'
  easting: number  // centroid
  northing: number
}

interface AttributeTableProps {
  rows: AttributeRow[]
  onSelectRow?: (row: AttributeRow) => void
  onDeleteRow?: (id: string) => void
  onExport?: () => void
}

type SortField = keyof AttributeRow
type SortDirection = 'asc' | 'desc'

const STATUS_COLORS: Record<string, string> = {
  registered: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30',
  pending: 'bg-amber-500/10 text-amber-400 border-amber-500/30',
  disputed: 'bg-red-500/10 text-red-400 border-red-500/30',
  cancelled: 'bg-gray-500/10 text-gray-400 border-gray-500/30',
}

export function AttributeTable({ rows, onSelectRow, onDeleteRow, onExport }: AttributeTableProps) {
  const [query, setQuery] = useState('')
  const [sortField, setSortField] = useState<SortField>('parcelNumber')
  const [sortDir, setSortDir] = useState<SortDirection>('asc')
  const [selectedRows, setSelectedRows] = useState<Set<string>>(new Set())
  const [editingCell, setEditingCell] = useState<{ id: string; field: string } | null>(null)
  const [editValue, setEditValue] = useState('')

  // Filter
  const filteredRows = useMemo(() => {
    if (!query.trim()) return rows
    const q = query.toLowerCase()
    return rows.filter(r =>
      r.parcelNumber.toLowerCase().includes(q) ||
      r.ownerName.toLowerCase().includes(q) ||
      r.lrNumber.toLowerCase().includes(q) ||
      r.status.toLowerCase().includes(q)
    )
  }, [rows, query])

  // Sort
  const sortedRows = useMemo(() => {
    const sorted = [...filteredRows].sort((a, b) => {
      const aVal = a[sortField]
      const bVal = b[sortField]
      if (typeof aVal === 'number' && typeof bVal === 'number') {
        return sortDir === 'asc' ? aVal - bVal : bVal - aVal
      }
      const aStr = String(aVal || '')
      const bStr = String(bVal || '')
      return sortDir === 'asc' ? aStr.localeCompare(bStr) : bStr.localeCompare(aStr)
    })
    return sorted
  }, [filteredRows, sortField, sortDir])

  const handleSort = useCallback((field: SortField) => {
    if (sortField === field) {
      setSortDir(prev => prev === 'asc' ? 'desc' : 'asc')
    } else {
      setSortField(field)
      setSortDir('asc')
    }
  }, [sortField])

  const toggleRowSelection = useCallback((id: string) => {
    setSelectedRows(prev => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }, [])

  const selectAll = useCallback(() => {
    if (selectedRows.size === sortedRows.length) {
      setSelectedRows(new Set())
    } else {
      setSelectedRows(new Set(sortedRows.map(r => r.id)))
    }
  }, [selectedRows, sortedRows])

  const handleCellEdit = useCallback((id: string, field: string, currentValue: string) => {
    setEditingCell({ id, field })
    setEditValue(currentValue)
  }, [])

  const saveCellEdit = useCallback(() => {
    // In a real implementation, this would call an API to update the record
    setEditingCell(null)
    setEditValue('')
  }, [])

  const columns: Array<{ key: SortField; label: string; width: string; align?: 'left' | 'right' | 'center' }> = [
    { key: 'parcelNumber', label: 'Parcel No.', width: '120px' },
    { key: 'ownerName', label: 'Owner', width: '150px' },
    { key: 'lrNumber', label: 'LR Number', width: '120px' },
    { key: 'areaHa', label: 'Area (ha)', width: '90px', align: 'right' },
    { key: 'perimeterM', label: 'Perimeter (m)', width: '100px', align: 'right' },
    { key: 'beaconCount', label: 'Beacons', width: '70px', align: 'center' },
    { key: 'status', label: 'Status', width: '100px', align: 'center' },
  ]

  return (
    <div className="card overflow-hidden">
      {/* Toolbar */}
      <div className="flex items-center justify-between p-3 border-b border-[var(--border-color)]">
        <div className="flex items-center gap-2">
          <span className="text-sm font-semibold text-[var(--text-primary)]">
            Attribute Table
          </span>
          <span className="text-[10px] text-gray-500">
            {sortedRows.length} of {rows.length} parcels
          </span>
          {selectedRows.size > 0 && (
            <span className="text-[10px] text-[var(--accent)]">
              {selectedRows.size} selected
            </span>
          )}
        </div>

        <div className="flex items-center gap-2">
          {/* Search */}
          <div className="relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-500" />
            <input
              type="text"
              value={query}
              onChange={e => setQuery(e.target.value)}
              aria-label="Filter..."
              className="h-7 pl-7 pr-2 w-40 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
            />
          </div>

          {/* Export */}
          {onExport && (
            <button
              onClick={onExport}
              className="flex items-center gap-1 px-2.5 h-7 rounded-lg bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-xs text-gray-400 hover:text-gray-200"
            >
              <Download className="w-3.5 h-3.5" />
              Export
            </button>
          )}

          {/* Bulk delete */}
          {selectedRows.size > 0 && onDeleteRow && (
            <button
              onClick={() => {
                selectedRows.forEach(id => onDeleteRow(id))
                setSelectedRows(new Set())
              }}
              className="flex items-center gap-1 px-2.5 h-7 rounded-lg bg-red-500/10 border border-red-500/30 text-xs text-red-400 hover:bg-red-500/20"
            >
              <Trash2 className="w-3.5 h-3.5" />
              Delete ({selectedRows.size})
            </button>
          )}
        </div>
      </div>

      {/* Table */}
      <div className="overflow-x-auto max-h-[400px] overflow-y-auto">
        <table className="w-full">
          <thead className="sticky top-0 bg-[var(--bg-card)] z-10">
            <tr className="border-b border-[var(--border-color)]">
              <th className="px-2 py-2 w-8">
                <input aria-label="Select all rows"
                  type="checkbox"
                  checked={selectedRows.size === sortedRows.length && sortedRows.length > 0}
                  onChange={selectAll}
                  className="w-3.5 h-3.5 rounded border-[var(--border-color)] accent-[var(--accent)]"
                />
              </th>
              {columns.map(col => (
                <th
                  key={col.key}
                  onClick={() => handleSort(col.key)}
                  className={`px-2 py-2 cursor-pointer hover:bg-white/[0.04] transition-colors ${
                    col.align === 'right' ? 'text-right' : col.align === 'center' ? 'text-center' : 'text-left'
                  }`}
                  style={{ width: col.width }}
                >
                  <div className={`flex items-center gap-1 ${col.align === 'right' ? 'justify-end' : col.align === 'center' ? 'justify-center' : ''}`}>
                    <span className="text-[9px] text-gray-500 uppercase tracking-wider font-semibold">{col.label}</span>
                    <ArrowUpDown className={`w-2.5 h-2.5 ${sortField === col.key ? 'text-[var(--accent)]' : 'text-gray-600'}`} />
                  </div>
                </th>
              ))}
              <th className="px-2 py-2 w-8"></th>
            </tr>
          </thead>
          <tbody>
            {sortedRows.length === 0 ? (
              <tr>
                <td colSpan={columns.length + 2} className="px-4 py-8 text-center">
                  <MapPin className="w-8 h-8 text-gray-600 mx-auto mb-2" />
                  <p className="text-sm text-gray-500">No parcels found</p>
                  <p className="text-[10px] text-gray-600 mt-1">Import parcels or adjust your filter</p>
                </td>
              </tr>
            ) : (
              sortedRows.map(row => (
                <tr
                  key={row.id}
                  onClick={() => onSelectRow?.(row)}
                  className={`border-b border-[var(--border-color)]/30 cursor-pointer transition-colors ${
                    selectedRows.has(row.id) ? 'bg-[var(--accent)]/5' : 'hover:bg-white/[0.02]'
                  }`}
                >
                  <td className="px-2 py-1.5" onClick={(e) => { e.stopPropagation(); toggleRowSelection(row.id) }}>
                    <input aria-label="Select row"
                      type="checkbox"
                      checked={selectedRows.has(row.id)}
                      onChange={() => toggleRowSelection(row.id)}
                      className="w-3.5 h-3.5 rounded border-[var(--border-color)] accent-[var(--accent)]"
                    />
                  </td>
                  {columns.map(col => (
                    <td
                      key={col.key}
                      className={`px-2 py-1.5 text-xs ${
                        col.align === 'right' ? 'text-right font-mono' : col.align === 'center' ? 'text-center' : ''
                      }`}
                      onDoubleClick={() => handleCellEdit(row.id, col.key, String(row[col.key] || ''))}
                    >
                      {editingCell?.id === row.id && editingCell.field === col.key ? (
                        <input aria-label="Search filter"
                          // eslint-disable-next-line jsx-a11y/no-autofocus -- focus into the editing cell (inline edit)
                          autoFocus
                          type="text"
                          value={editValue}
                          onChange={e => setEditValue(e.target.value)}
                          onBlur={saveCellEdit}
                          onKeyDown={e => { if (e.key === 'Enter') saveCellEdit(); if (e.key === 'Escape') setEditingCell(null) }}
                          className="w-full h-6 px-1 bg-white border border-[var(--accent)] rounded text-xs text-black"
                        />
                      ) : col.key === 'status' ? (
                        <span className={`inline-flex items-center px-1.5 py-0.5 rounded text-[9px] font-medium border ${STATUS_COLORS[row[col.key]]}`}>
                          {row[col.key]}
                        </span>
                      ) : col.key === 'areaHa' || col.key === 'perimeterM' ? (
                        <span className="text-[var(--text-secondary)]">
                          {typeof row[col.key] === 'number' ? (row[col.key] as number).toFixed(col.key === 'areaHa' ? 4 : 2) : ''}
                        </span>
                      ) : (
                        <span className="text-[var(--text-primary)]">{row[col.key]}</span>
                      )}
                    </td>
                  ))}
                  <td className="px-2 py-1.5">
                    {onDeleteRow && (
                      <button
                        onClick={(e) => { e.stopPropagation(); onDeleteRow(row.id) }}
                        className="w-6 h-6 flex items-center justify-center rounded text-gray-500 hover:text-red-400 hover:bg-red-500/5"
                      >
                        <Trash2 className="w-3 h-3" />
                      </button>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Footer */}
      <div className="flex items-center justify-between p-2 border-t border-[var(--border-color)] text-[10px] text-gray-500">
        <span>
          {sortedRows.length} parcel{sortedRows.length !== 1 ? 's' : ''}
          {selectedRows.size > 0 && ` · ${selectedRows.size} selected`}
        </span>
        <span>Double-click any cell to edit</span>
      </div>
    </div>
  )
}

'use client'

import { useEffect, useRef, useState, useCallback, useMemo } from 'react'
import Konva from 'konva'
import { shoelaceArea } from '@/lib/engine/area'
import { formatBearingDegMinSec, bearingFromDelta, distance } from '@/lib/reports/surveyPlan/geometry'

export interface ParcelVertex {
  id: string
  label: string
  easting: number
  northing: number
}

export type DrawingMode = 'draw' | 'edit' | 'select'

export interface ParcelCanvasProps {
  width?: number
  height?: number
  /** Initial parcels (pre-defined boundaries to show as reference) */
  existingParcels?: Array<{
    id: string
    vertices: ParcelVertex[]
    fill?: string
    stroke?: string
  }>
  /** Currently selected parcel being edited */
  activeParcel?: ParcelVertex[]
  /** Drawing mode */
  mode?: DrawingMode
  /** CRS origin for coordinate display */
  originEasting?: number
  originNorthing?: number
  /** Called when the user finishes drawing (closes polygon or clicks Done) */
  onParcelComplete?: (vertices: ParcelVertex[]) => void
  /** Called on every vertex add */
  onVerticesChange?: (vertices: ParcelVertex[]) => void
  /** Whether to show live area while drawing */
  showLiveArea?: boolean
  /** Whether to show bearing/distance labels on legs */
  showLegAnnotations?: boolean
  className?: string
}

interface CanvasTransform {
  scale: number
  originE: number
  originN: number
}

function computeTransform(
  vertices: ParcelVertex[],
  canvasWidth: number,
  canvasHeight: number,
  padding = 60
): CanvasTransform {
  if (vertices.length === 0) {
    return { scale: 1, originE: 0, originN: 0 }
  }

  const eastings = vertices.map(v => v.easting)
  const northings = vertices.map(v => v.northing)

  const minE = Math.min(...eastings)
  const maxE = Math.max(...eastings)
  const minN = Math.min(...northings)
  const maxN = Math.max(...northings)

  const rangeE = maxE - minE || 1
  const rangeN = maxN - minN || 1

  const availW = canvasWidth - padding * 2
  const availH = canvasHeight - padding * 2

  const scale = Math.min(availW / rangeE, availH / rangeN, 50)

  const originE = minE - (availW / scale - rangeE) / 2 - padding / scale
  const originN = maxN + (availH / scale - rangeN) / 2 + padding / scale

  return { scale, originE, originN }
}

function w2c(
  e: number,
  n: number,
  t: CanvasTransform,
  canvasHeight: number
): { x: number; y: number } {
  return {
    x: (e - t.originE) * t.scale,
    y: canvasHeight - (n - t.originN) * t.scale,
  }
}

const BEACON_RADIUS = 6
const BEACON_COLOR = '#E63946'
const VERTEX_RADIUS = 5
const VERTEX_COLOR = '#1B3A5C'
const EDGE_COLOR = '#1B3A5C'
const PREVIEW_EDGE_COLOR = '#6BA3D6'
const AREA_BOX_COLOR = '#F0F4F8'
const AREA_TEXT_COLOR = '#1B3A5C'

function formatArea(sqM: number): string {
  if (sqM >= 10000) return `${(sqM / 10000).toFixed(4)} Ha`
  if (sqM >= 1) return `${sqM.toFixed(2)} m²`
  return `${(sqM * 10000).toFixed(4)} m²`
}

export default function ParcelCanvas({
  width = 800,
  height = 600,
  existingParcels = [],
  activeParcel = [],
  mode = 'draw',
  originEasting = 0,
  originNorthing = 0,
  onParcelComplete,
  onVerticesChange,
  showLiveArea = true,
  showLegAnnotations = true,
  className = '',
}: ParcelCanvasProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const stageRef = useRef<Konva.Stage | null>(null)
  const layerRef = useRef<Konva.Layer | null>(null)

  const [vertices, setVertices] = useState<ParcelVertex[]>(activeParcel)
  const [hoveredVertex, setHoveredVertex] = useState<string | null>(null)
  const [selectedVertex, setSelectedVertex] = useState<string | null>(null)
  const [mouseWorld, setMouseWorld] = useState<{ e: number; n: number } | null>(null)

  const t = useMemo(
    () => computeTransform(vertices, width, height),
    [vertices, width, height]
  )

  const currentArea = useMemo(() => {
    if (vertices.length < 3) return 0
    return shoelaceArea(vertices.map(v => ({ easting: v.easting, northing: v.northing })))
  }, [vertices])

  const isClosed = vertices.length >= 3

  const legData = useMemo(() => {
    if (vertices.length < 2) return []
    const legs: Array<{
      from: ParcelVertex
      to: ParcelVertex
      bearing: string
      distance: number
      midX: number
      midY: number
    }> = []

    const pts = isClosed ? vertices : vertices
    for (let i = 0; i < pts.length; i++) {
      const a = pts[i]
      const b = pts[(i + 1) % pts.length]
      if (isClosed === false && i === pts.length - 1) break
      const bearing = bearingFromDelta(b.easting - a.easting, b.northing - a.northing)
      const dist = distance(a.easting, a.northing, b.easting, b.northing)
      const cA = w2c(a.easting, a.northing, t, height)
      const cB = w2c(b.easting, b.northing, t, height)
      legs.push({
        from: a,
        to: b,
        bearing: formatBearingDegMinSec(bearing),
        distance: dist,
        midX: (cA.x + cB.x) / 2,
        midY: (cA.y + cB.y) / 2,
      })
    }
    return legs
  }, [vertices, isClosed, t, height])

  const initStage = useCallback(() => {
    if (!containerRef.current) return

    const existing = containerRef.current.querySelector('.konva-container')
    if (existing) existing.remove()

    const stage = new Konva.Stage({
      container: containerRef.current,
      width,
      height,
    })
    stageRef.current = stage

    const layer = new Konva.Layer()
    stage.add(layer)
    layerRef.current = layer

    stage.on('mousemove', () => {
      const pos = stage.getPointerPosition()
      if (!pos) return
      const e = pos.x / t.scale + t.originE
      const n = (height - pos.y) / t.scale + t.originN
      setMouseWorld({ e, n })
    })

    stage.on('click', (e) => {
      if (mode !== 'draw') return

      const pos = stage.getPointerPosition()
      if (!pos) return

      const wE = pos.x / t.scale + t.originE
      const wN = (height - pos.y) / t.scale + t.originN

      const newVertex: ParcelVertex = {
        id: `v_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
        label: `P${vertices.length + 1}`,
        easting: Math.round(wE * 1000) / 1000,
        northing: Math.round(wN * 1000) / 1000,
      }

      const next = [...vertices, newVertex]
      setVertices(next)
      onVerticesChange?.(next)
    })

    return () => stage.destroy()
  }, [width, height, mode, t, vertices, onVerticesChange])

  useEffect(() => {
    const destroy = initStage()
    return () => { destroy?.() }
  }, [initStage])

  const draw = useCallback(() => {
    const layer = layerRef.current
    const stage = stageRef.current
    if (!layer || !stage) return

    layer.destroyChildren()

    layer.add(
      new Konva.Rect({
        x: 0,
        y: 0,
        width,
        height,
        fill: '#FAFCFF',
      })
    )

    if (mode === 'draw' && mouseWorld) {
      const mc = w2c(mouseWorld.e, mouseWorld.n, t, height)
      layer.add(
        new Konva.Circle({
          x: mc.x,
          y: mc.y,
          radius: 4,
          fill: PREVIEW_EDGE_COLOR,
          opacity: 0.6,
          dash: [3, 3],
        })
      )
    }

    for (const parcel of existingParcels) {
      if (parcel.vertices.length < 2) continue
      const pts = parcel.vertices.map(v => w2c(v.easting, v.northing, t, height))
      const flatPts = pts.flatMap(p => [p.x, p.y])

      const poly = new Konva.Line({
        points: flatPts,
        fill: parcel.fill || '#e8f4fd',
        stroke: parcel.stroke || '#94c3d9',
        strokeWidth: 1.5,
        closed: true,
        opacity: 0.7,
      })
      layer.add(poly)
    }

    if (vertices.length >= 2) {
      const pts = vertices.map(v => w2c(v.easting, v.northing, t, height))
      const flatPts = pts.flatMap(p => [p.x, p.y])

      layer.add(
        new Konva.Line({
          points: flatPts,
          stroke: isClosed ? EDGE_COLOR : PREVIEW_EDGE_COLOR,
          strokeWidth: isClosed ? 2 : 1.5,
          dash: isClosed ? [] : [6, 3],
          closed: isClosed,
        })
      )
    }

    if (mode === 'draw' && vertices.length >= 1) {
      const pts = vertices.map(v => w2c(v.easting, v.northing, t, height))
      const flatPts = pts.flatMap(p => [p.x, p.y])

      const previewLine: number[] = []
      const last = pts[pts.length - 1]
      if (!isClosed && mouseWorld) {
        previewLine.push(last.x, last.y)
        const mp = w2c(mouseWorld.e, mouseWorld.n, t, height)
        previewLine.push(mp.x, mp.y)
      }

      if (previewLine.length >= 4) {
        layer.add(
          new Konva.Line({
            points: previewLine,
            stroke: PREVIEW_EDGE_COLOR,
            strokeWidth: 1,
            dash: [4, 4],
          })
        )
      }
    }

    if (showLegAnnotations && isClosed) {
      for (const leg of legData) {
        const labelText = `${leg.bearing}\n${leg.distance.toFixed(3)}m`
        const label = new Konva.Text({
          x: leg.midX,
          y: leg.midY - 12,
          text: labelText,
          fontSize: 9,
          fill: '#555',
          fontFamily: 'monospace',
          align: 'center',
        })
        label.offsetX(label.width() / 2)
        layer.add(label)
      }
    }

    if (isClosed && showLiveArea) {
      const pts = vertices.map(v => w2c(v.easting, v.northing, t, height))
      const xs = pts.map(p => p.x)
      const ys = pts.map(p => p.y)
      const cx = xs.reduce((a, b) => a + b, 0) / xs.length
      const cy = ys.reduce((a, b) => a + b, 0) / ys.length

      const areaText = formatArea(currentArea)
      const labelW = areaText.length * 7 + 16
      const labelH = 22

      layer.add(
        new Konva.Rect({
          x: cx - labelW / 2,
          y: cy - labelH / 2,
          width: labelW,
          height: labelH,
          fill: AREA_BOX_COLOR,
          stroke: AREA_TEXT_COLOR,
          strokeWidth: 1,
          cornerRadius: 3,
        })
      )
      const areaLabel = new Konva.Text({
        x: cx,
        y: cy,
        text: areaText,
        fontSize: 12,
        fill: AREA_TEXT_COLOR,
        fontFamily: 'Calibri, sans-serif',
        fontStyle: 'bold',
        align: 'center',
      })
      areaLabel.offsetX(areaLabel.width() / 2)
      areaLabel.offsetY(areaLabel.height() / 2)
      layer.add(areaLabel)
    }

    for (let i = 0; i < vertices.length; i++) {
      const v = vertices[i]
      const c = w2c(v.easting, v.northing, t, height)
      const isHov = hoveredVertex === v.id
      const isSel = selectedVertex === v.id

      const group = new Konva.Group({ x: c.x, y: c.y })

      if (isSel || isHov || mode === 'edit') {
        group.add(
          new Konva.Circle({
            x: 0,
            y: 0,
            radius: BEACON_RADIUS + (isHov || isSel ? 3 : 0),
            fill: isSel ? '#E63946' : BEACON_COLOR,
            stroke: isSel ? '#fff' : isHov ? '#1B3A5C' : 'transparent',
            strokeWidth: isSel ? 2 : 1,
          })
        )
      } else {
        group.add(
          new Konva.Circle({
            x: 0,
            y: 0,
            radius: VERTEX_RADIUS,
            fill: VERTEX_COLOR,
          })
        )
      }

      if (mode === 'edit') {
        group.add(
          new Konva.Text({
            x: BEACON_RADIUS + 4,
            y: -10,
            text: v.label,
            fontSize: 10,
            fill: '#333',
            fontFamily: 'monospace',
          })
        )
      }

      group.on('mouseenter', () => {
        setHoveredVertex(v.id)
        stage.container().style.cursor = 'pointer'
      })
      group.on('mouseleave', () => {
        setHoveredVertex(null)
        stage.container().style.cursor = 'default'
      })
      group.on('click', (evt) => {
        evt.cancelBubble = true
        if (mode === 'edit') {
          setSelectedVertex(selectedVertex === v.id ? null : v.id)
        }
      })

      if (mode === 'edit') {
        let dragStart = { e: 0, n: 0 }
        group.draggable(true)
        group.on('dragstart', () => {
          dragStart = { e: v.easting, n: v.northing }
        })
        group.on('dragmove', () => {
          const pos = group.position()
          const newE = pos.x / t.scale + t.originE
          const newN = (height - pos.y) / t.scale + t.originN
          const updated = vertices.map(vx =>
            vx.id === v.id
              ? { ...vx, easting: Math.round(newE * 1000) / 1000, northing: Math.round(newN * 1000) / 1000 }
              : vx
          )
          setVertices(updated)
          onVerticesChange?.(updated)
        })
        group.on('dragend', () => {
          const pos = group.position()
          const newE = pos.x / t.scale + t.originE
          const newN = (height - pos.y) / t.scale + t.originN
          const updated = vertices.map(vx =>
            vx.id === v.id
              ? { ...vx, easting: Math.round(newE * 1000) / 1000, northing: Math.round(newN * 1000) / 1000 }
              : vx
          )
          setVertices(updated)
          onVerticesChange?.(updated)
        })
      }

      layer.add(group)
    }

    layer.draw()
  }, [
    vertices, t, width, height, isClosed, currentArea, mode,
    hoveredVertex, selectedVertex, mouseWorld, existingParcels,
    showLegAnnotations, legData, showLiveArea, onVerticesChange,
  ])

  useEffect(() => {
    draw()
  }, [draw])

  const handleCloseParcel = () => {
    if (vertices.length >= 3) {
      onParcelComplete?.(vertices)
    }
  }

  const handleUndo = () => {
    const next = vertices.slice(0, -1)
    setVertices(next)
    onVerticesChange?.(next)
  }

  const handleClear = () => {
    setVertices([])
    onVerticesChange?.([])
  }

  const handleDeleteVertex = () => {
    if (!selectedVertex) return
    const next = vertices.filter(v => v.id !== selectedVertex)
    setVertices(next)
    setSelectedVertex(null)
    onVerticesChange?.(next)
  }

  return (
    <div className={className}>
      <div className="relative">
        <div ref={containerRef} className="w-full h-full" />

        {mouseWorld && mode === 'draw' && (
          <div
            className="absolute top-2 right-2 bg-white/90 border border-gray-200 rounded px-2 py-1 text-xs font-mono text-gray-700 pointer-events-none"
          >
            E{mouseWorld.e.toFixed(3)} N{mouseWorld.n.toFixed(3)}
          </div>
        )}

        <div className="absolute bottom-2 left-2 bg-white/90 border border-gray-200 rounded px-3 py-1.5 text-xs font-mono text-[#1B3A5C]">
          {mode === 'draw' && (
            <span>
              {vertices.length === 0
                ? 'Click to place first vertex'
                : vertices.length === 1
                ? 'Click to add more vertices'
                : `${vertices.length} vertices — ${isClosed ? 'Parcel closed' : 'Click to add or close'}`}
            </span>
          )}
          {mode === 'edit' && (
            <span>
              {selectedVertex ? `Selected: ${vertices.find(v => v.id === selectedVertex)?.label}` : 'Click a vertex to select, drag to move'}
            </span>
          )}
        </div>

        {isClosed && showLiveArea && (
          <div className="absolute top-2 left-2 bg-white border border-[#1B3A5C] rounded px-3 py-1.5 text-sm font-semibold text-[#1B3A5C]">
            Area: {formatArea(currentArea)}
          </div>
        )}
      </div>

      <div className="flex items-center gap-2 mt-2">
        {mode === 'draw' && (
          <>
            <button
              onClick={handleUndo}
              disabled={vertices.length === 0}
              className="px-3 py-1.5 text-xs bg-gray-100 hover:bg-gray-200 disabled:opacity-40 rounded border border-gray-300 text-gray-700"
            >
              Undo
            </button>
            <button
              onClick={handleClear}
              disabled={vertices.length === 0}
              className="px-3 py-1.5 text-xs bg-gray-100 hover:bg-gray-200 disabled:opacity-40 rounded border border-gray-300 text-gray-700"
            >
              Clear
            </button>
            <button
              onClick={handleCloseParcel}
              disabled={vertices.length < 3}
              className="px-3 py-1.5 text-xs bg-[#1B3A5C] hover:bg-[#142d49] disabled:opacity-40 rounded text-white font-semibold"
            >
              Done — Close Parcel
            </button>
          </>
        )}
        {mode === 'edit' && (
          <>
            <button
              onClick={handleDeleteVertex}
              disabled={!selectedVertex}
              className="px-3 py-1.5 text-xs bg-red-50 hover:bg-red-100 disabled:opacity-40 rounded border border-red-200 text-red-700"
            >
              Delete Vertex
            </button>
            <button
              onClick={() => { setSelectedVertex(null); setVertices([]); onVerticesChange?.([]) }}
              className="px-3 py-1.5 text-xs bg-gray-100 hover:bg-gray-200 rounded border border-gray-300 text-gray-700"
            >
              Clear
            </button>
            <button
              onClick={handleCloseParcel}
              disabled={vertices.length < 3}
              className="px-3 py-1.5 text-xs bg-[#1B3A5C] hover:bg-[#142d49] disabled:opacity-40 rounded text-white font-semibold"
            >
              Save Parcel
            </button>
          </>
        )}
      </div>
    </div>
  )
}

'use client';

import React from 'react'

/* ──────────────────────────────────────────────────────────────────────
 *  PremiumIcons — Custom SVG icon set for METARDU Map
 *
 *  Design system:
 *    - 20x20 viewBox with 2px stroke, stroke-linecap="round", stroke-linejoin="round"
 *    - Linear gradients with brand orange (#D17B47) → lighter (#FFB84D)
 *    - Fill icons use subtle gradient fills
 *    - All icons are 20x20 by default, accept className for sizing
 * ────────────────────────────────────────────────────────────────────── */

const GRADIENT_DEFS = (
  <>
    <defs>
      <linearGradient id="icon-gradient-primary" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stopColor="#FFB84D" />
        <stop offset="100%" stopColor="#D17B47" />
      </linearGradient>
      <linearGradient id="icon-gradient-orange" x1="0%" y1="0%" x2="0%" y2="100%">
        <stop offset="0%" stopColor="#FFB84D" />
        <stop offset="100%" stopColor="#D17B47" />
      </linearGradient>
      <linearGradient id="icon-gradient-muted" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stopColor="#6b7280" />
        <stop offset="100%" stopColor="#4b5563" />
      </linearGradient>
      <linearGradient id="icon-gradient-danger" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stopColor="#f87171" />
        <stop offset="100%" stopColor="#ef4444" />
      </linearGradient>
      <linearGradient id="icon-gradient-success" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stopColor="#4ade80" />
        <stop offset="100%" stopColor="#22c55e" />
      </linearGradient>
      <linearGradient id="icon-gradient-blue" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stopColor="#60a5fa" />
        <stop offset="100%" stopColor="#3b82f6" />
      </linearGradient>
    </defs>
  </>
)

interface IconProps {
  className?: string
  active?: boolean
}

const sb = { strokeWidth: 1.75, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const }

/* ── MapPin: Location marker ────────────────────────────────────────── */
export function MapPinIcon({ className = 'w-5 h-5', active }: IconProps) {
  const stroke = active ? 'url(#icon-gradient-primary)' : 'currentColor'
  return (
    <svg viewBox="0 0 20 20" fill="none" className={className}>
      {GRADIENT_DEFS}
      <path
        d="M10 18s-7-5.5-7-10a7 7 0 1114 0c0 4.5-7 10-7 10z"
        stroke={stroke} {...sb}
      />
      <circle cx="10" cy="8" r="2.5" stroke={stroke} {...sb} />
    </svg>
  )
}

/* ── Pencil: Drawing / edit tool ────────────────────────────────────── */
export function PencilIcon({ className = 'w-5 h-5', active }: IconProps) {
  const stroke = active ? 'url(#icon-gradient-primary)' : 'currentColor'
  return (
    <svg viewBox="0 0 20 20" fill="none" className={className}>
      {GRADIENT_DEFS}
      <path
        d="M12.5 2.5l5 5-10 10H2.5v-5l10-10z"
        stroke={stroke} {...sb}
      />
      <path d="M10 5l5 5" stroke={stroke} {...sb} />
    </svg>
  )
}

/* ── Hexagon: Polygon shape ─────────────────────────────────────────── */
export function HexagonIcon({ className = 'w-5 h-5', active }: IconProps) {
  const stroke = active ? 'url(#icon-gradient-primary)' : 'currentColor'
  return (
    <svg viewBox="0 0 20 20" fill="none" className={className}>
      {GRADIENT_DEFS}
      <path
        d="M10 1.5l7.5 4.33v8.34L10 18.5 2.5 14.17V5.83L10 1.5z"
        stroke={stroke} {...sb}
      />
    </svg>
  )
}

/* ── Circle: Circle shape ───────────────────────────────────────────── */
export function CircleIcon({ className = 'w-5 h-5', active }: IconProps) {
  const stroke = active ? 'url(#icon-gradient-primary)' : 'currentColor'
  return (
    <svg viewBox="0 0 20 20" fill="none" className={className}>
      {GRADIENT_DEFS}
      <circle cx="10" cy="10" r="8" stroke={stroke} {...sb} />
    </svg>
  )
}

/* ── Globe: Basemap / world ─────────────────────────────────────────── */
export function GlobeIcon({ className = 'w-5 h-5', active }: IconProps) {
  const stroke = active ? 'url(#icon-gradient-primary)' : 'currentColor'
  return (
    <svg viewBox="0 0 20 20" fill="none" className={className}>
      {GRADIENT_DEFS}
      <circle cx="10" cy="10" r="8" stroke={stroke} {...sb} />
      <ellipse cx="10" cy="10" rx="3.5" ry="8" stroke={stroke} {...sb} />
      <path d="M2 10h16" stroke={stroke} {...sb} />
      <path d="M3 6h14" stroke={stroke} {...sb} />
      <path d="M3 14h14" stroke={stroke} {...sb} />
