}

/* ── Satellite: Satellite imagery basemap ───────────────────────────── */
export function SatelliteIcon({ className = 'w-5 h-5', active }: IconProps) {
  const stroke = active ? 'url(#icon-gradient-primary)' : 'currentColor'
  return (
