/* ------------------------------------------------------------------ */
/*  Main SheetLayout component                                         */
/* ------------------------------------------------------------------ */

export default function SheetLayout({
  show,
  map,
  planGeometry,
  lrNumber,
  projectName,
  surveyorName,
  surveyorLicense,
  clientName,
  county,
}: SheetLayoutProps) {
  const [resolution, setResolution] = useState(0);
  const [containerSize, setContainerSize] = useState({ w: 0, h: 0 });
  const [gridTicks, setGridTicks] = useState<{
    top: GridTick[];
    bottom: GridTick[];
    left: GridTick[];
    right: GridTick[];
  }>({ top: [], bottom: [], left: [], right: [] });
  const [viewExtent21037, setViewExtent21037] = useState<{
    minE: number;
    maxE: number;
    minN: number;
    maxN: number;
  } | null>(null);

  /* ── Observe map size and resolution ────────────────────────────── */
  useEffect(() => {
    if (!map || !show) return;

    const updateSize = () => {
      const target = map.getTargetElement();
      if (target) {
        setContainerSize({ w: target.clientWidth, h: target.clientHeight });
      }
    };

    const updateResolution = () => {
      const view = map.getView();
      setResolution(view.getResolution() ?? 0);
    };

    // Observe map target resize
    const resizeObserver = new ResizeObserver(() => updateSize());
    const target = map.getTargetElement();
    if (target) {
      resizeObserver.observe(target);
      updateSize();
    }

    // Observe view changes (zoom/pan)
    const view = map.getView();
    view.on('change:resolution', updateResolution);
    view.on('change:center', () => {
      updateResolution();
    });

    updateResolution();

    return () => {
      resizeObserver.disconnect();
      view.un('change:resolution', updateResolution);
      view.un('change:center', updateResolution);
    };
  }, [map, show]);

  /* ── Compute grid ticks when view changes ──────────────────────── */
  const computeGridTicks = useCallback(async () => {
    if (!map || !show || containerSize.w === 0) return;

    const view = map.getView();
    const extent3857 = view.calculateExtent(map.getSize());
    const [x1, y1, x2, y2] = extent3857;

    // Convert corners to EPSG:21037
    const [[e1, n1], [e2, n2]] = await Promise.all([
      to21037(x1, y1),
      to21037(x2, y2),
    ]);

    const minE = Math.min(e1, e2);
    const maxE = Math.max(e1, e2);
    const minN = Math.min(n1, n2);
    const maxN = Math.max(n1, n2);

    setViewExtent21037({ minE, maxE, minN, maxN });

    const rangeE = maxE - minE;
    const rangeN = maxN - minN;

    const stepE = niceStep(rangeE, 6);
    const stepN = niceStep(rangeN, 6);

    const startE = roundTo(minE, stepE);
    const startN = roundTo(minN, stepN);

    // Horizontal ticks (bottom/top — E values)
    const ticksH: GridTick[] = [];
    for (let e = startE; e <= maxE + stepE * 0.01; e += stepE) {
      const frac = (e - minE) / rangeE;
      const px = frac * containerSize.w;
      if (px >= -5 && px <= containerSize.w + 5) {
        ticksH.push({ px, value: e, label: `E ${formatCoord(e)}` });
      }
    }

    // Vertical ticks (left/right — N values)
    const ticksV: GridTick[] = [];
    for (let n = startN; n <= maxN + stepN * 0.01; n += stepN) {
      const frac = 1 - (n - minN) / rangeN; // Invert because screen Y is down
      const px = frac * containerSize.h;
      if (px >= -5 && px <= containerSize.h + 5) {
        ticksV.push({ px, value: n, label: `N ${formatCoord(n)}` });
      }
    }

    setGridTicks({
      top: ticksH,
      bottom: ticksH,
      left: ticksV,
      right: ticksV,
    });
  }, [map, show, containerSize]);

  useEffect(() => {
    computeGridTicks();
  }, [computeGridTicks]);

  /* ── Scale bar ──────────────────────────────────────────────────── */
  const scaleBar = useMemo(() => {
    if (resolution <= 0) return { mapMeters: 0, pxLength: 0, label: '' };
    return niceScaleBar(resolution, 200);
  }, [resolution]);

  /* ── Scale label (e.g. "1:1000") ───────────────────────────────── */
  const scaleLabel = planGeometry ? `1:${planGeometry.scale.toLocaleString()}` : 'As Noted';

  /* ── Don't render when hidden ───────────────────────────────────── */
  if (!show) return null;

  return (
    <div
      className="absolute inset-0 overflow-hidden sheet-layout-overlay"
      style={{ zIndex: 20 }}
    >
      {/* North Arrow */}
      <NorthArrow />

      {/* Scale Bar */}
      <ScaleBar info={scaleBar} />

      {/* Grid Ticks */}
      <GridTicks
        ticksTop={gridTicks.top}
        ticksBottom={gridTicks.bottom}
        ticksLeft={gridTicks.left}
        ticksRight={gridTicks.right}
        containerWidth={containerSize.w}
        containerHeight={containerSize.h}
      />

      {/* Title Block */}
      <TitleBlock
        lrNumber={lrNumber}
        projectName={projectName}
        surveyorName={surveyorName}
        surveyorLicense={surveyorLicense}
        clientName={clientName}
        county={county}
        scale={scaleLabel}
      />

      {/* Surveyor's Certificate */}
      <SurveyorsCertificate
        surveyorName={surveyorName}
        surveyorLicense={surveyorLicense}
      />
    </div>
  );
}

'use client'
/**
 * StakeoutPanel — Floating stakeout info panel for GPS-guided point navigation
 *
 * Positioned at bottom-center of the map for mobile field use.
 * Shows distance, bearing, accuracy, elevation diff, and proximity progress.
 * Includes audio mute toggle and cancel stakeout button.
 * Auto-hides when arrived (<1m for 3 seconds).
 *
 * Touch-friendly with large text for field use.
 *
 * Now consumes all state from MapReactContext via useMapContext().
 * Previously received 9 props from MapClient — now reads from context directly.
 */

import React, { memo, useState, useEffect, useRef } from 'react'
import { useMapContext } from '@/app/map/MapReactContext'

export const StakeoutPanel = memo(function StakeoutPanel() {
  const {
    stakeoutActive: active,
    stakeoutTarget,
    stakeoutState,
    gpsPos21037,
    gpsPos,
    deactivateStakeout,
    audioMuted,
    setAudioMuted,
    isMobile,
  } = useMapContext()

  // Derive target in StakeoutTarget format
  const target = stakeoutTarget
    ? { easting: stakeoutTarget.e, northing: stakeoutTarget.n }
    : null

  const gpsAccuracy = gpsPos?.accuracy ?? 0

  const [arrivedStartTime, setArrivedStartTime] = useState<number | null>(null)
  const [autoHidden, setAutoHidden] = useState(false)
  const panelRef = useRef<HTMLDivElement>(null)

  // Auto-hide when arrived (<1m) for 3 continuous seconds
  useEffect(() => {
    if (!stakeoutState) return

    if (stakeoutState.proximityColor === 'green') {
      if (!arrivedStartTime) {
        setArrivedStartTime(Date.now())
      } else if (Date.now() - arrivedStartTime > 3000) {
        setAutoHidden(true)
      }
    } else {
      setArrivedStartTime(null)
      setAutoHidden(false)
    }
  }, [stakeoutState, arrivedStartTime])

  // Reset auto-hide when stakeout changes
  useEffect(() => {
    setAutoHidden(false)
    setArrivedStartTime(null)
  }, [target])

  if (!active || !target || autoHidden) return null

  const proximityColorMap = {
    green: {
      bg: 'bg-green-500/15',
      border: 'border-green-500/40',
      text: 'text-green-400',
      barBg: 'bg-green-500/20',
      barFill: 'bg-green-500',
      glow: 'shadow-green-500/20',
    },
    amber: {
      bg: 'bg-amber-500/15',
      border: 'border-amber-500/40',
      text: 'text-amber-400',
      barBg: 'bg-amber-500/20',
      barFill: 'bg-amber-500',
      glow: 'shadow-amber-500/20',
    },
    red: {
      bg: 'bg-[#D17B47]/15',
      border: 'border-[#D17B47]/40',
      text: 'text-[#D17B47]',
      barBg: 'bg-[#D17B47]/20',
      barFill: 'bg-[#D17B47]',
      glow: 'shadow-[#D17B47]/20',
    },
  }

  const colors = stakeoutState
    ? proximityColorMap[stakeoutState.proximityColor]
    : proximityColorMap.red

  // Progress bar: 0-3m range mapped to 0-100%
  const progressPercent = stakeoutState
    ? Math.max(0, Math.min(100, ((3 - Math.min(stakeoutState.distance, 3)) / 3) * 100))
    : 0

  const onToggleAudio = () => setAudioMuted(m => !m)

  return (
    <div
      ref={panelRef}
      className={`
        fixed z-[1001] left-1/2 -translate-x-1/2
        ${isMobile ? 'bottom-[72px] w-[calc(100%-24px)] max-w-[360px]' : 'bottom-4 w-[380px]'}
        ${colors.bg} backdrop-blur-xl ${colors.border} border rounded-2xl
        shadow-2xl ${colors.glow} overflow-hidden
        transition-all duration-300 ease-out
      `}
      role="region"
      aria-label="Stakeout navigation panel"
    >
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-2.5 border-b border-white/[0.06]">
        <div className="flex items-center gap-2">
          {/* Pulsing dot */}
          <div className="relative">
            <div
              className={`w-2.5 h-2.5 rounded-full ${
                stakeoutState?.proximityColor === 'green'
                  ? 'bg-green-500'
                  : stakeoutState?.proximityColor === 'amber'
                  ? 'bg-amber-500'
                  : 'bg-[#D17B47]'
              }`}
            />
            <div
              className={`absolute inset-0 rounded-full animate-ping opacity-50 ${
                stakeoutState?.proximityColor === 'green'
                  ? 'bg-green-500'
                  : stakeoutState?.proximityColor === 'amber'
                  ? 'bg-amber-500'
                  : 'bg-[#D17B47]'
              }`}
            />
          </div>
          <span className="text-[11px] font-bold text-gray-300 uppercase tracking-[0.15em]">
            Stakeout
          </span>
          {stakeoutState && (
            <span className={`text-[10px] font-semibold ${colors.text} uppercase`}>
              {stakeoutState.proximityLabel}
            </span>
          )}
        </div>

        <div className="flex items-center gap-1.5">
          {/* Audio mute toggle */}
          <button
            onClick={onToggleAudio}
            className="w-7 h-7 flex items-center justify-center rounded-lg
                       bg-white/[0.06] border border-white/[0.08] text-gray-400
                       hover:text-white hover:bg-white/[0.10] transition-colors"
            title={audioMuted ? 'Unmute audio alerts' : 'Mute audio alerts'}
            aria-label={audioMuted ? 'Unmute audio alerts' : 'Mute audio alerts'}
          >
            {audioMuted ? (
              <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
                <path strokeLinecap="round" strokeLinejoin="round" d="M17 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2" />
              </svg>
            ) : (
              <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
              </svg>
            )}
          </button>

          {/* Cancel button */}
          <button
            onClick={deactivateStakeout}
            className="w-7 h-7 flex items-center justify-center rounded-lg
                       bg-red-500/10 border border-red-500/20 text-red-400
                       hover:text-red-300 hover:bg-red-500/20 transition-colors"
            title="Cancel stakeout"
            aria-label="Cancel stakeout"
          >
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
      </div>

      {/* Body */}
      <div className="px-4 py-3">
        {/* Target info */}
        <div className="mb-3">
          <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-0.5">
            Target
          </div>
          <div className="text-sm text-white font-semibold truncate">
            Point
          </div>
          <div className="text-[11px] text-gray-400 font-mono">
            E: {target.easting.toFixed(2)} &nbsp; N: {target.northing.toFixed(2)}
          </div>
        </div>

        {/* Distance — large, bold, prominent */}
        {stakeoutState ? (
          <div className="mb-3">
            <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-0.5">
              Distance
            </div>
            <div className={`text-3xl font-bold font-mono ${colors.text} tabular-nums leading-tight`}>
              {stakeoutState.distance < 1000
                ? `${stakeoutState.distance.toFixed(2)} m`
                : `${(stakeoutState.distance / 1000).toFixed(3)} km`}
            </div>
          </div>
        ) : (
          <div className="mb-3">
            <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-0.5">
              Distance
            </div>
            <div className="text-sm text-gray-600">Waiting for GPS...</div>
          </div>
        )}

        {/* Bearing */}
        {stakeoutState && (
          <div className="mb-3 grid grid-cols-2 gap-3">
            <div>
              <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-0.5">
                Bearing (WCB)
              </div>
              <div className="text-base font-semibold font-mono text-blue-300 tabular-nums">
                {stakeoutState.bearingWCB}
              </div>
            </div>
            <div>
              <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-0.5">
                Azimuth
              </div>
              <div className="text-base font-semibold font-mono text-blue-300 tabular-nums">
                {stakeoutState.bearing.toFixed(4)}&deg;
              </div>
            </div>
          </div>
        )}

        {/* Accuracy & Elevation */}
        <div className="mb-3 grid grid-cols-2 gap-3">
          <div>
            <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-0.5">
              Accuracy
            </div>
            <div className="text-[11px] font-mono text-gray-300">
              {'\u00B1'}{gpsAccuracy.toFixed(1)} m
            </div>
          </div>
          {stakeoutState?.elevationDiff != null && (
            <div>
              <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-0.5">
                Elevation Diff
              </div>
              <div className="text-[11px] font-mono text-gray-300">
                {stakeoutState.elevationDiff >= 0 ? '+' : ''}
                {stakeoutState.elevationDiff.toFixed(2)} m
              </div>
            </div>
          )}
        </div>

        {/* dE / dN */}
        {stakeoutState && (
          <div className="mb-3 text-[10px] text-gray-500 font-mono">
            dE: {stakeoutState.dE >= 0 ? '+' : ''}{stakeoutState.dE.toFixed(2)} &nbsp;|&nbsp;
            dN: {stakeoutState.dN >= 0 ? '+' : ''}{stakeoutState.dN.toFixed(2)}
          </div>
        )}

        {/* Progress bar (0–3m tolerance) */}
        <div className="mb-1">
          <div className="flex items-center justify-between mb-1">
            <span className="text-[10px] text-gray-500 uppercase tracking-wider">Proximity</span>
            <span className="text-[10px] text-gray-500 tabular-nums">
              {stakeoutState ? `${stakeoutState.distance.toFixed(1)}m / 1.0m` : '---'}
            </span>
          </div>
          <div className={`h-2 rounded-full ${colors.barBg} overflow-hidden`}>
            <div
              className={`h-full rounded-full ${colors.barFill} transition-all duration-300 ease-out`}
              style={{ width: `${progressPercent}%` }}
            />
          </div>
          <div className="flex justify-between mt-0.5">
            <span className="text-[9px] text-gray-600">3m</span>
            <span className="text-[9px] text-gray-600">1m</span>
            <span className="text-[9px] text-gray-600">0m</span>
          </div>
        </div>
      </div>
    </div>
  )
})

'use client';

import { useState, useEffect } from 'react';
import dynamic from 'next/dynamic';

const DashboardSearch = dynamic(
  () => import('@/components/dashboard/DashboardSearch').then(m => m.default || m),
  { ssr: false }
);

export type Page = 'home' | 'dashboard' | 'projects' | 'pricing' | 'community' | 'account' | 'survey-marks';

interface HeaderProps {
  currentPage: Page;
  onNavigate: (page: Page) => void;
}

export default function Header({ currentPage, onNavigate }: HeaderProps) {
  const [scrolled, setScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 0);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems: { page: Page; label: string }[] = [
    { page: 'dashboard', label: 'Dashboard' },
    { page: 'projects', label: 'Projects' },
    { page: 'survey-marks', label: 'Survey Marks' },
    { page: 'community', label: 'Community' },
  ];

  return (
    <header className="sticky top-0 z-50 w-full" style={{ backgroundColor: '#0a0a0a' }}>
      <div className="border-b" style={{ borderColor: 'rgba(255,255,255,0.08)' }}>
        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
          <div className="flex h-14 items-center justify-between">
            {/* Logo - LEFT ONLY */}
            <div className="flex items-center gap-8">
              <button
                onClick={() => onNavigate('home')}
                className="flex items-center gap-2 group"
              >
                <div className="flex items-center">
                  <svg width="28" height="28" viewBox="0 0 28 28" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <rect width="28" height="28" rx="6" fill="#f97316" />
                    <path d="M14 6L22 10V18L14 22L6 18V10L14 6Z" stroke="white" strokeWidth="1.5" fill="none" />
                    <circle cx="14" cy="14" r="3" fill="white" />
                  </svg>
                  <span className="ml-2 text-lg font-bold tracking-tight" style={{ color: '#f97316' }}>
                    METARDU
                  </span>
                </div>
              </button>

              {/* Desktop Nav */}
              <nav className="hidden md:flex items-center gap-1">
                {navItems.map((item) => (
                  <button
                    key={item.page}
                    onClick={() => onNavigate(item.page)}
                    className="px-3 py-1.5 text-sm rounded-md transition-colors"
                    style={{
                      color: currentPage === item.page ? '#f97316' : 'rgba(255,255,255,0.6)',
                      backgroundColor: currentPage === item.page ? 'rgba(249,115,22,0.1)' : 'transparent',
                    }}
                    onMouseEnter={(e) => {
                      if (currentPage !== item.page) e.currentTarget.style.color = 'rgba(255,255,255,0.9)';
                    }}
                    onMouseLeave={(e) => {
                      if (currentPage !== item.page) e.currentTarget.style.color = 'rgba(255,255,255,0.6)';
                    }}
                  >
                    {item.label}
                  </button>
                ))}
              </nav>
            </div>

            {/* Right side - Search, Language, Profile */}
            <div className="flex items-center gap-3">
              {/* Search — functional DashboardSearch component */}
              <div className="hidden sm:flex items-center">
                <DashboardSearch />
              </div>

              {/* Language */}
              <button className="hidden lg:flex items-center gap-1.5 px-2 py-1.5 text-xs rounded-md transition-colors" style={{ color: 'rgba(255,255,255,0.5)' }}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <circle cx="12" cy="12" r="10" />
                  <path d="M2 12h20" />
                  <path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z" />
                </svg>
                EN
              </button>

              {/* Divider */}
              <div className="hidden lg:block h-5 w-px" style={{ backgroundColor: 'rgba(255,255,255,0.08)' }} />

              {/* User Profile */}
              <button
                onClick={() => onNavigate('account')}
                className="flex items-center gap-2 px-2 py-1.5 rounded-md transition-colors"
                onMouseEnter={(e) => e.currentTarget.style.backgroundColor = 'rgba(255,255,255,0.05)'}
                onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'transparent'}
              >
                <div className="w-7 h-7 rounded-full flex items-center justify-center text-xs font-semibold text-white" style={{ backgroundColor: '#f97316' }}>
                  S
                </div>
                <span className="hidden md:block text-sm" style={{ color: 'rgba(255,255,255,0.7)' }}>
                  Surveyor
                </span>
              </button>

              {/* Mobile menu toggle */}
              <button
                className="md:hidden flex items-center justify-center w-8 h-8 rounded-md transition-colors"
                style={{ color: 'rgba(255,255,255,0.6)' }}
                onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
                onMouseEnter={(e) => e.currentTarget.style.backgroundColor = 'rgba(255,255,255,0.05)'}
                onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'transparent'}
              >
                {mobileMenuOpen ? (
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M18 6 6 18" /><path d="m6 6 12 12" />
                  </svg>
                ) : (
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <line x1="4" x2="20" y1="12" y2="12" /><line x1="4" x2="20" y1="6" y2="6" /><line x1="4" x2="20" y1="18" y2="18" />
                  </svg>
                )}
              </button>
            </div>
          </div>

          {/* Mobile Menu */}
          {mobileMenuOpen && (
            <div className="md:hidden py-3 border-t" style={{ borderColor: 'rgba(255,255,255,0.08)' }}>
              {/* Mobile Search */}
              <div className="px-3 pb-3">
                <DashboardSearch />
              </div>
              <nav className="flex flex-col gap-1">
                {navItems.map((item) => (
                  <button
                    key={item.page}
                    onClick={() => {
                      onNavigate(item.page);
                      setMobileMenuOpen(false);
                    }}
                    className="text-left px-3 py-2 text-sm rounded-md transition-colors"
                    style={{
                      color: currentPage === item.page ? '#f97316' : 'rgba(255,255,255,0.6)',
                      backgroundColor: currentPage === item.page ? 'rgba(249,115,22,0.1)' : 'transparent',
                    }}
                  >
                    {item.label}
                  </button>
                ))}
                <button
                  onClick={() => {
                    onNavigate('pricing');
                    setMobileMenuOpen(false);
                  }}
                  className="text-left px-3 py-2 text-sm rounded-md transition-colors"
                  style={{ color: 'rgba(255,255,255,0.6)' }}
                >
                  Pricing
                </button>
              </nav>
            </div>
          )}
        </div>
      </div>
    </header>
  );
}

import Link from 'next/link'
import Image from 'next/image'

interface MetarduLogoProps {
  color?: string
  size?: number
  showWordmark?: boolean
  className?: string
}

/**
 * METARDU Logo Component
 *
 * Uses the official METARDU logo image (public/metardu-icon.png) — a
 * square PNG cropped from the original metardu-logo.jpg.
 *
 * The wordmark text color is controlled by the `color` prop.
 */
export default function MetarduLogo({
  color = 'currentColor',
  size = 32,
  showWordmark = true,
  className = '',
}: MetarduLogoProps) {
  return (
    <div className={`flex items-center gap-2 ${className}`}>
      {/* Official METARDU logo image */}
      <Image
        src="/metardu-icon.png"
        alt="METARDU logo"
        width={size}
        height={size}
        className="shrink-0 rounded"
        priority
      />

      {showWordmark && (
        <span
          className="font-bold tracking-tight"
          style={{
            fontSize: `${size * 0.47}px`,
            letterSpacing: '0.05em',
            color: color === 'currentColor' ? 'inherit' : color,
          }}
        >
          METARDU
        </span>
      )}
    </div>
  )
}

'use client';

import { useEffect, useState } from 'react'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { useSession } from 'next-auth/react'
import {
  FolderKanban, LayoutDashboard, MapPinned, UserRound, UsersRound, Wrench, FileText,
  CalendarDays, Radar, Store, ChevronRight, X, AlertTriangle, Clock,
  BookOpen, Compass, MapPin, ShieldCheck, type LucideIcon
} from 'lucide-react'
import { PRIMARY_NAV_ITEMS, isNavItemActive } from '@/lib/navigation-shell'

const iconMap: Record<string, LucideIcon> = {
  dashboard: LayoutDashboard,
  projects: FolderKanban,
  tools: Wrench,
  map: MapPinned,
  reports: FileText,
  community: UsersRound,
  profile: UserRound,
}

/** Pages hidden from the bottom tab bar — shown in the "More" drawer */
const MORE_PAGES = [
  { href: '/fieldbook', label: 'Field Book', icon: BookOpen, color: 'text-orange-400' },
  { href: '/field', label: 'Field Mode', icon: Compass, color: 'text-cyan-400' },
  { href: '/beacons', label: 'Beacon Registry', icon: MapPin, color: 'text-amber-400' },
  { href: '/schedule', label: 'Job Schedule', icon: CalendarDays, color: 'text-blue-400' },
  { href: '/equipment', label: 'Equipment Tracker', icon: Radar, color: 'text-green-400' },
  { href: '/marketplace', label: 'Equipment Marketplace', icon: Store, color: 'text-amber-400' },
]

export default function MobileNav() {
  const pathname = usePathname()
  const [mounted, setMounted] = useState(false)
  const [showMore, setShowMore] = useState(false)
  const { data: session, status: authStatus } = useSession()
  const isAuthenticated = !!session

  useEffect(() => { setMounted(true) }, [])

  // Show the unified 5-item navigation + "More" button
  const mobileNavItems = PRIMARY_NAV_ITEMS

  // Check if current page is in the "More" drawer (for active highlighting)
  const isMoreActive = MORE_PAGES.some(p => pathname === p.href || pathname.startsWith(p.href + '/'))

  return (
    <>
      <nav
        className="fixed bottom-0 left-0 right-0 bg-[var(--bg-primary)] border-t border-[var(--border-color)] md:hidden z-50"
        style={{
          paddingBottom: 'env(safe-area-inset-bottom, 0px)',
          // AUDIT FIX (2026-07-05): Use real safe-area inset instead of CSS class
          // (the class was a no-op). On notched Android devices this prevents
          // the nav from being obscured by the gesture bar.
        }}
        role="navigation"
        aria-label="Primary mobile navigation"
      >
        <div className="flex justify-around items-stretch">
          {mobileNavItems.slice(0, 4).map((item) => {
            const isActive = isNavItemActive(pathname, item.href)
            const iconName = item.icon || item.href.replace('/', '')
            const Icon = iconMap[iconName] || LayoutDashboard
            return (
              <Link
                key={item.href}
                href={item.href}
                aria-current={isActive ? 'page' : undefined}
                className={`flex flex-col items-center justify-center gap-0.5 px-2 min-h-[48px] py-2 text-[10px] font-medium tracking-wide transition-colors min-w-0 flex-1 ${
                  isActive ? 'text-[var(--accent)]' : 'text-gray-400 hover:text-white'
                }`}
              >
                <Icon className={`h-5 w-5 transition-colors ${isActive ? 'text-[var(--accent)]' : 'text-gray-400'}`} strokeWidth={1.9} />
                <span className="truncate">{item.label}</span>
              </Link>
            )
          })}

          {/* Reports */}
          {(() => {
            const reportsItem = mobileNavItems[4]
            const isActive = isNavItemActive(pathname, reportsItem.href)
            const Icon = iconMap['reports'] || FileText
            return (
              <Link
                key={reportsItem.href}
                href={reportsItem.href}
                aria-current={isActive ? 'page' : undefined}
                className={`flex flex-col items-center justify-center gap-0.5 px-2 min-h-[48px] py-2 text-[10px] font-medium tracking-wide transition-colors min-w-0 flex-1 ${
                  isActive ? 'text-[var(--accent)]' : 'text-gray-400 hover:text-white'
                }`}
              >
                <Icon className={`h-5 w-5 transition-colors ${isActive ? 'text-[var(--accent)]' : 'text-gray-400'}`} strokeWidth={1.9} />
                <span className="truncate">{reportsItem.label}</span>
              </Link>
            )
          })()}

          {/* More button */}
          <button
            onClick={() => setShowMore(true)}
            aria-label="Show more navigation options"
            aria-expanded={showMore}
            className={`flex flex-col items-center justify-center gap-0.5 px-2 min-h-[48px] py-2 text-[10px] font-medium tracking-wide transition-colors min-w-0 flex-1 ${
              isMoreActive ? 'text-[var(--accent)]' : 'text-gray-400 hover:text-white'
            }`}
          >
            <div className={`h-5 w-5 flex items-center justify-center ${isMoreActive ? 'text-[var(--accent)]' : 'text-gray-400'}`}>
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.9}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25H12" />
              </svg>
            </div>
            <span>More</span>
          </button>
        </div>
      </nav>

      {/* More Drawer */}
      {showMore && (
        <div className="fixed inset-0 z-[60] flex md:hidden" onKeyDown={(e) => { if (e.key === 'Escape') setShowMore(false) }}>
          {/* Backdrop */}
          <button type="button" aria-label="Close menu" tabIndex={-1} className="flex-1 bg-black/60 backdrop-blur-sm cursor-pointer border-0 p-0" onClick={() => setShowMore(false)} />

          {/* Panel slides up from bottom */}
          <div
            className="w-full bg-[var(--bg-primary)] border-t border-[var(--border-color)] rounded-t-2xl max-h-[70vh] overflow-y-auto animate-slide-up"
            onClick={e => e.stopPropagation()}
          >
            {/* Handle bar */}
            <div className="flex justify-center pt-3 pb-1">
              <div className="w-10 h-1 rounded-full bg-[var(--text-muted)]/30" />
            </div>

            {/* Header */}
            <div className="flex items-center justify-between px-5 py-3 border-b border-[var(--border-color)]">
              <h2 className="text-base font-semibold text-[var(--text-primary)]">More Tools</h2>
              <button onClick={() => setShowMore(false)} className="p-1 text-[var(--text-muted)] hover:text-[var(--text-primary)]">
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* Quick Actions Section */}
            <div className="px-5 pt-4 pb-2">
              <p className="text-[10px] font-semibold text-[var(--text-muted)] uppercase tracking-[0.15em] mb-2">Field Operations</p>
              <div className="space-y-1">
                {MORE_PAGES.map((page) => {
                  const isActive = pathname === page.href || pathname.startsWith(page.href + '/')
                  return (
                    <Link
                      key={page.href}
                      href={page.href}
                      onClick={() => setShowMore(false)}
                      className={`flex items-center gap-3 px-3 py-3 rounded-xl transition-all ${
                        isActive
                          ? 'bg-[var(--accent)]/10 border border-[var(--accent)]/20'
                          : 'hover:bg-[var(--bg-tertiary)] border border-transparent'
                      }`}
                    >
                      <div className={`w-9 h-9 rounded-lg flex items-center justify-center ${
                        isActive ? 'bg-[var(--accent)]/15' : 'bg-[var(--bg-tertiary)]'
                      }`}>
                        <page.icon className={`w-4.5 h-4.5 ${isActive ? 'text-[var(--accent)]' : page.color}`} strokeWidth={1.8} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <span className={`text-sm font-medium ${isActive ? 'text-[var(--accent)]' : 'text-[var(--text-primary)]'}`}>
                          {page.label}
                        </span>
                      </div>
                      <ChevronRight className={`w-4 h-4 ${isActive ? 'text-[var(--accent)]' : 'text-[var(--text-muted)]'}`} />
                    </Link>
                  )
                })}
              </div>
            </div>

            {/* Admin Section (only for admin users) */}
            {mounted && isAuthenticated && (() => {
              const userRole = (session?.user as { role?: string })?.role
              const isAdmin = userRole === 'super_admin' || userRole === 'admin' || userRole === 'org_admin'
              if (!isAdmin) return null
              return (
                <div className="px-5 pt-4 pb-2">
                  <p className="text-[10px] font-semibold text-[var(--text-muted)] uppercase tracking-[0.15em] mb-2">Administration</p>
                  <div className="space-y-1">
                    <Link
                      href="/admin"
                      onClick={() => setShowMore(false)}
                      className={`flex items-center gap-3 px-3 py-3 rounded-xl transition-all ${
                        pathname === '/admin' || pathname.startsWith('/admin/')
                          ? 'bg-[var(--accent)]/10 border border-[var(--accent)]/20'
                          : 'hover:bg-[var(--bg-tertiary)] border border-transparent'
                      }`}
                    >
                      <div className={`w-9 h-9 rounded-lg flex items-center justify-center ${
                        pathname === '/admin' ? 'bg-[var(--accent)]/15' : 'bg-[var(--bg-tertiary)]'
                      }`}>
                        <ShieldCheck className={`w-4.5 h-4.5 ${pathname === '/admin' ? 'text-[var(--accent)]' : 'text-[var(--accent)]'}`} strokeWidth={1.8} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <span className={`text-sm font-medium ${pathname === '/admin' ? 'text-[var(--accent)]' : 'text-[var(--text-primary)]'}`}>
                          Admin Dashboard
                        </span>
                      </div>
                      <ChevronRight className={`w-4 h-4 ${pathname === '/admin' ? 'text-[var(--accent)]' : 'text-[var(--text-muted)]'}`} />
                    </Link>
                  </div>
                </div>
              )
            })()}

            {/* Settings Section */}
            <div className="px-5 pt-4 pb-6">
              <p className="text-[10px] font-semibold text-[var(--text-muted)] uppercase tracking-[0.15em] mb-2">Settings</p>
              <div className="space-y-1">
                {[
                  { href: '/account', label: 'Account & Billing', icon: 'account' },
                  { href: '/pricing', label: 'Pricing Plans', icon: 'pricing' },
                  { href: '/docs', label: 'Documentation', icon: 'docs' },
                ].map((item) => (
                  <Link
                    key={item.href}
                    href={item.href}
                    onClick={() => setShowMore(false)}
                    className="flex items-center gap-3 px-3 py-3 rounded-xl hover:bg-[var(--bg-tertiary)] transition-all"
                  >
                    <div className="w-9 h-9 rounded-lg flex items-center justify-center bg-[var(--bg-tertiary)]">
                      <svg className="w-4 h-4 text-[var(--text-muted)]" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.8}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M9.594 3.94c.09-.542.56-.94 1.11-.94h2.593c.55 0 1.02.398 1.11.94l.213 1.281c.063.374.313.686.645.87.074.04.147.083.22.127.324.196.72.257 1.075.124l1.217-.456a1.125 1.125 0 011.37.49l1.296 2.247a1.125 1.125 0 01-.26 1.431l-1.003.827c-.293.24-.438.613-.431.992a6.759 6.759 0 010 .255c-.007.378.138.75.43.99l1.005.828c.424.35.534.954.26 1.43l-1.298 2.247a1.125 1.125 0 01-1.369.491l-1.217-.456c-.355-.133-.75-.072-1.076.124a6.57 6.57 0 01-.22.128c-.331.183-.581.495-.644.869l-.213 1.28c-.09.543-.56.941-1.11.941h-2.594c-.55 0-1.02-.398-1.11-.94l-.213-1.281c-.062-.374-.312-.686-.644-.87a6.52 6.52 0 01-.22-.127c-.325-.196-.72-.257-1.076-.124l-1.217.456a1.125 1.125 0 01-1.369-.49l-1.297-2.247a1.125 1.125 0 01.26-1.431l1.004-.827c.292-.24.437-.613.43-.992a6.932 6.932 0 010-.255c.007-.378-.138-.75-.43-.99l-1.004-.828a1.125 1.125 0 01-.26-1.43l1.297-2.247a1.125 1.125 0 011.37-.491l1.216.456c.356.133.751.072 1.076-.124.072-.044.146-.087.22-.128.332-.183.582-.495.644-.869l.214-1.281z" />
                        <path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
