                    <ChevronRight className="w-4 h-4 text-[var(--text-muted)]" />
                  </Link>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      <style jsx global>{`
        @keyframes slideUp {
          from {
            transform: translateY(100%);
