'use client'

/**
 * NotificationBell — Floating notification icon with unread count badge
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { useRouter } from 'next/navigation'
import {
  Bell, CheckCheck, Trash2, Loader2,
  Info, AlertTriangle, CheckCircle2, XCircle,
  FileText, MessageSquare, CreditCard, Users, Settings as SettingsIcon,
} from 'lucide-react'

interface Notification {
  id: string
  type: 'info' | 'success' | 'warning' | 'error'
  category: string
  title: string
  message: string
  action_url?: string | null
  action_label?: string | null
  read_at: string | null
  created_at: string
}

const TYPE_ICONS: Record<string, typeof Info> = {
  info: Info, success: CheckCircle2, warning: AlertTriangle, error: XCircle,
}

const CATEGORY_ICONS: Record<string, typeof Info> = {
  peer_review: FileText, payment: CreditCard, project_share: Users,
  message: MessageSquare, system: SettingsIcon,
}

function timeAgo(dateStr: string): string {
  const date = new Date(dateStr)
  const seconds = Math.floor((Date.now() - date.getTime()) / 1000)
  if (seconds < 60) return 'just now'
  const minutes = Math.floor(seconds / 60)
  if (minutes < 60) return `${minutes}m ago`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours}h ago`
  const days = Math.floor(hours / 24)
  if (days < 7) return `${days}d ago`
  return date.toLocaleDateString('en-KE', { month: 'short', day: 'numeric' })
}

export function NotificationBell() {
  const router = useRouter()
  const [open, setOpen] = useState(false)
  const [notifications, setNotifications] = useState<Notification[]>([])
  const [unreadCount, setUnreadCount] = useState(0)
  const [loading, setLoading] = useState(false)
  const dropdownRef = useRef<HTMLDivElement>(null)

  const fetchNotifications = useCallback(async () => {
    try {
      const res = await fetch('/api/notifications?limit=20')
      if (!res.ok) return
      const data = await res.json() as { data?: { notifications?: Notification[]; unreadCount?: number } }
      setNotifications(data.data?.notifications || [])
      setUnreadCount(data.data?.unreadCount || 0)
    } catch (err) {}
  }, [])

  useEffect(() => {
    fetchNotifications()
    const interval = setInterval(fetchNotifications, 60000)
    return () => clearInterval(interval)
  }, [fetchNotifications])

  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setOpen(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  const handleMarkRead = useCallback(async (id: string, actionUrl?: string | null) => {
    try {
      await fetch('/api/notifications', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id }),
      })
      setNotifications(prev =>
        prev.map(n => n.id === id ? { ...n, read_at: new Date().toISOString() } : n)
      )
      setUnreadCount(prev => Math.max(0, prev - 1))
      if (actionUrl) {
        router.push(actionUrl)
        setOpen(false)
      }
    } catch (err) {}
  }, [router])

  const handleMarkAllRead = useCallback(async () => {
    try {
      await fetch('/api/notifications', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ all: true }),
      })
      setNotifications(prev => prev.map(n => ({ ...n, read_at: n.read_at || new Date().toISOString() })))
      setUnreadCount(0)
    } catch (err) {}
  }, [])

  const handleDelete = useCallback(async (id: string, e: React.MouseEvent) => {
    e.stopPropagation()
    try {
      await fetch(`/api/notifications?id=${id}`, { method: 'DELETE' })
      setNotifications(prev => prev.filter(n => n.id !== id))
    } catch (err) {}
  }, [])

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        onClick={() => { setOpen(!open); if (!open) fetchNotifications() }}
        className="relative w-10 h-10 flex items-center justify-center rounded-lg text-gray-400 hover:text-white hover:bg-white/[0.06] transition-colors"
        aria-label={`Notifications${unreadCount > 0 ? ` (${unreadCount} unread)` : ''}`}
      >
        <Bell className="w-5 h-5" />
        {unreadCount > 0 && (
          <span className="absolute -top-0.5 -right-0.5 min-w-[18px] h-[18px] flex items-center justify-center px-1 rounded-full bg-red-500 text-white text-[9px] font-bold animate-in zoom-in duration-200">
            {unreadCount > 99 ? '99+' : unreadCount}
          </span>
        )}
      </button>

      {open && (
        <div className="absolute right-0 top-12 w-[360px] max-w-[calc(100vw-2rem)] bg-[#0d0d14]/95 backdrop-blur-2xl border border-white/[0.08] rounded-xl shadow-2xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
          <div className="flex items-center justify-between px-4 py-3 border-b border-white/[0.06]">
            <span className="text-sm font-semibold text-white">Notifications</span>
            {unreadCount > 0 && (
              <button
                onClick={handleMarkAllRead}
                className="flex items-center gap-1 text-[10px] text-gray-400 hover:text-white transition-colors"
              >
                <CheckCheck className="w-3 h-3" />
                Mark all read
              </button>
            )}
          </div>

          <div className="max-h-[400px] overflow-y-auto">
            {loading && (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="w-5 h-5 text-gray-500 animate-spin" />
              </div>
            )}

            {!loading && notifications.length === 0 && (
              <div className="flex flex-col items-center justify-center py-12 px-4 text-center">
                <Bell className="w-8 h-8 text-gray-600 mb-2" />
                <p className="text-sm text-gray-500">No notifications yet</p>
                <p className="text-[10px] text-gray-600 mt-1">
                  You&apos;ll see peer review requests, payment confirmations, and updates here.
                </p>
              </div>
            )}

            {!loading && notifications.map(notif => {
              const TypeIcon = TYPE_ICONS[notif.type] || Info
              const CatIcon = CATEGORY_ICONS[notif.category] || TypeIcon
              const Icon = CatIcon
              const isUnread = !notif.read_at

              return (
                <div
                  key={notif.id}
                  onClick={() => handleMarkRead(notif.id, notif.action_url)}
                  className={`flex items-start gap-3 px-4 py-3 border-b border-white/[0.04] cursor-pointer hover:bg-white/[0.03] transition-colors group ${
                    isUnread ? 'bg-blue-500/[0.03]' : ''
                  }`}
                >
                  <div className={`shrink-0 w-8 h-8 rounded-lg flex items-center justify-center ${
                    notif.type === 'error' ? 'bg-red-500/10' :
                    notif.type === 'warning' ? 'bg-amber-500/10' :
                    notif.type === 'success' ? 'bg-emerald-500/10' :
                    'bg-blue-500/10'
                  }`}>
                    <Icon className={`w-4 h-4 ${
                      notif.type === 'error' ? 'text-red-400' :
                      notif.type === 'warning' ? 'text-amber-400' :
                      notif.type === 'success' ? 'text-emerald-400' :
                      'text-blue-400'
                    }`} />
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-medium text-white truncate">{notif.title}</span>
                      {isUnread && (
                        <span className="w-2 h-2 rounded-full bg-blue-400 shrink-0" />
                      )}
                    </div>
                    <p className="text-[11px] text-gray-400 mt-0.5 line-clamp-2">{notif.message}</p>
                    <div className="flex items-center justify-between mt-1">
                      <span className="text-[9px] text-gray-600">{timeAgo(notif.created_at)}</span>
                      {notif.action_label && (
                        <span className="text-[9px] text-blue-400 font-medium">{notif.action_label} →</span>
                      )}
                    </div>
                  </div>

                  <button
                    onClick={(e) => handleDelete(notif.id, e)}
                    className="shrink-0 w-6 h-6 flex items-center justify-center rounded text-gray-600 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-all"
                    title="Delete"
                  >
                    <Trash2 className="w-3 h-3" />
                  </button>
                </div>
              )
            })}
          </div>

          {notifications.length > 0 && (
            <div className="border-t border-white/[0.06] px-4 py-2.5">
              <button
                onClick={() => { router.push('/notifications'); setOpen(false) }}
                className="w-full text-center text-xs text-gray-400 hover:text-white transition-colors"
              >
                View all notifications
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

/**
 * OnboardingTour — Interactive guided walkthrough for new users
 *
 * Features:
 * - Step-by-step tour with spotlight overlay
 * - Highlights key UI elements with descriptions
 * - Progress indicator (step X of Y)
 * - Skip / Next / Back navigation
 * - Persists completion in localStorage
 * - Auto-starts on first visit to dashboard
 *
 * Tour steps:
 * 1. Welcome to METARDU
 * 2. Dashboard — your projects
 * 3. Map — survey workflow
 * 4. Field Book — capture observations
 * 5. Tools — COGO, traverse, leveling
 * 6. Documents — generate deed plans
 * 7. Community — connect with surveyors
 * 8. Search (Cmd+K) — quick navigation
 * 9. Notifications — stay updated
 */

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import {
  X, ChevronLeft, ChevronRight, Check,
  LayoutDashboard, Map, FileText, Wrench, Users, Search, Bell,
} from 'lucide-react'

interface TourStep {
  title: string
  description: string
  icon: typeof LayoutDashboard
  href?: string
  highlight?: string // CSS selector to highlight
}

const TOUR_STEPS: TourStep[] = [
  {
    title: 'Welcome to METARDU',
    description: 'East Africa\'s professional surveying platform. This quick tour will show you the key features. You can skip this anytime and come back later.',
    icon: LayoutDashboard,
  },
  {
    title: 'Your Dashboard',
    description: 'This is your home base. Create new projects, view recent activity, and track your survey work. Each project contains its own map, field book, and documents.',
    icon: LayoutDashboard,
    href: '/dashboard',
  },
  {
    title: 'The Survey Map',
    description: 'The map is where you draw parcels, measure distances, and run COGO computations. Use the floating dock on the left to access tools. On mobile, use two fingers to pan.',
    icon: Map,
    href: '/map',
  },
  {
    title: 'Digital Field Book',
    description: 'Capture traverse, leveling, and control observations directly in the field. Works offline — your data syncs when you\'re back online. On mobile, use the bottom bar to take measurements.',
    icon: FileText,
    href: '/fieldbook',
  },
  {
    title: 'Survey Tools',
    description: '60+ calculation tools for every survey workflow: COGO, traverse adjustment, leveling, coordinate transformation, curves, areas, volumes, and more.',
    icon: Wrench,
    href: '/tools/cogo',
  },
  {
    title: 'Document Generation',
    description: 'Generate Kenya-compliant deed plans, Form C-22, beacon certificates, and traverse sheets. Free tier includes METARDU watermark; paid plans can add a company logo.',
    icon: FileText,
    href: '/documents',
  },
  {
    title: 'Surveyor Community',
    description: 'Connect with peers, submit plans for review, browse the equipment market, and track your CPD progress.',
    icon: Users,
    href: '/community',
  },
  {
    title: 'Quick Search',
    description: 'Press Cmd+K (Mac) or Ctrl+K (Windows) anywhere to open the command palette. Search across projects, parcels, tools, and pages instantly.',
    icon: Search,
  },
  {
    title: 'Notifications',
    description: 'Click the bell icon to see peer review requests, payment confirmations, and system updates. You\'re all set — welcome aboard!',
    icon: Bell,
  },
]

const STORAGE_KEY = 'metardu:onboarding-completed'

export function OnboardingTour() {
  const router = useRouter()
  const [active, setActive] = useState(false)
  const [step, setStep] = useState(0)

  // Check if tour should auto-start
  // UI-12 (2026-07-24): Also check the checklist's dismissed state so
  // the tour doesn't fire before the user has seen the checklist.
  useEffect(() => {
    if (typeof window === 'undefined') return
    const completed = localStorage.getItem(STORAGE_KEY)
    const skipped = localStorage.getItem('metardu:onboarding-skipped')
    const checklistDismissed = localStorage.getItem('metardu_onboarding_dismissed')
    if (!completed && !skipped && checklistDismissed) {
      // Only start the tour AFTER the checklist has been dismissed —
      // otherwise the user gets two onboarding overlays at once.
      const timer = setTimeout(() => setActive(true), 1500)
      return () => clearTimeout(timer)
    }
  }, [])

  const handleClose = useCallback(() => {
    setActive(false)
  }, [])

  const handleSkip = useCallback(() => {
    localStorage.setItem(STORAGE_KEY, new Date().toISOString())
    localStorage.setItem('metardu:onboarding-skipped', 'true')
    // AUDIT FIX (M18, 2026-07-02): Persist to server so cross-device users
    // don't see the tour again. Fire-and-forget — localStorage is the
    // immediate source of truth; the server record prevents the tour from
    // reappearing on a new device.
    fetch('/api/user/onboarding', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'skip' }),
      credentials: 'include',
    }).catch(() => { /* silent fail — localStorage is enough */ })
    setActive(false)
  }, [])

  const handleComplete = useCallback(() => {
    localStorage.setItem(STORAGE_KEY, new Date().toISOString())
    // AUDIT FIX (M18, 2026-07-02): Persist completion to server.
    fetch('/api/user/onboarding', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'complete' }),
      credentials: 'include',
    }).catch(() => { /* silent fail — localStorage is enough */ })
    setActive(false)
  }, [])

  const handleNext = useCallback(() => {
    const currentStep = TOUR_STEPS[step]
    if (step < TOUR_STEPS.length - 1) {
      // Navigate to the step's href if provided
      if (currentStep.href) {
        router.push(currentStep.href)
      }
      setStep(prev => prev + 1)
    } else {
      handleComplete()
    }
  }, [step, router, handleComplete])

  const handleBack = useCallback(() => {
    if (step > 0) {
      const prevStep = TOUR_STEPS[step - 1]
      if (prevStep.href) {
        router.push(prevStep.href)
      }
      setStep(prev => prev - 1)
    }
  }, [step, router])

  // Close the tour with Escape regardless of focus location
  // (handled at document level — the dialog element itself is not
  // focusable, so a local onKeyDown would only fire from child buttons)
  useEffect(() => {
    if (!active) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') handleSkip()
    }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [active, handleSkip])

  if (!active) return null

  const currentStep = TOUR_STEPS[step]
  const Icon = currentStep.icon
  const isLast = step === TOUR_STEPS.length - 1
  const isFirst = step === 0

  return (
    <>
      {/* AUDIT FIX (M16, 2026-07-02): Added ARIA attributes for accessibility.
          - role="dialog" + aria-modal on the tour card (screen readers announce it as a dialog)
          - aria-labelledby pointing to the step title
          - aria-label on the close button
          - The backdrop no longer dismisses on click (prevents accidental dismissal)
            — users must click Skip or press Escape. */}

      {/* Backdrop overlay — no onClick (prevents accidental dismissal) */}
      <div
        className="fixed inset-0 z-[9990] bg-black/70 backdrop-blur-sm"
        aria-hidden="true"
      />

      {/* Tour card */}
      <div
        className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[9991] w-[440px] max-w-[calc(100vw-2rem)]"
        role="dialog"
        aria-modal="true"
        aria-labelledby="tour-title"
      >
        <div className="bg-[#0d0d14]/95 backdrop-blur-2xl border border-[#D17B47]/30 rounded-2xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-300">
          {/* Progress bar */}
          <div className="h-1 bg-white/[0.06]">
            <div
              className="h-full bg-[#D17B47] transition-all duration-300"
              style={{ width: `${((step + 1) / TOUR_STEPS.length) * 100}%` }}
            />
          </div>

          {/* Header */}
          <div className="flex items-center justify-between px-5 pt-4 pb-2">
            <div className="flex items-center gap-2">
              <span className="text-[10px] text-gray-500 uppercase tracking-wider font-semibold">
                Step {step + 1} of {TOUR_STEPS.length}
              </span>
            </div>
            <button
              onClick={handleSkip}
              className="w-7 h-7 flex items-center justify-center rounded-lg text-gray-400 hover:text-white hover:bg-white/[0.06] transition-colors"
              title="Skip tour"
              aria-label="Skip onboarding tour"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {/* Content */}
          <div className="px-5 pb-5 space-y-3">
            <div className="flex items-start gap-3">
              <div className="shrink-0 w-12 h-12 rounded-xl bg-[#D17B47]/10 border border-[#D17B47]/20 flex items-center justify-center">
                <Icon className="w-6 h-6 text-[#D17B47]" />
              </div>
              <div className="flex-1 pt-1">
                <h3 id="tour-title" className="text-base font-bold text-white">{currentStep.title}</h3>
                <p className="text-xs text-gray-400 mt-1 leading-relaxed">{currentStep.description}</p>
              </div>
            </div>

            {/* Step dots */}
            <div className="flex items-center justify-center gap-1.5 pt-2">
              {TOUR_STEPS.map((_, i) => (
                <div
                  key={i}
                  className={`h-1.5 rounded-full transition-all duration-300 ${
                    i === step ? 'w-6 bg-[#D17B47]' : i < step ? 'w-1.5 bg-[#D17B47]/50' : 'w-1.5 bg-white/10'
                  }`}
                />
              ))}
            </div>

            {/* Actions */}
            <div className="flex items-center justify-between pt-2">
              <button
                onClick={handleSkip}
                className="text-[11px] text-gray-500 hover:text-gray-300 transition-colors"
              >
                Skip tour
              </button>
              <div className="flex items-center gap-2">
                {!isFirst && (
                  <button
                    onClick={handleBack}
                    className="flex items-center gap-1 px-3 h-8 rounded-lg bg-white/[0.04] border border-white/[0.06] text-xs text-gray-300 hover:bg-white/[0.08] transition-colors"
                  >
                    <ChevronLeft className="w-3.5 h-3.5" />
                    Back
                  </button>
                )}
                <button
                  onClick={handleNext}
                  className="flex items-center gap-1 px-4 h-8 rounded-lg bg-[#D17B47] hover:bg-[#FFB84D] text-black text-xs font-semibold transition-colors"
                >
                  {isLast ? (
                    <>
                      <Check className="w-3.5 h-3.5" />
                      Get Started
                    </>
                  ) : (
                    <>
                      Next
                      <ChevronRight className="w-3.5 h-3.5" />
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  )
}

/**
 * Hook to check if onboarding has been completed
 */
export function useOnboardingStatus() {
  const [completed, setCompleted] = useState(false)

  useEffect(() => {
    setCompleted(!!localStorage.getItem(STORAGE_KEY))
  }, [])

  return completed
}

/**
 * Reset onboarding (for testing or re-triggering)
 */
export function resetOnboarding() {
  localStorage.removeItem(STORAGE_KEY)
  localStorage.removeItem('metardu:onboarding-skipped')
}

'use client';

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { Upload, FileText, MapPin, Download, Loader2 , AlertTriangle } from 'lucide-react'
import type { GNSSBaseline } from '@/types/gnss'

interface FileWithLabel {
  file: File
  stationLabel: string
}

export default function GNSSProcessor({ projectId = '' }: { projectId?: string }) {
  const router = useRouter()
  const [files, setFiles] = useState<FileWithLabel[]>([])
  const [processing, setProcessing] = useState(false)
  const [status, setStatus] = useState('')
  const [results, setResults] = useState<GNSSBaseline[]>([])
  const [error, setError] = useState('')

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files).map((file) => ({
        file,
        stationLabel: ''
      }))
      setFiles(prev => [...prev, ...newFiles])
    }
  }

  const updateStationLabel = (index: number, label: string) => {
    setFiles(prev => prev.map((f, i) => 
      i === index ? { ...f, stationLabel: label } : f
    ))
  }

  const removeFile = (index: number) => {
    setFiles(prev => prev.filter((_, i) => i !== index))
  }

  const processBaselines = async () => {
    const hasLabels = files.every(f => f.stationLabel.trim())
    if (!hasLabels) {
      setError('Please label all stations before processing')
      return
    }

    setProcessing(true)
    setStatus('Uploading files...')
    setError('')

    try {
      setStatus('Processing baselines...')
      
      const formData = new FormData()
      files.forEach((f) => formData.append('files', f.file))
      formData.append('projectId', projectId)
      formData.append('stationLabels', JSON.stringify(files.map((f) => f.stationLabel)))

      const response = await fetch('/api/gnss/process', {
        method: 'POST',
        body: JSON.stringify({
          projectId,
          files: files.map((f) => ({
            filename: f.file.name,
            stationId: f.stationLabel,
            fileType: f.file.name.endsWith('.nav') ? 'NAV' : 'OBS',
            sizeBytes: f.file.size,
            storagePath: ''
          })),
          stationLabels: files.map((f) => f.stationLabel)
        })
      })

      const data = (await response.json()) as { error?: string; results?: GNSSBaseline[]; status?: string }
      
      if (!response.ok) {
        throw new Error(data.error || 'Processing failed')
      }

      setResults(data.results || [])
      
      if (data.status === 'simulated') {
        setError('Simulation mode — upload valid RINEX files for real processing')
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Processing failed')
    } finally {
      setProcessing(false)
      setStatus('')
    }
  }

  const fixedCount = results.filter((r) => r.fixed).length
  const rmsValues = results.map((r) => r.rmsError)
  const bestRms = rmsValues.length ? Math.min(...rmsValues) : 0
  const worstRms = rmsValues.length ? Math.max(...rmsValues) : 0

  return (
    <div className="space-y-6">
      {/* Upload Section */}
      <div className="border-2 border-dashed border-[var(--border-color)] rounded-xl p-6 text-center">
        <Upload className="w-10 h-10 mx-auto mb-3 text-[var(--text-muted)]" />
        <p className="text-sm mb-3">Drop RINEX files (.obs, .nav, .rnx, .21o)</p>
        <input
          type="file"
          multiple
          accept=".obs,.nav,.rnx,.21o,.24o"
          onChange={handleFileUpload}
          className="hidden"
          id="rinex-upload"
        />
        <label
          htmlFor="rinex-upload"
          className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm cursor-pointer inline-block"
        >
          Select Files
        </label>
      </div>

      {/* File List */}
      {files.length > 0 && (
        <div className="space-y-2">
          <h3 className="font-semibold text-sm">Uploaded Files</h3>
          {files.map((f, i) => (
            <div key={`${f}-${i}`} className="flex items-center gap-3 p-3 bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg">
              <FileText className="w-5 h-5 text-[var(--text-muted)]" />
              <div className="flex-1">
                <div className="text-sm font-medium">{f.file.name}</div>
                <div className="text-xs text-[var(--text-muted)]">
                  {(f.file.size / 1024).toFixed(1)} KB
                </div>
              </div>
              <input
                type="text"
                aria-label="Station label" placeholder="e.g. BASE, ROVER1"
                value={f.stationLabel}
                onChange={e => updateStationLabel(i, e.target.value)}
                className="px-3 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-sm w-48"
              />
              <button
                onClick={() => removeFile(i)}
                className="text-red-500 hover:text-red-600"
              >
                [x]
              </button>
            </div>
          ))}
        </div>
      )}

      {/* Process Button */}
      <button
        onClick={processBaselines}
        disabled={processing || files.length < 2}
        className="w-full py-3 bg-[var(--accent)] text-black font-semibold rounded-lg disabled:opacity-50"
      >
        {processing ? (
          <span className="flex items-center justify-center gap-2">
            <Loader2 className="w-4 h-4 animate-spin" />
            {status || 'Processing...'}
          </span>
        ) : (
          'Process Baselines'
        )}
      </button>

      {/* Error */}
      {error && (
        <div className="p-4 bg-amber-50 border border-amber-200 rounded-lg text-amber-700 text-sm">
          {error}
        </div>
      )}

      {/* Results */}
      {results.length > 0 && (
        <div className="space-y-4">
          {/* Summary Cards */}
          <div className="grid grid-cols-4 gap-4">
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-4 text-center">
              <div className="text-2xl font-bold">{results.length}</div>
              <div className="text-xs text-[var(--text-muted)]">Baselines</div>
            </div>
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-4 text-center">
              <div className="text-2xl font-bold text-green-600">{fixedCount}</div>
              <div className="text-xs text-[var(--text-muted)]">Fixed</div>
            </div>
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-4 text-center">
              <div className="text-2xl font-bold">{(bestRms * 1000).toFixed(1)}mm</div>
              <div className="text-xs text-[var(--text-muted)]">Best RMS</div>
            </div>
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-4 text-center">
              <div className="text-2xl font-bold">{(worstRms * 1000).toFixed(1)}mm</div>
              <div className="text-xs text-[var(--text-muted)]">Worst RMS</div>
            </div>
          </div>

          {/* Accuracy Banner */}
          <div className={`p-4 rounded-lg ${fixedCount === results.length ? 'bg-green-50 border border-green-200' : 'bg-amber-50 border border-amber-200'}`}>
            {fixedCount === results.length ? (
              <span className="text-green-700"> All baselines fixed — First Order accuracy achieved</span>
            ) : (
              <span className="text-amber-700"><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> Some baselines are float solutions — not suitable for cadastral work</span>
            )}
          </div>

          {/* Results Table */}
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-[var(--bg-tertiary)]">
                <tr>
                  <th className="text-left p-3">FROM</th>
                  <th className="text-left p-3">TO</th>
                  <th className="text-right p-3">DIST (m)</th>
                  <th className="text-right p-3">RMS</th>
                  <th className="text-right p-3">RATIO</th>
                  <th className="text-center p-3">FIXED</th>
                  <th className="text-center p-3">CLASS</th>
                </tr>
              </thead>
              <tbody>
                {results.map((r, i) => (
                  <tr key={`${r}-${i}`} className={`border-b border-[var(--border-color)] ${r.fixed ? 'bg-green-50' : 'bg-amber-50'}`}>
                    <td className="p-3">{r.fromStation}</td>
                    <td className="p-3">{r.toStation}</td>
                    <td className="p-3 text-right font-mono">{r.distance.toFixed(3)}</td>
                    <td className="p-3 text-right font-mono">{(r.rmsError * 1000).toFixed(1)}mm</td>
                    <td className="p-3 text-right font-mono">{r.ratio.toFixed(1)}</td>
                    <td className="p-3 text-center">{r.fixed ? '' : <AlertTriangle className="w-3.5 h-3.5 inline shrink-0 text-amber-500" />}</td>
                    <td className="p-3 text-center">{r.qualityClass}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState } from 'react'
import { coordinateArea } from '@/lib/engine/area'
import { distanceBearing } from '@/lib/engine/distance'
import type { SurveyPoint } from '@/types/surveyPoint'

interface ParcelAreaModalProps {
  isOpen: boolean
  onClose: () => void
  points: SurveyPoint[]
  onAreaResult?: (result: { squareMeters: number; hectares: number; acres: number; perimeter: number }) => void
}

export default function ParcelAreaModal({ isOpen, onClose, points, onAreaResult }: ParcelAreaModalProps) {
  const [selectedPoints, setSelectedPoints] = useState<SurveyPoint[]>([])
  const [result, setResult] = useState<{
    areaSqm: number
    areaHa: number
    areaAcres: number
    perimeter: number
  } | null>(null)

  const handlePointClick = (point: SurveyPoint) => {
    // Check if clicking first point to close
    if (selectedPoints.length >= 3 && selectedPoints[0].id === point.id) {
      calculateArea()
      return
    }
    
    // Add point if not already selected
    if (!selectedPoints.some((p) => p.id === point.id)) {
      setSelectedPoints([...selectedPoints, point])
    }
  }

  const calculateArea = () => {
    if (selectedPoints.length < 3) return

    const coords = selectedPoints.map((p) => ({
      easting: p.easting,
      northing: p.northing
    }))

    const areaResult = coordinateArea(coords)
    setResult(areaResult)
    if (onAreaResult) {
      onAreaResult({
        squareMeters: areaResult.areaSqm,
        hectares: areaResult.areaHa,
        acres: areaResult.areaAcres,
        perimeter: areaResult.perimeter
      })
    }
  }

  const clearSelection = () => {
    setSelectedPoints([])
    setResult(null)
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/70" onClick={onClose}></div>
      <div className="relative bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg p-6 w-full max-w-md">
        <h2 className="text-xl font-bold text-[var(--text-primary)] mb-4">Compute Parcel Area</h2>

        <p className="text-[var(--text-secondary)] text-sm mb-4">
          Click points on the map in boundary order. Click the first point again to close the polygon.
        </p>

        {/* Selected points list */}
        <div className="mb-4">
          <div className="flex justify-between items-center mb-2">
            <span className="text-sm text-[var(--text-primary)]">Selected Points ({selectedPoints.length})</span>
            <button
              onClick={clearSelection}
              className="text-xs text-red-400 hover:text-red-300"
            >
              Clear
            </button>
          </div>
          <div className="flex flex-wrap gap-2">
            {selectedPoints.map((p, i) => (
              <span
                key={p.id}
                className="px-2 py-1 bg-[var(--bg-tertiary)] rounded text-xs font-mono text-[var(--text-primary)]"
              >
                {i + 1}. {p.name}
              </span>
            ))}
          </div>
        </div>

        {/* Result */}
        {result && (
          <div className="mb-4 p-4 bg-[var(--bg-tertiary)]/50 rounded-lg border border-[var(--border-color)]">
            <h3 className="text-lg font-semibold text-[var(--accent)] mb-3">Parcel Area</h3>
            <div className="space-y-2 font-mono">
              <div className="flex justify-between">
                <span className="text-[var(--text-secondary)]">Area:</span>
                <span className="text-[var(--text-primary)]">{result.areaSqm.toFixed(4)} m²</span>
              </div>
              <div className="flex justify-between">
                <span className="text-[var(--text-secondary)]">Hectares:</span>
                <span className="text-[var(--text-primary)]">{result.areaHa.toFixed(6)} ha</span>
              </div>
              <div className="flex justify-between">
                <span className="text-[var(--text-secondary)]">Acres:</span>
                <span className="text-[var(--text-primary)]">{result.areaAcres.toFixed(6)} acres</span>
              </div>
              <div className="border-t border-[var(--border-color)] pt-2 mt-2 flex justify-between">
                <span className="text-[var(--text-secondary)]">Perimeter:</span>
                <span className="text-[var(--accent)] font-semibold">{result.perimeter.toFixed(4)} m</span>
              </div>
            </div>
          </div>
        )}

        <div className="flex gap-3">
          <button
            onClick={onClose}
            className="px-6 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded"
          >
            Close
          </button>
          {selectedPoints.length >= 3 && !result && (
            <button
              onClick={calculateArea}
              className="flex-1 px-6 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded"
            >
              Calculate Area
            </button>
          )}
          {result && (
            <button
              onClick={onClose}
              className="flex-1 px-6 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded"
            >
              Done
            </button>
          )}
        </div>
      </div>
    </div>
  )
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient, type BrowserSession } from '@/lib/api-client/client';
import { coordinateArea } from '@/lib/engine/area';
import { distanceBearing } from '@/lib/engine/distance';
import { logger } from '@/lib/logger'

interface Point {
  id: string;
  name: string;
  easting: number;
  northing: number;
  elevation?: number | null;
  is_control?: boolean;
  locked?: boolean;
}

interface ParcelBuilderModalProps {
  projectId: string;
  points: Point[];
  onClose: () => void;
  onParcelCreated: (parcel?: { id: string; name: string | null; boundary_points: Array<{ name?: string; easting: number; northing: number }>; created_at?: string }) => void;
  onDraftBoundaryChange?: (boundary: Array<{ easting: number; northing: number }> | null) => void;
}

interface BoundaryPoint {
  id: string;
  name: string;
  easting: number;
  northing: number;
}

interface BoundaryLine {
  from: string;
  to: string;
  bearing: string;
  bearingDeg: number;
  distance: number;
}

export default function ParcelBuilderModal({ projectId, points, onClose, onParcelCreated, onDraftBoundaryChange }: ParcelBuilderModalProps) {
  const [parcelName, setParcelName] = useState('');
  const [selectedPoints, setSelectedPoints] = useState<BoundaryPoint[]>([]);
  const [isSelecting, setIsSelecting] = useState(true);
  const [boundaryLines, setBoundaryLines] = useState<BoundaryLine[]>([]);
  const [areaResult, setAreaResult] = useState<{
    areaSqm: number;
    areaHa: number;
    areaAcres: number;
    perimeter: number;
  } | null>(null);
  const [saving, setSaving] = useState(false);
  const dbClient = createClient();

  const computeParcel = useCallback(() => {
    if (selectedPoints.length < 3) {
      setBoundaryLines([]);
      setAreaResult(null);
      return;
    }

    const coords = selectedPoints.map((p) => ({ easting: p.easting, northing: p.northing }));
    const areaData = coordinateArea(coords);

    const lines: BoundaryLine[] = [];
    for (let i = 0; i < selectedPoints.length; i++) {
      const from = selectedPoints[i];
      const to = selectedPoints[(i + 1) % selectedPoints.length];
      const db = distanceBearing(from, to);
      lines.push({
        from: from.name,
        to: to.name,
        bearing: db.bearingDMS,
        bearingDeg: db.bearing,
        distance: db.distance
      });
    }

    setBoundaryLines(lines);
    setAreaResult({
      areaSqm: areaData.areaSqm,
      areaHa: areaData.areaHa,
      areaAcres: areaData.areaAcres,
      perimeter: areaData.perimeter
    });
  }, [selectedPoints]);

  useEffect(() => {
    if (selectedPoints.length >= 3) {
      computeParcel();
    } else {
      setBoundaryLines([]);
      setAreaResult(null);
    }
  }, [selectedPoints, computeParcel]);

  const handlePointClick = (point: Point) => {
    if (!isSelecting) return;

    const firstPoint = selectedPoints[0]
    if (selectedPoints.length > 0 && firstPoint && firstPoint.id === point.id) {
      if (selectedPoints.length >= 3) setIsSelecting(false);
      return;
    }

    if (selectedPoints.find((p) => p.id === point.id)) return;

    setSelectedPoints([
      ...selectedPoints,
      {
        id: point.id,
        name: point.name,
        easting: point.easting,
        northing: point.northing
      }
    ]);
  };

  const handleSave = async () => {
    if (!parcelName || selectedPoints.length < 3 || !areaResult) return;

    setSaving(true);
    try {
      const { data: { session } } = await dbClient.auth.getSession();
      const user = (session as BrowserSession | null)?.user;

      const { data, error } = await dbClient.from('parcels').insert({
        project_id: projectId,
        name: parcelName,
        point_ids: selectedPoints.map((p) => p.id),
        boundary_points: selectedPoints.map((p) => ({
          name: p.name,
          easting: p.easting,
          northing: p.northing
        })),
        area_sqm: areaResult.areaSqm,
        area_ha: areaResult.areaHa,
        area_acres: areaResult.areaAcres,
        perimeter_m: areaResult.perimeter,
        created_by: user?.id
            }).select('id, name, boundary_points, created_at').single() as unknown as { data: { id: string; name: string | null; boundary_points: Array<{ name?: string; easting: number; northing: number }>; created_at?: string } | null; error: unknown };

      if (error) throw error;

      onParcelCreated((data ?? undefined) as { id: string; name: string | null; boundary_points: Array<{ name?: string; easting: number; northing: number }>; created_at?: string });
      onClose();
    } catch (err) {
      logger.error('Error saving parcel:', { error: err });
      alert('Failed to save parcel');
    } finally {
      setSaving(false);
    }
  };

  const handleReset = () => {
    setSelectedPoints([]);
    setIsSelecting(true);
    setBoundaryLines([]);
    setAreaResult(null);
    setParcelName('');
  };

  return (
    <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 p-4">
      <div className="bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-xl max-w-4xl w-full max-h-[90vh] overflow-y-auto">
        <div className="p-6 border-b border-[var(--border-color)] flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold text-white">Build Parcel</h2>
            <p className="text-sm text-[var(--text-secondary)]">Click points in boundary order. Click first point to close.</p>
          </div>
          <button onClick={onClose} className="text-[var(--text-secondary)] hover:text-white text-2xl">&times;</button>
        </div>

        <div className="p-6 space-y-6">
          <div className="grid md:grid-cols-2 gap-6">
            <div>
              <h3 className="font-semibold text-[var(--text-primary)] mb-3">Available Points</h3>
              <div className="bg-[var(--bg-tertiary)] rounded-lg p-3 max-h-64 overflow-y-auto">
                {points.filter((p) => !p.locked).length === 0 ? (
                  <p className="text-[var(--text-muted)] text-sm">No points available</p>
                ) : (
                  <div className="grid grid-cols-2 gap-2">
                    {points.filter((p) => !p.locked).map((point) => {
                      const isAlreadySelected = selectedPoints.some((p) => p.id === point.id)
                      const isFirst = selectedPoints.length > 0 && selectedPoints[0].id === point.id
                      const canClose = isFirst && selectedPoints.length >= 3
                      const disabled = !isSelecting || (isAlreadySelected && !canClose)

                      return (
                        <button
                          key={point.id}
                          onClick={() => handlePointClick(point)}
                          disabled={disabled}
                          className={`px-3 py-2 rounded text-sm font-mono text-left transition-colors ${
                            isAlreadySelected
                              ? canClose
                                ? 'bg-green-900/40 border border-green-700 text-green-200 hover:bg-green-900/60'
                                : 'bg-[var(--accent)] text-black'
                              : isSelecting
                                ? 'bg-gray-700 hover:bg-[var(--border-hover)] text-[var(--text-primary)]'
                                : 'bg-[var(--bg-tertiary)] text-[var(--text-muted)] cursor-not-allowed'
                          }`}
                          title={canClose ? 'Click to close boundary' : undefined}
                        >
                          <div className="flex items-center justify-between gap-2">
                            <span>{point.name}</span>
                            {canClose ? <span className="text-xs font-sans">Close</span> : null}
                          </div>
                          <span className="text-xs text-[var(--text-secondary)] ml-1 block">
                            {point.easting.toFixed(0)}, {point.northing.toFixed(0)}
                          </span>
                        </button>
                      )
                    })}
                  </div>
                )}
              </div>

              {isSelecting && selectedPoints.length > 0 && (
                <div className="mt-4">
                  <h4 className="text-sm font-semibold text-[var(--text-primary)] mb-2">Selected Boundary ({selectedPoints.length})</h4>
                  <div className="flex flex-wrap gap-2">
                    {selectedPoints.map((p, idx) => (
                      <span key={p.id} className="px-2 py-1 bg-[var(--accent)]/20 text-[var(--accent)] rounded text-sm">
                        {p.name}
                        {idx < selectedPoints.length - 1 && ' → '}
                      </span>
                    ))}
                  </div>
                  <div className="mt-3 flex items-center gap-2">
                    <button
                      onClick={() => {
                        if (selectedPoints.length >= 3) setIsSelecting(false)
                      }}
                      disabled={selectedPoints.length < 3}
                      className="px-3 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded text-sm disabled:opacity-50"
                    >
                      Close boundary
                    </button>
                    <span className="text-xs text-[var(--text-muted)]">
                      or click the first point again
                    </span>
                  </div>
                </div>
              )}
            </div>

            <div>
              {areaResult ? (
                <div className="bg-[var(--bg-tertiary)] rounded-xl p-6">
                  <h3 className="font-bold text-white text-lg mb-4">PARCEL SUMMARY</h3>
                  {isSelecting ? (
                    <div className="mb-3 rounded border border-amber-700/50 bg-amber-900/10 px-3 py-2 text-xs text-amber-200">
                      Preview only — close the boundary (click the first point again) to enter a name and save.
                    </div>
                  ) : null}
                  <div className="border-b border-[var(--border-color)] pb-2 mb-3">
                    <span className="text-[var(--text-secondary)] text-sm">Boundary: </span>
                    <span className="text-[var(--text-primary)]">
                      {selectedPoints.map((p) => p.name).join(' → ')}
                    </span>
                  </div>

                  <div className="overflow-x-auto">
                  <table className="w-full text-sm mb-4 min-w-[300px]">
                    <thead>
                      <tr className="border-b border-[var(--border-color)]">
                        <th className="text-left py-2 text-[var(--text-secondary)]">Line</th>
                        <th className="text-right py-2 text-[var(--text-secondary)]">Bearing</th>
                        <th className="text-right py-2 text-[var(--text-secondary)]">Distance</th>
                      </tr>
                    </thead>
                    <tbody>
                      {boundaryLines.map((line, idx) => (
                        <tr key={`${line}-${idx}`} className="border-b border-[var(--border-color)]">
                          <td className="py-2 text-[var(--text-primary)]">{line.from}→{line.to}</td>
                          <td className="py-2 text-right font-mono text-[var(--text-primary)]">{line.bearing}</td>
                          <td className="py-2 text-right font-mono text-[var(--text-primary)]">{line.distance.toFixed(3)} m</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  </div>

                  <div className="space-y-2 pt-4 border-t border-[var(--border-color)]">
                    <div className="flex justify-between">
                      <span className="text-[var(--text-secondary)]">Area:</span>
                      <span className="font-mono text-white">{areaResult.areaSqm.toFixed(4)} m²</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-[var(--text-secondary)]"></span>
                      <span className="font-mono text-white">{areaResult.areaHa.toFixed(6)} ha</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-[var(--text-secondary)]"></span>
                      <span className="font-mono text-white">{areaResult.areaAcres.toFixed(4)} acres</span>
                    </div>
                    <div className="flex justify-between pt-2 border-t border-[var(--border-color)]">
                      <span className="text-[var(--text-secondary)]">Perimeter:</span>
                      <span className="font-mono text-white">{areaResult.perimeter.toFixed(3)} m</span>
                    </div>
                  </div>
                </div>
              ) : (
                <div className="bg-[var(--bg-tertiary)]/50 rounded-xl p-6 text-center">
                  <p className="text-[var(--text-muted)]">
                    {selectedPoints.length < 3
                      ? `Select at least 3 points (${3 - selectedPoints.length} more)`
                      : 'Click the first point again to close the boundary'}
                  </p>
                </div>
              )}
            </div>
          </div>

          {!isSelecting && areaResult && (
            <div className="border-t border-[var(--border-color)] pt-6">
              <div className="max-w-md">
                <label className="label" htmlFor="parcel-name">Parcel Name</label>
                <input id="parcel-name"
                  className="input"
                  value={parcelName}
                  onChange={e => setParcelName(e.target.value)}
 placeholder="e.g., Plot A, Parcel 1"
                />
              </div>
            </div>
          )}
        </div>

        <div className="p-6 border-t border-[var(--border-color)] flex gap-3 justify-end">
          <button onClick={handleReset} className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded">
            Reset
          </button>
          <button onClick={onClose} className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded">
            Cancel
          </button>
          {!isSelecting && areaResult && (
            <button
              onClick={handleSave}
              disabled={!parcelName || saving}
              className="px-6 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded disabled:opacity-50"
            >
              {saving ? 'Saving...' : 'Save Parcel'}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

'use client'

/**
 * BatchParcelImport — Bulk import parcels from CSV/GeoJSON
 *
 * Solves the Mwavumbo Ward problem: importing 200+ parcels with owner data.
 */

import { useState, useCallback, useRef } from 'react'
import {
  Upload, Loader2, CheckCircle2, AlertTriangle,
  Download, Table, Layers, Users,
} from 'lucide-react'
import { processWithProgress } from '@/lib/performance'

interface GeoJSONParcelProps {
  parcel_number?: string
  parcelNumber?: string
  name?: string
  owner_name?: string
  ownerName?: string
  owner?: string
  owner_id?: string
  ownerId?: string
  national_id?: string
  lr_number?: string
  lrNumber?: string
  title_deed?: string
  area_ha?: string
  area?: string
}

interface GeoJSONGeometry {
  type?: string
  coordinates?: unknown
}

interface GeoJSONFeature {
  properties?: GeoJSONParcelProps
  geometry?: GeoJSONGeometry
}

interface ParsedParcel {
  id: string
  parcelNumber: string
  ownerName?: string
  ownerId?: string
  lrNumber?: string
  areaHa?: number
  vertices: Array<{ easting: number; northing: number }>
  valid: boolean
  errors: string[]
}

interface BatchParcelImportProps {
  projectId: string
  onImport?: (parcels: ParsedParcel[]) => void
}

export function BatchParcelImport({ projectId, onImport }: BatchParcelImportProps) {
  const [parcels, setParcels] = useState<ParsedParcel[]>([])
  const [parsing, setParsing] = useState(false)
  const [importing, setImporting] = useState(false)
  const [importProgress, setImportProgress] = useState(0)
  const [dragOver, setDragOver] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [importResult, setImportResult] = useState<{ success: number; failed: number } | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const parseCSV = useCallback((text: string): ParsedParcel[] => {
    const lines = text.split('\n').filter(l => l.trim())
    if (lines.length < 2) return []

    const header = lines[0].split(',').map(h => h.trim().toLowerCase())
    const parcelsMap = new Map<string, ParsedParcel>()

    const colIdx = {
      parcelNumber: header.findIndex(h => h.includes('parcel') || h.includes('plot')),
      easting: header.findIndex(h => h.includes('easting') || h === 'e'),
      northing: header.findIndex(h => h.includes('northing') || h === 'n'),
      ownerName: header.findIndex(h => h.includes('owner') && h.includes('name')),
      ownerId: header.findIndex(h => h.includes('owner') && h.includes('id')),
      lrNumber: header.findIndex(h => h.includes('lr') || h.includes('title')),
      areaHa: header.findIndex(h => h.includes('area') || h.includes('ha')),
    }

    for (let i = 1; i < lines.length; i++) {
      const cols = lines[i].split(',').map(c => c.trim())
      const parcelNum = colIdx.parcelNumber >= 0 ? cols[colIdx.parcelNumber] : `PARCEL-${i}`
      const easting = colIdx.easting >= 0 ? parseFloat(cols[colIdx.easting]) : NaN
      const northing = colIdx.northing >= 0 ? parseFloat(cols[colIdx.northing]) : NaN

      if (!parcelNum || !isFinite(easting) || !isFinite(northing)) continue

      if (!parcelsMap.has(parcelNum)) {
        parcelsMap.set(parcelNum, {
          id: crypto.randomUUID(),
          parcelNumber: parcelNum,
          ownerName: colIdx.ownerName >= 0 ? cols[colIdx.ownerName] : undefined,
          ownerId: colIdx.ownerId >= 0 ? cols[colIdx.ownerId] : undefined,
          lrNumber: colIdx.lrNumber >= 0 ? cols[colIdx.lrNumber] : undefined,
          areaHa: colIdx.areaHa >= 0 ? parseFloat(cols[colIdx.areaHa]) : undefined,
          vertices: [],
          valid: true,
          errors: [],
        })
      }

      parcelsMap.get(parcelNum)!.vertices.push({ easting, northing })
    }

    const parcels = Array.from(parcelsMap.values())
    for (const parcel of parcels) {
      if (parcel.vertices.length < 3) {
        parcel.errors.push('Needs at least 3 vertices')
        parcel.valid = false
      }
      if (!parcel.parcelNumber) {
        parcel.errors.push('Missing parcel number')
        parcel.valid = false
      }
    }

    return parcels
  }, [])

  const parseGeoJSON = useCallback((text: string): ParsedParcel[] => {
    const geojson = JSON.parse(text) as { features?: GeoJSONFeature[] }
    if (!geojson.features || !Array.isArray(geojson.features)) return []

    return geojson.features.map((feature, idx: number) => {
      const props: GeoJSONParcelProps = feature.properties || {}
      const geom: GeoJSONGeometry = feature.geometry || {}

      let vertices: Array<{ easting: number; northing: number }> = []

      if (geom.type === 'Polygon') {
        const ring = ((geom.coordinates as number[][][]) || [])[0] || []
        const verts = ring.slice(0, -1)
        vertices = verts.map((c: number[]) => ({ easting: c[0], northing: c[1] }))
      } else if (geom.type === 'MultiPolygon') {
        const ring = ((geom.coordinates as number[][][][]) || [])[0]?.[0] || []
        const verts = ring.slice(0, -1)
        vertices = verts.map((c: number[]) => ({ easting: c[0], northing: c[1] }))
      }

      const errors: string[] = []
      if (vertices.length < 3) errors.push('Needs at least 3 vertices')

      return {
        id: crypto.randomUUID(),
        parcelNumber: props.parcel_number || props.parcelNumber || props.name || `PARCEL-${idx + 1}`,
        ownerName: props.owner_name || props.ownerName || props.owner,
        ownerId: props.owner_id || props.ownerId || props.national_id,
        lrNumber: props.lr_number || props.lrNumber || props.title_deed,
        areaHa: props.area_ha ? parseFloat(props.area_ha) : props.area ? parseFloat(props.area) : undefined,
        vertices,
        valid: errors.length === 0,
        errors,
      }
    })
  }, [])

  const handleFile = useCallback(async (file: File) => {
    setParsing(true)
    setError(null)
    setImportResult(null)

    try {
      const text = await file.text()
      const ext = file.name.split('.').pop()?.toLowerCase()

      let parsed: ParsedParcel[] = []
      if (ext === 'geojson' || ext === 'json') {
        parsed = parseGeoJSON(text)
      } else {
        parsed = parseCSV(text)
      }

      setParcels(parsed)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to parse file')
    } finally {
      setParsing(false)
    }
  }, [parseCSV, parseGeoJSON])

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setDragOver(false)
    const file = e.dataTransfer.files[0]
    if (file) handleFile(file)
  }, [handleFile])

  const handleImport = useCallback(async () => {
    if (parcels.length === 0) return
    setImporting(true)
    setImportProgress(0)
    setError(null)

    try {
      // For large imports (100+ parcels), process in chunks to avoid UI freeze
      if (parcels.length > 100) {
        const validParcels = parcels.filter(p => p.valid)
        const chunkSize = 50
        const totalChunks = Math.ceil(validParcels.length / chunkSize)

        let totalSuccess = 0
        let totalFailed = 0

        for (let i = 0; i < validParcels.length; i += chunkSize) {
          const chunk = validParcels.slice(i, i + chunkSize)
          const currentChunk = Math.floor(i / chunkSize) + 1

          setImportProgress((currentChunk / totalChunks) * 100)

          try {
            const res = await fetch(`/api/projects/${projectId}/parcels/batch`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                parcels: chunk.map(p => ({
                  parcelNumber: p.parcelNumber,
                  ownerName: p.ownerName,
                  ownerId: p.ownerId,
                  lrNumber: p.lrNumber,
                  areaHa: p.areaHa,
                  vertices: p.vertices,
                })),
              }),
            })
            if (res.ok) {
              const data = (await res.json()) as { data?: { imported?: number; failed?: number } }
              totalSuccess += data.data?.imported || chunk.length
              totalFailed += data.data?.failed || 0
            } else {
              totalFailed += chunk.length
            }
          } catch {
            totalFailed += chunk.length
          }

          // Yield to event loop so UI can update
          await new Promise(resolve => setTimeout(resolve, 0))
        }

        setImportProgress(100)
        setImportResult({ success: totalSuccess, failed: totalFailed })
        onImport?.(parcels)
      } else {
        // Small import — single request
        const res = await fetch(`/api/projects/${projectId}/parcels/batch`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            parcels: parcels.map(p => ({
              parcelNumber: p.parcelNumber,
              ownerName: p.ownerName,
              ownerId: p.ownerId,
              lrNumber: p.lrNumber,
              areaHa: p.areaHa,
              vertices: p.vertices,
            })),
          }),
        })

        if (!res.ok) {
          const data = (await res.json()) as { error?: string }
          throw new Error(data.error || 'Import failed')
        }

        const data = (await res.json()) as { data?: { imported?: number; failed?: number } }
        setImportResult({
          success: data.data?.imported || parcels.length,
          failed: data.data?.failed || 0,
        })
        setImportProgress(100)
        onImport?.(parcels)
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Import failed')
    } finally {
      setImporting(false)
    }
  }, [parcels, projectId, onImport])

  const downloadTemplate = useCallback(() => {
    const csv = `parcel_number,easting,northing,owner_name,owner_id,lr_number,area_ha
MWAVUMBO/001,534850.123,9574220.456,John Doe,12345678,LR/12345/678,0.5000
MWAVUMBO/001,534852.456,9574221.789,John Doe,12345678,LR/12345/678,0.5000
MWAVUMBO/001,534854.789,9574222.123,John Doe,12345678,LR/12345/678,0.5000
MWAVUMBO/001,534850.123,9574220.456,John Doe,12345678,LR/12345/678,0.5000
MWAVUMBO/002,534860.000,9574230.000,Jane Smith,87654321,LR/12345/679,0.7500
MWAVUMBO/002,534862.000,9574231.000,Jane Smith,87654321,LR/12345/679,0.7500
MWAVUMBO/002,534864.000,9574232.000,Jane Smith,87654321,LR/12345/679,0.7500
MWAVUMBO/002,534860.000,9574230.000,Jane Smith,87654321,LR/12345/679,0.7500`
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = 'metardu-parcel-template.csv'
    a.click()
    URL.revokeObjectURL(url)
  }, [])

  const validCount = parcels.filter(p => p.valid).length
  const invalidCount = parcels.length - validCount

  return (
    <div className="space-y-4">
      <div
        onDragOver={(e) => { e.preventDefault(); setDragOver(true) }}
        onDragLeave={() => setDragOver(false)}
        onDrop={handleDrop}
        onClick={() => fileInputRef.current?.click()}
        className={`rounded-xl border-2 border-dashed p-8 text-center cursor-pointer transition-all ${
          dragOver ? 'border-[var(--accent)] bg-[var(--accent)]/5' : 'border-[var(--border-color)] hover:border-[var(--accent)]/50'
        }`}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept=".csv,.geojson,.json"
          onChange={(e) => e.target.files?.[0] && handleFile(e.target.files[0])}
          className="hidden"
        />
        {parsing ? (
          <div className="flex flex-col items-center">
            <Loader2 className="w-8 h-8 text-[var(--accent)] animate-spin mb-2" />
            <p className="text-sm text-gray-400">Parsing file...</p>
          </div>
        ) : (
          <div className="flex flex-col items-center">
            <div className="w-12 h-12 rounded-xl bg-[var(--accent)]/10 flex items-center justify-center mb-3">
              <Upload className="w-6 h-6 text-[var(--accent)]" />
            </div>
            <p className="text-sm font-medium text-[var(--text-primary)]">
              Drop CSV or GeoJSON here, or click to browse
            </p>
            <p className="text-[10px] text-gray-500 mt-1">
              Supports parcel boundaries with owner data — up to 1000 parcels
            </p>
          </div>
        )}
      </div>

      <div className="flex items-center justify-between">
        <button
          onClick={downloadTemplate}
          className="flex items-center gap-1.5 px-3 h-8 rounded-lg bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-xs text-gray-400 hover:text-gray-200"
        >
          <Download className="w-3.5 h-3.5" />
          Download CSV Template
        </button>
        {parcels.length > 0 && (
          <button onClick={() => setParcels([])} className="text-[10px] text-gray-500 hover:text-gray-300">
            Clear
          </button>
        )}
      </div>

      {error && (
        <div className="p-3 rounded-lg bg-red-500/5 border border-red-500/20 flex items-start gap-2">
          <AlertTriangle className="w-4 h-4 text-red-400 shrink-0 mt-0.5" />
          <p className="text-xs text-red-400">{error}</p>
        </div>
      )}

      {importResult && (
        <div className="p-3 rounded-lg bg-emerald-500/5 border border-emerald-500/20 flex items-start gap-2">
          <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0 mt-0.5" />
          <div>
            <p className="text-xs text-emerald-400 font-medium">
              Import complete: {importResult.success} parcels imported
            </p>
            {importResult.failed > 0 && (
              <p className="text-[10px] text-amber-400">{importResult.failed} failed</p>
            )}
          </div>
        </div>
      )}

      {parcels.length > 0 && (
        <div className="card p-4">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              <Table className="w-4 h-4 text-[var(--accent)]" />
              <span className="text-sm font-semibold text-[var(--text-primary)]">
                Preview ({parcels.length} parcels)
              </span>
            </div>
            <div className="flex items-center gap-3 text-[10px]">
              <span className="flex items-center gap-1 text-emerald-400">
                <CheckCircle2 className="w-3 h-3" />
                {validCount} valid
              </span>
              {invalidCount > 0 && (
                <span className="flex items-center gap-1 text-red-400">
                  <AlertTriangle className="w-3 h-3" />
                  {invalidCount} errors
                </span>
              )}
            </div>
          </div>

          <div className="max-h-[300px] overflow-y-auto">
            <table className="w-full">
              <thead className="sticky top-0 bg-[var(--bg-card)]">
                <tr className="border-b border-[var(--border-color)]">
                  <th className="px-2 py-2 text-left text-[9px] text-gray-500 uppercase">Parcel No.</th>
                  <th className="px-2 py-2 text-left text-[9px] text-gray-500 uppercase">Owner</th>
                  <th className="px-2 py-2 text-center text-[9px] text-gray-500 uppercase">Vertices</th>
                  <th className="px-2 py-2 text-right text-[9px] text-gray-500 uppercase">Area (ha)</th>
                  <th className="px-2 py-2 text-center text-[9px] text-gray-500 uppercase">Status</th>
                </tr>
              </thead>
              <tbody>
                {parcels.map(parcel => (
                  <tr key={parcel.id} className="border-b border-[var(--border-color)]/50">
                    <td className="px-2 py-2 text-xs font-mono text-[var(--text-primary)]">{parcel.parcelNumber}</td>
                    <td className="px-2 py-2 text-xs text-gray-400">{parcel.ownerName || '—'}</td>
                    <td className="px-2 py-2 text-xs text-center text-gray-400">{parcel.vertices.length}</td>
                    <td className="px-2 py-2 text-xs text-right font-mono text-gray-400">{parcel.areaHa ? parcel.areaHa.toFixed(4) : '—'}</td>
                    <td className="px-2 py-2 text-center">
                      {parcel.valid ? <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400 inline" /> : <AlertTriangle className="w-3.5 h-3.5 text-red-400 inline" />}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <button
            onClick={handleImport}
            disabled={importing || validCount === 0}
            className="w-full mt-3 flex items-center justify-center gap-2 h-10 rounded-lg bg-[var(--accent)] text-black text-sm font-semibold hover:bg-[var(--accent-dim)] disabled:opacity-40 disabled:cursor-not-allowed"
          >
            {importing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Layers className="w-4 h-4" />}
            {importing ? `${importProgress > 0 ? Math.round(importProgress) + '%' : 'Importing...'}` : `Import ${validCount} Parcels to Project`}
          </button>
        </div>
      )}

      <div className="flex items-start gap-2 p-3 rounded-lg bg-blue-500/5 border border-blue-500/10">
        <Users className="w-3.5 h-3.5 text-blue-400 shrink-0 mt-0.5" />
        <div className="text-[10px] text-blue-400/70 leading-relaxed">
          <p className="font-medium mb-1">CSV Format:</p>
          <p>Each row = one vertex. Multiple rows with the same parcel_number = one parcel&apos;s vertices.</p>
          <p className="mt-1">Columns: parcel_number, easting, northing, owner_name, owner_id, lr_number, area_ha</p>
          <p className="mt-1 font-medium">GeoJSON: Polygon features with properties for owner data.</p>
        </div>
      </div>
    </div>
  )
}

'use client'

/**
 * CollaborationPanel — Combined presence + chat panel for project workspaces
 *
 * Features:
 * - Online collaborators with avatars
 * - Live chat messages
 * - Send messages
 * - Conflict warnings
 * - Collapsible panel
 */

import { useState, useCallback, useRef, useEffect } from 'react'
import {
  MessageSquare, Send, Users, ChevronDown, ChevronUp,
  AlertTriangle, X,
} from 'lucide-react'
import { PresenceIndicator } from './PresenceIndicator'
import type { Collaborator } from '@/lib/realtime/useCollaboration'

interface ChatMessage {
  id: string
  userId: string
  userName: string
  message: string
  timestamp: number
}

interface CollaborationPanelProps {
  collaborators: Collaborator[]
  isConnected: boolean
  messages: ChatMessage[]
  onSend: (message: string) => void
  conflictWarnings?: string[]
}

export function CollaborationPanel({
  collaborators,
  isConnected,
  messages,
  onSend,
  conflictWarnings = [],
}: CollaborationPanelProps) {
  const [expanded, setExpanded] = useState(true)
  const [input, setInput] = useState('')
  const messagesEndRef = useRef<HTMLDivElement>(null)

  // Auto-scroll to bottom on new message
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  const handleSend = useCallback(() => {
    if (!input.trim()) return
    onSend(input.trim())
    setInput('')
  }, [input, onSend])

  const handleKeyPress = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSend()
    }
  }, [handleSend])

  return (
    <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
      {/* Header */}
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between px-4 py-3 hover:bg-[var(--bg-tertiary)]/50 transition-colors"
      >
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
            <Users className="w-4 h-4 text-[var(--accent)]" />
          </div>
          <div className="text-left">
            <span className="text-sm font-semibold text-[var(--text-primary)]">Team Collaboration</span>
            <p className="text-[10px] text-gray-500">
              {isConnected
                ? `${collaborators.length + 1} online`
                : 'Disconnected'}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <PresenceIndicator collaborators={collaborators} isConnected={isConnected} max={4} />
          {expanded ? <ChevronUp className="w-4 h-4 text-gray-500" /> : <ChevronDown className="w-4 h-4 text-gray-500" />}
        </div>
      </button>

      {expanded && (
        <div className="border-t border-[var(--border-color)]">
          {/* Conflict warnings */}
          {conflictWarnings.length > 0 && (
            <div className="p-2 bg-amber-500/5 border-b border-amber-500/10">
              {conflictWarnings.map((warning, i) => (
                <div key={`${warning}-${i}`} className="flex items-center gap-1.5 text-[10px] text-amber-400">
                  <AlertTriangle className="w-3 h-3 shrink-0" />
                  {warning}
                </div>
              ))}
            </div>
          )}

          {/* Chat messages */}
          <div className="max-h-[200px] overflow-y-auto p-3 space-y-2">
            {messages.length === 0 ? (
              <div className="text-center py-4">
                <MessageSquare className="w-6 h-6 text-gray-600 mx-auto mb-1" />
                <p className="text-[10px] text-gray-500">No messages yet</p>
                <p className="text-[9px] text-gray-600">Start a conversation with your team</p>
              </div>
            ) : (
              messages.map(msg => (
                <div key={msg.id} className="flex items-start gap-2">
                  <div className="shrink-0 w-6 h-6 rounded-full bg-[var(--accent)]/10 flex items-center justify-center text-[9px] font-bold text-[var(--accent)]">
                    {msg.userName.split(' ').map(n => n[0]).slice(0, 2).join('').toUpperCase()}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-baseline gap-1.5">
                      <span className="text-[10px] font-medium text-[var(--text-primary)]">{msg.userName}</span>
                      <span className="text-[8px] text-gray-600">
                        {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                    </div>
                    <p className="text-[11px] text-[var(--text-secondary)] break-words">{msg.message}</p>
                  </div>
                </div>
              ))
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input */}
          <div className="border-t border-[var(--border-color)] p-2 flex items-center gap-2">
            <input aria-label="Type a message"
              type="text"
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={handleKeyPress}
              placeholder={isConnected ? 'Type a message...' : 'Disconnected'}
              disabled={!isConnected}
              className="flex-1 h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none disabled:opacity-50"
            />
            <button
              onClick={handleSend}
              disabled={!isConnected || !input.trim()}
              aria-label="Send message"
              className="w-8 h-8 flex items-center justify-center rounded-lg bg-[var(--accent)] text-black disabled:opacity-40 disabled:cursor-not-allowed hover:bg-[var(--accent-dim)]"
            >
              <Send className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useRef, useEffect } from 'react'
import { useLanguage } from '@/lib/i18n/LanguageContext'
// XSS guard (2026-08-03): sheetId is built from user-entered district / location / registration-unit / sheet fields.
// It lands in the print document's <title> (RCDATA breakout) — must be XML-escaped before interpolation.
import { escapeXml } from '@/lib/xml/escape'

interface RIMParcel {
  id: string
  number: string
  x: number
  y: number
  width: number
  height: number
  area: string
  description: string
  color: string
  subParcelIds?: string[]
}

interface RIMAmendment {
  id: string
  date: string
  reference: string
  description: string
  edition: string
  affectedPlots: string
}

interface RIMSheetIndex {
  rows: number
  cols: number
  currentRow: number
  currentCol: number
}

interface RegistryIndexMapProps {
  isOpen: boolean
  onClose: () => void
  initialData?: {
    district?: string
    location?: string
    subLocation?: string
    registrationUnit?: string
    sheetNumber?: string
    edition?: string
    scale?: string
    parcels?: RIMParcel[]
  }
}

const PARCEL_COLORS = [
  '#fef3c7', '#d1fae5', '#dbeafe', '#ede9fe',
  '#fce7f3', '#ffedd5', '#f0fdf4', '#fafafa',
]

export default function RegistryIndexMap({ isOpen, onClose, initialData }: RegistryIndexMapProps) {
  const { t } = useLanguage()
  const printRef = useRef<HTMLDivElement>(null)

  const [district, setDistrict] = useState(initialData?.district ?? '')
  const [location, setLocation] = useState(initialData?.location ?? '')
  const [subLocation, setSubLocation] = useState(initialData?.subLocation ?? '')
  const [registrationUnit, setRegistrationUnit] = useState(initialData?.registrationUnit ?? '')
  const [sheetNumber, setSheetNumber] = useState(initialData?.sheetNumber ?? '1')
  const [edition, setEdition] = useState(initialData?.edition ?? '1st EDITION')
  const [scale, setScale] = useState(initialData?.scale ?? '1:2,500')
  const [amendments, setAmendments] = useState<RIMAmendment[]>([])
  const [parcels, setParcels] = useState<RIMParcel[]>(initialData?.parcels ?? [])
  const [selectedParcel, setSelectedParcel] = useState<string | null>(null)
  const [nextParcelNum, setNextParcelNum] = useState(1)
  const [mode, setMode] = useState<'view' | 'edit'>('view')

  const [sheetIndex, setSheetIndex] = useState<RIMSheetIndex>({
    rows: 3, cols: 3, currentRow: 1, currentCol: 1,
  })

  useEffect(() => {
    if (!isOpen) return
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose()
    }
    window.addEventListener('keydown', handleKey)
    return () => window.removeEventListener('keydown', handleKey)
  }, [isOpen, onClose])

  const sheetId = [district.toUpperCase(), location.toUpperCase(), registrationUnit.toUpperCase(), `SHEET ${sheetNumber}`]
    .filter(Boolean).join(' / ')

  const addParcel = () => {
    const gridCols = 4
    const row = Math.floor((nextParcelNum - 1) / gridCols)
    const col = (nextParcelNum - 1) % gridCols
    const cellW = 180
    const cellH = 120
    const padding = 8
    const newParcel: RIMParcel = {
      id: crypto.randomUUID(),
      number: String(nextParcelNum),
      x: padding + col * (cellW + padding),
      y: padding + row * (cellH + padding),
      width: cellW,
      height: cellH,
      area: '',
      description: '',
      color: PARCEL_COLORS[(nextParcelNum - 1) % PARCEL_COLORS.length],
    }
    setParcels(prev => [...prev, newParcel])
    setNextParcelNum(n => n + 1)
  }

  const updateParcel = (id: string, updates: Partial<RIMParcel>) => {
    setParcels(prev => prev.map((p) => p.id === id ? { ...p, ...updates } : p))
  }

  const removeParcel = (id: string) => {
    setParcels(prev => prev.filter((p) => p.id !== id))
    setSelectedParcel(null)
  }

  const addAmendment = () => {
    const prevEdition = amendments.length > 0
      ? amendments[amendments.length - 1].edition
      : edition
    const nextEd = parseInt(prevEdition.replace(/\D/g, '')) || 1
    setAmendments(prev => [...prev, {
      id: crypto.randomUUID(),
      date: new Date().toLocaleDateString('en-GB'),
      reference: '',
      description: '',
      edition: `${nextEd + 1}TH ED`,
      affectedPlots: '',
    }])
  }

  const updateAmendment = (id: string, updates: Partial<RIMAmendment>) => {
    setAmendments(prev => prev.map((a) => a.id === id ? { ...a, ...updates } : a))
  }

  const handlePrint = () => {
    const content = printRef.current
    if (!content) return
    const win = window.open('', '_blank')
    if (!win) return
    win.document.write(`<!DOCTYPE html>
<html>
<head>
  <title>RIM - ${escapeXml(sheetId)}</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: 'Courier New', monospace; background: white; padding: 20px; }
    .sheet {
      width: 210mm; min-height: 297mm;
      border: 2px solid #000;
      padding: 12mm;
      position: relative;
      background: white;
      page-break-after: always;
    }
    .sheet-header {
      text-align: center;
      border-bottom: 2px solid #000;
      padding-bottom: 6px;
      margin-bottom: 8px;
    }
    .sheet-title {
      font-size: 16pt;
      font-weight: bold;
      text-decoration: underline;
      letter-spacing: 1px;
    }
    .sheet-id {
      font-size: 11pt;
      margin-top: 2px;
    }
    .meta-row {
      display: flex;
      gap: 12px;
      margin-bottom: 6px;
      font-size: 9pt;
      flex-wrap: wrap;
    }
    .meta-item { display: flex; gap: 4px; }
    .meta-label { font-weight: bold; }
    .grid-area {
      display: grid;
      grid-template-columns: repeat(${sheetIndex.cols}, 1fr);
      grid-template-rows: repeat(${sheetIndex.rows}, 40px);
      border: 1px solid #999;
      margin-bottom: 8px;
    }
    .grid-cell {
      border: 1px solid #999;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 7pt;
      background: #f9f9f9;
    }
    .grid-cell.current {
      background: #000;
      color: white;
      font-weight: bold;
    }
    .parcel-map {
      border: 1px solid #000;
      min-height: 400px;
      position: relative;
      background: #f5f5f5;
      margin-bottom: 8px;
    }
    .parcel {
      position: absolute;
      border: 1.5px solid #000;
      background: #fff;
      cursor: pointer;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
    }
    .parcel.selected { outline: 2px solid #2563eb; }
    .parcel-num { font-size: 9pt; font-weight: bold; }
    .parcel-area { font-size: 7pt; color: #555; }
    .parcel-sub { font-size: 6pt; color: #888; }
    .history-table {
      width: 100%;
      border-collapse: collapse;
      font-size: 7pt;
      margin-bottom: 6px;
    }
    .history-table th, .history-table td {
      border: 1px solid #000;
      padding: 3px 5px;
      text-align: left;
    }
    .history-table th { background: #000; color: #fff; }
    .footer-row {
      display: flex;
      justify-content: space-between;
      font-size: 7pt;
      margin-top: 4px;
      border-top: 1px solid #000;
      padding-top: 4px;
    }
    @media print {
      body { padding: 0; }
      .sheet { border: none; margin: 0; }
    }
  </style>
</head>
<body>
</body>
</html>`)
    win.document.close()
    // XSS guard (2026-08-03): the sheet body is React-rendered DOM whose text
    // nodes are auto-escaped — clone the node into the print document instead of
    // serializing innerHTML back into a document.write() string.
    win.document.body.append(content.cloneNode(true))
    win.focus()
    setTimeout(() => { win.print(); win.close() }, 500)
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center bg-black/60 overflow-y-auto p-4">
      <div className="w-full max-w-5xl bg-white rounded-lg shadow-2xl overflow-hidden">
        {/* Toolbar */}
        <div className="bg-gray-800 text-white px-4 py-3 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="text-lg font-bold tracking-wide">[Clip]</span>
            <h2 className="font-semibold">Registry Index Map (RIM)</h2>
            <span className="text-xs bg-amber-600 px-2 py-0.5 rounded">Kenya — General Boundaries</span>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setMode(m => m === 'view' ? 'edit' : 'view')}
              className="px-3 py-1 text-xs bg-gray-700 hover:bg-gray-600 rounded"
            >
              {mode === 'view' ? '[Edit] Edit Sheet' : ' View'}
            </button>
            <button
              onClick={handlePrint}
              className="px-3 py-1 text-xs bg-blue-600 hover:bg-blue-500 rounded"
            >
               Print / Export
            </button>
            <button
              onClick={onClose}
              className="px-3 py-1 text-xs bg-gray-700 hover:bg-gray-600 rounded"
            >
              [x] Close
            </button>
          </div>
        </div>

        <div className="flex">
          {/* Sidebar controls */}
          {mode === 'edit' && (
            <div className="w-72 border-r border-gray-200 bg-gray-50 p-4 overflow-y-auto max-h-[90vh]">
              <h3 className="text-sm font-bold mb-3 text-gray-700 uppercase tracking-wide">Sheet Details</h3>

              <div className="space-y-3">
                <div>
                  <label className="text-xs font-semibold text-gray-600" htmlFor="district">District</label>
                  <input id="district" value={district} onChange={e => setDistrict(e.target.value)}
                    className="w-full px-2 py-1 border rounded text-sm uppercase" placeholder="e.g. KAJIADO" />
                </div>
                <div>
                  <label className="text-xs font-semibold text-gray-600" htmlFor="location">Location</label>
                  <input id="location" value={location} onChange={e => setLocation(e.target.value)}
                    className="w-full px-2 py-1 border rounded text-sm uppercase" placeholder="e.g. ILKISONGO" />
                </div>
                <div>
                  <label className="text-xs font-semibold text-gray-600" htmlFor="sub-location-registration-unit">Sub-Location / Registration Unit</label>
                  <input id="sub-location-registration-unit" value={registrationUnit} onChange={e => setRegistrationUnit(e.target.value)}
                    className="w-full px-2 py-1 border rounded text-sm uppercase" placeholder="e.g. ENTARARA" />
                </div>
                <div className="grid grid-cols-2 gap-2">
                  <div>
                    <label className="text-xs font-semibold text-gray-600" htmlFor="sheet-no">Sheet No.</label>
                    <input id="sheet-no" aria-label="Sheet No." type="number" value={sheetNumber} onChange={e => setSheetNumber(e.target.value)}
                      className="w-full px-2 py-1 border rounded text-sm" min={1} />
                  </div>
                  <div>
                    <label className="text-xs font-semibold text-gray-600" htmlFor="edition">Edition</label>
                    <input id="edition" value={edition} onChange={e => setEdition(e.target.value)}
                      className="w-full px-2 py-1 border rounded text-sm" placeholder="e.g. 1ST EDITION" />
                  </div>
                </div>
                <div>
                  <label className="text-xs font-semibold text-gray-600" htmlFor="scale">Scale</label>
                  <select  id="scale" value={scale} onChange={e => setScale(e.target.value)}
                    className="w-full px-2 py-1 border rounded text-sm">
                    <option value="1:2,500">1:2,500 (Land Consolidation / Adjudication)</option>
                    <option value="1:5,000">1:5,000 (Large-scale farms / Settlement)</option>
                    <option value="1:10,000">1:10,000 (Subdivision of large farms)</option>
                    <option value="1:50,000">1:50,000 (Pastoral / Range Provisional)</option>
                  </select>
                </div>

                <div className="border-t pt-3">
                  <h4 className="text-xs font-bold text-gray-700 mb-2">Sheet Index (Adjacent Sheets)</h4>
                  <div className="grid grid-cols-3 gap-1 mb-2">
                    {[[0,0],[0,1],[0,2],[1,0],[1,1,'●'],[1,2],[2,0],[2,1],[2,2]].map(([r,c,label],i) => (
                      <button key={`item-${i}`}
                        onClick={() => setSheetIndex(s => ({...s, currentRow: r as number, currentCol: c as number}))}
                        className={`h-8 text-xs rounded border ${r===sheetIndex.currentRow&&c===sheetIndex.currentCol?'bg-black text-white':'bg-gray-100 hover:bg-gray-200'}`}
                      >
                        {label ?? `${Number(r!)+1}-${Number(c!)+1}`}
                      </button>
                    ))}
                  </div>
                  <input type="text" aria-label="Index notes" placeholder="e.g. Sheet 2 to North"
                    className="w-full px-2 py-1 border rounded text-xs" />
                </div>

                <div className="border-t pt-3">
                  <div className="flex items-center justify-between mb-2">
                    <h4 className="text-xs font-bold text-gray-700">Parcels ({parcels.length})</h4>
                    <button onClick={addParcel}
                      className="px-2 py-1 text-xs bg-green-600 text-white rounded hover:bg-green-700">
                      + Add Parcel
                    </button>
                  </div>
                  <div className="space-y-1 max-h-48 overflow-y-auto">
                    {parcels.map((p) => (
                      <div key={p.id}
                        className={`flex items-center gap-1 p-1 rounded border cursor-pointer text-xs ${selectedParcel === p.id ? 'bg-blue-50 border-blue-400' : 'border-gray-200 hover:bg-gray-50'}`}
                        onClick={() => setSelectedParcel(p.id)}
                      >
                        <div className="w-4 h-4 rounded border" style={{background: p.color, borderColor: '#000'}} />
                        <span className="font-bold w-6">{p.number}.</span>
                        <input value={p.area} onChange={e => updateParcel(p.id, {area: e.target.value})}
                          onClick={e => e.stopPropagation()}
                          aria-label="Area (ha)"
                          className="flex-1 px-1 border rounded text-xs" />
                        <button onClick={e => { e.stopPropagation(); removeParcel(p.id) }}
                          className="text-red-500 hover:text-red-700 font-bold px-1">[x]</button>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="border-t pt-3">
                  <div className="flex items-center justify-between mb-2">
                    <h4 className="text-xs font-bold text-gray-700">Sheet History ({amendments.length})</h4>
                    <button onClick={addAmendment}
                      className="px-2 py-1 text-xs bg-gray-700 text-white rounded hover:bg-gray-600">
                      + Amendment
                    </button>
                  </div>
                  <div className="space-y-2">
                    {amendments.map((a) => (
                      <div key={a.id} className="border rounded p-2 bg-white text-xs space-y-1">
                        <div className="grid grid-cols-2 gap-1">
                          <input value={a.date} onChange={e => updateAmendment(a.id, {date: e.target.value})}
                            className="px-1 border rounded" aria-label="Date" />
                          <input value={a.edition} onChange={e => updateAmendment(a.id, {edition: e.target.value})}
                            className="px-1 border rounded" aria-label="Edition" />
                        </div>
                        <input value={a.reference} onChange={e => updateAmendment(a.id, {reference: e.target.value})}
                          className="w-full px-1 border rounded" aria-label="Reference (e.g. MUT/2/1036/1/88)" />
                        <input value={a.description} onChange={e => updateAmendment(a.id, {description: e.target.value})}
                          className="w-full px-1 border rounded" aria-label="Description (e.g. SUBDIV 904 INTO 3054-3061)" />
                        <input value={a.affectedPlots} onChange={e => updateAmendment(a.id, {affectedPlots: e.target.value})}
                          className="w-full px-1 border rounded" aria-label="Affected parcels" />
                        <button onClick={() => setAmendments(prev => prev.filter((x) => x.id !== a.id))}
                          className="text-red-500 hover:text-red-700 text-xs">Remove</button>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Print area */}
          <div className="flex-1 bg-gray-100 p-4 overflow-auto max-h-[90vh]">
            <div ref={printRef} className="bg-white">
              <RIMSheetContent
                sheetId={sheetId}
                district={district}
                location={location}
                subLocation={subLocation}
                registrationUnit={registrationUnit}
                sheetNumber={sheetNumber}
                edition={edition}
                scale={scale}
                parcels={parcels}
                selectedParcel={selectedParcel}
                amendments={amendments}
                sheetIndex={sheetIndex}
                mode={mode}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

function RIMSheetContent({
  sheetId, district, location, registrationUnit, sheetNumber, edition, scale,
  parcels, selectedParcel, amendments, sheetIndex, mode
}: {
  sheetId: string
  district: string; location: string; subLocation: string; registrationUnit: string
  sheetNumber: string; edition: string; scale: string
  parcels: RIMParcel[]; selectedParcel: string | null
  amendments: RIMAmendment[]
  sheetIndex: RIMSheetIndex
  mode: 'view' | 'edit'
}) {
  return (
    <div className="w-[210mm] min-h-[297mm] p-[12mm] border-2 border-black bg-white relative font-mono">
      {/* Header */}
      <div className="text-center border-b-2 border-black pb-2 mb-3">
        <div className="text-base font-bold underline tracking-widest uppercase">
          REGISTRY INDEX MAP
        </div>
        <div className="text-xs mt-1 tracking-wider">
          {sheetId || 'DISTRICT / LOCATION / REGISTRATION UNIT / SHEET N'}
        </div>
      </div>

      {/* Scale + Edition */}
      <div className="flex justify-between text-xs mb-2 px-1">
        <div><span className="font-bold">Scale:</span> {scale}</div>
        <div><span className="font-bold">Edition:</span> {edition || '—'}</div>
        <div><span className="font-bold">Sheet:</span> {sheetNumber || '1'}</div>
      </div>

      {/* Sheet Index (mini grid of adjacent sheets) */}
      <div className="flex items-start gap-2 mb-3">
        <div>
          <div className="text-[7pt] font-bold mb-0.5 uppercase">Sheet Index</div>
          <div className={`grid gap-px bg-gray-400 border border-gray-400`}
            style={{gridTemplateColumns: `repeat(${sheetIndex.cols}, 18px)`, gridTemplateRows: `repeat(${sheetIndex.rows}, 14px)`}}>
            {Array.from({length: sheetIndex.rows * sheetIndex.cols}).map((_, i) => {
              const r = Math.floor(i / sheetIndex.cols)
              const c = i % sheetIndex.cols
              const isCurrent = r === sheetIndex.currentRow && c === sheetIndex.currentCol
              const adjSheets = ['NW', 'N', 'NE', 'W', '●', 'E', 'SW', 'S', 'SE']
              return (
                <div key={`${_}-${i}`}
                  className={`flex items-center justify-center text-[6pt] ${isCurrent ? 'bg-black text-white font-bold' : 'bg-gray-100'}`}
                  title={adjSheets[i] ?? `${r+1}-${c+1}`}
                >
                  {isCurrent ? '●' : adjSheets[i]}
                </div>
              )
            })}
          </div>
          <div className="text-[6pt] text-gray-500 mt-0.5">
            {sheetIndex.currentRow === 0 ? 'North' : ''} {sheetIndex.currentCol === 0 ? 'West' : ''}
          </div>
        </div>

        {/* Sub-location / Location */}
        <div className="text-xs flex-1 border border-gray-300 p-1 bg-gray-50">
          <div className="font-bold text-[8pt] mb-1">Location Reference</div>
          <div className="grid grid-cols-2 gap-x-4 text-[7pt]">
            <div><span className="font-bold">District:</span> {district || '—'}</div>
            <div><span className="font-bold">Location:</span> {location || '—'}</div>
            <div><span className="font-bold">Sub-Location:</span> {(location as unknown as { subLocation?: string })?.subLocation || '—'}</div>
            <div><span className="font-bold">Reg. Unit:</span> {registrationUnit || '—'}</div>
          </div>
        </div>
      </div>

      {/* North Arrow */}
      <div className="absolute top-[38mm] right-[12mm] text-center">
        <div className="text-[8pt] font-bold">N</div>
        <svg width="28" height="36" viewBox="0 0 28 36">
          <polygon points="14,2 4,30 14,24 24,30" fill="#000" />
          <line x1="14" y1="8" x2="14" y2="34" stroke="#000" strokeWidth="1" />
          <text x="16" y="8" fontSize="7" fontWeight="bold" fill="#000">N</text>
        </svg>
        <div className="text-[6pt] text-gray-500">↑ Heading</div>
      </div>

      {/* Parcel Map Area */}
      <div className="border border-black mb-3 min-h-[360px] relative bg-gray-50/50"
        style={{height: 'auto', minHeight: '360px'}}>
        {/* Grid overlay */}
        <div className="absolute inset-0 pointer-events-none"
          style={{
            backgroundImage: 'linear-gradient(#ccc 1px, transparent 1px), linear-gradient(90deg, #ccc 1px, transparent 1px)',
            backgroundSize: '40px 40px',
          }} />

        {parcels.length === 0 ? (
          <div className="flex items-center justify-center h-full min-h-[360px] text-gray-400 text-sm">
            {mode === 'edit' ? '← Add parcels using the panel →' : 'No parcels on this sheet'}
          </div>
        ) : (
          parcels.map((p) => (
            <div key={p.id}
              className={`absolute flex flex-col items-center justify-center cursor-pointer ${selectedParcel === p.id ? 'outline-2 outline-blue-500' : ''}`}
              style={{
                left: p.x, top: p.y, width: p.width, height: p.height,
                background: p.color,
              }}
            >
              <span className="text-[9pt] font-bold leading-none">{p.number}</span>
              {p.area && <span className="text-[7pt] text-gray-600">{p.area} ha</span>}
              <div className="border-t border-black/30 w-3/4 mt-0.5" />
            </div>
          ))
        )}
      </div>

      {/* Parcel List Table */}
      {parcels.length > 0 && (
        <div className="mb-3">
          <div className="text-[7pt] font-bold border-b border-black pb-0.5 mb-1">PARCEL REGISTER</div>
          <table className="w-full border-collapse text-[7pt]">
            <thead>
              <tr className="bg-black text-white">
                <th className="border border-gray-400 px-1 py-0.5 text-left w-10">No.</th>
                <th className="border border-gray-400 px-1 py-0.5 text-left">Parcel Ref.</th>
                <th className="border border-gray-400 px-1 py-0.5 text-right w-16">Area (ha)</th>
                <th className="border border-gray-400 px-1 py-0.5 text-left">Remarks</th>
              </tr>
            </thead>
            <tbody>
              {parcels.map((p, i) => (
                <tr key={p.id} className={i % 2 === 0 ? 'bg-white' : 'bg-gray-50'}>
                  <td className="border border-gray-300 px-1 py-0.5 text-center font-bold">{p.number}</td>
                  <td className="border border-gray-300 px-1 py-0.5 uppercase">{[district, location, registrationUnit, p.number].filter(Boolean).join('/')}</td>
                  <td className="border border-gray-300 px-1 py-0.5 text-right">{p.area || '—'}</td>
                  <td className="border border-gray-300 px-1 py-0.5 text-gray-500">{p.description || '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Sheet History Table */}
      <div className="mb-3">
        <div className="text-[7pt] font-bold border-b border-black pb-0.5 mb-1 uppercase">
          Sheet History — Amendments & Subdivisions
        </div>
        {amendments.length === 0 ? (
          <div className="text-[7pt] text-gray-400 italic border border-dashed border-gray-300 p-1">
            No amendments recorded
          </div>
        ) : (
          <table className="w-full border-collapse text-[7pt]">
            <thead>
              <tr className="bg-black text-white">
                <th className="border border-gray-400 px-1 py-0.5 text-left w-14">Date</th>
                <th className="border border-gray-400 px-1 py-0.5 text-left w-28">Reference</th>
                <th className="border border-gray-400 px-1 py-0.5 text-left">Description</th>
                <th className="border border-gray-400 px-1 py-0.5 text-left w-14">Edition</th>
                <th className="border border-gray-400 px-1 py-0.5 text-left">Plots Affected</th>
              </tr>
            </thead>
            <tbody>
              {amendments.map((a, i) => (
                <tr key={a.id} className={i % 2 === 0 ? 'bg-white' : 'bg-gray-50'}>
                  <td className="border border-gray-300 px-1 py-0.5">{a.date}</td>
                  <td className="border border-gray-300 px-1 py-0.5 font-mono">{a.reference || '—'}</td>
                  <td className="border border-gray-300 px-1 py-0.5 uppercase">{a.description || '—'}</td>
                  <td className="border border-gray-300 px-1 py-0.5 font-bold">{a.edition}</td>
                  <td className="border border-gray-300 px-1 py-0.5">{a.affectedPlots || '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* Footer */}
      <div className="flex justify-between items-end text-[6pt] text-gray-600 border-t border-black pt-1 mt-1">
        <div>
          <span className="font-bold">NOTE:</span> Boundaries shown are GENERAL boundaries (undetermined precise line).
          Measurements must be obtained from field sheets / mutation forms.
        </div>
        <div className="text-right">
          <div>Registered Land Act (Cap. 300) — Director of Surveys</div>
          <div>RIM Sheet {sheetNumber} — {edition}</div>
        </div>
      </div>

      {/* Scale bar */}
      <div className="absolute bottom-[12mm] left-[12mm]">
        <div className="text-[6pt] mb-0.5">Scale: {scale}</div>
        <div className="flex items-end">
          {[0, 10, 20, 30, 40].map((_, i) => (
            <div key={`${_}-${i}`} className="flex items-end">
              <div className={`h-3 ${i % 2 === 0 ? 'bg-black w-4' : 'bg-black/50 w-2'}`} />
            </div>
          ))}
          <span className="text-[6pt] ml-1">m</span>
        </div>
      </div>
    </div>
  )
}

'use client'

/**
 * ReportTemplateEditor — Drag-and-drop document layout designer
 *
 * Inspired by QGIS Print Composer. Lets surveyors design custom document
 * templates by placing elements on a canvas:
 * - Map view (auto-scaled to fit)
 * - Text blocks (titles, labels, surveyor info)
 * - Tables (beacon schedule, area schedule)
 * - North arrow
 * - Scale bar
 * - Company logo
 * - Grid overlay
 *
 * Features:
 * - Drag elements from palette to canvas
 * - Resize/move elements with mouse
 * - Per-element styling (font, color, position, size)
 * - Template presets (deed plan, mutation, traverse sheet)
 * - Save/load templates to localStorage
 * - Preview before generating PDF
 * - Lock elements to prevent accidental moves
 *
 * This gives surveyors full control over document layout without
 * needing a developer to modify templates.
 */

import { useState, useCallback, useRef, useEffect } from 'react'
import {
  Type, Map as MapIcon, Table, Navigation, Ruler,
  Image, Grid3x3, Save, FolderOpen, Eye, Trash2,
  Lock, Unlock, Copy, Download, Plus, Settings2,
  Move, Maximize2,
} from 'lucide-react'

type ElementType = 'text' | 'map' | 'table' | 'north_arrow' | 'scale_bar' | 'logo' | 'grid'

interface TemplateElement {
  id: string
  type: ElementType
  x: number      // mm from left
  y: number      // mm from top
  width: number  // mm
  height: number // mm
  locked: boolean
  // Type-specific properties
  text?: string
  fontSize?: number
  fontWeight?: 'normal' | 'bold'
  align?: 'left' | 'center' | 'right'
  color?: string
  // Table
  tableData?: Array<Array<string>>
  // Map
  scale?: number
  // Logo
  logoUrl?: string
}

interface ReportTemplate {
  id: string
  name: string
  paperSize: 'A4' | 'A3' | 'A2' | 'A1'
  orientation: 'portrait' | 'landscape'
  elements: TemplateElement[]
}

// ---------------------------------------------------------------------------
// Paper sizes (mm)
// ---------------------------------------------------------------------------

const PAPER_DIMENSIONS = {
  A4: { width: 210, height: 297 },
  A3: { width: 297, height: 420 },
  A2: { width: 420, height: 594 },
  A1: { width: 594, height: 841 },
}

// ---------------------------------------------------------------------------
// Element palette
// ---------------------------------------------------------------------------

const ELEMENT_PALETTE: Array<{
  type: ElementType
  label: string
  icon: typeof Type
  defaultSize: { width: number; height: number }
}> = [
  { type: 'text', label: 'Text', icon: Type, defaultSize: { width: 80, height: 10 } },
  { type: 'map', label: 'Map', icon: MapIcon, defaultSize: { width: 150, height: 100 } },
  { type: 'table', label: 'Table', icon: Table, defaultSize: { width: 120, height: 60 } },
  { type: 'north_arrow', label: 'North Arrow', icon: Navigation, defaultSize: { width: 15, height: 20 } },
  { type: 'scale_bar', label: 'Scale Bar', icon: Ruler, defaultSize: { width: 50, height: 8 } },
  { type: 'logo', label: 'Logo', icon: Image, defaultSize: { width: 30, height: 15 } },
  { type: 'grid', label: 'Grid', icon: Grid3x3, defaultSize: { width: 150, height: 100 } },
]

// ---------------------------------------------------------------------------
// Template presets
// ---------------------------------------------------------------------------

const TEMPLATE_PRESETS: Array<{
  name: string
  description: string
  paperSize: 'A4' | 'A3' | 'A2' | 'A1'
  orientation: 'portrait' | 'landscape'
  elements: Omit<TemplateElement, 'id'>[]
}> = [
  {
    name: 'Deed Plan (A1 Landscape)',
    description: 'Standard SoK deed plan layout',
    paperSize: 'A1',
    orientation: 'landscape',
    elements: [
      { type: 'text', x: 297, y: 10, width: 297, height: 15, locked: false, text: 'REPUBLIC OF KENYA — DEED PLAN', fontSize: 8, fontWeight: 'bold', align: 'center' },
      { type: 'map', x: 20, y: 40, width: 400, height: 300, locked: false, scale: 2500 },
      { type: 'north_arrow', x: 410, y: 50, width: 15, height: 20, locked: false },
      { type: 'scale_bar', x: 30, y: 340, width: 50, height: 8, locked: false },
      { type: 'table', x: 440, y: 100, width: 130, height: 200, locked: false, tableData: [['BEACON', 'E', 'N'], ['MB/001', '534850.123', '9574220.456']] },
      { type: 'text', x: 440, y: 40, width: 130, height: 8, locked: false, text: 'LR No: ___________', fontSize: 4 },
      { type: 'text', x: 440, y: 320, width: 130, height: 20, locked: false, text: 'Surveyor: ___________\nLicense: ___________', fontSize: 3 },
    ],
  },
  {
    name: 'Mutation Form (A3 Landscape)',
    description: 'Subdivision mutation layout',
    paperSize: 'A3',
    orientation: 'landscape',
    elements: [
      { type: 'text', x: 148.5, y: 10, width: 297, height: 12, locked: false, text: 'MUTATION FORM', fontSize: 7, fontWeight: 'bold', align: 'center' },
      { type: 'map', x: 20, y: 40, width: 200, height: 150, locked: false, scale: 2500 },
      { type: 'north_arrow', x: 220, y: 50, width: 12, height: 16, locked: false },
      { type: 'scale_bar', x: 25, y: 195, width: 40, height: 6, locked: false },
      { type: 'table', x: 240, y: 60, width: 100, height: 120, locked: false, tableData: [['PARCEL', 'AREA (ha)'], ['001', '0.5000'], ['002', '0.7500']] },
      { type: 'text', x: 20, y: 260, width: 200, height: 15, locked: false, text: 'Surveyor: ___________  License: ___________', fontSize: 3 },
    ],
  },
  {
    name: 'Traverse Sheet (A4 Portrait)',
    description: 'Traverse computation sheet',
    paperSize: 'A4',
    orientation: 'portrait',
    elements: [
      { type: 'text', x: 105, y: 10, width: 210, height: 10, locked: false, text: 'TRAVERSE COMPUTATION SHEET', fontSize: 5, fontWeight: 'bold', align: 'center' },
      { type: 'table', x: 20, y: 40, width: 170, height: 200, locked: false, tableData: [['STATION', 'BEARING', 'DISTANCE', 'dE', 'dN']] },
      { type: 'text', x: 20, y: 260, width: 170, height: 15, locked: false, text: 'Linear Error: _______  Precision: 1:_______', fontSize: 3 },
    ],
  },
]

// ---------------------------------------------------------------------------
// Main Component
// ---------------------------------------------------------------------------

export function ReportTemplateEditor() {
  const [template, setTemplate] = useState<ReportTemplate>({
    id: crypto.randomUUID(),
    name: 'Untitled Template',
    paperSize: 'A4',
    orientation: 'portrait',
    elements: [],
  })
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [draggingFrom, setDraggingFrom] = useState<ElementType | null>(null)
  const [draggingElement, setDraggingElement] = useState<{ id: string; offsetX: number; offsetY: number } | null>(null)
  const [resizing, setResizing] = useState<{ id: string; handle: string } | null>(null)
  const [showPreview, setShowPreview] = useState(false)
  const canvasRef = useRef<HTMLDivElement>(null)

  const paper = PAPER_DIMENSIONS[template.paperSize]
  const canvasWidth = template.orientation === 'landscape' ? paper.height : paper.width
  const canvasHeight = template.orientation === 'landscape' ? paper.width : paper.height

  // Scale canvas to fit viewport (1mm = 2px for display)
  const displayScale = 2
  const displayWidth = canvasWidth * displayScale
  const displayHeight = canvasHeight * displayScale

  // ─── Add element from palette ─────────────────────────────────
  const addElement = useCallback((type: ElementType) => {
    const paletteItem = ELEMENT_PALETTE.find(p => p.type === type)
    if (!paletteItem) return

    const newElement: TemplateElement = {
      id: crypto.randomUUID(),
      type,
      x: 20,
      y: 20,
      width: paletteItem.defaultSize.width,
      height: paletteItem.defaultSize.height,
      locked: false,
    }

    // Default text for text elements
    if (type === 'text') {
      newElement.text = 'Double-click to edit text'
      newElement.fontSize = 4
      newElement.fontWeight = 'normal'
      newElement.align = 'left'
    }
    if (type === 'table') {
      newElement.tableData = [['Header 1', 'Header 2'], ['Cell 1', 'Cell 2']]
    }

    setTemplate(prev => ({
      ...prev,
      elements: [...prev.elements, newElement],
    }))
    setSelectedId(newElement.id)
  }, [])

  // ─── Move element ──────────────────────────────────────────────
  const handleElementMouseDown = useCallback((e: React.MouseEvent, element: TemplateElement) => {
    if (element.locked) return
    e.stopPropagation()
    setSelectedId(element.id)
    const rect = canvasRef.current?.getBoundingClientRect()
    if (!rect) return

    const scale = rect.width / canvasWidth
    const mouseX = (e.clientX - rect.left) / scale
    const mouseY = (e.clientY - rect.top) / scale

    setDraggingElement({
      id: element.id,
      offsetX: mouseX - element.x,
      offsetY: mouseY - element.y,
    })
  }, [canvasWidth, canvasHeight])

  // ─── Resize element ────────────────────────────────────────────
  const handleResizeMouseDown = useCallback((e: React.MouseEvent, elementId: string, handle: string) => {
    e.stopPropagation()
    e.preventDefault()
    setResizing({ id: elementId, handle })
  }, [])

  // ─── Mouse move (drag/resize) ──────────────────────────────────
  useEffect(() => {
    if (!draggingElement && !resizing) return

    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvasRef.current?.getBoundingClientRect()
      if (!rect) return

      const scale = rect.width / canvasWidth
      const mouseX = (e.clientX - rect.left) / scale
      const mouseY = (e.clientY - rect.top) / scale

      if (draggingElement) {
        setTemplate(prev => ({
          ...prev,
          elements: prev.elements.map(el =>
            el.id === draggingElement.id
              ? {
                  ...el,
                  x: Math.max(0, Math.min(canvasWidth - el.width, mouseX - draggingElement.offsetX)),
                  y: Math.max(0, Math.min(canvasHeight - el.height, mouseY - draggingElement.offsetY)),
                }
              : el
          ),
        }))
      }

      if (resizing) {
        setTemplate(prev => ({
          ...prev,
          elements: prev.elements.map(el => {
            if (el.id !== resizing.id) return el
            let { x, y, width, height } = el

            if (resizing.handle.includes('e')) width = Math.max(10, mouseX - x)
            if (resizing.handle.includes('s')) height = Math.max(10, mouseY - y)
            if (resizing.handle.includes('w')) {
              const newX = Math.min(x + width - 10, mouseX)
              width = width + (x - newX)
              x = newX
            }
            if (resizing.handle.includes('n')) {
              const newY = Math.min(y + height - 10, mouseY)
              height = height + (y - newY)
              y = newY
            }

            return { ...el, x, y, width, height }
          }),
        }))
      }
    }

    const handleMouseUp = () => {
      setDraggingElement(null)
      setResizing(null)
    }

    document.addEventListener('mousemove', handleMouseMove)
    document.addEventListener('mouseup', handleMouseUp)

    return () => {
      document.removeEventListener('mousemove', handleMouseMove)
      document.removeEventListener('mouseup', handleMouseUp)
    }
  }, [draggingElement, resizing, canvasWidth, canvasHeight])

  // ─── Delete element ────────────────────────────────────────────
  const deleteElement = useCallback((id: string) => {
    setTemplate(prev => ({
      ...prev,
      elements: prev.elements.filter(e => e.id !== id),
    }))
    setSelectedId(null)
  }, [])

  // ─── Duplicate element ─────────────────────────────────────────
  const duplicateElement = useCallback((id: string) => {
    const element = template.elements.find(e => e.id === id)
    if (!element) return

    const newElement: TemplateElement = {
      ...element,
      id: crypto.randomUUID(),
      x: element.x + 10,
      y: element.y + 10,
    }

    setTemplate(prev => ({
      ...prev,
      elements: [...prev.elements, newElement],
    }))
    setSelectedId(newElement.id)
  }, [template.elements])

  // ─── Toggle lock ───────────────────────────────────────────────
  const toggleLock = useCallback((id: string) => {
    setTemplate(prev => ({
      ...prev,
      elements: prev.elements.map(e =>
        e.id === id ? { ...e, locked: !e.locked } : e
      ),
    }))
  }, [])

  // ─── Update element property ───────────────────────────────────
  const updateElement = useCallback((id: string, updates: Partial<TemplateElement>) => {
    setTemplate(prev => ({
      ...prev,
      elements: prev.elements.map(e =>
        e.id === id ? { ...e, ...updates } : e
      ),
    }))
  }, [])

  // ─── Load preset ───────────────────────────────────────────────
  const loadPreset = useCallback((preset: typeof TEMPLATE_PRESETS[0]) => {
    setTemplate({
      id: crypto.randomUUID(),
      name: preset.name,
      paperSize: preset.paperSize,
      orientation: preset.orientation,
      elements: preset.elements.map(e => ({ ...e, id: crypto.randomUUID() })),
    })
    setSelectedId(null)
  }, [])

  // ─── Save template ─────────────────────────────────────────────
  const saveTemplate = useCallback(() => {
    const templates = JSON.parse(localStorage.getItem('metardu-report-templates') || '[]') as ReportTemplate[]
    const existing = templates.findIndex((t: ReportTemplate) => t.id === template.id)
    if (existing >= 0) {
      templates[existing] = template
    } else {
      templates.push(template)
    }
    localStorage.setItem('metardu-report-templates', JSON.stringify(templates))
    alert(`Template "${template.name}" saved`)
  }, [template])

  // ─── Load saved templates ──────────────────────────────────────
  const [savedTemplates, setSavedTemplates] = useState<ReportTemplate[]>([])
  const refreshSavedTemplates = useCallback(() => {
    const templates = JSON.parse(localStorage.getItem('metardu-report-templates') || '[]') as ReportTemplate[]
    setSavedTemplates(templates)
  }, [])

  useEffect(() => {
    refreshSavedTemplates()
  }, [refreshSavedTemplates])

  const loadTemplate = useCallback((t: ReportTemplate) => {
    setTemplate(t)
    setSelectedId(null)
  }, [])

  const selectedElement = template.elements.find(e => e.id === selectedId)

  return (
    <div className="flex flex-col lg:flex-row gap-4 h-full">
      {/* Left sidebar — element palette + presets */}
      <div className="w-full lg:w-64 space-y-4">
        {/* Element palette */}
        <div className="card p-3">
          <div className="text-[10px] font-semibold text-gray-500 uppercase tracking-wider mb-2">Elements</div>
          <div className="grid grid-cols-2 gap-1.5">
            {ELEMENT_PALETTE.map(item => {
              const Icon = item.icon
              return (
                <button
                  key={item.type}
                  onClick={() => addElement(item.type)}
                  className="flex flex-col items-center gap-1 py-2 rounded-lg border border-[var(--border-color)] hover:border-[var(--accent)]/30 hover:bg-[var(--accent)]/5 transition-colors"
                >
                  <Icon className="w-4 h-4 text-gray-400" />
                  <span className="text-[9px] text-gray-400">{item.label}</span>
                </button>
              )
            })}
          </div>
        </div>

        {/* Template presets */}
        <div className="card p-3">
          <div className="text-[10px] font-semibold text-gray-500 uppercase tracking-wider mb-2">Presets</div>
          <div className="space-y-1.5">
            {TEMPLATE_PRESETS.map(preset => (
              <button
                key={preset.name}
                onClick={() => loadPreset(preset)}
                className="w-full text-left p-2 rounded-lg border border-[var(--border-color)] hover:border-[var(--accent)]/30 hover:bg-[var(--accent)]/5 transition-colors"
              >
                <div className="text-xs font-medium text-[var(--text-primary)]">{preset.name}</div>
                <div className="text-[9px] text-gray-500">{preset.description}</div>
              </button>
            ))}
          </div>
        </div>

        {/* Saved templates */}
        <div className="card p-3">
          <div className="flex items-center justify-between mb-2">
            <div className="text-[10px] font-semibold text-gray-500 uppercase tracking-wider">Saved</div>
            <button onClick={refreshSavedTemplates} className="text-[9px] text-gray-500 hover:text-gray-300">
              Refresh
            </button>
          </div>
          {savedTemplates.length === 0 ? (
            <p className="text-[10px] text-gray-600 text-center py-2">No saved templates</p>
          ) : (
            <div className="space-y-1.5">
              {savedTemplates.map(t => (
                <button
                  key={t.id}
                  onClick={() => loadTemplate(t)}
                  className="w-full text-left p-2 rounded-lg border border-[var(--border-color)] hover:border-[var(--accent)]/30 hover:bg-[var(--accent)]/5 transition-colors"
                >
                  <div className="text-xs text-[var(--text-primary)] truncate">{t.name}</div>
                  <div className="text-[9px] text-gray-500">{t.paperSize} {t.orientation}</div>
                </button>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Center — canvas */}
      <div className="flex-1 flex flex-col">
        {/* Toolbar */}
        <div className="flex items-center justify-between mb-3 px-2">
          <div className="flex items-center gap-2">
            <input aria-label="Name"
              type="text"
              value={template.name}
              onChange={e => setTemplate(prev => ({ ...prev, name: e.target.value }))}
              className="h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] focus:border-[var(--accent)]/30 focus:outline-none"
            />
            <select
              value={template.paperSize}
              onChange={e => setTemplate(prev => ({ ...prev, paperSize: e.target.value as 'A4' | 'A3' | 'A2' | 'A1' }))}
              className="h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)]"
            >
              <option value="A4">A4</option>
              <option value="A3">A3</option>
              <option value="A2">A2</option>
              <option value="A1">A1</option>
            </select>
            <select
              value={template.orientation}
              onChange={e => setTemplate(prev => ({ ...prev, orientation: e.target.value as 'portrait' | 'landscape' }))}
              className="h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)]"
            >
              <option value="portrait">Portrait</option>
              <option value="landscape">Landscape</option>
            </select>
          </div>
          <div className="flex items-center gap-1.5">
            <button
              onClick={() => setShowPreview(!showPreview)}
              className={`flex items-center gap-1 px-2.5 h-8 rounded-lg text-xs font-medium ${
                showPreview ? 'bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)]' : 'bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-gray-400'
              }`}
            >
              <Eye className="w-3.5 h-3.5" />
              Preview
            </button>
            <button
              onClick={saveTemplate}
              className="flex items-center gap-1 px-2.5 h-8 rounded-lg bg-[var(--accent)] text-black text-xs font-semibold hover:bg-[var(--accent-dim)]"
            >
              <Save className="w-3.5 h-3.5" />
              Save
            </button>
          </div>
        </div>

        {/* Canvas */}
        <div className="flex-1 overflow-auto bg-[var(--bg-primary)] rounded-xl border border-[var(--border-color)] p-8 flex items-start justify-center">
          <div
            ref={canvasRef}
            onClick={() => setSelectedId(null)}
            className="relative bg-white shadow-2xl"
            style={{
              width: displayWidth,
              height: displayHeight,
              backgroundImage: showPreview
                ? 'none'
                : `linear-gradient(rgba(0,0,0,0.03) 1px, transparent 1px),
                   linear-gradient(90deg, rgba(0,0,0,0.03) 1px, transparent 1px)`,
              backgroundSize: `${displayScale * 10}px ${displayScale * 10}px`,
            }}
          >
            {/* Render elements */}
            {template.elements.map(element => (
              <ElementRenderer
                key={element.id}
                element={element}
                scale={displayScale}
                isSelected={element.id === selectedId}
                isPreview={showPreview}
                onMouseDown={(e) => handleElementMouseDown(e, element)}
                onResizeMouseDown={handleResizeMouseDown}
                onDelete={() => deleteElement(element.id)}
                onDuplicate={() => duplicateElement(element.id)}
                onToggleLock={() => toggleLock(element.id)}
                onEditText={(text) => updateElement(element.id, { text })}
              />
            ))}
          </div>
        </div>
      </div>

      {/* Right sidebar — properties */}
      {selectedElement && (
        <div className="w-full lg:w-64">
          <PropertiesPanel
            element={selectedElement}
            onUpdate={(updates) => updateElement(selectedElement.id, updates)}
            onDelete={() => deleteElement(selectedElement.id)}
            onDuplicate={() => duplicateElement(selectedElement.id)}
            onToggleLock={() => toggleLock(selectedElement.id)}
          />
        </div>
      )}
    </div>
  )
}

// ---------------------------------------------------------------------------
// Element Renderer
// ---------------------------------------------------------------------------

function ElementRenderer({
  element,
  scale,
  isSelected,
  isPreview,
  onMouseDown,
  onResizeMouseDown,
  onDelete,
  onDuplicate,
  onToggleLock,
  onEditText,
}: {
  element: TemplateElement
  scale: number
  isSelected: boolean
  isPreview: boolean
  onMouseDown: (e: React.MouseEvent) => void
  onResizeMouseDown: (e: React.MouseEvent, id: string, handle: string) => void
  onDelete: () => void
  onDuplicate: () => void
  onToggleLock: () => void
  onEditText: (text: string) => void
}) {
  const [editing, setEditing] = useState(false)

  const style: React.CSSProperties = {
    position: 'absolute',
    left: element.x * scale,
    top: element.y * scale,
    width: element.width * scale,
    height: element.height * scale,
    cursor: element.locked ? 'default' : 'move',
  }

  const content = () => {
    switch (element.type) {
      case 'text':
        return editing ? (
          <textarea
            autoFocus
            defaultValue={element.text}
            onBlur={(e) => { onEditText(e.target.value); setEditing(false) }}
            onKeyDown={(e) => { if (e.key === 'Escape') setEditing(false) }}
            className="w-full h-full p-1 text-black bg-white border-2 border-blue-400 outline-none resize-none"
            style={{ fontSize: (element.fontSize || 4) * scale, fontWeight: element.fontWeight, textAlign: element.align }}
          />
        ) : (
          <div
            onDoubleClick={() => !element.locked && setEditing(true)}
            className="w-full h-full flex items-center"
            style={{
              fontSize: (element.fontSize || 4) * scale,
              fontWeight: element.fontWeight,
              textAlign: element.align,
              color: element.color || '#000',
              padding: '2px',
              whiteSpace: 'pre-wrap',
            }}
          >
            {element.text || 'Double-click to edit'}
          </div>
        )

      case 'map':
        return (
          <div className="w-full h-full border-2 border-gray-400 bg-gray-100 flex items-center justify-center relative overflow-hidden">
            <MapIcon className="w-8 h-8 text-gray-300" />
            {element.scale && (
              <span className="absolute bottom-1 right-1 text-[8px] text-gray-500 font-mono">
                1:{element.scale}
              </span>
            )}
          </div>
        )

      case 'table':
        return (
          <div className="w-full h-full overflow-hidden border border-gray-400">
            <table className="w-full h-full">
              <tbody>
                {(element.tableData || []).map((row, i) => (
                  <tr key={`${row}-${i}`} className={i === 0 ? 'bg-gray-200 font-bold' : ''}>
                    {row.map((cell, j) => (
                      <td key={j} className="border border-gray-300 px-1 text-[8px] text-black">
                        {cell}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )

      case 'north_arrow':
        return (
          <div className="w-full h-full flex flex-col items-center justify-center">
            <Navigation className="w-full h-3/4 text-black" />
            <span className="text-[8px] font-bold text-black">N</span>
          </div>
        )

      case 'scale_bar':
        return (
          <div className="w-full h-full flex flex-col items-center justify-center border border-gray-400 bg-white">
            <div className="flex w-full h-1/2">
              <div className="flex-1 bg-black"></div>
              <div className="flex-1 bg-white border-l border-black"></div>
              <div className="flex-1 bg-black"></div>
              <div className="flex-1 bg-white border-l border-black"></div>
            </div>
            <span className="text-[6px] text-black">0 25 50m</span>
          </div>
        )

      case 'logo':
        return (
          <div className="w-full h-full border-2 border-dashed border-gray-400 flex items-center justify-center bg-gray-50">
            {/* lucide-react icon (decorative) — hidden from AT; rule targets next/image components */}
            {/* eslint-disable-next-line jsx-a11y/alt-text */}
            <Image aria-hidden="true" className="w-4 h-4 text-gray-400" />
          </div>
        )

      case 'grid':
        return (
          <div
            className="w-full h-full border border-gray-300"
            style={{
              backgroundImage: `linear-gradient(rgba(0,0,0,0.1) 1px, transparent 1px),
                                 linear-gradient(90deg, rgba(0,0,0,0.1) 1px, transparent 1px)`,
              backgroundSize: `${scale * 10}px ${scale * 10}px`,
            }}
          />
        )
    }
  }

  return (
    <div
      style={style}
      onMouseDown={onMouseDown}
      className={isSelected && !isPreview ? 'ring-2 ring-blue-400' : ''}
    >
      {content()}

      {/* Resize handles (only when selected and not locked and not preview) */}
      {isSelected && !element.locked && !isPreview && (
        <>
          {/* Resize handles */}
          {['nw', 'n', 'ne', 'e', 'se', 's', 'sw', 'w'].map(handle => (
            <div
              key={handle}
              onMouseDown={(e) => onResizeMouseDown(e, element.id, handle)}
              className="absolute w-2 h-2 bg-blue-400 border border-white"
              style={{
                cursor: `${handle}-resize`,
                ...(handle.includes('n') && { top: '-4px' }),
                ...(handle.includes('s') && { bottom: '-4px' }),
                ...(handle.includes('w') && { left: '-4px' }),
                ...(handle.includes('e') && { right: '-4px' }),
                ...(handle === 'n' || handle === 's' ? { left: '50%', transform: 'translateX(-50%)' } : {}),
                ...(handle === 'e' || handle === 'w' ? { top: '50%', transform: 'translateY(-50%)' } : {}),
              }}
            />
          ))}

          {/* Action buttons */}
          <div className="absolute -top-7 right-0 flex items-center gap-0.5 bg-white rounded shadow-lg p-0.5">
            <button onClick={(e) => { e.stopPropagation(); onToggleLock() }} className="w-5 h-5 flex items-center justify-center hover:bg-gray-100 rounded">
              {element.locked ? <Lock className="w-3 h-3 text-gray-600" /> : <Unlock className="w-3 h-3 text-gray-600" />}
            </button>
            <button onClick={(e) => { e.stopPropagation(); onDuplicate() }} className="w-5 h-5 flex items-center justify-center hover:bg-gray-100 rounded">
              <Copy className="w-3 h-3 text-gray-600" />
            </button>
            <button onClick={(e) => { e.stopPropagation(); onDelete() }} className="w-5 h-5 flex items-center justify-center hover:bg-red-100 rounded">
              <Trash2 className="w-3 h-3 text-red-500" />
            </button>
          </div>
        </>
      )}
    </div>
  )
}

// ---------------------------------------------------------------------------
// Properties Panel
// ---------------------------------------------------------------------------

function PropertiesPanel({
  element,
  onUpdate,
  onDelete,
  onDuplicate,
  onToggleLock,
}: {
  element: TemplateElement
  onUpdate: (updates: Partial<TemplateElement>) => void
  onDelete: () => void
  onDuplicate: () => void
  onToggleLock: () => void
}) {
  return (
    <div className="card p-3 space-y-3">
      <div className="flex items-center justify-between">
        <span className="text-[10px] font-semibold text-gray-500 uppercase tracking-wider">
          {element.type.replace('_', ' ')} Properties
        </span>
        <div className="flex items-center gap-0.5">
          <button onClick={onToggleLock} aria-label={element.locked ? 'Unlock element' : 'Lock element'} className="w-6 h-6 flex items-center justify-center hover:bg-white/[0.06] rounded">
            {element.locked ? <Lock className="w-3 h-3 text-gray-400" /> : <Unlock className="w-3 h-3 text-gray-400" />}
          </button>
          <button onClick={onDuplicate} aria-label="Duplicate element" className="w-6 h-6 flex items-center justify-center hover:bg-white/[0.06] rounded">
            <Copy className="w-3 h-3 text-gray-400" />
          </button>
          <button onClick={onDelete} aria-label="Delete element" className="w-6 h-6 flex items-center justify-center hover:bg-red-500/10 rounded">
            <Trash2 className="w-3 h-3 text-red-400" />
          </button>
        </div>
      </div>

      {/* Position */}
      <div className="grid grid-cols-2 gap-2">
        <div>
          <label className="block text-[9px] text-gray-500 uppercase mb-0.5">X (mm)</label>
          <input aria-label="X (mm)"
            type="number"
            value={Math.round(element.x)}
            onChange={e => onUpdate({ x: parseFloat(e.target.value) || 0 })}
            className="w-full h-7 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-[var(--text-primary)]"
          />
        </div>
        <div>
          <label className="block text-[9px] text-gray-500 uppercase mb-0.5">Y (mm)</label>
          <input aria-label="Y (mm)"
            type="number"
            value={Math.round(element.y)}
            onChange={e => onUpdate({ y: parseFloat(e.target.value) || 0 })}
            className="w-full h-7 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-[var(--text-primary)]"
          />
        </div>
      </div>

      {/* Size */}
      <div className="grid grid-cols-2 gap-2">
        <div>
          <label className="block text-[9px] text-gray-500 uppercase mb-0.5">Width (mm)</label>
          <input aria-label="Width (mm)"
            type="number"
            value={Math.round(element.width)}
            onChange={e => onUpdate({ width: parseFloat(e.target.value) || 10 })}
            className="w-full h-7 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-[var(--text-primary)]"
          />
        </div>
        <div>
          <label className="block text-[9px] text-gray-500 uppercase mb-0.5">Height (mm)</label>
          <input aria-label="Height (mm)"
            type="number"
            value={Math.round(element.height)}
            onChange={e => onUpdate({ height: parseFloat(e.target.value) || 10 })}
            className="w-full h-7 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-[var(--text-primary)]"
          />
        </div>
      </div>

      {/* Text-specific properties */}
      {element.type === 'text' && (
        <>
          <div>
            <label className="block text-[9px] text-gray-500 uppercase mb-0.5">Text Content</label>
            <textarea
              value={element.text || ''}
              onChange={e => onUpdate({ text: e.target.value })}
              rows={3}
              className="w-full px-2 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-[var(--text-primary)] resize-none"
            />
          </div>
          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="block text-[9px] text-gray-500 uppercase mb-0.5">Font Size (mm)</label>
              <input aria-label="Font Size (mm)"
                type="number"
                step="0.5"
                value={element.fontSize || 4}
                onChange={e => onUpdate({ fontSize: parseFloat(e.target.value) || 4 })}
                className="w-full h-7 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-[var(--text-primary)]"
              />
            </div>
            <div>
              <label className="block text-[9px] text-gray-500 uppercase mb-0.5">Align</label>
              <select
                value={element.align || 'left'}
                onChange={e => onUpdate({ align: e.target.value as 'left' | 'center' | 'right' })}
                className="w-full h-7 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-[var(--text-primary)]"
              >
                <option value="left">Left</option>
                <option value="center">Center</option>
                <option value="right">Right</option>
              </select>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => onUpdate({ fontWeight: element.fontWeight === 'bold' ? 'normal' : 'bold' })}
              className={`px-2 h-7 rounded text-xs font-bold ${element.fontWeight === 'bold' ? 'bg-[var(--accent)]/10 text-[var(--accent)] border border-[var(--accent)]/30' : 'bg-[var(--bg-tertiary)] text-gray-400 border border-[var(--border-color)]'}`}
            >
              B
            </button>
            <input aria-label="Color picker"
              type="color"
              value={element.color || '#000000'}
              onChange={e => onUpdate({ color: e.target.value })}
              className="w-7 h-7 rounded border border-[var(--border-color)] cursor-pointer"
            />
          </div>
        </>
      )}

      {/* Map-specific properties */}
      {element.type === 'map' && (
        <div>
          <label className="block text-[9px] text-gray-500 uppercase mb-0.5">Scale (1:N)</label>
          <select
            value={element.scale || 2500}
            onChange={e => onUpdate({ scale: parseInt(e.target.value) })}
            className="w-full h-7 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-[var(--text-primary)]"
          >
            <option value={500}>1:500</option>
            <option value={1000}>1:1,000</option>
            <option value={2500}>1:2,500</option>
            <option value={5000}>1:5,000</option>
            <option value={10000}>1:10,000</option>
          </select>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState } from 'react'
import { horizontalCurveElements, type HorizontalCurveInput, type HorizontalCurveResult } from '@/lib/computations/roadDesignEngine'
import { SimpleCurveDiagram } from '@/components/tools/SimpleCurveDiagram'

type Tab = 'elements' | 'setout'

export default function HorizontalCurveCalculator() {
  const [tab, setTab] = useState<Tab>('elements')
  const [result, setResult] = useState<HorizontalCurveResult | null>(null)
  const [resultSetout, setResultSetout] = useState<{ T: number; L: number; CT: number } | null>(null)

  const [radius, setRadius] = useState('300')
  const [deltaD, setDeltaD] = useState('45')
  const [deltaM, setDeltaM] = useState('00')
  const [deltaS, setDeltaS] = useState('00')
  const [ipChainage, setIpChainage] = useState('2500.000')

  const [interval, setInterval] = useState('20')

  function computeElements() {
    const input: HorizontalCurveInput = {
      radius: parseFloat(radius),
      deflectionAngleDeg: parseInt(deltaD) || 0,
      deflectionAngleMin: parseInt(deltaM) || 0,
      deflectionAngleSec: parseFloat(deltaS) || 0,
      ipChainage: parseFloat(ipChainage),
    }
    const r = horizontalCurveElements(input)
    setResult(r)
    setResultSetout({ T: r.tangentLength, L: r.curveLength, CT: r.ctChainage })
  }

  function ChainageDisplay(ch: number) {
    const km = Math.floor(ch / 1000)
    const m = ch % 1000
    return km > 0 ? `${km}+${m.toFixed(3)}` : `${m.toFixed(3)}`
  }

  return (
    <div className="space-y-6">
      <div className="flex gap-2 border-b border-[var(--border-color)] pb-3">
        <button onClick={() => setTab('elements')} className={`px-4 py-2 rounded-t text-sm font-medium ${tab === 'elements' ? 'bg-[var(--accent)] text-black' : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]'}`}>Curve Elements</button>
        <button onClick={() => setTab('setout')} className={`px-4 py-2 rounded-t text-sm font-medium ${tab === 'setout' ? 'bg-[var(--accent)] text-black' : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]'}`}>Set-Out Table</button>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="radius-r-m">Radius R (m)</label>
          <input id="radius-r-m" aria-label="Radius R (m)" value={radius} onChange={e => setRadius(e.target.value)} type="number" min="1"
            className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
        </div>
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="degrees">Δ Degrees</label>
          <input id="degrees" aria-label="Δ Degrees" value={deltaD} onChange={e => setDeltaD(e.target.value)} type="number" min="1" max="180"
            className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
        </div>
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="minutes">Δ Minutes</label>
          <input id="minutes" aria-label="Δ Minutes" value={deltaM} onChange={e => setDeltaM(e.target.value)} type="number" min="0" max="59"
            className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
