            className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
        </div>
      </div>

      <div className="flex items-center gap-3">
        <button onClick={computeElements} className="px-5 py-2 bg-[var(--accent)] text-black rounded text-sm font-medium hover:opacity-90">
          Compute
        </button>
        {result && (
          <span className={`text-xs font-mono px-2 py-1 rounded ${result.arithmeticCheck.passed ? 'bg-green-900/30 text-green-400' : 'bg-red-900/30 text-red-400'}`}>
            {result.arithmeticCheck.passed ? ' Arithmetic Check PASS' : `[x] Arithmetic Check FAIL (diff=${result.arithmeticCheck.diff.toFixed(4)}m)`}
          </span>
        )}
      </div>

      {tab === 'elements' && result && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          {[
            ['Tangent Length (T)', `${result.tangentLength.toFixed(4)} m`, 'RDM 1.3 §5.2'],
            ['Curve Length (L)', `${result.curveLength.toFixed(4)} m`, 'RDM 1.3 §5.2'],
            ['Long Chord (C)', `${result.longChord.toFixed(4)} m`, 'RDM 1.3 §5.2'],
            ['Mid Ordinate (M)', `${result.midOrdinate.toFixed(4)} m`, 'RDM 1.3 §5.2'],
            ['External Dist (E)', `${result.externalDistance.toFixed(4)} m`, 'RDM 1.3 §5.2'],
            ['Degree of Curve (D)', `${result.degreeOfCurve.toFixed(4)}°`, 'RDM 1.3 §5.2'],
            ['TC Chainage', ChainageDisplay(result.tcChainage), 'RDM 1.3 §5.2'],
            ['CC Chainage', ChainageDisplay(result.ccChainage), 'RDM 1.3 §5.2'],
            ['CT Chainage', ChainageDisplay(result.ctChainage), 'RDM 1.3 §5.2'],
            ['Δ (radians)', result.delta.toFixed(8), 'Ghilani Ch.24 Eq.24.1'],
          ].map(([label, value, source]) => (
            <div key={label} className="bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded p-3">
              <p className="text-xs text-[var(--text-muted)] mb-1">{label}</p>
              <p className="text-lg font-mono text-[var(--text-primary)]">{value}</p>
              <p className="text-[10px] text-[var(--text-muted)] mt-1">{source}</p>
            </div>
          ))}
        </div>
      )}

      {tab === 'elements' && result && (
        <SimpleCurveDiagram
          radius={parseFloat(radius)}
          deflectionDeg={result.delta * 180 / Math.PI}
          tangentLength={result.tangentLength}
          arcLength={result.curveLength}
          longChord={result.longChord}
          externalDistance={result.externalDistance}
          midOrdinate={result.midOrdinate}
          pcChainage={result.tcChainage}
          piChainage={parseFloat(ipChainage)}
          ptChainage={result.ctChainage}
        />
      )}

      {tab === 'elements' && result && result.steps && (
        <details className="text-xs">
          <summary className="cursor-pointer text-[var(--text-muted)] hover:text-[var(--text-primary)] font-medium mb-2">Show Computation Steps</summary>
          <div className="space-y-1">
            {result.steps.map((step, i) => (
              <div key={step.value} className="grid grid-cols-[1fr_auto_1fr_auto] gap-x-2 font-mono py-1 border-b border-[var(--border-color)]/20">
                <span className="text-[var(--text-secondary)]">{step.description}</span>
                <span className="text-[var(--text-muted)]">=</span>
                <span className="text-[var(--text-primary)]">{step.value}</span>
                <span className="text-[var(--text-muted)] text-right">{step.formula}</span>
              </div>
            ))}
          </div>
        </details>
      )}

      {tab === 'setout' && resultSetout && (
        <SetOutDisplay radius={parseFloat(radius)} T={resultSetout.T} tcChainage={parseFloat(radius) * Math.tan((parseFloat(deltaD) + parseFloat(deltaM)/60 + parseFloat(deltaS)/3600) * Math.PI / 360)} interval={parseInt(interval) || 20} deltaD={parseInt(deltaD)||0} deltaM={parseInt(deltaM)||0} deltaS={parseFloat(deltaS)||0} />
      )}

      {tab === 'setout' && !resultSetout && (
        <div className="text-sm text-[var(--text-muted)] text-center py-8">
          Compute curve elements first, then switch to Set-Out tab
        </div>
      )}

      {tab === 'setout' && (
        <div className="mt-2">
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="peg-interval-m">Peg Interval (m)</label>
          <input  id="peg-interval-m" aria-label="Peg Interval (m)" value={interval} onChange={e => setInterval(e.target.value)} type="number" min="1" max="100"
            className="w-24 px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
        </div>
      )}
    </div>
  )
}

function SetOutDisplay({ radius, T, tcChainage, interval, deltaD, deltaM, deltaS }: { radius: number; T: number; tcChainage: number; interval: number; deltaD: number; deltaM: number; deltaS: number }) {
  const delta = (deltaD + deltaM / 60 + deltaS / 3600) * Math.PI / 180
  const ctChainage = tcChainage + (Math.PI * radius * delta / 180)
  const rows: Array<{ peg: string; chainage: number; chord: number; defAngle: string; totalDef: string; remarks: string }> = []

  rows.push({ peg: 'TC', chainage: tcChainage, chord: 0, defAngle: '0°00\'00"', totalDef: '0°00\'00"', remarks: 'Tangent/Curve' })

  let ch = Math.ceil(tcChainage / interval) * interval
  while (ch < ctChainage) {
    const arc = ch - tcChainage
    const defRad = arc / radius
    const defDeg = (defRad * 180 / Math.PI) / 2
    const d = Math.floor(defDeg)
    const mf = (defDeg - d) * 60
    const m = Math.floor(mf)
    const s = (mf - m) * 60
    const chord = 2 * radius * Math.sin(arc / (2 * radius))
    rows.push({ peg: String(rows.length), chainage: ch, chord, defAngle: `${d}°${String(m).padStart(2,'0')}'${s.toFixed(1).padStart(4,'0')}"`, totalDef: `${d}°${String(m).padStart(2,'0')}'${s.toFixed(1).padStart(4,'0')}"`, remarks: '' })
    ch += interval
  }

  const finalArc = ctChainage - tcChainage
  const finalDefDeg = ((finalArc / radius) * 180 / Math.PI) / 2
  const fd = Math.floor(finalDefDeg)
  const fmf = (finalDefDeg - fd) * 60
  const fm = Math.floor(fmf)
  const fs = (fmf - fm) * 60
  const finalChord = 2 * radius * Math.sin(finalArc / (2 * radius))
  rows.push({ peg: 'CT', chainage: ctChainage, chord: finalChord, defAngle: `${fd}°${String(fm).padStart(2,'0')}'${fs.toFixed(1).padStart(4,'0')}"`, totalDef: `${fd}°${String(fm).padStart(2,'0')}'${fs.toFixed(1).padStart(4,'0')}"`, remarks: 'Curve/Tangent' })

  function fmtCh(ch: number) {
    const km = Math.floor(ch / 1000)
    const m = ch % 1000
    return km > 0 ? `${km}+${m.toFixed(3)}` : `${m.toFixed(3)}`
  }

  return (
    <div className="overflow-x-auto">
      <table className="w-full text-xs font-mono border-collapse">
        <thead>
          <tr className="bg-[var(--bg-tertiary)]">
            {['Peg', 'Chainage', 'Chord (m)', 'Deflection Angle', 'Cumulative Def', 'Remarks'].map((h) => (
              <th key={h} className="px-3 py-2 text-left text-[var(--text-muted)] font-medium border border-[var(--border-color)]">{h}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, i) => (
            <tr key={`${row}-${i}`} className="border border-[var(--border-color)]/50 hover:bg-[var(--bg-tertiary)]/50">
              <td className="px-3 py-1.5 text-[var(--text-primary)]">{row.peg}</td>
              <td className="px-3 py-1.5 text-[var(--text-primary)]">{fmtCh(row.chainage)}</td>
              <td className="px-3 py-1.5 text-[var(--text-primary)] text-right">{row.chord > 0 ? row.chord.toFixed(3) : '—'}</td>
              <td className="px-3 py-1.5 text-[var(--text-primary)]">{row.defAngle}</td>
              <td className="px-3 py-1.5 text-[var(--text-primary)]">{row.totalDef}</td>
              <td className="px-3 py-1.5 text-[var(--text-muted)]">{row.remarks}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

'use client';

import { useState, useRef, useCallback } from 'react'
import {
  Upload, X, FileSpreadsheet, AlertCircle, CheckCircle2,
  Loader2, Info
} from 'lucide-react'

interface ImportResult {
  total_rows: number
  created: number
  skipped: number
  errors: string[]
}

export default function CsvImportPanel({ projectId, blockId, blockName, onImportComplete }: {
  projectId: number | string
  blockId: number | string
  blockName: string
  onImportComplete?: () => void
}) {
  const fileRef = useRef<HTMLInputElement>(null)
  const [dragging, setDragging] = useState(false)
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState<ImportResult | null>(null)
  const [error, setError] = useState('')
  const [fileName, setFileName] = useState('')

  const doImport = async (file: File) => {
    setLoading(true)
    setError('')
    setResult(null)
    setFileName(file.name)

    const formData = new FormData()
    formData.append('project_id', String(projectId))
    formData.append('block_id', String(blockId))
    formData.append('file', file)

    try {
      const res = await fetch('/api/scheme/import', {
        method: 'POST',
        body: formData,
      })
      const json = await res.json() as { error?: string; data?: ImportResult | null }
      if (!res.ok) throw new Error(json.error || 'Import failed')

      setResult(json.data ?? null)
      if ((json.data?.created ?? 0) > 0 && onImportComplete) {
        onImportComplete()
      }
    } catch (err: unknown) {
      setError((err as Error).message)
    } finally {
      setLoading(false)
    }
  }

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) doImport(file)
  }

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setDragging(false)
    const file = e.dataTransfer.files?.[0]
    if (file) doImport(file)
  }, [])

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    setDragging(true)
  }

  const handleDragLeave = () => setDragging(false)

  // Sample CSV data for download
  const downloadSample = () => {
    const csv = `parcel_number,lr_number_proposed,area_ha,notes
1,MN/III/1001,0.0625,Northwest corner
2,MN/III/1002,0.1250,Central portion
3,MN/III/1003,0.0875,East boundary
4,MN/III/1004,0.1500,South section
5,MN/III/1005,0.1000,Road reserve
6,MN/III/1006,0.0750,Adjoining river
7,MN/III/1007,0.0500,Corner plot
8,MN/III/1008,0.2000,Large subdivision
9,MN/III/1009,0.1100,Commercial zone
10,MN/III/1010,0.0800,Public utility`
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `sample_parcels_${blockName}.csv`
    a.click()
    URL.revokeObjectURL(url)
  }

  return (
    <div className="border border-[var(--border-color)] rounded-xl overflow-hidden bg-[var(--bg-card)]">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--border-color)]">
        <span className="text-sm font-semibold text-[var(--text-primary)] flex items-center gap-2">
          <FileSpreadsheet className="w-4 h-4 text-blue-400" />
          Bulk Import Parcels
        </span>
        <button
          onClick={downloadSample}
          className="text-xs text-[var(--text-muted)] hover:text-[var(--accent)] transition-colors flex items-center gap-1"
        >
          <Info className="w-3 h-3" />
          Download Sample CSV
        </button>
      </div>

      <div className="px-4 py-3 space-y-3">
        {/* Upload Zone */}
        <div
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onClick={() => fileRef.current?.click()}
          className={`border-2 border-dashed rounded-xl p-6 text-center cursor-pointer transition-all ${
            dragging
              ? 'border-[var(--accent)] bg-[var(--accent)]/5'
              : 'border-[var(--border-color)] hover:border-[var(--accent)]/50 hover:bg-[var(--bg-secondary)]'
          }`}
        >
          <input
            ref={fileRef}
            type="file"
            accept=".csv,text/csv"
            onChange={handleFileChange}
            className="hidden"
          />
          {loading ? (
            <div className="flex flex-col items-center gap-2">
              <Loader2 className="w-8 h-8 animate-spin text-[var(--accent)]" />
              <p className="text-sm text-[var(--text-secondary)]">Importing {fileName}...</p>
            </div>
          ) : (
            <div className="flex flex-col items-center gap-2">
              <Upload className="w-8 h-8 text-[var(--text-muted)]" />
              <p className="text-sm text-[var(--text-secondary)]">
                Drop CSV here or <span className="text-[var(--accent)] underline">browse</span>
              </p>
              <p className="text-[10px] text-[var(--text-muted)]">
                Required columns: parcel_number | Optional: lr_number_proposed, area_ha, notes
              </p>
            </div>
          )}
        </div>

        {/* Error */}
        {error && (
          <div className="p-2.5 bg-red-900/20 border border-red-500/30 rounded-lg text-xs text-red-400 flex items-start gap-2">
            <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
            <span>{error}</span>
          </div>
        )}

        {/* Result */}
        {result && (
          <div className="space-y-2">
            <div className="p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <CheckCircle2 className="w-4 h-4 text-emerald-400" />
                <span className="text-sm font-medium text-emerald-400">
                  Import complete
                </span>
              </div>
              <div className="grid grid-cols-3 gap-3 text-xs">
                <div>
                  <span className="text-emerald-300 font-bold">{result.created}</span>
                  <span className="text-[var(--text-muted)]"> created</span>
                </div>
                <div>
                  <span className="text-yellow-300 font-bold">{result.skipped}</span>
                  <span className="text-[var(--text-muted)]"> skipped/updated</span>
                </div>
                <div>
                  <span className="text-[var(--text-secondary)]">{result.total_rows}</span>
                  <span className="text-[var(--text-muted)]"> total rows</span>
                </div>
              </div>
            </div>

            {result.errors.length > 0 && (
              <div className="p-2.5 bg-yellow-500/10 border border-yellow-500/20 rounded-lg">
                <p className="text-[10px] font-medium text-yellow-400 mb-1">
                  {result.errors.length} warning(s):
                </p>
                <div className="max-h-24 overflow-y-auto space-y-0.5">
                  {result.errors.map((e, i) => (
                    <p key={`${e}-${i}`} className="text-[10px] text-yellow-300/80">{e}</p>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

/**
 * CommandPalette — Global search and navigation (Cmd+K / Ctrl+K)
 *
 * Features:
 * - Press Cmd+K (Mac) or Ctrl+K (Windows/Linux) to open
 * - Search across: projects, parcels, beacons, tools, pages, documents
 * - Keyboard navigation (arrow keys, enter, escape)
 * - Recent items shown when query is empty
 * - Quick navigation shortcuts
 *
 * Integrates with:
 * - /api/search (existing backend search)
 * - Static page navigation (tools, docs, settings)
 */

import { useState, useEffect, useCallback, useRef, useMemo } from 'react'
import { useRouter } from 'next/navigation'
import {
  Search, Command, ArrowRight, ArrowLeft, CornerDownLeft,
  FolderKanban, Wrench, Map, FileText, Settings, LayoutDashboard,
  Calculator, Ruler, Compass, Users, CreditCard, BarChart3,
  BookOpen, HelpCircle, Loader2,
} from 'lucide-react'
import { useDebounceValue } from '@/lib/performance'

interface SearchResult {
  id: string
  type: string
  title: string
  subtitle?: string
  href?: string
  meta?: Record<string, unknown>
}

interface StaticNavItem {
  title: string
  subtitle: string
  href: string
  icon: typeof LayoutDashboard
  category: string
  keywords: string[]
}

// Static navigation items (always available)
const STATIC_NAV: StaticNavItem[] = [
  { title: 'Dashboard', subtitle: 'Your project overview', href: '/dashboard', icon: LayoutDashboard, category: 'Pages', keywords: ['home', 'main', 'overview'] },
  { title: 'Map', subtitle: 'Global survey map', href: '/map', icon: Map, category: 'Pages', keywords: ['openlayers', 'gis'] },
  { title: 'Field Book', subtitle: 'Digital field notes', href: '/fieldbook', icon: FileText, category: 'Pages', keywords: ['notes', 'observations', 'leveling', 'traverse'] },
  { title: 'Documents', subtitle: 'Generated documents', href: '/documents', icon: FileText, category: 'Pages', keywords: ['pdf', 'deed', 'plan'] },
  { title: 'Analytics', subtitle: 'Usage statistics', href: '/analytics', icon: BarChart3, category: 'Pages', keywords: ['stats', 'reports'] },
  { title: 'Community', subtitle: 'Surveyor network', href: '/community', icon: Users, category: 'Pages', keywords: ['network', 'peer', 'review'] },
  { title: 'Settings', subtitle: 'Account preferences', href: '/settings', icon: Settings, category: 'Pages', keywords: ['profile', 'account', 'preferences'] },
  { title: 'Pricing', subtitle: 'Subscription plans', href: '/pricing', icon: CreditCard, category: 'Pages', keywords: ['upgrade', 'plan', 'subscription'] },

  // Tools
  { title: 'COGO Calculator', subtitle: 'Coordinate geometry', href: '/tools/cogo', icon: Calculator, category: 'Tools', keywords: ['cogo', 'coordinate', 'geometry', 'intersection'] },
  { title: 'Traverse', subtitle: 'Traverse computation', href: '/tools/traverse', icon: Compass, category: 'Tools', keywords: ['bowditch', 'adjustment', 'closure'] },
  { title: 'Leveling', subtitle: 'Rise & fall computation', href: '/tools/leveling', icon: Ruler, category: 'Tools', keywords: ['level', 'rl', 'benchmark'] },
  { title: 'Distance Calculator', subtitle: 'Point-to-point distance', href: '/tools/distance', icon: Ruler, category: 'Tools', keywords: ['length', 'measure'] },
  { title: 'Area Calculator', subtitle: 'Polygon area', href: '/tools/area', icon: Calculator, category: 'Tools', keywords: ['acre', 'hectare', 'parcel'] },
  { title: 'Coordinate Transform', subtitle: 'Datum conversion', href: '/tools/coordinates', icon: Compass, category: 'Tools', keywords: ['utm', 'wgs84', 'arc 1960', 'cassini'] },
  { title: 'Curve Calculator', subtitle: 'Horizontal/vertical curves', href: '/tools/curves', icon: Compass, category: 'Tools', keywords: ['radius', 'arc', 'transition'] },
  { title: 'Cassini-UTM Conversion', subtitle: 'Legacy grid transform', href: '/tools/cassini-utm', icon: Compass, category: 'Tools', keywords: ['cassini', 'soldner', 'colonial'] },

  // Docs
  { title: 'Documentation', subtitle: 'User manuals & guides', href: '/docs', icon: BookOpen, category: 'Help', keywords: ['manual', 'guide', 'help', 'docs'] },
  { title: 'Quick Start Guide', subtitle: 'Get started in 5 minutes', href: '/docs/quick-start', icon: BookOpen, category: 'Help', keywords: ['begin', 'tutorial', 'setup'] },
  { title: 'API Documentation', subtitle: 'Developer reference', href: '/api-docs', icon: BookOpen, category: 'Help', keywords: ['api', 'developer', 'rest'] },
]

export function CommandPalette() {
  const router = useRouter()
  const [open, setOpen] = useState(false)
  const [query, setQuery] = useState('')
  const [selectedIndex, setSelectedIndex] = useState(0)
  const [searching, setSearching] = useState(false)
  const [apiResults, setApiResults] = useState<SearchResult[]>([])
  const inputRef = useRef<HTMLInputElement>(null)
  const listRef = useRef<HTMLDivElement>(null)

  // Open/close with Cmd+K / Ctrl+K
  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault()
        setOpen(prev => !prev)
      }
      if (e.key === 'Escape' && open) {
        setOpen(false)
      }
    }
    document.addEventListener('keydown', handleKeyDown)
    return () => document.removeEventListener('keydown', handleKeyDown)
  }, [open])

  // Focus input when opened
  useEffect(() => {
    if (open) {
      setTimeout(() => inputRef.current?.focus(), 50)
      setQuery('')
      setApiResults([])
      setSelectedIndex(0)
    }
  }, [open])

  // Debounced query using performance utility
  const debouncedQuery = useDebounceValue(query, 200)

  // Search API when debounced query changes
  useEffect(() => {
    if (!debouncedQuery.trim() || debouncedQuery.length < 2) {
      setApiResults([])
      return
    }

    setSearching(true)
    let cancelled = false

    async function doSearch() {
      try {
        const res = await fetch(`/api/search?q=${encodeURIComponent(debouncedQuery)}&limit=10`)
        if (cancelled || !res.ok) return
        const data = (await res.json()) as { data?: { groups?: Array<{ type: string; hits?: Array<{ id: string; title: string; subtitle?: string; meta?: Record<string, unknown> }> }> } }
        if (cancelled) return
        const results: SearchResult[] = []
        if (data.data?.groups) {
          for (const group of data.data.groups) {
            for (const hit of group.hits || []) {
              results.push({
                id: hit.id,
                type: group.type,
                title: hit.title,
                subtitle: hit.subtitle,
                href: getHrefForType(group.type, hit.id, hit.meta),
              })
            }
          }
        }
        setApiResults(results)
      } catch {
        // Silent fail
      } finally {
        if (!cancelled) setSearching(false)
      }
    }

    doSearch()

    return () => { cancelled = true }
  }, [debouncedQuery])

  // Filter static nav by query
  const filteredNav = useMemo(() => {
    if (!query.trim()) return STATIC_NAV.slice(0, 8)
    const q = query.toLowerCase()
    return STATIC_NAV.filter(item =>
      item.title.toLowerCase().includes(q) ||
      item.subtitle.toLowerCase().includes(q) ||
      item.keywords.some(k => k.includes(q))
    )
  }, [query])

  // Combine results
  const allResults = useMemo(() => {
    const combined: (StaticNavItem | SearchResult)[] = []
    if (apiResults.length > 0) combined.push(...apiResults)
    combined.push(...filteredNav)
    return combined.slice(0, 20)
  }, [apiResults, filteredNav])

  // Reset selected index when results change
  useEffect(() => {
    setSelectedIndex(0)
  }, [allResults.length])

  // Keyboard navigation
  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault()
      setSelectedIndex(prev => Math.min(prev + 1, allResults.length - 1))
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      setSelectedIndex(prev => Math.max(prev - 1, 0))
    } else if (e.key === 'Enter') {
      e.preventDefault()
      const item = allResults[selectedIndex]
      if (item) handleSelect(item)
    }
  }, [allResults, selectedIndex])

  const handleSelect = useCallback((item: StaticNavItem | SearchResult) => {
    const href = 'href' in item ? item.href : undefined
    if (href) {
      router.push(href)
      setOpen(false)
    }
  }, [router])

  // Scroll selected item into view
  useEffect(() => {
    const el = listRef.current?.children[selectedIndex] as HTMLElement
    if (el) el.scrollIntoView({ block: 'nearest' })
  }, [selectedIndex])

  if (!open) return null

  return (
    <>
      {/* Backdrop */}
      <div
        className="fixed inset-0 z-[9998] bg-black/60 backdrop-blur-sm"
        onClick={() => setOpen(false)}
      />

      {/* Palette */}
      <div className="fixed top-[15vh] left-1/2 -translate-x-1/2 z-[9999] w-[640px] max-w-[calc(100vw-2rem)] bg-[#0d0d14]/95 backdrop-blur-2xl border border-white/[0.1] rounded-2xl shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200">
        {/* Search input */}
        <div className="flex items-center gap-3 px-4 py-3.5 border-b border-white/[0.06]">
          {searching ? (
            <Loader2 className="w-5 h-5 text-gray-500 animate-spin shrink-0" />
          ) : (
            <Search className="w-5 h-5 text-gray-500 shrink-0" />
          )}
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={e => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            aria-label="Search projects, parcels, tools, pages..."
            className="flex-1 bg-transparent text-white text-sm placeholder-gray-600 focus:outline-none"
          />
          <kbd className="hidden sm:flex items-center gap-1 px-1.5 py-0.5 rounded bg-white/[0.06] border border-white/[0.1] text-[9px] text-gray-500 font-mono">
            ESC
          </kbd>
        </div>

        {/* Results */}
        <div ref={listRef} className="max-h-[400px] overflow-y-auto p-2">
          {allResults.length === 0 && query.length >= 2 && !searching && (
            <div className="flex flex-col items-center justify-center py-12 text-center">
              <Search className="w-8 h-8 text-gray-600 mb-2" />
              <p className="text-sm text-gray-500">No results for &quot;{query}&quot;</p>
              <p className="text-[10px] text-gray-600 mt-1">Try a different search term</p>
            </div>
          )}

          {allResults.length === 0 && query.length < 2 && (
            <div className="flex flex-col items-center justify-center py-12 text-center">
              <Command className="w-8 h-8 text-gray-600 mb-2" />
              <p className="text-sm text-gray-500">Start typing to search</p>
              <p className="text-[10px] text-gray-600 mt-1">
                Search across projects, parcels, beacons, tools, and pages
              </p>
            </div>
          )}

          {/* API results section */}
          {apiResults.length > 0 && (
            <div className="mb-2">
              <div className="px-2 py-1 text-[9px] text-gray-600 uppercase tracking-wider font-semibold">
                Database Results
              </div>
              {apiResults.map((item, idx) => (
                <ResultRow
                  key={`api-${item.id}`}
                  selected={idx === selectedIndex}
                  onClick={() => handleSelect(item)}
                  onHover={() => setSelectedIndex(idx)}
                  icon={getResultIcon(item.type)}
                  title={item.title}
                  subtitle={item.subtitle || item.type}
                  href={item.href}
                />
              ))}
            </div>
          )}

          {/* Static nav section */}
          {filteredNav.length > 0 && (
            <div>
              {apiResults.length > 0 && (
                <div className="px-2 py-1 text-[9px] text-gray-600 uppercase tracking-wider font-semibold">
                  Pages & Tools
                </div>
              )}
              {filteredNav.map((item, idx) => {
                const actualIndex = apiResults.length + idx
                return (
                  <ResultRow
                    key={`nav-${item.href}`}
                    selected={actualIndex === selectedIndex}
                    onClick={() => handleSelect(item)}
                    onHover={() => setSelectedIndex(actualIndex)}
                    icon={item.icon}
                    title={item.title}
                    subtitle={item.subtitle}
                    category={item.category}
                  />
                )
              })}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between px-4 py-2 border-t border-white/[0.06] bg-[#0d0d14]/60">
          <div className="flex items-center gap-3 text-[9px] text-gray-600">
            <span className="flex items-center gap-1">
              <kbd className="px-1 py-0.5 rounded bg-white/[0.06] border border-white/[0.1] font-mono">↑↓</kbd>
              Navigate
            </span>
            <span className="flex items-center gap-1">
              <kbd className="px-1 py-0.5 rounded bg-white/[0.06] border border-white/[0.1] font-mono">
                <CornerDownLeft className="w-2.5 h-2.5" />
              </kbd>
              Select
            </span>
          </div>
          <span className="text-[9px] text-gray-600">METARDU Search</span>
        </div>
      </div>
    </>
  )
}

// ─── Helper components ──────────────────────────────────────────────────

function ResultRow({
  selected, onClick, onHover, icon: Icon, title, subtitle, href, category,
}: {
  selected: boolean
  onClick: () => void
  onHover: () => void
  icon: typeof LayoutDashboard
  title: string
  subtitle: string
  href?: string
  category?: string
}) {
  return (
    <div
      onClick={onClick}
      onMouseEnter={onHover}
      className={`flex items-center gap-3 px-3 py-2.5 rounded-lg cursor-pointer transition-colors ${
        selected ? 'bg-[#D17B47]/10' : 'hover:bg-white/[0.03]'
      }`}
    >
      <div className={`shrink-0 w-8 h-8 rounded-lg flex items-center justify-center ${
        selected ? 'bg-[#D17B47]/15' : 'bg-white/[0.04]'
      }`}>
        <Icon className={`w-4 h-4 ${selected ? 'text-[#D17B47]' : 'text-gray-400'}`} />
      </div>
      <div className="flex-1 min-w-0">
        <div className="text-xs font-medium text-white truncate">{title}</div>
        <div className="text-[10px] text-gray-500 truncate">{subtitle}</div>
      </div>
      {category && (
        <span className="text-[9px] text-gray-600 px-1.5 py-0.5 rounded bg-white/[0.04] shrink-0">
          {category}
        </span>
      )}
      {selected && <ArrowRight className="w-3 h-3 text-[#D17B47] shrink-0" />}
    </div>
  )
}

function getResultIcon(type: string): typeof LayoutDashboard {
  switch (type) {
    case 'projects': return FolderKanban
    case 'tools': return Wrench
    case 'surveyors': return Users
    case 'documents': return FileText
    default: return Search
  }
}

function getHrefForType(type: string, id: string, meta?: Record<string, unknown>): string {
  switch (type) {
    case 'projects': return `/project/${id}`
    case 'surveyors': return `/community/directory?id=${id}`
    case 'documents': return `/documents?id=${id}`
    default: return `/search?q=${id}`
  }
}

'use client'

/**
 * AccessibilityAudit — ARIA labels and keyboard navigation for screen readers
 *
 * This component wraps children and provides:
 * - Skip links to main content
 * - ARIA live regions for dynamic updates
 * - Keyboard focus management
 * - Screen reader announcements
 *
 * Per Kenya Constitution Article 54 — persons with disabilities
 * have the right to access information.
 */

import { useEffect, useRef, useCallback, ReactNode } from 'react'

interface AccessibilityWrapperProps {
  children: ReactNode
  /** Announcements for screen readers */
  announcements?: string[]
}

export function AccessibilityWrapper({ children, announcements = [] }: AccessibilityWrapperProps) {
  const liveRegionRef = useRef<HTMLDivElement>(null)

  // Announce changes to screen readers
  useEffect(() => {
    if (liveRegionRef.current && announcements.length > 0) {
      liveRegionRef.current.textContent = announcements.join('. ')
    }
  }, [announcements])

  return (
    <>
      {children}
      {/* ARIA live region for screen reader announcements */}
      <div
        ref={liveRegionRef}
        aria-live="polite"
        aria-atomic="true"
        className="sr-only"
      />
    </>
  )
}

/**
 * Hook for managing focus trap (for modals, drawers)
 */
export function useFocusTrap(isActive: boolean) {
  const containerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!isActive || !containerRef.current) return

    const container = containerRef.current
    const focusableElements = container.querySelectorAll<HTMLElement>(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    )
    const firstElement = focusableElements[0]
    const lastElement = focusableElements[focusableElements.length - 1]

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key !== 'Tab') return

      if (e.shiftKey) {
        if (document.activeElement === firstElement) {
          e.preventDefault()
          lastElement?.focus()
        }
      } else {
        if (document.activeElement === lastElement) {
          e.preventDefault()
          firstElement?.focus()
        }
      }
    }

    container.addEventListener('keydown', handleKeyDown)
    firstElement?.focus()

    return () => container.removeEventListener('keydown', handleKeyDown)
  }, [isActive])

  return containerRef
}

/**
 * Common ARIA props for interactive elements
 */
export const ARIA_PROPS = {
  // Map controls
  mapContainer: {
