import { useState, useEffect, useCallback } from 'react';
import { X, Keyboard } from 'lucide-react';
import { useHotkeys, getRegisteredHotkeys, formatHotkey } from '@/hooks/useHotkeys';

export function HotkeyHelpOverlay() {
