'use client';

import { useState, useEffect, useCallback } from 'react'
import { AlertTriangle } from 'lucide-react'
import { 
  parseParcelNumber, 
  lookupRegistrationSection, 
  getUTMZoneForParcel,
  type ParsedParcelNumber 
} from '@/lib/compute/parcelNumber'
import { KENYA_COUNTIES, type RegistrationSection } from '@/lib/data/kenyaLocalities'

interface ParcelNumberInputProps {
  value: string
  onChange: (value: string, parsed: ParsedParcelNumber) => void
  onUTMZoneDetected?: (zone: number, hemisphere: 'N' | 'S') => void
  disabled?: boolean
  required?: boolean
}

export default function ParcelNumberInput({ 
  value, 
  onChange, 
  onUTMZoneDetected,
  disabled,
  required 
}: ParcelNumberInputProps) {
  const [parsed, setParsed] = useState<ParsedParcelNumber>(parseParcelNumber(value))
  const [inputMode, setInputMode] = useState<'free' | 'structured'>('free')
  
  // Structured input fields
  const [selectedCounty, setSelectedCounty] = useState('')
  const [selectedSection, setSelectedSection] = useState('')
  const [blockNumber, setBlockNumber] = useState('')
  const [parcelNumber, setParcelNumber] = useState('')

  const sections = selectedCounty 
    ? KENYA_COUNTIES.find((c) => c.code === selectedCounty)?.registrationSections || []
    : []

  const currentSection = sections.find((s) => s.code === selectedSection)

  // Parse free-text input
  useEffect(() => {
    const result = parseParcelNumber(value)
    setParsed(result)
    
    // Update structured fields if we have a match
    if (result.registrationSection) {
      const section = lookupRegistrationSection(result.registrationSection)
      if (section) {
        const county = KENYA_COUNTIES.find((c) => c.code === section.county)
        if (county) {
          setSelectedCounty(county.code)
          setSelectedSection(section.code)
          if (result.block) setBlockNumber(String(result.block))
          if (result.parcelNumber) setParcelNumber(String(result.parcelNumber))
        }
      }
    }
    
    // Auto-detect UTM zone
    if (result.registrationSection && result.isValid) {
      const { zone, hemisphere } = getUTMZoneForParcel(result.registrationSection)
      onUTMZoneDetected?.(zone, hemisphere)
    }
  }, [value, onUTMZoneDetected])

  const handleFreeTextChange = (text: string) => {
    const result = parseParcelNumber(text)
    setParsed(result)
    onChange(text, result)
    
    if (result.registrationSection && result.isValid) {
      const { zone, hemisphere } = getUTMZoneForParcel(result.registrationSection)
      onUTMZoneDetected?.(zone, hemisphere)
    }
  }

  const handleStructuredChange = useCallback(() => {
    if (!selectedSection || !parcelNumber) return
    
    let rawValue: string
    if (currentSection?.hasBlocks && blockNumber) {
      const sectionName = currentSection.name.split(' ')[0]
      rawValue = `${sectionName} BLOCK ${blockNumber}/${parcelNumber}`
    } else {
      rawValue = `${selectedSection}/${parcelNumber}`
    }
    
    const result = parseParcelNumber(rawValue)
    setParsed(result)
    onChange(rawValue, result)
    
    const { zone, hemisphere } = getUTMZoneForParcel(selectedSection)
    onUTMZoneDetected?.(zone, hemisphere)
  }, [selectedSection, blockNumber, parcelNumber, currentSection, onChange, onUTMZoneDetected])

  return (
    <div className="space-y-4">
      {/* Input mode toggle */}
      <div className="flex gap-2 text-sm">
        <button
          type="button"
          onClick={() => setInputMode('free')}
          className={`px-3 py-1 rounded ${inputMode === 'free' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)]'}`}
        >
          Free Text
        </button>
        <button
          type="button"
          onClick={() => setInputMode('structured')}
          className={`px-3 py-1 rounded ${inputMode === 'structured' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)]'}`}
        >
          Structured
        </button>
      </div>

      {inputMode === 'free' ? (
        <div>
          <input
            type="text"
            value={value}
            onChange={e => handleFreeTextChange(e.target.value)}
            disabled={disabled}
            required={required}
            aria-label="e.g. NAIROBI BLOCK 2/1234 or KIAMBU/456"
            className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
          />
        </div>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="county">County</label>
            <select id="county"
              value={selectedCounty}
              onChange={e => {
                setSelectedCounty(e.target.value)
                setSelectedSection('')
              }}
              disabled={disabled}
              className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-sm"
            >
              <option value="">Select County</option>
              {KENYA_COUNTIES.map((c) => (
                <option key={c.code} value={c.code}>{c.name}</option>
              ))}
            </select>
          </div>
          
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="section">Section</label>
            <select id="section"
              value={selectedSection}
              onChange={e => {
                setSelectedSection(e.target.value)
                handleStructuredChange()
              }}
              disabled={disabled || !selectedCounty}
              className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-sm"
            >
              <option value="">Select Section</option>
              {sections.map((s) => (
                <option key={s.code} value={s.code}>{s.name}</option>
              ))}
            </select>
          </div>
          
          {currentSection?.hasBlocks && (
            <div>
              <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="block">Block</label>
              <input id="block"
                type="number"
                value={blockNumber}
                onChange={e => {
                  setBlockNumber(e.target.value)
                  handleStructuredChange()
                }}
                disabled={disabled}
 placeholder="1"
                className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-sm"
              />
            </div>
          )}
          
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="parcel-no">Parcel No.</label>
            <input id="parcel-no"
              type="number"
              value={parcelNumber}
              onChange={e => {
                setParcelNumber(e.target.value)
                handleStructuredChange()
              }}
              disabled={disabled}
              required={required}
 placeholder="1234"
              className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-sm"
            />
          </div>
        </div>
      )}

      {/* Validation feedback */}
      {parsed.isValid ? (
        <div className="p-3 bg-green-50 border border-green-200 rounded-lg">
          <div className="flex items-center gap-2 text-green-700 text-sm">
            <span></span>
            <span>Valid parcel number</span>
          </div>
          {parsed.formatted && (
            <div className="mt-2 text-xs space-y-1">
              <div><span className="text-[var(--text-muted)]">Canonical:</span> {parsed.formatted}</div>
              <div><span className="text-[var(--text-muted)]">Short:</span> {parsed.shortForm}</div>
              {parsed.county && (
                <div><span className="text-[var(--text-muted)]">County:</span> {parsed.county}</div>
              )}
              {parsed.registrationSection && (
                <div><span className="text-[var(--text-muted)]">Section:</span> {parsed.registrationSection}</div>
              )}
              <div className="text-[var(--accent)] font-medium mt-1">
                UTM Zone: {getUTMZoneForParcel(parsed.registrationSection || '').zone}
                {getUTMZoneForParcel(parsed.registrationSection || '').hemisphere}
              </div>
            </div>
          )}
        </div>
      ) : (
        parsed.validationErrors.length > 0 && (
          <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
            <div className="flex items-center gap-2 text-red-700 text-sm mb-1">
              <span><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /></span>
              <span>Invalid</span>
            </div>
            <ul className="text-xs text-red-600 space-y-1">
              {parsed.validationErrors.map((err, i) => (
                <li key={`${err}-${i}`}>{err}</li>
              ))}
            </ul>
          </div>
        )
      )}
    </div>
  )
}

'use client';

import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import {
  VariableSizeList as List,
  type ListChildComponentProps,
} from 'react-window';
import { Checkbox } from '@/components/ui/checkbox';
import { Inbox } from 'lucide-react';

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export interface ColumnDef<T> {
  key: string;
  header: string;
  width: number;
  render?: (row: T) => ReactNode;
  sortable?: boolean;
  align?: 'left' | 'center' | 'right';
}

export interface VirtualizedTableProps<T> {
  rows: T[];
  columns: ColumnDef<T>[];
  /** Fixed row height in px (default 40) */
  rowHeight?: number;
  /** Height of the entire table viewport in px (default 500) */
  tableHeight?: number;
  onRowClick?: (row: T, index: number) => void;
  /** Set of selected row *indices* */
  selectedRows?: Set<number>;
  onSelectionChange?: (selected: Set<number>) => void;
  /** Show the checkbox column (default false) */
  selectable?: boolean;
  /** Stick header row to the top (default true) */
  headerSticky?: boolean;
  /** Unique key per row — defaults to index */
  rowKey?: (row: T, index: number) => string;
  /** Custom empty-state message */
  emptyMessage?: string;
  className?: string;
  /** Accessible label for the table */
  'aria-label'?: string;
}

/* ------------------------------------------------------------------ */
/*  Fallback (non-virtualized) renderer                                */
/* ------------------------------------------------------------------ */

function FallbackTable<T>({
  rows,
  columns,
  rowHeight = 40,
  onRowClick,
  selectedRows,
  onSelectionChange,
  selectable,
  emptyMessage = 'No data',
  rowKey,
}: VirtualizedTableProps<T>) {
  const allSelected = rows.length > 0 && selectedRows && selectedRows.size === rows.length;
  const someSelected = selectedRows && selectedRows.size > 0 && !allSelected;

  const toggleAll = () => {
    if (!onSelectionChange) return;
    if (allSelected) {
      onSelectionChange(new Set());
    } else {
      onSelectionChange(new Set(rows.map((_, i) => i)));
    }
  };

  const toggleRow = (idx: number) => {
    if (!onSelectionChange || !selectedRows) return;
    const next = new Set(selectedRows);
    if (next.has(idx)) next.delete(idx);
    else next.add(idx);
    onSelectionChange(next);
  };

  const totalWidth = columns.reduce((s, c) => s + c.width, 0) + (selectable ? 48 : 0);

  return (
    <div className="overflow-x-auto rounded-lg border border-[var(--border-color)]" style={{ maxHeight: 600 }}>
      <table className="w-full text-sm" style={{ minWidth: totalWidth }}>
        <thead className="sticky top-0 z-10">
          <tr
            className="border-b border-[var(--border-color)] text-left text-xs uppercase tracking-wider text-[var(--text-muted)]"
            style={{ background: 'var(--bg-secondary)' }}
          >
            {selectable && (
              <th className="px-3 py-2 w-12" style={{ width: 48 }}>
                <Checkbox
                  checked={allSelected ? true : someSelected ? 'indeterminate' : false}
                  onCheckedChange={toggleAll}
                  aria-label="Select all rows"
                />
              </th>
            )}
            {columns.map((col) => (
              <th
                key={col.key}
                className="px-3 py-2 font-semibold whitespace-nowrap"
                style={{
                  width: col.width,
                  minWidth: col.width,
                  textAlign: col.align ?? 'left',
                }}
              >
                {col.header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 && (
            <tr>
              <td
                colSpan={columns.length + (selectable ? 1 : 0)}
                className="py-16 text-center text-[var(--text-muted)]"
              >
                <Inbox className="mx-auto mb-2 h-8 w-8 opacity-40" />
                {emptyMessage}
              </td>
            </tr>
          )}
          {rows.map((row, idx) => {
            const isSelected = selectedRows?.has(idx) ?? false;
            return (
              <tr
                key={rowKey ? rowKey(row, idx) : idx}
                className={`
                  border-b border-[var(--border-color)]/30 transition-colors
                  ${idx % 2 === 0 ? 'bg-[var(--bg-primary)]' : 'bg-[var(--bg-secondary)]'}
                  ${isSelected ? 'bg-[var(--accent-subtle)]' : ''}
                  ${onRowClick ? 'cursor-pointer hover:bg-[var(--accent-subtle)]' : ''}
                `}
                style={{ height: rowHeight }}
                onClick={() => onRowClick?.(row, idx)}
                onKeyDown={(e) => {
                  if (onRowClick && (e.key === 'Enter' || e.key === ' ')) {
                    e.preventDefault()
                    onRowClick(row, idx)
                  }
                }}
                tabIndex={onRowClick ? 0 : undefined}
              >
                {selectable && (
                  <td className="px-3 py-2 w-12" onClick={(e) => e.stopPropagation()}>
                    <Checkbox
                      checked={isSelected}
                      onCheckedChange={() => toggleRow(idx)}
                      aria-label={`Select row ${idx + 1}`}
                    />
                  </td>
                )}
                {columns.map((col) => (
                  <td
                    key={col.key}
                    className="px-3 py-2 whitespace-nowrap"
                    style={{ textAlign: col.align ?? 'left' }}
                  >
                    {col.render ? col.render(row) : String((row as Record<string, unknown>)[col.key] ?? '—')}
                  </td>
                ))}
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Virtualized Table                                                  */
/* ------------------------------------------------------------------ */

function VirtualizedTableInner<T>(props: VirtualizedTableProps<T>) {
  const {
    rows,
    columns,
    rowHeight = 40,
    tableHeight = 500,
    onRowClick,
    selectedRows = new Set(),
    onSelectionChange,
    selectable = false,
    headerSticky = true,
    rowKey,
    emptyMessage = 'No data to display',
    className,
    'aria-label': ariaLabel,
  } = props;

  const listRef = useRef<List>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [containerWidth, setContainerWidth] = useState(0);

  /* ---- Responsive width ---- */
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const obs = new ResizeObserver((entries) => {
      setContainerWidth(entries[0]?.contentRect.width ?? 0);
    });
    obs.observe(el);
    return () => obs.disconnect();
  }, []);

  /* ---- Derived ---- */
  const totalWidth = useMemo(
    () => columns.reduce((s, c) => s + c.width, 0) + (selectable ? 48 : 0),
    [columns, selectable],
  );
  const needsHorizontalScroll = totalWidth > containerWidth && containerWidth > 0;
  const listWidth = needsHorizontalScroll ? totalWidth : containerWidth;

  const allSelected = rows.length > 0 && selectedRows.size === rows.length;
  const someSelected = selectedRows.size > 0 && !allSelected;

  /* ---- Handlers ---- */
  const toggleAll = useCallback(() => {
    if (!onSelectionChange) return;
    if (allSelected) {
      onSelectionChange(new Set());
    } else {
      onSelectionChange(new Set(rows.map((_, i) => i)));
    }
  }, [allSelected, onSelectionChange, rows]);

  const toggleRow = useCallback(
    (idx: number) => {
      if (!onSelectionChange) return;
      const next = new Set(selectedRows);
      if (next.has(idx)) next.delete(idx);
      else next.add(idx);
      onSelectionChange(next);
    },
    [onSelectionChange, selectedRows],
  );

  /* ---- Row height estimator (constant for now, but VariableSizeList ready) ---- */
  const getRowSize = useCallback(() => rowHeight, [rowHeight]);
  const headerHeight = 42;

  /* ---- Row renderer ---- */
  const Row = useCallback(
    ({ index, style }: ListChildComponentProps) => {
      const row = rows[index];
      const isSelected = selectedRows.has(index);
      const bgClass =
        isSelected
          ? 'bg-[var(--accent-subtle)]'
          : index % 2 === 0
            ? 'bg-[var(--bg-primary)]'
            : 'bg-[var(--bg-secondary)]';

      return (
        <div
          style={{
            ...style,
            display: 'flex',
            alignItems: 'center',
            cursor: onRowClick ? 'pointer' : undefined,
          }}
          className={`
            border-b border-[var(--border-color)]/20 transition-colors
            ${bgClass}
            ${onRowClick ? 'hover:bg-[var(--accent-subtle)]' : ''}
          `}
          onClick={() => onRowClick?.(row, index)}
          onKeyDown={(e) => {
            if (onRowClick && (e.key === 'Enter' || e.key === ' ')) {
              e.preventDefault()
              onRowClick(row, index)
            }
          }}
          tabIndex={onRowClick ? 0 : undefined}
          role="row"
        >
          {selectable && (
            <div
              className="flex items-center justify-center shrink-0"
              style={{ width: 48 }}
              onClick={(e) => e.stopPropagation()}
            >
              <Checkbox
                checked={isSelected}
                onCheckedChange={() => toggleRow(index)}
                aria-label={`Select row ${index + 1}`}
              />
            </div>
          )}
          {columns.map((col) => (
            <div
              key={col.key}
              className="px-3 py-2 text-sm whitespace-nowrap overflow-hidden text-ellipsis"
              style={{
                width: col.width,
                minWidth: col.width,
                textAlign: col.align ?? 'left',
              }}
              role="cell"
            >
              {col.render ? col.render(row) : String((row as Record<string, unknown>)[col.key] ?? '—')}
            </div>
          ))}
        </div>
      );
    },
    [rows, columns, selectable, selectedRows, onRowClick, toggleRow],
  );

  /* ---- Scroll-to-row ---- */
  const scrollToRow = useCallback(
    (index: number) => {
      listRef.current?.scrollToItem(index, 'center');
    },
    [],
  );

  // Expose scrollToRow via ref (imperative handle)
  React.useImperativeHandle(
    (props as VirtualizedTableProps<T> & { ref?: React.Ref<{ scrollToRow: (i: number) => void }> }).ref,
    () => ({ scrollToRow }),
    [scrollToRow],
  );

  /* ---- Empty state ---- */
  if (rows.length === 0) {
    return (
      <div
        ref={containerRef}
        className={`rounded-lg border border-[var(--border-color)] flex flex-col items-center justify-center text-[var(--text-muted)] ${className ?? ''}`}
        style={{ height: tableHeight, background: 'var(--bg-primary)' }}
      >
        <Inbox className="h-10 w-10 mb-2 opacity-40" />
        <p className="text-sm">{emptyMessage}</p>
      </div>
    );
  }

  /* ---- Render ---- */
  return (
    <div
      ref={containerRef}
      className={`rounded-lg border border-[var(--border-color)] overflow-hidden ${className ?? ''}`}
      style={{ background: 'var(--bg-primary)' }}
      role="table"
      aria-label={ariaLabel}
      aria-rowcount={rows.length + 1}
      aria-colcount={columns.length + (selectable ? 1 : 0)}
    >
      {/* Sticky header */}
      {headerSticky && (
        <div
          className="flex items-center border-b border-[var(--border-color)] text-xs uppercase tracking-wider text-[var(--text-muted)] shrink-0"
          style={{
            height: headerHeight,
            background: 'var(--bg-secondary)',
            minWidth: needsHorizontalScroll ? totalWidth : undefined,
          }}
          role="row"
        >
          {selectable && (
            <div className="flex items-center justify-center shrink-0" style={{ width: 48 }} role="columnheader">
              <Checkbox
                checked={allSelected ? true : someSelected ? 'indeterminate' : false}
                onCheckedChange={toggleAll}
                aria-label="Select all rows"
              />
            </div>
          )}
          {columns.map((col) => (
            <div
              key={col.key}
              className="px-3 py-2 font-semibold whitespace-nowrap"
              style={{
                width: col.width,
                minWidth: col.width,
                textAlign: col.align ?? 'left',
              }}
              role="columnheader"
              aria-sort={col.sortable ? 'none' : undefined}
            >
              {col.header}
            </div>
          ))}
        </div>
      )}

      {/* Virtualized body — wrap in scroll container for horizontal scroll */}
      <div className={needsHorizontalScroll ? 'overflow-x-auto' : ''}>
        <List
          ref={listRef}
          height={tableHeight - headerHeight}
          itemCount={rows.length}
          itemSize={getRowSize}
          width={listWidth}
          overscanCount={8}
        >
          {Row}
        </List>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Export with dynamic import guard                                    */
/* ------------------------------------------------------------------ */

/**
 * VirtualizedTable wraps react-window's VariableSizeList for efficient
 * rendering of large datasets (500+ rows).
 *
 * If react-window fails to load, it falls back to a standard HTML table.
 */
export function VirtualizedTable<T>(props: VirtualizedTableProps<T>) {
  const [useVirtualized, setUseVirtualized] = useState(true);

  useEffect(() => {
    // Verify react-window is actually available at runtime
    try {
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const rw = require('react-window') as { VariableSizeList?: unknown };
      if (!rw.VariableSizeList) setUseVirtualized(false);
    } catch {
      setUseVirtualized(false);
    }
  }, []);

  if (!useVirtualized) {
    return <FallbackTable {...props} />;
  }

  return <VirtualizedTableInner {...props} />;
}

export default VirtualizedTable;

'use client';

import type { Solution } from '@/lib/solution/schema'

export default function SolutionRenderer({ solution }: { solution: Solution }) {
  return (
    <div className="card">
      <div className="card-header flex items-center justify-between gap-4">
        <span className="label">Solution</span>
        {solution.title ? <span className="text-xs text-[var(--text-muted)]">{solution.title}</span> : null}
      </div>
      <div className="card-body space-y-4">
        <Section title="Given">
          <div className="grid md:grid-cols-2 gap-2">
            {solution.given.map((g, i) => (
              <div key={g.label} className="flex items-baseline justify-between gap-3 p-2 rounded bg-gray-950/30 border border-[var(--border-color)]">
                <div className="text-xs text-[var(--text-muted)]">{g.label}</div>
                <div className="font-mono text-sm text-[var(--text-primary)] text-right">{g.value}</div>
              </div>
            ))}
          </div>
        </Section>

        <Section title="To Find">
          <ul className="list-disc pl-5 text-sm text-[var(--text-primary)] space-y-1">
            {solution.toFind.map((x, i) => (
              <li key={`${x}-${i}`}>{x}</li>
            ))}
          </ul>
        </Section>

        <Section title="Solution">
          <div className="space-y-3">
            {solution.solution.map((s, i) => (
              <div key={s.title} className="rounded-lg border border-[var(--border-color)] bg-gray-950/20 p-3">
                {s.title ? <div className="text-sm font-semibold text-amber-300 mb-2">{s.title}</div> : null}
                <Row label="Formula" value={s.formula} />
                {s.substitution ? <Row label="Substitution" value={s.substitution} /> : null}
                {s.computation ? <Row label="Computation" value={s.computation} /> : null}
                {s.result ? <Row label="Result" value={s.result} highlight /> : null}
              </div>
            ))}
          </div>
        </Section>

        {solution.check && solution.check.length > 0 ? (
          <Section title="Check">
            <div className="space-y-2">
              {solution.check.map((c, i) => (
                <div
                  key={c.label}
                  className={`flex items-baseline justify-between gap-3 p-2 rounded border ${
                    c.ok === true
                      ? 'border-green-700 bg-green-900/10'
                      : c.ok === false
                        ? 'border-red-700 bg-red-900/10'
                        : 'border-[var(--border-color)] bg-gray-950/30'
                  }`}
                >
                  <div className="text-xs text-[var(--text-muted)]">{c.label}</div>
                  <div className="font-mono text-sm text-[var(--text-primary)] text-right">{c.value}</div>
                </div>
              ))}
            </div>
          </Section>
        ) : null}

        <Section title="Result">
          <div className="space-y-2">
            {solution.result.map((r, i) => (
              <div key={r.label} className="flex items-baseline justify-between gap-3 p-2 rounded bg-gray-950/30 border border-[var(--border-color)]">
                <div className="text-xs text-[var(--text-muted)]">{r.label}</div>
                <div className="font-mono text-sm text-amber-200 text-right">{r.value}</div>
              </div>
            ))}
          </div>
        </Section>
      </div>
    </div>
  )
}

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div>
      <div className="text-xs uppercase tracking-wider text-[var(--text-secondary)] mb-2">{title}</div>
      {children}
    </div>
  )
}

function Row({ label, value, highlight }: { label: string; value: string; highlight?: boolean }) {
  return (
    <div className="grid grid-cols-[100px_1fr] gap-3 text-sm">
      <div className="text-[var(--text-muted)]">{label}</div>
      <div className={`font-mono ${highlight ? 'text-amber-200 font-semibold' : 'text-[var(--text-primary)]'}`}>{value}</div>
    </div>
  )
}

'use client';
/**
 * METARDU Subdivision Panel
 *
 * UI panel for parcel subdivision operations.
 * Supports four methods: Grid, Radial, Area-Based, and Single Split.
 *
 * Style: Tailwind CSS, #1B3A5C primary, white cards, Calibri font.
 * Matches existing METARDU UI patterns from MeasurementTool and ParcelBuilderModal.
 */


import { useState } from 'react'
import {
  Grid3X3,
  Radar,
  Ruler,
  Scissors,
  Play,
  Trash2,
  Download,
  MapPin,
  Loader2,
  AlertCircle,
  ChevronDown,
  Info,
  Road,
  Eye,
  EyeOff,
  Printer,
} from 'lucide-react'
import type { SubdivisionMethod, SubdivisionParams, SubdivisionResult, SubdividedLot } from '@/types/subdivision'
import type { Point2D } from '@/lib/engine/types'
import { useSubdivision } from '@/hooks/useSubdivision'
import { usePrint, PrintButton, PrintHeader } from '@/hooks/usePrint'
import type Map from 'ol/Map'

interface SubdivisionPanelProps {
  /** Parent parcel vertices (EPSG:21037) */
  parentVertices: Point2D[]
  /** OpenLayers map instance */
  map: Map | null
  /** Project name for DXF export */
  projectName?: string
  /** CSS class for panel container */
  className?: string
}

type MethodOption = {
  id: SubdivisionMethod
  label: string
  icon: React.ReactNode
  description: string
}

const METHODS: MethodOption[] = [
  {
    id: 'grid',
    label: 'Grid',
    icon: <Grid3X3 className="w-4 h-4" />,
    description: 'Divide into equal grid cells',
  },
  {
    id: 'radial',
    label: 'Radial',
    icon: <Radar className="w-4 h-4" />,
    description: 'Create sectors from a center point',
  },
  {
    id: 'area',
    label: 'Area',
    icon: <Ruler className="w-4 h-4" />,
    description: 'Split by target lot area',
  },
  {
    id: 'single-split',
    label: 'Split Line',
    icon: <Scissors className="w-4 h-4" />,
    description: 'Cut by drawing a line on the map',
  },
]

function formatAreaHa(ha: number): string {
  if (ha < 0.01) return `${(ha * 10000).toFixed(1)} m²`
  return `${ha.toFixed(4)} ha`
}

function formatPerimeter(m: number): string {
  if (m < 1000) return `${m.toFixed(2)} m`
  return `${(m / 1000).toFixed(3)} km`
}

export default function SubdivisionPanel({
  parentVertices,
  map,
  projectName = 'METARDU_Subdivision',
  className = '',
}: SubdivisionPanelProps) {
  const {
    method,
    params,
    result,
    splitLine,
    isDrawingSplitLine,
    isComputing,
    error,
    roadReserveEnabled,
    roadReserveWidth,
    roadReserveEdges,
    roadReserveAuto,
    roadReservePreview,
    selectMethod,
    updateParams,
    execute,
    clear,
    startSplitLineDrawing,
    pickCenterPoint,
    exportDXF,
    setRoadReserveEnabled,
    setRoadReserveWidth,
    setRoadReserveAuto,
    previewRoadReserve,
    clearRoadReservePreview,
    toggleRoadReserveEdge,
  } = useSubdivision({
    parentVertices,
    map,
    projectName,
  })

  const [isCollapsed, setIsCollapsed] = useState(false)
  const { print, isPrinting, paperSize, setPaperSize, orientation, setOrientation } = usePrint({
    title: 'Subdivision Report',
    subtitle: `Method: ${method} · ${result ? `${result.lots.length} lots` : 'No results'}`,
  })

  // ─── Compute parent area ──────────────────────────────────────────────
  const parentArea = (() => {
    if (parentVertices.length < 3) return 0
    let area = 0
    const n = parentVertices.length
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n
      area += parentVertices[i].easting * parentVertices[j].northing
      area -= parentVertices[j].easting * parentVertices[i].northing
    }
    return Math.abs(area / 2) / 10000
  })()

  return (
    <div className={`bg-white rounded-lg shadow-lg border border-gray-200 ${className}`}>
      <PrintHeader
        title="Subdivision Report"
        subtitle={`Project: ${projectName} · Method: ${method} · ${result ? `${result.lots.length} lots · Total: ${formatAreaHa(result.totalAreaHa)}` : ''}`}
      />
      {/* ─── Header ──────────────────────────────────────────────────── */}
      <div
        className="flex items-center justify-between px-4 py-3 border-b border-gray-200 cursor-pointer select-none"
        onClick={() => setIsCollapsed(!isCollapsed)}
      >
        <div className="flex items-center gap-2">
          <div className="w-7 h-7 rounded bg-[#1B3A5C] flex items-center justify-center text-white">
            <Grid3X3 className="w-4 h-4" />
          </div>
          <div>
            <div className="text-sm font-semibold text-gray-900">Subdivision</div>
            <div className="text-[10px] text-gray-500">
              {parentVertices.length} pts · {formatAreaHa(parentArea)}
            </div>
          </div>
        </div>
        <ChevronDown className={`w-4 h-4 text-gray-400 transition-transform ${isCollapsed ? '-rotate-90' : ''}`} />
      </div>

      {isCollapsed ? null : (
        <div className="divide-y divide-gray-100">
          {/* ─── Road Reserve Section ──────────────────────────────────── */}
          <div className="p-3">
            <div className="flex items-center justify-between mb-2">
              <div className="text-[10px] text-gray-500 uppercase tracking-wider font-medium">
                Road Reserve
              </div>
              <button
                onClick={(e) => { e.stopPropagation(); setRoadReserveEnabled(!roadReserveEnabled); if (roadReserveEnabled) clearRoadReservePreview() }}
                className={`relative w-9 h-5 rounded-full transition-colors ${
                  roadReserveEnabled ? 'bg-[#1B3A5C]' : 'bg-gray-300'
                }`}
              >
                <span className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white shadow transition-transform ${
                  roadReserveEnabled ? 'translate-x-4' : 'translate-x-0'
                }`} />
              </button>
            </div>

            {roadReserveEnabled && (
              <div className="space-y-2.5 mt-2">
                {/* Width input */}
                <div>
                  <label className="text-[10px] text-gray-500 block mb-1" htmlFor="width-m">Width (m)</label>
                  <input id="width-m" aria-label="Width (m)"
                    type="number"
                    min={1}
                    max={100}
                    step={1}
                    value={roadReserveWidth}
                    onChange={(e) => setRoadReserveWidth(Math.max(1, parseFloat(e.target.value) || 1))}
                    className="w-full px-2.5 py-1.5 text-sm border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none font-mono"
                  />
                  <div className="text-[10px] text-gray-400 mt-1">
                    {roadReserveWidth < 8 ? 'Single lane' : roadReserveWidth < 16 ? '2-lane road' : roadReserveWidth < 24 ? '4-lane road' : 'Multi-lane / boulevard'}
                  </div>
                </div>

                {/* Edge selector */}
                <div>
                  <div className="text-[10px] text-gray-500 block mb-1">Edge Selection</div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => setRoadReserveAuto(true)}
                      className={`flex-1 px-2.5 py-1.5 text-[11px] font-medium rounded-md transition-colors ${
                        roadReserveAuto
                          ? 'bg-[#1B3A5C] text-white'
                          : 'bg-gray-100 text-gray-600 hover:bg-gray-200 border border-gray-200'
                      }`}
                    >
                      Auto (longest)
                    </button>
                    <button
                      onClick={() => setRoadReserveAuto(false)}
                      className={`flex-1 px-2.5 py-1.5 text-[11px] font-medium rounded-md transition-colors ${
                        !roadReserveAuto
                          ? 'bg-[#1B3A5C] text-white'
                          : 'bg-gray-100 text-gray-600 hover:bg-gray-200 border border-gray-200'
                      }`}
                    >
                      Manual
                    </button>
                  </div>
                </div>

                {/* Manual edge checkboxes */}
                {!roadReserveAuto && parentVertices.length >= 3 && (
                  <div className="border border-gray-200 rounded-md p-2 max-h-24 overflow-y-auto">
                    <div className="text-[10px] text-gray-400 mb-1">Select edges to apply road reserve:</div>
                    <div className="grid grid-cols-3 gap-1">
                      {parentVertices.map((_, idx) => {
                        if (idx >= parentVertices.length) return null
                        const nextIdx = (idx + 1) % parentVertices.length
                        const dx = parentVertices[nextIdx].easting - parentVertices[idx].easting
                        const dy = parentVertices[nextIdx].northing - parentVertices[idx].northing
                        const len = Math.sqrt(dx * dx + dy * dy)
                        return (
                          <label
                            key={`${_}-${idx}`}
                            className={`flex items-center gap-1 px-1.5 py-1 rounded text-[10px] cursor-pointer transition-colors ${
                              roadReserveEdges.includes(idx)
                                ? 'bg-amber-50 border border-amber-300 text-amber-800'
                                : 'bg-gray-50 border border-gray-200 text-gray-500 hover:bg-gray-100'
                            }`}
                          >
                            <input aria-label="Road reserve"
                              type="checkbox"
                              checked={roadReserveEdges.includes(idx)}
                              onChange={() => toggleRoadReserveEdge(idx)}
                              className="w-3 h-3 accent-[#1B3A5C]"
                            />
                            E{idx} ({len.toFixed(0)}m)
                          </label>
                        )
                      })}
                    </div>
                  </div>
                )}

                {/* Preview & info */}
                <div className="flex items-center gap-2">
                  <button
                    onClick={previewRoadReserve}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs text-[#1B3A5C] bg-amber-50 border border-amber-200 rounded-md hover:bg-amber-100 transition-colors"
                  >
                    <Eye className="w-3.5 h-3.5" />
                    Preview
                  </button>
                  {roadReservePreview && (
                    <button
                      onClick={clearRoadReservePreview}
                      className="flex items-center gap-1.5 px-3 py-1.5 text-xs text-gray-600 bg-gray-100 rounded-md hover:bg-gray-200 transition-colors"
                    >
                      <EyeOff className="w-3.5 h-3.5" />
                      Hide
                    </button>
                  )}
                </div>

                {roadReservePreview && (
                  <div className="p-2 bg-amber-50 border border-amber-200 rounded-md">
                    <div className="text-[11px] text-amber-800 font-medium mb-1">
                      <Road className="w-3.5 h-3.5 inline mr-1" />
                      Road Reserve Preview
                    </div>
                    <div className="text-[10px] text-amber-700 space-y-0.5">
                      <div>Width: {roadReservePreview.width}m</div>
                      <div>Area: {formatAreaHa(roadReservePreview.areaHa)}</div>
                      <div>Edge{roadReservePreview.clippedEdges.length !== 1 ? 's' : ''}: {roadReservePreview.clippedEdges.join(', ')}</div>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* ─── Method Selector ──────────────────────────────────────── */}
          <div className="p-3">
            <div className="text-[10px] text-gray-500 uppercase tracking-wider font-medium mb-2 block">
              Method
            </div>
            <div className="grid grid-cols-2 gap-1.5">
              {METHODS.map((m) => (
                <button
                  key={m.id}
                  onClick={() => selectMethod(m.id)}
                  className={`flex items-center gap-1.5 px-2.5 py-2 rounded-md text-xs font-medium transition-colors ${
                    method === m.id
                      ? 'bg-[#1B3A5C] text-white shadow-sm'
                      : 'bg-gray-50 text-gray-700 hover:bg-gray-100 border border-gray-200'
                  }`}
                  title={m.description}
                >
                  {m.icon}
                  <span>{m.label}</span>
                </button>
              ))}
            </div>
          </div>

          {/* ─── Parameters Form ──────────────────────────────────────── */}
          {method && (
            <div className="p-3 bg-gray-50/50">
              <div className="text-[10px] text-gray-500 uppercase tracking-wider font-medium mb-2 block">
                Parameters
              </div>

              {/* Grid params */}
              {method === 'grid' && (
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="text-[10px] text-gray-500 block mb-1" htmlFor="rows">Rows</label>
                    <input id="rows" aria-label="Rows"
                      type="number"
                      min={1}
                      max={20}
                      value={params.rows ?? 2}
                      onChange={(e) => updateParams({ rows: Math.max(1, parseInt(e.target.value) || 1) })}
                      className="w-full px-2.5 py-1.5 text-sm border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none"
                    />
                  </div>
                  <div>
                    <label className="text-[10px] text-gray-500 block mb-1" htmlFor="columns">Columns</label>
                    <input id="columns" aria-label="Columns"
                      type="number"
                      min={1}
                      max={20}
                      value={params.cols ?? 2}
                      onChange={(e) => updateParams({ cols: Math.max(1, parseInt(e.target.value) || 1) })}
                      className="w-full px-2.5 py-1.5 text-sm border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none"
                    />
                  </div>
                  <div className="col-span-2 text-[10px] text-gray-400 mt-1">
                    Creates up to {((params.rows ?? 2) * (params.cols ?? 2))} lots
                  </div>
                </div>
              )}

              {/* Radial params */}
              {method === 'radial' && (
                <div className="space-y-3">
                  <div>
                    <label className="text-[10px] text-gray-500 block mb-1" htmlFor="number-of-lots">Number of Lots</label>
                    <input id="number-of-lots" aria-label="Number of Lots"
                      type="number"
                      min={2}
                      max={36}
                      value={params.numLots ?? 4}
                      onChange={(e) => updateParams({ numLots: Math.max(2, parseInt(e.target.value) || 2) })}
                      className="w-full px-2.5 py-1.5 text-sm border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none"
                    />
                  </div>
                  <div>
                    <div className="text-[10px] text-gray-500 block mb-1">Center Point</div>
                    <div className="flex items-center gap-2">
                      <button
                        onClick={() => pickCenterPoint()}
                        className="flex items-center gap-1.5 px-3 py-1.5 text-xs bg-white border border-gray-300 rounded-md hover:bg-gray-50 transition-colors"
                      >
                        <MapPin className="w-3.5 h-3.5 text-[#1B3A5C]" />
                        {params.center
                          ? `E ${params.center.easting.toFixed(0)} N ${params.center.northing.toFixed(0)}`
                          : 'Click map to set'}
                      </button>
                      <span className="text-[10px] text-gray-400">
                        {params.center ? ' Set' : 'Default: centroid'}
                      </span>
                    </div>
                  </div>
                </div>
              )}

              {/* Area params */}
              {method === 'area' && (
                <div className="space-y-3">
                  <div>
                    <label className="text-[10px] text-gray-500 block mb-1" htmlFor="target-area-ha">Target Area (ha)</label>
                    <input id="target-area-ha" aria-label="Target Area (ha)"
                      type="number"
                      min={0.001}
                      step={0.01}
                      value={params.targetArea ?? (parentArea / 2).toFixed(4)}
                      onChange={(e) => updateParams({ targetArea: Math.max(0.001, parseFloat(e.target.value) || 0.001) })}
                      className="w-full px-2.5 py-1.5 text-sm border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none font-mono"
                    />
                    <div className="text-[10px] text-gray-400 mt-1">
                      Parent: {formatAreaHa(parentArea)} → ~{Math.max(1, Math.floor(parentArea / (params.targetArea ?? parentArea / 2)))} lots
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] text-gray-500 block mb-1" htmlFor="preferred-cut-bearing">Preferred Cut Bearing (°)</label>
                    <input id="preferred-cut-bearing"
                      type="number"
                      min={0}
                      max={360}
                      step={1}
                      aria-label="Preferred Cut Bearing (°)" placeholder="Auto (perpendicular)"
                      value={params.preferredBearing ?? ''}
                      onChange={(e) => {
                        const v = parseFloat(e.target.value)
                        updateParams({ preferredBearing: isNaN(v) ? undefined : v })
                      }}
                      className="w-full px-2.5 py-1.5 text-sm border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none font-mono"
                    />
                    <div className="text-[10px] text-gray-400 mt-1">
                      WCB: 0°=N, 90°=E, 180°=S, 270°=W. Leave empty for auto.
                    </div>
                  </div>
                </div>
              )}

              {/* Split line params */}
              {method === 'single-split' && (
                <div className="space-y-2">
                  {!splitLine && !isDrawingSplitLine && (
                    <div className="flex items-start gap-2 p-2.5 bg-blue-50 border border-blue-200 rounded-md">
                      <Info className="w-4 h-4 text-blue-600 mt-0.5 flex-shrink-0" />
                      <div>
                        <p className="text-xs text-blue-800">
                          Click the button below, then click two points on the map to define the split line.
                        </p>
                      </div>
                    </div>
                  )}
                  {isDrawingSplitLine && (
                    <div className="flex items-center gap-2 p-2.5 bg-amber-50 border border-amber-200 rounded-md">
                      <MapPin className="w-4 h-4 text-amber-600" />
                      <span className="text-xs text-amber-800 font-medium">
                        Click on the map to set the first point of the split line
                      </span>
                    </div>
                  )}
                  {splitLine && (
                    <div className="p-2.5 bg-green-50 border border-green-200 rounded-md">
                      <div className="text-xs text-green-800 font-medium mb-1"> Split line defined</div>
                      <div className="text-[10px] text-green-700 font-mono">
                        ({splitLine.startPoint.easting.toFixed(1)}, {splitLine.startPoint.northing.toFixed(1)}) →
                        ({splitLine.endPoint.easting.toFixed(1)}, {splitLine.endPoint.northing.toFixed(1)})
                      </div>
                    </div>
                  )}
                  {!splitLine && (
                    <button
                      onClick={startSplitLineDrawing}
                      className="flex items-center gap-1.5 px-3 py-1.5 text-xs bg-white border border-gray-300 rounded-md hover:bg-gray-50 transition-colors"
                    >
                      <Scissors className="w-3.5 h-3.5 text-[#1B3A5C]" />
                      Draw Split Line on Map
                    </button>
                  )}
                </div>
              )}
            </div>
          )}

          {/* ─── Error Display ────────────────────────────────────────── */}
          {error && (
            <div className="mx-3 mt-2 p-2.5 bg-red-50 border border-red-200 rounded-md flex items-start gap-2">
              <AlertCircle className="w-4 h-4 text-red-600 mt-0.5 flex-shrink-0" />
              <span className="text-xs text-red-800">{error}</span>
            </div>
          )}

          {/* ─── Action Buttons ───────────────────────────────────────── */}
          {method && (
            <div className="px-3 py-3 flex items-center gap-2">
              <button
                onClick={execute}
                disabled={isComputing || (method === 'single-split' && !splitLine)}
                className="flex items-center gap-1.5 px-4 py-2 bg-[#1B3A5C] text-white text-xs font-semibold rounded-md hover:bg-[#142d49] disabled:opacity-50 disabled:cursor-not-allowed transition-colors shadow-sm"
              >
                {isComputing ? (
                  <Loader2 className="w-3.5 h-3.5 animate-spin" />
                ) : (
                  <Play className="w-3.5 h-3.5" />
                )}
                {isComputing ? 'Computing...' : 'Subdivide'}
              </button>

              <button
                onClick={clear}
                className="flex items-center gap-1.5 px-3 py-2 text-xs text-gray-600 bg-gray-100 rounded-md hover:bg-gray-200 transition-colors"
              >
                <Trash2 className="w-3.5 h-3.5" />
                Clear
              </button>

              {result && result.lots.length > 0 && (
                <div className="flex items-center gap-2 ml-auto no-print print-hide">
                  <button
                    onClick={() => print({ title: 'Subdivision Report', subtitle: `Project: ${projectName} · ${result.lots.length} lots` })}
                    className="flex items-center gap-1.5 px-3 py-2 text-xs text-[#1B3A5C] bg-gray-50 border border-gray-200 rounded-md hover:bg-gray-100 transition-colors"
                  >
                    <Printer className="w-3.5 h-3.5" />
                    Print
                  </button>
                  <button
                    onClick={exportDXF}
                    className="flex items-center gap-1.5 px-3 py-2 text-xs text-[#1B3A5C] bg-blue-50 border border-blue-200 rounded-md hover:bg-blue-100 transition-colors"
                  >
                    <Download className="w-3.5 h-3.5" />
                    Export DXF
                  </button>
                </div>
              )}
            </div>
          )}

          {/* ─── Results Table ────────────────────────────────────────── */}
          {result && result.lots.length > 0 && (
            <div className="px-3 pb-3">
              {/* Road reserve summary in results */}
              {result.roadReserve && (
                <div className="mb-2 p-2 bg-amber-50 border border-amber-200 rounded-md">
                  <div className="text-[11px] text-amber-800 font-medium">
                    <Road className="w-3.5 h-3.5 inline mr-1" />
                    Road Reserve: {formatAreaHa(result.roadReserve.areaHa)}
                  </div>
                  <div className="text-[10px] text-amber-700">
                    {result.roadReserve.width}m width · Edge{result.roadReserve.clippedEdges.length !== 1 ? 's' : ''} {result.roadReserve.clippedEdges.join(', ')}
                  </div>
                </div>
              )}

              <div className="flex items-center justify-between mb-2">
                <label className="text-[10px] text-gray-500 uppercase tracking-wider font-medium">
                  Results — {result.lots.length} Lot{result.lots.length !== 1 ? 's' : ''}
                </label>
                <div className="text-[10px] text-gray-400">
                  Total: {formatAreaHa(result.totalAreaHa)}
                  {result.remainderAreaHa > 0.0001 && (
                    <span className="text-amber-600 ml-1">
                      (Remainder: {formatAreaHa(result.remainderAreaHa)})
                    </span>
                  )}
                </div>
              </div>

              <div className="border border-gray-200 rounded-md overflow-hidden max-h-64 overflow-y-auto">
                <table className="w-full text-xs">
                  <thead className="bg-gray-50 sticky top-0">
                    <tr className="border-b border-gray-200">
                      <th className="text-left py-1.5 px-2.5 text-[10px] text-gray-500 font-medium">Lot</th>
                      <th className="text-right py-1.5 px-2.5 text-[10px] text-gray-500 font-medium">Area (ha)</th>
                      <th className="text-right py-1.5 px-2.5 text-[10px] text-gray-500 font-medium">Perimeter</th>
                      <th className="text-left py-1.5 px-2.5 text-[10px] text-gray-500 font-medium">Centroid</th>
                    </tr>
                  </thead>
                  <tbody>
                    {result.lots.map((lot) => (
                      <LotRow key={lot.lotNumber} lot={lot} />
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* ─── Empty state ──────────────────────────────────────────── */}
          {!method && (
            <div className="px-3 py-6 text-center">
              <div className="text-gray-300 mb-2">
                <Grid3X3 className="w-8 h-8 mx-auto" />
              </div>
              <p className="text-xs text-gray-400">
                Select a subdivision method above to begin
              </p>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

/** Individual lot row in the results table. */
function LotRow({ lot }: { lot: SubdividedLot }) {
  return (
    <tr className="border-b border-gray-100 hover:bg-gray-50 transition-colors">
      <td className="py-1.5 px-2.5">
        <span className="inline-flex items-center justify-center w-6 h-6 rounded bg-[#1B3A5C] text-white text-[10px] font-bold">
          {lot.lotNumber}
        </span>
      </td>
      <td className="py-1.5 px-2.5 text-right font-mono font-medium">
        {lot.areaHa.toFixed(4)}
        {lot.areaError !== undefined && Math.abs(lot.areaError) > 0.001 && (
          <span className={`ml-1 text-[9px] ${Math.abs(lot.areaError) < 0.05 ? 'text-green-600' : 'text-amber-600'}`}>
            ({lot.areaError >= 0 ? '+' : ''}{lot.areaError.toFixed(4)})
          </span>
        )}
      </td>
      <td className="py-1.5 px-2.5 text-right font-mono text-gray-600">
        {formatPerimeter(lot.perimeter)}
      </td>
      <td className="py-1.5 px-2.5 font-mono text-gray-500 text-[10px]">
        E {lot.centroid.easting.toFixed(0)} N {lot.centroid.northing.toFixed(0)}
      </td>
    </tr>
  )
}

'use client'

/**
 * NLIMSExportPanel — UI for generating NLIMS/ArdhiSasa submission payloads
 *
 * Allows the surveyor to:
 * 1. Select submission type (mutation, subdivision, etc.)
 * 2. Enter surveyor info (auto-filled from profile if available)
 * 3. Select parcels to export
 * 4. Run validation
 * 5. Download the NLIMS JSON payload
 *
 * Uses the existing /api/export/nlims endpoint and lib/export/nlimsExporter.
 */

import { useState, useCallback } from 'react'
import {
  FileOutput, Download, Loader2, CheckCircle2, AlertCircle,
  Building2, MapPin, ShieldCheck,
} from 'lucide-react'
import { downloadNLIMSPayload, type NLIMSSubmissionPayload, type NLIMSValidationResult } from '@/lib/export/nlimsExporter'

interface NLIMSExportPanelProps {
  projectId: string
}

export function NLIMSExportPanel({ projectId }: NLIMSExportPanelProps) {
  const [expanded, setExpanded] = useState(false)
  const [generating, setGenerating] = useState(false)
  const [payload, setPayload] = useState<NLIMSSubmissionPayload | null>(null)
  const [validation, setValidation] = useState<NLIMSValidationResult | null>(null)
  const [error, setError] = useState<string | null>(null)

  // Form fields
  const [submissionType, setSubmissionType] = useState<'mutation' | 'subdivision' | 'amalgamation' | 'new_registration' | 'boundary_adjustment'>('subdivision')
  const [registry, setRegistry] = useState('Nairobi')
  const [county, setCounty] = useState('Nairobi')
  const [subCounty, setSubCounty] = useState('')
  const [surveyorName, setSurveyorName] = useState('')
  const [licenseNumber, setLicenseNumber] = useState('')
  const [firm, setFirm] = useState('')

  const handleGenerate = useCallback(async () => {
    setGenerating(true)
    setError(null)
    setPayload(null)
    setValidation(null)

    try {
      const res = await fetch('/api/export/nlims', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          submissionType,
          registry,
          county,
          subCounty,
          surveyor: {
            name: surveyorName,
            licenseNumber,
            firm: firm || undefined,
          },
          resultingParcels: [], // Will be populated from project data
          beacons: [],
          // Parent parcel info would come from the project's existing parcel data
        }),
      })

      const data = (await res.json()) as {
        validation?: NLIMSValidationResult | null
        error?: string
        payload?: NLIMSSubmissionPayload | null
      }

      if (!res.ok) {
        if (data.validation) {
          setValidation(data.validation)
          setError('Validation failed — fix the errors below')
        } else {
          setError(data.error || 'Failed to generate NLIMS payload')
        }
        return
      }

      setPayload(data.payload ?? null)
      setValidation(data.validation ?? null)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Network error')
    } finally {
      setGenerating(false)
    }
  }, [submissionType, registry, county, subCounty, surveyorName, licenseNumber, firm])

  const handleDownload = useCallback(() => {
    if (!payload) return
    downloadNLIMSPayload(payload)
  }, [payload])

  return (
    <div className="mt-6 rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
      {/* Header */}
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between px-4 py-3 hover:bg-[var(--bg-tertiary)]/50 transition-colors"
      >
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-blue-500/10 flex items-center justify-center">
            <Building2 className="w-4 h-4 text-blue-400" />
          </div>
          <div className="text-left">
            <span className="text-sm font-semibold text-[var(--text-primary)]">NLIMS / ArdhiSasa Export</span>
            <p className="text-[10px] text-gray-500">Generate registry-ready JSON submission</p>
          </div>
        </div>
        <svg className={`w-4 h-4 text-gray-500 transition-transform ${expanded ? 'rotate-180' : ''}`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
          <path d="M6 9l6 6 6-6" />
        </svg>
      </button>

      {expanded && (
        <div className="border-t border-[var(--border-color)] p-4 space-y-4">
          {/* Submission type */}
          <div>
            <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="submission-type">Submission Type</label>
            <select id="submission-type"
              value={submissionType}
              onChange={e => setSubmissionType(e.target.value as typeof submissionType)}
