          {/* Surveyor info */}
          <div className="pt-2 border-t border-[var(--border-color)]">
            <div className="flex items-center gap-1.5 mb-2">
              <ShieldCheck className="w-3.5 h-3.5 text-[var(--accent)]" />
              <span className="text-[10px] text-gray-500 uppercase tracking-wider font-semibold">Surveyor Information</span>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="name">Name</label>
                <input id="name"
                  type="text"
                  value={surveyorName}
                  onChange={e => setSurveyorName(e.target.value)}
                  className="input h-10 text-sm"
 placeholder="John Doe"
                />
              </div>
              <div>
                <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="license-no">License No.</label>
                <input id="license-no"
                  type="text"
                  value={licenseNumber}
                  onChange={e => setLicenseNumber(e.target.value)}
                  className="input h-10 text-sm font-mono"
 placeholder="ISK/LS/2021/0452"
                />
              </div>
            </div>
            <div className="mt-2">
              <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="firm-optional">Firm (optional)</label>
              <input id="firm-optional"
                type="text"
                value={firm}
                onChange={e => setFirm(e.target.value)}
                className="input h-10 text-sm"
 placeholder="Doe Surveyors Ltd"
              />
            </div>
          </div>

          {/* Generate button */}
          <button
            onClick={handleGenerate}
            disabled={generating || !surveyorName || !licenseNumber}
            className="w-full flex items-center justify-center gap-2 h-10 rounded-lg bg-blue-500 hover:bg-blue-600 text-white text-sm font-semibold transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
          >
            {generating ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileOutput className="w-4 h-4" />}
            {generating ? 'Generating...' : 'Generate NLIMS Payload'}
          </button>

          {/* Validation errors */}
          {validation && !validation.isValid && (
            <div className="p-3 rounded-lg bg-red-500/5 border border-red-500/20">
              <div className="flex items-center gap-1.5 mb-1.5">
                <AlertCircle className="w-3.5 h-3.5 text-red-400" />
                <span className="text-xs font-medium text-red-400">Validation Errors</span>
              </div>
              <ul className="text-[11px] text-red-400/80 space-y-0.5 list-disc list-inside">
                {validation.errors.map((e, i) => (
                  <li key={`${e}-${i}`}>{e.message}</li>
                ))}
              </ul>
              {validation.warnings.length > 0 && (
                <div className="mt-2 pt-2 border-t border-red-500/10">
                  <span className="text-[10px] text-amber-400 font-medium">Warnings:</span>
                  <ul className="text-[10px] text-amber-400/70 space-y-0.5 list-disc list-inside mt-0.5">
                    {validation.warnings.map((w, i) => (
                      <li key={`${w}-${i}`}>{w.message}</li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          )}

          {/* Success + download */}
          {payload && (
            <div className="p-3 rounded-lg bg-emerald-500/5 border border-emerald-500/20">
              <div className="flex items-center gap-2 mb-2">
                <CheckCircle2 className="w-4 h-4 text-emerald-400" />
                <span className="text-sm font-medium text-emerald-400">Payload Generated</span>
              </div>
              <div className="text-[11px] text-gray-400 space-y-0.5 mb-3">
                <div>Submission ID: <span className="font-mono">{payload.submissionId}</span></div>
                <div>Parcels: {payload.resultingParcels.length}</div>
                <div>Beacons: {payload.beacons.length}</div>
                <div>Integrity: <span className="font-mono">{payload.integrity.hash.substring(0, 16)}...</span></div>
                {payload.areaReconciliation.parentAreaHectares != null && (
                  <div className={payload.areaReconciliation.isWithinTolerance ? 'text-emerald-400' : 'text-red-400'}>
                    Area check: {payload.areaReconciliation.sumOfPartsHectares.toFixed(4)} ha vs parent {payload.areaReconciliation.parentAreaHectares.toFixed(4)} ha
                    ({payload.areaReconciliation.isWithinTolerance ? 'OK' : 'MISMATCH'})
                  </div>
                )}
              </div>
              <button
                onClick={handleDownload}
                className="w-full flex items-center justify-center gap-2 h-9 rounded-lg bg-emerald-500 hover:bg-emerald-600 text-white text-xs font-semibold transition-colors"
              >
                <Download className="w-3.5 h-3.5" />
                Download NLIMS JSON
              </button>
            </div>
          )}

          {/* Error */}
          {error && !validation && (
            <div className="p-3 rounded-lg bg-red-500/5 border border-red-500/20 flex items-start gap-2">
              <AlertCircle className="w-4 h-4 text-red-400 shrink-0 mt-0.5" />
              <p className="text-xs text-red-400">{error}</p>
            </div>
          )}

          {/* Info note */}
          <div className="flex items-start gap-2 p-2.5 rounded-lg bg-blue-500/5 border border-blue-500/10">
            <MapPin className="w-3.5 h-3.5 text-blue-400 shrink-0 mt-0.5" />
            <p className="text-[10px] text-blue-400/70 leading-relaxed">
              NLIMS payloads use Arc 1960 / UTM Zone 37S coordinates (EPSG:21037) with 3 decimal places.
              Area reconciliation tolerance: ±0.001 ha (10 m²). SHA-256 integrity hash ensures tamper detection.
            </p>
          </div>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useEffect } from 'react'
import { createClient } from '@/lib/api-client/client'
import { logger } from '@/lib/logger'

interface Doc {
  id: string
  type: string
  label: string
  required: boolean
  file_url: string | null
}

export function SupportingDocUpload({ projectId }: { projectId: string }) {
  const [docs, setDocs] = useState<Doc[]>([])
  const [uploading, setUploading] = useState<string | null>(null)
  const dbClient = createClient()

  useEffect(() => {
    loadDocs()
  }, [projectId])

  async function loadDocs() {
    const { data } = await dbClient
      .from('supporting_documents')
      .select('*')
            .eq('project_id', projectId) as unknown as { data: Doc[] | null }
    setDocs((data ?? []) as Doc[])
  }

  async function handleUpload(docId: string, docType: string, file: File) {
    setUploading(docId)
    try {
      const formData = new FormData()
      formData.append('file', file)
      formData.append('bucket', `submission-docs/${projectId}/${docType}`)

      const res = await fetch('/api/storage', {
        method: 'POST',
        body: formData
      })

      if (!res.ok) throw new Error('Upload failed')

      const json = await res.json() as { url: string }
      const fileUrl = json.url

      await dbClient
        .from('supporting_documents')
        .update({
          file_url: fileUrl,
          uploaded_at: new Date().toISOString()
        })
        .eq('id', docId)

      await loadDocs()
    } catch (err) {
      logger.error('Upload failed:', { error: err })
    } finally {
      setUploading(null)
    }
  }

  return (
    <div className="space-y-4">
      <h3 className="font-semibold text-lg">Supporting Documents</h3>
      {docs.map(doc => (
        <div
          key={doc.id}
          className="flex items-center justify-between border rounded-lg p-4"
        >
          <div>
            <p className="font-medium text-sm">{doc.label}</p>
            <p className="text-xs text-muted-foreground">
              {doc.required ? 'Required' : 'Optional'}
              {doc.file_url && (
                <span className="ml-2 text-green-400"> Uploaded</span>
              )}
            </p>
          </div>
          <label className="cursor-pointer">
            <span className="text-sm bg-secondary px-3 py-1.5 rounded border">
              {uploading === doc.id ? 'Uploading...' : doc.file_url ? 'Replace' : 'Upload PDF'}
            </span>
            <input
              type="file"
              accept=".pdf"
              className="hidden"
              disabled={uploading === doc.id}
              onChange={e => {
                const file = e.target.files?.[0]
                if (file) handleUpload(doc.id, doc.type, file)
              }}
            />
          </label>
        </div>
      ))}
    </div>
  )
}

'use client'

/**
 * ControlPointRegistry — SoK Control Point Index & Network Search
 *
 * Features:
 * - Search by coordinate + radius to find nearest control points
 * - Shows trig stations, KENCORS stations, and benchmarks
 * - Calculates bearing and distance to each point (for traverse planning)
 * - Filter by type (Trig, CORS, Benchmark)
 * - Click to highlight on map
 *
 * Uses existing:
 * - src/lib/map/kencors.ts (KENCORS_STATIONS + nearestKenCORSStations)
 * - src/lib/online/benchmarks.ts (benchmark database)
 */

import { useState, useCallback, useMemo } from 'react'
import {
  Radio, MapPin, Search, Loader2, Navigation,
  Triangle, Building2, ChevronRight,
} from 'lucide-react'
import { logger } from '@/lib/logger'

export interface ControlPoint {
  id: string
  name: string
  type: 'trig' | 'cors' | 'benchmark'
  easting: number
  northing: number
  county?: string
  elevation?: number | null
  distanceM?: number
  bearingDeg?: number
  status?: 'active' | 'inactive'
}

type PointType = 'all' | 'trig' | 'cors' | 'benchmark'

const TYPE_CONFIG: Record<string, { label: string; icon: typeof Radio; color: string; bg: string }> = {
  trig: { label: 'Trig Station', icon: Triangle, color: 'text-red-400', bg: 'bg-red-500/10' },
  cors: { label: 'CORS Station', icon: Radio, color: 'text-blue-400', bg: 'bg-blue-500/10' },
  benchmark: { label: 'Benchmark', icon: Building2, color: 'text-emerald-400', bg: 'bg-emerald-500/10' },
}

/**
 * Calculate bearing from origin to destination (in degrees, 0-360).
 */
function calculateBearing(fromE: number, fromN: number, toE: number, toN: number): number {
  const dE = toE - fromE
  const dN = toN - fromN
  let bearing = Math.atan2(dE, dN) * 180 / Math.PI
  if (bearing < 0) bearing += 360
  return bearing
}

/**
 * Format bearing as DMS (e.g., "45°30'15\"").
 */
function formatBearingDMS(bearing: number): string {
  const deg = Math.floor(bearing)
  const minFull = (bearing - deg) * 60
  const min = Math.floor(minFull)
  const sec = (minFull - min) * 60
  return `${deg}°${min}'${sec.toFixed(0)}"`
}

export function ControlPointRegistry() {
  const [easting, setEasting] = useState('')
  const [northing, setNorthing] = useState('')
  const [radius, setRadius] = useState('10000') // 10km default
  const [typeFilter, setTypeFilter] = useState<PointType>('all')
  const [results, setResults] = useState<ControlPoint[]>([])
  const [loading, setLoading] = useState(false)
  const [searched, setSearched] = useState(false)

  const search = useCallback(async () => {
    const e = parseFloat(easting)
    const n = parseFloat(northing)
    if (!isFinite(e) || !isFinite(n)) {
      alert('Enter valid easting and northing')
      return
    }

    setLoading(true)
    setSearched(true)
    try {
      // 1. Search KENCORS stations (existing module)
      const { KENCORS_STATIONS, nearestKenCORSStations } = await import('@/lib/map/kencors')
      const corsResults: ControlPoint[] = nearestKenCORSStations(e, n, 10).map(s => ({
        id: s.id,
        name: s.name,
        type: 'cors' as const,
        easting: s.easting,
        northing: s.northing,
        county: s.county,
        distanceM: s.distanceKm * 1000,
        bearingDeg: calculateBearing(e, n, s.easting, s.northing),
        status: s.status,
      }))

      // 2. Search benchmarks (existing module)
      let benchmarkResults: ControlPoint[] = []
      try {
        const { searchBenchmarks } = await import('@/lib/online/benchmarks')
        const benchmarks = await searchBenchmarks({
          latitude: 0, // Benchmarks use lat/lng — would need coordinate transform
          longitude: 0,
          radiusKm: parseFloat(radius) / 1000,
          type: 'ALL',
        })
        benchmarkResults = (benchmarks.benchmarks || []).slice(0, 10).map(b => ({
          id: b.id,
          name: b.name,
          type: 'benchmark' as const,
          easting: b.easting || 0,
          northing: b.northing || 0,
          county: b.region,
          elevation: b.elevation,
          distanceM: 0, // Would calculate if coords available
          status: 'active' as const,
        }))
      } catch {}

      // 3. Combine and filter
      let combined = [...corsResults, ...benchmarkResults]
      if (typeFilter !== 'all') {
        combined = combined.filter(p => p.type === typeFilter)
      }

      // Sort by distance
      combined.sort((a, b) => (a.distanceM || 0) - (b.distanceM || 0))

      // Limit to radius
      const radiusM = parseFloat(radius)
      combined = combined.filter(p => (p.distanceM || 0) <= radiusM)

      setResults(combined)
    } catch (err) {
      logger.error('[ControlPointRegistry] Search failed:', { error: err })
      setResults([])
    } finally {
      setLoading(false)
    }
  }, [easting, northing, radius, typeFilter])

  // Auto-search with default Nairobi coordinates
  const useDefaultLocation = useCallback(() => {
    setEasting('261518')
    setNorthing('9859340')
  }, [])

  return (
    <div className="space-y-4">
      {/* Search panel */}
      <div className="card p-4 space-y-3">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
            <Radio className="w-4 h-4 text-[var(--accent)]" />
          </div>
          <div>
            <h2 className="text-sm font-semibold text-[var(--text-primary)]">Control Point Registry</h2>
            <p className="text-[10px] text-gray-500">Find nearest Trig stations, KENCORS, and benchmarks</p>
          </div>
        </div>

        <div className="grid grid-cols-3 gap-2">
          <div>
            <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="easting-m">Easting (m)</label>
            <input id="easting-m" type="number" value={easting} onChange={e => setEasting(e.target.value)} placeholder="261518" className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none" />
          </div>
          <div>
            <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="northing-m">Northing (m)</label>
            <input id="northing-m" type="number" value={northing} onChange={e => setNorthing(e.target.value)} placeholder="9859340" className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none" />
          </div>
          <div>
            <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="radius-m">Radius (m)</label>
            <input id="radius-m" aria-label="Radius (m)" type="number" value={radius} onChange={e => setRadius(e.target.value)} className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono focus:border-[var(--accent)]/30 focus:outline-none" />
          </div>
        </div>

        <div className="flex items-center gap-2">
          <select
            value={typeFilter}
            onChange={e => setTypeFilter(e.target.value as PointType)}
            className="h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)]"
          >
            <option value="all">All Types</option>
            <option value="trig">Trig Stations</option>
            <option value="cors">CORS Stations</option>
            <option value="benchmark">Benchmarks</option>
          </select>
          <button
            onClick={useDefaultLocation}
            className="h-9 px-3 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-gray-400 hover:text-gray-200"
          >
            Use Nairobi
          </button>
          <button
            onClick={search}
            disabled={loading || !easting || !northing}
            className="flex-1 flex items-center justify-center gap-2 h-9 rounded-lg bg-[var(--accent)] text-black text-xs font-semibold hover:bg-[var(--accent-dim)] disabled:opacity-40"
          >
            {loading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Search className="w-3.5 h-3.5" />}
            Find Control Points
          </button>
        </div>
      </div>

      {/* Results */}
      {searched && (
        <div className="card p-4">
          {loading ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="w-6 h-6 text-gray-500 animate-spin" />
            </div>
          ) : results.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-8 text-center">
              <MapPin className="w-8 h-8 text-gray-600 mb-2" />
              <p className="text-sm text-gray-500">No control points found in radius</p>
              <p className="text-[10px] text-gray-600 mt-1">Try increasing the search radius</p>
            </div>
          ) : (
            <>
              <div className="flex items-center justify-between mb-3">
                <span className="text-xs font-medium text-[var(--text-primary)]">
                  {results.length} control point{results.length !== 1 ? 's' : ''} found
                </span>
                <span className="text-[10px] text-gray-500">
                  Sorted by distance from search location
                </span>
              </div>

              <div className="space-y-2">
                {results.map(point => {
                  const cfg = TYPE_CONFIG[point.type]
                  const Icon = cfg.icon
                  return (
                    <div
                      key={point.id}
                      className="flex items-start gap-3 p-3 rounded-lg border border-[var(--border-color)] hover:border-[var(--accent)]/30 transition-colors group"
                    >
                      <div className={`shrink-0 w-10 h-10 rounded-lg ${cfg.bg} flex items-center justify-center`}>
                        <Icon className={`w-4 h-4 ${cfg.color}`} />
                      </div>

                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="text-sm font-medium text-[var(--text-primary)]">{point.name}</span>
                          <span className={`text-[9px] px-1.5 py-0.5 rounded ${cfg.bg} ${cfg.color} uppercase`}>
                            {cfg.label}
                          </span>
                          {point.status === 'inactive' && (
                            <span className="text-[9px] px-1.5 py-0.5 rounded bg-gray-500/10 text-gray-400 uppercase">
                              Inactive
                            </span>
                          )}
                        </div>

                        <div className="text-[10px] text-gray-500 font-mono mt-0.5">
                          E: {point.easting.toFixed(3)} | N: {point.northing.toFixed(3)}
                          {point.elevation != null && ` | Elev: ${point.elevation.toFixed(2)}m`}
                        </div>

                        {point.county && (
                          <div className="text-[10px] text-gray-600 mt-0.5">{point.county}</div>
                        )}

                        {point.distanceM != null && point.bearingDeg != null && (
                          <div className="flex items-center gap-3 mt-1.5">
                            <span className="flex items-center gap-1 text-[10px] text-[var(--accent)] font-medium">
                              <Navigation className="w-2.5 h-2.5" />
                              {(point.distanceM / 1000).toFixed(2)} km
                            </span>
                            <span className="text-[10px] text-blue-400 font-mono">
                              Bearing: {formatBearingDMS(point.bearingDeg)}
                            </span>
                          </div>
                        )}
                      </div>

                      <ChevronRight className="w-4 h-4 text-gray-600 opacity-0 group-hover:opacity-100 transition-opacity" />
                    </div>
                  )
                })}
              </div>

              {/* Traverse planning note */}
              <div className="mt-3 flex items-start gap-2 p-2.5 rounded-lg bg-blue-500/5 border border-blue-500/10">
                <Navigation className="w-3 h-3 text-blue-400 shrink-0 mt-0.5" />
                <p className="text-[10px] text-blue-400/70 leading-relaxed">
                  Use these control points as reference stations for your traverse.
                  The bearing and distance help plan baseline vectors before field work.
                  Per Survey Act Cap 299, all cadastral traverses must be tied to the national geodetic network.
                </p>
              </div>
            </>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

/**
 * CoordinateChip — Live multi-datum coordinate display
 *
 * Shows a captured coordinate in multiple Kenya survey datums simultaneously:
 * - WGS84 (lat/lng) — what GNSS rovers record
 * - Arc 1960 / UTM 37S (EPSG:21037) — what registries use
 * - Cassini-Soldner — what legacy RIMs use
 *
 * This eliminates the need for surveyors to export to desktop software
 * just to verify their field points match reference title coordinates.
 */

import { useEffect, useState } from 'react'
import { Globe, MapPin, Layers } from 'lucide-react'
import { logger } from '@/lib/logger'

interface CoordinateChipProps {
  lat: number
  lng: number
  /** Show all datums or just WGS84 + UTM (compact mode) */
  showCassini?: boolean
  /** Label for the coordinate (e.g., "Captured Point", "Beacon 04") */
  label?: string
  /** Accuracy in meters (optional) */
  accuracy?: number
  /** Compact mode — smaller text, single line per datum */
  compact?: boolean
  /** T1.5 FIX (2026-07-09): UTM EPSG for the transform (default 'EPSG:21037') */
  epsg?: string
}

interface DatumDisplay {
  wgs84: { lat: number; lng: number } | null
  utm37s: { easting: number; northing: number } | null
  cassini: { easting: number; northing: number; sheet?: string } | null
}

export function CoordinateChip({
  lat,
  lng,
  showCassini = false,
  label,
  accuracy,
  compact = false,
  epsg = 'EPSG:21037',
}: CoordinateChipProps) {
  const [datums, setDatums] = useState<DatumDisplay>({
    wgs84: { lat, lng },
    utm37s: null,
    cassini: null,
  })

  useEffect(() => {
    let cancelled = false

    async function transform() {
      try {
        // Transform to UTM (Arc 1960 / UTM 37S by default)
        let utm37s: { easting: number; northing: number } | null = null
        try {
          const { transform } = await import('ol/proj')
          const [e, n] = transform([lng, lat], 'EPSG:4326', epsg) as [number, number]
          if (!cancelled && isFinite(e) && isFinite(n)) {
            utm37s = { easting: e, northing: n }
          }
        } catch {}

        // Transform to Cassini-Soldner (if requested)
        // Note: Cassini transform requires knowing the specific sheet origin.
        // The cassini module provides feet-to-UTM transforms, not direct WGS84→Cassini.
        // For now, we skip Cassini display unless a sheet-specific transform is available.
        let cassini: { easting: number; northing: number; sheet?: string } | null = null
        if (showCassini) {
          // TODO: Integrate sheet-specific Cassini transform when available
          // For now, display a note that Cassini requires sheet selection
          cassini = null
        }

        if (!cancelled) {
          setDatums({
            wgs84: { lat, lng },
            utm37s,
            cassini,
          })
        }
      } catch (err) {
        logger.warn('[CoordinateChip] Transform failed:', { error: err })
      }
    }

    transform()
    return () => { cancelled = true }
  }, [lat, lng, showCassini])

  const fmt = (n: number, decimals: number) => n.toFixed(decimals)

  return (
    <div className={`rounded-lg border border-white/[0.06] bg-[#0d0d14]/60 backdrop-blur-sm ${compact ? 'p-2' : 'p-3'} space-y-1.5`}>
      {label && (
        <div className="flex items-center justify-between mb-1">
          <span className="text-[10px] text-gray-500 uppercase tracking-wider font-semibold">{label}</span>
          {accuracy != null && (
            <span className={`text-[9px] font-mono px-1.5 py-0.5 rounded ${
              accuracy < 3 ? 'bg-emerald-500/15 text-emerald-400' :
              accuracy <= 10 ? 'bg-amber-500/15 text-amber-400' :
              'bg-red-500/15 text-red-400'
            }`}>
              ±{accuracy.toFixed(1)}m
            </span>
          )}
        </div>
      )}

      {/* WGS84 */}
      <div className="flex items-start gap-2">
        <Globe className="w-3 h-3 text-blue-400 shrink-0 mt-0.5" />
        <div className="flex-1 min-w-0">
          <span className="text-[9px] text-gray-600 uppercase tracking-wider">WGS84</span>
          <div className={`font-mono text-gray-300 ${compact ? 'text-[10px]' : 'text-xs'}`}>
            {fmt(datums.wgs84!.lat, 6)}, {fmt(datums.wgs84!.lng, 6)}
          </div>
        </div>
      </div>

      {/* Arc 1960 / UTM 37S */}
      {datums.utm37s && (
        <div className="flex items-start gap-2">
          <MapPin className="w-3 h-3 text-[#D17B47] shrink-0 mt-0.5" />
          <div className="flex-1 min-w-0">
            <span className="text-[9px] text-gray-600 uppercase tracking-wider">Arc 1960 / UTM 37S</span>
            <div className={`font-mono text-gray-300 ${compact ? 'text-[10px]' : 'text-xs'}`}>
              E: {fmt(datums.utm37s.easting, 3)}, N: {fmt(datums.utm37s.northing, 3)}
            </div>
          </div>
        </div>
      )}

      {/* Cassini-Soldner */}
      {datums.cassini && (
        <div className="flex items-start gap-2">
          <Layers className="w-3 h-3 text-purple-400 shrink-0 mt-0.5" />
          <div className="flex-1 min-w-0">
            <span className="text-[9px] text-gray-600 uppercase tracking-wider">
              Cassini{datums.cassini.sheet ? ` — Sheet ${datums.cassini.sheet}` : ''}
            </span>
            <div className={`font-mono text-gray-300 ${compact ? 'text-[10px]' : 'text-xs'}`}>
              E: {fmt(datums.cassini.easting, 3)}, N: {fmt(datums.cassini.northing, 3)}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

/**
 * FieldRecordVault — Crowdsourced historic F/R index
 *
 * Search and contribute historic Field Record numbers spatially.
 * Surveyors can find old F/R numbers by searching near their project area,
 * saving days of archival research at Ardhi House.
 *
 * Features:
 * - Text search (F/R number, locality, surveyor name)
 * - Proximity search (by coordinate + radius)
 * - Contribute new records
 * - View results with distance, year, surveyor, parcels
 */

import { useState, useCallback, useEffect } from 'react'
import {
  Search, MapPin, Plus, Loader2, CheckCircle2,
  Calendar, User, FileText, ChevronRight, X,
} from 'lucide-react'
import { VirtualList } from '@/components/shared/VirtualList'

interface FieldRecord {
  id: string
  fr_number: string
  fr_type: string
  easting: number
  northing: number
  county?: string
  locality?: string
  survey_year?: number
  surveyor_name?: string
  parcel_numbers?: string[]
  description?: string
  is_verified: boolean
  distance_m?: number
}

export function FieldRecordVault() {
  const [records, setRecords] = useState<FieldRecord[]>([])
  const [loading, setLoading] = useState(false)
  const [searchMode, setSearchMode] = useState<'text' | 'proximity'>('text')
  const [query, setQuery] = useState('')
  const [easting, setEasting] = useState('')
  const [northing, setNorthing] = useState('')
  const [radius, setRadius] = useState('5000')
  const [showAddForm, setShowAddForm] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const search = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const params = new URLSearchParams()
      if (searchMode === 'text' && query) {
        params.set('q', query)
      } else if (searchMode === 'proximity') {
        if (!easting || !northing) {
          setError('Enter easting and northing for proximity search')
          setLoading(false)
          return
        }
        params.set('easting', easting)
        params.set('northing', northing)
        params.set('radius', radius)
      }
      params.set('limit', '50')

      const res = await fetch(`/api/field-records?${params}`)
      if (!res.ok) throw new Error('Search failed')
      const data = await res.json() as { data?: { records?: FieldRecord[] } }
      setRecords(data.data?.records || [])
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Search failed')
    } finally {
      setLoading(false)
    }
  }, [searchMode, query, easting, northing, radius])

  useEffect(() => {
    search()
  }, [])

  return (
    <div className="space-y-4">
      {/* Search header */}
      <div className="card p-4 space-y-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
              <FileText className="w-4 h-4 text-[var(--accent)]" />
            </div>
            <div>
              <h2 className="text-sm font-semibold text-[var(--text-primary)]">F/R Index Vault</h2>
              <p className="text-[10px] text-gray-500">Crowdsourced historic field record search</p>
            </div>
          </div>
          <button
            onClick={() => setShowAddForm(!showAddForm)}
            className="flex items-center gap-1.5 px-3 h-8 rounded-lg bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)] text-xs font-medium hover:bg-[var(--accent)]/20"
          >
            <Plus className="w-3.5 h-3.5" />
            Contribute
          </button>
        </div>

        {/* Mode toggle */}
        <div className="flex gap-1 p-1 bg-[var(--bg-tertiary)]/50 rounded-lg">
          <button
            onClick={() => setSearchMode('text')}
            className={`flex-1 flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${
              searchMode === 'text' ? 'bg-[var(--accent)]/15 text-[var(--accent)]' : 'text-gray-400'
            }`}
          >
            <Search className="w-3.5 h-3.5" />
            Search by Text
          </button>
          <button
            onClick={() => setSearchMode('proximity')}
            className={`flex-1 flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${
              searchMode === 'proximity' ? 'bg-[var(--accent)]/15 text-[var(--accent)]' : 'text-gray-400'
            }`}
          >
            <MapPin className="w-3.5 h-3.5" />
            Search by Location
          </button>
        </div>

        {/* Search inputs */}
        {searchMode === 'text' ? (
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
            <input
              type="text"
              value={query}
              onChange={e => setQuery(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && search()}
              aria-label="Search F/R number, locality, surveyor..."
              className="w-full h-10 pl-9 pr-3 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
            />
          </div>
        ) : (
          <div className="grid grid-cols-3 gap-2">
            <div>
              <label className="block text-[9px] text-gray-500 uppercase mb-0.5" htmlFor="easting">Easting</label>
              <input id="easting" type="number" value={easting} onChange={e => setEasting(e.target.value)} placeholder="534850" className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono" />
            </div>
            <div>
              <label className="block text-[9px] text-gray-500 uppercase mb-0.5" htmlFor="northing">Northing</label>
              <input id="northing" type="number" value={northing} onChange={e => setNorthing(e.target.value)} placeholder="9574220" className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono" />
            </div>
            <div>
              <label className="block text-[9px] text-gray-500 uppercase mb-0.5" htmlFor="radius-m">Radius (m)</label>
              <input id="radius-m" aria-label="Radius (m)" type="number" value={radius} onChange={e => setRadius(e.target.value)} className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono" />
            </div>
          </div>
        )}

        <button
          onClick={search}
          disabled={loading}
          className="w-full flex items-center justify-center gap-2 h-9 rounded-lg bg-[var(--accent)] text-black text-sm font-semibold hover:bg-[var(--accent-dim)] disabled:opacity-50"
        >
          {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4" />}
          Search Records
        </button>
      </div>

      {/* Add form */}
      {showAddForm && (
        <AddRecordForm
          onClose={() => setShowAddForm(false)}
          onAdded={() => { setShowAddForm(false); search() }}
        />
      )}

      {/* Error */}
      {error && (
        <div className="p-3 rounded-lg bg-red-500/5 border border-red-500/20 text-xs text-red-400">{error}</div>
      )}

      {/* Results */}
      <div className="card p-4">
        {loading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="w-6 h-6 text-gray-500 animate-spin" />
          </div>
        ) : records.length === 0 ? (
          <div className="text-center py-8">
            <FileText className="w-8 h-8 text-gray-600 mx-auto mb-2" />
            <p className="text-sm text-gray-500">No field records found</p>
            <p className="text-[10px] text-gray-600 mt-1">
              Try a different search or contribute a record to the vault
            </p>
          </div>
        ) : (
          <>
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-medium text-[var(--text-primary)]">
                {records.length} record{records.length !== 1 ? 's' : ''} found
              </span>
            </div>
            {records.length > 30 ? (
              <VirtualList
                items={records}
                itemHeight={88}
                height={400}
                renderItem={(record) => (
                  <div className="p-1">
                    <div className="flex items-start gap-3 p-2 rounded-lg border border-[var(--border-color)] hover:border-[var(--accent)]/30 transition-colors">
                      <div className="shrink-0 w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
                        <FileText className="w-3.5 h-3.5 text-[var(--accent)]" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="text-xs font-medium font-mono text-[var(--text-primary)]">{record.fr_number}</span>
                          {record.is_verified && <CheckCircle2 className="w-3 h-3 text-emerald-400" />}
                          {record.distance_m != null && (
                            <span className="text-[9px] text-[var(--accent)] font-medium">
                              {record.distance_m < 1000 ? `${record.distance_m.toFixed(0)}m away` : `${(record.distance_m / 1000).toFixed(1)}km away`}
                            </span>
                          )}
                        </div>
                        {record.locality && <div className="text-[10px] text-gray-500 mt-0.5">{record.county ? `${record.county} — ` : ''}{record.locality}</div>}
                        <div className="flex items-center gap-3 mt-1 text-[9px] text-gray-600">
                          {record.survey_year && <span>{record.survey_year}</span>}
                          {record.surveyor_name && <span>{record.surveyor_name}</span>}
                        </div>
                      </div>
                      <ChevronRight className="w-3.5 h-3.5 text-gray-600 shrink-0" />
                    </div>
                  </div>
                )}
              />
            ) : (
            <div className="space-y-2">
              {records.map(record => (
                <div
                  key={record.id}
                  className="flex items-start gap-3 p-3 rounded-lg border border-[var(--border-color)] hover:border-[var(--accent)]/30 transition-colors"
                >
                  <div className="shrink-0 w-9 h-9 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
                    <FileText className="w-4 h-4 text-[var(--accent)]" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className="text-sm font-medium font-mono text-[var(--text-primary)]">
                        {record.fr_number}
                      </span>
                      {record.is_verified && (
                        <CheckCircle2 className="w-3 h-3 text-emerald-400" />
                      )}
                      {record.distance_m != null && (
                        <span className="text-[9px] text-[var(--accent)] font-medium">
                          {record.distance_m < 1000
                            ? `${record.distance_m.toFixed(0)}m away`
                            : `${(record.distance_m / 1000).toFixed(1)}km away`}
                        </span>
                      )}
                    </div>
                    {record.locality && (
                      <div className="flex items-center gap-1 text-[10px] text-gray-500 mt-0.5">
                        <MapPin className="w-2.5 h-2.5" />
                        {record.county ? `${record.county} — ` : ''}{record.locality}
                      </div>
                    )}
                    <div className="flex items-center gap-3 mt-1 text-[9px] text-gray-600">
                      {record.survey_year && (
                        <span className="flex items-center gap-0.5">
                          <Calendar className="w-2.5 h-2.5" />
                          {record.survey_year}
                        </span>
                      )}
                      {record.surveyor_name && (
                        <span className="flex items-center gap-0.5">
                          <User className="w-2.5 h-2.5" />
                          {record.surveyor_name}
                        </span>
                      )}
                    </div>
                    {record.parcel_numbers && record.parcel_numbers.length > 0 && (
                      <div className="flex items-center gap-1 mt-1 flex-wrap">
                        {record.parcel_numbers.slice(0, 3).map((pn, i) => (
                          <span key={`${pn}-${i}`} className="text-[8px] px-1 py-0.5 rounded bg-white/[0.04] text-gray-400 font-mono">
                            {pn}
                          </span>
                        ))}
                        {record.parcel_numbers.length > 3 && (
                          <span className="text-[8px] text-gray-600">+{record.parcel_numbers.length - 3} more</span>
                        )}
                      </div>
                    )}
                    {record.description && (
                      <p className="text-[10px] text-gray-600 mt-1">{record.description}</p>
                    )}
                  </div>
                  <ChevronRight className="w-4 h-4 text-gray-600 shrink-0" />
                </div>
              ))}
            </div>
            )}
          </>
        )}
      </div>

      {/* Info */}
      <div className="flex items-start gap-2 p-2.5 rounded-lg bg-blue-500/5 border border-blue-500/10">
        <FileText className="w-3 h-3 text-blue-400 shrink-0 mt-0.5" />
        <p className="text-[10px] text-blue-400/70 leading-relaxed">
          The F/R Index Vault is a crowdsourced spatial archive of historic survey field records.
          Search by area to find old F/R numbers, bearings, and reference markers used in past surveys.
          Contribute records you possess to help the surveying community save archival research time.
        </p>
      </div>
    </div>
  )
}

// ─── Add Record Form ─────────────────────────────────────────────

function AddRecordForm({ onClose, onAdded }: { onClose: () => void; onAdded: () => void }) {
  const [frNumber, setFrNumber] = useState('')
  const [easting, setEasting] = useState('')
  const [northing, setNorthing] = useState('')
  const [county, setCounty] = useState('')
  const [locality, setLocality] = useState('')
  const [surveyYear, setSurveyYear] = useState('')
  const [surveyorName, setSurveyorName] = useState('')
  const [description, setDescription] = useState('')
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const handleSave = useCallback(async () => {
    setSaving(true)
    setError(null)
    try {
      const res = await fetch('/api/field-records', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          frNumber, easting: parseFloat(easting), northing: parseFloat(northing),
          county, locality, surveyYear: surveyYear ? parseInt(surveyYear) : null,
          surveyorName, description,
        }),
      })
      if (!res.ok) {
        const data = await res.json() as { error?: string }
        throw new Error(data.error || 'Failed')
      }
      onAdded()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed')
    } finally {
      setSaving(false)
    }
  }, [frNumber, easting, northing, county, locality, surveyYear, surveyorName, description, onAdded])

  return (
    <div className="card p-4 space-y-3">
      <div className="flex items-center justify-between">
        <span className="text-xs font-semibold text-[var(--text-primary)]">Contribute F/R Record</span>
        <button onClick={onClose} className="text-gray-400"><X className="w-3.5 h-3.5" /></button>
      </div>
      <div className="grid grid-cols-2 gap-2">
        <div>
          <label className="block text-[9px] text-gray-500 uppercase mb-0.5" htmlFor="f-r-number">F/R Number *</label>
          <input id="f-r-number" type="text" value={frNumber} onChange={e => setFrNumber(e.target.value)} placeholder="FR/123/456" className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white font-mono" />
        </div>
        <div>
          <label className="block text-[9px] text-gray-500 uppercase mb-0.5" htmlFor="survey-year">Survey Year</label>
          <input id="survey-year" type="number" value={surveyYear} onChange={e => setSurveyYear(e.target.value)} placeholder="1995" className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white font-mono" />
        </div>
      </div>
      <div className="grid grid-cols-2 gap-2">
        <div>
          <label className="block text-[9px] text-gray-500 uppercase mb-0.5" htmlFor="easting-2">Easting *</label>
          <input id="easting-2" type="number" value={easting} onChange={e => setEasting(e.target.value)} placeholder="534850" className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white font-mono" />
        </div>
        <div>
          <label className="block text-[9px] text-gray-500 uppercase mb-0.5" htmlFor="northing-2">Northing *</label>
          <input id="northing-2" type="number" value={northing} onChange={e => setNorthing(e.target.value)} placeholder="9574220" className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white font-mono" />
        </div>
      </div>
      <input type="text" value={county} onChange={e => setCounty(e.target.value)} placeholder="County" className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white" />
      <input type="text" value={locality} onChange={e => setLocality(e.target.value)} placeholder="Locality" className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white" />
      <input type="text" value={surveyorName} onChange={e => setSurveyorName(e.target.value)} placeholder="Original Surveyor" className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white" />
      <textarea value={description} onChange={e => setDescription(e.target.value)} placeholder="Description (bearings, tie points, reference markers)..." rows={2} className="w-full px-2 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white resize-none" />
      {error && <p className="text-xs text-red-400">{error}</p>}
      <button onClick={handleSave} disabled={saving || !frNumber || !easting || !northing} className="w-full h-8 rounded bg-[var(--accent)] text-black text-xs font-semibold disabled:opacity-40">
        {saving ? 'Saving...' : 'Contribute to Vault'}
      </button>
    </div>
  )
}

'use client'

/**
 * GCPOptimizerPanel — Drone GCP planning and validation
 *
 * Features:
 * - Enter project area dimensions
 * - Auto-generate optimal GCP placement
 * - Validation checklist
 * - Export for Pix4D / WebODM
 * - Track GCP survey status
 */

import { useState, useCallback, useMemo } from 'react'
import {
  Drone, MapPin, CheckCircle2, AlertTriangle, Download,
  Plus, Loader2, Camera,
} from 'lucide-react'
import {
  generateGCPPlan,
  generateValidationChecklist,
  exportForPix4D,
  exportForWebODM,
  DEFAULT_UTM_ZONE,
  DEFAULT_HEMISPHERE,
  type GCPPlan,
  type GCPPoint,
} from '@/lib/engine/gcpOptimizer'

export function GCPOptimizerPanel() {
  const [areaHa, setAreaHa] = useState('')
  const [utmZone, setUtmZone] = useState<number>(DEFAULT_UTM_ZONE)
  const [hemisphere, setHemisphere] = useState<'N' | 'S'>(DEFAULT_HEMISPHERE)
  const [plan, setPlan] = useState<GCPPlan | null>(null)
  const [generating, setGenerating] = useState(false)

  const handleGenerate = useCallback(() => {
    const ha = parseFloat(areaHa)
    if (!isFinite(ha) || ha <= 0) return

    setGenerating(true)
    try {
      // Generate a simple rectangular boundary
      const sideM = Math.sqrt(ha * 10000)
      const boundary = [
        { easting: 0, northing: 0 },
        { easting: sideM, northing: 0 },
        { easting: sideM, northing: sideM },
        { easting: 0, northing: sideM },
      ]
      const newPlan = generateGCPPlan({ boundary, areaHa: ha })
      setPlan(newPlan)
    } finally {
      setGenerating(false)
    }
  }, [areaHa])

  const checklist = useMemo(() => {
    if (!plan) return []
    return generateValidationChecklist(plan)
  }, [plan])

  const handleExport = useCallback((format: 'pix4d' | 'webodm') => {
    if (!plan) return
    const csv = format === 'pix4d'
      ? exportForPix4D(plan.gcps, utmZone, hemisphere)
      : exportForWebODM(plan.gcps, utmZone, hemisphere)
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `gcp-export-${format}.csv`
    a.click()
    URL.revokeObjectURL(url)
  }, [plan, utmZone, hemisphere])

  return (
    <div className="space-y-4">
      {/* Area input */}
      <div className="card p-4">
        <div className="block text-[9px] text-gray-400 uppercase tracking-wider mb-1">Project Area (hectares)</div>
        <div className="flex items-center gap-2">
          <input
            type="number"
            step="0.01"
            value={areaHa}
            onChange={e => setAreaHa(e.target.value)}
            aria-label="Project area in hectares" placeholder="10.5"
            className="flex-1 h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-[var(--text-primary)] font-mono"
          />
          <button
            onClick={handleGenerate}
            disabled={!areaHa || generating}
            className="flex items-center gap-1.5 px-4 h-9 rounded-lg bg-[var(--accent)] text-black text-sm font-semibold disabled:opacity-40"
          >
            {generating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Drone className="w-4 h-4" />}
            Plan GCPs
          </button>
        </div>
        {/* UTM zone + hemisphere for export correctness (P0-1) */}
        <div className="flex items-center gap-2 mt-2">
          <label className="text-[9px] text-gray-400 uppercase tracking-wider" htmlFor="utm-zone">UTM Zone</label>
          <input
             id="utm-zone" type="number"
            min={1}
            max={60}
            value={utmZone}
            onChange={e => {
              const z = parseInt(e.target.value, 10)
              if (z >= 1 && z <= 60) setUtmZone(z)
            }}
            aria-label="UTM zone (1 to 60)"
            className="w-16 h-7 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono text-center"
          />
          <div className="flex rounded-lg border border-[var(--border-color)] overflow-hidden">
            {(['N', 'S'] as const).map(h => (
              <button
                key={h}
                onClick={() => setHemisphere(h)}
                className={`px-3 h-7 text-xs font-mono ${hemisphere === h ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-gray-400'}`}
                aria-pressed={hemisphere === h}
                aria-label={`Hemisphere ${h === 'N' ? 'North' : 'South'}`}
              >
                {h}
              </button>
            ))}
          </div>
          <span className="text-[9px] text-gray-400">Used for Pix4D/WebODM WGS84 export</span>
        </div>
      </div>

      {/* Plan results */}
      {plan && (
        <>
          {/* Summary */}
          <div className="grid grid-cols-3 gap-2">
            <div className="p-2 rounded-lg bg-[var(--bg-tertiary)]/50 text-center">
              <div className="text-lg font-bold text-[var(--accent)]">{plan.totalGCPs}</div>
              <div className="text-[9px] text-gray-400 uppercase">GCPs</div>
            </div>
            <div className="p-2 rounded-lg bg-[var(--bg-tertiary)]/50 text-center">
              <div className="text-lg font-bold text-emerald-400">±{plan.estimatedAccuracy}cm</div>
              <div className="text-[9px] text-gray-400 uppercase">Est. Accuracy</div>
            </div>
            <div className="p-2 rounded-lg bg-[var(--bg-tertiary)]/50 text-center">
              <div className="text-lg font-bold text-gray-300">{plan.coveragePercent.toFixed(0)}%</div>
              <div className="text-[9px] text-gray-400 uppercase">Coverage</div>
            </div>
          </div>

          {/* GCP list */}
          <div className="card p-4">
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-semibold text-[var(--text-primary)]">GCP Placement</span>
              <div className="flex items-center gap-1">
                <button onClick={() => handleExport('pix4d')} className="flex items-center gap-1 px-2 h-7 rounded bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-[10px] text-gray-400">
                  <Download className="w-3 h-3" /> Pix4D
                </button>
                <button onClick={() => handleExport('webodm')} className="flex items-center gap-1 px-2 h-7 rounded bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-[10px] text-gray-400">
                  <Download className="w-3 h-3" /> WebODM
                </button>
              </div>
            </div>
            <div className="space-y-1.5">
              {plan.gcps.map(gcp => (
                <div key={gcp.id} className="flex items-center gap-3 p-2 rounded-lg bg-white/[0.02] border border-[var(--border-color)]">
                  <div className={`shrink-0 w-7 h-7 rounded flex items-center justify-center ${
                    gcp.status === 'validated' ? 'bg-emerald-500/10' :
                    gcp.status === 'surveyed' ? 'bg-blue-500/10' : 'bg-gray-500/10'
                  }`}>
                    <MapPin className={`w-3.5 h-3.5 ${
                      gcp.status === 'validated' ? 'text-emerald-400' :
                      gcp.status === 'surveyed' ? 'text-blue-400' : 'text-gray-400'
                    }`} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="text-xs font-mono text-[var(--text-primary)]">{gcp.name}</div>
                    <div className="text-[9px] text-gray-400 font-mono">E:{gcp.easting.toFixed(1)} N:{gcp.northing.toFixed(1)}</div>
                  </div>
                  <div className="flex items-center gap-1.5">
                    {gcp.rtkFixed && <CheckCircle2 className="w-3 h-3 text-emerald-400" />}
                    {gcp.photoCaptured && <Camera className="w-3 h-3 text-blue-400" />}
                    <span className={`text-[9px] px-1.5 py-0.5 rounded ${
                      gcp.status === 'validated' ? 'bg-emerald-500/10 text-emerald-400' :
                      gcp.status === 'surveyed' ? 'bg-blue-500/10 text-blue-400' :
                      'bg-gray-500/10 text-gray-400'
                    }`}>{gcp.status}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Validation checklist */}
          <div className="card p-4">
            <span className="text-xs font-semibold text-[var(--text-primary)] mb-2 block">Field Validation Checklist</span>
            <div className="space-y-1.5">
              {checklist.map((item, i) => (
                <div key={`${item}-${i}`} className="flex items-center gap-2 p-2 rounded-lg bg-white/[0.02]">
                  {item.completed ? (
                    <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0" />
                  ) : (
                    <AlertTriangle className="w-4 h-4 text-amber-400 shrink-0" />
                  )}
                  <span className={`flex-1 text-xs ${item.completed ? 'text-emerald-400' : 'text-gray-400'}`}>{item.item}</span>
                  <span className="text-[9px] text-gray-400">{item.gcpsCompleted}/{item.totalGCPs}</span>
                </div>
              ))}
            </div>
          </div>
        </>
      )}
    </div>
  )
}

'use client'

/**
 * GNSSQualityReport — Comprehensive GNSS quality monitoring
 *
 * Enhances the existing GPSGuardrail with full quality metrics:
 * - Fix quality (RTK Fixed/Float, DGPS, GPS, No Fix)
 * - Satellites tracked (GPS, GLONASS, Galileo, BeiDou)
 * - PDOP (Position Dilution of Precision)
 * - HDOP (Horizontal DOP)
 * - VDOP (Vertical DOP)
 * - Base station distance (for RTK)
 * - Age of differential correction
 *
 * Generates a QA/QC report for ArdhiSasa submission compliance.
 * Warns if PDOP > 4.0 or fix is RTK Float (not acceptable for cadastral).
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import {
  Satellite, AlertTriangle, CheckCircle2, Activity,
  Download, RefreshCw,
} from 'lucide-react'

interface GNSSQuality {
  fixQuality: 'rtk_fixed' | 'rtk_float' | 'dgps' | 'gps' | 'none'
  satellites: number
  satellitesGPS: number
  satellitesGLONASS: number
  satellitesGalileo: number
  satellitesBeiDou: number
  pdop: number
  hdop: number
  vdop: number
  baseDistanceKm: number | null
  correctionAge: number | null  // seconds
  latitude: number
  longitude: number
  altitude: number
  timestamp: Date
}

interface QualityCheck {
  metric: string
  value: string
  threshold: string
  status: 'pass' | 'warning' | 'fail'
  description: string
}

const FIX_QUALITY_LABELS: Record<string, { label: string; color: string; icon: string }> = {
  rtk_fixed: { label: 'RTK Fixed', color: 'text-emerald-400', icon: '' },
  rtk_float: { label: 'RTK Float', color: 'text-amber-400', icon: '' },
  dgps: { label: 'DGPS', color: 'text-blue-400', icon: '' },
  gps: { label: 'GPS Only', color: 'text-amber-400', icon: '[Y]' },
  none: { label: 'No Fix', color: 'text-red-400', icon: '[R]' },
}

export function GNSSQualityReport({ externalPosition }: {
  /** When provided (from GNSS rover), uses NMEA data instead of browser geolocation */
  externalPosition?: { lat: number; lng: number; altitude: number; hdop: number; satellites: number; fixType: string; quality: number } | null
}) {
  const [quality, setQuality] = useState<GNSSQuality | null>(null)
  const [history, setHistory] = useState<GNSSQuality[]>([])
  const [watching, setWatching] = useState(false)
  const watchIdRef = useRef<number | null>(null)

  // Use external rover data when available
  useEffect(() => {
    if (!externalPosition) return

    const q: GNSSQuality = {
      fixQuality: externalPosition.fixType as GNSSQuality['fixQuality'] || (externalPosition.quality >= 4 ? 'rtk_fixed' : externalPosition.quality >= 2 ? 'dgps' : 'gps'),
      satellites: externalPosition.satellites || 0,
      satellitesGPS: 0,
      satellitesGLONASS: 0,
      satellitesGalileo: 0,
      satellitesBeiDou: 0,
      pdop: 0, // Not available from NMEA GGA
      hdop: externalPosition.hdop || 0,
      vdop: 0, // Not available from NMEA GGA
      baseDistanceKm: null,
      correctionAge: null,
      latitude: externalPosition.lat,
      longitude: externalPosition.lng,
      altitude: externalPosition.altitude,
      timestamp: new Date(),
    }
    setQuality(q)
    setHistory(prev => [...prev.slice(-99), q])
  }, [externalPosition])

  const startWatch = useCallback(() => {
    if (watchIdRef.current != null) return // Already watching
    if (externalPosition) return // Using external data, don't start browser GPS
    setWatching(true)

    if (!('geolocation' in navigator)) {
      setWatching(false)
      return
    }

    watchIdRef.current = navigator.geolocation.watchPosition(
      (pos) => {
        const q: GNSSQuality = {
          fixQuality: pos.coords.accuracy < 0.1 ? 'rtk_fixed' :
                       pos.coords.accuracy < 1 ? 'rtk_float' :
                       pos.coords.accuracy < 5 ? 'dgps' :
                       pos.coords.accuracy < 15 ? 'gps' : 'none',
          satellites: 0,
          satellitesGPS: 0,
          satellitesGLONASS: 0,
          satellitesGalileo: 0,
          satellitesBeiDou: 0,
          pdop: 0,
          hdop: pos.coords.accuracy || 99,
          vdop: pos.coords.altitudeAccuracy || 99,
          baseDistanceKm: null,
          correctionAge: null,
          latitude: pos.coords.latitude,
          longitude: pos.coords.longitude,
          altitude: pos.coords.altitude || 0,
          timestamp: new Date(pos.timestamp),
        }
        setQuality(q)
        setHistory(prev => [...prev.slice(-99), q])
      },
      () => {
        setQuality(null)
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 1000 }
    )
  }, [externalPosition]) // AUDIT FIX: Removed `watching` from deps — caused infinite loop

  const stopWatch = useCallback(() => {
    if (watchIdRef.current != null) {
      navigator.geolocation.clearWatch(watchIdRef.current)
      watchIdRef.current = null
    }
    setWatching(false)
  }, [])

  // AUDIT FIX: Only start on mount, don't re-run when startWatch changes
  useEffect(() => {
    startWatch()
    return () => stopWatch()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // Quality checks
  const checks: QualityCheck[] = quality ? [
    {
      metric: 'Fix Quality',
      value: FIX_QUALITY_LABELS[quality.fixQuality].label,
      threshold: 'RTK Fixed (cadastral), DGPS (topo)',
      status: quality.fixQuality === 'rtk_fixed' ? 'pass' :
              quality.fixQuality === 'rtk_float' ? 'warning' :
              quality.fixQuality === 'dgps' ? 'warning' : 'fail',
      description: 'RTK Fixed is required for cadastral surveys. RTK Float and DGPS are acceptable for topographic only.',
    },
    {
      metric: 'PDOP',
      value: quality.pdop > 0 ? quality.pdop.toFixed(2) : 'N/A',
      threshold: '< 4.0 (good), < 2.0 (excellent)',
      status: quality.pdop === 0 ? 'warning' :
              quality.pdop < 2.0 ? 'pass' :
              quality.pdop < 4.0 ? 'pass' : 'fail',
      description: 'Position Dilution of Precision. Lower is better. >4.0 means poor satellite geometry.',
    },
    {
      metric: 'HDOP',
      value: quality.hdop > 0 ? quality.hdop.toFixed(2) : 'N/A',
      threshold: '< 2.0 (good), < 1.0 (excellent)',
      status: quality.hdop === 0 ? 'warning' :
              quality.hdop < 1.0 ? 'pass' :
              quality.hdop < 2.0 ? 'pass' : 'warning',
      description: 'Horizontal Dilution of Precision. Affects Easting/Northing accuracy.',
    },
    {
      metric: 'VDOP',
      value: quality.vdop > 0 ? quality.vdop.toFixed(2) : 'N/A',
      threshold: '< 3.0 (good), < 2.0 (excellent)',
      status: quality.vdop === 0 ? 'warning' :
              quality.vdop < 2.0 ? 'pass' :
              quality.vdop < 3.0 ? 'pass' : 'warning',
      description: 'Vertical Dilution of Precision. Affects elevation accuracy.',
    },
    {
      metric: 'Satellites',
      value: quality.satellites > 0 ? String(quality.satellites) : 'N/A',
      threshold: '≥ 6 (minimum), ≥ 10 (good), ≥ 15 (excellent)',
      status: quality.satellites === 0 ? 'warning' :
              quality.satellites >= 15 ? 'pass' :
              quality.satellites >= 10 ? 'pass' :
              quality.satellites >= 6 ? 'warning' : 'fail',
      description: 'Number of satellites used in position calculation. More satellites = better geometry.',
    },
    {
      metric: 'Base Distance',
      value: quality.baseDistanceKm != null ? `${quality.baseDistanceKm.toFixed(1)} km` : 'N/A',
      threshold: '< 10 km (optimal), < 30 km (acceptable)',
      status: quality.baseDistanceKm == null ? 'warning' :
              quality.baseDistanceKm < 10 ? 'pass' :
              quality.baseDistanceKm < 30 ? 'pass' : 'warning',
      description: 'Distance to base station. RTK accuracy degrades beyond 30km.',
    },
    {
      metric: 'Correction Age',
      value: quality.correctionAge != null ? `${quality.correctionAge.toFixed(1)}s` : 'N/A',
      threshold: '< 5s (good), < 10s (acceptable)',
      status: quality.correctionAge == null ? 'warning' :
              quality.correctionAge < 5 ? 'pass' :
              quality.correctionAge < 10 ? 'pass' : 'fail',
      description: 'Age of differential correction. Stale corrections indicate connection issues.',
    },
  ] : []

  const overallStatus = checks.length > 0
    ? checks.some(c => c.status === 'fail') ? 'fail' :
      checks.some(c => c.status === 'warning') ? 'warning' : 'pass'
    : 'pending'

  const handleExport = useCallback(() => {
    if (!quality) return

    const report = {
      format: 'metardu-gnss-quality-v1',
      exportedAt: new Date().toISOString(),
      overallStatus,
      checks: checks.map(c => ({
        metric: c.metric,
        value: c.value,
        threshold: c.threshold,
        status: c.status,
        description: c.description,
      })),
      rawQuality: {
        fixQuality: quality.fixQuality,
        satellites: quality.satellites,
        pdop: quality.pdop,
        hdop: quality.hdop,
        vdop: quality.vdop,
        baseDistanceKm: quality.baseDistanceKm,
        correctionAge: quality.correctionAge,
        position: {
          latitude: quality.latitude,
          longitude: quality.longitude,
          altitude: quality.altitude,
        },
        timestamp: quality.timestamp.toISOString(),
      },
      history: history.slice(-20).map(h => ({
        timestamp: h.timestamp.toISOString(),
        fixQuality: h.fixQuality,
        hdop: h.hdop,
        satellites: h.satellites,
      })),
    }

    const json = JSON.stringify(report, null, 2)
    const blob = new Blob([json], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `gnss-quality-${Date.now()}.json`
    a.click()
    URL.revokeObjectURL(url)
  }, [quality, checks, overallStatus, history])

  return (
    <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--border-color)]">
        <div className="flex items-center gap-2">
          <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${
            overallStatus === 'pass' ? 'bg-emerald-500/10' :
            overallStatus === 'warning' ? 'bg-amber-500/10' :
            overallStatus === 'fail' ? 'bg-red-500/10' : 'bg-gray-500/10'
          }`}>
            <Satellite className={`w-4 h-4 ${
              overallStatus === 'pass' ? 'text-emerald-400' :
              overallStatus === 'warning' ? 'text-amber-400' :
              overallStatus === 'fail' ? 'text-red-400' : 'text-gray-400'
            }`} />
          </div>
          <div>
            <span className="text-sm font-semibold text-[var(--text-primary)]">GNSS Quality Report</span>
            <p className="text-[10px] text-gray-500">QA/QC for ArdhiSasa submission compliance</p>
          </div>
        </div>
        <div className="flex items-center gap-1.5">
          <button
            onClick={handleExport}
            disabled={!quality}
            className="flex items-center gap-1 px-2 h-7 rounded bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-[10px] text-gray-400 hover:text-gray-200 disabled:opacity-30"
          >
            <Download className="w-3 h-3" />
            Export
          </button>
          <button
            onClick={watching ? stopWatch : startWatch}
            className="flex items-center gap-1 px-2 h-7 rounded bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-[10px] text-gray-400 hover:text-gray-200"
          >
            <RefreshCw className={`w-3 h-3 ${watching ? 'animate-spin' : ''}`} />
            {watching ? 'Stop' : 'Start'}
          </button>
        </div>
      </div>

      {/* Overall status */}
      {quality && (
        <div className={`px-4 py-2 border-b border-[var(--border-color)] ${
          overallStatus === 'pass' ? 'bg-emerald-500/5' :
          overallStatus === 'warning' ? 'bg-amber-500/5' :
          'bg-red-500/5'
        }`}>
          <div className="flex items-center gap-2">
            {overallStatus === 'pass' && <CheckCircle2 className="w-4 h-4 text-emerald-400" />}
            {overallStatus === 'warning' && <AlertTriangle className="w-4 h-4 text-amber-400" />}
            {overallStatus === 'fail' && <AlertTriangle className="w-4 h-4 text-red-400" />}
            <span className={`text-xs font-semibold ${
              overallStatus === 'pass' ? 'text-emerald-400' :
              overallStatus === 'warning' ? 'text-amber-400' : 'text-red-400'
            }`}>
              {overallStatus === 'pass' ? 'ACCEPTABLE FOR SUBMISSION' :
               overallStatus === 'warning' ? 'ACCEPTABLE WITH CAUTION' :
               'NOT ACCEPTABLE — FIX BEFORE SUBMISSION'}
            </span>
          </div>
        </div>
      )}

      {/* Checks list */}
      <div className="p-4 space-y-2">
        {!quality ? (
          <div className="flex flex-col items-center py-6">
            <Activity className="w-8 h-8 text-gray-600 mb-2" />
            <p className="text-xs text-gray-500">Waiting for GNSS data...</p>
          </div>
        ) : (
          checks.map((check, i) => (
            <div
              key={`${check}-${i}`}
              className={`flex items-start gap-3 p-2.5 rounded-lg border ${
                check.status === 'pass' ? 'bg-emerald-500/5 border-emerald-500/20' :
                check.status === 'warning' ? 'bg-amber-500/5 border-amber-500/20' :
                'bg-red-500/5 border-red-500/20'
              }`}
            >
              <div className={`shrink-0 w-5 h-5 rounded flex items-center justify-center ${
                check.status === 'pass' ? 'bg-emerald-500/10' :
                check.status === 'warning' ? 'bg-amber-500/10' :
                'bg-red-500/10'
              }`}>
                {check.status === 'pass' ? <CheckCircle2 className="w-3 h-3 text-emerald-400" /> :
                 <AlertTriangle className={`w-3 h-3 ${check.status === 'warning' ? 'text-amber-400' : 'text-red-400'}`} />}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between">
                  <span className="text-[11px] font-medium text-[var(--text-primary)]">{check.metric}</span>
                  <span className={`text-[11px] font-mono font-bold ${
                    check.status === 'pass' ? 'text-emerald-400' :
                    check.status === 'warning' ? 'text-amber-400' : 'text-red-400'
                  }`}>
                    {check.value}
                  </span>
                </div>
                <p className="text-[9px] text-gray-500 mt-0.5">Threshold: {check.threshold}</p>
                <p className="text-[9px] text-gray-600 mt-0.5">{check.description}</p>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Live position */}
      {quality && (
        <div className="px-4 py-2 border-t border-[var(--border-color)] bg-[var(--bg-tertiary)]/30">
          <div className="grid grid-cols-3 gap-2 text-[10px]">
            <div>
              <span className="text-gray-600">Lat:</span>
              <span className="text-gray-300 font-mono ml-1">{quality.latitude.toFixed(8)}</span>
            </div>
            <div>
              <span className="text-gray-600">Lng:</span>
              <span className="text-gray-300 font-mono ml-1">{quality.longitude.toFixed(8)}</span>
            </div>
            <div>
              <span className="text-gray-600">Alt:</span>
              <span className="text-gray-300 font-mono ml-1">{quality.altitude.toFixed(2)}m</span>
            </div>
          </div>
          <div className="text-[8px] text-gray-600 mt-1">
            Updated: {quality.timestamp.toLocaleTimeString()} · History: {history.length} readings
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

/**
 * NeighborConsensusForm — Geofenced boundary sign-off
 *
 * Lets surveyors capture formal consensus from adjoining property owners:
 * - Neighbor name, National ID, phone, parcel number
 * - Signature on touchscreen canvas
 * - GPS geofence verification (must be within 5m of beacon)
 * - Cryptographic sealing of the consensus record
 *
 * The signature pad is locked until GPS verifies the surveyor is on-site.
 */

import { useState, useCallback, useRef, useEffect } from 'react'
import {
  User, Phone, MapPin, PenTool, CheckCircle2, AlertTriangle,
  Loader2, Lock, ShieldCheck, X,
} from 'lucide-react'
import {
  createConsensusRecord,
  verifyGeofence,
  GEOFENCE_RADIUS_M,
  type NeighborConsensusRecord,
} from '@/lib/survey/neighborConsensus'

interface NeighborConsensusFormProps {
  beaconId: string
  beaconEasting: number
  beaconNorthing: number
  surveyorId: string
  surveyorLicense: string
  onConsensusCaptured?: (record: NeighborConsensusRecord) => void
  onClose?: () => void
  /** T1.5 FIX (2026-07-09): UTM EPSG for GPS→UTM transform (default 'EPSG:21037') */
  epsg?: string
}

export function NeighborConsensusForm({
  beaconId,
  beaconEasting,
  beaconNorthing,
  surveyorId,
  surveyorLicense,
  onConsensusCaptured,
  onClose,
  epsg = 'EPSG:21037',
}: NeighborConsensusFormProps) {
  const [neighborName, setNeighborName] = useState('')
  const [neighborNationalId, setNeighborNationalId] = useState('')
  const [neighborPhone, setNeighborPhone] = useState('')
  const [neighborParcelNumber, setNeighborParcelNumber] = useState('')

  // Geofence state
  const [currentPos, setCurrentPos] = useState<{ easting: number; northing: number } | null>(null)
  const [distanceFromBeacon, setDistanceFromBeacon] = useState<number | null>(null)
  const [geofenceValid, setGeofenceValid] = useState(false)
  const [checkingLocation, setCheckingLocation] = useState(false)

  // Signature state
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [isDrawing, setIsDrawing] = useState(false)
  const [hasSignature, setHasSignature] = useState(false)

  // Saving state
  const [saving, setSaving] = useState(false)
  const [savedRecord, setSavedRecord] = useState<NeighborConsensusRecord | null>(null)
  const [error, setError] = useState<string | null>(null)

  // Check GPS location for geofence
  const checkLocation = useCallback(async () => {
    setCheckingLocation(true)
    if (!('geolocation' in navigator)) {
      setError('Geolocation not supported')
      setCheckingLocation(false)
      return
    }

    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        try {
          const { transform } = await import('ol/proj')
          const [e, n] = transform([pos.coords.longitude, pos.coords.latitude], 'EPSG:4326', epsg) as [number, number]
          const position = { easting: e, northing: n }
          setCurrentPos(position)

          const geofence = verifyGeofence(beaconEasting, beaconNorthing, e, n)
          setDistanceFromBeacon(geofence.distance)
          setGeofenceValid(geofence.isValid)
        } catch {
          setError('Failed to transform coordinates')
        }
        setCheckingLocation(false)
      },
      () => {
        setError('Failed to get GPS position')
        setCheckingLocation(false)
      },
      { enableHighAccuracy: true, timeout: 10000 },
    )
  }, [beaconEasting, beaconNorthing])

  // Auto-check location on mount
  useEffect(() => {
    checkLocation()
  }, [checkLocation])

  // Signature pad handlers
  const startDrawing = useCallback((e: React.MouseEvent<HTMLCanvasElement> | React.TouchEvent<HTMLCanvasElement>) => {
    if (!geofenceValid) return
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    setIsDrawing(true)
    const rect = canvas.getBoundingClientRect()
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY
    ctx.beginPath()
    ctx.moveTo(clientX - rect.left, clientY - rect.top)
  }, [geofenceValid])

  const draw = useCallback((e: React.MouseEvent<HTMLCanvasElement> | React.TouchEvent<HTMLCanvasElement>) => {
    if (!isDrawing) return
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    const rect = canvas.getBoundingClientRect()
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY
    ctx.lineTo(clientX - rect.left, clientY - rect.top)
    ctx.stroke()
    ctx.lineWidth = 2
    ctx.lineCap = 'round'
    ctx.strokeStyle = '#000'
    setHasSignature(true)
  }, [isDrawing])

  const stopDrawing = useCallback(() => {
    setIsDrawing(false)
  }, [])

  const clearSignature = useCallback(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    ctx.clearRect(0, 0, canvas.width, canvas.height)
    setHasSignature(false)
  }, [])

  // Save consensus
  const handleSave = useCallback(async () => {
    if (!geofenceValid) {
      setError('Must be within 5m of beacon to sign')
      return
    }
    if (!neighborName.trim() || !neighborNationalId.trim()) {
      setError('Neighbor name and National ID are required')
      return
    }
    if (!hasSignature) {
      setError('Signature is required')
      return
    }

    setSaving(true)
    setError(null)

    try {
      const canvas = canvasRef.current
      const signatureData = canvas?.toDataURL('image/png') || ''

      const record = await createConsensusRecord({
        beaconId,
        beaconEasting,
        beaconNorthing,
        neighborName,
        neighborNationalId,
        neighborPhone,
        neighborParcelNumber,
        signatureData,
        signLocationEasting: currentPos?.easting || 0,
        signLocationNorthing: currentPos?.northing || 0,
        surveyorId,
        surveyorLicense,
      })

      setSavedRecord(record)
      onConsensusCaptured?.(record)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save consensus')
    } finally {
      setSaving(false)
    }
  }, [geofenceValid, neighborName, neighborNationalId, neighborPhone, neighborParcelNumber, hasSignature, beaconId, beaconEasting, beaconNorthing, currentPos, surveyorId, surveyorLicense, onConsensusCaptured])

  if (savedRecord) {
    return (
      <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/5 p-4 text-center">
        <CheckCircle2 className="w-10 h-10 text-emerald-400 mx-auto mb-3" />
        <h3 className="text-sm font-semibold text-emerald-400">Consensus Captured</h3>
        <p className="text-[10px] text-gray-500 mt-1">
          {savedRecord.neighborName} signed at {new Date(savedRecord.signedAt).toLocaleString()}
        </p>
        <p className="text-[10px] text-gray-600 mt-2">
          Distance from beacon: {savedRecord.distanceFromBeacon.toFixed(2)}m ·
          Geofence: {savedRecord.isGeofenceValid ? 'VALID' : 'INVALID'} ·
          Sealed: {savedRecord.seal ? 'YES' : 'NO'}
        </p>
        {onClose && (
          <button onClick={onClose} className="mt-3 px-4 h-8 rounded-lg bg-emerald-500/20 text-emerald-400 text-xs font-medium">
            Done
          </button>
        )}
      </div>
    )
  }

  return (
    <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--border-color)]">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
            <ShieldCheck className="w-4 h-4 text-[var(--accent)]" />
          </div>
          <div>
            <span className="text-sm font-semibold text-[var(--text-primary)]">Boundary Consensus</span>
            <p className="text-[10px] text-gray-500">Geofenced sign-off for adjoining owner</p>
          </div>
        </div>
        {onClose && (
          <button onClick={onClose} className="w-7 h-7 flex items-center justify-center rounded text-gray-400 hover:text-white">
            <X className="w-4 h-4" />
          </button>
        )}
      </div>

      <div className="p-4 space-y-3">
        {/* Geofence status */}
        <div className={`p-3 rounded-lg border ${
          geofenceValid ? 'bg-emerald-500/5 border-emerald-500/20' :
          distanceFromBeacon != null ? 'bg-red-500/5 border-red-500/20' :
          'bg-amber-500/5 border-amber-500/20'
        }`}>
          <div className="flex items-center gap-2">
            {checkingLocation ? (
              <Loader2 className="w-4 h-4 text-amber-400 animate-spin" />
            ) : geofenceValid ? (
              <CheckCircle2 className="w-4 h-4 text-emerald-400" />
            ) : (
              <AlertTriangle className={`w-4 h-4 ${distanceFromBeacon != null ? 'text-red-400' : 'text-amber-400'}`} />
            )}
            <div>
              <span className={`text-xs font-medium ${
                geofenceValid ? 'text-emerald-400' :
                distanceFromBeacon != null ? 'text-red-400' : 'text-amber-400'
              }`}>
                {checkingLocation ? 'Checking location...' :
                 geofenceValid ? 'On-site — sign-off enabled' :
                 distanceFromBeacon != null ? `${distanceFromBeacon.toFixed(1)}m from beacon (must be <${GEOFENCE_RADIUS_M}m)` :
                 'Waiting for GPS...'}
              </span>
            </div>
          </div>
          <button
            onClick={checkLocation}
            className="mt-2 text-[10px] text-gray-500 hover:text-gray-300 flex items-center gap-1"
          >
            <MapPin className="w-3 h-3" />
            Re-check location
          </button>
        </div>

        {/* Neighbor info */}
        <div className="space-y-2">
          <div>
            <label className="flex items-center gap-1 text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="neighbor-name">
              <User className="w-3 h-3" />
              Neighbor Name *
            </label>
            <input id="neighbor-name"
              type="text"
              value={neighborName}
              onChange={e => setNeighborName(e.target.value)}
              placeholder="John Doe"
              className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
            />
          </div>
          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="national-id">National ID *</label>
              <input id="national-id"
                type="text"
                value={neighborNationalId}
                onChange={e => setNeighborNationalId(e.target.value)}
                placeholder="12345678"
                className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
              />
            </div>
            <div>
              <label className="flex items-center gap-1 text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="phone">
                <Phone className="w-3 h-3" />
                Phone
              </label>
              <input id="phone"
                type="tel"
                value={neighborPhone}
                onChange={e => setNeighborPhone(e.target.value)}
                placeholder="0712 345 678"
                className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
              />
            </div>
          </div>
          <div>
            <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="neighbor-parcel-no">Neighbor Parcel No.</label>
            <input id="neighbor-parcel-no"
              type="text"
              value={neighborParcelNumber}
              onChange={e => setNeighborParcelNumber(e.target.value)}
              placeholder="LR/12345/679"
              className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
            />
          </div>
        </div>

        {/* Signature pad */}
        <div>
          <div className="flex items-center gap-1 text-[9px] text-gray-500 uppercase tracking-wider mb-1">
            <PenTool className="w-3 h-3" />
            Signature *
          </div>
          <div className={`relative ${!geofenceValid ? 'opacity-40 pointer-events-none' : ''}`}>
            <canvas
              ref={canvasRef}
              width={300}
              height={120}
              onMouseDown={startDrawing}
              onMouseMove={draw}
              onMouseUp={stopDrawing}
              onMouseLeave={stopDrawing}
              onTouchStart={startDrawing}
              onTouchMove={draw}
              onTouchEnd={stopDrawing}
              className="w-full h-[120px] bg-white rounded-lg border border-[var(--border-color)] cursor-crosshair touch-none"
            />
            {!geofenceValid && (
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="flex items-center gap-1.5 text-[10px] text-gray-500">
                  <Lock className="w-3 h-3" />
                  Move within {GEOFENCE_RADIUS_M}m of beacon to unlock
                </div>
              </div>
            )}
          </div>
          {hasSignature && geofenceValid && (
            <button
              onClick={clearSignature}
              className="mt-1 text-[9px] text-gray-500 hover:text-red-400"
            >
              Clear signature
            </button>
          )}
        </div>

        {/* Error */}
        {error && (
          <div className="flex items-start gap-2 p-2 rounded-lg bg-red-500/5 border border-red-500/20">
            <AlertTriangle className="w-3.5 h-3.5 text-red-400 shrink-0 mt-0.5" />
            <p className="text-[11px] text-red-400">{error}</p>
          </div>
        )}

        {/* Save button */}
        <button
          onClick={handleSave}
          disabled={!geofenceValid || saving || !neighborName || !neighborNationalId || !hasSignature}
          className="w-full flex items-center justify-center gap-2 h-10 rounded-lg bg-[var(--accent)] text-black text-sm font-semibold hover:bg-[var(--accent-dim)] disabled:opacity-40 disabled:cursor-not-allowed"
        >
          {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <ShieldCheck className="w-4 h-4" />}
          {saving ? 'Sealing...' : 'Capture & Seal Consensus'}
        </button>
      </div>
    </div>
  )
}

'use client'

/**
 * RealTimeQCPanel — Live quality control during field work.
 *
 * Shows:
 *   - Running closure (live misclosure as each leg is added)
 *   - Precision ratio with color coding (green/amber/red)
 *   - Setup verification checklist
 *   - Redundant observation alerts
 *   - Outlier detection results
 *
 * Wired to src/lib/survey/realTimeQC.ts
 */

import { useState, useCallback, useMemo } from 'react'
import {
  RunningClosureMonitor,
  detectRedundantObservationDiscrepancies,
  verifySetup,
  formatPrecisionIndicator,
  type Observation,
  type SurveyClass,
} from '@/lib/survey/realTimeQC'
import {
  Activity, AlertTriangle, CheckCircle2, XCircle, Gauge,
  TrendingDown, Layers, ShieldCheck,
} from 'lucide-react'

interface RealTimeQCPanelProps {
  /** Observations from the current traverse (for redundant obs detection) */
  observations?: Observation[]
  /** Current survey class */
  surveyClass?: SurveyClass
  /** Compact mode (for embedding in field book sidebar) */
  compact?: boolean
}

export function RealTimeQCPanel({
  observations = [],
  surveyClass = 'urban',
  compact = false,
}: RealTimeQCPanelProps) {
  const [monitor] = useState(() => new RunningClosureMonitor(surveyClass))
  const [legs, setLegs] = useState<Array<{ bearing: number; distance: number }>>([])
  const [setupData, setSetupData] = useState({
    instrumentHeight: 1.5,
    targetHeight: 1.5,
    temperature: 25,
    pressure: 1013,
    isControlPoint: false,
  })

  const state = monitor.getState()

  const addLeg = useCallback((bearing: number, distance: number) => {
    monitor.addLeg(bearing, distance)
    setLegs(prev => [...prev, { bearing, distance }])
  }, [monitor])

  const undoLeg = useCallback(() => {
    monitor.removeLastLeg()
    setLegs(prev => prev.slice(0, -1))
  }, [monitor])

  const reset = useCallback(() => {
    monitor.reset()
    setLegs([])
  }, [monitor])

  // Redundant observation check
  const discrepancies = useMemo(
    () => detectRedundantObservationDiscrepancies(observations),
    [observations]
  )

  // Setup verification
  const setupChecks = useMemo(
    () => verifySetup(setupData),
    [setupData]
  )

  const precisionInfo = formatPrecisionIndicator(state.precisionRatio ?? null, surveyClass)

  if (compact) {
    return (
      <div className="space-y-2">
        {/* Precision indicator */}
        <div className="flex items-center justify-between">
          <span className="text-[10px] text-[var(--text-muted)] uppercase">Precision</span>
          <span className={`font-mono text-xs font-bold ${
            precisionInfo.color === 'green' ? 'text-emerald-400'
            : precisionInfo.color === 'amber' ? 'text-amber-400'
            : 'text-red-400'
          }`}>
            {precisionInfo.label}
          </span>
        </div>
        {/* Misclosure */}
        <div className="flex items-center justify-between">
          <span className="text-[10px] text-[var(--text-muted)] uppercase">Misclosure</span>
          <span className="font-mono text-xs text-[var(--text-primary)]">
            {state.linearMisclosure.toFixed(3)}m
          </span>
        </div>
        {/* Warnings */}
        {state.warnings.map((w, i) => (
          <div key={i} className="flex items-start gap-1 text-[10px] text-amber-400">
            <AlertTriangle className="w-3 h-3 shrink-0 mt-0.5" />
            <span>{w}</span>
          </div>
        ))}
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {/* ── Running Closure Monitor ── */}
      <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-4">
        <div className="flex items-center gap-2 mb-3">
          <Gauge className="w-4 h-4 text-[var(--accent)]" />
          <h3 className="text-sm font-bold text-[var(--text-primary)]">Running Closure</h3>
        </div>

        {/* Stats grid */}
        <div className="grid grid-cols-3 gap-2 mb-3">
          <div className="text-center">
            <p className="text-lg font-bold text-[var(--text-primary)]">{state.legCount}</p>
            <p className="text-[10px] text-[var(--text-muted)] uppercase">Legs</p>
          </div>
          <div className="text-center">
            <p className="text-lg font-bold text-[var(--text-primary)]">
              {state.linearMisclosure.toFixed(3)}m
            </p>
            <p className="text-[10px] text-[var(--text-muted)] uppercase">Misclosure</p>
          </div>
          <div className="text-center">
            <p className={`text-lg font-bold ${
              precisionInfo.color === 'green' ? 'text-emerald-400'
              : precisionInfo.color === 'amber' ? 'text-amber-400'
              : 'text-red-400'
            }`}>
              {precisionInfo.label}
            </p>
            <p className="text-[10px] text-[var(--text-muted)] uppercase">Precision</p>
          </div>
        </div>

        {/* Distance bar */}
        <div className="mb-2">
          <div className="flex justify-between text-[10px] text-[var(--text-muted)] mb-1">
            <span>Total: {state.totalDistance.toFixed(1)}m</span>
            <span>Required: 1:{state.minRequired.toLocaleString()}</span>
          </div>
          <div className="h-2 bg-[var(--bg-tertiary)] rounded-full overflow-hidden">
            <div
              className={`h-full transition-all ${
                state.meetsStandard ? 'bg-emerald-500' : 'bg-amber-500'
              }`}
              style={{
                width: state.totalDistance > 0 && state.precisionRatio
                  ? `${Math.min(100, (state.precisionRatio / state.minRequired) * 100)}%`
                  : '0%'
              }}
            />
          </div>
        </div>

        {/* Warnings */}
        {state.warnings.map((w, i) => (
          <div key={i} className="flex items-start gap-2 text-xs text-amber-400 bg-amber-500/10 rounded-lg p-2 mb-2">
            <AlertTriangle className="w-3.5 h-3.5 shrink-0 mt-0.5" />
            <span>{w}</span>
          </div>
        ))}

        {/* Quick add leg (for testing/manual entry) */}
        <div className="flex gap-2">
          <button
            onClick={() => addLeg(45, 50)}
            className="text-[10px] px-2 py-1 bg-[var(--bg-tertiary)] rounded text-[var(--text-secondary)] hover:bg-[var(--border-color)]"
          >
            + Test Leg (45°, 50m)
          </button>
          {legs.length > 0 && (
            <button
              onClick={undoLeg}
              className="text-[10px] px-2 py-1 bg-[var(--bg-tertiary)] rounded text-[var(--text-secondary)] hover:bg-[var(--border-color)]"
            >
              ↶ Undo
            </button>
          )}
          {legs.length > 0 && (
            <button
              onClick={reset}
              className="text-[10px] px-2 py-1 bg-red-500/10 text-red-400 rounded hover:bg-red-500/20"
            >
              Reset
            </button>
          )}
        </div>
      </div>

      {/* ── Setup Verification ── */}
      <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-4">
        <div className="flex items-center gap-2 mb-3">
          <ShieldCheck className="w-4 h-4 text-[var(--accent)]" />
          <h3 className="text-sm font-bold text-[var(--text-primary)]">Setup Check</h3>
        </div>

        <div className="space-y-2">
          {setupChecks.map((check, i) => (
            <div key={i} className="flex items-center gap-2 text-xs">
              {check.passed
                ? <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400 shrink-0" />
                : <XCircle className="w-3.5 h-3.5 text-red-400 shrink-0" />
              }
              <span className={`flex-1 ${check.passed ? 'text-[var(--text-secondary)]' : 'text-red-400'}`}>
                {check.message}
              </span>
            </div>
          ))}
        </div>
      </div>

      {/* ── Redundant Observation Alerts ── */}
      {discrepancies.length > 0 && (
        <div className="rounded-xl border border-red-500/20 bg-red-500/5 p-4">
          <div className="flex items-center gap-2 mb-3">
            <AlertTriangle className="w-4 h-4 text-red-400" />
            <h3 className="text-sm font-bold text-[var(--text-primary)]">
              Observation Discrepancies ({discrepancies.length})
            </h3>
          </div>
          <div className="space-y-2">
            {discrepancies.map((d, i) => (
              <div
                key={i}
                className={`text-xs rounded-lg p-2 ${
                  d.severity === 'error' ? 'bg-red-500/10 text-red-400' : 'bg-amber-500/10 text-amber-400'
                }`}
              >
                {d.message}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── Survey Class selector ── */}
      <div className="flex items-center gap-2">
        <span className="text-[10px] text-[var(--text-muted)] uppercase">Class:</span>
        {(['control', 'urban', 'rural', 'topographic'] as SurveyClass[]).map(cls => (
          <button
            key={cls}
            onClick={() => monitor.setSurveyClass(cls)}
            className={`text-[10px] px-2 py-1 rounded ${
              surveyClass === cls
                ? 'bg-[var(--accent)] text-black font-semibold'
                : 'bg-[var(--bg-tertiary)] text-[var(--text-muted)]'
            }`}
          >
            {cls}
          </button>
        ))}
      </div>
    </div>
  )
}

'use client'

/**
 * StakeoutRadar — Hot/Cold directional guidance for beacon recovery + AR Mode
 *
 * Features:
 * - Radar-style circular display
 * - Augmented Reality (AR) Camera overlay mode
 * - Directional arrow pointing to target
 * - Distance countdown (large, color-coded)
 * - Color shifts: Red (far) → Amber (close) → Green (on target)
 * - Bearing display in DMS
 * - Vibration feedback when within 1m (mobile)
 * - Audio beep that speeds up as you approach
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { Target, Navigation, Crosshair, Volume2, VolumeX, X, Camera, Compass } from 'lucide-react'

interface StakeoutRadarProps {
  targetE: number
  targetN: number
  onClose?: () => void
  epsg?: string
}

interface Position {
  lat: number
  lng: number
  accuracy: number
  easting: number
  northing: number
}

export function StakeoutRadar({ targetE, targetN, onClose, epsg = 'EPSG:21037' }: StakeoutRadarProps) {
  const [position, setPosition] = useState<Position | null>(null)
  const [distance, setDistance] = useState<number | null>(null)
  const [bearing, setBearing] = useState<number | null>(null)
  const [soundOn, setSoundOn] = useState(true)
  const [watching, setWatching] = useState(false)
  
  // AR State
  const [viewMode, setViewMode] = useState<'radar' | 'ar'>('radar')
  const [compassHeading, setCompassHeading] = useState<number | null>(null)
  const [cameraError, setCameraError] = useState<string | null>(null)
  
  const watchIdRef = useRef<number | null>(null)
  const audioCtxRef = useRef<AudioContext | null>(null)
  const lastBeepRef = useRef<number>(0)
  const videoRef = useRef<HTMLVideoElement>(null)
  const streamRef = useRef<MediaStream | null>(null)

  // Transform WGS84 to UTM
  const transformToUTM = useCallback(async (lat: number, lng: number): Promise<{ easting: number; northing: number }> => {
    try {
      const { transform } = await import('ol/proj')
      const [e, n] = transform([lng, lat], 'EPSG:4326', epsg) as [number, number]
      return { easting: e, northing: n }
    } catch {
      return { easting: 0, northing: 0 }
    }
  }, [epsg])

  // GPS Watch
  const startWatch = useCallback(() => {
    if (watching) return
    setWatching(true)
    if (!('geolocation' in navigator)) {
      setWatching(false)
      return
    }
    watchIdRef.current = navigator.geolocation.watchPosition(
      async (pos) => {
        const { easting, northing } = await transformToUTM(pos.coords.latitude, pos.coords.longitude)
        setPosition({
          lat: pos.coords.latitude,
          lng: pos.coords.longitude,
          accuracy: pos.coords.accuracy,
          easting,
          northing,
        })
        const dE = targetE - easting
        const dN = targetN - northing
        const dist = Math.sqrt(dE * dE + dN * dN)
        let brg = Math.atan2(dE, dN) * 180 / Math.PI
        if (brg < 0) brg += 360

        setDistance(dist)
        setBearing(brg)

        if (soundOn && dist < 10) {
          const now = Date.now()
          const interval = dist < 0.5 ? 200 : dist < 2 ? 500 : 1000
          if (now - lastBeepRef.current > interval) {
            lastBeepRef.current = now
            playBeep(dist < 0.5 ? 880 : dist < 2 ? 660 : 440)
          }
        }
        if (dist < 1 && 'vibrate' in navigator) {
          navigator.vibrate(100)
        }
      },
      () => {},
      { enableHighAccuracy: true, timeout: 5000, maximumAge: 1000 }
    )
  }, [watching, targetE, targetN, transformToUTM, soundOn])

  const stopWatch = useCallback(() => {
    if (watchIdRef.current != null) {
      navigator.geolocation.clearWatch(watchIdRef.current)
      watchIdRef.current = null
    }
    setWatching(false)
  }, [])

  useEffect(() => {
    startWatch()
    return () => stopWatch()
  }, [startWatch, stopWatch])

  const playBeep = useCallback((frequency: number) => {
    if (!soundOn) return
    try {
      if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || window.webkitAudioContext)()
      }
      const ctx = audioCtxRef.current
      const oscillator = ctx.createOscillator()
      const gainNode = ctx.createGain()
      oscillator.connect(gainNode)
      gainNode.connect(ctx.destination)
      oscillator.frequency.value = frequency
      oscillator.type = 'sine'
      gainNode.gain.setValueAtTime(0.1, ctx.currentTime)
      gainNode.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.15)
      oscillator.start(ctx.currentTime)
      oscillator.stop(ctx.currentTime + 0.15)
    } catch {}
  }, [soundOn])

  // --- AR Camera & Compass Integration ---
  
  const handleOrientation = useCallback((e: DeviceOrientationEvent) => {
    let heading = null
    if (typeof e.webkitCompassHeading === 'number') {
      // iOS
      heading = e.webkitCompassHeading
    } else if (e.alpha !== null) {
      // Android
      // Note: DeviceOrientationEvent uses alpha = 0 for North (if absolute) in some specs, 
      // but commonly compass heading is 360 - alpha.
      heading = 360 - e.alpha
      if (heading === 360) heading = 0
    }
    if (heading !== null) {
      setCompassHeading(heading)
    }
  }, [])

  const startAR = async () => {
    setCameraError(null)
    
    // 1. Camera
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment' }
      })
      streamRef.current = stream
      if (videoRef.current) {
        videoRef.current.srcObject = stream
      }
    } catch (err) {
      setCameraError('Camera access denied or unavailable.')
      return
    }

    // 2. Compass
    try {
      const DeviceOrientationEventCtor = DeviceOrientationEvent as typeof DeviceOrientationEvent & {
        requestPermission?: () => Promise<'granted' | 'denied'>
      }
      if (typeof DeviceOrientationEventCtor.requestPermission === 'function') {
        const permissionState = await DeviceOrientationEventCtor.requestPermission()
        if (permissionState === 'granted') {
          window.addEventListener('deviceorientation', handleOrientation, true)
        } else {
          setCameraError('Compass access denied.')
        }
      } else {
        window.addEventListener('deviceorientationabsolute', handleOrientation, true)
        // Fallback for non-absolute browsers
        window.addEventListener('deviceorientation', handleOrientation, true)
      }
    } catch (err) {
      setCameraError('Compass not supported on this device.')
    }
  }

  const stopAR = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop())
      streamRef.current = null
    }
    window.removeEventListener('deviceorientationabsolute', handleOrientation, true)
    window.removeEventListener('deviceorientation', handleOrientation, true)
  }

  const toggleViewMode = () => {
    if (viewMode === 'radar') {
      setViewMode('ar')
      startAR()
    } else {
      setViewMode('radar')
      stopAR()
    }
  }

  // Cleanup AR on unmount
  useEffect(() => {
    return () => {
      stopAR()
    }
  }, [handleOrientation])

  // --- Rendering ---
  
  const getColor = (dist: number | null) => {
    if (dist == null) return { ring: '#6b7280', text: 'text-gray-400', bg: 'bg-gray-500/10' }
    if (dist < 0.1) return { ring: '#10b981', text: 'text-emerald-400', bg: 'bg-emerald-500/10' }
    if (dist < 0.5) return { ring: '#10b981', text: 'text-emerald-400', bg: 'bg-emerald-500/10' }
    if (dist < 2) return { ring: '#84cc16', text: 'text-lime-400', bg: 'bg-lime-500/10' }
    if (dist < 5) return { ring: '#eab308', text: 'text-amber-400', bg: 'bg-amber-500/10' }
    if (dist < 15) return { ring: '#f97316', text: 'text-orange-400', bg: 'bg-orange-500/10' }
    return { ring: '#ef4444', text: 'text-red-400', bg: 'bg-red-500/10' }
  }

  const colors = getColor(distance)
  const isOnTarget = distance != null && distance < 0.5

  const formatBearing = (brg: number) => {
    const deg = Math.floor(brg)
    const minFull = (brg - deg) * 60
    const min = Math.floor(minFull)
    const sec = (minFull - min) * 60
    return `${deg}°${min}'${sec.toFixed(0)}"`
  }

  // Calculate AR target X position (-50vw to +50vw)
  // Assuming 60 degrees horizontal field of view
  let arTargetLeft = '50%'
  let arTargetVisible = false
  if (bearing != null && compassHeading != null) {
    let diff = bearing - compassHeading
    if (diff > 180) diff -= 360
    if (diff < -180) diff += 360
    
    if (Math.abs(diff) < 90) {
      arTargetVisible = true
      // Linear mapping: 30 degrees = 50vw offset
      const offsetVw = (diff / 30) * 50
      arTargetLeft = `calc(50% + ${offsetVw}vw)`
    }
  }

  // Scale target marker by distance (closer = bigger)
  let arScale = 1
  if (distance != null && distance > 0) {
    arScale = Math.max(0.2, Math.min(2.0, 10 / distance))
  }

  return (
    <div className={`fixed inset-0 z-[9999] flex flex-col items-center justify-center p-4 overflow-hidden ${viewMode === 'radar' ? 'bg-[#0a0a0f]' : 'bg-black'}`}>
      
      {/* AR Video Background */}
      {viewMode === 'ar' && (
        <div className="absolute inset-0 overflow-hidden">
          <video 
            ref={videoRef}
            autoPlay 
            playsInline 
            muted 
            className="absolute inset-0 w-full h-full object-cover opacity-80"
          />
          {cameraError && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/80 p-8 text-center text-red-400">
              {cameraError}
            </div>
          )}
        </div>
      )}

      {/* AR Target Marker */}
      {viewMode === 'ar' && !cameraError && (
        <div className="absolute inset-0 pointer-events-none">
          {arTargetVisible ? (
            <div 
              className="absolute top-1/2 -translate-y-1/2 -translate-x-1/2 transition-all duration-75 ease-linear"
              style={{ 
                left: arTargetLeft, 
                transform: `translate(-50%, -50%) scale(${arScale})` 
              }}
            >
              <div className="flex flex-col items-center drop-shadow-xl">
                <Target className="w-16 h-16 transition-colors duration-300 animate-pulse" style={{ color: colors.ring }} />
                <div className="mt-2 px-3 py-1 rounded bg-black/60 backdrop-blur text-white font-mono text-xl font-bold border border-white/20">
                  {distance?.toFixed(2)}m
                </div>
              </div>
            </div>
          ) : (
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-white/50 bg-black/40 px-4 py-2 rounded-full backdrop-blur-md">
              Turn towards target...
            </div>
          )}
        </div>
      )}

      {/* Header */}
      <div className="absolute top-4 left-4 right-4 flex items-center justify-between z-10">
        <div className="flex items-center gap-2 bg-black/40 backdrop-blur-md px-3 py-1.5 rounded-full border border-white/10">
          <Target className="w-4 h-4 text-[#D17B47]" />
          <span className="text-sm font-semibold text-white">
            {viewMode === 'radar' ? 'Stakeout Radar' : 'AR Stakeout'}
          </span>
        </div>
        <div className="flex items-center gap-2">
          {/* View Toggle */}
          <button
            onClick={toggleViewMode}
            className="w-10 h-10 flex items-center justify-center rounded-full bg-black/40 backdrop-blur-md border border-white/10 text-gray-300 hover:text-white transition-all hover:bg-white/10"
            title={viewMode === 'radar' ? 'Switch to AR Camera' : 'Switch to 2D Radar'}
          >
            {viewMode === 'radar' ? <Camera className="w-4 h-4" /> : <Compass className="w-4 h-4" />}
          </button>
          
          <button
            onClick={() => setSoundOn(!soundOn)}
            className="w-10 h-10 flex items-center justify-center rounded-full bg-black/40 backdrop-blur-md border border-white/10 text-gray-300 hover:text-white transition-all hover:bg-white/10"
          >
            {soundOn ? <Volume2 className="w-4 h-4" /> : <VolumeX className="w-4 h-4" />}
          </button>
          
          {onClose && (
            <button
              onClick={onClose}
              className="w-10 h-10 flex items-center justify-center rounded-full bg-red-500/20 backdrop-blur-md border border-red-500/30 text-red-400 hover:bg-red-500/40 hover:text-red-300 transition-all"
            >
              <X className="w-5 h-5" />
            </button>
          )}
        </div>
      </div>

      {/* 2D Radar display */}
      {viewMode === 'radar' && (
        <div className="relative w-72 h-72 mb-8 z-10">
          <div className="absolute inset-0 rounded-full border-2 transition-colors duration-300" style={{ borderColor: colors.ring, opacity: 0.3 }} />
          <div className="absolute inset-8 rounded-full border transition-colors duration-300" style={{ borderColor: colors.ring, opacity: 0.2 }} />
          <div className="absolute inset-16 rounded-full border transition-colors duration-300" style={{ borderColor: colors.ring, opacity: 0.4 }} />
          <div className="absolute top-1/2 left-0 right-0 h-px" style={{ backgroundColor: colors.ring, opacity: 0.2 }} />
          <div className="absolute left-1/2 top-0 bottom-0 w-px" style={{ backgroundColor: colors.ring, opacity: 0.2 }} />
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2">
            <div className={`w-4 h-4 rounded-full ${isOnTarget ? 'animate-ping' : ''}`} style={{ backgroundColor: colors.ring }} />
          </div>
          {bearing != null && (
            <div className="absolute top-1/2 left-1/2 origin-bottom" style={{ transform: `translate(-50%, -100%) rotate(${bearing}deg)`, height: '50%' }}>
              <div className="flex flex-col items-center">
                <Navigation className="w-8 h-8 transition-colors duration-300" style={{ color: colors.ring }} fill="currentColor" />
              </div>
            </div>
          )}
          <div className="absolute top-1 left-1/2 -translate-x-1/2 text-[10px] font-bold text-gray-500">N</div>
          <div className="absolute bottom-1 left-1/2 -translate-x-1/2 text-[10px] font-bold text-gray-500">S</div>
          <div className="absolute left-1 top-1/2 -translate-y-1/2 text-[10px] font-bold text-gray-500">W</div>
          <div className="absolute right-1 top-1/2 -translate-y-1/2 text-[10px] font-bold text-gray-500">E</div>
        </div>
      )}

      {/* Distance display (bottom center) */}
      <div className={`absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center z-10 ${viewMode === 'ar' ? 'bg-black/40 backdrop-blur-xl px-8 py-4 rounded-3xl border border-white/10' : ''}`}>
        <div className={`text-6xl font-bold font-mono ${colors.text} transition-colors duration-300`}>
          {distance != null ? distance.toFixed(2) : '—'}
        </div>
        <div className="text-xs text-gray-400 mt-1 uppercase tracking-widest font-semibold">Meters to target</div>
        
        {bearing != null && (
          <div className="flex items-center gap-2 mt-4 text-gray-300 bg-white/5 px-3 py-1.5 rounded-lg border border-white/10">
            <Crosshair className="w-4 h-4 opacity-50" />
            <span className="text-sm font-mono">Bearing: {formatBearing(bearing)}</span>
            {compassHeading != null && (
              <span className="text-sm font-mono ml-2 border-l border-white/20 pl-3">HDG: {Math.round(compassHeading)}°</span>
            )}
          </div>
        )}

        <div className={`mt-4 px-4 py-2 rounded-xl ${colors.bg} border ${colors.text} border-current/20 backdrop-blur-md w-full`}>
          <p className="text-sm font-medium text-center">
            {isOnTarget ? 'ON TARGET — Dig here!' :
             distance == null ? 'Waiting for GPS...' :
             distance < 2 ? 'Almost there — slow down' :
             distance < 5 ? 'Getting close' :
             distance < 15 ? 'Approaching target' :
             'Follow the beacon'}
          </p>
        </div>
      </div>
    </div>
  )
}

'use client'

/**
 * TopologyGuardrail — Real-time topology validation UI for cadastral surveys
 *
 * Displays topology issues as they're detected during parcel drawing.
 * Shows:
 * - Error count and warning count badges
 * - Expandable list of issues with severity colors
 * - Map highlight integration (passes issue coordinates back to parent)
 *
 * Integrates with:
 * - lib/survey/topologyChecker.ts (the validation engine)
 * - Map drawing interactions (parent passes drawn vertices)
 * - Existing parcel data (parent passes neighboring parcels)
 */

import { useState, useEffect, useCallback, useMemo } from 'react'
import {
  AlertTriangle, AlertCircle, Info, CheckCircle2,
  ChevronDown, ChevronUp, MapPin, ShieldAlert, ShieldCheck,
} from 'lucide-react'
import {
  runTopologyCheck,
  type TopologyIssue,
  type TopologyCheckResult,
  type ExistingParcel,
  type RoadReserve,
} from '@/lib/survey/topologyChecker'
import type { SurveyPoint } from '@/lib/map/turfHelpers'
import { logger } from '@/lib/logger'

interface TopologyGuardrailProps {
  /** Vertices of the parcel currently being drawn/edited */
  vertices: SurveyPoint[]
  /** Existing neighboring parcels to check against */
  existingParcels?: ExistingParcel[]
  /** Road reserves to check encroachment against */
  roadReserves?: RoadReserve[]
  /** Beacon positions (for duplicate detection) */
  beacons?: SurveyPoint[]
  /** Called when issues are detected — parent can highlight on map */
  onIssuesChange?: (issues: TopologyIssue[]) => void
  /** Whether to show the panel expanded by default */
  defaultExpanded?: boolean
  /** Compact mode (for inline display) */
  compact?: boolean
}

const SEVERITY_CONFIG = {
  error: {
    icon: AlertCircle,
    color: 'text-red-400',
    bg: 'bg-red-500/10',
    border: 'border-red-500/30',
    label: 'Error',
  },
  warning: {
    icon: AlertTriangle,
    color: 'text-amber-400',
    bg: 'bg-amber-500/10',
    border: 'border-amber-500/30',
    label: 'Warning',
  },
  info: {
    icon: Info,
    color: 'text-blue-400',
    bg: 'bg-blue-500/10',
    border: 'border-blue-500/30',
    label: 'Info',
  },
}

const ISSUE_TYPE_LABELS: Record<string, string> = {
  overlap: 'Parcel Overlap',
  sliver: 'Sliver Gap',
  self_intersection: 'Self-Intersection',
  road_encroachment: 'Road Reserve',
  duplicate_beacon: 'Duplicate Beacon',
  unclosed_polygon: 'Unclosed Polygon',
  insufficient_vertices: 'Insufficient Vertices',
}

export function TopologyGuardrail({
  vertices,
  existingParcels = [],
  roadReserves = [],
  beacons = [],
  onIssuesChange,
  defaultExpanded = true,
  compact = false,
}: TopologyGuardrailProps) {
  const [result, setResult] = useState<TopologyCheckResult | null>(null)
  const [expanded, setExpanded] = useState(defaultExpanded)
  const [checking, setChecking] = useState(false)

  // Run topology check when vertices change (debounced)
  useEffect(() => {
    if (vertices.length < 2) {
      setResult(null)
      onIssuesChange?.([])
      return
    }

    setChecking(true)
    const timer = setTimeout(async () => {
      try {
        const checkResult = await runTopologyCheck({
          newVertices: vertices,
          existingParcels,
          roadReserves,
          beacons,
        })
        setResult(checkResult)
        onIssuesChange?.(checkResult.issues)
      } catch (err) {
        logger.error('[TopologyGuardrail] Check failed:', { error: err })
      } finally {
        setChecking(false)
      }
    }, 300) // 300ms debounce

    return () => clearTimeout(timer)
  }, [vertices, existingParcels, roadReserves, beacons, onIssuesChange])

  const errorCount = useMemo(
    () => result?.issues.filter(i => i.severity === 'error').length ?? 0,
    [result]
  )
  const warningCount = useMemo(
    () => result?.issues.filter(i => i.severity === 'warning').length ?? 0,
    [result]
  )

  // Don't render if no vertices or all clear
  if (vertices.length < 2) {
    return null
  }

  if (result && result.issues.length === 0 && !checking) {
    return (
      <div className={`rounded-xl border border-emerald-500/30 bg-emerald-500/5 p-3 ${compact ? '' : 'p-4'}`}>
        <div className="flex items-center gap-2">
          <ShieldCheck className="w-4 h-4 text-emerald-400 shrink-0" />
          <span className="text-sm text-emerald-400 font-medium">Topology Valid</span>
        </div>
        {!compact && (
          <p className="text-[11px] text-emerald-400/70 mt-1">
            No overlaps, slivers, or encroachments detected. Safe for registry submission.
          </p>
        )}
      </div>
    )
  }

  return (
    <div className={`rounded-xl border ${errorCount > 0 ? 'border-red-500/30 bg-red-500/5' : 'border-amber-500/30 bg-amber-500/5'} overflow-hidden`}>
      {/* Header */}
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between px-3 py-2.5 hover:bg-white/[0.02] transition-colors"
      >
        <div className="flex items-center gap-2">
          {errorCount > 0 ? (
            <ShieldAlert className="w-4 h-4 text-red-400 shrink-0" />
          ) : (
            <AlertTriangle className="w-4 h-4 text-amber-400 shrink-0" />
          )}
          <span className={`text-sm font-medium ${errorCount > 0 ? 'text-red-400' : 'text-amber-400'}`}>
            Topology Issues
          </span>
          {checking && (
            <span className="text-[10px] text-gray-500 animate-pulse">checking...</span>
          )}
        </div>
        <div className="flex items-center gap-1.5">
          {errorCount > 0 && (
            <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium bg-red-500/15 text-red-400 border border-red-500/30">
              <AlertCircle className="w-3 h-3" />
              {errorCount}
            </span>
          )}
          {warningCount > 0 && (
            <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium bg-amber-500/15 text-amber-400 border border-amber-500/30">
              <AlertTriangle className="w-3 h-3" />
              {warningCount}
            </span>
          )}
          {expanded ? <ChevronUp className="w-3.5 h-3.5 text-gray-500" /> : <ChevronDown className="w-3.5 h-3.5 text-gray-500" />}
        </div>
      </button>

      {/* Issue list */}
      {expanded && result && (
        <div className="border-t border-white/[0.06] max-h-[300px] overflow-y-auto">
          {result.issues.map((issue, idx) => {
            const cfg = SEVERITY_CONFIG[issue.severity]
            const Icon = cfg.icon
            return (
              <div
                key={issue.id || idx}
                className={`px-3 py-2.5 border-b border-white/[0.04] last:border-b-0 ${cfg.bg}`}
              >
                <div className="flex items-start gap-2">
                  <Icon className={`w-3.5 h-3.5 ${cfg.color} shrink-0 mt-0.5`} />
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className={`text-xs font-medium ${cfg.color}`}>
                        {ISSUE_TYPE_LABELS[issue.type] || issue.type}
                      </span>
                    </div>
                    <p className="text-xs text-gray-300 mt-0.5">{issue.message}</p>
                    {issue.details && (
                      <p className="text-[10px] text-gray-500 mt-1 leading-relaxed">{issue.details}</p>
                    )}
                  </div>
                </div>
              </div>
            )
          })}
        </div>
      )}

      {/* Footer summary */}
      {!compact && expanded && result && (
        <div className="px-3 py-2 border-t border-white/[0.06] bg-[#0d0d14]/40">
          <p className="text-[10px] text-gray-500">
            {result.isValid
              ? 'No blocking errors — parcel can be saved.'
              : `${errorCount} error(s) must be fixed before registry submission.`}
          </p>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useRef, useEffect } from 'react'
import type { SurveyPlanData, PlanOptions } from '@/lib/reports/surveyPlan/types'
import { SurveyPlanRenderer } from '@/lib/reports/surveyPlan/renderer'
import { FormNo4Renderer } from '@/lib/reports/surveyPlan/formNo4Renderer'
import { SurveyPlanDataSchema } from '@/lib/validation/surveySchema'
import ComplianceChecklistModal from '@/components/ComplianceChecklistModal'
import { AlertCircle, FileCheck, Globe } from 'lucide-react'
import { sanitizeHtml } from '@/lib/security/sanitize'
import { logger } from '@/lib/logger'

interface SurveyPlanViewerProps {
  data: SurveyPlanData
  options?: PlanOptions
  className?: string
  submissionNumber?: string // For Form No. 4
}

const ZOOM_LEVELS = [0.25, 0.5, 0.75, 1.0, 1.5, 2.0, 4.0]

export default function SurveyPlanViewer({ data, options, className = '', submissionNumber }: SurveyPlanViewerProps) {
  const [scale, setScale] = useState(1.0)
  const [currentSheet, setCurrentSheet] = useState(0)
  const [svgContent, setSvgContent] = useState('')
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [showCompliance, setShowCompliance] = useState(false)
  const [useFormNo4, setUseFormNo4] = useState(true) // Default to Form No. 4 for Kenya
  const containerRef = useRef<HTMLDivElement>(null)
  const rendererRef = useRef<SurveyPlanRenderer | FormNo4Renderer | null>(null)

  useEffect(() => {
    setLoading(true)
    setError(null)

    try {
      // Quality Hardening: Validate data before rendering
      const validation = SurveyPlanDataSchema.safeParse(data)
      if (!validation.success) {
        logger.error('Survey plan data validation failed:', { error: validation.error })
        setError(validation.error.errors[0].message)
        return
      }

      let renderer: SurveyPlanRenderer | FormNo4Renderer
      let content: string

      // Choose renderer based on toggle and data availability
      const hasFormNo4Data = data.project.folioNumber || data.project.registerNumber || data.project.lrNumber
      
      if (useFormNo4 && hasFormNo4Data) {
        // Use Kenya Form No. 4 standard
        renderer = new FormNo4Renderer(data, { ...options, submissionNumber })
        content = (renderer as FormNo4Renderer).renderFormNo4()
      } else {
        // Use standard renderer
        renderer = new SurveyPlanRenderer(data, options)
        content = renderer.render()
      }
      
      rendererRef.current = renderer
      setSvgContent(content)
    } catch (e) {
      logger.error('Survey plan render error:', { error: e })
      setError(e instanceof Error ? e.message : 'Unknown rendering error')
      setSvgContent('')
    } finally {
      setLoading(false)
    }
  }, [data, options, useFormNo4, submissionNumber])

  const zoomIn = () => {
    const idx = ZOOM_LEVELS.findIndex(z => z > scale)
    if (idx !== -1) setScale(ZOOM_LEVELS[idx])
  }
  const zoomOut = () => {
    const idx = ZOOM_LEVELS.findLastIndex(z => z < scale)
    if (idx !== -1) setScale(ZOOM_LEVELS[idx])
  }
  const fitToWidth = () => setScale(1.0)

  const handleDownloadCSV = () => {
    if (!rendererRef.current) return
    const csv = rendererRef.current.exportToCSV()
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = `${(data.project.name || 'survey-plan').replace(/\s+/g, '_')}-bearing-schedule.csv`
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
    URL.revokeObjectURL(url)
  }

  const handleDownloadSVG = () => {
    if (!svgContent) return
    const blob = new Blob([svgContent], { type: 'image/svg+xml;charset=utf-8' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    const suffix = useFormNo4 ? '_FormNo4' : '_Plan'
    link.download = `${data.project.name.replace(/\s+/g, '_')}${suffix}.svg`
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
    URL.revokeObjectURL(url)
  }

  const handlePrint = () => window.print()

  // Check if Form No. 4 data is available
  const hasFormNo4Data = data.project.folioNumber || data.project.registerNumber || data.project.lrNumber

  return (
    <div className={`flex flex-col h-full ${className}`}>
      <div className="flex items-center gap-2 px-3 py-2 border-b border-[var(--border)] bg-[var(--bg-secondary)] no-print">
        <button onClick={zoomOut} disabled={scale <= ZOOM_LEVELS[0]}
          className="px-2 py-1 text-sm rounded hover:bg-[var(--bg-tertiary)] disabled:opacity-30">−</button>
        <span className="text-xs font-mono min-w-[48px] text-center">{Math.round(scale * 100)}%</span>
        <button onClick={zoomIn} disabled={scale >= ZOOM_LEVELS[ZOOM_LEVELS.length - 1]}
          className="px-2 py-1 text-sm rounded hover:bg-[var(--bg-tertiary)] disabled:opacity-30">+</button>
        <button onClick={fitToWidth}
          className="px-2 py-1 text-xs rounded hover:bg-[var(--bg-tertiary)] border border-[var(--border)]">Fit</button>
        
        <div className="w-px h-6 bg-[var(--border)] mx-2" />
        
        {/* Form No. 4 Toggle */}
        {hasFormNo4Data && (
          <button
            onClick={() => setUseFormNo4(!useFormNo4)}
            className={`flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-lg font-medium transition-colors ${
              useFormNo4 
                ? 'bg-green-600 text-white hover:bg-green-700' 
                : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)] hover:bg-[var(--border)]'
            }`}
            title={useFormNo4 ? 'Using Kenya Form No. 4 standard' : 'Using standard plan format'}
          >
            <FileCheck className="w-3.5 h-3.5" />
            {useFormNo4 ? 'Form No. 4 (Kenya)' : 'Standard Plan'}
          </button>
        )}
        
        <div className="flex-1" />
        
        {svgContent && (
          <button onClick={handleDownloadSVG}
            className="px-3 py-1 text-xs rounded bg-[var(--accent)] text-black font-medium hover:opacity-80">
            Download SVG
          </button>
        )}
        <button onClick={handlePrint}
          className="px-3 py-1 text-xs rounded bg-gray-600 text-white hover:opacity-80">
          Print
        </button>
        <button onClick={handleDownloadCSV}
          className="px-3 py-1 text-xs rounded bg-green-600 text-white hover:opacity-80">
          Download CSV
        </button>
        <button onClick={() => setShowCompliance(true)}
          className="px-3 py-1 text-xs rounded bg-[var(--accent)] text-black font-semibold hover:opacity-80">
          Export Plan
        </button>
      </div>
      
      {/* Info banner for Form No. 4 */}
      {useFormNo4 && hasFormNo4Data && (
        <div className="px-3 py-1.5 bg-green-50 border-b border-green-200 flex items-center gap-2">
          <FileCheck className="w-4 h-4 text-green-600" />
          <span className="text-xs text-green-700">
            Kenya Form No. 4 Survey Plan — Compliant with Survey Act Cap. 299 and Survey Regulations 1994
          </span>
          {submissionNumber && (
            <span className="ml-auto text-xs font-mono text-green-600">
              Submission: {submissionNumber}
            </span>
          )}
        </div>
      )}
      
      {svgContent && svgContent.includes('Sheet ') && (
        (() => {
          const match = svgContent.match(/Sheet \d+ of (\d+)/)
          const total = match ? parseInt(match[1], 10) : 1
          return (
            <div className="flex items-center justify-center gap-2 px-3 py-1 border-b border-[var(--border)] bg-[var(--bg-secondary)]">
              <span className="text-xs font-mono text-[var(--text-secondary)]">Sheet {currentSheet + 1} of {total}</span>
              <button onClick={() => setCurrentSheet(Math.max(0, currentSheet - 1))} disabled={currentSheet === 0}
                className="px-2 py-0.5 text-xs rounded hover:bg-[var(--bg-tertiary)] disabled:opacity-30 border border-[var(--border)]">&lt;</button>
              <button onClick={() => setCurrentSheet(Math.min(total - 1, currentSheet + 1))} disabled={currentSheet >= total - 1}
                className="px-2 py-0.5 text-xs rounded hover:bg-[var(--bg-tertiary)] disabled:opacity-30 border border-[var(--border)]">&gt;</button>
            </div>
          )
        })()
      )}
      
      <div ref={containerRef} className="flex-1 overflow-auto bg-[#e8e8e8] p-4">
        {loading ? (
          <div className="flex flex-col items-center justify-center h-full text-[var(--text-secondary)] gap-3">
            <div className="w-8 h-8 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin" />
            <div className="font-mono text-xs uppercase tracking-widest">
              {useFormNo4 ? 'Generating Form No. 4 plan...' : 'Generating plan...'}
            </div>
          </div>
        ) : error ? (
          <div className="flex flex-col items-center justify-center h-full max-w-md mx-auto text-center gap-4">
            <div className="p-4 rounded-full bg-red-500/10 text-red-500">
              <AlertCircle className="w-8 h-8" />
            </div>
            <div>
              <h3 className="text-lg font-bold text-red-500 uppercase tracking-tight">Render Failed</h3>
              <p className="text-sm text-[var(--text-secondary)] mt-1">{error}</p>
            </div>
            <button
              onClick={() => {
                setUseFormNo4(false)
                setError(null)
              }}
              className="px-4 py-2 bg-[var(--bg-secondary)] border border-[var(--border)] rounded-lg text-xs font-semibold hover:bg-[var(--bg-tertiary)]"
            >
              Try Standard Format
            </button>
          </div>
        ) : svgContent ? (
          svgContent.includes('Sheet ') ? (
            <div
              className="shadow-lg mx-auto"
              style={{
                width: '1587px',
                height: '1123px',
                overflow: 'hidden',
              }}
            >
              <div
                style={{
                  transform: `translate(${-currentSheet * 1587 * scale}px, 0) scale(${scale})`,
                  transformOrigin: 'top left',
                  position: 'absolute',
                }}
                dangerouslySetInnerHTML={{ __html: sanitizeHtml(svgContent) }}
              />
            </div>
          ) : (
            <div className="shadow-lg mx-auto" style={{ transform: `scale(${scale})`, transformOrigin: 'top center', width: 'fit-content' }}
              dangerouslySetInnerHTML={{ __html: sanitizeHtml(svgContent) }} />
          )
        ) : (
          <div className="flex items-center justify-center h-full text-[var(--text-secondary)]">No plan data available</div>
        )}
      </div>

      <ComplianceChecklistModal
        isOpen={showCompliance}
        onClose={() => setShowCompliance(false)}
        data={data}
        onExport={handlePrint}
      />
    </div>
  )
}

'use client';

import { useState, useEffect, useCallback, useMemo, useRef } from 'react'
import { createClient } from '@/lib/api-client/client'
import { sanitizeHtml } from '@/lib/security/sanitize'
import { usePrint, PrintButton, PrintHeader } from '@/hooks/usePrint'
import { buildSubmissionNumber, normaliseRegistrationNo, validateSubmissionNumber } from '@/lib/submission/format'
import { z } from 'zod'
import { apiPost, ApiError } from '@/lib/api/client'
// import { PHASE13_DEMO_PROJECTS } from '@/lib/standards/rdm11'
import type { 
  SurveyReportInput, 
  SectionContent,
  SectionGap,

  ReportSection,
  ReportCompletenessResult,
  EquipmentItem,
  PersonnelItem,
  ControlPoint
} from '@/types/surveyReport'
import { logger } from '@/lib/logger'

interface SurveyReportBuilderProps {
  projectId: string
  existingReportId?: string
}

const SECTION_INFO: { section: ReportSection; number: number; title: string; autoGenerated: boolean }[] = [
  { section: 'TITLE_PAGE', number: 1, title: 'Title Page', autoGenerated: false },
  { section: 'TABLE_OF_CONTENTS', number: 2, title: 'Table of Contents', autoGenerated: true },
  { section: 'INTRODUCTION', number: 3, title: 'Introduction', autoGenerated: false },
  { section: 'SCOPE_OF_WORK', number: 4, title: 'Scope of Work', autoGenerated: false },
  { section: 'EQUIPMENT_AND_PERSONNEL', number: 5, title: 'Equipment and Personnel', autoGenerated: false },
  { section: 'CONTROL_SURVEY', number: 6, title: 'Control Survey', autoGenerated: false },
  { section: 'TOPOGRAPHIC_SURVEY', number: 7, title: 'Topographic Survey', autoGenerated: false },
  { section: 'DATA_PROCESSING', number: 8, title: 'Data Processing', autoGenerated: true },
  { section: 'RESULTS_AND_ACCURACY', number: 9, title: 'Results and Accuracy', autoGenerated: false },
  { section: 'COORDINATE_REGISTER', number: 10, title: 'Coordinate Register', autoGenerated: true },
  { section: 'BENCHMARK_REGISTER', number: 11, title: 'Benchmark Register', autoGenerated: true },
  { section: 'TRAVERSE_COMPUTATIONS', number: 12, title: 'Traverse Computations', autoGenerated: true },
  { section: 'LEVELLING_COMPUTATIONS', number: 13, title: 'Levelling Computations', autoGenerated: true },
  { section: 'CONCLUSIONS_AND_RECOMMENDATIONS', number: 14, title: 'Conclusions and Recommendations', autoGenerated: false },
  { section: 'DECLARATION', number: 15, title: 'Surveyor\'s Declaration', autoGenerated: false },
]

const DEFAULT_SCOPE_ITEMS = [
  'Establishment of survey control network',
  'Topographic survey of the project area',
  'Traverse computation and adjustment',
  'Levelling and reduced levels',
  'Survey plan production per Survey Regulations 1994',
  'Survey report per RDM 1.1 Table 5.4'
]

// ─── API response schemas (Zod) ────────────────────────────────────────────
const generateReportResponseSchema = z.object({
  sections: z.array(z.object({}).passthrough()),
  completeness: z.object({}).passthrough(),
  input: z.object({}).passthrough(),
}).passthrough()

const saveReportResponseSchema = z.object({
  id: z.string().optional(),
  saved: z.boolean().optional(),
  created: z.boolean().optional(),
}).passthrough()

export default function SurveyReportBuilder({ projectId, existingReportId }: SurveyReportBuilderProps) {
  const [activeSection, setActiveSection] = useState<ReportSection>('TITLE_PAGE')
  const [reportInput, setReportInput] = useState<Partial<SurveyReportInput>>({})
  const [generatedSections, setGeneratedSections] = useState<SectionContent[]>([])
  const [completeness, setCompleteness] = useState<ReportCompletenessResult | null>(null)
  const [mode, setMode] = useState<'edit' | 'preview'>('edit')
  const [isSaving, setIsSaving] = useState(false)
  const [isGenerating, setIsGenerating] = useState(false)
  const [isDirty, setIsDirty] = useState(false)
  const [reportId, setReportId] = useState(existingReportId || '')
  const [error, setError] = useState<string | null>(null)
  const [editingAutoSection, setEditingAutoSection] = useState<string | null>(null)
  const [autoSectionDraft, setAutoSectionDraft] = useState('')
  const { print, isPrinting, paperSize, setPaperSize, orientation, setOrientation } = usePrint({ title: 'Survey Report' })

  const dbClient = createClient()

  const generateReport = useCallback(async (input: Partial<SurveyReportInput>) => {
    setIsGenerating(true)
    setError(null)
    try {
      const data = await apiPost(
        '/api/survey-report/generate',
        generateReportResponseSchema,
        { projectId, input }
      )
      setReportInput(data.input as Partial<SurveyReportInput>)
      setGeneratedSections(data.sections as unknown as SectionContent[])
      setCompleteness(data.completeness as unknown as ReportCompletenessResult)
      setIsDirty(false)
    } catch (err) {
      if (err instanceof ApiError) {
        setError(err.message)
      } else {
        setError(err instanceof Error ? err.message : 'Generation failed')
      }
    } finally {
      setIsGenerating(false)
    }
  }, [projectId])

  const loadReport = useCallback(async () => {
    if (existingReportId) {
      try {
        const { getSurveyReportById } = await import('@/lib/api-client/surveyReports')
        const report = await getSurveyReportById(existingReportId)
        if (report) {
          setReportInput({
            ...report,
            projectId
          } as SurveyReportInput)
          setGeneratedSections(report.sections)
          setReportId(existingReportId)
          // Reconstruct completeness from saved data so auto-save works
          const savedPercent = report.completeness || 0
          setCompleteness({
            overallPercent: savedPercent,
            sectionsComplete: report.sections?.filter((s: SectionContent) => s.completeness >= 100).length || 0,
            sectionsIncomplete: report.sections?.filter((s: SectionContent) => s.completeness < 100).map((s: SectionContent) => ({
              section: s.section,
              sectionNumber: s.sectionNumber,
              missingFields: [],
              completeness: s.completeness,
            })) || [],
            readyToFinalise: savedPercent >= 100,
          })
          return
        }
      } catch (err) {
        logger.error('Failed to load report:', { error: err })
      }
    }
    // Only generate fresh report when creating new (no existingReportId)
    await generateReport({ projectId } as SurveyReportInput)
  }, [existingReportId, projectId, generateReport])

  useEffect(() => {
    loadReport()
  }, [loadReport])

  const saveReport = useCallback(async () => {
    if (!completeness) return
    
    setIsSaving(true)
    try {
      const data = await apiPost(
        '/api/survey-report/save',
        saveReportResponseSchema,
        {
          reportId: reportId || undefined,
          projectId,
          input: reportInput,
          sections: generatedSections,
          completeness: completeness.overallPercent
        }
      )
      if (data.id) {
        setReportId(data.id)
      }
      setIsDirty(false)
    } catch (err) {
      if (err instanceof ApiError) {
        setError(err.message)
      } else {
        setError(err instanceof Error ? err.message : 'Save failed')
      }
    } finally {
      setIsSaving(false)
    }
  }, [completeness, reportId, projectId, reportInput, generatedSections])

  const saveTimeoutRef = useRef<NodeJS.Timeout | null>(null)

  useEffect(() => {
    if (isDirty && reportInput.projectId && completeness) {
      if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current)
      saveTimeoutRef.current = setTimeout(() => {
        saveReport().catch(() => {})
      }, 2000)
    }
    return () => {
      if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current)
    }
  }, [reportInput, generatedSections, isDirty, saveReport, completeness])

  const updateInput = (field: keyof SurveyReportInput, value: SurveyReportInput[keyof SurveyReportInput]) => {
    setReportInput(prev => ({ ...prev, [field]: value }))
    setIsDirty(true)
  }

  // Demo removed — function no longer needed

  const DEFAULT_DECLARATION = `I, the undersigned, being a Registered Surveyor under the Survey Act (Cap. 299), do hereby declare that:

1. The survey described in this report was carried out under my direct supervision in accordance with the Survey Act (Cap. 299), the Survey Regulations 1994, and the Road Design Manual Part 1 (RDM 1.1, 2025).

2. All field observations, computations, and plans contained herein are accurate and correct to the best of my knowledge and professional belief.

3. The instruments used were in proper adjustment and calibrated within the period specified by the manufacturer and applicable standards.

4. The coordinates, levels, and areas stated in this report have been computed and checked, and are fit for the purpose described in Section 4 (Scope of Work).

Signed: ___________________________    Date: _______________

Name: ___________________________    ISK No: _______________

Firm: ___________________________    Stamp: _______________`

  const exportReport = async (format: 'pdf' | 'docx') => {
    if (!reportId) {
      await saveReport()
    }
    
    try {
      // ponytail: binary download bypasses typed client
      const response = await fetch('/api/survey-report/export', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reportId: reportId || existingReportId, format })
      })
      
      if (!response.ok) {
        throw new Error('Export failed')
      }
      
      const blob = await response.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `${reportInput.reportNumber || 'survey_report'}.${format}`
      a.click()
      URL.revokeObjectURL(url)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Export failed')
    }
  }

  const getCompletenessForSection = (section: ReportSection): number => {
    if (!completeness) return 0
    const gap = completeness.sectionsIncomplete.find((g: SectionGap) => g.section === section)
    return gap ? gap.completeness : 100
  }

  const isSectionComplete = (section: ReportSection): boolean => {
    return getCompletenessForSection(section) >= 100
  }

  const getSectionBadge = (info: typeof SECTION_INFO[0]) => {
    if (info.autoGenerated) {
      return <span className="text-[10px] px-1.5 py-0.5 bg-gray-200 text-gray-600 rounded">AUTO</span>
    }
    const comp = getCompletenessForSection(info.section)
    if (comp >= 100) {
      return <span className="w-2 h-2 bg-green-500 rounded-full" />
    } else if (comp >= 50) {
      return <span className="w-2 h-2 bg-amber-500 rounded-full" />
    } else {
      return <span className="w-2 h-2 bg-red-500 rounded-full" />
    }
  }

  const renderSectionForm = () => {
    const sectionInfo = SECTION_INFO.find((s: (typeof SECTION_INFO)[number]) => s.section === activeSection)
    if (!sectionInfo) return null

    if (sectionInfo.autoGenerated) {
      const section = generatedSections.find((s: SectionContent) => s.section === activeSection)
      const isEditing = editingAutoSection === activeSection

      const startEditing = () => {
        setEditingAutoSection(activeSection)
        // Strip HTML tags for textarea editing
        const raw = section?.content?.replace(/<[^>]*>/g, '\n').replace(/\n{3,}/g, '\n\n').trim() || ''
        setAutoSectionDraft(raw)
      }

      const saveEditing = () => {
        if (!section) return
        const updated = generatedSections.map((s: SectionContent) =>
          s.section === activeSection
            ? { ...s, content: autoSectionDraft.split('\n').filter((l: string) => l.trim()).map((l: string) => `<p>${l}</p>`).join('') }
            : s
        )
        setGeneratedSections(updated)
        setEditingAutoSection(null)
        setAutoSectionDraft('')
        setIsDirty(true)
      }

      const cancelEditing = () => {
        setEditingAutoSection(null)
        setAutoSectionDraft('')
      }

      return (
        <div className="space-y-4">
          <div className="bg-gray-50 border border-gray-200 rounded-lg p-4 text-sm text-gray-600">
            <p className="flex items-center gap-2">
              <span>(i)</span>
              This section is auto-generated from your project data.
            </p>
          </div>
          {isEditing ? (
            <div className="space-y-3">
              <textarea
                value={autoSectionDraft}
                onChange={e => setAutoSectionDraft(e.target.value)}
                rows={20}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm font-mono"
                placeholder="Edit section content..."
              />
              <div className="flex gap-2">
                <button
                  onClick={saveEditing}
                  className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-medium"
                >
                  Save Changes
                </button>
                <button
                  onClick={cancelEditing}
                  className="px-4 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                >
                  Cancel
                </button>
              </div>
            </div>
          ) : (
            <div
              className="bg-gray-50 border border-gray-200 rounded-lg p-6 prose prose-sm max-w-none"
              dangerouslySetInnerHTML={{ __html: sanitizeHtml(section?.content || '<p class="text-gray-400">No content generated yet. Click Regenerate to populate this section.</p>') }}
            />
          )}
          <div className="flex gap-2">
            {!isEditing && (
              <button
                onClick={startEditing}
                className="px-4 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm font-medium hover:border-[var(--accent)]"
              >
                Edit Content
              </button>
            )}
            <button
              onClick={() => generateReport(reportInput as SurveyReportInput)}
              disabled={isGenerating}
              className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-medium disabled:opacity-50"
            >
              {isGenerating ? 'Regenerating...' : 'Regenerate'}
            </button>
          </div>
        </div>
      )
    }

    switch (activeSection) {
      case 'TITLE_PAGE':
        return (
          <div className="space-y-4">
            <div>
              <label htmlFor="sr-report-title" className="block text-sm font-medium mb-1">Report Title</label>
              <input
                id="sr-report-title"
                type="text"
                value={reportInput.reportTitle || ''}
                onChange={e => updateInput('reportTitle', e.target.value)}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                placeholder="Topographic Survey Report"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-report-number" className="block text-sm font-medium mb-1">Report Number</label>
                <input id="sr-report-number"
                  type="text"
                  value={reportInput.reportNumber || ''}
                  onChange={e => updateInput('reportNumber', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
              <div>
                <label htmlFor="sr-revision" className="block text-sm font-medium mb-1">Revision</label>
                <input id="sr-revision"
                  type="text"
                  value={reportInput.revisionNumber || 'Rev 0'}
                  onChange={e => updateInput('revisionNumber', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
            </div>
            <div>
              <label htmlFor="sr-submission-number" className="block text-sm font-medium mb-1">Submission Number (SRVY2025-1)</label>
              <div className="flex gap-2">
                <input
                  id="sr-submission-number"
                  type="text"
                  value={reportInput.submissionNumber || ''}
                  onChange={e => updateInput('submissionNumber', e.target.value.toUpperCase())}
                  className={`flex-1 px-3 py-2 bg-[var(--bg-tertiary)] border rounded-lg text-sm font-mono ${
                    reportInput.submissionNumber && !validateSubmissionNumber(reportInput.submissionNumber)
                      ? 'border-red-500'
                      : 'border-[var(--border-color)]'
                  }`}
                  aria-label="Submission number" placeholder="RS149_2026_001_R00"
                />
                <button
                  onClick={() => {
                    const reg = normaliseRegistrationNo(reportInput.surveyorRegistrationNumber || 'RS149')
                    updateInput('submissionNumber', buildSubmissionNumber({
                      registrationNo: reg,
                      year: new Date().getFullYear(),
                      sequence: 1,
                      revision: 0,
                    }))
                  }}
                  className="px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs"
                >
                  Generate
                </button>
              </div>
              <p className="text-xs text-gray-500 mt-1">Format: registration_year_sequence_revision, e.g. RS149_2026_002_R00.</p>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-client-name" className="block text-sm font-medium mb-1">Client Name</label>
                <input id="sr-client-name"
                  type="text"
                  value={reportInput.clientName || ''}
                  onChange={e => updateInput('clientName', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
              <div>
                <label htmlFor="sr-report-date" className="block text-sm font-medium mb-1">Report Date</label>
                <input id="sr-report-date"
                  type="date"
                  value={reportInput.reportDate || ''}
                  onChange={e => updateInput('reportDate', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
            </div>
            <div>
              <label htmlFor="sr-client-address" className="block text-sm font-medium mb-1">Client Address</label>
              <textarea
                id="sr-client-address"
                value={reportInput.clientAddress || ''}
                onChange={e => updateInput('clientAddress', e.target.value)}
                rows={2}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-firm-name" className="block text-sm font-medium mb-1">Firm Name</label>
                <input id="sr-firm-name"
                  type="text"
                  value={reportInput.firmName || ''}
                  onChange={e => updateInput('firmName', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
              <div>
                <label htmlFor="sr-firm-isk" className="block text-sm font-medium mb-1">ISK Number</label>
                <input id="sr-firm-isk"
                  type="text"
                  value={reportInput.firmIskNumber || ''}
                  onChange={e => updateInput('firmIskNumber', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-surveyor-name" className="block text-sm font-medium mb-1">Surveyor Name</label>
                <input id="sr-surveyor-name"
                  type="text"
                  value={reportInput.surveyorName || ''}
                  onChange={e => updateInput('surveyorName', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
              <div>
                <label htmlFor="sr-surveyor-isk" className="block text-sm font-medium mb-1">Surveyor ISK Number</label>
                <input id="sr-surveyor-isk"
                  type="text"
                  value={reportInput.surveyorIskNumber || ''}
                  onChange={e => updateInput('surveyorIskNumber', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
            </div>
            <div>
              <label htmlFor="sr-surveyor-reg" className="block text-sm font-medium mb-1">Surveyor Registration Number</label>
              <input
                id="sr-surveyor-reg"
                type="text"
                value={reportInput.surveyorRegistrationNumber || ''}
                onChange={e => updateInput('surveyorRegistrationNumber', normaliseRegistrationNo(e.target.value))}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm font-mono"
                placeholder="RS149"
              />
            </div>
          </div>
        )

      case 'INTRODUCTION':
        return (
          <div className="space-y-4">
            <div>
              <label htmlFor="sr-project-location" className="block text-sm font-medium mb-1">Project Location</label>
              <input
                id="sr-project-location"
                type="text"
                value={reportInput.projectLocation || ''}
                onChange={e => updateInput('projectLocation', e.target.value)}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                placeholder="e.g., Kiserian, Kajiado County"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-county" className="block text-sm font-medium mb-1">County</label>
                <input id="sr-county"
                  type="text"
                  value={reportInput.county || ''}
                  onChange={e => updateInput('county', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
              <div>
                <label htmlFor="sr-constituency" className="block text-sm font-medium mb-1">Constituency (optional)</label>
                <input id="sr-constituency"
                  type="text"
                  value={reportInput.constituency || ''}
                  onChange={e => updateInput('constituency', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
            </div>
            <div>
              <label htmlFor="sr-project-purpose" className="block text-sm font-medium mb-1">Project Purpose</label>
              <textarea
                id="sr-project-purpose"
                value={reportInput.projectPurpose || ''}
                onChange={e => updateInput('projectPurpose', e.target.value)}
                rows={4}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                placeholder="Describe why this survey was commissioned..."
              />
            </div>
            <div>
              <label htmlFor="sr-site-description" className="block text-sm font-medium mb-1">Site Description</label>
              <textarea
                id="sr-site-description"
                value={reportInput.siteDescription || ''}
                onChange={e => updateInput('siteDescription', e.target.value)}
                rows={4}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                placeholder="Describe terrain, land use, vegetation, access..."
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-survey-start" className="block text-sm font-medium mb-1">Survey Start Date</label>
                <input id="sr-survey-start"
                  type="date"
                  value={reportInput.surveyPeriodStart || ''}
                  onChange={e => updateInput('surveyPeriodStart', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
              <div>
                <label htmlFor="sr-survey-end" className="block text-sm font-medium mb-1">Survey End Date</label>
                <input id="sr-survey-end"
                  type="date"
                  value={reportInput.surveyPeriodEnd || ''}
                  onChange={e => updateInput('surveyPeriodEnd', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
            </div>
          </div>
        )

      case 'SCOPE_OF_WORK':
        return (
          <div className="space-y-4">
            <div className="block text-sm font-medium mb-1">Scope Items</div>
            {(reportInput.scopeItems || []).map((item, idx) => (
              <div key={`${item}-${idx}`} className="flex gap-2">
                <input aria-label={`Scope item ${idx + 1}`}
                  type="text"
                  value={item}
                  onChange={e => {
                    const newItems = [...(reportInput.scopeItems || [])]
                    newItems[idx] = e.target.value
                    updateInput('scopeItems', newItems)
                  }}
                  className="flex-1 px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
                <button
                  onClick={() => {
                    const newItems = (reportInput.scopeItems || []).filter((_, i) => i !== idx)
                    updateInput('scopeItems', newItems)
                  }}
                  className="px-3 py-2 text-red-500 hover:bg-red-50 rounded-lg text-sm"
                >
                  Remove
                </button>
              </div>
            ))}
            <button
              onClick={() => updateInput('scopeItems', [...(reportInput.scopeItems || []), ''])}
              className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-medium"
            >
              + Add Scope Item
            </button>
          </div>
        )

      case 'EQUIPMENT_AND_PERSONNEL':
        return (
          <div className="space-y-6">
            <div>
              <h4 className="text-sm font-medium mb-2">Equipment</h4>
              {(reportInput.equipment || []).map((eq, idx) => (
                <div key={`${eq}-${idx}`} className="grid grid-cols-6 gap-2 mb-2">
                  <input
                    type="text"
                    aria-label="Equipment Type" placeholder="e.g. Total Station"
                    value={eq.type}
                    onChange={e => {
                      const newEq = [...(reportInput.equipment || [])]
                      newEq[idx] = { ...newEq[idx], type: e.target.value }
                      updateInput('equipment', newEq)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <input
                    type="text"
                    aria-label="Make" placeholder="e.g. Leica"
                    value={eq.make}
                    onChange={e => {
                      const newEq = [...(reportInput.equipment || [])]
                      newEq[idx] = { ...newEq[idx], make: e.target.value }
                      updateInput('equipment', newEq)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <input
                    type="text"
                    aria-label="Serial No" placeholder="e.g. SN-12345"
                    value={eq.serialNumber}
                    onChange={e => {
                      const newEq = [...(reportInput.equipment || [])]
                      newEq[idx] = { ...newEq[idx], serialNumber: e.target.value }
                      updateInput('equipment', newEq)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <input aria-label="Calibration Date"
                    type="date"
                    value={eq.calibrationDate}
                    onChange={e => {
                      const newEq = [...(reportInput.equipment || [])]
                      newEq[idx] = { ...newEq[idx], calibrationDate: e.target.value }
                      updateInput('equipment', newEq)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <input
                    type="text"
                    aria-label="Cert No" placeholder="e.g. CERT-2026-01"
                    value={eq.calibrationCert}
                    onChange={e => {
                      const newEq = [...(reportInput.equipment || [])]
                      newEq[idx] = { ...newEq[idx], calibrationCert: e.target.value }
                      updateInput('equipment', newEq)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <button
                    onClick={() => {
                      const newEq = (reportInput.equipment || []).filter((_, i) => i !== idx)
                      updateInput('equipment', newEq)
                    }}
                    className="text-red-500 text-xs"
                  >
                    [x]
                  </button>
                </div>
              ))}
              <button
                onClick={() => updateInput('equipment', [...(reportInput.equipment || []), { type: '', make: '', serialNumber: '', calibrationDate: '', calibrationCert: '' }])}
                className="px-3 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs"
              >
                + Add Equipment
              </button>
            </div>
            <div>
              <h4 className="text-sm font-medium mb-2">Personnel</h4>
              {(reportInput.personnel || []).map((p, idx) => (
                <div key={p.name} className="grid grid-cols-4 gap-2 mb-2">
                  <input
                    type="text"
                    aria-label="Personnel Name" placeholder="e.g. J. Mwangi"
                    value={p.name}
                    onChange={e => {
                      const newP = [...(reportInput.personnel || [])]
                      newP[idx] = { ...newP[idx], name: e.target.value }
                      updateInput('personnel', newP)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <input
                    type="text"
                    aria-label="Role" placeholder="e.g. Surveyor"
                    value={p.role}
                    onChange={e => {
                      const newP = [...(reportInput.personnel || [])]
                      newP[idx] = { ...newP[idx], role: e.target.value }
                      updateInput('personnel', newP)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <input
                    type="text"
                    aria-label="Qualification" placeholder="e.g. BSc Geomatics"
                    value={p.qualification}
                    onChange={e => {
                      const newP = [...(reportInput.personnel || [])]
                      newP[idx] = { ...newP[idx], qualification: e.target.value }
                      updateInput('personnel', newP)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <button
                    onClick={() => {
                      const newP = (reportInput.personnel || []).filter((_, i) => i !== idx)
                      updateInput('personnel', newP)
                    }}
                    className="text-red-500 text-xs"
                  >
                    [x]
                  </button>
                </div>
              ))}
              <button
                onClick={() => updateInput('personnel', [...(reportInput.personnel || []), { name: '', role: '', qualification: '' }])}
                className="px-3 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs"
              >
                + Add Personnel
              </button>
            </div>
          </div>
        )

      case 'CONTROL_SURVEY':
        return (
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-datum" className="block text-sm font-medium mb-1">Datum</label>
                <select
                  id="sr-datum"
                  value={reportInput.datum || 'ARC1960'}
                  onChange={e => updateInput('datum', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                >
                  <option value="ARC1960">ARC1960</option>
                  <option value="WGS84">WGS84</option>
                </select>
              </div>
              <div>
                <label htmlFor="sr-projection" className="block text-sm font-medium mb-1">Projection</label>
                <input
                  id="sr-projection"
                  type="text"
                  value={reportInput.projection || ''}
                  onChange={e => updateInput('projection', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                  placeholder="e.g., UTM Zone 37S"
                />
              </div>
            </div>
            <div>
              <label htmlFor="sr-gnss-method" className="block text-sm font-medium mb-1">GNSS Method (optional)</label>
              <input
                id="sr-gnss-method"
                type="text"
                value={reportInput.gnssMethod || ''}
                onChange={e => updateInput('gnssMethod', e.target.value)}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                placeholder="e.g., Static GNSS, RTK"
              />
            </div>
            <div>
              <div className="block text-sm font-medium mb-1">Control Points ({reportInput.controlPoints?.length || 0})</div>
              <p className="text-xs text-gray-500 mb-2">Control points are imported from your project survey points.</p>
            </div>
          </div>
        )

      case 'TOPOGRAPHIC_SURVEY':
        return (
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-survey-method" className="block text-sm font-medium mb-1">Survey Method</label>
                <select
                  id="sr-survey-method"
                  value={reportInput.surveyMethod || 'GNSS_RTK'}
                  onChange={e => updateInput('surveyMethod', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                >
                  <option value="TOTAL_STATION">Total Station</option>
                  <option value="GNSS_RTK">GNSS RTK</option>
                  <option value="LEVEL">Level</option>
                  <option value="COMBINED">Combined Methods</option>
                </select>
              </div>
              <div>
                <label htmlFor="sr-instrument" className="block text-sm font-medium mb-1">Instrument Used</label>
                <input
                  id="sr-instrument"
                  type="text"
                  value={reportInput.instrumentUsed || ''}
                  onChange={e => updateInput('instrumentUsed', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                  placeholder="e.g., Trimble S7, Leica GS18"
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-point-density" className="block text-sm font-medium mb-1">Point Density (optional)</label>
                <input
                  id="sr-point-density"
                  type="text"
                  value={reportInput.pointDensity || ''}
                  onChange={e => updateInput('pointDensity', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                  placeholder="e.g., 1 point per 10m²"
                />
              </div>
              <div>
                <label htmlFor="sr-area" className="block text-sm font-medium mb-1">Area (hectares)</label>
                <input id="sr-area"
                  type="number"
                  value={reportInput.areaHectares || ''}
                  onChange={e => updateInput('areaHectares', parseFloat(e.target.value) || undefined)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
            </div>
          </div>
        )

      case 'RESULTS_AND_ACCURACY':
        return (
          <div className="space-y-4">
            <div>
              <label htmlFor="sr-traverse-accuracy" className="block text-sm font-medium mb-1">Traverse Accuracy</label>
              <input
                id="sr-traverse-accuracy"
                type="text"
                value={reportInput.traverseAccuracy || ''}
                onChange={e => updateInput('traverseAccuracy', e.target.value)}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                placeholder="e.g., 1:10,000"
              />
              <p className="text-xs text-gray-500 mt-1">Auto-populated from traverse computations if available.</p>
            </div>
            <div>
              <label htmlFor="sr-levelling-misclosure" className="block text-sm font-medium mb-1">Levelling Misclosure</label>
              <input
                id="sr-levelling-misclosure"
                type="text"
                value={reportInput.levellingMisclosure || ''}
                onChange={e => updateInput('levellingMisclosure', e.target.value)}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                placeholder="e.g., 12.5 mm"
              />
            </div>
          </div>
        )

      case 'CONCLUSIONS_AND_RECOMMENDATIONS':
        return (
          <div className="space-y-4">
            <div>
              <div className="block text-sm font-medium mb-2">Conclusions</div>
              {(reportInput.conclusions || []).map((c, idx) => (
                <div key={`${c}-${idx}`} className="flex gap-2 mb-2">
                  <textarea
                    aria-label={`Conclusion ${idx + 1}`}
                    value={c}
                    onChange={e => {
                      const newC = [...(reportInput.conclusions || [])]
                      newC[idx] = e.target.value
                      updateInput('conclusions', newC)
                    }}
                    rows={2}
                    className="flex-1 px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                  />
                  <button
                    onClick={() => updateInput('conclusions', (reportInput.conclusions || []).filter((_, i) => i !== idx))}
                    className="px-2 text-red-500 hover:bg-red-50 rounded"
                  >
                    [x]
                  </button>
                </div>
              ))}
              <button
                onClick={() => updateInput('conclusions', [...(reportInput.conclusions || []), ''])}
                className="px-3 py-1.5 bg-[var(--accent)] text-black rounded text-xs font-medium"
              >
                + Add Conclusion
              </button>
            </div>
            <div>
              <div className="block text-sm font-medium mb-2">Recommendations</div>
              {(reportInput.recommendations || []).map((r, idx) => (
                <div key={`${r}-${idx}`} className="flex gap-2 mb-2">
                  <textarea
                    aria-label={`Recommendation ${idx + 1}`}
                    value={r}
                    onChange={e => {
                      const newR = [...(reportInput.recommendations || [])]
                      newR[idx] = e.target.value
                      updateInput('recommendations', newR)
                    }}
                    rows={2}
                    className="flex-1 px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                  />
                  <button
                    onClick={() => updateInput('recommendations', (reportInput.recommendations || []).filter((_, i) => i !== idx))}
                    className="px-2 text-red-500 hover:bg-red-50 rounded"
                  >
                    [x]
                  </button>
                </div>
              ))}
              <button
                onClick={() => updateInput('recommendations', [...(reportInput.recommendations || []), ''])}
                className="px-3 py-1.5 bg-[var(--accent)] text-black rounded text-xs font-medium"
              >
                + Add Recommendation
              </button>
            </div>
          </div>
        )

      case 'DECLARATION':
        return (
          <div className="space-y-4">
            <div className="p-3 border border-amber-700/40 bg-amber-950/20 rounded-lg text-xs text-amber-200 leading-6">
              <strong>Survey Regulations 1994, Reg. 3(2)</strong> — Every survey report submitted to the Director of Surveys
              must contain a signed declaration by the licensed surveyor who supervised the work.
            </div>
            <div>
              <label htmlFor="sr-declaration" className="block text-sm font-medium mb-1">Declaration Statement</label>
              <textarea
                id="sr-declaration"
                value={reportInput.declarationStatement || ''}
                onChange={e => updateInput('declarationStatement', e.target.value)}
                rows={14}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm font-mono leading-6"
                placeholder="I, the undersigned, being a Registered Surveyor under the Survey Act (Cap. 299)..."
              />
            </div>
            <button
              onClick={() => updateInput('declarationStatement', DEFAULT_DECLARATION)}
              className="px-4 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs font-medium hover:border-[var(--accent)]"
            >
              Load Standard Declaration Template
            </button>
          </div>
        )

      default:
        return <p className="text-gray-500">No editing available for this section.</p>
    }
  }

  const renderPreview = () => {
    return (
      <div className="bg-white text-black p-8 max-w-[794px] mx-auto shadow-lg min-h-[1123px]">
        {generatedSections.map((section: SectionContent) => (
          <div key={section.section} className={section.sectionNumber > 1 ? 'mt-8' : ''}>
            {section.sectionNumber === 1 ? (
              <div dangerouslySetInnerHTML={{ __html: sanitizeHtml(section.content) }} />
            ) : (
              <>
                <h2 className="text-lg font-bold border-b border-gray-300 pb-2 mb-4">
                  {section.sectionNumber}. {section.title}
                </h2>
                <div dangerouslySetInnerHTML={{ __html: sanitizeHtml(section.content) }} />
              </>
            )}
          </div>
        ))}
      </div>
    )
  }

  if (isGenerating && !generatedSections.length) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="w-8 h-8 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin mx-auto mb-4" />
          <p className="text-[var(--text-muted)]">Generating report...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="flex h-screen overflow-hidden">
      {/* Left Sidebar */}
      <div className="w-72 border-r border-[var(--border-color)] bg-[var(--bg-card)] flex flex-col overflow-hidden">
        <div className="p-4 border-b border-[var(--border-color)]">
          <h1 className="text-lg font-semibold">Survey Report</h1>
          <div className="flex gap-1 mt-3 bg-[var(--bg-tertiary)] p-1 rounded-lg">
            <button
              onClick={() => setMode('edit')}
              className={`flex-1 py-1.5 text-xs font-medium rounded ${mode === 'edit' ? 'bg-[var(--accent)] text-black' : 'text-[var(--text-muted)]'}`}
            >
              Edit
            </button>
            <button
              onClick={() => setMode('preview')}
              className={`flex-1 py-1.5 text-xs font-medium rounded ${mode === 'preview' ? 'bg-[var(--accent)] text-black' : 'text-[var(--text-muted)]'}`}
            >
              Preview
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-2">
          {SECTION_INFO.map((info: (typeof SECTION_INFO)[number]) => (
            <button
              key={info.section}
              onClick={() => setActiveSection(info.section)}
              className={`w-full flex items-center justify-between px-3 py-2 rounded-lg text-sm mb-1 ${
                activeSection === info.section 
                  ? 'bg-blue-50 text-blue-700 border border-blue-200' 
                  : 'hover:bg-[var(--bg-tertiary)]'
              }`}
            >
              <span className="flex items-center gap-2">
                <span className="text-xs text-[var(--text-muted)]">{info.number}.</span>
                <span className="truncate">{info.title}</span>
              </span>
              {getSectionBadge(info)}
            </button>
          ))}
        </div>

        <div className="p-4 border-t border-[var(--border-color)]">
          <div className="text-xs text-[var(--text-muted)] mb-2">
            Report Completeness
          </div>
          <div className="w-full h-2 bg-[var(--bg-tertiary)] rounded-full overflow-hidden">
            <div 
              className="h-full bg-green-500 transition-all"
              style={{ width: `${completeness?.overallPercent || 0}%` }}
            />
          </div>
          <div className="flex justify-between text-xs mt-1">
            <span className="text-[var(--text-muted)]">{completeness?.overallPercent || 0}% complete</span>
            <span className="text-[var(--text-muted)]">{completeness?.sectionsComplete || 0} of 15 sections</span>
          </div>
        </div>

        <div className="p-4 border-t border-[var(--border-color)] space-y-2">
          <button
            onClick={saveReport}
            disabled={isSaving}
            className="w-full px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] border border-[var(--border-color)] rounded-lg text-sm font-medium disabled:opacity-50"
          >
            {isSaving ? 'Saving...' : 'Save Draft'}
          </button>
          <button
            onClick={saveReport}
            disabled={!completeness?.readyToFinalise || isSaving}
            className="w-full px-4 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black rounded-lg text-sm font-medium disabled:opacity-40 disabled:cursor-not-allowed"
            title={!completeness?.readyToFinalise ? 'Complete all required sections to finalise' : ''}
          >
            Finalise Report
          </button>
        </div>
      </div>

      {/* Right Panel */}
      <div className="flex-1 overflow-y-auto p-8 bg-[var(--bg-primary)]">
        {error && (
          <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm">
            {error}
          </div>
        )}

        {mode === 'edit' ? (
          <div className="max-w-2xl mx-auto">
            <div className="mb-6">
              <h2 className="text-xl font-semibold">
                Section {SECTION_INFO.find((s: (typeof SECTION_INFO)[number]) => s.section === activeSection)?.number} — {SECTION_INFO.find((s: (typeof SECTION_INFO)[number]) => s.section === activeSection)?.title}
              </h2>
            </div>
            {renderSectionForm()}
          </div>
        ) : (
          <div>
            <div className="sticky top-0 bg-[var(--bg-primary)] py-4 border-b border-[var(--border-color)] mb-6 flex gap-2 no-print print-hide">
              <PrintButton
                print={print}
                isPrinting={isPrinting}
                paperSize={paperSize}
                setPaperSize={setPaperSize}
                orientation={orientation}
                setOrientation={setOrientation}
                printTitle="Survey Report"
              />
              <button
                onClick={() => exportReport('pdf')}
                className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-medium"
              >
                Download PDF
              </button>
              <button
                onClick={() => exportReport('docx')}
                className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-medium"
              >
                Download Word
              </button>
            </div>
            <PrintHeader title="Survey Report" />
            {renderPreview()}
          </div>
        )}
      </div>
    </div>
  )
}

'use client';

import { useState } from 'react'
import { AlertTriangle } from 'lucide-react'
import { useLanguage } from '@/lib/i18n/LanguageContext'
import { usePrint, PrintButton, PrintHeader } from '@/hooks/usePrint'
import { useCountry } from '@/lib/country'
import RegistryIndexMap from './RegistryIndexMap'
import { formatAreaByCountry, getTraverseValidation } from '@/lib/engine/country-math'
import type { SurveyEnvironment } from '@/lib/country'

interface FieldCondition {
  id: string
  value: string
}

interface FixedPoint {
  id: string
  pointRef: string
  description: string
  usedForFixation: boolean
}

interface Discrepancy {
  id: string
  type: 'encroachment' | 'shortfall' | 'service_clash' | 'planning_conflict' | 'other'
  description: string
  suggestedSolution: string
}

interface SurveyReportProps {
  isOpen: boolean
  onClose: () => void
  jobNo?: string
  parcelAreaSqM?: number
  parcelDescription?: string
  environment?: SurveyEnvironment
  precisionRatio?: number
  linearError?: number
  totalDistance?: number
}

const FIELD_CONDITIONS = [
  'Open / undeveloped',
  'Built-up / urban',
  'Dense vegetation',
  'Coastal / marine',
  'Reclaimed land',
  'Rocky / mountainous',
  'Agricultural / rural',
] as const

const DISCREPANCY_TYPES = [
  { value: 'encroachment', label: 'Encroachment' },
  { value: 'shortfall', label: 'Shortfall' },
  { value: 'service_clash', label: 'Service / utility clash' },
  { value: 'planning_conflict', label: 'Planning intention conflict' },
  { value: 'other', label: 'Other' },
] as const

const SURVEY_METHODS = [
  'RTK GPS (PRN/base station)',
  'Conventional Total Station',
  'Taped offsets',
  'Tacheometry',
  'Static GPS',
  'Hybrid (GPS + TS)',
  'Aerial / drone mapping',
  'Lidar',
] as const

export default function SurveyReport({
  isOpen,
  onClose,
  jobNo: initialJobNo = '',
  parcelAreaSqM = 0,
  parcelDescription: initialParcelDesc = '',
  environment: initialEnv = 'rural',
  precisionRatio,
  linearError,
  totalDistance,
}: SurveyReportProps) {
  const { t } = useLanguage()
  const { standard, country, getTraverseOrder, getAreaRule } = useCountry()

  const [surveyorName, setSurveyorName] = useState('')
  const [date, setDate] = useState(new Date().toISOString().split('T')[0])
  const [jobNo, setJobNo] = useState(initialJobNo)
  const [parcelDescription, setParcelDescription] = useState(initialParcelDesc)
  const [fieldConditions, setFieldConditions] = useState<FieldCondition[]>([])
  const [boundaryDescription, setBoundaryDescription] = useState('')
  const [fixedPoints, setFixedPoints] = useState<FixedPoint[]>([
    { id: '1', pointRef: '', description: '', usedForFixation: true },
  ])
  const [locationMethod, setLocationMethod] = useState('')
  const [surveyMethods, setSurveyMethods] = useState<string[]>([])
  const [equipment, setEquipment] = useState('')
  const [accuracyNotes, setAccuracyNotes] = useState('')
  const [fieldChecks, setFieldChecks] = useState('')
  const [areaCalcMethod, setAreaCalcMethod] = useState('coordinate')
  const [difficulties, setDifficulties] = useState('')
  const [discrepancies, setDiscrepancies] = useState<Discrepancy[]>([])
  const [certificateText, setCertificateText] = useState(
    'I certify that this survey was carried out in compliance with all applicable Survey Regulations and Technical Instructions.'
  )
  const [supervisorName, setSupervisorName] = useState('')
  const [validated, setValidated] = useState(false)
  const [validationErrors, setValidationErrors] = useState<string[]>([])
  const [showRIM, setShowRIM] = useState(false)

  const { print, isPrinting, paperSize, setPaperSize, orientation, setOrientation } = usePrint({ title: 'Survey Report' })

  if (!isOpen) return null

  const rimData = { district: '', location: '', parcels: [] as Array<{ value: string }> }

  const areaResult = parcelAreaSqM > 0 ? formatAreaByCountry(country, parcelAreaSqM) : null

  const precisionValidation = (precisionRatio && linearError && totalDistance)
    ? getTraverseValidation({ country, environment: initialEnv, linearError, totalDistance })
    : null

  function toggleCondition(c: string) {
    setFieldConditions(prev =>
      prev.some((x) => x.value === c)
        ? prev.filter((x) => x.value !== c)
        : [...prev, { id: crypto.randomUUID(), value: c }]
    )
  }

  function toggleMethod(m: string) {
    setSurveyMethods(prev =>
      prev.includes(m) ? prev.filter((x) => x !== m) : [...prev, m]
    )
  }

  function addFixedPoint() {
    setFixedPoints(prev => [...prev, { id: crypto.randomUUID(), pointRef: '', description: '', usedForFixation: true }])
  }

  function removeFixedPoint(id: string) {
    setFixedPoints(prev => prev.filter((p) => p.id !== id))
  }

  function addDiscrepancy() {
    setDiscrepancies(prev => [...prev, { id: crypto.randomUUID(), type: 'other', description: '', suggestedSolution: '' }])
  }

  function removeDiscrepancy(id: string) {
    setDiscrepancies(prev => prev.filter((d) => d.id !== id))
  }

  function validateReport(): string[] {
    const errors: string[] = []
    if (surveyMethods.length === 0) errors.push('At least one survey method must be selected.')
    if (!boundaryDescription.trim()) errors.push('Boundary description is required.')
    if (!certificateText.trim()) errors.push('Certificate of compliance text is required.')
    return errors
  }

  function handleValidate() {
    const errors = validateReport()
    setValidationErrors(errors)
    setValidated(errors.length === 0)
  }

  const SectionHeader = ({ children }: { children: React.ReactNode }) => (
    <div className="text-xs font-semibold text-gray-500 uppercase tracking-wider mt-4 mb-2">
      {children}
    </div>
  )

  const FieldLabel = ({ children, required, htmlFor }: { children: React.ReactNode; required?: boolean; htmlFor?: string }) => (
    <label htmlFor={htmlFor} className="block text-sm font-medium text-gray-700 mb-1">
      {children}{required && <span className="text-red-500 ml-0.5">*</span>}
    </label>
  )

  const Input = ({ className = '', ...props }: React.InputHTMLAttributes<HTMLInputElement>) => (
    <input
      className={`w-full border border-gray-300 rounded px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${className}`}
      {...props}
    />
  )

  const Textarea = ({ className = '', ...props }: React.TextareaHTMLAttributes<HTMLTextAreaElement>) => (
    <textarea
      className={`w-full border border-gray-300 rounded px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 resize-y ${className}`}
      {...props}
    />
  )

  const Select = ({ className = '', ...props }: React.SelectHTMLAttributes<HTMLSelectElement>) => (
    <select
      className={`w-full border border-gray-300 rounded px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${className}`}
      {...props}
    >
      {props.children}
    </select>
  )

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-start justify-center overflow-y-auto p-4">
      <PrintHeader title="Survey Report" subtitle={jobNo || undefined} />
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[95vh] overflow-y-auto">
        <div className="sticky top-0 bg-white border-b border-gray-200 px-6 py-4 flex items-center justify-between rounded-t-xl z-10">
          <div>
            <h2 className="text-lg font-bold text-gray-900">
              {t('surveyReport.title')}
            </h2>
            <p className="text-xs text-gray-500 mt-0.5">
              {t('surveyReport.subtitle')}
            </p>
          </div>
          <div className="flex gap-2 no-print print-hide">
            <PrintButton
              print={print}
              isPrinting={isPrinting}
              paperSize={paperSize}
              setPaperSize={setPaperSize}
              orientation={orientation}
              setOrientation={setOrientation}
              printTitle="Survey Report"
              printSubtitle={jobNo || undefined}
            />
            <button
              onClick={onClose}
              className="px-3 py-1.5 text-sm border border-gray-300 rounded hover:bg-gray-50"
            >
              {t('common.close')}
            </button>
          </div>
        </div>

        <div className="px-6 py-4 space-y-4">
          <div className="bg-blue-50 border border-blue-200 rounded-lg px-3 py-2 text-xs text-blue-800 flex flex-wrap gap-4">
            <span><strong>{standard.name}</strong> ({standard.isoCode})</span>
            <span>Datum: <strong>{standard.datum}</strong> / {standard.ellipsoid}</span>
            <span>UTM Zone{standard.utmZones.length > 1 ? 's' : ''}: <strong>{standard.utmZones.join(', ')}</strong> {standard.utmHemisphere}</span>
            <span>Traverse: <strong>1:{getTraverseOrder(initialEnv)?.minPrecision.toLocaleString() ?? '—'}</strong></span>
            {standard.parcelMinArea && (
              <span>Min parcel: <strong>{standard.parcelMinArea.sqMetres} m²</strong></span>
            )}
          </div>
          <div className="grid grid-cols-3 gap-4">
            <div>
              <FieldLabel required htmlFor="sr-job-no">{t('surveyReport.jobNo')}</FieldLabel>
              <Input id="sr-job-no" value={jobNo} onChange={e => setJobNo(e.target.value)} placeholder="e.g. SD-2024-00123" />
            </div>
            <div>
              <FieldLabel required htmlFor="sr-surveyor">{t('surveyReport.surveyor')}</FieldLabel>
              <Input id="sr-surveyor"
                value={surveyorName}
                onChange={e => setSurveyorName(e.target.value.toUpperCase())}
                placeholder="JOHN M. KARIUKI"
                className="uppercase"
              />
            </div>
            <div>
              <FieldLabel required htmlFor="sr-date">{t('surveyReport.date')}</FieldLabel>
              <Input id="sr-date" type="date" value={date} onChange={e => setDate(e.target.value)} />
            </div>
          </div>

          <SectionHeader>{t('surveyReport.parcelInfo')}</SectionHeader>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <FieldLabel htmlFor="sr-parcel-desc">{t('surveyReport.parcelDesc')}</FieldLabel>
              <Input id="sr-parcel-desc"
                value={parcelDescription}
                onChange={e => setParcelDescription(e.target.value)}
                placeholder="Urban residential plot, Block 12, Dagoretti"
              />
            </div>
            <div>
              <FieldLabel htmlFor="sr-env">{t('surveyReport.environment')}</FieldLabel>
              <Select id="sr-env" value={initialEnv} disabled>
                <option value="urban">{t('surveyReport.envUrban')}</option>
                <option value="rural">{t('surveyReport.envRural')}</option>
                <option value="transmission_line">{t('surveyReport.envTransmission')}</option>
                <option value="detail">{t('surveyReport.envDetail')}</option>
              </Select>
            </div>
          </div>

          <div>
            <FieldLabel>{t('surveyReport.fieldConditions')}</FieldLabel>
            <div className="flex flex-wrap gap-2">
              {FIELD_CONDITIONS.map((c) => (
                <button
                  key={c}
                  onClick={() => toggleCondition(c)}
                  className={`px-3 py-1 text-xs rounded-full border transition-colors ${
                    fieldConditions.some((x) => x.value === c)
                      ? 'bg-blue-600 text-white border-blue-600'
                      : 'border-gray-300 text-gray-700 hover:border-blue-400'
                  }`}
                >
                  {c}
                </button>
              ))}
            </div>
          </div>

          <SectionHeader>{t('surveyReport.boundarySection')}</SectionHeader>
          <div>
            <FieldLabel required htmlFor="sr-boundary">{t('surveyReport.boundaryDesc')}</FieldLabel>
            <Textarea id="sr-boundary"
              rows={3}
              value={boundaryDescription}
              onChange={e => setBoundaryDescription(e.target.value)}
              placeholder="Parcel bounded on N by Road reserve (15m), E by remaining parent parcel..., etc."
            />
            <p className="text-xs text-gray-500 mt-1">
              {t('surveyReport.boundaryHint')}
            </p>
          </div>

          <SectionHeader>{t('surveyReport.controlSection')}</SectionHeader>

          <div>
            <div className="flex items-center justify-between mb-2">
              <FieldLabel>{t('surveyReport.fixedPoints')}</FieldLabel>
              <button
                onClick={addFixedPoint}
                className="text-xs text-blue-600 hover:underline"
              >
                + {t('surveyReport.addPoint')}
              </button>
            </div>
            <div className="space-y-2">
              {fixedPoints.map((fp, i) => (
                <div key={fp.id} className="grid grid-cols-3 gap-2 items-center">
                  <Input
                    value={fp.pointRef}
                    onChange={e => {
                      const updated = [...fixedPoints]
                      updated[i].pointRef = e.target.value
                      setFixedPoints(updated)
                    }}
                    placeholder={`Point ref (e.g. RM-001)`}
                    aria-label="Fixed point reference"
                  />
                  <Input
                    value={fp.description}
                    onChange={e => {
                      const updated = [...fixedPoints]
                      updated[i].description = e.target.value
                      setFixedPoints(updated)
                    }}
                    placeholder="Description / condition"
                    aria-label="Fixed point description"
                  />
                  <button
                    onClick={() => removeFixedPoint(fp.id)}
                    className="text-xs text-red-500 hover:underline"
                  >
                    {t('common.remove')}
                  </button>
                </div>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <FieldLabel htmlFor="sr-location-method">{t('surveyReport.locationMethod')}</FieldLabel>
              <Select id="sr-location-method" value={locationMethod} onChange={e => setLocationMethod(e.target.value)}>
                <option value="">{t('common.select')}</option>
                <option value="polar">{t('surveyReport.methodPolar')}</option>
                <option value="intersection">{t('surveyReport.methodIntersection')}</option>
                <option value="resection">{t('surveyReport.methodResection')}</option>
                <option value="gps_rtk">{t('surveyReport.methodRTK')}</option>
                <option value="tape_offset">{t('surveyReport.methodTapeOffset')}</option>
              </Select>
            </div>
            <div>
              <FieldLabel htmlFor="sr-area-method">{t('surveyReport.areaMethod')}</FieldLabel>
              <Select id="sr-area-method" value={areaCalcMethod} onChange={e => setAreaCalcMethod(e.target.value)}>
                <option value="coordinate">{t('surveyReport.areaCoord')}</option>
                <option value="subdivision">{t('surveyReport.areaSubdiv')}</option>
                <option value="decomposition">{t('surveyReport.areaDecomp')}</option>
                <option value="graphic">{t('surveyReport.areaGraphic')}</option>
              </Select>
            </div>
          </div>

          <SectionHeader>{t('surveyReport.methodsSection')}</SectionHeader>
          <div>
            <FieldLabel required>{t('surveyReport.surveyMethods')}</FieldLabel>
            <div className="flex flex-wrap gap-2">
              {SURVEY_METHODS.map((m) => (
                <button
                  key={m}
                  onClick={() => toggleMethod(m)}
                  className={`px-3 py-1 text-xs rounded-full border transition-colors ${
                    surveyMethods.includes(m)
                      ? 'bg-blue-600 text-white border-blue-600'
                      : 'border-gray-300 text-gray-700 hover:border-blue-400'
                  }`}
                >
                  {m}
                </button>
              ))}
            </div>
          </div>

          <div>
            <FieldLabel htmlFor="sr-equipment">{t('surveyReport.equipment')}</FieldLabel>
            <Input id="sr-equipment"
              value={equipment}
              onChange={e => setEquipment(e.target.value)}
              placeholder="Leica TS16, Trimble R12i RTK GPS, 50m steel tape..."
            />
          </div>

          <SectionHeader>{t('surveyReport.accuracySection')}</SectionHeader>

          {precisionValidation && (
            <div className={`rounded-lg p-3 text-sm ${
              precisionValidation.isAcceptable
                ? 'bg-green-50 border border-green-200'
                : 'bg-amber-50 border border-amber-200'
            }`}>
              <div className="flex items-center justify-between mb-1">
                <div className="font-medium">
                  {t('surveyReport.traverseAccuracy')}
                </div>
                <span className="text-xs px-2 py-0.5 rounded bg-blue-100 text-blue-800">
                  {standard.isoCode} · {precisionValidation.jurisdiction.toUpperCase()}
                </span>
              </div>
              <div className="grid grid-cols-2 gap-x-6 gap-y-1 text-xs">
                <div>Achieved: <strong>1:{Math.round(precisionValidation.achievedRatio).toLocaleString()}</strong></div>
                <div>Required: <strong>1:{precisionValidation.requiredRatio.toLocaleString()}</strong></div>
                <div>Order: <strong>{precisionValidation.orderLabel.replace('_', ' ').toUpperCase()}</strong></div>
                <div>Linear error: <strong>{precisionValidation.linearError.toFixed(4)} m</strong></div>
                <div className="col-span-2 text-gray-500">Regulation: {precisionValidation.regulation}</div>
                {precisionValidation.warnings.map((w, i) => (
                  <div key={`${w}-${i}`} className="col-span-2 text-amber-700 mt-1"><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> {w}</div>
                ))}
              </div>
            </div>
          )}

          <div>
            <FieldLabel htmlFor="sr-accuracy-notes">{t('surveyReport.accuracyNotes')}</FieldLabel>
            <Textarea id="sr-accuracy-notes"
              rows={2}
              value={accuracyNotes}
              onChange={e => setAccuracyNotes(e.target.value)}
              placeholder="Traverse closure: 1:24,500. EDM check: ±15mm. GPS occupation: 0.5 min per point..."
            />
          </div>

          <div>
            <FieldLabel htmlFor="sr-field-checks">{t('surveyReport.fieldChecks')}</FieldLabel>
            <Textarea id="sr-field-checks"
              rows={2}
              value={fieldChecks}
              onChange={e => setFieldChecks(e.target.value)}
              placeholder="Independent check measurement to RM-042: 0.005m difference. Second face observations: all within 20 arcsec..."
            />
          </div>

          <div className="flex items-center justify-between">
            <SectionHeader>{t('surveyReport.areaSection')}</SectionHeader>
            {country === 'kenya' && parcelAreaSqM > 0 && (
              <button
                onClick={() => setShowRIM(true)}
                className="px-3 py-1 text-xs bg-amber-100 text-amber-800 border border-amber-300 rounded hover:bg-amber-200 flex items-center gap-1"
              >
                [Clip] Generate RIM (Kenya)
              </button>
            )}
          </div>
          {areaResult ? (
            <div className="grid grid-cols-4 gap-4">
              <div>
                <span className="text-sm text-gray-600">{t('surveyReport.area')}</span>
                <div className="font-semibold text-lg">{areaResult.formattedHa} ha</div>
                <div className="text-xs text-gray-500">{areaResult.regulation}</div>
              </div>
              <div>
                <span className="text-sm text-gray-600">{t('surveyReport.areaSqM')}</span>
                <div className="font-semibold">{areaResult.formattedM2} m²</div>
              </div>
              <div>
                <span className="text-sm text-gray-600">{t('surveyReport.decimalPlaces')}</span>
                <div className="font-semibold">{areaResult.decimalPlaces}</div>
              </div>
              <div>
                <span className="text-sm text-gray-600">{t('surveyReport.countryStd')}</span>
                <div className="font-semibold text-xs">{standard.name}</div>
                <div className="text-xs text-gray-500">{standard.isoCode} — {standard.datum}</div>
              </div>
              {areaResult.warnings.length > 0 && (
                <div className="col-span-4">
                  {areaResult.warnings.map((w, i) => (
                    <div key={`${w}-${i}`} className="text-xs text-amber-600"><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> {w}</div>
                  ))}
                </div>
              )}
            </div>
          ) : (
            <p className="text-sm text-gray-400 italic">{t('surveyReport.noArea')}</p>
          )}

          <SectionHeader>{t('surveyReport.difficultiesSection')}</SectionHeader>
          <div>
            <FieldLabel htmlFor="sr-difficulties">{t('surveyReport.difficulties')}</FieldLabel>
            <Textarea id="sr-difficulties"
              rows={2}
              value={difficulties}
              onChange={e => setDifficulties(e.target.value)}
              placeholder="Beacon CM-07 destroyed — recovered from witness marks. Dense vegetation obscured line of sight..."
            />
          </div>

          <div>
            <div className="flex items-center justify-between mb-2">
              <FieldLabel>{t('surveyReport.discrepancies')}</FieldLabel>
              <button
                onClick={addDiscrepancy}
                className="text-xs text-blue-600 hover:underline"
              >
                + {t('surveyReport.addDiscrepancy')}
              </button>
            </div>
            <div className="space-y-3">
              {discrepancies.map((d) => (
                <div key={d.id} className="grid grid-cols-3 gap-2 p-3 bg-gray-50 rounded">
                  <div>
                    <FieldLabel htmlFor={`sr-disc-type-${d.id}`}>{t('surveyReport.discType')}</FieldLabel>
                    <Select id={`sr-disc-type-${d.id}`}
                      value={d.type}
                      onChange={e => {
                        const updated = discrepancies.map((x) => x.id === d.id ? { ...x, type: e.target.value as Discrepancy['type'] } : x)
                        setDiscrepancies(updated)
                      }}
                    >
                      {DISCREPANCY_TYPES.map((t) => (
                        <option key={t.value} value={t.value}>{t.label}</option>
                      ))}
                    </Select>
                  </div>
                  <div className="col-span-2">
                    <FieldLabel htmlFor={`sr-disc-desc-${d.id}`}>{t('surveyReport.discDesc')}</FieldLabel>
                    <Textarea id={`sr-disc-desc-${d.id}`}
                      rows={2}
                      placeholder="Describe and suggest a resolution..."
                      value={d.description}
                      onChange={e => {
                        const updated = discrepancies.map((x) => x.id === d.id ? { ...x, description: e.target.value } : x)
                        setDiscrepancies(updated)
                      }}
                    />
                  </div>
                  <div className="col-span-3 text-right">
                    <button
                      onClick={() => removeDiscrepancy(d.id)}
                      className="text-xs text-red-500 hover:underline"
                    >
                      {t('common.remove')}
                    </button>
                  </div>
                </div>
              ))}
              {discrepancies.length === 0 && (
                <p className="text-xs text-gray-400 italic">
                  {t('surveyReport.noDiscrepancies')}
                </p>
              )}
            </div>
          </div>

          <SectionHeader>{t('surveyReport.certificate')}</SectionHeader>
          <div>
            <Textarea
              rows={3}
              aria-label={t('surveyReport.certificate')}
              value={certificateText}
              onChange={e => setCertificateText(e.target.value)}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <FieldLabel>{t('surveyReport.signature')}</FieldLabel>
              <div className="border-b border-gray-400 pb-1 mt-6 text-sm font-medium uppercase">
                {surveyorName || <span className="text-gray-300 italic">{t('surveyReport.signHere')}</span>}
              </div>
              <div className="text-xs text-gray-500 mt-1">{surveyorName}</div>
            </div>
            <div>
              <FieldLabel htmlFor="sr-supervisor">{t('surveyReport.supervisor')}</FieldLabel>
              <Input id="sr-supervisor"
                value={supervisorName}
                onChange={e => setSupervisorName(e.target.value.toUpperCase())}
                placeholder="SUPERVISOR NAME"
                className="uppercase"
              />
              <div className="border-b border-gray-400 pb-1 mt-4 text-sm font-medium uppercase">
                {supervisorName || <span className="text-gray-300 italic">{t('surveyReport.signHere')}</span>}
              </div>
            </div>
          </div>
        </div>

        <div className="sticky bottom-0 bg-gray-50 border-t border-gray-200 px-6 py-4 flex items-center justify-between rounded-b-xl">
          {validated ? (
            <div className="text-sm text-green-600 font-medium">
               {t('surveyReport.validated')}
            </div>
          ) : validationErrors.length > 0 ? (
            <div className="text-sm text-red-600">
              {validationErrors.map((e, i) => <div key={`${e}-${i}`}>[x] {e}</div>)}
            </div>
          ) : (
            <div className="text-xs text-gray-500">
              {t('surveyReport.validationHint')}
            </div>
          )}
          <div className="flex gap-2 no-print print-hide">
            <button
              onClick={handleValidate}
              className="px-4 py-1.5 text-sm bg-blue-600 text-white rounded hover:bg-blue-700"
            >
              {t('surveyReport.validate')}
            </button>
            <PrintButton
              print={print}
              isPrinting={isPrinting}
              paperSize={paperSize}
              setPaperSize={setPaperSize}
              orientation={orientation}
              setOrientation={setOrientation}
              printTitle="Survey Report"
              printSubtitle={jobNo || undefined}
            />
          </div>
        </div>
      </div>

      <RegistryIndexMap
        isOpen={showRIM}
        onClose={() => setShowRIM(false)}
        initialData={{
          district: 'KAJIADO',
          location: locationMethod || 'ILKISONGO',
          registrationUnit: jobNo || 'ENTARARA',
          sheetNumber: '1',
          edition: '1ST EDITION',
          scale: '1:2,500',
          parcels: parcelAreaSqM > 0 ? [{
            id: crypto.randomUUID(),
            number: '1',
            x: 40, y: 40, width: 180, height: 120,
            area: (parcelAreaSqM / 10_000).toFixed(4),
            description: parcelDescription || 'Parcel 1',
            color: '#fef3c7',
          }] : [],
        }}
      />
    </div>
  )
}

