  className?: string;
  from?: string;
  via?: string;
  to?: string;
}) {
  // v0.3: gradient text is banned by impeccable skill. Solid accent color instead.
  return (
    <span
      className={cn(
        "inline-block text-[var(--accent)]",
        className
      )}
    >
      {children}
    </span>
