  const BTN = 'w-7 h-7 flex items-center justify-center rounded-md bg-[#14141e]/90 border border-white/[0.08] hover:bg-[#14141e] text-gray-400 hover:text-white transition-colors';

  return (
    <MapEB>
      <div className="h-full w-full relative bg-[#0a0a0f]">
        <div ref={containerRef} className="w-full h-full" />

        {!ready && (
          <div className="absolute inset-0 flex items-center justify-center bg-[#0a0a0f]/80 z-10">
            <div className="text-center">
              <div className="w-6 h-6 border-2 border-[#D17B47] border-t-transparent rounded-full animate-spin mx-auto mb-2" />
              <p className="text-xs text-gray-500">Loading map...</p>
            </div>
          </div>
        )}

        {ready && (
          <>
            {/* Controls - top right */}
            <div className="absolute top-2 right-2 z-10 flex flex-col gap-1">
              <button onClick={fitProject} title="Fit to project" className={BTN}>
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                </svg>
              </button>
              <button onClick={() => zoomBy(1)} title="Zoom in" className={BTN}>
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v12m6-6H6" />
                </svg>
              </button>
              <button onClick={() => zoomBy(-1)} title="Zoom out" className={BTN}>
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M18 12H6" />
                </svg>
              </button>
              <div className="w-full h-px bg-white/[0.06] my-0.5" />
              <button onClick={() => toggleBasemap('osm')} title="OSM" className={BTN}>
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7" />
                </svg>
              </button>
              <button onClick={() => toggleBasemap('satellite')} title="Satellite" className={BTN}>
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M3.055 11H5a2 2 0 012 2v1a2 2 0 002 2 2 2 0 012 2v2.945M8 3.935V5.5A2.5 2.5 0 0010.5 8h.5a2 2 0 012 2 2 2 0 104 0 2 2 0 012-2h1.064M15 20.488V18a2 2 0 012-2h3.064M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </button>
            </div>

            {/* Station badge - top left */}
            {stationCount > 0 && (
              <div className="absolute top-2 left-2 z-10">
                <div className="bg-[#14141e]/90 border border-white/[0.08] rounded-full px-2.5 py-1">
                  <span className="text-xs text-[#D17B47] font-semibold">{stationCount} beacon{stationCount > 1 ? 's' : ''}</span>
                </div>
              </div>
            )}

            {/* Coordinate bar - bottom */}
            <div className="absolute bottom-0 left-0 right-0 z-10">
              <div ref={coordBarRef} className="mx-2 mb-2 h-7 bg-[#14141e]/90 border border-white/[0.06] rounded-md flex items-center justify-center px-3">
                <span className="text-xs text-gray-600">Move cursor for coordinates</span>
              </div>
            </div>
          </>
        )}
      </div>
    </MapEB>
  );
}

/**
 * Centralised fetch wrapper for API calls used by React Query hooks.
 *
 * - Automatically handles JSON parsing
 * - Redirects to /login on 401 responses
 * - Throws typed errors for React Query's error handling
 */

export class ApiError extends Error {
  status: number
  code?: string

  constructor(message: string, status: number, code?: string) {
    super(message)
    this.name = 'ApiError'
    this.status = status
    this.code = code
  }
}

export async function apiFetch<T>(
  input: RequestInfo | URL,
  init?: RequestInit
): Promise<T> {
  const url = typeof input === 'string' ? input : input instanceof URL ? input.toString() : input.url

  const response = await fetch(input, {
    ...init,
    headers: {
      'Content-Type': 'application/json',
      ...init?.headers,
    },
  })

  if (response.status === 401) {
    if (typeof window !== 'undefined') {
      window.location.href = '/login'
    }
    throw new ApiError('Unauthorized', 401, 'UNAUTHORIZED')
  }

  if (!response.ok) {
    let errorMessage = `Request failed: ${response.status} ${response.statusText}`
    let errorCode: string | undefined

    try {
      const body = (await response.json()) as { error?: string; code?: string }
      if (body.error) errorMessage = body.error
      if (body.code) errorCode = body.code
    } catch {
      // response body is not JSON — use default message
    }

    throw new ApiError(errorMessage, response.status, errorCode)
  }

  return response.json() as Promise<T>
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { apiFetch, ApiError } from './fetcher'

// ── Types inferred from API responses ──────────────────────────────────

export interface AuditEvent {
  id: string
  table_name: string
  row_id: string
  user_id: string
  user_email?: string | null
  action: string
  summary?: string | null
  prev_hash: string
  hash: string
  created_at: string
  payload?: Record<string, unknown> | null
}

interface AuditEventsResponse {
  events: AuditEvent[]
  count: number
}

export interface VerifyPayload {
  row_id: string
  table_name: 'project_fieldbook_entries' | 'survey_points'
}

interface VerifyValidResponse {
  valid: true
  events: number
  last_hash: string
  last_action: string
}

interface VerifyInvalidResponse {
  valid: false
  broken_at: string
  broken_at_action: string
  expected_prev: string
  actual_prev: string
  events: number
}

interface VerifyEmptyResponse {
  valid: true
  events: 0
  message: string
}

export type VerifyResponse =
  | VerifyValidResponse
  | VerifyInvalidResponse
  | VerifyEmptyResponse

// ── Cache keys ─────────────────────────────────────────────────────────

export const auditKeys = {
  all: ['audit'] as const,
  byProject: (projectId: string) => [...auditKeys.all, projectId] as const,
  events: (projectId: string, limit?: number) =>
    [...auditKeys.byProject(projectId), 'events', limit] as const,
  verify: () => [...auditKeys.all, 'verify'] as const,
}

// ── Default stale time for audit queries ───────────────────────────────

const AUDIT_STALE_TIME = 2 * 60 * 1000 // 2 minutes

// ── Hooks ──────────────────────────────────────────────────────────────

/**
 * Fetch audit events for a given project.
 * Uses refetchOnWindowFocus: false — audit data is append-only
 * and does not change retroactively.
 */
export function useAuditEvents(
  projectId: string | undefined,
  options?: { limit?: number; enabled?: boolean }
) {
  const limit = options?.limit ?? 100
  const enabled = options?.enabled !== false && !!projectId

  const query = useQuery<AuditEventsResponse, ApiError>({
    queryKey: auditKeys.events(projectId ?? '', limit),
    queryFn: () => {
      const params = new URLSearchParams({ project_id: projectId!, limit: String(limit) })
      return apiFetch<AuditEventsResponse>(`/api/fieldbook/audit?${params.toString()}`)
    },
    enabled,
    staleTime: AUDIT_STALE_TIME,
    refetchOnWindowFocus: false,
  })

  return {
    events: query.data?.events ?? [],
    count: query.data?.count ?? 0,
    isLoading: query.isLoading,
    error: query.error,
    isFetching: query.isFetching,
    refetch: query.refetch,
  }
}

/**
 * Verify the integrity of the audit hash chain for a specific row.
 */
export function useVerifyAuditChain() {
  const queryClient = useQueryClient()

  return useMutation<VerifyResponse, ApiError, VerifyPayload>({
    mutationFn: (payload) =>
      apiFetch<VerifyResponse>('/api/fieldbook/audit/verify', {
        method: 'POST',
        body: JSON.stringify(payload),
      }),

    onSuccess: () => {
      // Invalidate audit caches so the UI reflects any updated state
      queryClient.invalidateQueries({ queryKey: auditKeys.all })
    },
  })
}

"use client"

// Inspired by react-hot-toast library
import * as React from "react"

import type {
  ToastActionElement,
  ToastProps,
} from "@/components/ui/toast"

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
    type: ActionType["ADD_TOAST"]
    toast: ToasterToast
  }
  | {
    type: ActionType["UPDATE_TOAST"]
    toast: Partial<ToasterToast>
  }
  | {
    type: ActionType["DISMISS_TOAST"]
    toastId?: ToasterToast["id"]
  }
  | {
    type: ActionType["REMOVE_TOAST"]
    toastId?: ToasterToast["id"]
  }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t
        ),
      }

    case "DISMISS_TOAST": {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
              ...t,
              open: false,
            }
            : t
        ),
      }
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, "id">

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  }
}

export { useToast, toast }

'use client';

/**
 * useHotkeys — Global keyboard shortcut system for METARDU.
 * ──────────────────────────────────────────────────────────────
 * Registers keyboard shortcuts that work anywhere in the app.
 * Supports:
 *   - Modifier combos: Ctrl+Z, Ctrl+Shift+N, Alt+Enter
 *   - Single keys: Escape, Delete, ?
 *   - Scoped shortcuts (only active when a specific element is focused)
 *   - Descriptions for the shortcut help overlay (? key)
 *
 * Usage:
 *   useHotkeys('ctrl+z', handleUndo, { description: 'Undo last action' })
 *   useHotkeys('ctrl+shift+z', handleRedo, { description: 'Redo' })
 *   useHotkeys('escape', handleDismiss, { description: 'Close modal' })
 *   useHotkeys('?', () => setShowHelp(true), { description: 'Show shortcuts' })
 */

import { useEffect, useCallback, useRef } from 'react';

interface HotkeyOptions {
  /** Human-readable description for the help overlay */
  description?: string;
  /** Only fire when this element or its descendants are focused */
  scope?: string;
  /** Prevent default browser behavior (default: true) */
  preventDefault?: boolean;
  /** Enable in input/textarea/select (default: false) */
  enableInInput?: boolean;
  /** Disable the shortcut */
  disabled?: boolean;
}

export interface HotkeyRegistration {
  keys: string;
  description: string;
}

// Global registry for the help overlay
const globalRegistry: HotkeyRegistration[] = [];

if (typeof window !== 'undefined') {
  (window as unknown as { __metarduHotkeys?: HotkeyRegistration[] }).__metarduHotkeys = globalRegistry;
}

/**
 * Parse a key combo string into its components.
 * Examples:
 *   'ctrl+z'           → { ctrl: true, shift: false, alt: false, meta: false, key: 'z' }
 *   'ctrl+shift+n'     → { ctrl: true, shift: true, alt: false, meta: false, key: 'n' }
 *   'escape'           → { ctrl: false, shift: false, alt: false, meta: false, key: 'escape' }
 *   'alt+enter'        → { ctrl: false, shift: false, alt: true, meta: false, key: 'enter' }
 *   'mod+s'            → { ctrl/mac: true, key: 's' }
 */
function parseCombo(combo: string) {
  const parts = combo.toLowerCase().split('+').map(p => p.trim());
  const result = {
    ctrl: false,
    shift: false,
    alt: false,
    meta: false,
    key: '',
  };

  for (const part of parts) {
    switch (part) {
      case 'ctrl':
      case 'control':
        result.ctrl = true;
        break;
      case 'shift':
        result.shift = true;
        break;
      case 'alt':
      case 'option':
        result.alt = true;
        break;
      case 'meta':
      case 'cmd':
      case 'command':
        result.meta = true;
        break;
      case 'mod':
        // Mod = Ctrl on Windows/Linux, Cmd on Mac
        if (typeof navigator !== 'undefined' && /mac/i.test(navigator.userAgent)) {
          result.meta = true;
        } else {
          result.ctrl = true;
        }
        break;
      default:
        result.key = part;
    }
  }

  return result;
}

export function useHotkeys(
  combo: string,
  handler: () => void,
  options: HotkeyOptions = {},
) {
  const { preventDefault = true, enableInInput = false, disabled = false } = options;
  const handlerRef = useRef(handler);
  handlerRef.current = handler;

  // Register description for help overlay
  useEffect(() => {
    if (options.description && !disabled) {
      const entry = { keys: combo, description: options.description };
      globalRegistry.push(entry);
      return () => {
        const idx = globalRegistry.indexOf(entry);
        if (idx !== -1) globalRegistry.splice(idx, 1);
      };
    }
  }, [combo, options.description, disabled]);

  const callback = useCallback(
    (e: KeyboardEvent) => {
      if (disabled) return;

      const parsed = parseCombo(combo);

      // Check if we're in an input/textarea/select and shouldn't be
      const target = e.target as HTMLElement;
      const tag = target.tagName.toLowerCase();
      const isInput = tag === 'input' || tag === 'textarea' || tag === 'select' || target.isContentEditable;
      if (isInput && !enableInInput) return;

      // Match the combo
      const ctrlMatch = parsed.ctrl ? (e.ctrlKey || e.metaKey) : !e.ctrlKey && !e.metaKey;
      const shiftMatch = parsed.shift ? e.shiftKey : !e.shiftKey;
      const altMatch = parsed.alt ? e.altKey : !e.altKey;
      const metaMatch = parsed.meta ? e.metaKey : !e.metaKey;

      // For 'mod', we already set ctrl or meta in parseCombo
      const modCtrlMatch = parsed.ctrl ? (e.ctrlKey || e.metaKey) : true;

      const keyMatch = e.key.toLowerCase() === parsed.key ||
        e.code.toLowerCase() === `key${parsed.key}` ||
        (parsed.key === 'escape' && e.key === 'Escape') ||
        (parsed.key === 'enter' && e.key === 'Enter') ||
        (parsed.key === 'tab' && e.key === 'Tab') ||
        (parsed.key === 'delete' && (e.key === 'Delete' || e.key === 'Backspace')) ||
        (parsed.key === '?' && e.key === '?');

      if (keyMatch && modCtrlMatch && shiftMatch && altMatch) {
        if (preventDefault) e.preventDefault();
        handlerRef.current();
      }
    },
    [combo, preventDefault, enableInInput, disabled],
  );

  useEffect(() => {
    if (disabled) return;
    window.addEventListener('keydown', callback);
    return () => window.removeEventListener('keydown', callback);
  }, [callback, disabled]);
}

/**
 * Get all registered hotkeys for the help overlay.
 */
export function getRegisteredHotkeys(): HotkeyRegistration[] {
  return [...globalRegistry];
}

/**
 * Format a key combo for display (e.g., "Ctrl+Z", "⌘+Shift+N").
 */
export function formatHotkey(combo: string): string {
  const isMac = typeof navigator !== 'undefined' && /mac/i.test(navigator.userAgent);
  return combo
    .replace(/\bmod\b/gi, isMac ? '⌘' : 'Ctrl')
    .replace(/\bctrl\b/gi, isMac ? '⌃' : 'Ctrl')
    .replace(/\bshift\b/gi, isMac ? '⇧' : 'Shift')
    .replace(/\balt\b/gi, isMac ? '⌥' : 'Alt')
    .replace(/\bmeta\b/gi, isMac ? '⌘' : 'Win')
    .replace(/\bcmd\b/gi, '⌘')
    .replace(/\bcommand\b/gi, '⌘')
    .replace(/\bescape\b/gi, 'Esc')
    .replace(/\benter\b/gi, '↵')
    .replace(/\bdelete\b/gi, '⌫')
    .replace(/\btab\b/gi, '⇥')
    .split('+')
    .map(part => part.charAt(0).toUpperCase() + part.slice(1))
    .join(isMac ? '' : '+');
}

/**
 * METARDU — useInstrumentConnection Hook
 * ========================================
 * React hook for managing serial instrument connections.
 * Provides real-time data stream from Total Stations and GNSS receivers.
 *
 * Usage:
 * ```tsx
 * const { connect, disconnect, status, lastPoint, isStreaming } = useInstrumentConnection()
 *
 * // Connect to a Leica TS16
 * await connect({ baudRate: 115200 })
 *
 * // Or use a preset
 * await connectWithPreset('leica-ts16')
 * ```
 */

'use client'

import { useState, useCallback, useRef, useEffect } from 'react'
import {
  InstrumentSerialConnection,
  isSerialSupported,
  type ConnectionStatus,
  type SerialConnectionConfig,
  type ParsedInstrumentData,
  type InstrumentInfo,
  type NMEAPosition,
} from '@/lib/serial'
import type {
  GSIMeasurement,
  TopconMeasurement,
  TrimbleMeasurement,
  SokkiaMeasurement,
} from '@/lib/serial/protocolParsers'
import { logger } from '@/lib/logger'

export interface StreamedPoint {
  id: string
  pointName: string
  latitude: number
  longitude: number
  northing: number
  easting: number
  elevation: number | null
  timestamp: Date
  source: 'nmea' | 'gsi'
  quality?: number     // Fix quality (NMEA)
  satellites?: number  // Number of satellites (NMEA)
  hdop?: number        // Horizontal dilution of precision
  raw: NMEAPosition | GSIMeasurement | TopconMeasurement | TrimbleMeasurement | SokkiaMeasurement
}

export interface UseInstrumentConnectionReturn {
  /** Connect to an instrument (triggers port selection dialog) */
  connect: (config?: Partial<SerialConnectionConfig>) => Promise<void>
  /** Connect using a named preset */
  connectWithPreset: (presetKey: string) => Promise<void>
  /** Disconnect from instrument */
  disconnect: () => Promise<void>
  /** Current connection status */
  status: ConnectionStatus
  /** Whether data is actively streaming */
  isStreaming: boolean
  /** Whether the Web Serial API is available */
  isSupported: boolean
  /** Instrument info (detected manufacturer, protocol) */
  instrumentInfo: InstrumentInfo | null
  /** All points received during this session */
  points: StreamedPoint[]
  /** Most recently received point */
  lastPoint: StreamedPoint | null
  /** Total bytes received */
  bytesReceived: number
  /** Total messages parsed */
  messagesParsed: number
  /** Total errors */
  errorCount: number
  /** Clear all received points */
  clearPoints: () => void
  /** Send an instrument command */
  sendCommand: (commandType: string, ...args: unknown[]) => Promise<void>
  /** Error message if connection failed */
  error: string | null
}

let pointCounter = 0

export function useInstrumentConnection(): UseInstrumentConnectionReturn {
  const [status, setStatus] = useState<ConnectionStatus>('disconnected')
  const [isStreaming, setIsStreaming] = useState(false)
  const [instrumentInfo, setInstrumentInfo] = useState<InstrumentInfo | null>(null)
  const [points, setPoints] = useState<StreamedPoint[]>([])
  const [lastPoint, setLastPoint] = useState<StreamedPoint | null>(null)
  const [bytesReceived, setBytesReceived] = useState(0)
  const [messagesParsed, setMessagesParsed] = useState(0)
  const [errorCount, setErrorCount] = useState(0)
  const [error, setError] = useState<string | null>(null)

  const connectionRef = useRef<InstrumentSerialConnection | null>(null)

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (connectionRef.current) {
        connectionRef.current.disconnect()
      }
    }
  }, [])

  const connect = useCallback(async (config?: Partial<SerialConnectionConfig>) => {
    setError(null)

    const connection = new InstrumentSerialConnection(config)

    // Wire up event handlers
    connection.onStatus((newStatus) => {
      setStatus(newStatus)
      setIsStreaming(newStatus === 'streaming')
    })

    connection.onError((err) => {
      setError(err.message)
    })

    connection.onData((data: ParsedInstrumentData) => {
      setMessagesParsed(prev => prev + 1)

      let point: StreamedPoint | null = null

      if (data.type === 'nmea') {
        const nmea = data.data as NMEAPosition
        if (nmea.latitude && nmea.longitude) {
          point = {
            id: `stream-${Date.now()}-${pointCounter++}`,
            pointName: `GNSS-${pointCounter}`,
            latitude: nmea.latitude,
            longitude: nmea.longitude,
            northing: 0,
            easting: 0,
            elevation: nmea.altitude || null,
            timestamp: nmea.timestamp || new Date(),
            source: 'nmea',
            quality: nmea.fixQuality,
            satellites: nmea.satellites,
            hdop: nmea.hdop,
            raw: nmea,
          }
        }
      } else if (data.type === 'gsi') {
        const gsi = data.data
        if (gsi.easting !== undefined && gsi.northing !== undefined) {
          point = {
            id: `stream-${Date.now()}-${pointCounter++}`,
            pointName: gsi.stationId || `TS-${gsi.pointNumber || pointCounter}`,
            latitude: 0,
            longitude: 0,
            northing: gsi.northing,
            easting: gsi.easting,
            elevation: gsi.height || null,
            timestamp: new Date(),
            source: 'gsi',
            raw: gsi,
          }
        }
      } else if (data.type === 'topcon') {
        const topcon = data.data
        if (topcon.easting !== undefined && topcon.northing !== undefined) {
          point = {
            id: `stream-${Date.now()}-${pointCounter++}`,
            pointName: `TS-${topcon.pointNumber || pointCounter}`,
            latitude: 0,
            longitude: 0,
            northing: topcon.northing,
            easting: topcon.easting,
            elevation: topcon.elevation || null,
            timestamp: new Date(),
            source: 'gsi', // Treat all total stations similarly in UI for now
            raw: topcon,
          }
        }
      } else if (data.type === 'trimble') {
        const trimble = data.data
        if (trimble.easting !== undefined && trimble.northing !== undefined) {
          point = {
            id: `stream-${Date.now()}-${pointCounter++}`,
            pointName: `TS-${trimble.pointNumber || pointCounter}`,
            latitude: 0,
            longitude: 0,
            northing: trimble.northing,
            easting: trimble.easting,
            elevation: trimble.elevation || null,
            timestamp: new Date(),
            source: 'gsi',
            raw: trimble,
          }
        }
      } else if (data.type === 'sokkia') {
        const sokkia = data.data
        if (sokkia.easting !== undefined && sokkia.northing !== undefined) {
          point = {
            id: `stream-${Date.now()}-${pointCounter++}`,
            pointName: `TS-${sokkia.pointNumber || pointCounter}`,
            latitude: 0,
            longitude: 0,
            northing: sokkia.northing,
            easting: sokkia.easting,
            elevation: sokkia.elevation || null,
            timestamp: new Date(),
            source: 'gsi',
            raw: sokkia,
          }
        }
      }

      if (point) {
        setLastPoint(point)
        setPoints(prev => [...prev, point!])
        // Expose the latest reading globally so other components (e.g.
        // the mobile fieldbook's "Pull from instrument" button) can
        // read it without re-instantiating the connection.
        if (typeof window !== 'undefined') {
          ;(window as unknown as { __metarduLastInstrumentReading?: unknown }).__metarduLastInstrumentReading = {
            easting: point.easting,
            northing: point.northing,
            elevation: point.elevation,
            pointName: point.pointName,
            timestamp: point.timestamp.toISOString(),
          }
        }
      }
    })

    connectionRef.current = connection

    try {
      await connection.connect()
      setInstrumentInfo(connection.instrumentInfo)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Connection failed')
      throw err
    }
  }, [])

  const connectWithPreset = useCallback(async (presetKey: string) => {
    setError(null)

    const connection = new InstrumentSerialConnection()

    connection.onStatus((newStatus) => {
      setStatus(newStatus)
      setIsStreaming(newStatus === 'streaming')
    })

    connection.onError((err) => {
      setError(err.message)
    })

    connection.onData((data: ParsedInstrumentData) => {
      setMessagesParsed(prev => prev + 1)
      // Same parsing logic as connect()
      let point: StreamedPoint | null = null
      if (data.type === 'nmea') {
        const nmea = data.data as NMEAPosition
        if (nmea.latitude && nmea.longitude) {
          point = {
            id: `stream-${Date.now()}-${pointCounter++}`,
            pointName: `GNSS-${pointCounter}`,
            latitude: nmea.latitude,
            longitude: nmea.longitude,
            northing: 0,
            easting: 0,
            elevation: nmea.altitude || null,
            timestamp: nmea.timestamp || new Date(),
            source: 'nmea',
            quality: nmea.fixQuality,
            satellites: nmea.satellites,
            hdop: nmea.hdop,
            raw: nmea,
          }
        }
      } else if (data.type === 'gsi') {
        const gsi = data.data
        if (gsi.easting !== undefined && gsi.northing !== undefined) {
          point = {
            id: `stream-${Date.now()}-${pointCounter++}`,
            pointName: gsi.stationId || `TS-${gsi.pointNumber || pointCounter}`,
            latitude: 0,
            longitude: 0,
            northing: gsi.northing,
            easting: gsi.easting,
            elevation: gsi.height || null,
            timestamp: new Date(),
            source: 'gsi',
            raw: gsi,
          }
        }
      } else if (data.type === 'topcon') {
        const topcon = data.data
        if (topcon.easting !== undefined && topcon.northing !== undefined) {
          point = {
            id: `stream-${Date.now()}-${pointCounter++}`,
            pointName: `TS-${topcon.pointNumber || pointCounter}`,
            latitude: 0,
            longitude: 0,
            northing: topcon.northing,
            easting: topcon.easting,
            elevation: topcon.elevation || null,
            timestamp: new Date(),
            source: 'gsi', // Treat all total stations similarly in UI for now
            raw: topcon,
          }
        }
      } else if (data.type === 'trimble') {
        const trimble = data.data
        if (trimble.easting !== undefined && trimble.northing !== undefined) {
          point = {
            id: `stream-${Date.now()}-${pointCounter++}`,
            pointName: `TS-${trimble.pointNumber || pointCounter}`,
            latitude: 0,
            longitude: 0,
            northing: trimble.northing,
            easting: trimble.easting,
            elevation: trimble.elevation || null,
            timestamp: new Date(),
            source: 'gsi',
            raw: trimble,
          }
        }
      } else if (data.type === 'sokkia') {
        const sokkia = data.data
        if (sokkia.easting !== undefined && sokkia.northing !== undefined) {
          point = {
            id: `stream-${Date.now()}-${pointCounter++}`,
            pointName: `TS-${sokkia.pointNumber || pointCounter}`,
            latitude: 0,
            longitude: 0,
            northing: sokkia.northing,
            easting: sokkia.easting,
            elevation: sokkia.elevation || null,
            timestamp: new Date(),
            source: 'gsi',
            raw: sokkia,
          }
        }
      }
      if (point) {
        setLastPoint(point)
        setPoints(prev => [...prev, point!])
        if (typeof window !== 'undefined') {
          ;(window as unknown as { __metarduLastInstrumentReading?: unknown }).__metarduLastInstrumentReading = {
            easting: point.easting,
            northing: point.northing,
            elevation: point.elevation,
            pointName: point.pointName,
            timestamp: point.timestamp.toISOString(),
          }
        }
      }
    })

    connectionRef.current = connection

    try {
      await connection.connectWithPreset(presetKey)
      setInstrumentInfo(connection.instrumentInfo)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Connection failed')
      throw err
    }
  }, [])

  const disconnect = useCallback(async () => {
    if (connectionRef.current) {
      await connectionRef.current.disconnect()
      connectionRef.current = null
    }
  }, [])

  const clearPoints = useCallback(() => {
    setPoints([])
    setLastPoint(null)
    if (typeof window !== 'undefined') {
      try {
        delete (window as unknown as { __metarduLastInstrumentReading?: unknown }).__metarduLastInstrumentReading
      } catch { /* ignore */ }
    }
  }, [])

  const sendCommand = useCallback(async (commandType: string, ...args: unknown[]) => {
    if (!connectionRef.current) return
    const brand = connectionRef.current.getCurrentBrand()
    if (!brand) return
    try {
      await connectionRef.current.sendInstrumentCommand(brand, commandType, ...args)
    } catch (err) {
      logger.error('Failed to send instrument command:', { error: err })
      setError(err instanceof Error ? err.message : 'Command failed')
    }
  }, [])

  return {
    connect,
    connectWithPreset,
    disconnect,
    status,
    isStreaming,
    isSupported: isSerialSupported(),
    instrumentInfo,
    points,
    lastPoint,
    bytesReceived,
    messagesParsed,
    errorCount,
    clearPoints,
    sendCommand,
    error,
  }
}

'use client';

import { useState, useCallback, useRef, useEffect } from 'react';
import type Map from 'ol/Map';
import type VectorSource from 'ol/source/Vector';
import type VectorLayer from 'ol/layer/Vector';
import type { FeatureLike } from 'ol/Feature';
import {
  calculateDistance,
  calculateArea,
  calculateBearing,
  formatBearingWCB,
  formatDistance,
  formatArea,
  type Point,
} from '@/lib/map/measurements';

export type MeasurementMode = 'none' | 'distance' | 'area' | 'bearing' | 'coordinate';

export interface MeasurementState {
  mode: MeasurementMode;
  points: Point[];
  result: {
    distance?: number;
    area?: number;
    bearing?: number;
    coordinate?: Point;
  } | null;
  isActive: boolean;
}

export interface FormattedResult {
  type: string;
  raw: number;
  formatted: string;
}

export function useMeasurement(map: Map | null) {
  const [state, setState] = useState<MeasurementState>({
    mode: 'none',
    points: [],
    result: null,
    isActive: false,
  });
  
  const sourceRef = useRef<VectorSource | null>(null);
  const layerRef = useRef<VectorLayer | null>(null);
  const clickHandlerRef = useRef<((evt: import('ol/MapBrowserEvent').default) => void) | null>(null);
  const ctorsRef = useRef<{
    VectorSource: typeof VectorSource
    VectorLayer: typeof VectorLayer
    Feature: typeof import('ol/Feature').default
    OlPoint: typeof import('ol/geom/Point').default
    OlLineString: typeof import('ol/geom/LineString').default
    OlPolygon: typeof import('ol/geom/Polygon').default
  } | null>(null);

  const createLayer = useCallback(async () => {
    if (!map) return null;

    // Dynamic OL imports for SSR safety
    const [
      VectorSourceMod, VectorLayerMod, StyleMod, StrokeMod,
      FillMod, CircleMod, LineStringMod, PolygonMod, PointMod,
    ] = await Promise.all([
      import('ol/source/Vector'), import('ol/layer/Vector'),
      import('ol/style/Style'), import('ol/style/Stroke'),
      import('ol/style/Fill'), import('ol/style/Circle'),
      import('ol/geom/LineString'), import('ol/geom/Polygon'),
      import('ol/geom/Point'),
    ]);

    const VectorSource = VectorSourceMod.default;
    const VectorLayer = VectorLayerMod.default;
    const Style = StyleMod.default;
    const Stroke = StrokeMod.default;
    const Fill = FillMod.default;
    const Circle = CircleMod.default;
    const OlLineString = LineStringMod.default;
    const OlPolygon = PolygonMod.default;
    const OlPoint = PointMod.default;
    
    const source = new VectorSource();
    const layer = new VectorLayer({
      source,
      style: (feature: FeatureLike) => {
        const geometry = feature.getGeometry();
        const type = feature.get('type') as string;
        
        if (geometry instanceof OlPoint) {
          return new Style({
            image: new Circle({
              radius: 6,
              fill: new Fill({ color: '#1B3A5C' }),
              stroke: new Stroke({ color: '#FFFFFF', width: 2 }),
            }),
          });
        } else if (geometry instanceof OlLineString) {
          return new Style({
            stroke: new Stroke({
              color: '#1B3A5C',
              width: 2,
            }),
          });
        } else if (geometry instanceof OlPolygon) {
          return new Style({
            stroke: new Stroke({
              color: '#1B3A5C',
              width: 2,
            }),
            fill: new Fill({
              color: 'rgba(27, 58, 92, 0.1)',
            }),
          });
        }
        
        return new Style({});
      },
      zIndex: 100,
    });
    
    map.addLayer(layer);
    sourceRef.current = source;
    layerRef.current = layer;

    // Store constructors for later use
    ctorsRef.current = { VectorSource, VectorLayer, Feature: (await import('ol/Feature')).default, OlPoint, OlLineString, OlPolygon };
    
    return { source, layer };
  }, [map]);

  const clearSource = useCallback(() => {
    if (sourceRef.current) {
      sourceRef.current.clear();
    }
  }, []);

  const addPointToMap = useCallback(async (point: Point) => {
    if (!sourceRef.current) return;
    const { Feature, OlPoint } = ctorsRef.current || {};
    if (!Feature || !OlPoint) return;
    const feature = new Feature(new OlPoint([point.easting, point.northing]));
    feature.set('type', 'vertex');
    sourceRef.current.addFeature(feature);
  }, []);

  const addLineToMap = useCallback(async (points: Point[]) => {
    if (!sourceRef.current || points.length < 2) return;
    const { Feature, OlLineString } = ctorsRef.current || {};
    if (!Feature || !OlLineString) return;
    const coords = points.map(p => [p.easting, p.northing] as [number, number]);
    const feature = new Feature(new OlLineString(coords));
    feature.set('type', 'line');
    sourceRef.current.addFeature(feature);
  }, []);

  const addPolygonToMap = useCallback(async (points: Point[]) => {
    if (!sourceRef.current || points.length < 3) return;
    const { Feature, OlPolygon } = ctorsRef.current || {};
    if (!Feature || !OlPolygon) return;
    const coords = [...points.map(p => [p.easting, p.northing] as [number, number]), [points[0].easting, points[0].northing] as [number, number]];
    const feature = new Feature(new OlPolygon([coords]));
    feature.set('type', 'polygon');
    sourceRef.current.addFeature(feature);
  }, []);

  const startMeasurement = useCallback(async (mode: MeasurementMode) => {
    if (!map) return;
    
    if (!sourceRef.current) {
      await createLayer();
    }
    
    clearSource();
    
    setState({
      mode,
      points: [],
      result: null,
      isActive: true,
    });

    const handleClick = (evt: import('ol/MapBrowserEvent').default) => {
      const coord = evt.coordinate;
      
      const point: Point = {
        easting: coord[0],
        northing: coord[1],
      };
      
      handlePointClick(point, mode);
    };
    
    clickHandlerRef.current = handleClick;
    map.on('click', handleClick);
  }, [map, createLayer, clearSource]);

  const handlePointClick = useCallback((point: Point, mode: MeasurementMode) => {
    setState((prev) => {
      const newPoints = [...prev.points, point];
      
      addPointToMap(point);
      
      let result: MeasurementState['result'] = null;
      
      if (mode === 'distance' && newPoints.length === 2) {
        const distance = calculateDistance(newPoints[0], newPoints[1]);
        result = { distance };
        addLineToMap(newPoints);
      } else if (mode === 'bearing' && newPoints.length === 2) {
        const bearing = calculateBearing(newPoints[0], newPoints[1]);
        result = { bearing };
        addLineToMap(newPoints);
      } else if (mode === 'coordinate') {
        result = { coordinate: point };
      } else if (mode === 'area' && newPoints.length >= 3) {
        addPolygonToMap(newPoints);
      }
      
      const isFinished = mode !== 'area' && newPoints.length >= 2;
      
      return {
        ...prev,
        points: newPoints,
        result: result || (mode === 'area' && newPoints.length >= 3 ? { area: calculateArea(newPoints) } : null),
        isActive: mode === 'area' || !isFinished,
      };
    });
  }, [addPointToMap, addLineToMap, addPolygonToMap]);

  const finishAreaMeasurement = useCallback(() => {
    if (state.points.length < 3) return;
    
    const area = calculateArea(state.points);
    addPolygonToMap(state.points);
    
    setState((prev) => ({
      ...prev,
      result: { area },
      isActive: false,
    }));
  }, [state.points, addPolygonToMap]);

  const cancelMeasurement = useCallback(() => {
    clearSource();
    
    if (map && clickHandlerRef.current) {
      map.un('click', clickHandlerRef.current);
      clickHandlerRef.current = null;
    }
    
    setState({
      mode: 'none',
      points: [],
      result: null,
      isActive: false,
    });
  }, [map, clearSource]);

  const clearMeasurement = useCallback(() => {
    clearSource();
    setState((prev) => ({
      ...prev,
      points: [],
      result: null,
    }));
  }, [clearSource]);

  const getFormattedResult = useCallback((): FormattedResult | null => {
    if (!state.result) return null;
    
    if (state.result.distance !== undefined) {
      return {
        type: 'distance',
        raw: state.result.distance,
        formatted: formatDistance(state.result.distance),
      };
    }
    
    if (state.result.area !== undefined) {
      return {
        type: 'area',
        raw: state.result.area,
        formatted: formatArea(state.result.area),
      };
    }
    
    if (state.result.bearing !== undefined) {
      return {
        type: 'bearing',
        raw: state.result.bearing,
        formatted: formatBearingWCB(state.result.bearing),
      };
    }
    
    if (state.result.coordinate) {
      return {
        type: 'coordinate',
        raw: 0,
        formatted: `E ${state.result.coordinate.easting.toFixed(3)}  N ${state.result.coordinate.northing.toFixed(3)}`,
      };
    }
    
    return null;
  }, [state.result]);

  // Clean up on unmount: remove layer and click handler from map
  useEffect(() => {
    return () => {
      if (map) {
        if (clickHandlerRef.current) {
          map.un('click', clickHandlerRef.current);
          clickHandlerRef.current = null;
        }
        if (layerRef.current) {
          map.removeLayer(layerRef.current);
          layerRef.current = null;
        }
        sourceRef.current = null;
      }
    };
  }, [map]);

  return {
    state,
    startMeasurement,
    finishAreaMeasurement,
    cancelMeasurement,
    clearMeasurement,
    getFormattedResult,
  };
}

/**
 * METARDU useSubdivision Hook
 *
 * React hook for managing subdivision state and map interactions.
 * Follows the patterns established in useMeasurement.ts.
 *
 * Provides:
 * - State management for subdivision method, parameters, and results
 * - Map layer management (add/remove subdivision overlay)
 * - Split line drawing interaction
 * - DXF export trigger
 */

'use client'

import { useState, useCallback, useRef, useEffect } from 'react'
import type Map from 'ol/Map'
import type { SubdivisionMethod, SubdivisionParams, SubdivisionResult, SplitLine, RoadReserveInfo } from '@/types/subdivision'
import type { Point2D } from '@/lib/engine/types'
import { subdivide, createRoadReserve } from '@/lib/engine/subdivision'
import { downloadSubdivisionDXF } from '@/lib/export/subdivisionDXF'
import { logger } from '@/lib/logger'
import { createSubdivisionLayer, createSplitLineLayer, createRoadReservePreviewLayer } from '@/lib/map/subdivisionLayer'

export interface UseSubdivisionOptions {
  /** Parent parcel vertices (EPSG:21037) */
  parentVertices: Point2D[]
  /** OpenLayers map instance */
  map: Map | null
  /** Project name for DXF export */
  projectName?: string
}

export function useSubdivision({
  parentVertices,
  map,
  projectName = 'METARDU_Subdivision',
}: UseSubdivisionOptions) {
  // ─── State ────────────────────────────────────────────────────────────
  const [method, setMethod] = useState<SubdivisionMethod | null>(null)
  const [params, setParams] = useState<SubdivisionParams>({})
  const [result, setResult] = useState<SubdivisionResult | null>(null)
  const [splitLine, setSplitLine] = useState<SplitLine | null>(null)
  const [isDrawingSplitLine, setIsDrawingSplitLine] = useState(false)
  const [isComputing, setIsComputing] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // ─── Road reserve state ──────────────────────────────────────────────
  const [roadReserveEnabled, setRoadReserveEnabled] = useState(false)
  const [roadReserveWidth, setRoadReserveWidth] = useState(12)
  const [roadReserveEdges, setRoadReserveEdges] = useState<number[]>([])
  const [roadReserveAuto, setRoadReserveAuto] = useState(true)
  const [roadReservePreview, setRoadReservePreview] = useState<RoadReserveInfo | null>(null)

  // ─── Refs for map layers ──────────────────────────────────────────────
  const subdivisionLayerRef = useRef<import('ol/layer/Vector').default | null>(null)
  const splitLineLayerRef = useRef<import('ol/layer/Vector').default | null>(null)
  const roadReserveLayerRef = useRef<import('ol/layer/Vector').default | null>(null)
  const drawInteractionRef = useRef<import('ol/interaction/Draw').default | null>(null)
  const clickHandlerRef = useRef<((evt: import('ol/MapBrowserEvent').default) => void) | null>(null)
  const splitLinePointsRef = useRef<Point2D[]>([])

  // ─── Stable refs for cleanup callbacks ────────────────────────────────
  const mapRef = useRef<Map | null>(null)
  const removeSubdivisionLayerRef = useRef<() => void>(() => {})
  const removeSplitLineLayerRef = useRef<() => void>(() => {})
  const removeRoadReserveLayerRef = useRef<() => void>(() => {})
  const removeDrawInteractionRef = useRef<() => void>(() => {})
  const addSubdivisionLayerRef = useRef<(r: SubdivisionResult) => void>(() => {})
  const addSplitLineLayerRef = useRef<(l: SplitLine) => void>(() => {})
  const addRoadReserveLayerRef = useRef<(r: RoadReserveInfo) => void>(() => {})

  // Keep map ref in sync
  useEffect(() => { mapRef.current = map }, [map])

  // Keep stable cleanup/add refs
  useEffect(() => {
    removeSubdivisionLayerRef.current = removeSubdivisionLayer
    removeSplitLineLayerRef.current = removeSplitLineLayer
    removeRoadReserveLayerRef.current = removeRoadReserveLayer
    removeDrawInteractionRef.current = removeDrawInteraction
    addSubdivisionLayerRef.current = addSubdivisionLayer
    addSplitLineLayerRef.current = addSplitLineLayer
    addRoadReserveLayerRef.current = addRoadReserveLayer
  })

  // ─── Clean up layers on unmount ──────────────────────────────────────
  useEffect(() => {
    return () => {
      removeSubdivisionLayerRef.current()
      removeSplitLineLayerRef.current()
      removeRoadReserveLayerRef.current()
      removeDrawInteractionRef.current()
    }
  }, [])

  // ─── Method selection ────────────────────────────────────────────────

  const selectMethod = useCallback((newMethod: SubdivisionMethod) => {
    setMethod(newMethod)
    setResult(null)
    setError(null)
    removeSubdivisionLayerRef.current()

    // If switching away from single-split, remove split line stuff
    if (newMethod !== 'single-split') {
      setSplitLine(null)
      removeSplitLineLayerRef.current()
      removeDrawInteractionRef.current()
      setIsDrawingSplitLine(false)
      splitLinePointsRef.current = []
    }
  }, [])

  // ─── Parameters ───────────────────────────────────────────────────────

  const updateParams = useCallback((newParams: Partial<SubdivisionParams>) => {
    setParams(prev => ({ ...prev, ...newParams }))
  }, [])

  // ─── Execute subdivision ──────────────────────────────────────────────

  const execute = useCallback(() => {
    if (!method) {
      setError('Select a subdivision method first.')
      return
    }

    if (parentVertices.length < 3) {
      setError('Parent parcel must have at least 3 vertices.')
      return
    }

    // Validate params per method
    if (method === 'single-split' && !splitLine) {
      setError('Draw a split line on the map first.')
      return
    }
    if (method === 'grid' && (!params.rows || !params.cols)) {
      setError('Specify rows and columns for grid subdivision.')
      return
    }
    if (method === 'radial' && (!params.numLots || params.numLots < 2)) {
      setError('Specify at least 2 lots for radial subdivision.')
      return
    }
    if (method === 'area' && (!params.targetArea || params.targetArea <= 0)) {
      setError('Specify a valid target area.')
      return
    }

    setIsComputing(true)
    setError(null)

    try {
      const fullParams: SubdivisionParams = { ...params }
      if (method === 'single-split') {
        fullParams.splitLine = splitLine!
      }

      // Apply road reserve if enabled
      if (roadReserveEnabled && roadReserveWidth > 0) {
        fullParams.roadReserveWidth = roadReserveWidth
        fullParams.roadReserveEdges = roadReserveAuto ? [] : roadReserveEdges
      }

      const subResult = subdivide(parentVertices, method, fullParams)
      setResult(subResult)

      // Remove road reserve preview layer
      removeRoadReserveLayerRef.current()
      setRoadReservePreview(null)

      // Add subdivision layer to map
      addSubdivisionLayerRef.current(subResult)
    } catch (err: unknown) {
      setError((err as Error).message || 'Subdivision computation failed.')
      setResult(null)
    } finally {
      setIsComputing(false)
    }
  }, [method, params, splitLine, parentVertices, roadReserveEnabled, roadReserveWidth, roadReserveEdges, roadReserveAuto])

  // ─── Clear everything ────────────────────────────────────────────────

  const clear = useCallback(() => {
    setMethod(null)
    setParams({})
    setResult(null)
    setSplitLine(null)
    setError(null)
    setIsDrawingSplitLine(false)
    splitLinePointsRef.current = []
    setRoadReserveEnabled(false)
    setRoadReserveWidth(12)
    setRoadReserveEdges([])
    setRoadReserveAuto(true)
    setRoadReservePreview(null)
    removeSubdivisionLayerRef.current()
    removeSplitLineLayerRef.current()
    removeRoadReserveLayerRef.current()
    removeDrawInteractionRef.current()
  }, [])

  // ─── Split line drawing ──────────────────────────────────────────────

  const startSplitLineDrawing = useCallback(() => {
    if (!map) return
    setIsDrawingSplitLine(true)
    splitLinePointsRef.current = []
    setSplitLine(null)
    removeSplitLineLayerRef.current()
    setError(null)
  }, [map])

  // Handle clicks for split line drawing
  useEffect(() => {
    if (!map || !isDrawingSplitLine) return

    const handleClick = async (evt: import('ol/MapBrowserEvent').default) => {
      const [x, y] = evt.coordinate as [number, number]

      // Convert from EPSG:3857 to EPSG:21037
      const { to21037 } = await import('@/lib/map/projection')
      const [e, n] = await to21037(x, y)

      const point: Point2D = { easting: e, northing: n }
      splitLinePointsRef.current = [...splitLinePointsRef.current, point]

      if (splitLinePointsRef.current.length === 1) {
        return
      }

      if (splitLinePointsRef.current.length === 2) {
        const newSplitLine: SplitLine = {
          startPoint: splitLinePointsRef.current[0],
          endPoint: splitLinePointsRef.current[1],
        }
        setSplitLine(newSplitLine)
        setIsDrawingSplitLine(false)
        addSplitLineLayerRef.current(newSplitLine)
      }
    }

    clickHandlerRef.current = handleClick
    map.on('click', handleClick)

    return () => {
      if (clickHandlerRef.current) {
        map.un('click', clickHandlerRef.current)
        clickHandlerRef.current = null
      }
    }
  }, [map, isDrawingSplitLine])

  // ─── DXF export ──────────────────────────────────────────────────────

  const exportDXF = useCallback(() => {
    if (!result) return
    downloadSubdivisionDXF(result, projectName)
  }, [result, projectName])

  // ─── Map layer management (using stable refs to avoid dep warnings) ────

  const removeSubdivisionLayer = useCallback(() => {
    if (mapRef.current && subdivisionLayerRef.current) {
      mapRef.current.removeLayer(subdivisionLayerRef.current)
      subdivisionLayerRef.current = null
    }
  }, [])

  const addSubdivisionLayer = useCallback(async (subResult: SubdivisionResult) => {
    if (!map) return
    removeSubdivisionLayerRef.current()

    try {
      const layer = await createSubdivisionLayer(subResult)
      map.addLayer(layer)
      subdivisionLayerRef.current = layer
    } catch (err) {
      logger.error('Failed to create subdivision layer:', { error: err })
    }
  }, [map])

  const removeSplitLineLayer = useCallback(() => {
    if (mapRef.current && splitLineLayerRef.current) {
      mapRef.current.removeLayer(splitLineLayerRef.current)
      splitLineLayerRef.current = null
    }
  }, [])

  const removeDrawInteraction = useCallback(() => {
    if (mapRef.current && drawInteractionRef.current) {
      mapRef.current.removeInteraction(drawInteractionRef.current)
      drawInteractionRef.current = null
    }
  }, [])

  const addSplitLineLayer = useCallback(async (sLine: SplitLine) => {
    if (!map) return
    removeSplitLineLayerRef.current()

    try {
      const layer = await createSplitLineLayer(sLine)
      if (layer) {
        map.addLayer(layer)
        splitLineLayerRef.current = layer
      }
    } catch (err) {
      logger.error('Failed to create split line layer:', { error: err })
    }
  }, [map])

  const removeRoadReserveLayer = useCallback(() => {
    if (mapRef.current && roadReserveLayerRef.current) {
      mapRef.current.removeLayer(roadReserveLayerRef.current)
      roadReserveLayerRef.current = null
    }
  }, [])

  const addRoadReserveLayer = useCallback(async (rrInfo: RoadReserveInfo) => {
    if (!map) return
    removeRoadReserveLayerRef.current()

    try {
      const layer = await createRoadReservePreviewLayer(rrInfo)
      if (layer) {
        map.addLayer(layer)
        roadReserveLayerRef.current = layer
      }
    } catch (err) {
      logger.error('Failed to create road reserve layer:', { error: err })
    }
  }, [map])

  // ─── Center point picking (for radial) ───────────────────────────────

  const pickCenterPointHandlerRef = useRef<((evt: import('ol/MapBrowserEvent').default) => void) | null>(null)

  // Clean up pickCenterPoint handler on unmount
  useEffect(() => {
    return () => {
      if (mapRef.current && pickCenterPointHandlerRef.current) {
        mapRef.current.un('click', pickCenterPointHandlerRef.current)
        pickCenterPointHandlerRef.current = null
      }
    }
  }, [])

  const pickCenterPoint = useCallback(() => {
    if (!map) return

    // Clean up previous handler if any
    if (pickCenterPointHandlerRef.current) {
      map.un('click', pickCenterPointHandlerRef.current)
    }

    const handleMapClick = async (evt: import('ol/MapBrowserEvent').default) => {
      const [x, y] = evt.coordinate as [number, number]
      const { to21037 } = await import('@/lib/map/projection')
      const [e, n] = await to21037(x, y)

      const center: Point2D = { easting: e, northing: n }
      updateParams({ center })

      if (pickCenterPointHandlerRef.current) {
        map.un('click', pickCenterPointHandlerRef.current)
        pickCenterPointHandlerRef.current = null
      }
    }

    pickCenterPointHandlerRef.current = handleMapClick
    map.on('click', handleMapClick)
  }, [map, updateParams])

  // ─── Road reserve preview ───────────────────────────────────────────

  const previewRoadReserve = useCallback(() => {
    if (parentVertices.length < 3 || roadReserveWidth <= 0) return

    try {
      const edges = roadReserveAuto ? [] : roadReserveEdges
      const rr = createRoadReserve(parentVertices, roadReserveWidth, edges)

      if (rr.roadPolygon.length >= 3) {
        // Compute area
        let area = 0
        const pts = rr.roadPolygon
        const n = pts.length
        for (let i = 0; i < n; i++) {
          const j = (i + 1) % n
          area += pts[i].easting * pts[j].northing
          area -= pts[j].easting * pts[i].northing
        }
        const areaHaVal = Math.abs(area / 2) / 10000

        const info: RoadReserveInfo = {
          roadPolygon: rr.roadPolygon,
          width: roadReserveWidth,
          clippedEdges: rr.clippedEdges,
          areaHa: areaHaVal,
        }

        setRoadReservePreview(info)
        addRoadReserveLayerRef.current(info)
      } else {
        setRoadReservePreview(null)
        removeRoadReserveLayerRef.current()
      }
    } catch (err) {
      logger.error('Road reserve preview failed:', { error: err })
    }
  }, [parentVertices, roadReserveWidth, roadReserveAuto, roadReserveEdges])

  const clearRoadReservePreview = useCallback(() => {
    setRoadReservePreview(null)
    removeRoadReserveLayerRef.current()
  }, [])

  const toggleRoadReserveEdge = useCallback((edgeIdx: number) => {
    setRoadReserveEdges(prev => {
      if (prev.includes(edgeIdx)) {
        return prev.filter(e => e !== edgeIdx)
      }
      return [...prev, edgeIdx].sort((a, b) => a - b)
    })
  }, [])

  // ─── Return ──────────────────────────────────────────────────────────

  return {
    // State
    method,
    params,
    result,
    splitLine,
    isDrawingSplitLine,
    isComputing,
    error,

    // Road reserve state
    roadReserveEnabled,
    roadReserveWidth,
    roadReserveEdges,
    roadReserveAuto,
    roadReservePreview,

    // Actions
    selectMethod,
    updateParams,
    execute,
    clear,
    startSplitLineDrawing,
    pickCenterPoint,
    exportDXF,
    setSplitLine,

    // Road reserve actions
    setRoadReserveEnabled,
    setRoadReserveWidth,
    setRoadReserveAuto,
    previewRoadReserve,
    clearRoadReservePreview,
    toggleRoadReserveEdge,
  }
}

'use client';

/**
 * useUndoRedo — Command-pattern undo/redo for fieldbook edits.
 * ──────────────────────────────────────────────────────────────
 * Provides an undo/redo stack for any state that needs reversible
 * mutations. Used by the fieldbook page to let surveyors recover
 * from accidental edits, row deletions, and data clears.
 *
 * Each command has:
 *   - execute() — apply the change
 *   - undo()    — reverse the change
 *   - label     — human-readable description for the undo toast
 *
 * Usage:
 *   const { execute, undo, redo, canUndo, canRedo } = useUndoRedo()
 *   execute({
 *     execute: () => setRows(prev => [...prev, newRow]),
 *     undo:    () => setRows(prev => prev.filter(r => r.id !== newRow.id)),
 *     label:   'Add observation P3',
 *   })
 */

import { useState, useCallback, useRef } from 'react';
import { useHotkeys } from '@/hooks/useHotkeys';

export interface Command {
  execute: () => void;
  undo: () => void;
  label: string;
}

interface UndoRedoState {
  past: Command[];
  future: Command[];
}

const MAX_HISTORY = 100;

export function useUndoRedo() {
  const [state, setState] = useState<UndoRedoState>({ past: [], future: [] });

  const execute = useCallback(
    (command: Command) => {
      command.execute();
      setState((prev) => ({
        past: [...prev.past.slice(-MAX_HISTORY + 1), command],
        future: [], // Clear redo stack on new action
      }));
    },
    [],
  );

  const undo = useCallback(() => {
    setState((prev) => {
      if (prev.past.length === 0) return prev;
      const command = prev.past[prev.past.length - 1];
      command.undo();
      return {
        past: prev.past.slice(0, -1),
        future: [command, ...prev.future],
      };
    });
  }, []);

  const redo = useCallback(() => {
    setState((prev) => {
      if (prev.future.length === 0) return prev;
      const command = prev.future[0];
      command.execute();
      return {
        past: [...prev.past, command],
        future: prev.future.slice(1),
      };
    });
  }, []);

  const clear = useCallback(() => {
    setState({ past: [], future: [] });
  }, []);

  // Register global keyboard shortcuts
  useHotkeys('ctrl+z', undo, {
    description: 'Undo last action',
    enableInInput: false,
  });
  useHotkeys('ctrl+shift+z', redo, {
    description: 'Redo',
    enableInInput: false,
  });
  useHotkeys('ctrl+y', redo, {
    description: 'Redo (alternative)',
    enableInInput: false,
  });

  const canUndo = state.past.length > 0;
  const canRedo = state.future.length > 0;
  const undoLabel = canUndo ? state.past[state.past.length - 1].label : null;
  const redoLabel = canRedo ? state.future[0].label : null;

  return {
    execute,
    undo,
    redo,
    clear,
    canUndo,
    canRedo,
    undoLabel,
    redoLabel,
    historySize: state.past.length,
  };
}

/**
 * METARDU useVertexEditing Hook
 *
 * React hook for managing vertex editing on the survey map.
 * Provides OpenLayers Modify, Snap interactions, vertex insertion (dblclick),
 * vertex removal (right-click), and coordinate readback in EPSG:21037.
 *
 * All OL imports are dynamic (await import()) to match existing patterns.
 * Coordinate math in EPSG:21037, rendering in EPSG:3857.
 */

'use client';

import { useState, useCallback, useRef, useEffect } from 'react';
import type Map from 'ol/Map';
import type { Feature } from 'ol';
import type { Polygon as OlPolygon } from 'ol/geom';
import { to21037, arrayTo3857, SRID_3857, SRID_21037 } from '@/lib/map/projection';

/* ------------------------------------------------------------------ */
/*  Public types                                                       */
/* ------------------------------------------------------------------ */

export interface VertexPoint {
  easting: number;
  northing: number;
}

export interface VertexEditingOptions {
  /** OpenLayers map instance */
  map: Map | null;
  /** Current parcel vertices in EPSG:21037 (used to initialise the editable polygon) */
  vertices: VertexPoint[];
  /** Whether editing interactions are active */
  enabled: boolean;
  /** Callback with updated vertices after every edit */
  onVerticesChange: (updated: VertexPoint[]) => void;
  /** Snap tolerance in pixels (default 10) */
  snapTolerance?: number;
  /** Whether magnetic snap is on (default true) */
  snapEnabled?: boolean;
}

export interface VertexEditingState {
  vertexCount: number;
  hoveredVertex: { easting: number; northing: number; index: number } | null;
  lastEditedVertex: { easting: number; northing: number; index: number } | null;
}

/* ------------------------------------------------------------------ */
/*  Geometry helpers (all in map projection – EPSG:3857)              */
/* ------------------------------------------------------------------ */

function pointToSegmentDist(
  p: [number, number],
  a: [number, number],
  b: [number, number]
): number {
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  const len2 = dx * dx + dy * dy;
  if (len2 === 0)
    return Math.sqrt((p[0] - a[0]) ** 2 + (p[1] - a[1]) ** 2);
  const t = Math.max(
    0,
    Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / len2)
  );
  return Math.sqrt((p[0] - (a[0] + t * dx)) ** 2 + (p[1] - (a[1] + t * dy)) ** 2);
}

function nearestPointOnSegment(
  p: [number, number],
  a: [number, number],
  b: [number, number]
): [number, number] {
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  const len2 = dx * dx + dy * dy;
  if (len2 === 0) return [a[0], a[1]];
  const t = Math.max(
    0,
    Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / len2)
  );
  return [a[0] + t * dx, a[1] + t * dy];
}

function vertexDist(
  p: [number, number],
  v: [number, number]
): number {
  return Math.sqrt((p[0] - v[0]) ** 2 + (p[1] - v[1]) ** 2);
}

/* ------------------------------------------------------------------ */
/*  Hook                                                               */
/* ------------------------------------------------------------------ */

export function useVertexEditing({
  map,
  vertices,
  enabled,
  onVerticesChange,
  snapTolerance = 10,
  snapEnabled = true,
}: VertexEditingOptions) {
  const [state, setState] = useState<VertexEditingState>({
    vertexCount: 0,
    hoveredVertex: null,
    lastEditedVertex: null,
  });

  // --- Refs for OL objects ---
  const sourceRef = useRef<import('ol/source/Vector').default | null>(null);
  const layerRef = useRef<import('ol/layer/Vector').default | null>(null);
  const modifyRef = useRef<import('ol/interaction/Modify').default | null>(null);
  const snapRef = useRef<import('ol/interaction/Snap').default | null>(null);
  const featureRef = useRef<Feature<OlPolygon> | null>(null);
  const mapRef = useRef<Map | null>(null);

  // Stable function refs (avoids stale closures)
  const onVerticesChangeRef = useRef(onVerticesChange);
  const verticesRef = useRef<VertexPoint[]>(vertices);

  // Event handler refs for cleanup
  const dblClickRef = useRef<((evt: import('ol/MapBrowserEvent').default) => void) | null>(null);
  const contextMenuRef = useRef<((evt: import('ol/MapBrowserEvent').default) => void) | null>(null);
  const pointerMoveRef = useRef<((evt: import('ol/MapBrowserEvent').default) => void) | null>(null);

  // --- Keep refs in sync ---
  useEffect(() => { mapRef.current = map; }, [map]);
  useEffect(() => { verticesRef.current = vertices; }, [vertices]);
  useEffect(() => { onVerticesChangeRef.current = onVerticesChange; }, [onVerticesChange]);

  // --- Read polygon geometry → EPSG:21037 vertices ---
  const readVerticesFromFeature = useCallback(async (): Promise<VertexPoint[]> => {
    const feat = featureRef.current;
    if (!feat) return verticesRef.current;
    const geom = feat.getGeometry();
    if (!geom) return verticesRef.current;
    const ring = geom.getCoordinates()[0] as number[][];
    // Remove closing vertex (duplicate of first)
    const open = ring.slice(0, -1);
    const pts = await Promise.all(open.map(([x, y]) => to21037(x, y)));
    return pts.map(([e, n]) => ({ easting: e, northing: n }));
  }, []);

  // --- Callback after any geometry edit ---
  const syncVertices = useCallback(async () => {
    const updated = await readVerticesFromFeature();
    onVerticesChangeRef.current(updated);
    setState(prev => ({
      ...prev,
      vertexCount: updated.length,
    }));
  }, [readVerticesFromFeature]);

  // --- Full cleanup ---
  const cleanup = useCallback(() => {
    const m = mapRef.current;
    if (!m) return;

    if (modifyRef.current) {
      m.removeInteraction(modifyRef.current);
      modifyRef.current = null;
    }
    if (snapRef.current) {
      m.removeInteraction(snapRef.current);
      snapRef.current = null;
    }
    if (dblClickRef.current) {
      m.un('dblclick', dblClickRef.current);
      dblClickRef.current = null;
    }
    if (contextMenuRef.current) {
      (m as unknown as { un(type: string, listener: (e: import('ol/MapBrowserEvent').default) => void): void }).un('contextmenu', contextMenuRef.current);
      contextMenuRef.current = null;
    }
    if (pointerMoveRef.current) {
      m.un('pointermove', pointerMoveRef.current);
      pointerMoveRef.current = null;
    }
    if (layerRef.current) {
      m.removeLayer(layerRef.current);
      layerRef.current = null;
    }
    sourceRef.current = null;
    featureRef.current = null;

    setState({
      vertexCount: 0,
      hoveredVertex: null,
      lastEditedVertex: null,
    });
  }, []);

  // --- Main setup effect ---
  useEffect(() => {
    if (!map || !enabled) {
      cleanup();
      return;
    }

    if (vertices.length < 3) return;

    let cancelled = false;

    async function setup() {
      // Dynamic imports (must be dynamic per project rules)
      const [
        { default: VectorSource },
        { default: VectorLayer },
        { default: Feature },
        { default: Polygon },
        { default: Modify },
        { default: Snap },
        olStyle,
      ] = await Promise.all([
        import('ol/source/Vector'),
        import('ol/layer/Vector'),
        import('ol/Feature'),
        import('ol/geom/Polygon'),
        import('ol/interaction/Modify'),
        import('ol/interaction/Snap'),
        import('ol/style'),
      ]);

      const Style = olStyle.Style;
      const FillCls = olStyle.Fill;
      const StrokeCls = olStyle.Stroke;
      const CircleStyle = olStyle.Circle;
      const TextCls = olStyle.Text;

      if (cancelled || !map) return;

      // --- Vector source & layer ---
      const source = new VectorSource();
      const layer = new VectorLayer({
        source,
        style: new Style({
          fill: new FillCls({ color: 'rgba(27, 58, 92, 0.08)' }),
          stroke: new StrokeCls({ color: '#1B3A5C', width: 2.5 }),
        }),
        zIndex: 200,
      });

      // --- Convert vertices to 3857 and build closed ring ---
      const coords21037 = vertices.map(v => [v.easting, v.northing] as [number, number]);
      const coords3857 = await arrayTo3857(coords21037);
      const closedRing: number[][] = [...coords3857.map(c => [...c]), [...coords3857[0]]];

      const polygon = new Polygon([closedRing]);
      const feature = new Feature({ geometry: polygon });
      source.addFeature(feature);

      sourceRef.current = source;
      layerRef.current = layer;
      featureRef.current = feature;

      // --- Modify interaction (drag vertices) ---
      const vertexStyle = new Style({
        image: new CircleStyle({
          radius: 7,
          fill: new FillCls({ color: '#D17B47' }),
          stroke: new StrokeCls({ color: '#FFFFFF', width: 2.5 }),
        }),
        text: new TextCls({
          text: '',
          offsetY: -16,
          fill: new FillCls({ color: '#1B3A5C' }),
          stroke: new StrokeCls({ color: '#FFFFFF', width: 3 }),
          font: 'bold 11px Calibri, sans-serif',
        }),
      });

      const modify = new Modify({
        source,
        style: vertexStyle,
      });

      // Listen for modifyend
      const handleModifyEnd = async () => {
        if (cancelled) return;
        const updated = await readVerticesFromFeature();
        onVerticesChangeRef.current(updated);
        setState(prev => ({
          ...prev,
          vertexCount: updated.length,
        }));
      };
      modify.on('modifyend', handleModifyEnd);

      map.addInteraction(modify);
      modifyRef.current = modify;

      // --- Snap interaction (magnetic snap to own vertices) ---
      let snap: import('ol/interaction/Snap').default | null = null;
      if (snapEnabled) {
        snap = new Snap({
          source,
          pixelTolerance: snapTolerance,
        });
        map.addInteraction(snap);
        snapRef.current = snap;
      }

      // --- Double-click: insert vertex on nearest edge ---
      const handleDblClick = async (evt: import('ol/MapBrowserEvent').default) => {
        evt.stopPropagation();
        if (cancelled) return;

        const pixel = evt.pixel as [number, number];
        const coord = evt.coordinate as [number, number];
        const geom = feature.getGeometry() as OlPolygon;
        const ring = geom.getCoordinates()[0] as number[][];

        // Find nearest edge
        let minDist = Infinity;
        let bestIdx = -1;
        for (let i = 0; i < ring.length - 1; i++) {
          const d = pointToSegmentDist(coord, ring[i] as [number, number], ring[i + 1] as [number, number]);
          if (d < minDist) {
            minDist = d;
            bestIdx = i + 1;
          }
        }

        // Use a generous pixel-based threshold (30 px ≈ 30 m at zoom 16-18)
        const resolution = map.getView().getResolution() ?? 1;
        const threshold = resolution * 30;
        if (minDist > threshold) return;

        // Compute insertion point
        const segStart = ring[bestIdx - 1] as [number, number];
        const segEnd = ring[bestIdx] as [number, number];
        const insertPt = nearestPointOnSegment(coord, segStart, segEnd);

        // Insert into ring (before closing vertex)
        const newRing = [...ring.slice(0, bestIdx), insertPt, ...ring.slice(bestIdx)];
        geom.setCoordinates([newRing]);

        const updated = await readVerticesFromFeature();
        onVerticesChangeRef.current(updated);
        setState(prev => ({
          ...prev,
          vertexCount: updated.length,
          lastEditedVertex: updated[bestIdx]
            ? { ...updated[bestIdx], index: bestIdx }
            : prev.lastEditedVertex,
        }));
      };

      dblClickRef.current = handleDblClick;
      map.on('dblclick', handleDblClick);

      // --- Right-click (contextmenu): remove vertex (min 3) ---
      const handleContextMenu = async (evt: import('ol/MapBrowserEvent').default) => {
        evt.preventDefault();
        evt.stopPropagation();
        if (cancelled) return;

        const coord = evt.coordinate as [number, number];
        const geom = feature.getGeometry() as OlPolygon;
        const ring = geom.getCoordinates()[0] as number[][];

        if (ring.length - 1 <= 3) return; // need at least 3 unique vertices

        // Find nearest vertex (exclude closing vertex)
        let minDist = Infinity;
        let bestIdx = -1;
        for (let i = 0; i < ring.length - 1; i++) {
          const d = vertexDist(coord, ring[i] as [number, number]);
          if (d < minDist) {
            minDist = d;
            bestIdx = i;
          }
        }

        const resolution = map.getView().getResolution() ?? 1;
        const threshold = resolution * 15;
        if (minDist > threshold) return;

        // Remove vertex at bestIdx and rebuild closed ring
        const openRing = ring.slice(0, -1);
        openRing.splice(bestIdx, 1);
        const newRing = [...openRing, [...openRing[0]]];
        geom.setCoordinates([newRing]);

        const updated = await readVerticesFromFeature();
        onVerticesChangeRef.current(updated);
        setState(prev => ({
          ...prev,
          vertexCount: updated.length,
          lastEditedVertex: null,
        }));
      };

      contextMenuRef.current = handleContextMenu;
      (map as unknown as { on(type: string, listener: (e: import('ol/MapBrowserEvent').default) => void): void }).on('contextmenu', handleContextMenu);

      // --- Pointer move: detect hovered vertex for coordinate display ---
      const handlePointerMove = async (evt: import('ol/MapBrowserEvent').default) => {
        if (cancelled) return;

        const coord = evt.coordinate as [number, number];
        const geom = feature.getGeometry() as OlPolygon;
        if (!geom) return;

        const ring = geom.getCoordinates()[0] as number[][];
        let minDist = Infinity;
        let bestIdx = -1;
        for (let i = 0; i < ring.length - 1; i++) {
          const d = vertexDist(coord, ring[i] as [number, number]);
          if (d < minDist) {
            minDist = d;
            bestIdx = i;
          }
        }

        const resolution = map.getView().getResolution() ?? 1;
        const threshold = resolution * 15;

        if (minDist <= threshold && bestIdx >= 0) {
          const [x, y] = ring[bestIdx];
          const [e, n] = await to21037(x, y);
          setState(prev => ({
            ...prev,
            hoveredVertex: { easting: e, northing: n, index: bestIdx },
          }));
        } else {
          setState(prev =>
            prev.hoveredVertex ? { ...prev, hoveredVertex: null } : prev
          );
        }
      };

      pointerMoveRef.current = handlePointerMove;
      map.on('pointermove', handlePointerMove);

      // --- Add layer to map ---
      map.addLayer(layer);

      // --- Initial state ---
      setState({
        vertexCount: vertices.length,
        hoveredVertex: null,
        lastEditedVertex: null,
      });
    }

    setup();

    return () => {
      cancelled = true;
      cleanup();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [map, enabled, snapTolerance, snapEnabled, cleanup, readVerticesFromFeature]);

  // --- Public API ---
  return {
    state,
    cleanup,
    syncVertices,
  };
}

'use client';

import React, {
  createContext,
  useContext,
  useState,
  useCallback,
 useEffect,
  useRef,
  type ReactNode,
} from 'react';
import { useUIStore } from '@/stores/uiStore';
import { useProjectStore } from '@/stores/projectStore';

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export interface BridgeSelection {
  type: 'station' | 'traverse_leg' | 'none';
  index?: number;
  stationName?: string;
  easting?: number;
  northing?: number;
}

export interface ComputationLogEntry {
  id: string;
  timestamp: Date;
  phase: 'input' | 'compute' | 'adjustment' | 'output';
  level: 'info' | 'success' | 'warning' | 'error';
  message: string;
  detail?: string;
  data?: Record<string, unknown>;
}

export interface WorkspaceBridgeContextType {
  // Selection state (data grid ↔ map)
  selection: BridgeSelection;
  setSelection: (sel: BridgeSelection) => void;
  clearSelection: () => void;

  // Computation log
  computationLogs: ComputationLogEntry[];
  addLog: (entry: Omit<ComputationLogEntry, 'id' | 'timestamp'>) => void;
  clearLogs: () => void;

  // Computation state
  isComputing: boolean;
  setIsComputing: (v: boolean) => void;

  // Misclosure / precision (shown in status bar)
  misclosureValue: string;
  setMisclosureValue: (v: string) => void;
  precisionValue: string;
  setPrecisionValue: (v: string) => void;
  areaValue: string;
  setAreaValue: (v: string) => void;
}

/* ------------------------------------------------------------------ */
/*  Default / empty states                                             */
/* ------------------------------------------------------------------ */

const EMPTY_SELECTION: BridgeSelection = { type: 'none' };

const DEFAULT_CONTEXT: WorkspaceBridgeContextType = {
  selection: EMPTY_SELECTION,
  setSelection: () => {},
  clearSelection: () => {},
  computationLogs: [],
  addLog: () => {},
  clearLogs: () => {},
  isComputing: false,
  setIsComputing: () => {},
  misclosureValue: '—',
  setMisclosureValue: () => {},
  precisionValue: '—',
  setPrecisionValue: () => {},
  areaValue: '—',
  setAreaValue: () => {},
};

/* ------------------------------------------------------------------ */
/*  Context                                                            */
/* ------------------------------------------------------------------ */

const WorkspaceBridgeContext =
  createContext<WorkspaceBridgeContextType>(DEFAULT_CONTEXT);

/* ------------------------------------------------------------------ */
/*  Provider                                                           */
/* ------------------------------------------------------------------ */

export function WorkspaceBridgeProvider({ children }: { children: ReactNode }) {
  /* -- Selection -- */
  const [selection, setSelectionState] = useState<BridgeSelection>(EMPTY_SELECTION);

  const uiClearSelection = useUIStore(s => s.clearSelection);
  const uiSetSelectedPointIds = useUIStore(s => s.setSelectedPointIds);
  const uiSetSelectedFeatureId = useUIStore(s => s.setSelectedFeatureId);

  const setSelection = useCallback((sel: BridgeSelection) => {
    setSelectionState(sel);
    // Sync to uiStore so map and other components pick it up
    if (sel.type === 'station' && sel.stationName) {
      uiSetSelectedPointIds([sel.stationName]);
    } else if (sel.type === 'none') {
      uiClearSelection();
    }
  }, [uiSetSelectedPointIds, uiClearSelection]);

  const clearSelection = useCallback(() => {
    setSelectionState(EMPTY_SELECTION);
    uiClearSelection();
  }, [uiClearSelection]);

  /* -- Computation logs -- */
  const [computationLogs, setComputationLogs] = useState<ComputationLogEntry[]>(
    [],
  );

  const addLog = useCallback(
    (entry: Omit<ComputationLogEntry, 'id' | 'timestamp'>) => {
      const id =
        typeof crypto !== 'undefined' && crypto.randomUUID
          ? crypto.randomUUID()
          : `log-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;

      setComputationLogs((prev: ComputationLogEntry[]) => [
        ...prev,
        {
          ...entry,
          id,
          timestamp: new Date(),
        },
      ]);
    },
    [],
  );

  const clearLogs = useCallback(() => {
    setComputationLogs([]);
  }, []);

  /* -- Computation running state -- */
  const [isComputing, setIsComputing] = useState(false);

  /* -- Status bar values -- */
  const [misclosureValue, setMisclosureValue] = useState('—');
  const [precisionValue, setPrecisionValue] = useState('—');
  const [areaValue, setAreaValue] = useState('—');

  // Sync uiStore global loading with isComputing
  const setGlobalLoading = useUIStore(s => s.setGlobalLoading);
  useEffect(() => {
    if (isComputing) {
      setGlobalLoading(true, 'Computing…');
    } else {
      setGlobalLoading(false);
    }
  }, [isComputing, setGlobalLoading]);

  // Expose a ref for accessing the bridge from non-React code (e.g. worker callbacks)
  const bridgeRef = useRef<WorkspaceBridgeContextType | null>(null);
  bridgeRef.current = {
    selection,
    setSelection,
    clearSelection,
    computationLogs,
    addLog,
    clearLogs,
    isComputing,
    setIsComputing,
    misclosureValue,
    setMisclosureValue,
    precisionValue,
    setPrecisionValue,
    areaValue,
    setAreaValue,
  };

  const value: WorkspaceBridgeContextType = bridgeRef.current;

  return (
    <WorkspaceBridgeContext.Provider value={value}>
      {children}
    </WorkspaceBridgeContext.Provider>
  );
}

/* ------------------------------------------------------------------ */
/*  Hook                                                               */
/* ------------------------------------------------------------------ */

export function useWorkspaceBridge(): WorkspaceBridgeContextType {
  const ctx = useContext(WorkspaceBridgeContext);

  // Guard against missing provider – helpful during development
  if (ctx === DEFAULT_CONTEXT) {
    // We intentionally return the default context rather than throwing
    // so the hook is safe to use even without a provider (e.g. in tests
    // or standalone component previews).
  }

  return ctx;
}

export default useWorkspaceBridge;

/**
 * METARDU Smart AI Service (Hybrid Cloud / Edge)
 * =======================================================
 * Automatically switches between NVIDIA NIM Cloud AI and Local WebGPU LLM.
 * 
 * - When online & connected: routes to /api/ai/chat (NVIDIA NIM)
 * - When offline in remote trench: routes to localLlmService (WebLLM - Survey Act Cap 299)
 */

import { localLlmService, LocalChatOptions } from './localLlmService'
import type { InitProgressReport } from '@mlc-ai/web-llm'
import { logger } from '@/lib/logger'

export interface SmartChatOptions {
  messages: Array<{ role: 'system' | 'user' | 'assistant'; content: string }>
  onToken?: (token: string) => void
  onProgress?: (report: InitProgressReport) => void
  forceOffline?: boolean
}

export async function smartChat(options: SmartChatOptions): Promise<string> {
  const isOnline = typeof navigator !== 'undefined' ? navigator.onLine : false

  if (isOnline && !options.forceOffline) {
    try {
      const res = await fetch('/api/ai/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'chat',
          messages: options.messages,
        }),
      })

      if (res.ok) {
        const data = (await res.json()) as { response?: string }
        const text = data.response || ''
        if (options.onToken) {
          options.onToken(text)
        }
        return text
      }
    } catch {
      logger.warn('[smartAiService] Cloud AI request failed — switching to Offline WebGPU LLM Engine')
    }
  }

  // Fallback to Offline Local LLM with Cap 299 Knowledge
  return await localLlmService.chat({
    messages: options.messages,
    onToken: options.onToken,
    onProgress: options.onProgress,
  })
}

const smartAiService = {
  smartChat,
  localLlmService,
}

export default smartAiService

const AI_BASE_URL = process.env.NEXT_PUBLIC_AI_SERVICE_URL || 'https://metardu-ai.up.railway.app'

export interface AICallOptions {
  endpoint: string
  body: Record<string, unknown>
  requirePro?: boolean
}

export interface AIResponse<T> {
  success: boolean
  data: T | null
  error: string | null
  tier: string | null
  callsRemaining: number | null
}

/**
 * Check if the current user has a paid subscription.
 * Uses the /api/subscription endpoint which includes admin email detection
 * and correctly reads from user_subscriptions (not profiles.tier).
 */
async function checkSubscriptionAccess(): Promise<{ allowed: boolean; plan: string; isAdmin: boolean }> {
  try {
    const res = await fetch('/api/subscription', {
      cache: 'no-store',
      credentials: 'same-origin',
    })
    if (!res.ok) return { allowed: false, plan: 'free', isAdmin: false }

    const data = (await res.json()) as { plan?: string; isAdmin?: boolean }
    const plan = data.plan || 'free'
    const isAdmin = data.isAdmin === true

    // Admin always has access; paid plans (pro, team, firm, enterprise) have access
    const allowed = isAdmin || ['pro', 'team', 'firm', 'enterprise'].includes(plan)
    return { allowed, plan, isAdmin }
  } catch {
    return { allowed: false, plan: 'free', isAdmin: false }
  }
}

export async function callAI<T>(options: AICallOptions): Promise<AIResponse<T>> {
  const { endpoint, body, requirePro = true } = options

  if (requirePro) {
    const access = await checkSubscriptionAccess()
    if (!access.allowed) {
      return {
        success: false,
        data: null,
        error: 'PRO_REQUIRED',
        tier: access.plan,
        callsRemaining: null,
      }
    }
  }

  try {
    const response = await fetch(`${AI_BASE_URL}${endpoint}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    })

    if (response.status === 403) {
      return {
        success: false,
        data: null,
        error: 'PRO_REQUIRED',
        tier: null,
        callsRemaining: null,
      }
    }

    if (!response.ok) {
      const errorText = await response.text()
      return {
        success: false,
        data: null,
        error: `AI_SERVICE_ERROR: ${response.status}`,
        tier: null,
        callsRemaining: null,
      }
    }

    const data: unknown = await response.json()
    return {
      success: true,
      data: data as T,
      error: null,
      tier: null,
      callsRemaining: null,
    }
  } catch (err) {
    return {
      success: false,
      data: null,
      error: err instanceof Error ? err.message : 'UNKNOWN_ERROR',
      tier: null,
      callsRemaining: null,
    }
  }
}

export function isProError(response: AIResponse<unknown>): boolean {
  return !response.success && response.error === 'PRO_REQUIRED'
}

/**
 * apiHandler — Next-generation standardized API route wrapper for METARDU.
 *
 * @deprecated (audit H3, 2026-07-02): Use `@/lib/apiHandler` (v1) instead.
 *   The v1 handler now has feature parity with this v2:
 *     - X-Request-Id header (opt-in via `requestId: true`, default true)
 *     - Structured JSON error logging (opt-in via `structuredLogs: true`, default true)
 *     - Tamper-evident audit chain (opt-in via `auditChain` option)
