} as const

// ---------------------------------------------------------------------------
// Precision Validation
// ---------------------------------------------------------------------------

export interface PrecisionCheck {
  field: string
  value: string
  isValid: boolean
  expectedFormat: string
}

/**
 * Validate that coordinates meet SoK precision requirements.
 */
export function validateCoordinatePrecision(easting: number, northing: number): PrecisionCheck[] {
  const checks: PrecisionCheck[] = []

  // Easting should be 6-7 digits + 3 decimals for UTM 37S
  const eStr = easting.toFixed(3)
  checks.push({
    field: 'Easting',
    value: eStr,
    isValid: /^\d{6,7}\.\d{3}$/.test(eStr),
    expectedFormat: 'XXXXXX.XXX (6-7 digits, 3 decimals)',
  })

  // Northing should be 7 digits + 3 decimals for UTM 37S (equatorial)
  const nStr = northing.toFixed(3)
  checks.push({
    field: 'Northing',
    value: nStr,
    isValid: /^\d{7}\.\d{3}$/.test(nStr),
    expectedFormat: 'XXXXXXX.XXX (7 digits, 3 decimals)',
  })

  return checks
}

/**
 * Deed Plan Template — Kenya Survey Department Standard
 *
 * Generates a complete vector PDF deed plan that meets Kenya
 * Survey Department (SoK) standards for submission to Ardhi House.
 *
 * Layout: A1 landscape (841 × 594mm)
 * Title block in bottom-right corner (SoK standard layout)
 * Grid overlay with Cassini-Soldner or UTM coordinates
 * North arrow with grid convergence
 * Beacon schedule table
 * Area computation table
 * Surveyor signature block
 * Plan number, LR number, registry
 * Scale bar
 *
 * Watermark:
 * - Free plan: "METARDU" watermark diagonally across the plan
 * - Paid plan + company logo: Logo in title block
 * - Paid plan + no logo: Blank (no watermark)
 */

import {
  createSurveyDocument,
  drawLine,
  drawRect,
  drawText,
  drawBeaconSymbol,
  drawNorthArrow,
  drawScaleBar,
  drawCompanyLogo,
  drawMetarduWatermark,
  PAPER_SIZES,
  LINE_WEIGHTS,
  TEXT_SIZES,
  type PaperSizeName,
  type DocumentMetadata,
} from '../pdf-engine';
import type { DocumentTemplate, TemplateGenerateOptions } from './registry';
import type { ResolvedLogo } from '../resolve-logo';
import type { PlanId } from '@/lib/subscription/catalog';

// ─── Types ───────────────────────────────────────────────────────

export interface DeedPlanPoint {
  easting: number;
  northing: number;
  label: string;
  beaconType: 'control' | 'beacon' | 'benchmark';
  description?: string;
}

export interface DeedPlanBoundary {
  fromIndex: number;
  toIndex: number;
  type: 'scheme' | 'parcel' | 'road' | 'river' | 'dimension';
  bearing?: string;
  distance?: string;
}

export interface DeedPlanTemplateData {
  /** Points defining the parcel boundary */
  points: DeedPlanPoint[];
  /** Boundary lines connecting points */
  boundaries: DeedPlanBoundary[];
  /** Paper size (A1 or A2) */
  paperSize: PaperSizeName;
  /** Map scale (e.g., 1000 for 1:1000) */
  scale: number;
  /** Title block data */
  titleData: {
    lrNumber: string;
    area: string;
    scale: number;
    surveyorName: string;
    surveyorLicense: string;
    date: string;
    county: string;
    subCounty?: string;
    revision?: string;
    projection?: string;
    datum?: string;
    planNumber?: string;
    registry?: string;
    /** Registry Map Sheet reference number (required by Survey Act Cap 299) */
    registryMapSheet?: string;
    /** Deed Plan number (DP number) */
    deedPlanNumber?: string;
    /** Director of Surveys approval reference */
    directorOfSurveysRef?: string;
  };
  /** Document metadata */
  metadata: DocumentMetadata;
  /** Grid convergence at map center (decimal degrees) */
  convergence?: number;
  /** Grid interval in meters (default: auto) */
  gridInterval?: number;
  /** Margin around map area (mm) */
  mapMargin?: number;
}

// ─── Constants ───────────────────────────────────────────────────

const TITLE_BLOCK_RESERVE = 70; // mm reserved for title block at bottom (increased for DoS approval block)
const MARGIN = 15; // mm margin around the page

// ─── Core Generator ──────────────────────────────────────────────

async function generateDeedPlanPdf(
  data: DeedPlanTemplateData,
  options?: TemplateGenerateOptions
): Promise<Buffer> {
  const {
    points,
    boundaries,
    paperSize,
    scale,
    titleData,
    metadata,
    convergence,
    gridInterval,
    mapMargin = 10,
  } = data;

  const plan: PlanId = options?.plan ?? 'free';
  const companyLogo: ResolvedLogo | null = options?.companyLogo ?? null;

  const paper = PAPER_SIZES[paperSize];

  // Create PDF document (landscape orientation for deed plans)
  const doc = createSurveyDocument({
    paperSize,
    orientation: 'landscape',
    scale,
    metadata,
    companyLogo: companyLogo?.data ?? null,
    plan,
  });

  // Collect PDF data into a buffer
  const chunks: Buffer[] = [];
  doc.on('data', (chunk: Buffer) => chunks.push(chunk));

  const pdfPromise = new Promise<Buffer>((resolve) => {
    doc.on('end', () => resolve(Buffer.concat(chunks)));
  });

  // ─── Page dimensions (landscape) ──────────────────────────────
  const pageW = paper.height; // Landscape: swap width/height
  const pageH = paper.width;

  // ─── Apply METARDU watermark for free plan ────────────────────
  if (plan === 'free') {
    drawMetarduWatermark(doc, pageW, pageH);
  }

  // ─── Compute map area ─────────────────────────────────────────
  const mapAreaX = MARGIN;
  const mapAreaY = MARGIN;
  const mapAreaW = pageW - 2 * MARGIN;
  const mapAreaH = pageH - 2 * MARGIN - TITLE_BLOCK_RESERVE;

  // ─── Compute coordinate extent of the survey ──────────────────
  const eastings = points.map((p) => p.easting);
  const northings = points.map((p) => p.northing);

  const minE = Math.min(...eastings);
  const maxE = Math.max(...eastings);
  const minN = Math.min(...northings);
  const maxN = Math.max(...northings);

  // Add 10% padding around the survey area
  const rangeE = maxE - minE || 100;
  const rangeN = maxN - minN || 100;
  const paddingE = rangeE * 0.1;
  const paddingN = rangeN * 0.1;

  const originE = minE - paddingE;
  const originN = minN - paddingN;
  const extentE = rangeE + 2 * paddingE;
  const extentN = rangeN + 2 * paddingN;

  // mm per meter on the plan
  const mmPerMeter = 1000 / scale;

  // ─── Draw map border ──────────────────────────────────────────
  drawRect(doc, mapAreaX, mapAreaY, mapAreaW, mapAreaH, LINE_WEIGHTS.titleBorder);

  // ─── Draw coordinate grid (UTM ticks) ─────────────────────────
  const gridInt = gridInterval ?? computeGridInterval(scale);
  drawGridTicks(doc, originE, originN, extentE, extentN,
    mapAreaX + mapMargin, mapAreaY + mapMargin,
    mapAreaW - 2 * mapMargin, mapAreaH - 2 * mapMargin,
    scale, gridInt);

  // ─── Coordinate transform: ground (meters) → paper (mm) ───────
  const groundToPaperX = (easting: number) => {
    return mapAreaX + mapMargin + (easting - originE) * mmPerMeter;
  };
  const groundToPaperY = (northing: number) => {
    return mapAreaY + mapMargin + (maxN + paddingN - northing) * mmPerMeter;
  };

  // ─── Draw boundary lines ──────────────────────────────────────
  for (const boundary of boundaries) {
    const fromPt = points[boundary.fromIndex];
    const toPt = points[boundary.toIndex];

    if (!fromPt || !toPt) continue;

    const x1 = groundToPaperX(fromPt.easting);
    const y1 = groundToPaperY(fromPt.northing);
    const x2 = groundToPaperX(toPt.easting);
    const y2 = groundToPaperY(toPt.northing);

    // Draw boundary line with appropriate weight
    const weight = boundary.type === 'scheme' ? LINE_WEIGHTS.schemeBoundary
      : boundary.type === 'road' ? LINE_WEIGHTS.roadLine
      : LINE_WEIGHTS.parcelBoundary;

    drawLine(doc, x1, y1, x2, y2, weight);

    // Bearing and distance labels
    if (boundary.bearing || boundary.distance) {
      const midX = (x1 + x2) / 2;
      const midY = (y1 + y2) / 2;

      // Offset label perpendicular to the line
      const dx = x2 - x1;
      const dy = y2 - y1;
      const length = Math.sqrt(dx * dx + dy * dy) || 1;
      const nx = (-dy / length) * 3;
      const ny = (dx / length) * 3;

      if (boundary.bearing) {
        drawText(doc, boundary.bearing, midX + nx, midY + ny, TEXT_SIZES.bearing, { align: 'center' });
      }
      if (boundary.distance) {
        drawText(doc, boundary.distance, midX + nx, midY + ny + 2, TEXT_SIZES.dimension, { align: 'center' });
      }
    }
  }

  // ─── Draw beacon symbols ──────────────────────────────────────
  for (const point of points) {
    const px = groundToPaperX(point.easting);
    const py = groundToPaperY(point.northing);

    drawBeaconSymbol(doc, px, py, 3, 0.15);
    drawText(doc, point.label, px + 3, py - 1, TEXT_SIZES.coordinate);

    // Coordinate label
    const coordText = `E ${point.easting.toFixed(1)}  N ${point.northing.toFixed(1)}`;
    drawText(doc, coordText, px + 3, py + 1.5, TEXT_SIZES.small);
  }

  // ─── Draw beacon schedule table ───────────────────────────────
  const scheduleX = mapAreaX;
  const scheduleY = pageH - MARGIN - TITLE_BLOCK_RESERVE;
  drawBeaconSchedule(doc, points, scheduleX, scheduleY);

  // ─── Draw area computation table ──────────────────────────────
  const areaX = scheduleX + 205;
  drawAreaTable(doc, titleData.area, areaX, scheduleY, 120);

  // ─── Draw title block (SoK standard, bottom-right) ────────────
  drawDeedPlanTitleBlock(doc, pageW - MARGIN, pageH - MARGIN, titleData, companyLogo, plan);

  // ─── North arrow ──────────────────────────────────────────────
  drawNorthArrow(doc, MARGIN + 15, MARGIN + 25, 15, convergence);

  // ─── Scale bar ────────────────────────────────────────────────
  const groundDistance = scale <= 1000 ? 100 : 200;
  drawScaleBar(doc, MARGIN + 5, scheduleY - 10, scale, 80, groundDistance, 0.3);

  // ─── Finalize PDF ─────────────────────────────────────────────
  doc.end();

  return pdfPromise;
}

// ─── Helper: Draw grid ticks ─────────────────────────────────────

function drawGridTicks(
  doc: PDFKit.PDFDocument,
  originE: number, originN: number,
  extentE: number, extentN: number,
  paperX: number, paperY: number,
  paperW: number, paperH: number,
  scale: number, gridInterval: number
): void {
  const mmPerMeter = 1000 / scale;
  const tickLength = 2; // mm

  // Easting ticks (vertical lines at grid interval)
  const firstE = Math.ceil(originE / gridInterval) * gridInterval;
  for (let e = firstE; e <= originE + extentE; e += gridInterval) {
    const dx = (e - originE) * mmPerMeter;
    const px = paperX + dx;
    if (px < paperX || px > paperX + paperW) continue;

    // Top and bottom ticks
    drawLine(doc, px, paperY, px, paperY - tickLength, LINE_WEIGHTS.gridLine);
    drawLine(doc, px, paperY + paperH, px, paperY + paperH + tickLength, LINE_WEIGHTS.gridLine);

    // Coordinate label
    drawText(doc, Math.round(e).toString(), px, paperY + paperH + tickLength + 0.5, TEXT_SIZES.gridLabel, { align: 'center' });
  }

  // Northing ticks (horizontal lines at grid interval)
  const firstN = Math.ceil(originN / gridInterval) * gridInterval;
  for (let n = firstN; n <= originN + extentN; n += gridInterval) {
    const dy = (n - originN) * mmPerMeter;
    const py = paperY + paperH - dy;
    if (py < paperY || py > paperY + paperH) continue;

    // Left and right ticks
    drawLine(doc, paperX, py, paperX - tickLength, py, LINE_WEIGHTS.gridLine);
    drawLine(doc, paperX + paperW, py, paperX + paperW + tickLength, py, LINE_WEIGHTS.gridLine);

    // Coordinate label
    drawText(doc, Math.round(n).toString(), paperX - tickLength - 1, py - 0.75, TEXT_SIZES.gridLabel, { align: 'right' });
  }
}

// ─── Helper: Beacon Schedule Table ───────────────────────────────

function drawBeaconSchedule(
  doc: PDFKit.PDFDocument,
  points: DeedPlanPoint[],
  x: number, y: number
): void {
  const mmToPt = 2.8346;
  const rowHeight = 5;
  const headerHeight = 6;
  const colWidths = [30, 55, 55, 60];
  const headers = ['Beacon', 'Easting', 'Northing', 'Description'];

  // Header row
  let cx = x;
  for (let i = 0; i < headers.length; i++) {
    drawRect(doc, cx, y, colWidths[i], headerHeight, 0.2, 'black', '#E0E0E0');
    drawText(doc, headers[i], cx + 1, y + 1, TEXT_SIZES.small, { bold: true });
    cx += colWidths[i];
  }

  // Data rows (max 8 rows for space)
  const maxRows = Math.min(points.length, 8);
  for (let r = 0; r < maxRows; r++) {
    cx = x;
    const rowY = y + headerHeight + r * rowHeight;
    const pt = points[r];
    const values = [
      pt.label,
      pt.easting.toFixed(3),
      pt.northing.toFixed(3),
      pt.description ?? '',
    ];

    for (let i = 0; i < colWidths.length; i++) {
      drawRect(doc, cx, rowY, colWidths[i], rowHeight, 0.08);
      drawText(doc, values[i], cx + 1, rowY + 1, TEXT_SIZES.small);
      cx += colWidths[i];
    }
  }
}

// ─── Helper: Area Computation Table ──────────────────────────────

function drawAreaTable(
  doc: PDFKit.PDFDocument,
  area: string,
  x: number, y: number,
  width: number
): void {
  const rowHeight = 5;

  drawRect(doc, x, y, width, 6, 0.2, 'black', '#E0E0E0');
  drawText(doc, 'AREA COMPUTATION', x + 2, y + 1, TEXT_SIZES.small, { bold: true });

  drawRect(doc, x, y + 6, width, rowHeight, 0.08);
  drawText(doc, 'Area:', x + 2, y + 7, TEXT_SIZES.small, { bold: true });
  drawText(doc, `${area} Ha`, x + 30, y + 7, TEXT_SIZES.coordinate);

  // Note about computation method
  drawRect(doc, x, y + 6 + rowHeight, width, rowHeight, 0.08);
  drawText(doc, 'Method:', x + 2, y + 7 + rowHeight, TEXT_SIZES.small, { bold: true });
  drawText(doc, 'Coordinates', x + 30, y + 7 + rowHeight, TEXT_SIZES.small);

  // Survey Act reference
  drawRect(doc, x, y + 6 + rowHeight * 2, width, rowHeight, 0.08);
  drawText(doc, 'Ref:', x + 2, y + 7 + rowHeight * 2, TEXT_SIZES.small, { bold: true });
  drawText(doc, 'Survey Act Cap 299', x + 30, y + 7 + rowHeight * 2, TEXT_SIZES.small);
}

// ─── Helper: Deed Plan Title Block (SoK Standard) ───────────────

function drawDeedPlanTitleBlock(
  doc: PDFKit.PDFDocument,
  x: number, y: number,
  data: DeedPlanTemplateData['titleData'],
  companyLogo: ResolvedLogo | null,
  plan: PlanId
): void {
  const tbWidth = 180;
  const tbHeight = 65; // Increased to accommodate Republic of Kenya header and DoS block
  const innerMargin = 3;
  const rowHeight = 5;

  // Title block origin (top-left corner)
  const bx = x - tbWidth;
  const by = y - tbHeight;

  // Outer border
  drawRect(doc, bx, by, tbWidth, tbHeight, LINE_WEIGHTS.titleBorder);

  // ─── Logo area (top-left of title block) ──────────────────────
  if (companyLogo?.data) {
    // Render company logo in title block (max 40x15mm)
    drawCompanyLogo(doc, companyLogo.data, bx + innerMargin, by + innerMargin, 40, 10);
  } else if (plan === 'free') {
    // METARDU text for free tier
    drawText(doc, 'METARDU', bx + innerMargin, by + innerMargin, 4, {
      bold: true,
      color: '#999999',
    });
  }
  // If paid plan but no logo: leave blank

  // ─── Republic of Kenya Header (required by Survey Act Cap 299) ──
  const headerY = by + innerMargin;
  drawText(doc, 'REPUBLIC OF KENYA', bx + 50, headerY, TEXT_SIZES.small, {
    bold: true,
    align: 'center',
  });

  // Deed Plan title
  drawText(doc, 'DEED PLAN', bx + 50, headerY + 3.5, TEXT_SIZES.titleBlock, {
    bold: true,
    align: 'center',
  });

  // DP number (Deed Plan number)
  if (data.deedPlanNumber) {
    drawText(doc, `DP No. ${data.deedPlanNumber}`, bx + 120, headerY, TEXT_SIZES.small, { bold: true });
  }
  // Fallback: planNumber
  if (!data.deedPlanNumber && data.planNumber) {
    drawText(doc, `Plan No. ${data.planNumber}`, bx + 120, headerY, TEXT_SIZES.small);
  }

  // Separator line below header
  drawLine(doc, bx, by + rowHeight * 3 + 3, bx + tbWidth, by + rowHeight * 3 + 3, 0.3);

  // ─── Data rows (two columns) ─────────────────────────────────
  const currentY = by + rowHeight * 3 + 3 + innerMargin;
  const col1X = bx + innerMargin;
  const col2X = bx + tbWidth / 2 + innerMargin;
  const labelWidth = 32;

  // Left column
  drawLabelValue(doc, col1X, currentY, 'LR No.:', data.lrNumber, labelWidth);
  drawLabelValue(doc, col1X, currentY + rowHeight, 'Area:', data.area, labelWidth);
  drawLabelValue(doc, col1X, currentY + rowHeight * 2, 'Scale:', `1:${data.scale}`, labelWidth);
  drawLabelValue(doc, col1X, currentY + rowHeight * 3, 'County:', data.county, labelWidth);
  if (data.registryMapSheet) {
    drawLabelValue(doc, col1X, currentY + rowHeight * 4, 'Reg. Map:', data.registryMapSheet, labelWidth);
  }

  // Right column
  drawLabelValue(doc, col2X, currentY, 'Surveyor:', data.surveyorName, labelWidth);
  drawLabelValue(doc, col2X, currentY + rowHeight, 'License:', data.surveyorLicense, labelWidth);
  drawLabelValue(doc, col2X, currentY + rowHeight * 2, 'Date:', data.date, labelWidth);
  drawLabelValue(doc, col2X, currentY + rowHeight * 3, 'Datum:', data.datum ?? 'Arc 1960', labelWidth);
  if (data.registry) {
    drawLabelValue(doc, col2X, currentY + rowHeight * 4, 'Registry:', data.registry, labelWidth);
  }

  // Column separator
  drawLine(doc, bx + tbWidth / 2, by + rowHeight * 3 + 3, bx + tbWidth / 2, by + tbHeight, 0.15);

  // ─── Revision ────────────────────────────────────────────────
  if (data.revision) {
    drawText(doc, `Rev: ${data.revision}`, bx + tbWidth - 30, by + tbHeight - 5, TEXT_SIZES.small);
  }

  // ─── Director of Surveys Approval Block (required by Survey Act Cap 299) ─
  const dosY = by + tbHeight - 8;
  drawLine(doc, bx, dosY, bx + tbWidth, dosY, 0.15);
  drawText(doc, 'DIRECTOR OF SURVEYS', bx + innerMargin, dosY + 1, TEXT_SIZES.small, { bold: true });
  if (data.directorOfSurveysRef) {
    drawText(doc, `Ref: ${data.directorOfSurveysRef}`, bx + innerMargin + 45, dosY + 1, TEXT_SIZES.small);
  }
  drawLine(doc, bx + 80, dosY + 5, bx + tbWidth - 3, dosY + 5, 0.15);
  drawText(doc, 'Approved / Date', bx + 80, dosY + 6, TEXT_SIZES.small);

  // ─── Surveyor signature block ────────────────────────────────
  const sigY = by + tbHeight + 3;
  drawLine(doc, bx + 80, sigY, bx + tbWidth, sigY, 0.2);
  drawText(doc, `Signed: ${data.surveyorName}`, bx + 80, sigY + 1, TEXT_SIZES.small);
  drawText(doc, `(${data.surveyorLicense})`, bx + 80, sigY + 3, TEXT_SIZES.small);
}

/** Draw a label-value pair */
function drawLabelValue(
  doc: PDFKit.PDFDocument,
  x: number, y: number,
  label: string, value: string,
  labelWidth: number
): void {
  drawText(doc, label, x, y, TEXT_SIZES.small, { bold: true });
  drawText(doc, value, x + labelWidth, y, TEXT_SIZES.coordinate);
}

/** Compute grid interval from scale */
function computeGridInterval(scale: number): number {
  if (scale <= 500) return 50;
  if (scale <= 2000) return 100;
  if (scale <= 5000) return 200;
  if (scale <= 10000) return 500;
  return 1000;
}

// ─── Template Registration ───────────────────────────────────────

export const DEED_PLAN_TEMPLATE: DocumentTemplate<DeedPlanTemplateData> = {
  id: 'deed-plan',
  name: 'Kenya Deed Plan',
  description: 'A1 landscape deed plan with grid, north arrow, beacon schedule, area table, and SoK standard title block',
  documentType: 'deed-plan',
  paperSize: 'A1',
  orientation: 'landscape',
  generate: generateDeedPlanPdf,
};

/**
 * @module mutationVectorLayout
 *
 * Automated Mutation Form Vector Layout Engine
 *
 * Generates print-ready Mutation Form PDFs with:
 * - Parent parcel boundary drawing (vector)
 * - Subdivision boundaries overlaid
 * - North arrow pointing up (parallel to sheet sides)
 * - Scale bar at standard scales (1:1000, 1:2500, 1:5000)
 * - Area allocation schedule (text blocks, uppercase)
 * - Beacon schedule
 * - Surveyor signature block
 *
 * Per Survey of Kenya regulations:
 * - North must be vertical and parallel to sheet sides
 * - Drawing auto-scales to fit standard survey scales
 * - Area schedules in capital letters, upright open style
 */

import PDFDocument from 'pdfkit'
import {
  createSurveyDocument,
  drawLine,
  drawRect,
  drawText,
  drawCompanyLogo,
  drawMetarduWatermark,
  drawDigitalSignatureStamp,
  PAPER_SIZES,
  LINE_WEIGHTS,
  TEXT_SIZES,
} from '../pdf-engine'
import { drawGridOverlay } from '../deed-plan/grid-overlay'
import type { SurveyPoint } from '@/lib/map/turfHelpers'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface MutationLayoutData {
  // Parent parcel
  parentParcelNumber: string
  parentTitleDeed: string
  parentAreaHectares: number
  parentVertices: SurveyPoint[]

  // Resulting parcels (subdivisions)
  resultingParcels: Array<{
    parcelNumber: string
    vertices: SurveyPoint[]
    areaHectares: number
  }>

  // Beacons
  beacons: Array<{
    beaconNumber: string
    coordinate: SurveyPoint
    description?: string
  }>

  // Surveyor
  surveyorName: string
  surveyorLicense: string
  surveyorFirm?: string
  registry: string
  county: string
  datePrepared: string

  // Scale
  scale?: 500 | 1000 | 2500 | 5000

  // Branding
  plan?: 'free' | 'pro' | 'team' | 'firm' | 'enterprise'
  companyLogo?: Buffer | null
}

// ---------------------------------------------------------------------------
// Geometry helpers
// ---------------------------------------------------------------------------

/**
 * Calculate the bounding box of all vertices.
 */
function getBoundingBox(vertices: SurveyPoint[]): {
  minE: number; maxE: number; minN: number; maxN: number
  width: number; height: number
} {
  if (vertices.length === 0) {
    return { minE: 0, maxE: 0, minN: 0, maxN: 0, width: 0, height: 0 }
  }
  let minE = vertices[0].easting
  let maxE = vertices[0].easting
  let minN = vertices[0].northing
  let maxN = vertices[0].northing

  for (const v of vertices) {
    minE = Math.min(minE, v.easting)
    maxE = Math.max(maxE, v.easting)
    minN = Math.min(minN, v.northing)
    maxN = Math.max(maxN, v.northing)
  }

  return {
    minE, maxE, minN, maxN,
    width: maxE - minE,
    height: maxN - minN,
  }
}

/**
 * Auto-select the best standard scale to fit the drawing.
 */
function autoSelectScale(bboxWidth: number, bboxHeight: number, availableWidthMm: number, availableHeightMm: number): number {
  // Convert mm to meters at scale
  const scales = [500, 1000, 2500, 5000]
  for (const scale of scales) {
    const drawingWidthMm = (bboxWidth / scale) * 1000
    const drawingHeightMm = (bboxHeight / scale) * 1000
    if (drawingWidthMm <= availableWidthMm && drawingHeightMm <= availableHeightMm) {
      return scale
    }
  }
  // Default to largest if nothing fits
  return 5000
}

function transformToPage(
  vertex: SurveyPoint,
  bbox: ReturnType<typeof getBoundingBox>,
  scale: number,
  originX: number,
  originY: number,
): [number, number] {
  const scaleM = scale / 1000 // meters per mm
  const dxMm = (vertex.easting - bbox.minE) / scaleM
  const dyMm = (bbox.maxN - vertex.northing) / scaleM // Y inverted

  return [originX + dxMm, originY + dyMm]
}

// ---------------------------------------------------------------------------
// North Arrow
// ---------------------------------------------------------------------------

function drawNorthArrow(doc: PDFKit.PDFDocument, x: number, y: number, size: number = 15) {
  // North arrow pointing up (parallel to sheet sides)
  const halfSize = size / 2

  // Arrow shaft
  drawLine(doc, x, y, x, y + size, LINE_WEIGHTS.parcelBoundary)

  // Arrowhead (triangle pointing up)
  doc.save()
  doc.moveTo(x - halfSize * 0.4, y + size * 0.6)
  doc.lineTo(x, y + size)
  doc.lineTo(x + halfSize * 0.4, y + size * 0.6)
  doc.closePath()
  doc.fillColor('black')
  doc.fill()
  doc.restore()

  // "N" label above arrow
  drawText(doc, 'N', x - 1.5, y + size + 1, TEXT_SIZES.gridLabel, { bold: true })
}

// ---------------------------------------------------------------------------
// Scale Bar
// ---------------------------------------------------------------------------

function drawScaleBar(doc: PDFKit.PDFDocument, x: number, y: number, scale: number, lengthM: number) {
  // Draw a scale bar showing `lengthM` meters at the given scale
  const lengthMm = (lengthM / scale) * 1000

  // Main bar
  drawRect(doc, x, y, lengthMm, 1.5, LINE_WEIGHTS.gridLine, 'black', '#000000')

  // Divisions (4 segments)
  const segWidth = lengthMm / 4
  for (let i = 0; i < 4; i++) {
    if (i % 2 === 1) {
      drawRect(doc, x + i * segWidth, y, segWidth, 1.5, 0, 'black', '#000000')
    }
  }

  // Tick marks and labels
  for (let i = 0; i <= 4; i++) {
    const tickX = x + i * segWidth
    drawLine(doc, tickX, y - 1, tickX, y + 2.5, LINE_WEIGHTS.gridLine)
    const label = `${(lengthM * i / 4).toFixed(0)}`
    drawText(doc, label, tickX - 2, y - 4, TEXT_SIZES.gridLabel)
  }

  // Scale text
  drawText(doc, `SCALE 1:${scale}`, x, y + 4, TEXT_SIZES.gridLabel, { bold: true })
}

// ---------------------------------------------------------------------------
// Main Generator
// ---------------------------------------------------------------------------

export async function generateMutationVectorLayout(data: MutationLayoutData): Promise<Buffer> {
  const scale = data.scale || 1000

  const doc = createSurveyDocument({
    paperSize: 'A3',
    orientation: 'landscape',
    scale,
    metadata: {
      title: `Mutation Form — ${data.parentParcelNumber}`,
      surveyorName: data.surveyorName,
      surveyorLicense: data.surveyorLicense,
      projectReference: data.parentParcelNumber,
      date: data.datePrepared,
    },
    plan: data.plan,
    companyLogo: data.companyLogo,
  })

  const chunks: Buffer[] = []
  doc.on('data', (chunk: Buffer) => chunks.push(chunk))
  const pdfPromise = new Promise<Buffer>((resolve) => {
    doc.on('end', () => resolve(Buffer.concat(chunks)))
  })

  const mmToPt = 2.8346
  const pageWidth = 420 // A3 landscape width in mm
  const pageHeight = 297
  const mx = 20 // left/right margin

  let y = 15

  // ─── Header ──────────────────────────────────────────────────
  drawText(doc, 'REPUBLIC OF KENYA', mx, y, 6, { align: 'center', bold: true })
  y += 7
  drawText(doc, 'THE SURVEY ACT (CAP 299)', mx, y, 3.5, { align: 'center', bold: true })
  y += 6
  drawText(doc, 'MUTATION FORM', mx, y, 7, { align: 'center', bold: true })
  y += 8
  drawText(doc, `${data.registry} — ${data.county}`, mx, y, 3, { align: 'center' })
  y += 8

  // Separator
  drawLine(doc, mx, y, pageWidth - mx, y, LINE_WEIGHTS.titleBorder)
  y += 5

  // ─── Drawing Area ────────────────────────────────────────────
  // Left side: vector drawing (60% of page)
  const drawingWidth = (pageWidth - 2 * mx) * 0.6
  const drawingHeight = pageHeight - y - 80 // leave room for schedules
  const drawingX = mx
  const drawingY = y

  // Drawing border
  drawRect(doc, drawingX, drawingY, drawingWidth, drawingHeight, LINE_WEIGHTS.parcelBoundary)

  // Collect all vertices (parent + subdivisions) for bounding box
  const allVertices = [
    ...data.parentVertices,
    ...data.resultingParcels.flatMap(p => p.vertices),
  ]

  const bbox = getBoundingBox(allVertices)

  // Auto-select scale if not specified
  const actualScale = data.scale || autoSelectScale(
    bbox.width, bbox.height,
    drawingWidth - 20, drawingHeight - 20,
  )

  const mapMargin = 10;
  
  // Draw Grid Overlay
  drawGridOverlay(doc, {
    originEasting: bbox.minE,
    originNorthing: bbox.minN,
    groundWidth: bbox.width,
    groundHeight: bbox.height,
    paperOriginX: drawingX + mapMargin,
    paperOriginY: drawingY + mapMargin,
    paperWidth: drawingWidth - 2 * mapMargin,
    paperHeight: drawingHeight - 2 * mapMargin,
    scale: actualScale,
  })

  // Draw parent parcel boundary
  if (data.parentVertices.length >= 2) {
    doc.save()
    doc.lineWidth(LINE_WEIGHTS.parcelBoundary)
    doc.strokeColor('black')

    const firstPt = transformToPage(
      data.parentVertices[0], bbox, actualScale,
      drawingX + mapMargin, drawingY + mapMargin
    )
    doc.moveTo(firstPt[0], firstPt[1])

    for (let i = 1; i < data.parentVertices.length; i++) {
      const pt = transformToPage(
        data.parentVertices[i], bbox, actualScale,
        drawingX + mapMargin, drawingY + mapMargin
      )
      doc.lineTo(pt[0], pt[1])
    }
    doc.closePath()
    doc.stroke()
    doc.restore()
  }

  // Draw subdivision boundaries
  for (const parcel of data.resultingParcels) {
    if (parcel.vertices.length < 2) continue

    // dashed line for subdivisions
    doc.save()
    doc.lineWidth(LINE_WEIGHTS.gridLine)
    doc.strokeColor('#333333')

    const firstPt = transformToPage(
      parcel.vertices[0], bbox, actualScale,
      drawingX + mapMargin, drawingY + mapMargin
    )
    doc.moveTo(firstPt[0], firstPt[1])

    for (let i = 1; i < parcel.vertices.length; i++) {
      const pt = transformToPage(
        parcel.vertices[i], bbox, actualScale,
        drawingX + mapMargin, drawingY + mapMargin
      )
      doc.lineTo(pt[0], pt[1])
    }
    doc.closePath()
    doc.stroke()
    doc.restore()

    // Label parcel number at centroid
    const centroid: SurveyPoint = parcel.vertices.reduce(
      (acc, v) => ({ easting: acc.easting + v.easting / parcel.vertices.length, northing: acc.northing + v.northing / parcel.vertices.length }),
      { easting: 0, northing: 0 },
    )
    const labelPt = transformToPage(
      centroid, bbox, actualScale,
      drawingX + mapMargin, drawingY + mapMargin
    )
    drawText(doc, parcel.parcelNumber, labelPt[0] - 5, labelPt[1] - 1, TEXT_SIZES.small, { bold: true })
  }

  // Draw beacons
  for (const beacon of data.beacons) {
    const pt = transformToPage(
      beacon.coordinate, bbox, actualScale,
      drawingX + mapMargin, drawingY + mapMargin
    )
    // Small cross marker
    doc.save()
    doc.lineWidth(0.2)
    doc.lineJoin('round')
    doc.circle(pt[0], pt[1], 0.8)
    doc.fillColor('black')
    doc.fill()
    doc.restore()

    // Beacon label
    drawText(doc, beacon.beaconNumber, pt[0] + 1, pt[1] - 1, TEXT_SIZES.small, )
  }

  // North arrow (top-right of drawing area, pointing up)
  drawNorthArrow(doc, drawingX + drawingWidth - 15, drawingY + 5, 12)

  // Scale bar (bottom-left of drawing area)
  drawScaleBar(doc, drawingX + 5, drawingY + drawingHeight - 10, actualScale, 50)

  // ─── Right side: Schedules ───────────────────────────────────
  const scheduleX = mx + drawingWidth + 10
  const scheduleWidth = pageWidth - mx - scheduleX
  let sy = drawingY

  // Area Allocation Schedule
  drawText(doc, 'AREA ALLOCATION SCHEDULE', scheduleX, sy, 4, { bold: true })
  sy += 6

  drawLine(doc, scheduleX, sy, scheduleX + scheduleWidth, sy, LINE_WEIGHTS.gridLine)
  sy += 3

  // Table header
  drawText(doc, 'PARCEL NO.', scheduleX, sy, 2.5, { bold: true })
  drawText(doc, 'AREA (HA)', scheduleX + scheduleWidth * 0.6, sy, 2.5, { bold: true, align: 'right' })
  sy += 4
  drawLine(doc, scheduleX, sy, scheduleX + scheduleWidth, sy, 0.1)
  sy += 3

  // Parent parcel
  drawText(doc, data.parentParcelNumber, scheduleX, sy, TEXT_SIZES.small)
  drawText(doc, data.parentAreaHectares.toFixed(4), scheduleX + scheduleWidth * 0.6, sy, TEXT_SIZES.small, { align: 'right' })
  sy += 4

  // Resulting parcels (uppercase per SoK standard)
  for (const parcel of data.resultingParcels) {
    drawText(doc, parcel.parcelNumber.toUpperCase(), scheduleX, sy, TEXT_SIZES.small)
    drawText(doc, parcel.areaHectares.toFixed(4), scheduleX + scheduleWidth * 0.6, sy, TEXT_SIZES.small, { align: 'right' })
    sy += 4
  }

  // Total
  drawLine(doc, scheduleX, sy, scheduleX + scheduleWidth, sy, 0.1)
  sy += 3
  const totalArea = data.resultingParcels.reduce((sum, p) => sum + p.areaHectares, 0)
  drawText(doc, 'TOTAL', scheduleX, sy, TEXT_SIZES.small, { bold: true })
  drawText(doc, totalArea.toFixed(4), scheduleX + scheduleWidth * 0.6, sy, TEXT_SIZES.small, { bold: true, align: 'right' })
  sy += 8

  // Beacon Schedule
  drawText(doc, 'BEACON SCHEDULE', scheduleX, sy, 4, { bold: true })
  sy += 6
  drawLine(doc, scheduleX, sy, scheduleX + scheduleWidth, sy, LINE_WEIGHTS.gridLine)
  sy += 3

  drawText(doc, 'BEACON', scheduleX, sy, 2.5, { bold: true })
  drawText(doc, 'EASTING', scheduleX + scheduleWidth * 0.3, sy, 2.5, { bold: true })
  drawText(doc, 'NORTHING', scheduleX + scheduleWidth * 0.65, sy, 2.5, { bold: true })
  sy += 4
  drawLine(doc, scheduleX, sy, scheduleX + scheduleWidth, sy, 0.1)
  sy += 3

  for (const beacon of data.beacons) {
    drawText(doc, beacon.beaconNumber, scheduleX, sy, TEXT_SIZES.small, )
    drawText(doc, beacon.coordinate.easting.toFixed(3), scheduleX + scheduleWidth * 0.3, sy, TEXT_SIZES.small, )
    drawText(doc, beacon.coordinate.northing.toFixed(3), scheduleX + scheduleWidth * 0.65, sy, TEXT_SIZES.small, )
    sy += 4
  }

  // ─── Footer: Surveyor details ────────────────────────────────
  let fy = pageHeight - 35
  drawLine(doc, mx, fy, pageWidth - mx, fy, LINE_WEIGHTS.titleBorder)
  fy += 4

  drawText(doc, `SURVEYOR: ${data.surveyorName.toUpperCase()}`, mx, fy, TEXT_SIZES.small, { bold: true })
  drawText(doc, `LICENSE: ${data.surveyorLicense}`, mx + 80, fy, TEXT_SIZES.small, { bold: true })
  drawText(doc, `DATE: ${data.datePrepared}`, pageWidth - mx - 40, fy, TEXT_SIZES.small, { align: 'right' })
  fy += 6

  // Digital Signature Stamp
  drawDigitalSignatureStamp(
    doc,
    mx,
    fy + 1,
    data.surveyorName,
    data.surveyorLicense,
    data.datePrepared,
    25 // 25mm diameter
  )
  
  // Director of Surveys
  drawLine(doc, pageWidth - mx - 50, fy + 8, pageWidth - mx, fy + 8, LINE_WEIGHTS.gridLine)
  drawText(doc, 'Director of Surveys', pageWidth - mx - 50, fy + 10, 2)

  // Watermark (free plan only)
  if (data.plan === 'free' || !data.plan) {
    drawMetarduWatermark(doc, pageWidth, pageHeight)
  } else if (data.companyLogo) {
    drawCompanyLogo(doc, data.companyLogo, pageWidth - mx - 30, 10, 25, 8)
  }

  doc.end()
  return pdfPromise
}

/**
 * Setting Out Sheet Template
 *
 * A4 portrait document for setting out survey points.
 * Contains a coordinate table with design and offset values.
 *
 * Layout:
 * - Header: Project name, surveyor, date
 * - Table: Point ID, Design E, Design N, Offset E, Offset N, Remarks
 * - Footer: Surveyor signature, checked-by line
 *
 * Watermark:
 * - Free plan: METARDU watermark
 * - Paid plan + company logo: Logo in header
 * - Paid plan + no logo: Blank
 */

import {
  createSurveyDocument,
  drawLine,
  drawRect,
  drawText,
  drawCompanyLogo,
  drawMetarduWatermark,
  PAPER_SIZES,
  LINE_WEIGHTS,
  TEXT_SIZES,
} from '../pdf-engine';
import type { DocumentTemplate, TemplateGenerateOptions } from './registry';
import type { ResolvedLogo } from '../resolve-logo';
import type { PlanId } from '@/lib/subscription/catalog';

// ─── Types ───────────────────────────────────────────────────────

export interface SettingOutPoint {
  /** Point identifier */
  pointId: string;
  /** Design easting coordinate */
  designE: number;
  /** Design northing coordinate */
  designN: number;
  /** Bearing from control station to design point (e.g., "45°30'15\"") */
  bearing?: string;
  /** Distance from control station to design point (meters) */
  distance?: string;
  /** Offset from design position (easting) */
  offsetE?: number;
  /** Offset from design position (northing) */
  offsetN?: number;
  /** Tolerance check result (e.g., "PASS", "FAIL", "±0.010m") */
  toleranceCheck?: string;
  /** Additional remarks */
  remarks?: string;
}

export interface SettingOutSheetData {
  /** Project name */
  projectName: string;
  /** Surveyor name */
  surveyorName: string;
  /** Surveyor license number */
  surveyorLicense: string;
  /** Date of setting out */
  date: string;
  /** Reference station name */
  referenceStation?: string;
  /** Instrument used */
  instrument?: string;
  /** Coordinate system / projection */
  projection?: string;
  /** Datum */
  datum?: string;
  /** List of setting out points */
  points: SettingOutPoint[];
}

// ─── Core Generator ──────────────────────────────────────────────

async function generateSettingOutPdf(
  data: SettingOutSheetData,
  options?: TemplateGenerateOptions
): Promise<Buffer> {
  const plan: PlanId = options?.plan ?? 'free';
  const companyLogo: ResolvedLogo | null = options?.companyLogo ?? null;
  const pageW = PAPER_SIZES.A4.width;
  const pageH = PAPER_SIZES.A4.height;

  const doc = createSurveyDocument({
    paperSize: 'A4',
    orientation: 'portrait',
    scale: 1,
    metadata: {
      title: `Setting Out Sheet - ${data.projectName}`,
      surveyorName: data.surveyorName,
      surveyorLicense: data.surveyorLicense,
      projectReference: data.projectName,
      date: data.date,
    },
    companyLogo: companyLogo?.data ?? null,
    plan,
  });

  const chunks: Buffer[] = [];
  doc.on('data', (chunk: Buffer) => chunks.push(chunk));
  const pdfPromise = new Promise<Buffer>((resolve) => {
    doc.on('end', () => resolve(Buffer.concat(chunks)));
  });

  // METARDU watermark for free plan
  if (plan === 'free') {
    drawMetarduWatermark(doc, pageW, pageH);
  }

  const mx = 15; // Left margin
  const rightMargin = 15;
  let y = 15;

  // ─── Header with logo ──────────────────────────────────────
  if (companyLogo?.data) {
    drawCompanyLogo(doc, companyLogo.data, mx, y, 30, 10);
    y += 2;
  }

  drawText(doc, 'SETTING OUT SHEET', mx + (companyLogo?.data ? 32 : 0), y, 5, { bold: true });
  y += 7;

  // Project info line
  drawText(doc, data.projectName, mx, y, 3, { bold: true });
  y += 4;
  drawText(doc, `Surveyor: ${data.surveyorName} (${data.surveyorLicense})  |  Date: ${data.date}`, mx, y, TEXT_SIZES.coordinate);
  y += 4;

  // Additional info
  const infoParts: string[] = [];
  if (data.referenceStation) infoParts.push(`Ref: ${data.referenceStation}`);
  if (data.instrument) infoParts.push(`Instr: ${data.instrument}`);
  if (data.projection) infoParts.push(`Proj: ${data.projection}`);
  if (data.datum) infoParts.push(`Datum: ${data.datum}`);
  if (infoParts.length > 0) {
    drawText(doc, infoParts.join('  |  '), mx, y, TEXT_SIZES.small);
    y += 4;
  }

  // Separator line
  drawLine(doc, mx, y, pageW - rightMargin, y, LINE_WEIGHTS.titleBorder);
  y += 5;

  // ─── Coordinate Table ───────────────────────────────────────
  const colWidths = [18, 28, 28, 18, 20, 20, 20, 18, 40];
  const colHeaders = ['Point', 'Design E', 'Design N', 'Bearing', 'Dist (m)', 'Offset E', 'Offset N', 'Tol.', 'Remarks'];
  const headerHeight = 7;
  const rowHeight = 6;

  // Table header
  let cx = mx;
  for (let i = 0; i < colHeaders.length; i++) {
    drawRect(doc, cx, y, colWidths[i], headerHeight, 0.2, 'black', '#E8E8E8');
    drawText(doc, colHeaders[i], cx + 1, y + 2, TEXT_SIZES.small, { bold: true });
    cx += colWidths[i];
  }
  y += headerHeight;

  // Table rows
  const maxRows = Math.min(data.points.length, 32); // Max rows that fit on A4
  for (let r = 0; r < maxRows; r++) {
    cx = mx;
    const pt = data.points[r];
    const values = [
      pt.pointId,
      pt.designE.toFixed(3),
      pt.designN.toFixed(3),
      pt.bearing ?? '',
      pt.distance ?? '',
      pt.offsetE != null ? pt.offsetE.toFixed(3) : '',
      pt.offsetN != null ? pt.offsetN.toFixed(3) : '',
      pt.toleranceCheck ?? '',
      pt.remarks ?? '',
    ];

    for (let i = 0; i < colWidths.length; i++) {
      drawRect(doc, cx, y, colWidths[i], rowHeight, 0.08);
      drawText(doc, values[i], cx + 1, y + 1.5, TEXT_SIZES.small);
      cx += colWidths[i];
    }
    y += rowHeight;
  }

  // Overflow note if too many points
  if (data.points.length > maxRows) {
    y += 2;
    drawText(doc, `... and ${data.points.length - maxRows} more points (continued on next page)`, mx, y, TEXT_SIZES.small, { color: '#999999' });
    y += 5;
  }

  // ─── Summary statistics ─────────────────────────────────────
  y += 5;
  drawLine(doc, mx, y, pageW - rightMargin, y, 0.3);
  y += 3;

  const totalPoints = data.points.length;
  const pointsWithOffsets = data.points.filter(p => p.offsetE != null || p.offsetN != null).length;
  const maxOffsetE = Math.max(...data.points.filter(p => p.offsetE != null).map(p => Math.abs(p.offsetE!)), 0);
  const maxOffsetN = Math.max(...data.points.filter(p => p.offsetN != null).map(p => Math.abs(p.offsetN!)), 0);

  drawText(doc, 'SUMMARY', mx, y, TEXT_SIZES.coordinate, { bold: true });
  y += 4;
  drawText(doc, `Total Points: ${totalPoints}`, mx, y, TEXT_SIZES.small);
  drawText(doc, `Points with Offsets: ${pointsWithOffsets}`, mx + 50, y, TEXT_SIZES.small);
  drawText(doc, `Max |Offset E|: ${maxOffsetE.toFixed(3)}m`, mx + 120, y, TEXT_SIZES.small);
  y += 4;
  drawText(doc, `Max |Offset N|: ${maxOffsetN.toFixed(3)}m`, mx, y, TEXT_SIZES.small);

  // ─── Footer: Signature and checked-by ───────────────────────
  // Position at bottom of page
  const footerY = pageH - 30;

  drawLine(doc, mx, footerY, pageW - rightMargin, footerY, 0.1);
  y = footerY + 3;

  // Surveyor signature
  drawLine(doc, mx + 80, y, mx + 140, y, 0.2);
  drawText(doc, data.surveyorName, mx + 80, y + 1, TEXT_SIZES.small);
  drawText(doc, `License: ${data.surveyorLicense}`, mx + 80, y + 3, TEXT_SIZES.small);

  // Checked-by line
  drawLine(doc, mx + 80, y + 12, mx + 140, y + 12, 0.2);
  drawText(doc, 'Checked by', mx + 80, y + 13, TEXT_SIZES.small);

  // Date field
  drawLine(doc, mx + 80, y + 24, mx + 140, y + 24, 0.2);
  drawText(doc, 'Date', mx + 80, y + 25, TEXT_SIZES.small);

  doc.end();
  return pdfPromise;
}

// ─── Template Registration ───────────────────────────────────────

export const SETTING_OUT_TEMPLATE: DocumentTemplate<SettingOutSheetData> = {
  id: 'setting-out',
  name: 'Setting Out Sheet',
  description: 'A4 portrait sheet with coordinate table for design and offset values, with surveyor signature block',
  documentType: 'setting-out',
  paperSize: 'A4',
  orientation: 'portrait',
  generate: generateSettingOutPdf,
};

/**
 * Server-side DOCX generation using docx package
 * Generates professional Word documents for survey reports
 * Supports survey-type-specific templates
 */

import {
  Document,
  Packer,
  Paragraph,
  TextRun,
  HeadingLevel,
  TableOfContents,
  AlignmentType,
  Table,
  TableRow,
  TableCell,
  WidthType,
} from 'docx'
import type { SectionContent } from '@/types/surveyReport'
import type { SurveyType } from '@/types/project'

export interface DocxGenerationOptions {
  title: string
  reportNumber?: string
  sections?: SectionContent[]
  surveyType?: SurveyType
  clientName?: string
  projectName?: string
  projectLocation?: string
  areaHectares?: number
  date?: string
  useTemplate?: boolean
}

export async function generateDocx(options: DocxGenerationOptions): Promise<Buffer> {
  const {
    title,
    reportNumber,
    sections: inputSections,
    surveyType = 'cadastral',
    clientName = '',
    projectName = '',
    projectLocation = '',
    areaHectares,
    date = new Date().toLocaleDateString('en-GB'),
    useTemplate = true,
  } = options

  // Use template-based sections if available, otherwise use input sections
  const sections = useTemplate
    ? inputSections || []
    : inputSections || []

  const docSections: (Paragraph | TableOfContents)[] = []

  // Title Page
  docSections.push(
    new Paragraph({
      children: [
        new TextRun({
          text: title.toUpperCase(),
          bold: true,
          size: 48,
          break: 1,
        }),
        ...(reportNumber
          ? [
              new TextRun({
                text: `\n${reportNumber}`,
                size: 28,
                italics: true,
              }),
            ]
          : []),
        new TextRun({ text: '\n\n\n', size: 24 }),
        ...(clientName
          ? [
              new TextRun({
                text: `Client: ${clientName}`,
                size: 28,
              }),
              new TextRun({ text: '\n', size: 24 }),
            ]
          : []),
        ...(projectName
          ? [
              new TextRun({
                text: `Project: ${projectName}`,
                size: 28,
              }),
              new TextRun({ text: '\n', size: 24 }),
            ]
          : []),
        new TextRun({
          text: `\n\n${date}`,
          size: 24,
        }),
      ],
      alignment: AlignmentType.CENTER,
      spacing: {
        before: 200,
        after: 200,
      },
    })
  )

  // Page break after title
  docSections.push(
    new Paragraph({
      children: [new TextRun({ text: '' })],
      pageBreakBefore: true,
    })
  )

  // Table of Contents
  docSections.push(
    new Paragraph({
      children: [
        new TextRun({
          text: 'TABLE OF CONTENTS',
          bold: true,
          size: 28,
        }),
      ],
      heading: HeadingLevel.HEADING_1,
      spacing: {
        before: 200,
        after: 200,
      },
    })
  )

  docSections.push(
    new TableOfContents('1-3')
  )

  docSections.push(
    new Paragraph({
      children: [new TextRun({ text: '' })],
      pageBreakBefore: true,
    })
  )

  // Add each section
  for (const section of sections) {
    if (section.sectionNumber <= 2) continue

    // Section heading
    docSections.push(
      new Paragraph({
        children: [
          new TextRun({
            text: `${section.sectionNumber}. ${section.title}`,
            bold: true,
            size: 32,
          }),
        ],
        heading: HeadingLevel.HEADING_1,
        spacing: {
          before: 400,
          after: 200,
        },
      })
    )

    // Section content
    const contentParagraphs = parseHtmlToParagraphs(section.content)
    docSections.push(...contentParagraphs)
  }

  const doc = new Document({
    sections: [
      {
        properties: {},
        children: docSections,
      },
    ],
  })

  const buffer = await Packer.toBuffer(doc)
  return buffer
}

function parseHtmlToParagraphs(html: string): Paragraph[] {
  const paragraphs: Paragraph[] = []
  if (!html) return paragraphs

  const cleanHtml = html.replace(/\n/g, ' ').trim()
  const rawParagraphs = cleanHtml.split(/<\/p>|<br\s*\/?>|\n\n/)

  for (const para of rawParagraphs) {
    const text = para
      .replace(/<[^>]*>/g, '')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .trim()

    if (text) {
      paragraphs.push(
        new Paragraph({
          children: [
            new TextRun({
              text: text,
              size: 22,
            }),
          ],
          spacing: {
            after: 200,
          },
        })
      )
    }
  }

  if (paragraphs.length === 0 && cleanHtml) {
    const text = cleanHtml
      .replace(/<[^>]*>/g, '')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .trim()

    if (text) {
      paragraphs.push(
        new Paragraph({
          children: [
            new TextRun({
              text: text,
              size: 22,
            }),
          ],
        })
      )
    }
  }

  return paragraphs
}

export default generateDocx

/**
