      alignment: [{ name: 'B', easting: 100, northing: 0 }],
    })
    const pt = reverseChainageLinear({ targetChainage: 50, table })
    expect(pt).not.toBeNull()
    expect(pt!.easting).toBeCloseTo(50, 3)
