// METARDU As-Built Survey Module
// Source: RDM 1.3 Section 8 (Quality Assurance & Tolerances)
// Source: RDM 1.1 Detail Tolerances
// Source: KeNHA Construction Supervision Manual

// ─── TYPES ─────────────────────────────────────────────────────────────────────

export interface DesignPoint {
  chainage: number
  designLevel: number
  designEasting?: number
  designNorthing?: number
}

export interface AsBuiltPoint {
  chainage: number
  surveyedLevel: number
  surveyedEasting?: number
  surveyedNorthing?: number
  timestamp?: string
  surveyor?: string
}

export interface ToleranceBand {
  level: number     // mm — vertical tolerance (±)
  horizontal: number // mm — horizontal tolerance (±)
}

export interface AsBuiltComparisonRow {
  chainage: number
  designLevel: number
  asBuiltLevel: number
  deviation: number      // mm — positive = built higher
  tolerance: number      // mm
  pass: boolean
  designEasting?: number
  designNorthing?: number
  asBuiltEasting?: number
  asBuiltNorthing?: number
  horizontalDeviation?: number
  horizontalPass?: boolean
}

export interface AsBuiltSummary {
  totalPoints: number
  passCount: number
  failCount: number
  passRate: number
  maxLevelDeviation: number
  maxHorizontalDeviation: number
  meanLevelDeviation: number
  standardDeviation: number
  rmsError: number
  isCompliant: boolean   // KeNHA requires >= 95% pass rate
  certificationReady: boolean
  issues: string[]
}

export interface AsBuiltSurveyResult {
  comparisons: AsBuiltComparisonRow[]
  summary: AsBuiltSummary
  toleranceBand: ToleranceBand
}

// ─── TOLERANCE BANDS (RDM 1.1 Table 5.1, RDM 1.3 Section 8) ───────────────────

export const TOLERANCE_BANDS: Record<string, ToleranceBand> = {
  paved: { level: 25, horizontal: 50 },
  gravel: { level: 50, horizontal: 100 },
  earth: { level: 100, horizontal: 150 },
  bridge: { level: 10, horizontal: 25 },
}

export const DEFAULT_TOLERANCE = TOLERANCE_BANDS.paved

// ─── STATISTICS ────────────────────────────────────────────────────────────────

export interface Statistics {
  mean: number
  stdDev: number
  rms: number
  max: number
  min: number
}

export function computeStatistics(deviations: number[]): Statistics {
  if (deviations.length === 0) {
    return { mean: 0, stdDev: 0, rms: 0, max: 0, min: 0 }
  }

  const n = deviations.length
  const mean = deviations.reduce((s, d) => s + d, 0) / n
  const variance = deviations.reduce((s, d) => s + (d - mean) ** 2, 0) / n
  const stdDev = Math.sqrt(variance)
  const rms = Math.sqrt(deviations.reduce((s, d) => s + d ** 2, 0) / n)

  return {
    mean,
    stdDev,
    rms,
    max: Math.max(...deviations),
    min: Math.min(...deviations),
  }
}

// ─── INTERPOLATION ─────────────────────────────────────────────────────────────

function interpolateLevel(points: Array<{ chainage: number; level: number }>, targetChainage: number): number | null {
  if (points.length === 0) return null
  if (points.length === 1) return points[0].level

  // Sort by chainage
  const sorted = [...points].sort((a, b) => a.chainage - b.chainage)

  // Exact match
  for (const p of sorted) {
    if (Math.abs(p.chainage - targetChainage) < 0.001) return p.level
  }

  // Bracket
  if (targetChainage <= sorted[0].chainage || targetChainage >= sorted[sorted.length - 1].chainage) {
    return null // outside range
  }

  for (let i = 0; i < sorted.length - 1; i++) {
    if (targetChainage >= sorted[i].chainage && targetChainage <= sorted[i + 1].chainage) {
      const t = (targetChainage - sorted[i].chainage) / (sorted[i + 1].chainage - sorted[i].chainage)
      return sorted[i].level + t * (sorted[i + 1].level - sorted[i].level)
    }
  }
  return null
}

function interpolateCoord(points: Array<{ chainage: number; easting: number; northing: number }>, targetChainage: number): { easting: number; northing: number } | null {
  if (points.length === 0) return null
  if (points.length === 1) return { easting: points[0].easting, northing: points[0].northing }

  const sorted = [...points].sort((a, b) => a.chainage - b.chainage)

  if (targetChainage <= sorted[0].chainage || targetChainage >= sorted[sorted.length - 1].chainage) {
    return null
  }

  for (let i = 0; i < sorted.length - 1; i++) {
    if (targetChainage >= sorted[i].chainage && targetChainage <= sorted[i + 1].chainage) {
      const t = (targetChainage - sorted[i].chainage) / (sorted[i + 1].chainage - sorted[i].chainage)
      return {
        easting: sorted[i].easting + t * (sorted[i + 1].easting - sorted[i].easting),
        northing: sorted[i].northing + t * (sorted[i + 1].northing - sorted[i].northing),
      }
    }
  }
  return null
}

// ─── MAIN COMPARISON ──────────────────────────────────────────────────────────

export function compareDesignVsAsBuilt(
  design: DesignPoint[],
  asBuilt: AsBuiltPoint[],
  tolerance: ToleranceBand = DEFAULT_TOLERANCE
): AsBuiltSurveyResult {
  const comparisons: AsBuiltComparisonRow[] = []
  const issues: string[] = []

  if (asBuilt.length === 0) {
    return {
      comparisons: [],
      summary: {
        totalPoints: 0, passCount: 0, failCount: 0, passRate: 0,
        maxLevelDeviation: 0, maxHorizontalDeviation: 0,
        meanLevelDeviation: 0, standardDeviation: 0, rmsError: 0,
        isCompliant: false, certificationReady: false, issues: ['No as-built survey data provided'],
      },
      toleranceBand: tolerance,
    }
  }

  // Prepare design point arrays for interpolation
  const designLevels = design.map(d => ({ chainage: d.chainage, level: d.designLevel }))
  const designCoords = design.filter(d => d.designEasting && d.designNorthing).map(d => ({
    chainage: d.chainage, easting: d.designEasting!, northing: d.designNorthing!,
  }))

  for (const ab of asBuilt) {
    const designLevel = interpolateLevel(designLevels, ab.chainage)
    if (designLevel === null) {
      // No design data at this chainage — skip or warn
      continue
    }

    const levelDeviation = (ab.surveyedLevel - designLevel) * 1000 // convert m to mm
    const levelPass = Math.abs(levelDeviation) <= tolerance.level

    // Horizontal comparison
    let horizontalDeviation: number | undefined
    let horizontalPass: boolean | undefined

    // Interpolate design coordinates at this chainage
    const designCoord = designCoords.length > 0
      ? interpolateCoord(designCoords, ab.chainage)
      : null

    if (ab.surveyedEasting && ab.surveyedNorthing && designCoord) {
      const dE = ab.surveyedEasting - designCoord.easting
      const dN = ab.surveyedNorthing - designCoord.northing
      horizontalDeviation = Math.sqrt(dE * dE + dN * dN) * 1000 // m to mm
      horizontalPass = horizontalDeviation <= tolerance.horizontal
    }

    comparisons.push({
      chainage: ab.chainage,
      designLevel,
      asBuiltLevel: ab.surveyedLevel,
      deviation: Math.round(levelDeviation * 10) / 10,
      tolerance: tolerance.level,
      pass: levelPass,
      designEasting: designCoord?.easting,
      designNorthing: designCoord?.northing,
      asBuiltEasting: ab.surveyedEasting,
      asBuiltNorthing: ab.surveyedNorthing,
      horizontalDeviation: horizontalDeviation !== undefined ? Math.round(horizontalDeviation * 10) / 10 : undefined,
      horizontalPass,
    })
  }

  // Compute statistics
  const levelDeviations = comparisons.map(c => Math.abs(c.deviation))
  const stats = computeStatistics(levelDeviations)

  const passCount = comparisons.filter(c => c.pass).length
  const failCount = comparisons.length - passCount
  const passRate = comparisons.length > 0 ? (passCount / comparisons.length) * 100 : 0

  // KeNHA requires >= 95% pass rate for certification
  const isCompliant = passRate >= 95

  // Max horizontal deviation
  const horizDevs = comparisons.filter(c => c.horizontalDeviation !== undefined).map(c => c.horizontalDeviation!)
  const maxHorizontalDeviation = horizDevs.length > 0 ? Math.max(...horizDevs) : 0

  // Generate issues
  if (passRate < 95) {
    issues.push(`Pass rate ${passRate.toFixed(1)}% is below the KeNHA threshold of 95%`)
  }
  if (stats.max > tolerance.level * 2) {
    issues.push(`Maximum deviation (${stats.max.toFixed(1)}mm) exceeds 2x tolerance (${tolerance.level * 2}mm)`)
  }
  if (stats.mean > tolerance.level * 0.5) {
    issues.push(`Mean deviation (${stats.mean.toFixed(1)}mm) indicates systematic error`)
  }
  if (comparisons.length < 20) {
    issues.push(`Insufficient survey points (${comparisons.length}). Minimum recommended: 20`)
  }

  return {
    comparisons,
    summary: {
      totalPoints: comparisons.length,
      passCount,
      failCount,
      passRate: Math.round(passRate * 10) / 10,
      maxLevelDeviation: stats.max,
      maxHorizontalDeviation,
      meanLevelDeviation: Math.round(stats.mean * 10) / 10,
      standardDeviation: Math.round(stats.stdDev * 10) / 10,
      rmsError: Math.round(stats.rms * 10) / 10,
      isCompliant,
      certificationReady: isCompliant && comparisons.length >= 20,
      issues,
    },
    toleranceBand: tolerance,
  }
}

// ─── CERTIFICATE DATA ──────────────────────────────────────────────────────────

export interface AsBuiltCertificate {
  certificateNumber: string
  issueDate: string
  projectName: string
  roadName: string
  roadClass: string
  chainageStart: number
  chainageEnd: number
  surveyorName: string
  surveyorLicense: string
  result: AsBuiltSummary
}

export function generateAsBuiltCertificate(data: {
  projectName: string
  roadName: string
  roadClass: string
  chainageStart: number
  chainageEnd: number
  surveyorName: string
  surveyorLicense: string
  date: string
  result: AsBuiltSurveyResult
}): AsBuiltCertificate {
  return {
    certificateNumber: `ABC-${new Date().getFullYear()}-${String(Math.floor(Math.random() * 999) + 1).padStart(3, '0')}`,
    issueDate: data.date,
    projectName: data.projectName,
    roadName: data.roadName,
    roadClass: data.roadClass,
    chainageStart: data.chainageStart,
    chainageEnd: data.chainageEnd,
    surveyorName: data.surveyorName,
    surveyorLicense: data.surveyorLicense,
    result: data.result.summary,
  }
}

// ─── CSV PARSING ───────────────────────────────────────────────────────────────

export function parseAsBuiltCSV(csv: string): AsBuiltPoint[] {
  const lines = csv.trim().split('\n')
  if (lines.length < 2) return []

  const points: AsBuiltPoint[] = []
  // Skip header row
  for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split(',').map(c => c.trim())
    if (cols.length < 2) continue

    const chainage = parseFloat(cols[0])
    const level = parseFloat(cols[1])
    if (isNaN(chainage) || isNaN(level)) continue

    points.push({
      chainage,
      surveyedLevel: level,
      surveyedEasting: cols[2] ? parseFloat(cols[2]) : undefined,
      surveyedNorthing: cols[3] ? parseFloat(cols[3]) : undefined,
    })
  }

  return points
}

/**
 * Engineering Computation Library
 * 
 * Kenya RDM 1.1 (Roads Development Authority) and KeRRA (Kenya Rural Roads Authority)
 * compliant civil engineering calculations for road design.
 * 
 * Coordinate System: Arc 1960 / UTM Zone 37S (SRID 21037)
 * All distances in metres, angles in decimal degrees unless otherwise specified.
 * 
 * @packageDocumentation
 */

import { z } from 'zod';
import type { createClient } from '@/lib/api-client/client';
import { logger } from '@/lib/logger'

let dbClient: ReturnType<typeof createClient> | null = null;

export async function initComputeLogger() {
  const { createClient } = await import('@/lib/api-client/client');
  dbClient = createClient();
}

async function logComputation(
  computationType: string,
  input: unknown,
  result: unknown,
  projectId?: string,
  userId?: string
) {
  if (!dbClient) {
    try {
      const { createClient } = await import('@/lib/api-client/client');
      dbClient = createClient();
    } catch (e) {
      logger.warn('Compute logger: DbClient not available');
      return;
    }
  }
  
  if (!dbClient) return;
  
  try {
    await dbClient.from('engineering_compute_logs').insert({
      computation_type: computationType,
      project_id: projectId,
      user_id: userId,
      input,
      result,
      created_at: new Date().toISOString()
    });
  } catch (e) {
    logger.warn('Compute logger: Failed to log', { error: e });
  }
}

export async function logEngineeringCompute(
  computationType: string,
  input: unknown,
  result: unknown,
  options?: { projectId?: string; userId?: string }
) {
  return logComputation(computationType, input, result, options?.projectId, options?.userId);
}

/**
 * Input validation schemas per RDM 1.1 / KeRRA standards
 */

// Horizontal Curve Input
// Reference: RDM 1.1 Volume 2, Chapter 3 - Horizontal Alignment
export const HorizontalCurveSchema = z.object({
  R: z.number().positive().max(2000, 'Radius must be ≤ 2000m for rural roads'),
  deltaDeg: z.number().positive().max(180, 'Deflection angle must be ≤ 180°'),
  chainageStart: z.number().min(0),
}).default({ R: 100, deltaDeg: 30, chainageStart: 0 });

export type HorizontalCurveInput = z.infer<typeof HorizontalCurveSchema>;

// Vertical Curve Input
// Reference: RDM 1.1 Volume 2, Chapter 4 - Vertical Alignment
export const VerticalCurveSchema = z.object({
  L: z.number().positive().min(40, 'Minimum curve length 40m per RDM 1.1'),
  g1: z.number().min(-15).max(15, 'Grade must be between -15% and +15%'),
  g2: z.number().min(-15).max(15),
  chainage_VIP: z.number().min(0),
  elevation_VIP: z.number(),
  designSpeedKph: z.number().positive().min(20).max(120).optional().default(80),
  K: z.number().positive().optional(),
});

export type VerticalCurveInput = z.infer<typeof VerticalCurveSchema>;

// Superelevation Input
// Reference: RDM 1.1 Volume 2, Section 3.4 - Superelevation
// KeRRA Rural Roads Design Manual Section 4.2
export const SuperelevationSchema = z.object({
  R: z.number().positive().max(2000, 'Maximum radius 2000m'),
  V: z.number().positive().min(20).max(120, 'Design speed 20-120 km/h'),
  eMax: z.number().positive().max(0.12).default(0.07),
  transitionLength: z.number().positive().optional(),
});

export type SuperelevationInput = z.infer<typeof SuperelevationSchema>;

// Cross Section Volume Input
// Reference: RDM 1.1 Volume 3, Chapter 2 - Earthworks
export const CrossSectionVolumeSchema = z.object({
  areas: z.array(z.number()).min(2, 'Need at least 2 cross-sections'),
  stationInterval: z.number().positive().max(100, 'Max interval 100m').default(20),
  method: z.enum(['prismoidal', 'end-area']).default('prismoidal'),
});

export type CrossSectionVolumeInput = z.infer<typeof CrossSectionVolumeSchema>;

// Mass Haul Diagram Input
export const MassHaulSchema = z.object({
  cumulativeVolumes: z.array(z.number()).min(2),
  stationInterval: z.number().positive().default(20),
});

export type MassHaulInput = z.infer<typeof MassHaulSchema>;

/**
 * Horizontal Curve Elements
 * 
 * Computes all curve elements per RDM 1.1:
 * - T: Tangent Length
 * - L: Curve Length (arc)
 * - LC: Long Chord
 * - M: Mid-Ordinate
 * - E: External Distance
 * - Setting out table at 20m intervals
 * 
 * @param input - Curve parameters
 * @returns Complete curve elements and setting-out table
 * 
 * @example
 * ```ts
 * const result = horizontalCurve({
 *   R: 300,
 *   deltaDeg: 45,
 *   chainageStart: 1000
 * });
 * // Returns T, L, LC, M, E, chainage_TC, chainage_CT, settingOutTable
 * ```
 */
export interface HorizontalCurveResult {
  /** Tangent Length (T = R × tan(Δ/2)) */
  T: number;
  /** Curve Length - Arc (L = R × Δ in radians) */
  L: number;
  /** Long Chord (LC = 2R × sin(Δ/2)) */
  LC: number;
  /** Mid-Ordinate (M = R × (1 - cos(Δ/2))) */
  M: number;
  /** External Distance (E = R × (1/cos(Δ/2) - 1)) */
  E: number;
  deflectionAngleDeg: number;
  chainageStart: number;
  chainage_TC: number;
  chainage_CT: number;
  settingOutTable: SettingOutRow[];
}

export interface SettingOutRow {
  chainage: number;
  deflectionFromTC: number;
  chordFromTC: number;
  chordIncrement: number;
}

export function horizontalCurve(input: HorizontalCurveInput): HorizontalCurveResult {
  const parsed = HorizontalCurveSchema.parse(input);
  const { R, deltaDeg, chainageStart } = parsed;
  const deltaRad = (deltaDeg * Math.PI) / 180;

  // RDM 1.1 Formulae (Volume 2, Chapter 3)
  const T = R * Math.tan(deltaRad / 2);
  const L = R * deltaRad;
  const LC = 2 * R * Math.sin(deltaRad / 2);
  const M = R * (1 - Math.cos(deltaRad / 2));
  const E = R * (1 / Math.cos(deltaRad / 2) - 1);

  const chainage_TC = chainageStart - T;
  const chainage_CT = chainage_TC + L;

  // Setting out table per RDM 1.1 - 20m intervals
  const pegInterval = 20;
  const settingOutTable: SettingOutRow[] = [];

  let peg = Math.ceil(chainage_TC / pegInterval) * pegInterval;
  let prevChord = 0;

  while (peg <= chainage_CT) {
    const arc = peg - chainage_TC;
    const deflection = (arc / (2 * R)) * (180 / Math.PI);
    const chord = 2 * R * Math.sin((arc / R) / 2);
    const increment = chord - prevChord;

    settingOutTable.push({
      chainage: peg,
      deflectionFromTC: parseFloat(deflection.toFixed(6)),
      chordFromTC: parseFloat(chord.toFixed(4)),
      chordIncrement: parseFloat(increment.toFixed(4))
    });

    prevChord = chord;
    peg += pegInterval;
  }

  // Always include CT point
  if (settingOutTable[settingOutTable.length - 1]?.chainage !== chainage_CT) {
    settingOutTable.push({
      chainage: parseFloat(chainage_CT.toFixed(3)),
      deflectionFromTC: parseFloat((deltaDeg / 2).toFixed(6)),
      chordFromTC: parseFloat(LC.toFixed(4)),
      chordIncrement: parseFloat((LC - prevChord).toFixed(4))
    });
  }

  return {
    T: parseFloat(T.toFixed(4)),
    L: parseFloat(L.toFixed(4)),
    LC: parseFloat(LC.toFixed(4)),
    M: parseFloat(M.toFixed(4)),
    E: parseFloat(E.toFixed(4)),
    deflectionAngleDeg: deltaDeg,
    chainageStart,
    chainage_TC: parseFloat(chainage_TC.toFixed(3)),
    chainage_CT: parseFloat(chainage_CT.toFixed(3)),
    settingOutTable
  };
}

/**
 * Vertical Curve Computation
 * 
 * Parabolic vertical curve per RDM 1.1 Volume 2, Chapter 4:
 * - Computes elevation at any point on curve
 * - K value (rate of vertical curvature) per sight distance requirements
 * - Automatic crest/sag classification
 * 
 * @param input - Vertical curve parameters
 * @returns Elevation table and curve properties
 */
export interface VerticalCurveResult {
  gradeIn: number;
  gradeOut: number;
  algebraicDiff: number;
  kValue: number;
  length: number;
  isCrest: boolean;
  chainage_VPC: number;
  chainage_VPT: number;
  sightDistance: number;
  elevationTable: VerticalCurvePoint[];
}

export interface VerticalCurvePoint {
  chainage: number;
  elevation: number;
  grade: number;
  cutFill: number;
}

export function verticalCurve(input: VerticalCurveInput): VerticalCurveResult {
  const parsed = VerticalCurveSchema.parse(input);
  const { L: curveLength, g1, g2, chainage_VIP, elevation_VIP, designSpeedKph } = parsed;

  const A = g2 - g1;
  const K = curveLength / Math.abs(A);
  const isCrest = A < 0;

  // RDM 1.1 minimum K values for stopping sight distance
  const minK = isCrest ? 0.6 * Math.pow(designSpeedKph, 2) / Math.abs(A) : 3;

  const chainage_VPC = chainage_VIP - curveLength / 2;
  const chainage_VPT = chainage_VIP + curveLength / 2;
  const elevation_VPC = elevation_VIP - (g1 / 100) * (curveLength / 2);

  // Stopping sight distance (SSD) per RDM 1.1
  const SSD = 0.278 * designSpeedKph * 2.5 + Math.pow(designSpeedKph, 2) / (254 * (Math.abs(A) / 100));

  const elevationTable: VerticalCurvePoint[] = [];
  const step = 20;

  let ch = Math.ceil(chainage_VPC / step) * step;
  while (ch <= chainage_VPT) {
    const x = ch - chainage_VPC;
    // Parabolic equation: y = y₀ + g₁x + (A/200L)x²
    const elevation = elevation_VPC + (g1 / 100) * x + (A / (200 * curveLength)) * x * x;
    const grade = g1 + (A / curveLength) * x;
    
    elevationTable.push({
      chainage: parseFloat(ch.toFixed(3)),
      elevation: parseFloat(elevation.toFixed(4)),
      grade: parseFloat(grade.toFixed(4)),
      cutFill: 0 // To be filled when design level is provided
    });
    ch += step;
  }

  return {
    gradeIn: g1,
    gradeOut: g2,
    algebraicDiff: parseFloat(A.toFixed(4)),
    kValue: parseFloat(K.toFixed(2)),
    length: curveLength,
    isCrest,
    chainage_VPC: parseFloat(chainage_VPC.toFixed(3)),
    chainage_VPT: parseFloat(chainage_VPT.toFixed(3)),
    sightDistance: parseFloat(SSD.toFixed(1)),
    elevationTable
  };
}

/**
 * Superelevation Calculation
 * 
 * Per RDM 1.1 Section 3.4 and KeRRA Design Manual:
 * - Maximum superelevation eMax = 7% for rural roads (can be 8% in special cases)
 * - Minimum transition length per KeRRA
 * - Rate of superelevation application
 * 
 * @param input - Superelevation parameters
 * @returns Applied superelevation and transition table
 */
export interface SuperelevationResult {
  eDesign: number;
  eMax: number;
  transitionLength: number;
  rate: number;
  table: SuperelevationRow[];
}

export interface SuperelevationRow {
  chainageOffset: number;
  eApplied: number;
  rotation: 'left' | 'right' | 'both';
}

/**
 * Calculate superelevation for a curve
 * 
 * Formula: e = V²/(225R) - f (where f = 0.01 minimum normal crown)
 * Reference: RDM 1.1 Equation 3.1
 */
export function superelevationCalc(input: SuperelevationInput): SuperelevationResult {
  const parsed = SuperelevationSchema.parse(input);
  const { R, V, eMax, transitionLength } = parsed;

  // RDM 1.1 formula: e = V²/(225R) - 0.01
  const e = (V * V) / (225 * R) - 0.01;
  const eDesign = Math.min(Math.max(e, 0), eMax);

  // KeRRA minimum transition length: L = 0.6V²/R (minimum 30m)
  const L = transitionLength || Math.max(0.6 * (V * V) / R, 30);
  
  const rate = eDesign / L;

  // Generate transition table
  const table: SuperelevationRow[] = [];
  const steps = 10;
  for (let i = 0; i <= steps; i++) {
    const progress = i / steps;
    table.push({
      chainageOffset: parseFloat((progress * L).toFixed(2)),
      eApplied: parseFloat((eDesign * progress * 100).toFixed(2)),
      rotation: 'both'
    });
  }

  return {
    eDesign: parseFloat((eDesign * 100).toFixed(2)),
    eMax: parseFloat((eMax * 100).toFixed(2)),
    transitionLength: parseFloat(L.toFixed(2)),
    rate: parseFloat((rate * 100).toFixed(4)),
    table
  };
}

/**
 * Cross-Section Volume Calculation
 * 
 * Computes earthwork volumes using:
 * - Prismoidal method (more accurate, RDM 1.1 preferred)
 * - End-area method (simpler, acceptable for preliminary estimates)
 * 
 * Reference: RDM 1.1 Volume 3, Chapter 2
 * 
 * @param input - Cross-section areas and station interval
 * @returns Volume table with cut/fill per station
 */
export interface CrossSectionVolumeResult {
  method: 'prismoidal' | 'end-area';
  totalCut: number;
  totalFill: number;
  netVolume: number;
  isBalanced: boolean;
  volumeTable: VolumeRow[];
}

export interface VolumeRow {
  station: number;
  cutArea: number;
  fillArea: number;
  cutVolume: number;
  fillVolume: number;
  cumulativeCut: number;
  cumulativeFill: number;
}

export function crossSectionVolume(input: CrossSectionVolumeInput): CrossSectionVolumeResult {
  const parsed = CrossSectionVolumeSchema.parse(input);
  const { areas, stationInterval, method } = parsed;

  // Precompute per-station incremental volumes
  const stationVolumes: number[] = new Array<number>(areas.length).fill(0);

  if (method === 'prismoidal' && areas.length >= 3) {
    // Simpson's 1/3 rule for groups of 3 stations (2 intervals each)
    // V = (2d/3) × (A[i] + 4·A[i+1] + A[i+2])
    let i = 0;
    while (i + 2 < areas.length) {
      stationVolumes[i + 2] = (2 * stationInterval / 3) * (areas[i] + 4 * areas[i + 1] + areas[i + 2]);
      i += 2;
    }
    // Remaining pair: fall back to end-area
    if (i + 1 < areas.length) {
      stationVolumes[i + 1] = (stationInterval / 2) * (areas[i] + areas[i + 1]);
    }
  } else {
    // End-area method (or prismoidal with < 3 stations)
    for (let i = 1; i < areas.length; i++) {
      stationVolumes[i] = (stationInterval / 2) * (areas[i - 1] + areas[i]);
    }
  }

  const volumeTable: VolumeRow[] = [];
  let cumulativeCut = 0;
  let cumulativeFill = 0;

  for (let i = 0; i < areas.length; i++) {
    const station = i * stationInterval;
    const currentArea = areas[i];
    const cutArea = currentArea > 0 ? currentArea : 0;
    const fillArea = currentArea < 0 ? Math.abs(currentArea) : 0;

    const vol = stationVolumes[i];
    const cutVolume = vol > 0 ? vol : 0;
    const fillVolume = vol < 0 ? Math.abs(vol) : 0;

    cumulativeCut += cutVolume;
    cumulativeFill += fillVolume;

    volumeTable.push({
      station,
      cutArea: parseFloat(cutArea.toFixed(2)),
      fillArea: parseFloat(fillArea.toFixed(2)),
      cutVolume: parseFloat(cutVolume.toFixed(2)),
      fillVolume: parseFloat(fillVolume.toFixed(2)),
      cumulativeCut: parseFloat(cumulativeCut.toFixed(2)),
      cumulativeFill: parseFloat(cumulativeFill.toFixed(2))
    });
  }

  const totalCut = cumulativeCut;
  const totalFill = cumulativeFill;
  const netVolume = totalCut - totalFill;

  return {
    method,
    totalCut: parseFloat(totalCut.toFixed(2)),
    totalFill: parseFloat(totalFill.toFixed(2)),
    netVolume: parseFloat(netVolume.toFixed(2)),
    isBalanced: Math.abs(netVolume) < totalCut * 0.05,
    volumeTable
  };
}

/**
 * Mass Haul Diagram
 * 
 * Generates cumulative mass-haul diagram for earthwork balancing:
 * - Cumulative volume curve
 * - Balance point detection
 * - Haul and overhaul calculations
 * 
 * Reference: RDM 1.1 Volume 3, Section 2.6
 * 
 * @param input - Array of cut/fill volumes (positive = cut, negative = fill)
 * @returns Cumulative values and balance points
 */
export interface MassHaulResult {
  cumulativeVolume: number[];
  maxSurplus: number;
  maxDeficit: number;
  balancePoint: number | null;
  haulDistance: number;
  overhaulDistance: number;
  diagram: MassHaulPoint[];
}

export interface MassHaulPoint {
  station: number;
  volume: number;
  cumulative: number;
  zone: 'cut' | 'fill' | 'balance';
}

export function massHaulDiagram(input: MassHaulInput): MassHaulResult {
  const parsed = MassHaulSchema.parse(input);
  const { cumulativeVolumes, stationInterval } = parsed;

  const cumulative: number[] = [];
  let running = 0;

  for (const vol of cumulativeVolumes) {
    running += vol;
    cumulative.push(running);
  }

  const maxSurplus = Math.max(...cumulative, 0);
  const maxDeficit = Math.min(...cumulative, 0);

  // Find balance point (where cumulative crosses zero)
  let balancePoint: number | null = null;
  for (let i = 1; i < cumulative.length; i++) {
    if ((cumulative[i - 1] < 0 && cumulative[i] >= 0) || 
        (cumulative[i - 1] > 0 && cumulative[i] <= 0)) {
      balancePoint = i * stationInterval;
      break;
    }
  }

  // Calculate haul distance (area under cumulative curve)
  let haulDistance = 0;
  for (let i = 1; i < cumulative.length; i++) {
    const avgVol = (cumulative[i] + cumulative[i - 1]) / 2;
    haulDistance += Math.abs(avgVol) * stationInterval;
  }

  // Simplified overhaul calculation
  const overhaulDistance = Math.abs(maxDeficit) * stationInterval * 0.5;

  const diagram: MassHaulPoint[] = cumulativeVolumes.map((vol, i) => ({
    station: i * stationInterval,
    volume: vol,
    cumulative: cumulative[i],
    zone: vol > 0 ? 'cut' : vol < 0 ? 'fill' : 'balance'
  }));

  return {
    cumulativeVolume: cumulative.map(v => parseFloat(v.toFixed(2))),
    maxSurplus: parseFloat(maxSurplus.toFixed(2)),
    maxDeficit: parseFloat(maxDeficit.toFixed(2)),
    balancePoint,
    haulDistance: parseFloat(haulDistance.toFixed(2)),
    overhaulDistance: parseFloat(overhaulDistance.toFixed(2)),
    diagram
  };
}

/**
 * Widening on Curves
 * 
 * Additional carriageway width on small radius curves per RDM 1.1 Section 3.5
 * 
 * @param R - Radius in metres
 * @param baseWidth - Base carriageway width (default 7.0m)
 * @returns Extra width to be added
 */
export interface WideningResult {
  radius: number;
  baseWidth: number;
  extraWidth: number;
  totalWidth: number;
}

export function wideningOnCurve(R: number, baseWidth: number = 7.0): WideningResult {
  // RDM 1.1 formula: W = 80/R for single lane addition
  // Simplified: extra width proportional to 1/R
  let extraWidth = 0;
  
  if (R < 300) {
    extraWidth = 0.5; // 0.5m for R < 300m
  } else if (R < 500) {
    extraWidth = 0.3; // 0.3m for R 300-500m
  } else if (R < 750) {
    extraWidth = 0.2; // 0.2m for R 500-750m
  }

  return {
    radius: R,
    baseWidth,
    extraWidth: parseFloat(extraWidth.toFixed(2)),
    totalWidth: parseFloat((baseWidth + extraWidth).toFixed(2))
  };
}

/**
 * Stopping Sight Distance Calculation
 * 
 * Per RDM 1.1 Section 2.3 and AASHTO
 * 
 * @param V - Design speed in km/h
 * @param grade - Grade in percent (positive for uphill)
 * @returns SSD in metres
 */
export function stoppingSightDistance(V: number, grade: number = 0): number {
  // AASHTO SSD formula: SSD = 0.278VT + V²/(254(f+G))
  // Where T = 2.5s perception-reaction time
  const T = 2.5;
  const f = 0.35; // friction coefficient
  
  const term1 = 0.278 * V * T;
  const term2 = (V * V) / (254 * (f + grade / 100));
  
  return parseFloat((term1 + term2).toFixed(1));
}

/**
 * Passing Sight Distance
 * 
 * Per RDM 1.1 for overtaking maneuvers
 */
export function passingSightDistance(V: number): number {
  // PSD = 3 * SSD approximately
  return parseFloat((3 * stoppingSightDistance(V)).toFixed(1));
}

/**
 * Minimum Curve Radius
 * 
 * Per RDM 1.1 based on design speed and superelevation
 */
export function minimumRadius(V: number, e: number = 0.07, f: number = 0.15): number {
  // R = V²/(127(e+f))
  return parseFloat((V * V / (127 * (e + f))).toFixed(1));
}

/**
 * Cross-Section Geometry Utilities
 *
 * Computes road formation templates, camber profiles, slope intercepts,
 * and cut/fill areas for road engineering cross-sections.
 *
 * References:
 *   - N.N. Basak, Surveying and Levelling, Ch. 8 — Earthwork computation
 *   - Ghilani & Wolf, Elementary Surveying, 16th Ed., §26.3
 *   - Kenya RDM 1.1 2025, §8 — Road cross-section design
 *
 * Conventions:
 *   - Offsets are measured from centreline: negative = left, positive = right.
 *   - Levels are Reduced Levels (RL) in metres.
 *   - Slopes expressed as "1V:H" (e.g. "1:2" means 1 vertical, 2 horizontal).
 *   - Camber is a percentage (e.g. 2.5 means 2.5%).
 *   - No intermediate rounding — full floating point throughout.
 */

// ─── TYPES ─────────────────────────────────────────────────────────────────────

export interface ProfilePoint {
  offset: number
  level: number
}

export interface RoadTemplate {
  carriagewayWidth: number
  shoulderWidth: number
  cutSlope: string     // "1:2" format (V:H)
  fillSlope: string    // "1:1.5" format
  camber: number       // percentage, e.g. 2.5
  subgradeDepth: number
}

// ─── SLOPE PARSING ─────────────────────────────────────────────────────────────

/**
 * Parse a slope string like "1:2", "1V:2H", "1:1.5" to a ratio (H per 1V).
 *
 * Examples:
 *   "1:2"   → 2    (for every 1m vertical, go 2m horizontal)
 *   "1:1.5" → 1.5
 *   "1:3"   → 3
 *
 * @param slope - Slope string in "1:H" or "1V:H" format
 * @returns Horizontal run per unit vertical rise
 * @throws Error if slope format is invalid
 */
export function parseSlopeRatio(slope: string): number {
  const trimmed = slope.trim().toUpperCase()

  // Match patterns like "1:2", "1V:2H", "1 V : 2 H"
  const match = trimmed.match(/^1\s*V?\s*:\s*(\d+(?:\.\d+)?)\s*H?$/)
  if (!match) {
    throw new Error(
      `Invalid slope format: "${slope}". Expected format: "1:H" or "1V:H" (e.g. "1:2").`
    )
  }

  return parseFloat(match[1])
}

// ─── CAMBER PROFILE ────────────────────────────────────────────────────────────

/**
 * Compute parabolic camber profile across the carriageway.
 *
 * Camber equation: y = c * x² where c = camber / (CW/2)²
 *
 * The camber creates a parabolic curve with the highest point at centreline
 * (formationLevel) sloping down symmetrically to both edges.
 *
 * Example: With 7m carriageway and 2.5% camber:
 *   - Half-width = 3.5m
 *   - c = 2.5 / 100 / 3.5² = 0.0002041
 *   - Edge level = formationLevel - 0.025 * 3.5 = formationLevel - 0.0875m
 *
 * @param carriagewayWidth - Total carriageway width in metres
 * @param camber - Camber percentage (e.g. 2.5 for 2.5%)
 * @param formationLevel - RL at centreline (top of camber)
 * @returns Array of {offset, level} points from left edge to right edge
 */
export function computeCamberProfile(
  carriagewayWidth: number,
  camber: number,
  formationLevel: number
): ProfilePoint[] {
  const halfWidth = carriagewayWidth / 2

  if (halfWidth <= 0) {
    return [{ offset: 0, level: formationLevel }]
  }

  // Camber coefficient: c = (camber / 100) / (halfWidth)²
  // This ensures the edge drop equals camber * halfWidth / 100
  const c = (camber / 100) / (halfWidth * halfWidth)

  // Generate points at 0.5m intervals along the carriageway
  const numPoints = Math.max(Math.ceil(carriagewayWidth / 0.5), 2)
  const points: ProfilePoint[] = []

  for (let i = 0; i <= numPoints; i++) {
    const x = -halfWidth + (carriagewayWidth * i) / numPoints
    const levelDrop = c * x * x
    points.push({
      offset: x,
      level: formationLevel - levelDrop,
    })
  }

  return points
}

// ─── SLOPE INTERCEPT ───────────────────────────────────────────────────────────

/**
 * Compute where a cut or fill slope intersects the ground profile.
 *
 * For a CUT slope: the slope rises from the shoulder edge upward toward the ground.
 * For a FILL slope: the slope descends from the shoulder edge downward toward the ground.
 *
 * Uses linear interpolation between ground points to find the exact intersection.
 *
 * @param shoulderOffset - Horizontal offset of the shoulder edge from centreline
 * @param shoulderLevel - RL at the shoulder edge
 * @param slopeRatio - H per 1V (e.g., 2 means 1V:2H)
 * @param isCut - true for cut slope (going up from shoulder), false for fill slope
 * @param groundPoints - Ground profile points sorted by offset
 * @returns Intersection point {offset, level} or null if no intersection found
 */
export function computeSlopeIntercept(
  shoulderOffset: number,
  shoulderLevel: number,
  slopeRatio: number,
  isCut: boolean,
  groundPoints: ProfilePoint[]
): ProfilePoint | null {
  if (groundPoints.length < 2) return null

  // Sort ground points by offset
  const sorted = [...groundPoints].sort((a, b) => a.offset - b.offset)

  // Determine slope direction
  // For cut: slope goes UP and OUTWARD from shoulder
  // For fill: slope goes DOWN and OUTWARD from shoulder
  const direction = shoulderOffset >= 0 ? 1 : -1

  // Maximum offset to check — extend slope to the extent of ground data
  const maxAbsOffset = Math.max(
    ...sorted.map(p => Math.abs(p.offset))
  )
  const maxSlopeOffset = maxAbsOffset + 10 // extra margin
  const maxVertical = maxSlopeOffset / slopeRatio

  // Check intersection with each ground segment
  for (let i = 0; i < sorted.length - 1; i++) {
    const gp1 = sorted[i]
    const gp2 = sorted[i + 1]

    // Skip segments that don't overlap with our slope direction
    if (direction > 0) {
      // Right side: slope extends to positive offsets
      if (gp1.offset > shoulderOffset && gp2.offset < shoulderOffset) continue
      if (gp2.offset < shoulderOffset) continue
    } else {
      // Left side: slope extends to negative offsets
      if (gp1.offset > shoulderOffset && gp2.offset < shoulderOffset) continue
      if (gp1.offset > shoulderOffset) continue
    }

    // Compute slope line parameters
    // Slope line: level = shoulderLevel + (isCut ? +1 : -1) * (|offset - shoulderOffset| / slopeRatio)
    const slopeEndOffset = shoulderOffset + direction * maxSlopeOffset
    const slopeEndLevel = shoulderLevel +
      (isCut ? 1 : -1) * (Math.abs(slopeEndOffset - shoulderOffset) / slopeRatio)

    // Line 1: slope line from (shoulderOffset, shoulderLevel) to (slopeEndOffset, slopeEndLevel)
    // Line 2: ground segment from (gp1.offset, gp1.level) to (gp2.offset, gp2.level)

    const x1 = shoulderOffset
    const y1 = shoulderLevel
    const x2 = slopeEndOffset
    const y2 = slopeEndLevel
    const x3 = gp1.offset
    const y3 = gp1.level
    const x4 = gp2.offset
    const y4 = gp2.level

    const denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
    if (Math.abs(denom) < 1e-12) continue // parallel lines

    const t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / denom
    const u = -((x1 - x2) * (y1 - y3) - (y1 - y2) * (x1 - x3)) / denom

    // Intersection is valid if both t and u are in [0, 1]
    if (t >= 0 && t <= 1 && u >= 0 && u <= 1) {
      const intersectX = x1 + t * (x2 - x1)
      const intersectY = y1 + t * (y2 - y1)

      // Verify the intersection is in the correct direction from the shoulder
      const offsetFromShoulder = intersectX - shoulderOffset
      if ((direction > 0 && offsetFromShoulder <= 0) || (direction < 0 && offsetFromShoulder >= 0)) {
        continue
      }

      return { offset: intersectX, level: intersectY }
    }
  }

  // If no intersection found, return the furthest point the slope would reach
  // within the ground extent (for rendering purposes)
  const furthestGround = direction > 0
    ? sorted[sorted.length - 1]
    : sorted[0]

  const furthestDist = Math.abs(furthestGround.offset - shoulderOffset)
  const furthestLevel = shoulderLevel + (isCut ? 1 : -1) * (furthestDist / slopeRatio)

  // Only return if the slope would actually cross the ground at this point
  if (isCut && furthestLevel < furthestGround.level) {
    return null
  }
  if (!isCut && furthestLevel > furthestGround.level) {
    return null
  }

  return {
    offset: furthestGround.offset,
    level: furthestLevel,
  }
}

// ─── FORMATION LINE ────────────────────────────────────────────────────────────

/**
 * Compute the full formation line (carriageway + shoulders + slope intercepts).
 *
 * Builds the complete road template cross-section:
 *   1. Left slope intercept (if ground is above shoulder → cut, below → fill)
 *   2. Left shoulder
 *   3. Carriageway with parabolic camber
 *   4. Right shoulder
 *   5. Right slope intercept
 *
 * Shoulders have a slight outward cross-fall of 3-5% (hardcoded at 4% per RDM 1.1).
 *
 * @param template - Road template parameters
 * @param formationLevel - RL at centreline
 * @param groundPoints - Natural ground profile
 * @param isCut - Overall section mode (determines which slope ratio to use)
 * @returns Array of {offset, level} points defining the formation template
 */
export function computeFormationLine(
  template: RoadTemplate,
  formationLevel: number,
  groundPoints: ProfilePoint[],
  isCut: boolean
): ProfilePoint[] {
  const {
    carriagewayWidth,
    shoulderWidth,
    cutSlope,
    fillSlope,
    camber,
    subgradeDepth,
  } = template

  const halfCW = carriagewayWidth / 2
  const points: ProfilePoint[] = []

  // Determine slope ratio based on section mode
  const slopeStr = isCut ? cutSlope : fillSlope
  const slopeRatio = parseSlopeRatio(slopeStr)

  // Shoulder cross-fall (outward slope) — 4% per Kenya RDM 1.1
  const shoulderCrossfall = 0.04

  // --- Left side ---

  // Left carriageway edge level (from camber profile)
  const leftEdgeLevel = formationLevel - (camber / 100) * halfCW

  // Left shoulder outer edge
  const leftShoulderOffset = -(halfCW + shoulderWidth)
  const leftShoulderLevel = leftEdgeLevel - shoulderCrossfall * shoulderWidth

  // Left slope intercept
  const leftIntercept = computeSlopeIntercept(
    leftShoulderOffset,
    leftShoulderLevel,
    slopeRatio,
    isCut,
    groundPoints
  )

  // --- Right side ---

  // Right carriageway edge level (from camber profile)
  const rightEdgeLevel = formationLevel - (camber / 100) * halfCW

  // Right shoulder outer edge
  const rightShoulderOffset = halfCW + shoulderWidth
  const rightShoulderLevel = rightEdgeLevel - shoulderCrossfall * shoulderWidth

  // Right slope intercept
  const rightIntercept = computeSlopeIntercept(
    rightShoulderOffset,
    rightShoulderLevel,
    slopeRatio,
    isCut,
    groundPoints
  )

  // --- Build points array (left to right) ---

  // Left slope
  if (leftIntercept) {
    points.push(leftIntercept)
  }
  points.push({ offset: leftShoulderOffset, level: leftShoulderLevel })

  // Left carriageway edge
  points.push({ offset: -halfCW, level: leftEdgeLevel })

  // Carriageway with camber (centre point only — for key points)
  // Full camber profile can be generated separately
  points.push({ offset: 0, level: formationLevel })

  // Right carriageway edge
  points.push({ offset: halfCW, level: rightEdgeLevel })

  // Right shoulder
  points.push({ offset: rightShoulderOffset, level: rightShoulderLevel })

  // Right slope
  if (rightIntercept) {
    points.push(rightIntercept)
  }

  return points
}

/**
 * Compute the full formation line with detailed camber points for rendering.
 *
 * This returns a more detailed set of points including multiple camber profile
 * points across the carriageway (instead of just edge-centre-edge).
 */
export function computeDetailedFormationLine(
  template: RoadTemplate,
  formationLevel: number,
  groundPoints: ProfilePoint[],
  isCut: boolean
): ProfilePoint[] {
  const {
    carriagewayWidth,
    shoulderWidth,
    cutSlope,
    fillSlope,
    camber,
  } = template

  const halfCW = carriagewayWidth / 2
  const points: ProfilePoint[] = []

  const slopeStr = isCut ? cutSlope : fillSlope
  const slopeRatio = parseSlopeRatio(slopeStr)
  const shoulderCrossfall = 0.04

  // Left carriageway edge level
  const leftEdgeLevel = formationLevel - (camber / 100) * halfCW
  const rightEdgeLevel = formationLevel - (camber / 100) * halfCW

  // Left shoulder
  const leftShoulderOffset = -(halfCW + shoulderWidth)
  const leftShoulderLevel = leftEdgeLevel - shoulderCrossfall * shoulderWidth

  // Right shoulder
  const rightShoulderOffset = halfCW + shoulderWidth
  const rightShoulderLevel = rightEdgeLevel - shoulderCrossfall * shoulderWidth

  // Slope intercepts
  const leftIntercept = computeSlopeIntercept(
    leftShoulderOffset,
    leftShoulderLevel,
    slopeRatio,
    isCut,
    groundPoints
  )
  const rightIntercept = computeSlopeIntercept(
    rightShoulderOffset,
    rightShoulderLevel,
    slopeRatio,
    isCut,
    groundPoints
  )

  // Left slope
  if (leftIntercept) {
    points.push(leftIntercept)
  }
  points.push({ offset: leftShoulderOffset, level: leftShoulderLevel })
  points.push({ offset: -halfCW, level: leftEdgeLevel })

  // Detailed camber profile
  const camberProfile = computeCamberProfile(carriagewayWidth, camber, formationLevel)
  for (const cp of camberProfile) {
    // Skip duplicate points at edges and centre
    if (Math.abs(cp.offset - (-halfCW)) < 0.01) continue
    if (Math.abs(cp.offset - halfCW) < 0.01) continue
    if (Math.abs(cp.offset) < 0.01) continue
    points.push(cp)
  }

  // Centre point
  points.push({ offset: 0, level: formationLevel })

  // Right carriageway edge
  points.push({ offset: halfCW, level: rightEdgeLevel })
  points.push({ offset: rightShoulderOffset, level: rightShoulderLevel })

  // Right slope
  if (rightIntercept) {
    points.push(rightIntercept)
  }

  // Sort by offset to ensure correct rendering order
  return points.sort((a, b) => a.offset - b.offset)
}

// ─── CUT/FILL AREA (SHOELACE METHOD) ───────────────────────────────────────────

/**
 * Compute the area between ground profile and formation line using the shoelace formula.
 *
 * The function creates a closed polygon by tracing:
 *   1. Ground profile from left to right
 *   2. Formation line from right to left
 *   3. Close back to start
 *
 * Shoelace formula (surveyor's formula):
 *   A = ½ |Σ(xᵢyᵢ₊₁ - xᵢ₊₁yᵢ)|
 *
 * Sign convention:
 *   - Positive result = cut (ground above formation, material to remove)
 *   - Negative result = fill (ground below formation, material to add)
 *
 * Reference: Ghilani & Wolf, Elementary Surveying, §26.3
 *
 * @param groundPoints - Ground profile points (sorted by offset)
 * @param formationPoints - Formation line points (sorted by offset)
 * @returns Signed area: positive = cut, negative = fill (m²)
 */
export function computeCutFillArea(
  groundPoints: ProfilePoint[],
  formationPoints: ProfilePoint[]
): number {
  if (groundPoints.length < 2 || formationPoints.length < 2) {
    return 0
  }

  // Sort both profiles by offset
  const sortedGround = [...groundPoints].sort((a, b) => a.offset - b.offset)
  const sortedFormation = [...formationPoints].sort((a, b) => a.offset - b.offset)

  // Build a closed polygon by combining both profiles
  // Trace ground from left to right, then formation from right to left
  const polygon: ProfilePoint[] = []

  // Use the wider extent of both profiles
  const minOffset = Math.min(sortedGround[0].offset, sortedFormation[0].offset)
  const maxOffset = Math.max(
    sortedGround[sortedGround.length - 1].offset,
    sortedFormation[sortedFormation.length - 1].offset
  )

  // Helper: interpolate level at a given offset from a profile
  function interpolateLevel(profile: ProfilePoint[], offset: number): number {
    if (offset <= profile[0].offset) return profile[0].level
    if (offset >= profile[profile.length - 1].offset) {
      return profile[profile.length - 1].level
    }

    for (let i = 0; i < profile.length - 1; i++) {
      if (
        profile[i].offset <= offset &&
        profile[i + 1].offset >= offset
      ) {
        const segLen = profile[i + 1].offset - profile[i].offset
        if (segLen < 1e-12) return profile[i].level
        const t = (offset - profile[i].offset) / segLen
        return profile[i].level + t * (profile[i + 1].level - profile[i].level)
      }
    }
    return profile[profile.length - 1].level
  }

  // Build combined polygon with offset-aligned points
  const numSamples = Math.max(
    sortedGround.length + sortedFormation.length,
    20
  )

  // Collect all unique offset values from both profiles
  const offsets = new Set<number>()
  for (const p of sortedGround) offsets.add(p.offset)
  for (const p of sortedFormation) offsets.add(p.offset)

  const sortedOffsets = Array.from(offsets).sort((a, b) => a - b)

  // Build closed polygon:
  // Ground left→right, then Formation right→left
  for (const offset of sortedOffsets) {
    polygon.push({
      offset,
      level: interpolateLevel(sortedGround, offset),
    })
  }
  for (let i = sortedOffsets.length - 1; i >= 0; i--) {
    polygon.push({
      offset: sortedOffsets[i],
      level: interpolateLevel(sortedFormation, sortedOffsets[i]),
    })
  }

  // Shoelace formula
  let area = 0
  const n = polygon.length
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n
    area += polygon[i].offset * polygon[j].level
    area -= polygon[j].offset * polygon[i].level
  }

  area = area / 2

  // Positive area = clockwise = ground above formation = cut
  // We need to verify the sign convention by checking the first point relationship
  // If ground is above formation at centre → cut (positive)
  const centreGround = interpolateLevel(sortedGround, 0)
  const centreFormation = interpolateLevel(sortedFormation, 0)

  // If ground > formation at centre → cut, which should be positive
  // Shoelace convention: if vertices are ordered clockwise, result is positive
  // Our ground→formation polygon should give positive for cut
  // If the sign is wrong, negate it
  if (centreGround > centreFormation && area < 0) {
    return -area
  }
  if (centreGround < centreFormation && area > 0) {
    return -area
  }

  return area
}

// ─── UTILITY FUNCTIONS ─────────────────────────────────────────────────────────

/**
 * Determine whether a cross-section is predominantly cut or fill.
 *
 * A section is "cut" if the ground level at centreline is above the formation level,
 * "fill" if below, and "mixed" if there are significant areas of both.
 *
 * @param groundPoints - Ground profile points
 * @param formationLevel - Formation RL at centreline
 * @returns 'cut' | 'fill' | 'mixed'
 */
export function determineSectionType(
  groundPoints: ProfilePoint[],
  formationLevel: number
): 'cut' | 'fill' | 'mixed' {
  if (groundPoints.length === 0) return 'fill'

  const sorted = [...groundPoints].sort((a, b) => a.offset - b.offset)

  let aboveCount = 0
  let belowCount = 0

  for (const p of sorted) {
    if (p.level > formationLevel) aboveCount++
    else if (p.level < formationLevel) belowCount++
  }

  if (aboveCount === 0) return 'fill'
  if (belowCount === 0) return 'cut'

  // If more than 70% of points are on one side, classify as that side
  const total = aboveCount + belowCount
  if (aboveCount / total > 0.7) return 'cut'
  if (belowCount / total > 0.7) return 'fill'

  return 'mixed'
}

/**
 * Format chainage as "Km+mmm.ddd" for display.
 *
 * @param chainage - Chainage in metres
 * @returns Formatted chainage string
 */
export function formatChainage(chainage: number): string {
  const km = Math.floor(chainage / 1000)
  const m = chainage % 1000
  return km > 0
    ? `${km}+${m.toFixed(3).padStart(6, '0')}`
    : `${m.toFixed(3)}`
}

/**
 * Compute ground level at centreline by interpolation.
 */
export function interpolateGroundAtCentre(
  groundPoints: ProfilePoint[]
): number | null {
  if (groundPoints.length === 0) return null

  const sorted = [...groundPoints].sort((a, b) => a.offset - b.offset)

  // Check if we have a point at offset 0
  const exact = sorted.find(p => Math.abs(p.offset) < 0.001)
  if (exact) return exact.level

  // Check if offset 0 is within the range
  if (sorted[0].offset > 0 || sorted[sorted.length - 1].offset < 0) {
    // Extrapolate from the nearest two points
    if (sorted[0].offset > 0) {
      const p1 = sorted[0]
      const p2 = sorted[1] || p1
      const dOffset = p2.offset - p1.offset
      if (Math.abs(dOffset) < 1e-12) return p1.level
      return p1.level + (-p1.offset / dOffset) * (p2.level - p1.level)
    }
    const p1 = sorted[sorted.length - 2] || sorted[0]
    const p2 = sorted[sorted.length - 1]
    const dOffset = p2.offset - p1.offset
    if (Math.abs(dOffset) < 1e-12) return p2.level
    return p1.level + (-p1.offset / dOffset) * (p2.level - p1.level)
  }

  // Linear interpolation
  for (let i = 0; i < sorted.length - 1; i++) {
    if (sorted[i].offset <= 0 && sorted[i + 1].offset >= 0) {
      const t = -sorted[i].offset / (sorted[i + 1].offset - sorted[i].offset)
      return sorted[i].level + t * (sorted[i + 1].level - sorted[i].level)
    }
  }

  return null
}

// All angles in decimal degrees. Distances in metres.
// Standards: KRDM 2017, KeRRA Rural Roads Design Manual

export interface SimpleCurveInput {
  radius: number          // R in metres
  deflectionAngle: number // Δ (total deflection) in decimal degrees
  chainage_IP: number     // chainage at intersection point
}

export interface SimpleCurveResult {
  radius: number
  deflectionAngle: number
  tangentLength: number       // T
  curveLength: number         // L
  longChord: number           // C
  midOrdinate: number         // M
  externalDistance: number    // E
  chainage_TC: number         // chainage at tangent-to-curve
  chainage_CC: number         // chainage at curve centre (mid)
  chainage_CT: number         // chainage at curve-to-tangent
  settingOutTable: SettingOutRow[]
}

export interface SettingOutRow {
  chainage: number
  deflectionFromTC: number    // cumulative deflection angle from TC
  chordFromTC: number         // chord from TC to this point
  chordIncrement: number      // chord from previous point
}

export function simpleCircularCurve(input: SimpleCurveInput): SimpleCurveResult {
  const { radius: R, deflectionAngle: Delta, chainage_IP } = input
  const DeltaRad = (Delta * Math.PI) / 180

  const T = R * Math.tan(DeltaRad / 2)
  const L = (Math.PI * R * Delta) / 180
  const C = 2 * R * Math.sin(DeltaRad / 2)
  const M = R * (1 - Math.cos(DeltaRad / 2))
  const E = R * (1 / Math.cos(DeltaRad / 2) - 1)

  const chainage_TC = chainage_IP - T
  const chainage_CT = chainage_TC + L
  const chainage_CC = chainage_TC + L / 2

  // Setting out table — pegs at every 20m chainage
  const pegInterval = 20
  const settingOutTable: SettingOutRow[] = []

  let peg = Math.ceil(chainage_TC / pegInterval) * pegInterval
  let prevChord = 0

  while (peg <= chainage_CT) {
    const arc = peg - chainage_TC
    const deflection = (arc / (2 * R)) * (180 / Math.PI)
    const chord = 2 * R * Math.sin((arc / R) / 2)
    const increment = chord - prevChord

    settingOutTable.push({
      chainage: peg,
      deflectionFromTC: parseFloat(deflection.toFixed(6)),
      chordFromTC: parseFloat(chord.toFixed(4)),
      chordIncrement: parseFloat(increment.toFixed(4))
    })

    prevChord = chord
    peg += pegInterval
  }

  // Always include CT
  if (settingOutTable[settingOutTable.length - 1]?.chainage !== chainage_CT) {
    const arc = L
    const deflection = Delta / 2
    const chord = C
    settingOutTable.push({
      chainage: parseFloat(chainage_CT.toFixed(3)),
      deflectionFromTC: parseFloat(deflection.toFixed(6)),
      chordFromTC: parseFloat(chord.toFixed(4)),
      chordIncrement: parseFloat((chord - prevChord).toFixed(4))
    })
  }

  return {
    radius: R,
    deflectionAngle: Delta,
    tangentLength: parseFloat(T.toFixed(4)),
    curveLength: parseFloat(L.toFixed(4)),
    longChord: parseFloat(C.toFixed(4)),
    midOrdinate: parseFloat(M.toFixed(4)),
    externalDistance: parseFloat(E.toFixed(4)),
    chainage_TC: parseFloat(chainage_TC.toFixed(3)),
    chainage_CC: parseFloat(chainage_CC.toFixed(3)),
    chainage_CT: parseFloat(chainage_CT.toFixed(3)),
    settingOutTable
  }
}

export interface VerticalCurveInput {
  gradeIn: number        // g1 in percent (e.g. +3.5 = 3.5)
  gradeOut: number       // g2 in percent
  length: number         // L in metres (must satisfy K and sight distance)
  chainage_VIP: number   // chainage at vertical intersection point
  elevation_VIP: number  // elevation at VIP
}

export interface VerticalCurveResult {
  gradeIn: number
  gradeOut: number
  algebraicDiff: number  // A = g2 - g1
  kValue: number         // K = L / A
  length: number
  isCrest: boolean
  chainage_VPC: number   // start of curve
  chainage_VPT: number   // end of curve
  elevationTable: VerticalCurvePoint[]
}

export interface VerticalCurvePoint {
  chainage: number
  elevation: number
  grade: number          // grade at this point
}

export function verticalCurve(input: VerticalCurveInput): VerticalCurveResult {
  const { gradeIn: g1, gradeOut: g2, length: L, chainage_VIP, elevation_VIP } = input

  const A = g2 - g1
  const K = Math.abs(L / A)
  const isCrest = A < 0

  const chainage_VPC = chainage_VIP - L / 2
  const chainage_VPT = chainage_VIP + L / 2
  const elevation_VPC = elevation_VIP - (g1 / 100) * (L / 2)

  const elevationTable: VerticalCurvePoint[] = []
  const step = 20

  let ch = Math.ceil(chainage_VPC / step) * step
  while (ch <= chainage_VPT) {
    const x = ch - chainage_VPC
    // Parabolic equation: y = elevation_VPC + (g1/100)*x + (A/200L)*x²
    const elevation = elevation_VPC + (g1 / 100) * x + (A / (200 * L)) * x * x
    const grade = g1 + (A / L) * x   // instantaneous grade at x
    elevationTable.push({
      chainage: parseFloat(ch.toFixed(3)),
      elevation: parseFloat(elevation.toFixed(4)),
      grade: parseFloat(grade.toFixed(4))
    })
    ch += step
  }

  return {
    gradeIn: g1,
    gradeOut: g2,
    algebraicDiff: parseFloat(A.toFixed(4)),
    kValue: parseFloat(K.toFixed(2)),
    length: L,
    isCrest,
    chainage_VPC: parseFloat(chainage_VPC.toFixed(3)),
    chainage_VPT: parseFloat(chainage_VPT.toFixed(3)),
    elevationTable
  }
}

// METARDU Drainage Design Module
// Source: RDM 1.3 Section 6 (Drainage)
// Source: KeNHA Drainage Design Manual
// Source: BS EN 752:2008

// ─── TYPES ─────────────────────────────────────────────────────────────────────

export interface PipeInput {
  diameter: number        // mm
  manningN: number
  slope: number           // m/m (e.g., 0.005 for 0.5%)
  flowDepth?: number      // mm (if not full bore)
}

export interface PipeCapacity {
  fullBoreCapacity: number   // m³/s
  fullBoreVelocity: number   // m/s
  timeOfConcentration: number // min estimate
  isSelfCleansing: boolean
  minSelfCleansingGradient: number
  isVelocityAcceptable: boolean
}

export interface CatchmentInput {
  area: number            // hectares
  runoffCoefficient: number // 0-1
  rainfallIntensity: number // mm/hr
  timeOfConcentration: number // min
}

export interface CatchmentResult {
  peakFlow: number        // m³/s
  catchmentArea: number
  effectiveArea: number
  returnPeriod: string
}

export interface ChannelInput {
  bedWidth: number        // m
  sideSlope: number       // H:V (e.g., 1.5)
  manningN: number
  slope: number           // m/m
  flowDepth: number       // m
}

export interface ChannelCapacity {
  flowArea: number
  wettedPerimeter: number
  hydraulicRadius: number
  velocity: number
  discharge: number
  topWidth: number
  isSelfCleansing: boolean
}

// ─── MANNING'S N VALUES ───────────────────────────────────────────────────────

export const MANNING_N: Record<string, number> = {
  'Concrete pipe': 0.013,
  'HDPE': 0.011,
  'uPVC': 0.011,
  'VCP': 0.013,
  'Corrugated steel': 0.024,
  'Concrete channel': 0.015,
  'Earth channel': 0.025,
  'Grass channel': 0.035,
  'Stone lining': 0.025,
  'Masonry': 0.017,
}

// ─── RUNOFF COEFFICIENTS ──────────────────────────────────────────────────────

export const RUNOFF_COEFFICIENTS: Record<string, { min: number; max: number; typical: number }> = {
  'Asphalt/Concrete': { min: 0.85, max: 0.95, typical: 0.90 },
  'Paved': { min: 0.75, max: 0.85, typical: 0.80 },
  'Gravel': { min: 0.35, max: 0.70, typical: 0.50 },
  'Bare earth': { min: 0.20, max: 0.40, typical: 0.30 },
  'Grass/Park': { min: 0.10, max: 0.25, typical: 0.15 },
  'Forest': { min: 0.05, max: 0.15, typical: 0.10 },
  'Commercial': { min: 0.70, max: 0.95, typical: 0.85 },
  'Residential': { min: 0.40, max: 0.70, typical: 0.55 },
  'Industrial': { min: 0.50, max: 0.80, typical: 0.65 },
  'Agriculture': { min: 0.15, max: 0.45, typical: 0.25 },
}

// ─── STANDARD PIPE SIZES (mm) ────────────────────────────────────────────────

export const STANDARD_PIPE_SIZES = [100, 150, 200, 225, 300, 375, 450, 525, 600, 675, 750, 900, 1050, 1200, 1350, 1500]

// ─── PIPE HYDRAULICS ─────────────────────────────────────────────────────────

export function manningPipeCapacity(input: PipeInput): PipeCapacity {
  const { diameter, manningN, slope, flowDepth } = input
  const D = diameter / 1000 // mm to m

  // Full bore calculations
  const area = Math.PI * D * D / 4
  const wettedPerimeter = Math.PI * D
  const hydraulicRadius = D / 4

  const velocity = (1 / manningN) * Math.pow(hydraulicRadius, 2 / 3) * Math.pow(slope, 0.5)
  const capacity = velocity * area

  // Min slope for self-cleansing (V >= 0.6 m/s per RDM 1.3)
  const minSlope = Math.pow(0.6 * manningN / Math.pow(hydraulicRadius, 2 / 3), 2)

  // Max velocity check (V < 3.0 m/s for concrete, higher for HDPE/uPVC)
  const maxVelocity = manningN <= 0.012 ? 5.0 : 3.0

  return {
    fullBoreCapacity: Math.round(capacity * 10000) / 10000,
    fullBoreVelocity: Math.round(velocity * 1000) / 1000,
    timeOfConcentration: Math.round((D * 1000 / velocity / 60) * 10) / 10, // rough estimate in minutes
    isSelfCleansing: velocity >= 0.6,
    minSelfCleansingGradient: Math.round(minSlope * 100000) / 100000,
    isVelocityAcceptable: velocity < maxVelocity,
  }
}

export function minPipeSlope(diameterMm: number, manningN: number, minVelocity: number = 0.6): number {
  const D = diameterMm / 1000
  const R = D / 4
  return Math.pow(minVelocity * manningN / Math.pow(R, 2 / 3), 2)
}

// ─── CATCHMENT / RATIONAL METHOD ─────────────────────────────────────────────

export function rationalMethodCatchment(input: CatchmentInput): CatchmentResult {
  const { area, runoffCoefficient, rainfallIntensity, timeOfConcentration } = input

  // Q = (C × I × A) / 360
  // Converts mm/hr × ha to m³/s: divide by 3.6 × 100
  const peakFlow = (runoffCoefficient * rainfallIntensity * area) / 360

  // Return period recommendation (RDM 1.3)
  const isUrban = runoffCoefficient > 0.5
  const returnPeriod = isUrban ? '1 in 50 years' : '1 in 25 years'

  return {
    peakFlow: Math.round(peakFlow * 10000) / 10000,
    catchmentArea: area,
    effectiveArea: Math.round(runoffCoefficient * area * 100) / 100,
    returnPeriod,
  }
}

// ─── PIPE SIZING ──────────────────────────────────────────────────────────────

export function sizePipe(
  peakFlow: number,
  manningN: number,
  slope: number,
  fillRatio: number = 0.75
): { diameter: number; velocity: number; capacity: number; isSelfCleansing: boolean } | null {
  if (peakFlow <= 0 || slope <= 0) return null

  for (const diameter of STANDARD_PIPE_SIZES) {
    const result = manningPipeCapacity({ diameter, manningN, slope })

    // At partial fill, capacity ≈ full × flowRatio
    // Simplified: for fillRatio, capacity ≈ full × (theta - sin(theta)) / (2*pi)
    // More accurate: use hydraulic elements chart approximation
    const partialCapacity = result.fullBoreCapacity * (0.85 + 0.15 * fillRatio) // reasonable approximation

    if (partialCapacity >= peakFlow && result.isSelfCleansing) {
      return {
        diameter,
        velocity: result.fullBoreVelocity,
        capacity: result.fullBoreCapacity,
        isSelfCleansing: result.isSelfCleansing,
      }
    }
  }

  return null // no standard size sufficient
}

// ─── CHANNEL HYDRAULICS (TRAPEZOIDAL) ────────────────────────────────────────

export function manningChannelCapacity(input: ChannelInput): ChannelCapacity {
  const { bedWidth, sideSlope, manningN, slope, flowDepth } = input

  const y = flowDepth
  const z = sideSlope

  // Trapezoidal channel geometry
  const flowArea = (bedWidth + z * y) * y
  const wettedPerimeter = bedWidth + 2 * y * Math.sqrt(1 + z * z)
  const hydraulicRadius = flowArea / wettedPerimeter
  const topWidth = bedWidth + 2 * z * y

  const velocity = (1 / manningN) * Math.pow(hydraulicRadius, 2 / 3) * Math.pow(slope, 0.5)
  const discharge = velocity * flowArea

  return {
    flowArea: Math.round(flowArea * 10000) / 10000,
    wettedPerimeter: Math.round(wettedPerimeter * 10000) / 10000,
    hydraulicRadius: Math.round(hydraulicRadius * 10000) / 10000,
    velocity: Math.round(velocity * 1000) / 1000,
    discharge: Math.round(discharge * 10000) / 10000,
    topWidth: Math.round(topWidth * 100) / 100,
    isSelfCleansing: velocity >= 0.6,
  }
}

// ─── HYDRAULIC GRADIENT CHECK ────────────────────────────────────────────────

export function checkPipeGradient(
  pipeDiameterMm: number,
  manningN: number,
  peakFlow: number
): { requiredGradient: number; velocityAtGradient: number; isAdequate: boolean } {
  if (peakFlow <= 0) return { requiredGradient: 0, velocityAtGradient: 0, isAdequate: false }

  const D = pipeDiameterMm / 1000
  const R = D / 4
  const A = Math.PI * D * D / 4

  // Rearranged Manning's for slope: V = Q/A, S = (V*n/R^(2/3))^2
  const V = peakFlow / A
  const S = Math.pow(V * manningN / Math.pow(R, 2 / 3), 2)

  return {
    requiredGradient: Math.round(S * 100000) / 100000,
    velocityAtGradient: Math.round(V * 1000) / 1000,
    isAdequate: V >= 0.6 && V <= 3.0,
  }
}

/**
 * Geotagged Photo EXIF Parsing
 *
 * Client-side EXIF GPS data extraction from JPEG/TIFF photo files.
 * No npm dependencies — all parsing implemented from scratch using the
 * EXIF 2.3 Specification and well-documented binary format structures.
 *
 * Standards:
 * - EXIF 2.3 Specification (JEITA CP-3451)
 * - OGC EXIF Metadata
 * - WGS84 Technical Manual (NIMA TR8350.2)
 *
 * @packageDocumentation
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export interface EXIFGPSData {
  /** Latitude in decimal degrees */
  latitude: number;
  /** Longitude in decimal degrees */
  longitude: number;
  /** Altitude in meters above sea level (may be negative) */
  altitude: number;
  /** Altitude reference: above/below sea level */
  altitudeRef: 'above' | 'below' | 'unknown';
  /** Photo capture timestamp */
  timestamp: Date;
  /** Camera manufacturer */
  cameraMake: string;
  /** Camera model */
  cameraModel: string;
  /** GPS compass heading 0–360°, -1 if unavailable */
  heading: number;
  /** GPS accuracy in meters, -1 if unavailable */
  accuracy: number;
  /** Original filename */
  filename: string;
  /** Base64-encoded JPEG thumbnail if available */
  thumbnail: string | null;
}

export interface PhotoWithLocation {
  file: File;
  /** EXIF data, or null if no GPS information found */
  exif: EXIFGPSData | null;
  /** Whether any EXIF data was found (even without GPS) */
  hasEXIF: boolean;
  /** Error message if parsing failed */
  error?: string;
}

// ─── Internal EXIF Types ─────────────────────────────────────────────────────

const TIFF_BYTE_ORDER_LE = 0x4949; // 'II' (Intel, little-endian)
const TIFF_BYTE_ORDER_BE = 0x4d4d; // 'MM' (Motorola, big-endian)
const TIFF_MAGIC = 42;

// EXIF data types
const EXIF_TYPE_BYTE = 1; // 1 byte
const EXIF_TYPE_ASCII = 2; // 1 byte per char, null-terminated
const EXIF_TYPE_SHORT = 3; // 2 bytes unsigned
const EXIF_TYPE_LONG = 4; // 4 bytes unsigned
const EXIF_TYPE_RATIONAL = 5; // 8 bytes (numerator/denominator)
const EXIF_TYPE_UNDEFINED = 7; // 1 byte
const EXIF_TYPE_SLONG = 9; // 4 bytes signed
const EXIF_TYPE_SRATIONAL = 10; // 8 bytes signed rational

// Tag sizes in bytes
const TAG_TYPE_SIZES: Record<number, number> = {
  [EXIF_TYPE_BYTE]: 1,
  [EXIF_TYPE_ASCII]: 1,
  [EXIF_TYPE_SHORT]: 2,
  [EXIF_TYPE_LONG]: 4,
  [EXIF_TYPE_RATIONAL]: 8,
  [EXIF_TYPE_UNDEFINED]: 1,
  [EXIF_TYPE_SLONG]: 4,
  [EXIF_TYPE_SRATIONAL]: 8,
};

// Main IFD tag IDs
const TAG_MAKE = 0x010f;
const TAG_MODEL = 0x0110;
const TAG_DATE_TIME_ORIGINAL = 0x9003;
const TAG_GPS_IFD_POINTER = 0x8825;

// GPS IFD tag IDs
const TAG_GPS_LATITUDE_REF = 0x0001;
const TAG_GPS_LATITUDE = 0x0002;
const TAG_GPS_LONGITUDE_REF = 0x0003;
const TAG_GPS_LONGITUDE = 0x0004;
const TAG_GPS_ALTITUDE_REF = 0x0005;
const TAG_GPS_ALTITUDE = 0x0006;
const TAG_GPS_TIMESTAMP = 0x0007;
const TAG_GPS_IMG_DIRECTION = 0x0011;
const TAG_GPS_H_POSITIONING_ERROR = 0x001e;

interface IFDEntry {
  tag: number;
  type: number;
  count: number;
  valueOffset: number; // offset from TIFF header start
  isOffset: boolean; // true if value doesn't fit in 4 bytes
}

interface ParsedEXIF {
  byteOrder: 'le' | 'be';
  tiffHeaderOffset: number; // offset in the ArrayBuffer where TIFF header starts
  ifd0Entries: IFDEntry[];
  ifd1Offset: number | null; // thumbnail IFD offset (relative to TIFF header)
  gpsEntries: IFDEntry[];
}

// ─── Binary Reader Helper ────────────────────────────────────────────────────

/**
 * Lightweight binary reader that handles both little-endian and big-endian byte orders.
 */
class BinaryReader {
  private view: DataView;
  private order: 'le' | 'be';

  constructor(buffer: ArrayBuffer, order: 'le' | 'be') {
    this.view = new DataView(buffer);
    this.order = order;
  }

  getUint8(offset: number): number {
    return this.view.getUint8(offset);
  }

  getUint16(offset: number): number {
    return this.order === 'le'
      ? this.view.getUint16(offset, true)
      : this.view.getUint16(offset, false);
  }

  getInt16(offset: number): number {
    return this.order === 'le'
      ? this.view.getInt16(offset, true)
      : this.view.getInt16(offset, false);
  }

  getUint32(offset: number): number {
    return this.order === 'le'
      ? this.view.getUint32(offset, true)
      : this.view.getUint32(offset, false);
  }

  getInt32(offset: number): number {
    return this.order === 'le'
      ? this.view.getInt32(offset, true)
      : this.view.getInt32(offset, false);
  }

  getFloat64(offset: number): number {
    return this.view.getFloat64(offset, this.order === 'le');
  }

  /**
   * Read a rational number (two 32-bit values: numerator/denominator).
   * Returns the floating-point result.
   */
  getRational(offset: number): number {
    const num = this.getUint32(offset);
    const den = this.getUint32(offset + 4);
    return den === 0 ? 0 : num / den;
  }

  /**
   * Read a signed rational number.
   */
  getSRational(offset: number): number {
    const num = this.getInt32(offset);
    const den = this.getInt32(offset + 4);
    return den === 0 ? 0 : num / den;
  }

  /**
   * Read an ASCII string (null-terminated).
   */
  getASCII(offset: number, length: number): string {
    const bytes = new Uint8Array(this.view.buffer, offset, length);
    // Find null terminator
    let end = bytes.indexOf(0);
    if (end === -1) end = length;
    let str = '';
    for (let i = 0; i < end; i++) {
      str += String.fromCharCode(bytes[i]);
    }
    return str.trim();
  }

  getBufferLength(): number {
    return this.view.byteLength;
  }
}

// ─── EXIF Parsing ────────────────────────────────────────────────────────────

/**
 * Find the EXIF APP1 segment in a JPEG file.
 *
 * JPEG structure:
 * - Starts with FF D8 (SOI marker)
 * - APP1 marker: FF E1, followed by 2-byte length, "Exif\0\0", then TIFF data
 *
 * @returns offset of TIFF header within the buffer, or -1 if not found
 */
function findEXIFAPP1(buffer: ArrayBuffer): number {
  const view = new DataView(buffer);

  // Verify JPEG SOI marker
  if (view.byteLength < 4) return -1;
  if (view.getUint8(0) !== 0xff || view.getUint8(1) !== 0xd8) return -1;

  let offset = 2;

  while (offset < view.byteLength - 4) {
    const marker = view.getUint16(offset);

    // Check for APP1 (0xFFE1)
    if (marker === 0xffe1) {
      const segLength = view.getUint16(offset + 2);

      // Verify "Exif\0\0" header
      if (offset + 4 + 6 <= view.byteLength) {
        const exifHeader = String.fromCharCode(
          view.getUint8(offset + 4),
          view.getUint8(offset + 5),
          view.getUint8(offset + 6),
          view.getUint8(offset + 7),
          view.getUint8(offset + 8),
          view.getUint8(offset + 9)
        );
        if (exifHeader === 'Exif\0\0') {
          // TIFF header starts right after "Exif\0\0"
          return offset + 10;
        }
      }
    }

    // Not APP1 — skip to next segment
    if ((marker & 0xff00) !== 0xff00) break; // Not a valid marker
    if (marker === 0xffd8 || marker === 0xffd9) break; // SOI or EOI

    const segLength = view.getUint16(offset + 2);
    if (segLength < 2) break; // Invalid segment length
    offset += 2 + segLength;
  }

  return -1;
}

/**
 * Parse the EXIF data from a JPEG ArrayBuffer.
 *
 * Returns structured IFD entries, raw buffer reference, and byte order info.
 */
function parseEXIFData(buffer: ArrayBuffer): ParsedEXIF | null {
  const tiffOffset = findEXIFAPP1(buffer);
  if (tiffOffset === -1) return null;

  const view = new DataView(buffer);
  if (tiffOffset + 8 > view.byteLength) return null;

  // Read TIFF header
  const byteOrderMark = view.getUint16(tiffOffset);
  let order: 'le' | 'be';
  if (byteOrderMark === TIFF_BYTE_ORDER_LE) {
    order = 'le';
  } else if (byteOrderMark === TIFF_BYTE_ORDER_BE) {
    order = 'be';
  } else {
    return null; // Invalid byte order
  }

  const reader = new BinaryReader(buffer, order);

  // Verify TIFF magic number (42)
  const magic = reader.getUint16(tiffOffset + 2);
  if (magic !== TIFF_MAGIC) return null;

  // Offset to first IFD (relative to TIFF header start)
  const ifd0Offset = reader.getUint32(tiffOffset + 4);
  if (ifd0Offset + tiffOffset > view.byteLength) return null;

  // Parse IFD0 (main image IFD)
  const { entries: ifd0Entries, nextIFDOffset } = parseIFD(
    reader,
    tiffOffset,
    ifd0Offset
  );

  // Find GPS IFD pointer
  let gpsEntries: IFDEntry[] = [];
  const gpsPointerEntry = ifd0Entries.find((e) => e.tag === TAG_GPS_IFD_POINTER);
  if (gpsPointerEntry) {
    const gpsIFDOffset = gpsPointerEntry.valueOffset;
    const gpsResult = parseIFD(reader, tiffOffset, gpsIFDOffset);
    gpsEntries = gpsResult.entries;
  }

  return {
    byteOrder: order,
    tiffHeaderOffset: tiffOffset,
    ifd0Entries,
    ifd1Offset: nextIFDOffset,
    gpsEntries,
  };
}

/**
 * Parse an IFD (Image File Directory) at a given offset.
 *
 * IFD structure:
 * - 2 bytes: number of entries
 * - N × 12 bytes: entries (tag:2, type:2, count:4, value/offset:4)
 * - 4 bytes: offset to next IFD (0 if none)
 */
function parseIFD(
  reader: BinaryReader,
  tiffOffset: number,
  ifdOffset: number
): { entries: IFDEntry[]; nextIFDOffset: number | null } {
  const absOffset = tiffOffset + ifdOffset;

  if (absOffset + 2 > reader.getBufferLength()) {
    return { entries: [], nextIFDOffset: null };
  }

  const entryCount = reader.getUint16(absOffset);
  const entries: IFDEntry[] = [];
  let ptr = absOffset + 2;

  for (let i = 0; i < entryCount; i++) {
    if (ptr + 12 > reader.getBufferLength()) break;

    const tag = reader.getUint16(ptr);
    const type = reader.getUint16(ptr + 2);
    const count = reader.getUint32(ptr + 4);

    const typeSize = TAG_TYPE_SIZES[type] ?? 1;
    const totalSize = count * typeSize;

    // If total data fits in 4 bytes, value is stored inline;
    // otherwise it's an offset from TIFF header
    let valueOffset: number;
    let isOffset: boolean;

    if (totalSize <= 4) {
      // Value is stored inline at ptr + 8
      valueOffset = ptr + 8;
      isOffset = false;
    } else {
      // Value offset is relative to TIFF header start
      valueOffset = tiffOffset + reader.getUint32(ptr + 8);
      isOffset = true;
    }

    entries.push({ tag, type, count, valueOffset, isOffset });
    ptr += 12;
  }

  // Next IFD offset
  let nextIFDOffset: number | null = null;
  if (ptr + 4 <= reader.getBufferLength()) {
    const next = reader.getUint32(ptr);
    if (next !== 0) {
      nextIFDOffset = next;
    }
  }

  return { entries, nextIFDOffset };
}

/**
 * Find an IFD entry by tag number.
 */
function findEntry(entries: IFDEntry[], tag: number): IFDEntry | undefined {
  return entries.find((e) => e.tag === tag);
}

/**
 * Read a string value from an IFD entry.
 */
function readStringValue(reader: BinaryReader, entry: IFDEntry): string {
  if (entry.type !== EXIF_TYPE_ASCII) return '';
  return reader.getASCII(entry.valueOffset, entry.count);
}

/**
 * Read a single unsigned 32-bit value from an IFD entry.
 * Used for IFD pointer offsets.
 */
function readLongValue(reader: BinaryReader, entry: IFDEntry): number {
  if (entry.isOffset) {
    return reader.getUint32(entry.valueOffset);
  }
  return reader.getUint32(entry.valueOffset);
}

/**
 * Read a rational array from an IFD entry (e.g., GPS coordinates).
 * GPS latitude/longitude are stored as 3 rationals: [degrees, minutes, seconds].
 */
function readRationalArray(reader: BinaryReader, entry: IFDEntry): number[] {
  const result: number[] = [];
  const count = entry.count;

  for (let i = 0; i < count; i++) {
    const offset = entry.valueOffset + i * 8;
    result.push(reader.getRational(offset));
  }

  return result;
}

/**
 * Read a single rational value from an IFD entry.
 */
function readRationalValue(reader: BinaryReader, entry: IFDEntry): number {
  return reader.getRational(entry.valueOffset);
}

/**
 * Read a single unsigned byte value from an IFD entry.
 */
function readByteValue(reader: BinaryReader, entry: IFDEntry): number {
  return reader.getUint8(entry.valueOffset);
}

/**
 * Parse a GPS date/time string (format: "YYYY:MM:DD HH:MM:SS").
 */
function parseEXIFDateTime(dateStr: string): Date {
  // Format: "2024:01:15 14:30:45"
  const cleaned = dateStr.trim();
  const match = cleaned.match(
    /^(\d{4}):(\d{2}):(\d{2})\s+(\d{2}):(\d{2}):(\d{2})$/
  );

  if (match) {
    const [, year, month, day, hour, minute, second] = match;
    return new Date(
      parseInt(year, 10),
      parseInt(month, 10) - 1,
      parseInt(day, 10),
      parseInt(hour, 10),
      parseInt(minute, 10),
      parseInt(second, 10)
    );
  }

  // Fallback: try native Date parsing
  const fallback = new Date(cleaned.replace(/:/g, '-'));
  return isNaN(fallback.getTime()) ? new Date() : fallback;
}

/**
 * Convert GPS DMS (degrees, minutes, seconds) rational values to decimal degrees.
 *
 * @param dms   Array of 3 rational values [degrees, minutes, seconds]
 * @param ref   Reference direction ('N', 'S', 'E', 'W')
 * @returns Decimal degrees (negative for S/W)
 */
function gpsDMSToDecimal(dms: number[], ref: string): number {
  const degrees = dms[0];
  const minutes = dms[1];
  const seconds = dms[2];

  let decimal = degrees + minutes / 60 + seconds / 3600;

  if (ref === 'S' || ref === 'W') {
    decimal = -decimal;
  }

  return decimal;
}

/**
 * Extract thumbnail from IFD1 (second Image File Directory).
 *
 * Thumbnail data is referenced by two tags in IFD1:
 * - 0x0201: JPEGInterchangeFormat (offset to JPEG data)
 * - 0x0202: JPEGInterchangeFormatLength (length of JPEG data)
 */
function extractThumbnail(
  reader: BinaryReader,
  tiffOffset: number,
  ifd1Offset: number
): string | null {
  if (ifd1Offset === 0 || ifd1Offset === null) return null;

  const { entries } = parseIFD(reader, tiffOffset, ifd1Offset);
  if (entries.length === 0) return null;

  const jpegOffsetEntry = findEntry(entries, 0x0201);
  const jpegLengthEntry = findEntry(entries, 0x0202);

  if (!jpegOffsetEntry || !jpegLengthEntry) return null;

  const jpegDataOffset = tiffOffset + readLongValue(reader, jpegOffsetEntry);
  const jpegDataLength = readLongValue(reader, jpegLengthEntry);

  if (
    jpegDataOffset + jpegDataLength > reader.getBufferLength() ||
    jpegDataLength <= 0
  ) {
    return null;
  }

  // Extract the raw JPEG bytes and convert to base64
  const bytes = new Uint8Array(
    reader.getBufferLength() === reader.getBufferLength()
      ? reader['view'].buffer
      : reader['view'].buffer,
    jpegDataOffset,
    jpegDataLength
  );

  // Convert to base64
  let binary = '';
  for (let i = 0; i < bytes.length; i++) {
    binary += String.fromCharCode(bytes[i]);
  }

  return 'data:image/jpeg;base64,' + btoa(binary);
}

// ─── Main: extractEXIFGPS ───────────────────────────────────────────────────

/**
 * Extract EXIF GPS data from a JPEG photo file.
 *
 * Parses the binary JPEG/TIFF file, locates the EXIF APP1 marker (0xFFE1),
 * reads IFD entries, finds the GPS IFD (tag 0x8825), and extracts:
 *
 * - GPS Latitude/Longitude (DMS rationals → decimal degrees)
 * - GPS Altitude and reference
 * - GPS timestamp
 * - Camera make/model
 * - GPS compass heading and accuracy
 * - Thumbnail from IFD1
 *
 * @param file  JPEG or TIFF File object
 * @returns Parsed EXIF GPS data
 * @throws Error if file cannot be read or has no EXIF data
 *
 * @example
 * ```ts
 * const exif = await extractEXIFGPS(photoFile);
 * }, ${exif.longitude.toFixed(6)}`);
 * } m ${exif.altitudeRef}`);
 * ```
 */
export async function extractEXIFGPS(file: File): Promise<EXIFGPSData> {
  const buffer = await file.arrayBuffer();
  const exif = parseEXIFData(buffer);

  if (!exif) {
    throw new Error(`No EXIF data found in "${file.name}". Ensure the photo contains EXIF metadata.`);
  }

  const reader = new BinaryReader(buffer, exif.byteOrder);

  // ── Extract camera info from IFD0 ──
  const makeEntry = findEntry(exif.ifd0Entries, TAG_MAKE);
  const modelEntry = findEntry(exif.ifd0Entries, TAG_MODEL);
  const dateTimeEntry = findEntry(exif.ifd0Entries, TAG_DATE_TIME_ORIGINAL);

  const cameraMake = makeEntry ? readStringValue(reader, makeEntry) : '';
  const cameraModel = modelEntry ? readStringValue(reader, modelEntry) : '';

  // Try DateTimeOriginal first, fall back to DateTime (0x0132)
  let timestamp = new Date();
  if (dateTimeEntry) {
    timestamp = parseEXIFDateTime(readStringValue(reader, dateTimeEntry));
  } else {
    const dtEntry = findEntry(exif.ifd0Entries, 0x0132);
    if (dtEntry) {
      timestamp = parseEXIFDateTime(readStringValue(reader, dtEntry));
    }
  }

  // ── Extract GPS data ──
  if (exif.gpsEntries.length === 0) {
    throw new Error(
      `No GPS data found in "${file.name}". The photo may not have geotagging enabled.`
    );
  }

  const latRefEntry = findEntry(exif.gpsEntries, TAG_GPS_LATITUDE_REF);
  const latEntry = findEntry(exif.gpsEntries, TAG_GPS_LATITUDE);
  const lonRefEntry = findEntry(exif.gpsEntries, TAG_GPS_LONGITUDE_REF);
  const lonEntry = findEntry(exif.gpsEntries, TAG_GPS_LONGITUDE);
  const altRefEntry = findEntry(exif.gpsEntries, TAG_GPS_ALTITUDE_REF);
  const altEntry = findEntry(exif.gpsEntries, TAG_GPS_ALTITUDE);

  // Validate required GPS fields
  if (!latEntry || !lonEntry) {
    throw new Error(
      `Incomplete GPS coordinates in "${file.name}". Both latitude and longitude are required.`
    );
  }

  // GPS Latitude
  const latDMS = readRationalArray(reader, latEntry);
  const latRef = latRefEntry ? readStringValue(reader, latRefEntry) : 'N';
  const latitude = gpsDMSToDecimal(latDMS, latRef);

  // GPS Longitude
  const lonDMS = readRationalArray(reader, lonEntry);
  const lonRef = lonRefEntry ? readStringValue(reader, lonRefEntry) : 'E';
  const longitude = gpsDMSToDecimal(lonDMS, lonRef);

  // GPS Altitude
  let altitude = 0;
  let altitudeRef: 'above' | 'below' | 'unknown' = 'unknown';
  if (altEntry) {
    altitude = readRationalValue(reader, altEntry);
    if (altRefEntry) {
      const ref = readByteValue(reader, altRefEntry);
      altitudeRef = ref === 0 ? 'above' : ref === 1 ? 'below' : 'unknown';
      if (altitudeRef === 'below') {
        altitude = -Math.abs(altitude);
      }
    }
  }

  // GPS Timestamp (use if DateTimeOriginal not available)
  if (!dateTimeEntry) {
    const gpsTimeEntry = findEntry(exif.gpsEntries, TAG_GPS_TIMESTAMP);
    if (gpsTimeEntry) {
      const timeDMS = readRationalArray(reader, gpsTimeEntry);
      if (timeDMS.length === 3) {
        const gpsDateEntry = findEntry(exif.gpsEntries, 0x001d); // GPSDateStamp
        if (gpsDateEntry) {
          const dateStr = readStringValue(reader, gpsDateEntry);
          // Format: "YYYY:MM:DD"
          const parts = dateStr.split(':');
          if (parts.length === 3) {
            timestamp = new Date(
              parseInt(parts[0], 10),
              parseInt(parts[1], 10) - 1,
              parseInt(parts[2], 10),
              Math.floor(timeDMS[0]),
              Math.floor(timeDMS[1]),
              Math.floor(timeDMS[2])
            );
          }
        }
      }
    }
  }

  // GPS Heading (compass direction)
  let heading = -1;
  const headingEntry = findEntry(exif.gpsEntries, TAG_GPS_IMG_DIRECTION);
  if (headingEntry) {
    heading = readRationalValue(reader, headingEntry);
  }

  // GPS Horizontal Positioning Error (accuracy)
  let accuracy = -1;
  const hpeEntry = findEntry(exif.gpsEntries, TAG_GPS_H_POSITIONING_ERROR);
  if (hpeEntry) {
    accuracy = readRationalValue(reader, hpeEntry);
  }

  // Thumbnail
  let thumbnail: string | null = null;
  if (exif.ifd1Offset !== null && exif.ifd1Offset > 0) {
    try {
      thumbnail = extractThumbnail(reader, exif.tiffHeaderOffset, exif.ifd1Offset);
    } catch {
      // Thumbnail extraction is best-effort — don't fail the whole parse
      thumbnail = null;
    }
  }

  return {
    latitude,
    longitude,
    altitude: roundTo(altitude, 2),
    altitudeRef,
    timestamp,
    cameraMake,
    cameraModel,
    heading: roundTo(heading, 2),
    accuracy: roundTo(accuracy, 2),
    filename: file.name,
    thumbnail,
  };
}

// ─── Main: processPhotoFiles ────────────────────────────────────────────────

/**
 * Process multiple photo files, extracting EXIF GPS data from each.
 *
 * Files are processed in parallel for performance. Each result indicates
 * whether EXIF was found and whether GPS data is available.
 *
 * @param files  Array of File objects (JPEG/TIFF)
 * @returns Array of results with file reference, EXIF data, and status
 *
 * @example
 * ```ts
 * const results = await processPhotoFiles(fileInput.files);
 * const geotagged = results.filter(r => r.exif !== null);
 * 
 * ```
 */
export async function processPhotoFiles(
  files: File[]
): Promise<PhotoWithLocation[]> {
  const results: PhotoWithLocation[] = await Promise.all(
    files.map(async (file) => {
      try {
        const exif = await extractEXIFGPS(file);
        return {
          file,
          exif,
          hasEXIF: true,
        };
      } catch (err) {
        const message =
          err instanceof Error ? err.message : 'Unknown error';
        return {
          file,
          exif: null,
          hasEXIF: false,
          error: message,
        };
      }
    })
  );

  return results;
}

// ─── Main: photosToGeoJSON ──────────────────────────────────────────────────

/**
 * Convert geotagged photos to a GeoJSON FeatureCollection of Point features.
 *
 * Only photos with valid EXIF GPS data are included. Each feature's properties
 * contain the full EXIF metadata.
 *
 * @param photos  Processed photo results from `processPhotoFiles`
 * @returns GeoJSON FeatureCollection with Point geometries
 *
 * @example
 * ```ts
 * const geojson = photosToGeoJSON(results);
 * // Use with any GeoJSON-compatible viewer (Leaflet, Mapbox, etc.)
 * ```
 */
export function photosToGeoJSON(
  photos: PhotoWithLocation[]
): GeoJSON.FeatureCollection {
  const features: GeoJSON.Feature[] = [];

  for (const photo of photos) {
    if (!photo.exif) continue;

    const exif = photo.exif;

    const feature: GeoJSON.Feature = {
      type: 'Feature',
      geometry: {
        type: 'Point',
        coordinates: [exif.longitude, exif.latitude, exif.altitude],
      },
      properties: {
        filename: exif.filename,
        altitude: exif.altitude,
        altitudeRef: exif.altitudeRef,
        timestamp: exif.timestamp.toISOString(),
        cameraMake: exif.cameraMake,
        cameraModel: exif.cameraModel,
        heading: exif.heading,
        accuracy: exif.accuracy,
      },
    };

    features.push(feature);
  }

  return {
    type: 'FeatureCollection',
    features,
  };
}

// ─── Main: photosToSurveyPoints ─────────────────────────────────────────────

/**
 * Convert geotagged photos to survey point format with UTM coordinates.
 *
 * GPS coordinates (WGS84 lat/lon) are converted to UTM Zone 37S (Arc 1960)
 * for Kenya. If the photo is outside Kenya, the appropriate UTM zone is
 * determined from the longitude.
 *
 * The conversion uses a simple Transverse Mercator projection formula
 * with WGS84 ellipsoid parameters (a=6378137.0, f=1/298.257223563).
 * Accuracy is within a few metres — sufficient for photo locations.
 *
 * @param photos  Processed photo results from `processPhotoFiles`
 * @returns Array of survey points with UTM easting, northing, elevation
 *
 * @example
 * ```ts
 * const surveyPoints = photosToSurveyPoints(results);
 * for (const sp of surveyPoints) {
 *   } N: ${sp.northing.toFixed(2)} RL: ${sp.elevation.toFixed(2)}`);
 * }
 * ```
 */
export function photosToSurveyPoints(
  photos: PhotoWithLocation[]
): Array<{
  easting: number;
  northing: number;
  elevation: number;
  code: string;
  description: string;
}> {
  const results: Array<{
    easting: number;
    northing: number;
    elevation: number;
    code: string;
    description: string;
  }> = [];

  for (const photo of photos) {
    if (!photo.exif) continue;

    const exif = photo.exif;
    const { easting, northing, zone, hemisphere } = latLonToUTM(
      exif.latitude,
      exif.longitude
    );

    const code = 'PHOTO';
    const dt = exif.timestamp;
    const dateStr = dt
      ? `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, '0')}-${String(dt.getDate()).padStart(2, '0')}`
      : 'unknown-date';
    const timeStr = dt
      ? `${String(dt.getHours()).padStart(2, '0')}:${String(dt.getMinutes()).padStart(2, '0')}:${String(dt.getSeconds()).padStart(2, '0')}`
      : '';

    const description = [
      `Photo: ${exif.filename}`,
      exif.cameraMake ? `Camera: ${exif.cameraMake} ${exif.cameraModel}` : '',
      `Date: ${dateStr} ${timeStr}`,
      `Alt: ${exif.altitude.toFixed(1)}m ${exif.altitudeRef}`,
      exif.heading >= 0 ? `Heading: ${exif.heading.toFixed(1)}°` : '',
      `UTM Zone ${zone}${hemisphere}`,
    ]
      .filter(Boolean)
      .join(' | ');

    results.push({
      easting: roundTo(easting, 3),
      northing: roundTo(northing, 3),
      elevation: roundTo(exif.altitude, 3),
      code,
      description,
    });
  }

  return results;
}

// ─── UTM Conversion (Transverse Mercator Projection) ────────────────────────

/**
 * WGS84 ellipsoid parameters.
 */
const WGS84_A = 6378137.0; // Semi-major axis (metres)
const WGS84_F = 1 / 298.257223563; // Flattening
const WGS84_B = WGS84_A * (1 - WGS84_F); // Semi-minor axis
const WGS84_E2 = 2 * WGS84_F - WGS84_F * WGS84_F; // First eccentricity squared
const WGS84_EP2 =
  WGS84_E2 / (1 - WGS84_E2); // Second eccentricity squared
const UTM_K0 = 0.9996; // Scale factor
const UTM_FE = 500000.0; // False easting (metres)
const UTM_FN = 10000000.0; // False northing for southern hemisphere (metres)

/**
 * Convert latitude/longitude (WGS84) to UTM coordinates.
 *
 * Uses the Transverse Mercator projection formulas from:
 * - "Map Projections — A Working Manual" (Snyder, USGS Professional Paper 1395)
 * - WGS84 Technical Manual (NIMA TR8350.2)
 *
 * For Kenya, defaults to Zone 37S. For other locations, the zone is
 * determined from the longitude: zone = floor((lon + 180) / 6) + 1.
 *
 * @param lat  Latitude in decimal degrees
 * @param lon  Longitude in decimal degrees
 * @returns UTM coordinates with zone and hemisphere info
 */
function latLonToUTM(
  lat: number,
  lon: number
): { easting: number; northing: number; zone: number; hemisphere: 'N' | 'S' } {
  const latRad = (lat * Math.PI) / 180;
  const lonRad = (lon * Math.PI) / 180;

  // Determine UTM zone
  const zone = Math.floor((lon + 180) / 6) + 1;
  const centralMeridianRad = ((zone - 1) * 6 - 180 + 3) * (Math.PI / 180);

  // Northern or southern hemisphere
  const hemisphere = lat >= 0 ? 'N' : 'S';

  const sinPhi = Math.sin(latRad);
  const cosPhi = Math.cos(latRad);
  const tanPhi = Math.tan(latRad);

  const N = WGS84_A / Math.sqrt(1 - WGS84_E2 * sinPhi * sinPhi); // Radius of curvature in prime vertical
  const T = tanPhi * tanPhi; // tan²(φ)
  const C = WGS84_EP2 * cosPhi * cosPhi; // e'²cos²(φ)
  const A = cosPhi * (lonRad - centralMeridianRad); // (λ - λ₀)cos(φ)

  // Meridional arc distance from equator
  const M = computeMeridionalArc(latRad);

  // Transverse Mercator easting
  let easting =
    UTM_K0 *
    N *
    (A +
      (1 - T + C) * (A * A * A) / 6 +
      (5 - 18 * T + T * T + 72 * C - 58 * WGS84_EP2) *
        (A * A * A * A * A) /
        120);

  // Transverse Mercator northing
  let northing =
    UTM_K0 *
    (M +
      N *
        tanPhi *
        ((A * A) / 2 +
          (5 - T + 9 * C + 4 * C * C) * (A * A * A * A) / 24 +
          (61 -
            58 * T +
            T * T +
            600 * C -
            330 * WGS84_EP2) *
            (A * A * A * A * A * A) /
            720));

  easting += UTM_FE;
  if (hemisphere === 'S') {
    northing += UTM_FN;
  }

  return { easting, northing, zone, hemisphere };
}

/**
 * Compute meridional arc distance M(φ) from the equator to latitude φ.
 *
 * Uses the series expansion per Snyder (1987):
 *   M = a[(1 − e²/4 − 3e⁴/64 − 5e⁶/256)φ
 *        − (3e²/8 + 3e⁴/32 + 45e⁶/1024)sin(2φ)
 *        + (15e⁴/256 + 45e⁶/1024)sin(4φ)
 *        − (35e⁶/3072)sin(6φ)]
 */
function computeMeridionalArc(phi: number): number {
  const e2 = WGS84_E2;
  const e4 = e2 * e2;
  const e6 = e4 * e2;

  const m0 = 1 - e2 / 4 - (3 * e4) / 64 - (5 * e6) / 256;
  const m1 = (3 * e2) / 8 + (3 * e4) / 32 + (45 * e6) / 1024;
  const m2 = (15 * e4) / 256 + (45 * e6) / 1024;
  const m3 = (35 * e6) / 3072;

  return WGS84_A * (m0 * phi - m1 * Math.sin(2 * phi) + m2 * Math.sin(4 * phi) - m3 * Math.sin(6 * phi));
}

// ─── Main: isEXIFSupported ──────────────────────────────────────────────────

/**
 * Check if the browser/environment supports EXIF parsing.
 *
 * Requires:
 * - File API (File, Blob, FileReader)
 * - ArrayBuffer support
 *
 * @returns true if EXIF parsing is supported
 */
export function isEXIFSupported(): boolean {
  if (typeof window === 'undefined') return false;
  if (typeof File === 'undefined') return false;
  if (typeof ArrayBuffer === 'undefined') return false;
  if (typeof DataView === 'undefined') return false;
  if (typeof Uint8Array === 'undefined') return false;
  if (typeof btoa === 'undefined') return false;

  return true;
}

// ─── Utility ─────────────────────────────────────────────────────────────────

/**
 * Round a number to a given number of decimal places.
 */
function roundTo(value: number, decimals: number): number {
  if (value === -1) return -1;
  const factor = Math.pow(10, decimals);
  return Math.round(value * factor) / factor;
}

/**
 * Superelevation runout + Grade analysis + Bridge pier alignment + Pipeline as-built
 * Combined module for P2 engineering gaps.
 */

// ─── 1. SUPERELEVATION RUNOUT ───────────────────────────────────────────────

export interface SuperelevationRunoutResult {
  /** Tangent runout length (m) — from normal crown to zero cross-slope */
  tangentRunout: number
  /** Runout length (m) — from zero cross-slope to full superelevation */
  runoutLength: number
  /** Total transition length (m) = tangentRunout + runoutLength */
  totalTransition: number
  /** Cross-slope at each station along the transition */
  profile: Array<{ chainage: number; crossSlope: number; description: string }>
}

/**
 * Compute the superelevation runout profile for a horizontal curve.
 *
 * The transition from normal crown (2% cross-slope) to full superelevation
 * happens in two stages:
 *   1. Tangent runout: rotate outer lane from -2% to 0% (flat)
 *   2. Runout: rotate both lanes from 0% to full superelevation (e.g., 8%)
 *
 * @param designSpeed km/h
 * @param radius Curve radius (m)
 * @param laneWidth Lane width (m)
 * @param numLanes Number of lanes
 * @param normalCrossSlope Normal crown cross-slope (default 2%)
 * @param maxSuperelevation Maximum superelevation (default 8%)
 * @param rateOfChange Rate of change (% per m, default 1/244 per RDM 1.3)
 */
export function computeSuperelevationRunout(
  designSpeed: number,
  radius: number,
  laneWidth: number,
  numLanes: number,
  normalCrossSlope: number = 2,
  maxSuperelevation: number = 8,
  rateOfChange: number = 1 / 244,
): SuperelevationRunoutResult {
  const roadWidth = laneWidth * numLanes
  const fullSuperelevation = Math.min(maxSuperelevation, (designSpeed ** 2 / (127 * radius)) * 100)

  // Tangent runout: time to remove the normal crown from the outer half
  const tangentRunout = (normalCrossSlope / rateOfChange) / 2

  // Runout: from 0% to full superelevation
  const runoutLength = (fullSuperelevation / rateOfChange)

  const totalTransition = tangentRunout + runoutLength

  // Generate profile at 1m intervals
  const profile: Array<{ chainage: number; crossSlope: number; description: string }> = []

  // Tangent runout phase (0 to tangentRunout)
  for (let ch = 0; ch <= tangentRunout + 0.001; ch += 1) {
    const slope = -normalCrossSlope + (normalCrossSlope * ch / tangentRunout)
    profile.push({ chainage: ch, crossSlope: slope, description: 'Tangent runout' })
  }

  // Runout phase (tangentRunout to totalTransition)
  for (let ch = tangentRunout + 1; ch <= totalTransition + 0.001; ch += 1) {
    const slope = (fullSuperelevation * (ch - tangentRunout) / runoutLength)
    profile.push({ chainage: ch, crossSlope: slope, description: 'Runout' })
  }

  // Full superelevation
  profile.push({ chainage: totalTransition + 10, crossSlope: fullSuperelevation, description: 'Full superelevation' })

  return { tangentRunout, runoutLength, totalTransition, profile }
}

// ─── 2. GRADE ANALYSIS ──────────────────────────────────────────────────────

export interface GradeSegment {
  startChainage: number
  endChainage: number
  length: number
  grade: number // %
  isSustained: boolean // > 3% for > 200m
  isCritical: boolean // > 6% (Kenya rural road standard)
  needsClimbingLane: boolean // > 4% for > 1000m (AASHTO)
}

export interface GradeAnalysisResult {
  segments: GradeSegment[]
  maxGrade: number
  maxGradeLocation: number
  totalUphill: number
  totalDownhill: number
  sustainedGradeCount: number
  criticalGradeCount: number
  climbingLaneWarrants: number
  summary: string
}

/**
 * Analyze a vertical grade profile for sustained grades, critical grades,
 * and climbing lane warrants.
 *
 * @param profile Array of { chainage, elevation } points
 * @param thresholdSustained Grade % considered sustained (default 3%)
 * @param thresholdCritical Grade % considered critical (default 6%)
 * @param thresholdClimbingLane Grade % that warrants a climbing lane (default 4%)
 * @param minSustainedLength Min length for sustained grade (default 200m)
 * @param minClimbingLaneLength Min length for climbing lane warrant (default 1000m)
 */
export function analyzeGrades(
  profile: Array<{ chainage: number; elevation: number }>,
  thresholdSustained: number = 3,
  thresholdCritical: number = 6,
  thresholdClimbingLane: number = 4,
  minSustainedLength: number = 200,
  minClimbingLaneLength: number = 1000,
): GradeAnalysisResult {
  const segments: GradeSegment[] = []
  let maxGrade = 0
  let maxGradeLocation = 0
  let totalUphill = 0
  let totalDownhill = 0

  for (let i = 0; i < profile.length - 1; i++) {
    const p1 = profile[i]
    const p2 = profile[i + 1]
    const length = p2.chainage - p1.chainage
    if (length <= 0) continue

    const grade = ((p2.elevation - p1.elevation) / length) * 100
    const absGrade = Math.abs(grade)

    if (absGrade > maxGrade) {
      maxGrade = absGrade
      maxGradeLocation = p1.chainage
    }

    if (grade > 0) totalUphill += Math.abs(p2.elevation - p1.elevation)
    else totalDownhill += Math.abs(p2.elevation - p1.elevation)

    segments.push({
      startChainage: p1.chainage,
      endChainage: p2.chainage,
      length,
      grade,
      isSustained: absGrade >= thresholdSustained && length >= minSustainedLength,
      isCritical: absGrade >= thresholdCritical,
      needsClimbingLane: absGrade >= thresholdClimbingLane && length >= minClimbingLaneLength,
    })
  }

  const sustainedCount = segments.filter(s => s.isSustained).length
  const criticalCount = segments.filter(s => s.isCritical).length
  const climbingLaneCount = segments.filter(s => s.needsClimbingLane).length

  const summary = `Max grade ${maxGrade.toFixed(2)}% at KM ${(maxGradeLocation / 1000).toFixed(3)}. ` +
    `${sustainedCount} sustained grade(s), ${criticalCount} critical grade(s), ${climbingLaneCount} climbing lane warrant(s).`

  return {
    segments,
    maxGrade,
    maxGradeLocation,
    totalUphill,
    totalDownhill,
    sustainedGradeCount: sustainedCount,
    criticalGradeCount: criticalCount,
    climbingLaneWarrants: climbingLaneCount,
    summary,
  }
}

// ─── 3. BRIDGE PIER ALIGNMENT ───────────────────────────────────────────────

export interface PierStake {
  pierNumber: number
  pierChainage: number
  centerE: number
  centerN: number
  /** Perpendicular offsets (left and right of centerline) */
  offsets: Array<{ offset: number; easting: number; northing: number; label: string }>
}

/**
 * Compute bridge pier setting-out data.
 *
 * Given a bridge centerline (alignment) and pier chainages, computes
 * the coordinates of each pier center + perpendicular offsets for
 * pier edges/foundations.
 *
 * @param centerlineBearing Bearing of the bridge centerline (decimal degrees)
 * @param startE, startN Starting coordinates of the centerline
 * @param pierChainages Array of chainages for each pier (metres from start)
 * @param offsetDistances Array of perpendicular offsets to stake (e.g., [-5, 0, 5])
 */
export function computePierAlignment(
  centerlineBearing: number,
  startE: number,
  startN: number,
  pierChainages: number[],
  offsetDistances: number[] = [-5, 0, 5],
): PierStake[] {
  const bearingRad = (centerlineBearing * Math.PI) / 180
  const perpBearingRad = ((centerlineBearing + 90) * Math.PI) / 180

  return pierChainages.map((ch, i) => {
    // Pier center = start + chainage × (sin, cos) of bearing
    const centerE = startE + ch * Math.sin(bearingRad)
    const centerN = startN + ch * Math.cos(bearingRad)

    const offsets = offsetDistances.map(offset => ({
      offset,
      easting: centerE + offset * Math.sin(perpBearingRad),
      northing: centerN + offset * Math.cos(perpBearingRad),
      label: offset === 0 ? 'CL' : offset > 0 ? `R${offset}` : `L${Math.abs(offset)}`,
    }))

    return { pierNumber: i + 1, pierChainage: ch, centerE, centerN, offsets }
  })
}

// ─── 4. PIPELINE AS-BUILT ───────────────────────────────────────────────────

export interface PipelinePoint {
  chainage: number
  invertElevation: number // pipe invert (bottom inside)
  groundElevation: number // ground surface above pipe
  pipeDiameter: number // mm
  jointType?: string
  remarks?: string
}

export interface PipelineAnalysisResult {
  points: Array<{
    chainage: number
    invertElevation: number
    groundElevation: number
    coverDepth: number // ground - invert - diameter/2 (top of pipe to ground)
    coverAdequate: boolean // cover > 0.6m (Kenya standard for shallow pipes)
    grade: number // % grade to next point
    jointType?: string
    remarks?: string
  }>
  minCover: number
  minCoverLocation: number
  inadequateCoverCount: number
  maxGrade: number
  summary: string
}

/**
 * Analyze a pipeline as-built survey.
 *
 * Computes cover depth, grade between joints, and flags inadequate cover.
 *
 * @param points Pipeline survey points (chainage, invert, ground, diameter)
 * @param minCover Minimum cover depth in metres (default 0.6m)
 */
export function analyzePipelineAsBuilt(
  points: PipelinePoint[],
  minCover: number = 0.6,
): PipelineAnalysisResult {
  const analyzed = points.map((p, i) => {
    const topOfPipe = p.invertElevation + p.pipeDiameter / 1000
    const coverDepth = p.groundElevation - topOfPipe

    let grade = 0
    if (i < points.length - 1) {
      const next = points[i + 1]
      const dist = next.chainage - p.chainage
      if (dist > 0) {
        grade = ((next.invertElevation - p.invertElevation) / dist) * 100
      }
    }

    return {
      chainage: p.chainage,
      invertElevation: p.invertElevation,
      groundElevation: p.groundElevation,
      coverDepth: Math.max(0, coverDepth),
      coverAdequate: coverDepth >= minCover,
      grade,
      jointType: p.jointType,
      remarks: p.remarks,
    }
  })

  let minCoverVal = Infinity
  let minCoverLocation = 0
  let inadequateCount = 0
  let maxGrade = 0

  for (const p of analyzed) {
    if (p.coverDepth < minCoverVal) {
      minCoverVal = p.coverDepth
      minCoverLocation = p.chainage
    }
    if (!p.coverAdequate) inadequateCount++
    if (Math.abs(p.grade) > maxGrade) maxGrade = Math.abs(p.grade)
  }

  const summary = `${analyzed.length} pipe points. Min cover: ${minCoverVal.toFixed(3)}m at KM ${(minCoverLocation / 1000).toFixed(3)}. ` +
    `${inadequateCount} point(s) with cover < ${minCover}m. Max grade: ${maxGrade.toFixed(2)}%.`

  return {
    points: analyzed,
    minCover: minCoverVal === Infinity ? 0 : minCoverVal,
    minCoverLocation,
    inadequateCoverCount: inadequateCount,
    maxGrade,
    summary,
  }
}

// METARDU Construction Progress Monitoring Module
// Track construction progress against programme with photo attachments and sign-off workflow

// ─── TYPES ─────────────────────────────────────────────────────────────────────

export interface InspectionCheckpoint {
  id?: string;
  projectId: string;
  chainage?: number;
  gridRef?: string;
  description: string;
  category: 'earthworks' | 'drainage' | 'pavement' | 'structure' | 'utilities' | 'finishing' | 'other';
  plannedDate: string;
  plannedPercentage: number;
  status: 'pending' | 'in_progress' | 'completed' | 'delayed' | 'inspected' | 'approved' | 'rejected';
  actualDate?: string;
  actualPercentage?: number;
  photos?: string[];
  notes?: string;
  inspectedBy?: string;
  approvedBy?: string;
  deviations?: string[];
  timestamp?: string;
}

export interface ProgressSummary {
  totalCheckpoints: number;
  completedCheckpoints: number;
  delayedCheckpoints: number;
  inProgressCheckpoints: number;
  pendingCheckpoints: number;
  overallProgress: number;
  plannedProgress: number;
  variance: number;
  estimatedCompletion: string;
  milestones: {
    name: string;
    planned: string;
    actual?: string;
    status: InspectionCheckpoint['status'];
  }[];
  photoCount: number;
  criticalItems: InspectionCheckpoint[];
}

export interface ProgressChart {
  dates: string[];
  plannedProgress: number[];
  actualProgress: number[];
}

// ─── CONSTANTS ─────────────────────────────────────────────────────────────────

export const CATEGORY_LABELS: Record<InspectionCheckpoint['category'], string> = {
