 */
function initialiseDXFLayers(drawing: Drawing): void {
  initialiseSokDXFLayers(drawing)
}

import { FieldProject, FieldExportOptions } from '@/types/field';

export function projectToGeoJSON(project: FieldProject): GeoJSON.FeatureCollection {
  const features: GeoJSON.Feature[] = [];

  project.beacons.forEach(b => {
    features.push({
      type: 'Feature',
      geometry: { type: 'Point', coordinates: [b.coordinate.lng, b.coordinate.lat] },
      properties: {
        label: b.label,
        beaconType: b.beaconType,
        notes: b.notes ?? '',
        capturedAt: new Date(b.capturedAt).toISOString(),
      },
    });
  });

  project.parcels.forEach(p => {
    if (p.walkPoints.length < 3) return;
    const coords = p.walkPoints.map(wp => [wp.coordinate.lng, wp.coordinate.lat]);
    coords.push(coords[0]); // close ring
    features.push({
      type: 'Feature',
      geometry: { type: 'Polygon', coordinates: [coords] },
      properties: {
        label: p.label,
        areaM2: p.computedAreaM2,
        areaHa: p.computedAreaM2 ? (p.computedAreaM2 / 10000).toFixed(4) : null,
        perimeterM: p.computedPerimeterM,
      },
    });
  });

  return { type: 'FeatureCollection', features };
}

function escapeXml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

export function exportToKML(project: FieldProject): string {
  const lines: string[] = [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<kml xmlns="http://www.opengis.net/kml/2.2">',
    '<Document>',
    `  <name>${escapeXml(project.name)}</name>`,
    '  <description>Field data exported from Metardu</description>',
    '',
    '  <!-- Beacon Styles -->',
    '  <Style id="beaconStyle">',
    '    <IconStyle><color>ff00aaff</color><scale>1.2</scale>',
    '      <Icon><href>http://maps.google.com/mapfiles/kml/paddle/ylw-circle.png</href></Icon>',
    '    </IconStyle>',
    '    <LabelStyle><color>ff00aaff</color><scale>0.9</scale></LabelStyle>',
    '  </Style>',
    '  <Style id="parcelStyle">',
    '    <LineStyle><color>ff00cc44</color><width>2</width></LineStyle>',
    '    <PolyStyle><color>4400cc44</color></PolyStyle>',
    '  </Style>',
    '',
  ];

  // Beacons folder
  if (project.beacons.length > 0) {
    lines.push('  <Folder>');
    lines.push('    <name>Beacons</name>');
    project.beacons.forEach(b => {
      lines.push('    <Placemark>');
      lines.push(`      <name>${escapeXml(b.label)}</name>`);
      lines.push(`      <description>Type: ${b.beaconType}${b.notes ? '\n' + escapeXml(b.notes) : ''}\nAccuracy: ±${b.coordinate.accuracy?.toFixed(1) ?? '?'}m\nCaptured: ${new Date(b.capturedAt).toISOString()}</description>`);
      lines.push('      <styleUrl>#beaconStyle</styleUrl>');
      lines.push(`      <Point><coordinates>${b.coordinate.lng},${b.coordinate.lat},${b.coordinate.altitude ?? 0}</coordinates></Point>`);
      lines.push('    </Placemark>');
    });
    lines.push('  </Folder>');
  }

  // Parcels folder
  if (project.parcels.length > 0) {
    lines.push('  <Folder>');
    lines.push('    <name>Parcels</name>');
    project.parcels.forEach(p => {
      if (p.walkPoints.length < 3) return;
      const coordStr = p.walkPoints
        .map(wp => `${wp.coordinate.lng},${wp.coordinate.lat},${wp.coordinate.altitude ?? 0}`)
        .join(' ');
      // Close the ring
      const first = p.walkPoints[0];
      const closed = coordStr + ` ${first.coordinate.lng},${first.coordinate.lat},${first.coordinate.altitude ?? 0}`;

      lines.push('    <Placemark>');
      lines.push(`      <name>${escapeXml(p.label)}</name>`);
      lines.push(`      <description>Area: ${p.computedAreaM2 ? (p.computedAreaM2 / 10000).toFixed(4) + ' ha' : 'N/A'}\nPerimeter: ${p.computedPerimeterM?.toFixed(1) ?? 'N/A'} m\nPoints: ${p.walkPoints.length}</description>`);
      lines.push('      <styleUrl>#parcelStyle</styleUrl>');
      lines.push('      <Polygon>');
      lines.push('        <outerBoundaryIs><LinearRing>');
      lines.push(`          <coordinates>${closed}</coordinates>`);
      lines.push('        </LinearRing></outerBoundaryIs>');
      lines.push('      </Polygon>');
      lines.push('    </Placemark>');
    });
    lines.push('  </Folder>');
  }

  lines.push('</Document>');
  lines.push('</kml>');
  return lines.join('\n');
}

export function exportToCSV(project: FieldProject): string {
  const rows: string[] = ['Label,Latitude,Longitude,Altitude,Accuracy,Type,Notes,CapturedAt'];
  project.beacons.forEach(b => {
    rows.push([
      b.label,
      b.coordinate.lat.toFixed(8),
      b.coordinate.lng.toFixed(8),
      b.coordinate.altitude?.toFixed(3) ?? '',
      b.coordinate.accuracy?.toFixed(2) ?? '',
      b.beaconType,
      `"${(b.notes ?? '').replace(/"/g, '""')}"`,
      new Date(b.capturedAt).toISOString(),
    ].join(','));
  });
  return rows.join('\n');
}

export function downloadBlob(content: string, filename: string, mime: string): void {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

/**
 * Field Session Manager — orchestrates the field data collection workflow
 *
 * Ties together: instrumentStore (connection) + fieldBookDB (persistence)
 * + liveToleranceChecker (QC) + syncQueue (sync) + stakeout (navigation)
 *
 * Works offline-first: all measurements saved locally, synced when online.
 */

import { useInstrumentStore } from '@/stores/instrumentStore'
import { checkTolerance, type ToleranceCheckResult } from '@/lib/survey/liveToleranceChecker'

// ─── Types ──────────────────────────────────────────────────────────────────

export type SurveyType = 'cadastral' | 'engineering' | 'topographic' | 'control' | 'leveling'
export type InstrumentType = 'total_station' | 'gnss_rover' | 'gnss_static' | 'level'
export type MeasurementMode = 'traverse' | 'radiation' | 'stakeout' | 'leveling' | 'walk'

export interface StationSetup {
  stationName: string
  instrumentHeight: number
  targetHeight: number
  backsightStation?: string
  backsightBearing?: { deg: number; min: number; sec: number }
  temperature?: number
  pressure?: number
  isControlPoint: boolean
  easting?: number
  northing?: number
  elevation?: number
}

export interface FieldMeasurement {
  id: string
  timestamp: number
  pointId: string
  stationFrom: string
  stationTo?: string
  // GNSS observations (from StreamedPoint)
  latitude?: number
  longitude?: number
  elevation?: number
  fixQuality?: string
  satellites?: number
  hdop?: number
  // Total station observations (from GSI parser — future)
  slopeDistance?: number
  horizontalAngle?: { deg: number; min: number; sec: number }
  verticalAngle?: { deg: number; min: number; sec: number }
  // Reduced coordinates
  easting?: number
  northing?: number
  // Metadata
  instrumentType: InstrumentType
  mode: MeasurementMode
  notes?: string
  synced: boolean
}

export interface FieldSessionState {
  projectId: string
  surveyType: SurveyType
  setup: StationSetup | null
  measurements: FieldMeasurement[]
  stakeoutTarget: { easting: number; northing: number; elevation: number } | null
  toleranceStatus: ToleranceCheckResult | null
  isOnline: boolean
  isSyncing: boolean
  pendingSyncCount: number
  lastSyncAt: number | null
}

// ─── Field Session Class ────────────────────────────────────────────────────

class FieldSession {
  private state: FieldSessionState
  private listeners: Set<(state: FieldSessionState) => void> = new Set()

  constructor(projectId: string, surveyType: SurveyType) {
    this.state = {
      projectId,
      surveyType,
      setup: null,
      measurements: [],
      stakeoutTarget: null,
      toleranceStatus: null,
      isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
      isSyncing: false,
      pendingSyncCount: 0,
      lastSyncAt: null,
    }
  }

  subscribe = (listener: (state: FieldSessionState) => void): (() => void) => {
    this.listeners.add(listener)
    return () => { this.listeners.delete(listener) }
  }

  getSnapshot = (): FieldSessionState => this.state

  private setState(updates: Partial<FieldSessionState>) {
    this.state = { ...this.state, ...updates }
    this.listeners.forEach(l => l(this.state))
  }

  // ─── Station Setup ────────────────────────────────────────────────────────

  setupStation(setup: StationSetup) {
    this.setState({ setup })
  }

  isReady(): boolean {
    return this.state.setup !== null
  }

  // ─── Measurement Capture ──────────────────────────────────────────────────

  /**
   * Capture a measurement from the connected instrument.
   * Reads the latest reading from the instrument store and saves it.
   */
  async captureMeasurement(params: {
    pointId: string
    stationTo?: string
    targetHeight?: number
    notes?: string
  }): Promise<FieldMeasurement | null> {
    if (!this.state.setup) {
      return null
    }

    const instrumentStore = useInstrumentStore.getState()
    const latestPoint = instrumentStore.latestPoint

    if (!latestPoint) {
      return null
    }

    // Determine instrument type from the reading source
    const instrumentType: InstrumentType = latestPoint.source === 'nmea'
      ? 'gnss_rover'
      : latestPoint.source === 'gsi'
        ? 'total_station'
        : 'gnss_rover'

    // Build the measurement from the StreamedPoint
    const measurement: FieldMeasurement = {
      id: `obs-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      timestamp: Date.now(),
      pointId: params.pointId,
      stationFrom: this.state.setup.stationName,
      stationTo: params.stationTo,
      // GNSS fields (from StreamedPoint)
      latitude: latestPoint.latitude,
      longitude: latestPoint.longitude,
      elevation: latestPoint.elevation ?? undefined,
      fixQuality: latestPoint.quality != null
        ? (latestPoint.quality >= 4 ? 'fixed' : latestPoint.quality >= 2 ? 'float' : 'single')
        : undefined,
      satellites: latestPoint.satellites,
      hdop: latestPoint.hdop,
      // Reduced coordinates (StreamedPoint has easting/northing)
      easting: latestPoint.easting,
      northing: latestPoint.northing,
      // Metadata
      instrumentType,
      mode: this.state.surveyType === 'leveling' ? 'leveling' : 'traverse',
      notes: params.notes,
      synced: false,
    }

    // Save to IndexedDB (offline-first)
    try {
      const { saveObservation } = await import('@/lib/offline/fieldBookDB')
      await saveObservation({
        id: measurement.id,
        projectId: this.state.projectId,
        surveyType: measurement.mode as 'traverse' | 'leveling' | 'topo' | 'gnss' | 'hydro' | 'mining',
        station: measurement.stationFrom,
        backsight: this.state.setup.backsightStation,
        foresight: measurement.stationTo,
        // GNSS fields
        latitude: measurement.latitude,
        longitude: measurement.longitude,
        // Coordinates
        easting: measurement.easting,
        northing: measurement.northing,
        elevation: measurement.elevation,
        // Metadata
        notes: measurement.notes,
        createdAt: new Date(measurement.timestamp).toISOString(),
        syncedAt: null,
      })
    } catch {
      /* ignore offline save error */
    }

    // Add to session state
    const measurements = [...this.state.measurements, measurement]
    this.setState({ measurements, pendingSyncCount: this.state.pendingSyncCount + 1 })

    // Trigger haptic feedback (mobile)
    this.hapticFeedback()

    return measurement
  }

  /**
   * Trigger haptic feedback on measurement capture.
   */
  private hapticFeedback() {
    if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
      navigator.vibrate(50)
    }
  }

  // ─── Stakeout ─────────────────────────────────────────────────────────────

  activateStakeout(target: { easting: number; northing: number; elevation: number }) {
    this.setState({ stakeoutTarget: target })
  }

  deactivateStakeout() {
    this.setState({ stakeoutTarget: null })
  }

  // ─── Sync ─────────────────────────────────────────────────────────────────

  async syncNow(): Promise<{ synced: number; failed: number }> {
    if (this.state.isSyncing) return { synced: 0, failed: 0 }

    this.setState({ isSyncing: true })

    try {
      const { syncObservations } = await import('@/lib/offline/fieldBookDB')
      const result = await syncObservations()

      const syncedCount = result.synced || 0
      const failedCount = result.failed || 0

      // Mark synced measurements
      const measurements = this.state.measurements.map(m => ({
        ...m,
        synced: m.synced || (syncedCount > 0 && !this.state.measurements.find(x => x.id === m.id && !x.synced)),
      }))

      this.setState({
        isSyncing: false,
        measurements,
        pendingSyncCount: Math.max(0, this.state.pendingSyncCount - syncedCount),
        lastSyncAt: Date.now(),
        isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
      })

      return { synced: syncedCount, failed: failedCount }
    } catch {
      this.setState({ isSyncing: false })
      return { synced: 0, failed: this.state.pendingSyncCount }
    }
  }

  /**
   * Load existing measurements from IndexedDB (for session resume).
   */
  async loadMeasurements() {
    try {
      const { getObservations } = await import('@/lib/offline/fieldBookDB')
      const observations = await getObservations(this.state.projectId)
      const measurements: FieldMeasurement[] = observations.map((obs) => ({
        id: obs.id,
        timestamp: new Date(obs.createdAt).getTime(),
        pointId: '',
        stationFrom: obs.station || '',
        stationTo: obs.foresight || undefined,
        latitude: obs.latitude,
        longitude: obs.longitude,
        elevation: obs.elevation ?? undefined,
        easting: obs.easting,
        northing: obs.northing,
        instrumentType: obs.latitude ? 'gnss_rover' : 'total_station',
        mode: (obs.surveyType as MeasurementMode) || 'traverse',
        notes: obs.notes,
        synced: obs.syncedAt != null,
      }))
      this.setState({
        measurements,
        pendingSyncCount: measurements.filter(m => !m.synced).length,
      })
    } catch {
      /* ignore load error */
    }
  }

  /**
   * Clear all measurements.
   */
  clearMeasurements() {
    this.setState({ measurements: [], pendingSyncCount: 0, toleranceStatus: null })
  }
}

// ─── Session Registry ───────────────────────────────────────────────────────

const sessions = new Map<string, FieldSession>()

export function getFieldSession(projectId: string, surveyType: SurveyType = 'cadastral'): FieldSession {
  const key = `${projectId}:${surveyType}`
  if (!sessions.has(key)) {
    sessions.set(key, new FieldSession(projectId, surveyType))
  }
  return sessions.get(key)!
}

// ─── React Hook ─────────────────────────────────────────────────────────────

export function useFieldSession(options: {
  projectId: string
  surveyType?: SurveyType
}): FieldSession {
  const { projectId, surveyType = 'cadastral' } = options
  return getFieldSession(projectId, surveyType)
}

// pdfjs-dist v5 API — note: GlobalWorkerOptions must be set before getDocument()
import type { PDFDocumentProxy, PDFPageProxy } from 'pdfjs-dist';
import { GeoPDFLayer } from '@/types/field';

let pdfjsLib: typeof import('pdfjs-dist') | null = null;

async function getPDFJS() {
  if (pdfjsLib) return pdfjsLib;
  pdfjsLib = await import('pdfjs-dist');
  // v5: worker is bundled separately — point to the CDN build
  pdfjsLib.GlobalWorkerOptions.workerSrc =
    `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.mjs`;
  return pdfjsLib;
}

export interface RenderedPDF {
  dataUrl: string;   // PNG base64
  widthPx: number;
  heightPx: number;
}

export async function renderPDFPageToDataURL(
  file: File,
  pageNumber = 1,
  scale = 2.0            // 2x for retina — keeps map overlay sharp at zoom
): Promise<RenderedPDF> {
  const lib = await getPDFJS();
  const arrayBuffer = await file.arrayBuffer();
  const pdf: PDFDocumentProxy = await lib.getDocument({ data: arrayBuffer }).promise;
  const page: PDFPageProxy = await pdf.getPage(pageNumber);
  const viewport = page.getViewport({ scale });

  const canvas = document.createElement('canvas');
  canvas.width = viewport.width;
  canvas.height = viewport.height;
  const ctx = canvas.getContext('2d')!;

  const renderParams: import('pdfjs-dist/types/src/display/api').RenderParameters = { canvasContext: ctx, canvas: ctx.canvas, viewport };
  await page.render(renderParams).promise;

  return {
    dataUrl: canvas.toDataURL('image/png'),
    widthPx: viewport.width,
    heightPx: viewport.height,
  };
}

// Build an OpenLayers ImageStatic layer from a GeoPDFLayer with 4 GCPs.
// GCPs define the bounding box: min/max lat/lng of the 4 corners.
// OL imports are done via require() since this function is only called
// inside MapViewer's browser-only useEffect via dynamic import.
export function buildOLGeoPDFLayer(layer: GeoPDFLayer): import('ol/layer/Base').default {
  // Browser-only dynamic require (SSR-safe, see note above).
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { default: ImageLayer } = require('ol/layer/Image') as typeof import('ol/layer/Image');
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { default: ImageStatic } = require('ol/source/ImageStatic') as typeof import('ol/source/ImageStatic');
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { transformExtent } = require('ol/proj') as typeof import('ol/proj');

  const lats = layer.gcps.map((g) => g.lat);
  const lngs = layer.gcps.map((g) => g.lng);
  const extent4326: [number, number, number, number] = [
    Math.min(...lngs),
    Math.min(...lats),
    Math.max(...lngs),
    Math.max(...lats),
  ];
  // Convert extent from WGS84 → EPSG:3857 for OpenLayers
  const extent3857 = transformExtent(extent4326, 'EPSG:4326', 'EPSG:3857');

  return new ImageLayer({
    source: new ImageStatic({
      url: layer.dataUrl,
      imageExtent: extent3857,
      projection: 'EPSG:3857',
    }),
    opacity: 0.75,
    visible: layer.visible,
  });
}

import JSZip from 'jszip';
import db from '@/lib/db';
import { computeDeedPlanGeometry, loadPreAdjustedFromDB } from './deedPlanGeometry';

export async function generateBoundaryShapefile(
  projectId: string
): Promise<Buffer> {
  const projectRes = await db.query<{ name: string; utm_zone: number | null; hemisphere: string | null }>(
    'SELECT name, utm_zone, hemisphere FROM projects WHERE id = $1',
    [projectId]
  );
  const project = projectRes.rows[0];

  if (!project) throw new Error('Project not found');

  // Use Bowditch-adjusted coordinates from traverse engine — single source of truth
  const preAdjusted = await loadPreAdjustedFromDB(projectId);
  const geom = await computeDeedPlanGeometry(projectId, {
    preAdjustedCoordinates: preAdjusted?.stations,
    preAdjustedClosure: preAdjusted?.closure,
  });

  const beacons = geom.stations.map((s, i) => ({
    name: s.station,
    e: s.easting,
    n: s.northing,
    beaconNo: s.beaconNo,
  }));

  const zip = new JSZip();

  const geoJson = {
    type: 'FeatureCollection',
    features: [{
      type: 'Feature',
      geometry: {
        type: 'Polygon',
        coordinates: [beacons.map((b) => [b.e, b.n]).concat([[beacons[0].e, beacons[0].n]])]
      },
      properties: {
        project: project.name,
        area_m2: geom.areaM2,
        area_ha: geom.areaHa,
        surveyed_date: new Date().toISOString().split('T')[0],
        rdm_compliant: true
      }
    }]
  };

  zip.file(`${project.name}_Boundary.geojson`, JSON.stringify(geoJson, null, 2));

  const zone = project.utm_zone || 37;
  const hemisphere = project.hemisphere || 'S';
  const prjContent = `PROJCS["Arc 1960 / UTM zone ${zone}${hemisphere}",GEOGCS["Arc 1960",DATUM["Arc_1960",SPHEROID["Clarke_1880_RGS",6378249.145,293.465]],PRIMEM["Greenwich",0],UNIT["degree",0.0174532925199433]],PROJECTION["Transverse_Mercator"],PARAMETER["latitude_of_origin",0],PARAMETER["central_meridian",${zone * 6 - 183}],PARAMETER["scale_factor",0.9996],PARAMETER["false_easting",500000],PARAMETER["false_northing",${hemisphere === 'S' ? 10000000 : 0}],UNIT["metre",1]]`;

  zip.file(`${project.name}_Boundary.prj`, prjContent);

  const blob = await zip.generateAsync({ type: 'nodebuffer' });
  return Buffer.from(blob);
}

import db from '@/lib/db';
import { coordinateArea } from '@/lib/engine/area';
import { bowditchAdjustment } from '@/lib/engine/traverse';
import { bearingToString } from '@/lib/engine/angles';
import type { NamedPoint2D } from '@/lib/engine/types';
import { computeLineScaleFactor, computeUTMPointScaleFactor } from '@/lib/survey/adapter';
import type { LineScaleFactorResult } from '@/lib/survey/adapter';

export interface TraverseStation {
  station: string;
  bearing: number;
  distance: number;
  beaconNo?: string;
  monument?: string;
  markStatus?: string;
}

export interface AdjustedStation {
  station: string;
  easting: number;
  northing: number;
  beaconNo?: string;
  monument?: string;
  markStatus?: string;
}

export interface BearingLeg {
  from: string;
  to: string;
  bearing: string;
  distance: string;
}

export interface DeedPlanGeometry {
  stations: AdjustedStation[];
  bearingSchedule: BearingLeg[];
  areaM2: number;
  areaHa: number;
  areaAcres: number;
  misclosureMm: number;
  precisionRatio: string;
  closureStatus: 'PASS' | 'FAIL' | 'UNVERIFIED';
  minE: number;
  maxE: number;
  minN: number;
  maxN: number;
  /** Source of the coordinates — tracks whether pre-adjusted or independently computed */
  coordinateSource: 'pre_adjusted' | 'computed';
  /** Line scale factor for each boundary leg (survey engine, Simpson's rule) */
  lineScaleFactors?: Array<{
    from: string;
    to: string;
    scaleFactor: number;
    ppmFromUnity: number;
    gridDistance: number;
    ellipsoidalDistance: number;
  }>;
  /** UTM projection used for scale factor computation */
  projection?: 'UTM36S' | 'UTM37S';
}

/**
 * Pre-adjusted coordinates from an external source (e.g. traverse_coordinates
 * table, or a TraverseComputationResult). When provided to
 * computeDeedPlanGeometry(), the function skips independent Bowditch
 * computation and uses these coordinates directly — guaranteeing 100%
 * consistency with the traverse computation sheet.
 */
export interface PreAdjustedCoordinate {
  station: string;
  easting: number;
  northing: number;
  beaconNo?: string;
  monument?: string;
  markStatus?: string;
}

export interface PreAdjustedClosure {
  misclosureMm: number;
  precisionRatio: number;
}

export interface ComputeDeedPlanGeometryOptions {
  /**
   * Pre-adjusted traverse coordinates from an authoritative source.
   * When provided, computeDeedPlanGeometry() will use these coordinates
   * directly instead of recomputing from raw field book entries.
   * This ensures single-source-of-truth consistency with the traverse
   * computation sheet and all other output documents.
   */
  preAdjustedCoordinates?: PreAdjustedCoordinate[];
  /** Closure metrics corresponding to the pre-adjusted coordinates */
  preAdjustedClosure?: PreAdjustedClosure;
}

function parseBearing(raw: string | number): number {
  if (typeof raw === 'number') return raw;
  const dmsMatch = String(raw).match(/(\d+)[°\-\s](\d+)['\-\s](\d+\.?\d*)/);
  if (dmsMatch) {
    const [, d, m, s] = dmsMatch.map(Number);
    return d + m / 60 + s / 3600;
  }
  return parseFloat(String(raw)) || 0;
}


export async function computeDeedPlanGeometry(
  projectId: string,
  options?: ComputeDeedPlanGeometryOptions
): Promise<DeedPlanGeometry> {
  // ── Path A: Use pre-adjusted coordinates from an authoritative source ──
  // When the caller has already computed adjusted traverse coordinates (e.g.
  // from the traverse computation sheet or the traverse_coordinates table),
  // use them directly. This guarantees 100% consistency between all output
  // documents — the deed plan, computation sheet, Form C22, and DXF all
  // derive from the same adjusted coordinates.
  if (options?.preAdjustedCoordinates && options.preAdjustedCoordinates.length >= 3) {
    return buildFromPreAdjusted(options.preAdjustedCoordinates, options.preAdjustedClosure);
  }

  // ── Path B: Try to load pre-adjusted coordinates from the DB ──
  // If the project has a saved traverse with adjusted coordinates in the
  // traverse_coordinates table, use those instead of recomputing.
  const savedCoords = await loadPreAdjustedFromDB(projectId);
  if (savedCoords) {
    return buildFromPreAdjusted(savedCoords.stations, savedCoords.closure);
  }

  // ── Path C: Compute from raw field book entries (fallback) ──
  return computeFromFieldBook(projectId);
}

/**
 * Build DeedPlanGeometry from pre-adjusted coordinates.
 * Bearings and distances are RECOMPUTED from the adjusted coordinates to
 * ensure the bearing schedule is consistent with the coordinate schedule.
 */
function buildFromPreAdjusted(
  coords: PreAdjustedCoordinate[],
  closure?: PreAdjustedClosure
): DeedPlanGeometry {
  const adjusted: AdjustedStation[] = coords.map(c => ({
    station: c.station,
    easting: c.easting,
    northing: c.northing,
    beaconNo: c.beaconNo,
    monument: c.monument,
    markStatus: c.markStatus,
  }));

  // Compute area from adjusted coordinates (Shoelace formula)
  const pts = adjusted.map((s) => ({ easting: s.easting, northing: s.northing }));
  const areaResult = coordinateArea(pts);

  // Bearing schedule recomputed from adjusted positions — ensures consistency
  // Now includes grid scale factors from the survey engine (Simpson's rule)
  const projection: 'UTM36S' | 'UTM37S' = 'UTM37S'; // Default for Kenya
  const bearingSchedule: BearingLeg[] = adjusted.map((st, i) => {
    const next = adjusted[(i + 1) % adjusted.length];
    const dE = next.easting - st.easting;
    const dN = next.northing - st.northing;
    let brg = (Math.atan2(dE, dN) * 180) / Math.PI;
    if (brg < 0) brg += 360;
    const dist = Math.sqrt(dE ** 2 + dN ** 2);
    return {
      from: st.station,
      to: next.station,
      bearing: bearingToString(brg),
      distance: dist.toFixed(3),
    };
  });

  // Compute line scale factors using the survey engine's Simpson's rule
  const lineScaleFactors = adjusted.map((st, i) => {
    const next = adjusted[(i + 1) % adjusted.length];
    try {
      const sfResult = computeLineScaleFactor(
        st.easting, st.northing,
        next.easting, next.northing,
        projection
      );
      return {
        from: st.station,
        to: next.station,
        scaleFactor: sfResult.lineScaleFactor,
        ppmFromUnity: sfResult.ppmCorrection,
        gridDistance: sfResult.gridDistance,
        ellipsoidalDistance: sfResult.ellipsoidalDistance,
      };
    } catch {
      return {
        from: st.station,
        to: next.station,
        scaleFactor: 1.0,
        ppmFromUnity: 0,
        gridDistance: 0,
        ellipsoidalDistance: 0,
      };
    }
  });

  const eastings = adjusted.map((s) => s.easting);
  const northings = adjusted.map((s) => s.northing);

  const misclosureMm = closure?.misclosureMm ?? 0;
  const ratio = closure?.precisionRatio ?? Infinity;
  const precisionRatio = ratio === Infinity ? '1:∞' : `1:${Math.round(ratio).toLocaleString()}`;
  const closureStatus: 'PASS' | 'FAIL' | 'UNVERIFIED' =
    ratio >= 5000 ? 'PASS' : ratio > 0 && ratio < Infinity ? 'FAIL' : 'UNVERIFIED';

  return {
    stations: adjusted,
    bearingSchedule,
    areaM2: areaResult.areaSqm,
    areaHa: areaResult.areaHa,
    areaAcres: areaResult.areaAcres,
    misclosureMm,
    precisionRatio,
    closureStatus,
    minE: Math.min(...eastings),
    maxE: Math.max(...eastings),
    minN: Math.min(...northings),
    maxN: Math.max(...northings),
    coordinateSource: 'pre_adjusted',
    lineScaleFactors,
    projection,
  };
}

/**
 * Attempt to load pre-adjusted coordinates from the traverse_coordinates
 * table. Returns null if no saved traverse exists.
 *
 * Also queries the field book entries for beacon descriptions (monument type,
 * mark status, beacon number) so that the DeedPlanGeometry includes rich
 * beacon metadata — matching the behaviour of the external helper in
 * deedPlan.ts.
 */
export async function loadPreAdjustedFromDB(
  projectId: string
): Promise<{ stations: PreAdjustedCoordinate[]; closure: PreAdjustedClosure } | null> {
  try {
    // Find the most recent traverse for this project via parcels
    const traverseRes = await db.query<{ id: string; linear_misclosure: number | null; precision_ratio: number | null }>(
      `SELECT pt.id, pt.linear_misclosure, pt.precision_ratio
       FROM parcel_traverses pt
       JOIN parcels p ON p.id = pt.parcel_id
       JOIN blocks b ON b.id = p.block_id
       WHERE b.project_id = $1
       ORDER BY pt.created_at DESC LIMIT 1`,
      [projectId]
    );

    if (traverseRes.rows.length === 0) return null;

    const traverse = traverseRes.rows[0];
    const traverseId = traverse.id;

    const coordsRes = await db.query(
      'SELECT station, easting, northing, rl FROM traverse_coordinates WHERE traverse_id = $1 ORDER BY station',
      [traverseId]
    );

    if (coordsRes.rows.length < 3) return null;

    // Also try to get beacon info from field book entries for richer metadata
    const beaconLookup = new Map<string, { beaconNo: string; monument: string; markStatus: string }>();
    try {
      const fbRes = await db.query<{ station: string; raw_data: Record<string, unknown> | null }>(
        'SELECT station, raw_data FROM project_fieldbook_entries WHERE project_id = $1 ORDER BY row_index ASC',
        [projectId]
      );
      for (const row of fbRes.rows) {
        const raw = row.raw_data as Record<string, unknown> | null;
        if (row.station && raw) {
          beaconLookup.set(String(row.station), {
            beaconNo: String(raw.beacon_no ?? ''),
            monument: String(raw.monument_type ?? ''),
            markStatus: String(raw.mark_status ?? raw.monument_status ?? 'FOUND'),
          });
        }
      }
    } catch {
      // Field book table may not exist — proceed with defaults
    }

    const stations: PreAdjustedCoordinate[] = coordsRes.rows.map((c: Record<string, unknown>) => {
      const stn = String(c.station);
      const beacon = beaconLookup.get(stn);
      return {
        station: stn,
        easting: parseFloat(String(c.easting)),
        northing: parseFloat(String(c.northing)),
        beaconNo: beacon?.beaconNo || stn,
        monument: beacon?.monument || 'psc found',
        markStatus: beacon?.markStatus || 'FOUND',
      };
    });

    const closure: PreAdjustedClosure = {
      misclosureMm: parseFloat(String(traverse.linear_misclosure ?? 0)) * 1000,
      precisionRatio: parseFloat(String(traverse.precision_ratio ?? 0)) || Infinity,
    };

    return { stations, closure };
  } catch {
    // Table may not exist in all deployments — fall back gracefully
    return null;
  }
}

/**
 * Compute DeedPlanGeometry from raw field book entries using Bowditch
 * adjustment. This is the fallback path when no pre-adjusted coordinates
 * are available.
 */
async function computeFromFieldBook(projectId: string): Promise<DeedPlanGeometry> {
  const entriesRes = await db.query<{ row_index: number; station: string; raw_data: Record<string, unknown> }>(
    'SELECT row_index, station, raw_data FROM project_fieldbook_entries WHERE project_id = $1 ORDER BY row_index ASC',
    [projectId]
  );
  const entries = entriesRes.rows;

  if (!entries || entries.length < 3) {
    throw new Error('Deed Plan requires at least 3 traverse stations. Add observations in the Field Book panel.');
  }

  const projectRes = await db.query<{ boundary_data: Record<string, unknown> | null; utm_zone: number | null; hemisphere: string | null }>(
    'SELECT boundary_data, utm_zone, hemisphere FROM projects WHERE id = $1',
    [projectId]
  );
  const project = projectRes.rows[0];

  const legs: TraverseStation[] = entries
    .map((e: { row_index: number; station: string; raw_data: Record<string, unknown> }) => ({
      station: String(e.station ?? e.raw_data?.station ?? ''),
      bearing: parseBearing(String(e.raw_data?.bearing ?? e.raw_data?.bs ?? 0)),
      distance: parseFloat(String(e.raw_data?.distance ?? e.raw_data?.hd ?? '0')) || 0,
      beaconNo: String(e.raw_data?.beacon_no ?? ''),
      monument: String(e.raw_data?.monument_type ?? ''),
      markStatus: String(e.raw_data?.mark_status ?? e.raw_data?.monument_status ?? 'FOUND'),
    }))
    .filter((l) => l.distance > 0);

  if (legs.length < 3) {
    throw new Error('Insufficient traverse data. Ensure bearing and distance are entered for each leg.');
  }

  // Use boundary seed as starting coordinate
  const seed = project?.boundary_data as { startE?: number; startN?: number } | null;
  const startE = seed?.startE ?? 0;
  const startN = seed?.startN ?? 0;

  // Build the traverse input for the engine's Bowditch adjustment
  // This ensures the deed plan uses the SAME adjusted coordinates as the
  // traverse computation sheet — single source of truth for all outputs.
  // Source: Ghilani & Wolf Ch.12 — Bowditch (Compass) Rule
  const startPoint: NamedPoint2D = { name: legs[0].station, easting: startE, northing: startN };
  const traversePoints: NamedPoint2D[] = legs.map(l => ({ name: l.station, easting: 0, northing: 0 }));

  const traverseResult = bowditchAdjustment({
    points: [startPoint, ...traversePoints],
    distances: legs.map(l => l.distance),
    bearings: legs.map(l => l.bearing),
    closingPoint: { easting: startE, northing: startN },
  });

  // Extract adjusted coordinates from the engine result
  const adjusted: AdjustedStation[] = traverseResult.legs.map((leg, i) => ({
    station: legs[i].station,
    easting: leg.adjEasting,
    northing: leg.adjNorthing,
    beaconNo: legs[i].beaconNo,
    monument: legs[i].monument,
    markStatus: legs[i].markStatus,
  }));

  // Compute area from adjusted coordinates (Shoelace formula)
  const pts = adjusted.map((s) => ({ easting: s.easting, northing: s.northing }));
  const areaResult = coordinateArea(pts);
  const areaM2 = areaResult.areaSqm;
  const areaHa = areaResult.areaHa;
  const areaAcres = areaResult.areaAcres;

  // Closure metrics from the engine result
  const misclosureMm = traverseResult.linearError * 1000;
  const ratio = traverseResult.precisionRatio;
  const precisionRatio = `1:${Math.round(ratio).toLocaleString()}`;
  const closureStatus: 'PASS' | 'FAIL' | 'UNVERIFIED' =
    ratio >= 5000 ? 'PASS' : ratio > 0 ? 'FAIL' : 'UNVERIFIED';

  // Bearing schedule from adjusted coordinates — bearings are recomputed from
  // the adjusted positions to ensure consistency with the coordinate schedule
  // Now includes grid scale factors from the survey engine (Simpson's rule)
  const projection: 'UTM36S' | 'UTM37S' = 'UTM37S'; // Default for Kenya
  const bearingSchedule: BearingLeg[] = adjusted.map((st, i) => {
    const next = adjusted[(i + 1) % adjusted.length];
    const dE = next.easting - st.easting;
    const dN = next.northing - st.northing;
    let brg = (Math.atan2(dE, dN) * 180) / Math.PI;
    if (brg < 0) brg += 360;
    const dist = Math.sqrt(dE ** 2 + dN ** 2);
    return {
      from: st.station,
      to: next.station,
      bearing: bearingToString(brg),
      distance: dist.toFixed(3),
    };
  });

  // Compute line scale factors using the survey engine's Simpson's rule
  const lineScaleFactors = adjusted.map((st, i) => {
    const next = adjusted[(i + 1) % adjusted.length];
    try {
      const sfResult = computeLineScaleFactor(
        st.easting, st.northing,
        next.easting, next.northing,
        projection
      );
      return {
        from: st.station,
        to: next.station,
        scaleFactor: sfResult.lineScaleFactor,
        ppmFromUnity: sfResult.ppmCorrection,
        gridDistance: sfResult.gridDistance,
        ellipsoidalDistance: sfResult.ellipsoidalDistance,
      };
    } catch {
      return {
        from: st.station,
        to: next.station,
        scaleFactor: 1.0,
        ppmFromUnity: 0,
        gridDistance: 0,
        ellipsoidalDistance: 0,
      };
    }
  });

  const eastings = adjusted.map((s) => s.easting);
  const northings = adjusted.map((s) => s.northing);

  return {
    stations: adjusted,
    bearingSchedule,
    areaM2,
    areaHa,
    areaAcres,
    misclosureMm,
    precisionRatio,
    closureStatus,
    minE: Math.min(...eastings),
    maxE: Math.max(...eastings),
    minN: Math.min(...northings),
    maxN: Math.max(...northings),
    coordinateSource: 'computed',
    lineScaleFactors,
    projection,
  };
}

import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { addPageFooter } from './pdfTitleBlock';
import { shoelaceArea as computePolygonArea } from '@/lib/engine/area';

// ---------------------------------------------------------------------------
// Input interface
// ---------------------------------------------------------------------------

export interface FormC22Input {
  projectName: string;
  lrNumber: string;
  parcelNumber: string;
  county: string;
  division: string;
  district: string;
  locality: string;
  surveyType: string;
  surveyorName: string;
  iskNumber: string;
  firmName: string;
  referenceNumber: string;
  revision: string;
  stations: Array<{
    label: string;
    observedBearing: number; // degrees
    observedDistance: number; // metres
    easting: number;
    northing: number;
    adjustedEasting: number;
    adjustedNorthing: number;
    departureRaw: number;
    latitudeRaw: number;
    departureCorrection: number;
    latitudeCorrection: number;
  }>;
  angularMisclosureSec: number;
  angularToleranceSec: number;
  linearMisclosureM: number;
  perimeterM: number;
  precisionRatio: number;
  areaM2: number;
  areaHa: number;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Convert decimal degrees to DMS string e.g. 45°30'15.2" */
function decimalToDMS(deg: number): string {
  const absolute = Math.abs(deg);
  const d = Math.floor(absolute);
  const minFloat = (absolute - d) * 60;
  const m = Math.floor(minFloat);
  const s = (minFloat - m) * 60;
  return `${d}°${String(m).padStart(2, '0')}'${s.toFixed(1)}"`;
}

/** Convert decimal degrees to WCB (Whole Circle Bearing) quadrant string e.g. N 45°30'15.2" E */
function decimalToWCB(deg: number): string {
  const normalised = ((deg % 360) + 360) % 360;
  if (normalised <= 90) {
    return `N ${decimalToDMS(normalised)} E`;
  } else if (normalised <= 180) {
    return `S ${decimalToDMS(180 - normalised)} E`;
  } else if (normalised <= 270) {
    return `S ${decimalToDMS(normalised - 180)} W`;
  } else {
    return `N ${decimalToDMS(360 - normalised)} W`;
  }
}

// computeShoelaceArea removed — now uses canonical shoelaceArea from @/lib/engine/area
// Call sites map adjustedEasting/adjustedNorthing → easting/northing.

/** Format a precision ratio like "1:12500" */
function formatPrecisionRatio(ratio: number): string {
  if (ratio <= 0 || !isFinite(ratio)) return '—';
  return `1:${Math.round(ratio).toLocaleString()}`;
}

// ---------------------------------------------------------------------------
// Page dimensions — A3 landscape
// ---------------------------------------------------------------------------

const PAGE_W = 420;
const PAGE_H = 297;
const MARGIN = 10;
const CONTENT_W = PAGE_W - MARGIN * 2;

// ---------------------------------------------------------------------------
// Main generator
// ---------------------------------------------------------------------------

export function generateFormC22Pdf(input: FormC22Input): Buffer {
  const doc = new jsPDF({
    orientation: 'landscape',
    unit: 'mm',
    format: 'a3',
  });

  const today = new Date().toLocaleDateString('en-KE', {
    day: '2-digit',
    month: 'long',
    year: 'numeric',
  });

  // Track pages for numbering — we add footer at the end for all pages
  let currentPage = 1;
  const totalPages = estimateTotalPages(input.stations.length);

  // =========================================================================
  // PAGE 1 — Header + Info + Tables 1 & 2
  // =========================================================================
  drawPageHeader(doc, input, today);
  drawProjectInfoBlock(doc, input, today);
  drawSurveyorInfoBlock(doc, input);

  let y = 56;

  // --- Table 1: Observed Bearings and Distances ---
  y = drawObservedBearingsTable(doc, input, y);
  y += 4;

  // --- Table 2: Traverse Adjustment ---
  y = drawTraverseAdjustmentTable(doc, input, y);
  y += 4;

  // Check if we need a new page for Table 3 & 4
  if (y > PAGE_H - 100) {
    addPageFooter(doc, currentPage, totalPages, input.projectName);
    doc.addPage();
    currentPage++;
    y = MARGIN;
  }

  // --- Table 3: Area Computation ---
  y = drawAreaComputationTable(doc, input, y);
  y += 4;

  // --- Table 4: Closure Summary ---
  y = drawClosureSummaryTable(doc, input, y);
  y += 6;

  // Check if we need a new page for certificate
  if (y > PAGE_H - 70) {
    addPageFooter(doc, currentPage, totalPages, input.projectName);
    doc.addPage();
    currentPage++;
    y = MARGIN;
  }

  // --- Surveyor's Certificate ---
  drawSurveyorCertificate(doc, input, y, today);

  // --- Professional Disclaimer ---
  drawDisclaimer(doc);

  // Finalize page footers on all pages
  const actualTotal = doc.getNumberOfPages();
  for (let p = 1; p <= actualTotal; p++) {
    doc.setPage(p);
    // Remove any previously drawn footer on this page by overwriting with white
    // Actually, addPageFooter draws a line + text; we just call it for every page
    addPageFooter(doc, p, actualTotal, input.projectName);
  }

  return Buffer.from(doc.output('arraybuffer'));
}

// ---------------------------------------------------------------------------
// Estimate page count
// ---------------------------------------------------------------------------

function estimateTotalPages(stationCount: number): number {
  // Rough heuristic: up to ~15 stations fit on 1 page, more needs 2
  if (stationCount <= 15) return 1;
  if (stationCount <= 30) return 2;
  return 3;
}

// ---------------------------------------------------------------------------
// Draw the Republic of Kenya / DoLS header
// ---------------------------------------------------------------------------

function drawPageHeader(doc: jsPDF, input: FormC22Input, _today: string): void {
  const cx = PAGE_W / 2;

  doc.setDrawColor(0, 0, 0);
  doc.setLineWidth(1.0);
  doc.rect(MARGIN, MARGIN, CONTENT_W, 36);

  // Double border effect
  doc.setLineWidth(0.3);
  doc.rect(MARGIN + 1.5, MARGIN + 1.5, CONTENT_W - 3, 33);

  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 0, 0);
  doc.text('REPUBLIC OF KENYA', cx, MARGIN + 10, { align: 'center' });

  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(40, 40, 40);
