  '88': { field: 'instrument_height', description: 'Instrument height (HI)',      divisor: 1000 },
};

// String-type word indices (don't parse as numeric)
const STRING_WORD_INDICES = new Set([
  '11', '12', '13', '18', '19',
  '41', '42', '43', '44', '45', '46', '47', '48', '49',
  '71', '72', '73', '74', '75', '76', '77', '78', '79',
]);

// ─── Types ────────────────────────────────────────────────────────────────────

export interface GSIObservation {
  lineNumber: number;
  pointId: string;
  hzAngle?: number;       // degrees (converted from gon if needed)
  vAngle?: number;        // degrees
  slopeDist?: number;     // metres
  hzDist?: number;        // metres
  heightDiff?: number;    // metres
  easting?: number;
  northing?: number;
  rl?: number;
  instrumentHeight?: number;
  targetHeight?: number;
  featureCode?: string;
  prismConstant?: number;
  face?: 'FL' | 'FR';    // detected face
  raw: Record<string, number | string>;
}

export interface GSIFacePair {
  pointId: string;
  fl: GSIObservation;
  fr: GSIObservation;
  meanHz: number;         // degrees
  meanV: number;          // degrees
  meanSD: number;         // metres
  collimation: number;    // arc-seconds — horizontal collimation error
  indexError: number;     // arc-seconds — vertical index error
}

export interface GSIParseResult extends ParseResult {
  observations: GSIObservation[];
  facePairs: GSIFacePair[];
  stationSetups: GSIStationSetup[];
  format: 'gsi';
  gsiVersion: 8 | 16;
  angleUnit: 'gon' | 'deg' | 'dms';
}

export interface GSIStationSetup {
  stationId: string;
  instrumentHeight: number;
  backsightId?: string;
  observations: GSIObservation[];
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

/** Detect GSI format version (8 or 16) from content. */
function detectGSIVersion(content: string): 8 | 16 {
  const firstLine = content.trim().split('\n')[0] ?? '';
  // GSI-16 has 24-char word blocks; GSI-8 has 16-char blocks
  // After the leading '*', check if the first word block is ≥ 24 chars
  const stripped = firstLine.startsWith('*') ? firstLine.slice(1) : firstLine;
  // Word blocks separated by spaces in some instruments, or contiguous
  // Heuristic: if the block after WI has > 16 chars of data, it's GSI-16
  if (stripped.length > 0) {
    // Check if the line has space-delimited words
    const words = stripped.split(/\s+/).filter(Boolean);
    if (words.length > 0 && words[0].length >= 23) return 16;
    // Check for contiguous: if total length / word count suggests 24-char blocks
    if (words.length > 1 && words[0].length >= 15 && words[0].length <= 16) return 8;
    if (words.length > 1 && words[0].length >= 23) return 16;
  }
  return 8;
}

/** Parse a single GSI word block into a field name and value. */
function parseWord(word: string, gsiVersion: 8 | 16): {
  wi: string;
  field: string | null;
  value: number | string;
  sign: number;
} | null {
  if (word.length < (gsiVersion === 16 ? 23 : 15)) return null;

  const wi = word.slice(0, 2);
  const def = GSI_WORD_INDEX[wi];
  if (!def) return null;

  // Sign/decimal indicator at position 5 (0-indexed: pos 4 for GSI-8, pos 6 for GSI-16)
  const signPos = gsiVersion === 16 ? 6 : 5;
  const signChar = word[signPos] ?? '+'
  const sign = signChar === '-' ? -1 : 1;

  // Data portion: last N characters
  const dataStart = gsiVersion === 16 ? 7 : 6;
  const dataStr = word.slice(dataStart).replace(/^0+/, '') || '0';

  if (STRING_WORD_INDICES.has(wi)) {
    // String value — strip leading zeros and return as string
    const strVal = word.slice(dataStart).replace(/^0+/, '').trim() || word.slice(dataStart).trim();
    return { wi, field: def.field, value: strVal, sign: 1 };
  }

  // Numeric value
  const rawNum = parseInt(dataStr, 10);
  if (isNaN(rawNum)) return null;

  const value = (sign * rawNum) / def.divisor;
  return { wi, field: def.field, value, sign };
}

/** Convert gon to degrees. */
function gonToDeg(gon: number): number {
  return gon * 360 / 400;
}

/** Detect if the angles are in gon (gradian) or degrees. */
function detectAngleUnit(observations: GSIObservation[]): 'gon' | 'deg' | 'dms' {
  // Heuristic: if any horizontal angle > 360 but ≤ 400, it's gon
  for (const obs of observations) {
    if (obs.hzAngle !== undefined && obs.hzAngle > 360 && obs.hzAngle <= 400) return 'gon';
    if (obs.vAngle !== undefined && obs.vAngle > 360 && obs.vAngle <= 400) return 'gon';
  }
  return 'deg'; // default to degrees
}

/** Detect face from vertical angle (FL: 0–200g or 0–180°, FR: 200–400g or 180–360°). */
function detectFace(vAngle: number | undefined, angleUnit: 'gon' | 'deg' | 'dms'): 'FL' | 'FR' | undefined {
  if (vAngle === undefined) return undefined;
  if (angleUnit === 'gon') {
    return vAngle < 200 ? 'FL' : 'FR';
  }
  return vAngle < 180 ? 'FL' : 'FR';
}

/** Mean of two angles, handling wraparound. */
function meanAngle(a: number, b: number, fullCircle: number): number {
  // For horizontal angle mean from FL/FR: mean = (FL + FR ± 180°) / 2
  // Standard face reduction
  let diff = b - a;
  if (diff > fullCircle / 2) diff -= fullCircle;
  if (diff < -fullCircle / 2) diff += fullCircle;
  let mean = a + diff / 2;
  if (mean < 0) mean += fullCircle;
  if (mean >= fullCircle) mean -= fullCircle;
  return mean;
}

// ─── Main Parser ──────────────────────────────────────────────────────────────

function parseGSIContent(content: string): GSIParseResult {
  const lines = content.trim().split('\n');
  const gsiVersion = detectGSIVersion(content);
  const observations: GSIObservation[] = [];
  const warnings: string[] = [];
  const points: ParsedPoint[] = [];

  const wordLength = gsiVersion === 16 ? 24 : 16;

  for (let lineIdx = 0; lineIdx < lines.length; lineIdx++) {
    const line = lines[lineIdx].trim();
    if (!line || !line.startsWith('*')) continue;

    // Strip leading '*' and split into word blocks
    const stripped = line.slice(1);

    // Words can be space-separated or contiguous
    let words: string[];
    if (stripped.includes(' ')) {
      words = stripped.split(/\s+/).filter(Boolean);
    } else {
      // Contiguous: split by word length
      words = [];
      for (let i = 0; i < stripped.length; i += wordLength) {
        const w = stripped.slice(i, i + wordLength);
        if (w.length >= wordLength - 2) words.push(w);
      }
    }

    const obs: GSIObservation = {
      lineNumber: lineIdx + 1,
      pointId: '',
      raw: {},
    };

    for (const word of words) {
      const parsed = parseWord(word, gsiVersion);
      if (!parsed || !parsed.field) continue;

      obs.raw[parsed.wi] = parsed.value;

      switch (parsed.field) {
        case 'point_id':
          obs.pointId = String(parsed.value);
          break;
        case 'hz_angle':
        case 'hz_angle_avg':
          obs.hzAngle = parsed.value as number;
          break;
        case 'v_angle':
        case 'v_angle_avg':
          obs.vAngle = parsed.value as number;
          break;
        case 'slope_dist':
          obs.slopeDist = parsed.value as number;
          break;
        case 'hz_dist':
          obs.hzDist = parsed.value as number;
          break;
        case 'height_diff':
          obs.heightDiff = parsed.value as number;
          break;
        case 'easting':
          obs.easting = parsed.value as number;
          break;
        case 'northing':
          obs.northing = parsed.value as number;
          break;
        case 'rl':
          obs.rl = parsed.value as number;
          break;
        case 'instrument_height':
          obs.instrumentHeight = parsed.value as number;
          break;
        case 'target_height':
          obs.targetHeight = parsed.value as number;
          break;
        case 'feature_code':
          obs.featureCode = String(parsed.value);
          break;
        case 'prism_constant':
          obs.prismConstant = parsed.value as number;
          break;
      }
    }

    if (obs.pointId) {
      observations.push(obs);
    } else {
      warnings.push(`Line ${lineIdx + 1}: No point ID found — skipped`);
    }
  }

  // Detect angle unit and convert if necessary
  const angleUnit = detectAngleUnit(observations);
  if (angleUnit === 'gon') {
    for (const obs of observations) {
      if (obs.hzAngle !== undefined) obs.hzAngle = gonToDeg(obs.hzAngle);
      if (obs.vAngle !== undefined) obs.vAngle = gonToDeg(obs.vAngle);
    }
  }

  // Detect faces
  for (const obs of observations) {
    obs.face = detectFace(obs.vAngle, angleUnit);
  }

  // Build face pairs (group by point ID, pair FL with FR)
  const facePairs = buildFacePairs(observations, angleUnit);

  // Build station setups (group by instrument height changes)
  const stationSetups = buildStationSetups(observations);

  // Build ParsedPoint array for the universal importer
  for (const obs of observations) {
    const pt: ParsedPoint = { raw: obs.raw as Record<string, unknown> };
    if (obs.pointId) (pt as Record<string, unknown>)['point_no'] = obs.pointId;
    if (obs.easting !== undefined) (pt as Record<string, unknown>)['easting'] = obs.easting;
    if (obs.northing !== undefined) (pt as Record<string, unknown>)['northing'] = obs.northing;
    if (obs.rl !== undefined) (pt as Record<string, unknown>)['rl'] = obs.rl;
    if (obs.hzAngle !== undefined) (pt as Record<string, unknown>)['bearing'] = obs.hzAngle;
    if (obs.slopeDist !== undefined) (pt as Record<string, unknown>)['distance'] = obs.slopeDist;
    if (obs.hzDist !== undefined) (pt as Record<string, unknown>)['distance'] = obs.hzDist;
    if (obs.featureCode) (pt as Record<string, unknown>)['feature_code'] = obs.featureCode;
    if (obs.targetHeight !== undefined) (pt as Record<string, unknown>)['target_height'] = obs.targetHeight;
    if (obs.instrumentHeight !== undefined) (pt as Record<string, unknown>)['instrument_height'] = obs.instrumentHeight;
    points.push(pt);
  }

  return {
    format: 'gsi',
    points,
    warnings,
    observations,
    facePairs,
    stationSetups,
    gsiVersion,
    angleUnit,
  };
}

// ─── Face Pairing ─────────────────────────────────────────────────────────────

function buildFacePairs(observations: GSIObservation[], angleUnit: 'gon' | 'deg' | 'dms'): GSIFacePair[] {
  const pairs: GSIFacePair[] = [];

  // Group observations by point ID
  const byPointId = new Map<string, GSIObservation[]>();
  for (const obs of observations) {
    if (!obs.pointId || obs.face === undefined) continue;
    const existing = byPointId.get(obs.pointId) ?? [];
    existing.push(obs);
    byPointId.set(obs.pointId, existing);
  }

  for (const [pointId, obsList] of Array.from(byPointId.entries())) {
    const flObs = obsList.filter(o => o.face === 'FL');
    const frObs = obsList.filter(o => o.face === 'FR');

    // Pair FL[i] with FR[i]
    const pairCount = Math.min(flObs.length, frObs.length);
    for (let i = 0; i < pairCount; i++) {
      const fl = flObs[i];
      const fr = frObs[i];

      if (fl.hzAngle === undefined || fr.hzAngle === undefined) continue;
      if (fl.vAngle === undefined || fr.vAngle === undefined) continue;

      const fullCircle = 360; // already converted from gon

      // Mean horizontal angle: (Hz_FL + Hz_FR ± 180°) / 2
      const frHzCorrected = fr.hzAngle >= 180 ? fr.hzAngle - 180 : fr.hzAngle + 180;
      let meanHz = (fl.hzAngle + frHzCorrected) / 2;
      if (meanHz >= 360) meanHz -= 360;
      if (meanHz < 0) meanHz += 360;

      // Mean vertical angle: (V_FL + (360° - V_FR)) / 2
      const meanV = (fl.vAngle + (360 - fr.vAngle)) / 2;

      // Mean slope distance
      const meanSD = ((fl.slopeDist ?? 0) + (fr.slopeDist ?? 0)) / 2;

      // Collimation error: (Hz_FL - (Hz_FR ± 180°)) / 2 → in arc-seconds
      const collimation = ((fl.hzAngle - frHzCorrected) / 2) * 3600;

      // Index error: (V_FL + V_FR - 360°) / 2 → in arc-seconds
      const indexError = ((fl.vAngle + fr.vAngle - 360) / 2) * 3600;

      pairs.push({
        pointId,
        fl,
        fr,
        meanHz,
        meanV,
        meanSD,
        collimation,
        indexError,
      });
    }
  }

  return pairs;
}

// ─── Station Setups ───────────────────────────────────────────────────────────

function buildStationSetups(observations: GSIObservation[]): GSIStationSetup[] {
  const setups: GSIStationSetup[] = [];
  let currentSetup: GSIStationSetup | null = null;

  for (const obs of observations) {
    // Detect station setup change: when instrument height appears
    if (obs.instrumentHeight !== undefined && obs.instrumentHeight > 0) {
      if (currentSetup && currentSetup.observations.length > 0) {
        setups.push(currentSetup);
      }
      currentSetup = {
        stationId: obs.pointId,
        instrumentHeight: obs.instrumentHeight,
        observations: [],
      };
      continue;
    }

    if (currentSetup) {
      currentSetup.observations.push(obs);
    } else {
      // Observations before first station setup — create implicit setup
      currentSetup = {
        stationId: 'UNKNOWN',
        instrumentHeight: 0,
        observations: [obs],
      };
    }
  }

  if (currentSetup && currentSetup.observations.length > 0) {
    setups.push(currentSetup);
  }

  return setups;
}

// ─── Register with Universal Importer ─────────────────────────────────────────

registerParser({
  format: 'gsi',
  label: 'Leica GSI (Professional)',
  extensions: ['gsi', 'txt'],
  detect: (content) => {
    const trimmed = content.trimStart();
    return trimmed.startsWith('*') && /^\*\d{2}/.test(trimmed);
  },
  parse: (content): ParseResult => {
    const result = parseGSIContent(content);
    return {
      format: 'gsi',
      points: result.points,
      warnings: result.warnings,
    };
  },
});

// Export for direct use by advanced components
export { parseGSIContent };

import { ParsedSurveyData } from '../droneTypes';

/**
 * LAS/LAZ Point Cloud Parser
 *
 * AUDIT FIX (2026-07-03): Upgraded from a minimal parser that only supported
 * LAS point format 0 (20 bytes, no RGB, no GPS-time) with a hardcoded 28-byte
 * record length and 50K point cap.
 *
 * Now properly reads the LAS header to support:
 *   - LAS 1.2, 1.3, 1.4 (version major.minor at bytes 24-25)
 *   - Point data formats 0-3 (LAS 1.2-1.3) and 6-8 (LAS 1.4)
 *   - Variable point record length (read from header, not hardcoded)
 *   - RGB data (formats 2, 3, 7, 8)
 *   - GPS time (formats 1, 3, 6, 7, 8)
 *   - Variable header size with VLRs (offset to point data from bytes 96-99)
 *   - 100K point cap (was 50K)
 *
 * References:
 *   - LAS Specification 1.4-r15 (ASPRS, 2019)
 *   - LAS 1.2/1.3 point data record formats
 */

interface LasHeader {
  versionMajor: number
  versionMinor: number
  pointDataFormatId: number
  pointDataRecordLength: number
  pointDataOffset: number
  numberOfPointRecords: number
  scaleX: number
  scaleY: number
  scaleZ: number
  offsetX: number
  offsetY: number
  offsetZ: number
}

function readHeader(view: DataView): LasHeader {
  // File signature ("LASF")
  const sig = String.fromCharCode(
    view.getUint8(0), view.getUint8(1),
    view.getUint8(2), view.getUint8(3),
  )
  if (sig !== 'LASF') {
    throw new Error(`Invalid LAS file signature: "${sig}" (expected "LASF")`)
  }

  const versionMajor = view.getUint8(24)
  const versionMinor = view.getUint8(25)

  if (versionMajor < 1 || (versionMajor === 1 && versionMinor < 2)) {
    throw new Error(`Unsupported LAS version: ${versionMajor}.${versionMinor} (minimum 1.2)`)
  }

  // Header size (offset to first VLR) — typically 227 for LAS 1.2-1.3, 375 for LAS 1.4
  const headerSize = view.getUint16(94, true)

  // Offset to point data (may be larger than headerSize if VLRs exist)
  const pointDataOffset = view.getUint32(96, true)

  // Point data format ID (low 4 bits of byte 104; high 4 bits reserved in 1.4)
  const pointDataFormatId = view.getUint8(104) & 0x0F

  // Point data record length (bytes 105-106)
  const pointDataRecordLength = view.getUint16(105, true)

  // Number of point records (bytes 107-110 in 1.2-1.3; in 1.4 may be 0 if using extended counts)
  const numberOfPointRecords = view.getUint32(107, true)

  // Scale factors and offsets
  const scaleX = view.getFloat64(131, true)
  const scaleY = view.getFloat64(139, true)
  const scaleZ = view.getFloat64(147, true)
  const offsetX = view.getFloat64(155, true)
  const offsetY = view.getFloat64(163, true)
  const offsetZ = view.getFloat64(171, true)

  return {
    versionMajor,
    versionMinor,
    pointDataFormatId,
    pointDataRecordLength,
    pointDataOffset: pointDataOffset || headerSize,
    numberOfPointRecords,
    scaleX, scaleY, scaleZ,
    offsetX, offsetY, offsetZ,
  }
}

/**
 * Parse a single point record based on the point data format.
 *
 * LAS Point Data Record Formats:
 *   Format 0 (20 bytes): X, Y, Z, intensity, return info, classification, etc. (no GPS, no RGB)
 *   Format 1 (28 bytes): Format 0 + GPS time (8 bytes)
 *   Format 2 (26 bytes): Format 0 + RGB (2+2+2 bytes)
 *   Format 3 (34 bytes): Format 0 + GPS time + RGB
 *   Format 6 (30 bytes): LAS 1.4 — X, Y, Z, intensity, return info, classification, GPS time (no RGB)
 *   Format 7 (36 bytes): Format 6 + RGB
 *   Format 8 (38 bytes): Format 7 + NIR
 */
function parsePoint(
  view: DataView,
  offset: number,
  format: number,
  header: LasHeader,
): { x: number; y: number; z: number; r?: number; g?: number; b?: number; gpsTime?: number; classification?: number } {
  // X, Y, Z are always the first 12 bytes (3 × int32) in all formats
  const x = view.getInt32(offset, true) * header.scaleX + header.offsetX
  const y = view.getInt32(offset + 4, true) * header.scaleY + header.offsetY
  const z = view.getInt32(offset + 8, true) * header.scaleZ + header.offsetZ

  // Intensity (uint16 at offset 12)
  const intensity = view.getUint16(offset + 12, true)

  // Classification (offset 20 for formats 0-5, offset 18 for formats 6-8 in LAS 1.4)
  let classification = 0
  let gpsTime: number | undefined
  let r: number | undefined, g: number | undefined, b: number | undefined

  if (format <= 5) {
    classification = view.getUint8(offset + 20) & 0x1F  // low 5 bits

    // GPS time (format 1, 3, 4, 5) at offset 20
    if (format === 1 || format === 3 || format === 4 || format === 5) {
      gpsTime = view.getFloat64(offset + 20, true)
    }

    // RGB (format 2, 3, 5) — at the end of the record
    if (format === 2 || format === 3 || format === 5) {
      const rgbOffset = format === 2 ? offset + 20 : offset + 28
      r = view.getUint16(rgbOffset, true)
      g = view.getUint16(rgbOffset + 2, true)
      b = view.getUint16(rgbOffset + 4, true)
    }
  } else {
    // LAS 1.4 formats 6-8
    classification = view.getUint8(offset + 18) & 0x1F

    // GPS time at offset 22 for all 1.4 formats (6, 7, 8)
    gpsTime = view.getFloat64(offset + 22, true)

    // RGB (format 7, 8) at offset 30
    if (format === 7 || format === 8) {
      r = view.getUint16(offset + 30, true)
      g = view.getUint16(offset + 32, true)
      b = view.getUint16(offset + 34, true)
    }
  }

  return { x, y, z, r, g, b, gpsTime, classification }
}

export async function parseLas(file: File): Promise<ParsedSurveyData> {
  const arrayBuffer = await file.arrayBuffer();
  const view = new DataView(arrayBuffer);

  try {
    const header = readHeader(view)

    // Cap at 100K points (was 50K) for browser memory
    const maxPoints = Math.min(header.numberOfPointRecords, 100000)
    const recordLen = header.pointDataRecordLength

    const points: ParsedSurveyData['points'] = [];
    let hasRgb = false
    let hasGpsTime = false

    for (let i = 0; i < maxPoints; i++) {
      const offset = header.pointDataOffset + i * recordLen;
      if (offset + recordLen > arrayBuffer.byteLength) break;

      const pt = parsePoint(view, offset, header.pointDataFormatId, header)

      if (pt.r !== undefined) hasRgb = true
      if (pt.gpsTime !== undefined) hasGpsTime = true

      // Map LAS classification codes to feature codes
      let code = 'DRONE-PC'
      if (pt.classification === 2) code = 'GROUND'
      else if (pt.classification === 3) code = 'LOW-VEG'
      else if (pt.classification === 4) code = 'MED-VEG'
      else if (pt.classification === 5) code = 'HIGH-VEG'
      else if (pt.classification === 6) code = 'BUILDING'
      else if (pt.classification === 8) code = 'MODEL-KEY'
      else if (pt.classification === 9) code = 'WATER'

      points.push({
        easting: Number(pt.x.toFixed(3)),
        northing: Number(pt.y.toFixed(3)),
        rl: Number(pt.z.toFixed(3)),
        code,
      });
    }

    return {
      points,
      metadata: {
        source: 'LAS Point Cloud',
        format: `LAS ${header.versionMajor}.${header.versionMinor} (point format ${header.pointDataFormatId})`,
        totalPoints: header.numberOfPointRecords,
        droneSpecific: {
          flightDate: new Date().toISOString(),
          hasRgb,
          hasGpsTime,
          pointDataFormat: header.pointDataFormatId,
          recordLength: recordLen,
        },
      },
    };
  } catch (err) {
    throw new Error(
      `Failed to parse LAS file: ${err instanceof Error ? err.message : 'invalid format'}`
    );
  }
}

export async function parseLaz(file: File): Promise<ParsedSurveyData> {
  // LAZ is LASzip-compressed LAS — requires server-side decompression
  // (laszip-python or PDAL). The /api/compute/parse-laz route would
  // call PDAL or laszip to decompress, then parse the result.
  const formData = new FormData();
  formData.append('file', file);
  formData.append('type', 'parse-laz');

  const res = await fetch('/api/compute/parse-laz', {
    method: 'POST',
    body: formData,
  });

  if (!res.ok) {
    throw new Error(
      'LAZ parsing requires server-side processing (PDAL/laszip). ' +
      'The /api/compute/parse-laz endpoint is not yet configured. ' +
      'Convert your LAZ file to LAS using laszip or PDAL, then upload the .las file.'
    );
  }

  return (await res.json()) as ParsedSurveyData;
}

import { registerParser } from '../registry';
import { ParseResult, ParsedPoint } from '@/types/importer';
import { parseSouthData } from '@/lib/import/totalStation/parseSouth';

/**
 * South total station .dat/.dc format registration.
 *
 * Detection strategy:
 * 1. If file starts with "South," header — confirmed South
 * 2. If file contains SS observation rows with South-style DMS angles — likely South
 * 3. If .dat/.dc extension and coordinate rows match pattern — South coordinate export
 *
 * Note: .dc is also used by Trimble RW5. The detect function checks content to
 * disambiguate. Trimble detection runs first if file contains "--Trimble" markers.
 */
registerParser({
  format: 'south',
  label: 'South Total Station (.dat/.dc)',
  extensions: ['dat', 'dc'],
  detect: (content) => {
    const trimmed = content.trim();
    const firstLine = trimmed.split('\n')[0]?.trim() ?? '';

    // Explicit South header
    if (firstLine.toLowerCase().startsWith('south,')) return true;

    // SS observation rows (South format: SS,obs#,station,target,HCL_DMS,...)
    // Distinguished from Trimble SS by key=value absence and numeric DMS angle
    const ssLineMatch = /^(SS,)\d+,/.test(firstLine) &&
      !firstLine.includes('=') &&
      /\d{2,3}\.\d{4}/.test(firstLine);

    if (ssLineMatch) return true;

    // Coordinate-only South file: integer pt#, name, numeric E, N, RL, quoted code, type
    // Pattern: 1,BM1,984321.456,1234567.890,1542.345,"BM1",0
    const coordLineMatch = /^\s*\d+\s*,/.test(firstLine) &&
      !/^\s*\d+\s*,\s*[\d.]+\s*,\s*[\d.]+\s*,\s*[\d.]+/.test(firstLine.replace(/"[^"]*"/g, '').replace(/'[^']*'/g, '')) === false;

    // More reliable: check if any line matches the full South coordinate pattern
    const lines = trimmed.split('\n').slice(0, 10);
    const southCoordRegex = /^\s*\d+\s*,\s*\w+\s*,\s*[\d.]+\s*,\s*[\d.]+\s*,\s*[\d.]+/;
    const hasSouthCoord = lines.some((l) => southCoordRegex.test(l.trim()));

    // Must NOT be Trimble (Trimble uses key=value pairs)
    const hasTrimbleMarkers = trimmed.includes('--Trimble') || /[A-Z]{2}=/i.test(trimmed);

    if (hasSouthCoord && !hasTrimbleMarkers) return true;

    return false;
  },
  parse: (content): ParseResult => {
    const result = parseSouthData(content);
    const points: ParsedPoint[] = [];
    const warnings: string[] = [...result.warnings];

    // Convert coordinate points to ParsedPoint format
    for (const coord of result.coordinates) {
      const point: ParsedPoint = {
        point_no: String(coord.pointNumber),
        easting: coord.easting,
        northing: coord.northing,
        rl: coord.elevation,
        code: coord.code || undefined,
        remark: coord.pointName !== String(coord.pointNumber) ? coord.pointName : undefined,
        raw: {
          pointNumber: coord.pointNumber,
          pointName: coord.pointName,
          pointType: coord.pointType,
        } as Record<string, unknown>,
      };
      points.push(point);
    }

    // Convert observations to ParsedPoint entries
    for (const obs of result.observations) {
      const point: ParsedPoint = {
        point_no: obs.target,
        bearing:
          obs.hclDeg + obs.hclMin / 60 + obs.hclSec / 3600,
        distance: obs.slopeDistance,
        code: `${obs.station}→${obs.target}`,
        raw: {
          observationNumber: obs.observationNumber,
          station: obs.station,
          target: obs.target,
          hcl: `${obs.hclDeg}°${obs.hclMin}'${obs.hclSec}"`,
          targetHeight: obs.targetHeight,
          slopeDistance: obs.slopeDistance,
          va: `${obs.vaDeg}°${obs.vaMin}'${obs.vaSec}"`,
          instrumentHeight: obs.instrumentHeight,
        } as Record<string, unknown>,
      };
      points.push(point);
    }

    // Pass through errors as warnings (registry parsers use warnings, not errors)
    for (const err of result.errors) {
      warnings.push(err);
    }

    if (points.length === 0) {
      warnings.push(
        'No valid South coordinate or observation records parsed. Verify the file format.'
      );
    }

    return {
      format: 'south',
      points,
      warnings,
      metadata: {
        fileType: result.type,
        coordinateCount: result.coordinates.length,
        observationCount: result.observations.length,
      },
    };
  },
});

