import { SurveyDataset } from '../workflows/workflowEngine'

export function detectSurveyType(
  headers: string[], 
  rows: Record<string, string>[]
): SurveyDataset['surveyType'] {
  
  const h = headers.map((h) => h.toLowerCase().trim())
  
  // Leveling detection
  if (h.includes('bs') || h.includes('fs') || h.includes('is')) {
    return 'leveling'
  }
  
  // Traverse detection  
  if (
    (h.includes('bearing') || h.includes('wcb')) && 
    (h.includes('distance') || h.includes('length'))
  ) {
    return 'traverse'
  }
  
  // Radiation detection
  if (
    h.includes('angle') && h.includes('distance') &&
    !h.includes('bearing')
  ) {
    return 'radiation'
  }
  
  // Coordinate data
  if (h.includes('easting') && h.includes('northing')) {
    return 'coordinates'
  }
  
  return 'unknown'
}

export interface ParsedPoint {
  pointId: string
  easting?: number
  northing?: number
  elevation?: number
  code?: string
  rawData: Record<string, string>
}

export interface ParseResult {
  format: 'gsi' | 'jobxml' | 'topcon' | 'csv' | 'unknown'
  points: ParsedPoint[]
  errors: string[]
  warnings: string[]
  metadata: Record<string, string>
}

function detectFormat(content: string, filename: string): string {
  const ext = filename.toLowerCase().split('.').pop() || ''
  if (ext === 'gsi' || ext === 'xml') {
    const trimmed = content.trim()
    if (trimmed.startsWith('*') && trimmed.includes('21.') && trimmed.includes('22.')) return 'gsi'
    if (trimmed.startsWith('<')) return 'jobxml'
  }
  if (ext === 'csv' || ext === 'txt') {
    const lines = content.split('\n').filter((l) => l.trim())
    if (lines[0]?.toLowerCase().includes('pt') && lines[0]?.toLowerCase().includes('n')) return 'topcon'
    if (lines[0]?.toLowerCase().includes('point') || lines[0]?.toLowerCase().includes('easting')) return 'csv'
  }
  const trimmed = content.trim()
  if (trimmed.startsWith('*') && trimmed.includes('21.') && trimmed.includes('22.')) return 'gsi'
  if (trimmed.startsWith('<')) return 'jobxml'
  return 'unknown'
}

function parseGSI(content: string): ParseResult {
  const points: ParsedPoint[] = []
  const errors: string[] = []
  const warnings: string[] = []
  const metadata: Record<string, string> = { format: 'Leica GSI' }

  const lines = content.split('\n').filter((l) => l.trim())
  let pointCount = 0

  for (const line of lines) {
    const trimmed = line.trim()
    if (!trimmed.startsWith('*')) continue

    const words = trimmed.split(/\s+/)
    const pointData: Record<string, string> = {}

    for (const word of words) {
      if (!word.includes('.')) continue
      const dotIdx = word.indexOf('.')
      const key = word.substring(0, dotIdx)
      const value = word.substring(dotIdx + 1)
      pointData[key] = value
    }

    if (Object.keys(pointData).length === 0) continue

    const pointId = pointData['1']?.replace(/^0+/, '') || `P${pointCount + 1}`
    const easting = parseFloat(pointData['21']) / 10000
    const northing = parseFloat(pointData['22']) / 10000
    const elevation = pointData['23'] ? parseFloat(pointData['23']) / 10000 : undefined
    const code = pointData['33']?.replace(/\+/g, ' ').trim() || undefined

    if (!isNaN(easting) && !isNaN(northing)) {
      points.push({ pointId, easting, northing, elevation, code, rawData: pointData })
      pointCount++
    } else {
      warnings.push(`Point ${pointId}: Missing or invalid coordinates — skipped`)
    }
  }

  if (points.length === 0) {
    errors.push('No valid coordinate points found in GSI file. Ensure file contains GSI-8 or GSI-16 format with 21/22 word codes.')
  }

  return { format: 'gsi', points, errors, warnings, metadata }
}

function parseJobXML(content: string): ParseResult {
  const points: ParsedPoint[] = []
  const errors: string[] = []
  const warnings: string[] = []
  const metadata: Record<string, string> = { format: 'Trimble JobXML' }

  try {
    const parser = new DOMParser()
    const doc = parser.parseFromString(content, 'text/xml')

    const jobName = doc.querySelector('Job')?.getAttribute('name') || doc.querySelector('Name')?.textContent || ''
    metadata['job'] = jobName

    const obsElements = doc.querySelectorAll('Obs, Point, Observation')
    let pointCount = 0

    for (const obs of Array.from(obsElements)) {
      const getAttr = (el: Element, name: string) =>
        el.getAttribute(name) || el.querySelector(name)?.textContent || ''

      const pointId = getAttr(obs as Element, 'name') || getAttr(obs as Element, 'id') || getAttr(obs as Element, 'pt') || `P${pointCount + 1}`
      const rawEl = obs as Element

      const easting = parseFloat(getAttr(rawEl, 'east') || getAttr(rawEl, 'easting') || rawEl.querySelector('Easting')?.textContent || '')
      const northing = parseFloat(getAttr(rawEl, 'north') || getAttr(rawEl, 'northing') || rawEl.querySelector('Northing')?.textContent || '')
      const elevation = parseFloat(getAttr(rawEl, 'z') || getAttr(rawEl, 'elev') || rawEl.querySelector('Elevation')?.textContent || '')
      const code = getAttr(rawEl, 'code') || getAttr(rawEl, 'desc') || undefined

      if (!isNaN(easting) && !isNaN(northing)) {
        points.push({
          pointId: String(pointId),
          easting,
          northing,
          elevation: isNaN(elevation) ? undefined : elevation,
          code: code || undefined,
          rawData: {},
        })
        pointCount++
      }
    }
  } catch {
    errors.push('Failed to parse JobXML. Ensure valid XML format.')
  }

  if (points.length === 0) {
    errors.push('No valid coordinate points found in JobXML file.')
  }

  return { format: 'jobxml', points, errors, warnings, metadata }
}

function parseTopconGTS(content: string): ParseResult {
  const points: ParsedPoint[] = []
  const errors: string[] = []
  const warnings: string[] = []
  const metadata: Record<string, string> = { format: 'Topcon GTS' }

  const lines = content.split('\n').filter((l) => l.trim())
  const header = lines[0]?.toLowerCase() || ''
  const hasHeader = header.includes('pt') || header.includes('n') || header.includes('e')

  const dataLines = hasHeader ? lines.slice(1) : lines
  let pointCount = 0

  for (const line of dataLines) {
    const parts = line.split(/[,\t\s]+/).filter((p) => p.trim())
    if (parts.length < 3) continue

    const pointId = parts[0].trim()
    const n = parseFloat(parts[1])
    const e = parseFloat(parts[2])
    const z = parts[3] ? parseFloat(parts[3]) : undefined
    const code = parts[4]?.trim() || undefined

    if (!isNaN(n) && !isNaN(e)) {
      points.push({
        pointId,
        easting: e,
        northing: n,
        elevation: z && !isNaN(z) ? z : undefined,
        code,
        rawData: {},
      })
      pointCount++
    } else {
      warnings.push(`Line "${line}": Invalid numeric data — skipped`)
    }
  }

  if (points.length === 0) {
    errors.push('No valid coordinate points found. Expected format: PT, N, E, Z, CD (comma or tab separated).')
  }

  return { format: 'topcon', points, errors, warnings, metadata }
}

function parseCSV(content: string): ParseResult {
  const points: ParsedPoint[] = []
  const errors: string[] = []
  const warnings: string[] = []
  const metadata: Record<string, string> = { format: 'Generic CSV' }

  const lines = content.split('\n').filter((l) => l.trim())
  if (lines.length < 2) {
    errors.push('CSV file must have at least a header row and one data row.')
    return { format: 'csv', points, errors, warnings, metadata }
  }

  const header = lines[0].toLowerCase()
  const cols = lines[0].split(/[,\t]+/).map((c) => c.trim().toLowerCase().replace(/[^a-z0-9_]/g, ''))

  const pidIdx = cols.findIndex(c => c.includes('id') || c.includes('label') || c === 'pt' || c === 'point')
  const eIdx = cols.findIndex(c => c.includes('east') || c === 'e' || c === 'x')
  const nIdx = cols.findIndex(c => c.includes('north') || c === 'n' || c === 'y')
  const zIdx = cols.findIndex(c => c.includes('elev') || c.includes('z') || c.includes('height') || c === 'rl')
  const codeIdx = cols.findIndex(c => c.includes('code') || c.includes('desc') || c.includes('cd'))

  if (eIdx === -1 || nIdx === -1) {
    errors.push('CSV must contain at least Easting (E) and Northing (N) columns.')
    return { format: 'csv', points, errors, warnings, metadata }
  }

  for (let i = 1; i < lines.length; i++) {
    const parts = lines[i].split(/[,\t]+/).map((p) => p.trim())
    const pointId = pidIdx >= 0 ? (parts[pidIdx] || `P${i}`) : `P${i}`
    const easting = parseFloat(parts[eIdx])
    const northing = parseFloat(parts[nIdx])
    const elevation = zIdx >= 0 && parts[zIdx] ? parseFloat(parts[zIdx]) : undefined
    const code = codeIdx >= 0 ? parts[codeIdx] : undefined

    if (!isNaN(easting) && !isNaN(northing)) {
      points.push({
        pointId,
        easting,
        northing,
        elevation: elevation && !isNaN(elevation) ? elevation : undefined,
        code: code || undefined,
        rawData: {},
      })
    } else {
      warnings.push(`Row ${i + 1}: Invalid coordinates — skipped`)
    }
  }

  metadata['pointCount'] = String(points.length)
  return { format: 'csv', points, errors, warnings, metadata }
}

export function parseTotalStationFile(content: string, filename: string): ParseResult {
  const format = detectFormat(content, filename)
  switch (format) {
    case 'gsi': return parseGSI(content)
    case 'jobxml': return parseJobXML(content)
    case 'topcon': return parseTopconGTS(content)
    case 'csv': return parseCSV(content)
    default: {
      const csvResult = parseCSV(content)
      if (csvResult.points.length > 0) return csvResult
      return {
        format: 'unknown',
        points: [],
        errors: ['Unknown file format. Supported formats: Leica GSI, Trimble JobXML, Topcon GTS, and Generic CSV.'],
        warnings: [],
        metadata: {},
      }
    }
  }
}

export function parseTraverseCSV(content: string): {
  headers: string[]
  rows: string[][]
  errors: string[]
} {
  const lines = content.split('\n').filter((l) => l.trim())
  if (lines.length < 2) return { headers: [], rows: [], errors: ['File is empty or has no data rows'] }

  const headers = lines[0].split(/[,\t]+/).map((h) => h.trim().toLowerCase().replace(/\s+/g, '_'))
  const rows = lines.slice(1).map((line) =>
    line.split(/[,\t]+/).map((cell) => cell.trim())
  ).filter((r) => r.some((c) => c.length > 0))

  const errors: string[] = []
  if (!headers.some((h) => h.includes('station'))) errors.push('Missing "station" column')
  if (!headers.some((h) => h.includes('slope_dist') || h.includes('dist') || h.includes('sd'))) {
    errors.push('Missing slope distance column (slope_dist, dist, or sd)')
  }

  return { headers, rows, errors }
}

/**
 * PayPal Payment Integration
 * Processes PayPal payments
 */
import { logger } from '@/lib/logger'

export interface PayPalConfig {
  clientId: string
  clientSecret: string
  mode: 'sandbox' | 'live'
}

export interface PayPalOrder {
  id: string
  status: string
  links: { rel: string; href: string }[]
}

export interface PayPalCaptureResult {
  id: string
  status: string
  purchase_units: {
    payments: {
      captures: { id: string; status: string; amount: { value: string; currency_code: string } }[]
    }[]
  }[]
}

export class PayPalService {
  private clientId: string
  private clientSecret: string
  private mode: 'sandbox' | 'live'
  private accessToken: string | null = null
  private tokenExpiry: number = 0

  constructor(config: PayPalConfig) {
    this.clientId = config.clientId
    this.clientSecret = config.clientSecret
    this.mode = config.mode
  }

  private get baseUrl(): string {
    return this.mode === 'sandbox'
      ? 'https://api-m.sandbox.paypal.com'
      : 'https://api-m.paypal.com'
  }

  private async getAccessToken(): Promise<string> {
    if (this.accessToken && Date.now() < this.tokenExpiry) {
      return this.accessToken
    }

    const credentials = Buffer.from(`${this.clientId}:${this.clientSecret}`).toString('base64')
    
    const response = await fetch(`${this.baseUrl}/v1/oauth2/token`, {
      method: 'POST',
      headers: {
        'Authorization': `Basic ${credentials}`,
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      body: 'grant_type=client_credentials'
    })

    if (!response.ok) {
      const errorBody = await response.text().catch(() => 'unknown')
      logger.error(`[PayPal] Token request failed: ${response.status} ${response.statusText} | mode=${this.mode} | body=${errorBody}`)
      throw new Error(`Failed to obtain PayPal access token (${response.status}). Mode: ${this.mode}. Check PAYPAL_MODE, CLIENT_ID and CLIENT_SECRET.`)
    }

    const data = (await response.json()) as { access_token: string; expires_in: number }
    this.accessToken = data.access_token
    this.tokenExpiry = Date.now() + (data.expires_in * 1000) - 60000

    return this.accessToken!
  }

  private currencyMinorUnitDigits(currency: string): number {
    try {
      const nf = new Intl.NumberFormat('en-US', { style: 'currency', currency: currency.toUpperCase() })
      return nf.resolvedOptions().maximumFractionDigits ?? 2
    } catch {
      return 2
    }
  }

  async createOrder(input: {
    amount: number
    currency?: string
    description?: string
    returnUrl?: string
    cancelUrl?: string
  }): Promise<PayPalOrder> {
    const accessToken = await this.getAccessToken()
    const currency = input.currency || 'USD'
    const digits = this.currencyMinorUnitDigits(currency)
    const value = input.amount.toFixed(digits)

    const response = await fetch(`${this.baseUrl}/v2/checkout/orders`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        intent: 'CAPTURE',
        purchase_units: [{
          amount: {
            currency_code: currency,
            value
          },
          ...(input.description && { description: input.description })
        }],
        ...(input.returnUrl || input.cancelUrl
          ? {
              application_context: {
                return_url: input.returnUrl,
                cancel_url: input.cancelUrl,
                brand_name: 'METARDU',
                landing_page: 'NO_PREFERENCE',
                user_action: 'PAY_NOW',
              },
            }
          : {}),
      })
    })

    if (!response.ok) {
      const error = (await response.json()) as { message?: string }
      throw new Error(error.message || 'Failed to create PayPal order')
    }

    return (await response.json()) as PayPalOrder
  }

  async captureOrder(orderId: string): Promise<PayPalCaptureResult> {
    const accessToken = await this.getAccessToken()

    const response = await fetch(`${this.baseUrl}/v2/checkout/orders/${orderId}/capture`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      }
    })

    if (!response.ok) {
      const error = (await response.json()) as { message?: string }
      throw new Error(error.message || 'Failed to capture PayPal order')
    }

    return (await response.json()) as PayPalCaptureResult
  }

  async getOrderDetails(orderId: string): Promise<PayPalOrder> {
    const accessToken = await this.getAccessToken()

    const response = await fetch(`${this.baseUrl}/v2/checkout/orders/${orderId}`, {
      headers: {
        'Authorization': `Bearer ${accessToken}`
      }
    })

    if (!response.ok) {
      throw new Error('Failed to get PayPal order details')
    }

    return (await response.json()) as PayPalOrder
  }

  async createSubscription(planId: string, subscriber: { email: string; name?: string }): Promise<{ subscriptionId: string; approvalUrl: string }> {
    const accessToken = await this.getAccessToken()

    const response = await fetch(`${this.baseUrl}/v1/billing/subscriptions`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        plan_id: planId,
        subscriber: {
          email_address: subscriber.email,
          ...(subscriber.name && {
            name: { given_name: subscriber.name.split(' ')[0], surname: subscriber.name.split(' ').slice(1).join(' ') }
          })
        },
        application_context: {
          brand_name: 'METARDU',
          landing_page: 'NO_PREFERENCE',
          user_action: 'SUBSCRIBE_NOW',
          return_url: `${process.env.NEXT_PUBLIC_APP_URL}/subscription/success`,
          cancel_url: `${process.env.NEXT_PUBLIC_APP_URL}/subscription/cancel`
        }
      })
    })

    if (!response.ok) {
      const error = (await response.json()) as { message?: string }
      throw new Error(error.message || 'Failed to create subscription')
    }

    const data = (await response.json()) as { id: string; links?: Array<{ rel: string; href: string }> }
    const approveLink = data.links?.find((l: { rel: string }) => l.rel === 'approve')

    return {
      subscriptionId: data.id,
      approvalUrl: approveLink?.href || ''
    }
  }

  async activateSubscription(subscriptionId: string): Promise<boolean> {
    const accessToken = await this.getAccessToken()

    const response = await fetch(`${this.baseUrl}/v1/billing/subscriptions/${subscriptionId}/activate`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      }
    })

    return response.ok
  }

  async cancelSubscription(subscriptionId: string): Promise<boolean> {
    const accessToken = await this.getAccessToken()

    const response = await fetch(`${this.baseUrl}/v1/billing/subscriptions/${subscriptionId}/cancel`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ reason: 'User requested cancellation' })
    })

    return response.ok
  }
}

export function getPayPalService(): PayPalService | null {
  const clientId = process.env.PAYPAL_CLIENT_ID
  const clientSecret = process.env.PAYPAL_CLIENT_SECRET
  
  if (!clientId || !clientSecret) {
    logger.warn('[PayPal] PAYPAL_CLIENT_ID or PAYPAL_CLIENT_SECRET not set — PayPal disabled')
    return null
  }

  // Default to sandbox unless PAYPAL_MODE=live is explicitly set.
  // NEVER auto-detect from NODE_ENV — prevents sandbox credentials hitting live API.
  const mode = (process.env.PAYPAL_MODE as 'sandbox' | 'live') || 'sandbox'

  return new PayPalService({
    clientId,
    clientSecret,
    mode
  })
}

/**
 * Server-side PDF generation using Puppeteer
 * Generates print-ready PDFs from survey report HTML
 */

import puppeteer from 'puppeteer'
import type { SectionContent } from '@/types/surveyReport'

export interface PdfGenerationOptions {
  title: string
  sections: SectionContent[]
  paperSize?: 'A4' | 'A3'
  orientation?: 'portrait' | 'landscape'
}

export async function generatePdf(options: PdfGenerationOptions): Promise<Buffer> {
  const {
    title,
    sections,
    paperSize = 'A4',
    orientation = 'portrait',
  } = options

  const browser = await puppeteer.launch({
    headless: true,
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-dev-shm-usage',
      '--disable-gpu',
    ],
  })

  try {
    const page = await browser.newPage()

    // Generate HTML content
    const html = generateReportHtml(title, sections)

    // Set HTML content
    await page.setContent(html, {
      waitUntil: 'networkidle0',
    })

    // Wait for fonts and images to load
    await new Promise(resolve => setTimeout(resolve, 1000))

  // Generate PDF
  const pdfBuffer = await page.pdf({
    format: paperSize.toLowerCase() as 'a4' | 'a3',
    printBackground: true,
    margin: {
      top: '10mm',
      right: '10mm',
      bottom: '10mm',
      left: '10mm',
    },
    displayHeaderFooter: false,
    preferCSSPageSize: true,
  })

    return Buffer.from(pdfBuffer)
  } finally {
    await browser.close()
  }
}

