  <div class="watermark">METARDU</div>
  <div class="content-wrapper">
    ${sections
      .map((section, index) => {
        const isTitlePage = section.sectionNumber === 1
        return `
    <div class="section ${isTitlePage ? 'title-page' : ''}">
      ${
        isTitlePage
          ? section.content
          : `
      <h2>${section.sectionNumber}. ${section.title}</h2>
      ${section.content}
      `
      }
    </div>
      `
      })
      .join('')}
  </div>
</body>
</html>
  `
}

