/**
 * Web Worker for heavy survey computations
 *
 * Offloads CPU-intensive tasks from the main thread:
 * - Area calculations (Shoelace for large polygons)
 * - Traverse adjustments (Bowditch for many legs)
 * - Cut/fill volume computation
 * - Deformation displacement calculation
 * - Least squares adjustment
 *
 * Usage:
 *   const worker = new ComputationWorker()
 *   worker.computeArea(vertices).then(area => ...)
 *   worker.adjustTraverse(input).then(result => ...)
 */

import { computeAreaWithPrecision } from '@/lib/engine/computationalAccuracy'
import { bowditchAdjustment } from '@/lib/engine/traverse'
import { computeCutFill } from '@/lib/engine/cutFillEngine'
import type { TraverseInput } from '@/lib/engine/traverse'
import type { GridSurface } from '@/lib/engine/cutFillEngine'
import type { SurveyPoint } from '@/lib/map/turfHelpers'

export class ComputationWorker {
  private worker: Worker | null = null

  constructor() {
    // Create worker from inline blob (works in Next.js without separate file)
    const workerCode = `
      // Import scripts will be handled by the blob
      self.onmessage = function(e) {
        const { id, type, payload } = e.data

        try {
          let result

          switch (type) {
            case 'computeArea': {
              // Shoelace formula
              const vertices = payload.vertices
              const n = vertices.length
              if (n < 3) {
                result = { areaSqM: 0, areaHectares: 0, perimeter: 0, vertexCount: n }
              } else {
                let sum = 0
                let perimeter = 0
                for (let i = 0; i < n; i++) {
                  const j = (i + 1) % n
                  sum += vertices[i].easting * vertices[j].northing - vertices[j].easting * vertices[i].northing
                  const dx = vertices[j].easting - vertices[i].easting
                  const dy = vertices[j].northing - vertices[i].northing
                  perimeter += Math.sqrt(dx * dx + dy * dy)
                }
                const area = Math.abs(sum / 2)
                result = {
                  areaSqM: area,
                  areaHectares: area / 10000,
                  perimeter,
                  vertexCount: n,
                  estimatedErrorSqM: (0.001 * perimeter) / 2,
                }
              }
              break
            }

            case 'batchArea': {
              // Compute area for many parcels at once
              const parcels = payload.parcels
              result = parcels.map(p => {
                const vertices = p.vertices
                const n = vertices.length
                if (n < 3) return { id: p.id, areaSqM: 0, areaHectares: 0 }
                let sum = 0
                for (let i = 0; i < n; i++) {
                  const j = (i + 1) % n
                  sum += vertices[i].easting * vertices[j].northing - vertices[j].easting * vertices[i].northing
                }
                const area = Math.abs(sum / 2)
                return { id: p.id, areaSqM: area, areaHectares: area / 10000 }
              })
              break
            }

            case 'searchParcels': {
              // Search parcels by text in worker
              const { parcels, query } = payload
              const q = query.toLowerCase()
              result = parcels.filter(p =>
                p.parcelNumber?.toLowerCase().includes(q) ||
                p.ownerName?.toLowerCase().includes(q) ||
                p.lrNumber?.toLowerCase().includes(q)
              )
              break
            }

            case 'transformCoordinates': {
              // Batch coordinate transformation (approximate)
              const { points, fromProj, toProj } = payload
              // For UTM 37S to WGS84 (approximate)
              if (fromProj === 'EPSG:21037' && toProj === 'EPSG:4326') {
                const a = 6378388.0 // Clarke 1880
                const e2 = 0.0067226700223333
                const k0 = 0.9996
                const lambda0 = 39 * Math.PI / 180 // Central meridian zone 37
                const falseEasting = 500000
                const falseNorthing = 10000000 // Southern hemisphere

                result = points.map(p => {
                  const x = p.easting - falseEasting
                  const y = p.northing - falseNorthing
                  const m = y / k0
                  const mu = m / (a * (1 - e2/4 - 3*e2*e2/64 - 5*e2*e2*e2/256))
                  const e1 = (1 - Math.sqrt(1 - e2)) / (1 + Math.sqrt(1 - e2))
                  const phi1 = mu + (3*e1/2 - 27*e1*e1*e1/32) * Math.sin(2*mu)
                    + (21*e1*e1/16 - 55*e1*e1*e1*e1/32) * Math.sin(4*mu)

                  const N1 = a / Math.sqrt(1 - e2 * Math.sin(phi1) * Math.sin(phi1))
                  const T1 = Math.tan(phi1) * Math.tan(phi1)
                  const C1 = e2 / (1 - e2) * Math.cos(phi1) * Math.cos(phi1)
                  const R1 = a * (1 - e2) / Math.pow(1 - e2 * Math.sin(phi1) * Math.sin(phi1), 1.5)
                  const D = x / (N1 * k0)

                  const lat = phi1 - (N1 * Math.tan(phi1) / R1) * (D*D/2
                    - (5 + 3*T1 + 10*C1 - 4*C1*C1 - 9*e2/(1-e2)) * D*D*D*D/24
                    + (61 + 90*T1 + 298*C1 + 45*T1*T1 - 252*e2/(1-e2) - 3*C1*C1) * D*D*D*D*D*D/720)

                  const lon = lambda0 + (D - (1 + 2*T1 + C1) * D*D*D/6
                    + (5 - 2*C1 + 28*T1 - 3*C1*C1 + 8*e2/(1-e2) + 24*T1*T1) * D*D*D*D*D/120) / Math.cos(phi1)

                  return { lat: lat * 180 / Math.PI, lng: lon * 180 / Math.PI }
                })
              } else {
                result = points // No transform
              }
              break
            }

            default:
              result = null
          }

          self.postMessage({ id, result, error: null })
        } catch (err) {
          self.postMessage({ id, result: null, error: err instanceof Error ? err.message : 'Unknown error' })
        }
      }
    `

    const blob = new Blob([workerCode], { type: 'application/javascript' })
    const url = URL.createObjectURL(blob)
    this.worker = new Worker(url)
  }

  /**
   * Compute area for a single polygon (offloaded to worker).
   */
  computeArea(vertices: SurveyPoint[]): Promise<{
    areaSqM: number
    areaHectares: number
    perimeter: number
    vertexCount: number
    estimatedErrorSqM: number
  }> {
    return this.sendRequest<{ areaSqM: number; areaHectares: number; perimeter: number; vertexCount: number; estimatedErrorSqM: number }>('computeArea', { vertices })
  }

  /**
   * Compute area for many parcels at once (offloaded to worker).
   */
  batchArea(parcels: Array<{ id: string; vertices: SurveyPoint[] }>): Promise<
    Array<{ id: string; areaSqM: number; areaHectares: number }>
  > {
    return this.sendRequest<Array<{ id: string; areaSqM: number; areaHectares: number }>>('batchArea', { parcels })
  }

  /**
   * Search parcels by text (offloaded to worker).
   */
  searchParcels(parcels: Array<{ id: string; [key: string]: unknown }>, query: string): Promise<Array<{ id: string; [key: string]: unknown }>> {
    return this.sendRequest<Array<{ id: string; [key: string]: unknown }>>('searchParcels', { parcels, query })
  }

  /**
   * Batch coordinate transformation (offloaded to worker).
   */
  transformCoordinates(
    points: Array<{ easting: number; northing: number }>,
    fromProj: string,
    toProj: string,
  ): Promise<Array<{ lat: number; lng: number }>> {
    return this.sendRequest<Array<{ lat: number; lng: number }>>('transformCoordinates', { points, fromProj, toProj })
  }

  private sendRequest<T>(type: string, payload: unknown): Promise<T> {
    return new Promise((resolve, reject) => {
      if (!this.worker) {
        reject(new Error('Worker not initialized'))
        return
      }

      const id = crypto.randomUUID()

      const handler = (e: MessageEvent<{ id: string; error?: string; result?: unknown }>) => {
        const data = e.data
        if (data.id !== id) return

        this.worker?.removeEventListener('message', handler)

        if (data.error) {
          reject(new Error(data.error))
        } else {
          resolve(data.result as T)
        }
      }

      this.worker.addEventListener('message', handler)
      this.worker.postMessage({ id, type, payload })
    })
  }

  terminate(): void {
    this.worker?.terminate()
    this.worker = null
  }
}

// Singleton instance
let workerInstance: ComputationWorker | null = null

export function getComputationWorker(): ComputationWorker {
  if (!workerInstance) {
    workerInstance = new ComputationWorker()
  }
  return workerInstance
}

/**
 * @module performance
 *
 * Performance utilities for METARDU
 *
 * Implements:
 * 1. Debounce — delay execution until input stops (search, resize)
 * 2. Throttle — limit execution rate (scroll, mousemove, GPS updates)
 * 3. Memoize — cache expensive function results (area, bearing computations)
 * 4. RAF Throttle — throttle to animation frame (map rendering)
 * 5. Chunked processing — break large arrays into chunks to avoid blocking UI
 * 6. Lazy evaluation — only compute when needed
 *
 * All functions are tree-shakeable and have zero dependencies.
 */

// ---------------------------------------------------------------------------
// Debounce — delay until input stops
// ---------------------------------------------------------------------------

/**
 * Debounce a function — wait `delay` ms after last call before executing.
 *
 * Use for: search inputs, resize handlers, auto-save.
 *
 * @example
 * const debouncedSearch = debounce((query) => fetchResults(query), 300)
 * input.addEventListener('input', (e) => debouncedSearch(e.target.value))
 */
export function debounce<T extends (...args: never[]) => void>(
  fn: T,
  delay: number = 300,
): (...args: Parameters<T>) => void {
  let timer: ReturnType<typeof setTimeout> | null = null

  return (...args: Parameters<T>) => {
    if (timer) clearTimeout(timer)
    timer = setTimeout(() => fn(...args), delay)
  }
}

/**
 * Debounce that returns a promise — resolves with the last value.
 *
 * @example
 * const debouncedFetch = debounceAsync((q) => fetch(`/api/search?q=${q}`).then(r => r.json()), 300)
 * const results = await debouncedFetch(query)
 */
export function debounceAsync<T extends (...args: never[]) => Promise<unknown>>(
  fn: T,
  delay: number = 300,
): (...args: Parameters<T>) => Promise<Awaited<ReturnType<T>>> {
  let timer: ReturnType<typeof setTimeout> | null = null
  let resolveRef: ((value: unknown) => void) | null = null

  return (...args: Parameters<T>) => {
    return new Promise((resolve) => {
      if (timer) clearTimeout(timer)
      if (resolveRef) resolveRef(undefined) // resolve previous with undefined

      resolveRef = resolve as (value: unknown) => void
      timer = setTimeout(async () => {
        const result = await fn(...args)
        resolveRef?.(result)
        resolveRef = null
      }, delay)
    })
  }
}

// ---------------------------------------------------------------------------
// Throttle — limit execution rate
// ---------------------------------------------------------------------------

/**
 * Throttle a function — execute at most once per `limit` ms.
 *
 * Use for: scroll, mousemove, GPS position updates, map rendering.
 *
 * @example
 * const throttledPan = throttle((coord) => updateMap(coord), 16) // 60fps
 */
export function throttle<T extends (...args: never[]) => void>(
  fn: T,
  limit: number = 16, // 16ms = 60fps
): (...args: Parameters<T>) => void {
  let inThrottle = false
  let lastArgs: Parameters<T> | null = null

  return (...args: Parameters<T>) => {
    if (!inThrottle) {
      fn(...args)
      inThrottle = true
      lastArgs = null

      setTimeout(() => {
        inThrottle = false
        if (lastArgs) {
          fn(...lastArgs)
          lastArgs = null
        }
      }, limit)
    } else {
      lastArgs = args
    }
  }
}

/**
 * Throttle using requestAnimationFrame — for smooth visual updates.
 *
 * Use for: map cursor, drawing, canvas rendering.
 */
export function rafThrottle<T extends (...args: never[]) => void>(
  fn: T,
): (...args: Parameters<T>) => void {
  let ticking = false
  let lastArgs: Parameters<T> | null = null

  return (...args: Parameters<T>) => {
    lastArgs = args
    if (!ticking) {
      requestAnimationFrame(() => {
        if (lastArgs) fn(...lastArgs)
        ticking = false
      })
      ticking = true
    }
  }
}

// ---------------------------------------------------------------------------
// Memoize — cache expensive function results
// ---------------------------------------------------------------------------

/**
 * Memoize a function — cache results by argument values.
 *
 * Use for: area calculations, bearing computations, coordinate transforms.
 *
 * @example
 * const memoizedArea = memoize(computeArea)
 * memoizedArea(vertices) // computed
 * memoizedArea(vertices) // cached (same vertices reference)
 */
export function memoize<T extends (...args: never[]) => unknown>(
  fn: T,
  options?: {
    maxSize?: number       // max cache entries (default: 100)
    keyFn?: (...args: Parameters<T>) => string  // custom key function
  },
): T {
  const cache = new Map<string, unknown>()
  const maxSize = options?.maxSize ?? 100
  const keyFn = options?.keyFn ?? ((...args: never[]) => JSON.stringify(args))

  const memoized = (...args: Parameters<T>) => {
    const key = keyFn(...args)

    if (cache.has(key)) {
      return cache.get(key)
    }

    const result = fn(...args)

    // Evict oldest entry if cache is full (LRU)
    if (cache.size >= maxSize) {
      const firstKey = cache.keys().next().value as string
      if (firstKey) cache.delete(firstKey)
    }

    cache.set(key, result)
    return result
  }

  return memoized as T
}

/**
 * Memoize with a time-to-live — cache expires after `ttl` ms.
 *
 * Use for: API responses, coordinate transforms that might change.
 */
export function memoizeTTL<T extends (...args: never[]) => unknown>(
  fn: T,
  ttl: number = 60000, // 1 minute default
  keyFn?: (...args: Parameters<T>) => string,
): T {
  const cache = new Map<string, { value: unknown; expires: number }>()
  const getKey = keyFn ?? ((...args: never[]) => JSON.stringify(args))

  return ((...args: Parameters<T>) => {
    const key = getKey(...args)
    const now = Date.now()

    const cached = cache.get(key)
    if (cached && cached.expires > now) {
      return cached.value
    }

    const result = fn(...args)
    cache.set(key, { value: result, expires: now + ttl })
    return result
  }) as T
}

// ---------------------------------------------------------------------------
// Chunked Processing — avoid blocking UI on large arrays
// ---------------------------------------------------------------------------

/**
 * Process a large array in chunks, yielding to the event loop between chunks.
 *
 * Use for: batch parcel import, large CSV parsing, point cloud processing.
 *
 * @example
 * for await (const chunk of chunkedProcess(largeArray, 100)) {
 *   processChunk(chunk)
 * }
 */
export async function* chunkedProcess<T>(
  array: T[],
  chunkSize: number = 100,
): AsyncGenerator<T[]> {
  for (let i = 0; i < array.length; i += chunkSize) {
    const chunk = array.slice(i, i + chunkSize)
    yield chunk
    // Yield to event loop so UI can update
    await new Promise(resolve => setTimeout(resolve, 0))
  }
}

/**
 * Process a large array with a progress callback.
 *
 * @example
 * await processWithProgress(
 *   parcels,
 *   (chunk) => importParcels(chunk),
 *   (progress) => setProgress(progress)
 * )
 */
export async function processWithProgress<T, R>(
  array: T[],
  processor: (chunk: T[]) => Promise<R>,
  onProgress: (progress: number) => void,
  chunkSize: number = 100,
): Promise<R[]> {
  const results: R[] = []
  const total = array.length

  for (let i = 0; i < total; i += chunkSize) {
    const chunk = array.slice(i, i + chunkSize)
    const result = await processor(chunk)
    results.push(result)
    onProgress(((i + chunk.length) / total) * 100)
    await new Promise(resolve => setTimeout(resolve, 0))
  }

  return results
}

// ---------------------------------------------------------------------------
// Lazy Evaluation — only compute when accessed
// ---------------------------------------------------------------------------

/**
 * Create a lazy value — computed once on first access, then cached.
 *
 * @example
 * const heavyConfig = lazy(() => buildConfigFromDB())
 * // Not computed yet
 * const config = heavyConfig() // Computed now, cached for next call
 */
export function lazy<T>(factory: () => T): () => T {
  let cached: T | undefined
  let computed = false

  return () => {
    if (!computed) {
      cached = factory()
      computed = true
    }
    return cached as T
  }
}

// ---------------------------------------------------------------------------
// Binary Search — O(log n) search in sorted arrays
// ---------------------------------------------------------------------------

/**
 * Binary search in a sorted array. Returns index of target, or -1.
 *
 * Use for: searching sorted coordinate arrays, beacon lists, time-series.
 *
 * @example
 * const idx = binarySearch(sortedBeacons, beacon => beacon.easting - targetE)
 */
export function binarySearch<T>(
  array: T[],
  compare: (item: T) => number, // negative = target is before, 0 = found, positive = after
): number {
  let left = 0
  let right = array.length - 1

  while (left <= right) {
    const mid = Math.floor((left + right) / 2)
    const cmp = compare(array[mid])

    if (cmp === 0) return mid
    if (cmp < 0) left = mid + 1
    else right = mid - 1
  }

  return -1
}

// ---------------------------------------------------------------------------
// Spatial Index — R-tree-lite for fast nearest-neighbor queries
// ---------------------------------------------------------------------------

/**
 * Simple spatial index using grid bucketing.
 *
 * For small-to-medium datasets (<10K points), this is faster than
 * a full R-tree implementation and has zero dependencies.
 *
 * @example
 * const index = new SpatialIndex()
 * index.add({ x: 534850, y: 9574220, data: beacon })
 * const nearest = index.findNearest(534851, 9574221, 5) // within 5m
 */
export class SpatialIndex<T> {
  private grid: Map<string, Array<{ x: number; y: number; data: T }>> = new Map()
  private cellSize: number

  constructor(cellSize: number = 100) {
    this.cellSize = cellSize
  }

  add(point: { x: number; y: number; data: T }): void {
    const key = this.getCellKey(point.x, point.y)
    if (!this.grid.has(key)) {
      this.grid.set(key, [])
    }
    this.grid.get(key)!.push(point)
  }

  findNearest(x: number, y: number, maxResults: number = 10, maxDistance?: number): Array<{ x: number; y: number; data: T; distance: number }> {
    const results: Array<{ x: number; y: number; data: T; distance: number }> = []

    // Search in expanding rings of cells
    const maxRing = maxDistance ? Math.ceil(maxDistance / this.cellSize) : 3

    for (let ring = 0; ring <= maxRing; ring++) {
      const cells = this.getCellsInRing(x, y, ring)

      for (const cellKey of cells) {
        const cellPoints = this.grid.get(cellKey)
        if (!cellPoints) continue

        for (const point of cellPoints) {
          const dx = point.x - x
          const dy = point.y - y
          const distance = Math.sqrt(dx * dx + dy * dy)

          if (maxDistance && distance > maxDistance) continue

          results.push({ ...point, distance })
        }
      }

      // If we have enough results, sort and return
      if (results.length >= maxResults) break
    }

    results.sort((a, b) => a.distance - b.distance)
    return results.slice(0, maxResults)
  }

  findInRadius(x: number, y: number, radius: number): Array<{ x: number; y: number; data: T; distance: number }> {
    return this.findNearest(x, y, Infinity, radius)
  }

  clear(): void {
    this.grid.clear()
  }

  get size(): number {
    let count = 0
    for (const cell of this.grid.values()) {
      count += cell.length
    }
    return count
  }

  private getCellKey(x: number, y: number): string {
    const cx = Math.floor(x / this.cellSize)
    const cy = Math.floor(y / this.cellSize)
    return `${cx},${cy}`
  }

  private getCellsInRing(x: number, y: number, ring: number): string[] {
    if (ring === 0) return [this.getCellKey(x, y)]

    const cells: string[] = []
    const cx = Math.floor(x / this.cellSize)
    const cy = Math.floor(y / this.cellSize)

    for (let dx = -ring; dx <= ring; dx++) {
      for (let dy = -ring; dy <= ring; dy++) {
        if (Math.abs(dx) === ring || Math.abs(dy) === ring) {
          cells.push(`${cx + dx},${cy + dy}`)
        }
      }
    }

    return cells
  }
}

// ---------------------------------------------------------------------------
// React Hooks
// ---------------------------------------------------------------------------

/**
 * useDebounce — React hook for debounced values.
 *
 * @example
 * const [query, setQuery] = useState('')
 * const debouncedQuery = useDebounceValue(query, 300)
 * useEffect(() => { search(debouncedQuery) }, [debouncedQuery])
 */
export function useDebounceValue<T>(value: T, delay: number = 300): T {
  const [debounced, setDebounced] = useState<T>(value)

  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delay)
    return () => clearTimeout(timer)
  }, [value, delay])

  return debounced
}

/**
 * useDebouncedCallback — React hook for debounced function calls.
 */
export function useDebouncedCallback<T extends (...args: never[]) => void>(
  callback: T,
  delay: number = 300,
): (...args: Parameters<T>) => void {
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const callbackRef = useRef(callback)

  useEffect(() => {
    callbackRef.current = callback
  }, [callback])

  useEffect(() => {
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current)
    }
  }, [])

  return useCallback((...args: Parameters<T>) => {
    if (timerRef.current) clearTimeout(timerRef.current)
    timerRef.current = setTimeout(() => callbackRef.current(...args), delay)
  }, [delay])
}

/**
 * useThrottledCallback — React hook for throttled function calls.
 */
export function useThrottledCallback<T extends (...args: never[]) => void>(
  callback: T,
  limit: number = 16,
): (...args: Parameters<T>) => void {
  const lastRunRef = useRef(0)
  const callbackRef = useRef(callback)

  useEffect(() => {
    callbackRef.current = callback
  }, [callback])

  return useCallback((...args: Parameters<T>) => {
    const now = Date.now()
    if (now - lastRunRef.current >= limit) {
      callbackRef.current(...args)
      lastRunRef.current = now
    }
  }, [limit])
}

// ---------------------------------------------------------------------------
// React imports (conditional — only if React is available)
// ---------------------------------------------------------------------------

// These imports are at the bottom to keep the file tree-shakeable
// for non-React contexts (Node.js, web workers).
import { useState, useEffect, useRef, useCallback } from 'react'

/**
 * METARDU — Contour SVG Renderer
 * Renders contour lines from Python engine output (/api/compute/contours)
 * into SVG elements for the topographic plan.
 *
 * Source: Ghilani & Wolf, Elementary Surveying 16th Ed. (Pearson 2021), Chapter 17
 *         Survey of Kenya — Standard Symbols for Topographic Plans
 *
 * Line weight levels (Brief 12):
 *   INDEX contour   → 0.35mm stroke (heavy)
 *   FORM contour    → 0.18mm stroke (light)
 *   Spot heights    → 0.13mm text
 *   Formline        → 0.13mm dashed (supplementary half-interval)
 */

// Contour types - Python API returns { contours: ContourLine[], spotHeights: SpotHeight[], interval: number }
interface ContourLine {
  elevation: number
  isIndex: boolean
  points: Array<{ x: number; y: number }>
}

export interface SpotHeight {
  x: number
  y: number
  z: number
  label?: string
}

export interface ContourResult {
  interval_m: number
  extent?: {
    x_min: number
    x_max: number
    y_min: number
    y_max: number
  }
  contours: Array<{
    elevation: number
    is_index: boolean
    segments: Segment[]
  }>
  spot_heights: SpotHeight[]
}

// ─────────────────────────────────────────────────────────────────────────────
// LINE WEIGHT CONSTANTS — Brief 12
// Source: Survey of Kenya Topographic Plan Standards
// Four levels as specified
// ─────────────────────────────────────────────────────────────────────────────

export const LINE_WEIGHTS = {
  INDEX_CONTOUR:  0.35,   // mm — every 5th contour, labelled
  FORM_CONTOUR:   0.18,   // mm — intermediate contours
  FORMLINE:       0.13,   // mm — supplementary (dashed, half-interval)
  SPOT_HEIGHT:    0.13,   // mm — spot height text and tick mark
  BOUNDARY:       0.50,   // mm — survey/property boundary
  ROAD:           0.25,   // mm — road/track
  WATER:          0.20,   // mm — watercourse / drainage
  BUILDING:       0.25,   // mm — structure outline
} as const;

// px per mm at standard plan scale (1:1000 default, 96 dpi)
// Adjust scaleFactor when rendering at different plan scales
function mmToPx(mm: number, scaleFactor = 1): number {
  return mm * 3.7795275591 * scaleFactor;
}

// ─────────────────────────────────────────────────────────────────────────────
// WORLD → SVG COORDINATE TRANSFORM
// ─────────────────────────────────────────────────────────────────────────────

export interface ViewTransform {
  x_min: number;
  x_max: number;
  y_min: number;
  y_max: number;
  svg_width: number;
  svg_height: number;
  margin: number;
}

export function worldToSvg(
  wx: number,
  wy: number,
  t: ViewTransform
): [number, number] {
  const usable_w = t.svg_width  - 2 * t.margin;
  const usable_h = t.svg_height - 2 * t.margin;
  const world_w  = t.x_max - t.x_min;
  const world_h  = t.y_max - t.y_min;

  const sx = t.margin + ((wx - t.x_min) / world_w) * usable_w;
  // SVG Y-axis is inverted relative to survey Y (North = up)
  const sy = t.margin + ((t.y_max - wy) / world_h) * usable_h;

  return [sx, sy];
}

// ─────────────────────────────────────────────────────────────────────────────
// SEGMENT CHAIN BUILDER
// Joins adjacent segments into polylines (chains) for cleaner SVG output
// and correct label placement.
// ─────────────────────────────────────────────────────────────────────────────

type Segment = [[number, number], [number, number]];
type Chain   = [number, number][];

function buildChains(segments: Segment[]): Chain[] {
  if (!segments.length) return [];

  // Build adjacency: endpoint → segment index
  const tolerance = 1e-4;

  const chains: Chain[] = [];
  const used = new Set<number>();

  for (let start = 0; start < segments.length; start++) {
    if (used.has(start)) continue;

    const chain: Chain = [...segments[start]];
    used.add(start);

    let extended = true;
    while (extended) {
      extended = false;
      const tail = chain[chain.length - 1];

      for (let i = 0; i < segments.length; i++) {
        if (used.has(i)) continue;
        const [a, b] = segments[i];

        if (Math.abs(a[0] - tail[0]) < tolerance && Math.abs(a[1] - tail[1]) < tolerance) {
          chain.push(b);
          used.add(i);
          extended = true;
          break;
        }
        if (Math.abs(b[0] - tail[0]) < tolerance && Math.abs(b[1] - tail[1]) < tolerance) {
          chain.push(a);
          used.add(i);
          extended = true;
          break;
        }
      }
    }
    chains.push(chain);
  }

  return chains;
}

// ─────────────────────────────────────────────────────────────────────────────
// CONTOUR LABEL PLACEMENT
// Places elevation label at the midpoint of the longest chain segment.
// Source: Ghilani & Wolf Ch.17 — contour labelling conventions
// ─────────────────────────────────────────────────────────────────────────────

function contourLabelPath(chain: Chain, t: ViewTransform): { x: number; y: number; angle: number } | null {
  if (chain.length < 2) return null;

  // Find the longest segment in the chain for label placement
  let maxLen = 0;
  let bestIdx = 0;

  for (let i = 0; i < chain.length - 1; i++) {
    const [ax, ay] = worldToSvg(chain[i][0],   chain[i][1],   t);
    const [bx, by] = worldToSvg(chain[i+1][0], chain[i+1][1], t);
    const len = Math.hypot(bx - ax, by - ay);
    if (len > maxLen) { maxLen = len; bestIdx = i; }
  }

  if (maxLen < 40) return null; // Too short to label

  const [ax, ay] = worldToSvg(chain[bestIdx][0],   chain[bestIdx][1],   t);
  const [bx, by] = worldToSvg(chain[bestIdx+1][0], chain[bestIdx+1][1], t);

  const mx = (ax + bx) / 2;
  const my = (ay + by) / 2;
  let angle = Math.atan2(by - ay, bx - ax) * (180 / Math.PI);

  // Keep text readable (never upside down)
  if (angle > 90 || angle < -90) angle += 180;

  return { x: mx, y: my, angle };
}

// ─────────────────────────────────────────────────────────────────────────────
// RENDER CONTOUR LINES TO SVG STRING
// ─────────────────────────────────────────────────────────────────────────────

export interface ContourRenderOptions {
  transform: ViewTransform;
  scaleFactor?: number;
  labelIndexContours?: boolean;
  contourColor?: string;
  indexContourColor?: string;
}

export function renderContoursToSvg(
  data: ContourResult,
  options: ContourRenderOptions
): string {
  const {
    transform: t,
    scaleFactor = 1,
    labelIndexContours = true,
    contourColor = '#8B7355',
    indexContourColor = '#5C4A2A',
  } = options;

  const lines: string[] = [];
  const labels: string[] = [];

  lines.push(`<g id="contours" data-interval="${data.interval_m}">`);

  for (const contour of data.contours) {
    const isIndex    = contour.is_index;
    const strokeW    = mmToPx(isIndex ? LINE_WEIGHTS.INDEX_CONTOUR : LINE_WEIGHTS.FORM_CONTOUR, scaleFactor);
    const stroke     = isIndex ? indexContourColor : contourColor;
    const opacity    = isIndex ? '0.9' : '0.65';

    const chains = buildChains(contour.segments as Segment[]);

    for (const chain of chains) {
      if (chain.length < 2) continue;

      // Build SVG polyline points
      const pts = chain
        .map(([wx, wy]) => {
          const [sx, sy] = worldToSvg(wx, wy, t);
          return `${sx.toFixed(2)},${sy.toFixed(2)}`;
        })
        .join(' ');

      lines.push(
        `<polyline points="${pts}" fill="none" stroke="${stroke}" ` +
        `stroke-width="${strokeW.toFixed(3)}" opacity="${opacity}" ` +
        `stroke-linecap="round" stroke-linejoin="round"/>`
      );

      // Label index contours
      if (isIndex && labelIndexContours) {
        const labelPos = contourLabelPath(chain, t);
        if (labelPos) {
          const fontSize = mmToPx(1.4, scaleFactor);
          labels.push(
            `<text x="${labelPos.x.toFixed(2)}" y="${labelPos.y.toFixed(2)}" ` +
            `transform="rotate(${labelPos.angle.toFixed(1)},${labelPos.x.toFixed(2)},${labelPos.y.toFixed(2)})" ` +
            `text-anchor="middle" dominant-baseline="middle" ` +
            `font-family="Arial Narrow,Arial,sans-serif" font-size="${fontSize.toFixed(2)}" ` +
            `fill="${indexContourColor}" stroke="white" stroke-width="${(fontSize * 0.25).toFixed(2)}" ` +
            `paint-order="stroke fill">${contour.elevation.toFixed(1)}</text>`
          );
        }
      }
    }
  }

  lines.push('</g>');
  if (labels.length) {
    lines.push('<g id="contour-labels">');
    lines.push(...labels);
    lines.push('</g>');
  }

  return lines.join('\n');
}

// ─────────────────────────────────────────────────────────────────────────────
// RENDER SPOT HEIGHTS TO SVG
// Source: Ghilani & Wolf Ch.17 — spot height symbols on plans
// Symbol: small cross (+) with elevation label to the right
// ─────────────────────────────────────────────────────────────────────────────

export function renderSpotHeightsToSvg(
  points: SpotHeight[],
  transform: ViewTransform,
  scaleFactor = 1,
  color = '#3A3A3A'
): string {
  const lines: string[] = ['<g id="spot-heights">'];
  const tickSize  = mmToPx(1.0, scaleFactor);
  const fontSize  = mmToPx(1.2, scaleFactor);
  const strokeW   = mmToPx(LINE_WEIGHTS.SPOT_HEIGHT, scaleFactor);

  for (const pt of points) {
    const [sx, sy] = worldToSvg(pt.x, pt.y, transform);
    const label = pt.label ? `${pt.label} (${pt.z.toFixed(3)}m)` : `${pt.z.toFixed(3)}`;

    // Cross symbol
    lines.push(
      `<line x1="${(sx - tickSize).toFixed(2)}" y1="${sy.toFixed(2)}" ` +
      `x2="${(sx + tickSize).toFixed(2)}" y2="${sy.toFixed(2)}" ` +
      `stroke="${color}" stroke-width="${strokeW.toFixed(3)}"/>`,

      `<line x1="${sx.toFixed(2)}" y1="${(sy - tickSize).toFixed(2)}" ` +
      `x2="${sx.toFixed(2)}" y2="${(sy + tickSize).toFixed(2)}" ` +
      `stroke="${color}" stroke-width="${strokeW.toFixed(3)}"/>`,

      // Elevation label to the right and slightly above
      `<text x="${(sx + tickSize + 1.5).toFixed(2)}" y="${(sy - 1.5).toFixed(2)}" ` +
      `font-family="Arial Narrow,Arial,sans-serif" font-size="${fontSize.toFixed(2)}" ` +
      `fill="${color}" dominant-baseline="auto">${label}</text>`
    );
  }

  lines.push('</g>');
  return lines.join('\n');
}

/**
 * METARDU — Topographic Plan Renderer
 * Master renderer for Brief 12 topographic plan improvements.
 *
 * Composes:
 *   - Contour lines (from Python engine output)
 *   - Spot height labels
 *   - Survey of Kenya standard feature symbols
 *   - Four line weight levels
 *   - Dimension leader lines for internal measurements
 *   - Grid / graticule
 *   - North arrow
 *   - Title block (Survey Act Cap 299 compliant)
 *   - Digital signature verification block (Phase 2)
 *
 * Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Ch.17
 *         Survey of Kenya Standard Symbols
 *         Survey Act Cap 299 (Revised 2022)
 *         Survey Regulations 1994
 */

import type { ContourResult, SpotHeight }    from './contourRenderer';
import { renderContoursToSvg, renderSpotHeightsToSvg, type ViewTransform } from './contourRenderer';
import { buildSymbolDefs, renderSymbol, type SurveySymbol }                from './surveySymbols';
import { buildLineWeightLegend, LINE_STYLES, svgStrokeAttrs, lineWeightPx } from './lineWeights';
import { buildArrowDefs, renderLinearDimension, renderLeaderLine }          from './dimensionLeaders';
import type { SignatureRecord }               from '@/lib/integrations/digitalSignature';
import { buildVerificationBlock }             from '@/lib/integrations/digitalSignature';

const MM_TO_PX = 3.7795275591;
function mm(val: number, sf = 1): number { return val * MM_TO_PX * sf; }

// ─────────────────────────────────────────────────────────────────────────────
// PLAN OPTIONS
// ─────────────────────────────────────────────────────────────────────────────

export interface TopographicPlanOptions {
  // Plan metadata
  title:            string;
  drawnBy:          string;
  checkedBy?:       string;
  scale:            string;          // e.g. '1:1000'
  date:             string;
  drawingNo?:       string;
  client?:          string;
  project?:         string;
  datum:            string;          // e.g. 'ARC1960 / UTM Zone 37S (EPSG:21037)'
  county?:          string;

  // SVG canvas
  svgWidth?:        number;          // px
  svgHeight?:       number;          // px
  margin?:          number;          // px
  scaleFactor?:     number;

  // Data layers (all optional)
  contours?:        ContourResult;
  spotHeights?:     SpotHeight[];
  featurePoints?:   FeaturePoint[];
  dimensions?:      DimensionSpec[];
  leaders?:         LeaderSpec[];
  boundaries?:      BoundaryChain[];

  // Signature (Phase 2)
  signature?:       SignatureRecord;

  // Display options
  showGrid?:        boolean;
  showNorthArrow?:  boolean;
  showLegend?:      boolean;
  showScaleBar?:    boolean;
  contourInterval?: number;
}

export interface FeaturePoint {
  x: number; y: number;
  symbolId: string;
  label?: string;
  rotation?: number;
}

export interface DimensionSpec {
  x1: number; y1: number;
  x2: number; y2: number;
  label?: string;
  offset?: number;
}

export interface LeaderSpec {
  featureX: number; featureY: number;
  labelX: number;   labelY: number;
  label: string;
  subLabel?: string;
}

export interface BoundaryChain {
  points: [number, number][];  // world coords (E, N)
  closed?: boolean;
  styleKey?: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// NORTH ARROW
// ─────────────────────────────────────────────────────────────────────────────

function renderNorthArrow(x: number, y: number, sf = 1): string {
  const h  = mm(12, sf);
  const hw = mm(3,  sf);
  const fontSize = mm(3, sf).toFixed(2);

  return `
<g id="north-arrow" transform="translate(${x},${y})">
  <!-- Arrow shaft -->
  <line x1="0" y1="${h/2}" x2="0" y2="${-h/2}" stroke="#000" stroke-width="${lineWeightPx(4, sf).toFixed(3)}"/>
  <!-- North half (filled) -->
  <polygon points="0,${-h/2} ${-hw},0 ${hw},0" fill="#000"/>
  <!-- South half (outline) -->
  <polygon points="0,${h/2} ${-hw},0 ${hw},0" fill="white" stroke="#000" stroke-width="${lineWeightPx(4, sf).toFixed(3)}"/>
  <!-- N label -->
  <text x="0" y="${(-h/2 - mm(2, sf))}" text-anchor="middle" font-family="Arial,sans-serif" font-size="${fontSize}" font-weight="bold" fill="#000">N</text>
</g>`;
}

// ─────────────────────────────────────────────────────────────────────────────
// SCALE BAR
// ─────────────────────────────────────────────────────────────────────────────

function renderScaleBar(x: number, y: number, scaleString: string, sf = 1): string {
  const barW  = mm(40, sf);
  const barH  = mm(2.5, sf);
  const ticks = 4;
  const tickW = barW / ticks;
  const fontSize = mm(2.2, sf).toFixed(2);
  const sw = lineWeightPx(4, sf).toFixed(3);

  const parts: string[] = [`<g id="scale-bar" transform="translate(${x},${y})">`];

  for (let i = 0; i < ticks; i++) {
    const fill = i % 2 === 0 ? '#000' : '#fff';
    parts.push(
      `<rect x="${(i * tickW).toFixed(2)}" y="0" width="${tickW.toFixed(2)}" height="${barH.toFixed(2)}" fill="${fill}" stroke="#000" stroke-width="${sw}"/>`
    );
  }

  // Scale label
  parts.push(
    `<text x="${(barW / 2).toFixed(2)}" y="${(barH + mm(4, sf)).toFixed(2)}" text-anchor="middle" ` +
    `font-family="Arial,sans-serif" font-size="${fontSize}" fill="#000">Scale ${scaleString}</text>`
  );

  parts.push('</g>');
  return parts.join('\n');
}

// ─────────────────────────────────────────────────────────────────────────────
// TITLE BLOCK
// Survey Act Cap 299 compliant
// ─────────────────────────────────────────────────────────────────────────────

function renderTitleBlock(opts: TopographicPlanOptions, svgW: number, svgH: number, sf = 1): string {
  const margin    = opts.margin ?? mm(10, sf);
  const tbH       = mm(40, sf);
  const tbW       = svgW - 2 * margin;
  const tbY       = svgH - margin - tbH;
  const tbX       = margin;
  const bw        = lineWeightPx(1, sf).toFixed(3);
  const lw        = lineWeightPx(4, sf).toFixed(3);
  const titleSize = mm(5, sf).toFixed(2);
  const bodySize  = mm(2.8, sf).toFixed(2);
  const labelSize = mm(2.0, sf).toFixed(2);

  const col2X = tbX + mm(80, sf);
  const col3X = tbX + mm(140, sf);

  return `
<g id="title-block">
  <!-- Outer border -->
  <rect x="${tbX.toFixed(2)}" y="${tbY.toFixed(2)}" width="${tbW.toFixed(2)}" height="${tbH.toFixed(2)}" fill="white" stroke="#000" stroke-width="${bw}"/>
  
  <!-- Vertical dividers -->
  <line x1="${col2X.toFixed(2)}" y1="${tbY.toFixed(2)}" x2="${col2X.toFixed(2)}" y2="${(tbY + tbH).toFixed(2)}" stroke="#000" stroke-width="${lw}"/>
  <line x1="${col3X.toFixed(2)}" y1="${tbY.toFixed(2)}" x2="${col3X.toFixed(2)}" y2="${(tbY + tbH).toFixed(2)}" stroke="#000" stroke-width="${lw}"/>

  <!-- Column 1: Title, Client, Project -->
  <text x="${(tbX + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(10, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${titleSize}" font-weight="bold" fill="#000">${opts.title}</text>
  <text x="${(tbX + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(17, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">CLIENT</text>
  <text x="${(tbX + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(21, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${bodySize}" fill="#000">${opts.client ?? '—'}</text>
  <text x="${(tbX + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(27, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">PROJECT</text>
  <text x="${(tbX + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(31, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${bodySize}" fill="#000">${opts.project ?? '—'}</text>
  <text x="${(tbX + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(38, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">${opts.datum}</text>

  <!-- Column 2: Drawing details -->
  <text x="${(col2X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(8, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">DRAWN BY</text>
  <text x="${(col2X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(12, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${bodySize}" fill="#000">${opts.drawnBy}</text>
  <text x="${(col2X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(18, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">CHECKED BY</text>
  <text x="${(col2X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(22, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${bodySize}" fill="#000">${opts.checkedBy ?? '—'}</text>
  <text x="${(col2X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(28, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">DATE</text>
  <text x="${(col2X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(32, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${bodySize}" fill="#000">${opts.date}</text>
  <text x="${(col2X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(38, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">COUNTY: ${opts.county ?? '—'}</text>

  <!-- Column 3: Scale, Drawing No -->
  <text x="${(col3X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(8, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">SCALE</text>
  <text x="${(col3X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(13, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${(mm(4.5, sf)).toFixed(2)}" font-weight="bold" fill="#000">${opts.scale}</text>
  <text x="${(col3X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(20, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#666">DRAWING NO.</text>
  <text x="${(col3X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(25, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${bodySize}" fill="#000">${opts.drawingNo ?? '—'}</text>
  <text x="${(col3X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(32, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#555">Prepared by METARDU</text>
  <text x="${(col3X + mm(4, sf)).toFixed(2)}" y="${(tbY + mm(37, sf)).toFixed(2)}" font-family="Arial,sans-serif" font-size="${labelSize}" fill="#777">Survey Act Cap 299 | Regs 1994</text>

</g>`;
}

// ─────────────────────────────────────────────────────────────────────────────
// GRID
// ─────────────────────────────────────────────────────────────────────────────

function renderGrid(t: ViewTransform, sf = 1): string {
  const strokeAttr = svgStrokeAttrs('grid_line', sf);
  const lines: string[] = ['<g id="grid" opacity="0.4">'];

  const usableW = t.svg_width  - 2 * t.margin;
  const usableH = t.svg_height - 2 * t.margin;
  const gridPx  = mm(20, sf); // grid spacing in px

  for (let x = t.margin; x <= t.margin + usableW; x += gridPx) {
    lines.push(`<line x1="${x.toFixed(1)}" y1="${t.margin}" x2="${x.toFixed(1)}" y2="${(t.margin + usableH).toFixed(1)}" ${strokeAttr}/>`);
  }
  for (let y = t.margin; y <= t.margin + usableH; y += gridPx) {
    lines.push(`<line x1="${t.margin}" y1="${y.toFixed(1)}" x2="${(t.margin + usableW).toFixed(1)}" y2="${y.toFixed(1)}" ${strokeAttr}/>`);
  }

  lines.push('</g>');
  return lines.join('\n');
}

// ─────────────────────────────────────────────────────────────────────────────
// MASTER RENDER FUNCTION
// ─────────────────────────────────────────────────────────────────────────────

export function renderTopographicPlan(opts: TopographicPlanOptions): string {
  const sf         = opts.scaleFactor ?? 1;
  const svgW       = opts.svgWidth    ?? mm(297, sf);   // A4 landscape width
  const svgH       = opts.svgHeight   ?? mm(210, sf);   // A4 landscape height
  const margin     = opts.margin      ?? mm(12, sf);

  const titleBlockH = mm(42, sf);
  const drawAreaH   = svgH - margin - titleBlockH - margin;

  // Build view transform
  const contourExtent = opts.contours?.extent
  const t: ViewTransform = {
    x_min:      contourExtent?.x_min ?? 0,
    x_max:      contourExtent?.x_max ?? 1000,
    y_min:      contourExtent?.y_min ?? 0,
    y_max:      contourExtent?.y_max ?? 1000,
    svg_width:  svgW,
    svg_height: svgH - titleBlockH,
    margin,
  };

  // Expand extent from spot heights if no contours
  if (!opts.contours && opts.spotHeights?.length) {
    t.x_min = Math.min(...opts.spotHeights.map((p: SpotHeight) => p.x));
    t.x_max = Math.max(...opts.spotHeights.map((p: SpotHeight) => p.x));
    t.y_min = Math.min(...opts.spotHeights.map((p: SpotHeight) => p.y));
    t.y_max = Math.max(...opts.spotHeights.map((p: SpotHeight) => p.y));
  }

  const parts: string[] = [];

  // SVG header
  parts.push(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${svgW}" height="${svgH}" viewBox="0 0 ${svgW} ${svgH}">`
  );

  // Defs
  parts.push('<defs>');
  parts.push(buildSymbolDefs());
  parts.push(buildArrowDefs(sf));
  parts.push('</defs>');

  // Background
  parts.push(`<rect width="${svgW}" height="${svgH}" fill="white"/>`);

  // Plan border
  const bw = lineWeightPx(1, sf).toFixed(3);
  parts.push(`<rect x="${margin}" y="${margin}" width="${(svgW - 2*margin).toFixed(2)}" height="${(svgH - 2*margin).toFixed(2)}" fill="none" stroke="#000" stroke-width="${bw}"/>`);

  // Drawing area clip
  const clipId = 'drawing-area-clip';
  parts.push(`<clipPath id="${clipId}"><rect x="${margin}" y="${margin}" width="${(svgW-2*margin).toFixed(2)}" height="${drawAreaH.toFixed(2)}"/></clipPath>`);
  parts.push(`<g clip-path="url(#${clipId})">`);

  // Grid
  if (opts.showGrid !== false) {
    parts.push(renderGrid(t, sf));
  }

  // Contour lines
  if (opts.contours) {
    parts.push(renderContoursToSvg(opts.contours, {
      transform: t,
      scaleFactor: sf,
      labelIndexContours: true,
    }));
  }

  // Spot heights
  if (opts.spotHeights?.length) {
    parts.push(renderSpotHeightsToSvg(opts.spotHeights, t, sf));
  }

  // Feature symbols
  if (opts.featurePoints?.length) {
    const symbolGroup: string[] = ['<g id="features">'];
    for (const fp of opts.featurePoints) {
      const [sx, sy] = [fp.x, fp.y]; // caller provides SVG coords for features
      symbolGroup.push(renderSymbol(fp.symbolId, sx, sy, {
        scaleFactor: sf,
        rotation: fp.rotation,
        label: fp.label,
      }));
    }
    symbolGroup.push('</g>');
    parts.push(symbolGroup.join('\n'));
  }

  // Boundaries
  if (opts.boundaries?.length) {
    const boundaryGroup: string[] = ['<g id="boundaries">'];
    for (const b of opts.boundaries) {
      if (b.points.length < 2) continue;
      const styleKey = (b.styleKey as keyof typeof LINE_STYLES) ?? 'survey_boundary';
      const strokeAttr = svgStrokeAttrs(styleKey, sf);
      const pts = b.points.map(([wx, wy]) => {
        const [sx, sy] = [wx, wy]; // world to SVG conversion handled upstream
        return `${sx.toFixed(2)},${sy.toFixed(2)}`;
      }).join(' ');
      const tag = b.closed ? 'polygon' : 'polyline';
      boundaryGroup.push(`<${tag} points="${pts}" fill="none" ${strokeAttr}/>`);
    }
    boundaryGroup.push('</g>');
    parts.push(boundaryGroup.join('\n'));
  }

  // Dimensions
  if (opts.dimensions?.length) {
    const dimGroup: string[] = ['<g id="dimensions">'];
    for (const d of opts.dimensions) {
      dimGroup.push(renderLinearDimension({ ...d, scaleFactor: sf }));
    }
    dimGroup.push('</g>');
    parts.push(dimGroup.join('\n'));
  }

  // Leader lines
  if (opts.leaders?.length) {
    const leaderGroup: string[] = ['<g id="leaders">'];
    for (const l of opts.leaders) {
      leaderGroup.push(renderLeaderLine({ ...l, scaleFactor: sf }));
    }
    leaderGroup.push('</g>');
    parts.push(leaderGroup.join('\n'));
  }

  parts.push('</g>'); // end clip

  // North arrow
  if (opts.showNorthArrow !== false) {
    parts.push(renderNorthArrow(svgW - margin - mm(15, sf), margin + mm(18, sf), sf));
  }

  // Scale bar
  if (opts.showScaleBar !== false) {
    parts.push(renderScaleBar(margin + mm(5, sf), svgH - margin - titleBlockH - mm(12, sf), opts.scale, sf));
  }

  // Line weight legend
  if (opts.showLegend !== false) {
    parts.push(buildLineWeightLegend(svgW - margin - mm(55, sf), margin + mm(5, sf), sf));
  }

  // Title block
  parts.push(renderTitleBlock(opts, svgW, svgH, sf));

  // Digital signature verification block (Phase 2) — below title block
  if (opts.signature) {
    const sigY = svgH - margin - mm(5, sf);
    const sigX = margin;
    parts.push(`<g transform="translate(${sigX},${sigY})">`);
    parts.push(buildVerificationBlock(opts.signature));
    parts.push('</g>');
  }

  parts.push('</svg>');
  return parts.join('\n');
}

/**
 * METARDU — Deed Plan / Boundary Identification Plan (BIP)
 *
 * Produces a Kenya Survey Regulations 1994-compliant A3 landscape deed plan
 * suitable for submission to the Director of Surveys.
 *
 * Layout: Left panel (parcel drawing) | Right panel (title block + schedules)
 *
 * References:
 *   Survey Act Cap 299, s.22 & s.28 (plan requirements)
 *   Survey Regulations 1994, Reg. 5 (plan format), Reg. 20 (beacon descriptions)
 *   Land Registration Act 2012, s.10 (title plan requirements)
 *   Basak, N.N. — Surveying and Levelling, Ch. 11 (traverse closure)
 */

import { openPrint } from './buildPrintDocument'
import type { DeedPlanInput, BoundaryPoint, BoundaryLeg } from '@/types/deedPlan'
import { computeBoundaryLegs, computeArea, computeClosureCheck } from '@/lib/compute/deedPlan'

// ── Types ─────────────────────────────────────────────────────────────────────

export interface DeedPlanPrintInput {
  input: DeedPlanInput
}

// ── Area conversions ──────────────────────────────────────────────────────────

function areaHa(sqm: number): string  { return (sqm / 10000).toFixed(4) }
function areaAcres(sqm: number): string { return (sqm / 4046.856).toFixed(4) }

function esc(value: string | number | undefined | null): string {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

function blank(value: string | number | undefined | null): string {
  const text = String(value ?? '').trim()
  return text ? esc(text) : '&mdash;'
}

// ── Parcel SVG drawing ────────────────────────────────────────────────────────

interface ScaledPoint { x: number; y: number; id: string; markType: string; markStatus: string }

function drawParcelSVG(points: BoundaryPoint[], legs: BoundaryLeg[], scale: number): string {
  if (points.length < 3) {
    return `<svg viewBox="0 0 600 500" xmlns="http://www.w3.org/2000/svg">
      <text x="300" y="250" text-anchor="middle" font-size="14" fill="#999">Add at least 3 boundary points</text>
    </svg>`
  }

  const PAD = 60
  const W = 580
  const H = 480

  const minE = Math.min(...points.map(p => p.easting))
  const maxE = Math.max(...points.map(p => p.easting))
  const minN = Math.min(...points.map(p => p.northing))
  const maxN = Math.max(...points.map(p => p.northing))

  const rangeE = maxE - minE || 1
  const rangeN = maxN - minN || 1

  const scaleX = (W - PAD * 2) / rangeE
  const scaleY = (H - PAD * 2) / rangeN
  const s = Math.min(scaleX, scaleY)

  // Centre the drawing
  const drawW = rangeE * s
  const drawH = rangeN * s
  const offX = (W - drawW) / 2
  const offY = (H - drawH) / 2

  // N is up in surveying — invert Y axis
  const toX = (e: number) => offX + (e - minE) * s
  const toY = (n: number) => H - offY - (n - minN) * s

  const scaled: ScaledPoint[] = points.map(p => ({
    x: toX(p.easting),
    y: toY(p.northing),
    id: esc(p.id),
    markType: p.markType,
    markStatus: p.markStatus,
  }))

  // Polygon outline
  const polyPoints = scaled.map(p => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ')

  // Hatching definition for parcel fill
  const hatch = `
  <defs>
    <pattern id="hatch" patternUnits="userSpaceOnUse" width="8" height="8" patternTransform="rotate(45)">
      <line x1="0" y1="0" x2="0" y2="8" stroke="#c8d8e8" stroke-width="0.5"/>
    </pattern>
  </defs>`

  // Polygon
  const polygon = `<polygon points="${polyPoints}" fill="url(#hatch)" stroke="#000" stroke-width="1.5" stroke-linejoin="round"/>`

  // Beacon symbols at each point
  const beaconSymbols = scaled.map(p => {
    const isMasonry = p.markType === 'MASONRY_NAIL' || p.markType === 'RIVET'
    const isControl = p.markType === 'PSC' || p.markType === 'SSC' || p.markType === 'TSC'
    const r = isControl ? 5 : 4

    if (isMasonry) {
      return `<circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="2.5" fill="#000" stroke="#000" stroke-width="0.5"/>
<line x1="${(p.x-5).toFixed(1)}" y1="${p.y.toFixed(1)}" x2="${(p.x+5).toFixed(1)}" y2="${p.y.toFixed(1)}" stroke="#000" stroke-width="0.8"/>
<line x1="${p.x.toFixed(1)}" y1="${(p.y-5).toFixed(1)}" x2="${p.x.toFixed(1)}" y2="${(p.y+5).toFixed(1)}" stroke="#000" stroke-width="0.8"/>`
    }
    if (isControl) {
      return `<polygon points="${p.x.toFixed(1)},${(p.y-r-2).toFixed(1)} ${(p.x+r).toFixed(1)},${(p.y+r).toFixed(1)} ${(p.x-r).toFixed(1)},${(p.y+r).toFixed(1)}" fill="none" stroke="#000" stroke-width="1.2"/>`
    }
    // Default: square for concrete beacon, circle for iron pin
    if (p.markType === 'CONCRETE_BEACON') {
      return `<rect x="${(p.x - r).toFixed(1)}" y="${(p.y - r).toFixed(1)}" width="${(r*2).toFixed(1)}" height="${(r*2).toFixed(1)}" fill="white" stroke="#000" stroke-width="1.2"/>`
    }
    return `<circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="${r}" fill="white" stroke="#000" stroke-width="1.2"/>`
  }).join('\n')

  // Point labels
  const labels = scaled.map((p, i) => {
    const centX = scaled.reduce((a, b) => a + b.x, 0) / scaled.length
    const centY = scaled.reduce((a, b) => a + b.y, 0) / scaled.length
    const dx = p.x - centX
    const dy = p.y - centY
    const len = Math.sqrt(dx*dx + dy*dy) || 1
    const ox = (dx/len) * 14
    const oy = (dy/len) * 14
    return `<text x="${(p.x + ox).toFixed(1)}" y="${(p.y + oy + 3).toFixed(1)}" text-anchor="middle" font-size="9" font-family="Courier New, monospace" font-weight="bold" fill="#000">${p.id}</text>`
  }).join('\n')

  // Bearing & distance labels on each leg
  const legLabels = legs.map((leg, i) => {
    const from = scaled.find(p => p.id === leg.fromPoint)
    const to   = scaled.find(p => p.id === leg.toPoint)
    if (!from || !to) return ''

    const mx = (from.x + to.x) / 2
    const my = (from.y + to.y) / 2
    const dx = to.x - from.x
    const dy = to.y - from.y
    const len = Math.sqrt(dx*dx + dy*dy) || 1
    // Perpendicular offset (outward from centroid)
    const centX = scaled.reduce((a, b) => a + b.x, 0) / scaled.length
    const centY = scaled.reduce((a, b) => a + b.y, 0) / scaled.length
    const pcx = mx - centX
    const pcy = my - centY
    const plen = Math.sqrt(pcx*pcx + pcy*pcy) || 1
    const ox = (pcx/plen) * 18
    const oy = (pcy/plen) * 18

    // Rotation angle for label
    let angle = Math.atan2(dy, dx) * 180 / Math.PI
    if (angle > 90) angle -= 180
    if (angle < -90) angle += 180

    // Only show on legs long enough to label (> 30px)
    if (len < 30) {
      return `<text x="${(mx+ox).toFixed(1)}" y="${(my+oy).toFixed(1)}" text-anchor="middle" font-size="7" font-family="Courier New, monospace" fill="#333">${leg.distance.toFixed(2)}m</text>`
    }

    return `<g transform="translate(${(mx+ox).toFixed(1)},${(my+oy).toFixed(1)}) rotate(${angle.toFixed(1)})">
  <text x="0" y="-3" text-anchor="middle" font-size="6.5" font-family="Courier New, monospace" fill="#333">${leg.bearing}</text>
  <text x="0" y="6" text-anchor="middle" font-size="7" font-family="Courier New, monospace" font-weight="bold" fill="#000">${leg.distance.toFixed(2)}m</text>
</g>`
  }).join('\n')

  // North arrow (top-right)
  const nax = W - 38
  const nay = 32
  const northArrow = `
<g transform="translate(${nax},${nay})">
  <polygon points="0,-18 5,5 0,0 -5,5" fill="#000"/>
  <polygon points="0,18 5,-5 0,0 -5,-5" fill="white" stroke="#000" stroke-width="0.8"/>
  <text x="0" y="-22" text-anchor="middle" font-size="10" font-family="Arial, sans-serif" font-weight="bold" fill="#000">N</text>
  <line x1="0" y1="-18" x2="0" y2="18" stroke="#000" stroke-width="0.5"/>
</g>`

  // Scale bar (bottom-left)
  // Compute nice round distance that fits ~100px
  const mapDist = 100 / s  // real-world distance represented by 100px
  // Round to nearest nice number
  const magnitudes = [0.1, 0.25, 0.5, 1, 2, 5, 10, 20, 25, 50, 100, 200, 250, 500, 1000, 2000, 5000]
  const niceDist = magnitudes.reduce((prev, curr) => Math.abs(curr - mapDist) < Math.abs(prev - mapDist) ? curr : prev)
  const barPx = niceDist * s

  const sbx = PAD
  const sby = H - 22
  const scaleBar = `
<g>
  <rect x="${sbx}" y="${sby}" width="${barPx.toFixed(1)}" height="5" fill="#000"/>
  <rect x="${(sbx + barPx/2).toFixed(1)}" y="${sby}" width="${(barPx/2).toFixed(1)}" height="5" fill="white" stroke="#000" stroke-width="0.5"/>
  <text x="${sbx}" y="${sby+14}" font-size="7" font-family="Arial, sans-serif" fill="#000">0</text>
  <text x="${(sbx + barPx/2).toFixed(1)}" y="${sby+14}" text-anchor="middle" font-size="7" font-family="Arial, sans-serif" fill="#000">${(niceDist/2).toFixed(niceDist < 1 ? 2 : 0)}</text>
  <text x="${(sbx + barPx).toFixed(1)}" y="${sby+14}" text-anchor="end" font-size="7" font-family="Arial, sans-serif" fill="#000">${niceDist >= 1000 ? (niceDist/1000)+'km' : niceDist+'m'}</text>
  <text x="${sbx}" y="${sby-4}" font-size="7" font-family="Arial, sans-serif" fill="#555">Scale 1:${scale.toLocaleString()}</text>
</g>`

  // Grid reference label (bottom right of drawing)
  const gridLabel = `<text x="${W - PAD}" y="${H - 8}" text-anchor="end" font-size="7" font-family="Courier New, monospace" fill="#666">Arc 1960 / UTM Zone 37S (SRID 21037)</text>`

  return `<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:100%;">
  ${hatch}
  <!-- Border -->
  <rect x="1" y="1" width="${W-2}" height="${H-2}" fill="none" stroke="#000" stroke-width="1.5"/>
  <!-- Parcel polygon -->
  ${polygon}
  <!-- Beacon symbols -->
  ${beaconSymbols}
  <!-- Point labels -->
  ${labels}
  <!-- Bearing & distance labels -->
  ${legLabels}
  <!-- North arrow -->
  ${northArrow}
  <!-- Scale bar -->
  ${scaleBar}
  <!-- Grid reference -->
  ${gridLabel}
</svg>`
}

// ── Main HTML generator ───────────────────────────────────────────────────────

export function generateDeedPlanPrint(inp: DeedPlanPrintInput): string {
  const { input } = inp
  const pts = input.boundaryPoints

  if (pts.length < 3) {
    throw new Error('At least 3 boundary points are required to generate a deed plan.')
  }

  const legs   = computeBoundaryLegs(pts)
  const areaSqm = computeArea(pts)
  const closure = computeClosureCheck(pts)

  const planSvg = drawParcelSVG(pts, legs, input.scale)

  const today = new Date().toLocaleDateString('en-KE', { day: '2-digit', month: 'long', year: 'numeric' })
  const survDate = input.surveyDate
    ? new Date(input.surveyDate).toLocaleDateString('en-KE', { day: '2-digit', month: 'long', year: 'numeric' })
    : today

  // ── Bearing & Distance schedule rows ───────────────────────────────────────
  const legRows = legs.map((l, i) => `
<tr>
  <td>${i + 1}</td>
  <td class="bold">${esc(l.fromPoint)}</td>
  <td class="bold">${esc(l.toPoint)}</td>
  <td class="mono">${l.bearing}</td>
  <td class="right mono">${l.distance.toFixed(3)}</td>
</tr>`).join('')

  // ── Coordinate schedule rows ───────────────────────────────────────────────
  const coordRows = pts.map((p, i) => `
<tr>
  <td>${i + 1}</td>
  <td class="bold mono">${esc(p.id)}</td>
  <td class="right mono">${p.easting.toFixed(3)}</td>
  <td class="right mono">${p.northing.toFixed(3)}</td>
  <td>${esc(p.markType.replace(/_/g, ' '))}</td>
  <td class="center">${esc(p.markStatus)}</td>
</tr>`).join('')

  // ── Closure status ─────────────────────────────────────────────────────────
  const closureText  = closure.passes ? 'PASS' : 'FAIL'

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Deed Plan — ${blank(input.parcelNumber || 'METARDU')}</title>
<style>
  * { margin:0; padding:0; box-sizing:border-box; }
  body {
    font-family: 'Courier New', monospace;
    font-size: 7.5pt;
    color: #000;
    background: #fff;
  }

  /* ── A3 landscape page ─── */
  @page { size: A3 landscape; margin: 6mm; }
  @media print { body { margin: 0; } }

  /* ── Main two-column layout ─── */
  .page {
    width: 100%;
    height: 100vh;
    display: grid;
    grid-template-columns: 62% 38%;
    border: 2px solid #000;
  }

  /* ── Left: plan area ─── */
  .plan-panel {
    border-right: 1.5px solid #000;
    display: flex;
    flex-direction: column;
  }
  .plan-label {
    padding: 3px 6px;
    border-bottom: 1px solid #000;
    font-size: 7pt;
    color: #555;
    font-style: italic;
    background: #f8f8f8;
  }
  .plan-drawing {
    flex: 1;
    padding: 4px;
    overflow: hidden;
  }
  .plan-drawing svg { display: block; width: 100%; height: 100%; }

  /* ── Right: title block + schedules ─── */
  .info-panel {
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }

  /* Title block */
  .title-block {
    border-bottom: 1.5px solid #000;
    padding: 6px 8px 4px;
    text-align: center;
    background: #000;
    color: #fff;
  }
  .title-main { font-size: 11pt; font-weight: bold; letter-spacing: 2px; }
  .title-sub  { font-size: 7pt;  letter-spacing: 0.5px; margin-top: 1px; }
  .title-ref  { font-size: 6.5pt; margin-top: 2px; opacity: 0.8; }

  /* Info grid */
  .info-grid {
    border-bottom: 1px solid #000;
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
  .info-cell {
    padding: 3px 6px;
    border-right: 1px solid #ccc;
    border-bottom: 1px solid #ccc;
  }
  .info-cell:nth-child(even) { border-right: none; }
  .info-cell-full {
    grid-column: 1 / -1;
    padding: 3px 6px;
    border-bottom: 1px solid #ccc;
  }
  .info-label { font-size: 6pt; text-transform: uppercase; color: #666; display: block; }
  .info-value { font-size: 7.5pt; font-weight: bold; }

  /* Area box */
  .area-box {
    border-bottom: 1px solid #000;
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    background: #f4f4f4;
  }
  .area-cell { padding: 3px 6px; border-right: 1px solid #ccc; text-align: center; }
  .area-cell:last-child { border-right: none; }
  .area-num  { font-size: 9.5pt; font-weight: bold; font-family: 'Courier New', monospace; }
  .area-unit { font-size: 6pt; text-transform: uppercase; color: #666; }

  /* Schedules */
  .schedule-section {
    border-bottom: 1px solid #ccc;
    overflow: hidden;
  }
  .schedule-header {
    padding: 2px 6px;
    background: #111;
    color: #fff;
    font-size: 6.5pt;
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 6.5pt;
  }
  th {
    background: #444;
    color: #fff;
    padding: 2px 4px;
    text-align: left;
    font-weight: bold;
    border: 1px solid #000;
  }
  td {
    padding: 2px 4px;
    border: 1px solid #ddd;
  }
  tr:nth-child(even) td { background: #f7f7f7; }
  .bold   { font-weight: bold; }
  .mono   { font-family: 'Courier New', monospace; }
  .right  { text-align: right; }
  .center { text-align: center; }

  /* Abuttals */
  .abuttals-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    border-bottom: 1px solid #ccc;
  }
  .abuttal-cell {
    padding: 3px 6px;
    border-right: 1px solid #ccc;
    border-bottom: 1px solid #ccc;
    font-size: 6.5pt;
  }
  .abuttal-cell:nth-child(even) { border-right: none; }
  .abuttal-dir { font-size: 6pt; text-transform: uppercase; color: #888; display: block; }

  /* Closure */
  .closure-row {
    display: flex;
    justify-content: space-between;
    padding: 2px 6px;
    border-bottom: 1px solid #ddd;
    font-size: 6.5pt;
  }
  .closure-pass { font-weight: bold; color: #14532d; }
  .closure-fail { font-weight: bold; color: #7f1d1d; }

  /* Surveyor certificate */
  .cert-block {
    border-top: 1.5px solid #000;
    padding: 5px 8px;
    flex: 1;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    min-height: 80px;
  }
  .cert-title { font-size: 6.5pt; font-weight: bold; text-transform: uppercase; letter-spacing: 0.5px; border-bottom: 1px solid #bbb; padding-bottom: 2px; margin-bottom: 4px; }
  .cert-text  { font-size: 6pt; line-height: 1.5; font-style: italic; margin-bottom: 6px; }
  .cert-sig-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
  .cert-sig-line { border-bottom: 1px solid #000; height: 18px; margin-bottom: 2px; }
  .cert-sig-label { font-size: 5.5pt; text-transform: uppercase; color: #666; }

  /* Legend */
  .legend {
    padding: 3px 6px;
    border-top: 1px solid #ccc;
    font-size: 6pt;
    color: #555;
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
  }
  .legend-item { display: flex; align-items: center; gap: 3px; }
</style>
</head>
<body>
<div class="page">

  <!-- ══ LEFT: PLAN DRAWING ══════════════════════════════════════════════ -->
  <div class="plan-panel">
    <div class="plan-label">
      BOUNDARY IDENTIFICATION PLAN &nbsp;|&nbsp; ${blank(input.parcelNumber)} &nbsp;|&nbsp;
      ${blank(input.locality)}, ${blank(input.county)} &nbsp;|&nbsp;
      Scale 1:${input.scale.toLocaleString()} &nbsp;|&nbsp; ${blank(input.datum)}
    </div>
    <div class="plan-drawing">
      ${planSvg}
    </div>
    <div class="legend">
      <span class="legend-item">
        <svg width="10" height="10"><rect x="1" y="1" width="8" height="8" fill="none" stroke="#000" stroke-width="1.2"/></svg>
        Concrete Beacon (SET)
      </span>
      <span class="legend-item">
        <svg width="10" height="10"><circle cx="5" cy="5" r="4" fill="none" stroke="#000" stroke-width="1.2"/></svg>
        Iron Pin (SET)
      </span>
      <span class="legend-item">
        <svg width="10" height="10"><line x1="2" y1="5" x2="8" y2="5" stroke="#000" stroke-width="0.8"/><line x1="5" y1="2" x2="5" y2="8" stroke="#000" stroke-width="0.8"/><circle cx="5" cy="5" r="1.5" fill="#000"/></svg>
        Masonry Nail / Rivet
      </span>
      <span class="legend-item">
        <svg width="10" height="10"><polygon points="5,1 9,9 1,9" fill="none" stroke="#000" stroke-width="1.2"/></svg>
        Control Mark (PSC/SSC)
      </span>
      <span style="margin-left:auto;color:#888;">Coordinates: Arc 1960 / UTM Zone 37S (SRID 21037)</span>
    </div>
  </div>

  <!-- ══ RIGHT: TITLE BLOCK + SCHEDULES ═══════════════════════════════════ -->
