/**
 * METARDU — GNSS Observation Log / Baseline Report
 *
 * Produces a formal GNSS observation log suitable for submission
 * to the Director of Surveys or project record-keeping.
 *
 * Includes:
 *   - Session header (project, equipment, date, operator)
 *   - Occupation schedule table (start/end, duration, satellites, PDOP)
 *   - Baseline vectors table (from/to, ΔE/ΔN/ΔU, distance, RMS)
 *   - Quality assessment summary
 *   - Surveyor's Certificate
 *
 * References:
 *   Survey Act Cap 299, s.22 (survey records)
 *   Survey Regulations 1994, Reg. 21 (instrument records)
 *   ISK — GNSS Best Practice Guidelines (2019)
 *   ISO 17123-8: GNSS field procedures
 */

import { buildPrintDocument, openPrint } from './buildPrintDocument'
import type { PrintMeta } from './buildPrintDocument'

// ── Types ─────────────────────────────────────────────────────────────────────

export interface GNSSObservationEntry {
  /** Point ID e.g. "BM_101" */
  pointId: string
  /** Session start time ISO string */
  startTime: string
  /** Session end time ISO string */
  endTime: string
  /** Duration in minutes */
  durationMin: number
  /** Number of satellites tracked */
  satellites: number
  /** Position Dilution of Precision */
  pdop: number
  /** Horizontal DOP */
  hdop: number
  /** Vertical DOP */
  vdop: number
  /** Fix type */
  fixType: 'FIX' | 'FLOAT' | 'DGNSS' | 'AUTONOMOUS' | 'RTK_FIX' | 'RTK_FLOAT'
  /** Antenna height in metres */
  antennaHeight: number
  /** Antenna measurement method */
  antennaMeasurement: 'SLANT' | 'VERTICAL' | 'ARP'
  /** Easting (projected) */
  easting?: number
  /** Northing (projected) */
  northing?: number
  /** Ellipsoidal height */
  ellHeight?: number
  /** Orthometric height */
  orthoHeight?: number
  /** RMS horizontal error (metres) */
  rmsH?: number
  /** RMS vertical error (metres) */
  rmsV?: number
  /** Notes */
  notes?: string
}

export interface GNSSBaselineEntry {
  /** From station */
  from: string
  /** To station */
  to: string
  /** Delta Easting (metres) */
  deltaE: number
  /** Delta Northing (metres) */
  deltaN: number
  /** Delta Elevation (metres) */
  deltaU: number
  /** Slope distance (metres) */
  distance: number
  /** Azimuth WCB (degrees) */
  azimuth: number
  /** Solution type */
  solution: 'FIX' | 'FLOAT' | 'DGNSS'
  /** Ratio (fix quality indicator) */
  ratio?: number
  /** RMS of baseline solution (metres) */
  rms: number
}

export interface GNSSLogInput {
  observations: GNSSObservationEntry[]
  baselines: GNSSBaselineEntry[]
  /** Equipment details */
  receiverModel: string
  receiverSerial: string
  antennaModel: string
  antennaSerial: string
  /** Reference station */
  baseStationId: string
  baseStationSource: 'OWN_BASE' | 'CORS' | 'VRS' | 'THIRD_PARTY'
  /** Coordinate system / datum */
  datum: string
  projection: string
  geoidModel: string
  /** Cutoff angle in degrees */
  elevationMask: number
  /** Epoch interval in seconds */
  epochInterval: number
  /** RINEX version if applicable */
  rinexVersion?: string
  /** Processing software */
  processingSoftware?: string
  /** Meta for header */
  meta: PrintMeta
}

// ── Formatting helpers ────────────────────────────────────────────────────────

function fmtTime(iso: string): string {
  try {
    const d = new Date(iso)
    return d.toLocaleTimeString('en-KE', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false })
  } catch { return iso }
}

function fmtDate(iso: string): string {
  try {
    const d = new Date(iso)
    return d.toLocaleDateString('en-KE', { day: '2-digit', month: 'short', year: 'numeric' })
  } catch { return iso }
}

function fixClass(fix: string): string {
  if (fix === 'FIX' || fix === 'RTK_FIX') return 'pass'
  if (fix === 'FLOAT' || fix === 'RTK_FLOAT') return 'warn'
  return 'fail'
}

function dmsFromDec(deg: number): string {
  const d = Math.floor(deg)
  const minDec = (deg - d) * 60
  const m = Math.floor(minDec)
  const s = (minDec - m) * 60
  return `${String(d).padStart(3, '0')}°${String(m).padStart(2, '0')}'${s.toFixed(1).padStart(4, '0')}"`
}

// ── Body HTML builder ─────────────────────────────────────────────────────────

function esc(value: string | number | undefined | null): string {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

function blank(value: string | number | undefined | null): string {
  const text = String(value ?? '').trim()
  return text ? esc(text) : '&mdash;'
}

function buildBody(inp: GNSSLogInput): string {
  const obs = inp.observations
  const bsl = inp.baselines

  // ── Equipment box ────────────────────────────────────────────
  const equipmentBox = `
<div class="summary-box" style="display:grid;grid-template-columns:1fr 1fr;gap:0;">
  <div class="summary-row"><span class="summary-label">Receiver</span><span class="summary-value">${blank(inp.receiverModel)}</span></div>
  <div class="summary-row"><span class="summary-label">Receiver S/N</span><span class="summary-value">${blank(inp.receiverSerial)}</span></div>
  <div class="summary-row"><span class="summary-label">Antenna</span><span class="summary-value">${blank(inp.antennaModel)}</span></div>
  <div class="summary-row"><span class="summary-label">Antenna S/N</span><span class="summary-value">${blank(inp.antennaSerial)}</span></div>
  <div class="summary-row"><span class="summary-label">Base Station</span><span class="summary-value">${blank(inp.baseStationId)} (${blank(inp.baseStationSource.replace(/_/g, ' '))})</span></div>
  <div class="summary-row"><span class="summary-label">Elevation Mask</span><span class="summary-value">${inp.elevationMask}°</span></div>
  <div class="summary-row"><span class="summary-label">Epoch Interval</span><span class="summary-value">${inp.epochInterval}s</span></div>
  <div class="summary-row"><span class="summary-label">Datum / Projection</span><span class="summary-value">${blank(inp.datum)} / ${blank(inp.projection)}</span></div>
  <div class="summary-row"><span class="summary-label">Geoid Model</span><span class="summary-value">${blank(inp.geoidModel)}</span></div>
  <div class="summary-row"><span class="summary-label">Processing Software</span><span class="summary-value">${blank(inp.processingSoftware || 'N/A')}</span></div>
</div>`

  // ── Observation schedule table ──────────────────────────────
  const obsRows = obs.map((o, i) => `
<tr>
  <td class="center">${i + 1}</td>
  <td class="bold mono">${blank(o.pointId)}</td>
  <td class="mono">${fmtTime(o.startTime)}</td>
  <td class="mono">${fmtTime(o.endTime)}</td>
  <td class="right mono">${o.durationMin.toFixed(0)}</td>
  <td class="center">${o.satellites}</td>
  <td class="right mono">${o.pdop.toFixed(1)}</td>
  <td class="right mono">${o.hdop.toFixed(1)}</td>
  <td class="center"><span class="${fixClass(o.fixType)}">${o.fixType.replace(/_/g, ' ')}</span></td>
  <td class="right mono">${o.antennaHeight.toFixed(3)}</td>
  <td class="center" style="font-size:7.5pt">${o.antennaMeasurement}</td>
</tr>`).join('')

  const obsTable = `
<h2>1. Occupation Schedule</h2>
<table>
  <thead>
    <tr>
      <th style="width:4%">No.</th>
      <th style="width:10%">Point</th>
      <th style="width:8%">Start</th>
      <th style="width:8%">End</th>
      <th class="right" style="width:6%">Min</th>
      <th style="width:5%">Sats</th>
      <th class="right" style="width:6%">PDOP</th>
      <th class="right" style="width:6%">HDOP</th>
      <th style="width:10%">Fix</th>
      <th class="right" style="width:8%">Ant H (m)</th>
      <th style="width:5%">Meas</th>
    </tr>
  </thead>
  <tbody>
    ${obsRows || '<tr><td colspan="11" class="center" style="color:#999;font-style:italic;">No observations entered</td></tr>'}
  </tbody>
</table>`

  // ── Coordinate results table ────────────────────────────────
  const coordRows = obs.filter(o => o.easting && o.northing).map((o, i) => `
<tr>
  <td class="center">${i + 1}</td>
  <td class="bold mono">${blank(o.pointId)}</td>
  <td class="right mono">${o.easting!.toFixed(3)}</td>
  <td class="right mono">${o.northing!.toFixed(3)}</td>
  <td class="right mono">${o.ellHeight?.toFixed(3) ?? '—'}</td>
  <td class="right mono">${o.orthoHeight?.toFixed(3) ?? '—'}</td>
  <td class="right mono">${o.rmsH?.toFixed(3) ?? '—'}</td>
  <td class="right mono">${o.rmsV?.toFixed(3) ?? '—'}</td>
</tr>`).join('')

  const coordTable = coordRows ? `
<h2>2. Coordinate Results — ${blank(inp.datum)}</h2>
<table>
  <thead>
    <tr>
      <th style="width:4%">No.</th>
      <th style="width:10%">Point</th>
      <th class="right" style="width:14%">Easting (m)</th>
      <th class="right" style="width:14%">Northing (m)</th>
      <th class="right" style="width:12%">Ell. Ht (m)</th>
      <th class="right" style="width:12%">Ortho Ht (m)</th>
      <th class="right" style="width:10%">RMS H (m)</th>
      <th class="right" style="width:10%">RMS V (m)</th>
    </tr>
  </thead>
  <tbody>${coordRows}</tbody>
</table>` : ''

  // ── Baseline vectors table ──────────────────────────────────
  const bslRows = bsl.map((b, i) => `
<tr>
  <td class="center">${i + 1}</td>
  <td class="bold mono">${blank(b.from)}</td>
  <td class="bold mono">${blank(b.to)}</td>
  <td class="right mono">${b.deltaE.toFixed(3)}</td>
  <td class="right mono">${b.deltaN.toFixed(3)}</td>
  <td class="right mono">${b.deltaU.toFixed(3)}</td>
  <td class="right mono">${b.distance.toFixed(3)}</td>
  <td class="mono">${dmsFromDec(b.azimuth)}</td>
  <td class="center"><span class="${b.solution === 'FIX' ? 'pass' : b.solution === 'FLOAT' ? 'warn' : 'fail'}">${b.solution}</span></td>
  <td class="right mono">${b.ratio?.toFixed(1) ?? '—'}</td>
  <td class="right mono">${b.rms.toFixed(4)}</td>
</tr>`).join('')

  const bslTable = bsl.length > 0 ? `
<h2>${coordRows ? '3' : '2'}. Baseline Vectors</h2>
<table>
  <thead>
    <tr>
      <th style="width:4%">No.</th>
      <th style="width:8%">From</th>
      <th style="width:8%">To</th>
      <th class="right" style="width:10%">ΔE (m)</th>
      <th class="right" style="width:10%">ΔN (m)</th>
      <th class="right" style="width:10%">ΔU (m)</th>
      <th class="right" style="width:10%">Dist (m)</th>
      <th style="width:12%">Azimuth</th>
      <th style="width:6%">Sol</th>
      <th class="right" style="width:6%">Ratio</th>
      <th class="right" style="width:8%">RMS (m)</th>
    </tr>
  </thead>
  <tbody>${bslRows}</tbody>
</table>` : ''

  // ── Quality assessment ──────────────────────────────────────
  const fixCount = obs.filter(o => o.fixType === 'FIX' || o.fixType === 'RTK_FIX').length
  const floatCount = obs.filter(o => o.fixType === 'FLOAT' || o.fixType === 'RTK_FLOAT').length
  const avgPdop = obs.length > 0 ? obs.reduce((a, o) => a + o.pdop, 0) / obs.length : 0
  const avgSats = obs.length > 0 ? obs.reduce((a, o) => a + o.satellites, 0) / obs.length : 0
  const maxRms = bsl.length > 0 ? Math.max(...bsl.map(b => b.rms)) : 0
  const avgRms = bsl.length > 0 ? bsl.reduce((a, b) => a + b.rms, 0) / bsl.length : 0
  const allFixed = fixCount === obs.length
  const minSats = obs.length > 0 ? Math.min(...obs.map(o => o.satellites)) : 0

  const qualitySection = `
<h2>${coordRows ? '4' : bsl.length > 0 ? '3' : '2'}. Quality Assessment</h2>
<div class="summary-box">
  <div class="summary-row"><span class="summary-label">Total observations</span><span class="summary-value">${obs.length}</span></div>
  <div class="summary-row"><span class="summary-label">Fixed solutions</span><span class="summary-value ${allFixed ? 'pass' : 'warn'}">${fixCount} / ${obs.length} (${obs.length > 0 ? ((fixCount / obs.length) * 100).toFixed(0) : 0}%)</span></div>
  <div class="summary-row"><span class="summary-label">Float solutions</span><span class="summary-value">${floatCount}</span></div>
  <div class="summary-row"><span class="summary-label">Avg PDOP</span><span class="summary-value ${avgPdop <= 3 ? 'pass' : avgPdop <= 6 ? 'warn' : 'fail'}">${avgPdop.toFixed(2)}</span></div>
  <div class="summary-row"><span class="summary-label">Avg satellites</span><span class="summary-value">${avgSats.toFixed(1)}</span></div>
  <div class="summary-row"><span class="summary-label">Min satellites</span><span class="summary-value ${minSats >= 5 ? 'pass' : 'fail'}">${minSats}</span></div>
  ${bsl.length > 0 ? `
  <div class="summary-row"><span class="summary-label">Total baselines</span><span class="summary-value">${bsl.length}</span></div>
  <div class="summary-row"><span class="summary-label">Avg baseline RMS</span><span class="summary-value ${avgRms <= 0.01 ? 'pass' : avgRms <= 0.05 ? 'warn' : 'fail'}">${avgRms.toFixed(4)} m</span></div>
  <div class="summary-row"><span class="summary-label">Max baseline RMS</span><span class="summary-value ${maxRms <= 0.02 ? 'pass' : maxRms <= 0.1 ? 'warn' : 'fail'}">${maxRms.toFixed(4)} m</span></div>
  ` : ''}
  <div class="summary-row"><span class="summary-label">Overall quality</span><span class="summary-value ${allFixed && avgPdop <= 3 ? 'pass' : 'warn'}">${allFixed && avgPdop <= 3 ? 'EXCELLENT' : fixCount > obs.length / 2 ? 'ACCEPTABLE' : 'REVIEW REQUIRED'}</span></div>
</div>`

  // ── Field notes ─────────────────────────────────────────────
  const obsWithNotes = obs.filter(o => o.notes)
  const notesSection = obsWithNotes.length > 0 ? `
<h2>Field Notes</h2>
<table>
  <thead>
    <tr>
      <th style="width:15%">Point</th>
      <th>Notes</th>
    </tr>
  </thead>
  <tbody>
    ${obsWithNotes.map(o => `<tr><td class="bold mono">${blank(o.pointId)}</td><td>${blank(o.notes)}</td></tr>`).join('')}
  </tbody>
</table>` : ''

  return `
${equipmentBox}
${obsTable}
${coordTable}
${bslTable}
${qualitySection}
${notesSection}
`
}

// ── Public API ────────────────────────────────────────────────────────────────

export function generateGNSSObservationLog(inp: GNSSLogInput): string {
  const meta: PrintMeta = {
    ...inp.meta,
    title: inp.meta.title || 'GNSS Observation Log',
    reference: 'Survey Act Cap 299 | Survey Regulations 1994, Reg. 21 | ISK GNSS Guidelines 2019 | ISO 17123-8',
  }
  return buildPrintDocument(buildBody(inp), meta)
}

export function printGNSSObservationLog(inp: GNSSLogInput): void {
  openPrint(generateGNSSObservationLog(inp))
}

/**
 * @module collaborationServer
 *
 * Real-time collaboration server using WebSocket.
 *
 * Features:
 * - Live presence (who's online in a project)
 * - Cursor sharing (see other users' mouse position on the map)
 * - Live feature editing (see when others draw/edit features)
 * - Conflict resolution via last-write-wins (LWW) with timestamp comparison.
 *   AUDIT FIX (M17, 2026-07-02): Previous docstring claimed "operational
 *   transforms" — that was inaccurate. The actual implementation is LWW:
 *   incoming edits with an older timestamp than the server's copy are
 *   rejected with a `conflict_rejected` message. Three-way merge is
 *   available in the offline sync queue (src/lib/offline/syncQueue.ts)
 *   but is NOT used by the realtime collaboration server.
 *
 * This module sets up a WebSocket server that can be integrated
 * with Next.js custom server or run as a separate process.
 *
 * For Docker deployment, this runs alongside the Next.js app
 * on a separate port (3001) or as a serverless WebSocket.
 */
/* eslint-disable no-console */

import { WebSocketServer, WebSocket } from 'ws'
import { createServer, IncomingMessage } from 'http'
import { parse } from 'url'
import { createHmac, createVerify } from 'crypto'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface Collaborator {
  id: string
  userId: string
  userName: string
  projectId: string
  cursor?: { lat: number; lng: number }
  color: string
  lastSeen: number
  ws: WebSocket
}

interface CollaborationMessage {
  type: 'join' | 'leave' | 'cursor' | 'feature_edit' | 'feature_delete' | 'chat' | 'presence'
  userId?: string
  userName?: string
  projectId?: string
  cursor?: { lat: number; lng: number }
  feature?: {
    id: string
    type: 'Point' | 'LineString' | 'Polygon'
    geometry: unknown
    properties?: Record<string, unknown>
  }
  featureId?: string
  message?: string
  timestamp: number
}

// ---------------------------------------------------------------------------
// JWT Authentication
// ---------------------------------------------------------------------------

/**
 * Verify a JWT token (NextAuth-compatible).
 *
 * NextAuth uses HS256 by default with AUTH_SECRET as the key.
 * This verifies the token signature without importing NextAuth
 * (keeps the WebSocket server lightweight).
 */
function verifyToken(token: string, secret: string): { userId?: string; email?: string; name?: string } | null {
  try {
    const parts = token.split('.')
    if (parts.length !== 3) return null

    const [headerB64, payloadB64, signatureB64] = parts
    const signedContent = `${headerB64}.${payloadB64}`

    // Verify signature
    const verify = createVerify('RSA-SHA256')
    verify.update(signedContent)
    verify.end()

    // NextAuth uses HS256 (HMAC), not RSA
    // For HMAC verification, we need crypto.createHmac
    const expectedSig = createHmac('sha256', secret)
      .update(signedContent)
      .digest('base64url')

    if (expectedSig !== signatureB64) {
      return null
    }

    // Decode payload
    const payload = JSON.parse(Buffer.from(payloadB64, 'base64url').toString()) as { sub?: string; userId?: string; email?: string; name?: string; fullName?: string }
    return {
      userId: payload.sub || payload.userId,
      email: payload.email,
      name: payload.name || payload.fullName,
    }
  } catch {
    return null
  }
}

/**
 * Authenticate a WebSocket connection request.
 * Returns the user info if valid, null otherwise.
 */
function authenticateRequest(req: IncomingMessage): { userId: string; userName: string } | null {
  const url = parse(req.url || '', true)
  const token = url.query.token as string
  const userId = url.query.userId as string
  const userName = url.query.userName as string

  // If AUTH_SECRET is set, require valid token
  const secret = process.env.AUTH_SECRET || process.env.NEXTAUTH_SECRET
  if (secret) {
    if (!token) return null
    const decoded = verifyToken(token, secret)
    if (!decoded || !decoded.userId) return null
    return {
      userId: decoded.userId,
      userName: decoded.name || userName || `User ${decoded.userId.substring(0, 6)}`,
    }
  }

  // Fallback: no secret set, allow unauthenticated (development only)
  if (!userId) return null
  return { userId, userName: userName || `User ${userId.substring(0, 6)}` }
}

// ---------------------------------------------------------------------------
// Conflict Resolution (Last-Write-Wins with timestamps)
// ---------------------------------------------------------------------------

interface FeatureVersion {
  featureId: string
  version: number
  timestamp: number
  userId: string
  data: unknown
}

class ConflictResolver {
  private versions: Map<string, FeatureVersion> = new Map()

  /**
   * Attempt to apply an update. Returns true if accepted, false if rejected
   * (stale version).
   */
  applyUpdate(featureId: string, data: unknown, timestamp: number, userId: string): boolean {
    const existing = this.versions.get(featureId)

    if (existing && timestamp < existing.timestamp) {
      // Stale update — reject
      return false
    }

    this.versions.set(featureId, {
      featureId,
      version: (existing?.version || 0) + 1,
      timestamp,
      data,
      userId,
    })

    return true
  }

  delete(featureId: string): void {
    this.versions.delete(featureId)
  }

  getVersion(featureId: string): FeatureVersion | undefined {
    return this.versions.get(featureId)
  }
}

// ---------------------------------------------------------------------------
// Collaboration Server
// ---------------------------------------------------------------------------

export class CollaborationServer {
  private wss: WebSocketServer | null = null
  private collaborators: Map<string, Collaborator> = new Map()
  private projectRooms: Map<string, Set<string>> = new Map() // projectId -> set of collaborator IDs
  private conflictResolvers: Map<string, ConflictResolver> = new Map() // projectId -> resolver

  // User colors for cursor display
  private readonly COLORS = [
    '#D17B47', '#3B82F6', '#10B981', '#8B5CF6',
    '#F59E0B', '#EF4444', '#06B6D4', '#EC4899',
  ]

  start(port: number = 3001) {
    const server = createServer((req, res) => {
      // Tiny HTTP listener for health checks. The collaboration server's
      // real traffic is WebSocket on /ws/collaboration; this endpoint only
      // exists so orchestrators (docker-compose healthcheck, k8s liveness)
      // can confirm the process is alive.
      if ((req.url || '').split('?')[0] === '/health') {
        res.writeHead(200, { 'content-type': 'application/json' })
        res.end(JSON.stringify({
          status: 'healthy',
          collaborators: this.collaborators.size,
          projects: this.projectRooms.size,
          uptime: process.uptime(),
        }))
        return
      }
      res.writeHead(404, { 'content-type': 'text/plain' })
      res.end('Not Found')
    })
    this.wss = new WebSocketServer({ server, path: '/ws/collaboration' })

    this.wss.on('connection', (ws: WebSocket, req: IncomingMessage) => {
      // Authenticate the connection
      const auth = authenticateRequest(req)
      if (!auth) {
        ws.close(1008, 'Authentication failed')
        return
      }

      const url = parse(req.url || '', true)
      const projectId = url.query.projectId as string

      if (!projectId) {
        ws.close(1008, 'Missing projectId')
        return
      }

      const { userId, userName } = auth
      const collaboratorId = `${userId}-${Date.now()}`
      const color = this.COLORS[this.collaborators.size % this.COLORS.length]

      const collaborator: Collaborator = {
        id: collaboratorId,
        userId,
        userName: userName || `User ${userId.substring(0, 6)}`,
        projectId,
        color,
        lastSeen: Date.now(),
        ws,
      }

      this.collaborators.set(collaboratorId, collaborator)

      // Add to project room
      if (!this.projectRooms.has(projectId)) {
        this.projectRooms.set(projectId, new Set())
      }
      this.projectRooms.get(projectId)!.add(collaboratorId)

      // Notify room of new collaborator
      this.broadcastToProject(projectId, {
        type: 'join',
        userId,
        userName: collaborator.userName,
        projectId,
        timestamp: Date.now(),
      }, collaboratorId)

      // Send current presence to new collaborator
      this.sendPresence(ws, projectId)

      ws.on('message', (data: Buffer) => {
        try {
                    const msg: CollaborationMessage = JSON.parse(data.toString()) as unknown as CollaborationMessage
          collaborator.lastSeen = Date.now()

          switch (msg.type) {
            case 'cursor':
              collaborator.cursor = msg.cursor
              this.broadcastToProject(projectId, {
                type: 'cursor',
                userId,
                userName: collaborator.userName,
                cursor: msg.cursor,
                timestamp: Date.now(),
              }, collaboratorId)
              break

            case 'feature_edit': {
              // Conflict resolution: last-write-wins with timestamps
              const resolver = this.getResolver(projectId)
              const featureId = msg.feature?.id
              if (!featureId) break

              const accepted = resolver.applyUpdate(
                featureId,
                msg.feature,
                msg.timestamp,
                userId,
              )

              if (accepted) {
                this.broadcastToProject(projectId, {
                  type: 'feature_edit',
                  userId,
                  userName: collaborator.userName,
                  feature: msg.feature,
                  timestamp: msg.timestamp,
                }, collaboratorId)
              } else {
                // Reject stale update — notify sender
                ws.send(JSON.stringify({
                  type: 'conflict_rejected',
                  featureId,
                  message: 'Update rejected — newer version exists',
                  timestamp: Date.now(),
                }))
              }
              break
            }

            case 'feature_delete': {
              const resolver = this.getResolver(projectId)
              if (msg.featureId) {
                resolver.delete(msg.featureId)
              }
              this.broadcastToProject(projectId, {
                type: 'feature_delete',
                userId,
                userName: collaborator.userName,
                featureId: msg.featureId,
                timestamp: Date.now(),
              }, collaboratorId)
              break
            }

            case 'chat':
              this.broadcastToProject(projectId, {
                type: 'chat',
                userId,
                userName: collaborator.userName,
                message: msg.message,
                timestamp: Date.now(),
              }, collaboratorId)
              break
          }
        } catch (err) {
          console.error('[CollaborationServer] Message parse error:', err)
        }
      })

      ws.on('close', () => {
        this.collaborators.delete(collaboratorId)
        this.projectRooms.get(projectId)?.delete(collaboratorId)

        this.broadcastToProject(projectId, {
          type: 'leave',
          userId,
          userName: collaborator.userName,
          timestamp: Date.now(),
        })
      })

      ws.on('error', (err) => {
        console.error('[CollaborationServer] WebSocket error:', err)
      })
    })

    // Heartbeat — remove stale connections
    setInterval(() => {
      const now = Date.now()
      for (const [id, collab] of this.collaborators) {
        if (now - collab.lastSeen > 60000) { // 60s timeout
          collab.ws.terminate()
          this.collaborators.delete(id)
          this.projectRooms.get(collab.projectId)?.delete(id)
        }
      }
    }, 30000)

    server.listen(port, () => {
    })
  }

  private broadcastToProject(projectId: string, msg: CollaborationMessage, excludeId?: string) {
    const room = this.projectRooms.get(projectId)
    if (!room) return

    const data = JSON.stringify(msg)
    for (const collabId of room) {
      if (collabId === excludeId) continue
      const collab = this.collaborators.get(collabId)
      if (collab && collab.ws.readyState === WebSocket.OPEN) {
        collab.ws.send(data)
      }
    }
  }

  private getResolver(projectId: string): ConflictResolver {
    if (!this.conflictResolvers.has(projectId)) {
      this.conflictResolvers.set(projectId, new ConflictResolver())
    }
    return this.conflictResolvers.get(projectId)!
  }

  private sendPresence(ws: WebSocket, projectId: string) {
    const room = this.projectRooms.get(projectId)
    if (!room) return

    const presence = Array.from(room)
      .map(id => this.collaborators.get(id))
      .filter((c): c is Collaborator => c !== undefined)
      .map(c => ({
        userId: c.userId,
        userName: c.userName,
        color: c.color,
        cursor: c.cursor,
      }))

    ws.send(JSON.stringify({
      type: 'presence',
      timestamp: Date.now(),
      payload: presence,
    }))
  }

  stop() {
    this.wss?.close()
    this.collaborators.clear()
    this.projectRooms.clear()
    this.conflictResolvers.clear()
  }
}

// ---------------------------------------------------------------------------
// Singleton instance
// ---------------------------------------------------------------------------

let serverInstance: CollaborationServer | null = null

export function getCollaborationServer(): CollaborationServer {
  if (!serverInstance) {
    serverInstance = new CollaborationServer()
  }
  return serverInstance
}

/**
 * METARDU Enterprise Yjs Offline Mesh Network
 * ===========================================
 * Replaces HTTP polling with true Peer-to-Peer CRDTs using WebRTC.
 * Allows surveyors to sync GNSS points locally over Wi-Fi without internet.
 */

import * as Y from 'yjs'
import { WebrtcProvider } from 'y-webrtc'
import { IndexeddbPersistence } from 'y-indexeddb'

export interface PresenceUser {
  userId: string
  userName: string
  color: string
  cursor?: { lat: number; lng: number }
  onlineAt?: string
}

class YjsMeshNetwork {
  private docs: Map<string, Y.Doc> = new Map()
  private providers: Map<string, WebrtcProvider> = new Map()
  private persistences: Map<string, IndexeddbPersistence> = new Map()

  public getDoc(projectId: string): Y.Doc {
    if (this.docs.has(projectId)) return this.docs.get(projectId)!

    const doc = new Y.Doc()
    this.docs.set(projectId, doc)

    // Offline persistence
    const persistence = new IndexeddbPersistence(`metardu-sync-${projectId}`, doc)
    this.persistences.set(projectId, persistence)

    // WebRTC Provider for P2P Local LAN sync (using public/local signaling)
    const provider = new WebrtcProvider(`metardu-mesh-${projectId}`, doc, {
      signaling: ['wss://signaling.yjs.dev', 'ws://localhost:4444'], // Add local fallback if deployed offline
      password: 'metardu-secure-field'
    })
    this.providers.set(projectId, provider)

    return doc
  }

  public getProvider(projectId: string): WebrtcProvider | undefined {
    return this.providers.get(projectId)
  }

  public async unsubscribe(projectId: string): Promise<void> {
    const provider = this.providers.get(projectId)
    if (provider) {
      provider.disconnect()
      provider.destroy()
      this.providers.delete(projectId)
    }

    const persistence = this.persistences.get(projectId)
    if (persistence) {
      persistence.destroy()
      this.persistences.delete(projectId)
    }

    const doc = this.docs.get(projectId)
    if (doc) {
      doc.destroy()
      this.docs.delete(projectId)
    }
  }

  public async unsubscribeAll(): Promise<void> {
    for (const projectId of Array.from(this.docs.keys())) {
      await this.unsubscribe(projectId)
    }
  }
}

export const realtimeService = new YjsMeshNetwork()

export function subscribeToProjectChanges(
  projectId: string,
  user: { id: string; email?: string; name?: string },
  callbacks: {
    onPointsChange?: (payload: unknown) => void
    onTraverseChange?: (payload: unknown) => void
    onLevelingChange?: (payload: unknown) => void
    onPresenceChange?: (users: PresenceUser[]) => void
  }
): { unsubscribe: () => Promise<void> } {
  // This is a compatibility layer for the old HTTP polling interface.
  // In the new architecture, Zustand automatically syncs with Yjs via the sync layer.
  // We just handle presence here.

  const provider = realtimeService.getProvider(projectId)
  if (!provider) {
    // Force init
    realtimeService.getDoc(projectId)
  }
  
  const activeProvider = realtimeService.getProvider(projectId)
  if (activeProvider && callbacks.onPresenceChange) {
    const awareness = activeProvider.awareness

    // Set local presence
    awareness.setLocalStateField('user', {
      userId: user.id,
      userName: user.name || user.email || 'Unknown Surveyor',
      color: '#' + Math.floor(Math.random()*16777215).toString(16),
      onlineAt: new Date().toISOString()
    })

    const handleAwarenessChange = () => {
      const states = Array.from(awareness.getStates().values())
      const users = states
        .filter((state: { user?: { userId?: string } }) => state.user && state.user.userId !== user.id)
        .map(state => state.user as PresenceUser)
      callbacks.onPresenceChange!(users)
    }

    awareness.on('change', handleAwarenessChange)
    
    // Initial emit
    handleAwarenessChange()

    return {
      unsubscribe: async () => {
        awareness.off('change', handleAwarenessChange)
      }
    }
  }

  return {
    unsubscribe: async () => {}
  }
}

import { useProjectStore, ProjectData } from '@/stores/projectStore'
import { realtimeService } from './index'
import * as Y from 'yjs'

// Track active syncs to avoid duplicate listeners
const activeSyncs = new Set<string>()

export function initProjectSync(projectId: string) {
  if (activeSyncs.has(projectId)) return
  activeSyncs.add(projectId)

  const doc = realtimeService.getDoc(projectId)
  const yProject = doc.getMap<unknown>('project')

  // 1. Initial Load: If Yjs has data, push it to Zustand
  if (Array.from(yProject.keys()).length > 0) {
    const projectData = yProject.toJSON() as unknown as ProjectData
    useProjectStore.getState().loadProject(projectData)
  } else {
    // If Yjs is empty, initialize it from Zustand
    const state = useProjectStore.getState()
    const project = state.projects[projectId]
    if (project) {
      doc.transact(() => {
        Object.entries(project).forEach(([key, value]) => {
          yProject.set(key, value)
        })
      })
    }
  }

  // 2. Yjs -> Zustand (Observe changes from other tablets)
  yProject.observe((event) => {
    // Prevent echo loops by checking if we caused this change
    if (event.transaction.local) return

    const updatedData = yProject.toJSON() as unknown as ProjectData
    useProjectStore.getState().loadProject(updatedData)
  })

  // 3. Zustand -> Yjs (Observe local changes and push to mesh)
  useProjectStore.subscribe(
    (state) => state.projects[projectId],
    (project, prevProject) => {
      if (!project) return
      
      // We only want to push to Yjs if this change came from the local user
      // A simple way to check is to diff the objects.
      // But since Yjs handles merges cleanly, we can just dump it in.
      
      doc.transact(() => {
        // We do a naive replace of the top-level keys
        // For a production app, we would observe nested properties (ControlPoints Map, etc.)
        // But Y.Map set() overwrites cleanly.
        Object.entries(project).forEach(([key, value]) => {
          const currentY = yProject.get(key)
          // Naive deep equality check to avoid unnecessary writes
          if (JSON.stringify(currentY) !== JSON.stringify(value)) {
            yProject.set(key, value)
          }
        })
      })
    },
    { equalityFn: (a, b) => JSON.stringify(a) === JSON.stringify(b) }
  )
}

export interface ConvertedCoordinate {
  id?: string
  easting: number
  northing: number
  datum: string
  epsg: number
}

export interface ConversionResult {
  success: boolean
  coordinates: ConvertedCoordinate[]
  error?: string
}

interface ConvertDatumResponse {
  data?: Array<{ id?: string; easting: number; northing: number; datum?: string }>
  error?: string
}

export async function convertToArc1960(
  coordinates: Array<{ id?: string; easting: number; northing: number }>
): Promise<ConversionResult> {
  try {
    const response = await fetch('/api/convert-datum', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        coords: coordinates,
        fromDatum: 'WGS84',
        toDatum: 'ARC1960'
      })
    })
    const data = (await response.json()) as ConvertDatumResponse
    if (response.ok && data.data) {
      const coords = data.data.map((c) => ({
        id: c.id,
        easting: c.easting,
        northing: c.northing,
        datum: c.datum || 'ARC1960',
        epsg: 21037
      }))
      return { success: true, coordinates: coords }
    }
    return { success: false, coordinates: [], error: data.error || 'Conversion failed' }
  } catch (err) {
    return { success: false, coordinates: [], error: 'Network error' }
  }
}

export async function convertFromArc1960(
  coordinates: Array<{ id?: string; easting: number; northing: number }>
): Promise<ConversionResult> {
  try {
    const response = await fetch('/api/convert-datum', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        coords: coordinates,
        fromDatum: 'ARC1960',
        toDatum: 'WGS84'
      })
    })
    const data = (await response.json()) as ConvertDatumResponse
    if (response.ok && data.data) {
      const coords = data.data.map((c) => ({
        id: c.id,
        easting: c.easting,
        northing: c.northing,
        datum: c.datum || 'WGS84',
        epsg: 32637
      }))
      return { success: true, coordinates: coords }
    }
    return { success: false, coordinates: [], error: data.error || 'Conversion failed' }
  } catch (err) {
    return { success: false, coordinates: [], error: 'Network error' }
  }
}

export function isArc1960Easting(easting: number): boolean {
  return easting >= 166000 && easting <= 850000
}

export function isArc1960Northing(northing: number): boolean {
  return northing >= 9500000 || (northing >= 0 && northing < 500000)
}

export function isWgs84UtmEasting(easting: number): boolean {
  return easting >= 166000 && easting <= 850000
}

export function isWgs84UtmNorthing(northing: number): boolean {
  return (northing >= 0 && northing < 1100000) || (northing > 10000000)
}

/**
 * Form No. 3 Mutation Survey Plan — SVG Renderer
 *
 * Standalone renderer producing Kenya cadastral mutation survey plan output
 * compliant with Survey Act Cap. 299, Survey Regulations 1994 and RDM 1.1.
 *
 * Page: A1 landscape (841 × 594 mm)
 * NOT extending SurveyPlanRenderer — Form No. 3 has its own page layout.
 *
 * Drawing layers (bottom → top):
 *   1.  Page background
 *   2.  Double-line border frame
 *   3.  Grid tick marks & coordinate labels
 *   4.  Scheme boundary outline
 *   5.  Plot boundaries (black, no fill)
 *   6.  Beacon circles (red, unfilled)
 *   7.  Dimension lines (bearing & distance)
 *   8.  Area labels ("A = X.XXXX Ha")
 *   9.  Road corridors & labels
 *  10.  Survey monuments (M1–M10)
 *  11.  Bearing schedule table (top-left)
 *  12.  Authentication block (bottom-right)
 *  13.  Title block strip (bottom)
 *  14.  North arrow & scale bar
 */

import type { MutationPlanData } from './formNo3Types'
import {
  DPI,
  PX_PER_MM,
  PX_PER_M,
  mmToPx,
  mToPx,
  bearingFromDelta,
  distance,
  centroid,
  boundingBox,
  formatBearingDegMinSec,
  shoelaceArea,
  STANDARD_SCALES,
  segmentAngle,
  offsetFromMidpoint,
} from './geometry'
import {
  escapeXml,
  C_BLACK,
  C_RED,
  C_GRID_MAJOR,
  C_GRID_MINOR,
} from './symbols'

// ─── Layout constants (all in mm) ──────────────────────────────────────────

const PAGE_W_MM = 841
const PAGE_H_MM = 594

/** Outer border inset from page edge */
const BORDER_OUTER_INSET = 5
/** Inner border inset from page edge */
const BORDER_INNER_INSET = 10

/** Drawing area margin inside inner border */
const DRAW_MARGIN = 15
/** Title block height at bottom */
const TITLE_BLOCK_H_MM = 28
/** Auth block reserved height */
const AUTH_BLOCK_H_MM = 68

const FONT_LABEL = "'Times New Roman', serif"
const FONT_FORM = "'Calibri', sans-serif"

// ─── Internal renderer state ────────────────────────────────────────────────

interface RenderState {
  pageW: number
  pageH: number
  drawX: number
  drawY: number
  drawW: number
  drawH: number
  scale: number
  pxPerM: number
  bbMinE: number
  bbMaxE: number
  bbMinN: number
  bbMaxN: number
  offsetX: number
  offsetY: number
  toSvgX: (m: number) => number
  toSvgY: (m: number) => number
}

// ─── Main entry point ───────────────────────────────────────────────────────

/**
 * Render a complete Form No. 3 Mutation Survey Plan as SVG.
 *
 * @param data - Fully populated MutationPlanData
 * @returns Complete SVG document string
 */
export function renderFormNo3(data: MutationPlanData): string {
  const state = buildState(data)
  const layers: string[] = []

  // 1 – Page background
  layers.push(drawPageBackground(state))
  // 2 – Double-line border
  layers.push(drawDoubleBorder(state))
  // 3 – Grid ticks & labels
  layers.push(drawGridTicksAndLabels(state, data))
  // 4 – Scheme boundary
  layers.push(drawSchemeBoundary(state, data))
  // 5 – Plot boundaries
  layers.push(drawPlotBoundaries(state, data))
  // 6 – Beacon circles
  layers.push(drawBeaconCircles(state, data))
  // 7 – Dimension lines
  layers.push(drawDimensionLines(state, data))
  // 8 – Area labels
  layers.push(drawAreaLabels(state, data))
  // 9 – Road corridors
  layers.push(drawRoadCorridors(state, data))
  // 10 – Survey monuments
  layers.push(drawSurveyMonuments(state, data))
  // 11 – Bearing schedule table
  layers.push(drawBearingScheduleTable(state, data))
  // 12 – Authentication block
  layers.push(drawAuthBlock(state, data))
  // 13 – Title block
  layers.push(drawTitleBlock(state, data))
  // 14 – North arrow & scale bar
  layers.push(drawNorthArrowAndScaleBar(state, data))

  return (
    `<svg xmlns="http://www.w3.org/2000/svg"` +
    ` viewBox="0 0 ${state.pageW} ${state.pageH}"` +
    ` width="${state.pageW}" height="${state.pageH}"` +
    ` style="font-family: ${FONT_LABEL}; background: white;">` +
    layers.join('\n') +
    `</svg>`
  )
}

export default renderFormNo3

// ─── State builder ──────────────────────────────────────────────────────────

function buildState(data: MutationPlanData): RenderState {
  const pageW = mmToPx(PAGE_W_MM)
  const pageH = mmToPx(PAGE_H_MM)

  // Drawing area: inside inner border, above title block
  const drawX = mmToPx(BORDER_INNER_INSET + DRAW_MARGIN)
  const drawY = mmToPx(BORDER_INNER_INSET + DRAW_MARGIN)
  const drawW = pageW - 2 * drawX
  const drawH = pageH - drawY - mmToPx(BORDER_INNER_INSET + DRAW_MARGIN + TITLE_BLOCK_H_MM)

  // Compute bounding box of all geometry
  const allPts = [
    ...data.schemeBoundary,
    ...data.plots.flatMap((p) => p.boundaryPoints),
    ...data.roads.flatMap((r) => r.centerline),
    ...data.monuments.map((m) => ({ easting: m.easting, northing: m.northing })),
  ]
  const bb = boundingBox(allPts)

  // Compute scale: fit data into drawing area with padding
  const padding = mmToPx(10)
  const effectiveW = drawW - padding * 2
  const effectiveH = drawH - padding * 2
  const rawPxPerM = Math.min(effectiveW / bb.rangeE, effectiveH / bb.rangeN)
  const rawScale = PX_PER_M / rawPxPerM

  // Use project-provided scale if set, otherwise snap to standard
  const scale = data.project.scale > 0
    ? data.project.scale
    : STANDARD_SCALES.find((s) => s >= rawScale) || 10000

  const pxPerM = PX_PER_M / scale
  const offsetX = (effectiveW - bb.rangeE * pxPerM) / 2
  const offsetY = (effectiveH - bb.rangeN * pxPerM) / 2

  const toSvgX = (m: number): number =>
    drawX + padding + offsetX + (m - bb.minE) * pxPerM

  const toSvgY = (m: number): number =>
    drawY + padding + offsetY + (bb.maxN - m) * pxPerM

  return {
    pageW,
    pageH,
    drawX,
    drawY,
    drawW,
    drawH,
    scale,
    pxPerM,
    bbMinE: bb.minE,
    bbMaxE: bb.maxE,
    bbMinN: bb.minN,
    bbMaxN: bb.maxN,
    offsetX,
    offsetY,
    toSvgX,
    toSvgY,
  }
}

// ─── Layer 1: Page background ──────────────────────────────────────────────

function drawPageBackground(s: RenderState): string {
  return `<rect x="0" y="0" width="${s.pageW}" height="${s.pageH}" fill="white"/>`
}

// ─── Layer 2: Double-line border ───────────────────────────────────────────

function drawDoubleBorder(s: RenderState): string {
  const oi = mmToPx(BORDER_OUTER_INSET)
  const ii = mmToPx(BORDER_INNER_INSET)
  return [
    `<rect x="${oi}" y="${oi}" width="${s.pageW - 2 * oi}" height="${s.pageH - 2 * oi}"` +
    ` fill="none" stroke="${C_BLACK}" stroke-width="2.5"/>`,
    `<rect x="${ii}" y="${ii}" width="${s.pageW - 2 * ii}" height="${s.pageH - 2 * ii}"` +
    ` fill="none" stroke="${C_BLACK}" stroke-width="0.8"/>`,
  ].join('')
}

// ─── Layer 3: Grid tick marks & coordinate labels ─────────────────────────

function drawGridTicksAndLabels(s: RenderState, data: MutationPlanData): string {
  const g = data.grid
  const gridMinE = Math.floor(g.minE / g.intervalE) * g.intervalE
  const gridMaxE = Math.ceil(g.maxE / g.intervalE) * g.intervalE
  const gridMinN = Math.floor(g.minN / g.intervalN) * g.intervalN
  const gridMaxN = Math.ceil(g.maxN / g.intervalN) * g.intervalN

  const tickLen = mmToPx(3)
  const marginInner = mmToPx(BORDER_INNER_INSET)
  const labelOffset = mmToPx(5.5)
  const fontSize = mmToPx(2.2)

  let svg = ''

  // Vertical grid ticks along top & bottom margins (easting labels)
  for (let e = gridMinE; e <= gridMaxE; e += g.intervalE) {
    const x = s.toSvgX(e)
    // Top tick
    svg += `<line x1="${x}" y1="${marginInner}" x2="${x}" y2="${marginInner + tickLen}"` +
      ` stroke="${C_BLACK}" stroke-width="0.5"/>`
    // Bottom tick
    svg += `<line x1="${x}" y1="${s.pageH - marginInner}" x2="${x}" y2="${s.pageH - marginInner - tickLen}"` +
      ` stroke="${C_BLACK}" stroke-width="0.5"/>`
    // Label at top (formatted with space group, e.g. "114 500")
    svg += `<text x="${x}" y="${marginInner - mmToPx(1.5)}" text-anchor="middle"` +
      ` font-family="${FONT_FORM}" font-size="${fontSize}" fill="${C_BLACK}">` +
      `${escapeXml(formatGridCoord(e))}</text>`
  }

  // Horizontal grid ticks along left & right margins (northing labels)
  for (let n = gridMinN; n <= gridMaxN; n += g.intervalN) {
    const y = s.toSvgY(n)
    // Left tick
    svg += `<line x1="${marginInner}" y1="${y}" x2="${marginInner + tickLen}" y2="${y}"` +
      ` stroke="${C_BLACK}" stroke-width="0.5"/>`
    // Right tick
    svg += `<line x1="${s.pageW - marginInner}" y1="${y}" x2="${s.pageW - marginInner - tickLen}" y2="${y}"` +
      ` stroke="${C_BLACK}" stroke-width="0.5"/>`
    // Label at left
    svg += `<text x="${marginInner + tickLen + mmToPx(1)}" y="${y + mmToPx(0.8)}"` +
      ` font-family="${FONT_FORM}" font-size="${fontSize}" fill="${C_BLACK}">` +
      `${escapeXml(formatGridCoord(n))}</text>`
  }

  return svg
}

/** Format coordinate with space grouping, e.g. 114500 → "114 500" */
function formatGridCoord(val: number): string {
  const str = Math.round(val).toString()
  // Group last 3 digits
  if (str.length > 3) {
    return str.slice(0, -3) + ' ' + str.slice(-3)
  }
  return str
}

// ─── Layer 4: Scheme boundary ──────────────────────────────────────────────

function drawSchemeBoundary(s: RenderState, data: MutationPlanData): string {
  const pts = data.schemeBoundary
  if (pts.length < 2) return ''
  const coords = pts.map((p) => `${s.toSvgX(p.easting)},${s.toSvgY(p.northing)}`).join(' ')
  const close = `${s.toSvgX(pts[0].easting)},${s.toSvgY(pts[0].northing)}`
  return `<polyline points="${coords} ${close}" fill="none" stroke="${C_BLACK}" stroke-width="1.5"` +
    ` stroke-dasharray="6,3" opacity="0.6"/>`
}

// ─── Layer 5: Plot boundaries ──────────────────────────────────────────────

function drawPlotBoundaries(s: RenderState, data: MutationPlanData): string {
  let svg = ''
  for (const plot of data.plots) {
    const pts = plot.boundaryPoints
    if (pts.length < 3) continue
    const coords = pts.map((p) => `${s.toSvgX(p.easting)},${s.toSvgY(p.northing)}`).join(' ')
    const close = `${s.toSvgX(pts[0].easting)},${s.toSvgY(pts[0].northing)}`
    svg += `<polygon points="${coords} ${close}" fill="none" stroke="${C_BLACK}" stroke-width="1.2"/>`
  }
  return svg
}

// ─── Layer 6: Beacon circles ───────────────────────────────────────────────

function drawBeaconCircles(s: RenderState, data: MutationPlanData): string {
  const beaconRadius = mmToPx(0.9) // 1.8pt diameter → 0.9pt radius
  let svg = ''
  const seen = new Set<string>()

  for (const plot of data.plots) {
    for (const pt of plot.boundaryPoints) {
      const key = `${pt.easting.toFixed(3)},${pt.northing.toFixed(3)}`
      if (seen.has(key)) continue
      seen.add(key)
      const cx = s.toSvgX(pt.easting)
      const cy = s.toSvgY(pt.northing)
      // Red unfilled circle
      svg += `<circle cx="${cx}" cy="${cy}" r="${beaconRadius}" fill="none" stroke="${C_RED}" stroke-width="0.8"/>`
      // Tiny centre dot
      svg += `<circle cx="${cx}" cy="${cy}" r="0.6" fill="${C_RED}"/>`
    }
  }
  return svg
}

// ─── Layer 7: Dimension lines (bearing & distance) ─────────────────────────

function drawDimensionLines(s: RenderState, data: MutationPlanData): string {
  const labelFontSize = mmToPx(3.0)
  let svg = ''
  const seen = new Set<string>()

  for (const plot of data.plots) {
    const pts = plot.boundaryPoints
    for (let i = 0; i < pts.length; i++) {
      const from = pts[i]
      const to = pts[(i + 1) % pts.length]

      // Avoid duplicate lines on shared boundaries
      const lineKey = [
        from.easting.toFixed(2), from.northing.toFixed(2),
        to.easting.toFixed(2), to.northing.toFixed(2),
      ].join('|')
      const lineKeyRev = [
        to.easting.toFixed(2), to.northing.toFixed(2),
        from.easting.toFixed(2), from.northing.toFixed(2),
      ].join('|')
      if (seen.has(lineKey) || seen.has(lineKeyRev)) continue
      seen.add(lineKey)
      seen.add(lineKeyRev)

      const dist = distance(from.easting, from.northing, to.easting, to.northing)
      const bearing = bearingFromDelta(to.easting - from.easting, to.northing - from.northing)
      const bearingStr = formatBearingDegMinSec(bearing)
      const distStr = `${dist.toFixed(2)} m`

      const angleDeg = segmentAngle(from.easting, from.northing, to.easting, to.northing)
      let textAngle = angleDeg
      if (textAngle > 90 || textAngle < -90) textAngle += 180

      // Offset midpoint perpendicular to the line
      const offsetM = 5 / s.pxPerM // 5mm in ground units
      const [mx, my] = offsetFromMidpoint(from.easting, from.northing, to.easting, to.northing, offsetM)
      const bx = s.toSvgX(mx)
      const by = s.toSvgY(my)

      const tw = Math.max(bearingStr.length * 4.5, distStr.length * 4) + 8
      const th = mmToPx(7)

      svg += `<g transform="translate(${bx},${by})">`
      svg += `<g transform="rotate(${textAngle})">`
      // White background for readability
      svg += `<rect x="${-tw / 2}" y="${-th / 2}" width="${tw}" height="${th}" fill="white" opacity="0.88" stroke="none"/>`
      // Bearing text
      svg += `<text x="0" y="${-mmToPx(0.8)}" text-anchor="middle" font-family="${FONT_LABEL}" font-size="${labelFontSize}" fill="${C_BLACK}">${escapeXml(bearingStr)}</text>`
      // Distance text
      svg += `<text x="0" y="${mmToPx(2.2)}" text-anchor="middle" font-family="${FONT_LABEL}" font-size="${labelFontSize}" fill="${C_BLACK}">${escapeXml(distStr)}</text>`
      svg += `</g>`

      // V-arrowheads at each end of the dimension line
      const fx = s.toSvgX(from.easting)
      const fy = s.toSvgY(from.northing)
      const tx = s.toSvgX(to.easting)
      const ty = s.toSvgY(to.northing)

      // "From" arrowhead
      svg += drawVArrowhead(fx, fy, bx, by, C_BLACK, 4)
      // "To" arrowhead
      svg += drawVArrowhead(tx, ty, bx, by, C_BLACK, 4)

      svg += `</g>`
    }
  }
  return svg
}

/** Draw a V-shaped arrowhead pointing from tip toward the midpoint */
function drawVArrowhead(tipX: number, tipY: number, midX: number, midY: number, color: string, size: number): string {
  const angle = Math.atan2(midY - tipY, midX - tipX)
  const a1 = angle + Math.PI / 6
  const a2 = angle - Math.PI / 6
  const x1 = tipX + size * Math.cos(a1)
  const y1 = tipY + size * Math.sin(a1)
  const x2 = tipX + size * Math.cos(a2)
  const y2 = tipY + size * Math.sin(a2)
  return `<polygon points="${tipX},${tipY} ${x1},${y1} ${x2},${y2}" fill="${color}"/>`
}

// ─── Layer 8: Area labels ─────────────────────────────────────────────────

function drawAreaLabels(s: RenderState, data: MutationPlanData): string {
  const labelFontSize = mmToPx(3.0)
  let svg = ''

  for (const plot of data.plots) {
    const pts = plot.boundaryPoints
    if (pts.length < 3) continue

    const [ce, cn] = centroid(pts)
    const cx = s.toSvgX(ce)
    const cy = s.toSvgY(cn)

    const areaText = `A = ${plot.area_ha.toFixed(4)} Ha`
    if (plot.isApprox) {
      const mainText = areaText
      const approxText = '(Approx)'
      const approxFontSize = mmToPx(2.2)
      svg += `<text x="${cx}" y="${cy - mmToPx(0.5)}" text-anchor="middle"` +
        ` font-family="${FONT_LABEL}" font-size="${labelFontSize}" fill="${C_BLACK}">` +
        `${escapeXml(mainText)}</text>`
      svg += `<text x="${cx}" y="${cy + mmToPx(2.2)}" text-anchor="middle"` +
        ` font-family="${FONT_LABEL}" font-size="${approxFontSize}" font-style="italic" fill="#555">` +
        `${escapeXml(approxText)}</text>`
    } else {
      svg += `<text x="${cx}" y="${cy + mmToPx(1)}" text-anchor="middle"` +
        ` font-family="${FONT_LABEL}" font-size="${labelFontSize}" fill="${C_BLACK}">` +
        `${escapeXml(areaText)}</text>`
    }

    // Plot ID label (watermark-style, larger, behind area text)
    const idFontSize = mmToPx(6)
    svg += `<text x="${cx}" y="${cy - mmToPx(5)}" text-anchor="middle"` +
      ` font-family="${FONT_LABEL}" font-size="${idFontSize}" font-weight="bold"` +
      ` fill="${C_BLACK}" opacity="0.15">${escapeXml(plot.id.toUpperCase())}</text>`
  }
  return svg
}

// ─── Layer 9: Road corridors ───────────────────────────────────────────────

function drawRoadCorridors(s: RenderState, data: MutationPlanData): string {
  let svg = ''
  const roadFontSize = mmToPx(3.2)
  const bearingFontSize = mmToPx(2.4)

  for (const road of data.roads) {
    if (road.centerline.length < 2) continue

    // Compute road polygon by offsetting centreline
    const roadPoly = computeRoadPolygon(road.centerline, road.width_m)
    if (roadPoly.length < 3) continue

    // Draw road polygon (very light fill)
    const coords = roadPoly.map((p) => `${s.toSvgX(p.easting)},${s.toSvgY(p.northing)}`).join(' ')
    svg += `<polygon points="${coords}" fill="#f0f0f0" stroke="${C_BLACK}" stroke-width="0.8"/>`

    // Centreline dashed
    const clCoords = road.centerline.map((p) => `${s.toSvgX(p.easting)},${s.toSvgY(p.northing)}`).join(' ')
    svg += `<polyline points="${clCoords}" fill="none" stroke="${C_BLACK}" stroke-width="0.4" stroke-dasharray="4,3" opacity="0.5"/>`

    // Road label — vertically stacked, centred at midpoint of centreline
    const [mcE, mcN] = centroid(road.centerline)
    const lx = s.toSvgX(mcE)
    const ly = s.toSvgY(mcN)

    // Split label into words, stack them
    const parts = road.label.split(' ')
    const lineH = mmToPx(3.8)
    const startY = ly - ((parts.length - 1) * lineH) / 2

    parts.forEach((part, i) => {
      svg += `<text x="${lx}" y="${startY + i * lineH + mmToPx(1)}" text-anchor="middle"` +
        ` font-family="${FONT_LABEL}" font-size="${roadFontSize}" font-weight="bold"` +
        ` fill="${C_BLACK}">${escapeXml(part)}</text>`
    })

    // Road bearing label near road edges
    if (road.bearing_dms) {
      // Place bearing near first point of centreline
      const firstPt = road.centerline[0]
      const bx = s.toSvgX(firstPt.easting)
      const by = s.toSvgY(firstPt.northing) - mmToPx(2)
      svg += `<text x="${bx}" y="${by}" text-anchor="middle"` +
        ` font-family="${FONT_LABEL}" font-size="${bearingFontSize}" font-style="italic"` +
        ` fill="#444">${escapeXml(road.bearing_dms)}</text>`
    }
  }
  return svg
}

/**
 * Offset a centreline polyline by half-width to produce a road polygon.
 * Returns array of left-edge points + reversed right-edge points.
 */
function computeRoadPolygon(
  centerline: Array<{ easting: number; northing: number }>,
  widthM: number,
): Array<{ easting: number; northing: number }> {
  const halfW = widthM / 2
  const leftEdge: Array<{ easting: number; northing: number }> = []
  const rightEdge: Array<{ easting: number; northing: number }> = []

  for (let i = 0; i < centerline.length; i++) {
    const prev = centerline[(i - 1 + centerline.length) % centerline.length]
    const curr = centerline[i]
    const next = centerline[(i + 1) % centerline.length]

    // Average direction
    const dx1 = curr.easting - prev.easting
    const dy1 = curr.northing - prev.northing
    const dx2 = next.easting - curr.easting
    const dy2 = next.northing - curr.northing
    const dx = dx1 + dx2
    const dy = dy1 + dy2
    const len = Math.sqrt(dx * dx + dy * dy) || 1

    // Perpendicular direction
    const perpE = -dy / len
    const perpN = dx / len

    leftEdge.push({
      easting: curr.easting + perpE * halfW,
      northing: curr.northing + perpN * halfW,
    })
    rightEdge.push({
      easting: curr.easting - perpE * halfW,
      northing: curr.northing - perpN * halfW,
    })
  }

  return [...leftEdge, ...rightEdge.reverse()]
}

// ─── Layer 10: Survey monuments ───────────────────────────────────────────

function drawSurveyMonuments(s: RenderState, data: MutationPlanData): string {
  let svg = ''
  const labelFontSize = mmToPx(2.2)
  const monumentSize = mmToPx(1.5)

  for (const m of data.monuments) {
    const cx = s.toSvgX(m.easting)
    const cy = s.toSvgY(m.northing)

    if (m.type === 'control') {
      // Filled square for control monuments
      svg += `<rect x="${cx - monumentSize}" y="${cy - monumentSize}"` +
        ` width="${monumentSize * 2}" height="${monumentSize * 2}"` +
        ` fill="none" stroke="${C_BLACK}" stroke-width="1"/>`
      svg += `<line x1="${cx - monumentSize * 0.6}" y1="${cy}" x2="${cx + monumentSize * 0.6}" y2="${cy}"` +
        ` stroke="${C_BLACK}" stroke-width="0.6"/>`
      svg += `<line x1="${cx}" y1="${cy - monumentSize * 0.6}" x2="${cx}" y2="${cy + monumentSize * 0.6}"` +
        ` stroke="${C_BLACK}" stroke-width="0.6"/>`
    } else {
      // Unfilled circle for intermediate
      svg += `<circle cx="${cx}" cy="${cy}" r="${monumentSize}" fill="none" stroke="${C_BLACK}" stroke-width="0.8"/>`
    }

    // Label
    svg += `<text x="${cx + monumentSize + mmToPx(1)}" y="${cy - mmToPx(0.5)}"` +
      ` font-family="${FONT_LABEL}" font-size="${labelFontSize}" font-weight="bold"` +
      ` fill="${C_BLACK}">${escapeXml(m.id)}</text>`
  }
  return svg
}

// ─── Layer 11: Bearing schedule table ──────────────────────────────────────

function drawBearingScheduleTable(s: RenderState, data: MutationPlanData): string {
  const schedule = data.bearingSchedule
  if (schedule.length === 0) return ''

  const marginInner = mmToPx(BORDER_INNER_INSET)
  const tableX = marginInner + mmToPx(4)
  const tableMaxW = mmToPx(95) // Max table width
  const rowH = mmToPx(4)
  const headerH = mmToPx(6)
  const maxRows = Math.min(schedule.length, 20)
  const tableH = headerH + maxRows * rowH + mmToPx(6) // +6 for title row
  const tableY = marginInner + mmToPx(4)
  const tableW = Math.min(tableMaxW, s.drawW * 0.28)

  const colWidths = [
    tableW * 0.12,  // #
    tableW * 0.18,  // From
    tableW * 0.18,  // To
    tableW * 0.34,  // Bearing
    tableW * 0.18,  // Distance
  ]
  const headerFontSize = mmToPx(2.2)
  const dataFontSize = mmToPx(2.0)
  const titleFontSize = mmToPx(2.8)

  let svg = `<g class="bearing-schedule">`

  // Table background
  svg += `<rect x="${tableX}" y="${tableY}" width="${tableW}" height="${tableH}"` +
    ` fill="white" fill-opacity="0.92" stroke="${C_BLACK}" stroke-width="0.5"/>`

  // Title
  svg += `<text x="${tableX + tableW / 2}" y="${tableY + mmToPx(3.5)}" text-anchor="middle"` +
    ` font-family="${FONT_FORM}" font-size="${titleFontSize}" font-weight="bold"` +
    ` fill="${C_BLACK}">BEARING SCHEDULE</text>`

  // Header row separator
  const hdrY = tableY + mmToPx(5)
  svg += `<line x1="${tableX}" y1="${hdrY}" x2="${tableX + tableW}" y2="${hdrY}"` +
    ` stroke="${C_BLACK}" stroke-width="0.5"/>`

  // Column headers
  const headers = ['Line', 'From', 'To', 'Bearing', 'Dist (m)']
  let hx = tableX
  headers.forEach((h, i) => {
    svg += `<text x="${hx + colWidths[i] / 2}" y="${hdrY + mmToPx(2.2)}" text-anchor="middle"` +
      ` font-family="${FONT_FORM}" font-size="${headerFontSize}" font-weight="bold"` +
      ` fill="#555">${h}</text>`
    hx += colWidths[i]
  })

  // Data rows
  const rows = schedule.slice(0, maxRows)
  rows.forEach((entry, i) => {
    const ry = hdrY + rowH * (i + 1)
    // Row separator
    if (i > 0) {
      svg += `<line x1="${tableX}" y1="${ry}" x2="${tableX + tableW}" y2="${ry}"` +
        ` stroke="${C_BLACK}" stroke-width="0.2" opacity="0.4"/>`
    }

    let cx = tableX
    const cells = [
      entry.lineId,
      entry.from,
      entry.to,
      entry.bearing_dms,
      entry.distance_m.toFixed(3),
    ]
    cells.forEach((cell, ci) => {
      svg += `<text x="${cx + colWidths[ci] / 2}" y="${ry + mmToPx(2)}" text-anchor="middle"` +
        ` font-family="${FONT_FORM}" font-size="${dataFontSize}" fill="${C_BLACK}">` +
        `${escapeXml(cell)}</text>`
      cx += colWidths[ci]
    })
  })

  svg += `</g>`
  return svg
}

// ─── Layer 12: Authentication block ────────────────────────────────────────

function drawAuthBlock(s: RenderState, data: MutationPlanData): string {
  const p = data.project
  const marginInner = mmToPx(BORDER_INNER_INSET)
  const blockW = mmToPx(130)
  const blockH = mmToPx(AUTH_BLOCK_H_MM)
  const blockX = s.pageW - marginInner - blockW
  const blockY = s.pageH - marginInner - mmToPx(TITLE_BLOCK_H_MM) - blockH - mmToPx(4)

  const headerFontSize = mmToPx(2.5)
  const fieldFontSize = mmToPx(2.2)
  const smallFontSize = mmToPx(1.8)
  const lineH = mmToPx(3.5)
  const labelFontSize = mmToPx(2.0)

  let svg = `<g class="auth-block">`

  // Block background
  svg += `<rect x="${blockX}" y="${blockY}" width="${blockW}" height="${blockH}"` +
    ` fill="white" fill-opacity="0.93" stroke="${C_BLACK}" stroke-width="0.5"/>`

  // Title
  svg += `<text x="${blockX + blockW / 2}" y="${blockY + mmToPx(4)}" text-anchor="middle"` +
    ` font-family="${FONT_FORM}" font-size="${headerFontSize}" font-weight="bold"` +
    ` fill="${C_BLACK}">AUTHENTICATION</text>`

  // Separator
  const sepY = blockY + mmToPx(5.5)
  svg += `<line x1="${blockX}" y1="${sepY}" x2="${blockX + blockW}" y2="${sepY}"` +
    ` stroke="${C_BLACK}" stroke-width="0.4"/>`

  // "FOR DIRECTOR OF SURVEYS" sub-header
  svg += `<text x="${blockX + blockW / 2}" y="${sepY + mmToPx(3)}" text-anchor="middle"` +
    ` font-family="${FONT_FORM}" font-size="${smallFontSize}" font-weight="bold"` +
    ` fill="#555">FOR DIRECTOR OF SURVEYS</text>`

  // Surveyor details section
  let y = sepY + mmToPx(6)
  const leftPad = blockX + mmToPx(4)
  const rightPad = blockX + blockW - mmToPx(4)
  const fieldPad = mmToPx(2)

  svg += `<text x="${leftPad}" y="${y}" font-family="${FONT_FORM}" font-size="${labelFontSize}" font-weight="bold" fill="#555">SURVEYOR DETAILS</text>`
  y += lineH

  const surveyorFields = [
    ['Surveyor', p.surveyor_name || '________________________'],
    ['Licence No.', p.surveyor_licence ? `LS/${p.surveyor_licence}` : '________________________'],
    ['Date', p.date || '________________________'],
  ]

  surveyorFields.forEach(([label, value]) => {
    svg += `<text x="${leftPad}" y="${y}" font-family="${FONT_FORM}" font-size="${fieldFontSize}" fill="#555">${escapeXml(label)}:</text>`
    svg += `<text x="${rightPad}" y="${y}" text-anchor="end" font-family="${FONT_FORM}" font-size="${fieldFontSize}" font-weight="bold" fill="${C_BLACK}">${escapeXml(value)}</text>`
    y += lineH
  })

  // Signature line
  y += mmToPx(1)
  svg += `<line x1="${leftPad}" y1="${y}" x2="${rightPad}" y2="${y}" stroke="${C_BLACK}" stroke-width="0.4"/>`
  svg += `<text x="${leftPad}" y="${y + mmToPx(2.5)}" font-family="${FONT_FORM}" font-size="${smallFontSize}" fill="#555">Signature of Licensed Surveyor</text>`

  // Director of Surveys authentication fields
  y += mmToPx(6)
  svg += `<line x1="${leftPad}" y1="${y}" x2="${rightPad}" y2="${y}" stroke="${C_BLACK}" stroke-width="0.4"/>`

  y += mmToPx(3)
  const authFields = [
    ['Examined by', '________________________'],
    ['Approved by', '________________________'],
    ['Authenticated by', '________________________'],
  ]

  authFields.forEach(([label, value]) => {
    svg += `<text x="${leftPad}" y="${y}" font-family="${FONT_FORM}" font-size="${fieldFontSize}" fill="#555">${escapeXml(label)}:</text>`
    svg += `<text x="${rightPad}" y="${y}" text-anchor="end" font-family="${FONT_FORM}" font-size="${smallFontSize}" fill="#555">Date: ___________</text>`
    y += lineH
  })

  // Seal placeholder
  const sealW = mmToPx(25)
  const sealH = mmToPx(12)
  const sealX = rightPad - sealW
  const sealY = y + mmToPx(1)
  svg += `<rect x="${sealX}" y="${sealY}" width="${sealW}" height="${sealH}"` +
    ` fill="none" stroke="${C_BLACK}" stroke-width="0.3" stroke-dasharray="2,2"/>`
  svg += `<text x="${sealX + sealW / 2}" y="${sealY + mmToPx(5)}" text-anchor="middle"` +
    ` font-family="${FONT_FORM}" font-size="${smallFontSize}" fill="#888">SEAL OF SURVEY</text>`
  svg += `<text x="${sealX + sealW / 2}" y="${sealY + mmToPx(8)}" text-anchor="middle"` +
    ` font-family="${FONT_FORM}" font-size="${smallFontSize}" fill="#888">OF KENYA</text>`

  svg += `</g>`
  return svg
}

// ─── Layer 13: Title block (bottom strip) ──────────────────────────────────

function drawTitleBlock(s: RenderState, data: MutationPlanData): string {
  const p = data.project
  const marginInner = mmToPx(BORDER_INNER_INSET)
  const blockH = mmToPx(TITLE_BLOCK_H_MM)
  const blockY = s.pageH - marginInner - blockH
  const blockX = marginInner
  const blockW = s.pageW - 2 * marginInner

  const titleFontSize = mmToPx(4)
  const fieldFontSize = mmToPx(2.8)
  const smallFontSize = mmToPx(2.0)
  const labelFontSize = mmToPx(2.2)

  let svg = `<g class="title-block">`

  // Background
  svg += `<rect x="${blockX}" y="${blockY}" width="${blockW}" height="${blockH}"` +
    ` fill="#fafafa" stroke="${C_BLACK}" stroke-width="0.8"/>`

  // Top separator line (double)
  svg += `<line x1="${blockX}" y1="${blockY}" x2="${blockX + blockW}" y2="${blockY}"` +
    ` stroke="${C_BLACK}" stroke-width="1.5"/>`
  svg += `<line x1="${blockX}" y1="${blockY + mmToPx(1)}" x2="${blockX + blockW}" y2="${blockY + mmToPx(1)}"` +
    ` stroke="${C_BLACK}" stroke-width="0.4"/>`

  // Column layout: left (project info) | centre (form title) | right (folio/register)
  const leftSectionX = blockX + mmToPx(5)
  const centreSectionX = blockX + blockW * 0.35
  const rightSectionX = blockX + blockW * 0.65
  const rightEdgeX = blockX + blockW - mmToPx(5)

  let y = blockY + mmToPx(5)

  // ── Left section: project metadata ──
  const leftFields = [
    ['Registration District', p.registrationDistrict],
    ['Locality', p.locality],
    ['Location', p.location],
    ['Cadastral Sheet', p.cadastralSheet],
    ['RIM Reference', p.rimReference],
  ]

  leftFields.forEach(([label, value]) => {
    if (!value) return
    svg += `<text x="${leftSectionX}" y="${y}" font-family="${FONT_FORM}" font-size="${smallFontSize}" fill="#555">${escapeXml(label)}:</text>`
    svg += `<text x="${centreSectionX - mmToPx(3)}" y="${y}" text-anchor="end" font-family="${FONT_FORM}" font-size="${smallFontSize}" font-weight="bold" fill="${C_BLACK}">${escapeXml(value)}</text>`
    y += mmToPx(3.5)
  })

  // ── Centre section: form title & scale ──
  let cy = blockY + mmToPx(6)
  svg += `<text x="${centreSectionX + (rightSectionX - centreSectionX) / 2}" y="${cy}" text-anchor="middle"` +
    ` font-family="${FONT_LABEL}" font-size="${titleFontSize}" font-weight="bold"` +
    ` fill="${C_BLACK}">MUTATION SURVEY PLAN</text>`
  cy += mmToPx(5.5)

  svg += `<text x="${centreSectionX + (rightSectionX - centreSectionX) / 2}" y="${cy}" text-anchor="middle"` +
    ` font-family="${FONT_FORM}" font-size="${fieldFontSize}" font-weight="bold"` +
    ` fill="#333">Form No. 3</text>`
  cy += mmToPx(5)

  svg += `<text x="${centreSectionX + (rightSectionX - centreSectionX) / 2}" y="${cy}" text-anchor="middle"` +
    ` font-family="${FONT_FORM}" font-size="${smallFontSize}" fill="#555">Survey Act Cap. 299</text>`
  cy += mmToPx(3.5)

  // Datum & zone
  const datum = p.datum || 'ARC1960'
  const zone = `${p.utmZone || 37}${p.hemisphere || 'S'}`
  svg += `<text x="${centreSectionX + (rightSectionX - centreSectionX) / 2}" y="${cy}" text-anchor="middle"` +
    ` font-family="${FONT_FORM}" font-size="${smallFontSize}" fill="#555">${escapeXml(datum)} / UTM Zone ${escapeXml(zone)}</text>`
  cy += mmToPx(3.5)

  // Scale
  svg += `<text x="${centreSectionX + (rightSectionX - centreSectionX) / 2}" y="${cy}" text-anchor="middle"` +
    ` font-family="${FONT_FORM}" font-size="${fieldFontSize}" font-weight="bold"` +
    ` fill="${C_BLACK}">SCALE 1 : ${s.scale.toLocaleString()}</text>`
  cy += mmToPx(4)

  // Survey regulations reference
  svg += `<text x="${centreSectionX + (rightSectionX - centreSectionX) / 2}" y="${cy}" text-anchor="middle"` +
    ` font-family="${FONT_FORM}" font-size="${mmToPx(1.6)}" fill="#888">Survey Regulations 1994 | RDM 1.1 §5</text>`

  // ── Right section: folio / register numbers ──
  let ry = blockY + mmToPx(6)

  if (p.folioNumber) {
    svg += `<text x="${rightSectionX + (rightEdgeX - rightSectionX) / 2}" y="${ry}" text-anchor="middle"` +
      ` font-family="${FONT_LABEL}" font-size="${labelFontSize}" fill="#555">FOLIO No.</text>`
    ry += mmToPx(3.5)
    svg += `<text x="${rightSectionX + (rightEdgeX - rightSectionX) / 2}" y="${ry}" text-anchor="middle"` +
      ` font-family="${FONT_LABEL}" font-size="${fieldFontSize}" font-weight="bold"` +
      ` fill="${C_BLACK}">${escapeXml(p.folioNumber)}</text>`
    ry += mmToPx(5)
  }

  if (p.registerNumber) {
    svg += `<text x="${rightSectionX + (rightEdgeX - rightSectionX) / 2}" y="${ry}" text-anchor="middle"` +
      ` font-family="${FONT_LABEL}" font-size="${labelFontSize}" fill="#555">REGISTER No.</text>`
    ry += mmToPx(3.5)
    svg += `<text x="${rightSectionX + (rightEdgeX - rightSectionX) / 2}" y="${ry}" text-anchor="middle"` +
      ` font-family="${FONT_LABEL}" font-size="${fieldFontSize}" font-weight="bold"` +
      ` fill="${C_BLACK}">${escapeXml(p.registerNumber)}</text>`
    ry += mmToPx(5)
  }

  if (p.transactions) {
    svg += `<text x="${rightSectionX + (rightEdgeX - rightSectionX) / 2}" y="${ry}" text-anchor="middle"` +
      ` font-family="${FONT_LABEL}" font-size="${labelFontSize}" fill="#555">TRANSACTION(s)</text>`
    ry += mmToPx(3.5)
    svg += `<text x="${rightSectionX + (rightEdgeX - rightSectionX) / 2}" y="${ry}" text-anchor="middle"` +
      ` font-family="${FONT_LABEL}" font-size="${fieldFontSize}" font-weight="bold"` +
      ` fill="${C_BLACK}">${escapeXml(p.transactions)}</text>`
  }

  // Surveyor name & licence (right section bottom)
  ry = blockY + blockH - mmToPx(8)
  svg += `<text x="${rightSectionX + (rightEdgeX - rightSectionX) / 2}" y="${ry}" text-anchor="middle"` +
    ` font-family="${FONT_FORM}" font-size="${smallFontSize}" fill="#555">` +
    `${escapeXml(p.surveyor_name || '')}  |  LS/${escapeXml(p.surveyor_licence || '')}</text>`

  svg += `</g>`
  return svg
}

// ─── Layer 14: North arrow & scale bar ─────────────────────────────────────

function drawNorthArrowAndScaleBar(s: RenderState, data: MutationPlanData): string {
  let svg = ''

  // ── North arrow (blue filled polygon) ──
  const arrowSize = mmToPx(18)
  const arrowX = s.drawX + s.drawW - mmToPx(18)
  const arrowY = s.drawY + mmToPx(18)
  const shaftW = mmToPx(1.2)
  const shaftH = arrowSize * 0.55
  const headW = arrowSize * 0.35
  const headH = arrowSize * 0.45
  const nLabelSize = mmToPx(4)

  // Arrow points upward (north). Tip at top.
  const tipY = arrowY - shaftH - headH
  const baseY = arrowY - shaftH

  svg += `<g class="north-arrow">`
  // Shaft
  svg += `<rect x="${arrowX - shaftW / 2}" y="${baseY}" width="${shaftW}" height="${shaftH}" fill="#1a5276"/>`
  // North arrowhead (filled blue)
  svg += `<polygon points="${arrowX},${tipY} ${arrowX - headW},${baseY} ${arrowX + headW},${baseY}" fill="#1a5276"/>`
  // South half (unfilled outline)
  const southBaseY = arrowY + headH
  svg += `<polygon points="${arrowX},${southBaseY} ${arrowX - headW},${arrowY} ${arrowX + headW},${arrowY}"` +
    ` fill="none" stroke="#1a5276" stroke-width="0.8"/>`
  // South shaft
  svg += `<rect x="${arrowX - shaftW / 2}" y="${arrowY}" width="${shaftW}" height="${headH}" fill="none" stroke="#1a5276" stroke-width="0.5"/>`
  // N label
  svg += `<text x="${arrowX}" y="${tipY - mmToPx(2)}" text-anchor="middle"` +
    ` font-family="${FONT_LABEL}" font-size="${nLabelSize}" font-weight="bold" fill="#1a5276">N</text>`
  svg += `</g>`

  // ── Scale bar ──
  const scaleBarW = mmToPx(50)
  const scaleBarH = mmToPx(3)
  const scaleBarX = s.drawX + s.drawW - mmToPx(18) - scaleBarW
  const scaleBarY = arrowY + arrowSize / 2 + mmToPx(8)
  const numSegments = 4

  // Determine what ground distance the bar represents
  const barGroundDist = (scaleBarW / PX_PER_MM) * s.scale / 1000 // km equivalent
  const segmentMetres = Math.round((barGroundDist * 1000) / numSegments)

  svg += `<g class="scale-bar">`
  for (let i = 0; i < numSegments; i++) {
    const segX = scaleBarX + i * (scaleBarW / numSegments)
    const segW = scaleBarW / numSegments
    if (i % 2 === 0) {
      svg += `<rect x="${segX}" y="${scaleBarY}" width="${segW}" height="${scaleBarH}" fill="${C_BLACK}"/>`
    } else {
      svg += `<rect x="${segX}" y="${scaleBarY}" width="${segW}" height="${scaleBarH}" fill="white" stroke="${C_BLACK}" stroke-width="0.5"/>`
    }
  }
  // Border
  svg += `<rect x="${scaleBarX}" y="${scaleBarY}" width="${scaleBarW}" height="${scaleBarH}" fill="none" stroke="${C_BLACK}" stroke-width="0.8"/>`

  // Labels below
  const labelY = scaleBarY + scaleBarH + mmToPx(3)
  const labelFontSize = mmToPx(2)
  for (let i = 0; i <= numSegments; i++) {
    const lx = scaleBarX + i * (scaleBarW / numSegments)
    const val = i * segmentMetres
    svg += `<text x="${lx}" y="${labelY}" text-anchor="middle"` +
      ` font-family="${FONT_FORM}" font-size="${labelFontSize}" fill="${C_BLACK}">${val}</text>`
  }

  // "METRES" label
  svg += `<text x="${scaleBarX + scaleBarW / 2}" y="${labelY + mmToPx(2.5)}" text-anchor="middle"` +
    ` font-family="${FONT_FORM}" font-size="${mmToPx(1.8)}" fill="#555">METRES</text>`

  // Scale text
  svg += `<text x="${scaleBarX + scaleBarW / 2}" y="${labelY + mmToPx(4.5)}" text-anchor="middle"` +
    ` font-family="${FONT_FORM}" font-size="${mmToPx(2.2)}" font-weight="bold" fill="${C_BLACK}">SCALE 1 : ${s.scale.toLocaleString()}</text>`

  svg += `</g>`

  return svg
}

/**
 * Form No. 4 Survey Plan Renderer Extension
 * Kenya Land Office compliant survey plan rendering
 * Extends base SurveyPlanRenderer with Form No. 4 specific features
 */

import { createHash } from 'crypto'
import { SurveyPlanRenderer } from './renderer'
import type { SurveyPlanData, PlanOptions, CoordinateScheduleEntry } from './types'
import { getRoadReserveWidth } from './types'
import {
  DPI, PX_PER_MM, PX_PER_M,
  PAGE_WIDTH_MM, PAGE_HEIGHT_MM,
  mmToPx,
} from './geometry'
import {
  escapeXml,
  C_BLACK, C_GREEN, C_RED,
} from './symbols'

/**
 * Extended SurveyPlanRenderer that produces Form No. 4 compliant output
 */
export class FormNo4Renderer extends SurveyPlanRenderer {
  private formNo4Data: FormNo4Data

  constructor(data: SurveyPlanData, options?: PlanOptions & { submissionNumber?: string }) {
    super(data, options)
    this.formNo4Data = this.extractFormNo4Data(data, options?.submissionNumber)
  }

  private extractFormNo4Data(data: SurveyPlanData, submissionNumber?: string): FormNo4Data {
    const p = data.project
    return {
      folioNumber: p.folioNumber || '',
      registerNumber: p.registerNumber || '',
      lrNumber: p.lrNumber || '',
      plotParcelNumber: p.plotParcelNumber || '',
      refMapRIM: p.refMapRIM || '',
      registrationBlock: p.registrationBlock || '',
      registrationDistrict: p.registrationDistrict || '',
      locality: p.locality || '',
      formNumber: p.formNumber || 'Form No. 4',
      computationsNo: p.computationsNo || '',
      fieldBookNo: p.fieldBookNo || '',
      dateReceived: p.dateReceived || '',
      fileReference: p.fileReference || '',
      scale: p.scale || `1:${this.getScale()}`,
      firNumber: p.firNumber || '',
      submissionNumber: submissionNumber || '',
      // Authentication block
      examinedBy: '',
      examinedDate: '',
      approvedBy: '',
      approvedDate: '',
      authenticatedBy: '',
      authenticatedDate: '',
      // Surveyor declaration — per Survey Act Cap. 299, Form No. 4
      declarationText: `I, ${p.surveyor_name || '[SURVEYOR NAME]'}, a Licensed Surveyor ${p.surveyor_licence ? '(LS/' + p.surveyor_licence + ')' : '(LS/_______________)'}, ${p.iskRegNo ? 'ISK Reg. No. ' + p.iskRegNo + ',' : ''} hereby certify that this survey was carried out under my direct supervision in accordance with the Survey Act Cap. 299 and the Survey Regulations 1994, and that all measurements, computations and beacon placements are correct.`,
      declarationDate: new Date().toLocaleDateString('en-GB'),
      letterNo: '',
      // Surveyor credentials for stamp area
      surveyorName: p.surveyor_name || '',
      surveyorLicence: p.surveyor_licence || '',
      iskRegNo: p.iskRegNo || '',
      firmName: p.firm_name || '',
    }
  }

  /**
   * Render Form No. 4 compliant survey plan
   */
  renderFormNo4(): string {
    const layers: string[] = []
    
    // Base layers
    layers.push(this.drawBackground())
    layers.push(this.drawSheetBorder())
    layers.push(this.drawPanelDivider())
    layers.push(this.drawGrid())
    layers.push(this.drawLotFill())
    
    // Form No. 4 specific layers
    layers.push(this.drawCoordinateTables())
    layers.push(this.drawLRNumbersOnParcels())
    layers.push(this.drawRoadAnnotations())
    
    // Standard layers
    layers.push(this.drawAdjacentLots())
    layers.push(this.drawRoadTruncationLines())
    layers.push(this.drawBoundary())
    layers.push(this.drawBoundaryLabels())
    layers.push(this.drawBoundaryAdjacentLRNumbers())
    layers.push(this.drawMonuments())
    layers.push(this.drawNorthArrow())
    layers.push(this.drawScaleBar())
    
    // Form No. 4 panels and footer
    layers.push(this.drawFormNo4RightPanel())
    layers.push(this.drawFormNo4TitleBlock())
    layers.push(this.drawSubmissionNumberHeader())
    layers.push(this.drawLegalReferenceLine())
    layers.push(this.drawPrintVerification())
    
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${this.pageW} ${this.pageH}" width="${this.pageW}" height="${this.pageH}" style="font-family: 'JetBrains Mono', 'Courier New', monospace;">${layers.join('\n')}</svg>`
  }

  /**
   * Draw coordinate tables (Form No. 4 Rule 1)
   * Split into left and right tables
   */
  private drawCoordinateTables(): string {
    const controlPts = this.getControlPoints()
    if (controlPts.length === 0) return ''

    // Split beacons: P/K-series on left, N/D-series on right
const leftSideBeacons = controlPts.filter(p =>
  p.station.startsWith('P') || p.station.startsWith('K')
)
const rightSideBeacons = controlPts.filter(p =>
  p.station.startsWith('N') || p.station.startsWith('D')
)

    let svg = ''
    
    // Left table
    if (leftSideBeacons.length > 0) {
      svg += this.drawCoordinateTable(leftSideBeacons, 'left', mmToPx(15), mmToPx(25))
    }
    
    // Right table
    if (rightSideBeacons.length > 0) {
svg += this.drawCoordinateTable(rightSideBeacons, 'right',
      this.pageW - mmToPx(15) - mmToPx(65), mmToPx(25))
    }

    return svg
  }

  private drawCoordinateTable(
    beacons: CoordinateScheduleEntry[],
    side: 'left' | 'right',
    x: number,
    y: number
  ): string {
    const colWidths = [mmToPx(15), mmToPx(18), mmToPx(18), mmToPx(12), mmToPx(12)]
    const rowHeight = mmToPx(6)
    const tableWidth = colWidths.reduce((a, b) => a + b, 0)
    const tableHeight = rowHeight * (beacons.length + 1)

    let svg = `<g class="coordinate-table-${side}">`
    
    // Table border
    svg += `<rect x="${x}" y="${y}" width="${tableWidth}" height="${tableHeight}" fill="white" stroke="${C_BLACK}" stroke-width="0.5"/>`
    
    // Header
    const headers = ['Station', 'Northings', 'Eastings', 'Heights', 'Class']
    let hx = x
    headers.forEach((h, i) => {
      svg += `<rect x="${hx}" y="${y}" width="${colWidths[i]}" height="${rowHeight}" fill="#f0f0f0" stroke="${C_BLACK}" stroke-width="0.3"/>`
      svg += `<text x="${hx + colWidths[i]/2}" y="${y + rowHeight/2 + 2}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="6" font-weight="bold" fill="${C_BLACK}">${h}</text>`
      hx += colWidths[i]
    })

    // Data rows
    beacons.forEach((beacon, rowIdx) => {
      const rowY = y + rowHeight * (rowIdx + 1)
      hx = x
      
      const cells = [
        beacon.station,
        beacon.northing.toFixed(4),
        beacon.easting.toFixed(4),
        beacon.height?.toFixed(3) || '—',
        this.formatBeaconClass(beacon.beaconClass)
      ]
      
      cells.forEach((cell, i) => {
        svg += `<rect x="${hx}" y="${rowY}" width="${colWidths[i]}" height="${rowHeight}" fill="white" stroke="${C_BLACK}" stroke-width="0.3"/>`
        svg += `<text x="${hx + (i < 1 ? 2 : colWidths[i]/2)}" y="${rowY + rowHeight/2 + 2}" text-anchor="${i < 1 ? 'start' : 'middle'}" font-family="JetBrains Mono, Courier New" font-size="5.5" fill="${C_BLACK}">${escapeXml(cell)}</text>`
        hx += colWidths[i]
      })
    })

    svg += '</g>'
    return svg
  }

  private formatBeaconClass(cls: string): string {
    const map: Record<string, string> = {
      'new': 'New',
      'old': 'Old',
      'theoretical': 'Theoretical',
      'IPCU': 'I.P.C.U.'
    }
    return map[cls] || cls
  }

  /**
   * Draw LR numbers on parcels (Form No. 4 Rule 4)
   */
private drawLRNumbersOnParcels(): string {
  const p = this.data.project
    if (!p.lrNumber) return ''

    const boundaryPts = this.rotatedPoints
    if (boundaryPts.length < 3) return ''

    // Calculate centroid of parcel
    const centroid = this.calculateCentroid(boundaryPts)
  const cx = this.toSvgX(centroid.easting)
  const cy = this.toSvgY(centroid.northing)

  const parcelArea = this.data.parcel.area_sqm || 0
    const areaHa = (parcelArea / 10000).toFixed(4)

    let svg = ''
    
    // LR Number label
    svg += `<text x="${cx}" y="${cy - 10}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="11" font-weight="bold" fill="${C_BLACK}">LR No. ${escapeXml(p.lrNumber)}</text>`
    
    // Area label
    svg += `<text x="${cx}" y="${cy + 2}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="9" fill="${C_BLACK}">A=co=${areaHa} Ha</text>`
    
    // DP Number if available
    if (p.plotParcelNumber) {
      svg += `<text x="${cx}" y="${cy + 14}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="8" fill="${C_BLACK}">D.P No. ${escapeXml(p.plotParcelNumber)}</text>`
    }

    return svg
  }

  /**
   * Draw road annotations for Form No. 4.
   * Shows road reserve width annotation and truncation note using actual
   * road class data. The base class drawRoadTruncationLines() provides
   * the actual tick marks along road boundaries.
   */
  private drawRoadAnnotations(): string {
  const p = this.data.project

  const minE = Math.min(...this.rotatedPoints.map(pt => pt.easting))
  const maxE = Math.max(...this.rotatedPoints.map(pt => pt.easting))
  const minN = Math.min(...this.rotatedPoints.map(pt => pt.northing))
    
    const cx = this.toSvgX((minE + maxE) / 2)
    const cy = this.toSvgY(minN) + mmToPx(15)

    let svg = ''

    // Compute actual road reserve width from project road_class
    const roadClass = p.road_class
    const roadWidth = roadClass ? getRoadReserveWidth(roadClass) : 0
    const widthText = roadWidth > 0 ? `All new roads are ${roadWidth.toFixed(2)}m Wide` : 'All new roads are 12.00m Wide'
    
    // Road width note with actual width value
    svg += `<text x="${cx}" y="${cy}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="7" fill="${C_BLACK}">${widthText}</text>`
    
    // Road truncation note
    svg += `<text x="${cx}" y="${cy + mmToPx(5)}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="7" fill="${C_BLACK}">All road truncations ±6mm</text>`

    return svg
  }

  /**
   * Draw Form No. 4 right panel
   */
private drawFormNo4RightPanel(): string {
  const p = this.data.project
  const d = this.formNo4Data
  const panelX = this.panelX
  const panelW = this.panelW
    const margin = mmToPx(10)
    
    let y = margin + mmToPx(5)
    let svg = `<g class="form-no-4-panel">`

    // Title
    svg += `<text x="${panelX + panelW/2}" y="${y}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="10" font-weight="bold" fill="${C_BLACK}">SURVEYOR'S PLAN</text>`
    y += mmToPx(6)
    
    // Form number
    svg += `<text x="${panelX + panelW/2}" y="${y}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="9" fill="${C_BLACK}">${d.formNumber}</text>`
    y += mmToPx(8)

    // Plan info box
    const infoFields = [
      ['Registration District', d.registrationDistrict || p.location?.split(',')[0] || ''],
      ['Locality', d.locality || p.location || ''],
      ['LR Number', d.lrNumber],
      ['Folio Number', d.folioNumber],
      ['Register Number', d.registerNumber],
      ['FIR Number', d.firNumber],
      ['Scale', d.scale],
      ['Datum', p.datum || 'ARC1960'],
      ['UTM Zone', `${p.utm_zone || 37}${p.hemisphere || 'S'}`],
    ]

    svg += `<rect x="${panelX + margin/2}" y="${y}" width="${panelW - margin}" height="${mmToPx(50)}" fill="#f9f9f9" stroke="${C_BLACK}" stroke-width="0.5"/>`
    
    let fieldY = y + mmToPx(5)
    infoFields.forEach(([label, value]) => {
      if (value) {
        svg += `<text x="${panelX + margin}" y="${fieldY}" font-family="JetBrains Mono, Courier New" font-size="6" fill="#555">${escapeXml(label)}:</text>`
        svg += `<text x="${panelX + panelW - margin}" y="${fieldY}" text-anchor="end" font-family="JetBrains Mono, Courier New" font-size="6" font-weight="bold" fill="${C_BLACK}">${escapeXml(value)}</text>`
        fieldY += mmToPx(5)
      }
    })
    
    y += mmToPx(55)

    // Legend
    svg += this.drawFormNo4Legend(panelX + margin/2, y, panelW - margin)
    y += mmToPx(40)

    // Revision history
    svg += this.drawFormNo4RevisionHistory(panelX + margin/2, y, panelW - margin)
    y += mmToPx(22)

    // Surveyor certificate
    svg += this.drawSurveyorCertificateInternal(panelX + margin/2, y, panelW - margin)

    svg += '</g>'
    return svg
  }

  private drawFormNo4Legend(x: number, y: number, w: number): string {
    let svg = `<rect x="${x}" y="${y}" width="${w}" height="${mmToPx(35)}" fill="#fafafa" stroke="${C_BLACK}" stroke-width="0.5"/>`
    svg += `<text x="${x + w/2}" y="${y + mmToPx(5)}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="7" font-weight="bold" fill="${C_BLACK}">LEGEND</text>`
    
    const items = [
      { symbol: '■', color: C_GREEN, label: 'Found Monument' },
      { symbol: '○', color: C_GREEN, label: 'Set Monument' },
      { symbol: '●', color: C_RED, label: 'Masonry Nail' },
      { symbol: '---', color: C_BLACK, label: 'Boundary Line' },
    ]
    
    let itemY = y + mmToPx(10)
    items.forEach(item => {
      svg += `<text x="${x + mmToPx(3)}" y="${itemY}" font-family="JetBrains Mono, Courier New" font-size="10" fill="${item.color}">${item.symbol}</text>`
      svg += `<text x="${x + mmToPx(8)}" y="${itemY}" font-family="JetBrains Mono, Courier New" font-size="6" fill="${C_BLACK}">${item.label}</text>`
      itemY += mmToPx(6)
    })
    
    return svg
  }

  /**
   * Draw revision history table (Form No. 4 Rule 7)
   * Shows all revisions to the plan with date, description, and surveyor.
   * Per Survey Act Cap. 299, every amendment to a registered plan must
   * be recorded with a revision entry.
   */
  private drawFormNo4RevisionHistory(x: number, y: number, w: number): string {
    const p = this.data.project
    const revisions = p.revisions || []
    const h = mmToPx(20)

    let svg = `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="white" stroke="${C_BLACK}" stroke-width="0.5"/>`
    svg += `<text x="${x + w/2}" y="${y + mmToPx(4)}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="6" font-weight="bold" fill="${C_BLACK}">REVISION HISTORY</text>`
    svg += `<line x1="${x}" y1="${y + mmToPx(5.5)}" x2="${x + w}" y2="${y + mmToPx(5.5)}" stroke="${C_BLACK}" stroke-width="0.3"/>`

    // Column headers
    const colWidths = [mmToPx(8), mmToPx(18), mmToPx(32), mmToPx(18)]
    const headers = ['Rev', 'Date', 'Description', 'By']
    let hx = x
    headers.forEach((h, i) => {
      svg += `<text x="${hx + 1}" y="${y + mmToPx(8)}" font-family="JetBrains Mono, Courier New" font-size="4.5" font-weight="bold" fill="#555">${h}</text>`
      hx += colWidths[i]
    })

    svg += `<line x1="${x}" y1="${y + mmToPx(9)}" x2="${x + w}" y2="${y + mmToPx(9)}" stroke="${C_BLACK}" stroke-width="0.2"/>`

    // Revision rows — if none, show "Initial Issue"
    const rows = revisions.length > 0 ? revisions.slice(0, 3) : [
      { rev: 'A', date: new Date().toLocaleDateString('en-GB'), description: 'Initial issue', by: p.surveyor_name || '' }
    ]

    let rowY = y + mmToPx(11.5)
    rows.forEach((row, i) => {
      hx = x
      const cells = [row.rev, row.date, row.description.length > 25 ? row.description.slice(0, 23) + '..' : row.description, row.by]
      cells.forEach((cell, ci) => {
        svg += `<text x="${hx + 1}" y="${rowY}" font-family="JetBrains Mono, Courier New" font-size="4" fill="${C_BLACK}">${escapeXml(cell)}</text>`
        hx += colWidths[ci]
      })
      rowY += mmToPx(3)
    })

    return svg
  }

  private drawSurveyorCertificateInternal(x: number, y: number, w: number): string {
    const d = this.formNo4Data
    const h = mmToPx(105) // Expanded to accommodate declaration + enhanced auth block

    let svg = `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="white" stroke="${C_BLACK}" stroke-width="0.5"/>`

    // ── DECLARATION ──
    svg += `<text x="${x + w/2}" y="${y + mmToPx(5)}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="7" font-weight="bold" fill="${C_BLACK}">DECLARATION</text>`
    svg += `<line x1="${x}" y1="${y + mmToPx(6.5)}" x2="${x + w}" y2="${y + mmToPx(6.5)}" stroke="${C_BLACK}" stroke-width="0.3"/>`

    // Declaration text (wrapped at ~48 chars per line)
    const words = d.declarationText.split(' ')
    const lines: string[] = []
    let currentLine = ''

    words.forEach(word => {
      if ((currentLine + word).length > 48) {
        lines.push(currentLine.trim())
        currentLine = word + ' '
      } else {
        currentLine += word + ' '
      }
    })
    if (currentLine) lines.push(currentLine.trim())

    let textY = y + mmToPx(12)
    lines.slice(0, 6).forEach(line => {
      svg += `<text x="${x + mmToPx(2)}" y="${textY}" font-family="JetBrains Mono, Courier New" font-size="4.5" fill="${C_BLACK}">${escapeXml(line)}</text>`
      textY += mmToPx(4)
    })

    // Surveyor signature line with name and licence
    textY += mmToPx(2)
    svg += `<line x1="${x + mmToPx(2)}" y1="${textY}" x2="${x + w * 0.55}" y2="${textY}" stroke="${C_BLACK}" stroke-width="0.5"/>`
    svg += `<text x="${x + mmToPx(2)}" y="${textY + mmToPx(3.5)}" font-family="JetBrains Mono, Courier New" font-size="4" fill="#555">Signature of Licensed Surveyor</text>`

    // Date on the right side of signature line
    svg += `<line x1="${x + w * 0.6}" y1="${textY}" x2="${x + w - mmToPx(2)}" y2="${textY}" stroke="${C_BLACK}" stroke-width="0.5"/>`
    svg += `<text x="${x + w * 0.6}" y="${textY + mmToPx(3.5)}" font-family="JetBrains Mono, Courier New" font-size="4" fill="#555">Date: ${escapeXml(d.declarationDate)}</text>`

    // Surveyor credentials below signature
    textY += mmToPx(6)
    if (d.surveyorName) {
      svg += `<text x="${x + mmToPx(2)}" y="${textY}" font-family="JetBrains Mono, Courier New" font-size="4.5" font-weight="bold" fill="${C_BLACK}">${escapeXml(d.surveyorName)}</text>`
      textY += mmToPx(3.5)
    }
    if (d.surveyorLicence) {
      svg += `<text x="${x + mmToPx(2)}" y="${textY}" font-family="JetBrains Mono, Courier New" font-size="4" fill="#555">LS/${escapeXml(d.surveyorLicence)}</text>`
      textY += mmToPx(3.5)
    }
    if (d.iskRegNo) {
      svg += `<text x="${x + mmToPx(2)}" y="${textY}" font-family="JetBrains Mono, Courier New" font-size="4" fill="#555">ISK Reg. ${escapeXml(d.iskRegNo)}</text>`
      textY += mmToPx(3.5)
    }
    if (d.firmName) {
      svg += `<text x="${x + mmToPx(2)}" y="${textY}" font-family="JetBrains Mono, Courier New" font-size="4" fill="#555">${escapeXml(d.firmName)}</text>`
      textY += mmToPx(3.5)
    }

    // ── Surveyor Stamp & Seal Area ──
    // Two areas: ISK rubber stamp (left) and Surveyor's seal (right)
    // Per ISK practice, the surveyor applies their rubber stamp next to the
    // signature. The seal circle represents the surveyor's corporate seal.
    const stampRowY = textY - mmToPx(14)
    
    // ISK Association Stamp area
    const iskStampX = x + mmToPx(2)
    const iskStampW = mmToPx(28)
    const iskStampH = mmToPx(12)
    svg += `<rect x="${iskStampX}" y="${stampRowY}" width="${iskStampW}" height="${iskStampH}" fill="none" stroke="#999" stroke-width="0.3" stroke-dasharray="2,1"/>`
    svg += `<text x="${iskStampX + iskStampW/2}" y="${stampRowY + mmToPx(4)}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="3" fill="#aaa">ISK ASSOCIATION</text>`
    svg += `<text x="${iskStampX + iskStampW/2}" y="${stampRowY + mmToPx(7)}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="3" fill="#aaa">RUBBER STAMP</text>`
    if (d.firmName) {
      svg += `<text x="${iskStampX + iskStampW/2}" y="${stampRowY + mmToPx(10)}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="2.5" fill="#bbb">${escapeXml(d.firmName)}</text>`
    }

    // Surveyor's Corporate Seal area
    const sealX = x + w - mmToPx(22)
    const sealW = mmToPx(18)
    const sealH = mmToPx(12)
    svg += `<rect x="${sealX}" y="${stampRowY}" width="${sealW}" height="${sealH}" fill="none" stroke="#999" stroke-width="0.3" stroke-dasharray="2,1"/>`
    svg += `<circle cx="${sealX + sealW/2}" cy="${stampRowY + sealH/2}" r="${mmToPx(4)}" fill="none" stroke="#ccc" stroke-width="0.3" stroke-dasharray="1.5,1"/>`
    svg += `<text x="${sealX + sealW/2}" y="${stampRowY + sealH/2 - 1}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="3" fill="#aaa">SURVEYOR</text>`
    svg += `<text x="${sealX + sealW/2}" y="${stampRowY + sealH/2 + 2}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="3" fill="#aaa">SEAL</text>`

    textY += mmToPx(2)

    // ── SoK AUTHENTICATION BLOCK ──
    // Per Survey Act Cap. 299, Form No. 4 — this block is completed by the
    // Director of Surveys office after the plan is submitted for authentication.
    // The three signature lines correspond to: examination (checking computations),
    // approval (verifying compliance), and authentication (official SoK seal).
    const authY = textY + mmToPx(1)
    const authH = mmToPx(36)
    svg += `<rect x="${x}" y="${authY}" width="${w}" height="${authH}" fill="#fafafa" stroke="${C_BLACK}" stroke-width="0.5"/>`

    // Header
    svg += `<text x="${x + w/2}" y="${authY + mmToPx(4)}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="5" font-weight="bold" fill="${C_BLACK}">FOR DIRECTOR OF SURVEYS</text>`
    svg += `<line x1="${x}" y1="${authY + mmToPx(5.5)}" x2="${x + w}" y2="${authY + mmToPx(5.5)}" stroke="${C_BLACK}" stroke-width="0.3"/>`

    // Letter No. — reference number for the Director of Surveys' covering letter
    svg += `<text x="${x + mmToPx(2)}" y="${authY + mmToPx(9)}" font-family="JetBrains Mono, Courier New" font-size="4.5" fill="${C_BLACK}">Letter No.: ${d.letterNo || '________________________'}</text>`
    svg += `<text x="${x + w - mmToPx(2)}" y="${authY + mmToPx(9)}" text-anchor="end" font-family="JetBrains Mono, Courier New" font-size="4" fill="#555">Ref: ${d.firNumber || '___________'}</text>`

    // Examined by — checks computations and field work
    svg += `<text x="${x + mmToPx(2)}" y="${authY + mmToPx(14)}" font-family="JetBrains Mono, Courier New" font-size="4.5" fill="${C_BLACK}">Examined by: ________________________</text>`
    svg += `<text x="${x + w - mmToPx(2)}" y="${authY + mmToPx(14)}" text-anchor="end" font-family="JetBrains Mono, Courier New" font-size="4" fill="#555">Date: ___________</text>`

    // Approved by — verifies compliance with Survey Act Cap. 299
    svg += `<text x="${x + mmToPx(2)}" y="${authY + mmToPx(19)}" font-family="JetBrains Mono, Courier New" font-size="4.5" fill="${C_BLACK}">Approved by: ________________________</text>`
    svg += `<text x="${x + w - mmToPx(2)}" y="${authY + mmToPx(19)}" text-anchor="end" font-family="JetBrains Mono, Courier New" font-size="4" fill="#555">Date: ___________</text>`

    // Authenticated by — applies the official Survey of Kenya seal
    svg += `<text x="${x + mmToPx(2)}" y="${authY + mmToPx(24)}" font-family="JetBrains Mono, Courier New" font-size="4.5" fill="${C_BLACK}">Authenticated by: ____________________</text>`
    svg += `<text x="${x + w - mmToPx(2)}" y="${authY + mmToPx(24)}" text-anchor="end" font-family="JetBrains Mono, Courier New" font-size="4" fill="#555">Date: ___________</text>`

    // Official SoK Seal area — circle with proper label
    const sealCx = x + w - mmToPx(11)
    const sealCy = authY + mmToPx(30)
    const sealR = mmToPx(5)
    svg += `<circle cx="${sealCx}" cy="${sealCy}" r="${sealR}" fill="none" stroke="${C_BLACK}" stroke-width="0.4" stroke-dasharray="1.5,1"/>`
    svg += `<text x="${sealCx}" y="${sealCy - 1}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="3" fill="#888">OFFICIAL SEAL</text>`
    svg += `<text x="${sealCx}" y="${sealCy + 2}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="3" fill="#888">SURVEY OF KENYA</text>`

    // Legal reference note at bottom of auth block
    svg += `<text x="${x + mmToPx(2)}" y="${authY + mmToPx(33)}" font-family="JetBrains Mono, Courier New" font-size="3" fill="#999">Per Survey Act Cap. 299, Sec. 22 — Authentication by Director of Surveys</text>`

    return svg
  }

  /**
   * Draw Form No. 4 title block at bottom
   */
  private drawFormNo4TitleBlock(): string {
    const d = this.formNo4Data
  const footerY = this.pageH - mmToPx(50)
  const footerH = mmToPx(44)
  const margin = mmToPx(10)
  const cols = 6
  const colW = (this.pageW - margin * 2) / cols

    let svg = `<g class="form-no-4-title-block">`
    
    // Main title block with 6 columns
    const headers = ['Registration', 'Transaction', 'Authentication', 'Date', 'Records', 'Date']
    let x = margin
    
    headers.forEach((header, i) => {
      svg += `<rect x="${x}" y="${footerY}" width="${colW}" height="${footerH}" fill="#f8f8f8" stroke="${C_BLACK}" stroke-width="0.5"/>`
      svg += `<text x="${x + colW/2}" y="${footerY + mmToPx(4)}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="5" font-weight="bold" fill="${C_BLACK}">${header}</text>`
      x += colW
    })

    // Folio and Register numbers (large text below)
    const folioY = footerY + footerH + mmToPx(3)
    
    if (d.folioNumber) {
      svg += `<text x="${this.pageW/2 - mmToPx(40)}" y="${folioY}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="14" font-weight="bold" fill="${C_BLACK}">Folio No. ${escapeXml(d.folioNumber)}</text>`
    }
    
    if (d.registerNumber) {
      svg += `<text x="${this.pageW/2 + mmToPx(40)}" y="${folioY}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="14" font-weight="bold" fill="${C_BLACK}">Register No. ${escapeXml(d.registerNumber)}</text>`
    }
    
    if (d.firNumber) {
      svg += `<text x="${this.pageW/2}" y="${folioY + mmToPx(6)}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="10" fill="${C_BLACK}">FIR No. ${escapeXml(d.firNumber)}</text>`
    }

    svg += '</g>'
    return svg
  }

  /**
   * Draw submission number in header
   */
  private drawSubmissionNumberHeader(): string {
    const d = this.formNo4Data
    if (!d.submissionNumber) return ''

  const y = mmToPx(8)
  const cx = this.pageW / 2

    return `<text x="${cx}" y="${y}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="8" font-weight="bold" fill="${C_BLACK}">Submission: ${escapeXml(d.submissionNumber)}</text>`
  }

  // drawRoadTruncationLines() — inherited from SurveyPlanRenderer base class

  /**
   * Draw print verification hash at the bottom of the plan.
   * Overrides base class to include Form No. 4 specific data (folio, register).
   * Uses SHA-256 cryptographic hash for production-grade verification.
   */
  protected drawPrintVerification(): string {
    const d = this.formNo4Data
    const pts = this.rotatedPoints
    const p = this.data.project

    // Build a verification string from key plan data (includes Form No. 4 fields)
    const coordString = pts.map(pt => `${pt.easting.toFixed(4)},${pt.northing.toFixed(4)}`).join('|')
    const areaVal = this.data.parcel.area_sqm.toFixed(4)
    const lrNum = d.lrNumber || 'UNKNOWN'
    const scaleVal = this.scale
    const dateStr = d.declarationDate || new Date().toISOString().split('T')[0]
    const folio = d.folioNumber || ''
    const register = d.registerNumber || ''
    const surveyorLicence = p.surveyor_licence || ''
    const revisionsCount = (p.revisions || []).length

    // SHA-256 cryptographic hash for deterministic verification code
    const rawString = `${coordString}|${areaVal}|${lrNum}|${scaleVal}|${dateStr}|${folio}|${register}|${surveyorLicence}|${revisionsCount}`
    const verCode = createHash('sha256').update(rawString).digest('hex').toUpperCase().slice(0, 16)

    const y = this.pageH - mmToPx(3)
    const cx = this.pageW / 2

    let svg = ''
    svg += `<text x="${cx}" y="${y}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="4" fill="#999">Verification: ${verCode} | Generated: ${escapeXml(dateStr)} | Scale: 1:${scaleVal}</text>`
    svg += `<text x="${cx}" y="${y + mmToPx(2)}" text-anchor="middle" font-family="JetBrains Mono, Courier New" font-size="3" fill="#bbb">Alteration of this plan invalidates verification — Per Survey Act Cap. 299, Sec. 23</text>`

    return svg
  }

private getControlPoints(): CoordinateScheduleEntry[] {
    return this.data.controlPoints.map(cp => ({
      station: cp.name,
      northing: cp.northing,
      easting: cp.easting,
      height: cp.elevation,
      beaconClass: this.mapMonumentTypeToClass(cp.monumentType),
      description: cp.beaconDescription
    }))
  }

  private mapMonumentTypeToClass(mt: string): 'new' | 'old' | 'theoretical' | 'IPCU' {
    if (mt === 'set') return 'new'
    if (mt === 'found') return 'old'
    return 'theoretical'
  }
  
  private calculateCentroid(points: Array<{ easting: number; northing: number }>): { easting: number; northing: number } {
    const sumE = points.reduce((sum, p) => sum + p.easting, 0)
    const sumN = points.reduce((sum, p) => sum + p.northing, 0)
    return {
      easting: sumE / points.length,
      northing: sumN / points.length
    }
  }
}

