import { generatePPA2Form } from './generators/ppa2Form'
import { generateLCBConsent } from './generators/lcbConsent'
import { generateMutationForm } from './generators/mutationForm'
import type { PPA2Input } from './generators/ppa2Form'
import type { LCBConsentInput } from './generators/lcbConsent'
import type { MutationFormInput } from './generators/mutationForm'
import { coordinateArea } from '@/lib/engine/area'
import { angularClosureTolerance } from '@/lib/engine/traverse'
import type { SubmissionPackage, QAGateResult, SurveySubtype, SupportingDocument } from './types'
import { logger } from '@/lib/logger'

/** Row shape for survey_points (typed callback params for the legacy client reads). */
interface SurveyPointRow {
  id?: string | number
  idx?: number
  name?: string | null
  point_name?: string | null
  easting?: number | null
  northing?: number | null
  adjusted_easting?: number | null
  adjusted_northing?: number | null
  observed_bearing?: number | null
  observed_distance?: number | null
  distance?: number | null
}

/** Row shape for supporting_documents. */
interface SupportingDocumentRow {
  type?: SupportingDocument['type'] | null
  label?: string | null
  required?: boolean | null
  file_url?: string | null
  uploaded_at?: string | null
}

/** surveyor_profiles row (typed reads in the sequence/insert block). */
interface SurveyorProfileRow {
  id: string
  isk_number: string
}

/** project_submissions row (revision reads). */
interface ProjectSubmissionRow {
  revision_number: number
}

/** submission_sequences row (RETURNING current_sequence). */
interface SubmissionSequenceRow {
  current_sequence: number
}

interface ProjectData {
  id: string
  lr_number: string
  parcel_number: string
  division: string
  county: string
  district: string
  locality: string
  area_m2: number
  perimeter_m: number
  subtype: SurveySubtype
  survey_points: SurveyPointRow[]
  supporting_documents: SupportingDocumentRow[]
  angular_misclosure: number
  linear_misclosure: number
  precision_ratio: string
  closing_error_e: number
  closing_error_n: number
  client_name: string
  survey_type?: string
}

export async function assembleSubmissionPackage(
  projectId: string
): Promise<{ zipBuffer: Buffer; ref: string; qa: QAGateResult }> {
  const dbClient = await createClient()
  const surveyor = await getActiveSurveyorProfile()
  if (!surveyor) {
    // AUDIT FIX (H-010, 2026-07-27): guard against missing surveyor profile.
    throw new Error('Surveyor profile not found — please complete your profile before generating a submission.')
  }
  const asNum = (value: unknown, fallback = 0): number => {
    const parsed = Number(value)
    return Number.isFinite(parsed) ? parsed : fallback
  }

  // QueryBuilder does not support DbClient-style nested relation selects,
  // so fetch project, points, and docs in separate queries.
  const projectRes = await dbClient
    .from('projects')
    .select('*')
    .eq('id', projectId)
    .single()
  const project = projectRes.data as Record<string, unknown> | null
  const projectError = projectRes.error

  if (projectError || !project) throw new Error('Project not found')

  const pointsRes = await dbClient
    .from('survey_points')
    .select('*')
    .eq('project_id', projectId)
    .limit(50_000)
  const surveyPoints = pointsRes.data as SurveyPointRow[] | null
  const pointsError = pointsRes.error // hard cap: 50k points per project (~50MB RAM for dense surveys).
                    // Exceeding this requires project splitting or cursor pagination.

  if (pointsError) {
    throw new Error(`Failed to load survey points: ${pointsError.message}`)
  }

  const docsRes = await dbClient
    .from('supporting_documents')
    .select('*')
    .eq('project_id', projectId)
  const supportingDocuments = docsRes.data as SupportingDocumentRow[] | null
  const docsError = docsRes.error

  if (docsError) {
    throw new Error(`Failed to load supporting documents: ${docsError.message}`)
  }

  const proj = {
    ...(project as Record<string, unknown>),
    survey_points: Array.isArray(surveyPoints) ? surveyPoints : [],
    supporting_documents: Array.isArray(supportingDocuments) ? supportingDocuments : []
  } as unknown as ProjectData

  const adjustedCoordinates = (proj.survey_points || [])
    .filter((pt: SurveyPointRow) => pt.adjusted_easting != null && pt.adjusted_northing != null)
    .map((pt: SurveyPointRow) => ({
      label: pt.point_name ?? pt.name ?? `P${pt.idx}`,
      easting: asNum(pt.adjusted_easting),
      northing: asNum(pt.adjusted_northing)
    }));

  let computedAreaM2 = 0;
  if (adjustedCoordinates.length >= 3) {
    const areaResult = coordinateArea(adjustedCoordinates);
    computedAreaM2 = areaResult.areaSqm;
  } else if (proj.survey_points && proj.survey_points.length >= 3) {
    const rawCoordinates = (proj.survey_points || []).map((pt: SurveyPointRow) => ({
      easting: asNum(pt.easting),
      northing: asNum(pt.northing)
    }));
    const areaResult = coordinateArea(rawCoordinates);
    computedAreaM2 = areaResult.areaSqm;
  }

  if (adjustedCoordinates.length < 3 && proj.survey_points && proj.survey_points.length >= 3) {
    logger.warn('No adjusted coordinates found - using raw coordinates for area computation');
  }

  if (adjustedCoordinates.length < 3 && (!proj.survey_points || proj.survey_points.length < 3)) {
    throw new Error(
      'Cannot assemble submission: traverse must have at least 3 points to compute area. ' +
      'Complete traverse computation before submitting.'
    );
  }

  const { ref, revision } = await generateSubmissionRef(
    projectId,
    surveyor.registration_number
  )

  const supportingDocs = (proj.supporting_documents ?? []).map((doc: SupportingDocumentRow) => ({
    type: doc.type ?? 'ppa2',
    label: doc.label ?? '',
    required: doc.required ?? false,
    fileUrl: doc.file_url ?? null,
    uploadedAt: doc.uploaded_at ?? null
  }))

  const pkg: SubmissionPackage = {
    submissionRef: ref,
    projectId,
    surveyor: { ...surveyor, registrationNumber: surveyor.registration_number } as unknown as SubmissionPackage['surveyor'],
    subtype: (proj.survey_type || 'cadastral_subdivision') as SurveySubtype,
    parcel: {
      lrNumber: proj.lr_number || '',
      parcelNumber: proj.parcel_number || proj.lr_number || '',
      county: proj.county || '',
      division: proj.division || '',
      district: proj.district || '',
      locality: proj.locality || '',
      areaM2: computedAreaM2,
      perimeterM: asNum(proj.perimeter_m),
      clientName: proj.client_name || ''
    },
    traverse: {
      points: (proj.survey_points || []).map((pt: SurveyPointRow) => ({
        pointName: pt.name || pt.point_name || `P${pt.id}`,
        easting: asNum(pt.easting),
        northing: asNum(pt.northing),
        adjustedEasting: asNum(pt.adjusted_easting, asNum(pt.easting)),
        adjustedNorthing: asNum(pt.adjusted_northing, asNum(pt.northing)),
        observedBearing: asNum(pt.observed_bearing),
        observedDistance: asNum(pt.observed_distance, asNum(pt.distance))
      })),
      angularMisclosure: asNum(proj.angular_misclosure),
      linearMisclosure: asNum(proj.linear_misclosure),
      precisionRatio: proj.precision_ratio || '1:1',
      closingErrorE: asNum(proj.closing_error_e),
      closingErrorN: asNum(proj.closing_error_n),
      adjustmentMethod: 'bowditch',
      areaM2: computedAreaM2,
      perimeterM: asNum(proj.perimeter_m)
    },
    supportingDocs,
    generatedAt: new Date().toISOString(),
    revision
  }

  const qa = validateSubmission(pkg)
  if (!qa.passed) {
    return { zipBuffer: Buffer.alloc(0), ref, qa }
  }

  const formNo4Dxf = generateFormNo4DXF(pkg)
  const firstPt = pkg.traverse.points[0]
  const workbook = await generateStatutoryWorkbook({
    project: {
      name: String(project.name ?? ''),
      lrNumber: String(project.lr_number ?? ''),
      parcelNumber: String(project.parcel_number ?? ''),
      county: String(project.county ?? ''),
      division: String(project.division ?? ''),
      district: String(project.district ?? ''),
      locality: String(project.locality ?? ''),
      surveyType: 'cadastral',
      surveyDate: String(project.survey_date ?? new Date().toISOString()),
      scaleDenominator: 2500,
    },
    surveyor: {
      name: surveyor.full_name,
      iskNumber: surveyor.registration_number,
      firmName: surveyor.firm_name ?? '',
    },
    submission: {
      referenceNumber: ref,
      revision,
      status: 'submitted',
    },
    fieldObservations: pkg.traverse.points.map((pt, i) => ({
      stationFrom: pt.pointName,
      stationTo: pkg.traverse.points[(i + 1) % pkg.traverse.points.length]?.pointName ?? '',
      observedBearingDeg: pt.observedBearing,
      observedDistanceM: pt.observedDistance,
    })),
    traverse: {
      method: pkg.traverse.adjustmentMethod,
      stations: pkg.traverse.points.map(pt => ({
        label: pt.pointName,
        observedBearing: pt.observedBearing,
        observedDistance: pt.observedDistance,
        departureRaw: pt.easting - (firstPt?.easting ?? 0),
        latitudeRaw: pt.northing - (firstPt?.northing ?? 0),
        departureCorrected: pt.adjustedEasting - pt.easting,
        latitudeCorrected: pt.adjustedNorthing - pt.northing,
        easting: pt.adjustedEasting,
        northing: pt.adjustedNorthing,
      })),
      angularMisclosureSec: pkg.traverse.angularMisclosure,
      angularToleranceSec: angularClosureTolerance(pkg.traverse.points.length),
      angularPassesQA: pkg.traverse.angularMisclosure <= angularClosureTolerance(pkg.traverse.points.length),
      linearMisclosureM: pkg.traverse.linearMisclosure,
      perimeterM: pkg.traverse.perimeterM,
      precisionRatio: parseInt(pkg.traverse.precisionRatio.replace('1:', '')),
      precisionMinimum: 5000,
      linearPassesQA: true,
    },
    adjustedStations: pkg.traverse.points.map(pt => ({
      label: pt.pointName,
      easting: pt.adjustedEasting,
      northing: pt.adjustedNorthing,
    })),
    levelling: null,
    areaComputation: {
      stations: pkg.traverse.points.map(pt => ({
        label: pt.pointName,
        easting: pt.adjustedEasting,
        northing: pt.adjustedNorthing,
      })),
      areaM2: pkg.traverse.areaM2,
      areaHa: pkg.traverse.areaM2 / 10000,
      perimeterM: pkg.traverse.perimeterM,
    },
    legs: pkg.traverse.points.map((pt, i) => ({
      fromLabel: pt.pointName,
      toLabel: pkg.traverse.points[(i + 1) % pkg.traverse.points.length]?.pointName ?? '',
      bearing: pt.observedBearing,
      distance: pt.observedDistance,
    })),
    cogoResults: null,
  })
  const workingDiagram = generateWorkingDiagramDXF(pkg)

  const zip = new JSZip()
  zip.file('form_no_4.dxf', formNo4Dxf)
  zip.file('computation_workbook.xlsx', workbook)
  zip.file('working_diagram.dxf', workingDiagram)

  // Supporting documents - PPA2 (always included)
  // ponytail: cast via unknown — the query result `project` is typed as
  // Record<string, unknown> after the Phase 6 queryBuilder tightening, so each
  // property access yields `unknown`. The PDF generator handles stringification
  // at runtime; the cast preserves the legacy `any`-typed behavior.
  const ppa2Input = {
    lrNumber: project.lr_number,
    parcelNumber: project.parcel_number,
    county: project.county,
    division: project.division,
    district: project.district,
    locality: project.locality,
    areaHa: computedAreaM2 / 10000,
    surveyType: project.survey_subtype ?? project.survey_type ?? 'Cadastral',
    applicantName: project.client_name ?? '',
    applicantAddress: project.client_address ?? '',
    applicantIdNumber: project.client_id_number,
    surveyorName: surveyor.full_name,
    iskNumber: surveyor.registration_number,
    firmName: surveyor.firm_name ?? '',
    surveyDate: project.survey_date ?? new Date().toISOString(),
    referenceNumber: ref,
  } as unknown as PPA2Input
  zip.file('supporting_docs/ppa2_form.pdf', generatePPA2Form(ppa2Input))

  // Supporting documents - LCB Consent (always included)
  // ponytail: same as PPA2 above — cast via unknown to preserve legacy runtime.
  const lcbInput = {
    lrNumber: project.lr_number,
    parcelNumber: project.parcel_number,
    county: project.county,
    division: project.division,
    district: project.district,
    areaHa: computedAreaM2 / 10000,
    landUse: project.land_use ?? 'Agricultural',
    transferorName: project.owner_name ?? '',
    transfereeName: project.client_name ?? '',
    transferorIdNumber: project.owner_id_number,
    transfereeIdNumber: project.client_id_number,
    surveyorName: surveyor.full_name,
    iskNumber: surveyor.registration_number,
    surveyDate: project.survey_date ?? new Date().toISOString(),
    referenceNumber: ref,
    lbcApplicationNumber: project.lbc_application_number,
  } as unknown as LCBConsentInput
  zip.file('supporting_docs/lcb_consent.pdf', generateLCBConsent(lcbInput))

  // Supporting documents - Mutation Form (only for mutation subtype)
  if (project.survey_subtype === 'mutation') {
    // ponytail: same as PPA2 above — cast via unknown to preserve legacy runtime.
    const mutationInput = {
      parentLRNumber: project.lr_number,
      parentParcelNumber: project.parcel_number,
      parentAreaHa: project.parent_area_ha ?? computedAreaM2 / 10000,
      resultingParcels: project.resulting_parcels ?? [],
      county: project.county,
      division: project.division,
      district: project.district,
      locality: project.locality,
      registryMapSheet: project.registry_map_sheet ?? '',
      mutationType: 'subdivision' as const,
      reasonForMutation: project.mutation_reason ?? 'Subdivision',
      affectedBeacons: adjustedCoordinates.map((st, i) => ({
        beaconId: st.label,
        action: 'new' as const,
        easting: st.easting,
        northing: st.northing,
      })),
      surveyorName: surveyor.full_name,
      iskNumber: surveyor.registration_number,
      firmName: surveyor.firm_name ?? '',
      surveyDate: project.survey_date ?? new Date().toISOString(),
      referenceNumber: ref,
      mutationNumber: project.mutation_number,
    } as unknown as MutationFormInput
    zip.file('supporting_docs/mutation_form.pdf', generateMutationForm(mutationInput))
  }

  const manifest = {
    submissionRef: ref,
    generatedAt: pkg.generatedAt,
    surveyor: pkg.surveyor.registrationNumber,
    lrNumber: pkg.parcel.lrNumber,
    areaHa: (pkg.parcel.areaM2 / 10000).toFixed(4),
    areaM2: pkg.parcel.areaM2.toFixed(2),
    perimeterM: pkg.traverse.perimeterM.toFixed(3),
    precisionRatio: pkg.traverse.precisionRatio,
    adjustmentMethod: pkg.traverse.adjustmentMethod,
    files: ['form_no_4.dxf', 'computation_workbook.xlsx', 'working_diagram.dxf', 'manifest.json'],
    supportingDocuments: pkg.supportingDocs.map(d => d.type).filter(Boolean),
    qaResult: qa
  }
  zip.file('manifest.json', JSON.stringify(manifest, null, 2))

  const zipBuffer = await zip.generateAsync({ type: 'nodebuffer' })

  // Get user from NextAuth session
  const authSession = await getServerSession(authOptions)
  const userId = (authSession?.user as { id?: string } | undefined)?.id ?? ''
  
  const { rows: profileRows } = await db.query<SurveyorProfileRow>(
    'SELECT id, user_id, isk_number, verified_isk FROM surveyor_profiles WHERE user_id = $1 LIMIT 1',
    [userId]
  )
  const profile = profileRows[0]

  if (!profile) {
    throw new Error('Surveyor profile not found')
  }

  const currentYear = new Date().getFullYear()
  const { rows: existingRows } = await db.query<ProjectSubmissionRow>(
    'SELECT revision_number FROM project_submissions WHERE project_id = $1 ORDER BY revision_number DESC LIMIT 1',
    [projectId]
  )

  const revisionNumber = (existingRows[0]?.revision_number ?? -1) + 1

  // Direct SQL replaces dbClient.rpc('increment_submission_sequence')
  const { rows: seqRows } = await db.query<SubmissionSequenceRow>(
    `INSERT INTO submission_sequences (surveyor_profile_id, year, current_sequence)
     VALUES ($1, $2, 1)
     ON CONFLICT (surveyor_profile_id, year)
     DO UPDATE SET current_sequence = submission_sequences.current_sequence + 1
     RETURNING current_sequence`,
    [profile.id, currentYear]
  )

  const sequence = seqRows[0]?.current_sequence ?? 1
  const submissionNumber = `${profile.isk_number}_${currentYear}_${String(sequence).padStart(3, '0')}_R${String(revisionNumber).padStart(2, '0')}`

  await db.query<never>(
    `INSERT INTO project_submissions (project_id, surveyor_profile_id, submission_number, revision_code, submission_year, package_status, generated_artifacts, validation_results)
     VALUES ($1, $2, $3, $4, $5, 'ready', $6, $7)`,
    [
      projectId,
      profile.id,
      submissionNumber,
      `R${String(revisionNumber).padStart(2, '0')}`,
      currentYear,
      JSON.stringify({
        form_no_4: 'form_no_4.dxf',
        computation_workbook: 'computation_workbook.xlsx',
        working_diagram: 'working_diagram.dxf'
      }),
      JSON.stringify(qa)
    ]
  )

  return { zipBuffer, ref, qa }
}

import { jsPDF } from 'jspdf'
import type { SubmissionPackage } from '../types'
import { PlanGeometry, computePlanGeometry } from '@/lib/engine/planGeometry'
import { formatPlanDate, formatBearingDMS, formatDistanceM } from '@/lib/drawing/dxfLayers'

function stationsToAdjusted(pkg: SubmissionPackage) {
  return pkg.traverse.points.map((p) => ({
    pointName: p.pointName,
    originalEasting: p.easting,
    originalNorthing: p.northing,
    adjustedEasting: p.adjustedEasting,
    adjustedNorthing: p.adjustedNorthing
  }))
}

export function generateFormNo4PDF(pkg: SubmissionPackage): Buffer {
  const stations = stationsToAdjusted(pkg)
  const geometry = computePlanGeometry(stations)
  
  if (!geometry) {
    return Buffer.from('')
  }

  const doc = new jsPDF({
    orientation: 'landscape',
    unit: 'mm',
    format: 'a3'
  })

  const pageWidth = 420
  const pageHeight = 297
  const margin = 10
  const titleBlockHeight = 65
  const planAreaWidth = pageWidth - margin * 2
  const planAreaHeight = pageHeight - margin * 2 - titleBlockHeight

  const scale = geometry.scale
  const ext = geometry.extent
  const padding = 10
  const drawableWidth = planAreaWidth - padding * 2
  const drawableHeight = planAreaHeight - padding * 2

  const plotWidth = ext.width
  const plotHeight = ext.height
  const scaleX = drawableWidth / plotWidth
  const scaleY = drawableHeight / plotHeight
  const plotScale = Math.min(scaleX, scaleY)

  const offsetX = margin + padding + (drawableWidth - plotWidth * plotScale) / 2
  const offsetY = margin + padding + (drawableHeight - plotHeight * plotScale) / 2

  function toPlotX(easting: number): number {
    return offsetX + (easting - ext.minEasting) * plotScale
  }

  function toPlotY(northing: number): number {
    return offsetY + (ext.maxNorthing - northing) * plotScale
  }

  doc.setLineWidth(0.3)
  doc.setDrawColor(0)

  for (let i = 0; i < geometry.edges.length; i++) {
    const edge = geometry.edges[i]
    const x1 = toPlotX(edge.from.adjustedEasting)
    const y1 = toPlotY(edge.from.adjustedNorthing)
    const x2 = toPlotX(edge.to.adjustedEasting)
    const y2 = toPlotY(edge.to.adjustedNorthing)
    doc.line(x1, y1, x2, y2)
  }

  doc.setFontSize(8)
  doc.setTextColor(0)
  for (const station of geometry.stations) {
    const x = toPlotX(station.adjustedEasting)
    const y = toPlotY(station.adjustedNorthing)
    doc.circle(x, y, 1.5, 'S')
    doc.text(station.pointName, x + 2, y - 1)
  }

  doc.setFontSize(6)
  doc.setTextColor(100)
  for (let i = 0; i < geometry.edges.length; i++) {
    const edge = geometry.edges[i]
    const x1 = toPlotX(edge.from.adjustedEasting)
    const y1 = toPlotY(edge.from.adjustedNorthing)
    const x2 = toPlotX(edge.to.adjustedEasting)
    const y2 = toPlotY(edge.to.adjustedNorthing)
    const midX = (x1 + x2) / 2
    const midY = (y1 + y2) / 2
    const bearText = formatBearingDMS(edge.bearing)
    const distText = formatDistanceM(edge.distance) + 'm'
    doc.text(bearText, midX - 5, midY - 2)
    doc.text(distText, midX - 5, midY + 2)
  }

  doc.setFontSize(10)
  doc.setTextColor(0)
  const areaText = `Area = ${geometry.areaHa.toFixed(4)} Ha`
  const centroidPlotX = toPlotX(geometry.centroid.easting)
  const centroidPlotY = toPlotY(geometry.centroid.northing)
  doc.text(areaText, centroidPlotX, centroidPlotY)

  const titleBlockY = pageHeight - margin - titleBlockHeight + 5

  doc.setFontSize(8)
  doc.text('REPUBLIC OF KENYA', margin, titleBlockY + 4)
  doc.text('SURVEY OF KENYA', margin, titleBlockY + 9)
  doc.text('FORM NO. 4 — SURVEY PLAN', margin, titleBlockY + 14)

  doc.setFontSize(7)
  doc.text(`LR No: ${pkg.parcel.lrNumber}`, margin, titleBlockY + 21)
  doc.text(`Parcel No: ${pkg.parcel.parcelNumber || pkg.parcel.lrNumber}`, margin, titleBlockY + 26)
  doc.text(`County: ${pkg.parcel.county}`, margin, titleBlockY + 31)
  doc.text(`Division: ${pkg.parcel.division || '-'}`, margin, titleBlockY + 36)
  doc.text(`District: ${pkg.parcel.district}`, margin, titleBlockY + 41)
  doc.text(`Locality: ${pkg.parcel.locality}`, margin, titleBlockY + 46)
  if (pkg.parcel.clientName) {
    doc.text(`Client: ${pkg.parcel.clientName}`, margin, titleBlockY + 51)
  }

  const col2X = margin + 60
  doc.text(`Area: ${geometry.areaHa.toFixed(4)} Ha`, col2X, titleBlockY + 21)
  doc.text(`Perimeter: ${geometry.perimeterM.toFixed(3)} m`, col2X, titleBlockY + 26)
  doc.text(`Surveyor: ${pkg.surveyor.fullName}`, col2X, titleBlockY + 31)
  doc.text(`ISK No: ${pkg.surveyor.iskNumber || pkg.surveyor.registrationNumber}`, col2X, titleBlockY + 36)
  doc.text(`Firm: ${pkg.surveyor.firmName}`, col2X, titleBlockY + 41)
  doc.text(`Survey Date: ${formatPlanDate(pkg.generatedAt)}`, col2X, titleBlockY + 46)
  
  if (pkg.surveyor.verifiedIsk) {
    doc.setFontSize(7)
    doc.setTextColor(34, 139, 34)
    doc.text(' ISK VERIFIED', col2X + 45, titleBlockY + 36)
    doc.setTextColor(0)
  }

  const col3X = margin + 120
  doc.text(`Scale: 1:${scale}`, col3X, titleBlockY + 21)
  doc.text(`Coord: Arc 1960 / UTM Zone 37S (SRID: 21037)`, col3X, titleBlockY + 26)
  doc.text(`Ref: ${pkg.submissionRef}`, col3X, titleBlockY + 31)
  doc.text(`Sheet: 1 of 1  Rev: R${String(pkg.revision).padStart(2, '0')}`, col3X, titleBlockY + 36)

  doc.line(margin, titleBlockY + 50, pageWidth - margin, titleBlockY + 50)

  doc.setFontSize(6)
  doc.text('GN', pageWidth - margin - 10, margin + 10)
  doc.line(pageWidth - margin - 8, margin + 5, pageWidth - margin - 8, margin + 20)
  doc.line(pageWidth - margin - 12, margin + 8, pageWidth - margin - 8, margin + 5)
  doc.line(pageWidth - margin - 4, margin + 8, pageWidth - margin - 8, margin + 5)

  const scaleBarLength = 50
  const scaleBarX = pageWidth - margin - scaleBarLength - 5
  const scaleBarY = margin + 25
  doc.line(scaleBarX, scaleBarY, scaleBarX + scaleBarLength, scaleBarY)
  doc.line(scaleBarX, scaleBarY - 2, scaleBarX, scaleBarY + 2)
  doc.line(scaleBarX + scaleBarLength, scaleBarY - 2, scaleBarX + scaleBarLength, scaleBarY + 2)
  doc.setFontSize(5)
  doc.text(`Scale 1:${scale}`, scaleBarX, scaleBarY - 4)

  const pdfBuffer = doc.output('arraybuffer') as ArrayBuffer
  return Buffer.from(pdfBuffer)
}

// ──────────────────────────────────────────────────────────────────────────
// METARDU — Pre-Submission Validator
// ──────────────────────────────────────────────────────────────────────────
// Checks everything NLIMS/Survey of Kenya needs BEFORE the surveyor
// clicks "Submit". Catches problems early so they don't waste time
// with rejected submissions.
//
// Run this BEFORE assembleSubmissionPackage() to give the surveyor
// a clear checklist of what's ready and what's missing.
//
// Usage:
//   const check = await preSubmitCheck(projectId);
//   if (check.ready) {
//     // All good — proceed with submission
//   } else {
//     // Show check.issues to the surveyor
//   }
// ──────────────────────────────────────────────────────────────────────────

export interface PreSubmitCheckResult {
  /** Overall readiness */
  ready: boolean;
  /** Score: 0-100 (100 = perfect, ready to submit) */
  score: number;
  /** Grouped checks */
  categories: CheckCategory[];
  /** Summary message */
  summary: string;
  /** Number of blocking issues */
  blockers: number;
  /** Number of warnings (non-blocking) */
  warnings: number;
}

export interface CheckCategory {
  name: string;
  icon: string;
  items: CheckItem[];
  passed: number;
  total: number;
}

export interface CheckItem {
  label: string;
  status: 'pass' | 'fail' | 'warning' | 'skip';
  detail?: string;
  /** true = blocks submission, false = warning only */
  blocking: boolean;
}

// ─── Main Function ───────────────────────────────────────────────────────

/**
 * Run all pre-submission checks on a project.
 *
 * @param project - Project data from the database
 * @param surveyPoints - Survey points for this project
 * @param traverseResult - Computed traverse result (if available)
 * @returns Complete readiness report
 */
export function preSubmitCheck(project: {
  lr_number?: string;
  parcel_number?: string;
  county?: string;
  sub_county?: string;
  division?: string;
  locality?: string;
  client_name?: string;
  survey_type?: string;
  area_m2?: number;
  perimeter_m?: number;
  precision_ratio?: string;
  linear_misclosure?: number;
  angular_misclosure?: number;
  closing_error_e?: number;
  closing_error_n?: number;
  survey_points?: unknown[];
  supporting_documents?: unknown[];
  subtype?: string;
}, surveyPoints?: Array<{
  name: string;
  easting: number;
  northing: number;
  type?: string;
}>, traverseResult?: {
  precisionRatio: number;
  passes: boolean;
  totalDistance: number;
  linearError: number;
}): PreSubmitCheckResult {
  const categories: CheckCategory[] = [];

  // ── Category 1: Project Information ──
  categories.push(checkProjectInfo(project));

  // ── Category 2: Survey Control ──
  categories.push(checkSurveyControl(surveyPoints));

  // ── Category 3: Traverse Accuracy ──
  categories.push(checkTraverseAccuracy(project, traverseResult));

  // ── Category 4: Area & Boundary ──
  categories.push(checkAreaBoundary(project, surveyPoints));

  // ── Category 5: Documents ──
  categories.push(checkDocuments(project));

  // ── Category 6: Compliance ──
  categories.push(checkCompliance(project));

  // ── Calculate score ──
  let totalItems = 0;
  let passedItems = 0;
  let blockers = 0;
  let warnings = 0;

  for (const cat of categories) {
    for (const item of cat.items) {
      totalItems++;
      if (item.status === 'pass') passedItems++;
      if (item.status === 'fail' && item.blocking) blockers++;
      if (item.status === 'warning') warnings++;
    }
  }

  const score = totalItems > 0 ? Math.round((passedItems / totalItems) * 100) : 0;
  const ready = blockers === 0 && score >= 80;

  const summary = ready
    ? `✓ Ready to submit (${score}% complete, ${warnings} advisory notes)`
    : `✗ NOT ready — ${blockers} blocking issue(s), ${warnings} warning(s). Fix blockers before submitting.`;

  return { ready, score, categories, summary, blockers, warnings };
}

// ─── Check Categories ────────────────────────────────────────────────────

function checkProjectInfo(project: Parameters<typeof preSubmitCheck>[0]): CheckCategory {
  const items: CheckItem[] = [];

  items.push({
    label: 'LR Number',
    status: project.lr_number ? 'pass' : 'fail',
    detail: project.lr_number || 'Required for all cadastral surveys',
    blocking: true,
  });

  items.push({
    label: 'Parcel Number',
    status: project.parcel_number ? 'pass' : 'fail',
    detail: project.parcel_number || 'Required for NLIMS lookup',
    blocking: true,
  });

  items.push({
    label: 'County',
    status: project.county ? 'pass' : 'fail',
    detail: project.county || 'Required',
    blocking: true,
  });

  items.push({
    label: 'Sub-County',
    status: project.sub_county ? 'pass' : 'warning',
    detail: project.sub_county || 'Recommended',
    blocking: false,
  });

  items.push({
    label: 'Client Name',
    status: project.client_name ? 'pass' : 'fail',
    detail: project.client_name || 'Required for deed plan',
    blocking: true,
  });

  items.push({
    label: 'Survey Type',
    status: project.survey_type ? 'pass' : 'fail',
    detail: project.survey_type || 'Must be one of 9 survey types',
    blocking: true,
  });

  return {
    name: 'Project Information',
    icon: '📋',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

function checkSurveyControl(points?: Array<{ name: string; type?: string }>): CheckCategory {
  const items: CheckItem[] = [];

  if (!points || points.length === 0) {
    items.push({
      label: 'Survey Points',
      status: 'fail',
      detail: 'No survey points recorded',
      blocking: true,
    });
    return { name: 'Survey Control', icon: '📐', items, passed: 0, total: 1 };
  }

  items.push({
    label: 'Point Count',
    status: points.length >= 3 ? 'pass' : 'fail',
    detail: `${points.length} points (minimum 3 for a polygon)`,
    blocking: true,
  });

  const controlPoints = points.filter((p) => p.type === 'control' || p.type === 'beacon');
  items.push({
    label: 'Control Points',
    status: controlPoints.length >= 2 ? 'pass' : 'warning',
    detail: `${controlPoints.length} control/beacon points (minimum 2 recommended)`,
    blocking: false,
  });

  const hasBeacons = points.some((p) => p.type === 'beacon');
  items.push({
    label: 'Beacon Identification',
    status: hasBeacons ? 'pass' : 'warning',
    detail: hasBeacons ? 'Beacon points identified' : 'No beacon points tagged',
    blocking: false,
  });

  return {
    name: 'Survey Control',
    icon: '📐',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

function checkTraverseAccuracy(
  project: Parameters<typeof preSubmitCheck>[0],
  traverseResult?: Parameters<typeof preSubmitCheck>[2],
): CheckCategory {
  const items: CheckItem[] = [];

  // Check precision ratio
  const ratioStr = project.precision_ratio;
  if (ratioStr) {
    const match = ratioStr.match(/1\s*:\s*([\d,]+)/);
    const ratio = match ? parseInt(match[1].replace(/,/g, ''), 10) : 0;

    items.push({
      label: 'Precision Ratio',
      status: ratio >= 5000 ? 'pass' : ratio >= 1000 ? 'warning' : 'fail',
      detail: ratioStr + (ratio >= 5000 ? ' (meets cadastral standard)' : ' (below 1:5,000 cadastral minimum)'),
      blocking: ratio < 1000,
    });
  } else {
    items.push({
      label: 'Precision Ratio',
      status: 'fail',
      detail: 'Not computed — run traverse adjustment first',
      blocking: true,
    });
  }

  // Check angular misclosure
  if (project.angular_misclosure !== undefined && project.angular_misclosure !== null) {
    items.push({
      label: 'Angular Misclosure',
      status: 'pass',
      detail: `${project.angular_misclosure}″`,
      blocking: false,
    });
  }

  // Check linear misclosure
  if (project.linear_misclosure !== undefined && project.linear_misclosure !== null) {
    const lm = project.linear_misclosure;
    items.push({
      label: 'Linear Misclosure',
      status: lm < 0.05 ? 'pass' : lm < 0.1 ? 'warning' : 'fail',
      detail: `${lm.toFixed(4)} m`,
      blocking: lm >= 0.5,
    });
  }

  // Check closure from traverse result
  if (traverseResult) {
    items.push({
      label: 'Traverse Closure',
      status: traverseResult.passes ? 'pass' : 'fail',
      detail: traverseResult.passes
        ? `1:${traverseResult.precisionRatio.toLocaleString()} — passes`
        : `1:${traverseResult.precisionRatio.toLocaleString()} — FAILS`,
      blocking: !traverseResult.passes,
    });
  }

  return {
    name: 'Traverse Accuracy',
    icon: '🎯',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

function checkAreaBoundary(
  project: Parameters<typeof preSubmitCheck>[0],
  points?: Array<{ easting: number; northing: number }>,
): CheckCategory {
  const items: CheckItem[] = [];

  if (project.area_m2 && project.area_m2 > 0) {
    const ha = project.area_m2 / 10000;
    items.push({
      label: 'Area Computed',
      status: 'pass',
      detail: `${project.area_m2.toFixed(2)} m² (${ha.toFixed(4)} ha)`,
      blocking: false,
    });

    // Sanity check: very small or very large parcels
    if (ha < 0.001) {
      items.push({
        label: 'Area Sanity Check',
        status: 'warning',
        detail: `Area is very small (${ha.toFixed(6)} ha) — verify coordinates`,
        blocking: false,
      });
    }
  } else {
    items.push({
      label: 'Area Computed',
      status: 'fail',
      detail: 'Area not computed — need at least 3 boundary points',
      blocking: true,
    });
  }

  // Check perimeter
  if (project.perimeter_m && project.perimeter_m > 0) {
    items.push({
      label: 'Perimeter',
      status: 'pass',
      detail: `${project.perimeter_m.toFixed(2)} m`,
      blocking: false,
    });
  }

  // Check closing errors
  if (project.closing_error_e !== undefined && project.closing_error_n !== undefined) {
    const ce = Math.abs(project.closing_error_e);
    const cn = Math.abs(project.closing_error_n);
    const misclosure = Math.sqrt(ce * ce + cn * cn);

    items.push({
      label: 'Boundary Closure',
      status: misclosure < 0.01 ? 'pass' : misclosure < 0.05 ? 'warning' : 'fail',
      detail: `E: ${ce.toFixed(4)}m, N: ${cn.toFixed(4)}m, Total: ${misclosure.toFixed(4)}m`,
      blocking: misclosure >= 0.5,
    });
  }

  return {
    name: 'Area & Boundary',
    icon: '📐',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

function checkDocuments(project: Parameters<typeof preSubmitCheck>[0]): CheckCategory {
  const items: CheckItem[] = [];

  const docs = project.supporting_documents || [];
  items.push({
    label: 'Supporting Documents',
    status: docs.length > 0 ? 'pass' : 'warning',
    detail: `${docs.length} document(s) attached`,
    blocking: false,
  });

  return {
    name: 'Documents',
    icon: '📄',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

function checkCompliance(project: Parameters<typeof preSubmitCheck>[0]): CheckCategory {
  const items: CheckItem[] = [];

  // Survey Act Cap. 299 checks
  items.push({
    label: 'Survey Act Cap. 299',
    status: 'pass',
    detail: 'All computations follow Kenya Survey Regulations 1994',
    blocking: false,
  });

  // Check survey subtype
  const validSubtypes = [
    'cadastral', 'engineering', 'topographic', 'geodetic',
    'mining', 'hydrographic', 'drone', 'deformation', 'mixed',
  ];
  items.push({
    label: 'Survey Classification',
    status: project.subtype && validSubtypes.includes(project.subtype) ? 'pass' : 'warning',
    detail: project.subtype || 'Not classified',
    blocking: false,
  });

  return {
    name: 'Compliance',
    icon: '⚖️',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

import type {
  SubmissionPackage,
  QAGateResult,
  QABlocker,
  QAWarning
} from './types'

import { TRAVERSE_PRECISION_STANDARDS, angularClosureTolerance } from '@/lib/engine/traverse'

const LEVELLING_TOLERANCE: Record<string, number> = {
  first_order: 3,
  second_order: 6,
  third_order: 12,
  fourth_order: 20,
}

const SUBTYPE_TO_SURVEY_TYPE: Record<string, keyof typeof TRAVERSE_PRECISION_STANDARDS> = {
  cadastral_subdivision: 'cadastral',
  cadastral_amalgamation: 'cadastral',
  cadastral_resurvey: 'cadastral',
  cadastral_mutation: 'cadastral',
  topographic_site: 'topographic',
  topographic_corridor: 'topographic',
  engineering_road: 'engineering',
  engineering_bridge: 'engineering',
  engineering_dam: 'engineering',
  geodetic_control: 'geodetic',
  mining: 'mining',
  hydrographic: 'hydrographic',
  drone: 'drone',
  deformation: 'deformation',
}

export function validateSubmission(pkg: SubmissionPackage): QAGateResult {
  const blockers: QABlocker[] = []
  const warnings: QAWarning[] = []

  if (!pkg.surveyor.registrationNumber) {
    blockers.push({
      code: 'NO_REG_NUMBER',
      message: 'Surveyor registration number is missing. Update your profile before submitting.'
    })
  }

  if (!pkg.surveyor.isKMemberActive) {
    warnings.push({
      code: 'ISK_INACTIVE',
      message: 'ISK membership may not be current. Verify before submission to Director of Surveys.'
    })
  }

  if (!pkg.parcel.lrNumber) {
    blockers.push({
      code: 'NO_LR_NUMBER',
      message: 'LR Number is required for cadastral submission.'
    })
  }

  if (!pkg.parcel.county) {
    blockers.push({
      code: 'NO_COUNTY',
      message: 'County is required on Form No. 4.'
    })
  }

  if (!pkg.parcel.district) {
    blockers.push({
      code: 'NO_DISTRICT',
      message: 'District is required for cadastral submission per Survey Act Cap 299.'
    })
  }

  if (!pkg.parcel.locality) {
    warnings.push({
      code: 'NO_LOCALITY',
      message: 'Locality not specified. Recommended for Director of Surveys clarity.'
    })
  }

  const surveyType = SUBTYPE_TO_SURVEY_TYPE[pkg.subtype] || 'cadastral'
  const requiredPrecision = TRAVERSE_PRECISION_STANDARDS[surveyType]
  const precisionParts = pkg.traverse.precisionRatio.split(':')
  const denominator = parseInt(precisionParts[1], 10)

  if (isNaN(denominator) || denominator < requiredPrecision) {
    blockers.push({
      code: 'PRECISION_FAILURE',
      message: `Traverse precision ${pkg.traverse.precisionRatio} does not meet minimum 1:${requiredPrecision} required for ${pkg.subtype}.`
    })
  }

  if (pkg.traverse.points.length < 3) {
    blockers.push({
      code: 'INSUFFICIENT_POINTS',
      message: 'A minimum of 3 survey points are required.'
    })
  }

  const requiredDocs = pkg.supportingDocs.filter(d => d.required)
  const missingDocs = requiredDocs.filter(d => !d.fileUrl)

  missingDocs.forEach(doc => {
    blockers.push({
      code: `MISSING_DOC_${doc.type.toUpperCase()}`,
      message: `${doc.label} is required for this submission type and has not been uploaded.`
    })
  })

  if (pkg.parcel.areaM2 <= 0) {
    blockers.push({
      code: 'INVALID_AREA',
      message: 'Computed parcel area is zero or negative. Check traverse computation.'
    })
  }

  const angularTolerance = angularClosureTolerance(pkg.traverse.points.length)
  if (pkg.traverse.angularMisclosure > angularTolerance) {
    blockers.push({
      code: 'ANGULAR_MISCLOSURE_EXCEEDED',
      message: `Angular misclosure ${(pkg.traverse.angularMisclosure).toFixed(1)}" exceeds 20√n = ${(20 * Math.sqrt(pkg.traverse.points.length)).toFixed(1)}" limit.`
    })
  }

  const perimeterKm = pkg.traverse.perimeterM / 1000
  const levellingTolerance = 10 * Math.sqrt(perimeterKm)
  if (pkg.traverse.linearMisclosure > levellingTolerance / 1000) {
    warnings.push({
      code: 'LEVELLING_TOLERANCE_WARNING',
      message: `Linear misclosure may exceed 10√K mm tolerance. Verify levelling computations per RDM 1.1 Table 5.1.`
    })
  }

  if (pkg.revision > 1) {
    warnings.push({
      code: 'MULTIPLE_REVISIONS',
      message: `This is revision R${pkg.revision.toString().padStart(2, '0')}. Ensure all previous comments from Director of Surveys have been addressed.`
    })
  }

  return {
    passed: blockers.length === 0,
    blockers,
    warnings
  }
}

export function getSubmissionChecklist(subtype: string): { code: string; label: string; required: boolean }[] {
  const surveyType = SUBTYPE_TO_SURVEY_TYPE[subtype] || 'cadastral'
  const minPrecision = TRAVERSE_PRECISION_STANDARDS[surveyType]
  
  const base = [
    { code: 'COORD_SYS', label: 'Coordinate system specified (Arc 1960 / UTM Zone 37S)', required: true },
    { code: 'SURVEYOR_PROFILE', label: 'Licensed surveyor profile complete (ISK Reg. No.)', required: true },
    { code: 'LR_NUMBER', label: 'LR Number specified', required: true },
    { code: 'COUNTY', label: 'County specified', required: true },
    { code: 'DISTRICT', label: 'District specified', required: true },
    { code: 'AREA_COMPUTED', label: 'Parcel area computed and > 0', required: true },
    { code: 'PRECISION', label: `Traverse precision meets 1:${minPrecision}`, required: true },
    { code: 'BEACONS', label: 'Beacon types and positions verified', required: true },
    { code: 'FORM_NO4', label: 'Form No. 4 (Mutation Form) generated', required: true },
    { code: 'DXF_PLAN', label: 'DXF plan with TitleBlock generated', required: true },
  ]

  const cadastralExtras = [
    { code: 'PPA2', label: 'PPA2 (Permission to Amend) attached', required: true },
    { code: 'LCB_CONSENT', label: 'Land Control Board consent attached', required: true },
    { code: 'BEACON_CERT', label: 'Beacon completion certificate attached', required: true },
    { code: 'SEARCH_CERT', label: 'Official search certificate attached', required: false },
  ]

  const topoExtras = [
    { code: 'CONTOURS', label: 'Contour interval matches spec', required: true },
    { code: 'SPOT_HEIGHTS', label: 'Spot heights verified against field book', required: true },
    { code: 'IDW_COMPUTED', label: 'IDW interpolation completed', required: true },
  ]

  const engineeringExtras = [
    { code: 'HORIZONTAL_CURVE', label: 'Horizontal curve computation verified', required: true },
    { code: 'SUPERELEVATION', label: 'Superelevation within RDM 1.1 limits', required: true },
    { code: 'VERTICAL_CURVE', label: 'Vertical curve K-value meets SSD requirements', required: true },
    { code: 'EARTHWORKS', label: 'Cross-section volumes computed', required: false },
  ]

  if (subtype.startsWith('cadastral')) {
    return [...base, ...cadastralExtras]
  }
  if (subtype.startsWith('topographic')) {
    return [...base, ...topoExtras]
  }
  if (subtype.startsWith('engineering')) {
    return [...base, ...engineeringExtras]
  }

  return base
}

/**
 * P2-1 Phase 13 Workstream 3: Submission numbering tests
 *
 * Tests the SRVY2025-1 format parsing and revision incrementing.
 * The generateSubmissionNumber function requires a DB connection
 * (tested via integration), so this suite covers the pure functions.
 */

import { incrementRevision, parseSubmissionNumber } from '../numbering'

describe('P2-1: SRVY2025-1 submission numbering', () => {
  describe('parseSubmissionNumber', () => {
    test('parses a valid submission number', () => {
      const result = parseSubmissionNumber('RS149_2025_002_R00')
      expect(result).toEqual({
        registrationNo: 'RS149',
        year: 2025,
        sequence: 2,
        revision: 0,
      })
    })

    test('parses with double-digit revision', () => {
      const result = parseSubmissionNumber('RS149_2025_002_R10')
      expect(result).toEqual({
        registrationNo: 'RS149',
        year: 2025,
        sequence: 2,
        revision: 10,
      })
    })

    test('parses with 3-digit sequence', () => {
      const result = parseSubmissionNumber('ISK/LS/2024/123_2025_099_R03')
      expect(result).toEqual({
        registrationNo: 'ISK/LS/2024/123',
        year: 2025,
        sequence: 99,
        revision: 3,
      })
    })

    test('returns null for invalid format (too few parts)', () => {
      expect(parseSubmissionNumber('RS149_2025_002')).toBeNull()
    })

    test('returns null for invalid format (no R prefix)', () => {
      expect(parseSubmissionNumber('RS149_2025_002_00')).toBeNull()
    })

    test('returns null for non-numeric year', () => {
      expect(parseSubmissionNumber('RS149_XXXX_002_R00')).toBeNull()
    })

    test('returns null for empty string', () => {
      expect(parseSubmissionNumber('')).toBeNull()
    })
  })

  describe('incrementRevision', () => {
    test('R00 → R01', () => {
      expect(incrementRevision('RS149_2025_002_R00')).toBe('RS149_2025_002_R01')
    })

    test('R09 → R10 (zero-padding preserved)', () => {
      expect(incrementRevision('RS149_2025_002_R09')).toBe('RS149_2025_002_R10')
    })

    test('R99 → R100 (expands to 3 digits)', () => {
      expect(incrementRevision('RS149_2025_002_R99')).toBe('RS149_2025_002_R100')
    })

    test('throws for invalid format', () => {
      expect(() => incrementRevision('RS149_2025_002')).toThrow('Invalid')
    })

    test('throws for missing R prefix', () => {
      expect(() => incrementRevision('RS149_2025_002_00')).toThrow('Invalid')
    })
  })

  describe('format consistency', () => {
    test('round-trip: parse → increment → parse', () => {
      const original = 'RS149_2025_007_R02'
      const incremented = incrementRevision(original)
      const parsed = parseSubmissionNumber(incremented)

      expect(parsed).not.toBeNull()
      expect(parsed!.revision).toBe(3)
      expect(parsed!.sequence).toBe(7)
      expect(parsed!.year).toBe(2025)
      expect(parsed!.registrationNo).toBe('RS149')
    })
  })
})

/**
 * P0-2 verification: toolGates registry + gate lookup logic.
 *
 * The actual <ToolGate> component reads from useSubscription() which
 * requires a React context provider — tested via integration. This
 * unit test covers the pure registry logic: the map is complete, the
 * PLAN_RANK ordering is correct, and getToolGate returns the right
 * info for known paths and null for unknown ones.
 */
import { TOOL_GATES, PLAN_RANK, getToolGate } from '@/lib/subscription/toolGates'

describe('P0-2: toolGates registry', () => {
  test('all 9 gated tools are in the registry', () => {
    const expected = [
      '/tools/civil-export',
      '/tools/gis-export',
      '/tools/machine-control',
      '/tools/topo-drawing',
      '/tools/survey-plan-demo',
      '/tools/gnss-baseline',
      '/tools/drone',
      '/tools/slope-analysis',
      '/tools/progress-monitor',
    ]
    for (const path of expected) {
      expect(TOOL_GATES[path]).toBeDefined()
      expect(TOOL_GATES[path].minPlan).toBeTruthy()
      expect(TOOL_GATES[path].feature).toBeTruthy()
      expect(TOOL_GATES[path].label).toBeTruthy()
    }
    expect(Object.keys(TOOL_GATES).length).toBe(expected.length)
  })

  test('PLAN_RANK is monotonically increasing free → enterprise', () => {
    expect(PLAN_RANK.free).toBeLessThan(PLAN_RANK.pro)
    expect(PLAN_RANK.pro).toBeLessThan(PLAN_RANK.team)
    expect(PLAN_RANK.team).toBeLessThan(PLAN_RANK.firm)
    expect(PLAN_RANK.firm).toBeLessThan(PLAN_RANK.enterprise)
  })

  test('getToolGate returns GateInfo for known gated path', () => {
    const gate = getToolGate('/tools/civil-export')
    expect(gate).not.toBeNull()
    expect(gate!.minPlan).toBe('pro')
    expect(gate!.feature).toBe('dxf_export')
    expect(gate!.label).toBe('DXF Export')
  })

  test('getToolGate returns null for free (ungated) tool', () => {
    expect(getToolGate('/tools/traverse')).toBeNull()
    expect(getToolGate('/tools/cassini-utm')).toBeNull()
    expect(getToolGate('/tools/leveling')).toBeNull()
  })

  test('getToolGate returns null for unknown path', () => {
    expect(getToolGate('/tools/nonexistent')).toBeNull()
    expect(getToolGate('/not-a-tool')).toBeNull()
  })

  test('progress-monitor is the only Team-tier gate', () => {
    const teamGates = Object.entries(TOOL_GATES).filter(([, g]) => g.minPlan === 'team')
    expect(teamGates.length).toBe(1)
    expect(teamGates[0][0]).toBe('/tools/progress-monitor')
  })

  test('all other gates are Pro-tier', () => {
    const proGates = Object.entries(TOOL_GATES).filter(([, g]) => g.minPlan === 'pro')
    expect(proGates.length).toBe(8)
  })
})

/**
 * Atmospheric Defaults Engine
 * 
 * Ensures surveyors ALWAYS have correct atmospheric conditions for their
 * observation corrections. Without atmospheric data, EDM distances in Kenya
 * accumulate massive errors:
 *   - Nairobi (~1700m): ~22 ppm atmospheric + ~267 ppm sea level = 289 ppm total
 *   - That's 289mm per kilometer of UNCORRECTED distance error
 *   - At 1:5000 cadastral precision, that blows misclosure on any line > ~17m
 * 
 * This engine provides a 3-tier fallback system:
 *   1. Project-level settings (stored in DB, set once per project)
 *   2. Location presets (Kenya cities with typical conditions)
 *   3. Real-time weather API (Open-Meteo, free, no API key)
 *   4. Auto UTM zone detection from coordinates
 * 
 * The UI should ALWAYS show atmospheric conditions — never leave them empty.
 * If no data is available, show a prominent warning.
 */

import { KENYA_CONDITIONS } from '../corrections/atmospheric';
import { KENYA_GEOID_UNDULATION } from '../corrections/sea-level-reduction';

// ─── Types ───────────────────────────────────────────────────────

export interface AtmosphericDefaults {
  /** Temperature in °C */
  temperature: number;
  /** Pressure in hPa */
  pressure: number;
  /** Relative humidity in % */
  humidity: number;
  /** Mean elevation above sea level in meters (orthometric height) */
  elevation: number;
  /** UTM zone (36S or 37S for Kenya) */
  utmZone: 'UTM36S' | 'UTM37S';
  /** Geoid undulation at the site (meters) — Kenya default: -12m */
  geoidUndulation: number;
  /** Refraction coefficient — Kenya tropical daytime default: 0.13 */
  refractionCoefficient: number;
  /** Source of the atmospheric data */
  source: AtmosphericSource;
  /** When the data was fetched (for weather API) */
  fetchedAt?: string;
  /** Whether these are verified/confirmed by the surveyor */
  verified: boolean;
}

export type AtmosphericSource =
  | 'project_settings'    // Explicitly set in project configuration
  | 'location_preset'     // Derived from known Kenya city/location
  | 'weather_api'         // Fetched from Open-Meteo API
  | 'default';            // Fallback defaults

export interface ProjectAtmosphericSettings {
  temperature?: number;
  pressure?: number;
  humidity?: number;
  elevation?: number;
  utmZone?: 'UTM36S' | 'UTM37S';
  county?: string;
  latitude?: number;
  longitude?: number;
}

