/**
 * Beacon Reference Database — Offline-Cached Spatial Lookup
 * =========================================================
 *
 * A spatial query layer over the Survey of Kenya beacon database
 * (trig beacons, bench marks, control points). Optimized for field
 * use: the full database is cached locally so queries work without
 * internet, and spatial queries use accurate haversine distance
 * (not bounding-box approximation).
 *
 * Why this exists
 * ---------------
 * Surveyors spend hours searching SoK archives for nearby control
 * points when starting a new survey. A built-in lookup that works
 * offline saves that time. The existing src/lib/online/benchmarks.ts
 * uses bounding-box distance (Pythagorean on lat/lon degrees) which
 * is fine for filtering but inaccurate for distance reporting. This
 * module adds proper haversine distance and a local cache.
 *
 * What lives here
 * ---------------
 *   - Haversine distance (accurate great-circle distance on the
 *     ellipsoid, ±0.3% vs Vincenty)
 *   - Spatial nearest-K query: "find the 5 nearest trig beacons
 *     to this coordinate, within 10 km"
 *   - Offline cache: the full database is held in memory; queries
 *     never hit the network. Future work: persist to IndexedDB
 *     for cross-session offline use.
 *   - Bearing computation: "what bearing is the nearest BM from
 *     my current position?" — helps surveyors locate physical marks.
 *
 * Usage
 * -----
 *   import { findNearestBeacons } from '@/lib/survey/beaconLookup'
 *
 *   const results = await findNearestBeacons({
 *     latitude: -1.2921,
 *     longitude: 36.8219,
 *     radiusKm: 10,
 *     limit: 5,
 *     types: ['TRIG', 'BM'],
 *   })
 *
 *   for (const beacon of results.beacons) {
 *     console.log(`${beacon.name}: ${beacon.distanceKm.toFixed(2)} km at ${beacon.bearingDeg.toFixed(0)}°`)
 *   }
 */

import { BENCHMARK_DATABASE, type Benchmark } from '@/lib/online/benchmarks'

// ─── Types ──────────────────────────────────────────────────────────────

export type BeaconType = 'BM' | 'CP' | 'TRIG' | 'TIDAL'

export interface BeaconSearchParams {
  latitude: number
  longitude: number
  /** Maximum distance in kilometres. Default: 50 km. */
  radiusKm?: number
  /** Maximum number of results to return (sorted nearest first). Default: 10. */
  limit?: number
  /** Filter by beacon type. Omit to include all types. */
  types?: BeaconType[]
  /** Filter by country (case-insensitive). Omit for all countries. */
  country?: string
}

export interface BeaconSearchResult {
  /** Beacon with distance and bearing from the search point. */
  beacon: Benchmark
  /** Distance from search point in kilometres (haversine). */
  distanceKm: number
  /** Initial bearing from search point to beacon, in degrees (0-360). */
  bearingDeg: number
}

export interface BeaconSearchResponse {
  beacons: BeaconSearchResult[]
  total: number
  searchPoint: { latitude: number; longitude: number }
  radiusKm: number
  /** Time spent on the query, in milliseconds. */
  elapsedMs: number
  /** True if results came from the local cache (always true for now). */
  fromCache: boolean
}

// ─── Haversine distance ────────────────────────────────────────────────

const EARTH_RADIUS_KM = 6371

function toRadians(deg: number): number {
  return (deg * Math.PI) / 180
}

function toDegrees(rad: number): number {
  return (rad * 180) / Math.PI
}

/**
 * Haversine great-circle distance between two lat/lon points.
 * Accurate to ±0.3% vs Vincenty's formulae — more than enough for
 * beacon location (we're not doing geodesy here, just navigation).
 */
export function haversineDistanceKm(
  lat1: number,
  lon1: number,
  lat2: number,
  lon2: number
): number {
  const dLat = toRadians(lat2 - lat1)
  const dLon = toRadians(lon2 - lon1)
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRadians(lat1)) *
      Math.cos(toRadians(lat2)) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2)
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
  return EARTH_RADIUS_KM * c
}

/**
 * Initial bearing (forward azimuth) from point 1 to point 2.
 * Returns degrees 0-360, where 0 = north, 90 = east.
 *
 * Uses the standard spherical bearing formula. The bearing is
 * "initial" — it changes as you travel along the great circle.
 * For short distances (< 100 km) the change is negligible.
 */
export function bearingDegrees(
  lat1: number,
  lon1: number,
  lat2: number,
  lon2: number
): number {
  const φ1 = toRadians(lat1)
  const φ2 = toRadians(lat2)
  const Δλ = toRadians(lon2 - lon1)
  const y = Math.sin(Δλ) * Math.cos(φ2)
  const x =
    Math.cos(φ1) * Math.sin(φ2) -
    Math.sin(φ1) * Math.cos(φ2) * Math.cos(Δλ)
  return (toDegrees(Math.atan2(y, x)) + 360) % 360
}

// ─── Cache ──────────────────────────────────────────────────────────────

/**
 * In-memory cache of beacons with lat/lon coordinates.
 * Beacons without coordinates are excluded (can't do spatial search).
 *
 * Future work: persist to IndexedDB for cross-session offline use.
 * For now, the in-memory cache is populated on first query and
 * survives for the lifetime of the process.
 */
let cachedBeacons: Benchmark[] | null = null

function getCachedBeacons(): Benchmark[] {
  if (cachedBeacons === null) {
    cachedBeacons = BENCHMARK_DATABASE.filter(
      (b: Benchmark) =>
        b.latitude !== undefined && b.longitude !== undefined
    )
  }
  return cachedBeacons as Benchmark[]
}

/**
 * Force a cache rebuild on next query. Useful after database updates.
 */
export function invalidateBeaconCache(): void {
  cachedBeacons = null
}

/**
 * Get cache statistics (for UI display / debugging).
 */
export function getCacheStats(): {
  totalBeacons: number
  beaconsWithCoordinates: number
  isCached: boolean
} {
  const all = BENCHMARK_DATABASE
  const withCoords = all.filter(
    (b: Benchmark) => b.latitude !== undefined && b.longitude !== undefined
  )
  return {
    totalBeacons: all.length,
    beaconsWithCoordinates: withCoords.length,
    isCached: cachedBeacons !== null,
  }
}

// ─── Public API ─────────────────────────────────────────────────────────

/**
 * Find the nearest beacons to a coordinate.
 *
 * Uses haversine distance for accuracy. Results are sorted nearest-first.
 * Filters by radius, type, and country before sorting.
 *
 * @returns beacons within radiusKm, sorted nearest-first, limited to `limit`
 */
export async function findNearestBeacons(
  params: BeaconSearchParams
): Promise<BeaconSearchResponse> {
  const startTime = Date.now()
  const {
    latitude,
    longitude,
    radiusKm = 50,
    limit = 10,
    types,
    country,
  } = params

  const allBeacons = getCachedBeacons()

  // Filter + compute distance
  const results: BeaconSearchResult[] = []
  for (const beacon of allBeacons) {
    // Type filter
    if (types && !types.includes(beacon.type as BeaconType)) continue

    // Country filter
    if (country && beacon.country.toLowerCase() !== country.toLowerCase()) continue

    const distanceKm = haversineDistanceKm(
      latitude,
      longitude,
      beacon.latitude!,
      beacon.longitude!
    )

    // Radius filter
    if (distanceKm > radiusKm) continue

    const bearingDeg = bearingDegrees(
      latitude,
      longitude,
      beacon.latitude!,
      beacon.longitude!
    )

    results.push({ beacon, distanceKm, bearingDeg })
  }

  // Sort nearest-first
  results.sort((a, b) => a.distanceKm - b.distanceKm)

  // Limit
  const limited = results.slice(0, limit)

  return {
    beacons: limited,
    total: results.length,
    searchPoint: { latitude, longitude },
    radiusKm,
    elapsedMs: Date.now() - startTime,
    fromCache: true,
  }
}

/**
 * Get a single beacon by ID. Returns null if not found.
 */
export async function getBeaconById(id: string): Promise<Benchmark | null> {
  return BENCHMARK_DATABASE.find((b: Benchmark) => b.id === id) ?? null
}

/**
 * Format a beacon search result as a human-readable summary.
 * Useful for display in the UI or for a surveyor's field sheet.
 */
export function formatBeaconResults(response: BeaconSearchResponse): string {
  if (response.beacons.length === 0) {
    return `No beacons found within ${response.radiusKm} km of ${response.searchPoint.latitude.toFixed(4)}, ${response.searchPoint.longitude.toFixed(4)}.`
  }

  const lines: string[] = [
    `${response.total} beacon(s) within ${response.radiusKm} km (showing nearest ${response.beacons.length}, ${response.elapsedMs}ms):`,
    '',
  ]

  for (const { beacon, distanceKm, bearingDeg } of response.beacons) {
    const bearingLabel = formatBearing(bearingDeg)
    lines.push(
      `  ${beacon.name} (${beacon.type}): ${distanceKm.toFixed(2)} km ${bearingLabel} — ${beacon.elevation.toFixed(3)} m ${beacon.datum}`
    )
  }

  return lines.join('\n')
}

/**
 * Convert a bearing in degrees to a 16-point compass label.
 * 0° = N, 22.5° = NNE, 45° = NE, etc.
 */
function formatBearing(bearingDeg: number): string {
  const labels = [
    'N', 'NNE', 'NE', 'ENE', 'E', 'ESE', 'SE', 'SSE',
    'S', 'SSW', 'SW', 'WSW', 'W', 'WNW', 'NW', 'NNW',
  ]
  const idx = Math.round(bearingDeg / 22.5) % 16
  return `${labels[idx]} (${bearingDeg.toFixed(0)}°)`
}

/**
 * EDM Atmospheric Correction Module
 * 
 * Corrects measured EDM distances for atmospheric conditions
 * (temperature, pressure, humidity) using the IAG/ISO standard formula.
 * 
 * At Nairobi altitude (~1700m, P≈830hPa), uncorrected measurements
 * accumulate ~22 ppm error — that's 22mm per kilometer.
 * 
 * References:
 * - IAG Resolution (1999) for refractivity formulae
 * - ISO 17123-4:2012 for EDM testing
 * - Rüeger, J.M. (1996) "Electronic Distance Measurement"
 */

// ─── Types ───────────────────────────────────────────────────────

export type EDMWavelength = 0.6328 | 0.850 | 0.910; // μm: HeNe, IR, common IR

export interface AtmosphericConditions {
  /** Dry bulb temperature in degrees Celsius */
  temperature: number;
  /** Atmospheric pressure in hectopascals (mbar) */
  pressure: number;
  /** Relative humidity as percentage (0-100) */
  humidity: number;
}

export interface AtmosphericCorrectionResult {
  /** Original raw slope distance (meters) */
  rawDistance: number;
  /** Corrected slope distance (meters) */
  correctedDistance: number;
  /** Correction in parts per million */
  ppmCorrection: number;
  /** Absolute correction in meters */
  correctionMeters: number;
  /** First velocity correction (ppm) */
  firstVelocityCorrection: number;
  /** Second velocity correction (ppm) — small, usually < 0.1 ppm */
  secondVelocityCorrection: number;
  /** Partial water vapor pressure (hPa) used in computation */
  vaporPressure: number;
  /** Group refractivity under reference conditions */
  nRef: number;
  /** Group refractivity under observed conditions */
  nObs: number;
  /** Reference conditions used */
  referenceConditions: AtmosphericConditions;
}

export interface EDMInstrument {
  /** Carrier wavelength in micrometers */
  wavelength: EDMWavelength;
  /** Reference refractivity (N-value) — default 273.82 for most instruments */
  referenceN: number;
  /** Instrument constant in meters (additive) */
  constant: number;
  /** PPM setting on instrument (if pre-set) */
  ppmSetting: number;
}

// ─── Constants ───────────────────────────────────────────────────

/** Standard atmospheric conditions (most EDM instruments calibrated here) */
export const STANDARD_CONDITIONS: AtmosphericConditions = {
  temperature: 20,       // °C
  pressure: 1013.25,     // hPa (1 atm)
  humidity: 0,           // 0% for dry air reference
};

/** Kenya-specific typical conditions for validation */
export const KENYA_CONDITIONS = {
  nairobi: { temperature: 20, pressure: 830, humidity: 60 },
  mombasa: { temperature: 30, pressure: 1010, humidity: 75 },
  kisumu: { temperature: 24, pressure: 880, humidity: 65 },
  eldoret: { temperature: 18, pressure: 820, humidity: 70 },
} as const;

// ─── Core Functions ──────────────────────────────────────────────

/**
 * Compute partial water vapor pressure using the Magnus-Tetens formula.
 * 
 * e = (RH / 100) × 6.112 × exp(17.62 × t / (243.12 + t))
 * 
 * Valid for: -45°C < t < +60°C (sufficient for all field conditions)
 * Accuracy: ±0.2 hPa over normal survey temperature range
 * 
 * @param temperature - Dry bulb temperature (°C)
 * @param humidity - Relative humidity (%)
 * @returns Partial water vapor pressure (hPa)
 */
export function computeVaporPressure(temperature: number, humidity: number): number {
  if (temperature < -45 || temperature > 60) {
    throw new Error(`Temperature ${temperature}°C outside valid range (-45 to +60°C)`);
  }
  if (humidity < 0 || humidity > 100) {
    throw new Error(`Humidity ${humidity}% outside valid range (0-100%)`);
  }
  
  const saturationVaporPressure = 6.112 * Math.exp(
    (17.62 * temperature) / (243.12 + temperature)
  );
  
  return (humidity / 100) * saturationVaporPressure;
}

/**
 * Compute group refractivity (N-value) for a given wavelength and conditions.
 * 
 * N = (n_group - 1) × 10^6
 * 
 * Uses the IAG standard formula (Rüeger 1996) for GROUP refractivity:
 * 
 * N_grp = (n_g - 1) × 10^6
 *       = [(287.604 + 3 × 1.6288/λ² + 5 × 0.0136/λ⁴) × P × 1.0003 / (273.15 + t)]
 *         - [11.27 × e / (273.15 + t)]
 * 
 * The factors 3 and 5 on the dispersion terms convert phase refractivity
 * to group refractivity (which is what EDM instruments measure).
 * 
 * The factor 1.0003 is an enhancement factor for non-ideal gas behavior.
 * 
 * At standard conditions (20°C, 1013.25 hPa, 0% humidity, λ=0.850μm):
 *   N_ref ≈ 273-275 (consistent with most EDM instrument reference values)
 * 
 * @param wavelength - Carrier wavelength (μm)
 * @param conditions - Atmospheric conditions
 * @returns Group refractivity N-value
 */
export function computeGroupRefractivity(
  wavelength: EDMWavelength,
  conditions: AtmosphericConditions
): number {
  const { temperature, pressure, humidity } = conditions;
  
  // Partial water vapor pressure
  const e = computeVaporPressure(temperature, humidity);
  
  // Dry component of GROUP refractivity
  // The factors 3 and 5 on dispersion terms convert phase → group refractivity
  const lambdaSq = wavelength * wavelength;
  const lambdaFourth = lambdaSq * lambdaSq;
  const groupCoeff = 287.604 + (3 * 1.6288 / lambdaSq) + (5 * 0.0136 / lambdaFourth);
  
  // Enhancement factor for non-ideal gas (≈1.0003 at normal pressures)
  const enhancement = 1 + 0.0003;
  
  const N_dry = groupCoeff * pressure * enhancement / (273.15 + temperature);
  
  // Wet component (water vapor reduces refractivity)
  const N_wet = (11.27 * e) / (273.15 + temperature);
  
  return N_dry - N_wet;
}

/**
 * Apply atmospheric correction to an EDM distance measurement.
 * 
 * Corrected distance = Raw distance × (1 + (N_ref - N_obs) / 10^6)
 * 
 * This is the "first velocity correction". A second velocity correction
 * exists but is typically < 0.1 ppm and is included for completeness.
 * 
 * @param rawDistance - Raw measured slope distance (meters)
 * @param conditions - Observed atmospheric conditions
 * @param instrument - EDM instrument parameters
 * @returns Full correction result with audit trail
 */
export function applyAtmosphericCorrection(
  rawDistance: number,
  conditions: AtmosphericConditions,
  instrument: Partial<EDMInstrument> = {}
): AtmosphericCorrectionResult {
  // Defaults
  const wavelength: EDMWavelength = (instrument.wavelength as EDMWavelength) ?? 0.850;
  const referenceN = instrument.referenceN ?? computeGroupRefractivity(wavelength, STANDARD_CONDITIONS);
  const ppmSetting = instrument.ppmSetting ?? 0;
  
  // Validate inputs
  if (rawDistance < 0) {
    throw new Error(`Raw distance ${rawDistance}m must be non-negative`);
  }
  if (conditions.pressure < 500 || conditions.pressure > 1100) {
    throw new Error(`Pressure ${conditions.pressure} hPa outside valid range (500-1100 hPa)`);
  }
  
  // Compute observed refractivity
  const nObs = computeGroupRefractivity(wavelength, conditions);
  
  // First velocity correction (ppm)
  const firstVelocityCorrection = referenceN - nObs;
  
  // Second velocity correction (ppm) — small correction for the
  // difference between phase and group velocity in the atmosphere
  // Typically < 0.1 ppm, but included for completeness
  const e = computeVaporPressure(conditions.temperature, conditions.humidity);
  const secondVelocityCorrection = computeSecondVelocityCorrection(
    wavelength, conditions, e
  );
  
  // Total correction in ppm
  const ppmCorrection = firstVelocityCorrection + secondVelocityCorrection - ppmSetting;
  
  // Apply correction
  const correctionMeters = rawDistance * ppmCorrection / 1e6;
  const correctedDistance = rawDistance + correctionMeters;
  
  return {
    rawDistance,
    correctedDistance,
    ppmCorrection: Math.round(ppmCorrection * 100) / 100, // 2 decimal places
    correctionMeters: Math.round(correctionMeters * 1e6) / 1e6, // micrometer precision
    firstVelocityCorrection: Math.round(firstVelocityCorrection * 100) / 100,
    secondVelocityCorrection: Math.round(secondVelocityCorrection * 1000) / 1000,
    vaporPressure: Math.round(e * 100) / 100,
    nRef: Math.round(referenceN * 100) / 100,
    nObs: Math.round(nObs * 100) / 100,
    referenceConditions: STANDARD_CONDITIONS,
  };
}

/**
 * Compute the second velocity correction.
 * This accounts for the difference between the phase refractivity
 * (which the EDM actually measures) and the group refractivity
 * (which determines the propagation speed of the modulation).
 * 
 * Typically < 0.1 ppm but included for highest accuracy.
 * 
 * @param wavelength - Carrier wavelength (μm)
 * @param conditions - Atmospheric conditions
 * @param vaporPressure - Pre-computed vapor pressure (hPa)
 * @returns Second velocity correction in ppm
 */
function computeSecondVelocityCorrection(
  wavelength: EDMWavelength,
  conditions: AtmosphericConditions,
  vaporPressure: number
): number {
  const { temperature, pressure } = conditions;
  const T = 273.15 + temperature;
  
  // Wavelength dependence
  const lambdaSq = wavelength * wavelength;
  const lambdaFourth = lambdaSq * lambdaSq;
  
  // Derivative of dry refractivity with respect to wavelength
  const dN_dLambda2 = -2 * (1.6288 / (lambdaSq * lambdaSq)) - 4 * (0.0136 / (lambdaFourth * lambdaSq));
  
  // Second velocity correction
  const svc = dN_dLambda2 * lambdaSq * pressure / T * 1e-6;
  
  return svc;
}

// ─── Convenience Functions ───────────────────────────────────────

/**
 * Quick atmospheric correction — returns just the corrected distance.
 * Useful when you don't need the full audit trail.
 */
export function quickAtmosphericCorrection(
  rawDistance: number,
  temperature: number,
  pressure: number,
  humidity: number,
  wavelength: EDMWavelength = 0.850
): number {
  return applyAtmosphericCorrection(
    rawDistance,
    { temperature, pressure, humidity },
    { wavelength }
  ).correctedDistance;
}

/**
 * Compute the atmospheric correction ppm for given conditions.
 * Useful for checking if a measurement needs correction.
 */
export function getAtmosphericPPM(
  temperature: number,
  pressure: number,
  humidity: number,
  wavelength: EDMWavelength = 0.850
): number {
  return applyAtmosphericCorrection(
    1000, // arbitrary reference distance
    { temperature, pressure, humidity },
    { wavelength }
  ).ppmCorrection;
}

/**
 * Validate that atmospheric conditions are within reasonable ranges
 * for surveying in Kenya.
 */
export function validateAtmosphericConditions(conditions: AtmosphericConditions): {
  valid: boolean;
  warnings: string[];
} {
  const warnings: string[] = [];
  
  if (conditions.temperature < -10 || conditions.temperature > 50) {
    warnings.push(`Temperature ${conditions.temperature}°C is outside normal Kenya range (10-40°C)`);
  }
  if (conditions.pressure < 600 || conditions.pressure > 1050) {
    warnings.push(`Pressure ${conditions.pressure} hPa is unusual for Kenya (600-1050 hPa expected)`);
  }
  if (conditions.humidity > 95) {
    warnings.push(`Humidity ${conditions.humidity}% is very high — check for condensation on instrument`);
  }
  
  return {
    valid: warnings.length === 0,
    warnings,
  };
}

/**
 * Grid Scale Factor Module
 * 
 * Computes the point scale factor for UTM and Cassini-Soldner projections.
 * This is the BIGGEST accuracy gap in most surveying software.
 * 
 * At Nairobi (UTM Zone 37S, ~180km from central meridian):
 *   Scale factor ≈ 1.0004
 *   That's 400 ppm — 400mm per kilometer of uncorrected distance.
 * 
 * For cadastral work requiring 1:10,000 closure, this alone can
 * blow the misclosure on traverses longer than ~250m per line.
 * 
 * References:
 * - Snyder, J.P. (1987) "Map Projections — A Working Manual" (USGS PP 1395)
 * - Kenya Survey Department technical specifications
 */

import { WGS84_A, WGS84_E2 } from './curvature-refraction';

// ─── Types ───────────────────────────────────────────────────────

export type ProjectionType = 'UTM36S' | 'UTM37S' | 'CASSINI_SOLDNER';

export interface UTMZone {
  /** Zone number (36 or 37 for Kenya) */
  zone: number;
  /** Hemisphere: 'S' for southern */
  hemisphere: 'N' | 'S';
  /** Central meridian in degrees */
  centralMeridian: number;
  /** Central scale factor (0.9996 for UTM) */
  k0: number;
  /** False easting (500000 for UTM) */
  falseEasting: number;
  /** False northing (0 for N, 10000000 for S) */
  falseNorthing: number;
}

export interface PointScaleFactorResult {
  /** Point scale factor (dimensionless) */
  scaleFactor: number;
  /** Deviation from unity in ppm */
  ppmFromUnity: number;
  /** Easting from central meridian (meters) */
  eastingFromCM: number;
  /** Meridional radius of curvature (meters) */
  rho: number;
  /** Radius of curvature in prime vertical (meters) */
  nu: number;
  /** Mean radius of curvature (meters) */
  Rm: number;
  /** Grid convergence at point (decimal degrees) */
  convergence: number;
  /** Latitude of point (decimal degrees) */
  latitude: number;
  /** Projection used */
  projection: ProjectionType;
}

export interface LineScaleFactorResult {
  /** Line scale factor (Simpson's rule average) */
  lineScaleFactor: number;
  /** Scale factor at start point */
  startScaleFactor: number;
  /** Scale factor at midpoint */
  midScaleFactor: number;
  /** Scale factor at end point */
  endScaleFactor: number;
  /** Grid distance (meters) */
  gridDistance: number;
  /** Ellipsoidal distance (meters) */
  ellipsoidalDistance: number;
  /** Correction in ppm */
  ppmCorrection: number;
}

// ─── Pre-defined UTM Zones for Kenya ────────────────────────────

export const UTM_ZONES: Record<string, UTMZone> = {
  UTM36S: {
    zone: 36,
    hemisphere: 'S',
    centralMeridian: 33,
    k0: 0.9996,
    falseEasting: 500000,
    falseNorthing: 10000000,
  },
  UTM37S: {
    zone: 37,
    hemisphere: 'S',
    centralMeridian: 39,
    k0: 0.9996,
    falseEasting: 500000,
    falseNorthing: 10000000,
  },
};

// Cassini-Soldner parameters (varies by local system in Kenya)
export interface CassiniSoldnerParams {
  /** Origin latitude (decimal degrees) */
  originLatitude: number;
  /** Origin longitude (decimal degrees) */
  originLongitude: number;
  /** False easting (meters) */
  falseEasting: number;
  /** False northing (meters) */
  falseNorthing: number;
  /** Ellipsoid semi-major axis */
  a: number;
  /** Ellipsoid flattening reciprocal */
  rf: number;
}

// ─── Core Functions ──────────────────────────────────────────────

/**
 * Compute meridional radius of curvature ρ.
 * ρ = a(1 - e²) / (1 - e² × sin²(φ))^(3/2)
 */
function computeMeridionalRadius(latitude: number, a: number = WGS84_A, e2: number = WGS84_E2): number {
  const phi = latitude * Math.PI / 180;
  const sinPhi = Math.sin(phi);
  const denom = Math.pow(1 - e2 * sinPhi * sinPhi, 1.5);
  return a * (1 - e2) / denom;
}

/**
 * Compute radius of curvature in the prime vertical ν.
 * ν = a / √(1 - e² × sin²(φ))
 */
function computePrimeVerticalRadius(latitude: number, a: number = WGS84_A, e2: number = WGS84_E2): number {
  const phi = latitude * Math.PI / 180;
  const sinPhi = Math.sin(phi);
  return a / Math.sqrt(1 - e2 * sinPhi * sinPhi);
}

/**
 * Compute grid convergence at a point.
 * 
 * For UTM:
 * γ = (λ - λ₀) × sin(φ) × [1 + (λ - λ₀)² × cos²(φ) / 3 + ...]
 * 
 * @param latitude - Latitude in decimal degrees
 * @param longitude - Longitude in decimal degrees
 * @param centralMeridian - Central meridian in decimal degrees
 * @returns Grid convergence in decimal degrees
 */
export function computeGridConvergence(
  latitude: number,
  longitude: number,
  centralMeridian: number
): number {
  const phi = latitude * Math.PI / 180;
  const dLambda = (longitude - centralMeridian) * Math.PI / 180;
  const sinPhi = Math.sin(phi);
  const cosPhi = Math.cos(phi);
  
  // First-order convergence
  let gamma = dLambda * sinPhi;
  
  // Higher-order terms for better accuracy
  const dLambda2 = dLambda * dLambda;
  gamma += (dLambda2 * dLambda / 3) * sinPhi * cosPhi * cosPhi;
  
  // Convert back to degrees
  return gamma * 180 / Math.PI;
}

/**
 * Compute point scale factor for UTM projection.
 * 
 * k = k₀ × [1 + (E'²)/(2Rm²) × (1 + e'²cos²φ) + (E'⁴)/(24Rm⁴)]
 * 
 * Where E' = easting from central meridian = E - 500,000
 * 
 * Simplified (sufficient for 2nd order accuracy):
 * k = k₀ × (1 + E'² / (2 × Rm²))
 * 
 * @param easting - UTM easting in meters
 * @param northing - UTM northing in meters
 * @param projection - UTM zone identifier
 * @returns Point scale factor result
 */
export function computeUTMPointScaleFactor(
  easting: number,
  northing: number,
  projection: 'UTM36S' | 'UTM37S'
): PointScaleFactorResult {
  const zone = UTM_ZONES[projection];
  if (!zone) {
    throw new Error(`Unknown UTM zone: ${projection}`);
  }
  
  // Easting from central meridian
  const Eprime = easting - zone.falseEasting;
  
  // Estimate latitude from northing (for computing radii of curvature)
  // This uses the approximate footpoint latitude formula
  const latitude = estimateLatitudeFromNorthing(northing, zone);
  
  // Compute radii of curvature
  const rho = computeMeridionalRadius(latitude);
  const nu = computePrimeVerticalRadius(latitude);
  const Rm = Math.sqrt(rho * nu);
  
  // Second eccentricity squared
  const ePrime2 = WGS84_E2 / (1 - WGS84_E2);
  const cosPhi = Math.cos(latitude * Math.PI / 180);
  const cosPhi2 = cosPhi * cosPhi;
  
  // Point scale factor (full formula for 2nd order accuracy)
  const Eprime2 = Eprime * Eprime;
  const Eprime4 = Eprime2 * Eprime2;
  const Rm2 = Rm * Rm;
  const Rm4 = Rm2 * Rm2;
  
  const k = zone.k0 * (
    1 + 
    (Eprime2 / (2 * Rm2)) * (1 + ePrime2 * cosPhi2) +
    (Eprime4 / (24 * Rm4))
  );
  
  // Grid convergence
  const longitude = estimateLongitudeFromEasting(easting, zone, latitude);
  const convergence = computeGridConvergence(latitude, longitude, zone.centralMeridian);
  
  return {
    scaleFactor: k,
    ppmFromUnity: Math.round((k - 1) * 1e6 * 100) / 100,
    eastingFromCM: Eprime,
    rho,
    nu,
    Rm,
    convergence,
    latitude,
    projection,
  };
}

/**
 * Compute line scale factor using Simpson's rule.
 * 
 * k_line = (k_A + 4×k_M + k_B) / 6
 * 
 * Where k_A, k_M, k_B are point scale factors at start, mid, and end.
 * This gives much better accuracy than simple averaging, especially
 * for lines that cross significant latitude or easting changes.
 * 
 * @param startEasting - Start point easting (meters)
 * @param startNorthing - Start point northing (meters)
 * @param endEasting - End point easting (meters)
 * @param endNorthing - End point northing (meters)
 * @param projection - UTM zone
 * @returns Line scale factor result
 */
export function computeLineScaleFactor(
  startEasting: number,
  startNorthing: number,
  endEasting: number,
  endNorthing: number,
  projection: 'UTM36S' | 'UTM37S'
): LineScaleFactorResult {
  // Midpoint coordinates
  const midEasting = (startEasting + endEasting) / 2;
  const midNorthing = (startNorthing + endNorthing) / 2;
  
  // Point scale factors
  const sfStart = computeUTMPointScaleFactor(startEasting, startNorthing, projection);
  const sfMid = computeUTMPointScaleFactor(midEasting, midNorthing, projection);
  const sfEnd = computeUTMPointScaleFactor(endEasting, endNorthing, projection);
  
  // Simpson's rule line scale factor
  const lineScaleFactor = (sfStart.scaleFactor + 4 * sfMid.scaleFactor + sfEnd.scaleFactor) / 6;
  
  // Compute distances
  const dE = endEasting - startEasting;
  const dN = endNorthing - startNorthing;
  const gridDistance = Math.sqrt(dE * dE + dN * dN);
  const ellipsoidalDistance = gridDistance / lineScaleFactor;
  
  const ppmCorrection = (lineScaleFactor - 1) * 1e6;
  
  return {
    lineScaleFactor,
    startScaleFactor: sfStart.scaleFactor,
    midScaleFactor: sfMid.scaleFactor,
    endScaleFactor: sfEnd.scaleFactor,
    gridDistance,
    ellipsoidalDistance,
    ppmCorrection: Math.round(ppmCorrection * 100) / 100,
  };
}

/**
 * Apply grid scale factor to convert ellipsoidal distance to grid distance.
 * 
 * Grid distance = Ellipsoidal distance × Line scale factor
 * 
 * @param ellipsoidalDistance - Distance reduced to the ellipsoid (meters)
 * @param startEasting - Start point easting
 * @param startNorthing - Start point northing
 * @param endEasting - End point easting
 * @param endNorthing - End point northing
 * @param projection - UTM zone
 * @returns Grid distance in meters
 */
export function applyGridScaleFactor(
  ellipsoidalDistance: number,
  startEasting: number,
  startNorthing: number,
  endEasting: number,
  endNorthing: number,
  projection: 'UTM36S' | 'UTM37S'
): { gridDistance: number; lineScaleFactor: number; ppm: number } {
  const result = computeLineScaleFactor(
    startEasting, startNorthing,
    endEasting, endNorthing,
    projection
  );
  
  return {
    gridDistance: ellipsoidalDistance * result.lineScaleFactor,
    lineScaleFactor: result.lineScaleFactor,
    ppm: result.ppmCorrection,
  };
}

// ─── Helper Functions ────────────────────────────────────────────

/**
 * Estimate latitude from UTM northing (footpoint latitude).
 * Uses the series expansion of the inverse meridional arc formula.
 */
function estimateLatitudeFromNorthing(northing: number, zone: UTMZone): number {
  const a = WGS84_A;
  const e2 = WGS84_E2;
  const e4 = e2 * e2;
  const e6 = e4 * e2;
  
  // Adjusted northing
  const N = northing - zone.falseNorthing;
  
  // Meridional arc
  const M = N / zone.k0;
  
  // Footpoint latitude (series expansion)
  const mu = M / (a * (1 - e2 / 4 - 3 * e4 / 64 - 5 * e6 / 256));
  
  const ePrime2 = e2 / (1 - e2);
  
  const phi1 = mu + 
    (3 * ePrime2 / 2 - 27 * ePrime2 * ePrime2 / 32) * Math.sin(2 * mu) +
    (21 * ePrime2 * ePrime2 / 16 - 55 * ePrime2 * ePrime2 * ePrime2 / 32) * Math.sin(4 * mu) +
    (151 * ePrime2 * ePrime2 * ePrime2 / 96) * Math.sin(6 * mu);
  
  return phi1 * 180 / Math.PI;
}

/**
 * Estimate longitude from UTM easting and known latitude.
 */
function estimateLongitudeFromEasting(easting: number, zone: UTMZone, latitude: number): number {
  const phi = latitude * Math.PI / 180;
  const ePrime2 = WGS84_E2 / (1 - WGS84_E2);
  const nu = computePrimeVerticalRadius(latitude);
  const rho = computeMeridionalRadius(latitude);
  const T = Math.tan(phi) * Math.tan(phi);
  const C = ePrime2 * Math.cos(phi) * Math.cos(phi);
  const N = nu;
  const R = rho;
  const D = (easting - zone.falseEasting) / (zone.k0 * N);
  
  const lon = zone.centralMeridian * Math.PI / 180 + 
    (D - (1 + 2 * T + C) * D * D * D / 6 + 
     (5 - 2 * C + 28 * T - 3 * C * C + 8 * ePrime2 + 24 * T * T) * 
     D * D * D * D * D / 120) / Math.cos(phi);
  
  return lon * 180 / Math.PI;
}

/**
 * Sea Level / Ellipsoid Reduction Module
 * 
 * Reduces measured distances from ground level to the ellipsoid surface.
 * In Nairobi (~1700m elevation), this is a 267 ppm correction —
 * 267mm per kilometer of uncorrected distance.
 * 
 * This MUST be applied BEFORE the grid scale factor in the correction
 * pipeline. The full reduction chain is:
 * 
 *   Slope → Horizontal → Sea Level → Grid
 * 
 * Reference:
 * - Clark, D. (1975) "Plane and Geodetic Surveying"
 * - Bomford, G. (1980) "Geodesy"
 */

import { computeMeanEarthRadius, WGS84_A, WGS84_E2 } from './curvature-refraction';

// ─── Types ───────────────────────────────────────────────────────

export interface SeaLevelReductionInput {
  /** Horizontal distance measured at ground level (meters) */
  horizontalDistance: number;
  /** Mean height of the measured line above the ellipsoid (meters)
   *  If orthometric height is known, add geoid undulation N:
   *  h_ellipsoid = h_orthometric + N
   */
  heightAboveEllipsoid?: number;
  /** Latitude in decimal degrees (for computing Earth radius) */
  latitude?: number;
  /** Geoid undulation N at the point (meters)
   *  Positive = geoid above ellipsoid
   *  For Kenya: N ≈ -10 to -20m (EGM96)
   *  Set to 0 if using ellipsoidal heights directly
   */
  geoidUndulation?: number;
  /** Orthometric height (height above geoid/MSL) in meters
   *  Used to compute ellipsoidal height if not provided directly
   */
  orthometricHeight?: number;
}

export interface SeaLevelReductionResult {
  /** Original ground-level horizontal distance (meters) */
  groundDistance: number;
  /** Reduced ellipsoidal distance (meters) */
  ellipsoidalDistance: number;
  /** Reduction in meters */
  reductionMeters: number;
  /** Reduction in ppm */
  reductionPPM: number;
  /** Mean height above ellipsoid used (meters) */
  meanHeight: number;
  /** Earth radius used (meters) */
  earthRadius: number;
  /** Latitude used */
  latitude: number;
  /** Geoid undulation used (meters) */
  geoidUndulation: number;
}

// ─── Constants ───────────────────────────────────────────────────

/** Kenya geoid undulation estimates (EGM96) — meters */
export const KENYA_GEOID_UNDULATION: Record<string, number> = {
  nairobi: -12,
  mombasa: -8,
  kisumu: -15,
  eldoret: -14,
  nakuru: -13,
  // Default for Kenya
  default: -12,
};

// ─── Core Functions ──────────────────────────────────────────────

/**
 * Reduce a ground-level horizontal distance to the ellipsoid.
 * 
 * d_ellipsoid = d_ground × R / (R + h)
 * 
 * Where:
 *   R = mean radius of Earth at latitude
 *   h = mean height of the measured line above the ellipsoid
 * 
 * At Nairobi (h ≈ 1700m, R ≈ 6378000m):
 *   Reduction = 1700 / 6378000 = 266.5 ppm
 *   For a 1km line: reduction = 266.5mm
 * 
 * @param input - Reduction parameters
 * @returns Reduction result
 */
export function applySeaLevelReduction(
  input: SeaLevelReductionInput
): SeaLevelReductionResult {
  const {
    horizontalDistance,
    latitude = 0,
    geoidUndulation = 0,
    orthometricHeight,
  } = input;
  
  // Compute ellipsoidal height
  let heightAboveEllipsoid = input.heightAboveEllipsoid;
  
  // If orthometric height is given but ellipsoidal height isn't,
  // compute ellipsoidal height from orthometric + geoid undulation
  if (orthometricHeight !== undefined && heightAboveEllipsoid === undefined) {
    heightAboveEllipsoid = orthometricHeight + geoidUndulation;
  }
  
  if (heightAboveEllipsoid === undefined) {
    throw new Error('Either heightAboveEllipsoid or orthometricHeight must be provided');
  }
  
  if (horizontalDistance <= 0) {
    throw new Error(`Horizontal distance must be positive, got ${horizontalDistance}`);
  }
  
  // Compute Earth radius at latitude
  const R = computeMeanEarthRadius(latitude);
  
  // Apply reduction
  // d_ellipsoid = d_ground × R / (R + h)
  const reductionFactor = R / (R + heightAboveEllipsoid);
  const ellipsoidalDistance = horizontalDistance * reductionFactor;
  
  const reductionMeters = horizontalDistance - ellipsoidalDistance;
  const reductionPPM = (reductionMeters / horizontalDistance) * 1e6;
  
  return {
    groundDistance: horizontalDistance,
    ellipsoidalDistance,
    reductionMeters: Math.round(reductionMeters * 1e6) / 1e6,
    reductionPPM: Math.round(reductionPPM * 100) / 100,
    meanHeight: heightAboveEllipsoid,
    earthRadius: R,
    latitude,
    geoidUndulation,
  };
}

/**
 * Quick sea level reduction — returns just the reduced distance.
 */
export function quickSeaLevelReduction(
  horizontalDistance: number,
  heightAboveEllipsoid: number,
  latitude: number = 0
): number {
  const R = computeMeanEarthRadius(latitude);
  return horizontalDistance * R / (R + heightAboveEllipsoid);
}

/**
 * Compute the reduction factor for a given height and latitude.
 * Useful for checking the magnitude of the correction.
 */
export function computeReductionFactor(
  heightAboveEllipsoid: number,
  latitude: number = 0
): { factor: number; ppm: number } {
  const R = computeMeanEarthRadius(latitude);
  const factor = R / (R + heightAboveEllipsoid);
  const ppm = (1 - factor) * 1e6;
  
  return {
    factor,
    ppm: Math.round(ppm * 100) / 100,
  };
}

/**
 * Get estimated geoid undulation for a Kenya location.
 * Uses EGM96 approximate values.
 * 
 * For precise work, use the full EGM2008 model or local geoid.
 */
export function getKenyaGeoidUndulation(location: string): number {
  const key = location.toLowerCase();
  return KENYA_GEOID_UNDULATION[key] ?? KENYA_GEOID_UNDULATION.default;
}

/**
 * Reverse operation: expand ellipsoidal distance to ground distance.
 * Useful for setting out — converting grid/ellipsoidal distances
 * back to ground distances for field work.
 * 
 * d_ground = d_ellipsoid × (R + h) / R
 */
export function expandToGroundDistance(
  ellipsoidalDistance: number,
  heightAboveEllipsoid: number,
  latitude: number = 0
): number {
  const R = computeMeanEarthRadius(latitude);
  return ellipsoidalDistance * (R + heightAboveEllipsoid) / R;
}

/**
 * Chainage-Offset Transformation Engine — corridor coordinate system
 *
 * PROBLEM
 * -------
 * On a road corridor (KeNHA), surveyors work in (chainage, offset) space:
 *   - Chainage = distance along the centerline from the start (e.g., 12+450 = 12450m)
 *   - Offset = perpendicular distance from the centerline (left = negative, right = positive)
 *
 * But total stations and GNSS output easting/northing. This module converts
 * between the two coordinate systems along an alignment defined by PI points
 * (Points of Intersection).
 *
 * WHAT IT DOES
 * ------------
 * 1. ENtoChainageOffset(easting, northing) → { chainage, offset, onCurve }
 *    Given an EN coordinate, find which chainage station it's nearest to and
 *    how far left/right of the centerline it is.
 *
 * 2. chainageOffsetToEN(chainage, offset) → { easting, northing }
 *    Given a chainage and offset, compute the EN coordinate.
 *
 * 3. organizeShotsByChainage(shots, alignment, interval) → CrossSectionGroup[]
 *    Takes a batch of field shots (EN + RL) and automatically groups them
 *    into cross-sections at chainage intervals, computing each shot's offset.
 *
 * USAGE
 * -----
 *   import { buildAlignment, enToChainageOffset, organizeShotsByChainage } from
 *     '@/lib/survey/corridorEngine'
 *
 *   const alignment = buildAlignment(piPoints)
 *   const { chainage, offset } = enToChainageOffset(alignment, 264100, 9861100)
 *   // chainage = 12450.0, offset = -3.2 (3.2m left of CL)
 */

// ─── Types ──────────────────────────────────────────────────────────────────

export interface PIPoint {
  /** Point ID (e.g., 'PI1') */
  id: string
  /** Easting (meters) */
  e: number
  /** Northing (meters) */
  n: number
  /** Chainage at this PI (meters) — optional, computed if not given */
  chainage?: number
}

export interface AlignmentSegment {
  /** From PI */
  fromPI: string
  /** To PI */
  toPI: string
  /** Bearing of this segment (degrees) */
  bearing: number
  /** Length of this segment (meters) */
  length: number
  /** Cumulative chainage at the start of this segment */
  startChainage: number
  /** Cumulative chainage at the end of this segment */
  endChainage: number
  /** Start EN */
  startE: number
  startN: number
  /** End EN */
  endE: number
  endN: number
}

export interface Alignment {
  /** PI points in order */
  pis: PIPoint[]
  /** Computed segments */
  segments: AlignmentSegment[]
  /** Total length (meters) */
  totalLength: number
}

export interface ChainageOffsetResult {
  /** Chainage along the alignment (meters) */
  chainage: number
  /** Perpendicular offset from CL (meters, left = negative) */
  offset: number
  /** Which segment the point falls on */
  segmentIndex: number
  /** Whether the point is on a curve (always false for straight alignment) */
  onCurve: boolean
  /** The foot of the perpendicular (EN on the centerline) */
  footE: number
  footN: number
}

export interface FieldShot {
  /** Easting (meters) */
  e: number
  /** Northing (meters) */
  n: number
  /** Reduced level (meters) */
  rl: number
  /** Point name/ID */
  name?: string
  /** Point code (e.g., 'CL', 'LE', 'RE', 'DG') */
  code?: string
}

export interface CrossSectionShot {
  /** Original field shot */
  shot: FieldShot
  /** Computed chainage (meters) */
  chainage: number
  /** Computed offset (meters, left = negative) */
  offset: number
  /** Which cross-section group this belongs to */
  chainageStation: number
}

export interface CrossSectionGroup {
  /** Chainage station (rounded to interval) */
  chainage: number
  /** Chainage label (e.g., '12+450') */
  label: string
  /** All shots in this cross-section, sorted by offset (left to right) */
  shots: CrossSectionShot[]
  /** Leftmost offset */
  leftOffset: number
  /** Rightmost offset */
  rightOffset: number
  /** Centerline RL (shot nearest to offset=0) */
  centrelineRL: number | null
}

// ─── Build Alignment from PI Points ─────────────────────────────────────────

/**
 * Build an alignment from a sequence of PI (Point of Intersection) points.
 *
 * Computes bearings, segment lengths, and cumulative chainages.
 *
 * @param pis - PI points in order (start → end)
 * @param startChainage - Chainage at the first PI (default: 0)
 * @returns Alignment with computed segments
 */
export function buildAlignment(pis: PIPoint[], startChainage: number = 0): Alignment {
  if (pis.length < 2) {
    throw new Error('Alignment requires at least 2 PI points')
  }

  const segments: AlignmentSegment[] = []
  let cumulativeChainage = startChainage

  for (let i = 0; i < pis.length - 1; i++) {
    const from = pis[i]
    const to = pis[i + 1]
    const dE = to.e - from.e
    const dN = to.n - from.n
    const length = Math.sqrt(dE * dE + dN * dN)
    const bearing = (Math.atan2(dE, dN) * 180 / Math.PI + 360) % 360

    const segChainage = cumulativeChainage
    cumulativeChainage += length

    segments.push({
      fromPI: from.id,
      toPI: to.id,
      bearing,
      length,
      startChainage: segChainage,
      endChainage: cumulativeChainage,
      startE: from.e,
      startN: from.n,
      endE: to.e,
      endN: to.n,
    })
  }

  return {
    pis,
    segments,
    totalLength: cumulativeChainage - startChainage,
  }
}

// ─── EN → Chainage/Offset ───────────────────────────────────────────────────

/**
 * Convert an easting/northing coordinate to chainage/offset along an alignment.
 *
 * Finds the nearest point on the alignment (foot of perpendicular) and
 * computes the chainage at that point plus the perpendicular offset.
 *
 * Left of the centerline (looking in the direction of increasing chainage)
 * is negative offset; right is positive.
 *
 * @param alignment - The alignment (from buildAlignment)
 * @param easting - Easting of the point (meters)
 * @param northing - Northing of the point (meters)
 * @returns ChainageOffsetResult
 */
export function enToChainageOffset(
  alignment: Alignment,
  easting: number,
  northing: number,
): ChainageOffsetResult {
  let bestSegment = 0
  let bestDist = Infinity
  let bestFootE = 0
  let bestFootN = 0
  let bestT = 0 // parameter along segment (0=start, 1=end)

  for (let i = 0; i < alignment.segments.length; i++) {
    const seg = alignment.segments[i]
    const dE = seg.endE - seg.startE
    const dN = seg.endN - seg.startN
    const segLen2 = dE * dE + dN * dN

    if (segLen2 < 1e-12) continue

    // Project point onto segment
    const t = ((easting - seg.startE) * dE + (northing - seg.startN) * dN) / segLen2
    const tClamped = Math.max(0, Math.min(1, t))
    const footE = seg.startE + tClamped * dE
    const footN = seg.startN + tClamped * dN
    const dist = Math.sqrt((easting - footE) ** 2 + (northing - footN) ** 2)

    if (dist < bestDist) {
      bestDist = dist
      bestSegment = i
      bestFootE = footE
      bestFootN = footN
      bestT = tClamped
    }
  }

  const seg = alignment.segments[bestSegment]
  const chainage = seg.startChainage + bestT * seg.length

  // Compute offset sign: cross product to determine left/right
  // Direction vector of segment
  const dirE = seg.endE - seg.startE
  const dirN = seg.endN - seg.startN
  // Vector from foot to point
  const toPointE = easting - bestFootE
  const toPointN = northing - bestFootN
  // Cross product (2D z-component): dir × toPoint
  // In a standard EN coordinate system (x=east, y=north):
  //   positive cross → point is to the LEFT of travel direction
  //   negative cross → point is to the RIGHT
  const cross = dirE * toPointN - dirN * toPointE
  const offset = cross >= 0 ? -bestDist : bestDist

  return {
    chainage,
    offset,
    segmentIndex: bestSegment,
    onCurve: false,
    footE: bestFootE,
    footN: bestFootN,
  }
}

// ─── Chainage/Offset → EN ───────────────────────────────────────────────────

/**
 * Convert a chainage/offset coordinate to easting/northing.
 *
 * @param alignment - The alignment
 * @param chainage - Chainage along the alignment (meters)
 * @param offset - Perpendicular offset (meters, left = negative)
 * @returns { easting, northing }
 */
export function chainageOffsetToEN(
  alignment: Alignment,
  chainage: number,
  offset: number,
): { easting: number; northing: number } {
  // Find the segment containing this chainage
  let seg: AlignmentSegment | null = null
  for (const s of alignment.segments) {
    if (chainage >= s.startChainage && chainage <= s.endChainage) {
      seg = s
      break
    }
  }

  if (!seg) {
    // Clamp to the nearest end
    if (chainage < alignment.segments[0].startChainage) {
      seg = alignment.segments[0]
    } else {
      seg = alignment.segments[alignment.segments.length - 1]
    }
  }

  // Position along the segment
  const t = seg.length > 0
    ? (chainage - seg.startChainage) / seg.length
    : 0
  const clampedT = Math.max(0, Math.min(1, t))

  // Point on centerline
  const clE = seg.startE + clampedT * (seg.endE - seg.startE)
  const clN = seg.startN + clampedT * (seg.endN - seg.startN)

  // Perpendicular direction (rotate bearing by 90°)
  // Right perpendicular: bearing + 90°
  const perpBearing = (seg.bearing + 90) * Math.PI / 180
  const perpE = Math.sin(perpBearing)
  const perpN = Math.cos(perpBearing)

  // Apply offset
  const easting = clE + offset * perpE
  const northing = clN + offset * perpN

  return { easting, northing }
}

// ─── Organize Field Shots by Chainage ───────────────────────────────────────

/**
 * Organize a batch of field shots into cross-section groups by chainage.
 *
 * This is the core function for corridor survey: the surveyor captures shots
 * at cross-section intervals along a road, and this function automatically:
 *   1. Converts each shot's EN to (chainage, offset)
 *   2. Rounds the chainage to the nearest interval (e.g., 20m stations)
 *   3. Groups shots by station
 *   4. Sorts within each group by offset (left to right)
 *   5. Identifies the centerline shot (nearest to offset=0)
 *
 * @param shots - Array of field shots (EN + RL)
 * @param alignment - The alignment
 * @param interval - Cross-section interval in meters (default: 20)
 * @returns CrossSectionGroup[] sorted by chainage
 */
export function organizeShotsByChainage(
  shots: FieldShot[],
  alignment: Alignment,
  interval: number = 20,
): CrossSectionGroup[] {
  // Convert each shot to chainage/offset
  const crossSectionShots: CrossSectionShot[] = shots.map(shot => {
    const result = enToChainageOffset(alignment, shot.e, shot.n)
    const chainageStation = Math.round(result.chainage / interval) * interval
    return {
      shot,
      chainage: result.chainage,
      offset: result.offset,
      chainageStation,
    }
  })

  // Group by chainage station
  const groups = new Map<number, CrossSectionShot[]>()
  for (const css of crossSectionShots) {
    if (!groups.has(css.chainageStation)) {
      groups.set(css.chainageStation, [])
    }
    groups.get(css.chainageStation)!.push(css)
  }

  // Build CrossSectionGroup for each station
  const result: CrossSectionGroup[] = []
  for (const [chainage, groupShots] of groups) {
    // Sort by offset (left to right)
    groupShots.sort((a, b) => a.offset - b.offset)

    // Find centerline shot (nearest to offset=0)
    let clShot: CrossSectionShot | null = null
    let clDist = Infinity
    for (const cs of groupShots) {
      if (Math.abs(cs.offset) < clDist) {
        clDist = Math.abs(cs.offset)
        clShot = cs
      }
    }

    result.push({
      chainage,
      label: formatChainage(chainage),
      shots: groupShots,
      leftOffset: groupShots[0].offset,
      rightOffset: groupShots[groupShots.length - 1].offset,
      centrelineRL: clShot ? clShot.shot.rl : null,
    })
  }

  // Sort by chainage
  result.sort((a, b) => a.chainage - b.chainage)

  return result
}

// ─── Chainage Formatting ────────────────────────────────────────────────────

/**
 * Format a chainage in meters as a km+m string.
 * e.g., 12450 → '12+450'
 */
export function formatChainage(chainage: number): string {
  const km = Math.floor(chainage / 1000)
  const m = chainage % 1000
  return `${km}+${m.toFixed(0).padStart(3, '0')}`
}

/**
 * Parse a km+m chainage string to meters.
 * e.g., '12+450' → 12450
 */
export function parseChainage(str: string): number {
  const match = str.trim().match(/^(\d+)\+(\d+(?:\.\d+)?)$/)
  if (match) {
    return parseInt(match[1], 10) * 1000 + parseFloat(match[2])
  }
  return parseFloat(str) || 0
}

/**
 * Circular Curve Calculations
 * 
 * Horizontal circular curve computations for road and railway design.
 * Handles simple curves, compound curves, and reverse curves.
 * 
 * References:
 * - Schofield, W. (2001) "Engineering Surveying"
 * - Meyer, C.F. (1969) "Route Surveying and Design"
 */

// ─── Types ───────────────────────────────────────────────────────

export interface CircularCurveParams {
  /** Intersection angle (decimal degrees) — total deflection */
  intersectionAngle: number;
  /** Radius of the curve (meters) */
  radius: number;
}

export interface CircularCurveResult {
  /** Intersection angle (decimal degrees) */
  intersectionAngle: number;
  /** Radius (meters) */
  radius: number;
  /** Tangent length (meters) — PI to PC or PI to PT */
  tangentLength: number;
  /** Curve length (meters) — arc from PC to PT */
  curveLength: number;
  /** Length of long chord (meters) — straight line PC to PT */
  longChordLength: number;
  /** Mid-ordinate (meters) — distance from midpoint of long chord to curve */
  midOrdinate: number;
  /** External distance (meters) — distance from PI to curve midpoint */
  externalDistance: number;
  /** Degree of curvature (decimal degrees) — based on arc definition */
  degreeOfCurvature: number;
  /** Deflection angle to any point on curve (for setting out) */
  deflectionPerMeter: number; // degrees per meter of arc
}

export interface CurveStationResult {
  /** Chainage/station (meters) */
  chainage: number;
  /** Deflection angle from PC (decimal degrees) */
  deflectionAngle: number;
  /** Chord length from PC (meters) */
  chordLength: number;
  /** Easting coordinate */
  easting?: number;
  /** Northing coordinate */
  northing?: number;
}

// ─── Core Functions ──────────────────────────────────────────────

/**
 * Compute circular curve parameters from intersection angle and radius.
 * 
 * Standard formulas:
 *   T = R × tan(Δ/2)          — Tangent length
 *   L = R × Δ × (π/180)       — Curve length (arc)
 *   LC = 2R × sin(Δ/2)        — Long chord
 *   M = R × (1 - cos(Δ/2))    — Mid-ordinate
 *   E = R × (sec(Δ/2) - 1)    — External distance
 *   D = 5729.578 / R           — Degree of curvature (arc definition, 30m arc)
 */
export function computeCircularCurve(params: CircularCurveParams): CircularCurveResult {
  const { intersectionAngle, radius } = params;
  
  const deltaRad = intersectionAngle * Math.PI / 180;
  const halfDelta = deltaRad / 2;
  
  const tangentLength = radius * Math.tan(halfDelta);
  const curveLength = radius * deltaRad;
  const longChordLength = 2 * radius * Math.sin(halfDelta);
  const midOrdinate = radius * (1 - Math.cos(halfDelta));
  const externalDistance = radius * (1 / Math.cos(halfDelta) - 1);
  const degreeOfCurvature = 5729.578 / radius; // Arc definition (30m arc)
  const deflectionPerMeter = (intersectionAngle / 2) / curveLength; // degrees per meter
  
  return {
    intersectionAngle,
    radius,
    tangentLength: Math.round(tangentLength * 1000) / 1000,
    curveLength: Math.round(curveLength * 1000) / 1000,
    longChordLength: Math.round(longChordLength * 1000) / 1000,
    midOrdinate: Math.round(midOrdinate * 1000) / 1000,
    externalDistance: Math.round(externalDistance * 1000) / 1000,
    degreeOfCurvature: Math.round(degreeOfCurvature * 10000) / 10000,
    deflectionPerMeter: Math.round(deflectionPerMeter * 1000000) / 1000000,
  };
}

/**
 * Compute setting-out data for a circular curve at regular intervals.
 * 
 * Generates deflection angles and chord lengths for each station
 * along the curve, suitable for field stakeout.
 * 
 * @param curve - Circular curve parameters (from computeCircularCurve)
 * @param interval - Station interval (meters), default 10m
 * @param pcChainage - Chainage of PC (Point of Curvature)
 * @param pcEasting - Easting of PI (Point of Intersection)
 * @param pcNorthing - Northing of PI
 * @param backBearing - Bearing from PI to PC (decimal degrees)
 */
export function computeCurveStations(
  curve: CircularCurveResult,
  interval: number = 10,
  pcChainage: number = 0,
  piEasting?: number,
  piNorthing?: number,
  backBearing?: number,
): CurveStationResult[] {
  const stations: CurveStationResult[] = [];
  
  // PC station
  const pcDeflection = 0;
  stations.push({
    chainage: pcChainage,
    deflectionAngle: 0,
    chordLength: 0,
  });
  
  // Intermediate stations
  const numStations = Math.floor(curve.curveLength / interval);
  
  for (let i = 1; i <= numStations; i++) {
    const arcLength = i * interval;
    const deflectionAngle = arcLength * curve.deflectionPerMeter;
    const chordLength = 2 * curve.radius * Math.sin(deflectionAngle * Math.PI / 180);
    
    stations.push({
      chainage: pcChainage + arcLength,
      deflectionAngle: Math.round(deflectionAngle * 1000) / 1000,
      chordLength: Math.round(chordLength * 1000) / 1000,
    });
  }
  
  // PT station (exact)
  const ptArcLength = curve.curveLength;
  const ptDeflection = curve.intersectionAngle / 2;
  const ptChord = curve.longChordLength;
  
  // Only add if not already at an interval station
  const lastStation = stations[stations.length - 1];
  if (Math.abs(lastStation.chainage - (pcChainage + ptArcLength)) > 0.01) {
    stations.push({
      chainage: Math.round((pcChainage + ptArcLength) * 1000) / 1000,
      deflectionAngle: Math.round(ptDeflection * 1000) / 1000,
      chordLength: ptChord,
    });
  }
  
  // Compute coordinates if PI and bearing provided
  if (piEasting !== undefined && piNorthing !== undefined && backBearing !== undefined) {
    computeCurveCoordinates(stations, curve, piEasting, piNorthing, backBearing);
  }
  
  return stations;
}

/**
 * Compute coordinates for curve stations.
 */
function computeCurveCoordinates(
  stations: CurveStationResult[],
  curve: CircularCurveResult,
  piEasting: number,
  piNorthing: number,
  backBearing: number,
): void {
  // PC coordinates
  const pcBearing = backBearing; // Bearing from PI to PC
  const pcE = piEasting - curve.tangentLength * Math.sin(pcBearing * Math.PI / 180);
  const pcN = piNorthing - curve.tangentLength * Math.cos(pcBearing * Math.PI / 180);
  
  stations[0].easting = pcE;
  stations[0].northing = pcN;
  
  // Subsequent stations — compute from PC using deflection angles
  // AUDIT FIX (M6, 2026-07-02): original code was a no-op —
  // `if (tangentBearing >= 360) tangentBearing - 360;` computed the
  // subtraction but discarded the result. Replaced with modulo to wrap
  // to [0, 360). Also changed const → let.
  let tangentBearing = (backBearing + 180) % 360;
  if (tangentBearing < 0) tangentBearing += 360;
  
  for (let i = 1; i < stations.length; i++) {
    const deflRad = stations[i].deflectionAngle * Math.PI / 180;
    const tangentBearingRad = (tangentBearing) * Math.PI / 180;
    
    // Bearing to point on curve
    const bearingToStation = tangentBearingRad + deflRad;
    const chord = stations[i].chordLength;
    
    stations[i].easting = pcE + chord * Math.sin(bearingToStation);
    stations[i].northing = pcN + chord * Math.cos(bearingToStation);
  }
}

/**
 * Compute circular curve from tangent length and intersection angle.
 * Useful when radius is not directly specified.
 */
export function computeCurveFromTangent(
  tangentLength: number,
  intersectionAngle: number
): CircularCurveResult {
  const halfDelta = intersectionAngle * Math.PI / 360;
  const radius = tangentLength / Math.tan(halfDelta);
  
  return computeCircularCurve({ intersectionAngle, radius });
}

/**
 * Compute circular curve from degree of curvature.
 * Degree of curvature (arc definition): D = 5729.578 / R
 */
export function computeCurveFromDegree(
  degreeOfCurvature: number,
  intersectionAngle: number
): CircularCurveResult {
  const radius = 5729.578 / degreeOfCurvature;
  
  return computeCircularCurve({ intersectionAngle, radius });
}

/**
 * Spiral-to-Curve Alignment Engine
 *
 * Roadmap reference: docs/ROADMAP.md → Tier 2 → "Spiral-to-curve alignment
 * engine". Implements a full TS → SC → CS → ST alignment with clothoid
 * transition spirals on both ends of a circular curve.
 *
 * Stationing convention (Schofield / AASHTO):
 *
 *   TS (Tangent-to-Spiral)    start of entry spiral
 *   SC (Spiral-to-Curve)      end of entry spiral / start of circular curve
 *   CS (Curve-to-Spiral)      end of circular curve / start of exit spiral
 *   ST (Spiral-to-Tangent)    end of exit spiral
 *
 * Geometry (per AASHTO Green Book 2018 §3-Exhibit 3-22):
 *
 *   Δ     = intersection angle between approach and departure tangents (rad)
 *   R     = circular curve radius (m)
 *   Ls    = spiral length (m)
 *   θs    = Ls / (2R)              spiral angle (rad)
 *   p     = y - R·(1 - cos θs)     tangent shift (offset of curve from tangent)
 *   k     = x - R·sin θs           tangent extension (TS to shifted PI)
 *   T     = k + (R + p)·tan(Δ/2)   total tangent distance TS → PI
 *   Lc    = R·(Δ - 2θs)            circular curve length (m)
 *
 * The clothoid spiral coordinates (relative to TS, tangent along +X) are
 * computed via the standard series expansion (used by `transition.ts`).
 *
 * Output is a full station table plus a coordinate array that can be fed
 * directly to OpenLayers `LineString` or any other rendering layer.
 *
 * References:
 *   - Schofield, W. (2001) "Engineering Surveying", Chapter 12
 *   - AASHTO Green Book (2018), Chapter 3 — Horizontal Alignment
 *   - KeNHA Road Design Manual, Part 4 — Horizontal Curves
 */

import { computeSpiralCurve, type SpiralCurveInput, type SpiralCurveResult } from './transition'

// ─── Types ──────────────────────────────────────────────────────────────────

export interface SpiralAlignmentInput {
  /** Radius of the circular curve (metres). */
  radius: number
  /**
   * Intersection angle Δ in decimal degrees. This is the deflection
   * between the approach and departure tangents — i.e., 180° minus the
   * interior angle at the PI.
   */
  intersectionAngleDeg: number
  /** Spiral length Ls in metres (both spirals assumed equal). */
  spiralLength: number
  /** Chainage of the PI (Point of Intersection) in metres. */
  piChainage: number
  /**
   * Bearing of the approach tangent in decimal degrees (0° = North, clockwise).
   * Used to compute world coordinates; defaults to 0 (North).
   */
  approachBearingDeg?: number
  /** Easting of the PI (optional, for world-coordinate output). */
  piEasting?: number
  /** Northing of the PI (optional, for world-coordinate output). */
  piNorthing?: number
}

export interface SpiralAlignmentResult {
  /** Echoed input. */
  input: SpiralAlignmentInput
  /** Underlying spiral math (single spiral, applied symmetrically). */
  spiral: SpiralCurveResult
  /** Intersection angle in radians. */
  deltaRad: number
  /** Spiral angle θs in radians. */
  thetaSRad: number
  /** Tangent shift p (m). */
  p: number
  /** Tangent extension k (m, TS to shifted PI). */
  k: number
  /** Total tangent distance T (m, TS to PI). */
  T: number
  /** Circular curve length Lc (m, SC to CS). */
  Lc: number
  /** Total alignment length (m, TS to ST). Ls + Lc + Ls. */
  totalLength: number
  /** Chainage at TS. */
  tsChainage: number
  /** Chainage at SC. */
  scChainage: number
  /** Chainage at CS. */
  csChainage: number
  /** Chainage at ST. */
  stChainage: number
  /** World coordinates of TS (if PI coords supplied). */
  tsCoord: { easting: number; northing: number } | null
  /** World coordinates of SC. */
  scCoord: { easting: number; northing: number } | null
  /** World coordinates of CS. */
  csCoord: { easting: number; northing: number } | null
  /** World coordinates of ST. */
  stCoord: { easting: number; northing: number } | null
  /** World coordinates of PI (echoed). */
  piCoord: { easting: number; northing: number } | null
}

export interface AlignmentStation {
  /** Chainage (m). */
  chainage: number
  /** Distance from TS (m). */
  distanceFromTS: number
  /** Easting (m, world coords if PI supplied, else local). */
  easting: number
  /** Northing (m, world coords if PI supplied, else local). */
  northing: number
  /** Elevation/offset from tangent (m, +left of tangent). */
  offset: number
  /** Current segment. */
  segment: 'entry-spiral' | 'circular' | 'exit-spiral' | 'before' | 'after'
  /** Deflection angle from TS (decimal degrees, clockwise from approach tangent). */
  deflectionDeg: number
}

// ─── Math Helpers ───────────────────────────────────────────────────────────

const DEG = Math.PI / 180

/**
 * Compute a full TS → SC → CS → ST spiral alignment.
 *
 * The approach tangent is assumed to run from TS towards PI along the
 * +X axis (local coordinates). The departure tangent rotates by Δ
 * clockwise (right-hand curve). For a left-hand curve, supply a
 * negative intersection angle.
 */
export function computeSpiralAlignment(
  input: SpiralAlignmentInput
): SpiralAlignmentResult {
  const {
    radius,
    intersectionAngleDeg,
    spiralLength,
    piChainage,
    approachBearingDeg = 0,
    piEasting,
    piNorthing,
  } = input

  if (radius <= 0) throw new Error('Radius must be positive')
  if (spiralLength < 0) throw new Error('Spiral length must be non-negative')
  if (Math.abs(intersectionAngleDeg) < 1e-6) {
    throw new Error('Intersection angle must be non-zero')
  }

  // Single-spiral math (symmetric entry/exit)
  const spiralInput: SpiralCurveInput = {
    radius,
    designSpeed: 80, // placeholder, not used when Ls is derived externally
    c: 0.3,
  }
  const spiral = computeSpiralCurve(spiralInput)
  // Override the spiral length with the user-supplied value
  // (computeSpiralCurve derives Ls from speed; we override for direct control)
  const Ls = spiralLength
  const thetaS = Ls / (2 * radius)
  const deltaRad = Math.abs(intersectionAngleDeg) * DEG

  if (2 * thetaS >= deltaRad) {
    throw new Error(
      `Spiral angle ${thetaS / DEG}° × 2 ≥ intersection angle ${intersectionAngleDeg}° — no room for circular curve. Reduce Ls or increase Δ.`
    )
  }

  // Series expansion coordinates (Schofeld Eq. 12.8)
  const x = Ls * (1 - Math.pow(thetaS, 2) / 10 + Math.pow(thetaS, 4) / 216)
  const y = Ls * (thetaS / 3 - Math.pow(thetaS, 3) / 42 + Math.pow(thetaS, 5) / 1320)

  const p = y - radius * (1 - Math.cos(thetaS))
  const k = x - radius * Math.sin(thetaS)
  const T = k + (radius + p) * Math.tan(deltaRad / 2)
  const Lc = radius * (deltaRad - 2 * thetaS)
  const totalLength = 2 * Ls + Lc

  // Chainages
  const tsChainage = piChainage - T
  const scChainage = tsChainage + Ls
  const csChainage = scChainage + Lc
  const stChainage = csChainage + Ls

  // World coordinates (if PI supplied)
  let tsCoord: { easting: number; northing: number } | null = null
  let scCoord: { easting: number; northing: number } | null = null
  let csCoord: { easting: number; northing: number } | null = null
  let stCoord: { easting: number; northing: number } | null = null
  const piCoord =
    piEasting !== undefined && piNorthing !== undefined
      ? { easting: piEasting, northing: piNorthing }
      : null

  if (piCoord) {
    // Approach tangent direction (from TS to PI): approachBearing reversed
    const approachBrng = approachBearingDeg * DEG
    // TS is "behind" the PI along the approach tangent
    const dx = -T * Math.sin(approachBrng)
    const dy = -T * Math.cos(approachBrng)
    tsCoord = { easting: piCoord.easting + dx, northing: piCoord.northing + dy }

    // SC = TS + (x, y) in local frame, rotated by approachBearing
    // For a right-hand curve (positive Δ), Y points LEFT of the tangent
    scCoord = localToWorld(tsCoord, x, y, approachBrng)

    // CS = SC + circular arc (Δ - 2θs) along R
    // Center of circular curve is at distance (R + p) perpendicular to the
    // approach tangent, on the curve side. For right-hand curve, +Y direction.
    // Center = SC + R * (direction from curve to center)
    // Direction from SC to center: rotate tangent direction by 90° toward curve side
    // For right-hand curve: tangent +X, curve side +Y, center is at angle (90° + θs) from tangent at SC
    // Simpler: compute CS as SC rotated about center by (Δ - 2θs)
    const arcAngle = deltaRad - 2 * thetaS
    // Center of circular curve in local frame:
    // At SC, the tangent direction is rotated by θs from the original tangent.
    // The center is perpendicular to that, at distance R, on the inside of the curve.
    // For right-hand curve: center is at angle (90° + θs) from original tangent at TS.
    const centerLocalX = x - radius * Math.sin(thetaS)
    const centerLocalY = y + radius * Math.cos(thetaS)
    const centerWorld = localToWorld(tsCoord, centerLocalX, centerLocalY, approachBrng)
    // SC relative to center: rotate by -arcAngle to get CS (for right-hand curve, clockwise)
    // Vector from center to SC (local frame)
    const scRelCx = x - centerLocalX
    const scRelCy = y - centerLocalY
    // Rotate by -arcAngle (clockwise for right-hand curve)
    const csRelCx = scRelCx * Math.cos(-arcAngle) - scRelCy * Math.sin(-arcAngle)
    const csRelCy = scRelCx * Math.sin(-arcAngle) + scRelCy * Math.cos(-arcAngle)
    const csLocalX = centerLocalX + csRelCx
    const csLocalY = centerLocalY + csRelCy
    csCoord = localToWorld(tsCoord, csLocalX, csLocalY, approachBrng)

    // ST = CS + exit spiral (mirror of entry spiral)
    // At CS, tangent direction is rotated by (Δ - θs) from original.
    // Exit spiral mirrors entry: it curves in the opposite rotational sense,
    // starting from CS and ending at ST.
    // ST in local frame: reflect entry spiral about the perpendicular bisector.
    // Simplification: ST = PI + T * (departure tangent direction)
    const departureBrng = approachBrng + deltaRad // right-hand
    const stDx = T * Math.sin(departureBrng)
    const stDy = T * Math.cos(departureBrng)
    stCoord = { easting: piCoord.easting + stDx, northing: piCoord.northing + stDy }
  }

  return {
    input,
    spiral: { ...spiral, spiralLength: Ls, spiralAngle: (thetaS * 180) / Math.PI },
    deltaRad,
    thetaSRad: thetaS,
    p,
    k,
    T,
    Lc,
    totalLength,
    tsChainage,
    scChainage,
    csChainage,
    stChainage,
    tsCoord,
    scCoord,
    csCoord,
    stCoord,
    piCoord,
  }
}

/**
 * Transform a local-frame (x, y) point to world coordinates given a TS
 * origin and an approach bearing. Local frame: +X = along approach tangent
 * (toward PI), +Y = LEFT of tangent. Bearing convention: 0° = North, clockwise.
 */
function localToWorld(
  ts: { easting: number; northing: number },
  x: number,
  y: number,
  approachBrngRad: number
): { easting: number; northing: number } {
  // Approach tangent unit vector (TS → PI)
  const tx = Math.sin(approachBrngRad)
  const ty = Math.cos(approachBrngRad)
  // Left perpendicular (for right-hand curve, +Y is left)
  // For bearing 0 (North), tangent is (0, +1). Left of that is (-1, 0) which is West.
  // So left-perp = (-ty, tx)? Let's verify: rotate tangent 90° CCW = (-ty, tx)
  // For (0, 1) tangent, CCW 90° = (-1, 0). Yes that's West = left.
  const lx = -ty
  const ly = tx
  return {
    easting: ts.easting + x * tx + y * lx,
    northing: ts.northing + x * ty + y * ly,
  }
}

// ─── Station Interpolation ──────────────────────────────────────────────────

/**
 * Sample the spiral alignment at a fixed interval and return stations
 * with world coordinates, offsets, deflection angles, and segment labels.
 *
 * @param alignment  - Result of `computeSpiralAlignment`
 * @param interval   - Sample interval in metres (default 10)
 */
export function stationSpiralAlignment(
  alignment: SpiralAlignmentResult,
  interval: number = 10
): AlignmentStation[] {
  const stations: AlignmentStation[] = []
  const { input, thetaSRad, deltaRad, T, tsChainage, totalLength } = alignment
  const { radius, spiralLength: Ls, approachBearingDeg = 0 } = input
  const approachBrng = approachBearingDeg * DEG

  const N = Math.floor(totalLength / interval)
  for (let i = 0; i <= N; i++) {
    const d = i * interval // distance from TS
    if (d > totalLength + 0.01) continue
    const ch = tsChainage + d
    const station = stationAtDistance(alignment, d)
    if (station) stations.push({ ...station, chainage: ch })
  }
  // Ensure final station at ST
  const last = stations[stations.length - 1]
  if (!last || Math.abs(last.distanceFromTS - totalLength) > 0.01) {
    const station = stationAtDistance(alignment, totalLength)
    if (station) stations.push({ ...station, chainage: tsChainage + totalLength })
  }

  return stations
}

/**
 * Compute the station at a given distance from TS.
 *
 * Returns null for distances outside [0, totalLength].
 */
export function stationAtDistance(
  alignment: SpiralAlignmentResult,
  distanceFromTS: number
): AlignmentStation | null {
  const { input, thetaSRad, deltaRad, T, tsChainage, totalLength, tsCoord } = alignment
  const { radius, spiralLength: Ls, approachBearingDeg = 0 } = input
  const approachBrng = approachBearingDeg * DEG

  if (distanceFromTS < -0.01 || distanceFromTS > totalLength + 0.01) return null
  const d = Math.max(0, Math.min(totalLength, distanceFromTS))

  let localX: number
  let localY: number
  let segment: AlignmentStation['segment']
  let deflectionDeg: number

  if (d < Ls) {
    // Entry spiral (TS → SC)
    segment = 'entry-spiral'
    const s = d
    const theta = (s * s) / (2 * radius * Ls) // instantaneous spiral angle at s
    // Clothoid coordinates (series expansion about s)
    localX = s * (1 - Math.pow(theta, 2) / 10 + Math.pow(theta, 4) / 216)
    localY = s * (theta / 3 - Math.pow(theta, 3) / 42 + Math.pow(theta, 5) / 1320)
    deflectionDeg = (theta * 180) / Math.PI / 3 // approximate deflection (1/3 of spiral angle)
  } else if (d < Ls + alignment.Lc) {
    // Circular curve (SC → CS)
    segment = 'circular'
    const s = d - Ls
    const arcAngle = s / radius
    // At SC, the tangent is rotated by θs from the original tangent.
    // The point on the circular curve, measured from SC, is at angle
    // (θs + arcAngle) from the original tangent at TS.
    // Center is at (x_SC - R sin θs, y_SC + R cos θs) — see alignment computation
    const xSC = Ls * (1 - Math.pow(thetaSRad, 2) / 10 + Math.pow(thetaSRad, 4) / 216)
    const ySC = Ls * (thetaSRad / 3 - Math.pow(thetaSRad, 3) / 42 + Math.pow(thetaSRad, 5) / 1320)
    const centerLocalX = xSC - radius * Math.sin(thetaSRad)
    const centerLocalY = ySC + radius * Math.cos(thetaSRad)
    // Vector from center to SC
    const scRelCx = xSC - centerLocalX
    const scRelCy = ySC - centerLocalY
    // Rotate by -arcAngle (clockwise for right-hand curve)
    const relCx = scRelCx * Math.cos(-arcAngle) - scRelCy * Math.sin(-arcAngle)
    const relCy = scRelCx * Math.sin(-arcAngle) + scRelCy * Math.cos(-arcAngle)
    localX = centerLocalX + relCx
    localY = centerLocalY + relCy
    deflectionDeg = ((thetaSRad + arcAngle) * 180) / Math.PI
  } else {
    // Exit spiral (CS → ST) — mirror of entry
    segment = 'exit-spiral'
    const sFromST = totalLength - d // distance from ST, going backwards
    const s = sFromST
    const theta = (s * s) / (2 * radius * Ls)
    // Local coords of ST relative to TS would require rotating the entire
    // exit spiral; simpler to compute ST in local frame and add the reverse
    // spiral displacement
    // ST local: PI is at (T, 0); ST is at (T + T cos Δ, T sin Δ) ... actually
    // ST is reached by traveling T along departure tangent from PI.
    const stLocalX = T + T * Math.cos(deltaRad)
    const stLocalY = T * Math.sin(deltaRad) // right-hand curve: +Y
    // Reverse spiral at ST goes backward, curving opposite to entry spiral
    // For right-hand curve, exit spiral curves from CS (which is to the LEFT
    // of departure tangent) toward ST
    // Entry spiral coords (rotated): rotate (x, y) by Δ, then mirror
    const xSpiral = s * (1 - Math.pow(theta, 2) / 10 + Math.pow(theta, 4) / 216)
    const ySpiral = s * (theta / 3 - Math.pow(theta, 3) / 42 + Math.pow(theta, 5) / 1320)
    // At ST, looking back along the approach direction (departure tangent - 180°),
    // the spiral extends to the LEFT (for right-hand curve). So in the TS-local frame:
    localX = stLocalX - (xSpiral * Math.cos(deltaRad) + ySpiral * Math.sin(deltaRad))
    localY = stLocalY - (xSpiral * Math.sin(deltaRad) - ySpiral * Math.cos(deltaRad))
    deflectionDeg = ((deltaRad - theta) * 180) / Math.PI
  }

  // Offset = perpendicular distance from approach tangent (the Y coordinate in local frame)
  const offset = localY

  // World coordinates
  let easting = localX
  let northing = localY
  if (tsCoord) {
    const world = localToWorld(tsCoord, localX, localY, approachBrng)
    easting = world.easting
    northing = world.northing
  }

  return {
    chainage: tsChainage + d,
    distanceFromTS: Math.round(d * 1000) / 1000,
    easting: Math.round(easting * 1000) / 1000,
    northing: Math.round(northing * 1000) / 1000,
    offset: Math.round(offset * 1000) / 1000,
    segment,
    deflectionDeg: Math.round(deflectionDeg * 10000) / 10000,
  }
}

// ─── OpenLayers Geometry Helper ─────────────────────────────────────────────

/**
 * Produce a coordinate array for use with OpenLayers `LineString` or any
 * other rendering layer that expects [easting, northing] pairs.
 *
 * If the alignment was computed without PI coordinates, returns local-frame
 * coordinates (TS at origin, approach tangent along +X). Otherwise returns
 * world coordinates.
 */
export function alignmentToCoordinateArray(
  alignment: SpiralAlignmentResult,
  interval: number = 2
): Array<[number, number]> {
  const stations = stationSpiralAlignment(alignment, interval)
  return stations.map(s => [s.easting, s.northing])
}

/**
 * Convert stations to CSV for export.
 */
export function spiralAlignmentToCSV(stations: AlignmentStation[]): string {
  const header = 'Chainage_m,Distance_from_TS_m,Easting_m,Northing_m,Offset_m,Segment,Deflection_deg'
  const rows = stations.map(s =>
    [
      s.chainage.toFixed(3),
      s.distanceFromTS.toFixed(3),
      s.easting.toFixed(3),
      s.northing.toFixed(3),
      s.offset.toFixed(3),
      s.segment,
      s.deflectionDeg.toFixed(4),
    ].join(',')
  )
  return [header, ...rows].join('\n')
}

/**
 * Tests for spiralAlignment.ts
 *
 * Verifies:
 *   - TS/SC/CS/ST chainage computation
 *   - Tangent length T = k + (R+p)·tan(Δ/2)
 *   - Circular curve length Lc = R·(Δ - 2θs)
 *   - Total length = 2·Ls + Lc
 *   - Station interpolation at TS, SC, CS, ST
 *   - Coordinate array shape for OpenLayers
 *   - CSV export
 *   - Error handling (zero Δ, spirals too long, etc.)
 */

import {
  computeSpiralAlignment,
  stationSpiralAlignment,
  stationAtDistance,
  alignmentToCoordinateArray,
  spiralAlignmentToCSV,
  type SpiralAlignmentInput,
} from '../spiralAlignment'

const SAMPLE_INPUT: SpiralAlignmentInput = {
  radius: 300,
  intersectionAngleDeg: 30,
  spiralLength: 60,
  piChainage: 1000,
}

describe('computeSpiralAlignment — chainages', () => {
  it('computes TS < SC < CS < ST in order', () => {
    const a = computeSpiralAlignment(SAMPLE_INPUT)
    expect(a.tsChainage).toBeLessThan(a.scChainage)
    expect(a.scChainage).toBeLessThan(a.csChainage)
    expect(a.csChainage).toBeLessThan(a.stChainage)
  })

  it('places SC exactly Ls after TS', () => {
    const a = computeSpiralAlignment(SAMPLE_INPUT)
    expect(a.scChainage - a.tsChainage).toBeCloseTo(SAMPLE_INPUT.spiralLength, 2)
  })

  it('places ST exactly Ls after CS', () => {
    const a = computeSpiralAlignment(SAMPLE_INPUT)
    expect(a.stChainage - a.csChainage).toBeCloseTo(SAMPLE_INPUT.spiralLength, 2)
  })

  it('places CS exactly Lc after SC', () => {
    const a = computeSpiralAlignment(SAMPLE_INPUT)
    expect(a.csChainage - a.scChainage).toBeCloseTo(a.Lc, 2)
  })

  it('totalLength = 2·Ls + Lc', () => {
    const a = computeSpiralAlignment(SAMPLE_INPUT)
    expect(a.totalLength).toBeCloseTo(2 * SAMPLE_INPUT.spiralLength + a.Lc, 2)
  })

  it('stChainage - tsChainage = totalLength', () => {
    const a = computeSpiralAlignment(SAMPLE_INPUT)
    expect(a.stChainage - a.tsChainage).toBeCloseTo(a.totalLength, 2)
  })
})

describe('computeSpiralAlignment — geometry', () => {
  it('T = k + (R + p)·tan(Δ/2)', () => {
    const a = computeSpiralAlignment(SAMPLE_INPUT)
    const expectedT = a.k + (SAMPLE_INPUT.radius + a.p) * Math.tan(a.deltaRad / 2)
    expect(a.T).toBeCloseTo(expectedT, 2)
  })

  it('Lc = R·(Δ - 2θs)', () => {
    const a = computeSpiralAlignment(SAMPLE_INPUT)
    const expectedLc = SAMPLE_INPUT.radius * (a.deltaRad - 2 * a.thetaSRad)
    expect(a.Lc).toBeCloseTo(expectedLc, 2)
  })

  it('θs = Ls / (2R)', () => {
    const a = computeSpiralAlignment(SAMPLE_INPUT)
    const expectedTheta = SAMPLE_INPUT.spiralLength / (2 * SAMPLE_INPUT.radius)
    expect(a.thetaSRad).toBeCloseTo(expectedTheta, 6)
  })

  it('produces positive T, Lc, totalLength', () => {
    const a = computeSpiralAlignment(SAMPLE_INPUT)
    expect(a.T).toBeGreaterThan(0)
    expect(a.Lc).toBeGreaterThan(0)
    expect(a.totalLength).toBeGreaterThan(0)
  })

  it('reports world coordinates when PI coords are supplied', () => {
    const a = computeSpiralAlignment({
      ...SAMPLE_INPUT,
      piEasting: 5000,
      piNorthing: 6000,
      approachBearingDeg: 90, // East
    })
    expect(a.tsCoord).not.toBeNull()
    expect(a.scCoord).not.toBeNull()
    expect(a.csCoord).not.toBeNull()
    expect(a.stCoord).not.toBeNull()
    // TS is behind PI along approach tangent
    // Approach bearing 90° = East, so TS is WEST of PI
    expect(a.tsCoord!.easting).toBeLessThan(5000)
    expect(a.tsCoord!.northing).toBeCloseTo(6000, 1)
  })

  it('returns null coords when PI coords are not supplied', () => {
    const a = computeSpiralAlignment(SAMPLE_INPUT)
    expect(a.tsCoord).toBeNull()
    expect(a.scCoord).toBeNull()
    expect(a.csCoord).toBeNull()
    expect(a.stCoord).toBeNull()
    expect(a.piCoord).toBeNull()
  })
})

describe('computeSpiralAlignment — error handling', () => {
  it('throws on non-positive radius', () => {
    expect(() =>
