/**
 * Deformation Monitoring Engine — repeat-epoch comparison + alerting
 *
 * THE PROBLEM
 * -----------
 * For dam monitoring, landslide monitoring, and repeat-epoch boundary work,
 * a surveyor needs to compare coordinates from different observation epochs
 * and determine whether a monument has ACTUALLY MOVED — vs. just drifted
 * due to tectonic plate motion or measurement noise.
 *
 * Doing this by hand in Excel across months of readings is exactly the kind
 * of tedious, error-prone work an engineer will pay to never do again. This
 * module automates it.
 *
 * WHAT IT DOES
 * ------------
 * 1. Takes two (or more) adjustment results from different epochs
 * 2. Propagates both to a common epoch (using the epoch manager — plate
 *    velocity propagation) so tectonic drift is removed
 * 3. Computes the deformation vector (dE, dN, dH) per monument
 * 4. Runs a statistical significance test (is the movement real, or just
 *    measurement noise at the monument's accuracy level?)
 * 5. Flags monuments that have moved beyond the project's tolerance
 * 6. Produces a time-series analysis (trend, velocity, acceleration) when
 *    multiple epochs are available
 *
 * USAGE
 * -----
 *   import { compareEpochs, analyzeTimeSeries } from '@/lib/survey/deformationMonitoring'
 *
 *   const report = compareEpochs({
 *     baseline: { epoch: 2024.0, monuments: [...] },
 *     current: { epoch: 2025.5, monuments: [...] },
 *     tolerance: { horizontal: 0.005, vertical: 0.003 }, // 5mm H, 3mm V
 *     confidenceLevel: 0.95,
 *   })
 *
 *   if (report.alerts.length > 0) {
 *     // "Monument DM-07 has moved 8.2mm north (exceeds 5mm tolerance)."
 *   }
 */

import {
  propagateToEpoch,
  type EpochCoordinate,
  type ReferenceFrame,
} from '@/lib/geo/epochManager'
import { propagateToEpochRigorous } from '@/lib/geo/epochManagerRigorous'

// ─── Types ──────────────────────────────────────────────────────────────────

export interface MonumentObservation {
  /** Monument ID (e.g., 'DM-07' for Dam Monument 7) */
  monumentId: string
  /** Latitude (WGS84 degrees) */
  latitude: number
  /** Longitude (WGS84 degrees) */
  longitude: number
  /** Ellipsoidal height (meters) */
  height: number
  /** Reference frame */
  frame: ReferenceFrame
  /** Decimal year epoch (e.g., 2024.5 = July 2024) */
  epoch: number
  /** Standard deviation in East (meters) */
  sigmaE?: number
  /** Standard deviation in North (meters) */
  sigmaN?: number
  /** Standard deviation in Height (meters) */
  sigmaH?: number
  /** Covariance E-N (meters²) */
  sigmaEN?: number
}

export interface EpochSet {
  /** Epoch label (e.g., 'Baseline 2024-01', 'Q2 2025') */
  label: string
  /** Decimal year */
  epoch: number
  /** Monument observations for this epoch */
  monuments: MonumentObservation[]
}

export interface DeformationVector {
  monumentId: string
  /** Displacement East (meters) — positive = eastward movement */
  deltaE: number
  /** Displacement North (meters) — positive = northward movement */
  deltaN: number
  /** Displacement Up (meters) — positive = uplift */
  deltaH: number
  /** Horizontal displacement magnitude (meters) */
  horizontalDisplacement: number
  /** Bearing of movement (degrees, 0=N, 90=E) */
  bearing: number
  /** Whether the movement is statistically significant */
  isSignificant: boolean
  /** Whether the movement exceeds the tolerance */
  exceedsTolerance: boolean
  /** The statistical test result (if sigma values were available) */
  significance?: {
    testStatistic: number
    criticalValue: number
    passed: boolean
    interpretation: string
  }
}

export interface DeformationTolerance {
  /** Horizontal movement tolerance (meters). Default: 0.005 (5mm) */
  horizontal?: number
  /** Vertical movement tolerance (meters). Default: 0.003 (3mm) */
  vertical?: number
}

export interface DeformationAlert {
  monumentId: string
  severity: 'info' | 'warning' | 'critical'
  message: string
  /** Movement magnitude in mm */
  magnitudeMm: number
  /** Direction of movement */
  direction: string
}

export interface DeformationReport {
  /** Per-monument deformation vectors */
  vectors: DeformationVector[]

  /** Monuments that have moved beyond tolerance */
  alerts: DeformationAlert[]

  /** Monuments that are stable (within tolerance) */
  stable: string[]

  /** Monuments present in baseline but missing in current epoch */
  missingMonuments: string[]

  /** Monuments present in current but not in baseline (new monuments) */
  newMonuments: string[]

  /** Epochs compared */
  baselineEpoch: number
  currentEpoch: number
  commonEpoch: number

  /** Tolerances used */
  tolerance: Required<DeformationTolerance>

  /** Overall verdict */
  verdict: 'STABLE' | 'DEFORMING' | 'INCONCLUSIVE'
  /** Human-readable summary */
  summary: string

  /** Timestamp */
  timestamp: string
}

// ─── Time-Series Types ──────────────────────────────────────────────────────

export interface TimeSeriesPoint {
  epoch: number
  /** Position at this epoch (after propagation to common frame) */
  latitude: number
  longitude: number
  height: number
  /** Displacement from the first epoch (meters) */
  deltaE: number
  deltaN: number
  deltaH: number
  horizontalDisplacement: number
}

export interface TimeSeriesAnalysis {
  monumentId: string
  /** All epochs in the series */
  points: TimeSeriesPoint[]

  /** Linear trend (velocity) — meters per year */
  velocityE: number
  velocityN: number
  velocityH: number
  velocityHorizontal: number
  velocityBearing: number

  /** Acceleration (change in velocity) — meters per year² */
  accelerationHorizontal: number

  /** Whether the trend is statistically significant */
  trendSignificant: boolean

  /** R² of the linear fit (0-1) */
  rSquared: number

  /** Projected position 1 year from the last epoch */
  projectedDeltaE: number
  projectedDeltaN: number
  projectedDeltaH: number
  projectedHorizontalDisplacement: number

  /** Whether the projected movement will exceed tolerance */
  projectedExceedsTolerance: boolean

  /** Interpretation for display */
  interpretation: string
}

// ─── Main: Compare Two Epochs ───────────────────────────────────────────────

/**
 * Compare monument positions between two epochs and detect deformation.
 *
 * This is the core function for dam/boundary monitoring. It:
 *   1. Matches monuments by ID between the two epochs
 *   2. Propagates both to a common epoch (removing tectonic plate drift)
 *   3. Computes the deformation vector per monument
 *   4. Runs a statistical significance test (if accuracy data available)
 *   5. Flags monuments that exceed tolerance
 *
 * @returns DeformationReport with per-monument vectors + alerts
 */
export function compareEpochs(
  baseline: EpochSet,
  current: EpochSet,
  tolerance: DeformationTolerance = {},
  confidenceLevel: number = 0.95,
): DeformationReport {
  const tolH = tolerance.horizontal ?? 0.005  // 5mm default
  const tolV = tolerance.vertical ?? 0.003    // 3mm default
  const commonEpoch = Math.max(baseline.epoch, current.epoch)

  // Build lookup maps
  const baselineMap = new Map<string, MonumentObservation>()
  for (const m of baseline.monuments) {
    baselineMap.set(m.monumentId, m)
  }

  const currentMap = new Map<string, MonumentObservation>()
  for (const m of current.monuments) {
    currentMap.set(m.monumentId, m)
  }

  // Find common, missing, and new monuments
  const commonIds = [...baselineMap.keys()].filter(id => currentMap.has(id))
  const missingIds = [...baselineMap.keys()].filter(id => !currentMap.has(id))
  const newIds = [...currentMap.keys()].filter(id => !baselineMap.has(id))

  const vectors: DeformationVector[] = []
  const alerts: DeformationAlert[] = []
  const stable: string[] = []

  for (const id of commonIds) {
    const baseMon = baselineMap.get(id)!
    const currMon = currentMap.get(id)!

    // Propagate both to the common epoch (remove tectonic drift)
    // Use the RIGOROUS Rodrigues' rotation formula (no linearization error)
    // — critical for dam monitoring where sub-mm precision is needed.
    const baseProp = propagateToEpochRigorous(
      {
        latitude: baseMon.latitude,
        longitude: baseMon.longitude,
        height: baseMon.height,
        frame: baseMon.frame,
        epoch: baseMon.epoch,
      },
      commonEpoch,
    )

    const currProp = propagateToEpochRigorous(
      {
        latitude: currMon.latitude,
        longitude: currMon.longitude,
        height: currMon.height,
        frame: currMon.frame,
        epoch: currMon.epoch,
      },
      commonEpoch,
    )

    // Compute deformation vector
    // Convert lat/lon differences to meters (local ENU approximation)
    const lat0 = baseProp.latitude * Math.PI / 180
    const cosLat = Math.cos(lat0)
    const R = 6371000 // Earth radius in meters

    const deltaLat = currProp.latitude - baseProp.latitude
    const deltaLon = currProp.longitude - baseProp.longitude
    const deltaH = currProp.height - baseProp.height

    const deltaN = deltaLat * R * Math.PI / 180
    const deltaE = deltaLon * R * Math.PI / 180 * cosLat
    const horizontalDisplacement = Math.sqrt(deltaE ** 2 + deltaN ** 2)
    const bearing = (Math.atan2(deltaE, deltaN) * 180 / Math.PI + 360) % 360

    // Statistical significance test (if sigma values available)
    let significance: DeformationVector['significance']
    let isSignificant = false

    if (baseMon.sigmaE !== undefined && currMon.sigmaE !== undefined &&
        baseMon.sigmaN !== undefined && currMon.sigmaN !== undefined) {
      // Combined standard deviation (error propagation: σ_diff = √(σ1² + σ2²))
      const sigmaE_combined = Math.sqrt(baseMon.sigmaE ** 2 + currMon.sigmaE ** 2)
      const sigmaN_combined = Math.sqrt(baseMon.sigmaN ** 2 + currMon.sigmaN ** 2)

      // Test statistic: horizontal displacement / combined sigma
      const sigmaH_combined = Math.sqrt(sigmaE_combined ** 2 + sigmaN_combined ** 2)
      const testStatistic = sigmaH_combined > 0 ? horizontalDisplacement / sigmaH_combined : 0

      // Critical value: for 2D, 95% confidence → 2.45 (chi-square 2D)
      const criticalValue = confidenceLevel === 0.99 ? 3.03 : 2.45
      isSignificant = testStatistic > criticalValue

      significance = {
        testStatistic,
        criticalValue,
        passed: !isSignificant,
        interpretation: isSignificant
          ? `Movement is statistically significant at ${(confidenceLevel * 100).toFixed(0)}% confidence (test stat ${testStatistic.toFixed(2)} > ${criticalValue}). This is real movement, not measurement noise.`
          : `Movement is NOT statistically significant at ${(confidenceLevel * 100).toFixed(0)}% confidence (test stat ${testStatistic.toFixed(2)} ≤ ${criticalValue}). Likely measurement noise.`,
      }
    }

    const exceedsTolerance = horizontalDisplacement > tolH || Math.abs(deltaH) > tolV

    const vector: DeformationVector = {
      monumentId: id,
      deltaE,
      deltaN,
      deltaH,
      horizontalDisplacement,
      bearing,
      isSignificant,
      exceedsTolerance,
      significance,
    }
    vectors.push(vector)

    // Generate alert if exceeds tolerance AND is significant (or no sigma data)
    if (exceedsTolerance && (isSignificant || !significance)) {
      const severity = horizontalDisplacement > tolH * 3 || Math.abs(deltaH) > tolV * 3
        ? 'critical'
        : 'warning'

      const directionStr = formatBearing(bearing)
      const magMm = horizontalDisplacement * 1000

      alerts.push({
        monumentId: id,
        severity,
        message: `${id} has moved ${magMm.toFixed(1)}mm ${directionStr}` +
          (Math.abs(deltaH) > tolV ? ` and ${(deltaH * 1000).toFixed(1)}mm ${deltaH > 0 ? 'up' : 'down'}` : '') +
          ` (tolerance: ${tolH * 1000}mm H / ${tolV * 1000}mm V).` +
          (significance ? ` ${significance.interpretation}` : ''),
        magnitudeMm: magMm,
        direction: directionStr,
      })
    } else {
      stable.push(id)
    }
  }

  // Overall verdict
  let verdict: 'STABLE' | 'DEFORMING' | 'INCONCLUSIVE'
  let summary: string

  if (vectors.length === 0) {
    verdict = 'INCONCLUSIVE'
    summary = 'No common monuments between epochs. Cannot compare.'
  } else if (alerts.length === 0) {
    verdict = 'STABLE'
    summary = `All ${stable.length} monuments stable within tolerance (±${tolH * 1000}mm H / ±${tolV * 1000}mm V) between ${baseline.label} and ${current.label}.`
  } else {
    verdict = 'DEFORMING'
    const criticalCount = alerts.filter(a => a.severity === 'critical').length
    summary = `${alerts.length} monument(s) exceeded tolerance between ${baseline.label} and ${current.label}.` +
      (criticalCount > 0 ? ` ${criticalCount} CRITICAL.` : '') +
      ` Affected: ${alerts.map(a => a.monumentId).join(', ')}.`
  }

  return {
    vectors,
    alerts,
    stable,
    missingMonuments: missingIds,
    newMonuments: newIds,
    baselineEpoch: baseline.epoch,
    currentEpoch: current.epoch,
    commonEpoch,
    tolerance: { horizontal: tolH, vertical: tolV },
    verdict,
    summary,
    timestamp: new Date().toISOString(),
  }
}

// ─── Time-Series Analysis ───────────────────────────────────────────────────

/**
 * Analyze a time series of monument positions across multiple epochs.
 *
 * Computes:
 *   - Linear trend (velocity) in E, N, H — meters per year
 *   - Acceleration (change in velocity)
 *   - R² goodness of fit
 *   - 1-year projection
 *   - Whether the projection exceeds tolerance
 *
 * @param epochs - Array of EpochSets (at least 2, ideally 3+ for trend)
 * @param monumentId - Which monument to analyze
 * @param tolerance - Movement tolerance for projection check
 */
export function analyzeTimeSeries(
  epochs: EpochSet[],
  monumentId: string,
  tolerance: DeformationTolerance = {},
): TimeSeriesAnalysis {
  const tolH = tolerance.horizontal ?? 0.005
  const tolV = tolerance.vertical ?? 0.003

  // Collect all observations of this monument across epochs
  const observations: TimeSeriesPoint[] = []
  let firstObs: { lat: number; lon: number; h: number } | null = null

  // Sort epochs chronologically
  const sortedEpochs = [...epochs].sort((a, b) => a.epoch - b.epoch)

  for (const epochSet of sortedEpochs) {
    const mon = epochSet.monuments.find(m => m.monumentId === monumentId)
    if (!mon) continue

    // Propagate to a common reference (the first epoch)
    if (!firstObs) {
      firstObs = { lat: mon.latitude, lon: mon.longitude, h: mon.height }
    }

    const commonEpoch = sortedEpochs[0].epoch
    const prop = propagateToEpochRigorous(
      {
        latitude: mon.latitude,
        longitude: mon.longitude,
        height: mon.height,
        frame: mon.frame,
        epoch: mon.epoch,
      },
      commonEpoch,
    )

    // Compute displacement from first observation
    const lat0 = firstObs.lat * Math.PI / 180
    const cosLat = Math.cos(lat0)
    const R = 6371000

    const deltaLat = prop.latitude - firstObs.lat
    const deltaLon = prop.longitude - firstObs.lon
    const deltaH = prop.height - firstObs.h

    const deltaN = deltaLat * R * Math.PI / 180
    const deltaE = deltaLon * R * Math.PI / 180 * cosLat
    const horizontalDisplacement = Math.sqrt(deltaE ** 2 + deltaN ** 2)

    observations.push({
      epoch: mon.epoch,
      latitude: prop.latitude,
      longitude: prop.longitude,
      height: prop.height,
      deltaE,
      deltaN,
      deltaH,
      horizontalDisplacement,
    })
  }

  if (observations.length < 2) {
    return {
      monumentId,
      points: observations,
      velocityE: 0,
      velocityN: 0,
      velocityH: 0,
      velocityHorizontal: 0,
      velocityBearing: 0,
      accelerationHorizontal: 0,
      trendSignificant: false,
      rSquared: 0,
      projectedDeltaE: 0,
      projectedDeltaN: 0,
      projectedDeltaH: 0,
      projectedHorizontalDisplacement: 0,
      projectedExceedsTolerance: false,
      interpretation: 'Insufficient data for trend analysis (need ≥2 epochs).',
    }
  }

  // Linear regression: displacement vs time
  // y = a + b×t, where t = epoch, y = displacement
  const t0 = observations[0].epoch
  const tValues = observations.map(o => o.epoch - t0) // years from first epoch
  const eValues = observations.map(o => o.deltaE)
  const nValues = observations.map(o => o.deltaN)
  const hValues = observations.map(o => o.deltaH)
  const hDispValues = observations.map(o => o.horizontalDisplacement)

  const { slope: velE, r2: r2E } = linearRegression(tValues, eValues)
  const { slope: velN, r2: r2N } = linearRegression(tValues, nValues)
  const { slope: velH, r2: r2H } = linearRegression(tValues, hValues)
  const { slope: velHdisp, r2: r2Hdisp } = linearRegression(tValues, hDispValues)

  const velocityHorizontal = Math.sqrt(velE ** 2 + velN ** 2)
  const velocityBearing = (Math.atan2(velE, velN) * 180 / Math.PI + 360) % 360

  // Acceleration: difference in velocity between first and second half
  let accelerationHorizontal = 0
  if (observations.length >= 4) {
    const midIdx = Math.floor(observations.length / 2)
    const firstHalf = observations.slice(0, midIdx + 1)
    const secondHalf = observations.slice(midIdx)

    const t1 = firstHalf.map(o => o.epoch - t0)
    const h1 = firstHalf.map(o => o.horizontalDisplacement)
    const t2 = secondHalf.map(o => o.epoch - t0)
    const h2 = secondHalf.map(o => o.horizontalDisplacement)

    const vel1 = linearRegression(t1, h1).slope
    const vel2 = linearRegression(t2, h2).slope

    const dt = (secondHalf[secondHalf.length - 1].epoch - firstHalf[0].epoch) / 2
    if (dt > 0) {
      accelerationHorizontal = (vel2 - vel1) / dt
    }
  }

  // R² for horizontal displacement
  const rSquared = r2Hdisp

  // Trend significance: R² > 0.7 AND velocity > tolerance/year
  const trendSignificant = rSquared > 0.7 && velocityHorizontal > tolH

  // Project 1 year from last epoch
  const lastT = tValues[tValues.length - 1]
  const projectedT = lastT + 1.0
  const projectedDeltaE = velE * projectedT
  const projectedDeltaN = velN * projectedT
  const projectedDeltaH = velH * projectedT
  const projectedHorizontalDisplacement = Math.sqrt(projectedDeltaE ** 2 + projectedDeltaN ** 2)
  const projectedExceedsTolerance = projectedHorizontalDisplacement > tolH || Math.abs(projectedDeltaH) > tolV

  // Interpretation
  let interpretation: string
  if (velocityHorizontal < tolH) {
    interpretation = `Stable: velocity ${(velocityHorizontal * 1000).toFixed(1)}mm/yr is within tolerance. No action needed.`
  } else if (trendSignificant) {
    interpretation = `DEFORMING: velocity ${(velocityHorizontal * 1000).toFixed(1)}mm/yr ${formatBearing(velocityBearing)} (R²=${rSquared.toFixed(2)}).` +
      (projectedExceedsTolerance ? ` Projected to exceed tolerance within 1 year. Investigate.` : ` Trend is significant but projection is within tolerance.`)
  } else {
    interpretation = `Marginal: velocity ${(velocityHorizontal * 1000).toFixed(1)}mm/yr but R²=${rSquared.toFixed(2)} indicates high variability. More epochs needed to confirm trend.`
  }

  return {
    monumentId,
    points: observations,
    velocityE: velE,
    velocityN: velN,
    velocityH: velH,
    velocityHorizontal,
    velocityBearing,
    accelerationHorizontal,
    trendSignificant,
    rSquared,
    projectedDeltaE,
    projectedDeltaN,
    projectedDeltaH,
    projectedHorizontalDisplacement,
    projectedExceedsTolerance,
    interpretation,
  }
}

// ─── Helpers ────────────────────────────────────────────────────────────────

/**
 * Simple linear regression: y = a + b×x
 * Returns slope (b), intercept (a), and R².
 */
function linearRegression(x: number[], y: number[]): { slope: number; intercept: number; r2: number } {
  const n = x.length
  if (n < 2) return { slope: 0, intercept: 0, r2: 0 }

  const sumX = x.reduce((s, v) => s + v, 0)
  const sumY = y.reduce((s, v) => s + v, 0)
  const sumXY = x.reduce((s, v, i) => s + v * y[i], 0)
  const sumX2 = x.reduce((s, v) => s + v * v, 0)
  const sumY2 = y.reduce((s, v) => s + v * v, 0)

  const denom = n * sumX2 - sumX * sumX
  if (Math.abs(denom) < 1e-12) return { slope: 0, intercept: y[0], r2: 0 }

  const slope = (n * sumXY - sumX * sumY) / denom
  const intercept = (sumY - slope * sumX) / n

  // R²
  const meanY = sumY / n
  const ssTot = y.reduce((s, v) => s + (v - meanY) ** 2, 0)
  const ssRes = y.reduce((s, v, i) => s + (v - (intercept + slope * x[i])) ** 2, 0)
  const r2 = ssTot > 0 ? 1 - ssRes / ssTot : 0

  return { slope, intercept, r2 }
}

/**
 * Format a bearing in degrees as a compass direction.
 * e.g., 45° → "NE", 180° → "S", 270° → "W"
 */
function formatBearing(bearing: number): string {
  const dirs = ['N', 'NNE', 'NE', 'ENE', 'E', 'ESE', 'SE', 'SSE',
                'S', 'SSW', 'SW', 'WSW', 'W', 'WNW', 'NW', 'NNW']
  const idx = Math.round(bearing / 22.5) % 16
  return `${dirs[idx]} (${bearing.toFixed(1)}°)`
}

// ─── Display Helpers ────────────────────────────────────────────────────────

/**
 * Get the verdict color for deformation status.
 */
export function getDeformationVerdictColor(verdict: 'STABLE' | 'DEFORMING' | 'INCONCLUSIVE'): string {
  switch (verdict) {
    case 'STABLE': return 'green'
    case 'DEFORMING': return 'red'
    case 'INCONCLUSIVE': return 'yellow'
    default: return 'gray'
  }
}

/**
 * Get the alert severity color.
 */
export function getAlertSeverityColor(severity: 'info' | 'warning' | 'critical'): string {
  switch (severity) {
    case 'info': return 'blue'
    case 'warning': return 'yellow'
    case 'critical': return 'red'
    default: return 'gray'
  }
}

/**
 * Format a deformation vector for display.
 */
export function formatDeformationVector(v: DeformationVector): string {
  const parts: string[] = []
  parts.push(`dE=${(v.deltaE * 1000).toFixed(1)}mm`)
  parts.push(`dN=${(v.deltaN * 1000).toFixed(1)}mm`)
  if (v.deltaH !== 0) {
    parts.push(`dH=${(v.deltaH * 1000).toFixed(1)}mm`)
  }
  parts.push(`|H|=${(v.horizontalDisplacement * 1000).toFixed(1)}mm`)
  parts.push(formatBearing(v.bearing))
  if (v.significance) {
    parts.push(v.isSignificant ? 'SIGNIFICANT' : 'not significant')
  }
  if (v.exceedsTolerance) {
    parts.push('⚠ EXCEEDS TOLERANCE')
  }
  return parts.join('  ')
}

/**
 * Benchmark Sheet Generator
 *
 * Generates a benchmark schedule / control point summary sheet from
 * level network adjustment results. Used for Kenya survey submissions
 * to document known control points and their adjusted RLs.
 */

import {
  LevelAdjustmentResult,
  LevelControlPoint,
  LevelObservation,
  AdjustedLevel,
  LEVEL_ORDER_LIMITS,
} from './digitalLevelTypes'

// ─── Types ───────────────────────────────────────────────────────────────────

export interface BenchmarkRow {
  pointId: string
  description?: string
  rlOriginal?: number
  rlAdjusted: number
  sigmaRL: number
  isFixed: boolean
  order?: string
}

export interface BenchmarkSheet {
  projectName?: string
  surveyor?: string
  date?: string
  order: string
  instrument?: string
  staff?: string
  totalDistanceKm: number
  misclosureMm: number
  allowableMisclosureMm: number
  passed: boolean
  referenceVariance: number
  degreesOfFreedom: number
  benchmarks: BenchmarkRow[]
  remarks?: string
}

// ─── Sheet Generation ────────────────────────────────────────────────────────

/**
 * Generate a benchmark sheet from level network adjustment results.
 *
 * @param adjustmentResult - Output from adjustLevelNetwork()
 * @param controlPoints - Original control point data (for descriptions, original RLs)
 * @param options - Sheet metadata
 */
export function generateBenchmarkSheet(
  adjustmentResult: LevelAdjustmentResult,
  controlPoints: LevelControlPoint[],
  options?: {
    projectName?: string
    surveyor?: string
    date?: string
    instrument?: string
    staff?: string
    remarks?: string
  }
): BenchmarkSheet {
  // Build CP map for descriptions and original RLs
  const cpMap = new Map<string, LevelControlPoint>()
  for (const cp of controlPoints) {
    cpMap.set(cp.id, cp)
  }

  // Build benchmark rows
  const benchmarks: BenchmarkRow[] = adjustmentResult.adjustedLevels.map(function(level: AdjustedLevel) {
    const cp = cpMap.get(level.id)
    return {
      pointId: level.id,
      description: cp ? cp.id : undefined,
      rlOriginal: cp ? cp.rl : undefined,
      rlAdjusted: level.rl,
      sigmaRL: level.sigmaRL,
      isFixed: cp ? cp.isFixed : false,
      order: adjustmentResult.order,
    }
  })

  // Sort: fixed points first, then alphabetical
  benchmarks.sort(function(a, b) {
    if (a.isFixed && !b.isFixed) return -1
    if (!a.isFixed && b.isFixed) return 1
    return a.pointId.localeCompare(b.pointId)
  })

  const orderInfo = LEVEL_ORDER_LIMITS[adjustmentResult.order] || LEVEL_ORDER_LIMITS['fourth']

  return {
    projectName: options?.projectName,
    surveyor: options?.surveyor,
    date: options?.date,
    order: adjustmentResult.order,
    instrument: options?.instrument,
    staff: options?.staff,
    totalDistanceKm: adjustmentResult.totalDistance,
    misclosureMm: adjustmentResult.misclosure,
    allowableMisclosureMm: adjustmentResult.allowableMisclosure,
    passed: adjustmentResult.passed,
    referenceVariance: adjustmentResult.referenceVariance,
    degreesOfFreedom: adjustmentResult.degreesOfFreedom,
    benchmarks,
    remarks: options?.remarks,
  }
}

/**
 * Format a benchmark sheet as plain text (for field notes or CSV export).
 */
export function formatBenchmarkSheetAsText(sheet: BenchmarkSheet): string {
  const lines: string[] = []

  lines.push('BENCHMARK SHEET / CONTROL POINT SUMMARY')
  lines.push('========================================')
  if (sheet.projectName) lines.push('Project: ' + sheet.projectName)
  if (sheet.surveyor) lines.push('Surveyor: ' + sheet.surveyor)
  if (sheet.date) lines.push('Date: ' + sheet.date)
  if (sheet.instrument) lines.push('Instrument: ' + sheet.instrument)
  if (sheet.staff) lines.push('Staff: ' + sheet.staff)
  lines.push('Order: ' + sheet.order + ' (' + (LEVEL_ORDER_LIMITS[sheet.order]?.label || '') + ')')
  lines.push('Total Distance: ' + sheet.totalDistanceKm.toFixed(3) + ' km')
  lines.push('Misclosure: ' + sheet.misclosureMm.toFixed(1) + ' mm')
  lines.push('Allowable: ' + sheet.allowableMisclosureMm.toFixed(1) + ' mm')
  lines.push('Passed: ' + (sheet.passed ? 'YES' : 'NO'))
  lines.push('Reference Variance: ' + sheet.referenceVariance.toFixed(6))
  lines.push('Degrees of Freedom: ' + sheet.degreesOfFreedom)
  lines.push('')

  // Table header
  lines.push('Point        Fixed   RL Orig     RL Adjusted  Sigma RL (m)')
  lines.push('-----------  ------  ----------  -----------  ------------')

  for (const bm of sheet.benchmarks) {
    const fixed = bm.isFixed ? 'Yes' : 'No'
    const orig = bm.rlOriginal !== undefined ? bm.rlOriginal.toFixed(4) : '---'
    const adj = bm.rlAdjusted.toFixed(4)
    const sigma = bm.sigmaRL.toFixed(6)
    lines.push(
      bm.pointId.padEnd(12) + ' ' +
      fixed.padEnd(7) + ' ' +
      orig.padEnd(11) + ' ' +
      adj.padEnd(12) + ' ' +
      sigma
    )
  }

  if (sheet.remarks) {
    lines.push('')
    lines.push('REMARKS: ' + sheet.remarks)
  }

  return lines.join('\n')
}

/**
 * Validate whether a benchmark sheet meets Kenya survey standards
 * for the declared order.
 */
export function validateBenchmarkSheet(sheet: BenchmarkSheet): {
  valid: boolean
  errors: string[]
  warnings: string[]
} {
  const errors: string[] = []
  const warnings: string[] = []

  if (sheet.benchmarks.length === 0) {
    errors.push('No benchmark points in sheet')
  }

  const fixedCount = sheet.benchmarks.filter(function(b) { return b.isFixed }).length
  if (fixedCount === 0) {
    errors.push('At least one fixed control point is required')
  }

  if (!sheet.passed) {
    errors.push(
      'Misclosure (' + sheet.misclosureMm.toFixed(1) + ' mm) exceeds allowable limit (' +
      sheet.allowableMisclosureMm.toFixed(1) + ' mm) for ' + sheet.order + ' order'
    )
  }

  // Check sigma RL for adjusted points
  for (const bm of sheet.benchmarks) {
    if (!bm.isFixed && bm.sigmaRL > 0.1) {
      warnings.push(
        'Point ' + bm.pointId + ' has large sigma RL (' +
        (bm.sigmaRL * 1000).toFixed(1) + ' mm) — check observation quality'
      )
    }
  }

  if (sheet.totalDistanceKm === 0) {
    warnings.push('Total distance is zero — verify observation distances')
  }

  return {
    valid: errors.length === 0,
    errors,
    warnings,
  }
}

// Leica DiNi 12/22 Digital Level – RAW/DAT Format Parser
// Parses measurement files exported from Leica DiNi digital levels.

import { LevelReading, LevelObservation, LevelImportResult } from './digitalLevelTypes'

/**
 * Parse Leica DiNi RAW/DAT format into level readings and observations.
 *
 * Expected format (DiNi RAW):
 *   Start-No.|  1
 *   End-No.: |99999
 *   Staff1:  |  10001
 *   Staff2:  |  10002
 *   1|BM1          |  1.65432|  25.432|BM
 *   2|TP1          |  0.87654|  30.121|
 *
 * Or DAT format (simpler):
 *   BM1,1.65432,25.432,BS
 *   TP1,0.87654,30.121,FS
 */
export function parseDiNi(content: string, filename?: string): LevelImportResult {
  const lines = content.split(/\r?\n/)
  const parseErrors: string[] = []
  const readings: LevelReading[] = []

  const metadata: LevelImportResult['metadata'] = {
    rawLineCount: lines.length,
    parseErrors: [],
  }

  let instrument = 'DiNi'
  let jobNumber = ''
  let dateStr = ''
  let staffA = ''
  let staffB = ''
  const instrumentHeight = 1.6

  // Detect format: pipe-delimited (RAW) vs comma-delimited (DAT)
  const firstDataLine = lines.find(l => {
    const t = l.trim()
    return t.length > 0 && !t.startsWith('Start') && !t.startsWith('End') &&
           !t.startsWith('Staff') && !t.startsWith('Inst') && !t.startsWith('Job') &&
           !t.startsWith('Date') && !t.startsWith('Operator') && !t.startsWith('---')
  })

  const isRawFormat = firstDataLine ? firstDataLine.includes('|') : false

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    const trimmed = line.trim()

    if (!trimmed || trimmed.startsWith('---')) continue

    // ── Metadata ────────────────────────────────────────────────
    const instMatch = trimmed.match(/Inst[^:]*:\s*\|?\s*(.+)/i)
    if (instMatch) {
      instrument = instMatch[1].replace('|', '').trim() || instrument
      metadata.instrument = instrument
      continue
    }

    const jobMatch = trimmed.match(/Job[^:]*:\s*\|?\s*(.+)/i)
    if (jobMatch) {
      jobNumber = jobMatch[1].replace('|', '').trim()
      metadata.jobNumber = jobNumber
      continue
    }

    const dateMatch = trimmed.match(/Date[^:]*:\s*\|?\s*(.+)/i)
    if (dateMatch) {
      dateStr = dateMatch[1].replace('|', '').trim()
      metadata.date = dateStr
      continue
    }

    const staff1Match = trimmed.match(/Staff\s*1[^:]*:\s*\|?\s*(.+)/i)
    if (staff1Match) {
      staffA = staff1Match[1].replace('|', '').trim()
      metadata.staffA = staffA
      continue
    }

    const staff2Match = trimmed.match(/Staff\s*2[^:]*:\s*\|?\s*(.+)/i)
    if (staff2Match) {
      staffB = staff2Match[1].replace('|', '').trim()
      metadata.staffB = staffB
      continue
    }

    const opMatch = trimmed.match(/Operator[^:]*:\s*\|?\s*(.+)/i)
    if (opMatch) {
      metadata.operator = opMatch[1].replace('|', '').trim()
      continue
    }

    // Skip header keywords
    if (/^(Start|End|Adr|Code|PtID|Rem)/i.test(trimmed)) continue

    // ── Data rows ───────────────────────────────────────────────
    if (isRawFormat) {
      const reading = parseDiNiRawRow(trimmed, instrumentHeight, i + 1)
      if (reading) {
        readings.push(reading)
      } else if (trimmed.length > 2 && !trimmed.includes(':')) {
        parseErrors.push(`Line ${i + 1}: Could not parse DiNi RAW row: "${trimmed.substring(0, 60)}"`)
      }
    } else {
      const reading = parseDiNiDatRow(trimmed, instrumentHeight, i + 1)
      if (reading) {
        readings.push(reading)
      } else if (trimmed.includes(',') && trimmed.length > 3) {
        parseErrors.push(`Line ${i + 1}: Could not parse DiNi DAT row: "${trimmed.substring(0, 60)}"`)
      }
    }
  }

  metadata.parseErrors = parseErrors

  const observations = buildDiNiObservations(readings)

  return {
    format: 'dini',
    readings,
    observations,
    metadata,
  }
}

/**
 * Parse DiNi RAW format row.
 * Format: No|Station|StaffReading|Distance|Remark
 * Example: 1|BM1          |  1.65432|  25.432|BM
 */
function parseDiNiRawRow(
  line: string,
  instrumentHeight: number,
  lineNo: number
): LevelReading | null {
  const parts = line.split('|').map(s => s.trim()).filter(s => s.length > 0)
  if (parts.length < 3) return null

  // parts[0] = number, parts[1] = station, parts[2] = reading, [3] = distance, [4] = remark
  const stationId = parts[1]
  const staffReading = parseFloat(parts[2])
  if (isNaN(staffReading)) return null

  const distance = parts.length >= 4 ? parseFloat(parts[3]) : 30
  const remark = parts.length >= 5 ? parts[4] : undefined

  let type: 'BS' | 'FS' | 'IS' = 'BS'
  if (remark) {
    const lower = remark.toLowerCase()
    if (lower.includes('fs') || lower.includes('foresight')) type = 'FS'
    else if (lower.includes('is') || lower.includes('intermediate')) type = 'IS'
  }

  return {
    stationId,
    type,
    staffReading,
    distance: isNaN(distance) ? 30 : distance,
    instrumentHeight,
    comment: remark,
  }
}

/**
 * Parse DiNi DAT format row (CSV-like).
 * Format: Station,Reading,Distance,Type
 * Example: BM1,1.65432,25.432,BS
 */
function parseDiNiDatRow(
  line: string,
  instrumentHeight: number,
  lineNo: number
): LevelReading | null {
  const parts = line.split(',').map(s => s.trim()).filter(s => s.length > 0)
  if (parts.length < 2) return null

  const stationId = parts[0]
  const staffReading = parseFloat(parts[1])
  if (isNaN(staffReading)) return null

  const distance = parts.length >= 3 ? parseFloat(parts[2]) : 30
  const typeStr = parts.length >= 4 ? parts[3].toUpperCase() : 'BS'

  let type: 'BS' | 'FS' | 'IS' = 'BS'
  if (typeStr.includes('FS') || typeStr.includes('FORESIGHT')) type = 'FS'
  else if (typeStr.includes('IS') || typeStr.includes('INTERMEDIATE')) type = 'IS'

  return {
    stationId,
    type,
    staffReading,
    distance: isNaN(distance) ? 30 : distance,
    instrumentHeight,
  }
}

/**
 * Build observations from DiNi readings (BS/FS pairs).
 */
function buildDiNiObservations(readings: LevelReading[]): LevelObservation[] {
  const observations: LevelObservation[] = []
  let bsReading: LevelReading | null = null

  for (const r of readings) {
    if (r.type === 'BS') {
      bsReading = r
    } else if (r.type === 'FS' && bsReading) {
      const heightDifference = bsReading.staffReading - r.staffReading
      const distance = (bsReading.distance + r.distance) / 2
      const distKm = distance / 1000
      const weight = distKm > 0 ? 1 / (distKm * distKm) : 1000

      observations.push({
        fromId: bsReading.stationId,
        toId: r.stationId,
        heightDifference,
        distance,
        weight,
      })
      bsReading = null
    }
  }

  return observations
}

// Leica DNA03 / DNA03-2 Digital Level – RDT Format Parser
// Parses raw measurement files exported from Leica DNA03 digital levels.

import { LevelReading, LevelObservation, LevelImportResult } from './digitalLevelTypes'

/**
 * Parse Leica DNA03 RDT format into level readings and observations.
 *
 * Expected format:
 *   Header line: starts with " DNA03" or contains "Digital Level"
 *   Instrument/Job/Staff metadata lines
 *   Measurement header: RNo Sta  RNo Sta   Ht.m  Diff.m  Comments
 *   Data rows:   1  BM1  2  TP1    1.65432  1.23456  BS to TP1
 */
export function parseDNA03(content: string, filename?: string): LevelImportResult {
  const lines = content.split(/\r?\n/)
  const parseErrors: string[] = []
  const readings: LevelReading[] = []

  const metadata: LevelImportResult['metadata'] = {
    rawLineCount: lines.length,
    parseErrors: [],
  }

  let instrument = ''
  let jobNumber = ''
  let dateStr = ''
  let staffA = ''
  let staffB = ''
  const currentInstrumentHeight = 1.6 // default

  let inDataSection = false
  const bsBuffer: LevelReading | null = null

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    const trimmed = line.trim()

    if (!trimmed || trimmed.startsWith('---')) continue

    // ── Header detection ────────────────────────────────────────
    if (trimmed.includes('DNA03') && trimmed.includes('Digital Level')) {
      // Extract instrument info from header
      const parts = trimmed.split(/\s+/)
      if (parts.length >= 1) {
        instrument = parts[0] || 'DNA03'
      }
      // Date is typically DD.MM.YYYY
      const dateMatch = trimmed.match(/(\d{2}\.\d{2}\.\d{4})/)
      if (dateMatch) dateStr = dateMatch[1]
      continue
    }

    // ── Metadata fields ─────────────────────────────────────────
    if (trimmed.toLowerCase().startsWith('inst-no:')) {
      instrument = trimmed.split(':')[1]?.trim() || instrument
      metadata.instrument = instrument
      continue
    }
    if (trimmed.toLowerCase().startsWith('job-no:')) {
      jobNumber = trimmed.split(':')[1]?.trim() || ''
      metadata.jobNumber = jobNumber
      continue
    }
    if (trimmed.toLowerCase().startsWith('staff:')) {
      const staffParts = trimmed.split(/\s+/).filter(s => s)
      if (staffParts.length >= 2) staffA = staffParts[1] || ''
      if (staffParts.length >= 3) staffB = staffParts[2] || ''
      metadata.staffA = staffA
      metadata.staffB = staffB
      continue
    }
    if (trimmed.toLowerCase().startsWith('operator:')) {
      metadata.operator = trimmed.split(':')[1]?.trim()
      continue
    }

    // ── Date line ───────────────────────────────────────────────
    if (!dateStr) {
      const dateMatch = trimmed.match(/(\d{2}\.\d{2}\.\d{4})/)
      if (dateMatch) dateStr = dateMatch[1]
    }

    // ── Data section header ─────────────────────────────────────
    if (trimmed.includes('RNo') && trimmed.includes('Sta') && (trimmed.includes('Ht') || trimmed.includes('Diff'))) {
      inDataSection = true
      continue
    }

    // ── Measurement data rows ───────────────────────────────────
    if (inDataSection) {
      const reading = parseDNAMeasurementRow(trimmed, currentInstrumentHeight, i + 1)
      if (reading) {
        readings.push(reading)
      } else if (trimmed.length > 0) {
        // Try alternative format: numeric fields
        const altReading = parseDNAAltRow(trimmed, currentInstrumentHeight, i + 1)
        if (altReading) {
          readings.push(altReading)
        } else {
          parseErrors.push(`Line ${i + 1}: Could not parse measurement: "${trimmed.substring(0, 60)}"`)
        }
      }
    }
  }

  metadata.date = dateStr
  metadata.parseErrors = parseErrors

  // Build observations from consecutive BS/FS pairs
  const observations = buildObservationsFromReadings(readings)

  return {
    format: 'dna03',
    readings,
    observations,
    metadata,
  }
}

/**
 * Parse a DNA03 measurement row.
 * Format: RNo1 Sta1 RNo2 Sta2 Ht.m Diff.m Comments
 */
function parseDNAMeasurementRow(
  line: string,
  instrumentHeight: number,
  lineNo: number
): LevelReading | null {
  // Match pattern: number station number station number number comment
  // e.g., "1  BM1  2  TP1    1.65432     1.23456     BS to TP1"
  const match = line.match(
    /^(\d+)\s+(\S+)\s+(\d+)\s+(\S+)\s+([+-]?\d*\.?\d+)\s+([+-]?\d*\.?\d+)\s*(.*)?$/
  )
  if (!match) return null

  const staffReading = parseFloat(match[5])
  const stationId = match[4]
  const rNo1 = parseInt(match[1], 10)
  const comment = (match[7] || '').trim()

  // Determine reading type from context
  let type: 'BS' | 'FS' | 'IS' = 'BS'
  if (comment.toLowerCase().includes('fs') || comment.toLowerCase().includes('foresight')) {
    type = 'FS'
  } else if (comment.toLowerCase().includes('is') || comment.toLowerCase().includes('intermediate')) {
    type = 'IS'
  }

  // Estimate distance from staff reading magnitude (DNA03 stores dist internally)
  // In real data, distance may be embedded; here we derive from staff or use a default
  const distance = estimateDistanceFromStaffReading(staffReading)

  // Parse timestamp from comment if present
  let timestamp: Date | undefined
  const timeMatch = comment.match(/(\d{2}:\d{2}:\d{2})/)
  if (timeMatch) {
    timestamp = new Date(`1970-01-01T${timeMatch[1]}`)
  }

  return {
    stationId,
    type,
    staffReading,
    distance,
    instrumentHeight,
    timestamp,
    comment: comment || undefined,
  }
}

/**
 * Parse alternative DNA03 row format (simpler numeric columns).
 * Format: StaId  Reading  Distance  [Comment]
 */
function parseDNAAltRow(
  line: string,
  instrumentHeight: number,
  lineNo: number
): LevelReading | null {
  const parts = line.split(/\s+/).filter(s => s.length > 0)
  if (parts.length < 2) return null

  const stationId = parts[0]
  const staffReading = parseFloat(parts[1])
  if (isNaN(staffReading)) return null

  const distance = parts.length >= 3 ? parseFloat(parts[2]) : estimateDistanceFromStaffReading(staffReading)
  const comment = parts.length >= 4 ? parts.slice(3).join(' ') : undefined

  let type: 'BS' | 'FS' | 'IS' = 'BS'
  if (comment) {
    const lower = comment.toLowerCase()
    if (lower.includes('fs') || lower.includes('foresight')) type = 'FS'
    else if (lower.includes('is') || lower.includes('intermediate')) type = 'IS'
  }

  return {
    stationId,
    type,
    staffReading,
    distance: isNaN(distance) ? 30 : distance,
    instrumentHeight,
    comment,
  }
}

/**
 * Estimate distance based on staff reading magnitude.
 * Digital levels read invar barcode staff – typical sight distances 20-60 m.
 * This is a fallback when distance is not explicitly recorded.
 */
function estimateDistanceFromStaffReading(staffReading: number): number {
  // Typical range 0.3 – 3.0 m on staff
  // Return a reasonable default distance
  if (staffReading < 0.5 || staffReading > 4.0) return 30 // unusual reading
  return 30 // default 30 m sight distance
}

/**
 * Build LevelObservation array from a sequence of LevelReadings.
 * Consecutive BS/FS pairs become height difference observations.
 */
function buildObservationsFromReadings(readings: LevelReading[]): LevelObservation[] {
  const observations: LevelObservation[] = []
  let bsReading: LevelReading | null = null

  for (const r of readings) {
    if (r.type === 'BS') {
      bsReading = r
    } else if (r.type === 'FS' && bsReading) {
      const heightDifference = bsReading.staffReading - r.staffReading
      const distance = (bsReading.distance + r.distance) / 2
      const distKm = distance / 1000
      const weight = distKm > 0 ? 1 / (distKm * distKm) : 1000

      observations.push({
        fromId: bsReading.stationId,
        toId: r.stationId,
        heightDifference,
        distance,
        weight,
      })
      bsReading = null
    }
    // IS readings don't form observations directly
  }

  return observations
}

// Topcon DL Digital Level – Format Parser
// Parses measurement files exported from Topcon DL-101/102/103 digital levels.

import { LevelReading, LevelObservation, LevelImportResult } from './digitalLevelTypes'

/**
 * Parse Topcon DL format into level readings and observations.
 *
 * Topcon DL exports typically have:
 *   Job header lines with instrument/model info
 *   Data lines:  PtID  BM/TP flag  Reading  Distance  Comment
 *
 * Format variants:
 *   Space-separated: "BM1  BM  1.65432  25.4  BS"
 *   Or fixed-width columns from DL-102/DL-103
 */
export function parseTopconDL(content: string, filename?: string): LevelImportResult {
  const lines = content.split(/\r?\n/)
  const parseErrors: string[] = []
  const readings: LevelReading[] = []

  const metadata: LevelImportResult['metadata'] = {
    rawLineCount: lines.length,
    parseErrors: [],
  }

  let instrument = 'Topcon-DL'
  let jobNumber = ''
  let dateStr = ''
  const instrumentHeight = 1.6

  let inDataSection = false

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    const trimmed = line.trim()

    if (!trimmed || trimmed.startsWith('---')) continue

    // ── Header detection ────────────────────────────────────────
    if (trimmed.match(/topcon/i) && trimmed.match(/dl/i)) {
      metadata.instrument = trimmed.split(/\s+/)[0] || 'Topcon-DL'
      instrument = metadata.instrument
      continue
    }

    // Model line like "DL-102" or "DL103"
    if (trimmed.match(/^DL-\d{2,3}$/) || trimmed.match(/^DL\d{2,3}$/)) {
      instrument = trimmed
      metadata.instrument = instrument
      continue
    }

    // ── Metadata fields ─────────────────────────────────────────
    const jobMatch = trimmed.match(/job\s*[^:]*:\s*(.+)/i)
    if (jobMatch) {
      jobNumber = jobMatch[1].trim()
      metadata.jobNumber = jobNumber
      continue
    }

    const dateMatch = trimmed.match(/date\s*[^:]*:\s*(.+)/i)
    if (dateMatch) {
      dateStr = dateMatch[1].trim()
      metadata.date = dateStr
      continue
    }

    const opMatch = trimmed.match(/operator\s*[^:]*:\s*(.+)/i)
    if (opMatch) {
      metadata.operator = opMatch[1].trim()
      continue
    }

    // ── Column header detection ─────────────────────────────────
    if (trimmed.match(/(point|station|ptid|reading|dist)/i) && !trimmed.match(/^\d/)) {
      inDataSection = true
      continue
    }

    // ── Data rows ───────────────────────────────────────────────
    // Topcon DL data: starts with station ID (non-numeric or numeric+letter combo)
    if (trimmed.match(/^[\w-]+\s/) || trimmed.match(/^[\w-]+\t/)) {
      inDataSection = true
    }

    if (inDataSection) {
      const reading = parseTopconDataRow(trimmed, instrumentHeight, i + 1)
      if (reading) {
        readings.push(reading)
      } else if (trimmed.length > 2 && !trimmed.includes(':')) {
        // Maybe it's a data row with different format
        const altReading = parseTopconAltRow(trimmed, instrumentHeight, i + 1)
        if (altReading) {
          readings.push(altReading)
        } else {
          parseErrors.push(`Line ${i + 1}: Could not parse Topcon DL row: "${trimmed.substring(0, 60)}"`)
        }
      }
    } else if (trimmed.includes(';')) {
      // Semicolon-separated data may appear without column header
      const altReading = parseTopconAltRow(trimmed, instrumentHeight, i + 1)
      if (altReading) {
        inDataSection = true
        readings.push(altReading)
      }
    }
  }

  metadata.parseErrors = parseErrors

  const observations = buildTopconObservations(readings)

  return {
    format: 'topcon-dl',
    readings,
    observations,
    metadata,
  }
}

/**
 * Parse a Topcon DL data row.
 * Format: Station  [BM/TP flag]  Reading  Distance  [Type]
 * Example: "BM1  BM  1.65432  25.4  BS"
 */
function parseTopconDataRow(
  line: string,
  instrumentHeight: number,
  lineNo: number
): LevelReading | null {
  const parts = line.split(/[\s\t]+/).filter(s => s.length > 0)
  if (parts.length < 2) return null

  // First token is station ID
  const stationId = parts[0]

  // Find numeric tokens for reading and distance
  const numericTokens: number[] = []
  const nonNumericTokens: string[] = []

  for (let j = 1; j < parts.length; j++) {
    const val = parseFloat(parts[j])
    if (!isNaN(val)) {
      numericTokens.push(val)
    } else {
      nonNumericTokens.push(parts[j].toUpperCase())
    }
  }

  if (numericTokens.length === 0) return null

  const staffReading = numericTokens[0]
  const distance = numericTokens.length >= 2 ? numericTokens[1] : 30

  // Determine type from non-numeric tokens
  let type: 'BS' | 'FS' | 'IS' = 'BS'
  for (const token of nonNumericTokens) {
    if (token.includes('FS') || token === 'FORESIGHT') { type = 'FS'; break }
    if (token.includes('IS') || token === 'INTERMEDIATE') { type = 'IS'; break }
  }

  // If station starts with TP and there's no explicit type, assume FS
  if (stationId.toUpperCase().startsWith('TP') && nonNumericTokens.length === 0) {
    // Keep as BS – type determination requires sequential context
  }

  return {
    stationId,
    type,
    staffReading,
    distance: isNaN(distance) ? 30 : distance,
    instrumentHeight,
  }
}

/**
 * Alternative Topcon DL format: tab-separated or semicolon-separated.
 */
function parseTopconAltRow(
  line: string,
  instrumentHeight: number,
  lineNo: number
): LevelReading | null {
  // Try semicolon separator (some Topcon exports)
  if (line.includes(';')) {
    const parts = line.split(';').map(s => s.trim()).filter(s => s.length > 0)
    if (parts.length >= 2) {
      const stationId = parts[0]
      const staffReading = parseFloat(parts[1])
      if (isNaN(staffReading)) return null
      const distance = parts.length >= 3 ? parseFloat(parts[2]) : 30
      const typeStr = parts.length >= 4 ? parts[3].toUpperCase() : 'BS'

      let type: 'BS' | 'FS' | 'IS' = 'BS'
      if (typeStr.includes('FS')) type = 'FS'
      else if (typeStr.includes('IS')) type = 'IS'

      return {
        stationId,
        type,
        staffReading,
        distance: isNaN(distance) ? 30 : distance,
        instrumentHeight,
      }
    }
  }

  return null
}

/**
 * Build observations from Topcon readings (BS/FS pairs).
 */
function buildTopconObservations(readings: LevelReading[]): LevelObservation[] {
  const observations: LevelObservation[] = []
  let bsReading: LevelReading | null = null

  for (const r of readings) {
    if (r.type === 'BS') {
      bsReading = r
    } else if (r.type === 'FS' && bsReading) {
      const heightDifference = bsReading.staffReading - r.staffReading
      const distance = (bsReading.distance + r.distance) / 2
      const distKm = distance / 1000
      const weight = distKm > 0 ? 1 / (distKm * distKm) : 1000

      observations.push({
        fromId: bsReading.stationId,
        toId: r.stationId,
        heightDifference,
        distance,
        weight,
      })
      bsReading = null
    }
  }

  return observations
}

import {
  adjustLevelNetwork,
  computeObservations,
} from '../levelNetworkAdjustment'
import {
  allowableMisclosure,
  LevelObservation,
  LevelControlPoint,
} from '../digitalLevelTypes'

describe('adjustLevelNetwork', () => {
  test('adjusts simple leveling run A -> B -> C with 1 fixed', () => {
    const observations: LevelObservation[] = [
      { fromId: 'BM1', toId: 'TP1', heightDifference: 0.500, distance: 50, weight: 1 / (0.05 * 0.05) },
      { fromId: 'TP1', toId: 'TP2', heightDifference: -0.300, distance: 40, weight: 1 / (0.04 * 0.04) },
    ]
    const controlPoints: LevelControlPoint[] = [
      { id: 'BM1', rl: 1500.000, isFixed: true },
    ]

    const result = adjustLevelNetwork(observations, controlPoints, 'third')
    expect(result.passed).toBeDefined()
    expect(result.adjustedLevels.length).toBe(3) // BM1, TP1, TP2
    expect(result.adjustedLevels[0].id).toBe('BM1')
    expect(result.adjustedLevels[0].rl).toBeCloseTo(1500.000, 1)
  })

  test('computes misclosure for a closed loop', () => {
    // Triangle: BM1 -> TP1 -> TP2 -> BM1
    // True RLs: BM1=1000, TP1=1001, TP2=1002
    // Obs: +1.000, +1.000, -2.010 (with 10mm misclosure)
    const observations: LevelObservation[] = [
      { fromId: 'BM1', toId: 'TP1', heightDifference: 1.000, distance: 100, weight: 1 },
      { fromId: 'TP1', toId: 'TP2', heightDifference: 1.000, distance: 100, weight: 1 },
      { fromId: 'TP2', toId: 'BM1', heightDifference: -2.010, distance: 100, weight: 1 },
    ]
    const controlPoints: LevelControlPoint[] = [
      { id: 'BM1', rl: 1000.000, isFixed: true },
    ]

    const result = adjustLevelNetwork(observations, controlPoints, 'third')
    // Misclosure should be non-zero
    expect(result.misclosure).toBeDefined()
    expect(result.totalDistance).toBeCloseTo(0.3) // 3 x 100m = 300m = 0.3km
    expect(result.degreesOfFreedom).toBeGreaterThan(0)
  })

  test('allowable misclosure per Kenya order standards', () => {
    // 4th order: 20*sqrt(L) mm, L in km
    expect(allowableMisclosure(1.0, 'fourth')).toBeCloseTo(20.0, 1)
    // 1st order: 4*sqrt(L) mm
    expect(allowableMisclosure(1.0, 'first')).toBeCloseTo(4.0, 1)
    // 2nd order: 6*sqrt(L)
    expect(allowableMisclosure(1.0, 'second')).toBeCloseTo(6.0, 1)
    // 3rd order: 10*sqrt(L)
    expect(allowableMisclosure(1.0, 'third')).toBeCloseTo(10.0, 1)
    // For L=4 km, 4th order: 20*sqrt(4) = 40mm
    expect(allowableMisclosure(4.0, 'fourth')).toBeCloseTo(40.0, 1)
  })

  test('throws when no observations provided', () => {
    expect(function() {
      adjustLevelNetwork([], [{ id: 'A', rl: 100, isFixed: true }], 'third')
    }).toThrow('At least one level observation')
  })

  test('throws when no fixed control point', () => {
    const obs: LevelObservation[] = [
      { fromId: 'A', toId: 'B', heightDifference: 1.0, distance: 50, weight: 1 },
    ]
    expect(function() {
      adjustLevelNetwork(obs, [{ id: 'A', rl: 100, isFixed: false }], 'third')
    }).toThrow('At least one fixed control point')
  })

  test('forward propagation gives initial height estimates', () => {
    const observations: LevelObservation[] = [
      { fromId: 'BM1', toId: 'TP1', heightDifference: 2.500, distance: 50, weight: 1 },
      { fromId: 'TP1', toId: 'BM2', heightDifference: -1.200, distance: 50, weight: 1 },
    ]
    const controlPoints: LevelControlPoint[] = [
      { id: 'BM1', rl: 1200.000, isFixed: true },
    ]

    const result = adjustLevelNetwork(observations, controlPoints, 'third')
    const tp1 = result.adjustedLevels.find(function(p) { return p.id === 'TP1' })
    expect(tp1).toBeDefined()
    expect(tp1!.rl).toBeCloseTo(1202.5, 0) // initial: 1200 + 2.5
  })

  test('all-fixed-stations edge case returns residuals', () => {
    const observations: LevelObservation[] = [
      { fromId: 'BM1', toId: 'BM2', heightDifference: 5.000, distance: 100, weight: 1 },
    ]
    const controlPoints: LevelControlPoint[] = [
      { id: 'BM1', rl: 1000.000, isFixed: true },
      { id: 'BM2', rl: 1005.010, isFixed: true }, // 10mm misclosure
    ]

    const result = adjustLevelNetwork(observations, controlPoints, 'fourth')
    expect(result.adjustedLevels).toHaveLength(2)
    expect(result.residuals).toHaveLength(1)
    // Residual should be non-zero since observed diff != actual diff
    expect(result.residuals[0].residual).toBeDefined()
  })

  test('reference variance is computed', () => {
    const observations: LevelObservation[] = [
      { fromId: 'BM1', toId: 'TP1', heightDifference: 1.000, distance: 30, weight: 1000 },
      { fromId: 'TP1', toId: 'BM2', heightDifference: -0.500, distance: 30, weight: 1000 },
      { fromId: 'BM2', toId: 'BM1', heightDifference: -0.510, distance: 30, weight: 1000 }, // 10mm misclosure
    ]
    const controlPoints: LevelControlPoint[] = [
      { id: 'BM1', rl: 1000.000, isFixed: true },
    ]

    const result = adjustLevelNetwork(observations, controlPoints, 'third')
    expect(result.referenceVariance).toBeGreaterThanOrEqual(0)
    expect(result.degreesOfFreedom).toBeGreaterThan(0)
  })
})

