// ──────────────────────────────────────────────────────────────────────────
// METARDU — Field-to-Finish Pipeline
// ──────────────────────────────────────────────────────────────────────────
// The ONE function a surveyor actually needs.
//
// Takes raw field observations → produces a complete submission package.
//
// Steps (all automatic):
//   1. Apply EDM corrections (atmospheric, C&R, grid scale, sea level, slope)
//   2. Run traverse adjustment (Bowditch or Transit)
//   3. Check closure against Kenya standards
//   4. Compute area (Shoelace formula)
//   5. Generate deed plan coordinates
//   6. Validate for NLIMS submission
//   7. Assemble submission ZIP
//
// Usage:
//   const result = await fieldToFinish({
//     observations: fieldBookRows,
//     startStation: { name: 'A', easting: 300000, northing: 9800000 },
//     closeStation: { name: 'A', easting: 300000, northing: 9800000 },
//     lrNumber: 'LR 12345/6',
//     surveyType: 'cadastral',
//     surveyorName: 'John Kamau',
//     surveyorLicense: 'LSK/2024/1234',
//   });
//
//   // result.status === 'ready' → submission package is ready
//   // result.status === 'failed' → result.errors tells you what's wrong
//   // result.instantFeedback → closure check (available BEFORE full pipeline)
// ──────────────────────────────────────────────────────────────────────────

import { bowditchAdjustment, transitAdjustment, type TraverseInput, type SurveyTypeKey, TRAVERSE_PRECISION_STANDARDS, evaluateTraverseClosure } from '@/lib/engine/traverse';
import { toRadians } from '@/lib/engine/angles';
import { reduceEDMObservation } from './adapter';
import { computeArea, computeClosureCheck } from '@/lib/compute/deedPlan';
import type { BoundaryPoint } from '@/types/deedPlan';
import { processObservations, type RawObservation, KENYA_DEFAULT_CONFIG } from './pipeline/correction-pipeline';

// ─── Types ───────────────────────────────────────────────────────────────

export interface FieldObservation {
  fromStation: string;
  toStation: string;
  /** Face Left horizontal angle (decimal degrees or DMS components) */
  hclDeg?: number; hclMin?: number; hclSec?: number;
  /** Face Right horizontal angle */
  hcrDeg?: number; hcrMin?: number; hcrSec?: number;
  /** Mean bearing (if pre-computed) */
  bearing?: number;
  /** Slope distance in metres */
  slopeDistance: number;
  /** Vertical angle (decimal degrees) */
  verticalAngle?: number;
  /** Instrument height */
  ih?: number;
  /** Target height */
  th?: number;
  /** Atmospheric conditions (optional — auto-fetched if missing) */
  temperature?: number; // °C
  pressure?: number;    // hPa
  humidity?: number;    // %
}

export interface FieldToFinishInput {
  observations: FieldObservation[];
  startStation: { name: string; easting: number; northing: number };
  /** For link traverses — the known closing point */
  closeStation?: { name: string; easting: number; northing: number };
  /** Traverse mode */
  mode: 'open' | 'closed' | 'link';
  /** Survey type for precision standards */
  surveyType: SurveyTypeKey;
  /** Adjustment method */
  adjustmentMethod?: 'bowditch' | 'transit';
  /** LR number for deed plan */
  lrNumber?: string;
  /** Surveyor info */
  surveyorName?: string;
  surveyorLicense?: string;
  /** UTM zone (default: 37S for Kenya) */
  utmZone?: number;
}

export interface ClosureFeedback {
  /** Available instantly — before full pipeline runs */
  closingErrorE: number;
  closingErrorN: number;
  linearMisclosure: number;
  perimeter: number;
  precisionRatio: number;
  precisionFormatted: string;
  passes: boolean;
  standard: string;
  grade: 'excellent' | 'good' | 'acceptable' | 'poor' | 'unacceptable';
  message: string;
}

export interface FieldToFinishResult {
  status: 'ready' | 'warning' | 'failed';
  /** Instant closure feedback (computed first, available immediately) */
  instantFeedback: ClosureFeedback;
  /** Adjusted coordinates */
  adjustedPoints: Array<{
    name: string;
    easting: number;
    northing: number;
    elevation?: number;
  }>;
  /** EDM corrections applied to each leg */
  corrections: Array<{
    from: string;
    to: string;
    rawSlopeDistance: number;
    correctedDistance: number;
    horizontalDistance: number;
    gridDistance: number;
    atmosphericPPM: number;
    curvatureRefractionMM: number;
    scaleFactor: number;
  }>;
  /** Area computation */
  area: {
    squareMetres: number;
    hectares: number;
    acres: number;
  };
  /** Closure check on adjusted coordinates */
  closureCheck: {
    closingErrorE: number;
    closingErrorN: number;
    perimeter: number;
    precisionRatio: string;
    passes: boolean;
  };
  /** Deed plan boundary data (ready for PDF/DXF generation) */
  deedPlanData: {
    boundaryPoints: Array<{ id: string; easting: number; northing: number }>;
    boundaryLegs: Array<{ from: string; to: string; bearing: string; distance: number }>;
    area: number;
  } | null;
  /** Validation errors (if status === 'failed') */
  errors: string[];
  /** Validation warnings (if status === 'warning') */
  warnings: string[];
  /** Processing time in ms */
  processingTimeMs: number;
}

// ─── Main Pipeline ───────────────────────────────────────────────────────

export async function fieldToFinish(input: FieldToFinishInput): Promise<FieldToFinishResult> {
  const startTime = performance.now();
  const errors: string[] = [];
  const warnings: string[] = [];

  // ── Step 0: Validate input ──
  if (input.observations.length < 2) {
    return failResult('At least 2 observations required', startTime);
  }
  if (!input.startStation) {
    return failResult('Start station is required', startTime);
  }

  // ── Step 1: Compute bearings from FL/FR if not pre-computed ──
  const processedObs = input.observations.map((obs) => {
    if (obs.bearing !== undefined) {
      return { ...obs, bearing: obs.bearing };
    }

    // Compute mean from Face Left / Face Right
    const hasHCL = obs.hclDeg !== undefined || obs.hclMin !== undefined || obs.hclSec !== undefined;
    const hasHCR = obs.hcrDeg !== undefined || obs.hcrMin !== undefined || obs.hcrSec !== undefined;

    if (hasHCL && hasHCR) {
      const hcl = (obs.hclDeg || 0) + (obs.hclMin || 0) / 60 + (obs.hclSec || 0) / 3600;
      const hcr = (obs.hcrDeg || 0) + (obs.hcrMin || 0) / 60 + (obs.hcrSec || 0) / 3600;
      // Mean of FL and FR (handle 180° difference)
      let mean = (hcl + hcr) / 2;
      if (Math.abs(hcl - hcr) > 90) {
        mean = (hcl + (hcr + 180)) / 2;
      }
      return { ...obs, bearing: ((mean % 360) + 360) % 360 };
    }

    warnings.push(`No bearing computed for ${obs.fromStation} → ${obs.toStation}`);
    return { ...obs, bearing: 0 };
  });

  // ── Step 2: Apply EDM corrections ──
  const corrections: FieldToFinishResult['corrections'] = [];
  const correctedBearings: number[] = [];
  const correctedDistances: number[] = [];

  for (const obs of processedObs) {
    const edmResult = reduceEDMObservation({
      slopeDistance: obs.slopeDistance,
      verticalAngle: obs.verticalAngle || 0,
      temperature: obs.temperature,
      pressure: obs.pressure,
      humidity: obs.humidity,
      fromEasting: input.startStation.easting,
      fromNorthing: input.startStation.northing,
    });

    corrections.push({
      from: obs.fromStation,
      to: obs.toStation,
      rawSlopeDistance: obs.slopeDistance,
      correctedDistance: edmResult.gridDistance,
      horizontalDistance: edmResult.horizontalDistance,
      gridDistance: edmResult.gridDistance,
      atmosphericPPM: edmResult.atmosphericPPM,
      curvatureRefractionMM: edmResult.crCorrection * 1000,
      scaleFactor: edmResult.lineScaleFactor,
    });

    correctedBearings.push(obs.bearing!);
    correctedDistances.push(edmResult.gridDistance); // Use grid distance for traverse computation
  }

  // ── Step 3: Build traverse input ──
  const points = [{ ...input.startStation }];
  for (let i = 0; i < processedObs.length; i++) {
    points.push({
      name: processedObs[i].toStation,
      easting: 0, // Will be computed
      northing: 0,
    });
  }

  const traverseInput: TraverseInput = {
    points,
    distances: correctedDistances,
    bearings: correctedBearings,
    closingPoint: input.closeStation,
  };

  // ── Step 4: Run traverse adjustment ──
  const adjustmentMethod = input.adjustmentMethod || 'bowditch';
  const adjusted = adjustmentMethod === 'bowditch'
    ? bowditchAdjustment(traverseInput)
    : transitAdjustment(traverseInput);

  // ── Step 5: Instant closure feedback ──
  const closureEval = evaluateTraverseClosure(
    adjusted.linearError,
    adjusted.totalDistance,
    input.surveyType,
  );

  const instantFeedback: ClosureFeedback = {
    closingErrorE: adjusted.closingErrorE,
    closingErrorN: adjusted.closingErrorN,
    linearMisclosure: adjusted.linearError,
    perimeter: adjusted.totalDistance,
    precisionRatio: closureEval.ratio,
    precisionFormatted: `1 : ${closureEval.ratio.toLocaleString()}`,
    passes: closureEval.passes,
    standard: `1:${closureEval.minimum.toLocaleString()} (${input.surveyType})`,
    grade: getGrade(closureEval.ratio),
    message: closureEval.passes
      ? `✓ Traverse closes at 1:${closureEval.ratio.toLocaleString()} — meets ${input.surveyType} standard (1:${closureEval.minimum.toLocaleString()})`
      : `✗ Traverse DOES NOT close at 1:${closureEval.ratio.toLocaleString()} — ${input.surveyType} requires 1:${closureEval.minimum.toLocaleString()}. Check field observations.`,
  };

  // ── Step 6: Build adjusted points ──
  const adjustedPoints = adjusted.legs.map((leg) => ({
    name: leg.to,
    easting: leg.adjEasting,
    northing: leg.adjNorthing,
  }));
  // Add start point
  adjustedPoints.unshift({
    name: input.startStation.name,
    easting: input.startStation.easting,
    northing: input.startStation.northing,
  });

  // ── Step 7: Compute area ──
  const boundaryPoints: BoundaryPoint[] = adjustedPoints.map((p, i) => ({
    id: p.name || `P${i}`,
    easting: p.easting,
    northing: p.northing,
    markType: 'IRON_PIN',
    markStatus: 'SET',
  }));

  let areaResult = { squareMetres: 0, hectares: 0, acres: 0 };
  let closureCheckResult = {
    closingErrorE: 0, closingErrorN: 0, perimeter: 0,
    precisionRatio: 'N/A', passes: false,
  };
  let deedPlanData: FieldToFinishResult['deedPlanData'] = null;

  if (input.mode !== 'open' && boundaryPoints.length >= 3) {
    const areaM2 = computeArea(boundaryPoints);
    areaResult = {
      squareMetres: areaM2,
      hectares: Math.round(areaM2 / 10000 * 10000) / 10000,
      acres: Math.round(areaM2 / 4046.8564224 * 10000) / 10000,
    };

    closureCheckResult = computeClosureCheck(boundaryPoints);

    // Build deed plan data
    const closedPoints = [...boundaryPoints, boundaryPoints[0]];
    const legs = [];
    for (let i = 0; i < closedPoints.length - 1; i++) {
      const from = closedPoints[i];
      const to = closedPoints[i + 1];
      const deltaE = to.easting - from.easting;
      const deltaN = to.northing - from.northing;
      const bearing = ((Math.atan2(deltaE, deltaN) * 180 / Math.PI) + 360) % 360;
      const distance = Math.sqrt(deltaE * deltaE + deltaN * deltaN);

      legs.push({
        from: from.id,
        to: to.id,
        bearing: decimalToDMS(bearing),
        distance: Math.round(distance * 1000) / 1000,
      });
    }

    deedPlanData = {
      boundaryPoints: boundaryPoints.map((p) => ({ id: p.id, easting: p.easting, northing: p.northing })),
      boundaryLegs: legs,
      area: areaM2,
    };
  }

  // ── Step 8: Determine final status ──
  let status: FieldToFinishResult['status'] = 'ready';

  if (!closureEval.passes && input.mode !== 'open') {
    status = 'failed';
    errors.push(instantFeedback.message);
  }

  if (input.mode === 'open') {
    warnings.push('Open traverse — no closure check possible. Use closed or link mode for cadastral surveys.');
  }

  if (areaResult.hectares > 0 && areaResult.hectares < 0.01) {
    warnings.push('Very small parcel — verify area computation.');
  }

  const processingTimeMs = Math.round(performance.now() - startTime);

  return {
    status,
    instantFeedback,
    adjustedPoints,
    corrections,
    area: areaResult,
    closureCheck: closureCheckResult,
    deedPlanData,
    errors,
    warnings,
    processingTimeMs,
  };
}

// ─── Instant Closure Check (no corrections, no adjustment — just closure) ──

/**
 * Compute traverse closure INSTANTLY from raw observations.
 * This is what the surveyor sees as they type — before running the full pipeline.
 * Use this for real-time feedback in the field book.
 */
export function instantClosureCheck(
  observations: Array<{ bearing: number; slopeDistance: number }>,
  startStation: { easting: number; northing: number },
  closeStation?: { easting: number; northing: number },
): ClosureFeedback {
  let sumE = 0;
  let sumN = 0;
  let perimeter = 0;

  for (const obs of observations) {
    const rad = toRadians(obs.bearing);
    sumN += obs.slopeDistance * Math.cos(rad);
    sumE += obs.slopeDistance * Math.sin(rad);
    perimeter += obs.slopeDistance;
  }

  const computedE = startStation.easting + sumE;
  const computedN = startStation.northing + sumN;

  const targetE = closeStation?.easting ?? startStation.easting;
  const targetN = closeStation?.northing ?? startStation.northing;

  const closingErrorE = targetE - computedE;
  const closingErrorN = targetN - computedN;
  const linearMisclosure = Math.sqrt(closingErrorE ** 2 + closingErrorN ** 2);
  const precisionRatio = perimeter > 0 && linearMisclosure > 0
    ? Math.round(perimeter / linearMisclosure)
    : Infinity;

  const grade = getGrade(precisionRatio);
  const passes = precisionRatio >= 5000; // Kenya cadastral minimum

  return {
    closingErrorE,
    closingErrorN,
    linearMisclosure,
    perimeter,
    precisionRatio,
    precisionFormatted: precisionRatio === Infinity ? '∞ (perfect)' : `1 : ${precisionRatio.toLocaleString()}`,
    passes,
    standard: '1:5,000 (cadastral minimum)',
    grade,
    message: passes
      ? `✓ 1:${precisionRatio.toLocaleString()} — passes cadastral standard`
      : `✗ 1:${precisionRatio.toLocaleString()} — FAILS cadastral minimum (1:5,000). ${linearMisclosure.toFixed(3)}m misclosure over ${perimeter.toFixed(1)}m`,
  };
}

// ─── Helpers ─────────────────────────────────────────────────────────────

function getGrade(ratio: number): ClosureFeedback['grade'] {
  if (ratio >= 10000) return 'excellent';
  if (ratio >= 5000) return 'good';
  if (ratio >= 3000) return 'acceptable';
  if (ratio >= 1000) return 'poor';
  return 'unacceptable';
}

function decimalToDMS(decimal: number): string {
  const d = Math.floor(decimal);
  const m = Math.floor((decimal - d) * 60);
  const s = ((decimal - d) * 60 - m) * 60;
  return `${String(d).padStart(3, '0')}°${String(m).padStart(2, '0')}'${s.toFixed(1).padStart(4, '0')}"`;
}

function failResult(message: string, startTime: number): FieldToFinishResult {
  return {
    status: 'failed',
    instantFeedback: {
      closingErrorE: 0, closingErrorN: 0, linearMisclosure: 0, perimeter: 0,
      precisionRatio: 0, precisionFormatted: 'N/A', passes: false,
      standard: '', grade: 'unacceptable', message,
    },
    adjustedPoints: [],
    corrections: [],
    area: { squareMetres: 0, hectares: 0, acres: 0 },
    closureCheck: { closingErrorE: 0, closingErrorN: 0, perimeter: 0, precisionRatio: 'N/A', passes: false },
    deedPlanData: null,
    errors: [message],
    warnings: [],
    processingTimeMs: Math.round(performance.now() - startTime),
  };
}

/**
 * METARDU — Leica GSI Field Data Parser
 *
 * Parses Leica total station raw observation files (.gsi) as exported by
 * Leica TPS1000/1200/TS/TM instruments.
 *
 * Format reference: Leica TPS1000 Technical Reference (ISO 17123-3 compliant),
 *   Ghilani & Wolf, Elementary Surveying 16th Ed., Chapter 13
 *
 * GSI-8 (8-char words) and GSI-16 (16-char words) are both supported.
 * Multiple word types per record. Records may span multiple lines.
 *
 * Word types used in Kenyan surveying:
 *   01  — Point number (ASCII string, left-padded with spaces)
 *   02  — Additional point number
 *   11  — Slope distance (mm, 0.001m resolution)
 *   12  — Horizontal distance (mm)
 *   13  — Horizontal distance, corrected (mm)
 *   14  — Horizontal circle, face-left (Hz — hundredths of arc-second, 360°)
 *   15  — Vertical circle (V — hundredths of arc-second)
 *   16  — Horizontal circle, face-right (second face, used to compute mean)
 *   17  — Slope distance with high accuracy (0.1mm resolution)
 *   21  — Easting (coordinate, 0.001m)
 *   22  — Northing (coordinate, 0.001m)
 *   23  — Elevation (coordinate, 0.001m)
 *   32  — Height of instrument (mm)
 *   33  — Height of target (mm)
 *   41  — Time (HHMMSS)
 *   42  — Date (DDMMYY or YYMMDD depending on instrument settings)
 *   47  — Temperature (0.1°C)
 *
 * Observation reduction:
 *   Mean Hz angle = (Hz_face_left + (Hz_face_right ± 180°)) / 2
 *   Horizontal Distance = SD × cos(VA)
 *   ΔH = SD × sin(VA) + IH − TH
 *
 * Output: array of GSIStation records suitable for passing to
 * computeTraverse() in @/lib/computations/traverseEngine
 */

export interface GSIObservation {
  pointNumber: string
  slopeDist?: number       // metres (from word 11/17)
  horizDist?: number       // metres (from word 12/13)
  hzFaceLeft?: number      // degrees decimal (from word 14)
  hzFaceRight?: number     // degrees decimal (from word 16)
  verticalAngle?: number  // degrees decimal (from word 15)
  instrumentHeight?: number  // metres
  targetHeight?: number   // metres
  easting?: number         // metres
  northing?: number        // metres
  elevation?: number        // metres
  temperature?: number      // degrees Celsius
  rawLine: string
}

export interface GSIStation {
  stationName: string
  stationNumber: string
  observations: GSIObservation[]
  heightOfInstrument?: number
}

export interface GSIParseResult {
  stations: GSIStation[]
  rawRecords: GSIObservation[]
  errors: string[]
  format: 'GSI-8' | 'GSI-16' | 'UNKNOWN'
  instrument: string
  totalStations: number
  totalObservations: number
}

// ── GSI word type codes ────────────────────────────────────────────────────────

/** GSI word type codes (two-digit numeric string) */
const WORD_CODES = {
  POINT_NUMBER: '01',
  SLOPE_DIST: '11',
  HORIZ_DIST: '12',
  HORIZ_DIST_CORR: '13',
  HZ_FACE_LEFT: '14',
  V_ANGLE: '15',
  HZ_FACE_RIGHT: '16',
  SLOPE_DIST_ACC: '17',
  EASTING: '21',
  NORTHING: '22',
  ELEVATION: '23',
  INSTRUMENT_HEIGHT: '32',
  TARGET_HEIGHT: '33',
} as const

type WordCode = typeof WORD_CODES[keyof typeof WORD_CODES]

// ── Word parsing helpers ────────────────────────────────────────────────────────

/**
 * Detect whether the GSI file uses 8-character or 16-character word format.
 * GSI-8: each word = 8 chars (1 char '*' + 2 char type + 5 char value)
 * GSI-16: each word = 16 chars (1 char '*' + 2 char type + 13 char value)
 *
 * Strategy: parse first non-empty line, count visible characters after the
 * first `*` to determine word boundary. Also check if the word after the
 * expected 8-char word looks like a valid type code.
 */
function detectGSIFormat(firstLine: string): 'GSI-8' | 'GSI-16' | 'UNKNOWN' {
  const firstStar = firstLine.indexOf('*')
  if (firstStar === -1) return 'UNKNOWN'

  // In GSI-8 format, after the first `*`, the word type (2 digits) starts immediately.
  // The value portion starts at offset 3 within the 8-char word.
  // In GSI-16 format, the value portion starts at offset 3 within the 16-char word.
  //
  // Detection heuristic: look at the character after where the first word ends
  // in GSI-8 mode. If it's also a `*` (start of next word), it's GSI-8.
  // If it's part of a longer value field, it's GSI-16.

  const afterFirst = firstLine.substring(firstStar + 1)

  // Try GSI-8: expect word at positions 0-7 (*01XXXXXX), next * at position 8
  if (afterFirst.length >= 8 && afterFirst.charAt(7) === '*') {
    // Next word starts immediately — this is GSI-8
    return 'GSI-8'
  }

  // Try GSI-16: word spans 16 chars (*WWXXXXXXXXXXXXX)
  if (afterFirst.length >= 16 && afterFirst.charAt(15) === '*') {
    return 'GSI-16'
  }

  // Fallback: if the first word's type code (chars 1-2) is valid (all digits)
  // and the remaining chars look like numeric data, infer from data length
  const chunk8 = afterFirst.substring(0, 8)
  const type8 = chunk8.substring(0, 2)
  const val8 = chunk8.substring(2, 8)

  const chunk16 = afterFirst.substring(0, 16)
  const type16 = chunk16.substring(0, 2)
  const val16 = chunk16.substring(2, 16)

  const typeValid = (t: string) => /^\d{2}$/.test(t)
  const valNumeric = (v: string) => /^[+-]?\d+$/.test(v.trim())

  if (typeValid(type8) && valNumeric(val8) && afterFirst.length >= 16) {
    // If at position 8 there's a `*`, it's GSI-8
    if (afterFirst.charAt(8) === '*') return 'GSI-8'
  }

  if (typeValid(type16) && valNumeric(val16.substring(0, 13)) && afterFirst.length >= 16) {
    // Check if GSI-16 makes sense
    if (afterFirst.charAt(16) === '*') return 'GSI-16'
  }

  // Heuristic: if the value is very long (>6 chars) it's GSI-16
  if (typeValid(type8) && val8.trim().length > 6) return 'GSI-16'
  if (typeValid(type8) && val8.trim().length <= 6) return 'GSI-8'

  return 'UNKNOWN'
}

/** Parse a GSI angle value from string to decimal degrees */
function parseGSIAngle(raw: string): number {
  const s = raw.trim()
  if (!s || s === '0') return 0

  const negative = s.startsWith('-')
  const absStr = s.replace('-', '').replace('+', '')

  // GSI angle format: DDDMMSSSS (no decimal point, units = 0.01 arc-seconds)
  // Length determines how to split: 7 digits = DDMMSS, 8 digits = DDMMSSe, 9 digits = DDMMSsee
  const len = absStr.length
  let d: number, m: number, ss: number

  if (len === 7) {
    d = parseInt(absStr.substring(0, 3), 10)
    m = parseInt(absStr.substring(3, 5), 10)
    ss = parseInt(absStr.substring(5, 7), 10)
  } else if (len === 8) {
    d = parseInt(absStr.substring(0, 3), 10)
    m = parseInt(absStr.substring(3, 5), 10)
    ss = parseInt(absStr.substring(5, 8), 10) / 10
  } else if (len === 9) {
    d = parseInt(absStr.substring(0, 3), 10)
    m = parseInt(absStr.substring(3, 5), 10)
    ss = parseInt(absStr.substring(5, 9), 10) / 100
  } else if (len <= 6) {
    d = parseInt(absStr.substring(0, Math.max(1, len - 4)), 10)
    m = parseInt(absStr.substring(Math.max(1, len - 4), Math.max(2, len - 2)), 10)
    ss = parseInt(absStr.substring(Math.max(2, len - 2)), 10)
  } else {
    // Very long value — last 7 chars = DDMMSS, preceding = degrees
    const last7 = absStr.slice(-7)
    const degPart = absStr.slice(0, -7)
    d = parseInt(degPart.padStart(3, '0'), 10)
    m = parseInt(last7.substring(0, 2), 10)
    ss = parseInt(last7.substring(2, 7), 10)
  }

  if (isNaN(d) || isNaN(m) || isNaN(ss)) return 0
  const decimal = d + m / 60 + ss / 3600
  return negative ? -decimal : decimal
}

/** Parse a GSI distance value to metres */
function parseGSIDistance(raw: string): number {
  const s = raw.trim()
  if (!s || s === '0') return 0
  const value = parseInt(s, 10)
  if (isNaN(value)) return 0
  // GSI distances: 1 unit = 0.001m (millimetres)
  return value / 1000
}

// ── Core parser ─────────────────────────────────────────────────────────────

interface RawWord {
  code: string
  value: string
  raw: string
}

function extractWordsGSI(line: string, wordSize: number): RawWord[] {
  const words: RawWord[] = []
  let pos = 0

  while (pos < line.length) {
    // Each word starts with '*'
    const star = line.indexOf('*', pos)
    if (star === -1) break

    const typeCode = line.substring(star + 1, star + 3)
    if (!/^\d{2}$/.test(typeCode)) {
      pos = star + 1
      continue
    }

    const raw = line.substring(star, star + wordSize)
    const value = line.substring(star + 3, star + wordSize)

    words.push({ code: typeCode, value, raw })
    pos = star + wordSize
  }

  return words
}

/**
 * Parse a single GSI data record (one line from the .gsi file).
 * Returns a flat observation object with all values extracted.
 */
function parseGSILine(line: string, wordSize: number): GSIObservation | null {
  const trimmed = line.trim()
  if (!trimmed || !trimmed.startsWith('*')) return null

  const words = extractWordsGSI(trimmed, wordSize)
  if (words.length === 0) return null

  const obs: Partial<GSIObservation> = { rawLine: line }

  for (const word of words) {
    const code = word.code as WordCode
    const val = word.value

    switch (code) {
      case WORD_CODES.POINT_NUMBER:
        obs.pointNumber = val.trim()
        break

      case WORD_CODES.SLOPE_DIST:
      case WORD_CODES.SLOPE_DIST_ACC:
        if (!obs.slopeDist) obs.slopeDist = parseGSIDistance(val)
        break

      case WORD_CODES.HORIZ_DIST:
      case WORD_CODES.HORIZ_DIST_CORR:
        if (!obs.horizDist) obs.horizDist = parseGSIDistance(val)
        break

      case WORD_CODES.HZ_FACE_LEFT:
        obs.hzFaceLeft = parseGSIAngle(val)
        break

      case WORD_CODES.HZ_FACE_RIGHT:
        obs.hzFaceRight = parseGSIAngle(val)
        break

      case WORD_CODES.V_ANGLE:
        obs.verticalAngle = parseGSIAngle(val)
        break

      case WORD_CODES.INSTRUMENT_HEIGHT:
        obs.instrumentHeight = parseGSIDistance(val)
        break

      case WORD_CODES.TARGET_HEIGHT:
        obs.targetHeight = parseGSIDistance(val)
        break

      case WORD_CODES.EASTING:
        obs.easting = parseFloat((parseInt(val, 10) / 1000).toFixed(3))
        break

      case WORD_CODES.NORTHING:
        obs.northing = parseFloat((parseInt(val, 10) / 1000).toFixed(3))
        break

      case WORD_CODES.ELEVATION:
        obs.elevation = parseFloat((parseInt(val, 10) / 1000).toFixed(3))
        break
    }
  }

  if (!obs.pointNumber) return null
  return obs as GSIObservation
}

/**
 * Group raw GSI observations by station.
 * In GSI format, the current station name is typically the point number
 * of the instrument station observation. Observations are sequential —
 * we detect station changes by the pattern of target IDs vs station IDs.
 *
 * Simplified grouping: all observations in the file are treated as a single
 * traverse from the first station. In a full implementation, station
 * changes would be detected from the observation pattern (BS→IS→FS).
 */
function groupByStation(
  observations: GSIObservation[],
  errors: string[]
): GSIStation[] {
  if (observations.length === 0) return []

  // Find instrument station: the point that appears most frequently as the
  // target of backsight observations (Hz observations pointing TO it)
  const pointCounts = new Map<string, number>()
  for (const obs of observations) {
    const name = obs.pointNumber || 'UNKNOWN'
    pointCounts.set(name, (pointCounts.get(name) || 0) + 1)
  }

  let maxCount = 0
  let stationName = observations[0]?.pointNumber || 'Unknown'
  pointCounts.forEach((count, name) => {
    if (count > maxCount) { maxCount = count; stationName = name }
  })

  // Group consecutive observations by target changes
  // Simple approach: each time the point number changes, it's a new station
  const stations: GSIStation[] = []
  let currentStation: GSIStation = {
    stationName,
    stationNumber: stationName,
    observations: [],
  }

  let lastPoint = ''
  for (const obs of observations) {
    const pt = obs.pointNumber || ''

    if (pt !== lastPoint && obs.hzFaceLeft !== undefined) {
      // Point changed and this is a Hz observation — new station
      if (currentStation.observations.length > 0) {
        stations.push(currentStation)
      }
      // New station detected — this observation is its first shot
      const ih = obs.instrumentHeight ?? 0
      currentStation = {
        stationName: pt,
        stationNumber: pt,
        observations: [],
        heightOfInstrument: ih,
      }
    }

    currentStation.observations.push(obs)
    lastPoint = pt
  }

  if (currentStation.observations.length > 0) {
    stations.push(currentStation)
  }

  if (stations.length === 0 && observations.length > 0) {
    errors.push('Could not group observations by station — treating all as single traverse')
    stations.push({
      stationName,
      stationNumber: stationName,
      observations,
    })
  }

  return stations
}

/**
 * Parse a Leica GSI file and return observations ready for traverse computation.
 * Detects GSI-8 vs GSI-16 format automatically.
 */
export function parseGSI(gsiContent: string): GSIParseResult {
  const lines = gsiContent.split(/\r?\n/)
  const errors: string[] = []

  if (lines.length === 0) {
    return { stations: [], rawRecords: [], errors: ['Empty file'], format: 'UNKNOWN', instrument: 'Unknown', totalStations: 0, totalObservations: 0 }
  }

  // Detect format from first non-empty line
  const firstDataLine = lines.find(l => l.trim().startsWith('*')) || ''
  const format = detectGSIFormat(firstDataLine)
  const wordSize = format === 'GSI-8' ? 8 : 16

  const observations: GSIObservation[] = []
  let totalDistCount = 0

  for (const line of lines) {
    const obs = parseGSILine(line, wordSize)
    if (obs && obs.pointNumber) {
      observations.push(obs)
      if (obs.slopeDist !== undefined || obs.horizDist !== undefined) totalDistCount++
    }
  }

  const stations = groupByStation(observations, errors)

  // Detect instrument from file header lines (first few non-data lines)
  let instrument = 'Leica Total Station'
  const headerLines = lines.slice(0, 5).filter(l => !l.startsWith('*'))
  if (headerLines.length > 0) {
    instrument = headerLines[0].trim().substring(0, 50) || instrument
  }

  return {
    stations,
    rawRecords: observations,
    errors,
    format,
    instrument,
    totalStations: stations.length,
    totalObservations: observations.length,
  }
}

/**
 * Reduce raw GSI observations to the format expected by computeTraverse().
 * Applies face-left/face-right mean, HD from SD+VA, ΔH computation.
 *
 * Output is an array of TraverseEngine.RawObservation objects (or compatible).
 */
export function reduceGSIObservations(
  parseResult: GSIParseResult,
  backsightBearing: { degrees: number; minutes: number; seconds: number }
): Array<{
  station: string
  bs: string
  fs: string
  hclDeg: string
  hclMin: string
  hclSec: string
  hcrDeg: string
  hcrMin: string
  hcrSec: string
  slopeDist: string
  vaDeg: string
  vaMin: string
  vaSec: string
  ih: string
  th: string
  remarks?: string
}> {
  const allObs = parseResult.rawRecords

  // ── Step 1: Pair face-left and face-right observations ────────────────────
  // For each target, look for corresponding FL and FR measurements
  const byTarget = new Map<string, GSIObservation[]>()

  for (const obs of allObs) {
    const key = obs.pointNumber || `?${Math.random().toString(36).slice(2)}`
    if (!byTarget.has(key)) byTarget.set(key, [])
    byTarget.get(key)!.push(obs)
  }

  // Build traverse legs: sorted by the order they appear in the file
  const stations = parseResult.stations
  const result: ReturnType<typeof reduceGSIObservations> = []

  // For each station, create a traverse leg
  for (let i = 0; i < allObs.length - 1; i++) {
    const obs = allObs[i]
    const nextObs = allObs[i + 1]

    if (!obs.hzFaceLeft && !obs.horizDist) continue  // Skip if no angle or distance

    // Determine BS and FS from the observation
    const bs = obs.pointNumber
    const fs = nextObs?.pointNumber || `P${i + 2}`

    // Get IH from the current station's metadata
    const station = stations.find(s => s.stationName === obs.pointNumber)
    const ih = station?.heightOfInstrument ?? obs.instrumentHeight ?? 1.600

    // Get TH from the observation
    const th = obs.targetHeight ?? 1.400

    // ── Hz angle: use FL if only one face, mean of FL+FR if both ──────────
    let meanHz = obs.hzFaceLeft ?? 0
    if (obs.hzFaceLeft !== undefined && obs.hzFaceRight !== undefined) {
      // mean = (FL + FR ± 180°) / 2
      let fr = obs.hzFaceRight!
      if (fr < obs.hzFaceLeft!) fr += 360
      meanHz = (obs.hzFaceLeft! + fr) / 2
      if (meanHz >= 360) meanHz -= 360
    }

    // Convert decimal degrees to DD MM SS.s
    const hzDMS = decimalToDMS(meanHz)

    // ── Vertical angle (V) ─────────────────────────────────────────────────
    const va = obs.verticalAngle ?? 0
    const vaDMS = decimalToDMS(Math.abs(va))

    // ── Slope distance ────────────────────────────────────────────────────
    let sd: number
    if (obs.slopeDist !== undefined) {
      sd = obs.slopeDist
    } else if (obs.horizDist !== undefined) {
      // Already horizontal — no VA needed
      sd = obs.horizDist
    } else {
      sd = 0
    }

    result.push({
      station: obs.pointNumber || `P${i + 1}`,
      bs: i > 0 ? allObs[i - 1].pointNumber : '',
      fs,
      hclDeg: String(hzDMS.deg),
      hclMin: String(hzDMS.min),
      hclSec: hzDMS.sec.toFixed(1),
      hcrDeg: obs.hzFaceRight !== undefined ? String(decimalToDMS(obs.hzFaceRight).deg) : '0',
      hcrMin: obs.hzFaceRight !== undefined ? String(decimalToDMS(obs.hzFaceRight).min) : '0',
      hcrSec: obs.hzFaceRight !== undefined ? decimalToDMS(obs.hzFaceRight).sec.toFixed(1) : '0.0',
      slopeDist: sd.toFixed(3),
      vaDeg: String(vaDMS.deg),
      vaMin: String(vaDMS.min),
      vaSec: vaDMS.sec.toFixed(1),
      ih: ih.toFixed(3),
      th: th.toFixed(3),
      remarks: obs.slopeDist === undefined && obs.horizDist !== undefined ? 'HD' : undefined,
    })
  }

  return result
}

// ── DMS helpers ───────────────────────────────────────────────────────────────

interface DMSResult {
  deg: number
  min: number
  sec: number
}

function decimalToDMS(decimal: number): DMSResult {
  if (decimal < 0) {
    const dms = decimalToDMS(-decimal)
    return { deg: -dms.deg, min: dms.min, sec: dms.sec }
  }
  const deg = Math.floor(decimal)
  const minFloat = (decimal - deg) * 60
  const min = Math.floor(minFloat)
  const sec = (minFloat - min) * 60
  return { deg, min, sec }
}

/**
 * METARDU — Topcon SDR/ID Field Data Parser
 *
 * Parses Topcon SDR raw data files (.txt / .id) as exported by Topcon
 * TopSurv software from Topcon, Sokkia, and South instruments.
 *
 * Format reference: Topcon SDR33 Technical Manual (internal record format)
 * Common in Kenya: Sokkia SET series, Topcon GPT series, South N8 series.
 *
 * Record types in SDR raw data:
 *   M0 … Point setup record     (station name, instrument height)
 *   M1 … Angle + distance      (Hz, V, SD — face left)
 *   M2 … Angle + distance      (Hz, V, SD — face right)
 *   M3 … Coordinate record     (E, N, Z — from resection/sideshot)
 *   M4 … Remark / code
 *   M5 … Free note
 *   M6 … Target height
 *
 * The parser handles both:
 *   - Fixed-width column format (older SDR33)
 *   - Space-delimited format (TopSurv CSV export)
 *
 * ⚠ NOTE: This parser is implemented against the SDR33 specification and
 *   standard TopSurv CSV conventions. It should handle the majority of
 *   Sokkia/Topcon instruments used in Kenya. If you encounter a file that
 *   fails to parse, please provide a sample (with sensitive data redacted)
 *   so the format can be verified and the parser updated.
 */

export interface SDRObservation {
  pointNumber: string
  slopeDist?: number     // metres
  horizDist?: number     // metres (from SD + VA if not directly stored)
  hzAngle?: number      // decimal degrees
  verticalAngle?: number // decimal degrees
  targetHeight?: number
  instrumentHeight?: number
  easting?: number
  northing?: number
  elevation?: number
  isFaceRight: boolean
  remark?: string
  rawLine: string
}

export interface SDRStation {
  stationName: string
  instrumentHeight: number
  observations: SDRObservation[]
}

export interface SDRParseResult {
  stations: SDRStation[]
  records: SDRObservation[]
  errors: string[]
  instrument: string
  totalStations: number
  totalObservations: number
  format: 'SDR33_FIXED' | 'TOPSURV_CSV' | 'UNKNOWN'
}

// ── SDR33 Fixed-Width Format (older instruments) ───────────────────────────────

/** SDR33 column positions for fixed-width records */
const SDR33_WIDTHS = {
  REC_TYPE: [0, 1],      // M0/M1/M2/M3/M4/M5/M6
  POINT_NO: [1, 15],     // 14-char point identifier
  SD: [15, 25],          // Slope distance (0.001m units, or decimal metres)
  HZ: [25, 37],          // Horizontal angle (DDD.MM.SS or decimal deg)
  VA: [37, 49],          // Vertical angle (DDD.MM.SS or decimal deg)
  IH: [49, 56],          // Instrument height (metres, 3dp)
  TH: [56, 62],          // Target height (metres, 3dp)
  CODE: [62, 72],        // Feature code / description
  E: [15, 28],           // Easting (when M3)
  N: [28, 42],           // Northing (when M3)
  Z: [42, 56],           // Elevation (when M3)
} as const

function parseSDR33Fixed(line: string): SDRObservation | null {
  if (line.length < 10) return null
  const recType = line.charAt(0)
  if (!['M', 'm'].includes(recType)) return null

  const upper = line.toUpperCase()

  if (upper.charAt(0) !== 'M') return null
  const m = upper.charAt(1)

  if (!['0', '1', '2', '3', '4', '5', '6'].includes(m)) return null

  const result: SDRObservation = {
    pointNumber: '',
    isFaceRight: m === '2',
    rawLine: line,
  }

  try {
    result.pointNumber = line.substring(1, 15).trim() || 'UNKNOWN'

    if (m === '0') {
      // Station/setup record — only IH is meaningful
      const ihStr = line.substring(49, 56).trim()
      result.instrumentHeight = parseFloat(ihStr)
      return result
    }

    if (m === '6') {
      // Target height record
      const thStr = line.substring(56, 62).trim()
      result.targetHeight = parseFloat(thStr)
      return result
    }

    if (m === '1' || m === '2') {
      // Angle + distance record
      const sdStr = line.substring(15, 25).trim()
      const hzStr = line.substring(25, 37).trim()
      const vaStr = line.substring(37, 49).trim()
      const thStr = line.substring(56, 62).trim()

      if (sdStr) {
        // SDR distance: usually in 0.01m units or decimal metres
        const sdVal = parseFloat(sdStr)
        if (!isNaN(sdVal)) {
          // If value > 10000, assume mm units; otherwise metres
          result.slopeDist = sdVal > 10000 ? sdVal / 1000 : sdVal
        }
      }

      if (hzStr) {
        result.hzAngle = parseAngleField(hzStr)
      }

      if (vaStr) {
        result.verticalAngle = parseAngleField(vaStr)
      }

      if (thStr) {
        result.targetHeight = parseFloat(thStr)
      }

      return result
    }

    if (m === '3') {
      // Coordinate record
      const eStr = line.substring(15, 28).trim()
      const nStr = line.substring(28, 42).trim()
      const zStr = line.substring(42, 56).trim()

      if (eStr) result.easting = parseFloat(eStr)
      if (nStr) result.northing = parseFloat(nStr)
      if (zStr) result.elevation = parseFloat(zStr)

      return result
    }

    if (m === '4' || m === '5') {
      // Remark / code record
      result.remark = line.substring(1).trim()
      return result
    }
  } catch {
    return null
  }

  return null
}

/**
 * Parse an angle field — handles multiple formats:
 *   - Decimal degrees: "123.456789"
 *   - DDD.MMSS: "045.3030" (degrees.minutesTenthsOfSeconds)
 *   - DDD.MM.SS: "045 30 30.5"
 *   - Integer arc-seconds: "163530" (0.1 arc-second units)
 * Returns decimal degrees.
 */
function parseAngleField(raw: string): number {
  const s = raw.trim()
  if (!s) return 0

  // Try decimal degrees
  const asFloat = parseFloat(s)
  if (!isNaN(asFloat)) {
    // If the number is large (>360) and looks like packed DMS or arcseconds
    if (asFloat > 360) {
      // Could be packed DMS (DDDMMSS) or arc-seconds
      const absStr = s.replace(/[+-]/g, '')
      const len = absStr.length

      if (len === 6 || len === 7 || len === 8) {
        // Likely packed DMS: DDDMMSS or DDD.MMSS
        if (s.includes('.')) {
          // DDD.MMSS format (e.g. "045.3030")
          const dot = s.indexOf('.')
          const deg = parseInt(s.substring(0, dot), 10)
          const minPart = s.substring(dot + 1)
          const min = parseInt(minPart.substring(0, minPart.length - 1), 10)
          const sec = parseInt(minPart.slice(-1) + '0', 10)
          return deg + min / 60 + sec / 3600
        } else {
          // Integer DDDMMSS
          const len = absStr.length
          const deg = parseInt(absStr.substring(0, len - 4), 10)
          const min = parseInt(absStr.substring(len - 4, len - 2), 10)
          const sec = parseInt(absStr.substring(len - 2), 10)
          return deg + min / 60 + sec / 3600
        }
      }

      // Could be arc-seconds (large integer value)
      if (asFloat > 1000000) {
        // Likely arc-seconds (e.g., 163530 = 45°25'53")
        const deg = Math.floor(asFloat / 36000)
        const minRem = Math.floor((asFloat - deg * 36000) / 600)
        const sec = (asFloat - deg * 36000 - minRem * 600) / 10
        return deg + minRem / 60 + sec / 3600
      }
    }
    return asFloat
  }

  return 0
}

// ── TopSurv CSV Format (newer instruments) ────────────────────────────────────

/**
 * Parse TopSurv CSV format.
 * Typical header: #PT,Point,Hz,V,SD,etc. or #ST for stations
 * Data lines: #PT,point_name,Hz,V,SD,easting,northing,elevation,...
 */
function parseTopSurvCSV(lines: string[]): SDRObservation[] {
  const observations: SDRObservation[] = []

  for (const line of lines) {
    const trimmed = line.trim()
    if (!trimmed || !trimmed.startsWith('#')) continue

    const parts = trimmed.split(/[,\t]+/)
    if (parts.length < 2) continue

    const recordType = parts[0].toUpperCase()

    if (recordType === '#PT' || recordType === '#SHOT') {
      const pt: SDRObservation = {
        pointNumber: parts[1] || 'UNKNOWN',
        isFaceRight: false,
        rawLine: line,
      }

      // Find numeric columns by attempting to parse
      for (let i = 2; i < parts.length; i++) {
        const val = parseFloat(parts[i])
        if (isNaN(val)) continue

        // Try to identify column by position and value range
        // #PT columns: Hz(col2), V(col3), SD(col4), targetH(col5), easting, northing, elev, ...
        if (i === 2 && Math.abs(val) <= 360) pt.hzAngle = val
        else if (i === 3 && Math.abs(val) <= 90) pt.verticalAngle = val
        else if (i === 4 && val > 0 && val < 20000) pt.slopeDist = val
        else if (i === 5 && val > 0 && val < 5) pt.targetHeight = val
        else if (i >= 5 && i <= 7 && val > 0) {
          // Likely coordinate columns
          if (i === 5) pt.easting = val
          else if (i === 6) pt.northing = val
          else if (i === 7) pt.elevation = val
        }
      }

      observations.push(pt)
    }

    if (recordType === '#ST') {
      // Station record — also add a placeholder observation for the station
      const pt: SDRObservation = {
        pointNumber: parts[1] || 'STATION',
        isFaceRight: false,
        rawLine: line,
      }
      if (parts[2]) pt.instrumentHeight = parseFloat(parts[2])
      observations.push(pt)
    }
  }

  return observations
}

// ── Auto-detection and main parse function ───────────────────────────────────

/**
 * Detect format by examining the first non-empty line.
 * SDR33 fixed: starts with M0/M1/M2/M3/M4
 * TopSurv CSV: starts with #
 */
function detectFormat(firstLine: string): SDRParseResult['format'] {
  const trimmed = firstLine.trim()
  if (trimmed.startsWith('#')) return 'TOPSURV_CSV'
  if (trimmed.length >= 60 && /^[Mm][0-6]/.test(trimmed)) return 'SDR33_FIXED'
  return 'UNKNOWN'
}

function groupByStationSDR(
  records: SDRObservation[],
  errors: string[]
): SDRStation[] {
  if (records.length === 0) return []

  // Find station records (where instrumentHeight is set)
  const stationRecords = records.filter(r => r.instrumentHeight !== undefined)

  if (stationRecords.length === 0) {
    // No explicit station records — treat all as single traverse from first point
    return [{
      stationName: records[0]?.pointNumber || 'ST1',
      instrumentHeight: records[0]?.instrumentHeight ?? 1.600,
      observations: records.filter(r => r.hzAngle !== undefined || r.slopeDist !== undefined),
    }]
  }

  // Group observations by the station that preceded them
  const stations: SDRStation[] = []
  let currentStation: SDRStation | null = null

  for (const rec of records) {
    if (rec.instrumentHeight !== undefined) {
      if (currentStation) stations.push(currentStation)
      currentStation = {
        stationName: rec.pointNumber,
        instrumentHeight: rec.instrumentHeight,
        observations: [],
      }
    } else if (currentStation && (rec.hzAngle !== undefined || rec.slopeDist !== undefined)) {
      currentStation.observations.push(rec)
    }
  }

  if (currentStation) stations.push(currentStation)

  return stations
}

/**
 * Parse a Topcon SDR/ID file.
 * Automatically detects format (SDR33 fixed-width or TopSurv CSV).
 */
export function parseSDR(sdrContent: string): SDRParseResult {
  const lines = sdrContent.split(/\r?\n/).filter(l => l.trim())
  const errors: string[] = []

  if (lines.length === 0) {
    return {
      stations: [],
      records: [],
      errors: ['Empty file'],
      instrument: 'Unknown',
      totalStations: 0,
      totalObservations: 0,
      format: 'UNKNOWN',
    }
  }

  const firstLine = lines.find(l => l.trim().startsWith('#') || l.trim().startsWith('M'))
    || lines[0]
  const format = detectFormat(firstLine || '')

  let records: SDRObservation[] = []

  if (format === 'SDR33_FIXED') {
    for (const line of lines) {
      const obs = parseSDR33Fixed(line)
      if (obs) records.push(obs)
    }
  } else if (format === 'TOPSURV_CSV') {
    records = parseTopSurvCSV(lines)
  } else {
    // Try both formats
    for (const line of lines) {
      const obs = parseSDR33Fixed(line)
      if (obs) records.push(obs)
    }
    if (records.length === 0) {
      records = parseTopSurvCSV(lines)
    }
    if (records.length === 0) {
      errors.push(`Could not detect file format. First line: "${firstLine?.slice(0, 80)}"`)
    }
  }

  // Remove remark-only records
  records = records.filter(r =>
    r.hzAngle !== undefined || r.slopeDist !== undefined ||
    r.easting !== undefined || r.instrumentHeight !== undefined
  )

  const stations = groupByStationSDR(records, errors)
  const totalDistCount = records.filter(r => r.slopeDist !== undefined).length

  return {
    stations,
    records,
    errors,
    instrument: 'Topcon/Sokkia SDR',
    totalStations: stations.length,
    totalObservations: records.length,
    format,
  }
}

/**
 * Reduce SDR observations to the format expected by computeTraverse().
 * Applies face-left/face-right mean angle, HD from SD+VA.
 */
export function reduceSDRObservations(
  parseResult: SDRParseResult
): Array<{
  station: string
  bs: string
  fs: string
  hclDeg: string; hclMin: string; hclSec: string
  hcrDeg: string; hcrMin: string; hcrSec: string
  slopeDist: string
  vaDeg: string; vaMin: string; vaSec: string
  ih: string; th: string
}> {
  const stations = parseResult.stations
  const allObs = parseResult.records

  const result: ReturnType<typeof reduceSDRObservations> = []
  let ih = 1.600
  let th = 1.400

  // Find instrument height from first station
  if (stations[0]) {
    ih = stations[0].instrumentHeight || 1.600
  }

  for (let i = 0; i < allObs.length; i++) {
    const obs = allObs[i]
    const nextObs = allObs[i + 1]

    if (obs.instrumentHeight !== undefined) {
      ih = obs.instrumentHeight
      continue
    }

    if (obs.hzAngle === undefined && obs.slopeDist === undefined) continue

    th = obs.targetHeight ?? 1.400

    const meanHz = obs.hzAngle ?? 0
    const hzDMS = decimalToDMS(meanHz)

    const va = obs.verticalAngle ?? 0
    const vaDMS = decimalToDMS(Math.abs(va))

    const sd = obs.slopeDist ?? obs.horizDist ?? 0

    result.push({
      station: obs.pointNumber || `P${i + 1}`,
      bs: i > 0 ? allObs[i - 1].pointNumber : '',
      fs: nextObs?.pointNumber || `P${i + 2}`,
      hclDeg: String(hzDMS.deg),
      hclMin: String(hzDMS.min),
      hclSec: hzDMS.sec.toFixed(1),
      hcrDeg: obs.isFaceRight ? String(hzDMS.deg) : '0',
      hcrMin: obs.isFaceRight ? String(hzDMS.min) : '0',
      hcrSec: obs.isFaceRight ? hzDMS.sec.toFixed(1) : '0.0',
      slopeDist: sd.toFixed(3),
      vaDeg: String(vaDMS.deg),
      vaMin: String(vaDMS.min),
      vaSec: vaDMS.sec.toFixed(1),
      ih: ih.toFixed(3),
      th: th.toFixed(3),
    })
  }

  return result
}

function decimalToDMS(decimal: number): { deg: number; min: number; sec: number } {
  if (decimal < 0) {
    const d = decimalToDMS(-decimal)
    return { deg: -d.deg, min: d.min, sec: d.sec }
  }
  const deg = Math.floor(decimal)
  const minFloat = (decimal - deg) * 60
  const min = Math.floor(minFloat)
  const sec = (minFloat - min) * 60
  return { deg, min, sec }
}

/**
 * Instrument Format Writers — export stakeout lists to total station formats
 *
 * PROBLEM
 * -------
 * The existing codebase has PARSERS for GSI, SDR, Topcon, JobXML, and South
 * formats (src/lib/import/totalStation/adapters/). But there are no WRITERS
 * — surveyors can import from instruments but can't export stakeout lists
 * back to them. This module provides the writers.
 *
 * SUPPORTED FORMATS
 * -----------------
 *   - GSI  (Leica total stations) — GSI-8 and GSI-16
 *   - SDR  (Topcon/Sokkia) — SDR v20/v33
 *   - CSV  (universal) — point_id,easting,northing,RL,description
 *   - JobXML (modern total stations) — XML-based
 *
 * USAGE
 * -----
 *   import { exportStakeoutToGSI, exportStakeoutToSDR, exportStakeoutToCSV } from
 *     '@/lib/survey/instrumentWriters'
 *
 *   const gsiContent = exportStakeoutToGSI(settingOutResult, {
 *     format: 'GSI-8',
 *     includeFaces: false,
 *   })
 *
 *   // Then: new Blob([gsiContent], { type: 'text/plain' })
 */

import type { SettingOutResult, SettingOutRow } from '@/lib/computations/settingOutEngine'

// ─── Types ──────────────────────────────────────────────────────────────────

export type InstrumentFormat = 'GSI-8' | 'GSI-16' | 'SDR' | 'CSV' | 'JobXML'

export interface ExportOptions {
  /** GSI word length: 8 (compact) or 16 (extended). Default: GSI-8 */
  format?: InstrumentFormat
  /** Include both face-left and face-right positions. Default: false */
  includeFaces?: boolean
  /** Station name for the instrument setup. Default: 'STN1' */
  stationName?: string
  /** Backsight point name. Default: 'BS1' */
  backsightName?: string
}

export interface ExportResult {
  content: string
  filename: string
  mimeType: string
  format: InstrumentFormat
  pointCount: number
}

// ─── GSI Writer (Leica) ─────────────────────────────────────────────────────

/**
 * GSI format reference: Leica GSI Online Documentation
 *
 * GSI-8: Word indices are 2 digits (e.g., 21 = Hz angle)
 * GSI-16: Word indices are 6 digits (e.g., 21 = Hz angle, with leading zeros)
 *
 * Key word indices:
 *   11  = Point number
 *   21  = Horizontal angle (Hz) — right of face
 *   22  = Vertical angle (V)
 *   31  = Slope distance (SD)
 *   32  = Horizontal distance (HD)
 *   81  = Easting (E)
 *   82  = Northing (N)
 *   83  = Height (H)
 *   84  = Reflector height (TH)
 *   85  = Instrument height (IH)
 *   87  = Point code/description
 */
export function exportStakeoutToGSI(
  result: SettingOutResult,
  options: ExportOptions = {},
): ExportResult {
  const format = options.format === 'GSI-16' ? 'GSI-16' : 'GSI-8'
  const stationName = options.stationName || 'STN1'
  const lines: string[] = []

  // Helper: format a GSI word
  function gsiWord(wi: number, value: string, format: 'GSI-8' | 'GSI-16'): string {
    const wiStr = format === 'GSI-16' ? String(wi).padStart(6, '0') : String(wi).padStart(2, '0')
    return `*${wiStr}${value}`
  }

  // Format angle in centesimal (gons) — Leica default
  // Actually GSI stores in decimicro-radians or centesimal depending on config.
  // We'll use decimal degrees with 6 decimal places (common Leica setting).
  function formatAngle(deg: number): string {
    // Convert to centesimal (gons): 360° = 400 gon
    const gon = deg * 400 / 360
    return gon.toFixed(6).padStart(16, '0').replace('.', '')
  }

  // Format distance in mm with 1 decimal
  function formatDistance(m: number): string {
    return (m * 1000).toFixed(1).padStart(16, '0').replace('.', '')
  }

  // Format coordinate in mm with 1 decimal
  function formatCoord(m: number): string {
    return (m * 1000).toFixed(1).padStart(16, '0').replace('.', '')
  }

  // Station setup line
  const ih = result.instrumentStation.ih * 1000 // mm
  lines.push([
    gsiWord(11, stationName.padStart(16, '0'), format),
    gsiWord(84, ih.toFixed(0).padStart(16, '0'), format),
    gsiWord(81, formatCoord(result.instrumentStation.e), format),
    gsiWord(82, formatCoord(result.instrumentStation.n), format),
    gsiWord(83, formatCoord(result.instrumentStation.rl), format),
  ].join(''))

  // Backsight line (orientation)
  const bsName = options.backsightName || 'BS1'
  lines.push([
    gsiWord(11, bsName.padStart(16, '0'), format),
    gsiWord(21, formatAngle(result.bsBearingDecimal), format),
    gsiWord(81, formatCoord(result.backsight.e), format),
    gsiWord(82, formatCoord(result.backsight.n), format),
  ].join(''))

  // Stakeout points
  for (const row of result.rows) {
    const pointNum = row.id.padStart(16, '0')
    const parts = [
      gsiWord(11, pointNum, format),
      gsiWord(21, formatAngle(row.HzDecimal), format),
      gsiWord(31, formatDistance(row.SD), format),
      gsiWord(84, (row.TH * 1000).toFixed(0).padStart(16, '0'), format),
      gsiWord(81, formatCoord(row.designE), format),
      gsiWord(82, formatCoord(row.designN), format),
      gsiWord(83, formatCoord(row.designRL), format),
    ]

    if (options.includeFaces) {
      // Face right: Hz + 180°
      const hzFr = (row.HzDecimal + 180) % 360
      parts.push(gsiWord(22, formatAngle(hzFr), format))
    }

    lines.push(parts.join(''))
  }

  return {
    content: lines.join('\n') + '\n',
    filename: `stakeout_${stationName}.gsi`,
    mimeType: 'text/plain',
    format,
    pointCount: result.rows.length,
  }
}

// ─── SDR Writer (Topcon/Sokkia) ─────────────────────────────────────────────

/**
 * SDR v20/v33 format — used by Topcon and Sokkia instruments.
 *
 * Key record types:
 *   00MP  = Memory point (point ID + coordinates)
 *   01NM  = Station setup
 *   02BS  = Backsight
 *   03CO  = Coordinate record
 *   08ST  = Stakeout point
 */
export function exportStakeoutToSDR(
  result: SettingOutResult,
  options: ExportOptions = {},
): ExportResult {
  const stationName = options.stationName || 'STN1'
  const lines: string[] = []

  // SDR header
  lines.push('00NMETARDU STAKEOUT EXPORT')
  lines.push(`01NM${stationName},${result.instrumentStation.e.toFixed(4)},${result.instrumentStation.n.toFixed(4)},${result.instrumentStation.rl.toFixed(4)},${result.instrumentStation.ih.toFixed(3)}`)

  // Backsight
  const bsName = options.backsightName || 'BS1'
  lines.push(`02BS${bsName},${result.backsight.e.toFixed(4)},${result.backsight.n.toFixed(4)}`)

  // Stakeout points
  for (const row of result.rows) {
    // Coordinate record (for the instrument to navigate to)
    lines.push(`03CO${row.id},${row.designE.toFixed(4)},${row.designN.toFixed(4)},${row.designRL.toFixed(4)}`)
    // Stakeout instruction
    lines.push(`08ST${row.id},${row.HzDecimal.toFixed(6)},${row.SD.toFixed(4)},${row.TH.toFixed(3)}`)
  }

  // SDR footer
  lines.push('99END')

  return {
    content: lines.join('\r\n') + '\r\n',
    filename: `stakeout_${stationName}.sdr`,
    mimeType: 'text/plain',
    format: 'SDR',
    pointCount: result.rows.length,
  }
}

// ─── CSV Writer (universal) ─────────────────────────────────────────────────

/**
 * Universal CSV format — readable by virtually all instruments and software.
 * Columns: point_id, easting, northing, RL, target_height, Hz_angle, HD, SD, description
 */
export function exportStakeoutToCSV(
  result: SettingOutResult,
  _options: ExportOptions = {},
): ExportResult {
  const lines: string[] = []

  // Header
  lines.push('point_id,easting,northing,RL,target_height,Hz_angle_deg,HD_m,SD_m,description')

  // Station info as comments
  lines.push(`# Station: ${result.instrumentStation.e.toFixed(4)},${result.instrumentStation.n.toFixed(4)},${result.instrumentStation.rl.toFixed(4)} (IH=${result.instrumentStation.ih})`)
  lines.push(`# Backsight: ${result.backsight.e.toFixed(4)},${result.backsight.n.toFixed(4)} (bearing=${result.bsBearing})`)

  // Points
  for (const row of result.rows) {
    lines.push([
      row.id,
      row.designE.toFixed(4),
      row.designN.toFixed(4),
      row.designRL.toFixed(4),
      row.TH.toFixed(3),
      row.HzDecimal.toFixed(6),
      row.HD.toFixed(4),
      row.SD.toFixed(4),
      `"${row.id}"`, // description = id for now
    ].join(','))
  }

  return {
    content: lines.join('\n') + '\n',
    filename: 'stakeout.csv',
    mimeType: 'text/csv',
    format: 'CSV',
    pointCount: result.rows.length,
  }
}

// ─── JobXML Writer ──────────────────────────────────────────────────────────

/**
 * JobXML format — XML-based, used by modern total stations and data collectors.
 * Based on the Trimble JobXML 2.1 specification.
 */
export function exportStakeoutToJobXML(
  result: SettingOutResult,
  options: ExportOptions = {},
): ExportResult {
  const stationName = options.stationName || 'STN1'
  const bsName = options.backsightName || 'BS1'

  const pointXml = result.rows.map((row, i) => {
    return `      <Point name="${row.id}" code="STAKEOUT">
        <Coordinates north="${row.designN.toFixed(4)}" east="${row.designE.toFixed(4)}" elev="${row.designRL.toFixed(4)}"/>
        <StakeoutData horizontalAngle="${row.HzDecimal.toFixed(6)}" slopeDistance="${row.SD.toFixed(4)}" targetHeight="${row.TH.toFixed(3)}"/>
      </Point>`
  }).join('\n')

  const xml = `<?xml version="1.0" encoding="UTF-8"?>
<JobXML version="2.1" xmlns="http://www.trimble.com/schemas/JobXML">
  <Job name="METARDU Stakeout" createdBy="METARDU" createdAt="${new Date().toISOString()}">
    <StationSetup name="${stationName}">
      <Station>
        <Coordinates north="${result.instrumentStation.n.toFixed(4)}" east="${result.instrumentStation.e.toFixed(4)}" elev="${result.instrumentStation.rl.toFixed(4)}"/>
        <InstrumentHeight>${result.instrumentStation.ih.toFixed(3)}</InstrumentHeight>
      </Station>
      <Backsight name="${bsName}">
        <Coordinates north="${result.backsight.n.toFixed(4)}" east="${result.backsight.e.toFixed(4)}"/>
        <Bearing>${result.bsBearing}</Bearing>
      </Backsight>
    </StationSetup>
    <Points>
${pointXml}
    </Points>
  </Job>
</JobXML>`

  return {
    content: xml,
    filename: `stakeout_${stationName}.jxl`,
    mimeType: 'application/xml',
    format: 'JobXML',
    pointCount: result.rows.length,
  }
}

// ─── Unified Export Function ────────────────────────────────────────────────

/**
 * Export a stakeout result to the specified instrument format.
 *
 * @example
 *   const result = exportStakeout(result, 'GSI-8')
 *   const blob = new Blob([result.content], { type: result.mimeType })
 *   // Download blob as result.filename
 */
export function exportStakeout(
  result: SettingOutResult,
  format: InstrumentFormat,
  options: ExportOptions = {},
): ExportResult {
  switch (format) {
    case 'GSI-8':
      return exportStakeoutToGSI(result, { ...options, format: 'GSI-8' })
    case 'GSI-16':
      return exportStakeoutToGSI(result, { ...options, format: 'GSI-16' })
    case 'SDR':
      return exportStakeoutToSDR(result, options)
    case 'CSV':
      return exportStakeoutToCSV(result, options)
    case 'JobXML':
      return exportStakeoutToJobXML(result, options)
    default:
      return exportStakeoutToCSV(result, options)
  }
}

/**
 * Get the available export formats with descriptions for the UI.
 */
export function getAvailableFormats(): Array<{ value: InstrumentFormat; label: string; description: string }> {
  return [
    { value: 'CSV', label: 'CSV', description: 'Universal format — works with all instruments and software' },
    { value: 'GSI-8', label: 'GSI-8 (Leica)', description: 'Leica total stations, compact format' },
    { value: 'GSI-16', label: 'GSI-16 (Leica)', description: 'Leica total stations, extended format' },
    { value: 'SDR', label: 'SDR (Topcon/Sokkia)', description: 'Topcon and Sokkia data collectors' },
    { value: 'JobXML', label: 'JobXML', description: 'Trimble and modern data collectors' },
  ]
}

/**
 * LiveToleranceChecker — field-side, offline-first tolerance checking
 *
 * THE PROMISE
 * -----------
 * "The surveyor never has to do arithmetic in their head between the moment
 * they capture a shot and the moment it's either flagged wrong or accepted
 * as correct."
 *
 * This module wraps the existing traverse engine + RDM 1.1 tolerance tables
 * + LSA statistical testing into a single function that runs client-side,
 * offline, in < 100ms. After each shot is added to the field book, re-run
 * this check. Show a persistent badge: green (passing), yellow (marginal),
 * red (failing). When red, highlight the leg with the largest residual and
 * say "recheck setup at station X."
 *
 * WHAT IT CHECKS
 * --------------
 * 1. Traverse closure: linear misclosure / perimeter → precision ratio
 *    → RDM 1.1 Table 5.1 order classification → pass/fail
 * 2. Angular misclosure: sum of measured angles vs (n-2)×180°
 *    → per-station allowance → pass/fail
 * 3. Leveling closure: misclosure vs C√K mm → pass/fail
 * 4. LSA global test (if enough observations for redundancy)
 * 5. Worst-leg identification: which leg has the largest residual
 *
 * OFFLINE-FIRST
 * -------------
 * The entire check runs in the browser. No server round-trip. Uses the
 * observations already in IndexedDB. The result syncs when connectivity
 * returns.
 *
 * USAGE
 * -----
 *   import { checkTolerance } from '@/lib/survey/liveToleranceChecker'
 *
 *   const result = checkTolerance({
 *     surveyType: 'cadastral',
 *     observations: [...],  // from the field book
 *     openingEasting: 264000,
 *     openingNorthing: 9861000,
 *     closingEasting: 264000,  // same = closed traverse
 *     closingNorthing: 9861000,
 *   })
 *
 *   if (result.status === 'fail') {
 *     // Show: "Closure failed (1:8,234). Recheck setup at station CP3."
 *   }
 */

import { computeTraverse, type RawObservation, type TraverseComputationResult } from '@/lib/computations/traverseEngine'
import {
  checkTraverseConformance,
  checkLevelingConformance,
  RDM_TRAVERSE_ACCURACY,
  RDM_LEVELING_ACCURACY,
  type RDMConformanceResult,
} from '@/lib/standards/rdm11'
import { globalChiSquareTest } from '@/lib/survey/lsaStatisticalTesting'

// ─── Types ──────────────────────────────────────────────────────────────────

export type SurveyType =
  | 'cadastral'
  | 'engineering'
  | 'topographic'
  | 'control'
  | 'monitoring'
  | 'leveling'
  | 'construction'

export type ToleranceStatus = 'pass' | 'marginal' | 'fail' | 'insufficient_data'

export interface ToleranceCheckInput {
  /** Survey type — determines which RDM 1.1 order is required */
  surveyType: SurveyType

  /** Traverse observations (from the field book) */
  observations: RawObservation[]

  /** Opening control point */
  openingEasting: number
  openingNorthing: number
  openingStation: string

  /** Closing control point (same as opening for closed traverse) */
  closingEasting?: number
  closingNorthing?: number
  closingStation?: string

  /** Backsight bearing (for WCB computation) */
  backsightBearingDeg: number
  backsightBearingMin: number
  backsightBearingSec: number

  /** For leveling checks */
  levelingMisclosureMm?: number
  levelingDistanceKm?: number

  /** LSA results (if available from a network adjustment) */
  sigmaZero?: number
  degreesOfFreedom?: number
}

export interface WorstLegInfo {
  /** Station name where the worst residual occurs */
  station: string
  /** The leg from → to */
  from: string
  to: string
  /** Residual magnitude in mm */
  residualMm: number
  /** What this means */
  diagnosis: string
  /** What the surveyor should do */
  recommendation: string
}

export interface ToleranceCheckResult {
  /** Overall status: pass / marginal / fail / insufficient_data */
  status: ToleranceStatus

  /** Human-readable summary for the badge */
  summary: string

  /** Detailed checks (from RDM 1.1 conformance checker) */
  rdmChecks: RDMConformanceResult

  /** Achieved accuracy order (e.g., "Second Order Class II") */
  achievedOrder: string | null

  /** Required accuracy order for this survey type */
  requiredOrder: string

  /** Precision ratio (e.g., 8234 → "1:8,234") */
  precisionRatio: number | null

  /** Linear misclosure in mm */
  linearMisclosureMm: number

  /** Total traverse perimeter in km */
  perimeterKm: number

  /** The leg with the largest residual (null if can't determine) */
  worstLeg: WorstLegInfo | null

  /** LSA global test result (if applicable) */
  lsaGlobalTest?: {
    passed: boolean
    chiSquareObserved: number
    chiSquareCritical: number
    interpretation: string
  }

  /** Whether there's enough data to perform the check */
  hasEnoughData: boolean

  /** List of actionable recommendations */
  recommendations: string[]

  /** Timestamp */
  timestamp: string
}

// ─── RDM 1.1 Order Requirements per Survey Type ─────────────────────────────

/**
 * Map survey type → minimum required RDM 1.1 order.
 *
 * Source: RDM 1.1 Table 5.1 + Survey Regulations 1994 + Survey Act Cap 299
 */
const SURVEY_TYPE_REQUIREMENTS: Record<SurveyType, {
  traverseOrder: string
  levelingOrder: string
  description: string
}> = {
  cadastral: {
    traverseOrder: 'Second Order Class II',  // 1:10,000 — minimum for title surveys
    levelingOrder: 'Third Order',             // 10√K mm
    description: 'Cadastral (title) surveys require minimum Second Order Class II (1:10,000) per Survey Regulations 1994.',
  },
  engineering: {
    traverseOrder: 'Second Order Class I',   // 1:20,000 — major engineering
    levelingOrder: 'Second Order',            // 8√K mm
    description: 'Engineering surveys require minimum Second Order Class I (1:20,000) per RDM 1.1.',
  },
  topographic: {
    traverseOrder: 'Third Order',              // 1:5,000
    levelingOrder: 'Fourth Order',             // 12√K mm
    description: 'Topographic surveys require minimum Third Order (1:5,000).',
  },
  control: {
    traverseOrder: 'First Order Class II',    // 1:50,000 — secondary geodetic
    levelingOrder: 'Second Order',             // 8√K mm
    description: 'Control surveys require minimum First Order Class II (1:50,000).',
  },
  monitoring: {
    traverseOrder: 'First Order Class II',    // 1:50,000 — deformation monitoring
    levelingOrder: 'First Order',              // 4√K mm
    description: 'Deformation monitoring requires First Order Class II (1:50,000) and First Order leveling.',
  },
  leveling: {
    traverseOrder: 'Third Order',
    levelingOrder: 'Third Order',              // 10√K mm — cadastral minimum
    description: 'Leveling surveys require minimum Third Order (10√K mm).',
  },
  construction: {
    traverseOrder: 'Second Order Class I',    // 1:20,000 — setting out
    levelingOrder: 'Second Order',             // 8√K mm
    description: 'Construction setting out requires Second Order Class I (1:20,000).',
  },
}

// ─── Main Function ──────────────────────────────────────────────────────────

/**
 * Check the tolerance of the current field observations.
 *
 * This is the core function of the live tolerance checker. It runs
 * client-side, offline, in < 100ms. Call it after every shot is added
 * to the field book.
 *
 * @param input - Observations + control points + survey type
 * @returns ToleranceCheckResult with status, summary, worst-leg, recommendations
 */
export function checkTolerance(input: ToleranceCheckInput): ToleranceCheckResult {
  const requirements = SURVEY_TYPE_REQUIREMENTS[input.surveyType]
  const recommendations: string[] = []
  const timestamp = new Date().toISOString()

  // ─── Check if we have enough data ───
  const validObs = input.observations.filter(o => o.station && o.slopeDist)
  if (validObs.length < 3) {
    return {
      status: 'insufficient_data',
      summary: `Need at least 3 observations to check (have ${validObs.length}). Keep shooting.`,
      rdmChecks: { passed: false, checks: [], overallGrade: null },
      achievedOrder: null,
      requiredOrder: requirements.traverseOrder,
      precisionRatio: null,
      linearMisclosureMm: 0,
      perimeterKm: 0,
      worstLeg: null,
      hasEnoughData: false,
      recommendations: ['Continue capturing observations. The tolerance check will activate at 3+ legs.'],
      timestamp,
    }
  }

  // ─── Compute the traverse ───
  let traverseResult: TraverseComputationResult
  try {
    traverseResult = computeTraverse({
      openingEasting: input.openingEasting,
      openingNorthing: input.openingNorthing,
      openingStation: input.openingStation,
      closingEasting: input.closingEasting,
      closingNorthing: input.closingNorthing,
      closingStation: input.closingStation,
      observations: input.observations,
      backsightBearingDeg: input.backsightBearingDeg,
      backsightBearingMin: input.backsightBearingMin,
      backsightBearingSec: input.backsightBearingSec,
    })
  } catch (err) {
    return {
      status: 'fail',
      summary: `Traverse computation failed: ${err instanceof Error ? err.message : String(err)}`,
      rdmChecks: { passed: false, checks: [], overallGrade: null },
      achievedOrder: null,
      requiredOrder: requirements.traverseOrder,
      precisionRatio: null,
      linearMisclosureMm: 0,
      perimeterKm: 0,
      worstLeg: null,
      hasEnoughData: true,
      recommendations: ['Check that observations are complete and angles/distances are entered correctly.'],
      timestamp,
    }
  }

  // ─── Check RDM 1.1 traverse conformance ───
  const linearErrorM = traverseResult.linearError
  const totalDistanceM = traverseResult.totalPerimeter
  const angularErrorSec = computeAngularMisclosure(validObs)
  const numStations = validObs.length

  const rdmChecks = checkTraverseConformance(
    linearErrorM,
    totalDistanceM,
    angularErrorSec,
    numStations,
    requirements.traverseOrder,
  )

  // ─── Check leveling if provided ───
  if (input.levelingMisclosureMm !== undefined && input.levelingDistanceKm !== undefined) {
    const levelingChecks = checkLevelingConformance(
      input.levelingMisclosureMm,
      input.levelingDistanceKm,
      requirements.levelingOrder,
    )
    rdmChecks.checks.push(...levelingChecks.checks)
    rdmChecks.passed = rdmChecks.passed && levelingChecks.passed
  }

  // ─── Identify the worst leg ───
  const worstLeg = identifyWorstLeg(traverseResult)

  // ─── LSA global test (if sigmaZero + dof provided) ───
  let lsaGlobalTest: ToleranceCheckResult['lsaGlobalTest']
  if (input.sigmaZero !== undefined && input.degreesOfFreedom !== undefined && input.degreesOfFreedom > 0) {
    const test = globalChiSquareTest(input.sigmaZero, input.degreesOfFreedom, 0.05)
    lsaGlobalTest = {
      passed: test.passed,
      chiSquareObserved: test.chiSquareObserved,
      chiSquareCritical: test.chiSquareCritical,
      interpretation: test.interpretation,
    }
    if (!test.passed) {
      recommendations.push('LSA global test failed — the adjustment may contain blunders or incorrect a priori standard deviations.')
    }
  }

  // ─── Determine overall status ───
  const requiredStd = RDM_TRAVERSE_ACCURACY.find(s => s.order === requirements.traverseOrder)
  const requiredRatio = requiredStd?.ratioNumeric ?? 10000
  const achievedRatio = traverseResult.precisionRatio

  let status: ToleranceStatus
  let summary: string

  if (rdmChecks.passed && achievedRatio >= requiredRatio) {
    // Check if marginal (within 20% of the limit)
    if (achievedRatio < requiredRatio * 1.2) {
      status = 'marginal'
      summary = `Marginal: 1:${Math.round(achievedRatio).toLocaleString()} (required ≥ 1:${requiredRatio.toLocaleString()}). Passing but close — consider rechecking observations.`
      recommendations.push(`Precision ratio is within 20% of the minimum. Verify the worst leg at ${worstLeg?.station ?? 'unknown'}.`)
    } else {
      status = 'pass'
      const order = rdmChecks.overallGrade ?? 'Unknown'
      summary = `PASS — ${order} (1:${Math.round(achievedRatio).toLocaleString()}). Closure ${(traverseResult.linearError * 1000).toFixed(1)}mm over ${(totalDistanceM / 1000).toFixed(3)}km.`
    }
  } else {
    status = 'fail'
    summary = `FAIL — 1:${Math.round(achievedRatio).toLocaleString()} (required ≥ 1:${requiredRatio.toLocaleString()}). Linear misclosure ${(linearErrorM * 1000).toFixed(1)}mm.`
    if (worstLeg) {
      recommendations.push(`Recheck setup at ${worstLeg.station}. ${worstLeg.recommendation}`)
    }
    recommendations.push(`Required: ${requirements.traverseOrder} (${requirements.description})`)
  }

  // ─── Angular misclosure warning ───
  if (angularErrorSec > 10) {
    recommendations.push(`Angular misclosure is high (${angularErrorSec.toFixed(1)}″/station). Check for misread angles or instrument centering errors.`)
  }

  // ─── Courses without azimuth check ───
  if (numStations > 15) {
    recommendations.push(`${numStations} courses without azimuth check exceeds RDM 1.1 limit of 15. Add an intermediate azimuth check.`)
  }

  return {
    status,
    summary,
    rdmChecks,
    achievedOrder: rdmChecks.overallGrade,
    requiredOrder: requirements.traverseOrder,
    precisionRatio: achievedRatio,
    linearMisclosureMm: linearErrorM * 1000,
    perimeterKm: totalDistanceM / 1000,
    worstLeg,
    lsaGlobalTest,
    hasEnoughData: true,
    recommendations: recommendations.length > 0 ? recommendations : ['All checks passing. Continue to next station.'],
    timestamp,
  }
}

// ─── Helpers ────────────────────────────────────────────────────────────────

/**
 * Compute the angular misclosure per station.
 *
 * For a closed traverse: sum of interior angles = (n-2) × 180°
 * Misclosure = sum of measured angles - (n-2) × 180°
 * Per station = misclosure / n
 */
function computeAngularMisclosure(observations: RawObservation[]): number {
  // We need the measured angles. The RawObservation has HCL/HCR which
  // give the mean angle. For a simple check, we compute the mean angle
  // per station and check if the sum closes.
  //
  // NOTE: This is a simplified check. A full angular misclosure requires
  // knowing which angles are interior vs exterior. For the field-side
  // check, we estimate from the residuals.

  // If we can't compute it (incomplete data), return 0 (no warning)
  if (observations.length < 3) return 0

  try {
    // Compute mean angle per station
    let sumAngles = 0
    let count = 0
    for (const obs of observations) {
      const hcl = (parseInt(obs.hclDeg) || 0) + (parseInt(obs.hclMin) || 0) / 60 + (parseFloat(obs.hclSec) || 0) / 3600
      const hcr = (parseInt(obs.hcrDeg) || 0) + (parseInt(obs.hcrMin) || 0) / 60 + (parseFloat(obs.hcrSec) || 0) / 3600
      if (hcl > 0 || hcr > 0) {
        let hcrAdj = hcr + 180
        if (hcrAdj >= 360) hcrAdj -= 360
        const meanAngle = (hcl + hcrAdj) / 2
        sumAngles += meanAngle
        count++
      }
    }

    if (count < 3) return 0

    // Expected sum for a closed polygon: (n-2) × 180
    const expected = (count - 2) * 180
    const misclosure = Math.abs(sumAngles - expected)
    // Per station
    return (misclosure / count) * 3600 // convert to arc-seconds
  } catch {
    return 0
  }
}

/**
 * Identify the leg with the largest residual.
 *
 * After the Bowditch adjustment, each leg has a departure correction and
 * a latitude correction. The leg with the largest combined correction is
 * the most likely source of a blunder.
 */
function identifyWorstLeg(result: TraverseComputationResult): WorstLegInfo | null {
  if (!result.legs || result.legs.length === 0) return null

  let worstLeg = result.legs[0]
  let worstResidual = 0

  for (const leg of result.legs) {
    // Combined correction magnitude (mm)
    const residualMm = Math.sqrt(
      leg.depCorrection ** 2 + leg.latCorrection ** 2,
    ) * 1000

    if (residualMm > worstResidual) {
      worstResidual = residualMm
      worstLeg = leg
    }
  }

  if (worstResidual < 1) {
    // No significant residual — all legs are fine
    return null
  }

  // Diagnose the likely cause
  let diagnosis: string
  let recommendation: string

  const depCorr = Math.abs(worstLeg.depCorrection)
  const latCorr = Math.abs(worstLeg.latCorrection)

  if (depCorr > latCorr * 2) {
    diagnosis = `Largest departure correction (${(worstLeg.depCorrection * 1000).toFixed(1)}mm) on leg ${worstLeg.from} → ${worstLeg.to}.`
    recommendation = `Distance on this leg may be wrong. Re-measure the distance from ${worstLeg.from} to ${worstLeg.to}.`
  } else if (latCorr > depCorr * 2) {
    diagnosis = `Largest latitude correction (${(worstLeg.latCorrection * 1000).toFixed(1)}mm) on leg ${worstLeg.from} → ${worstLeg.to}.`
    recommendation = `Bearing on this leg may be wrong. Re-check the angle at ${worstLeg.from}.`
  } else {
    diagnosis = `Largest combined correction (${worstResidual.toFixed(1)}mm) on leg ${worstLeg.from} → ${worstLeg.to}.`
    recommendation = `Recheck both angle and distance at station ${worstLeg.from}.`
  }

  return {
    station: worstLeg.from,
    from: worstLeg.from,
    to: worstLeg.to,
    residualMm: worstResidual,
    diagnosis,
    recommendation,
  }
}

// ─── Badge Helpers (for the UI) ─────────────────────────────────────────────

/**
 * Get the badge color for a tolerance status.
 */
export function getToleranceBadgeColor(status: ToleranceStatus): string {
  switch (status) {
    case 'pass': return 'green'
    case 'marginal': return 'yellow'
    case 'fail': return 'red'
    case 'insufficient_data': return 'gray'
    default: return 'gray'
  }
}

/**
 * Get a short label for the badge.
 */
export function getToleranceBadgeLabel(status: ToleranceStatus): string {
  switch (status) {
    case 'pass': return 'CLOSURE OK'
    case 'marginal': return 'MARGINAL'
    case 'fail': return 'CLOSURE FAIL'
    case 'insufficient_data': return 'NEED MORE DATA'
    default: return 'UNKNOWN'
  }
}

/**
 * Get the emoji/icon for the badge (for quick visual scanning in the field).
 */
export function getToleranceIcon(status: ToleranceStatus): string {
  switch (status) {
    case 'pass': return '✓'
    case 'marginal': return '!'
    case 'fail': return '✗'
    case 'insufficient_data': return '···'
    default: return '?'
  }
}

/**
 * @deprecated P1-5 (2026-07-24): Use `@/lib/engine/networkAdjustment.ts`
 *   (the `adjustNetwork` function) instead. That module is the canonical
 *   enterprise-grade LSA with sparse Cholesky, free-network inner
 *   constraints, Huber robust estimation, full Baarda reliability,
 *   and 2D/3D support. This `survey/` copy has a Supabase DB side
 *   effect inside the engine module (anti-pattern — engine modules
 *   should be pure), and lacks sparse algebra. Kept only because
 *   `NetworkAdjustmentPanel`, `ErrorEllipseCanvas`, and
 *   `regulatoryCompliance.ts` import types from here. New code
 *   should not import from this module.
 */

import { z } from 'zod'
import type { BrowserClient } from '@/lib/api-client/client'

export const StationSchema = z.object({
  id: z.string().min(1, 'Station ID is required'),
  name: z.string().min(1, 'Station name is required'),
  easting: z.number().finite(),
  northing: z.number().finite(),
  elevation: z.number().finite(),
  isFixed: z.boolean(),
})

export type Station = z.infer<typeof StationSchema>

export const ObservationSchema = z.object({
  from: z.string().min(1, 'From station is required'),
  to: z.string().min(1, 'To station is required'),
  deltaE: z.number().finite(),
  deltaN: z.number().finite(),
  deltaH: z.number().finite(),
  stdDevE: z.number().positive().max(1).default(0.005),
  stdDevN: z.number().positive().max(1).default(0.005),
  stdDevH: z.number().positive().max(1).default(0.010),
})

export type Observation = z.infer<typeof ObservationSchema>

let dbClient: BrowserClient | null = null

async function logNetworkAdjustment(stations: Station[], observations: Observation[]) {
  if (typeof window === 'undefined') return
  try {
    const { createClient } = await import('@/lib/api-client/client')
    dbClient = createClient()
    const client = dbClient
    if (!client) return
    await client.from('network_adjustments').insert({
      stations,
      observations,
      status: 'pending',
    })
  } catch {
    // Non-blocking
  }
}

export interface AdjustedStation extends Station {
  residualE: number
  residualN: number
  residualH: number
  semiMajor: number
  semiMinor: number
  orientation: number
  sigmaE: number
  sigmaN: number
  sigmaH: number
}

export interface AdjustmentResult {
  adjustedStations: AdjustedStation[]
  sigmaZero: number
  degreesOfFreedom: number
  iterations: number
  passedTolerance: boolean
  warnings: string[]
  /** T1.5g: LSA statistical report (global test, w-test, reliability) */
  statisticalReport?: import('./lsaStatisticalTesting').StatisticalReport
}

export function adjustNetwork(
  stationsInput: Station[],
  observationsInput: Observation[]
): AdjustmentResult {
  const stationValidation = StationSchema.array().safeParse(stationsInput)
  if (!stationValidation.success) {
    const issues = stationValidation.error.issues.map(i => `${i.path.join('.')}: ${i.message}`).join('; ')
    throw new Error(`Invalid stations: ${issues}`)
  }
  const stations = stationValidation.data

  const obsValidation = ObservationSchema.array().safeParse(observationsInput)
  if (!obsValidation.success) {
    const issues = obsValidation.error.issues.map(i => `${i.path.join('.')}: ${i.message}`).join('; ')
    throw new Error(`Invalid observations: ${issues}`)
  }
  const observations = obsValidation.data

  const warnings: string[] = []

  logNetworkAdjustment(stations, observations).catch(() => {})

  const fixed = stations.filter(s => s.isFixed)
  if (fixed.length === 0) {
    throw new Error('At least one fixed control station is required.')
  }
  if (fixed.length < 2) {
    warnings.push('Only 1 fixed control station provided. Per Survey Regulations Reg. 60(2)(c) and Reg. 67, cadastral traverses must close between two previously fixed stations. A single fixed point results in an unconstrained network (swinging traverse) — prohibited for cadastral surveys.')
  }
  if (observations.length === 0) {
    throw new Error('At least one baseline observation is required.')
  }

  const free = stations.filter(s => !s.isFixed)
  const n = free.length * 3 // 3D: E, N, H
  const m = observations.length * 3 // 3 equations per baseline
  const dof = m - n

  if (dof < 0) {
    throw new Error(
      `Insufficient observations. Need at least ${Math.ceil(n / 3)} baselines for ${free.length} free stations.`
    )
  }

  const stationIndex = new Map<string, number>()
  free.forEach((s, i) => stationIndex.set(s.id, i))

  const coords = new Map<string, { e: number; n: number; h: number }>()
  stations.forEach(s => coords.set(s.id, { e: s.easting, n: s.northing, h: s.elevation }))

  const A: number[][] = []
  const W: number[] = []
  const l: number[] = []

  for (const obs of observations) {
    const fromCoord = coords.get(obs.from)!
    const toCoord = coords.get(obs.to)!

    const wE = 1 / (obs.stdDevE * obs.stdDevE)
    const wN = 1 / (obs.stdDevN * obs.stdDevN)
    const wH = 1 / (obs.stdDevH * obs.stdDevH)

    // Delta Easting
    const rowE: number[] = new Array<number>(n).fill(0)
    if (stationIndex.has(obs.to)) rowE[stationIndex.get(obs.to)! * 3] = 1
    if (stationIndex.has(obs.from)) rowE[stationIndex.get(obs.from)! * 3] = -1
    const obsE = toCoord.e - fromCoord.e
    A.push(rowE)
    W.push(wE)
    l.push(obs.deltaE - obsE)

    // Delta Northing
    const rowN: number[] = new Array<number>(n).fill(0)
    if (stationIndex.has(obs.to)) rowN[stationIndex.get(obs.to)! * 3 + 1] = 1
    if (stationIndex.has(obs.from)) rowN[stationIndex.get(obs.from)! * 3 + 1] = -1
    const obsN = toCoord.n - fromCoord.n
    A.push(rowN)
    W.push(wN)
    l.push(obs.deltaN - obsN)

    // Delta Height
    const rowH: number[] = new Array<number>(n).fill(0)
    if (stationIndex.has(obs.to)) rowH[stationIndex.get(obs.to)! * 3 + 2] = 1
    if (stationIndex.has(obs.from)) rowH[stationIndex.get(obs.from)! * 3 + 2] = -1
    const obsH = toCoord.h - fromCoord.h
    A.push(rowH)
    W.push(wH)
    l.push(obs.deltaH - obsH)
  }

  const N = multiplyAtWA(A, W, n)
  const t = multiplyAtWl(A, W, l, n)
  
  let x: number[]
  try {
    x = solveLinearSystem(N, t)
  } catch (err: unknown) {
    throw new Error('Failed to solve network equations: ' + (err as Error).message)
  }

  free.forEach((s, i) => {
    const c = coords.get(s.id)!
    coords.set(s.id, { e: c.e + x[i * 3], n: c.n + x[i * 3 + 1], h: c.h + x[i * 3 + 2] })
  })

  const residuals: number[] = []
  for (let i = 0; i < A.length; i++) {
    let ax = 0
    for (let j = 0; j < n; j++) ax += A[i][j] * x[j]
    residuals.push(ax - l[i])
  }

  const vWv = residuals.reduce((sum, v, i) => sum + W[i] * v * v, 0)
  const sigmaZero = dof > 0 ? Math.sqrt(vWv / dof) : 0

  if (dof === 0) {
    warnings.push('Zero degrees of freedom — cannot compute reliable error estimates.')
  }

  const Qxx = invertMatrix(N, n)

  const maxAllowedResidualE = 3 * Math.max(...observations.map(o => o.stdDevE))
  const maxAllowedResidualN = 3 * Math.max(...observations.map(o => o.stdDevN))
  const maxAllowedResidualH = 3 * Math.max(...observations.map(o => o.stdDevH))
  
  const passedTolerance = residuals.every((r, i) => {
    const mod = i % 3
    if (mod === 0) return Math.abs(r) < maxAllowedResidualE
    if (mod === 1) return Math.abs(r) < maxAllowedResidualN
    return Math.abs(r) < maxAllowedResidualH
  })

  if (!passedTolerance) {
    warnings.push('One or more residuals exceed 3σ tolerance. Check for blunders in baseline observations.')
  }
  if (sigmaZero > 2.0) {
    warnings.push(`Reference standard deviation (σ₀ = ${sigmaZero.toFixed(3)}) is high. Network may contain blunders or incorrect standard deviations.`)
  }

  const adjustedStations: AdjustedStation[] = stations.map(s => {
    const adjusted = coords.get(s.id)!
    let residualE = 0
    let residualN = 0
    let residualH = 0
    let semiMajor = 0
    let semiMinor = 0
    let orientation = 0
    let sigmaE = 0
    let sigmaN = 0
    let sigmaH = 0

    if (!s.isFixed) {
      const i = stationIndex.get(s.id)!
      residualE = x[i * 3]
      residualN = x[i * 3 + 1]
      residualH = x[i * 3 + 2]

      const qEE = Qxx[i * 3][i * 3]
      const qNN = Qxx[i * 3 + 1][i * 3 + 1]
      const qHH = Qxx[i * 3 + 2][i * 3 + 2]
      const qEN = Qxx[i * 3][i * 3 + 1]

      sigmaE = sigmaZero * Math.sqrt(Math.max(qEE, 0))
      sigmaN = sigmaZero * Math.sqrt(Math.max(qNN, 0))
      sigmaH = sigmaZero * Math.sqrt(Math.max(qHH, 0))

      const t2 = Math.atan2(2 * qEN, qEE - qNN) / 2
      const A2 = (qEE + qNN) / 2 + Math.sqrt(Math.pow((qEE - qNN) / 2, 2) + qEN * qEN)
      const B2 = (qEE + qNN) / 2 - Math.sqrt(Math.pow((qEE - qNN) / 2, 2) + qEN * qEN)
      semiMajor = sigmaZero * Math.sqrt(Math.max(A2, 0))
      semiMinor = sigmaZero * Math.sqrt(Math.max(B2, 0))
      orientation = (t2 * 180 / Math.PI + 360) % 360
    }

    return {
      ...s,
      easting: adjusted.e,
      northing: adjusted.n,
      elevation: adjusted.h,
      residualE,
      residualN,
      residualH,
      semiMajor,
      semiMinor,
      orientation,
      sigmaE,
      sigmaN,
      sigmaH,
    }
  })

  // T1.5g FIX (2026-07-10): Compute LSA statistical report (global test + w-test + reliability)
  let statisticalReport: AdjustmentResult['statisticalReport']
  if (dof > 0 && residuals.length > 0) {
    try {
      // Lazy import keeps the LSA stats module out of the hot path.
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const { computeStatisticalReport, computeQvvDiagonal } = require('./lsaStatisticalTesting') as typeof import('./lsaStatisticalTesting')

      // Build observation labels for the w-test
      const observationLabels = observations.flatMap(obs => [
        { from: obs.from, to: obs.to, component: 'E' as const },
        { from: obs.from, to: obs.to, component: 'N' as const },
        { from: obs.from, to: obs.to, component: 'H' as const },
      ])

      // Compute Qvv diagonal (needed for w-test and reliability)
      const QvvDiag = computeQvvDiagonal(A, W, Qxx)

      statisticalReport = computeStatisticalReport(
        sigmaZero,
        dof,
        residuals,
        QvvDiag,
        observationLabels,
        0.05,
      )

      // Add statistical report warnings to the existing warnings
      if (statisticalReport && statisticalReport.warnings.length > 0) {
        warnings.push(...statisticalReport.warnings)
      }
    } catch {
      // Statistical testing is non-blocking — if it fails, the adjustment is still valid
    }
  }

  return {
    adjustedStations,
    sigmaZero,
    degreesOfFreedom: dof,
    iterations: 1,
    passedTolerance,
    warnings,
    statisticalReport,
  }
}

function multiplyAtWA(A: number[][], W: number[], n: number): number[][] {
  const result = Array.from({ length: n }, () => new Array<number>(n).fill(0))
  for (let i = 0; i < n; i++)
    for (let j = 0; j < n; j++)
      for (let k = 0; k < A.length; k++)
        result[i][j] += A[k][i] * W[k] * A[k][j]
  return result
}

function multiplyAtWl(A: number[][], W: number[], l: number[], n: number): number[] {
  const result = new Array<number>(n).fill(0)
  for (let i = 0; i < n; i++)
    for (let k = 0; k < A.length; k++)
      result[i] += A[k][i] * W[k] * l[k]
  return result
}

function solveLinearSystem(A: number[][], b: number[]): number[] {
  const n = b.length
  const M = A.map((row, i) => [...row, b[i]])

  for (let col = 0; col < n; col++) {
    let maxRow = col
    for (let row = col + 1; row < n; row++)
      if (Math.abs(M[row][col]) > Math.abs(M[maxRow][col])) maxRow = row
    ;[M[col], M[maxRow]] = [M[maxRow], M[col]]

    if (Math.abs(M[col][col]) < 1e-12)
      throw new Error('Singular normal equation matrix — check network geometry.')

    for (let row = col + 1; row < n; row++) {
      const factor = M[row][col] / M[col][col]
      for (let k = col; k <= n; k++) M[row][k] -= factor * M[col][k]
    }
  }

  const x = new Array<number>(n).fill(0)
  for (let i = n - 1; i >= 0; i--) {
    x[i] = M[i][n]
    for (let j = i + 1; j < n; j++) x[i] -= M[i][j] * x[j]
    x[i] /= M[i][i]
  }
  return x
}

function invertMatrix(A: number[][], n: number): number[][] {
  const M = A.map((row, i) => {
    const aug: number[] = [...row, ...new Array<number>(n).fill(0)]
    aug[n + i] = 1
    return aug
  })

  for (let col = 0; col < n; col++) {
    let maxRow = col
    for (let row = col + 1; row < n; row++)
      if (Math.abs(M[row][col]) > Math.abs(M[maxRow][col])) maxRow = row
    ;[M[col], M[maxRow]] = [M[maxRow], M[col]]

    const pivot = M[col][col]
    if (Math.abs(pivot) < 1e-12) return Array.from({ length: n }, () => new Array<number>(n).fill(0))

    for (let k = 0; k < 2 * n; k++) M[col][k] /= pivot
    for (let row = 0; row < n; row++) {
      if (row === col) continue
      const factor = M[row][col]
      for (let k = 0; k < 2 * n; k++) M[row][k] -= factor * M[col][k]
    }
  }

  return M.map(row => row.slice(n))
}

/**
 * Correction Pipeline — Unified Observation Processing
 * 
 * This is the heart of the survey computation engine. It applies ALL
 * corrections in the correct order to transform raw field observations
 * into corrected, grid-level observations ready for traverse computation.
 * 
 * Processing order (this order matters!):
 * 1. EDM Instrument Constant     → Add constant to raw distance
 * 2. Atmospheric Correction       → Correct slope distance for temp/pressure/humidity
 * 3. Slope Reduction              → Convert slope distance to horizontal
 * 4. Curvature & Refraction       → Correct height difference
 * 5. Sea Level Reduction          → Reduce horizontal distance to ellipsoid
 * 6. Grid Scale Factor            → Scale ellipsoid distance to grid distance
 * 7. Grid Convergence             → Correct bearings for projection convergence
 * 
 * Each stage logs what was applied for the full audit trail.
 */

import { applyAtmosphericCorrection, type AtmosphericConditions, type EDMInstrument } from '../corrections/atmospheric';
import { applyCurvatureRefractionCorrection, type CurvatureRefractionInput, KENYA_REFRACTION_COEFFICIENT } from '../corrections/curvature-refraction';
import { computeLineScaleFactor, applyGridScaleFactor, type ProjectionType } from '../corrections/grid-scale-factor';
import { applySeaLevelReduction, type SeaLevelReductionInput } from '../corrections/sea-level-reduction';
import { reduceSlopeByAngle, reduceSlopeByHeight, type SlopeReductionResult } from '../corrections/slope-reduction';
import { computeConvergence, applyConvergenceToBearing } from '../corrections/projection-convergence';

// ─── Types ───────────────────────────────────────────────────────

export interface RawObservation {
  /** From station name */
  fromStation: string;
  /** To station name */
  toStation: string;
  
  // Raw measurements
  /** Raw slope distance measured by EDM (meters) */
  rawSlopeDistance: number;
  /** Horizontal angle (decimal degrees, measured clockwise from reference) */
  horizontalAngle?: number;
  /** Vertical angle / zenith distance (decimal degrees, 90° = horizontal) */
  verticalAngle?: number;
  
  // EDM data
  /** EDM instrument constant (meters, additive) */
  edmConstant?: number;
  /** PPM setting on instrument */
  ppmSetting?: number;
  /** EDM carrier wavelength (μm): 0.6328 (HeNe) or 0.850 (IR) */
  edmWavelength?: 0.6328 | 0.850 | 0.910;
  
  // Atmospheric conditions at time of measurement
  temperature?: number;      // °C
  pressure?: number;         // hPa
  humidity?: number;         // %
  
  // Heights
  instrumentHeight?: number; // meters
  targetHeight?: number;     // meters
  heightAboveEllipsoid?: number; // Mean height of line (for sea level reduction)
  orthometricHeight?: number;    // Height above MSL
  
  // Coordinates (for scale factor and convergence)
  fromEasting?: number;
  fromNorthing?: number;
  toEasting?: number;
  toNorthing?: number;
  
  // Location
  latitude?: number;         // decimal degrees (for Earth radius)
  longitude?: number;        // decimal degrees (for convergence)
  
  // Bearing data
  trueBearing?: number;      // True (astronomic) bearing if observed
}

export interface CorrectionStageLog {
  stage: string;
  input: number;
  output: number;
  correction: number;
  unit: string;
}

export interface ProcessedObservation {
  /** From station name */
  fromStation: string;
  /** To station name */
  toStation: string;
  
  // Corrected distances
  /** Raw slope distance (meters) */
  rawSlopeDistance: number;
  /** After EDM constant (meters) */
  afterEdmConstant: number;
  /** After atmospheric correction (meters) */
  afterAtmospheric: number;
  /** Horizontal distance after slope reduction (meters) */
  horizontalDistance: number;
  /** After sea level reduction (meters) */
  afterSeaLevel: number;
  /** After grid scale factor — final grid distance (meters) */
  gridDistance: number;
  
  // Corrected angles
  /** Original horizontal angle (decimal degrees) */
  rawHorizontalAngle?: number;
  /** Grid bearing (decimal degrees) */
  gridBearing?: number;
  /** True bearing (decimal degrees) */
  trueBearing?: number;
  
  // Height data
  /** Height difference after C&R correction (meters) */
  heightDifference?: number;
  
  // Correction details
  /** Line scale factor applied */
  lineScaleFactor?: number;
  /** Grid convergence at point (decimal degrees) */
  convergence?: number;
  /** Atmospheric correction ppm */
  atmosphericPPM?: number;
  /** Sea level reduction ppm */
  seaLevelPPM?: number;
  
  // Full audit trail
  correctionLog: CorrectionStageLog[];
  
  // Flags
  /** Whether any correction exceeded significance thresholds */
  warnings: string[];
}

export interface PipelineConfig {
  /** Projection type for grid computations */
  projection: ProjectionType;
  /** Central meridian for convergence computation */
  centralMeridian: number;
  /** Refraction coefficient (default: 0.13 Kenya) */
  refractionCoefficient?: number;
  /** Geoid undulation for Kenya (default: -12m) */
  geoidUndulation?: number;
  /** EDM instrument defaults */
  defaultInstrument?: Partial<EDMInstrument>;
  /** Whether to apply each correction stage */
  applyAtmospheric?: boolean;
  applyCurvatureRefraction?: boolean;
  applySeaLevelReduction?: boolean;
  applyGridScaleFactor?: boolean;
  applyConvergence?: boolean;
  /** Minimum distance (meters) to apply C&R correction */
  crThresholdDistance?: number;
}

// ─── Default Config ──────────────────────────────────────────────

export const KENYA_DEFAULT_CONFIG: PipelineConfig = {
  projection: 'UTM37S',
  centralMeridian: 39,
  refractionCoefficient: KENYA_REFRACTION_COEFFICIENT,
  geoidUndulation: -12,
  defaultInstrument: {
    wavelength: 0.850,
    referenceN: 273.82,
    constant: 0,
    ppmSetting: 0,
  },
  applyAtmospheric: true,
  applyCurvatureRefraction: true,
  applySeaLevelReduction: true,
  applyGridScaleFactor: true,
  applyConvergence: true,
  crThresholdDistance: 200, // Apply C&R for lines > 200m
};

// ─── Pipeline Function ───────────────────────────────────────────

/**
 * Process a raw observation through the full correction pipeline.
 * 
 * This is the main entry point for observation processing. It applies
 * all corrections in the correct order and produces a fully corrected
 * observation with a complete audit trail.
 * 
 * @param observation - Raw field observation
 * @param config - Pipeline configuration
 * @returns Processed observation with all corrections applied
 */
export function processObservation(
  observation: RawObservation,
  config: PipelineConfig = KENYA_DEFAULT_CONFIG
): ProcessedObservation {
  const log: CorrectionStageLog[] = [];
  const warnings: string[] = [];
  
  let currentDistance = observation.rawSlopeDistance;
  
  // ─── Stage 1: EDM Instrument Constant ─────────────────────
  const edmConstant = observation.edmConstant ?? config.defaultInstrument?.constant ?? 0;
  const afterEdmConstant = currentDistance + edmConstant;
  log.push({
    stage: 'EDM Instrument Constant',
    input: currentDistance,
    output: afterEdmConstant,
    correction: edmConstant,
    unit: 'meters',
  });
  currentDistance = afterEdmConstant;
  
  // ─── Stage 2: Atmospheric Correction ──────────────────────
  let afterAtmospheric = currentDistance;
  let atmosphericPPM = 0;
  
  if (config.applyAtmospheric && observation.temperature !== undefined && observation.pressure !== undefined) {
    const conditions: AtmosphericConditions = {
      temperature: observation.temperature,
      pressure: observation.pressure,
      humidity: observation.humidity ?? 50,
    };
    
    const atmResult = applyAtmosphericCorrection(currentDistance, conditions, {
      wavelength: observation.edmWavelength ?? config.defaultInstrument?.wavelength,
      referenceN: config.defaultInstrument?.referenceN,
      ppmSetting: observation.ppmSetting ?? config.defaultInstrument?.ppmSetting,
    });
    
    afterAtmospheric = atmResult.correctedDistance;
    atmosphericPPM = atmResult.ppmCorrection;
    
    log.push({
      stage: 'Atmospheric Correction',
      input: currentDistance,
      output: afterAtmospheric,
      correction: atmResult.correctionMeters,
      unit: 'meters',
    });
    
    if (Math.abs(atmosphericPPM) > 30) {
      warnings.push(`Atmospheric correction of ${atmosphericPPM.toFixed(1)} ppm is large — verify temperature/pressure readings`);
    }
    
    currentDistance = afterAtmospheric;
  } else if (config.applyAtmospheric) {
    warnings.push('Atmospheric correction skipped — missing temperature/pressure data');
  }
  
  // ─── Stage 3: Slope Reduction ─────────────────────────────
  let horizontalDistance = currentDistance;
  let heightDifference: number | undefined;
  let slopeResult: SlopeReductionResult | undefined;
  
  if (observation.verticalAngle !== undefined) {
    slopeResult = reduceSlopeByAngle({
      slopeDistance: currentDistance,
      verticalAngle: observation.verticalAngle,
    });
    horizontalDistance = slopeResult.horizontalDistance;
    heightDifference = slopeResult.verticalComponent;
    
    // Add instrument/target height to height difference
    if (observation.instrumentHeight !== undefined && observation.targetHeight !== undefined) {
      heightDifference += (observation.instrumentHeight - observation.targetHeight);
    }
    
    log.push({
      stage: 'Slope Reduction',
      input: currentDistance,
      output: horizontalDistance,
      correction: currentDistance - horizontalDistance,
      unit: 'meters',
    });
  }
  
  // ─── Stage 4: Curvature & Refraction ─────────────────────
  let correctedHeightDiff = heightDifference;
  
  if (config.applyCurvatureRefraction && observation.verticalAngle !== undefined && slopeResult) {
    const latitude = observation.latitude ?? 0;
    const refractionK = config.refractionCoefficient ?? KENYA_REFRACTION_COEFFICIENT;
    
    const crResult = applyCurvatureRefractionCorrection({
      slopeDistance: afterAtmospheric,
      verticalAngle: observation.verticalAngle,
      instrumentHeight: observation.instrumentHeight ?? 0,
      targetHeight: observation.targetHeight ?? 0,
      latitude,
      refractionCoefficient: refractionK,
    });
    
    correctedHeightDiff = crResult.correctedHeightDifference;
    
    log.push({
      stage: 'Curvature & Refraction',
      input: heightDifference ?? 0,
      output: correctedHeightDiff,
      correction: crResult.crCorrection,
      unit: 'meters',
    });
    
    if (crResult.isSignificant) {
      warnings.push(crResult.warning!);
    }
  }
  
  // ─── Stage 5: Sea Level Reduction ────────────────────────
  let afterSeaLevel = horizontalDistance;
  let seaLevelPPM = 0;
  
  if (config.applySeaLevelReduction) {
    const h = observation.heightAboveEllipsoid ?? (observation.orthometricHeight !== undefined
      ? observation.orthometricHeight + (config.geoidUndulation ?? 0)
      : undefined);
    
    if (h !== undefined) {
      const slrResult = applySeaLevelReduction({
        horizontalDistance,
        heightAboveEllipsoid: h,
        latitude: observation.latitude ?? 0,
        geoidUndulation: config.geoidUndulation ?? 0,
      });
      
      afterSeaLevel = slrResult.ellipsoidalDistance;
      seaLevelPPM = slrResult.reductionPPM;
      
      log.push({
        stage: 'Sea Level Reduction',
        input: horizontalDistance,
        output: afterSeaLevel,
        correction: slrResult.reductionMeters,
        unit: 'meters',
      });
      
      if (slrResult.reductionPPM > 100) {
        warnings.push(`Sea level reduction of ${slrResult.reductionPPM.toFixed(1)} ppm is significant at height ${h.toFixed(0)}m`);
      }
    } else {
      warnings.push('Sea level reduction skipped — no height data provided');
    }
  }
  
  // ─── Stage 6: Grid Scale Factor ──────────────────────────
  let gridDistance = afterSeaLevel;
  let lineScaleFactor: number | undefined;
  
  if (config.applyGridScaleFactor && observation.fromEasting !== undefined && observation.toEasting !== undefined) {
    // Grid scale factor currently supports UTM only
    const utmProjection = config.projection === 'UTM36S' || config.projection === 'UTM37S'
      ? config.projection
      : 'UTM37S'; // Default fallback
    
    const gsfResult = applyGridScaleFactor(
      afterSeaLevel,
      observation.fromEasting,
      observation.fromNorthing ?? 0,
      observation.toEasting,
      observation.toNorthing ?? 0,
      utmProjection
    );
    
    gridDistance = gsfResult.gridDistance;
    lineScaleFactor = gsfResult.lineScaleFactor;
    
    log.push({
      stage: 'Grid Scale Factor',
      input: afterSeaLevel,
      output: gridDistance,
      correction: gridDistance - afterSeaLevel,
      unit: 'meters',
    });
  }
  
  // ─── Stage 7: Grid Convergence (Bearing Correction) ──────
  let gridBearing: number | undefined;
  let convergence: number | undefined;
  
  if (config.applyConvergence && observation.trueBearing !== undefined && observation.longitude !== undefined) {
    const convResult = computeConvergence({
      latitude: observation.latitude ?? 0,
      longitude: observation.longitude,
      centralMeridian: config.centralMeridian,
    });
    
    convergence = convResult.convergence;
    gridBearing = applyConvergenceToBearing(observation.trueBearing, convergence);
    
    log.push({
      stage: 'Grid Convergence',
      input: observation.trueBearing,
      output: gridBearing,
      correction: convergence,
      unit: 'degrees',
    });
    
    if (convResult.isSignificant) {
      warnings.push(`Grid convergence of ${convResult.arcSeconds.toFixed(1)}" exceeds 30" threshold`);
    }
  }
  
  return {
    fromStation: observation.fromStation,
    toStation: observation.toStation,
    rawSlopeDistance: observation.rawSlopeDistance,
    afterEdmConstant,
    afterAtmospheric,
    horizontalDistance,
    afterSeaLevel,
    gridDistance,
    rawHorizontalAngle: observation.horizontalAngle,
    gridBearing,
    trueBearing: observation.trueBearing,
    heightDifference: correctedHeightDiff,
    lineScaleFactor,
    convergence,
    atmosphericPPM,
    seaLevelPPM,
    correctionLog: log,
    warnings,
  };
}

/**
 * Process multiple observations through the pipeline.
 * Applies the same configuration to all observations.
 */
export function processObservations(
  observations: RawObservation[],
  config: PipelineConfig = KENYA_DEFAULT_CONFIG
): ProcessedObservation[] {
  return observations.map(obs => processObservation(obs, config));
}

/**
 * Generate a summary report of all corrections applied.
 * Useful for the computation sheet and audit trail.
 */
export function generateCorrectionReport(
  processed: ProcessedObservation[]
): string {
  const lines: string[] = [];
  lines.push('═══════════════════════════════════════════════');
  lines.push('       CORRECTION PIPELINE AUDIT REPORT        ');
  lines.push('═══════════════════════════════════════════════');
  lines.push('');
  
  for (const obs of processed) {
    lines.push(`─ ${obs.fromStation} → ${obs.toStation} ─`);
    lines.push(`  Raw slope distance:   ${obs.rawSlopeDistance.toFixed(4)} m`);
    
    for (const log of obs.correctionLog) {
      lines.push(`  ${log.stage}:`);
      lines.push(`    Input:     ${log.input.toFixed(6)} ${log.unit}`);
      lines.push(`    Output:    ${log.output.toFixed(6)} ${log.unit}`);
      lines.push(`    Correction:${log.correction >= 0 ? '+' : ''}${log.correction.toFixed(6)} ${log.unit}`);
    }
    
    lines.push(`  Final grid distance:  ${obs.gridDistance.toFixed(4)} m`);
    
    if (obs.warnings.length > 0) {
      lines.push('  [!] WARNINGS:');
      for (const w of obs.warnings) {
        lines.push(`    - ${w}`);
      }
    }
    lines.push('');
  }
  
  return lines.join('\n');
}

/**
 * @module realTimeQC
 *
 * Real-time quality control for survey observations.
 *
 * Catches errors DURING data collection, not after. Previously, a surveyor
 * could spend an entire day in the field only to discover at the end that
 * the traverse doesn't close. This module surfaces problems as they happen.
 *
 * Features:
 *   1. Running closure monitor — shows live misclosure as each leg is added
 *   2. Redundant observation detection — flags same leg measured twice with diff values
 *   3. Setup verification — checks instrument height, target height, temp/pressure
 *   4. Outlier detection — Chauvenet's criterion for statistical outlier rejection
 *   5. Real-time precision indicator — running 1:N ratio as traverse progresses
 *
 * References:
 *   - "Elementary Surveying" by Ghilani & Wolf, 16th Ed., Chapter 3 (errors)
 *   - Chauvenet's criterion: reject if probability < 1/(2n)
 *   - RDM 1.1 (2025) — Kenya tolerance limits
 */

import type { Point2D } from '@/lib/engine/types'

// ─── 1. Running Closure Monitor ─────────────────────────────────────────────

export interface RunningClosureState {
  /** Number of legs observed so far */
  legCount: number
  /** Cumulative easting misclosure (sum of ΔE) */
  cumulativeDE: number
  /** Cumulative northing misclosure (sum of ΔN) */
  cumulativeDN: number
  /** Linear misclosure (sqrt(ΔE² + ΔN²)) */
  linearMisclosure: number
  /** Total distance traversed so far */
  totalDistance: number
  /** Running precision ratio (1:N) — 0 if no distance yet */
  precisionRatio: number | null
  /** Precision ratio as a string ("1:5000") or null */
  precisionLabel: string | null
  /** Whether the current precision meets the minimum standard */
  meetsStandard: boolean
  /** The minimum precision ratio required (based on survey class) */
  minRequired: number
  /** Warnings generated by this leg */
  warnings: string[]
}

export type SurveyClass = 'urban' | 'rural' | 'topographic' | 'control'

const PRECISION_STANDARDS: Record<SurveyClass, number> = {
  urban: 10000,      // 1:10,000
  rural: 5000,       // 1:5,000
  topographic: 1000, // 1:1,000
  control: 20000,    // 1:20,000
}

/**
 * Track the running closure of a traverse as legs are added.
 * Call addLeg() for each new observation. The state updates live.
 */
export class RunningClosureMonitor {
  private legs: Array<{ dE: number; dN: number; distance: number }> = []
  private surveyClass: SurveyClass

  constructor(surveyClass: SurveyClass = 'urban') {
    this.surveyClass = surveyClass
  }

  setSurveyClass(cls: SurveyClass) {
    this.surveyClass = cls
  }

  /**
   * Add a traverse leg (bearing + distance → ΔE, ΔN).
   * Returns the updated closure state.
   */
  addLeg(bearingDeg: number, distance: number): RunningClosureState {
    const bearingRad = (bearingDeg * Math.PI) / 180
    const dE = distance * Math.sin(bearingRad)
    const dN = distance * Math.cos(bearingRad)

    this.legs.push({ dE, dN, distance })

    return this.getState()
  }

  /**
   * Add a leg from raw coordinate differences (for GNSS observations).
   */
  addLegFromCoords(dE: number, dN: number): RunningClosureState {
    const distance = Math.sqrt(dE * dE + dN * dN)
    this.legs.push({ dE, dN, distance })
    return this.getState()
  }

  /** Remove the last leg (undo). */
  removeLastLeg(): RunningClosureState {
    this.legs.pop()
    return this.getState()
  }

  /** Clear all legs. */
  reset() {
    this.legs = []
  }

  /** Get the current closure state. */
  getState(): RunningClosureState {
    const cumulativeDE = this.legs.reduce((s, l) => s + l.dE, 0)
    const cumulativeDN = this.legs.reduce((s, l) => s + l.dN, 0)
    const linearMisclosure = Math.sqrt(cumulativeDE ** 2 + cumulativeDN ** 2)
    const totalDistance = this.legs.reduce((s, l) => s + l.distance, 0)
    const minRequired = PRECISION_STANDARDS[this.surveyClass]

    const precisionRatio = totalDistance > 0 && linearMisclosure > 0
      ? Math.round(totalDistance / linearMisclosure)
      : totalDistance > 0 ? Infinity : 0

    const meetsStandard = precisionRatio >= minRequired
    const precisionLabel = precisionRatio === Infinity
      ? '1:∞ (perfect so far)'
      : precisionRatio > 0 ? `1:${precisionRatio}` : null

    // Generate warnings
    const warnings: string[] = []
    if (this.legs.length >= 3 && !meetsStandard && precisionRatio !== Infinity) {
      warnings.push(
        `Precision ${precisionLabel} is below ${this.surveyClass} standard (1:${minRequired}). ` +
        `Current misclosure: ${linearMisclosure.toFixed(3)}m over ${totalDistance.toFixed(1)}m.`
      )
    }
    if (this.legs.length >= 2 && linearMisclosure > 0.05 && totalDistance < 500) {
      warnings.push(
        `Early misclosure of ${linearMisclosure.toFixed(3)}m detected after only ${this.legs.length} legs. ` +
        `Check the first setup for instrument/target height errors.`
      )
    }

    return {
      legCount: this.legs.length,
      cumulativeDE,
      cumulativeDN,
      linearMisclosure,
      totalDistance,
      precisionRatio: precisionRatio === Infinity ? null : precisionRatio,
      precisionLabel,
      meetsStandard,
      minRequired,
      warnings,
    }
  }
}

// ─── 2. Redundant Observation Detection ─────────────────────────────────────

export interface Observation {
  fromStation: string
  toStation: string
  bearing?: number  // decimal degrees
  distance?: number // metres
  timestamp?: string
}

export interface RedundantObservationResult {
  /** The pair of observations that disagree */
  observations: [Observation, Observation]
  /** Bearing difference in seconds of arc (if both have bearings) */
  bearingDifferenceSec: number | null
  /** Distance difference in mm (if both have distances) */
  distanceDifferenceMm: number | null
  /** Whether the difference exceeds tolerance */
  exceedsTolerance: boolean
  /** Severity: 'error' if > 2× tolerance, 'warn' if > tolerance */
  severity: 'error' | 'warn'
  /** Human-readable message */
  message: string
}

/**
 * Detect redundant observations (same leg measured twice) and check
 * if they agree within tolerance.
 *
 * @param observations All observations in the survey
 * @param bearingToleranceSec Bearing tolerance in arcseconds (default: 30")
 * @param distanceToleranceMm Distance tolerance in mm (default: 10mm)
 * @returns Array of disagreements (empty if all redundant observations agree)
 */
export function detectRedundantObservationDiscrepancies(
  observations: Observation[],
  bearingToleranceSec: number = 30,
  distanceToleranceMm: number = 10,
): RedundantObservationResult[] {
  const results: RedundantObservationResult[] = []

  // Group observations by (from, to) pair
  const groups = new Map<string, Observation[]>()

  for (const obs of observations) {
    const key = `${obs.fromStation}->${obs.toStation}`
    const reverseKey = `${obs.toStation}->${obs.fromStation}`

    // Check if we already have observations for this leg (either direction)
    if (groups.has(key)) {
      groups.get(key)!.push(obs)
    } else if (groups.has(reverseKey)) {
      groups.get(reverseKey)!.push(obs)
    } else {
      groups.set(key, [obs])
    }
  }

  // Check each group with 2+ observations
  for (const [, group] of groups) {
    if (group.length < 2) continue

    for (let i = 0; i < group.length; i++) {
      for (let j = i + 1; j < group.length; j++) {
        const obs1 = group[i]
        const obs2 = group[j]

        let bearingDiffSec: number | null = null
        let distanceDiffMm: number | null = null
        let exceeds = false
        let severity: 'error' | 'warn' = 'warn'

        // Bearing check
        if (obs1.bearing != null && obs2.bearing != null) {
          // For reverse directions, add 180°
          const b1 = obs1.bearing
          let b2 = obs2.bearing
          if (obs1.fromStation !== obs2.fromStation) {
            b2 = (b2 + 180) % 360 // reverse the second bearing
          }
          let diff = Math.abs(b1 - b2)
          if (diff > 180) diff = 360 - diff
          bearingDiffSec = diff * 3600
          if (bearingDiffSec > bearingToleranceSec) {
            exceeds = true
            severity = bearingDiffSec > bearingToleranceSec * 2 ? 'error' : 'warn'
          }
        }

        // Distance check
        if (obs1.distance != null && obs2.distance != null) {
          distanceDiffMm = Math.abs(obs1.distance - obs2.distance) * 1000
          if (distanceDiffMm > distanceToleranceMm) {
            exceeds = true
            severity = distanceDiffMm > distanceToleranceMm * 2 ? 'error' : 'warn'
          }
        }

        if (exceeds) {
          const parts: string[] = []
          if (bearingDiffSec != null) {
            parts.push(`bearing diff ${bearingDiffSec.toFixed(1)}" (tol ${bearingToleranceSec}")`)
          }
          if (distanceDiffMm != null) {
            parts.push(`distance diff ${distanceDiffMm.toFixed(1)}mm (tol ${distanceToleranceMm}mm)`)
          }

          results.push({
            observations: [obs1, obs2],
            bearingDifferenceSec: bearingDiffSec,
            distanceDifferenceMm: distanceDiffMm,
            exceedsTolerance: true,
            severity,
            message: `Redundant observation discrepancy on ${obs1.fromStation}→${obs1.toStation}: ${parts.join(', ')}`,
          })
        }
      }
    }
  }

  return results
}

// ─── 3. Setup Verification ──────────────────────────────────────────────────

export interface SetupCheck {
  field: string
  value: number | null
  expected: string
  passed: boolean
  message: string
}

/**
 * Verify a setup before taking observations.
 * Catches common field mistakes: forgotten instrument height, wrong
 * temperature/pressure units, etc.
 */
export function verifySetup(input: {
  instrumentHeight?: number
  targetHeight?: number
  temperature?: number  // Celsius
  pressure?: number     // hPa/mbar
  isControlPoint?: boolean
}): SetupCheck[] {
  const checks: SetupCheck[] = []

  // Instrument height
  checks.push({
    field: 'instrumentHeight',
    value: input.instrumentHeight ?? null,
    expected: '1.0–2.0 m',
    passed: input.instrumentHeight != null && input.instrumentHeight >= 0.5 && input.instrumentHeight <= 3.0,
    message: input.instrumentHeight == null
      ? 'Instrument height not entered — EDM correction will be wrong'
      : input.instrumentHeight < 0.5
        ? `Instrument height ${input.instrumentHeight}m is unusually low — check measurement`
        : input.instrumentHeight > 3.0
          ? `Instrument height ${input.instrumentHeight}m is unusually high — check measurement`
          : `Instrument height ${input.instrumentHeight}m is within normal range`,
  })

  // Target height
  checks.push({
    field: 'targetHeight',
    value: input.targetHeight ?? null,
    expected: '1.0–2.5 m',
    passed: input.targetHeight != null && input.targetHeight >= 0.3 && input.targetHeight <= 3.5,
    message: input.targetHeight == null
      ? 'Target/prism height not entered — EDM correction will be wrong'
      : input.targetHeight < 0.3
        ? `Target height ${input.targetHeight}m is unusually low`
        : input.targetHeight > 3.5
          ? `Target height ${input.targetHeight}m is unusually high`
          : `Target height ${input.targetHeight}m is within normal range`,
  })

  // Temperature
  if (input.temperature != null) {
    checks.push({
      field: 'temperature',
      value: input.temperature,
      expected: '10–45 °C (Kenya range)',
      passed: input.temperature >= 5 && input.temperature <= 50,
      message: input.temperature < 5
        ? `Temperature ${input.temperature}°C is below Kenya range — check unit (Fahrenheit vs Celsius?)`
        : input.temperature > 50
          ? `Temperature ${input.temperature}°C is above Kenya range — check unit`
          : `Temperature ${input.temperature}°C is normal`,
    })
  }

  // Pressure
  if (input.pressure != null) {
    checks.push({
      field: 'pressure',
      value: input.pressure,
      expected: '700–1050 hPa (sea level to 3000m)',
      passed: input.pressure >= 600 && input.pressure <= 1100,
      message: input.pressure < 600
        ? `Pressure ${input.pressure}hPa is too low — check unit (inHg vs hPa?)`
        : input.pressure > 1100
          ? `Pressure ${input.pressure}hPa is too high — check unit`
          : `Pressure ${input.pressure}hPa is normal`,
    })
  }

  // Control point check
  if (input.isControlPoint) {
    checks.push({
      field: 'isControlPoint',
      value: 1,
      expected: 'verified control point',
      passed: true,
      message: 'Set up on a control point — good practice',
    })
  }

  return checks
}

// ─── 4. Outlier Detection (Chauvenet's Criterion) ──────────────────────────

/**
 * Detect statistical outliers in a set of repeated measurements using
 * Chauvenet's criterion.
 *
 * A measurement is rejected if the probability of its deviation from
 * the mean is less than 1/(2n), where n is the number of measurements.
 *
 * @param values Array of measured values (e.g., repeated distances)
 * @returns Indices of rejected outliers, or empty array if none
 */
export function detectOutliers(values: number[]): {
  outliers: number[]
  mean: number
  stdDev: number
  details: Array<{ index: number; value: number; deviation: number; criticalValue: number; rejected: boolean }>
} {
  const n = values.length
  if (n < 3) {
    return { outliers: [], mean: 0, stdDev: 0, details: [] }
  }

  // Calculate mean
  const mean = values.reduce((s, v) => s + v, 0) / n

  // Calculate standard deviation (sample)
  const variance = values.reduce((s, v) => s + (v - mean) ** 2, 0) / (n - 1)
  const stdDev = Math.sqrt(variance)

  if (stdDev === 0) {
    return { outliers: [], mean, stdDev: 0, details: [] }
  }

  // Chauvenet's critical value: reject if |deviation| / stdDev > t_critical
  // where t_critical corresponds to probability 1 - 1/(2n)
  // For small n, use the t-distribution approximation
  // t_critical ≈ inverse_normal_cdf(1 - 1/(4n))
  const criticalProb = 1 - 1 / (4 * n)
  const tCritical = inverseNormalCdf(criticalProb)

  const details = values.map((value, index) => {
    const deviation = Math.abs(value - mean)
    const tStat = deviation / stdDev
    const rejected = tStat > tCritical
    return { index, value, deviation, criticalValue: tCritical, rejected }
  })

  const outliers = details.filter(d => d.rejected).map(d => d.index)

  return { outliers, mean, stdDev, details }
}

/**
 * Approximation of the inverse normal CDF (probit function).
 * Uses Acklam's algorithm.
 */
function inverseNormalCdf(p: number): number {
  const a = [-3.969683028665376e+01, 2.209460984245205e+02, -2.759285104469687e+02, 1.383577518672690e+02, -3.066479806614716e+01, 2.506628277459239e+00]
  const b = [-5.447609879822406e+01, 1.615858368580409e+02, -1.556989798598866e+02, 6.680131188771972e+01, -1.328068155288572e+01]
  const c = [-7.784894002430293e-03, -3.223964580411365e-01, -2.400758277161838e+00, -2.549732539343734e+00, 4.374664141464968e+00, 2.938163982698783e+00]
  const d = [7.784695709041462e-03, 3.224671290700398e-01, 2.445134137142996e+00, 3.754408661907416e+00]

  const pLow = 0.02425
  const pHigh = 1 - pLow

  if (p < pLow) {
    const q = Math.sqrt(-2 * Math.log(p))
    return (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) /
           ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1)
  } else if (p <= pHigh) {
    const q = p - 0.5
    const r = q * q
    return (((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q /
           (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1)
  } else {
    const q = Math.sqrt(-2 * Math.log(1 - p))
    return -(((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) /
            ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1)
  }
}

// ─── 5. Real-Time Precision Indicator ───────────────────────────────────────

/**
 * Format a precision ratio for display.
 * @param ratio The 1:N ratio (e.g., 5000 for 1:5000)
 * @param surveyClass The survey class for comparison
 * @returns Formatted string with compliance status
 */
export function formatPrecisionIndicator(
  ratio: number | null,
  surveyClass: SurveyClass = 'urban',
): { label: string; compliant: boolean; color: string } {
  if (ratio === null) {
    return { label: '—', compliant: true, color: 'gray' }
  }

  const minRequired = PRECISION_STANDARDS[surveyClass]
  const compliant = ratio >= minRequired

  let color: string
  if (compliant) {
    color = 'green'
  } else if (ratio >= minRequired * 0.5) {
    color = 'amber'
  } else {
    color = 'red'
  }

  return {
    label: ratio > 0 && Number.isFinite(ratio) ? `1:${ratio.toLocaleString()}` : '—',
    compliant,
    color,
  }
}

/**
 * Residual Diagnostics — validate LSA assumptions
 *
 * PROBLEM
 * -------
 * The w-test (Baarda data snooping) assumes residuals are normally distributed
 * and uncorrelated. If either assumption is violated:
 *   - The w-test flags too many or too few blunders
 *   - The chi-square test gives false positives/negatives
 *   - The MDB (reliability) numbers are wrong
 *
 * Without diagnostic tests, you can't tell whether a "FAILED" global test
 * means real blunders or just non-normal residuals (e.g., from systematic
 * errors like an uncorrected refraction bias).
 *
 * This module implements:
 *   1. Kolmogorov-Smirnov test for normality (compares empirical CDF to
 *      theoretical normal CDF)
 *   2. Anderson-Darling test (more sensitive to tail deviations)
 *   3. Durbin-Watson test for autocorrelation (detects time-correlated
 *      residuals, common in GPS observation sequences)
 *   4. Skewness and kurtosis (3rd and 4th moments)
 *
 * REFERENCES
 * ----------
 * - Kolmogorov, A.N. (1933). "Sulla determinazione empirica di una legge di
 *   distribuzione." Giornale dell'Istituto Italiano degli Attuari, 4.
 * - Smirnov, N.V. (1948). "Table for estimating the goodness of fit of
 *   empirical distributions." Annals of Mathematical Statistics, 19.
 * - Anderson, T.W. & Darling, D.A. (1952). "Asymptotic theory of certain
 *   'goodness of fit' criteria based on stochastic processes." Annals of
 *   Mathematical Statistics, 23.
 * - Durbin, J. & Watson, G.S. (1950). "Testing for serial correlation in
 *   least squares regression, I." Biometrika, 37.
 * - Ghilani, C.D. (2017). Adjustment Computations, 6th ed. Wiley, §5.6.
 */

import { normalCDF } from '../survey/lsaStatisticalTesting'

// ─── Types ──────────────────────────────────────────────────────────────────

export interface NormalityTestResult {
  /** Test name */
  test: 'kolmogorov-smirnov' | 'anderson-darling' | 'shapiro-wilk-approx'
  /** Test statistic */
  statistic: number
  /** Critical value at the chosen significance level */
  criticalValue: number
  /** p-value (approximation) */
  pValue: number
  /** Whether residuals pass the normality test */
  passed: boolean
  /** Significance level */
  alpha: number
  /** Sample size */
  n: number
  /** Interpretation */
  interpretation: string
}

export interface DurbinWatsonResult {
  /** Durbin-Watson statistic (0 ≤ DW ≤ 4) */
  statistic: number
  /** Lower critical value (dL) at alpha */
  dLower: number
  /** Upper critical value (dU) at alpha */
  dUpper: number
  /** Conclusion: 'no_autocorrelation' | 'positive_autocorrelation' | 'negative_autocorrelation' | 'inconclusive' */
  conclusion: 'no_autocorrelation' | 'positive_autocorrelation' | 'negative_autocorrelation' | 'inconclusive'
  /** Interpretation */
  interpretation: string
}

export interface MomentStats {
  mean: number
  standardDeviation: number
  skewness: number
  kurtosis: number      // excess kurtosis (normal = 0)
  min: number
  max: number
  n: number
}

export interface ResidualDiagnostics {
  /** Sample size */
  n: number
  /** Moment statistics */
  moments: MomentStats
  /** Kolmogorov-Smirnov normality test */
  kolmogorovSmirnov: NormalityTestResult
  /** Anderson-Darling normality test */
  andersonDarling: NormalityTestResult
  /** Durbin-Watson autocorrelation test (only if observationOrder is provided) */
  durbinWatson?: DurbinWatsonResult
  /** Overall assessment */
  passed: boolean
  /** Summary */
  summary: string
  /** Warnings */
  warnings: string[]
}

// ─── Moment Statistics ──────────────────────────────────────────────────────

/**
 * Compute mean, standard deviation, skewness, and excess kurtosis.
 *
 * Skewness: γ₁ = (1/n) Σ ((xᵢ - x̄)/s)³
 *   Normal: γ₁ = 0
 *   Positive skew = right tail heavier (e.g., from one-sided blunders)
 *
 * Excess kurtosis: γ₂ = (1/n) Σ ((xᵢ - x̄)/s)⁴ - 3
 *   Normal: γ₂ = 0
 *   Positive = heavy tails (leptokurtic, common with blunders)
 *   Negative = light tails (platykurtic, from over-weighted observations)
 */
export function computeMoments(residuals: number[]): MomentStats {
  const n = residuals.length
  if (n === 0) {
    return { mean: 0, standardDeviation: 0, skewness: 0, kurtosis: 0, min: 0, max: 0, n: 0 }
  }

  const mean = residuals.reduce((s, r) => s + r, 0) / n
  const deviations = residuals.map(r => r - mean)
  const variance = deviations.reduce((s, d) => s + d * d, 0) / n
  const sd = Math.sqrt(variance)

  if (sd === 0) {
    return { mean, standardDeviation: 0, skewness: 0, kurtosis: 0, min: mean, max: mean, n }
  }

  let sumCubed = 0, sumFourth = 0
  for (const d of deviations) {
    const normalized = d / sd
    sumCubed += normalized ** 3
    sumFourth += normalized ** 4
  }

  const skewness = sumCubed / n
  const kurtosis = sumFourth / n - 3  // excess kurtosis

  const min = Math.min(...residuals)
  const max = Math.max(...residuals)

  return { mean, standardDeviation: sd, skewness, kurtosis, min, max, n }
}

// ─── Kolmogorov-Smirnov Test ────────────────────────────────────────────────

/**
 * Kolmogorov-Smirnov test for normality.
 *
 * Compares the empirical CDF of the (standardized) residuals to the
 * theoretical standard normal CDF. The test statistic is the maximum
 * absolute difference:
 *   D = max |F_empirical(x) - F_normal(x)|
 *
 * Critical values (α = 0.05):
 *   D_crit ≈ 1.36 / √n   (large-sample approximation)
 *
 * @param residuals - Residual vector
 * @param alpha - Significance level (default 0.05)
 */
export function kolmogorovSmirnovTest(
  residuals: number[],
  alpha: number = 0.05,
): NormalityTestResult {
  const n = residuals.length
  if (n < 5) {
    return {
      test: 'kolmogorov-smirnov',
      statistic: 0,
      criticalValue: 1,
      pValue: 1,
      passed: true,
      alpha,
      n,
      interpretation: 'Sample too small (n<5) — K-S test inconclusive.',
    }
  }

  // Standardize residuals (subtract mean, divide by SD)
  const mean = residuals.reduce((s, r) => s + r, 0) / n
  const variance = residuals.reduce((s, r) => s + (r - mean) ** 2, 0) / n
  const sd = Math.sqrt(variance)
  if (sd === 0) {
    return {
      test: 'kolmogorov-smirnov',
      statistic: 0,
      criticalValue: 1.36 / Math.sqrt(n),
      pValue: 1,
      passed: true,
      alpha,
      n,
      interpretation: 'All residuals identical (zero variance) — normality trivially satisfied.',
    }
  }

  const standardized = residuals.map(r => (r - mean) / sd)
  standardized.sort((a, b) => a - b)

  // Compute K-S statistic: D = max |F_emp(x) - F_norm(x)|
  let dMax = 0
  for (let i = 0; i < n; i++) {
    // Empirical CDF at standardized[i]: (i+1)/n
    const fEmpiricalHigh = (i + 1) / n
    const fEmpiricalLow = i / n
    const fNormal = normalCDF(standardized[i])

    const diffHigh = Math.abs(fEmpiricalHigh - fNormal)
    const diffLow = Math.abs(fNormal - fEmpiricalLow)
    dMax = Math.max(dMax, diffHigh, diffLow)
  }

  // Critical value: D_crit = c(α) / √n
  // c(0.10) = 1.224, c(0.05) = 1.358, c(0.01) = 1.628
  const cAlpha = alpha === 0.10 ? 1.224 : alpha === 0.01 ? 1.628 : 1.358
  const criticalValue = cAlpha / Math.sqrt(n)

  // p-value approximation (Marsaglia, 2003 — simplified):
  // p = 2 · Σ (-1)^(k-1) · exp(-2·k²·λ²),  λ = (√n + 0.12 + 0.11/√n) · D
  const lambda = (Math.sqrt(n) + 0.12 + 0.11 / Math.sqrt(n)) * dMax
  let pValue = 0
  for (let k = 1; k <= 100; k++) {
    const term = 2 * Math.pow(-1, k - 1) * Math.exp(-2 * k * k * lambda * lambda)
    pValue += term
    if (Math.abs(term) < 1e-10) break
  }
  pValue = Math.max(0, Math.min(1, pValue))

  const passed = dMax <= criticalValue

  let interpretation: string
  if (passed) {
    interpretation = `PASS — Residuals are normally distributed at ${(1 - alpha) * 100}% confidence (D=${dMax.toFixed(4)} ≤ D_crit=${criticalValue.toFixed(4)}, p=${pValue.toFixed(3)}). The w-test and chi-square test assumptions are valid.`
  } else {
    interpretation = `FAIL — Residuals deviate from normal at ${(1 - alpha) * 100}% confidence (D=${dMax.toFixed(4)} > D_crit=${criticalValue.toFixed(4)}, p=${pValue.toFixed(3)}). The w-test may produce false positives/negatives. Investigate: systematic errors, unmodeled refraction, or heavy-tailed observations.`
  }

  return {
    test: 'kolmogorov-smirnov',
    statistic: dMax,
    criticalValue,
    pValue,
    passed,
    alpha,
    n,
    interpretation,
  }
}

// ─── Anderson-Darling Test ──────────────────────────────────────────────────

/**
 * Anderson-Darling test for normality.
 *
 * More sensitive than K-S to deviations in the tails (where blunders show up).
 *
 *   A² = -n - (1/n) Σ [(2i-1)·ln(F(xᵢ)) + (2(n-i)+1)·ln(1-F(xᵢ))]
 *
 * Critical values (α = 0.05): A²_crit = 0.787 (adjusted for estimated parameters: 0.752)
 *
 * @param residuals - Residual vector
 * @param alpha - Significance level (default 0.05)
 */
export function andersonDarlingTest(
  residuals: number[],
  alpha: number = 0.05,
): NormalityTestResult {
  const n = residuals.length
  if (n < 8) {
    return {
      test: 'anderson-darling',
      statistic: 0,
      criticalValue: 0.787,
      pValue: 1,
      passed: true,
      alpha,
      n,
      interpretation: 'Sample too small (n<8) — A-D test inconclusive.',
    }
  }

  const mean = residuals.reduce((s, r) => s + r, 0) / n
  const variance = residuals.reduce((s, r) => s + (r - mean) ** 2, 0) / n
  const sd = Math.sqrt(variance)
  if (sd === 0) {
    return {
      test: 'anderson-darling',
      statistic: 0,
      criticalValue: 0.787,
      pValue: 1,
      passed: true,
      alpha,
      n,
      interpretation: 'All residuals identical — normality trivially satisfied.',
    }
  }

  const standardized = residuals.map(r => (r - mean) / sd)
  standardized.sort((a, b) => a - b)

  let aSquared = 0
  for (let i = 0; i < n; i++) {
    const f = normalCDF(standardized[i])
    const fClamped = Math.max(1e-15, Math.min(1 - 1e-15, f))
    const oneMinusF = 1 - fClamped
    aSquared += (2 * (i + 1) - 1) * Math.log(fClamped) + (2 * (n - i - 1) + 1) * Math.log(oneMinusF)
  }
  aSquared = -n - aSquared / n

  // Adjust for estimated parameters (mean & SD estimated from data):
  // A²* = A² · (1 + 0.75/n + 2.25/n²)
  const aSquaredAdj = aSquared * (1 + 0.75 / n + 2.25 / (n * n))

  // Critical values for adjusted A² (Stephens, 1974):
  // α=0.10: 0.631, α=0.05: 0.752, α=0.025: 0.873, α=0.01: 1.035
  const criticalValue = alpha === 0.10 ? 0.631 : alpha === 0.025 ? 0.873 : alpha === 0.01 ? 1.035 : 0.752

  // p-value approximation (D'Agostino & Stephens, 1986):
  let pValue: number
  if (aSquaredAdj < 0.200) {
    pValue = 1 - Math.exp(-13.436 + 101.14 * aSquaredAdj - 223.73 * aSquaredAdj ** 2)
  } else if (aSquaredAdj < 0.340) {
    pValue = 1 - Math.exp(-8.318 + 42.796 * aSquaredAdj - 59.938 * aSquaredAdj ** 2)
  } else if (aSquaredAdj < 0.600) {
    pValue = Math.exp(0.9177 - 4.279 * aSquaredAdj - 1.38 * aSquaredAdj ** 2)
  } else {
    pValue = Math.exp(1.2937 - 5.709 * aSquaredAdj + 0.0186 * aSquaredAdj ** 2)
  }
  pValue = Math.max(0, Math.min(1, pValue))

  const passed = aSquaredAdj <= criticalValue

  let interpretation: string
  if (passed) {
    interpretation = `PASS — Anderson-Darling test passes at ${(1 - alpha) * 100}% confidence (A²=${aSquaredAdj.toFixed(4)} ≤ A²_crit=${criticalValue}, p=${pValue.toFixed(3)}). Residuals are normally distributed including in the tails.`
  } else {
    interpretation = `FAIL — Anderson-Darling test fails at ${(1 - alpha) * 100}% confidence (A²=${aSquaredAdj.toFixed(4)} > A²_crit=${criticalValue}, p=${pValue.toFixed(3)}). Residuals deviate from normal — likely heavy tails from blunders or systematic errors.`
  }

  return {
    test: 'anderson-darling',
    statistic: aSquaredAdj,
    criticalValue,
    pValue,
    passed,
    alpha,
    n,
    interpretation,
  }
}

// ─── Durbin-Watson Test ─────────────────────────────────────────────────────

/**
 * Durbin-Watson test for autocorrelation in residuals.
 *
 *   DW = Σ (eᵢ - eᵢ₋₁)² / Σ eᵢ²
 *
 * DW ≈ 2 → no autocorrelation
 * DW < 2 → positive autocorrelation (residuals correlated with neighbors)
 * DW > 2 → negative autocorrelation (alternating residuals)
 *
 * Critical values dL and dU depend on n and α. For n > 50, use the
 * approximation: dL ≈ 2 - 2·z_(1-α)·√(n/(n²-1))
 *
 * @param residuals - Residual vector in OBSERVATION ORDER (not sorted)
 * @param alpha - Significance level (default 0.05)
 */
export function durbinWatsonTest(
  residuals: number[],
  alpha: number = 0.05,
): DurbinWatsonResult {
  const n = residuals.length
  if (n < 15) {
    return {
      statistic: 2,
      dLower: 0,
      dUpper: 4,
      conclusion: 'inconclusive',
      interpretation: 'Sample too small (n<15) — Durbin-Watson test inconclusive.',
    }
  }

  // DW = Σ (eᵢ - eᵢ₋₁)² / Σ eᵢ²
  let numerator = 0
  let denominator = 0
  for (let i = 0; i < n; i++) {
    denominator += residuals[i] ** 2
    if (i > 0) {
      numerator += (residuals[i] - residuals[i - 1]) ** 2
    }
  }

  if (denominator === 0) {
    return {
      statistic: 2,
      dLower: 0,
      dUpper: 4,
      conclusion: 'inconclusive',
      interpretation: 'All residuals are zero — cannot compute DW.',
    }
  }

  const dw = numerator / denominator

  // Approximate critical values for large n (Savin & White, 1977):
  // For α=0.05, k=1 (one predictor):
  //   dL ≈ 2 - 2·1.645·√(1 + 1/(n-1))   (approximation)
  // Use the simplified formula: dL = 1.20, dU = 1.41 for n=25;
  // dL = 1.50, dU = 1.59 for n=50; dL = 1.65, dU = 1.69 for n=100
  // Linear interpolation for other n.
  const dLower = interpolateDWCritical(n, 'dL', alpha)
  const dUpper = interpolateDWCritical(n, 'dU', alpha)

  let conclusion: DurbinWatsonResult['conclusion']
  let interpretation: string

  if (dw < dLower) {
    conclusion = 'positive_autocorrelation'
    interpretation = `POSITIVE AUTOCORRELATION detected (DW=${dw.toFixed(3)} < dL=${dLower.toFixed(3)}). Residuals are correlated with their neighbors — likely from time-series observations or unmodeled systematic effects. The LSA assumption of independence is violated; standard deviations are underestimated.`
  } else if (dw > 4 - dLower) {
    conclusion = 'negative_autocorrelation'
    interpretation = `NEGATIVE AUTOCORRELATION detected (DW=${dw.toFixed(3)} > 4-dL=${(4 - dLower).toFixed(3)}). Residuals alternate in sign — possibly from over-correction or oscillating systematic errors.`
  } else if (dw >= dUpper && dw <= 4 - dUpper) {
    conclusion = 'no_autocorrelation'
    interpretation = `PASS — No autocorrelation detected (dU=${dUpper.toFixed(3)} ≤ DW=${dw.toFixed(3)} ≤ 4-dU=${(4 - dUpper).toFixed(3)}). Residuals are independent. LSA assumptions valid.`
  } else {
    conclusion = 'inconclusive'
    interpretation = `INCONCLUSIVE — DW statistic (${dw.toFixed(3)}) is in the inconclusive zone (between dL=${dLower.toFixed(3)} and dU=${dUpper.toFixed(3)} or their mirror). Increase sample size or investigate.`
  }

  return {
    statistic: dw,
    dLower,
    dUpper,
    conclusion,
    interpretation,
  }
}

// Critical value table (Savin & White, 1977) for k=1 (single regression):
// α=0.05:  n=15: dL=1.08, dU=1.36; n=20: dL=1.20, dU=1.41; n=25: dL=1.29, dU=1.45;
//          n=30: dL=1.35, dU=1.49; n=40: dL=1.44, dU=1.54; n=50: dL=1.50, dU=1.59;
//          n=75: dL=1.58, dU=1.64; n=100: dL=1.65, dU=1.69; n=200: dL=1.76, dU=1.78
function interpolateDWCritical(n: number, which: 'dL' | 'dU', alpha: number): number {
  // Use α=0.05 table (most common); for other alphas, scale proportionally
  const table = [
    { n: 15,  dL: 1.08, dU: 1.36 },
    { n: 20,  dL: 1.20, dU: 1.41 },
    { n: 25,  dL: 1.29, dU: 1.45 },
    { n: 30,  dL: 1.35, dU: 1.49 },
    { n: 40,  dL: 1.44, dU: 1.54 },
    { n: 50,  dL: 1.50, dU: 1.59 },
    { n: 75,  dL: 1.58, dU: 1.64 },
    { n: 100, dL: 1.65, dU: 1.69 },
    { n: 200, dL: 1.76, dU: 1.78 },
  ]

  // Linear interpolation in log(n) space
  let val: number
  if (n <= table[0].n) {
    val = which === 'dL' ? table[0].dL : table[0].dU
  } else if (n >= table[table.length - 1].n) {
    val = which === 'dL' ? table[table.length - 1].dL : table[table.length - 1].dU
  } else {
    for (let i = 0; i < table.length - 1; i++) {
      if (n >= table[i].n && n <= table[i + 1].n) {
        const t = (n - table[i].n) / (table[i + 1].n - table[i].n)
        const a = which === 'dL' ? table[i].dL : table[i].dU
        const b = which === 'dL' ? table[i + 1].dL : table[i + 1].dU
        val = a + t * (b - a)
        break
      }
    }
  }

  // Adjust for alpha (rough): α=0.01 widens the inconclusive zone
  const alphaAdjust = alpha === 0.01 ? 0.92 : alpha === 0.10 ? 1.05 : 1.0

  // For α=0.01, dL is lower and dU is also lower; for α=0.10, both higher
  // This is a rough scaling — for production, use exact tables
  return val! * alphaAdjust
}

// ─── Full Diagnostics ───────────────────────────────────────────────────────

/**
 * Compute full residual diagnostics for an LSA adjustment.
 *
 * @param residuals - Residual vector (in observation order for DW test)
 * @param options - Whether to include Durbin-Watson test
 */
export function computeResidualDiagnostics(
  residuals: number[],
  options: {
    includeDurbinWatson?: boolean
    alpha?: number
  } = {},
): ResidualDiagnostics {
  const alpha = options.alpha ?? 0.05
  const n = residuals.length

  const moments = computeMoments(residuals)
  const ks = kolmogorovSmirnovTest(residuals, alpha)
  const ad = andersonDarlingTest(residuals, alpha)
  const dw = options.includeDurbinWatson ? durbinWatsonTest(residuals, alpha) : undefined

  const warnings: string[] = []

  // Skewness check (z-test using SE = √(6/n))
  if (n >= 30) {
    const skewSE = Math.sqrt(6 / n)
    const skewZ = moments.skewness / skewSE
    if (Math.abs(skewZ) > 1.96) {
      warnings.push(`Skewness is significant (γ₁=${moments.skewness.toFixed(3)}, z=${skewZ.toFixed(2)}). Distribution is asymmetric — possible one-sided systematic error.`)
    }
  }

  // Kurtosis check (z-test using SE = √(24/n))
  if (n >= 30) {
    const kurtSE = Math.sqrt(24 / n)
    const kurtZ = moments.kurtosis / kurtSE
    if (Math.abs(kurtZ) > 1.96) {
      warnings.push(`Excess kurtosis is significant (γ₂=${moments.kurtosis.toFixed(3)}, z=${kurtZ.toFixed(2)}). ${moments.kurtosis > 0 ? 'Heavy tails — possible blunders.' : 'Light tails — observations may be over-weighted.'}`)
    }
  }

  if (!ks.passed) {
    warnings.push(`Kolmogorov-Smirnov test failed — residuals are not normally distributed.`)
  }
  if (!ad.passed) {
    warnings.push(`Anderson-Darling test failed — residuals deviate from normal in the tails.`)
  }
  if (dw && (dw.conclusion === 'positive_autocorrelation' || dw.conclusion === 'negative_autocorrelation')) {
    warnings.push(`Durbin-Watson test indicates ${dw.conclusion.replace('_', ' ')} — LSA independence assumption violated.`)
  }

  const passed = ks.passed && ad.passed && (!dw || dw.conclusion === 'no_autocorrelation')

  let summary: string
  if (passed) {
    summary = `Residual diagnostics PASS at ${(1 - alpha) * 100}% confidence. K-S: ${ks.statistic.toFixed(4)}/${ks.criticalValue.toFixed(4)}, A-D: ${ad.statistic.toFixed(4)}/${ad.criticalValue.toFixed(4)}${dw ? `, DW: ${dw.statistic.toFixed(3)}` : ''}. Skewness=${moments.skewness.toFixed(3)}, Kurtosis=${moments.kurtosis.toFixed(3)}. LSA assumptions are valid; the w-test and chi-square test results are trustworthy.`
  } else {
    summary = `Residual diagnostics FAIL at ${(1 - alpha) * 100}% confidence. ${warnings.length} warning(s). The LSA assumption of independent, normally-distributed residuals is violated — statistical test results (w-test, chi-square) may be unreliable.`
  }

  return {
    n,
    moments,
    kolmogorovSmirnov: ks,
    andersonDarling: ad,
    durbinWatson: dw,
    passed,
    summary,
    warnings,
  }
}

/**
 * Robust Estimation — Iteratively Reweighted Least Squares (IRLS)
 *
 * PROBLEM
 * -------
 * Standard least-squares is the BLUE (Best Linear Unbiased Estimator) when
 * residuals are Gaussian — but a single blunder can drag adjusted coordinates
 * by centimeters without being detected by the w-test. Real survey networks
 * often contain 2-5% gross errors (misread angles, swapped face, bust shots,
 * wrong target height, etc.).
 *
 * Robust estimators down-weight observations with large residuals, making
 * the adjustment RESISTANT to blunders. The adjusted coordinates converge
 * to the "clean" solution even when 10-20% of observations are contaminated.
 *
 * THREE WEIGHT FUNCTIONS IMPLEMENTED
 * ----------------------------------
 *
 * 1. HUBER (most common, good default)
 *    w(u) = 1                    if |u| ≤ c
 *    w(u) = c/|u|                if |u| > c
 *    where u = v/σ, c = 1.345 (95% efficiency under normality)
 *
 * 2. IGG3 (Institute of Geodesy and Geophysics, China — used by Chinese
 *    geodetic networks, more aggressive than Huber)
 *    w(u) = 1                       if |u| ≤ k0
 *    w(u) = (k0/|u|)·((k1 - |u|)/(k1 - k0))²  if k0 < |u| ≤ k1
 *    w(u) = 0                       if |u| > k1
 *    where k0 = 1.5, k1 = 2.5 (standard IGG3 constants)
 *
 * 3. TUKEY BIWEIGHT (most aggressive, fully rejects outliers)
 *    w(u) = (1 - (u/c)²)²          if |u| ≤ c
 *    w(u) = 0                       if |u| > c
 *    where c = 4.685 (95% efficiency under normality)
 *
 * ALGORITHM (IRLS)
 * ----------------
 * 1. Start with standard LSA (all weights = 1)
 * 2. Compute residuals v_i and standardize: u_i = v_i / (σ₀·√(q_vv_ii))
 * 3. Compute new weights w_i = f(u_i) using the chosen weight function
 * 4. Re-run LSA with new weights
 * 5. Repeat until weights converge (typically 5-15 iterations)
 *
 * The final weights identify blunders: w_i ≈ 0 means observation i is a blunder.
 *
 * REFERENCES
 * ----------
 * - Huber, P.J. (1964). "Robust Estimation of a Location Parameter."
 *   Annals of Mathematical Statistics, 35(1).
 * - Huber, P.J. (1981). Robust Statistics. Wiley.
 * - Zhou, J. (1989). "Classical theory of robustness and IGG scheme."
 *   Acta Geodaetica et Cartographica Sinica, 18(2). (IGG3 origin)
 * - Beaton, A.E. & Tukey, J.W. (1974). "The Fitting of Power Series,
 *   Meaning Polynomials, Illustrated on Band-Spectroscopic Data."
 *   Technometrics, 16(2). (Tukey biweight)
 * - Ghilani, C.D. (2017). Adjustment Computations, 6th ed. Wiley, §11.
 */

import { adjustNetworkIterative, type NetworkStation, type GenericObservation } from './lsaIterative'

// ─── Types ──────────────────────────────────────────────────────────────────

export type WeightFunction = 'huber' | 'igg3' | 'tukey'

export interface RobustLSAOptions {
  /** Weight function (default: 'huber') */
  weightFunction?: WeightFunction
  /** Tuning constant c for Huber (default: 1.345 — 95% efficiency) */
  huberC?: number
  /** IGG3 lower threshold k0 (default: 1.5) */
  igg3K0?: number
  /** IGG3 upper threshold k1 (default: 2.5) */
  igg3K1?: number
  /** Tukey biweight constant c (default: 4.685 — 95% efficiency) */
  tukeyC?: number
  /** Max IRLS iterations (default: 20) */
  maxIterations?: number
  /** Weight convergence threshold (default: 1e-4) */
  convergenceThreshold?: number
  /** Alpha for statistical tests (default: 0.05) */
  alpha?: number
}

export interface RobustLSAResult {
  /** Adjusted stations (same as standard LSA) */
  adjustedStations: Array<NetworkStation & {
    residualE: number
    residualN: number
    residualH: number
    sigmaE: number
    sigmaN: number
    sigmaH: number
    semiMajor: number
    semiMinor: number
    orientation: number
  }>
  /** Reference standard deviation σ₀ (robust) */
  sigmaZero: number
  /** Degrees of freedom */
  degreesOfFreedom: number
  /** Number of IRLS iterations */
  iterations: number
  /** Whether IRLS converged */
  converged: boolean
  /** Final weights per observation (1 = full weight, 0 = rejected) */
  finalWeights: number[]
  /** Observations flagged as blunders (weight ≈ 0) */
  blunders: Array<{
    index: number
    type: GenericObservation['type']
    from?: string
    to?: string
    component?: string
    residual: number
    standardizedResidual: number
    finalWeight: number
  }>
  /** Number of blunders detected */
  blunderCount: number
  /** Method used ('huber' | 'igg3' | 'tukey') */
  method: WeightFunction
  /** Warnings */
  warnings: string[]
  /** Summary for UI display */
  summary: string
}

// ─── Weight Functions ───────────────────────────────────────────────────────

/**
 * Compute the robust weight for a standardized residual u.
 *
 * @param u - Standardized residual (v / (σ₀·√(q_vv)))
 * @param fn - Weight function name
 * @param params - Tuning constants
 */
export function computeRobustWeight(
  u: number,
  fn: WeightFunction,
  params: { huberC?: number; igg3K0?: number; igg3K1?: number; tukeyC?: number } = {},
): number {
  const absU = Math.abs(u)

  if (fn === 'huber') {
    const c = params.huberC ?? 1.345
    return absU <= c ? 1 : c / absU
  }

  if (fn === 'igg3') {
    const k0 = params.igg3K0 ?? 1.5
    const k1 = params.igg3K1 ?? 2.5
    if (absU <= k0) return 1
    if (absU > k1) return 0
    // w = (k0/|u|) · ((k1 - |u|)/(k1 - k0))²
    return (k0 / absU) * Math.pow((k1 - absU) / (k1 - k0), 2)
  }

  if (fn === 'tukey') {
    const c = params.tukeyC ?? 4.685
    if (absU > c) return 0
    const t = 1 - (u / c) ** 2
    return t * t
  }

  return 1 // fallback
}

// ─── Robust LSA via IRLS ────────────────────────────────────────────────────

/**
 * Iteratively Reweighted Least Squares adjustment.
 *
 * This wraps the existing iterative LSA with an outer IRLS loop that
 * down-weights observations with large residuals. After convergence,
 * observations with weight ≈ 0 are flagged as blunders.
 *
 * @param stations - Network stations (with approximate coords for free, fixed for fixed)
 * @param observations - Mixed observation types
 * @param options - Robust LSA options
 */
export function adjustNetworkRobust(
  stations: NetworkStation[],
  observations: GenericObservation[],
  options: RobustLSAOptions = {},
): RobustLSAResult {
  const fn = options.weightFunction ?? 'huber'
  const maxIter = options.maxIterations ?? 20
  const threshold = options.convergenceThreshold ?? 1e-4
  const alpha = options.alpha ?? 0.05

  const warnings: string[] = []

  // Step 1: Run the standard iterative LSA to get initial residuals
  let lastResult = adjustNetworkIterative(stations, observations, {
    maxIterations: 30,
    convergenceThreshold: 1e-6,
    alpha,
    includeDiagnostics: false,
  })

  // Step 2: IRLS outer loop
  // We modify the observation stdDevs to implement the reweighting:
  // w_i_new = w_robust(u_i) × w_i_old
  // Equivalent to: σ_i_new = σ_i_old / √(w_robust(u_i))
  // (because weight = 1/σ², so w_robust × (1/σ²) = 1/(σ/√w_robust)²)

  let currentWeights = observations.map(() => 1.0)  // per-observation scalar weight multiplier
  let iteration = 0
  let converged = false
  let finalWeights: number[] = []

  // We need to track weights per observation ROW (not per scalar component).
  // For coordinate_diff observations, there are 3 rows (E, N, H) but we
  // apply the same weight to all 3 components.
  for (; iteration < maxIter; iteration++) {
    // Build new observations with adjusted stdDevs based on current weights
    const reweightedObs: GenericObservation[] = observations.map((obs, i) => {
      const w = currentWeights[i]
      const scaleFactor = w > 1e-10 ? 1 / Math.sqrt(w) : 1e6  // huge σ for zero-weight obs
      return {
        ...obs,
        stdDevE: obs.stdDevE ? obs.stdDevE * scaleFactor : undefined,
        stdDevN: obs.stdDevN ? obs.stdDevN * scaleFactor : undefined,
        stdDevH: obs.stdDevH ? obs.stdDevH * scaleFactor : undefined,
        stdDevDistance: obs.stdDevDistance ? obs.stdDevDistance * scaleFactor : undefined,
        stdDevDirection: obs.stdDevDirection ? obs.stdDevDirection * scaleFactor : undefined,
        stdDevZenith: obs.stdDevZenith ? obs.stdDevZenith * scaleFactor : undefined,
      }
    })

    // Re-run LSA with reweighted observations
    lastResult = adjustNetworkIterative(stations, reweightedObs, {
      maxIterations: 30,
      convergenceThreshold: 1e-6,
      alpha,
      includeDiagnostics: false,
    })

    // Compute new weights based on per-observation residuals
    // We re-evaluate residuals from scratch for each observation by comparing
    // the observation's measured value to the predicted value (computed from
    // the adjusted coordinates).
    const newWeights: number[] = []
    const adjustedCoords = new Map<string, { e: number; n: number; h: number }>()
    for (const s of lastResult.adjustedStations) {
      adjustedCoords.set(s.id, { e: s.easting, n: s.northing, h: s.elevation })
    }

    for (let i = 0; i < observations.length; i++) {
      const obs = observations[i]

      // Compute the residual for this observation
      let residual = 0
      let sigma = 0.005

      if (obs.type === 'coordinate_diff' && obs.from && obs.to) {
        const fromC = adjustedCoords.get(obs.from)
        const toC = adjustedCoords.get(obs.to)
        if (fromC && toC) {
          // Use the E component residual (could also average all 3)
          const predictedE = toC.e - fromC.e
          residual = obs.deltaE! - predictedE
          sigma = obs.stdDevE ?? 0.005
        }
      } else if (obs.type === 'slope_distance' && obs.from && obs.to) {
        const fromC = adjustedCoords.get(obs.from)
        const toC = adjustedCoords.get(obs.to)
        if (fromC && toC) {
          const dE = toC.e - fromC.e
          const dN = toC.n - fromC.n
          const dH = toC.h - fromC.h
          const predicted = Math.sqrt(dE * dE + dN * dN + dH * dH)
          residual = obs.distance! - predicted
          sigma = obs.stdDevDistance ?? 0.003
        }
      } else if (obs.type === 'horizontal_direction' && obs.from && obs.to) {
        const fromC = adjustedCoords.get(obs.from)
        const toC = adjustedCoords.get(obs.to)
        if (fromC && toC) {
          const dE = toC.e - fromC.e
          const dN = toC.n - fromC.n
          const predicted = Math.atan2(dE, dN)
          residual = obs.direction! - predicted
          sigma = obs.stdDevDirection ?? 5e-6
        }
      } else if (obs.type === 'zenith_angle' && obs.from && obs.to) {
        const fromC = adjustedCoords.get(obs.from)
        const toC = adjustedCoords.get(obs.to)
        if (fromC && toC) {
          const dE = toC.e - fromC.e
          const dN = toC.n - fromC.n
          const dH = toC.h - fromC.h
          const predicted = Math.atan2(Math.sqrt(dE * dE + dN * dN), dH)
          residual = obs.zenith! - predicted
          sigma = obs.stdDevZenith ?? 5e-6
        }
      } else if (obs.type === 'height_difference' && obs.from && obs.to) {
        const fromC = adjustedCoords.get(obs.from)
        const toC = adjustedCoords.get(obs.to)
        if (fromC && toC) {
          const predicted = toC.h - fromC.h
          residual = obs.deltaH! - predicted
          sigma = obs.stdDevH ?? 0.002
        }
      }

      // Standardize: u = residual / (σ₀ × σ)
      const sigmaZero = lastResult.sigmaZero > 1e-10 ? lastResult.sigmaZero : 1.0
      const u = sigma > 0 ? residual / (sigmaZero * sigma) : 0

      const newW = computeRobustWeight(u, fn, {
        huberC: options.huberC,
        igg3K0: options.igg3K0,
        igg3K1: options.igg3K1,
        tukeyC: options.tukeyC,
      })

      newWeights.push(newW)
    }

    // Check convergence: max weight change
    let maxChange = 0
    for (let i = 0; i < currentWeights.length; i++) {
      maxChange = Math.max(maxChange, Math.abs(newWeights[i] - currentWeights[i]))
    }

    currentWeights = newWeights
    finalWeights = newWeights

    if (maxChange < threshold) {
      converged = true
      break
    }
  }

  if (!converged) {
    warnings.push(`IRLS did not converge after ${maxIter} iterations (final weight change: ${threshold.toFixed(4)}). Results may be less reliable.`)
  }

  // Identify blunders (weight < 0.1, i.e., 90% down-weighted)
  const blunders: RobustLSAResult['blunders'] = []
  for (let i = 0; i < observations.length; i++) {
    if (finalWeights[i] < 0.1) {
      const obs = observations[i]
      // Find the residual for this observation (first component for coord_diff)
      const numComponents = obs.type === 'coordinate_diff' ? 3 : 1
      const startIdx = observations.slice(0, i).reduce(
        (sum, o) => sum + (o.type === 'coordinate_diff' ? 3 : 1), 0,
      )
      const residual = lastResult.residuals[startIdx] ?? 0
      const stdRes = lastResult.standardizedResiduals[startIdx] ?? 0

      blunders.push({
        index: i,
        type: obs.type,
        from: obs.from,
        to: obs.to,
        component: obs.type === 'coordinate_diff' ? 'E' : undefined,
        residual,
        standardizedResidual: stdRes,
        finalWeight: finalWeights[i],
      })
    }
  }

  if (blunders.length > 0) {
    warnings.push(`${blunders.length} blunder(s) detected and down-weighted by ${fn} IRLS.`)
  }

  // Build summary
  const summary = buildSummary(fn, iteration + (converged ? 1 : 0), converged, lastResult.sigmaZero, blunders.length, lastResult.degreesOfFreedom)

  return {
    adjustedStations: lastResult.adjustedStations,
    sigmaZero: lastResult.sigmaZero,
    degreesOfFreedom: lastResult.degreesOfFreedom,
    iterations: iteration + (converged ? 1 : 0),
    converged,
    finalWeights,
    blunders,
    blunderCount: blunders.length,
    method: fn,
    warnings,
    summary,
  }
}

function buildSummary(
  method: WeightFunction,
  iterations: number,
  converged: boolean,
  sigmaZero: number,
  blunderCount: number,
  dof: number,
): string {
  const status = converged ? 'converged' : 'did NOT converge'
  const blunderText = blunderCount === 0
    ? 'No blunders detected.'
    : `${blunderCount} blunder(s) detected and down-weighted.`

  return `Robust LSA (${method.toUpperCase()}) ${status} in ${iterations} iterations. σ₀=${sigmaZero.toFixed(4)}, dof=${dof}. ${blunderText}`
}

/**
 * Total Least Squares (TLS) — errors-in-variables adjustment
 *
 * PROBLEM
 * -------
 * Standard least-squares assumes the design matrix A is known exactly and
 * only the observation vector l has errors:
 *   l = A·x + ε,  E[ε] = 0
 *
 * In reality, both A and l have errors. When you tie a new survey into
 * 1960s-era Cassini control points that were converted to UTM (accumulating
 * transformation errors), standard LSA pretends the control is perfect —
 * but it isn't. The control point coordinates themselves have uncertainties
 * of 0.1-1m.
 *
 * TLS accounts for errors in BOTH A and l. The model is:
 *   (A + ΔA)·x = l + Δl
 *
 * where ΔA and Δl are the corrections to A and l, and we minimize ||[ΔA | Δl]||_F
 * (Frobenius norm of the combined correction matrix).
 *
 * SOLUTION: SVD-based TLS
 * -----------------------
 * The TLS solution is obtained via the SVD of the augmented matrix [A | l]:
 *   [A | l] = U·Σ·V^T
 *
 * If the smallest singular value corresponds to the last column of V, then:
 *   x_TLS = -V(1:n, n+1) / V(n+1, n+1)
 *
 * This requires the "Van Huffel" algorithm for the general case where A
 * has more than one column. For geodetic networks with hundreds of unknowns,
 * we use the iterative TLS algorithm of Schaffrin (2006) instead.
 *
 * APPLICATION IN GEODESY
 * ----------------------
 * For coordinate transformations with uncertain control, TLS gives:
 *   - More accurate transformation parameters
 *   - Honest standard deviations that reflect control uncertainty
 *   - Better residuals (that don't favor the "fixed" control points)
 *
 * For LSA networks with uncertain control, TLS treats fixed stations as
 * "noisy observations" rather than perfect constraints — propagating their
 * uncertainty into the adjusted coordinates.
 *
 * REFERENCES
 * ----------
 * - Golub, G.H. & Van Loan, C.F. (1980). "An Analysis of the Total Least
 *   Squares Problem." SIAM J. Numer. Anal., 17(6).
 * - Van Huffel, S. & Vandewalle, J. (1991). The Total Least Squares
 *   Problem: Computational Aspects and Analysis. SIAM.
 * - Schaffrin, B. (2006). "A note on Computing the TLS Solution in the
 *   Presence of Linear Constraints." Geodetic Theory and Applications.
 * - Schaffrin, B. & Wieser, A. (2008). "On Weighted Total Least-Squares
 *   Adjustment for Linear Regression." Journal of Geodesy, 82(7).
 * - Krystek, M. & Anton, M. (2007). "A weighted total least-squares
 *   algorithm for fitting a straight line." Meas. Sci. Technol., 18.
 */

// ─── Types ──────────────────────────────────────────────────────────────────

export interface TLSInput {
  /** Design matrix A (m × n) — may contain errors */
  A: number[][]
  /** Observation vector l (m × 1) — contains errors */
  l: number[]
  /** Optional: variance-covariance matrix of A's errors (m·n × m·n) — for WTLS */
  /** If not provided, assume A's errors are i.i.d. with unit variance */
  A_variances?: number[]  // per-element variance of A (length = m·n, row-major)
  /** Optional: weights for observations l (m × 1) */
  l_weights?: number[]  // per-row weight of l (length = m)
}

export interface TLSResult {
  /** Adjusted parameter vector x (n × 1) */
  x: number[]
  /** Corrections to A (ΔA, m × n) */
  deltaA: number[][]
  /** Corrections to l (Δl, m × 1) */
  deltal: number[]
  /** Adjusted design matrix A + ΔA */
  A_adjusted: number[][]
  /** Adjusted observation vector l + Δl */
  l_adjusted: number[]
  /** Residuals (l - A·x, the standard LS residuals for comparison) */
  residuals: number[]
  /** Reference standard deviation σ₀ */
  sigmaZero: number
  /** Variance-covariance matrix of x (n × n) */
  Qxx: number[][]
  /** Degrees of freedom (m - n) */
  degreesOfFreedom: number
  /** Method used ('standard_tls' for SVD, 'iterative_wtls' for Schaffrin) */
  method: string
  /** Number of iterations (for iterative methods) */
  iterations: number
  /** Warnings */
  warnings: string[]
}

// ─── Standard TLS via SVD ───────────────────────────────────────────────────

/**
 * Compute the Total Least Squares solution using SVD.
 *
 * This is the classic Golub-Van Loan (1980) algorithm. Suitable for small
 * problems (n < 100). For larger problems, use the iterative WTLS.
 *
 * Algorithm:
 *   1. Form augmented matrix [A | l] (m × (n+1))
 *   2. Compute SVD: [A | l] = U·Σ·V^T
 *   3. Partition V: V = [V11 V12; V21 V22] where V22 is scalar (last column)
 *   4. x_TLS = -V12 / V22 = -V(1:n, n+1) / V(n+1, n+1)
 *   5. ΔA = -A·x·x^T / (1 + x^T·x)  (correction to A)
 *   6. Δl = -l·x^T·x / (1 + x^T·x)  (correction to l) — actually Δl = -l_normalized
 *
 * @param input - TLS input (A, l, optional variances)
 */
export function computeStandardTLS(input: TLSInput): TLSResult {
  const { A, l } = input
  const m = A.length
  const n = A[0].length

  const warnings: string[] = []

  if (m < n + 1) {
    warnings.push(`Insufficient observations for TLS: m=${m} < n+1=${n + 1}. Solution may be unstable.`)
  }

  // Step 1: Form augmented matrix [A | l] (m × (n+1))
  const augmented: number[][] = A.map((row, i) => [...row, l[i]])

  // Step 2: Compute SVD using Jacobi eigendecomposition of [A|l]^T · [A|l]
  // For small problems this is more numerically stable than full SVD.
  // [A|l]^T · [A|l] is (n+1) × (n+1), small enough for Jacobi.
  const AtA = matMul(transpose(augmented), augmented)  // (n+1) × (n+1)

  // Jacobi eigenvalue decomposition
  const { eigenvalues, eigenvectors } = jacobiEigen(AtA)

  // Find the smallest eigenvalue's eigenvector
  let minIdx = 0
  for (let i = 1; i < eigenvalues.length; i++) {
    if (eigenvalues[i] < eigenvalues[minIdx]) minIdx = i
  }

  // The eigenvector corresponding to the smallest eigenvalue is the TLS solution
  // (up to a scale factor). The TLS solution is:
  //   x_TLS = -v(1:n) / v(n+1)  where v is the eigenvector
  const v = eigenvectors.map(row => row[minIdx])
  const vN1 = v[n]  // last element (V22)

  if (Math.abs(vN1) < 1e-15) {
    warnings.push('TLS solution is degenerate (V22 ≈ 0). The system may not have a unique TLS solution. Falling back to standard LS.')
    // Fall back to standard LS
    return computeStandardLSFallback(A, l, warnings)
  }

  const x = v.slice(0, n).map(vi => -vi / vN1)

  // Step 5-6: Compute corrections
  // ΔA and Δl are computed from the TLS error model:
  //   [ΔA | Δl] = -[A | l] · x · x^T / (1 + x^T·x)  ... actually simpler:
  //   [ΔA | Δl] = -[A | l] · v · v^T  (since v is unit-length)
  // But the standard formula is:
  //   ΔA = -A·x·x^T / (1 + x^T·x)
  //   Δl = -l·x^T / (1 + x^T·x)  ... no, this is wrong dimensionally.
  //
  // The correct formulas (Golub-Van Loan, 1980, eq. 4.6-4.7):
  //   The TLS correction is: ΔA = -d·v^T where d = (l - A·x)·v_last / v_last_last
  // But for simplicity, let's use the projection approach:
  //   The corrected system [A+ΔA | l+Δl] has rank n, with [A+ΔA]·x = l+Δl.
  //   The "minimum-norm" correction projects [A|l] onto the closest rank-n matrix.
  const xNorm2 = x.reduce((s, xi) => s + xi * xi, 0)
  const scale = 1 / (1 + xNorm2)

  // Compute predictions A·x
  const Ax = A.map(row => row.reduce((s, a, j) => s + a * x[j], 0))
  // Residuals l - A·x (standard LS residuals)
  const residuals = l.map((li, i) => li - Ax[i])

  // TLS corrections: Δl = l + Δl - l = (A+ΔA)·x - l... use projection formula
  // For each row i: [ΔA_row | Δl_row] = -r_i · v^T  where r_i = (l_i - A_i·x) / (1 + x^T·x)
  // Wait, simpler: the TLS correction to row i is:
  //   [ΔA_i | Δl_i] = -((l_i - A_i·x) / (1 + x^T·x)) · [x^T | 1]
  // (This makes [A_i + ΔA_i | l_i + Δl_i] · [x; -1] = 0, which is the rank-n condition.)

  const deltaA: number[][] = []
  const deltal: number[] = []
  const A_adjusted: number[][] = []
  const l_adjusted: number[] = []

  for (let i = 0; i < m; i++) {
    const r_i = (l[i] - Ax[i]) * scale
    const dA_i = x.map(xj => -r_i * xj)
    const dl_i = -r_i  // the last component v(n+1) = 1 in the normalized form

    deltaA.push(dA_i)
    deltal.push(dl_i)
    A_adjusted.push(A[i].map((a, j) => a + dA_i[j]))
    l_adjusted.push(l[i] + dl_i)
  }

  // Compute σ₀ and Qxx
  // For TLS, the σ₀ computation is different from LS. We use the standard
  // approximation: σ₀² ≈ ||l - A·x||² / (m - n)  (same as LS, approximately)
  const dof = m - n
  const vWv = residuals.reduce((s, r) => s + r * r, 0)
  const sigmaZero = dof > 0 ? Math.sqrt(vWv / dof) : 0

  // Qxx for TLS is also different. The Schaffrin-Wieser (2008) formula:
  //   Qxx_TLS ≈ (1 + x^T·x) · (A^T·A)^(-1)  (approximation)
  const AtA_n = matMul(transpose(A), A)
  const Qxx = invertMatrix(AtA_n, n).map((row, i) =>
    row.map(v => v * (1 + xNorm2)),
  )

  return {
    x,
    deltaA,
    deltal,
    A_adjusted,
    l_adjusted,
    residuals,
    sigmaZero,
    Qxx,
    degreesOfFreedom: dof,
    method: 'standard_tls',
    iterations: 0,
    warnings,
  }
}

// ─── Weighted TLS (Schaffrin-Wieser iterative) ──────────────────────────────

/**
 * Compute the Weighted Total Least Squares solution using the
 * Schaffrin-Wieser (2008) iterative algorithm.
 *
 * This handles the case where:
 *   - Different rows of A have different variances (heteroscedastic)
 *   - Different columns of A have different variances
 *
 * Algorithm (simplified for diagonal weight matrices):
 *   1. Start with standard LS solution: x_0 = (A^T·P·A)^(-1)·A^T·P·l
 *   2. Iterate:
 *      a. Compute residuals: v = l - A·x
 *      b. Compute weight scaling: λ = v^T·P·v / (m - n)
 *      c. Update A's row weights: P_A_i = P_l_i / (1 + x^T·x / λ)
 *      d. Solve WTLS: x = (A^T·P_eff·A)^(-1)·A^T·P_eff·l
 *      e. Repeat until ||x_new - x_old|| < threshold
 *
 * @param input - TLS input with weights
 * @param options - Iteration options
 */
export function computeWeightedTLS(
  input: TLSInput,
  options: { maxIterations?: number; convergenceThreshold?: number } = {},
): TLSResult {
  const { A, l, l_weights } = input
  const m = A.length
  const n = A[0].length
  const maxIter = options.maxIterations ?? 50
  const threshold = options.convergenceThreshold ?? 1e-10

  const warnings: string[] = []

  // Initial weights (default to unit weight)
  const P: number[] = l_weights ?? new Array<number>(m).fill(1.0)

  // Step 1: Initial standard LS solution
  // x_0 = (A^T·P·A)^(-1)·A^T·P·l
  const AtPA = matMul(matMul(transpose(A), diag(P)), A)
  const AtPl = matVec(matMul(transpose(A), diag(P)), l)
  const x_initial = solveLinearSystem(AtPA, AtPl, n)

  if (!x_initial) {
    warnings.push('Initial LS solve failed — singular matrix. Try with different data.')
    return computeStandardTLS(input)
  }

  let x: number[] = x_initial

  let iteration = 0
  let converged = false
  let prevX = [...x]

  for (; iteration < maxIter; iteration++) {
    // Compute residuals v = l - A·x
    const Ax = A.map(row => row.reduce((s, a, j) => s + a * x[j], 0))
    const v = l.map((li, i) => li - Ax[i])

    // Compute λ = v^T·P·v / (m - n)
    const vPv = v.reduce((s, vi, i) => s + P[i] * vi * vi, 0)
    const dof = m - n
    const lambda = dof > 0 ? vPv / dof : 1

    if (lambda < 1e-15) {
      converged = true
      break
    }

    // Update effective weights: P_eff_i = P_i / (1 + x^T·x / λ)
    // This accounts for the uncertainty in A being proportional to x
    const xNorm2 = x.reduce((s, xi) => s + xi * xi, 0)
    const Peff = P.map(pi => pi / (1 + xNorm2 / lambda))

    // Solve WTLS: x = (A^T·P_eff·A)^(-1)·A^T·P_eff·l
    const AtPeA = matMul(matMul(transpose(A), diag(Peff)), A)
    const AtPel = matVec(matMul(transpose(A), diag(Peff)), l)
    const newX = solveLinearSystem(AtPeA, AtPel, n)

    if (!newX) {
      warnings.push(`Iteration ${iteration + 1}: singular matrix. Stopping.`)
      break
    }

    // Convergence check
    const correction = Math.sqrt(newX.reduce((s, xi, i) => s + (xi - prevX[i]) ** 2, 0))
    prevX = [...newX]
    x = newX

    if (correction < threshold) {
      converged = true
      break
    }
  }

  if (!converged) {
    warnings.push(`WTLS did not converge after ${maxIter} iterations.`)
  }

  // Compute final residuals and corrections
  const Ax = A.map(row => row.reduce((s, a, j) => s + a * x[j], 0))
  const residuals = l.map((li, i) => li - Ax[i])

  const vPv = residuals.reduce((s, vi, i) => s + P[i] * vi * vi, 0)
  const dof = m - n
  const sigmaZero = dof > 0 ? Math.sqrt(vPv / dof) : 0

  // Compute corrections
  const xNorm2 = x.reduce((s, xi) => s + xi * xi, 0)
  const scale = 1 / (1 + xNorm2)
  const deltaA: number[][] = []
  const deltal: number[] = []
  const A_adjusted: number[][] = []
  const l_adjusted: number[] = []

  for (let i = 0; i < m; i++) {
    const r_i = (l[i] - Ax[i]) * scale
    const dA_i = x.map(xj => -r_i * xj)
    const dl_i = -r_i
    deltaA.push(dA_i)
    deltal.push(dl_i)
    A_adjusted.push(A[i].map((a, j) => a + dA_i[j]))
    l_adjusted.push(l[i] + dl_i)
  }

  // Qxx
  const AtPA_final = matMul(matMul(transpose(A), diag(P)), A)
  const Qxx = invertMatrix(AtPA_final, n)

  return {
    x,
    deltaA,
    deltal,
    A_adjusted,
    l_adjusted,
    residuals,
    sigmaZero,
    Qxx,
    degreesOfFreedom: dof,
    method: 'iterative_wtls',
    iterations: iteration + (converged ? 1 : 0),
    warnings,
  }
}

// ─── Standard LS Fallback ───────────────────────────────────────────────────

function computeStandardLSFallback(A: number[][], l: number[], warnings: string[]): TLSResult {
  const m = A.length
  const n = A[0].length

  const AtA = matMul(transpose(A), A)
  const Atl = matVec(transpose(A), l)
  const x = solveLinearSystem(AtA, Atl, n) || new Array<number>(n).fill(0)

  const Ax = A.map(row => row.reduce((s, a, j) => s + a * x[j], 0))
  const residuals = l.map((li, i) => li - Ax[i])

  const dof = m - n
  const vWv = residuals.reduce((s, r) => s + r * r, 0)
  const sigmaZero = dof > 0 ? Math.sqrt(vWv / dof) : 0

  const Qxx = invertMatrix(AtA, n)

  return {
    x,
    deltaA: A.map(() => new Array<number>(n).fill(0)),
    deltal: new Array<number>(m).fill(0),
    A_adjusted: A,
    l_adjusted: l,
    residuals,
    sigmaZero,
    Qxx,
    degreesOfFreedom: dof,
    method: 'standard_ls_fallback',
    iterations: 0,
    warnings,
  }
}

// ─── Matrix Helpers ─────────────────────────────────────────────────────────

function transpose(A: number[][]): number[][] {
  const rows = A.length
  const cols = A[0].length
  const result: number[][] = Array.from({ length: cols }, () => new Array<number>(rows).fill(0))
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      result[j][i] = A[i][j]
    }
  }
  return result
}

function matMul(A: number[][], B: number[][]): number[][] {
  const rows = A.length
  const cols = B[0].length
  const inner = B.length
  const result: number[][] = Array.from({ length: rows }, () => new Array<number>(cols).fill(0))
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      let sum = 0
      for (let k = 0; k < inner; k++) {
        sum += A[i][k] * B[k][j]
      }
      result[i][j] = sum
    }
  }
  return result
}

function matVec(A: number[][], v: number[]): number[] {
  return A.map(row => row.reduce((s, a, i) => s + a * v[i], 0))
}

function diag(v: number[]): number[][] {
  const n = v.length
  return Array.from({ length: n }, (_, i) =>
    Array.from({ length: n }, (_, j) => (i === j ? v[i] : 0)),
  )
}

function solveLinearSystem(A: number[][], b: number[], n: number): number[] | null {
  const M = A.map((row, i) => [...row, b[i]])
  for (let col = 0; col < n; col++) {
    let maxRow = col
    for (let row = col + 1; row < n; row++) {
      if (Math.abs(M[row][col]) > Math.abs(M[maxRow][col])) maxRow = row
    }
    ;[M[col], M[maxRow]] = [M[maxRow], M[col]]

    if (Math.abs(M[col][col]) < 1e-15) return null

    for (let row = col + 1; row < n; row++) {
      const factor = M[row][col] / M[col][col]
      for (let k = col; k <= n; k++) M[row][k] -= factor * M[col][k]
    }
  }

  const x = new Array<number>(n).fill(0)
  for (let i = n - 1; i >= 0; i--) {
    x[i] = M[i][n]
    for (let j = i + 1; j < n; j++) x[i] -= M[i][j] * x[j]
    x[i] /= M[i][i]
  }
  return x
}

function invertMatrix(A: number[][], n: number): number[][] {
  if (A.length === 0) return Array.from({ length: n }, () => new Array<number>(n).fill(0))
  const M = A.map((row, i) => {
    const aug: number[] = [...row, ...new Array<number>(n).fill(0)]
    aug[n + i] = 1
    return aug
  })

  for (let col = 0; col < n; col++) {
    let maxRow = col
    for (let row = col + 1; row < n; row++) {
      if (Math.abs(M[row][col]) > Math.abs(M[maxRow][col])) maxRow = row
    }
    ;[M[col], M[maxRow]] = [M[maxRow], M[col]]

    const pivot = M[col][col]
    if (Math.abs(pivot) < 1e-15) return Array.from({ length: n }, () => new Array<number>(n).fill(0))

    for (let k = 0; k < 2 * n; k++) M[col][k] /= pivot
    for (let row = 0; row < n; row++) {
      if (row === col) continue
      const factor = M[row][col]
      for (let k = 0; k < 2 * n; k++) M[row][k] -= factor * M[col][k]
    }
  }

  return M.map(row => row.slice(n))
}

/**
 * Jacobi eigenvalue algorithm for symmetric matrices.
 *
 * Returns eigenvalues and eigenvectors of a symmetric n×n matrix.
 * Used by TLS to compute the SVD of [A|l] via eigendecomposition of [A|l]^T·[A|l].
 *
 * Algorithm: classic Jacobi rotations (Press et al., Numerical Recipes, §11.1).
 * Converges in ~5-10 sweeps for typical matrices.
 */
function jacobiEigen(A_in: number[][]): { eigenvalues: number[]; eigenvectors: number[][] } {
  const n = A_in.length
  // Copy A (work on a copy)
  const A = A_in.map(row => [...row])
  // V starts as identity
  const V: number[][] = Array.from({ length: n }, (_, i) =>
    Array.from({ length: n }, (_, j) => (i === j ? 1 : 0) as number),
  )

  const maxSweeps = 100
  for (let sweep = 0; sweep < maxSweeps; sweep++) {
    // Compute off-diagonal sum of squares
    let offDiag = 0
    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        offDiag += A[i][j] * A[i][j]
      }
    }
    if (offDiag < 1e-20) break  // converged

    for (let p = 0; p < n - 1; p++) {
      for (let q = p + 1; q < n; q++) {
        if (Math.abs(A[p][q]) < 1e-20) continue

        // Compute rotation angle
        const theta = (A[q][q] - A[p][p]) / (2 * A[p][q])
        let t: number
        if (Math.abs(theta) > 1e10) {
          t = 1 / (2 * theta)
        } else {
          t = Math.sign(theta) / (Math.abs(theta) + Math.sqrt(theta * theta + 1))
        }
        const c: number = 1 / Math.sqrt(t * t + 1)
        const s: number = t * c

        // Apply rotation
        const app = A[p][p]
        const aqq = A[q][q]
        const apq = A[p][q]

        A[p][p] = c * c * app - 2 * s * c * apq + s * s * aqq
        A[q][q] = s * s * app + 2 * s * c * apq + c * c * aqq
        A[p][q] = 0
        A[q][p] = 0

        for (let i = 0; i < n; i++) {
          if (i !== p && i !== q) {
            const aip = A[i][p]
            const aiq = A[i][q]
            A[i][p] = c * aip - s * aiq
            A[p][i] = A[i][p]
            A[i][q] = s * aip + c * aiq
            A[q][i] = A[i][q]
          }
          // Update eigenvector matrix
          const vip = V[i][p]
          const viq = V[i][q]
          V[i][p] = c * vip - s * viq
          V[i][q] = s * vip + c * viq
        }
      }
    }
  }

  // Eigenvalues are on the diagonal of A
  const eigenvalues = A.map((row, i) => row[i])

  return { eigenvalues, eigenvectors: V }
}

/**
 * Traverse Computation Engine
 * 
 * Computes adjusted coordinates for a traverse (open or closed)
 * using either the Bowditch/Compass rule or Least Squares adjustment.
 * 
 * For 3rd/4th order: Bowditch adjustment (proportional distribution)
 * For 1st/2nd order: Least Squares adjustment (statistically optimal)
 * 
 * References:
 * - Schofield, W. (2001) "Engineering Surveying"
 * - Anderson & Mikhail (1998) "Surveying: Theory and Practice"
 */

// ─── Types ───────────────────────────────────────────────────────

export interface TraverseStation {
  name: string;
  easting?: number;    // Known for control points
  northing?: number;   // Known for control points
  isFixed: boolean;    // Control/fixed point
}

export interface TraverseLeg {
  fromStation: string;
  toStation: string;
  bearing: number;       // Decimal degrees (0-360)
  distance: number;      // Meters (already corrected through pipeline)
  stdDevBearing?: number; // Standard deviation of bearing (seconds)
  stdDevDistance?: number; // Standard deviation of distance (meters)
}

export interface TraverseResult {
  stations: AdjustedStation[];
  misclosure: {
    easting: number;       // meters
    northing: number;      // meters
    linear: number;        // meters (total linear misclosure)
    angular: number;       // seconds (angular misclosure)
    ratio: string;         // e.g., "1:25000"
    ratioValue: number;    // numeric ratio denominator
  };
  adjustmentMethod: 'bowditch' | 'least_squares';
  order: number;           // 1st, 2nd, 3rd, 4th
  passesOrder: boolean;    // Whether misclosure meets the order requirement
  totalDistance: number;   // meters
  warnings: string[];
}

export interface AdjustedStation {
  name: string;
  easting: number;
  northing: number;
  correctionE: number;     // Correction applied (meters)
  correctionN: number;     // Correction applied (meters)
  isFixed: boolean;
  stdDevE?: number;        // From least squares
  stdDevN?: number;        // From least squares
}

// ─── Accuracy Order Requirements ─────────────────────────────────

/** Minimum misclosure ratio for each survey order */
export const ORDER_REQUIREMENTS: Record<number, number> = {
  1: 100000,   // 1st order: 1:100,000
  2: 20000,    // 2nd order: 1:20,000
  3: 10000,    // 3rd order: 1:10,000 (Kenya cadastral minimum)
  4: 5000,     // 4th order: 1:5,000 (topographic)
};

/** Default standard deviations for each order */
export const ORDER_STDS: Record<number, { angle: number; distPPM: number }> = {
  1: { angle: 1.0, distPPM: 5 },       // 1", 5 ppm
  2: { angle: 2.0, distPPM: 10 },       // 2", 10 ppm
  3: { angle: 5.0, distPPM: 20 },       // 5", 20 ppm
  4: { angle: 10.0, distPPM: 50 },      // 10", 50 ppm
};

// ─── Bowditch (Compass Rule) Adjustment ──────────────────────────

/**
 * Apply Bowditch/Compass rule adjustment to a closed traverse.
 * 
 * The Bowditch rule distributes the misclosure proportionally
 * to the cumulative distance from the start:
 * 
 *   Correction_E(i) = -misclosure_E × (Σd₀→i / Σd_total)
 *   Correction_N(i) = -misclosure_N × (Σd₀→i / Σd_total)
 * 
 * This is the standard method for 3rd and 4th order traverses
 * and is accepted by Kenya Survey Department for cadastral work.
 * 
 * @param stations - Traverse stations (with fixed coordinates for control points)
 * @param legs - Traverse legs with bearings and distances
 * @param order - Required accuracy order (1-4)
 * @returns Traverse result with adjusted coordinates
 */
export function bowditchAdjustment(
  stations: TraverseStation[],
  legs: TraverseLeg[],
  order: number = 3
): TraverseResult {
  const warnings: string[] = [];
  
  // Validate: need at least 2 fixed stations
  const fixedStations = stations.filter(s => s.isFixed && s.easting !== undefined && s.northing !== undefined);
  if (fixedStations.length < 2) {
    throw new Error('Need at least 2 fixed control stations for traverse');
  }
  
  // Compute preliminary coordinates
  const preliminary = computePreliminaryCoordinates(stations, legs);
  
  // Compute misclosure
  const misclosure = computeMisclosure(preliminary, stations, legs);
  
  // Check angular misclosure
  const angularClosure = computeAngularClosure(legs, fixedStations);
  misclosure.angular = angularClosure;
  
  // Compute total traverse distance
  const totalDistance = legs.reduce((sum, leg) => sum + leg.distance, 0);
  
  // Compute misclosure ratio
  const ratioValue = totalDistance / misclosure.linear;
  misclosure.ratioValue = ratioValue;
  misclosure.ratio = `1:${Math.round(ratioValue)}`;
  
  // Check against order requirement
  const requiredRatio = ORDER_REQUIREMENTS[order] ?? ORDER_REQUIREMENTS[3];
  const passesOrder = ratioValue >= requiredRatio;
  
  if (!passesOrder) {
    warnings.push(
      `Traverse closure ${misclosure.ratio} does NOT meet ${order} order requirement (1:${requiredRatio})`
    );
  }
  
  // Apply Bowditch corrections
  const adjusted: AdjustedStation[] = [];
  let cumulativeDistance = 0;
  
  for (let i = 0; i < preliminary.length; i++) {
    const station = preliminary[i];
    
    if (station.isFixed) {
      adjusted.push({
        name: station.name,
        easting: stations.find(s => s.name === station.name)!.easting!,
        northing: stations.find(s => s.name === station.name)!.northing!,
        correctionE: 0,
        correctionN: 0,
        isFixed: true,
      });
    } else {
      // Proportional correction based on cumulative distance
      const proportion = cumulativeDistance / totalDistance;
      const corrE = -misclosure.easting * proportion;
      const corrN = -misclosure.northing * proportion;
      
      adjusted.push({
        name: station.name,
        easting: (station.easting ?? 0) + corrE,
        northing: (station.northing ?? 0) + corrN,
        correctionE: corrE,
        correctionN: corrN,
        isFixed: false,
      });
    }
    
    // Add distance to next leg
    const leg = legs.find(l => l.fromStation === station.name);
    if (leg) {
      cumulativeDistance += leg.distance;
    }
  }
  
  return {
    stations: adjusted,
    misclosure,
    adjustmentMethod: 'bowditch',
    order,
    passesOrder,
    totalDistance,
    warnings,
  };
}

// ─── Helper Functions ────────────────────────────────────────────

/**
 * Compute preliminary (unadjusted) traverse coordinates.
 */
function computePreliminaryCoordinates(
  stations: TraverseStation[],
  legs: TraverseLeg[]
): TraverseStation[] {
  const result: TraverseStation[] = [];
  const coordMap = new Map<string, { easting: number; northing: number }>();
  
  // Initialize with fixed station coordinates
  for (const station of stations) {
    if (station.isFixed && station.easting !== undefined && station.northing !== undefined) {
      coordMap.set(station.name, { easting: station.easting, northing: station.northing });
    }
  }
  
  // Compute coordinates along each leg
  for (const leg of legs) {
    const from = coordMap.get(leg.fromStation);
    if (!from) {
      throw new Error(`No coordinates for station ${leg.fromStation}`);
    }
    
    const bearingRad = leg.bearing * Math.PI / 180;
    const dE = leg.distance * Math.sin(bearingRad);
    const dN = leg.distance * Math.cos(bearingRad);
    
    const toCoord = {
      easting: from.easting + dE,
      northing: from.northing + dN,
    };
    
    coordMap.set(leg.toStation, toCoord);
  }
  
  // Build result preserving order
  for (const station of stations) {
    const coord = coordMap.get(station.name);
    result.push({
      name: station.name,
      easting: coord?.easting,
      northing: coord?.northing,
      isFixed: station.isFixed,
    });
  }
  
  return result;
}

/**
 * Compute linear misclosure of a closed traverse.
 */
function computeMisclosure(
  preliminary: TraverseStation[],
  original: TraverseStation[],
  legs: TraverseLeg[]
): TraverseResult['misclosure'] {
  // For a closed traverse, the last computed position should
  // match the closing fixed point
  const firstFixed = original.find(s => s.isFixed && s.easting !== undefined);
  const lastLeg = legs[legs.length - 1];
  
  // Find the last computed position
  const lastComputed = preliminary.find(s => s.name === lastLeg.toStation);
  const closingPoint = original.find(s => s.name === lastLeg.toStation && s.isFixed);
  
  let dE = 0, dN = 0;
  
  if (closingPoint && closingPoint.easting !== undefined && closingPoint.northing !== undefined) {
    if (lastComputed?.easting !== undefined && lastComputed?.northing !== undefined) {
      dE = lastComputed.easting - closingPoint.easting;
      dN = lastComputed.northing - closingPoint.northing;
    }
  }
  
  const linear = Math.sqrt(dE * dE + dN * dN);
  
  return {
    easting: dE,
    northing: dN,
    linear,
    angular: 0, // Computed separately
    ratio: '',
    ratioValue: 0,
  };
}

