        { id: 'P2', e: 264200.010, n: 9861100.005, rl: 1500.002 }, // 11mm — PASS
        { id: 'P3', e: 264200.020, n: 9861200.015, rl: 1500.001 }, // 25mm — borderline
        { id: 'P4', e: 264100.005, n: 9861200.020, rl: 1500.003 }, // 21mm — PASS
