      asBuiltE: 100.010, asBuiltN: 200.005, asBuiltRL: 50.002,
      deltaE: 0.010, deltaN: 0.005, deltaRL: 0.002,
      horizontalOffset: 0.0112,
      hStatus: 'PASS' as const,
