/**
 * Statutory Gate — Project Data Loader
 * ====================================
 *
 * Fetches project data from the database and assembles it into the
 * StatutoryGateInput shape required by runStatutoryGate().
 *
 * This is the integration layer between the project database and the
 * pure-function gate. Keeping it separate from the gate itself means
 * the gate remains trivially testable (no DB mocking required) while
 * this loader can be tested with a test database.
 *
 * Usage:
 *   import { loadGateInputForProject } from '@/lib/validation/statutoryGateLoader'
 *   import { runStatutoryGate } from '@/lib/validation/statutoryGate'
 *
 *   const input = await loadGateInputForProject(projectId)
 *   const result = runStatutoryGate(input)
 *   if (!result.passed) {
 *     // refuse export, show result.violations
 *   }
 */

import { db } from '@/lib/db'
import type { SurveyPoint } from '@/types/surveyPoint'
import type { SurveyType } from '@/types/project'
import type { StatutoryGateInput } from './statutoryGate'
import { shoelaceArea } from '@/lib/engine/area'

// ─── Types matching DB row shapes ───────────────────────────────────────

interface ProjectRow {
  id: string
  survey_type: string | null
  utm_zone: number | null
  hemisphere: string | null
}

interface TraverseRow {
  id: string
  linear_misclosure: number | null
  precision_ratio: number | null
  angular_misclosure: number | null
}

interface TraverseCoordinateRow {
  station: string
  easting: number | string
  northing: number | string
  rl: number | string | null
}

interface FieldBookEntryRow {
  row_index: number
  station: string | null
  raw_data: Record<string, unknown> | null
}

interface ParcelRow {
  id: string
  parcel_number: string | null
  boundary_points: unknown
  area_sqm: number | string | null
}

// ─── Helpers ────────────────────────────────────────────────────────────

function normalizeSurveyType(raw: string | null): SurveyType {
  const v = (raw ?? '').toLowerCase()
  if (v.includes('cadastral') || v.includes('boundary')) return 'cadastral'
  if (v.includes('engineering') || v.includes('road') || v.includes('construction')) return 'engineering'
  if (v.includes('geodetic') || v.includes('control')) return 'geodetic'
  if (v.includes('drone') || v.includes('uav')) return 'drone'
  if (v.includes('deformation') || v.includes('monitor')) return 'deformation'
  return 'topographic'
}

/**
 * Extract traverse station count from field book entries.
 * Each unique station name counts as one station.
 */
function countStations(entries: FieldBookEntryRow[]): number {
  const stations = new Set<string>()
  for (const e of entries) {
    if (e.station) stations.add(e.station)
    else if (e.raw_data?.station) stations.add(String(e.raw_data.station))
  }
  return stations.size
}

/**
 * Parse boundary points from a parcel row. The boundary_points column
 * can be either a JSON array of {easting, northing} objects, or a JSON
 * string of the same. Returns an empty array if unparseable.
 */
function parseBoundaryPoints(raw: unknown, fallbackAreaSqm: number | null): {
  vertices: SurveyPoint[]
  areaHectares: number | null
} {
  let pts: Array<{ easting?: number; northing?: number; name?: string }> = []

  if (Array.isArray(raw)) {
    pts = raw as typeof pts
  } else if (typeof raw === 'string') {
    try {
            const parsed: unknown = JSON.parse(raw)
      if (Array.isArray(parsed)) pts = parsed as typeof pts
    } catch {
      // not JSON — ignore
    }
  }

  const vertices: SurveyPoint[] = pts.map((p, i) => ({
    name: p.name ?? `P${i + 1}`,
    easting: Number(p.easting ?? 0),
    northing: Number(p.northing ?? 0),
  }))

  // Prefer the stored area; fall back to shoelace if vertices exist
  let areaHectares: number | null = null
  if (fallbackAreaSqm !== null && !Number.isNaN(Number(fallbackAreaSqm))) {
    areaHectares = Number(fallbackAreaSqm) / 10000
  } else if (vertices.length >= 3) {
    areaHectares = shoelaceArea(vertices) / 10000
  }

  return { vertices, areaHectares }
}

// shoelaceArea is imported from @/lib/engine/area (canonical implementation)

// ─── Public API ─────────────────────────────────────────────────────────

/**
 * Load project data from the database and assemble it into a
 * StatutoryGateInput ready for runStatutoryGate().
 *
 * Returns null if the project cannot be found.
 *
 * The loader is defensive: missing tables or NULL columns degrade
 * gracefully (the corresponding gate input field is omitted) rather
 * than throwing. This means the gate can run on partial data and
 * report which rules couldn't be evaluated.
 */
export async function loadGateInputForProject(
  projectId: string
): Promise<StatutoryGateInput | null> {
  // 1. Project row
  const projectRes = await db.query(
    'SELECT id, survey_type, utm_zone, hemisphere FROM projects WHERE id = $1',
    [projectId]
  )
  if (projectRes.rows.length === 0) return null
  const project = projectRes.rows[0] as ProjectRow
  const surveyType = normalizeSurveyType(project.survey_type)

  // 2. Traverse + coordinates (via parcels → parcel_traverses)
  let traverse: StatutoryGateInput['traverse'] | undefined
  try {
    const traverseRes = await db.query(
      `SELECT pt.id, pt.linear_misclosure, pt.precision_ratio, pt.angular_misclosure
       FROM parcel_traverses pt
       JOIN parcels p ON p.id = pt.parcel_id
       JOIN blocks b ON b.id = p.block_id
       WHERE b.project_id = $1
       ORDER BY pt.created_at DESC LIMIT 1`,
      [projectId]
    )
    if (traverseRes.rows.length > 0) {
      const t = traverseRes.rows[0] as TraverseRow
      const coordsRes = await db.query(
        'SELECT station, easting, northing, rl FROM traverse_coordinates WHERE traverse_id = $1 ORDER BY station',
        [t.id]
      )
      const stationCount = coordsRes.rows.length

      // Compute total traverse distance from consecutive coordinates
      let totalDistanceM = 0
      const coords = coordsRes.rows as TraverseCoordinateRow[]
      for (let i = 1; i < coords.length; i++) {
        const dx = Number(coords[i].easting) - Number(coords[i - 1].easting)
        const dy = Number(coords[i].northing) - Number(coords[i - 1].northing)
        totalDistanceM += Math.sqrt(dx * dx + dy * dy)
      }

      const linearErrorM = t.linear_misclosure ?? 0
      // precision_ratio in DB is typically stored as the large number (e.g. 5000 = 1:5000)
      // If it's stored as a decimal (e.g. 0.0002), convert.
      const storedRatio = t.precision_ratio ?? 0
      const precisionRatio = storedRatio > 0 && storedRatio < 1
        ? 1 / storedRatio
        : storedRatio

      const angularMisclosureSeconds = t.angular_misclosure ?? undefined

      traverse = {
        stationCount,
        angularMisclosureSeconds,
        linearErrorM,
        totalDistanceM,
        precisionRatio,
      }
    }
  } catch {
    // traverse tables may not exist — skip
  }

  // 3. Field book entries (for station count fallback if no traverse)
  if (!traverse) {
    try {
      const fbRes = await db.query(
        'SELECT row_index, station, raw_data FROM project_fieldbook_entries WHERE project_id = $1 ORDER BY row_index ASC',
        [projectId]
      )
      const entries = fbRes.rows as FieldBookEntryRow[]
      if (entries.length > 0) {
        traverse = {
          stationCount: countStations(entries),
          angularMisclosureSeconds: undefined,
          linearErrorM: 0,
          totalDistanceM: 0,
          precisionRatio: 0,
        }
      }
    } catch {
      // field book table may not exist — skip
    }
  }

  // 4. Parcels + parent parcel (for cadastral)
  let parcels: StatutoryGateInput['parcels'] | undefined
  let parentParcel: StatutoryGateInput['parentParcel'] | undefined
  try {
    const parcelRes = await db.query(
      'SELECT id, parcel_number, boundary_points, area_sqm FROM parcels WHERE project_id = $1 ORDER BY created_at ASC',
      [projectId]
    )
    if (parcelRes.rows.length > 0) {
      const parcelRows = parcelRes.rows as ParcelRow[]
      const parsed = parcelRows.map((p) =>
        parseBoundaryPoints(p.boundary_points, p.area_sqm === null ? null : Number(p.area_sqm))
      )
      parcels = parsed.map((p, i) => ({
        vertices: p.vertices,
        parcelNumber: parcelRows[i].parcel_number ?? `Parcel ${i + 1}`,
      }))

      // First parcel is treated as the parent if there's only one,
      // otherwise the parent is unknown (subdivisions should have a
      // separate parent parcel reference — for now we use the largest).
      if (parsed.length === 1 && parsed[0].areaHectares !== null) {
        parentParcel = {
          areaHectares: parsed[0].areaHectares,
          vertices: parsed[0].vertices,
        }
      } else if (parsed.length > 1) {
        // Find the largest parcel as the likely parent
        let maxIdx = 0
        let maxArea = -1
        for (let i = 0; i < parsed.length; i++) {
          if (parsed[i].areaHectares !== null && (parsed[i].areaHectares ?? 0) > maxArea) {
            maxArea = parsed[i].areaHectares ?? 0
            maxIdx = i
          }
        }
        if (parsed[maxIdx].areaHectares !== null) {
          parentParcel = {
            areaHectares: parsed[maxIdx].areaHectares!,
            vertices: parsed[maxIdx].vertices,
          }
        }
      }
    }
  } catch {
    // parcels table may not exist — skip
  }

  // 5. Surveyor (no DB table yet — use placeholder, real value comes from
  // the auth session or a future surveyor_profile table)
  // For now we use empty strings; the gate will block on missing name/license
  // and the caller must supply these from the request context.
  const surveyor = {
    name: '',
    licenseNumber: '',
  }

  return {
    surveyType,
    traverse,
    parcels,
    parentParcel,
    surveyor,
  }
}

/**
 * Merge a partial gate input (typically containing the surveyor identity
 * from the auth session) over the input loaded from the database.
 *
 * This is the pattern callers should use:
 *   const loaded = await loadGateInputForProject(projectId)
 *   if (!loaded) throw new Error('Project not found')
 *   const input = mergeGateInput(loaded, { surveyor: sessionSurveyor })
 *   const result = runStatutoryGate(input)
 */
export function mergeGateInput(
  base: StatutoryGateInput,
  override: Partial<StatutoryGateInput>
): StatutoryGateInput {
  const result: StatutoryGateInput = {
    surveyType: override.surveyType ?? base.surveyType,
    surveyor: {
      name: override.surveyor?.name ?? base.surveyor.name,
      licenseNumber: override.surveyor?.licenseNumber ?? base.surveyor.licenseNumber,
    },
    traverse: override.traverse ?? base.traverse,
    leveling: override.leveling ?? base.leveling,
    parcels: override.parcels ?? base.parcels,
    parentParcel: override.parentParcel ?? base.parentParcel,
    engineering: override.engineering ?? base.engineering,
    rimOverlaps: override.rimOverlaps ?? base.rimOverlaps,
    submissionType: override.submissionType ?? base.submissionType,
    toleranceProfileOverride: override.toleranceProfileOverride ?? base.toleranceProfileOverride,
    areaToleranceHectares: override.areaToleranceHectares ?? base.areaToleranceHectares,
  }
  return result
}

/**
 * Tolerance Engine
 * Validates survey results against tolerance profiles following Basak standards
 * 
 * METARDU Calculation Standards: N.N. Basak
 * - No intermediate rounding
 * - Full floating point precision
 * - Round only at display layer
 */

export type ToleranceProfile = 'cadastral' | 'engineering' | 'control'

export interface ToleranceConfig {
  name: string
  description: string
  linearPrecision: number
  angularMisclosure: number
  closingErrorMmPerKm: number
}

export interface ToleranceCheckResult {
  passed: boolean
  profile: ToleranceProfile
  checks: ToleranceCheck[]
  precisionGrade: string
  recommendations: string[]
}

export interface ToleranceCheck {
  name: string
  passed: boolean
  actual: number
  allowable: number
  unit: string
  message: string
}

const TOLERANCE_CONFIGS: Record<ToleranceProfile, ToleranceConfig> = {
  cadastral: {
    name: 'Cadastral',
    description: 'Urban property boundary surveys',
    linearPrecision: 5000,
    angularMisclosure: 60,
    closingErrorMmPerKm: 10 // RDM 1.1 (2025) Table 5.1: 10√K mm
  },
  engineering: {
    name: 'Engineering',
    description: 'Construction and engineering surveys',
    linearPrecision: 10000,
    angularMisclosure: 30,
    closingErrorMmPerKm: 8
  },
  control: {
    name: 'Control',
    description: 'High-precision control networks',
    linearPrecision: 20000,
    angularMisclosure: 10,
    closingErrorMmPerKm: 4
  }
}

export function getToleranceConfig(profile: ToleranceProfile): ToleranceConfig {
  return TOLERANCE_CONFIGS[profile]
}

export function getAllToleranceProfiles(): ToleranceProfile[] {
  return ['cadastral', 'engineering', 'control']
}

export interface TraverseValidationInput {
  precisionRatio: number
  angularMisclosure: number | null
  linearError: number
  totalDistance: number
  numStations: number
}

export interface LevelingValidationInput {
  arithmeticCheckPassed: boolean
  arithmeticDiff: number
  closingError: number
  distanceKm: number
}

export interface ValidationInput {
  traverse?: TraverseValidationInput
  leveling?: LevelingValidationInput
}

export function checkTolerance(
  input: ValidationInput,
  profile: ToleranceProfile
): ToleranceCheckResult {
  const config = TOLERANCE_CONFIGS[profile]
  const checks: ToleranceCheck[] = []
  const recommendations: string[] = []

  if (input.traverse) {
    const { precisionRatio, angularMisclosure, linearError, totalDistance, numStations } = input.traverse

    // FIXED: Previous version used `precision = 1/precisionRatio` which is a tiny decimal
  // (e.g. 0.0002 for 1:5000), and compared it against config.linearPrecision (e.g. 5000).
  // This meant the check ALWAYS failed. The precisionRatio IS already the large number
  // (e.g. 5000 means 1:5000), so compare it directly.
  // Source: Basak, Ghilani & Wolf — precision ratio = perimeter / linearMisclosure
  checks.push({
      name: 'Linear Precision',
      passed: precisionRatio >= config.linearPrecision,
      actual: precisionRatio,
      allowable: config.linearPrecision,
      unit: '1:X',
      message: precisionRatio >= config.linearPrecision
        ? `Precision 1:${Math.round(precisionRatio)} meets ${config.name} standard (1:${config.linearPrecision})`
        : `Precision 1:${Math.round(precisionRatio)} below ${config.name} standard (1:${config.linearPrecision})`
    })

    if (angularMisclosure !== null) {
      const angularAllowable = config.angularMisclosure * Math.sqrt(numStations)
      checks.push({
        name: 'Angular Misclosure',
        passed: Math.abs(angularMisclosure) <= angularAllowable,
        actual: Math.abs(angularMisclosure),
        allowable: angularAllowable,
        unit: 'seconds',
        message: Math.abs(angularMisclosure) <= angularAllowable
          ? `Angular misclosure ${angularMisclosure.toFixed(1)}" within limit ${angularAllowable.toFixed(1)}"`
          : `Angular misclosure ${angularMisclosure.toFixed(1)}" exceeds limit ${angularAllowable.toFixed(1)}"`
      })
    }

    if (totalDistance > 0 && linearError > 0) {
      const linearPrecision = totalDistance / linearError
      const allowableMm = (config.closingErrorMmPerKm * totalDistance) / 1000
      
      checks.push({
        name: 'Linear Misclosure',
        passed: linearError <= allowableMm,
        actual: linearError,
        allowable: allowableMm,
        unit: 'm',
        message: linearError <= allowableMm
          ? `Closing error ${(linearError * 1000).toFixed(1)}mm within allowable ${allowableMm.toFixed(3)}m`
          : `Closing error ${(linearError * 1000).toFixed(1)}mm exceeds allowable ${allowableMm.toFixed(3)}m`
      })
    }
  }

  if (input.leveling) {
    const { arithmeticCheckPassed, arithmeticDiff, closingError, distanceKm } = input.leveling

    checks.push({
      name: 'Arithmetic Check',
      passed: arithmeticCheckPassed,
      actual: Math.abs(arithmeticDiff),
      allowable: 0,
      unit: 'm',
      message: arithmeticCheckPassed
        ? `Arithmetic check passed (diff: ${Math.abs(arithmeticDiff).toFixed(4)}m)`
        : `Arithmetic check failed (diff: ${arithmeticDiff.toFixed(4)}m) - BLOCKED`
    })

    if (distanceKm > 0 && closingError !== undefined) {
      const closingErrorMm = Math.abs(closingError) * 1000
      const allowableMm = config.closingErrorMmPerKm * Math.sqrt(distanceKm)
      
      checks.push({
        name: 'Closing Error',
        passed: closingErrorMm <= allowableMm,
        actual: closingErrorMm,
        allowable: allowableMm,
        unit: 'mm',
        message: closingErrorMm <= allowableMm
          ? `Closing error ${closingErrorMm.toFixed(1)}mm within allowable ${allowableMm.toFixed(1)}mm`
          : `Closing error ${closingErrorMm.toFixed(1)}mm exceeds allowable ${allowableMm.toFixed(1)}mm`
      })
    }
  }

  const allPassed = checks.every(c => c.passed)
  const precisionGrade = getPrecisionGrade(checks)

  if (!allPassed) {
    const failedChecks = checks.filter((c) => !c.passed)
    for (const failed of failedChecks) {
      if (failed.name === 'Linear Precision') {
        recommendations.push('Consider re-measuring traverse legs or adding control points')
      }
      if (failed.name === 'Angular Misclosure') {
        recommendations.push('Check angle measurements - possible instrument or booking error')
      }
      if (failed.name === 'Linear Misclosure') {
        recommendations.push('Review distance measurements - possible systematic error')
      }
      if (failed.name === 'Arithmetic Check') {
        recommendations.push('Recompute field notes - arithmetic error detected')
      }
      if (failed.name === 'Closing Error') {
        recommendations.push('Consider running double-run leveling for verification')
      }
    }
  }

  return {
    passed: allPassed,
    profile,
    checks,
    precisionGrade,
    recommendations
  }
}

function getPrecisionGrade(checks: ToleranceCheck[]): string {
  const linearCheck = checks.find((c) => c.name === 'Linear Precision')
  if (!linearCheck) return 'Unknown'

  // FIXED: linearCheck.actual is now the precision ratio (e.g. 5000 for 1:5000),
  // not the reciprocal (0.0002). Compare ratio directly against thresholds.
  const ratio = linearCheck.actual

  if (ratio >= 20000) return 'Control Grade'
  if (ratio >= 10000) return 'Engineering Grade'
  if (ratio >= 5000) return 'Cadastral Grade'
  if (ratio >= 3000) return 'Good'
  if (ratio >= 1000) return 'Acceptable'
  return 'Poor - Rejected'
}

export function formatToleranceCheck(result: ToleranceCheckResult): string {
  const status = result.passed ? ' PASS' : '[x] FAIL'
  const lines = [
    `Tolerance Check: ${status}`,
    `Profile: ${TOLERANCE_CONFIGS[result.profile].name}`,
    `Grade: ${result.precisionGrade}`,
    ''
  ]

  for (const check of result.checks) {
    lines.push(`${check.passed ? '' : '[x]'} ${check.name}: ${check.message}`)
  }

  if (result.recommendations.length > 0) {
    lines.push('')
    lines.push('Recommendations:')
    for (const rec of result.recommendations) {
      lines.push(`  • ${rec}`)
    }
  }

  return lines.join('\n')
}

/**
 * Tests for the Statutory Validation Gate.
 *
 * The gate is a pure function — no DB, no I/O — so tests construct
 * StatutoryGateInput objects directly and assert on the returned
 * StatutoryGateResult.
 *
 * Coverage:
 *   - Each rule in isolation (pass + fail case where applicable)
 *   - Tolerance profile auto-selection by surveyType
 *   - Severity ordering (block → warn → info)
 *   - passed flag reflects block count only
 *   - Graceful degradation when input fields are missing
 *   - Rule versioning is exposed
 *   - listRules() returns all registered rules
 *   - formatGateResult() produces readable output
 */

import {
  runStatutoryGate,
  formatGateResult,
  listRules,
  RULE_VERSION,
  type StatutoryGateInput,
} from '../statutoryGate'

// ─── Helpers ────────────────────────────────────────────────────────────

function makeBaseInput(overrides: Partial<StatutoryGateInput> = {}): StatutoryGateInput {
  const baseSurveyor = { name: 'Jane Doe', licenseNumber: 'ISK/LS/2020/123' }
  const { surveyor: overrideSurveyor, ...restOverrides } = overrides
  return {
    surveyType: 'cadastral',
    ...restOverrides,
    surveyor: {
      name: overrideSurveyor?.name ?? baseSurveyor.name,
      licenseNumber: overrideSurveyor?.licenseNumber ?? baseSurveyor.licenseNumber,
    },
  }
}

/** A passing cadastral traverse: 1:6000 precision, 4 stations, small misclosure. */
function makePassingTraverse() {
  return {
    stationCount: 4,
    angularMisclosureSeconds: 10, // well within 60×√4 = 120"
    linearErrorM: 0.005, // 5mm
    totalDistanceM: 1000, // 1 km → allowable 10√1 = 10 mm
    precisionRatio: 6000, // 1:6000, above cadastral minimum 1:5000
  }
}

/** A failing cadastral traverse: 1:2000 precision (below 1:5000 minimum). */
function makeFailingTraverse() {
  return {
    stationCount: 4,
    angularMisclosureSeconds: 10,
    linearErrorM: 0.005,
    totalDistanceM: 1000,
    precisionRatio: 2000, // below 1:5000
  }
}

describe('Statutory Validation Gate', () => {
  // ─── Overall behavior ─────────────────────────────────────────────────

  describe('runStatutoryGate', () => {
    it('passes with a valid cadastral input including passing traverse', () => {
      const input = makeBaseInput({ traverse: makePassingTraverse() })
      const result = runStatutoryGate(input)
      expect(result.passed).toBe(true)
      expect(result.summary.block).toBe(0)
    })

    it('blocks when traverse precision is below profile minimum', () => {
      const input = makeBaseInput({ traverse: makeFailingTraverse() })
      const result = runStatutoryGate(input)
      expect(result.passed).toBe(false)
      expect(result.summary.block).toBeGreaterThanOrEqual(1)
      const precisionViolation = result.violations.find(
        (v) => v.rule === 'rdm_1_1.traverse_precision'
      )
      expect(precisionViolation).toBeDefined()
      expect(precisionViolation!.severity).toBe('block')
      expect(precisionViolation!.actual).toBe(2000)
      expect(precisionViolation!.allowable).toBe(5000)
    })

    it('blocks when surveyor name is missing', () => {
      const input = makeBaseInput({
        surveyor: { name: '', licenseNumber: 'ISK/LS/2020/123' },
      })
      const result = runStatutoryGate(input)
      expect(result.passed).toBe(false)
      expect(
        result.violations.some((v) => v.rule === 'sok_standard.surveyor_name_required')
      ).toBe(true)
    })

    it('blocks when surveyor license is missing', () => {
      const input = makeBaseInput({
        surveyor: { name: 'Jane Doe', licenseNumber: '' },
      })
      const result = runStatutoryGate(input)
      expect(result.passed).toBe(false)
      expect(
        result.violations.some((v) => v.rule === 'sok_standard.surveyor_license_required')
      ).toBe(true)
    })

    it('warns (does not block) when license format is non-standard', () => {
      const input = makeBaseInput({
        surveyor: { name: 'Jane Doe', licenseNumber: 'LEGACY-123' },
      })
      const result = runStatutoryGate(input)
      const formatViolation = result.violations.find(
        (v) => v.rule === 'sok_standard.surveyor_license_format'
      )
      expect(formatViolation).toBeDefined()
      expect(formatViolation!.severity).toBe('warn')
      // Should not block — warn only
      const blockViolations = result.violations.filter((v) => v.severity === 'block')
      expect(blockViolations.some((v) => v.rule === 'sok_standard.surveyor_license_format')).toBe(false)
    })
  })

  // ─── Tolerance profile auto-selection ────────────────────────────────

  describe('profile auto-selection', () => {
    it('selects cadastral profile for cadastral surveys', () => {
      const input = makeBaseInput({ surveyType: 'cadastral' })
      const result = runStatutoryGate(input)
      expect(result.profile).toBe('cadastral')
    })

    it('selects engineering profile for engineering surveys', () => {
      const input = makeBaseInput({ surveyType: 'engineering' })
      const result = runStatutoryGate(input)
      expect(result.profile).toBe('engineering')
    })

    it('selects control profile for geodetic surveys', () => {
      const input = makeBaseInput({ surveyType: 'geodetic' })
      const result = runStatutoryGate(input)
      expect(result.profile).toBe('control')
    })

    it('respects toleranceProfileOverride over auto-selection', () => {
      const input = makeBaseInput({
        surveyType: 'cadastral',
        toleranceProfileOverride: 'control',
      })
      const result = runStatutoryGate(input)
      expect(result.profile).toBe('control')
    })

    it('applies stricter precision threshold for control profile', () => {
      // 1:6000 passes cadastral (1:5000) but fails control (1:20000)
      const input = makeBaseInput({
        surveyType: 'geodetic',
        traverse: makePassingTraverse(), // 1:6000
      })
      const result = runStatutoryGate(input)
      expect(result.passed).toBe(false)
      expect(
        result.violations.some(
          (v) => v.rule === 'rdm_1_1.traverse_precision' && v.allowable === 20000
        )
      ).toBe(true)
    })
  })

  // ─── Traverse rules ──────────────────────────────────────────────────

  describe('traverse rules', () => {
    it('blocks on angular misclosure exceeding √n × 60" for cadastral', () => {
      // 4 stations → allowable 60×√4 = 120"
      const input = makeBaseInput({
        traverse: {
          stationCount: 4,
          angularMisclosureSeconds: 150, // exceeds 120"
          linearErrorM: 0.001,
          totalDistanceM: 100,
          precisionRatio: 6000,
        },
      })
      const result = runStatutoryGate(input)
      expect(
        result.violations.some((v) => v.rule === 'cap299.angular_misclosure')
      ).toBe(true)
      expect(result.passed).toBe(false)
    })

    it('blocks on linear misclosure exceeding 10√K mm for cadastral', () => {
      // 1 km traverse → allowable 10√1 = 10 mm
      const input = makeBaseInput({
        traverse: {
          stationCount: 4,
          angularMisclosureSeconds: 5,
          linearErrorM: 0.05, // 50 mm — far above 10 mm
          totalDistanceM: 1000,
          precisionRatio: 6000,
        },
      })
      const result = runStatutoryGate(input)
      expect(
        result.violations.some((v) => v.rule === 'rdm_1_1.linear_misclosure')
      ).toBe(true)
      expect(result.passed).toBe(false)
    })

    it('blocks on insufficient station count for cadastral (<3)', () => {
      const input = makeBaseInput({
        traverse: {
          stationCount: 2,
          angularMisclosureSeconds: 0,
          linearErrorM: 0,
          totalDistanceM: 100,
          precisionRatio: 6000,
        },
      })
      const result = runStatutoryGate(input)
      expect(
        result.violations.some((v) => v.rule === 'cap299.min_stations')
      ).toBe(true)
      expect(result.passed).toBe(false)
    })

    it('does not enforce min station count for engineering surveys', () => {
      const input = makeBaseInput({
        surveyType: 'engineering',
        traverse: {
          stationCount: 2,
          angularMisclosureSeconds: 0,
          linearErrorM: 0,
          totalDistanceM: 100,
          precisionRatio: 15000,
        },
      })
      const result = runStatutoryGate(input)
      expect(
        result.violations.some((v) => v.rule === 'cap299.min_stations')
      ).toBe(false)
    })
  })

  // ─── Leveling rules ──────────────────────────────────────────────────

  describe('leveling rules', () => {
    it('blocks on arithmetic check failure', () => {
      // ΣBS − ΣFS should equal Last RL − First RL
      // Here: (1.5 − 0.5) = 1.0 but (100.5 − 100.0) = 0.5 → mismatch
      const input = makeBaseInput({
        leveling: {
          sumBS: 1.5,
          sumFS: 0.5,
          firstRL: 100.0,
          lastRL: 100.5, // expected 1.0 difference, got 0.5
          distanceKm: 0.5,
          type: 'ordinary' as const,
        },
      })
      const result = runStatutoryGate(input)
      expect(
        result.violations.some((v) => v.rule === 'survey_regs_1994.leveling_arithmetic')
      ).toBe(true)
      expect(result.passed).toBe(false)
    })

    it('blocks on leveling closure exceeding 10√K mm for ordinary', () => {
      // 1 km ordinary leveling → allowable 10√1 = 10 mm = 0.010 m
      // Arithmetic must balance: ΣBS - ΣFS must equal lastRL - firstRL
      // Closing error of 50mm: firstRL=100.0, lastRL=100.05, so
      // ΣBS - ΣFS must also = 0.05 to pass arithmetic check, then
      // the closing error of 0.05m = 50mm exceeds the 10mm allowable.
      const input = makeBaseInput({
        leveling: {
          sumBS: 1.55,
          sumFS: 1.5, // arithmetic: 1.55 - 1.5 = 0.05 = lastRL - firstRL 
          firstRL: 100.0,
          lastRL: 100.05, // 50 mm closing error
          distanceKm: 1.0,
          type: 'ordinary' as const,
        },
      })
      const result = runStatutoryGate(input)
      expect(
        result.violations.some((v) => v.rule === 'rdm_1_1.leveling_closure')
      ).toBe(true)
      expect(result.passed).toBe(false)
    })

    it('applies 5√K mm for precise leveling (stricter)', () => {
      // 1 km precise leveling → allowable 5√1 = 5 mm
      // 8mm closure fails precise but passes ordinary
      // Arithmetic balance: ΣBS - ΣFS = lastRL - firstRL = 0.008
      const preciseInput = makeBaseInput({
        leveling: {
          sumBS: 1.508,
          sumFS: 1.5, // arithmetic: 1.508 - 1.5 = 0.008 = lastRL - firstRL 
          firstRL: 100.0,
          lastRL: 100.008, // 8 mm
          distanceKm: 1.0,
          type: 'precise' as const,
        },
      })
      const preciseResult = runStatutoryGate(preciseInput)
      expect(preciseResult.passed).toBe(false)

      const ordinaryInput = makeBaseInput({
        leveling: {
