          sumFS: 1.5,
          firstRL: 100.0,
          lastRL: 100.008,
          distanceKm: 1.0,
          type: 'ordinary' as const,
        },
      })
      const ordinaryResult = runStatutoryGate(ordinaryInput)
      // 8 mm < 10 mm allowable for ordinary → passes closure rule
