      fromNorthing: 9850000,
      toEasting: 250350,
      toNorthing: 9850350,
      latitude: -1.0,
      longitude: 37.5,
      edmWavelength: 0.850,
    }, KENYA_DEFAULT_CONFIG);
    
    // Should have all correction stages applied
    expect(result.correctionLog.length).toBeGreaterThan(0);
